  [3089] = {
    'Mit Runen beschriftetes Pergament',
    {'Ah, während Ihr fort wart, kam ein Pergament für Euch, $N.|n|nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.', },
    {'Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen.', },
  },
  [3090] = {
    'Besudeltes Pergament',
    {'Ah, während Ihr fort wart, kam ein Pergament für Euch, $N.|n|nIch versuche normalerweise, jedweden Kontakt mit Hexenmeistern zu vermeiden, aber ich glaube, Ihr solltet es lesen, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von Eurem neuen Lehrer Nartok. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.', },
    {'Lest das besudelte Pergament und sprecht mit Nartok im Tal der Prüfungen.', },
  },
  [3091] = {
    'Einfache Notiz',
    {'Lest die einfache Nachricht und sprecht mit Harutt Donnerhorn im Camp Narache.', },
    {'Lest die einfache Nachricht und sprecht mit Harutt Donnerhorn im Camp Narache.', },
  },
  [3092] = {
