  [7181] = {
    'Die Legende von Korrak',
    {'Die angreifenden Sturmlanzen sind nicht die einzige Bedrohung in dieser Region, Soldat. Der Krieg in diesem Tal tobt an zwei Fronten. Den kannibalistischen Winteraxtrollen dürstet es ebenso nach Macht.|n|nAngeführt werden sie von Korrak dem Blutrünstigen - einem grausamen und verschlagenen Biest.|n|nEin Streich gegen Korrak könnte sich als vernichtender Schlag für den Winteraxklan erweisen. Tötet diesen Bastard und Ihr werdet entlohnt.', },
    {'Der Legende zufolge erscheint der mächtige Anführer der Winteraxtrolle nach gutdünken, um Angst und Schrecken unter den Bewohnen des Alteractals zu verbreiten.|n|nSollte Korrak auftauchen, tötet ihn und kehrt zu Kriegsmeister Laggrond zurück.', },
  },
  [7201] = {
    'Das letzte Element',
    {'Es gibt Arbeit für diejenigen, die sich in die Tiefen wagen, $N.|n|nDen Dunkeleisenzwergen ist es gelungen, extrem mächtige Golems zu erschaffen.|n|nErsten Berichten unserer Spione zufolge verwenden die Zwerge eine einzigartige Kraftquelle, die ihren Schöpfungen eine unvergleichliche Kraft zum Töten gibt.|n|nStellt Euch nur einmal vor, was wir mit unseren Monstrositäten tun könnten, wenn wir diese Essenz der Elemente in die Hände bekommen könnten! Stellt die ganze Stadt auf den Kopf, wenn es sein muss, aber kommt nicht wieder, ehe Ihr nicht die Essenz gefunden habt! Die Bezahlung ist es wert, das Risiko einzugehen.', },
    {'Begebt Euch in die Schwarzfelstiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat.', },
  },
  [7202] = {
    'Korrak der Blutrünstige',
    {'Die eingeborenen Winteraxtrolle dieser Region sind unbarmherzige Wilde, die nichts lieber täten, als unsere Knochen in einer ihrer widerlichen Mahlzeiten zu sehen.|n|nWir müssen ihnen unsere Macht vor Augen führen!|n|nWir konnten einige Schriftstücke aus ihren Höhlen entwenden, die Aufzeichnungen über ihre Führungshierarchie enthalten. Diese Schriftstücke lassen vermuten, dass ihr Anführer, Korrak der Blutrünstige, sich solange versteckt hält, bis er einen Grund hat sich zu zeigen.|n|nDer Tod Korraks, würde den Tod des Winteraxklans bedeuten! Tötet ihn und kehrt zu mir zurück.', },
    {'Der Legende zufolge erscheint der mächtige Anführer der Winteraxtrolle nach gutdünken, um Angst und Schrecken unter den Bewohnen des Alteractals zu verbreiten.|n|nSollte Korrak auftauchen, tötet ihn und kehrt zu Leutnant Haggerdin im Alteracgebirge zurück.', },
  },
  [7221] = {
    'Sprecht mit Ausgrabungsleiter Steinhauer',
    {'Ah, $N, Ihr wollt Euch zum Dienst melden, oder? Großartig, die Sturmlanzen können jeden gebrauchen, der sich freiwillig mustern lässt!|n|nSprecht mit Ausgrabungsleiter Steinhauer in Dun Baldar. Momentan sucht sie nach Freiwilligen für eine entscheidende Mission im Feindesland. Ihr findet sie unterhalb der Garnison von Dun Baldar.|n|nUnd haltet ein Auge offen, während Ihr durch Dun Baldar geht. $GEin hart arbeitender:Eine hart arbeitende:c; $C wie Ihr findet sicher viel zu tun, sofern Ihr nicht davor zurückscheut, Euch die Hände schmutzig zu machen.', },
    {'Sprecht mit Ausgrabungsleiter Steinhauer in der Garnison von Dun Baldar.', },
  },
  [7222] = {
    'Sprecht mit Voggah Todesgriff',
    {'Ah, $Gein:eine:c; $C! Wir sind alle hoch erfreut, Euch hier in Alterac anzutreffen, $N. Zwergische Eindringlinge und ihre Verbündeten sind in unser Tal einmarschiert und wir sind froh über jedes Mitglied der Horde, das uns in dieser gerechten Schlacht zur Seite steht!|n|nSprecht mit Voggah Todesgriff. Er sucht nach Freiwilligen für eine wichtige Mission. Es geht um die Allianzfestung hier im Alteractal!|n|nIhr findet Voggah in Burg Frostwolf.', },
    {'Sprecht mit Voggah in Burg Frostwolf.', },
  },
  [7223] = {
    'Rüstungsfetzen',
    {'Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Eisenschmiede bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.|n|nWenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann unterstützt unsere Kriegsbemühungen und bringt mir diese Stücke!', },
    {'Bringt Murgot Tiefenschmied in Dun Baldar 20 Rüstungsfetzen.', },
  },
  [7224] = {
    'Beutezug im Feindesland',
    {'Wenn Ihr gegen den Feind kämpft, sammelt die Fetzen seiner Rüstungen ein und bringt sie zu mir. Aus den Fetzen werde ich neue Rüstungen für unsere eigenen Truppen herstellen!', },
    {'Bringt 20 Rüstungsfetzen zu Schmied Regzar im Dorf der Frostwölfe.', },
  },
  [7241] = {
    'Die Verteidigung der Frostwölfe',
    {'In der Ferne kann man den Klang der Kriegstrommeln vernehmen, $C. Die ehrlose Sturmlanzengarde aus Eisenschmiede greift den Klan Eures Kriegshäuptlings an.|n|nIhr seid kampfgestählt, das verrät mir Euer Auftreten. Es scheint, dass Ihr wahrlich bereit seid, der Sache des Frostwolfklans zu dienen.|n|nEs liegt nun an Euch, den nächsten Schritt in Eurer Entwicklung zu gehen.|n|nReist in das Vorgebirge des Hügellands, dort befindet sich der Zugang zum Alteractal. Betretet das Tal und sucht Kriegsmeister Laggrond auf. Beeilung $C, die Schlacht hat bereits begonnen!', },
    {'Reist ins Alteractal im Vorgebirge des Hügellands. Sucht dort Kriegsmeister Laggrond auf und beginnt Eure Karriere als Soldat der Frostwölfe.', },
  },
  [7261] = {
    'Die hoheitliche Anordnung',
    {'Reist ins Alteractal im Vorgebirge des Hügellands. Wenn Ihr dort angekommen seid, meldet Euch umgehend bei Leutnant Haggerdin.|n|nFür den Ruhm von Bronzebart!', },
    {'Reist ins Alteractal im Vorgebirge des Hügellands. Wenn Ihr dort angekommen seid, meldet Euch umgehend bei Leutnant Haggerdin.|n|nFür den Ruhm von Bronzebart!', },
  },
  [7281] = {
    'Bruderliebe',
    {'Welch tragische Fügung... Mein Bruder steht mir auf dem Schlachtfeld gegenüber: Er ist einer der Kommandanten der Sturmlanzen.|n|nVon allen vier Kommandanten stellt er zweifellos die größte Gefahr dar. Falls man ihn tötet, würde die Bansheekönigin ihn vielleicht wiedererwecken, so wie sie es mit mir getan hat - und ihm die Irrtümer seines bisherigen Handelns vor Augen führen...|n|nTief im feindlichen Gebiet werdet Ihr meinen Bruder finden. Tötet ihn und bringt ihn zu mir zurück. Ich vertraue darauf, dass Ihr diese Mission erfolgreich zu Ende bringt, Soldat. |n|nUnd Soldat... geht nicht alleine.', },
    {'Begebt Euch ins Gebiet der Sturmlanzen und tötet Kommandant Karl Philips. Kehrt zu Kommandant Louis Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt.', },
  },
  [7282] = {
    'Bruderliebe',
    {'Er muss aus seinem Elend befreit werden, Soldat! Mein Bruder weiß nicht mehr, was er tut. Er ist nur noch eine willenlose Marionette der grausamen Bansheekönigin.|n|nBegebt Euch, über das Feld des Kampfes, in die Tiefen des Gebiets der Frostwölfe. Findet meinen Bruder und zerstört, was von ihm übrig ist. Seine Qualen sollen endlich ein Ende haben.', },
    {'Begebt euch ins Frostwolfgebiet und tötet Kommandant Louis Philips. Kehrt zu Kommandant Karl Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt.', },
  },
  [7301] = {
    'Gefallene Himmelsstürmer',
    {'Wir konnten sie gefangennehmen, $R. Ich rede von ihren Schwadronskommandanten. Es war eine wilde Himmelsschlacht, doch letztendlich haben wir sie geschlagen! Sie fielen wie Steine vom Himmel! Leider hat es auch viele unserer besten Piloten erwischt, als Sie die Burg Frostwolf angriffen. Ihr müsst herausfinden was aus ihnen geworden ist.|n|nDurchkämmt das Gebiet der Westturmstellung und Burg Frostwolf. Dort wurden Sie das letzte Mal gesehen. Und geht gründlich vor!', },
    {'Begebt Euch ins Frostwolfterritorium und sucht nach Schwadronskommandant Slidore, Schwadronskommandant Vipore und Schwadronskommandant Ichman. Meldet Euch bei Kommandant Duffy, sobald Ihr Eure Mission erfüllt habt.', },
  },
  [7302] = {
    'Gefallene Himmelsstürmer',
    {'Unsere Luftunterstützung musste einen schweren Schlag hinnehmen, $N. Sämtliche Schwadronskommandanten wurden über feindlichem Gebiet abgeschossen. Ihr müsst herausfinden, was aus ihnen geworden ist, sodass wir einen Rettungsversuch unternehmen können!|n|nGuse wurde das letzte Mal gesehen, als sie über den Eisschwingenbunker hinwegflog. Jetzors Reittier wurde zuletzt am Sägewerk der Sturmlanzen gesichtet. Mulverick... dieser waghalsige Narr, stürzte in der Nähe des Nordbunkers von Dun Baldar ab.|n|nDas sind alle Informationen, die ich habe. Schwärmt aus und durchsucht das Gebiet gründlich!', },
    {'Findet heraus, was aus Schwadronskommandantin Guse, Schwadronskommandantin Jeztor und Schwadronskommandant Mulverick geworden ist. Wenn Eure Mission erfüllt ist, kehrt zu Kommandant Mulfort zurück.', },
  },
  [7321] = {
    'Milde Schildkrötensuppe',
    {'Wer sagt denn, dass Untote keine Ahnung vom Kochen haben? Nehmt als Beispiel nur mal mein Rezept für Schildkrötensuppe. Ich habe Leute getroffen, die sogar von den Toten zurückgekehrt sind, nur um eine Schüssel voll davon zu kosten.|n|nDa wir gerade davon sprechen: In letzter Zeit konnte ich keine mehr kochen. Ich bin früher selbst bis zum Lordameresee gereist, um Schnappkiefer zu jagen, aber meine Arbeit hier beschäftigt mich mittlerweile einfach zu sehr.|n|nWenn Ihr mir etwas Schildkrötenfleisch von den Schnappkiefern bringt, dann werd ich Euch in das Geheimnis meines Rezepts einweihen!', },
    {'Bringt 10 Stücke Schildkrötenfleisch zu Christoph Jeffkott in Tarrens Mühle.', },
  },
  [7341] = {
    'Ein gerechter Handel',
    nil,
    nil,
  },
  [7342] = {
    'Pfeile sind was für Memmen',
    nil,
    nil,
  },
  [7361] = {
    'Die Gunst der Dunkelspeere',
    {'<Najak knurrt.>|n|nBevor die Nachtelfen waren, waren die Trolle. Erst von den Trollen sind Nachtelfen gekommen.|n|nIhre aufrührerischen Angriffe gegen mein Volk können nicht toleriert werden. Hirschhaupt will uns auslöschen - sämtliche Spuren derer vernichten, die ihn und seines Gleichen ausgetragen haben. Das wird nie geschehen!|n|nFür jeden Nachtelfen, den Ihr tötet und enthauptet, wird Najak Euch die Gunst der Dunkelspeere sichern. Die Kunde Eurer Taten wird sich über ganz Kalimdor und den Östlichen Königreichen verbreiten. Geht nun und dient den Dunkelspeeren!', },
    {'Ihr wurdet beauftragt gegnerische Nachtelfenspieler im Alteractal zu töten.|n|nTötet einen Nachtelfen und bringt einen abgeschlagenen Nachtelfenkopf zu Najak Hexxen in Burg Frostwolf.', },
  },
  [7362] = {
    'Verbündeter der Tauren',
    {'Die Älteste hat mich in dieses Kriegsgebiet geschickt um die anderen Völker zu erforschen. Genau genommen bin ich hier, um Proben von den Gnomen zu nehmen. Magatha interessiert sich insbesondere für ihre Überlebensfähigkeit. Die Gnome - obwohl erbärmlich schwach und winzig - scheinen sowohl im Kampf als auch körperlich äußerst widerstandsfähig zu sein.|n|nZum Glück für Euch, suche ich nach Freiwilligen, die Magathas Anweisungen in die Tat umsetzen. Bringt mir Gnomhaarbüschel und die Tauren werden Euch als Verbündeten anerkennen.', },
    {'Ihr wurdet beauftragt gegnerische Gnomspieler im Alteractal zu töten.|n|nTötet einen Gnom und bringt ein Büschel Gnomhaar zu Ravak Grimmtotem in Burg Frostwolf.', },
  },
  [7363] = {
    'Die menschliche Existenz',
    {'Menschen sind schlichtweg verabscheuenswert.|n|n<Kommandant Philips schneidet eine Grimasse.>|n|nZwar entspricht es den Tatsachen, dass ich ein Soldat der Frostwölfe bin, dennoch bleibe ich ein Diener Sylvanas.|n|nNeben der Ausübung meiner Pflichten, arbeite ich auch für die Dunklen Apotheker von Unterstadt.|n|nIch bin damit beauftragt worden menschliche Knochensplitter einzusammeln, die helfen sollen, uns von der menschlichen Existenz zu befreien.|n|nMan hat mich außerdem dazu berechtigt, diese Aufgabe an meine Untergebenen weiterzureichen.|n|nFindet sie. Tötet sie. Bringt mir ihre Knochensplitter.', },
    {'Ihr wurdet beauftragt gegnerische Menschenspieler im Alteractal zu töten.|n|nTötet einen Menschen und bringt dessen Knochensplitter zu Kommandant Louis Philips (er bewegt sich zwischen den Frontlinien und Burg Frostwolf hin und her).|n|nDie Heilung für die menschliche Existenz ist zum Greifen nahe!', },
  },
  [7364] = {
    'Gnomeregan Kopfgeld',
    {'Der Hochtüftler persönlich hat mich auf dieses Schlachtfeld beordert, um meinen Brüdern und Schwestern beizustehen. Es ist uns zu Ohren gekommen, dass die Tauren sich einzelne Gnome herauspicken und töten. Noch viel schlimmer ist, dass sie den Leichen ihr prächtiges Gnomhaar büschelweise abschneiden. Diese Greultaten müssen aufgehalten werden. Wir müssen Vergeltung üben!|n|nIch will sie alle enthuft sehen, $C. Bringt mir ihre Hufe! Erweist euch als Verbündeter der Gnome.', },
    {'Ihr wurdet beauftragt gegnerische Taurenspieler im Alteractal zu töten.|n|nTötet einen Tauren und bringt dessen Taurenhuf zu Dirk Schwindel in Dun Baldar.', },
  },
  [7365] = {
    'Hirschhaupts Requiem',
    {'Hirschhaupt hat uns Anweisung gegeben, alle Trolle auf dem Schlachtfeld auszulöschen. Ihrer lächerlichen Behauptung die Nachtelfen erschaffen zu haben, kann nur mit aller Macht und militärischen Mitteln entgegengewirkt werden.|n|nTötet sie alle und bringt mir ihr Mojo. Ich wiederhole: Stehlt ihnen ihr Mojo.', },
    {'Ihr wurdet beauftragt gegnerische Trollspieler im Alteractal zu töten.|n|nTötet einen Troll und bringt Athramanis in Dun Baldar etwas Trollmojo der Dunkelspeere.', },
  },
  [7366] = {
    'Die Gnade des Erzbischofs',
    {'Der Erzbischof ist so gütig wie er weise ist. Dass ein Mann wie er derartig gnädig zu einer solch elenden Bande sein kann...|n|n<Kommandant Philips schüttelt ungläubig den Kopf.>|n|nZu gütig... einfach zu gütig.|n|nDer Erzbischof möchte, dass wir uns der Untoten erbarmen und ihnen einen schnellen und endgültigen Tod gewähren. Für diesen großen Akt der Gnade benötigen wir nur ihre schwarzen, von Krankheit besessenen Herzen.|n|nBringt mir die Herzen der Verlassenen, sodass wir sie in der Kathedrale des Lichts zeremoniell verbrennen können. Eilt euch, $N!', },
    {'Ihr wurdet beauftragt gegnerische Verlassenen-Spieler im Alteractal zu töten.|n|nTötet einen Verlassenen und bringt dessen Herz zu Kommandant Karl Philips (er bewegt sich zwischen dem Sägewerk und der Mine hin und her).', },
  },
  [7367] = {
    'Die Gefahr bannen',
    {'Die Frostwölfe haben ihre Frontlinien und Basen allesamt vermint, $C. Achtet darauf wohin Ihr tretet, wenn Ihr in feindliches Territorium eindringt.|n|nWenn wir dem Feind einen entscheidenden Schlag versetzten wollen, müsst Ihr seine Quelle für Sprengwaffen zum Versiegen bringen - Ich rede vom feindlichen Sprengmeister! Tötet ihn und wir können alle Minen sicher entschärfen. Solange er ausfällt, fallen auch seine Minen aus.|n|nVermutlich befindet er sich in einem Turm, nahe der Eisblutgarnison. Viel Glück, Soldat!', },
    {'Findet den Sprengmeister der Frostwölfe und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Sturmlanzen zurück.', },
  },
  [7368] = {
    'Die Gefahr bannen',
    {'Ich weiß alles über Landminen. Immerhin habe ich alle Minen an unseren Frontlinien selbst verlegt.|n|nWenn Ihr das Minenfeld der Sturmlanzen unschädlich machen wollt, braucht Ihr nur eines zu tun - Tötet den feindlichen Sprengmeister! Zweifellos versteckt sich der feige Zwerg im ersten Turm, auf dem Feld des Kampfes. Schaltet ihn aus und die Landminen werden nicht zurückkommen, nachdem sie von Euch entschärft wurden.|n|nFalls Ihr es schaffen solltet den Sprengmeister zu töten, kommt zu mir zurück und lasst es mich wissen. Keine gute Tat soll unbelohnt bleiben.', },
    {'Findet den Sprengmeister der Sturmlanzen und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Frostwölfe zurück.', },
  },
  [7381] = {
    'Korraks Rückkehr',
    {'Es ist zwar eine Tatsache, dass Korrak gefallen ist, jedoch bleibt eine Frage offen: Wird er auch tot bleiben? Trolle sind berüchtigt für ihre außerweltliche Stammesmagie. Mich würde es nicht überraschen, wenn ihr toter Anführer wiedererweckt würde, um wieder einmal über seinen Klan zu herrschen.|n|nIhr wisst ja was in einem solchen Fall zu tun ist.|n|n<Kriegsmeister Laggrond deutet mit seinem Finger eine Schneidebewegung an seinem Hals an.>|n|nUnd nächstes mal möchte ich seinen Schädel. Haltet einfach die Augen offen, Soldat.|n|nWegtreten!', },
    {'Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn.|n|nBringt Korraks Schädel zu Kriegsmeister Laggrond auf Burg Frostwolf.', },
  },
  [7382] = {
    'Korrak der Unsterbliche',
    {'Irgendetwas stimmt an dieser Sache nicht... Hat jemand daran gedacht Korraks Körper zu verbrennen? Diese Trolle werden vor nichts halt machen, um ihren gefallenen Anführer wiederzubeleben - so wie es die blauhäutigen Heiden des öfteren tun.|n|nHaltet immer ein Auge offen, $N. Seid nicht beunruhigt, wenn Karrak überraschend wieder auftaucht. Und wenn er das tut, will ich ihn tot sehen - seinen Körper zu Asche verbrannt.|n|nObendrein, schlagt ihm seinen Kopf ab und bringt mir seinen Schädel, bevor Ihr seinen leblosen Körper verbrennt.', },
    {'Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn.|n|nBringt Korraks Schädel zu Leutnant Haggerdin in Dun Baldar.', },
  },
  [7383] = {
    'Teldrassil: Die Bürde der Kaldorei',
    nil,
    nil,
  },
  [7384] = {
    'Die Schuppenmacher',
    {'Gebt mir einige Schuppen.', },
    {'Sammelt für Karana im Sicheren Hafen, in den Sümpfen des Elends einige Schuppen.', },
  },
  [7385] = {
    'Eine Gallone Blut',
    {'Ich bin ebenso begierig wie Ihr darauf, meine tragbare Schreddereinheit auszuprobieren, $R, aber bevor ich das Set herstellen kann, benötige ich Material - viel Material!|n|nUm genau zu sein, benötige ich einen Berg aus Thorium, Mithril und Eisen. Ich benötige außerdem eine Dampfsäge pro Einheit. Diese müsst Ihr beim Sägewerk beschaffen.|n|nAls ich mich hier umgesehen habe (vor meiner Gefangennahme), ist mir ein Stapel Dampfsägen im Holzlager der Sturmlanzen aufgefallen.', },
    nil,
  },
  [7386] = {
    'Haufenweise Kristalle',
    {'Ich bin ebenso begierig wie Ihr darauf, meine tragbare Schreddereinheit auszuprobieren, $R, aber bevor ich das Set herstellen kann, benötige ich Material - viel Material!|n|nUm genau zu sein, benötige ich einen Berg aus Thorium, Mithril und Eisen. Ich benötige außerdem eine Dampfsäge pro Einheit. Diese müsst Ihr beim Sägewerk beschaffen.|n|nAls ich mich hier umgesehen habe (vor meiner Gefangennahme), ist mir ein Stapel Dampfsägen im Holzlager der Sturmlanzen aufgefallen.', },
    nil,
  },
  [7401] = {
    'GESUCHT: ZWERGE!',
    {'Auf Befehl von Unteroffizier Yazra Murrblut sind alle Zwerge auf dem Schlachtfeld umgehend zu töten.|n|nSolltet Ihr einen Zwerg im Kampf töten, schneidet ihm sein Rückgrat heraus und lasst den rückgratlosen Fleischhaufen als Mahnmal für alle zurück, die sich gegen die Frostwölfe stellen.|n|nKehrt anschließend mit dem Beweis Eurer Heldentat zu Unteroffizier Yazra Murrblut zurück.', },
    {'Ihr wurdet damit beauftragt, alle feindlichen Zwergenspieler im Alteractal zu töten.|n|nTötet einen Zwerg und schneidet ihm sein Rückgrat heraus. Bringt anschließend das Zwergenrückgrat zu Unteroffizier Yazra Murrblut in Burg Frostwolf.', },
  },
  [7402] = {
    'GESUCHT: ORCS!',
    {'Auf Befehl von Korporal Noreg Sturmlanze sind alle verfügbaren Soldaten dazu aufgefordert, jeden gegnerischen Orc auf dem Schlachtfeld umgehend zu töten.|n|nDie Soldaten sind weiterhin dazu aufgefordert, einen Hauer oder Zahn aus dem Maul des Feindes zu entfernen, um diese als Beweis für ihre Tat vorzeigen zu können.|n|nBitte tragt dafür Schutzhandschuhe.', },
    {'Ihr wurdet damit beauftragt, alle feindlichen orcischen Spieler im Alteractal zu töten.|n|nTötet einen Orc und bringt seinen Zahn zurück zu Korporal Noreg Sturmlanze in Dun Baldar.', },
  },
