  [8149] = {
    'Die Ehrung eines Helden',
    {'Während des Erntedankfests in Azeroth danken wir unseren Helden für all die Opfer, die sie in unserem Namen dargebracht haben. Für einige war es gar das höchste aller Opfer, ihr Leben. Die Allianz kennt viele Helden, doch keine Heldensage und kein Lebensweg ist so tragisch, wie der von Uther Lichtbringer.|n|nHelft uns Uther zu ehren, indem Ihr diese Opfergabe zu seinem Grabmal in den Westlichen Pestländern bringt. Legt sie an seiner Statue nieder und kehrt zu mir zurück. Lasst Euch nicht zu viel Zeit, denn ich bin nur bis zum Ende des Erntedankfests hier.', },
    {'Reist zu Uthers Grabmal in den Westlichen Pestländern und benutzt Uthers Tribut an seiner Statue. Kehrt zu Wagner Hammerschlag außerhalb von Eisenschmiede zurück, bevor das Erntedankfest endet.', },
  },
  [8150] = {
    'Die Ehrung eines Helden',
    {'Während des Erntedankfests in Azeroth danken wir unseren Helden für all die Opfer, die sie in unserem Namen dargebracht haben. Für einige war es gar das höchste aller Opfer, ihr Leben. Die Horde kennt viele Helden, doch niemand verkörpert Stärke und Opferbereitschaft so sehr, wie Grom Höllschrei.|n|nHelft uns Grom zu ehren, indem Ihr diese Opfergabe zu seinem Monument im Dämonensturz im Eschental bringt. Legt sie an seinem Monument nieder und kehrt zu mir zurück. Lasst Euch nicht zu viel Zeit, denn ich bin nur bis zum Ende des Erntedankfests hier.', },
    {'Reist zu Groms Monument im Dämonensturz im Eschental und benutzt Groms Tribut am Fuße seines Monuments. Kehrt zu Javnir Nashak außerhalb von Orgrimmar zurück, bevor das Erntedankfest endet.', },
  },
  [8151] = {
    'Der Talisman des Jägers',
    {'Ogtinc von Azshara sucht nach erfahrenen Jägern, genau wie Ihr es seid. Er ist ein Furbolg-Jäger, der seinen Stamm verlassen hat, um dem Zirkel des Cenarius zu helfen. Seine Lehren sollen das Wissen anderer, die sein Geschick teilen, bereichern und ihnen dabei helfen, das Gleichgewicht zu bewahren. Ihr würdet gut daran tun, mit ihm zu sprechen.|n|nOgtinc hält sich auf den Klippen von Azshara, nordöstlich der Ruinen von Eldarath, auf.', },
    {'Sprecht mit Ogtinc in Azshara.', },
  },
  [8152] = {
    nil,
    {'In Azshara lebt ein Furbolg namens Ogtinc, er ist ein mächtiger und weiser Jäger. Besucht ihn, wenn Ihr Euch stark genug fühlt. Er sollte in der Lage sein, Euch weiter in den Künsten der Jagd zu unterweisen und Eure Fähigkeiten weiter zu verbessern.|n|nOgtinc lebt oben auf den Klippen, nordöstlich der Ruinen von Eldarath in Azshara.', },
    {'Sprecht mit Ogtinc in Azshara.', },
  },
  [8153] = {
    'Gehörnte Renner',
    {'Die Renner tragen die gewaltigsten Geweihe die es in der bekannten Welt zu finden gibt. Solche Geweihe nutzt der Renner, um sich selbst zu verteidigen, indem er Feinde damit aufspießt. Meistens brechen sie dadurch die Spitzen der Geweihe ab. Perfekte, natürliche Geweihe sind das Zeichen für ein extrem selbstsicheres Tier.|n|nEin solches Geweih zu erlangen, würde auch in Euch dasselbe Selbstvertrauen fließen lassen.|n|nGeht auf die Jagd nach Mooshufrennern, findet die perfekten Geweihe und bringt sie mir.', },
    {'Bringt ein Paar perfekte Rennergeweihe zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath.', },
  },
  [8166] = {
    'Die Schlacht um das Arathibecken!',
    {'$N, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpositionen anzugreifen.|n|nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!|n|nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpositionen gelungen ist.', },
    {'Erobert die Mine, das Sägewerk, die Schmiede und den Hof und meldet Euch anschließend bei Feldmarschall Lichtmark in der Zuflucht.', },
  },
  [8167] = {
    'Die Schlacht um das Arathibecken!',
    {'$N, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpositionen anzugreifen.|n|nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!|n|nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpositionen gelungen ist.', },
    {'Erobert die Mine, das Sägewerk, die Schmiede und den Hof und meldet Euch anschließend bei Feldmarschall Lichtmark in der Zuflucht.', },
  },
  [8168] = {
