  [8762] = {
    'Metzen das Rentier',
    {'Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!|n|nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir glauben, dass dieser schreckliche, monströse Griesgram, der sich im Vorgebirge des Hügellandes versteckt, ihn entführt hat. Gerade jetzt zur Festzeit können wir hier nicht weg. Bitte findet Metzen, besiegt seine Entführer und bringt ihn zu uns zurück!', },
    {'Befreit Metzen das Rentier aus den Klauen seiner Entführer nahe der Eisfellhöhle im Vorgebirge des Hügellandes.', },
  },
  [8763] = {
    'Der Held des Tages',
    {'Eigentlich darf ich Euch das gar nicht sagen, aber da Ihr ja der Held des Tages seid, mach ich mal \'ne Ausnahme.|n|nUm diese Jahreszeit gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Wir haben eine Maschine, die Tannenzweige konserviert - die bleiben dann für immer frisch! Wir benutzen sie um die Festtage etwas aufzupeppen... und unsere Profite im Sommer zu steigern!|n|nIch lasse Euch den Konservierer benutzen, aber nur, wenn Ihr ein Meisterkoch seid. Ihr werdet etwas Tiefsteinsalz und etwa zwei, drei, ach, sagen wir einfach fünf Goldstücke brauchen. Damit solltet Ihr ein nettes Bündel konservieren können, das Ihr behalten könnt.', },
    {'Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten.', },
  },
