  [9074] = {
    'Gurt des Erdspalters',
    {'Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?|n|nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.|n|nBringt mir die Überbleibsel der Gefallenen sowie die läuternden Materialien, dann soll Erdspalter Euer sein.|n|nSucht in Naxxramas.', },
    {'Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Gurt des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gurt, 8 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 3 Nexuskristalle.', },
  },
  [9075] = {
    'Handgelenksschützer des Erdspalters',
    {'Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?|n|nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.|n|nBringt mir die Überbleibsel der Gefallenen sowie die läuternden Materialien, dann soll Erdspalter Euer sein.|n|nSucht in Naxxramas.', },
    {'Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Paar Handgelenksschützer des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Handgelenksschützer, 6 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.', },
  },
  [9076] = {
    'Getriebener Rädelsführer',
    {'Die Getriebenen sind so auf den Verzehr von fauler Magie konzentriert, sie haben nicht einmal gemerkt, dass wir den Großteil unserer Waffen wieder an uns gebracht haben. Wir können uns allerdings nicht auf ihren Zustand der Benommenheit verlassen. Es ist an der Zeit für einen ausschlaggebenden Angriff. Lasst uns anhand ihres Anführers Aldaron ein Exempel statuieren. Er wurde im obersten Teil des Gebäudes beim Ankerplatz gesichtet. Bringt mir seinen Kopf, ich werde Euch entsprechend entlohnen.', },
    {'Bringt Aldarons Kopf zu Velendris Weißflor nahe des Ankerplatzes der Sonnensegel im Immersangwald.', },
  },
  [9077] = {
    'Brustplatte der Knochensense',
    {'Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.|n|nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.', },
    {'Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Brustplatte der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Brustplatte, 25 kampfzerschlissene Lederstücke, 2 Arkanitbarren und 6 geschmeidige unverwüstliche Bälge.', },
  },
  [9078] = {
    'Beinplatten der Knochensense',
    {'Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.|n|nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.', },
    {'Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinplatten der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinplatten, 20 kampfzerschlissene Lederstücke, 1 Arkanitbarren, 8 geschmeidige unverwüstliche Bälge und 100 Goldstücke.', },
  },
  [9079] = {
    'Helm der Knochensense',
    {'Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.|n|nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.', },
    {'Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Helm der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Helm, 15 kampfzerschlissene Lederstücke, 8 geschmeidige unverwüstliche Bälge. 1 Nexuskristall und 75 Goldstücke.', },
  },
  [9080] = {
