  [9189] = {
    'Lieferung an das Grabmal',
    {'Ihr habt das Herz der Fürstin gerührt, obwohl es nicht mehr schlägt.|n|nIch habe Anweisungen, die zum Grabmal nach Silberwald gebracht werden müssen. Berater Sorrelon repräsentiert uns und berät dort die Verlassenen.|n|nDie kürzeste Route, wenn man von ihren fliegenden Fledermäusen absieht, ist es, Unterstadt zu verlassen und die Straße nach Süden zu nehmen. Es gibt Wegweiser, also sollte es nicht zu schwer sein, den Ort zu finden. Aber nehmt Euch in Acht, das Grabmal selbst ist eine zerfallene Gruft.|n|nDiese Verlassenen sind schon merkwürdige Kreaturen.', },
    {'Bringt die Befehle der Sin\'dorei zu Berater Sorrelon beim Grabmal im Silberwald.', },
  },
  [9190] = {
    'Handwerksverfügung - Runenstoffstiefel',
    {'Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.|n|nVertragsnummer TR-635:|n|n8 Runenstoffstiefel.|n|nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.|n|nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.|n|n-Einsatzkommandant Metz, die Argentumdämmerung', },
    {'Bringt 8 Runenstoffstiefel und die Handwerksverfügung für die Runenstoffstiefel zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
  [9191] = {
    'Handwerksverfügung - Runenstofftasche',
    {'Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.|n|nVertragsnummer TR-9999:|n|n8 Runenstofftaschen.|n|nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.|n|nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.|n|n-Einsatzkommandant Metz, die Argentumdämmerung', },
    {'Bringt 8 Runenstofftaschen und die Handwerksverfügung für die Runenstofftaschen zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
  [9192] = {
    'Ärger in den Grubenlichtminen',
    {'Die Grubenlichtminen im Südwesten wurden von einem Gnollklan, der sich die Schwarzpfoten nennt, überrannt. Ich muss Euch sicherlich nicht daran erinnern, wie wichtig diese Minen in strategischer Hinsicht für unseren fortwährenden Schlachtzug in den Geisterlanden sind!|n|nNehmt die Straße, die nach Süden führt, und haltet Euch rechts an der Wegzweigung. Kurz nach dem Ziggurat zur Rechten kommt ein kurzer Trampelpfad Richtung Westen. Folgt ihm.|n|nWir brauchen das Erz!', },
    {'Tötet 8 Gnolle der Schwarzpfoten, 6 Strauchdiebe der Schwarzpfoten und 4 Schamanen der Schwarzpfoten. Kehrt anschließend zu Todespirscher Maltendis in Tristessa in den Geisterlanden zurück.', },
  },
  [9193] = {
    'Untersucht die Amanikatakomben',
    {'$C, wir haben aus zuverlässigen Quellen erfahren, dass die Trolle, die in den Amanikatakomben innerhalb des Sonnenhügels begraben wurden, wieder von den Toten auferstanden sind. Dame Auriferous möchte, dass Ihr die Katakomben untersucht und dass Ihr alle leblosen Überreste, die Ihr dort auffindet, verbrennt. Die Auferstehung weiterer Kreaturen soll dadurch verhindert werden.|n|nIhr kommt am schnellsten dorthin, wenn Ihr Richtung Norden reist und dann die erste Abzweigung nach rechts nehmt. Somit gelangt Ihr auf die Nordseite des Hügels, seht Richtung Süden nach dem Eingang.', },
    {'Untersucht die Amanikatakomben und verbrennt 10 mumifizierte Trollüberreste. Kehrt anschließend zu Beraterin Valwyn in Tristessa in den Geisterlanden zurück.', },
  },
  [9194] = {
    'Handwerksverfügung - Runenstoffrobe',
    {'Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.|n|nVertragsnummer TR-7229:|n|n8 Runenstoffroben.|n|nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern gebracht werden.|n|nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.|n|n-Einsatzkommandant Metz, die Argentumdämmerung', },
    {'Bringt 8 Runenstoffroben und die Handwerksverfügung für die Runenstoffroben zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
