  [9269] = {
    nil,
    {'Die letzte Aufgabe ist zugleich die schwierigste von allen, $N. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras\' stellen.|n|nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.', },
    {'Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.', },
  },
  [9270] = {
    nil,
    {'Die letzte Aufgabe ist zugleich die schwierigste von allen, $N. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras\' stellen.|n|nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.', },
    {'Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.', },
  },
  [9271] = {
    nil,
    {'Die letzte Aufgabe ist zugleich die schwierigste von allen, $N. Ihr seid einem Alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras\' stellen.|n|nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.', },
    {'Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.', },
  },
  [9272] = {
    'Kleider machen Seebären',
    nil,
    nil,
  },
  [9273] = {
    'iCoke-Gewinngutschein einlösen',
    nil,
    nil,
  },
  [9274] = {
    'Geister der Ertrunkenen',
    {'Der See im Norden wird seit langer Zeit von den Geistern meiner Ahnen heimgesucht, $N. Die armen Seelen waren Opfer eines tragischen Unfalls, bei dem etliche von ihnen am Grund des Sees ertranken.|n|nDie Ursache dieser Geschehnisse ist längst in Vergessenheit geraten, aber ihre quälenden Schreie erinnern noch heute an ihren Fluch.|n|nFalls Ihr dazu bereit seid, möchte ich, dass Ihr zum See geht und ihrem Leiden ein Ende bereitet, $N. Ich wäre Euch dankbar dafür, und sie auch, da bin ich sicher.', },
    {'Waldläufer Krenn\'an aus der Enklave der Weltenwanderer möchte, dass Ihr beim nahegelegenen See 8 rachsüchtige Erscheinungen und 8 ruhelose Erscheinungen tötet.', },
  },
  [9275] = {
    'In der Würze liegt der Tod',
    {'Ich wurde von den Weltenwanderern angeheuert, um ihnen bei der Lösung ihres Trollproblems behilflich zu sein. Ich denke, dass ich die Antwort auf ihr Problem parat habe.|n|nIch verfüge über eine Reihe hochwirksamer Gifte. Trolle sind lebende Wesen wie Ihr und ich, und müssen daher regelmäßig Nahrung zu sich nehmen. Wenn wir also etwas Gift unter ihr Essen mischen... nun, das Resultat dürfte sehr unterhaltsam sein!|n|nSicherlich möchtet Ihr uns zur Hand gehen, um uns die Waldschattentrolle südlich von hier, in Zeb\'Nowa, vom Hals zu schaffen? Das Lager erstreckt sich über die ganze nördliche und südliche Seite der Straße nach Zul\'Aman.', },
    {'Vergiftet die Trollnahrungsvorräte in den Lagern von Zeb\'Nowa. Kehrt anschließend zu Apotheker Venustus bei der Enklave der Weltenwanderer in den Geisterlanden zurück.', },
  },
  [9276] = {
    'Angriff auf Zeb\'Tela',
    {'Unsere Ressourcen hier sind recht begrenzt, $C, daher ist Eure Hilfe für uns unverzichtbar. Ich wurde vom Hauptmann damit beauftragt, die regelmäßigen Störangriffe auf die Lager der Waldschattentrolle zu überwachen. Wir versuchen die Trolle so lange zu beschäftigen, bis wir genug Kräfte für eine vernichtende Offensive zusammenziehen können, um sie endgültig auszulöschen.|n|nBis dahin benötigen wir jeden Freiwilligen, der uns dabei helfen kann, die Anzahl der Waldschattentrolle zu reduzieren.|n|nDenkt Ihr, Ihr könntet nach Osten in Richtung Zeb\'Tela reisen und ihnen ein wenig Schaden zufügen?', },
    {'Tötet 8 Schattenzauberer der Waldschattentrolle und 8 Kopfjäger der Waldschattentrolle. Kehrt anschließend zu Weltenwanderin Solanna bei der Enklave der Weltenwanderer in den Geisterlanden zurück.', },
  },
  [9277] = {
    'Angriff auf Zeb\'Nowa',
    {'Es ist Zeit für eine größere Herausforderung. Zeb\'Nowa, südlich von hier, beherbergt die mächtigsten Waldschattentrolle. In unserem Bestreben, die Anzahl der Trolle so klein wie möglich zu halten, erteile ich Euch den Auftrag, dorthin zu gehen und alle Euch zur Verfügung stehenden Mittel einzusetzen, um den Trollen so viel wie möglich zuzusetzen.|n|nKann ich auf Euch zählen, $N? Seid Ihr bereit für die Trolljagd?', },
    {'Tötet 10 Pantherlords der Waldschattentrolle und 10 Verhexer der Waldschattentrolle. Kehrt anschließend zu Weltenwanderin Solanna bei der Enklave der Weltenwanderer in den Geisterlanden zurück.', },
  },
  [9278] = {
    'Willkommen!',
    nil,
    nil,
  },
  [9279] = {
    'Ihr habt überlebt!',
    {'Kümmert Euch nicht um meine Wunden, $G Bruder : Schwester;. Es ist ein Wunder, dass überhaupt jemand von uns überlebt hat!|n|nIch dachte schon, Ihr wärt nicht durchgekommen; Ihr wurdet seit Wochen vermisst!|n|nEs ist etwas passiert und die Exodar ist abgestürzt. Viele ließen ihr Leben.|n|nEs ist ein Segen, dass Ihr noch unter uns weilt, $N! Mit Euch an unserer Seite werden wir bald wieder in Sicherheit sein! Proenitus hat mich beauftragt, Euch zu ihm zu schicken, sobald Ihr erwacht seid. Er wartet außerhalb des Schiffes, südwestlich am Fuße des Hügels auf Euch.', },
    {'Sprecht mit Proenitus bei der Absturzstelle im Am\'mental.', },
  },
  [9280] = {
    'Wiederaufladen der Heilkristalle',
    {'Unsere dringlichste Sorge ist die Erschöpfung unserer Heilkristalle. Wir müssen sie so schnell wie möglich wieder aufladen!|n|nUnglücklicherweise können wir das derzeit nur, indem wir das Blut der einheimischen Talmotten abzapfen. Ihr Blut eignet sich als Ersatzstoff.|n|nMan findet die Motten entlang des gesamten Tals, jedoch verstärkt im Nordwesten.', },
    {'Beschafft Euch 6 Phiolen mit Mottenblut von den in der Nähe hausenden Talmotten und bringt sie zu Proenitus bei der Absturzstelle im Am\'mental.', },
  },
  [9281] = {
    'Den Weg frei machen',
    {'Magister Kaendris hat mich entsandt, um die Gegend von aggressiven Wildtieren zu säubern. Sobald die Gegend sicher ist, wollen die Magister hier einen Außenposten gegen die Geißel errichten.|n|nWenn Ich als Lehrling eines gelernt habe, dann ist das, Verantwortung zu delegieren, besonders bei solch lebensgefährlichen Unternehmungen!|n|nWenn Ihr Interesse habt, werde ich Euch gut dafür bezahlen, die Großen Spindelweber und Geisterklauenverheerer westlich und südlich von hier aus dem Weg zu räumen.', },
    {'Lehrling Vor\'el von Andiliens Grund in den Geisterlanden möchte, dass Ihr 10 Große Spindelweber und 10 Geisterklauenverheerer tötet.', },
  },
  [9282] = {
    'Die Enklave der Weltenwanderer',
    {'Die Magister und die Weltenwanderer mögen nicht immer einer Meinung sein, $N, doch wenn es um Dar\'Khan geht, stimmen alle überein, dass wir gemeinsam einen Weg finden müssen, um ihn und seine Legionen zu besiegen.|n|nWaldläuferin Vynna, in der Enklave der Weltenwanderer im Nordosten, ist auf einige wichtige Informationen über unseren Feind gestoßen. Sucht sie auf und seht, ob sie Eure Hilfe benötigt.', },
    {'Magister Kaendris beim Sanktum der Sonne möchte, dass Ihr mit Waldläuferin Vynna bei der Enklave der Weltenwanderer in den Geisterlanden sprecht.', },
  },
  [9283] = {
    'Rettet die Überlebenden!',
    {'Jetzt haben wir wieder genügend Heilkristalle, aber sie sind nicht der einzige Weg, wie wir den Verletzten helfen können. Alle Draenei können die Gabe der Naaru einsetzen, um zu heilen. Ihr müsst den Überlebenden des Absturzes mit dieser Gabe helfen.|n|nDie meisten Überlebenden findet Ihr im Westen und Nordwesten, aber der Absturz hat uns alle im gesamten Tal verstreut.|n|nDie Überlebenden haben sehr unter der Strahlung der Energiekristalle gelitten, daher solltet Ihr sie an dem roten Schein, der sie umgibt, erkennen können.|n|nIhr müsst uns helfen, sie zu retten, $N!', },
    {'Wendet Eure Gabe der Naaru an, um einen der Überlebenden der Draenei zu heilen, die über das ganze Am\'mental verstreut sind. Kehrt dann zu Zalduun bei der Absturzstelle im Am\'mental zurück.', },
  },
  [9287] = {
    'Ausbildung zum Paladin',
    nil,
    nil,
  },
  [9288] = {
    'Ausbildung zum Jäger',
    nil,
    nil,
  },
  [9289] = {
    'Ausbildung zum Krieger',
    nil,
    nil,
  },
  [9290] = {
    'Ausbildung zum Magier',
    nil,
    nil,
  },
  [9291] = {
    'Ausbildung zum Priester',
    nil,
    nil,
  },
  [9292] = {
    'Gesprungener nekrotischer Kristall',
    {'Ihr entdeckt beim Körper der toten Monstrosität einen gesprungenen Kristall, der langsam mit nekrotischer Energie pulsiert.', },
    {'Bringt den gesprungenen nekrotischen Kristall zu Leutnant Orrin außerhalb der Tore von Sturmwind.', },
  },
  [9293] = {
    'Was getan werden muss...',
    {'Der nahegelegene See wurde von einem Energiekristall des Schiffs verseucht. Zahlreiche Pflanzen und Tiere des Am\'mentals sind deswegen mutiert.|n|nIch habe bereits eine Theorie aufgestellt, wie man den See heilen kann, allerdings brauche ich Proben von mutierten Wurzelpeitschern für eine Auswertung. Man findet sie im Westen der Am\'menfelder.|n|nWerdet Ihr mir helfen, $C?', },
    {'Sammelt 10 Peitscherproben ein und bringt sie zu Botanikerin Taerix bei der Absturzstelle im Am\'mental.', },
  },
  [9294] = {
    'Die Heilung des Sees',
    {'Dem Licht sei Dank, ich glaube es wird funktionieren! Ich habe einen Wirkstoff, den Ihr beim Silberwellensee im Süden einsetzen müsst. Er wird den Effekt des strahlenden Energiekristalls des Schiffs, der hier heruntergestürzt ist, neutralisieren.|n|nSchwimmt raus auf den See und verwendet dort den Neutralisierungswirkstoff. Keine Sorge, Ihr werdet der Strahlung nicht lange genug ausgesetzt sein, um verseucht zu werden.', },
    {'Verwendet den Neutralisierungswirkstoff bei dem strahlenden Energiekristall und kehrt anschließend zu Botanikerin Taerix bei der Absturzstelle im Am\'mental zurück.', },
  },
  [9295] = {
    'Brief von der Front',
    {'Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...', },
    {'Bringt den zerfledderten Brief zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
  [9296] = {
    nil,
    {'Der Stein strahlt eine dunkle Energie aus. Bringt ihn zu einer bestimmten Person.', },
    {'Bringt den dunklen nekrotischen Stein zu einer bestimmten Person.', },
  },
  [9297] = {
    nil,
    {'Der Stein strahlt eine dunkle Energie aus. Bringt ihn zu einer bestimmten Person.', },
    {'Bringt den dunklen nekrotischen Stein zu einer bestimmten Person.', },
  },
  [9298] = {
    nil,
    {'Der Stein strahlt eine dunkle Energie aus. Bringt ihn zu einer bestimmten Person.', },
    {'Bringt den dunklen nekrotischen Stein zu einer bestimmten Person.', },
  },
  [9299] = {
    'Notiz von der Front',
    {'Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...', },
    {'Bringt die verblichene Notiz zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
  [9300] = {
    'Nachricht von der Front',
    {'Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...', },
    {'Bringt die zerfranste Seite zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
  [9301] = {
    'Umschlag von der Front',
    {'Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...', },
    {'Bringt den blutbefleckten Umschlag zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
  [9302] = {
    'Schreiben von der Front',
    {'Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...', },
    {'Bringt das zerknitterte Schreiben zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
  [9303] = {
    'Immunisierung',
    {'Zhanaa braucht unsere Hilfe, um Teile aus der Exodar zu bergen. Taerix hat eine Immunisierungsmethode vorbereitet, mit der die Nisteleulkins behandelt werden können. Sie bewohnen die Gegend, in der die meisten Teile gefunden werden können.|n|nNähert Euch den noch nicht verseuchten Biestern und wendet den Kristall auf sie an. Die anderen müsst Ihr leider umbringen. Ihr findet sie im Nisteldickicht und bei den Nistelhügeln im Südosten.', },
    {'Wendet den Immunisierungskristall auf 6 Nisteleulkin an. Kehrt anschließend zu Verteidiger Aldar bei der Absturzstelle im Am\'mental zurück.', },
  },
  [9304] = {
    'Dokument von der Front',
    {'Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des Hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...', },
    {'Bringt das verschmierte Dokument zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
  [9305] = {
    'Ersatzteile',
    {'Wir konnten einen beschädigten holografischen Emitter nach dem Absturz bergen. Sollten wir ihn reparieren können, besteht die Möglichkeit, dass wir noch andere Überlebende außerhalb des Am\'mentals finden.|n|nVon dem Schiff hätte man einige Apparaturen sichern können, die geeignete Ersatzteile geliefert hätten, aber die heimischen Eulkin haben sie verschleppt, bevor wir sie überhaupt erreichen konnten.|n|n$N, Ihr müsst ins Nisteldickicht und in die Nistelhügel im Süden gehen und die Ersatzteile zurückholen!', },
    {'Beschafft 4 Emitterersatzteile und kehrt anschließend zu Technikerin Zhanaa bei der Absturzstelle im Am\'mental zurück.', },
  },
  [9306] = {
    'Sprecht mit Verteidiger Aldar',
    {'$N, Verteidiger Aldar hat sich nach jemandem umgesehen, der sich um unser Problem, das wir wegen der mutierten Eulkin im Nisteldickicht haben, kümmert. Es gilt den bedauerlichen Nebeneffekt unserer unbeabsichtigten Landung hier in den Griff zu bekommen.|n|nIhr findet ihn draußen im Süden bei der Absturzstelle. Bitte, sprecht mit ihm so bald Ihr könnt.', },
    {'Sprecht mit Verteidiger Aldar bei der Absturzstelle im Am\'mental.', },
  },
  [9307] = {
    'Mitleid',
    {'Der nahegelegene Silberwellensee wurde durch ein Teil des Schiffs, das in ihn stürzte, verseucht. Daraufhin sind die meisten Lebewesen in der Umgebung mutiert, manche wurden sogar feindselig. Am schlimmsten sind die mutierten Eulkin.|n|nGeht nach Süden ins Nisteldickicht und tötet so viele dieser bemitleidenswerten Kreaturen, wie Ihr könnt. Es ist eine traurige Aufgabe, $C, bitte macht es schnell und schmerzlos.', },
    {'Tötet 14 mutierte Eulkin und kehrt anschließend zu Verteidiger Aldar bei der Absturzstelle im Am\'mental zurück.', },
  },
  [9308] = {
    'Überreste eines Blutelfen?',
    {'Ihr vermutet, dass der tote Blutelf, dessen Überreste Ihr hier auf dem Boden liegend gefunden habt, den Sin\'dorei angehörte. Wie es aussieht, fiel er den wilden Klauen von mehreren mutierten Eulkin im Dickicht zum Opfer.|n|nBeim Durchsuchen des Leichnams entdeckt Ihr ein Amulett, das an einer Kette um seinen Hals hängt. Vielleicht ist es für Verteidiger Aldar von Interesse?', },
    {'Bringt das Blutelfenamulett zu Verteidiger Aldar bei der Absturzstelle im Am\'mental.', },
  },
  [9309] = {
    'Der vermisste Späher',
    {'Verschiedene Quellen konnten uns nun bestätigen, dass beim Schattenkamm ungewöhnliche Dinge vor sich gehen.|n|nDas ist äußerst beunruhigend, denn wir dachten, dass die bisherigen Aufklärungsmissionen gründlich genug gewesen wären. Einer meiner Späher hat sich noch nicht zurückgemeldet.|n|n$C, Ihr müsst für mich Richtung Südwesten gehen, zur anderen Uferseite des Silberwellensees, und Tolaan finden. Findet heraus, was ihn aufgehalten hat.', },
    {'Sprecht mit Tolaan im Schattenkamm im Am\'mental.', },
  },
  [9310] = {
    'Schwacher nekrotischer Kristall',
    {'Bringt den schwachen nekrotischen Kristall zu Leutnant Rukag im Hof von Unterstadt.', },
    {'Bringt den schwachen nekrotischen Kristall zu Leutnant Rukag im Hof von Unterstadt.', },
  },
  [9311] = {
    'Blutelfenspionage',
    {'Ich habe einen Plan. Wir müssen ihren Anführer umbringen. Vielleicht ziehen sie sich ohne ihren Meister zurück, um sich neu zu formieren. Wir müssen Zeit schinden, damit wir die Reparaturen abschließen können.|n|nVerteidiger Aldar muss davon erfahren. Tötet die Gutachterin und kehrt dann zu ihm zurück, um ihn zu erzählen, was wir herausgefunden haben.', },
    {'Tötet Gutachterin Kandress und informiert anschließend Verteidiger Aldar bei der Absturzstelle im Am\'mental über die Ereignisse.', },
  },
  [9312] = {
    'Der Emitter',
    {'$N, während Ihr den Schattenkamm erkundet habt, hat Zhanaa weiter am holografischen Emitter gearbeitet. Vielleicht solltet Ihr mit ihr sprechen.', },
    {'Sprecht mit Technikerin Zhanaa bei der Absturzstelle im Am\'mental.', },
  },
  [9313] = {
    'Reise zur Azurwacht',
    {'Soweit so gut, $N, Ihr müsst allerdings sofort zur Azurwacht reisen und mit Dyvuun sprechen!|n|nEs gibt einen Pfad, der westlich von dieser winzigen Insel führt. Folgt ihm und überquert den Kristallfluss, um auf den größeren Teil der Insel zu gelangen. Wenn Ihr dem Pfad noch weiter folgt, solltet Ihr die Azurwacht finden.|n|nVielleicht könnt Ihr sie ja überzeugen, uns etwas Hilfe und Vorräte zukommen zu lassen. Wir kommen nach, sobald wir können.|n|nIch danke Euch, ohne Euch hätten wir das nicht geschafft!', },
    {'Sprecht mit Techniker Dyvuun bei der Azurwacht auf der Azurmythosinsel.', },
  },
  [9314] = {
    'Nachricht von der Azurwacht',
    {'$C! Ein paar dieser mutierten Biester haben mich angesprungen und jetzt ist mein Bein verletzt.|n|nNachdem wir von Zhanaa gehört hatten, wurde ich von der Azurwacht auf eine Spähmission geschickt. Könntet Ihr vielleicht an meiner statt mit Versorgerin Chellan sprechen? Sie muss wissen, wie viele Leute sie in der Azurwacht erwarten soll. Ihr müsst lediglich den Kristallfluss hier überqueren und dem Pfad bis zur Azurwacht folgen.|n|nVergesst nicht, nach einer Unterkunft zu fragen, wenn Ihr dort seid.', },
    {'Sprecht mit Versorgerin Chellan bei der Azurwacht auf der Azurmythosinsel.', },
  },
  [9315] = {
    nil,
    {'Kommt näher, ich... ich sterbe.|n|nMan entsandte mich hierher, um... um die Neruber zu besiegen, doch Vandril konnte nicht ahnen, dass sie... sie eine Anführerin haben.|n|n<Der sterbende Blutelf spuckt etwas Blut.>|n|nIhr müsst Anok\'suten finden und... und töten. Sie wandert in der Umgebung von... Sonnenkuppe umher.', },
    {'Tötet Anok\'suten und kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.', },
  },
  [9316] = {
    'Wilde Goblins',
    {'<Brianna schaut Euch prüfend an.>|n|nIhr wollt also ein paar Goblins töten, was? Nun, wenn Ihr dazu bereit seid, könnt Ihr mit den Wilden in der Nähe anfangen. Bringt mir ihre Zähne als Beweis Eurer Taten.', },
    {'Brianna Schneider auf der Designerinsel möchte, dass Ihr ihr 10 Goblinzähne bringt.', },
  },
  [9317] = {
    'Geweihte Wetzsteine',
    nil,
    nil,
  },
  [9318] = {
    'Gesegnetes Zauberöl',
    nil,
    nil,
  },
  [9319] = {
    'Licht im Dunkeln',
    {'Wir sind nicht die Einzigen, die dieses Fest feiern, $N. Die Flamme ist ein wichtiger Bestandteil aller Lebewesen, aller Kulturen. Selbst an den dunkelsten Orten beginnen die Feuer zu leuchten.|n|nWenn Ihr dergleichen sehen möchtet, so wagt Euch in die Tiefe. Sucht nach den Freudenfeuern in Stratholme, Scholomance, bei den Ogern des Düsterbruchs und in den Hallen der Schwarzfelsspitze selbst. Ich erwarte Eure Rückkehr.', },
    {'Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Kehrt dann zum Flammenbewahrer zurück.', },
  },
  [9320] = {
    'Erstklassiger Manatrank',
    nil,
    nil,
  },
  [9321] = {
    'Erstklassiger Heiltrank',
    nil,
    nil,
  },
  [9322] = {
    'Glühende Feuer in Kalimdor',
    {'Die Freudenfeuer des Sonnenwendfests werden überall in Azeroth gefeiert, die mannigfaltigen Länder Kalimdors sind dabei keine Ausnahme. Ihr scheint mir tauglich für eine Reise - wie wäre es mit einem Ausflug?|n|nDas Sonnenwendfest ist erst dann ein Ereignis, wenn man die blau glühenden Feuer in der Welt gesehen hat. Die Feiernden haben Feuer im eisigen Westen von Winterquell, im Nordosten von Azshara, in der Nähe der Heldenwacht in Silithus und beim Eingang zum üppigen Krater von Un\'Goro entzündet. Kehrt zu mir zurück, sobald Ihr die Reise beendet habt.', },
    {'Sucht die Lager des Sonnenwendfests in Azshara, Silithus, dem Krater von Un\'Goro und Winterquell auf. Kehrt dann zum Flammenbewahrer zurück.', },
  },
  [9323] = {
    'Glühende Feuer in den Östlichen Königreichen',
    {'Das Fest der Flamme ist im ganzen Land verbreitet, $C. Kein Ort bleibt von der Wärme dieses Ereignisses unberührt, und die prächtigsten Feuer lodern in einem strahlenden Blau. Sucht nach ihnen.|n|nEines befindet sich genau nördlich von der Schwarzfelsspitze. Die anderen liegen tief im Innern der Östlichen Pestländer, in der Nähe eines verfallenen Dorfes; entlang der Straße, die zu den Klippen im bergigen Hinterland führt, und auf dem Weg zu dem Dunklen Portal in den Verwüsteten Landen.|n|nKehrt anschließend zu mir zurück.', },
    {'Reist zu den Lagern des Sonnenwendfests in den Verwüsteten Landen, den Östlichen Pestländern, dem Hinterland und der Sengenden Schlucht. Kehrt dann zum Flammenbewahrer zurück.', },
  },
  [9324] = {
    'Raubt die Flamme von Orgrimmar',
    {'Die Flamme, die aus dem Zentrum von Orgrimmar entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...', },
    {'Bringt die Flamme von Orgrimmar zum Meister der Lehren.', },
  },
  [9325] = {
    'Raubt die Flamme von Donnerfels',
    {'Die Flamme, die dem Schamanen von Donnerfels entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...', },
    {'Bringt die Flamme von Donnerfels zum Meister der Lehren.', },
  },
  [9326] = {
    'Raubt die Flamme von Unterstadt',
    {'Die Flamme, die aus den Ruinen über Unterstadt entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...', },
    {'Bringt die Flamme von Unterstadt zum Meister der Lehren.', },
  },
  [9327] = {
    'Die Verlassenen',
    {'Ich weiß, es mag seltsam erscheinen, aber die Verlassenen sind hier, um uns zu helfen. Ihr solltet mit Hochexekutor Mavren sprechen. Er befindet sich in dem Turm im Westen der Stadt.|n|nWenn Ihr mit ihm gesprochen habt, kehrt bitte zu mir zurück, es gibt da eine schlimme Angelegenheit, bei der ich dringend Eure Unterstützung benötige.', },
    {'Sprecht mit Hochexekutor Mavren in Tristessa in den Geisterlanden.', },
  },
  [9328] = {
    'Held der Sin\'dorei',
    {'Dies ist der Beginn eines neuen Zeitalters für unser Volk, $N. Wir werden unser Land zurückerobern und unseren Bund mit Sylvanas und ihren Verbündeten festigen.|n|nBringt den Kopf des Verräters nach Silbermond, zu Lor\'themar Theron, dem Lordregenten Silbermond. Er wird begierig sein, die Neuigkeit zu erfahren.', },
    {'Bringt Dar\'Khans Kopf zu Lor\'themar Theron in Silbermond.', },
  },
  [9329] = {
    'Die Verlassenen',
    {'Ich weiß, es mag seltsam erscheinen, aber die Verlassenen sind hier, um uns zu helfen. Ihr solltet mit Hochexekutor Mavren sprechen. Er befindet sich in dem Turm im Westen der Stadt.|n|nWenn Ihr mit ihm gesprochen habt, kehrt bitte zu mir zurück, es gibt da eine schlimme Angelegenheit, bei der ich dringend Eure Unterstützung benötige.', },
    {'Sprecht mit Hochexekutor Mavren in Tristessa in den Geisterlanden.', },
  },
  [9330] = {
    'Raubt die Flamme von Sturmwind',
    {'Die Flamme, die aus dem Zentrum von Sturmwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...', },
    {'Bringt die Flamme von Sturmwind zum Geschichtenerzähler.', },
  },
  [9331] = {
    'Raubt die Flamme von Eisenschmiede',
    {'Die Flamme, die aus dem Zentrum von Eisenschmiede entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...', },
    {'Bringt die Flamme von Eisenschmiede zum Geschichtenerzähler.', },
  },
  [9332] = {
    'Raubt die Flamme von Darnassus',
    {'Die Flamme, die von der Küste Teldrassils entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...', },
    {'Bringt die Flamme von Darnassus zum Geschichtenerzähler.', },
  },
  [9333] = {
    'Handschuhe der Argentumdämmerung',
    nil,
    nil,
  },
  [9334] = {
    'Gesegnetes Zauberöl',
    nil,
    nil,
  },
  [9335] = {
    'Geweihte Wetzsteine',
    nil,
    nil,
  },
  [9336] = {
    'Erstklassiger Heiltrank',
    nil,
    nil,
  },
  [9337] = {
    'Erstklassiger Manatrank',
    nil,
    nil,
  },
  [9338] = {
    'Treue zum Zirkel des Cenarius',
    nil,
    nil,
  },
  [9339] = {
    'Der Lohn des Diebes',
    nil,
    {'Bringt die Flamme von Sturmwind zu $N.', },
  },
  [9340] = {
    'Die Große Kluft',
    {'Wir stehen kurz davor, vollständig von den Streitkräften der Allianz eingekesselt zu werden. Mit dem ständigen Zustrom von Sin\'doreiflüchtlingen aus Azeroth, müssen wir einen Weg finden, der vor den neugierigen Blicken des Feindes sicher ist.|n|nIch habe darüber etwas nachgedacht und bin kürzlich zu einer Lösung gekommen. Wir werden eine sichere Passage durch die Große Kluft etablieren.|n|nJa, auch wenn es dort nur so von tödlichen Felsklauen wimmelt, sind sie doch nichts weiter als bloße Tiere, denen wir beibringen können, uns zu fürchten. Ich möchte, dass Ihr loszieht und eine größere Anzahl dieser Biester erlegt. Zeigen wir ihnen, was Angst ist!', },
    {'Waldläuferhauptmann Venn\'ren in der Falkenwacht möchte, dass Ihr 8 Steinsichelwelpen und 3 Steinsichelalphas bei der Großen Kluft östlich der Falkenwacht erlegt.', },
  },
  [9341] = {
    'Wappenrock der Argentumdämmerung',
    nil,
    nil,
  },
  [9342] = {
    'Plündernde Krustenbohrer',
    {'Als ob es nicht schon schlimm genug wäre, dass die Gan\'arg in den Minen eingefallen sind, rücken uns nun diese Riesenwürmer von der anderen Seite auf die Pelle!|n|nDa Thrallmars Garnison mit der Verteidigung gegen die Legion und dem Pflegen der Verwundeten beschäftigt ist, bedeutet das, dass ich und die Minenarbeiter uns um dieses Problem kümmern müssen.|n|n<Der Großknecht zeigt auf die schlafenden Peons.>|n|nUnd Ihr sehr ja selbst wie hilfreich sie sind...|n|nIch bezahle Euch gerne ihr Gehalt, wenn Ihr ein paar dieser Würmer vernichtet.', },
    {'Großknecht Razelcraz bei den Minen in der Nähe von Thrallmar möchte, dass Ihr 15 plündernde Krustenbohrer tötet. Die Würmer haben die Angewohnheit, unplötzlich aus ihren unterirdischen Tunneln anzugreifen.', },
  },
  [9343] = {
    'Wappenrock der Argentumdämmerung',
    nil,
    nil,
  },
  [9344] = {
    'Der überstürzte Aufbruch',
    {'Seid gegrüßt, $N. Die Scherbenwelt ist ein Ort voller Gefahren, beinahe jedes Mitglied unserer Expedition musste diese leidvolle Erfahrung machen. Ich befürchte, der junge Grelag hat diese Lektion aus erster Hand erfahren.|n|nEr ist ein viel versprechender Schüler, doch es mangelt ihm an Geduld! Er studiert mit Begeisterung die Geschichte seines Volkes und vergisst dabei manchmal die Gefahren des heutigen Lebens.|n|nEr ist zum Rückenbrecherposten aufgebrochen, ohne an die Legion und die Höllenorcs zu denken. Ich habe Angst, dass ihm etwas zugestoßen ist.', },
    {'Scharfseherin Regulkut möchte, dass Ihr ihren Schüler Grelag findet.', },
  },
  [9345] = {
    'Herstellung der Salbe',
    {'Als ich gerade Zeth\'Gor erkennen konnte, wurde ich von einer Patrouille der Legion entdeckt. Ich rannte los in der Hoffnung, dass ich mich in einem der Türme in der Ferne verstecken kann, aber einer ihrer Teufelshunde hat mich eingeholt und mich fast zerfleischt!|n|nIch konnte entkommen, aber mein Bein ist in einem sehr schlechten Zustand. Steingardist Ambelan hat mich gefunden und hierher gebracht.|nJetzt muss ich einen Weg finden, um mein Bein zu versorgen. Wirbelkraut wächst in und um das Tal der Knochen im Norden herum. Eine Salbe daraus wird den Schmerz lange genug betäuben, dass ich weiterreisen kann.', },
    {'Grelag im Rückenbrecherposten möchte, dass Ihr ihm 12 Höllenwirbelkräuter für seine Salbe bringt.', },
  },
  [9346] = {
    'Wenn Hölleneber fliegen',
    {'Habt Ihr schon mal einen fliegenden Hölleneber gesehen? Die brauchen nicht mal Flügel!|n|n<Wachtkommandant Krunk lacht schallend.>|n|nDer Kampf gegen die Lager der Legion im Norden hat unsere Vorräte restlos erschöpft, einschließlich der Katapultmunition. Also der perfekte Augenblick, mal etwas völlig Neues auszuprobieren.|n|nStatt Steine zu verschießen, dachte ich daran, die Kadaver verhungernder Hölleneber in Brand zu stecken, um damit die Lager der Legion zu bombardieren.|n|nMeldet Ihr Euch freiwillig oder muss ich Euch erst dazu zwingen?', },
    {'Wachtkommandant Krunk in Thrallmar möchte, dass Ihr ihm 10 klobige Hölleneberkadaver von verhungernden Höllenebern bringt.', },
  },
  [9347] = {
    'Wilde Leerwandler',
    {'Als Ihr die Essenz eingehender betrachtet, erblickt Ihr bösartig umherwirbelnde Energien, die in einem Gefäß aus einem unbekannten Material eingeschlossen sind. Ihr haltet einen Moment inne und fühlt, wie sich irgendetwas in Eure Gedanken schleicht und Ihr verspürt das Verlangen, näher zu kommen und tiefer in die Essenz zu blicken.|n|nAls Ihr bemerkt, dass Euer Bewusstsein immer mehr abgleitet, wendet Ihr erschrocken Euren Blick ab. Während Ihr überlegt, was Ihr mit Eurem Fund anstellen sollt, bemerkt Ihr am Rande Eures Bewusstseins noch immer die lauernde Gegenwart der Essenz.', },
    {'Bringt die pulsierende Leerwandleressenz zu Mahuram Starkhuf in Thrallmar.', },
  },
  [9348] = {
    'Felshetzerzusammentrieb',
    {'Die Scherbenwelt ist voller faszinierender Lebewesen. Faszinierend und extrem tödlich.|n|nDas Land beherbergt eine große Zahl der unterschiedlichsten Raubtiere. Das erscheint zunächst seltsam für solch ein ödes Land, doch bei genauer Betrachtung haben diese Kreaturen untereinander eine Art Hierarchie entwickelt.|n|nDie Felsklauen haben sich eine weitere tödliche Bestie untertan gemacht, den Felshetzer. Anscheinend züchten und halten sie diese als Jagd- und Wachtiere. Ich muss unbedingt in Erfahrung bringen, mit welchen Methoden sie die Felshetzer abrichten. Dazu müssen wir ihre Brutstätte nahe Terokkar im Südwesten ausräuchern und untersuchen.', },
    {'Tötet 10 gefangene Felshetzerjungtiere und sammelt 12 Felshetzereier für Mahuram Starkhuf in Thrallmar.', },
  },
  [9349] = {
    'Felshetzereier sammeln',
    {'Ich bin am verhungern!|n|nIst das nicht ironisch? Ein verhungernder Koch?|n|n<Legassi lacht halbherzig und tippt auf ein gefaltetes Pergament in seiner Tasche.>|n|nLaut dieser Touristenkarte, der wir gefolgt waren, bevor wir so hinterhältig niedergeschossen wurden, gibt es im Südwesten eine Gegend, nahe bei den Wäldern von Terokkar. Sie wird der Messerdornpfad genannt und angeblich soll es dort von leckeren Felshetzereiern nur so wimmeln!|n|nIch könnte ein tolles Festmahl daraus zaubern, wenn nur jemand mutig genug wäre, dorthin zu gehen und ein paar zu sammeln!', },
    {'Bringt 12 Felshetzereier zu Legassi bei der Zeppelinabsturzstelle auf der Höllenfeuerhalbinsel.', },
  },
  [9350] = {
    'Die Arbeit eines Peons ist nie zu Ende',
    {'Die dauernden Angriffe der Legion haben unsere Verteidigung schwer in Mitleidenschaft gezogen. Wenn die Palisaden fallen, fällt auch Thrallmar. Ich habe die Peons beauftragt, den Wall zu verstärken und reparieren, aber uns gehen die Materialien aus.|n|nGrelag, einer der Schüler der Scharfseher, kennt sich gut mit den alten Riten aus und hat vorgeschlagen, auf einen Brauch unserer Vorfahren zurückzugreifen. Vor langer Zeit versorgte die Grollhufjagd uns mit Fleisch, Fellen und Knochen. Wenn wir die Jagd auf die Grollhufe im Südosten wieder aufnehmen, bekommen wir alles, was wir brauchen, und ehren gleichzeitig unsere Vorfahren.', },
    {'Sammelt 8 Grollhufbälge und 8 Grollhufknochen von tobenden Grollhufen. Kehrt zu Wachkommandant Krunk in Thrallmar zurück, wenn Ihr alle Materialien beisammen habt.', },
  },
  [9351] = {
    'Wilde Leerwandler',
    {'Auch wenn ich den Rahmen des Zeppelins repariert bekomme, muss ich einen Ersatztreibstoff finden! Ich habe kein Benzin mehr, und es gibt weit und breit keine Tankstelle!|n|nSüdlich von hier liegt eine Gegend namens Sphärenfelder. Dort wimmelt es nur so von wilden und unkontrollierten Leerwandlern, aber für mich sind sie eher wandelnde Batterien.|n|nWenn Ihr mir genug von Ihrer Essenz bringt, kann ich damit den Motor des Zeppelins zum Laufen bekommen. Ich wette fünf Gold, dass ich dann sogar einen niedrigeren Verbrauch habe!', },
    {'Bringt 10 kondensierte Leerwandleressenzen zu "Schreihals" Quack Lufthans bei der Zeppelinabsturzstelle.', },
  },
  [9352] = {
    'Darnassische Eindringlinge',
    {'Abgesehen von der konstanten Bedrohung durch die Getriebenen, befasse ich mich auch mit den zahlreichen Berichten über angebliche Nachtelfensichtungen.|n|nObwohl viele dieser Sichtungen frei erfunden sind, gibt es doch einen Vorfall, der weiterer Untersuchungen bedarf. Das Sanktum des Westens, eine unserer primären Energiequellen, hatte eine massive Fehlfunktion und Gerüchte, eine darnassische Sabotageaktion sei der Grund dafür, machen die Runde.|n|nBegebt Euch dorthin und kümmert Euch um jeden, der verdächtig aussieht. Meldet Euch bei Leybewahrerin Velania, sie überwacht das Sanktum.', },
    {'Reist zum Sanktum des Westens südwestlich vom Falkenplatz und vernichtet jegliche Eindringlinge, die Ihr dort findet. Berichtet anschließend Leybewahrerin Velania.', },
  },
  [9353] = {
    'iCoke-Geschenkgutschein einlösen',
    nil,
    nil,
  },
  [9354] = {
    'Auf der Suche nach neuen Materialien',
    {'<Der Zwerg schaut erwartungsvoll von seiner Arbeit auf.>|n|nWenn Ihr etwas bestellen wollt, stell Euch hinten an, $C. Ich habe beide Hände mit der Reparatur der Ausrüstung der Söhne und den Vorbereitungen für den Tag, an dem wir wieder in die Schlacht gegen den Feind ziehen, voll.|n|nSeit die Krustenbohrer in den Minen eingefallen sind, nehmen unsere Metallvorräte stetig ab. Ich habe schon mit natürlichen Materialien von den tobenden Grollhufen, die nordwestlich der Feste grasen, experimentiert. Auch wenn sie kein Ersatz für Eisen sind, kann ich sie gut einsetzen.', },
    {'Sammelt 8 Grollhufbälge und 8 Grollhufsehnen von den tobenden Grollhufen. Wenn Ihr die Materialien habt, bringt sie zu Humphry in der Ehrenfeste.', },
  },
  [9355] = {
    'Eine Aufgabe für einen intelligenten Helden',
    {'Gut, $C. Nun, da die Verstärkung anrückt, können wir endlich wieder ein mehr oder weniger normales Leben führen.|n|nEines unserer ersten Ziele ist die Wiederaufnahme des Transports von Männern und Waren auf der Straße nach Südwesten, aber dazu müssen wir sie erst von den Krustenbohrern zurückfordern, die diese Gegend in Beschlag genommen haben.|n|nWenn Ihr uns bei dieser Aufgabe helfen würdet, wären die Söhne Euch sehr dankbar. Gebt auf die aufgewühlte Erde Acht, die sie hinterlassen!', },
    {'Tötet 15 plündernde Krustenbohrer und kehrt dann zu Großknecht Biggums in der Ehrenfeste zurück.', },
  },
  [9356] = {
    'So weich wie Butter',
    {'Quack sagt immer, er fliegt "so weich wie Butter". Ich glaube eher, sein Kopf ist so "weich wie Butter"!|n|nSchaut Euch nur die Trümmer da drüben an. Er nennt das eine "harte" Landung.|n|nKlar, wir wurden beschossen, und ich würde es ihm ja auch nachsehen, wenn er nicht immer so mit seinen Flugkünsten angeben würde!|n|nIch glaube, ich koche ihm ein paar Flügel, um ihm einmal einen Wink mit dem Zaunpfahl zu geben. Im Osten, im Tal der Knochen, findet Ihr Knochenhäuterbussarde. Ihre Flügel sind fleischig, dick und perfekt für meine Zwecke.', },
    {'Bringt 12 fleischige Bussardflügel zu Legassi bei der Zeppelinabsturzstelle.', },
  },
  [9357] = {
    'Meldet Euch bei Aeldon Sonnenmal',
    {'Wenn Ihr nach Arbeit sucht, dann sprecht mit Hauptmann Sonnenmal beim inneren Elfentor, geht einfach durch die Türen hinter mir.|n|nLasst mich jetzt in Ruhe, ich muss diesen Halunken verhören.', },
    {'Meldet Euch bei Aeldon Sonnenmal beim inneren Elfentor im Immersangwald.', },
  },
  [9358] = {
    'Waldläuferin Sareyn',
    {'Betrachtet die Sicherheit dieses Orts nicht als selbstverständlich. Wir werden von der Geißel im Osten und von den Getriebenen im Westen belagert.|n|nWaldläuferin Sareyn sichert unsere Grenzen vor den Untoten, die uns von der Todesschneise her bedrängen. Folgt der Straße in Richtung Osten und erkundigt Euch, ob sie Unterstützung braucht.', },
    {'Meldet Euch bei Waldläuferin Sareyn außerhalb von Morgenluft im Immersangwald.', },
  },
  [9359] = {
    'Zuflucht der Weltenwanderer',
    {'Ihr habt uns geholfen die Getriebenen wieder unter Kontrolle zu bekommen und dies war von unschätzbarem Wert. Die Weltenwanderer könnten jemanden wie Euch in ihrem Kampf gegen die Amanitrolle gebrauchen.|n|nHaltet nach der Zuflucht der Weltenwanderer nordöstlich von hier Ausschau, sprecht mit Leutnant Dämmerflucht und erkundigt Euch, ob sie Unterstützung braucht.', },
    {'Meldet Euch bei Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer im Immersangwald.', },
  },
  [9360] = {
    'Angriff der Amani',
    {'Ihr versteht zwar die Sprache dieser Schlachtpläne nicht, aber Ihr könnt klar eine Karte mit den eingetragenen Positionen der Zuflucht der Weltenwanderer und von Morgenluft ausmachen.|n|nAm besten informiert Ihr Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer darüber.', },
    {'Bringt die Angriffspläne der Amani zu Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer.', },
  },
  [9361] = {
    'Hölleneber, die etwas andere Delikatesse',
    {'Diese Eier sind wundervoll, aber was haltet Ihr davon, wenn wir noch einen Zahn zulegen?|n|nEine Scheibe Speck würde unser Mahl erst richtig abrunden, und ich weiß ganz genau, wo man sie herbekommen könnte.|n|nDieser Ort wimmelt nur so von Höllenebern. Natürlich kann hier niemand das Fleisch überprüfen und weichklopfen, aber wir haben Glück!|n|n<Legassi kramt in seinem Beutel und holt eine Flasche hervor.>|n|nDies wurde zwar nicht gemacht, um es mit Schweinefleisch zu benutzen, aber Improvisation ist alles!', },
    {'Legassi bei der Zeppelinabsturzstelle möchte, dass Ihr 8 Stück geläutertes Hölleneberfleisch sammelt. Um das Fleisch zu reinigen, schüttet die Läuterungsmischung über das besudelte Hölleneberfleisch, das Ihr von den Höllenebern gesammelt habt.', },
  },
  [9362] = {
    'Kriegsherr Krellian',
    {'Die Zeit drängt, $N! Meine Orakelsprüche haben eine mächtige Quelle der Magie offenbart. Ich kann den Turm nicht verlassen und bitte Euch deshalb, diese bösartige Kreatur, die im Besitz dieses Artefakts ist, zu töten.|n|nDer erbärmliche Schwachkopf ist bekannt als Kriegsherr Krellian und versteckt sich hinter seinen Wachen im Tempel von Zin-Malor. Verbrennt ihn zu Asche und nehmt die prismatische Muschel, die er so begehrt, an Euch.', },
    {'Beschafft die prismatische Muschel für Erzmagier Xylem. Der Erzmagier befindet sich in einem Turm auf den Klippen von Azshara.', },
  },
  [9363] = {
    'Warnt Morgenluft',
    {'Geht nach Morgenluft und klärt Waldläufer Degolien über die Pläne der Amani auf. Morgenluft muss sich auch nach dem Tod von Zul\'marosh noch auf einen Angriff der Trolle vorbereiten. Sagt Degolien, dass ich ihm so schnell wie möglich Verstärkung schicken werde.', },
    {'Reist nach Morgenluft im Immersangwald und sprecht mit Waldläufer Degolien.', },
  },
  [9364] = {
    'Gespaltene Magie',
    {'Meine Untersuchungen haben den einzigartigen Zweck für die prismatische Muschel enthüllt.|n|nGreift die Grollflossen von Azshara mit Verwandlungszaubern an und tragt dabei diese Muschel bei Euch. Wenn Ihr einen Moment wartet, wird die chaotische Aura der Muschel dafür sorgen, dass sie sich für eine kurze Zeit in mehrere kleinere Versionen aufspalten. Tötet diese Kopien so schnell wie möglich, und deren gespaltene Essenzen werden in der Muschel gesammelt.|n|nKehrt zu mir zurück, sobald die Muschel gefüllt ist.', },
    {'Verwandelt die Grollflossen von Azshara und tötet die Kopien, die einige Sekunden später auftauchen. Wenn Ihr 50 verwandelte Kopien vernichtet habt, kehrt zu Erzmagier Xylem in Azshara zurück.', },
  },
  [9365] = {
    'Der Lohn des Diebes',
    nil,
    {'Bringt die Flamme von Sturmwind zu $N.', },
  },
  [9366] = {
    'Die Suche nach Teufelsblut',
    {'Nordöstlich von hier liegen die Teiche von Aggonar. Vor langer Zeit waren sie ein Heiligtum der Draenei, doch fielen sie der Verderbnis anheim, als das Blut des Dämonen Aggonar in die heiligen Wasser vergossen wurde.|n|nObwohl es alt und verwässert ist, ist das Blut noch immer von einer enormen Macht erfüllt. Angetrieben durch die puren dämonischen Energien des ursprünglichen Blutes, durchstreifen Terrorbestien dieses Gebiet. Vernichtet sie und sammelt so viel von dem Teufelsblut ein, wie Ihr tragen könnt. Ich werde Euch fürstlich belohnen.', },
    {'Ryathen der Düstere an der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 6 Teufelsblutproben von den Terrorbestien bringt, die bei den Teichen von Aggonar umherstreifen.', },
  },
  [9367] = {
    'Das Fest des Feuers',
    {'Die Zeit des Sonnenwendfests ist wieder angebrochen!|n|nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.|n|nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!', },
    {'Wärmt Euch an den Freudenfeuern in Sturmwind, Eisenschmiede und Darnassus. Sprecht anschließend mit einem Meister der Lehren innerhalb der Hauptstädte.', },
  },
  [9368] = {
    'Das Fest des Feuers',
    {'Die Zeit des Sonnenwendfests ist wieder angebrochen!|n|nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.|n|nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!', },
    {'Wärmt Euch an den Freudenfeuern in Orgrimmar, Donnerfels und Unterstadt. Sprecht anschließend mit einem Geschichtenerzähler innerhalb der Hauptstädte.', },
  },
  [9369] = {
    'Wiederaufladen der Heilkristalle',
    {'Wir sind die Draenei. Unser Schiff ist hier abgestürzt und es gibt etliche Verwundete. Unsere dringlichste Sorge ist die Erschöpfung unserer Heilkristalle. Wir müssen sie so schnell wie möglich wieder aufladen!|n|nUnglücklicherweise können wir das derzeit nur, indem wir das Blut der einheimischen Talmotten abzapfen. Ihr Blut eignet sich als Ersatzstoff.|n|nMan findet die Motten entlang des gesamten Tals, jedoch verstärkt im Nordwesten.', },
    {'Beschafft Euch 6 Phiolen mit Mottenblut von den in der Nähe hausenden Talmotten und bringt sie zu Proenitus bei der Absturzstelle im Am\'mental.', },
  },
  [9370] = {
    'Stoppt das Säuberungsritual',
    {'Unsere Späher haben kürzlich einen Paladin der Draenei in der Nähe der Teiche von Aggonar aufgegriffen. Wir nehmen an, dass er vorhatte, an einem Säuberungsritual zur Reinigung der Teiche teilzunehmen. Natürlich müssen wir das Vorhaben der Draenei stoppen, oder unsere Teufelsblutquelle wird für immer versiegen.|n|nEr hatte diesen Signalstein bei sich. Offensichtlich hatte er den Auftrag, einen sicheren Ort zu markieren, an dem ein Priester - sie selbst nennen sich \'Anachoret\' - in aller Sicherheit ein Säuberungsritual durchführen kann. Nehmt den Stein und platziert ihn am Altar von Aggonar und bereitet einen Hinterhalt für die eintreffenden Draenei vor.|n|nIch schlage vor, dass Ihr besser ein oder zwei Freunde mit Euch bringt.', },
    {'Platziert den Signalstein bei den Teichen von Aggonar am Altar von Aggonar und besiegt alle Anachoreten der Draenei, die auf Eure Signal reagieren. Kehrt anschließend mit dem Signalstein zu Ryathen dem Düsteren bei der Falkenwacht zurück.', },
  },
  [9371] = {
    'Botanikerin Taerix',
    {'$N, Botanikerin Taerix braucht Eure Hilfe. Bitte, sucht sie bei ihren Lehrlingen außerhalb der Westseite des Schiffes auf.', },
    {'Sprecht mit Botanikerin Taerix bei der Absturzstelle im Am\'mental.', },
  },
  [9372] = {
    'Dämonische Verderbnis',
    {'Willkommen im Posten des Cenarius, $C. Wir bekommen hier draußen nicht oft Besuch, daher freue ich mich ganz besonders über Eure Anwesenheit. Meine Arbeit mit den Lebewesen dieser trostlosen Umgebung macht es oft erforderlich, alleine in die abgelegensten Winkel zu reisen.|n|nDie Expedition des Cenarius hat mich mit dem Studium einiger der gefährlichsten Tiere der Scherbenwelt beauftragt, und dabei habe ich eine verblüffende Entdeckung gemacht. Obwohl viele Kreaturen bereits massive Veränderungen durchgemacht haben, scheint die Verderbnis noch immer neue Mutationen hervorzurufen. Ich habe mit dem Sammeln von Blutproben begonnen, um diese Veränderungen zu dokumentieren, und dabei ist mir jede Hilfe recht.', },
    {'Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel möchte, dass Ihr 6 Blutproben eines Höllenebers von bulligen Höllenebern sammelt.', },
  },
  [9373] = {
    'Fehlender Schriftverkehr',
    {'Bei der Untersuchung des ramponierten Lederkoffers stellt Ihr fest, dass die Beschädigung des Behälters von der ätzenden Flüssigkeit im Verdauungstrakt des Wurms herrühren muss. Das Leder scheint einst kunstvoll verarbeitet gewesen zu sein, aber die Verzierungen sind nicht mehr deutlich sichtbar.|n|nDas Einzige, was noch zu erkennen ist, ist ein abgenutztes Symbol des Zirkels des Cenarius. Da Ihr nichts über den Inhalt wisst, haltet Ihr es für das Beste, den Koffer zu einem Mitglied des Zirkels zu bringen.', },
    {'Bringt den zerfressenen Lederkoffer zu Thiah Rotmähne in der Nähe der Ruinen von Sha\'naar im westlichen Teil der Höllenfeuerhalbinsel.', },
  },
  [9374] = {
    'Arelions Tagebuch',
    {'Mein Mann Arelion war seit unserer Ankunft in der Scherbenwelt von den Teichen von Aggonar fasziniert. Er verbrachte fast seine gesamte Zeit mit dem Studium der heimischen Schleimarten!|n|nVor einigen Tagen verschwand er spurlos. Man sagte mir, dass er tot sei und dass ich nichts mehr für ihn tun könnte.|n|nDoch was ich noch zu tun vermag, ist sicherzustellen, dass seine Forschungen nicht mit ihm gestorben sind. Begebt Euch zu den Teichen im Nordosten und haltet nach den Seiten seines Tagebuchs Ausschau. Er bewahrte sie immer in einem braunen Wanderknappsack auf.', },
    {'Magistrix Carinda bei der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr zu den Teichen von Aggonar reist und Arelions Tagebuch sucht.', },
  },
  [9375] = {
    'Der Weg zur Falkenwacht',
    {'<Auf dem geschundenen Gesicht der Blutelfe zeichnet sich bei Eurem Anblick Erleichterung ab.>|n|nBitte, $C, holt mich aus diesem Käfig heraus! Ich bin der Gruppe aus Thrallmar, trotz Martik Tor\'seldoris Warnungen, vorausgereist.|n|nSchreckliche Kreaturen lauerten mir auf. Ich glaube, es waren diese Felshetzer, von denen er immer sprach. Zunächst gelang es mir ihnen zu entkommen, doch das war erst der Anfang meiner Schwierigkeiten.|n|nIch verband gerade meine Wunden, als mich die Vogelmenschen fanden und zurück in ihre Höhle schleiften, wo sie mich in diesen Käfig sperrten! Ich muss unbedingt zur Falkenwacht!', },
    {'Beschützt die verwundete Blutelfenpilgerin auf Ihrem Weg zur Falkenwacht und sprecht dann mit Taleris Morgenblick.', },
  },
  [9376] = {
    'Die Pflicht eines Pilgers',
    {'Diese verletzte Pilgerin schreit irgendwas von einem Beutel.|n|nHabt Ihr einen Beutel in der Nähe gesehen, als Ihr sie gefunden habt? Hmm...|n|nIhre Angreifer müssen sich damit aus dem Staub gemacht haben, als sie sie vertrieben hat. Die Stachelklauenfelshetzer aus der Schlucht im Süden sind bekannt dafür, dass sie einsame Reisende angreifen.|n|nWenn sie sich nicht beruhigt, kann ich ihre Wunden nicht behandeln. Ihre Sturheit könnte sie das Leben kosten.|n|nGeht zur Staubstachelschlucht und haltet nach ihrem Lager Ausschau. Ich möchte wetten, dass sie ihn da verloren hat.', },
    {'Die verletzte Blutelfpilgerin wurde von giftigen Stachelklauenfelshetzern angegriffen, als sie die Staubstachelschlucht erkunden wollte. Findet ihr Lager und haltet nach dem vermissten Beutel Ausschau.', },
  },
  [9377] = {
    'Hunger nach Macht',
    {'Falkenwacht ist ein stark besuchter Zwischenstopp für alle Pilger auf ihrer langen Reise in die Scherbenwelt. Obwohl wir einer der ersten Außenposten auf dem Weg in die Scherbenwelt sind, erreichen uns viele der Pilger in einem Zustand totaler Erschöpfung, ausgemergelt durch ihre Abhängigkeit.|n|nIn einer Welt wie dieser, versuchen die meisten von ihnen nun ihre Abhängigkeit von der Magie unter Kontrolle zu halten. Essen und Trinken helfen fürs Erste, $C, doch der Durst nach magischen Energien ist ihr stärkstes Verlangen. Die Überreste von Leerwandlern aus der Scherbenwelt sind eine mächtige Energiequelle, allerdings gibt es nicht viele davon, man findet sie lediglich bei den Sphärenfeldern.', },
    {'Beschafft eine potente Leerwandleressenz von den unkontrollierten Leerwandlern und kehrt anschließend zu Taleris Morgenblick in der Falkenwacht zurück.', },
  },
  [9378] = {
    'Die Zitadelle des Schreckens - Naxxramas',
    {'Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch, dort hineinzugelangen, von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichtegemacht. Zumindest war es bis heute so.|n|nWir haben einen Weg gefunden, wie wir uns mithilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können – einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung jedoch unerschütterlich ist, werden wir Euch sämtliche Kosten erlassen.', },
    {'Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird Euch die arkane Tarnung kostenfrei gewähren. Euer Ruf bei der Argentumdämmerung muss ehrfürchtig sein.', },
  },
  [9379] = {
    'Stärkt den Teufelsjäger',
    {'Seid gegrüßt, $C. Sagt ruhig auch \'Hallo\' zu Jir\'see. Keine Sorge, er wird nicht beißen, solange ich es ihm nicht befehle.|n|n<Angela gurrt dem Teufelsjäger zu.>|n|nEr ist so winzig im Vergleich zu den Sphärenhunden, die hier in der Scherbenwelt leben. Wir werden da allerdings für Abhilfe sorgen, ja, das werden wir, nicht wahr Jir\'see?|n|nIch glaube ich weiß jetzt, was es zu tun gilt. Ich brauche jede Menge Blut von den Sphärenhunden. Jetzt zu Eurer Rolle. Während Ihr sie ihm Südosten jagen geht, mache ich alles bereit für das Experi... ähm, die Behandlung.', },
    {'Sammelt 6 Einheiten Sphärenhundblut und bringt sie zu Angela "Die Klaue" Kestrel in Thrallmar.', },
  },
  [9380] = {
    'Die Hatz nach mehr',
    {'Ich sage Euch, sollte ich noch einen Brief von Eisenschmiede bekommen...|n|nHabt Ihr jemals versucht, jemandem etwas zu erklären, der nicht zuhört, $C? Ich habe den Jungs in Eisenschmiede das von ihnen angeforderte Sphärenhundexemplar geschickt. Jetzt waren sie so frech und haben mir zurückgeschrieben, dass sie ein ganzes "Rudel" dieser Viecher möchten! Ein Rudel!|n|nIch habe ihnen also zu erklären versucht, dass Sphärenhunde Einzelgänger sind, aber es schert sie nicht. Ich bin es leid zu diskutieren. In der Gegend östlich der Festung findet Ihr sie. Beschafft sechs der besten und bringt sie hierher zurück?', },
    {'Beschafft 6 unversehrte Sphärenhundkadaver und bringt sie zu Ausgrabungsleiter Murantus in der Ehrenfeste.', },
  },
  [9381] = {
    'Treffsichere Pfeile',
    {'Mit dem Zustrom von Pilgern und dem Vordringen der Allianz, war die Falkenwacht in letzter Zeit ein sehr geschäftiger Ort. In meiner freien Zeit stelle ich normalerweise Pfeile für die Waldläufer her. Leider habe ich schon lange keine Zeit mehr dazu gehabt, die für die Pfeilherstellung notwendigen Federn zu beschaffen.|n|nEs wäre mir ein paar Münzen wert, wenn Ihr die Schwanzfedern von Knochenhäutern für mich einsammeln würdet. In der Vergangenheit habe ich diese Geier oft über den Knochen verendeter Kreaturen, nördlich der Falkenwacht, ausfindig gemacht.', },
    {'Sammelt 8 Schwanzfedern eines Knochenhäuters von den Knochenhäutergeiern und bringt sie Falknerin Drenna Flusswind in der Falkenwacht.', },
  },
  [9382] = {
    'Das Schicksal der Grollhufe',
    {'Grüße, $C.|n|nIch bin sicher, dass Ihr auf Euren Reisen etwas von der Verderbtheit dieser Welt mitbekommen habt. Sie ist so allgegenwärtig, dass sie sogar die einheimischen Tiere verändert hat. Natürlich nur die, die sie überlebt haben.|n|nDie Grollhufe im Süden und Westen waren einst friedliche Weidentiere, aber die Verderbtheit hat sie mit einer unstillbaren Wut erfüllt. Der einzige Ausweg aus dieser Qual ist der Tod, auch wenn wir nur ungern ihr Blut vergießen. Helft Ihr mir dabei, das Leiden der borstigen Grollhufe zu beenden?', },
    {'Tötet 15 borstige Grollhufe und kehrt dann zu Amaan dem Weisen im Tempel von Telhamat zurück.', },
  },
  [9383] = {
    'Ein gewagter Plan',
    {'Die Blutelfen verkörpern den völlig unverantwortlichen Umgang mit den Mächten der Magie, $C. Sie kontrollieren die Magie nicht, nein, vielmehr sind sie ihre Sklaven und sie werden niemanden zwischen ihre Abhängigkeit und die magischen Energien kommen lassen, nach denen es ihnen dürstet. Die Blutelfen nutzen die Energien der Scherbenweltleerwandler, um ihre dämonische Magie zu wirken.|n|nIch habe einen Kristall mit einem Zauber aufgeladen, der es uns ermöglichen wird, einen Leerwandler zu neutralisieren und das magische Band zwischen ihm und dieser Welt zu zerschneiden. Ich habe die Leerwandler hauptsächlich in den Sphärenfeldern und südöstlich der Höllenfeuerzitadelle gesehen.', },
    {'Wendet den geweihten Kristall auf einen verwundeten unkontrollierten Leerwandler an. Kehrt anschließend zu Elsaana beim Tempel von Telhamat zurück.', },
  },
  [9384] = {
    'Nutzt das Licht',
    {'Die Zeit ist gekommen, diesen Dämon zu vernichten. Ich empfehle Euch vorsichtig zu sein, $N, denn es gibt noch vieles, dass Ihr noch nicht über die Leerwandler der Scherbenwelt wisst.|n|nBringt Rumatu dieses Gefäß, damit er sich um dessen Zerstörung kümmern kann. Beobachtet den Vorgang genau und berichtet mir, sobald der Prozess abgeschlossen ist.', },
    {'Bringt den leuchtenden geweihten Kristall zu Rumatu beim Tempel von Sha\'naar, damit er den darin eingeschlossenen Dämon mit den Kräften des Lichts zerschlagen kann.', },
  },
  [9385] = {
    'Tobende Felshetzer',
    {'Also schickt uns die Ehrenfeste hierher, um mit den Arakkoa fertigzuwerden, und wir bauen unser Lager auf und denken uns hey, schön hier. Wir hatten ja keine Ahnung, dass wir so nahe bei den Stachelklauenfelshetzern sind.|n|nSie sind erbarmungslose Raubtiere und haben jegliche Arbeit unsererseits zunichtegemacht. Wenn Ihr Euch darum kümmert, würde ich Euch bezahlen. Habt Ihr Lust?', },
    {'Tötet 10 Stachelklauenfelshetzer und kehrt anschließend zu Gremni Langbart auf der Höllenfeuerhalbinsel zurück.', },
  },
  [9386] = {
    'Licht im Dunkeln',
    {'Ihr seid ziemlich eifrig, oder? Solltet Ihr Euch noch einmal in die Tiefen wagen, so bin ich gerne bereit, Euch dafür zu belohnen.|n|nSucht die Freudenfeuer in Stratholme, Scholomance, dem Düsterbruch und den Hallen der Schwarzfelsspitze auf. Ich erwarte Eure Rückkehr, $N.', },
    {'Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Sprecht dann mit dem Flammenbewahrer.', },
  },
  [9387] = {
    'Die Quelle der Verderbtheit',
    {'Unverderbte Draenei, wie dieser unglückliche Geselle hier, sind begabte Helden des Lichts. Welche Verderbtheit hat wohl ihr großartiges Volk dazu gebracht, sich zu Zerschlagenen und Verirrten zurückzuentwickeln?|n|nMir ist eine Theorie zu Ohren gekommen, die besagt, dass die Mutation von teuflischen Energien ausgelöst wurde. Ich würde diese Theorie gerne überprüfen.|n|nNordwestlich von hier findet Ihr die Ruinen von Sha\'naar. Dort befinden sich einige einfache Zerschlagene unter dem Befehl der Zuchtmeister der Illidari. Bringt mir die dämonischen Essenzen der Zuchtmeister, damit ich sie an diesem Draenei ausprobieren kann.', },
    {'Reist zu den Ruinen von Sha\'naar auf der Höllenfeuerhalbinsel und besorgt 5 dämonische Essenzen von den Zuchtmeistern der Illidari. Kehrt zu Apotheker Azethen in der Falkenwacht zurück, wenn Ihr die Aufgabe erfüllt habt.', },
  },
  [9388] = {
    'Lodernde Flammen in Kalimdor',
    {'Heute lodern zahlreiche Flammen in der Welt, $N. Die Feuer, die am schwierigsten zu unterhalten sind, leuchten grün; werden sie nicht ständig beaufsichtigt, brennen sie nicht lange. Versichert Euch für unseren Flammenbewahrer, dass die Smaragdfeuer in Kalimdor auch weiterhin lodern, eh?|n|nIhr findet sie in der Nähe von Ratschet im Brachland, unweit der Meistergleve in Dunkelküste, im Wald des Eschentals bei der Brücke nahe des Außenpostens der Silberschwingen und entlang der Hauptstraße im Steinkrallengebirge, in der Nähe der Straße, die zur Scherwindklippe führt.', },
    {'Sucht die Freudenfeuer im Eschental, dem Brachland, der Dunkelküste und dem Steinkrallengebirge auf. Sprecht anschließend mit dem Flammenbewahrer.', },
  },
  [9389] = {
    'Lodernde Flammen in den Östlichen Königreichen',
    {'Die Feuer des Sonnenwendfests lassen das Land traditionsgemäß im Licht unzähliger Flammen erstrahlen. Manche behaupten, dass die grünen Flammen die besten seien, da sie so schwierig zu unterhalten sind und eine solch ungewöhnliche Farbgebung haben.|n|nVersichert Euch für unseren Flammenbewahrer, dass die Feuer in den Östlichen Königreichen auch weiterhin lodern. Ihr findet sie in der Nähe von Dun Modr im Sumpfland, unweit von Lohenscheit im Silberwald, bei den Klippen zum Leuchtturm in Westfall und nahe dem zerstörten Turm im Vorgebirge des Hügellands.', },
    {'Sucht die Freudenfeuer im Vorgebirge des Hügellands, im Silberwald, in Westfall und dem Sumpfland auf. Sprecht anschließend mit dem Flammenbewahrer.', },
  },
  [9390] = {
    'Die Suche nach Sedai',
    {'Hört mein Leid, $C. Mein Bruder Sedai ist schon vor längerer Zeit losgezogen, um den Orcs beim Posten der Mag\'har eine Botschaft zu übermitteln. Als ein unverbesserlicher Idealist war er der Meinung, dass der Zeitpunkt nun gekommen sei, unsere Differenzen beizulegen und einen Friedensvertrag mit ihnen auszuhandeln.|n|nEr wird jetzt schon seit Tagen vermisst und ich befürchte das Schlimmste.|n|nWürdet Ihr für mich nach ihm Ausschau halten, damit ich endlich wieder Ruhe finde? Sedai müsste sich irgendwo in der östlichen Umgebung aufhalten.', },
    {'Anachoret Obadei möchte, dass Ihr östlich von hier auf der Höllenfeuerhalbinsel nach seinem Bruder Sedai Ausschau haltet.', },
  },
  [9391] = {
    'Den Weg kennzeichnen',
    {'Nachdem die Felsklauenpopulation ausgedünnt ist, müssen wir die sichere Passage nur noch für unsere Pilger kenntlich machen. Nehmt diese Fackel und begebt Euch erneut in die Große Kluft. Sucht dort die drei Leuchtsignale, die den Verlauf des Pfads im Osten kennzeichnen.|n|nEntzündet die drei Signale und kehrt anschließend zu mir zurück. Doch seid gewarnt, das Entzünden eines Leuchtsignals zieht unweigerlich die Felsklauen aus der Umgebung an.', },
    {'Waldläuferhauptmann Venn\'ren an der Falkenwacht möchte, dass Ihr auf der Höllenfeuerhalbinsel die Große Kluft aufsucht und dort das südliche Leuchtsignal, westliche Leuchtsignal und das zentrale Leuchtsignal entzündet. Kehrt anschließend mit der brennenden Fackel zu ihm zurück.', },
  },
  [9392] = {
    'Ausbildung zum Schurken',
    {'Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Der Lehrer für junge Schurken hier auf der Insel der Sonnenwanderer ist Pfadpirscher Kariel. Sprecht mit Kariel, um herauszufinden, welche Ausbildung er Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.|n|nKariel - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.', },
    {'Sprecht mit Pfadpirscher Kariel - dem Schurkenlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.', },
  },
  [9393] = {
    'Ausbildung zum Jäger',
    {'Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Die Lehrerin für junge Jäger hier auf der Insel der Sonnenwanderer ist Waldläuferin Sallina. Sprecht mit Sallina, um herauszufinden, welche Ausbildung sie Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.|n|nSallina - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.', },
    {'Sprecht mit Waldläuferin Sallina - der Jägerlehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.', },
  },
  [9394] = {
    'Wo ist Wyllithen?',
    {'Der Nachtschimmergrundbewahrer ist verschwunden! Jemand muss vergessen haben, ihm zu sagen, dass er den Ort verlassen sollte, als der Magister und alle anderen es taten. Ich weiß, dass er sich noch irgendwo hier auf dem Grund aufhält, aber ich getraue mich nicht, selbst nach ihm zu sehen, da sich hier so viele magische Kreaturen herumtreiben.|n|nKönnt Ihr ihn für mich finden, $C? Bitte seht nach, ob er in Ordnung ist.', },
    {'Findet Grundbewahrer Wyllithen beim Nachtschimmergrund im Immersangwald.', },
  },
  [9395] = {
    'Saltherils Hafen',
    {'Ich schwöre, dass ich jemandem einen Feuerball verpasse, wenn Lord Saltheril mir auch nur noch eine Lieferanfrage für seine endlosen Feste schickt. Sehe ich verdammt nochmal wie ein Festtagsplaner aus?! Unter uns gesagt, dieser Verrückte und seine Bande von Speichelleckern scheinen bis heute zu verdrängen, dass wir unter ständiger Belagerung stehen!|n|nEinige von uns sind doch tatsächlich mit, äh, ich weiß nicht... der verdammten Verteidigung unseres Königreichs, Quel\'Thalas, beschäftigt?! Würdet Ihr mir einen Gefallen tun, $C? Seid doch so gut und reist für mich nach Saltherils Hafen und seht zu, dass er endlich Ruhe gibt! Es ist gleich die Straße runter, Richtung Westen.', },
    {'Sprecht mit Lord Saltheril in Saltherils Hafen im Immersangwald.', },
  },
  [9396] = {
    'Die Magie der Arakkoa',
    {'Die Scherbenwelt birgt viele Geheimnisse, $N. Es ist nur noch eine Frage der Zeit, bis wir sie alle enträtselt haben.|n|nDas Volk der halb Vogel, halb menschlichen Arakkoa verfügt über uraltes arkanes Wissen, welches sich als sehr nützlich für unsere Erforschung dieser Welt erweisen würde. Reist nach Süden zum Haal\'eshbau. Nehmt alle magischen Rollen an Euch, die Ihr bei den Haal\'eshi finden könnt und bringt sie mir.', },
    {'Bringt 4 Rollen der Haal\'eshi zu Arkanist Calesthris Morgenstern bei der Falkenwacht auf der Höllenfeuerhalbinsel.', },
  },
  [9397] = {
    'Kommt ein Vogel geflogen',
    {'Die Arakkoa der Haal\'eshi haben eine wunderschöne Vogelart, den Kaliri, domestiziert.|n|nMir ist es gelungen, ein junges Kalirimännchen einzufangen, und sie scheinen zähmbar zu sein. Die weiblichen Exemplare sind deutlich seltener, aber wenn es mir gelänge, eines davon zu ergattern, sollte ich in der Lage sein, sie selbst zu züchten. Es muss jedoch ein junges Weibchen sein, fast noch ein Küken. Ein alter Wildvogel würde die Gefangenschaft nicht lange überleben.|n|nNehmt diesen Käfig und reist nach Süden zum Haal\'eshbau. Sucht nach Eiern, die kurz vor dem Schlüpfen stehen. Wenn Ihr mir ein junges Weibchen zurückbringt, werde ich Euch fürstlich belohnen.', },
    {'Reist zum Haal\'eshbau auf der Höllenfeuerhalbinsel und durchsucht die Kalirinester nach einem jungen Kaliriweibchen. Benutzt den leeren Vogelkäfig, um es zu fangen, und kehrt anschließend zu Falknerin Drenna Flusswind in der Falkenwacht zurück.', },
  },
  [9398] = {
    'Tödliche Raubtiere',
    {'Die Zerschlagenen in der Scherbenwelt haben unendlich viel Grausamkeit ertragen müssen. Kein Wunder, dass sie sofort nach der Öffnung des Dunklen Portals scharenweise in der Hoffnung, diesem Land entfliehen zu können, dorthin gepilgert sind.|n|nZum Pech für unsere verwirrten Brüder und Schwestern sind sie für die Felsklauen, die in der Großen Kluft leben, eine leichte Beute. Geht dort hin und vernichtet einige der Felsklauen, damit unseresgleichen eine Chance hat.', },
    {'Späher Vanura im Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr 8 Steinsichelwelpen und 4 Steinsichelalpha tötet.', },
  },
  [9399] = {
    'Die Grausamkeit der Zuchtmeister',
    {'Sicherlich glaubt auch Ihr, dass die meisten Zerschlagenen bösartig sind, nicht wahr? In Wahrheit mangelt es vielen nur an geistiger Führung.|n|nIch war ebenfalls verloren, bevor ich die Omenai getroffen habe.|n|nUnser Verstand litt sehr unter der dämonischen Magie der Orcs. Man kann uns leicht in die Irre führen und ausnutzen.|n|nDämonen, die mit Illidan verbündet sind, überfallen täglich die Höllenfeuerhalbinsel und verschleppen unseresgleichen als Sklaven. Doch mit den Omenai kam die Hoffnung. Reist zu den Ruinen von Sha\'naar, südwestlich von hier, und tötet die Zuchtmeister der Illidari, damit mein Volk endlich wieder frei ist!', },
    {'Reist zu den Ruinen von Sha\'naar und erschlagt 4 Zuchtmeister der Illidari. Kehrt anschließend zu Ikan zum Tempel von Telhamat zurück.', },
  },
  [9400] = {
    'Der Assassine',
    {'$N, wir haben erst kürzlich einen Plan zur Ermordung unseres Gesandten in der Falkenwacht aufgedeckt. Spione der Höllenfeuerzitadelle haben von unseren Plänen, eine Expedition zur Wacht auszusenden, erfahren und einen Hinterhalt vorbereitet.|n|nUnsere Späher berichteten mir, dass ein Assassine namens Krun Rückenbrecher auf der Straße nördlich der Zitadelle in Stellung gegangen ist. Begebt Euch dorthin und tötet diesen Assassinen. Macht den Höllenorcs klar, dass man mit uns keine Spielchen treibt.', },
    {'Nazgrel möchte, dass Ihr zu der Straße nördlich der Höllenfeuerzitadelle reist und nach einem Assassinen namens Krun Rückenbrecher Ausschau haltet.', },
  },
  [9401] = {
    'Eine seltsame Waffe',
    {'Ihr zieht die Steinaxt aus dem toten Körper, um sie eingehender zu untersuchen. Irgendetwas an der Verarbeitung der Axt ist ungewöhnlich.|n|nSie scheint orcischen Ursprungs zu sein und dennoch besteht sie aus einem Material, das Ihr noch nie zuvor gesehen habt. Nazgrel wäre bestimmt daran interessiert, die Axt weiter zu untersuchen.', },
    {'Bringt die schwere Steinaxt zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.', },
  },
  [9402] = {
    'Fangt!',
    {'So... Ihr seid $N, oder? Fühlt Euch nicht geschmeichelt, ich kenne Euren Namen, einer meiner Schüler ist bei Euch herumscharwenzelt und plappert ununterbrochen.|n|nHmm... wenn Ihr $Gihn:sie; beeindrucken möchtet, warum helft Ihr mir dann nicht aus? Auf dem Grund des Stillwispertümpels hinter mir liegt eine Azurphiole. Taucht in die Tiefe, schnappt sie Euch und bringt sie zu mir.', },
    {'Taucht auf den Grund des Stillwispertümpels und holt die Azurphiole für Instrukteur Antheol.', },
  },
  [9403] = {
    'Das reinste Wasser',
    {'Jetzt, da Ihr eine kleine Lektion gelernt habt, bitte ich Euch etwas Handfesteres an. Es betrifft Eure Fähigkeiten der Selbstverteidigung. Ihr solltet natürlich nur im äußersten Notfall von Nahkampftechniken Gebrauch machen, aber deshalb sollte man trotzdem nicht unvorbereitet sein.|n|nIch kann Euch bei der Herstellung eines Stabs helfen, der einem Magier Eures Ranges gerecht wird. Nehmt die Phiole, die Ihr für mich besorgt habt, und füllt sie bei den Elrendarfällen auf. Folgt einfach dem Fluss südöstlich von hier.', },
    {'Instrukteur Antheol möchte, dass Ihr die Azurphiole bei den Elrendarfällen auffüllt.', },
  },
  [9404] = {
    'Noch lebendig',
    {'Ihr habt vielleicht die wandelnden Bäume nahe der Elrendarfälle bemerkt. Als Behüter der Natur sind sie mit urzeitlicher Magie erfüllt, die wir mithilfe des reinem Wassers, das Ihr mir gebracht habt, umformen und für unsere Zwecke verwenden können.|n|nUnglücklicherweise sind die Waldbehüter knorrige und verdrehte Kreaturen, so dass Ihr womöglich erst einige töten müsst, bevor Ihr einen brauchbaren Zweig findet.', },
    {'Tötet die Immersangwaldbehüter bis Ihr einen lebendigen Zweig für Instrukteur Antheol findet.', },
  },
  [9405] = {
    'Das Anliegen des Kriegshäuptlings',
    {'Wie Ihr wisst, steht der Kriegshäuptling aus ganzer Kraft hinter dieser Expedition und das aus gutem Grund. Dies ist unsere Heimatwelt. Hier liegen unsere Wurzeln.|n|nDiese Reise hat für Orcs und Blutelfen gänzlich unterschiedliche Bedeutung. Für sie ist es die Suche nach dem gelobten Land. Für uns ist es die Rückkehr in unsere lange verlorene Heimat.|n|nWer auch immer diese Axt gefertigt hat, ist mit den alten Traditionen vertraut. Wir müssen Kontakt zu ihnen aufnehmen. Diese Angelegenheit ist zu wichtig, als dass wir reguläre Methoden des Aufspürens verwenden. Zeigt Scharfseherin Regulkut die Waffe; sie wird wissen, was zu tun ist.', },
    {'Bringt die schwere Steinaxt zu Scharfseherin Regulkut in Thrallmar auf der Höllenfeuerhalbinsel.', },
  },
  [9406] = {
    'Die Mag\'har',
    {'Diese Neuigkeiten, die Ihr von jenseits des Dunklen Portals bringt... Ihr wollt mir ernsthaft Glauben machen, dass der Sohn Durotans über die jenseitigen Länder geherrscht hat? Frei von dämonischem Einfluss? Und nun sind seine Leute in diese Welt zurückgekehrt?|n|nUm Euretwillen hoffe ich, dass das nicht irgendein perfider Witz sein soll, $C. Es ist schwer zu beschreiben, was dies für mein Volk bedeutet. Ich werde umgehend eine Botschaft nach Nagrand schicken! Höllschrei muss davon erfahren.|n|nBringt diesen Brief zu Eurem Anführer in Thrallmar. Sagt ihm, die Mag\'har heißen Euch willkommen!', },
    {'Bringt den Brief von den Mag\'har zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.', },
  },
  [9407] = {
    'Durch das Dunkle Portal',
    {'Viele Jahre stand das Dunkle Portal still... vergessen. Aber nun ist es nicht mehr still.|n|nNachdem der Angriff der Dämonen aufgehalten wurde, haben unsere Truppen das Portal durchschritten und sich den Dämonen auf ihrem eigenen Gebiet gestellt!|n|nNun sind wir in einem wilden Krieg gefangen, und einige sind der Meinung, dass wir ihn nicht gewinnen können. Es ist also unsere Pflicht und unser grausames Vergnügen, unsere Feinde in der Scherbenwelt zu bekämpfen und unseren Sieg zu sichern, $N.|n|nWenn Ihr uns helfen wollt, meldet Euch unverzüglich bei Generalleutnant Orion. Er erwartet Euch in der Scherbenwelt...', },
    {'Reist durch das Dunkle Portal und meldet Euch bei Generalleutnant Orion. Er erwartet Euch auf der anderen Seite - in der Scherbenwelt.', },
  },
  [9408] = {
    'Vergessene Helden',
    {'Auch wenn es mich traurig macht, dass wir so viele Soldaten bei dem Versuch, das Portal zu durchbrechen, verloren haben, erfüllt es mich doch mit Stolz, dass das ursprüngliche Expeditionskorps noch am Leben ist.|n|nIch kann es kaum glauben, aber dort stehen sie - ein Zeichen für die Entschlossenheit der Allianz.|n|nIn dieser Festung steht einer unserer großartigsten Helden: Danath Trollbann! Geht zu ihm, $C. Er hat schon all unsere Soldaten getroffen und mit ihnen gesprochen. Er möchte Euch sicher kennenlernen.', },
    {'Sprecht mit Truppenkommandant Danath Trollbann in der Ehrenfeste.', },
  },
  [9409] = {
    'Eilige Lieferung!',
    {'Da Ihr jetzt alles besorgt habt, was zum Wiederaufladen der Heilkristalle benötigt wird, müsst Ihr die Phiolen zu unserem Priester Zalduun bringen. Er kümmert sich um die Verwundeten innerhalb der zentralen Kammer des Schiffes.', },
    {'Bringt die Phiolensammlung zu Zalduun bei der Absturzstelle im Am\'mental.', },
  },
  [9410] = {
    'Spirituelle Führung',
    {'Selbst die Sinne unserer besten Spürwölfe können sich irren, $N. Die Geister jedoch, haben eine andere Sicht auf diese Welt. Das Wesen, welches Ihr beschwören werdet, wird die von Euch gesuchte Person ausfindig machen, denn es spürt nicht dem Geruch des Gesuchten hinterher sondern seiner Essenz.|n|nGeht jetzt, $C, nehmt dieses Totem mit Euch und benutzt es an dem Ort, wo Ihr die Steinaxt gefunden habt.', },
    {'Verwendet das Wolfstotem an dem Ort, wo Ihr Krun Rückenbrechers Leichnam gefunden habt und folgt dem Ahnengeistwolf.', },
  },
  [9411] = {
    'Durchdrungene Verbände',
    nil,
    nil,
  },
  [9412] = {
    'Kristallflockendrops',
    nil,
    nil,
  },
  [9413] = {
    'Kristallflockendrops',
    nil,
    nil,
  },
  [9414] = {
    'Durchdrungene Verbände',
    nil,
    nil,
  },
  [9415] = {
    'Meldung bei Marschall Himmelswand',
    {'Gehört Ihr zu Marschall Himmelswands neuen Rekruten? Natürlich.|n|nAuf was wartet Ihr noch? Gute Soldaten verlieren ihr Leben in der Wüste. Freut es Euch nicht, bald dazuzugehören?|n|nLos jetzt, macht Euch auf den Weg... und trocknet dabei nicht aus.', },
    {'Sprecht mit Marschall Himmelswand beim Lager der Allianz in der Nähe des Zoraschwarmbaus.', },
  },
  [9416] = {
    'Meldung bei General Kirika',
    {'Ihr müsst zu General Kirikas neuen Rekruten gehören. Es wurde Zeit, dass Ihr kommt. Der Truppenverschleiß in der Wüste ist hoch.|n|nDie Zwerge haben tagtäglich Verstärkung bekommen, wir können es uns nicht leisten in unserem Kampf um Ressourcen in Silithus an Boden zu verlieren.|n|nLasst Euch vom General weitere Anweisungen geben. Ich muss Euch Rekruten lediglich finden, nicht ausbilden.', },
    {'Sprecht mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.', },
  },
  [9417] = {
    'Die Arakkoabedrohung',
    {'Die Arakkoa sind hochintelligente Wesen... genauso gerissen wie Gnome. Nur, dass sie über ein aggressives Gemüt und ein Händchen für Magie verfügen.|n|nIn letzter Zeit haben sie häufiger Patrouillen der Ehrenfeste überfallen, was auch der Grund für unsere Anwesenheit hier ist. Wisst Ihr, Mirren und ich sind weltbekannte Scharfschützen, ja, das sind wir! Allerdings sind wir eher auf Federvieh und Wildtiere spezialisiert... nicht auf diese Blitze schleudernden Vogelmenschen.|n|nWas sagt Ihr, greift Ihr uns in dieser Sache etwas unter die Arme? Ihr findet den Haal\'eshbau im Südosten.', },
    {'Gremni Langbart auf der Höllenfeuerinsel möchte, dass Ihr 4 Windspäher der Haal\'eshi und 6 Krallenwachen der Haal\'eshi tötet.', },
  },
  [9418] = {
    'Avruus Kugel',
    {'<Als Ihr die Kugel näher an Euer Ohr haltet, hört Ihr, wie Euch eine Stimme anspricht.>|n|nIhr seid kein Arakkoa, wie ich spüre. Deswegen werde ich versuchen, Euch einen Handel für meine Freiheit vorzuschlagen. Mein Name ist Aeranas. Ich regierte einst über die östlichen Winde. Der Magier der Haal\'eshi, Avruu, hat mich in dieser Kugel eingefangen.|n|nSucht den Altar der Arakkoa, mit dessen Hilfe sie mich versklavt haben. Er ist südöstlich vom Bau der Arakkoa versteckt. Nähert Euch ihm mit der Kugel und gebt sie mir, sobald ich frei bin. Als Ausgleich für meine Freiheit werde ich Euch einen mächtigen Schatz geben!', },
    {'Bringt Avruus Kugel zum Altar der Haal\'eshi südöstlich des Haal\'eshbaus auf der Höllenfeuerhalbinsel und gebt sie Aeranas, sobald er frei ist.', },
  },
  [9419] = {
    'Durchkämmen der Wüste',
    {'Wir hatten vor Kurzem herausgefunden, dass die Horde die Wüste von Silithus nach Ressourcen abgesucht hat, schenkten dem Ganzen aber keine besondere Beachtung. Wir dachten, es wäre die Sache nicht wert, eine größere Anzahl von Soldaten in dieser Bruthitze zu stationieren.|n|nWie dem auch sei, wir haben die Wichtigkeit dieser Ressourcen erkannt und versuchen nun, um jeden Preis aufzuholen.|n|nWenn Ihr uns unterstützen wollt, müsst Ihr in die Wüste gehen, dort nach Silithyst suchen und diesen anschließend hierher bringen.', },
    {'Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Marschall Himmelswand beim Lager der Allianz in der Nähe des Zoraschwarmbaus.', },
  },
  [9420] = {
    'Feinste Daunen',
    {'Die Arakkoa das Haaleshbaus südlich von hier züchten eine besonders prächtige Art von Vögeln, namens Kaliri. Ihre Federn würden mir in den Handelsposten Azeroths einen ganz schönen Batzen Gold einbringen. Denkt nur an all das viele Bier, das ich mir leisten könnte!|n|nIch sag Euch was, bringt mir eine Ladung Kalirifedern und ich gebe Euch meinen Hut. Was sagt Ihr dazu? So einen Hut wie diesen hier, werdet Ihr nirgendwo sonst finden! Sind wir im Geschäft?', },
    {'Mirren Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 8 Kalirifedern von den Kaliris im Haal\'eshbau bringt.', },
  },
  [9421] = {
    'Ausbildung zum Schamanen',
    nil,
    nil,
  },
  [9422] = {
    'Durchkämmen der Wüste',
    {'Wir haben die Wüste von Silithus bereits seit einiger Zeit nach Kristallressourcen durchkämmt. Die einzigen Gefahren, die sich uns dabei in den Weg gestellt haben, waren die Kreaturen, die dort heimisch sind, sowie Sand, Staub und Hitze.|n|nDie Allianz scheint nun aber Wind von unserem Unterfangen bekommen zu haben. Ein Rennen hat begonnen. Ein Rennen um die natürlichen Ressourcen und um deren Verteidigung.|n|nWir brauchen jede helfende Hand, die wir bekommen können. Ich hoffe, Ihr werdet uns unterstützen.', },
    {'Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.', },
  },
  [9423] = {
    'Rückkehr zu Obadei',
    {'Jetzt, da sich Sedais Tod bestätigt hat, liegt es an Euch, Obadei die traurige Nachricht zu überbringen.', },
    {'Kehrt zu Anachoret Obadei beim Tempel von Telhamat auf der Höllenfeuerhalbinsel zurück und berichtet ihm von Sedais Tod.', },
  },
  [9424] = {
    'Makurus Rache',
    {'Sedai war für Makuru wie ein Bruder. Ich schulde ihm mein Leben und noch weit mehr! Sie sagen, Makuru sei verrückt, doch wenn die Omenai nach seinem Tod nichts tun wollen, dann sind sie die wahren Verrückten!|n|nMakuru kann in dieser Welt nicht viel sein Eigen nennen, aber ich werde Euch mit Freuden meinen einzigen Besitz überlassen, wenn Ihr Sedai rächt. |n|nIch habe die braunen Orcgrunzer schon mal gesehen, oben in den Bergen, im Nordosten. Sie hassen uns! Sie haben unser Mitleid nicht verdient! Geht und rächt Sedais Tod. Bringt mir ihre Ahnenperlen als Beweis!', },
    {'Makuru im Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 10 Ahnenperlen der Mag\'har bringt.', },
  },
  [9425] = {
    'Bericht an Tarrens Mühle',
    {'Ah, gut Euch hier zu sehen, $C! Ich habe eine Aufgabe, die wie für Euch gemacht ist.|n|nAls neue Mitglieder der Horde müssen wir dafür sorgen, dass wir sie bei ihren Unternehmungen unterstützen und bei ihren Problemen helfen. Dann werden sie uns auch bereitwilliger bei unseren helfen.|n|nReist zum Dorf der Verlassenen, Tarrens Mühle, im Vorgebirge des Hügellands im Südwesten. Meldet Euch bei Beraterin Morgenabend, wenn Ihr da seid.', },
    {'Reist nach Tarrens Mühle im Vorgebirge des Hügellands und sprecht mit Beraterin Morgenabend.', },
  },
  [9426] = {
    'Die Teiche von Aggonar',
    {'Seit den Tagen, in denen wir dieses Land Draenor nannten, hat sich viel geändert. Teile des Landes wurden durch die Verderbtheit der Dämonen für immer verwandelt.|n|nDazu gehören die Teiche von Aggonar. Einst befanden sich an diesem Ort die heiligen Quellen unseres Volkes. Das Blut des Dämonen Aggonar hat die Essenz des geheiligten Wassers verschmutzt. Dieses teuflische Blut hat verderbte Kreaturen vorgebracht, die ausgelöscht werden müssen, wenn wir die Teiche jemals zurückfordern möchten. Reist von hier aus nach Osten und tötet die Teufelsblutelementare und den Schleim, der sich in den Teichen herumtreibt.', },
    {'Amaan der Weise möchte, dass Ihr zu den Teichen von Aggonar geht und 6 Teufelsblutschrecken und 6 mörderische Faulschleime tötet.', },
  },
  [9427] = {
    'Reinigung des Wassers',
    {'Ich muss euch bitten, das, was wir angefangen haben, zu Ende zu bringen. Jetzt, da der teuflische Einfluss nachgelassen hat, müsst Ihr diese Reinigungsphiole nehmen und sie auf den Ursprung der Verderbnis schütten, Aggonars Leiche.|n|nIhr könnt die Knochen des Dämonen am nördlichen Ende der Teiche finden. Aber seid vorsichtig, seine Essenz ist immer noch nicht ganz aus dieser Welt verschwunden.', },
    {'Amaan der Weise möchte, dass Ihr zu den Teichen von Aggonar reist und die Reinigungsphiole bei Aggonars Leiche benutzt. Kehrt zu ihm zurück, wenn Ihr das Wasser von Aggonars Essenz befreit habt.', },
  },
  [9428] = {
    'Bericht an den Splitterholzposten',
    {'<Die Botschafterin senkt die Stimme und beugt sich zu Euch.>|n|nEuer Ruf eilt Euch voraus, $N. Ich möchte, dass Ihr zum Splitterholzposten im Eschental reist. Zu Fuß gelangt man am einfachsten durch Durotar, das Brachland und dann an der Weggabelung nach Norden dorthin.|n|nWenn Ihr dort angekommen seid, sprecht mit Berater Sonnenschwur. Reist vorsichtig, das Eschental kann sehr gefährlich sein!', },
    {'Reist zum Splitterholzposten im Eschental und sprecht mit Berater Sonnenschwur.', },
  },
  [9429] = {
    'Reist nach Dunkelhain',
    {'Mir wurde gesagt, dass es einen Dorn in der Seite des Königreichs von Sturmwind gibt, Dämmerwald genannt. Dieser Ort ist erfüllt vom bösen und niederträchtigen Gestank des Untodes.|n|nDa wir versuchen, so gut wie möglich zu helfen, möchte ich, dass Ihr nach Südosten zu der größeren Menschensiedlung Dunkelhain reist. Anachoret Delan wird dort auf Eure Ankunft warten.', },
    {'Reist nach Dunkelhain im Dämmerwald und sprecht mit Anachoret Delan.', },
  },
  [9430] = {
    'Relikte von Sha\'naar',
    {'Wie ich es Euch bereits sagte, ich brauche mein Augenlicht nicht, um zu sehen, was andere nicht zu erkennen vermögen. Ich werde nicht verurteilen, was Ihr in Makurus Namen getan habt, dennoch denke ich, Ihr solltet über das, was Euch Eure Augen zeigen, hinausblicken.|n|nReist zu den Ruinen von Sha\'naar im Südwesten und sammelt so viele Relikte ein, wie Ihr finden könnt. Wenn es das Schicksal so will, werdet Ihr finden, was wir brauchen.|n|nDie Bedeutung meiner Bitte mag Euch im Moment unklar sein, doch habt vertrauen, $N. Der Geduldige wird erleuchtet werden.', },
    {'Amaan der Weise beim Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr zu den Ruinen von Sha\'naar reist und 10 Relikte von Sha\'naar einsammelt.', },
  },
  [9431] = {
    'Eine andere Lösung',
    {'Was hat es zu heißen, wenn ein Sin\'dorei auf dem Gipfel einer vom Wind gepeitschten Plattform steht anstatt in den Hallen von Silbermond?|n|nGanz einfach. Meine Brüder wollen mich nicht mehr haben. Jede Abschrift meiner Abhandlung über die natürliche Heilung unserer Abhängigkeit wurde verbrannt.|n|nIch kann meine Forschungen hier sicher fortsetzen, aber ich habe keine Reagenzien. Wenn Ihr bereit wärt, etwas reinigende Erde von den donnernden Felskloppern am westlichen Ende der Nadeln zu besorgen und zu meinem Verbündeten beim Weißgipfelposten zu bringen, wäre ich Euch sehr dankbar.', },
    {'Sammelt 2 Handvoll reinigende Erde von den donnernden Felskloppern und bringt sie zu Wizlo Lagerputzer beim Weißgipfelposten.', },
  },
  [9432] = {
    'Reist nach Astranaar',
    {'Ich bin froh, dass Ihr helfen wollt. Es gibt in der Tat etwas, was Ihr tun könnt.|n|nAls Teil unseres Bündnisses mit der Allianz möchte ich, dass Ihr zur Elfenstadt Astranaar reist. Sie befindet sich im Eschental, einem großen Wald südlich von Dunkelküste auf dem Kontinent Kalimdor.|n|nBitte sprecht mit Verteidigerin Palanaar, wenn Ihr angekommen seid, und fragt nach, ob es etwas gibt, bei dem Ihr den Bewohnern behilflich sein könnt.', },
    {'Reist nach Astranaar im Eschental und sprecht mit Verteidigerin Palanaar.', },
  },
  [9433] = {
    'Ein Bad im Mondbrunnen',
    {'Schaut mich nicht so an! Ich habe nicht behauptet, dass ich Euch mit einer Kelle und einer Flasche zum Mondbrunnen von Thalanaar schicke!|n|nIch habe ein wenig an einem Produkt, das ich für einen Kunden transportiert habe, äh... herumexperimentiert. Ehrlich gesagt habe ich bereits eine tragbare Steuerungskonsole für den Robotron in der Nähe von Thalanaar aufgestellt. Ihr müsst diese Steuerungseinheit mitnehmen und in der Nähe meiner versteckten Konsole benutzen.|n|nWenn mein Kunde je erfährt, dass ich den Robotron auch nur aus der Verpackung genommen habe, hängt er mich an den Ohren auf!', },
    {'Benutzt die Bedienungseinheit für Robotron in der Nähe der versteckten Steuerungskonsole in einer kleinen Gruppe von Büschen am Rand der Nadel, die sich am dichtesten an Thalanaar befindet, und übernehmt die Steuerung des Robotron 3000. Steuert den Roboter zum westlichen Ende von Tausend Nadeln zum Allianzaußenposten von Thalanaar. Benutzt den Roboter, um eine Probe Mondbrunnenwasser zu besorgen und bringt sie zu Wizlo Lagerputzer beim Weißgipfelposten.', },
  },
  [9434] = {
    'Das Tonikum testen',
    {'<Wizlo nimmt dem Roboter die Wasserprobe ab und legt sie zusammen mit der Felskloppererde und verschiedenen anderen Dingen in eine Kiste.>|n|nSo, das ist alles auf Magistrix Elosais Liste. Sagt ihr, dass es mir eine Ehre war, mit ihr zusammen zu arbeiten, und dass ich ihr viel Glück bei ihren Forschungen wünsche.', },
    {'Bringt die Kiste mit Reagenzien zu Magistrix Elosai im Freiwindposten.', },
  },
  [9435] = {
    'Vermisste Kristalle',
    {'Wenn man etwas mit Sicherheit über das Hügelland sagen kann, dann, dass es auserkoren wurde, um unter dem Schatten des Krieges zu leben. Sogar etwas so Harmloses wie eine Wagenladung Steine kann als Ziel dienen.|n|nNormalerweise ist der Verlust von Baumaterial kein allzu großes Problem, aber bei der letzten Lieferung aus dem Azurschacht war eine Kiste mit seltenen Kristallen dabei, die ich sehr gerne untersucht hätte. Plünderer der Verlassenen haben den Wagen abgefangen und ihn nach Nordosten zu einem Turm gebracht, den sie wiederaufbauen wollen. Wir müssen diese Kristalle zurückholen, $C!', },
    {'Besorgt die Lieferung seltener Kristalle von den Verlassenen und bringt sie zu Huraan in Süderstade zurück.', },
  },
  [9436] = {
    'Erkenntnisse über die Blutskalpe',
    {'Das trifft sich gut, $C. Auf meinen Reisen habe ich die Kampftechniken der verschiedenen Trollstämme untersucht und eine Entwicklung erkannt. Die Blutskalpe in den Ruinen von Tkashi und Bal\'lal im Norden benutzen die gleichen Taktiken wie die Amani in den nördlichen Wäldern.|n|nIhre Magie scheint sich in eine interessante Richtung entwickelt zu haben, und sie haben sie benutzt, um der mächtigste Stamm in der Gegend zu werden. Sie könnte der Kern einer Waffe gegen die Amani sein, aber ich muss noch mehr darüber herausfinden.', },
    {'Nemeth Falkenauge im Basislager von Grom\'gol möchte, dass Ihr ihm ein Totem der Blutskalpe von einem Schamanen der Blutskalpe bringt.', },
  },
  [9437] = {
    'Der Untergang der Morgenbö',
    {'Die Oger hier sind für nichts außer dreckige Witze, bitteres Bier und Wettkämpfe im Köpfe-aneinander-Schlagen zu gebrauchen. Als mein Schiff, die Morgenbö, untergegangen ist, haben sich diese Hunde von Theramore mit meiner Ladung und dem letzten überlebenden Crewmitglied aus dem Staub gemacht. Ich habe mich auf der Suche nach Hilfe hierher begeben, aber diese nichtsnutzigen Oger haben mich nur dumm angeschaut, als ich ihnen erzählt habe, was passiert ist.|n|nIch könnte die Hilfe eines zuverlässigen Helden brauchen, um die Überreste meiner Ladung und Ithania aus der Nordwacht zu retten. Der Turm befindet sich im Nordosten.', },
    {'Balandar Sternenlicht in Brackenwall möchte, dass Ihr die Fracht der Morgenbö wiederholt und den Ersten Maat Ithania von den Streitkräften von Theramore in der Nordwacht befreit.', },
  },
  [9438] = {
    'Bote für Thrall',
    {'Seitdem wir das erste Mal die Scherbenwelt betreten haben, hat der Kriegshäuptling auf diese Nachricht gehofft. Nun seid Ihr es, der die Ehre hat, ihm persönlich die Botschaft der Mag\'har zu übermitteln.|n|nVerliert keine Zeit, $N. Nehmt diesen Brief, er enthält mein persönliches Siegel. Es gibt nichts, was Thrall mehr erfreuen wird, als die Botschaft, die Ihr bei Euch tragt.', },
    {'Reist nach Orgrimmar und übergebt Thrall Nazgrels Brief.', },
  },
  [9439] = {
    'Unabgeholtes Gepäck',
    {'Das ist Kargath? Oh je. Ich habe eine... nun, eine Art Siedlung erwartet, ein Zeichen von Zivilisation inmitten der Wildnis.|n|nDas muss ein Fehler sein, diese Hütte voller ungehobelter, ungewaschener, dümmlich grinsender Wilder kann nicht das Hauptquartier des Expeditionskorps sein. Diese flegelhaften Barbaren haben es gewagt, mich auszulachen, als ich ihnen erzählt habe, wie die Dunkeleisenzwerge mich überfallen haben und dann in der Festung Angor verschwunden sind. Ich kann darauf zählen, dass Ihr mir meinen Besitz und meine Würde zurückbringt, oder?', },
    {'Holt den Beutel des Beraters und das Rapier des Beraters aus der Festung Angor und kehrt dann zu Berater Sarophas in Kargath zurück.', },
  },
  [9440] = {
    'Kleine Häppchen',
    {'Ich baue gerade eine Waffe gegen die Draenei und Ihr werdet mir dabei helfen!|n|nDie Verirrten sind die zurückgebliebenen Vettern der Draenei und ich habe ein paar Experimente mit ihnen durchgeführt. Ihr müsst nur ein paar teuflische Häppchen zu ihrem Vieh bringen. Wenn sie die Tiere dann schlachten und essen werden sie verflucht sein! Das wird es dem spießigen Anachoreten Avuun im Sicheren Hafen zeigen!|n|nGeht nun und beeilt Euch! Ihr findet die Verirrten und ihre eingesperrten Tiere im Nordosten in der Zuflucht der Verirrten.', },
    {'Verfüttert die teuflischen Häppchen an die gefangenen Tiere der Verirrten. Bringt die Überbleibsel zu Cersei Abendsänger in Steinard in den Sümpfen des Elends.', },
  },
  [9441] = {
    'Entsandt zu den Mag\'har',
    {'Nachdem Ihr mir diese Botschaft überbracht habt, würde ich umgehend in die Scherbenwelt aufbrechen. Leider machen wichtige Angelegenheiten meine Anwesenheit in Durotar erforderlich.|n|nIch werde den Mag\'har umgehend einen würdigen Tribut als Zeichen unserer Freundschaft zukommen lassen. Des Weiteren entsende ich meine fähigsten Diplomaten. All das wird Vorbereitungen und Zeit kosten... wir benötigen jemanden, der uns schon heute vor den Mag\'har würdig vertreten kann.|n|nIch setzte mein gesamtes Vertrauen in Euch, $N. Reist zum Posten der Mag\'har auf der Höllenfeuerhalbinsel und bietet ihnen Eure Dienste im Namen unseres gesamten Volkes an. Enttäuscht mich nicht, $N. Zu viel hängt davon ab.', },
    {'Kehrt zu Gorkan Blutfaust beim Posten der Mag\'har auf der Höllenfeuerhalbinsel zurück und bietet ihm im Namen Thralls Eure Dienste an.', },
  },
  [9442] = {
    'Eine erschöpfende Krankheit',
    {'Es ist schön, dass Ihr uns helfen wollt, $N. Unsere Grunzer haben verdorbenes Wasser getrunken und sind krank geworden. Leider fehlt mir eine Zutat für eine Heilsalbe. Ich benötige einen seltenen Pilz namens Trockenkappe.|n|nUnser wichtigster Befehl ist, unseren Aufenthaltsort geheim zu halten, weswegen ich nicht riskieren kann, bei der Suche danach entdeckt zu werden. Der einzige Ort, an dem man auf der Höllenfeuerhalbinsel Trockenkappen finden kann, ist eine Höhle in der Nähe der Großen Kluft, südlich von hier.|n|nSeid äußerst vorsichtig, wenn Ihr Euch entschließen solltet, danach zu suchen.', },
    {'Erdenruferin Ryga beim Posten der Mag\'har auf der Höllenfeuerhalbinsel möchte, dass Ihr 1 Trockenkappe aus einer Höhle in der Großen Kluft besorgt.', },
  },
  [9443] = {
    'Das sogenannte Mal des Lichtbringers',
    {'Einst war ich ein Schüler von Uther Lichtbringer, dem Gründervater der Ritter der Silbernen Hand. Ich sah sein Versagen bei der Ausbildung von Prinz Arthas. Es führte zu der Zerstörung meines Heimatlandes, Quel\'Thalas, und ich gebe Uther die alleinige Schuld daran! Und nun ruht er in einem Grabmal, das zu seinen Ehren erbaut wurde - wie liebenswert.|n|nMeine Quellen berichteten mir, dass diese Scharlachroten Narren eines seiner \'heiligen\' Relikte in der Spitze ihres Wachturms, nahe den Toren Herdweilers aufbewahren.|n|nBegebt Euch in die Westlichen Pestländer und bringt es mir.', },
    {'Nehmt das Mal des Lichtbringers an Euch und kehrt anschließend zu Mehlar Dämmerklinge beim Bollwerk in den Westlichen Pestländern zurück.', },
  },
  [9444] = {
    'Entweiht Uthers Grabmal',
    {'So, dass ist viel besser. Ich habe ihm etwas dämonische Magie hinzugefügt.|n|nNun müsst Ihr es zu seiner Ruhestätte in den Westlichen Pestländern bringen. Benutzt das verderbte heilige Symbol in der Gegenwart von Uthers Statue, um sein Grabmal zu entweihen! Geht nahe heran, sonst kann die Magie ihre Wirkung nicht entfalten.|n|nDas Grabmal befindet sich südöstlich von den Ruinen Andorhals. Kehrt zu mir zurück, wenn Euer Werk vollbracht ist.|n|nBeeilt Euch, $C!', },
    {'Entweiht Uthers Grabmal und kehrt anschließend zu Mehlar Dämmerklinge beim Bollwerk in den Westlichen Pestländern zurück.', },
  },
  [9445] = {
    'Ein würdiges Opfer',
    nil,
    {'Beschafft Euch Uthers Segen von der Spitze des Wachturms beim Eingang zu Herdweiler und bringt ihn zu <NPC> beim Zugwindlager.', },
  },
  [9446] = {
    'Das Grab des Lichtbringers',
    {'Jetzt, da Ihr das Mal des Lichtbringers zurückgeholt habt, müssen wir es nur noch zu Uthers Grabmal bringen.|n|nWollt Ihr mich dorthin begleiten? Es ist nicht weit und ich würde Eure Gesellschaft genießen. Danach könnt Ihr hierher zurückkehren und der Hohepriesterin MacDonnell von Eurer Erfahrung berichten.|n|nWas haltet Ihr davon, $N?', },
    {'Begleitet Anachoret Truun zu Uthers Grabmal in den Westlichen Pestländern. Sprecht danach mit Hohepriesterin MacDonnell im Zugwindlager in den Westlichen Pestländern.', },
  },
  [9447] = {
    'Salbe verabreichen',
    {'Ich habe mit den Kräutern, die Ihr mir gebracht habt, eine Salbe zubereitet, die die Stärke der Grunzer wiederherstellen sollte. Nehmt sie und verabreicht sie allen entkräfteten Grunzern an, die Ihr hier in der Nähe seht.', },
    {'Erdenruferin Ryga möchte, dass Ihr die Heilsalbe 10 entkräfteten Grunzern beim Posten der Mag\'har auf der Höllenfeuerhalbinsel verabreicht.', },
  },
  [9448] = {
    'Mitleid mit den Verfluchten',
    {'Diese Blutelfenhexe, Cersei Abendsänger, hat die Verirrten verflucht! Ich weiß es einfach! Ich weiß nicht wie und warum, aber die Folgen sind verheerend. Viele der Verirrten wurden noch weiter verderbt und mit noch teuflischeren Energien verflucht!|n|n$C, könnt Ihr tief in Eurem Inneren etwas Mitleid für diese armen Kreaturen aufbringen? Sie sollten ihr Leben nicht in einem so furchtbaren Zustand verbringen.|n|nIhr findet die verfluchten Verirrten in der Zuflucht der Verirrten, den Pfad hinunter nach Osten.', },
    {'Tötet 3 Verfluchte der Verirrten und kehrt dann zu Anachoret Avuun im Sicheren Hafen in den Sümpfen des Elends zurück.', },
  },
  [9449] = {
    'Ruf der Erde',
    {'Die Zeit ist gekommen, $N. Euer Körper und Euer Geist sind an einem Punkt angelangt, an dem Ihr direkt mit den elementaren Geistern Azeroths kommunizieren müsst.|n|nLasst Euch jedoch gewarnt sein. Ich spüre, dass unser ungewöhnliches Betreten dieser Welt und dessen unglückliche Nebenwirkungen die Erdgeister erzürnt und zu einem Ungleichgewicht der Elemente geführt haben.|n|nWollt Ihr Euer Erdtotem erschaffen, so müsst Ihr zuerst mit dem Geist des Tals sprechen. Ihr findet ihn im Heiligen Hain, der sich an die Hügel im Nordwesten schmiegt.', },
    {'Sprecht mit dem Geist des Tals beim Heiligen Hain im Am\'mental.', },
  },
  [9450] = {
    'Ruf der Erde',
    {'Das Gleichgewicht der Elemente wurde durch das gewaltsame Eindringen der Draenei ins Tal gestört. Euer Absturz hat die Erdgeister erzürnt und gegen die anderen Elemente gewendet. Ihr werdet sehen, dass man die Elemente nur dann verstehen kann, wenn diese in Einklang sind.|n|nFolglich müsst Ihr das Gleichgewicht wieder herstellen. Im Hain hinter mir findet Ihr ruhelose Erdgeister, die gegen die anderen drei Elemente aufbegehren. Helft uns, stellt den Einklang wieder her.', },
    {'Tötet 4 ruhelose Erdgeister und kehrt zum Geist des Tals beim Heiligen Hain im Am\'mental zurück.', },
  },
  [9451] = {
    'Ruf der Erde',
    {'Ich werde Euch jetzt einen Teil meines physischen Wesens geben, damit Ihr Euer Erdtotem erschaffen könnt. Bringt es zu dem, der Euch hierher gesandt hat. Ihr und ich werden von nun an auf Lebzeiten miteinander verbunden sein.|n|nDie Kräfte der Erde werden Euch in Eurem Leben fortwährend zur Verfügung stehen. Wenn Eure Knochen am Ende Eurer Tage wieder zu uns zurückkehren, schließt sich der Kreislauf wieder.|n|nSetzt Eure Macht weise ein.', },
    {'Bringt den Erdkristall zu Firmanvaar bei der Absturzstelle im Am\'mental.', },
  },
  [9452] = {
    'Schnapper - sehr, sehr lecker!',
    {'Ich habe festgestellt, dass es in diesen Gewässern von Schnappern nur so wimmelt. Das ist ein sehr, sehr leckerer Fisch.|n|nMit einem Fischernetz kann ich genug fangen, um dutzende von Draenei satt zu bekommen! Unglücklicherweise wurde ich erst kürzlich von einer Kreatur angegriffen, die man Murloc nennt, als ich im Fluss fischte. Ich wurde dabei verletzt und kann deshalb meine Arbeit nicht mehr verrichten. Ich brauche Hilfe!|n|nIhr müsst dieses Fischernetz lediglich in der Nähe von Schnapperschwärmen, die man im Kristalfluss östlich von hier findet, auswerfen.|n|nWas sagt Ihr? Vergesst aber nicht, das Netz nach getaner Arbeit wieder zurückzubringen.', },
    {'Verwendet das Fischernetz der Draenei, um 10 Schnapper zu fangen. Bringt die Fische und das Netz anschließend zu Diktynna auf der Azurmythosinsel zurück.', },
  },
  [9453] = {
    'Findet Acteon!',
    {'Ihr habt das wunderbar gemacht, $N. Unsere Leute werden Euch für diesen Fang sehr dankbar sein. Ach ja, könntet Ihr diese Ladung Schnapper vielleicht zu Acteon bei der Azurwacht bringen?|n|nEr dürfte leicht zu finden sein, da er diese Lieferung bereits erwartet.', },
    {'Bringt die Ladung Schnapper zu Acteon bei der Azurwacht.', },
  },
  [9454] = {
    'Die große Mondweidenjagd',
    {'Ihr macht Euch hier einen Namen, $N. Warum versucht Ihr Euch nicht mal im Jagen?|n|nAuf Draenor würden unsere besten Jäger Tiere jagen, die den Mondweidenhirschen dieser Gegend sehr ähneln und den Namen Talbuk tragen.|n|nWenn Ihr denkt, Ihr seid \'Draenei\' genug, dann zieht durch die Wildnis rund um die Azurwacht und tötet ausreichend Mondweidenhirsche und -böcke, um Eure Taschen mit ihrem Fleisch zu füllen.|n|nDie Hirsche grasen südlich der Azurwacht, die Böcke im Norden. Gebt auf ihre Hörner Acht!', },
    {'Acteon bei der Azurwacht möchte, dass Ihr ihm 6 Mondweidenhirschlenden bringt.', },
  },
  [9455] = {
    'Seltsame Funde',
    {'Der Kristall, den Ihr beim Körper des Nachtpirscherjungen gefunden habt, scheint ein Teil der Exodar zu sein. Vielleicht ist dies eine Erklärung für das ungewöhnliche Aufkommen und Verhalten einiger Tiere dieser Gegend.|n|nBringt den Kristall zurück zur Azurwacht. Der Exarch wird sicherlich von dieser Entdeckung erfahren wollen.', },
    {'Bringt den schwach leuchtenden Kristall zu Exarch Menelaous bei der Azurwacht.', },
  },
  [9456] = {
    'Nachtpirscherjagd',
    {'Ich werde nicht versuchen, irgendwelche Ausreden für das, was Ihr gefunden habt, zu finden. Es ist ganz klar unsere Schuld. Uns wurde von zertrümmerten Kristallfragmenten im östlich gelegenen Fluss berichtet, aber wir hatten beschlossen, diese Implikationen zu ignorieren. Wir können jetzt entweder auf dieser Insel herumsitzen und diese Tragödie beweinen, oder etwas tun, um eine Ausbreitung zu vermeiden.|n|nWenn Ihr es ertragen könnt, möchte ich, dass Ihr zurück in die Wildnis geht und so viele der infizierten Nachtpirscherjungen tötet, wie Ihr finden könnt.', },
    {'Exarch Menelaous bei der Azurwacht möchte, dass Ihr 8 infizierte Nachtpirscherjungen tötet.', },
  },
  [9457] = {
    'Ein ungewöhnlicher Patron',
    {'Naias ist also das Genie hinter den Blutskalpen und ihrer fremdartigen Magie? Ich muss zugeben, dass ich nie gedacht hätte, dass meine Nachforschungen dort enden würden, aber unsere Erkenntnisse könnten sich vielleicht trotzdem als hilfreich herausstellen.|n|nVor der Küste im Nordwesten befindet sich eine kleine Insel, die von geringen Wasserelementaren bewohnt wird. Es gibt dort eine grobe Steinplatte, die den Trollen vielleicht als Altar dienen könnte. Bringt das Totem, das Ihr gefunden habt, zu diesem Altar. Vielleicht können wir diesen Naias ja hervorlocken und seine Macht in eine angenehmere Form bringen.', },
    {'Benutzt Naias\' Gabe in der Nähe des Altars von Naias, um den Wasserelementar Naias zu rufen. Besiegt ihn und kehrt dann zu Nemeth Falkenauge im Basislanger von Grom\'gol mit dem Herz von Naias zurück.', },
  },
  [9458] = {
    'Trank der geschärften Sinne',
    nil,
    nil,
  },
  [9459] = {
    'Anticrittrank',
    nil,
    nil,
  },
  [9460] = {
    'Mit vereinten Kräften',
    {'Keltus Dunkellaub meldet sich zum Dienst!|n|nOh... wer seid Ihr eigentlich? Wenn Ihr wegen meinem Bericht hier seid, dann müsst Ihr mir zuerst helfen.|n|nIch habe vor, die Spione der Schildwache anzugreifen, möchte meine treue Tuschel aber als Vorhut vorausschicken. Sie braucht lediglich eine Fährte, die sie auf sie hetzt.|n|nJemand von Eurem Können kann sich doch sicherlich hineinschleichen und etwas von der Anführerin der Schildwachen stehlen?', },
    {'Keltus Dunkellaub möchte, dass Ihr das spitzenverzierte Taschentuch von der Anführerin der Schildwachen stehlt und zu ihm bringt.', },
  },
  [9461] = {
    'Ruf des Feuers',
    {'Ihr sollt wissen, dass der Prophet nach Euch gefragt hat, da er von Euren Erfolgen in Euren Prüfungen erfahren hat. Die Erschaffung Eures Feuertotems muss warten, bis Ihr mit ihm gesprochen habt.|n|nDies ist eine seltene Ehre; geht sofort zur Exodar, um so schnell wie möglich mit ihm zu sprechen!', },
    {'Geht zu Prophet Velen in der Halle des Lichts in der Exodar.', },
  },
  [9462] = {
    'Ruf des Feuers',
    {'$N! Es ist an der Zeit, dass Ihr weitere Ausbildung im Weg der Geister erhaltet. Ihr solltet mit Tuluun, dem Schamanen in der Azurwacht, sprechen. Er kann Euch in dem Verständnis und der Beherrschung der Macht des Feuers unterweisen.', },
    {'Geht zu Tuluun in der Azurwacht auf der Azurmythosinsel.', },
  },
  [9463] = {
    'Medizinische Notwendigkeit',
    {'Ich habe herausgefunden, dass die Ranken der Pflanzenkreaturen, den sogenannten Peitschern, auf dieser Insel eine regenerierende Eigenschaft besitzen. Wenn man die Ranken richtig verarbeitet, kann man aus ihnen eine hochwirksame Heilsalbe herstellen. Durch die vielen verletzten Draenei, die ständig in der Azurwacht eintreffen, sind unsere Vorräte an Heilmitteln beinahe erschöpft.|n|nUnser besonderer Gast wurde erst gestern schwer verletzt und bewusstlos am Kristallfluss gefunden. Bringt mir die Wurzeln und wir können sie möglicherweise retten.|n|nHaltet südlich und östlich von hier nach den Lauerwurzkreaturen Ausschau, $C. Ihr dürft keine Zeit verlieren!', },
    {'Anchoret Fateema bei der Azurwacht möchte, dass Ihr für sie 8 Lauerwurzranken sammelt.', },
  },
  [9464] = {
    'Ruf des Feuers',
    {'Ihr sollt noch einmal auf die Probe gestellt werden. Diesmal ist es das chaotische Element des Feuers, das Ihr verstehen müsst, wenn Ihr ein Totem erstellen wollt, um dessen Energien zu nutzen.|n|nIm Nordosten entlang der Küste gibt es einen heiligen Ort des Feuers, den Glutgrund. Inmitten der verbrannten Bäume wacht Glutos, ein besonders mächtiger und weiser Feuerelementar. Mit ihm müsst Ihr sprechen.|n|nGeht jetzt zu ihm, mögen die Elementargeister von Azeroth mit Euch sein.', },
    {'Sprecht mit Glutos beim Glutgrund auf der Azurmythosinsel.', },
  },
  [9465] = {
    'Ruf des Feuers',
    {'Einer meiner Brüder, Hauteur, ist verrückt geworden! Zweifellos ist der Absturz Eures Schiffs daran schuld. Er verlangt jetzt, dass ihn die heimischen Eulenbestien verehren.|n|nDas kann nicht so weitergehen! Keiner von uns würde jemals einen Gott verkörpern! Ihr müsst das Gleichgewicht wieder herstellen.|n|nAls Erstes müsst Ihr ihre Ritualfackel finden, welche in Besitz der wahnsinnigen Wildekin innerhalb der Tannenruhfeste im Westen ist.|n|nBringt mir diese Fackel.', },
    {'Erlangt die Ritualfackel wieder und bringt sie zu Glutos beim Glutgrund auf der Azurmythosinsel.', },
  },
  [9466] = {
    'Gesucht: Schwarzkralle die Wilde',
    {'Auf Anweisung des Waldläuferhauptmanns wird hiermit eine Belohnung auf die Erlegung der teuflischen Felsklauenmatriarchin, bekannt als Schwarzkralle die Wilde, ausgesetzt.|n|nSchwarzkralle wurde zuletzt in einer Höhle in der Großen Kluft gesichtet. Zum Erhalt der Belohnung müssen die Klauen der Kreatur vorgezeigt werden.', },
    {'Bringt Schwarzkralles Klauen zu Waldläuferhauptmann Venn\'ren bei der Falkenwacht auf der Höllenfeuerhalbinsel.', },
  },
  [9467] = {
    'Ruf des Feuers',
    {'Den Eulenbestien vom Mondschwingenbau auf der Silbermythosinsel, weit im Südwesten, wurde weisgemacht, dass Hauteur ein Gott sei, den es zu huldigen gilt. In Wirklichkeit ist er ein abtrünniger Elementar, den man von seinem Leid erlösen muss. Diese Fackel ist der Schlüssel zu seinem Niedergang.|n|nHauteur verlangt von den Eulenbestien die regelmäßige Entzündung eines Feuers zu seinen Ehren. Sobald Ihr es entfacht, wird er kommen. Tötet ihn und bringt mir seine Asche. Verwendet die Kugel in Eurer Tasche und ich werde Euch hierher zu mir zurückbringen.', },
    {'Besorgt Euch Hauteurs Asche und bringt sie zusammen mit der Ritualfackel zu Glutos beim Glutgrund auf der Azurmythosinsel. Vergesst nicht, dass Ihr die Kugel der Rückkehr verwenden könnt, um zu Glutos zurückzukehren, sobald Ihr die Asche habt.', },
  },
  [9468] = {
    'Ruf des Feuers',
    {'Ihr habt heute bei dem Versuch, Eure Bindung zum Feuer zu verstehen, etwas Großartiges geleistet. Vergesst nicht, dass Ihr ihm stets den gebührenden Respekt erweisen sollt, um Euch nicht selbst daran zu verbrennen.|n|nIch habe einen Teil von Hauteurs Asche für Euch aufgehoben. Verwendet ihn, wenn Ihr Euer Feuertotem erstellt und vergesst nichts von dem, was Ihr auf Eurem Weg hierher gelernt habt.|n|nKehrt jetzt zu Tuluun zurück.', },
    {'Bringt Hauteurs Asche zu Tuluun in der Azurwacht auf der Azurmythosinsel.', },
  },
  [9469] = {
    'Federbarts Unterstützung',
    {'Sollte ich endlich eine Audienz bei Falstad Wildhammer gewährt bekommen, hoffe ich einen der besten Fürsprecher der Wildhammerzwerge an meiner Seite zu haben, $N.|n|nFederbart genießt bei seinen Leuten hohes Ansehen, sei es wegen seiner legendären Ausbildungsmethoden für Greifen oder wegen seiner Weisheit. Wenn jemand Falstad Wildhammer überzeugen kann, dann er.|n|nIch würde ihn ja gerne selbst aufsuchen, allerdings darf ich den Nistgipfel nicht verlassen, solange ich meine Audienz erwarte. Sucht Federbart bei seiner Wohnstätte im Süden auf und fragt ihn, ob er an meiner Seite aussagen möchte.', },
    {'Geht zu Federbarts Hütte und stattet dem Zwerg dort einen Besuch ab. Solltet Ihr ihn nicht dort antreffen, so sucht nach Hinweisen auf seinen Verbleib.', },
  },
  [9470] = {
    'Eine Geste des guten Willens',
    {'Das zerklüftete Gebiet des Hinterlands ist nicht nur das Zuhause der Zwerge des Wildhammerklans und ihrer Greifen, sondern auch einiger Waldtrollstämme.|n|nDie Trolle betrachten die Wildhämmer als Besatzer ihres Heimatlands und lassen keine Gelegenheit aus, um die Zwerge zu belästigen, indem sie die Greifennester angreifen. Ein Weg uns in den Augen der Wildhämmer zu beweisen ist, diese Angriffe zum Ende zu bringen, indem wir einen Anführer der Bleichborken, Hexendoktor Mai\'jin, töten. Er befindet sich in einer Höhle in Bogens Kante, westlich von Shadra\'Alor.', },
    {'Botschafter Rualeth auf dem Nistgipfel möchte, dass Ihr Hexendoktor Mai\'jin und seine Spinne Tcha\'kaz tötet.', },
  },
  [9471] = {
    'Die Raubtiere zur Beute machen',
    {'Die Wildhammerzwerge sind die Begleiter, Hüter und Ausbilder der Greifen. Die Greifen haben genügend Feinde, vor allem unter den Stämmen der Waldtrolle.|n|nManchmal stammt die Gefahr aber auch von natürlichen Feinden, wie zum Beispiel den Wölfen. Ein einzelnes Tier ist kein erstzunehmender Gegner für einen Greifen, aber in letzter Zeit werden die Greifen immer häufiger von Rudeln angegriffen, da ihre natürliche Beute knapp wird. Die Wölfe auszulöschen könnte wesentlich zur Sicherheit der Greifen beitragen und uns bei den Wildhämmern sehr beliebt machen.', },
    {'Botschafter Rualeth auf dem Nistgipfel möchte, dass Ihr 10 räudige Silbermähnen und 5 Silbermähnenwölfe tötet.', },
  },
  [9472] = {
    'Arelions Geliebte',
    {'Bei all den wichtigen Dingen, die er zu tun hatte, fand Arelion immer noch genug Zeit seine Geliebte zu besuchen!|n|nJetzt wird mir alles klar. Viera Sonnenwisper, dieses widerwärtige Frauenzimmer... wir werden Ihr beibringen, sich niemals in die Angelegenheiten einer Magistrix einzumischen.|n|nNehmt diese Schriftrolle und findet Viera. Sucht einen Weg, sie vom Dorf wegzulocken und benutzt die Schriftrolle.|n|nArelion erwähnte, dass sie einem bestimmten Wein, der von den Druiden des Cenarius angebaut wird, nicht widerstehen kann. Vielleicht findet Ihr ein wenig davon bei der Zuflucht des Cenarius in den Zangarmarschen westlich von hier.', },
    {'Magistrix Carinda bei der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr Viera Sonnenwisper aus der Siedlung herauslockt und Carindas Rolle der Vergeltung auf sie anwendet.', },
  },
  [9473] = {
    'Eine alternative Alternative',
    {'Der Zustand des Mädchens ist bereits zu kritisch, als dass einfache Salben sie noch retten könnten. Es gibt möglicherweise noch einen anderen Weg...|n|nDer Wald von Azurmythos birgt viele Geheimnisse, eines davon ist eine seltene Pflanze, das Azurlöwenmäulchen, die viele als Allheilmittel ansehen.|n|nSie ist leicht zu entdecken, da sich ihr Aussehen sehr stark von allen anderen Pflanzen unterscheidet und sie ausschließlich im Schatten der Azurkiefer wächst. Beeilt Euch!|n|nUnd $N, nehmt Euch vor den Drescherwurzkreaturen in Acht! Sie ernähren sich von den Azurlöwenmäulchen.', },
    {'Daedal bei der Azurwacht möchte, dass Ihr für ihn 5 Azurlöwenmäulchen sammelt.', },
  },
  [9474] = {
    'Das Mal des Lichtbringers',
    {'In der kurzen Zeit, die ich in Azeroth verbracht habe, habe ich viele seiner Helden studiert. Einer von ihnen, Uther Lichtbringer, hebt sich von allen anderen ab. Nachdem er viele Jahre ein Held war, wurde er am Ende von seinem viel versprechendsten Schüler, Arthas, verraten.|n|nZu seiner Ehre würde ich gerne etwas, das er verloren hat, zu seinem Grabmal bringen. Man sagt, dass der Scharlachrote Kreuzzug eines seiner heiligen Relikte oben in dem Wachturm in der Nähe von Herdweiler aufbewahrt.|n|nBitte, $C, geht und holt es zurück.', },
    {'Besorgt das Mal des Lichtbringers und kehrt dann zu Anachoret Truuen im Zugwindlager in den Westlichen Pestländern zurück.', },
  },
  [9475] = {
    'Wiedererlangen der Eier',
    {'Die Begutachtung der Überreste lässt vermuten, dass es sich bei dem zerschmetterten Skelett um Federbart handeln muss. Eine der skelettierten Hände umklammert fest ein zerfetztes und schmutziges Stück Papier. Ihr zieht es vorsichtig heraus und rollt es auf. Zum Vorschein kommt eine handgezeichnete Karte und ein paar eilig hingekritzelte Notizen.|n|nDie Karte scheint eine Skizze von Shadra\'Alor und seinen drei Tempeln zu sein. Mehrere \'X\' auf der Zeichnung markieren vermutlich die Lage gestohlener Eier. Ihr packt die Karte ein und plant, sie an einem sicheren Ort genauer zu untersuchen.', },
    {'Erlangt 5 Greifeneier und bringt sie zu Botschafter Rualeth beim Nistgipfel.', },
  },
  [9476] = {
    'Suche nach Federbart',
    {'Die jüngsten Einträge in Federbarts Tagebuch beschreiben seine Sorge bezüglich der immer häufigeren Überfälle von Bleichborkentrollen auf die Greifen im Wildhammergebiet und die sich mehrenden Diebstähle von Eiern. Die Untersuchung der kleineren Bleichborkensiedlungen brachte keine Informationen zu Tage.|n|nDer letzte Eintrag handelt von Federbarts Verdacht, dass ein Hexendoktor der Bleichborken, namens Mai\'jin, hinter all den Raubzügen steckt. Am Ende des Eintrags, steht mit hastig geschriebenen Worten, dass der Zwerg die Absicht hat, nach Shadra\'Alor zu gehen und nach den Eiern zu suchen.', },
    {'Reist nach Shadra\'Alor und sucht nach Spuren von Federbart.', },
  },
  [9477] = {
    'Trank der natürlichen Rüstung',
    nil,
    nil,
  },
  [9478] = {
    'Tragbare Heilfontäne',
    nil,
    nil,
  },
  [9479] = {
    'Glorreiches Banner der Allianz',
    nil,
    nil,
  },
  [9480] = {
    'Schwächendes Banner',
    nil,
    nil,
  },
  [9481] = {
    'Leichtes Verbrauchsgut',
    nil,
    nil,
  },
  [9482] = {
    'Trank des Naturwiderstands',
    nil,
    nil,
  },
  [9483] = {
    'Die feinen Freuden im Leben',
    nil,
    nil,
  },
  [9484] = {
    'Die Zähmung der Bestie',
    {'Ihr habt zweifellos schon Tiere für Euren Schutz und für Euren Lebensunterhalt getötet, jedoch seid Ihr erst jetzt bereit, Euch mit ihnen anzufreunden und sie zu zähmen, um von ihrer Stärke Gebrauch zu machen. Ich kann Euch darin ausbilden.|n|nNehmt diese magische Zähmerrute, sie wird ein wildes Tier vorübergehend an Euch binden und an Eurer Seite kämpfen lassen. Beginnt mit einem wahnsinnigen Drachenfalken, ein recht gefügiger Vogel, den man außerhalb der Zuflucht der Weltenwanderer findet. Kehrt anschließend zu mir zurück.', },
    {'Verwendet die Zähmerrute, um einen wahnsinnigen Drachenfalken zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.', },
  },
  [9485] = {
    'Die Zähmung der Bestie',
    {'Ihr habt Euch gut geschlagen, $N. Euer Verständnis für die Wildnis wird rasch größer.|n|nDie Nebelfledermaus ist ein listiger Jäger, sie vereint die Schnelligkeit des Drachenfalken und die Wildheit einer Bachtatze. Man findet die Nebelfledermäuse direkt über dem Elrendar im Süden, wo sie unglücklichen Reisenden auflauern, die in den Geisterlanden umherwandern.|n|nVerwendet diese letzte Zähmerrute, um eine Nebelfledermaus zu bändigen. Kehrt anschließend zu mir zurück.', },
    {'Verwendet die Zähmerrute, um eine Nebelfledermaus zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.', },
  },
  [9486] = {
    'Die Zähmung der Bestie',
    {'Die alte Bachtatze ist ein gründlicher und geschickter Jäger. Wenn man sie zähmen möchte, sieht sie einen sofort als Beute. Lasst Euch nicht von Eurem Vorhaben abbringen.|n|nVerwendet die Zähmerrute, um diese große Katze gefügig zu machen und an ihrer Seite zu jagen. Man findet sie überall im Immersangwald, manche sogar ganz nahe bei der Jagdhütte. Kehrt zu mir zurück, wenn Ihr genug gelernt habt.', },
    {'Verwendet die Zähmerrute, um eine alte Bachtatze zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück.', },
  },
  [9487] = {
    'Arkanhäscher',
    {'Arkanhäscher sind magische Kunstwesen mit roher Kraft. Sie sind dick gepanzert und können schwere Schläge austeilen. Eure Zauberkraft gewährt Euch jedoch den Vorteil, ihre Abwehr umgehen und Treffer von ihnen vermeiden zu können, $N.|n|nReist zum Morgensternturm und sprengt die Arkanhäscher in Stücke! Bei ihren Überresten findet Ihr kristallisierte Fragmente magischer Energie. Sammelt diese und bringt sie zu mir. Den Morgensternturm findet Ihr im Osten, jenseits des Sees.', },
    {'Arkanist Vandril möchte, dass Ihr 10 Arkantrümmer für ihn sammelt.', },
  },
  [9488] = {
    'Eine einfache Robe',
    {'Die Arkantrümmer, die Ihr gesammelt habt, sind gut geeignet.|n|nGeeignet wofür, möchtet Ihr wissen? Um eine prächtige $Crobe für Euch herzustellen!|n|nAlles, was wir jetzt noch benötigen, ist etwas Leinenstoff und eine Seidendrüse der Spindelweber. Die Seidendrüse bekommt Ihr von einer Spindelweberspinne, vorzugsweise nachdem Ihr diese getötet habt.', },
    {'Arkanist Vandril möchte, dass Ihr ihm 15 Leinenstoff und eine Seidendrüse der Spindelweber bringt.', },
  },
  [9489] = {
    'Ordnung in der Schneise',
    {'$N, gut, dass Ihr hier seid. Die Geißel überfällt unsere Stadt mit so unendlichem Hass, dass ich befürchten muss, dass die Moral unserer Wache langsam dahinschwindet.|n|nEilt zu der Todesschneise südlich der Stadt, wo Jaela und ihre Waldläufer bereitstehen. Erfüllt sie mit Eurem Segen mit der Macht des Lichts.', },
    {'Wirkt das Machtwort: Seelenstärke auf 6 Waldläufer von Immersang in der Todesschneise.', },
  },
  [9490] = {
    'Die Felsklauenmatriarchin',
    {'Felsklauen sind bösartige, hinterhältige und grausame Kreaturen. Aber die normalen sind noch harmlose Schoßtierchen im Vergleich zu ihrer Matriarchin, Schwarzkralle der Wilden.|n|nMein Cousin wurde von ihr gefressen. Das war kein schöner Anblick. Ich habe an diesem Tag geschworen, dass Schwarzkralle dafür bezahlen wird. Bringt mir einen Beweis für den Tod dieses Monsters, und ich werde Euch meine Ersparnisse dafür geben. Einverstanden?|n|nIhr findet das Biest in einer Höhle in der Großen Kluft. Viel Erfolg!', },
    {'Besorgt Schwarzkralles Klauen von Schwarzkralle der Wilden in der Großen Kluft und bringt sie zu Ikan beim Tempel von Telhamat auf der Höllenfeuerhalbinsel.', },
  },
  [9491] = {
    'Gier',
    {'Ein reicher, und wenn ich sage \'reich\', meine ich \'stinkreicher\' Händler kam gestern hier vorbei und erzählte etwas über einen Ring von \'immenser archäologischer Bedeutung\', der in einer der zahllosen Grabtruhen in den Amanikatakomben eingeschlossen ist. Wenn er nicht über den Ring sprach, dann darüber, wie viel er dafür bezahlen würde.|n|nIch könnte Euch Diebeswerkzeug vorstrecken, und wenn es Euch gelingt, mir den Ring zu bringen, zahle ich Euch so viel, dass ihr zehn Ringe für Euch selbst kaufen könnt!', },
    {'Eralan in Tristessa möchte, dass Ihr ihr einen gekörnten Goldring aus den Amanikatakomben bringt.', },
  },
  [9492] = {
    'Das Schicksal wenden',
    {'Die weiterhin bestehende orcische Bedrohung ist eine der traurigen Wahrheiten der Scherbenwelt. Es gab eine Zeit, in der wir Söhne des Lothars glaubten, dass wir die Sicherheit der Ehrenfeste mit unserem Blut erkauft haben, aber es sollte keinen Frieden geben.|n|nDie Söhne werden sich keinem Orc fügen - ob er nun grün, braun oder eben rot sein mag - wir werden sie besiegen oder bei dem Versuch sterben. Wenn wir eine Chance auf den Sieg haben wollen, müssen wir sie in der Höllenfeuerzitadelle bekämpfen. Bringt mir die Waffe ihres selbsternannten Kriegshäuptlings Kargath Messerfaust, und ich werde Euch reich belohnen.', },
    {'Bringt Kriegshäuptling Kargaths Faust zu Truppenkommandant Danath Trollbann in der Ehrenfeste.', },
  },
  [9493] = {
    'Der Stolz der Höllenhorde',
    {'Wir wissen herzlich wenig über die Höllenhorde in der Höllenfeuerzitadelle, und die Informationen, die wir haben, wurden teuer mit Blut bezahlt.|n|nDie Truppen der Höllenhorde unter dem Kommando von Kargath Messerfaust sind ein blutrünstiger, schlachterprobter Haufen, der von bösartigen Magiern unterstützt wird. Die Elite dieser Streitkräfte, die Legionäre, Champions und Zenturios der Zerschmetterten Hand, werden von den gewöhnlichen Soldaten gefürchtet und dienen als Offiziere.|n|nAuf sie loszugehen und sie zu vernichten ist der erste wichtige Schritt für einen erfolgreichen Angriff auf die Führung der Höllenhorde.', },
    {'Feldkommandant Romus in der Ehrenfeste möchte, dass Ihr 8 Legionäre der Zerschmetterten Hand, 4 Zenturios der Zerschmetterten Hand und 4 Champions der Zerschmetterten Hand tötet.', },
  },
  [9494] = {
    'Teufelsglut',
    {'Die altmodischen Akademiker Azeroths haben sich schon viel zu lange in ihren Türmen versteckt. Jetzt ist es an mir, ihnen zu zeigen, was hochmoderne Forschung bedeutet! Sie haben Angst, mit dem Feuer zu spielen, und genau das werde ich tun! Das heißt, sobald ich dieses Feuer in die Finger bekomme.|n|nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle vollbringt der Großhexenmeister Nethekurse unerreichte magische Meisterleistungen, die von der Macht einer ungewöhnlichen Kohlenpfanne noch verstärkt werden. Benutzt dieses Gefäß, um ein Stück Teufelsglut zu fangen, und bringt es zu mir, $N.', },
    {'Magus Zabraxis in der Ehrenfeste möchte, dass Ihr ihr ein Stück Teufelsglut bringt.', },
  },
  [9495] = {
    'Der Wille des Kriegshäuptlings',
    {'Es ist nicht einfach, das orcische Volk von seinen verderbten Blutsverwandten zu befreien, $N. Kriegshäuptling Thrall hat schon zu viele orcische Helden durch die Hand des Schicksals fallen sehen. Und nun scheint es, als ob auch Kargath Messerfaust ihm zum Opfer gefallen ist.|n|nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle hat Kargath sich selbst den Titel Kriegshäuptling der Höllenhorde gegeben. Er und seine Armee von irren und blutdurstigen Höllenorcs werden nicht ruhen, bis Thrallmar in Trümmern liegt. Kriegshäuptling Thrall hat befohlen, Kargath und seine Streitkräfte koste es was es wolle zu vernichten.', },
    {'Bringt Kriegshäuptling Kargaths Faust zu Nazgrel in Thrallmar.', },
  },
  [9496] = {
    'Der Stolz der Höllenhorde',
    {'Von Oberanführer Stümmelfaust mal abgesehen, $N, ist mit der Höllenhorde nicht zu spaßen.|n|nSoweit wir wissen, sind die Truppen der Höllenhorde unter dem Kommando von Kargath Messerfaust ein blutrünstiger, schlachterprobter Haufen, der von bösartigen Magiern unterstützt wird. Die Elite dieser Streitkräfte, die Legionäre, Champions und Zenturios der Zerschmetterten Hand, werden von den gewöhnlichen Soldaten gefürchtet und dienen als Offiziere.|n|nAuf sie loszugehen und sie zu vernichten ist der erste wichtige Schritt für einen erfolgreichen Angriff auf die Führung der Höllenhorde.', },
    {'Schattenjäger Ty\'jin in Thrallmar möchte, dass Ihr 8 Legionäre der Zerschmetterten Hand, 4 Zenturios der Zerschmetterten Hand und 4 Champions der Zerschmetterten Hand tötet.', },
  },
  [9497] = {
    'Emblem der Höllenhorde',
    {'Als der Kriegshäuptling von der so genannten Höllenhorde hörte, wurde er sowohl wütend als auch sehr traurig. Wie Rend und seine Hochstapler damals wird auch diese falsche Horde fallen, und ihr Banner wird als Zeichen für die Macht unseres Kriegshäuptlings von den Zinnen der Feste Grommasch wehen.|n|nEs liegt an Euch, in dieser Angelegenheit den Willen des Kriegshäuptlings auszuführen, $N. Es wird nicht einfach werden, denn das Banner wird von einem Champion der Höllenhorde, bekannt als Kriegshetzer O\'mrogg, bewacht. Er wird sich das Banner nicht ohne Kampf nehmen lassen.', },
    {'Tötet Kriegshetzer O\'mrogg und besorgt Euch das Banner der Höllenhorde. Kehrt danach zu Oberanführer Hun Stümmelfaust in Thrallmar zurück.', },
  },
  [9498] = {
    'Falkenwacht',
    {'Mein Volk hat die Falkenwacht erst kürzlich als Operationsbasis im Südwesten der Höllenfeuerhalbinsel, hinter der Höllenfeuerzitadelle, fertiggestellt. Man wird Euch dort als Verbündeten willkommen heißen, $N.|n|nWenn Ihr also auf der Suche nach Arbeit seid, reist dorthin und sagt Waldläuferhauptmann Venn\'ren, dass ich Euch geschickt habe. Er wird Euch sicherlich eine Aufgabe zuweisen können, die Eurer Fähigkeiten würdig ist.', },
    {'Meldet Euch bei Waldläuferhauptmann Venn\'ren bei der Falkenwacht auf der Höllenfeuerhalbinsel.', },
  },
  [9499] = {
    'Falkenwacht',
    {'Was macht Ihr denn noch hier, $N? Habt Ihr nicht gehört, dass wir einen anständigen Außenposten der Sin\'dorei auf der Höllenfeuerhalbinsel errichtet haben?|n|nIhr wärt doch sicher viel lieber bei den Blutelfen als bei all diesem... Gestank hier. Ihr findet die Falkenwacht im Südosten, hinter der Höllenfeuerzitadelle. Meldet Euch bei Waldläuferhauptmann Venn\'ren, er wird sich um Euch kümmern.|n|nDie Straße dorthin ist sehr gefährlich und wird von den Spähern der Allianz überwacht. Reist lieber in Begleitung. Am besten mit Blutelfen.', },
    {'Reist zur Falkenwacht im Südwesten der Höllenfeuerhalbinsel und meldet Euch bei Waldläuferhauptmann Venn\'ren.', },
  },
  [9500] = {
    'Ruf des Wassers',
    {'Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Scharfseher Nobundo hat nach Euch gefragt. Ihr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.|n|nIhr wisst noch, dass Ihr ihn in der Kristallhalle der Exodar findet, ja?', },
    {'Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.', },
  },
  [9501] = {
    'Ruf des Wassers',
    {'Ein mächtiger Wasserelementar namens Aqueous hat nach Euch verlangt. Anscheinend ist das Element des Wassers auf der Blutmythosinsel aus dem Gleichgewicht geraten, was bei der unnatürlichen Vorliebe der Blutelfen nicht wirklich verwunderlich ist.|n|nIhr findet Aqueous in einem versteckten Riff unter den Wogen vor der Küste im Norden der Blutmythosinsel.|n|nNehmt diesen Trank, er wird Euch auf Eurem Weg zu Aqueous behilflich sein, sobald Ihr in der Nähe des Riffs im Wasser seid.', },
    {'Sprecht mit Aqueous im Versteckten Riff bei der Blutmythosinsel.', },
  },
  [9502] = {
    'Ruf des Wassers',
    {'Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Scharfseher Nobundo hat nach Euch gefragt. Ihr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.|n|nIhr wisst noch, dass Ihr ihn in der Kristallhalle der Exodar findet, ja?', },
    {'Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.', },
  },
  [9503] = {
    'Ruf des Wassers',
    {'In Verbindung mit den anderen Elementen ist Wasser der Quell und die Grundlage allen Lebens. Alle Kreaturen sind darauf angewiesen. Allerdings bringt das Wasser durch die Verunreinigung jetzt auch den Tod.|n|nWir müssen das Ausmaß des Schadens erfassen. Im Südwesten liegt ein derart verderbtes Gewässer, welches mittlerweile als besudelter Teich bekannt ist. Geht dorthin und besorgt Euch besudelte Essenzen von den dort lebenden Wassergeistern.', },
    {'Sammelt 6 besudelte Essenzen ein und bringt sie zu Aqueous im Versteckten Riff bei der Blutmythosinsel.', },
  },
  [9504] = {
    'Ruf des Wassers',
    nil,
    {'Füllt den leeren Botabeutel und kehrt anschließend zu Aqueous im Versteckten Riff bei der Blutmythosinsel zurück.', },
  },
  [9505] = {
    'Die Prophezeiung von Velen',
    {'Der Prophet sprach von diesem Tag, da auf dieser Insel, in dieser Welt, sich uns unsere Verbündeten offenbaren würden.|n|n"Man wird uns auf die Probe stellen. Wir werden für die Sünden unserer Vorväter bezahlen..."|n|nDamals blieb mir der Sinn seiner Worte verborgen; doch in dem Moment, als ich dieses Wesen erblickte, wurde mir die Bedeutung seiner Prophezeiung gewahr. Selbst an diesem Ort verspüre ich noch die schleichende Verderbnis unseres Volkes.|n|nBegebt Euch nach Süden, dort wo wir sie gefunden haben. Findet Ihresgleichen und berichtet ihnen von unserem Volk.', },
    {'Daedal möchte, dass Ihr nach Süden reist und die Personen aufsucht, von denen das verletzte Wesen gesprochen hat.', },
  },
  [9506] = {
    'Ein kleiner Anfang',
    {'Ich bin Admiral Odesyus vom Marinekommando der Allianz. Eine Plage der besonderen Art zwang uns dazu, an der Küste Eurer Insel vor Anker zu gehen. Es beschämt mich das sagen zu müssen, doch ein paar Goblins haben es irgendwie geschafft, sich als blinde Passagiere in den Frachträumen unserer beiden Schiffe zu verstecken.|n|nLetzte Nacht, als der Großteil der Schiffsmannschaften in den Kojen lag, schlugen sie zu!|n|nSie stahlen unsere Navigationsinstrumente und sprangen von Bord!|n|nAnschließend verschwanden sie im Dickicht, östlich von hier. Werdet Ihr uns bei der Suche nach den Instrumenten behilflich sein? Es wäre eine großzügige Geste von Euch.', },
    {'Admiral Odesyus bei Odesyus\' Ankerplatz möchte, dass Ihr den von der Venture Co. gestohlenen nautischen Kompass und die nautische Karte wiederbeschafft.', },
  },
  [9507] = {
    'Von Mogul Ratztunks Schreibtisch',
    {'Die Goblins sind diesen Plänen zufolge wegen der Kristalltrümmer der Exodar hier. Es scheint so, als beabsichtigten die Goblins, die Kristalle auf der gesamten Insel abzubauen und die zwei Schiffe der Allianz, die abseits der Küste angelegt haben, zu entführen, sobald sie ihre Pläne in die Tat umgesetzt haben.|n|nIhr solltet diese Pläne besser zu Admiral Odesyus bringen.', },
    {'Bringt die streng geheimen Pläne der Venture Company zu Admiral Odesyus bei Odesyus\' Ankerplatz.', },
  },
  [9508] = {
    'Ruf des Wassers',
    {'Ich habe den Ursprung der Verunreinigung gefunden. Es ist das Nebenprodukt eines wahnsinnigen Experiments und Ihr werdet dem Ganzen ein Ende bereiten!|n|nSüdwestlich des Besudelten Teichs liegt ein kleines Lager, wo Ihr auf das \'Experiment\' von Tel\'athion dem Unreinen stoßen werdet. An diesem Ort erzeugt er den Unrat und lässt ihn in die Gewässer der Insel sickern.|n|nVerwendet das reine Wasser aus dem Eschental, um seine Fässer zu zerstören. Das wird ihn sicherlich aus seinem Versteck locken.|n|nWir werden das alles ein für alle Mal beenden!', },
    {'Bringt Tel\'athions Kopf zu Aqueous im Versteckten Riff bei der Blutmythosinsel zurück.', },
  },
  [9509] = {
    'Ruf des Wassers',
    {'Ich habe etwas von dem Wasser aus dem Eschental beiseite gelegt, jedoch nicht, weil ich an Euren Fähigkeiten, die Situation in den Griff zu bekommen, gezweifelt habe. Im Gegenteil, ich wusste, dass Ihr Erfolg haben würdet. Ich wollte lediglich sicherstellen, dass Ihr etwas Besonderes habt, das Ihr zurück zu Nobundo bringen könnt.|n|nHier, $N, nehmt dieses Fläschchen mit reinstem Wasser. Die Erstellung eines mächtigen Wassertotems ist Euch dadurch gewiss.|n|nScharfseher Nobundo erwartet Eure Rückkehr bei der Exodar.', },
    {'Nehmt das Fläschchen mit reinstem Wasser zu Scharfseher Nobundo innerhalb der Exodar auf der Azurmythosinsel.', },
  },
  [9510] = {
    'Bälge eines borstigen Grollhufs',
    {'Ihr wollt Euch also nützlich machen? Unsere Vorräte an Grollhufbälgen sind sehr knapp, $N.|n|nWenn Ihr von hier aus nach Südwesten geht, werdet Ihr in der Nähe der Falkenwacht haufenweise borstige Grollhufe finden. Ihre Bälge sind ideal für die Lederverarbeitung. Bringt mir einen Stapel davon und ich werde Euch angemessen belohnen.', },
    {'Versorger Braknar beim Mag\'harposten auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 5 Bälge eines borstigen Grollhufs bringt.', },
  },
  [9511] = {
    'Kargaths Schlachtpläne',
    {'Die Dokumente, die Ihr bei Kargath gefunden habt, enthalten genaue Pläne für einen großen Angriff auf die Ehrenfeste.', },
    nil,
  },
  [9512] = {
    'Kräckas Jumboeintopf',
    {'Der Admiral hat wohl Recht, Ihr seid ziemlich clever. Könnt Ihr Kräcka vielleicht aushelfen?|n|nWenn ich der Mannschaft noch einmal Hühnchen vorsetze, werden\'se mich sicher kielholen.|n|nHab\' gesehen, dass es an der Küste nur so von Kriechern wimmelt! Bringt mir Kriecherfleisch und ich steh\' für immer in Eurer Schuld.|n|nHelft Ihr \'nem ehemaligen Piraten aus der Patsche?', },
    {'"Kräcka" Aschebäscha bei Odesyus\' Ankerplatz möchte, dass Ihr ihm 6 Stücke Raubkriecherfleisch bringt.', },
  },
  [9513] = {
    'Die Rückeroberung der Ruinen',
    {'Während einige glauben, dass unsere momentane Lage das Resultat einer langen Kette von unglücklichen Ereignissen ist, glaube ich vielmehr, dass wir aus einem bestimmten Grund hier sind. Die unsichtbare Hand des Schicksals hat uns an diesen Ort verschlagen. Die Gründe dafür werden sich uns im Laufe der Zeit offenbaren.|n|nIm Westen liegt eine uralte Stadt der Nachtelfen, heute sind es nur noch von Naga besetzte Ruinen. Ich wäre nachlässig, würde ich tatenlos zusehen, wie die Naga weiterhin das Land meiner Vorfahren mit ihrer Anwesenheit beflecken.|n|nIhr habt Eure Fähigkeiten als $C unter Beweis gestellt. Nun ehrt mein Volk und reinigt diese Ruinen von seinen unrechtmäßigen Einwohnern.', },
    {'Priesterin Kyleen Il\'dinare bei Odesyus\' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr 5 Myrmidonen der Hasspranken, 5 Naga der Hasspranken und 5 Sirenen der Hasspranken tötet.', },
  },
  [9514] = {
    'Runenbesetzte Schrifttafel',
    {'Es gelingt Euch nicht, die Symbole auf der Schrifttafel zu entziffern. Vielleicht ist die Priesterin in der Lage, die mysteriösen Runen zu entschlüsseln.', },
    {'Bringt die runenbesetzte Schrifttafel zu Priesterin Kyleen Il\'dinare bei Odesyus\' Ankerplatz auf der Azurmythosinsel.', },
  },
  [9515] = {
    'Kriegsherr Sriss\'tiz',
    {'Eine Nagainvasion wäre ein Desaster, $N. Ich habe gesehen, was diese Naga anrichten können und ich werde es nicht zulassen, dass sie weiter über unschuldige Wesen herfallen. Ich nehme an, dass dieser Kriegsherr Sriss\'tiz sich in einer Höhle versteckt - möglicherweise irgendwo an der Küste im Westen.|n|nMacht Kriegsherr Sriss\'tiz ausfindig und beendet seine Herrschaft für immer!', },
    {'Priesterin Kyleen Il\'dinare bei Odesyus\' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr Kriegsherr Sriss\'tiz tötet.', },
  },
  [9516] = {
    'Zerstört die Legion',
    {'Ich werde Ihre Existenz in dieser Welt nicht tolerieren! Die Brennende Legion hat unser Volk fast ausgerottet, und wir mussten ein neues Zuhause in einer neuen Welt suchen. Dann kamen sie erneut. Und wir haben uns zurückgezogen, immer und immer wieder.|n|nNie wieder!|n|nIm Süden gibt es noch ein Überbleibsel der Legion, in den Regionen, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind. Sie sind von dieser Macht, die einst in Eure Welt eingedrungen ist, übriggeblieben.|n|nGeht und zerstört so viele von ihnen, wie Ihr könnt, bevor es zu spät ist!', },
    {'Tötet 15 Dämonen auf dem Dämonenhügel, dem Dämonensturz und dem Dämonenstieg.', },
  },
  [9517] = {
    'Eine schändliche Verschwendung',
    {'Willkommen in Waldeslied, $C. Wo Ihr jetzt noch Zelte seht, werden einst Gebäude stehen, aber dieses Ziel erfordert einen ständigen Nachschub an Baumaterial. Ich bringe es nicht übers Herz, unseren Arbeitern zu befehlen, die uralten Bäume dieses Hains zu fällen, aber unsere Nachbarn im Süden und Westen haben keine so große Ehrfurcht vor dem Wald.|n|nWir werden das verdorbene Holz aus der Festung der Satyrn im Westen zurückfordern. Bringt das Holz zu Knorre im Holzfällerlager des Kriegshymnenklans. Er ist ein Urtum, der es für unsere Zwecke reinigen wird.', },
    {'Sammelt 5 Stück verdorbenes Satyrnaarholz.', },
  },
  [9518] = {
    'Agenten der Zerstörung',
    {'Das Holzfällerlager des Kriegshymnenklans ist ein Schandfleck in unserer Landschaft. Wann immer wir Fortschritte dabei machen, ihre Arbeiten zu stoppen, befiehlt Vorarbeiter Gorthak seinen Holzarbeitern, ihre Anstrengungen noch zu verdoppeln!|n|nJetzt fällen die Orcs mehr Holz, als sie je verbrauchen können und lassen es verrotten, während ihre Klingen schon wieder in frisches Holz schlagen! Dies ist eine Beleidigung gegenüber allem, für das wir einstehen, $N, und wir werden ihnen zeigen, dass wir uns eine weitere Zerstörung unseres Landes nicht gefallen lassen!|n|nGeht, und ruht nicht, bevor Vorarbeiter Gorthak und seine Lakaien tot sind!', },
    {'Tötet Vorarbeiter Gorthak und 12 weitere, beliebige Mitglieder der Horde im Holzfällerlager des Kriegshymnenklans.', },
  },
  [9519] = {
    'Elunes Kelch',
    {'Das Gebiet westlich von hier, das nun Satyrnaar heißt, war einst ein bedeutender Schrein meines Volkes. Dort befand sich ein Relikt von unschätzbarem Wert, Elunes Kelch, der den Hütern des Schreins von den Priestern Elunes anvertraut wurde. Einst reisten Pilger zu dem Schrein, um die heilenden Kräfte, die dem Kelch nachgesagt wurden, am eigenen Leib zu erfahren.|n|nVielleicht sind diese Geschichten nur Ammenmärchen, aber wenn nur ein Körnchen Wahrheit in ihnen steckt, könnte der Kelch vielleicht der Schlüssel zur Wiederherstellung unseres leidenden Waldes sein. Ich muss es wissen, $N.', },
    {'Bringt Elunes Kelch in Euren Besitz.', },
  },
  [9520] = {
    'Teuflische Pläne',
    {'Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise in der Allgemeinsprache verfasst wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend befehligen.|n|nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf Waldeslied im Norden, wo gerade eine neue Draeneisiedlung errichtet wird.|n|nVielleicht ist Verteidiger Vedaar im Holzfällerlager des Kriegshymnenklans daran interessiert?', },
    {'Bringt die teuflischen Pläne zu Verteidiger Vedaar im Holzfällerlager des Kriegshymnenklans im Eschental.', },
  },
  [9521] = {
    'Bericht von der Nordfront',
    {'Die Schlacht gegen das Holzfällerlager des Kriegshymnenklans wird nicht nur vom Rajenbaumturm aus geführt, $N. Eine beträchtliche Anzahl von Schildwachen der Silberschwingen hat sich im Hain der Silberschwingen, in der Nähe der Grenze zum Brachland, postiert. Schildwache Weltensang ist für unsere Bemühungen gegen die, die unser Land zerstören wollen, verantwortlich.|n|nIch bin mit meinem Bericht an Schildwache Weltensang etwas spät dran, möchte aber den Turm nur ungern unbewacht lassen. Wenn Eure Reisen Euch in die Nähe des Silberschwingenhains bringen, könntet Ihr dann meinen Bericht abgeben?', },
    {'Bringt Schildwache Melyrias Bericht zu Schildwache Weltensang im Hain der Silberschwingen im Eschental.', },
  },
  [9522] = {
    'Nie wieder!',
    {'$N, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Ihr müsst losziehen und ihre Anführer erschlagen. Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.|n|nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.|n|nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz. Um dort hinaufzugelangen, sucht nach einem Stieg in der Nähe des Denkmals der Horde für Grom Höllschrei.|n|nBringt mir ihre Waffen.', },
    {'Erhaltet Gorgannons flammende Klinge und den Teufelsspeer des Suchers.', },
  },
  [9523] = {
    'Marmor, Stein und Eisen bricht, aber uralte Nachtelfenrelikte nicht...',
    {'Die Priesterin sagte mir, dass die Ruinen im Westen die Überreste einer Nachtelfenkultur sind. Das erinnerte mich wiederum an etwas, was mein Paps immer über Nachtelfenruinen zu sagen pflegte: "Kleiner, wenn du Nachtelfenruinen siehst, dann sind bestimmt auch Nachtelfenrelikte in der Nähe."|n|nWas für ein Zwerg wäre ich wohl, wenn ich nicht die erste Person anstellen würde, die mir über den Weg läuft, um für mich nach Nachtelfenrelikten zu graben? Los jetzt!', },
    {'Archäologe Adamant Eisenherz bei Odesyus\' Ankerplatz möchte, dass Ihr ihm 8 uralte Relikte bringt.', },
  },
  [9524] = {
    'Gefangene der Zitadelle',
    {'Allianztruppen, hier?! Hört mir genau zu, $C.|n|nKargath hat viele unserer Kämpfer gefangen genommen. Unter ihnen ist auch Hauptmann Alina, einer unserer wichtigsten Offiziere. Rettet sie, bevor sie hingerichtet wird.|n|nMacht Euch um mich keine Sorgen, ich komme hier schon heraus, lasst mich nur etwas Luft schnappen.', },
    {'Rettet Hauptmann Alina aus der Höllenfeuerzitadelle, bevor sie hingerichtet wird.|n|nUm diese Aufgabe zu beenden, müsst Ihr den Dungeon auf dem Schwierigkeitsgrad \'Heroisch\' betreten.', },
  },
  [9525] = {
    'Gefangene der Zitadelle',
    {'Ich hatte Glück und konnte Kargaths Verlies entkommen, $N. Die Hinrichtung der meisten Gefangenen wurde bereits angesetzt, unter ihnen befindet sich einer unserer wichtigsten Offiziere.|n|nHauptmann Knochenbrechers Tod wäre für uns ein schwerer Schlag. Tut alles in Eurer Macht stehende, um ihn vor seinem Schicksal zu bewahren. Ich bin zu schwach, um weiter zu machen...', },
    {'Rettet Hauptmann Knochenbrecher aus der Höllenfeuerzitadelle, bevor er hingerichtet wird.|n|nUm diese Aufgabe zu beenden, müsst Ihr den Dungeon auf dem Schwierigkeitsgrad \'Heroisch\' betreten.', },
  },
  [9526] = {
    'Die Rückeroberung des Dämonenhügels',
    {'Kleines Wesen. Im Süden gibt es ein Gebiet im Nachtweisenwald, das seit kurzer Zeit Dämonenhügel genannt wird. Es ist sehr traurig zu sehen, wie die Dämonen auf ihm herumkrabbeln und ihre Verderbnis verbreiten.|n|nWürdet Ihr etwas tun, um dabei zu helfen, das Land zurückzuerobern?|n|nIch habe ein paar Samen, die ich für eine solche Gelegenheit aufgehoben habe. Bringt sie zum Dämonenhügel und pflanzt sie in fruchtbare Erdhaufen.', },
    {'Pflanzt 8 Baumsetzlinge in die fruchtbaren Erdhaufen.', },
  },
  [9527] = {
    'Was noch bleibt',
    {'Wir lebten viele Jahre in Frieden mit den Kreaturen dieser Insel. Ihr könnt Euch vorstellen, wie überrascht ich war, als sie den Strand stürmten und uns angriffen.|n|nIch habe mich mit Händen und Füßen gewehrt, wurde aber sofort überwältigt. Als ich auf Grund der zahlreichen Schläge in Ohnmacht fiel, betete ich, dass meine Familie nicht leiden muss.|n|nIch erwachte und alles war ruhig. Der Sand war rot, vor Blut getränkt - mit ihrem Blut. Man hatte sie vollständig verschlungen.|n|nIch sehne mich nicht nach Rache, $N. Ich wünsche mir nur, dass man mir ihre Überreste bringt, damit ich sie ordnungsgemäß bestatten kann.', },
    {'Cowlen auf der Azurmythosinsel möchte, dass Ihr ihm die Überreste von Cowlens Familie bringt.', },
  },
  [9528] = {
    'Ein Hilferuf',
    {'Meine Familie wurde vor einigen Wochen von den Murlocs und Eulkin dieser Insel überfallen. Ich schaffte es zu fliehen, aber ich glaube, dass mein Vater und meine Mutter getötet wurden. Ich weiß nicht, was ich jetzt tun soll, aber ich muss versuchen, zurück zu meinem Zuhause zu gehen - oder was davon übrig ist... Könnt Ihr mich durch den Wald begleiten?', },
    {'Begleitet Magwin über die Insel zu ihrem Zuhause.', },
  },
  [9529] = {
    'Der Stein',
    {'Ich bin mir sicher, dass Euer Wichtel sich als nützlicher und manchmal auch unterhaltsamer Begleiter bewiesen hat. Es ist jetzt an der Zeit, dass Ihr einen mächtigeren Dämonen zu beherrschen lernt: den Leerwandler.|n|nReist bis zu dem Punkt der Todesschneise, an dem sie vom Elrendar gekreuzt wird. Macht direkt südlich vom Fluss einen der blauen glühenden Steine ausfindig und nehmt ihn. Euer Weg wird sich Euch dort offenbaren.', },
    {'Beschafft Euch einen Leerstein von der Todesschneise.', },
  },
  [9530] = {
    'Einen Plan aus Hecken',
    {'Ich habe eine ganze Zeit nun darüber gegrübelt, aber es stellt sich als wahr heraus.|n|nEs gibt einen Verräter unter uns.|n|nDie Pläne, die von den Goblins zurückgelassen wurden, bestätigen diesen Komplott. Da ich nicht weiß, wer es sein könnte, benötige ich Eure Hilfe, um den Verräter auszumachen. Keinem aus meiner Mannschaft kann vertraut werden.|n|nFür ein gelungenes Unterfangen benötige ich einen ausgehöhlten Stamm und Laub. Sucht in der Nähe der Holzarbeiter nördlich von uns nach dem Baumstamm. Das Laub müsst Ihr selbst auftreiben. Durchforstet den Wald.', },
    {'Admiral Odesyus bei Odesyus\' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr ihm einen ausgehöhlten Stamm und 5 Laubhaufen bringt.', },
  },
  [9531] = {
    'Laubangriff',
    {'Der Verräter wird sich den Plänen zufolge mit dem Anführer der Goblins, Geezle, bei einer Bucht auf der westlichen Insel treffen. Ihr müsst zu diesem Treffen gehen, $N.|n|nErinnert Ihr Euch an den Stamm und das Laub? Ihr müsst Euch damit verkleiden! Es ist die perfekte Tarnung.|n|nGeht zur Bucht und haltet nach einer Nagaflagge Ausschau. Seht Ihr die Flagge, so wurde ein Treffen arrangiert. Legt die Verkleidung an, wenn Ihr die Flagge seht, und wartet. Der Verräter wird sich früher oder später zeigen. Lasst das Treffen enden und kehrt anschließend mit der Identität des Schufts zu mir zurück.', },
    {'Admiral Odesyus bei Odesyus\' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr das Treffen beobachtet, das Geezle und der Verräter gemeinsam ausgemacht haben.|n|nKehrt zu ihm zurück, wenn Ihr ihm die Identität des Verräters mitteilen könnt.', },
  },
  [9532] = {
    'Findet Keltus Dunkellaub',
    {'$N, einer unserer Späher nimmt seine Pflichten ein wenig zu ernst. Er bewacht unsere Feinde ohne Unterlass, erstattet uns aber keine Berichte darüber.|n|nIhr müsst diesen Spion, Keltus Dunkellaub, finden und überzeugen, damit er seinen Bericht aushändigt und so schnell wie möglich zu mir zurückkommt. Ihr findet ihn weit im Südwesten, wo der Elrendar sich teilt und um Goldnebel herum fließt. Er beobachtet die Nachtelfen von An\'daroth und hält sich sicher in ihrer Nähe auf.', },
    {'Macht Keltus Dunkellaub ausfindig.', },
  },
  [9533] = {
    'Eine helfende Hand',
    {'Meine Leute haben im Osten des Eschentals mithilfe der Kaldorei eine wichtige Entdeckung gemacht.|n|nUnter der Aufsicht von Architekt Nemos und Verteidiger Vedaar erneuern sie einen alten elfischen Außenposten. Der Wiederaufbau wird nicht leicht werden, $N, denn sie stehen vielen Herausforderungen und Feinden gegenüber. Ich weiß, dass Architekt Nemos und seine Landsleute in Waldeslied jede Hilfe, die sie bekommen können, zu schätzen wissen, und er bat mich, $G jeden Mann, der:jede Frau, die; Interesse hat, zu ihm zu schicken.', },
    {'Geht nach Waldeslied im Eschental und sprecht mit Architekt Nemos.|n|nVerteidigerin Palanaar kann Euch ein Reittier anbieten, um schneller dorthin zu gelangen.', },
  },
  [9534] = {
    'Zerstört die Legion',
    {'Die Überreste der Brennenden Legion sind uns schon viel zu lang ein Dorn im Auge!|n|nDas hat jetzt ein Ende!|n|nDie Dämonen greifen von den Gebieten im Osten, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind, an.|n|nGeht und zerstört so viele von ihnen, wie Ihr könnt, und erlangt Ruhm für Euch selbst und für die Horde!', },
    {'Tötet 15 Dämonen auf dem Dämonenhügel, dem Dämonensturz und dem Dämonenstieg und kehrt dann zu Valusha am Splitterholzposten im Eschental zurück.', },
  },
  [9535] = {
    'Teuflische Pläne',
    {'Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise auf Orcisch geschrieben wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend anführen.|n|nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf den Splitterholzposten im Nordwesten.|n|nIhr seid Euch sicher, dass Valusha im Splitterholzposten daran interessiert ist.', },
    {'Bringt die teuflischen Pläne zu Valusha im Splitterholzposten im Eschental.', },
  },
  [9536] = {
    'Nie wieder!',
    {'$N, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet! Geht und erschlagt diese Schreckenslords! Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.|n|nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.|n|nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz.|n|nKehrt mit ihren Waffen als Beweis Eurer Taten zu mir zurück.', },
    nil,
  },
  [9537] = {
    'Keine Gnade mit dem Gnom',
    {'Wir müssen uns Funks vornehmen!|n|nGeht zum Strand und sucht nach diesem betrügerischen Gnom. Quetscht so viele Informationen wie möglich aus ihm heraus!|n|nWer weiß, wie viele andere ebenfalls ein faules Spiel treiben, wenn schon ein hochrangiger Beamter der Allianz solch verräterische Taten begangen hat?|n|nUnd $N, wendet Gewalt an, wenn es nicht anders geht...', },
    {'Admiral Odesyus bei Odesyus\' Ankerplatz möchte, dass Ihr die Mitteilung des Verräters von Ingenieur "Funks" Oberschleif an Euch bringt.', },
  },
  [9538] = {
    'Erlernen der Sprache',
    {'Ich glaube, ich hab\'s, $N!|n|n<Aurren zeigt auf das Totem.>|n|nAlles, was wir über die Sprache der Furbolgs der Tannenruhfeste wissen müssen, ist auf ihren Totems verzeichnet. Wenn wir den grundlegenden Aufbau der Symbole verstehen, können wir die Totems studieren und somit lernen, mit den Furbolgs zu kommunizieren.|n|nIch habe das Grundmuster der Symbole auf dieses Pergament gezeichnet. Studiert es und untersucht dann das Totem. Es sollte Euch zu dem nächsten Sprachtotem führen.|n|nSprecht mit Arugoo, wenn Ihr als gelehrter $R zurückkehrt!', },
    {'Lest die Übersetzungsfibel der Tannenruhfeste, die Aurren Euch gegeben hat. Kommuniziert anschließend mit dem Totem von Akida bei der Azurwacht.', },
  },
  [9539] = {
    'Totem von Coo',
    {'Ihr beginnt das Totem zu entschlüsseln, die komplizierten Begriffe lassen sich kaum aussprechen. Langsam formen sich Worte in Eurem Kopf. Das Totem scheint Euch sagen zu wollen: Geht auf dem nahegelegenen Hügel nach oben, Richtung Nordosten.', },
    {'Findet das Totem von Coo, indem Ihr den Hinweisen folgt.', },
  },
  [9540] = {
    'Totem von Tikti',
    {'Ihr beginnt das Totem zu entschlüsseln, die Begriffe lassen sich bereits etwas leichter aussprechen. Worte formen sich in Eurem Kopf. Das Totem scheint Euch sagen zu wollen: Überquert den Kristallfluss Richtung Osten. Vielleicht liegt Euer Ziel ja auf der anderen Uferseite des Flusses.', },
    {'Findet das Totem von Tikti, indem Ihr den Hinweisen folgt.', },
  },
  [9541] = {
    'Totem von Yor',
    {'Die Symbole des Totems scheinen sich viel schneller entschlüsseln zu lassen. Die Begriffe ergeben rasch einen Sinn. Ihr seid ziemlich sicher, dass das Totem Euch auf etwas den Fluss herab im Süden verweist. Etwas muss auf dem Grund des Flusses selbst liegen.', },
    {'Findet das Totem von Yor, indem Ihr den Hinweisen folgt.', },
  },
  [9542] = {
    'Totem von Vark',
    {'Die Symbole auf dem Totem lassen sich jetzt ganz einfach lesen. Es ist, als wäre die Beschriftung auf dem Totem von Yor in Eurer Muttersprache verfasst worden.|n|nDie Hinweise deuten auf einen anderen Furbolgbau im Westen hin. Ihr entschlüsselt meisterhaft die Sprache auf dem Totem und wisst, dass Euer Ziel das Dorf der Sichelklauen ist. Yor wird Euch dorthin führen, falls Ihr Euch dennoch verlaufen solltet, wisst Ihr, dass Ihr die alte Elfenstraße im Wald nehmen könnt, die Richtung Westen zu Eurem Ziel führt.', },
    {'Findet das Totem von Vark, indem Ihr den Hinweisen folgt.', },
  },
  [9543] = {
    'Sühne',
    {'Unsere Vergangenheit mit den Orcs ist gezeichnet von andauernden Konflikten, $N. Einst hätten sie uns im Blutrausch beinahe vollständig ausgelöscht und selbst als der dämonische Einfluss von ihnen wich, haben wir uns weiter von den Orcs fern gehalten.|n|nTrotz dieser Vergangenheit... das Letzte, was Sedai gewollt hätte, wäre Rache und Blutvergießen. Sprecht mit unserem Ältesten, Amaan dem Weisen. Ihm wird es gelingen, Licht in diese Ereignisse zu bringen.', },
    {'Sprecht mit Amaan dem Weisen beim Tempel von Telhamat auf der Höllenfeuerhalbinsel.', },
  },
  [9544] = {
    'Die Prophezeiung von Akida',
    {'Die Abbildungen auf dem Totem stellen einen Krieg zwischen dem Furbolgstamm der Tannenruhfeste und dem der Sichelklauen dar. Die Motive zeigen Gräueltaten, die die Sichelklauen den Furbolgs der Tannenruhfeste angetan haben.|n|nInmitten des Chaos wird eine Prophezeiung offenbart: Ein Held wird kommen - in seinen Adern fließt kein Furbolgblut - er wird den Stamm der Tannenruhfeste erretten.|n|nTötet die Furbolgs der Sichelklauen im Dorf der Sichelklauen für ihre Schlüssel. Verwendet diese Schlüssel, um gefangene Furbolgs der Tannenruhfeste zu befreien. Sobald Ihr alle befreit habt, kehrt zu Arugoo der Tannenruhfeste zurück.', },
    {'Befreit 8 gefangene Furbolgs der Tannenruhfeste aus den Käfigen im Dorf der Sichelklauen. Kehrt anschließend zu Arugoo der Tannenruhfeste bei der Azurwacht zurück.', },
  },
  [9545] = {
    'Das Relikt des Sehers',
    {'Die Störrischen unter uns verschließen ihren Geist und glauben an die eine Wahrheit. Der Weise jedoch, hat ein offenes Ohr für die Existenz unterschiedlicher Möglichkeiten, die letztlich zur Gegenwart führen, oder von ihr ausgehen.|n|nBringt dieses Relikt zu dem Ort, an dem Ihr Sedai gefunden habt. Seht nicht mit Euren Augen, $N, sondern mit Eurem Verstand.', },
    {'Amaan der Weise beim Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr Sedais Leichnam erneut aufsucht, um dort das Relikt des Sehers zu benutzen. Kehrt nach Abschluss der Aufgabe zu ihm zurück.', },
  },
  [9546] = {
    'Einlösung eines Versprechens',
    {'Die Prophezeiung sprach von jemanden, der sich erheben würde und uns aus dem eisernen Griff der Sichelklauen befreien würde - die Geister selbst sollten das Erscheinen dieses Helden ankündigen.|n|nJetzt seid Ihr gekommen.|n|nIch verbeuge mich in Demut vor Euch, oh Einzigartiger. Ich flehe Euch an, rettet unsere Jüngsten. Sie wurden von den Sichelklauen entführt, nachdem man unsere Verteidigung lahmgelegt hat. Ihr findet sie in Käfigen im Dorf der Sichelklauen im Südwesten. Die Furbolgs der Sichelklauen tragen die Schlüssel für die Käfige bei sich. Streckt sie nieder und entwendet die Schlüssel. Befreit meinesgleichen.', },
    {'Arugoo der Tannenruhfeste hat Euch gebeten, 8 gefangene Furbolgs der Tannenruhfeste aus Käfigen im Dorf der Sichelklauen zu befreien.', },
  },
  [9547] = {
    'Ruf der Luft',
    {'$N, Scharfseher Nobundo hat nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!|n|nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.', },
    {'Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.', },
  },
  [9548] = {
    'Gestohlene Ausrüstung',
    {'Schhh! Sprecht leise und lenkt keine Aufmerksamkeit auf mich.|n|nWenn die Murlocs meiner Anwesenheit gewahr werden, ist es mit dem Experiment vorbei! Ich war schon sehr nahe daran, meine Arbeit zu gefährden.|n|nAls ich gestern am Herumkramen war, muss einer von ihnen zu nahe gekommen sein und mein Lager entdeckt haben. Ich kam noch rechtzeitig, um zwei von ihnen eine meiner Ausrüstungskisten fortschleppen zu sehen! Sie muss in einer ihrer Siedlungen hier zu finden sein, aber ich kann es nicht riskieren, meine Deckung aufzugeben. Wollt Ihr mir vielleicht helfen?', },
    {'Bringt Kloppers Ausrüstung zurück zu Klopper Knacksklug, der sich in einem angespülten Schildkrötenpanzer versteckt hält.', },
  },
  [9549] = {
    'Schwarzschlammartefakte',
    {'Meine Beobachtungen und Aufzeichnungen über die Murlocs der Schwarzschlammküste sind recht aufschlussreich, $N, aber ich habe gerade erst damit angefangen. Ich habe vor, mit Gegenständen, die auf primitivste Weise von den Murlocs der Schwarzschlammküste hergestellt wurden, nach Eisenschmiede zurückzukehren.|n|nDas Problem ist allerdings, dass die Murlocs diese Gegenstände stets bei sich tragen. Ich könnte es nicht ertragen, wenn meine Hände mit ihrem Blut befleckt wären. Wollt Ihr mir vielleicht dabei helfen, Götzen von den Sehern der Schwarzschlammküste und kunstlosen Messer von den Kriegern und Küstenschlägern der Schwarzschlammküste einzusammeln? Ich werde Euch auch nicht fragen, wie Ihr sie Euch beschafft habt.', },
    {'Bringt 3 kunstlose Murlocgötzen und 6 kunstlose Murlocmesser zu Klopper Knacksklug, der sich in einem angespülten Schildkrötenpanzer versteckt hält.', },
  },
  [9550] = {
    'Wohin führt die Karte?',
    {'Die nicht gerade sorgfältig gezeichnete Karte verrät zwar nichts über ihren Verfasser, scheint aber mit zittrigen Händen angefertigt worden zu sein. Krakelige Linien und Symbole beschreiben einen kleinen Pavillon mit eingestürzten Säulen. Er befindet sich im Westen eines Turms, der teilweise unter Wasser steht.|n|nGlaubt man der Karte, so liegen diese Ruinen an der östlichen Küste der Insel. Es ist Euch ein Rätsel, was Ihr dort vorfinden werdet, es scheint für die Erstellung dieser Karte jedoch wichtig genug gewesen zu sein.', },
    {'Macht den auf der Karte beschriebenen Pavillon ausfindig und sucht, auf was der Verfasser der Karte hinweisen wollte.', },
  },
  [9551] = {
    'Ruf der Luft',
    {'$N, Scharfseher Nobundo hat nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!|n|nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.', },
    {'Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.', },
  },
  [9552] = {
    'Ruf der Luft',
    {'Der mächtige Geist der Luft verlangt nach Euch, $N, es ist an der Zeit, diesem Ruf zu folgen.|n|nIch möchte, dass Ihr den Wildwindpfad im Norden hinaufwandert, dem Berg zugewandt, an dem die Exodar zerschellt ist. Auf seinem Gipfel werdet Ihr eine Höhle finden und darin eine meiner am besten ausgebildeten Schülerinnen, Velaada.|n|nBitte, hört auf ihre Weisheit und befolgt ihren Rat. Wenn Ihr zurückkehrt, werdet Ihr ein größeres Verständnis für das Element der Luft haben.', },
    {'Sprecht mit Velaada beim Wildwindgipfel auf der Azurmythosinsel.', },
  },
  [9553] = {
    'Ruf der Luft',
    {'Die Luft scheint flüchtig zu sein, sie ist jedoch eine alles bedeckende und durchdringende Kraft, die uns umgibt.|n|nAuch wenn Ihr sie nicht sehen könnt, so bestehen die Felsen dieser Höhle doch hauptsächlich aus Luft, das Wasser der Ozeane ist mit ihr gesättigt und ohne sie könnte kein Feuer bestehen. Lasst dies die Elemente niemals hören!|n|nDerjenige, den Ihr wegen dieses Wissens wirklich zu sprechen wünscht, ist ganz in der Nähe. Am nördlichen Ende der Felsklippe erwartet Euch Susurrus. Mit seiner Hilfe werdet Ihr verstehen lernen.', },
    {'Sprecht mit Susurrus beim Wildwindgipfel auf der Azurmythosinsel.', },
  },
  [9554] = {
    'Ruf der Luft',
    {'Während meine Brüder und Schwestern der anderen Elemente die Erfüllung verschiedenster Aufgaben von Euch verlangten, werde ich keine weiteren Anforderungen an Euch stellen. Ich glaube, dass Ihr genug geleistet habt, um für eine \'Wiedergutmachung\' für den Unfall, den der Absturz Eures Schiffs verursacht hat, zu sorgen. Ich kann sehen, dass Ihr bereits über die Erfahrenheit verfügt, die Ihr für einen weisen Umgang mit dem Element der Luft benötigt.|n|nNehmt diesen Teil meiner Selbst zurück zu Scharfseher Nobundo, damit er Euch bei der Erstellung Eures Totems helfen kann. Sobald Ihr bereit seid, werde ich Euch zurück zur Exodar fliegen.', },
    {'Kehrt mit dem Luftwirbel zu Scharfseher Nobundo bei der Exodar auf der Azurmythosinsel zurück.', },
  },
  [9555] = {
    'Ruf des Feuers',
    {'Es freut mich, dass Ihr den schwierigen Pfad des Schamanen gewählt habt. Nur wenige entscheiden sich für diesen Weg, aber ich spüre, dass es für unsere Zukunft von großer Bedeutung sein wird, die Macht des Schamanismus von den Zerschlagenen zu erlernen.|n|nMan nennt sie so, aber einst waren auch sie Draenei. Teuflische Magie hat sie verwandelt und deshalb können sie sich nicht auf die Macht des Lichts berufen. Einige missbilligen sie und den Schamanismus, den sie lehren, aber sie sind nicht bösartig.|n|nIch möchte, dass Ihr mit Scharfseher Nobundo sprecht. Er ist der weiseste Schamane, den ich kenne, er wird Euch viel beibringen können.', },
    {'Sprecht mit Scharfseher Nobundo in der Kristallhalle der Exodar.', },
  },
  [9556] = {
    'Dem Sieger...',
    {'Ihr habt zweifellos lange und hart um die Verteidigung der Türme gekämpft, $R. Wir würden Euch gerne etwas im Gegenzug für Euren tapferen Einsatz geben, allerdings müsst Ihr uns zuerst beweisen, dass Ihr die Gewichtigkeit dieser hier stattgefundenen Tragödien auch versteht.|n|nLauft durch Stratholme und sucht nach einer Phiole mit dem heiligen Wasser. Sobald Ihr sie gefunden habt, reist zum Magierviertel in Sturmwind oder nach Unterstadt... Dort werdet Ihr, insofern Ihr in diesen Landen siegreich wart, auf meinen Kollegen treffen.', },
    {'Sucht nach einer Phiole mit heiligem Wasser in Stratholme und bringt sie zu dem Magier von Lordaeron im Magierviertel von Sturmwind oder in Unterstadt, falls Eure Seite in den Östlichen Pestländern erfolgreich war.', },
  },
  [9557] = {
    'Entziffern des Buchs',
    {'Da Ihr über keinerlei Mittel verfügt, die es Euch ermöglichen würden, den Inhalt des Buchs zu entschlüsseln, versucht Ihr Euch jemanden ins Gedächtnis zu rufen, der Euch dabei helfen könnte, die ursprünglichen Eintragungen zwischen dem Gekritzel des Kartenverfassers herauszulesen.|n|nIhr erinnert Euch an Anachoret Paetheus\' Sammlung verschiedenster Artefakte, die die Draenei während ihrer Reisen entdeckten. Vielleicht können Euch ja seine erfahrenen Augen bei der Entzifferung des Buchs weiterhelfen.', },
    {'Bringt das alte Tagebuch zu Anachoret Paetheus bei der Blutwacht.', },
  },
  [9558] = {
    'Die Langbarts',
    {'Vor nicht allzu langer Zeit hatten wir einige Probleme mit Arakkoabanditen. Sie haben viele unserer Versorgungskarawanen überfallen, weswegen ich ein paar Zwerge angeheuert habe, die sich um sie kümmern sollten.|n|nEs waren Brüder, wobei Gremni Langbart der Älteste von ihnen war. Sie sind losgezogen und nie zurückgekehrt.|n|nIch mache mir ein wenig Sorgen um sie, versteht Ihr? Diese verrückten Zwerge haben mehr Bier als Essen oder Munition eingepackt! Könntet Ihr vielleicht einmal nach ihnen sehen?|n|nDas Versteck der Arakkoa, der Haal\'eshbau, befindet sich von hier aus weit im Westen, hinter der Großen Kluft. Sie müssen irgendwo dort in der Nähe ein Lager aufgeschlagen haben.', },
    {'Sucht nach Gremni Langbart nordwestlich des Haal\'eshbaus, weit im Westen der Ehrenfeste auf der Höllenfeuerhalbinsel.', },
  },
  [9559] = {
    'Tannenruhfeste',
    {'Auserwählter, Ihr müsst nach Norden zur Heimstätte meiner Leute reisen - zur Tannenruhfeste. Dort werdet Ihr auf Eure schrecklichste Herausforderung treffen.|n|nGeht jetzt, der Oberhäuptling der Tannenruhfeste erwartet Euch.', },
    {'Sprecht mit dem Oberhäuptling bei der Tannenruhfeste.', },
  },
  [9560] = {
    'Biester aus der Apokalypse!',
    {'Mein Bruder und ich waren im östlich gelegenen Wald beim Jagen, als wir von seltsamen, insektenartigen Biestern angegriffen wurden. Solch fremdartige Geschöpfe hatten wir zuvor noch nie auf der Azurmythosinsel gesehen! Könnten es die Vorboten der angekündigten Apokalypse sein? Der Weltuntergang, den IHR verhindern sollt?|n|nSolltet Ihr wirklich der auserwählte Held sein, so werdet Ihr die Biester der Apokalypse bezwingen... und mir ihre Bälge bringen. Ich kann Euch aus diesem Material eine mächtige Rüstung anfertigen!|n|nSucht Richtung Osten nach ihnen, abseits der Straße.', },
    {'Moordo bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr ihm 8 Felshetzerbälge bringt.', },
  },
  [9561] = {
    'Nolkais Worte',
    {'Ich bin mit der Entschlüsselung jetzt fertig, $N.|n|n<Anachoret Paetheus zeigt auf einen Textabschnitt am Ende seiner Abschrift.>|n|n\'Der Feind ist ganz nah. Wir haben alle Überlebenden zusammengerufen und uns mit ihnen zu dem östlich gelegenen Tempel geflüchtet. Es ist der letzte Ort auf dieser Insel, den wir noch halten können. Unter den Überlebenden hat sich der Glaube verbreitet, dass dies unsere endgültige Zuflucht sein wird. Ich habe Vorkehrungen getroffen und meine verbliebene Habe im Boden des Tempels vergraben. Ich hoffe, dass sie jemand finden und somit erfahren wird, was hier geschehen ist.\'', },
    {'Findet den in Nolkais Tagebuch beschriebenen Ort und sucht nach seinen seit langem vergrabenen Besitztümern.', },
  },
  [9562] = {
    'Murlocs... Warum hier? Warum jetzt?',
    {'Es herrschen dunkle Zeiten, $G Auserwählter:Auserwählte;. Sogar die Murlocs trampeln uns auf den Füßen herum - im wahrsten Sinne des Wortes. Unglücklicherweise wurde nicht nur mein Stolz verletzt.|n|nUnser Verhältnis zu den Schlickflossenmurlocs war zwar schon immer recht bescheiden, jedoch hätten wir uns niemals vorstellen können, dass sie uns angreifen und von unseren Essensvorräten stehlen würden! Reist Richtung Westen zur Schlickerküste und bringt uns unsere gestohlenen Vorräte wieder!|n|nUnd solltet Ihr einen dunkelhäutigen Murloc mit einem Stück weißen Fell zwischen den Schwimmhäuten sehen...', },
    {'Gurf bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr 5 Säcke mit Tannenruhgetreide wiedererlangt.', },
  },
  [9563] = {
    'Mirrens Vertrauen erlangen',
    {'Ihr wollt also unser Vertrauen erlangen? In diesen Zeiten vertraue ich nicht vielen Leuten.|n|nVor kurzer Zeit haben wir einen der unseren an die Arakkoa verloren. Das hat mich etwas nervös gemacht.|n|nIch sag\' Euch was, wenn Ihr Eure Loyalität gegenüber der Ehrenfeste beweisen könnt und... mir einen Krug Nethergarde Bitter bringt... ja, das klingt so weit ganz gut... dann biete ich Euch einen Handel an.|n|nBernie in der Burg Nethergarde hat das Bitter auf Lager.', },
    {'Mirren Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 1 Nethergarde Bitter bringt. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Ehrenfeste.', },
  },
  [9564] = {
    'Gurfs Würde',
    {'Nehmt dem Murloc das Stück Fell, das Gurf bei seiner Auseinandersetzung mit den Biestern "verloren" hat, ab und bringt es anschließend zu Gurf zurück. Lasst ihn sogleich wissen, dass der entsetzliche Murgurgula vernichtet wurde.', },
    {'Bringt Gurfs Würde zu Gurf bei der Tannenruhfeste auf der Azurmythosinsel.', },
  },
  [9565] = {
    'Sucht in der Tannenruhfeste',
    {'Als Oberhäuptling gilt meine erste Sorge der Ursache, die hinter der Verderbnis innerhalb der Tannenruhfeste steckt.|n|nWarum haben uns die Wildekin - einst unsere Verbündeten - angegriffen? Warum haben sie die Tannenruhfeste besetzt?|n|nVielleicht finden wir im Innern der Feste ja eine Antwort. Sucht in der Tannenruhfeste nach dem Quell der Verderbnis.', },
    {'Sucht in der Tannenruhfeste nach Hinweisen.', },
  },
  [9566] = {
    'Blutkristalle',
    {'Außerhalb des Wassers sieht der Kristall wie ein Teil der Exodar aus. Allerdings scheint mit diesem Kristall etwas nicht zu stimmen, denn er ist blutrot und löst sich sehr schnell im Wasser des Kellers auf.|n|nDas könnte das ungewöhnlich aggressive Verhalten der Kreaturen auf der Azurmythosinsel erklären. Kehrt mit diesen Informationen zum Oberhäuptling der Tannenruhfeste zurück.', },
    {'Sprecht mit dem Oberhäuptling bei der Tannenruhfeste.', },
  },
  [9567] = {
    'Kenne deinen Feind',
    {'Es tut gut, neue Gesichter hier bei der Blutwacht zu sehen, $C. Die Blutelfen stellen zwar die derzeit größte Bedrohung für uns dar, jedoch gibt es noch andere finstere Kreaturen, die die Blutmythosinsel zu ihrem Zuhause gemacht haben.|n|nDie Satyrn der Nazzivus beunruhigen uns besonders. Es sind üble, dämonische Kreaturen, die dunkle Magien beherrschen und sich an der Verderbnis nähren, die der Absturz der Exodar verursacht hat.|n|nWir müssen sie in Schach halten, aber bevor wir handeln, gilt es noch etwas mehr über sie in Erfahrung zu bringen. Geht nach Nazzivian im Westen und versucht so viel wie möglich von ihrem grotesken Monument zu lernen.', },
    {'Findet das Monument der Nazzivus in Nazzivian und beschafft Euch eine Glyphe vom Monument der Nazzivus. Kehrt zu Verteidiger Aalesia bei der Blutwacht zurück, sobald Ihr die Glyphe habt.', },
  },
  [9568] = {
    'In der Offensive',
    {'Es ist schlimmer, als ich dachte, $N. Wir Draenei wissen nur zu gut, was passiert, wenn man seine Seele an die Brennende Legion im Austausch für das Versprechen von Macht und Unsterblichkeit verkauft.|n|nDie Satyrn auf dieser Insel, die Nazzivus, sind Abkömmlinge der ersten abartigen Kreatur, die sich mit der Legion verbündet hatte. Ich fürchte, dass sie einen Weg finden werden, um die Kraft der Kristalle von der Exodar gegen uns zu verwenden.|n|nIhr habt gesehen, was sie diesem Land angetan haben. Stellt Euch nur vor, was sie in den Händen der Satyrn anrichten könnten. Geht Richtung Südwesten nach Nazzivian und startet unsere Offensive!', },
    {'Verteidigerin Aalesia bei der Blutwacht möchte, dass Ihr 10 Satyrn der Nazzivus, 5 Schurken der Nazzivus und 5 Teufelsanbeter der Nazzivus tötet.', },
  },
  [9569] = {
    'Die Bedrohung bekämpfen',
    {'Jetzt, da wir bei den Satyrn Eindruck hinterlassen haben, müssen wir ihnen zu verstehen geben, dass wir Übeltäter der Brennenden Legion hier nicht dulden.|n|nDie Draenei sind schon viel zu lange im Schatten der Legion und ihrer Diener geflohen, $N. Wo immer sie uns auch fanden, sie zeigten niemals Gnade.|n|nWir dürfen es nicht zulassen, dass die Satyrn den Absturz der Exodar ausnutzen und die verderbten Kristalle als Waffe einsetzen. Geht nach Axxarien im Norden, dem Sitz ihres Anführers. Tötet ihn und nehmt die verderbten Kristalle, die er angesammelt hat, an Euch!', },
    {'Tötet 5 Schattenpirscher von Axxarien, 5 Höllenrufer von Axxarien und Zevrax. Sammelt außerdem 5 verderbte Kristalle ein und kehrt zu Verteidigerin Aalesia bei der Blutwacht zurück.', },
  },
  [9570] = {
    'Kurken lauert',
    {'Nachdem der Kristallsturm nachgelassen hatte, erschien eine mythische Bestie in unserem Dorf. Das Untier, Kurken, das von den einfallenden Wildekin hierher gebracht wurde, legte alles in Trümmer. Zahlreiche Furbolgs der Tannenruhfeste wurden bei der Verteidigung unseres Landes von der Bestie getötet. Beim Versuch, das Untier zu bezwingen, ließen viele weitere ihr Leben.|n|nIn meinen Visionen sah ich jemanden, der Kurken besiegte. Diese Person müsst Ihr sein, $N. Es kann nur einen geben. Betretet die Tannenruhfeste und tötet Kurken. Bringt mir seinen Balg als Beweis für Eure Tat.', },
    {'Kurz der Weise bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr Kurken tötet und dass Ihr ihm Kurkens Balg bringt.', },
  },
  [9571] = {
    'Kurkens Balg',
    {'Bringt Kurkens Balg zu Moordo, auf der anderen Seite des Dorfes. Er wird daraus ein Rüstungsteil Eurer Wahl anfertigen.', },
    {'Bringt Kurkens Balg zu Moordo bei der Tannenruhfeste.', },
  },
  [9572] = {
    'Die Bollwerke schwächen',
    {'Schnell, wir haben nicht viel Zeit. Thrallmars Existenz steht auf Messers Schneide!|n|nWir sitzen zwischen der Höllenfeuerzitadelle im Westen und der Brennenden Legion im Osten fest. Da die Legion ihre Aufmerksamkeit auf das Dunkle Portal gerichtet hat, müssen wir die Chance nutzen, um die Höllenorcs in der Zitadelle anzugreifen. Der Schlüssel dazu ist, zunächst die Bollwerke zu durchbrechen!|n|nGeht dorthin, tötet ihre Anführer und bringt einen Beweis für Eure Tat zu Caza\'rez gegenüber von mir!', },
    {'Tötet den Wachhabenden Gargolmar, Omor den Narbenlosen und Nazan, den Drachen. Bringt Gargolmars Hand, Omors Huf und Nazans Kopf zu Caza\'rez in Thrallmar auf der Höllenfeuerhalbinsel.', },
  },
  [9573] = {
    'Häuptling Oomooroo',
    {'Ich bin der Jüngling Tannenruh, Erbe des Vermächtnisses von Tannenruh. Wie Ihr sehen könnt, haben meine Verteidiger eine Todesfalle für die irren Wildekin aufgestellt, die von der Tannenruhfeste aus angreifen. Wir können sie zwar hier draußen abwehren, allerdings hat es noch keiner meiner Verteidiger geschafft, in die Feste vorzudringen. Wenn es Euch gelingen sollte, dort hinein zu gelangen und ihren Anführer zu töten, würde uns das vielleicht eine Gelegenheit zum Angriff verschaffen!|n|nFindet Häuptling Oomooroo und vernichtet ihn. Tötet auch alle wahnsinnigen Wildekin, die Euch im Innern der Feste in die Quere kommen.', },
    {'Der Jüngling Tannenruh bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr Häuptling Oomooroo und 9 wahnsinnige Wildekin tötet.', },
  },
  [9574] = {
    'Opfer der Verderbnis',
    {'Unsere Ankunft hat die Blutmythosinsel für alle Zeit verändert. Der Absturz der Exodar hat Trümmer über die gesamte Insel verstreut und ich glaube, dass sich dies langsam negativ auf die Natur hier auswirkt.|n|nIch muss mir alles erst genauer ansehen, bevor ich meine Schlussfolgerung bestätigen kann. Die Kristalle scheinen die Bäume als erstes beeinträchtigt zu haben, also müssten die Treants am ehesten die Symptome aufweisen. Wenn Ihr mir Proben von der Rinde verderbter Treants bringen würdet, könnte ich mich weiter in meine Studien vertiefen.', },
    {'Bringt 6 Stücke kristallisierte Rinde zu Morae bei der Blutwacht.', },
  },
  [9575] = {
    'Die Bollwerke schwächen',
    {'Schnell, wir haben nicht viel Zeit. Die Existenz der Ehrenfeste steht auf Messers Schneide!|n|nWir sitzen zwischen der Höllenfeuerzitadelle im Westen und der Brennenden Legion im Osten fest. Da die Legion ihre Aufmerksamkeit auf das Dunkle Portal gerichtet hat, müssen wir die Chance nutzen, um die Höllenorcs in der Zitadelle anzugreifen. Der Schlüssel dazu ist, zunächst die Bollwerke zu durchbrechen!|n|nGeht dorthin, tötet ihre Anführer und bringt einen Beweis für Eure Tat zu Gunny gegenüber von mir!', },
    {'Tötet den Wachhabenden Gargolmar, Omor den Narbenlosen und Nazan, den Drachen. Bringt Gargolmars Hand, Omors Huf und Nazans Kopf zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel.', },
  },
  [9576] = {
    'Schandflosses Anhänger',
    {'Ihr untersucht den sehr simpel angefertigten Anhänger und stellt fest, dass der Kristall ganz sachte pulsiert. Er leuchtet ein wenig, aber Ihr spürt auch, dass irgendetwas Unnatürliches davon ausgeht.|n|nIhr seid Euch zwar nicht sicher, was Schandflosse zur Anfertigung dieses Anhängers getrieben hat, aber der Fund scheint zu wichtig, als dass er ignoriert werden könnte. Ihr solltet ihn jemandem bei der Blutwacht zeigen.', },
    {'Bringt den roten Kristallanhänger zu Morae bei der Blutwacht.', },
  },
  [9577] = {
    nil,
    {'Sucht<QUESTGIVER> in <LOCATION>. Sie/er hat eine schwierige Aufgabe für Euch.', },
    {'Sprecht mit <QUESTGIVER> in <AREA>.', },
  },
  [9578] = {
    'Suche nach Galaen',
    {'Denkt Ihr oft an Eure Familie, $N? An Bord der Exodar befanden sich einige Familien, aber ich habe nur von sehr wenigen gehört, die sich nach dem Absturz wiedergefunden haben.|n|nIch suche zum Beispiel nach Spuren von meinem Mann, Galaen. Er war Techniker im Kryokern. Die Trümmer davon wurden im Westen gefunden, allerdings wimmelt es dort nur so von Blutelfen!|n|nIch muss wissen, was Galaen zugestoßen ist! Selbst die Nachricht von seinem Tod wäre noch besser als diese Ungewissheit. Mein Mann trägt den gleichen Anhänger wie ich; sie waren ein Geschenk meiner Schwester.', },
    {'Sucht nach Moraes Mann Galaen.', },
  },
  [9579] = {
    'Galaens Schicksal',
    {'Die Informationen von Morae ermöglichen es Euch nicht, den Leichnam eindeutig als den von Galaen zu identifizieren, allerdings scheint man die Kleidung bei der Suche nach Kostbarkeiten zerrissen zu haben.|n|nDie Blutelfen der Umgebung hätten bei den Wrackteilen jeglichen Gegenstand von Wert an sich genommen, einschließlich das mit Juwelen besetzte Amulett von Galaen.|n|nAuch wenn Moraes Mann den Absturz nicht überlebt hat, so wird sie mit Sicherheit dankbar sein, wenn Ihr das Amulett von den Blutelfen wiedererlangt.', },
    {'Bringt Galaens Amulett zu Morae bei der Blutwacht.', },
  },
  [9580] = {
    'Bärdarfsgüter',
    {'Seit Ihr auf der Blutmythosinsel seid, habt Ihr sicherlich nur wenig gesehen, dass sich nicht auf Grund unserer Ankunft verändert hat. Meine Ausbildung und Erfahrung haben mich gelehrt, dass sogar die Erzeugnisse einer derartigen Umgebung noch von Nutzen sein können.|n|nMit so wenigen Ressourcen müssen wir uns auf unseren Einfallsreichtum verlassen, um versorgt zu sein. Ich habe unsere Läden mit Fleisch ausgestattet, das von Bären stammt, die auf dieser Insel umherstreifen. Wenn man es richtig zubereitet, kann es bedenkenlos verzehrt werden. Solltet Ihr da draußen unterwegs sein, so helft uns doch bitte unsere Vorräte aufzufüllen.', },
    {'Bringt 8 Flanken eines alten Braunbären zu Fährtenleser Lyceon bei der Blutwacht.', },
  },
  [9581] = {
    'Von den Kristallen lernen',
    {'Willkommen bei der Blutwacht, $C. Meine hauptsächliche Sorge gilt der Verteidigung des Außenpostens, aber unsere Anführer bei der Exodar haben mir auch zahlreiche andere Pflichten überantwortet.|n|nDas Problem ist nur, dass es eigentlich zu unsicher ist, eine große Anzahl von Forschern auszusenden, wenn die Insel so gefährlich ist. Ich brauche jemanden, der für mich eine Reihe von Kristallproben von verschiedenen Stellen der Insel einsammelt.|n|nDie erste Probe muss von den von Felshetzern besetzten Schiffstrümmern kommen, die südlich des Dorfs und auf der anderen Seite der Brücke liegen.', },
    {'Benutzt die Kristallspitzhacke, um eine Kristallprobe der Absturzstelle von einem Kristall der Absturzstelle zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.', },
  },
  [9582] = {
    'Die Stärke des Einen',
    {'Als das Schiff abstürzte, wurde unsere Menagerie an den nordöstlichen Stränden dieser Insel zerstreut. Mir wurde ein Schlüssel für den Käfig eines besonders gefährlichen Exemplars anvertraut, dem Todesfelshetzer. Die Kreatur ist zwar nur leicht gepanzert, widersteht aber fast jeglicher Magie. Man muss sie mit der einfachen Kraft des Schwerts erlegen.|n|nNehmt diesen Schlüssel und befreit den Felshetzer aus seinem Gefängnis und von seiner Qual. Wir können es nicht zulassen, dass er aus dem Käfig ausbricht und der Umwelt hier noch weiteren Schaden zufügt.', },
    {'Öffnet den Felshetzerkäfig und tötet den darin befindlichen Todesfelshetzer. Kehrt dann zu Ruada in der Azurwacht auf der Azurmythosinsel zurück.', },
  },
  [9584] = {
    'Die zweite Probe',
    {'Da wir nun einen Kristall als Vergleichsgrundlage haben, benötigen wir jetzt Proben von gefährlicheren Gegenden der Insel, um das Set zu vervollständigen, das ich zur Exodar senden möchte.|n|nDie nächste Probe muss von den Kristallen kommen, die von den Blutelfen in der Umgebung des Messerwinkels, nordwestlich der Blutwacht, kontrolliert werden. Berichten zufolge verändern und ernten sie die Kristalle, um sie in einer Art magischer Apparatur zu verwenden. Versucht einen Kristall zu finden, der noch nicht in eines dieser Geräte eingebaut wurde, und entnehmt eine Probe davon.', },
    {'Benutzt die Kristallspitzhacke, um eine Veränderte Kristallprobe von einem veränderten Blutmythoskristall zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.', },
  },
  [9585] = {
    'Die letzte Probe',
    {'Ich benötige nur noch eine letzte Probe, bevor ich das Set mit den Kristallen zur Exodar schicken kann, $N. Die letzte Probe muss von der Feste der Satyrn im Nordwesten, Axxarien, kommen.|n|nIch weiß nicht genau, was mir diese Probe aufzeigen wird, aber ich bin mir sicher, dass sie Spuren der Verderbnis enthalten wird. Achtet darauf, dass Ihr eine Probe von den Kristallen entnehmt, die wie die aussehen, von denen Ihr zuvor Proben entnommen habt, ansonsten können unsere Forscher keine korrekten Vergleiche mehr anstellen.', },
    {'Benutzt die Kristallspitzhacke, um eine Axxarienkristallprobe von einem Axxarienkristall zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht.', },
  },
  [9586] = {
    'Helft Tavara',
    {'Tavara, eine unserer Kräuterkundigen, ist bei ihrer Suche nach Kräutern viel zu weit gegangen. Ich befürchte sie wurde verletzt und braucht Hilfe, aber unglücklicherweise kann ich mich nicht selbst auf die Suche nach ihr begeben.|n|nBitte findet und heilt sie, wenn nötig, $C. Sie verließ die Azurwacht in Richtung Osten und machte sich auf den Weg zu einigen heißen Quellen.', },
    {'Guvan bei der Azurwacht möchte, dass Ihr Tavara findet und ihre Wunden heilt.', },
  },
  [9587] = {
    'Düstere Neuigkeiten',
    {'Die Durchsuchung der leblosen Hülle von Vazruden dem Herold fördert einen zusammengerollten Brief zu Tage. Ein kunstvolles "I" ziert das noch intakte, blutrote Siegel. Ihr brecht das Siegel auf und was Ihr lest, beunruhigt Euch zutiefst.|n|nSicherlich würde Truppenkommandant Danath Trollbann in der Ehrenfeste gerne einen Blick auf den Brief werfen.', },
    {'Bringt den unheilvollen Brief zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel.', },
  },
  [9588] = {
    'Düstere Neuigkeiten',
    {'Die Durchsuchung der leblosen Hülle von Vazruden dem Herold fördert einen zusammengerollten Brief zu Tage. Ein kunstvolles "I" ziert das noch intakte, blutrote Siegel. Ihr brecht das Siegel auf und was Ihr lest, beunruhigt Euch zutiefst.|n|nSicherlich würde Nazgrel in Thrallmar gerne einen Blick auf den Brief werfen!', },
    {'Bringt den unheilvollen Brief zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.', },
  },
  [9589] = {
    'Blut bedeutet Leben',
    {'Ich bin mir sicher, dass dieser Brief hier für einigen Aufruhr sorgen wird. Wir glauben, etwas gegen die Erschaffung immer neuer Höllenorcs unternehmen zu können, wenn wir nur mehr über ihren Entstehungsprozess in Erfahrung bringen. Es ist schon schlimm genug, dass wir im Osten gegen die Brennende Legion kämpfen müssen.|n|nHeute ist also Euer Glückstag, $G mein Bester:meine Beste;! Ihr bekommt die Chance auf einen Spaziergang im Blutkessel, wie manche den Innenhof der Höllenfeuerzitadelle nennen. Klingt verdammt heiß!|n|nZieht los, tötet ein paar Höllenorcs und bringt Proben ihres Blutes mit zurück.|n|nFühlt Ihr Euch der Aufgabe gewachsen?', },
    {'Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel.', },
  },
  [9590] = {
    'Blut bedeutet Leben',
    {'Dieser Brief beunruhigt mich zutiefst, und das nicht nur, weil er vom Verräter persönlich verfasst wurde. Wenn wir sie besiegen wollen, ist es von größter Wichtigkeit, herauszufinden, wie sie diese neuen Höllenorcs erschaffen! Schlimm genug, dass wir die Brennende Legion bei unserer östlichen Flanke bekämpfen müssen, jetzt auch noch eine Höllenorcarmee im Westen!|n|nEs liegt jetzt an Euch, den so genannten Blutkessel im Inneren der Höllenfeuerzitadelle zu infiltrieren. Bringt einige Blutproben von den dortigen Höllenorcs mit.', },
    {'Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Zenturio Caza\'rez in Thrallmar auf der Höllenfeuerhalbinsel.', },
  },
  [9591] = {
    'Die Zähmung der Bestie',
    {'Das Erste und Einzige, was $Gein:eine:c; $C am Anfang lernt, ist das Töten. Ihr scheint nun für den nächsten Schritt bereit zu sein.|n|nDie Furbolgs der Tannenruhfeste haben uns beigebracht, wie man Wildtiere zähmt, ohne monatelang zu studieren. Sie können ein Totem in der Gestalt eines Tiers formen, was sie für kurze Zeit mit einer Kreatur dieser Art verbindet.|n|nLektion Nummer Eins: Ihr nehmt dieses Totem und wendet es auf einen Stachelkriecher an. Ihr findet dergleichen an der westlichen Küste der Insel.', },
    {'Benutzt das Zähmertotem, um einen Stachelkriecher zu bändigen. Kehrt nach gelungenem Unterfangen zu Jägerin Kella Nachtbogen zurück.', },
  },
  [9592] = {
    'Die Zähmung der Bestie',
    {'Der Kriecher war zweifellos widerborstig, aber der Grünschreiter wird Eure Beharrlichkeit mit Sicherheit auf eine noch härtere Probe stellen. Stärkere Verbündete benötigen mehr Entschlossenheit.|n|nNehmt dieses Zähmertotem und bändigt damit einen großen Grünschreiter. Ihr findet diese Kreaturen im Norden der Azurmythosinsel.', },
    {'Benutzt das Zähmertotem, um einen großen Grünschreiter zu bändigen und kehrt anschließend zu Jägerin Kella Nachtbogen zurück.', },
  },
  [9593] = {
    'Die Zähmung der Bestie',
    {'Während der Zähmung des Grünschreiters sind Euch sicherlich die großen Katzen, die man Nachtpirscher nennt, aufgefallen. Es sind rasche und tödliche Jäger... und Verbündete.|n|nNehmt dieses Zähmertotem und bändigt damit einen Nachtpirscher. Geht mit dem Nachtpirscher auf die Jagd und schützt ihn vor Angreifern. Kehrt anschließend zu mir zurück.', },
    {'Benutzt das Zähmertotem, um einen Nachtpirscher zu bändigen und kehrt anschließend zu Jägerin Kella Nachtbogen zurück.', },
  },
  [9594] = {
    'Zeichen der Legion',
    {'Das Rüstungsstück wurde aus einem tiefschwarzen Metall geschmiedet, das Licht zu absorbieren scheint. Es wirkt zwar nicht verzaubert, allerdings kommt es Euch alles andere als normal vor.|n|nSolch eine Rüstung wird nur von einer bestimmten Macht verwendet - der Brennenden Legion. Die Gegenwart der Legion kann nur bedeuten, dass sie vorhaben, die Satyrn der Insel gegen die Draenei aufzuhetzen.|n|nGeht gegen die einheimischen Satyrn vor und zeigt dieses Rüstungsstück Verteidigerin Aalesia bei der Blutwacht.', },
    {'Tötet 8 Satyrn der Nazzivus und 8 Teufelsanbeter der Nazzivus. Bringt anschließend Tzeraks Panzerplatte zu Verteidigerin Aalesia bei der Blutwacht.', },
  },
  [9595] = {
    'Kontrolle',
    {'Ihr habt Euch entschieden, als $C durchs Leben zu gehen, also müsst Ihr jetzt Kontrolle erlernen. Ungezügelte Magie ist fähig, Seelen zu verderben und Welten zu zerstören.|n|nUm all das noch besser verstehen zu können, müsst Ihr einem Wesen gegenüber treten, das der eigens ausgeübten Magie erlegen ist. Reist zu den Stränden an der nordwestlichen Küste der Azurmythosinsel und setzt Eure Magie ein, um ein paar üble Murlocs zu vernichten. Euer Magiegebrauch wird wahrscheinlich die böse Macht hervorlocken, die sich dort herumtreibt - ein Magiergeist der Quel\'dorei. Vernichtet ihn.|n|nWenn Ihr fertig seid. macht Euch auf die Suche nach Bati in der Halle des Lichts der Exodar.', },
    {'Vernichtet die Murlocs der Schlickerküste, um einen Magiergeist der Quel\'dorei zu rufen, und vernichtet ihn. Sprecht dann mit Bati in der Halle des Lichts in der Exodar.', },
  },
  [9596] = {
    'Kontrolle',
    {'Macht etwas anderes, $C!', },
    {'Beschreibung', },
  },
  [9597] = {
    nil,
    {'Hey $GKleiner:Kleine;! Tut etwas Nützliches und sprecht mit Jonathan LeCraft.', },
    {'Beschreibung', },
  },
  [9598] = {
    'Erlösung',
    {'Ich bin dafür verantwortlich, die Paladine auf den Pfad der größten Tugend zu bringen, sobald sie sich dem Weg des Lichts verschreiben und unser Volk vor den Bedrohungen verteidigen.|n|nDie Zeit ist gekommen, den ersten Schritt hin zu wahrer Tugend zu tun. Wenn Ihr einverstanden seid, gebe ich Euch das Buch der Offenbarung. Wenn Ihr es studiert, erfahrt Ihr etwas über das Licht und was von Euch erwartet wird. Wenn Ihr es versteht und tüchtig seid, werdet Ihr erfolgreich größere Fähigkeiten erlangen.', },
    {'Lest das Buch der Offenbarung und sprecht mit Jol.', },
  },
  [9599] = {
    nil,
    {'Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten lediglich danach, in allem nur Gutes zu tun.|n|nAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den anderen Bürgern unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.|n|nBedenket das und vergesst es niemals.', },
    {'Sprecht mit Jol in der Exodar.', },
  },
  [9600] = {
    'Erlösung',
    {'Es wird Eure Aufgabe sein, $N, unseren neuen Verbündeten, den Furbolgs der Tannenruhfeste, zu helfen.|n|nEinige der jüngeren Schamanen der Tannenruhfeste sind in eine Enklave der Sichelklauen gestolpert und wurden allesamt getötet. Nehmt dieses Symbol des Lebens und erweckt einen der Schamanen wieder zum Leben.|n|nDie Enklave der Sichelklauen liegt östlich der Straße, direkt nachdem man die Brücke überquert, die die Azurmythosinsel und die Blutmythosinsel verbindet. Sprecht mit mir, wenn Ihr diese Aufgabe erfüllt habt.', },
    {'Jol möchte, dass Ihr einen jungen Schamanen der Furbolgs mit dem Symbol des Lebens wieder zum Leben erweckt und dass Ihr anschließend wieder zu ihr zurückkehrt.', },
  },
  [9601] = {
    'Zum Bollwerk',
    {'Der Blutritter Mehlar Dämmerklinge hat ein Treffen mit Euch gefordert, $N. Ihr findet Mehlar beim Bollwerk, das den Übergang zwischen Tirisfal und den Westlichen Pestländern schützt.|n|nEr ist nicht gerade für seine Geduld bekannt. Ihr solltet ihn also nicht warten lassen.', },
    {'Sprecht mit Mehlar Dämmerklinge beim Bollwerk.', },
  },
  [9602] = {
    'Unheilvolle Mitteilung',
    {'Ihr müsst Euren Leuten diese Informationen überbringen, $N. Auch wenn Euer mutiger Einsatz die Pläne von Kael\'thas und seinem dunklen Meister sicherlich ins Stocken gebracht hat, werden mit Sicherheit auch weiterhin Angriffe verübt werden.|n|nNehmt die Mitteilung des Verräters zu Euren Anführern. Sie müssen es mit ihren eigenen Augen sehen. Vielleicht verstehen sie einiges von dem Geschriebenen besser.', },
    {'Bringt die Mitteilung des Verräters zu Exarch Menelaous bei der Azurwacht.', },
  },
  [9603] = {
    'Betten, Verbände und noch viel mehr',
    {'Willkommen bei der Azurwacht, $C. Bitte entschuldigt die Unordnung, die hier überall herrscht. Man betrachtet die einfachsten Dinge oft als selbstverständlich, wie zum Beispiel ein komplett eingerichtetes und ausgestattetes Gasthaus... bis man selbst ein neues aus dem Nichts errichten muss.|n|nWir konnten dieses Wrackteil bergen und für das Gebäude verwenden, allerdings ist dieses Gasthaus lediglich ein besseres Zelt, ohne die entsprechende Einrichtung und die Notvorräte. Nurguni bei der Exodar hat uns angeboten, ein paar Vorräte mit den im Moment am dringendsten benötigten Dingen zusammenzustellen. Ich brauche jedoch jemanden, der ihm diese Liste hier bringt.', },
    {'Bringt Chellans Liste zu Zaldaan, dem Hippogryphenmeister bei der Azurwacht.', },
  },
  [9604] = {
    'Auf dem Rücken eines Hippogryphen',
    {'Ihr könnt einen meiner Hippogryphen gegen ein kleines Entgelt mieten, um zur Exodar zu fliegen.|n|nEinen Hippogryphen zu nehmen, ist eine schnellere und, was noch wichtiger ist, sichere Reisemöglichkeit für jemanden, der eine wichtige Nachricht zu überbringen hat. Wenn Ihr Euch für einen Hippogryphenritt entschieden habt, sprecht einfach nochmal mit mir und ich kümmere mich um den Rest.', },
    {'Erwerbt bei Zaldaan einen Hippogryphenritt zur Exodar. Bringt Chellans Liste nach der Landung zu Nurguni im Sitz der Naaru der Exodar.', },
  },
  [9605] = {
    'Hippogryphenmeister Stephanos',
    {'Hier ist die Kiste, $N. Es sollte genug sein, damit Chellan das Gasthaus fertigstellen und eröffnen kann. Richtet ihr bitte aus, dass sie bei steigendem Bedarf jederzeit weitere Vorräte anfordern kann. Die Azurwacht braucht unbedingt einen Ort, an dem Verwundete versorgt und Reisende empfangen werden können.|n|nSucht Stephanos auf, wenn Ihr zur Azurwacht zurück möchtet, er hält sich am Sitz der Naaru in der Exodar auf.', },
    {'Geht zu Stephanos am Sitz der Naaru in der Exodar und erwerbt einen Hippogryphenritt zurück zur Azurwacht.', },
  },
  [9606] = {
    'Zurück zu Versorgerin Chellan',
    nil,
    nil,
  },
  [9607] = {
    'Im Herzen des Hasses',
    {'$C, sucht Euch sofort eine Gruppe und kundschaftet den Blutkessel im Inneren der Höllenfeuerzitadelle aus! Und ich meine heute noch Prinzesschen!|n|nUnsere magische Überwachung besagt, dass dort etwas Unnatürliches vor sich geht. Jedoch werden unsere weiteren arkanen Untersuchungen von einer großen Macht im Inneren abgeblockt. Das sagt schon alles!|n|nRechnet mit starkem Widerstand; keine andere Truppe, die wir hineingeschickt haben, ist je zurückgekehrt.|n|nGeht hinein, untersucht das gesamte Areal und meldet Euch dann beim Truppenkommandant!', },
    {'Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel.', },
  },
  [9608] = {
    'Im Herzen des Hasses',
    {'$C, sucht Euch sofort eine Gruppe und kundschaftet den Blutkessel im Inneren der Höllenfeuerzitadelle aus!|n|nUnsere magische Überwachung besagt, dass dort etwas Unnatürliches vor sich geht. Jedoch werden unsere weiteren arkanen Untersuchungen von einer großen Macht im Inneren abgeblockt, also muss es sehr wichtig sein.|n|nRechnet mit starkem Widerstand; keine andere Truppe, die wir hineingeschickt haben, ist je zurückgekehrt.|n|nGeht hinein, untersucht das gesamte Areal und meldet Euch dann bei Nazgrel, Thralls Berater.', },
    {'Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.', },
  },
  [9609] = {
    'Helft Behüter Biggs',
    {'Magtoor hat mir gesagt, dass in der Nähe ein Behüter gestrandet ist. Offensichtlich wurde die Karawane, die er von Dunkelhain ab begleitet hat, von Verirrten angegriffen. Wie es aussieht ist er der einzige Überlebende.|n|nEr ist irgendwo im Süden. Bitte, $C, helft ihm.', },
    {'Sucht Behüter Biggs in den Sümpfen des Elends.', },
  },
  [9610] = {
    '[DEPRECATED] Tränenteich',
    {'Ich interessiere mich für die Geschichte von Azeroth und frage mich, ob Ihr mir helfen möchtet.|n|nIn der Nähe im Sumpf gibt es einen Platz von historischer Bedeutung, zu dem ich Euch gerne schicken möchte. Der Tränenteich liegt im Südosten. Man sagt, dass sich an seinem Ufer und in seinen Tiefen vergrabene Artefakte der Zivilisation der Atal\'aitrolle befänden.|n|nAber seid vorsichtig, der Teich wird von Somnus, einem uralten grünen Drachen, und seinen Drachlingen sowie fleischfressenden Fischen bewacht!', },
    {'Besorgt 5 Artefakte der Atal\'ai und bringt sie zu Holaaru im Sicheren Hafen in den Sümpfen des Elends.', },
  },
  [9611] = {
    'Azurmythosinsel',
    nil,
    nil,
  },
  [9612] = {
    'Herzlichen Dank!',
    {'Ihr habt mein Leben gerettet, $N! Ich danke Euch von ganzem Herzen! Wärt Ihr nicht gewesen, hätte mich diese Bestie in Fetzen gerissen.|n|nWenn Ihr den Exarch bei der Azurwacht seht, erzählt ihm von Eurer Tat. Ich bin mir sicher, dass er diese Neuigkeit mit Freuden aufnehmen wird!', },
    {'Sprecht mit Exarch Menelaous bei der Azurwacht.', },
  },
  [9613] = {
    'Keannas Wille',
    {'<Als Ihr das Schwert berührt, Hört Ihr eine weibliche Stimme, die Euch anspricht.>|n|nAu! Lasst das! Könnt Ihr nicht sehen, dass ich zerbrochen bin? Das tut weh!|n|nWie ich sehe, seid Ihr Karazhan nicht in die Falle gegangen. Dann müsst Ihr von Kadghar und dem Violetten Auge wissen.|n|nIhr müsst jemanden finden, der mich wieder zusammenfügen kann. Koren... er war einst unser Agent... er ist in der Nähe. Ich hoffe, dass Ihr zu den Guten gehört. Wenn ja, dann kann er uns helfen!', },
    {'Die zertrümmerte Klinge, die ihr in Karazhan gefunden habt, möchte, dass Ihr Koren bittet, sie zu reparieren. Ihr müsst außerdem einen wohlwollenden Ruf beim Violetten Auge innehaben, um die Quest abzuschließen.', },
  },
  [9614] = {
    'Eine Klinge zusammenfügen',
    {'Diese Waffe wurde in so viele Stücke zerbrochen... sie wieder zusammenzufügen wird nicht einfach.|n|nIch brauche Khorium. Viel davon. Und einen Kristall der Leere sowie etwas Urfeuer.', },
    {'Bringt 40 Khoriumbarren, 1 Kristall der Leere und 8 Urfeuer zu Koren in Karazhan.', },
  },
  [9615] = {
    'Eine Klinge zusammenfügen',
    {'Diese Waffe wurde in so viele Stücke zerbrochen... sie wieder zusammenzufügen wird nicht einfach.|n|nIch brauche Khorium. Viel davon. Und einen Kristall der Leere sowie etwas Urfeuer.', },
    {'Bringt 40 Khoriumbarren, 1 Kristall der Leere und 8 Urfeuer zu Koren in Karazhan.', },
  },
  [9616] = {
    'Banditen!',
    {'Es scheint sich um ein Kopfgeldverzeichnis zu handeln. Ihr könnt die Sprache der Blutelfen zwar nicht verstehen, aber Ihr bemerkt ein Bild, das einen toten Draenei darstellt, einen grinsenden Blutelfen, der sich über dessen Körper beugt, und ein Symbol, das Eurer Meinung nach für eine Art Währung der Blutelfen steht.|n|nSie haben es auf die Draenei abgesehen! Ihr müsst den Exarch darüber informieren.', },
    {'Nehmt das Blutelfendokument zu Exarch Menelaous bei der Azurwacht.', },
  },
  [9617] = {
    'Sucht die Weltenwanderer auf',
    {'Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer hat eine Audienz mit allen fähigen Jägern gefordert. Es wäre sicher von Vorteil für Euch, wenn Ihr Euch so schnell wie möglich bei Ihr meldet, $N. Sie ist ein wahrer Quell der Weisheit für Euresgleichen.|n|nDie Zuflucht der Weltenwanderer liegt südlich von Silbermond.', },
    {'Sprecht mit Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer.', },
  },
  [9618] = {
    'Überbringen der Berichte',
    {'Eure Geschicklichkeit war äußerst beeindruckend. Es besteht kein Zweifel, ich kann Euch die Überbringung dieser Berichte an Zelanis anvertrauen.', },
    {'Bringt Keltus Dunkellaubs Berichte zu Zelanis in Silbermond.', },
  },
  [9619] = {
    'Beschwörungsrune',
    {'Der Leerstein offenbart Euch eine Vision von einem mehrstöckigen Gebäude, das von geisterhaften Figuren behaust wird. Die Szene wird schärfer und verschwimmt dann wieder, andere Gebäude kommen ins Bild, es scheint sich um den Ort Goldnebel zu handeln.|n|nHausdächer und Baumwipfel schwirren plötzlich vorbei, sie verraten Euch den Weg nach Goldnebel, der den Elrendar entlang nach Westen führt.|n|nVerwendet den Leerstein, sobald Ihr dort angekommen seid, nahe der Beschwörungsrune auf dem Hauptgebäude und bezwingt den heraufbeschworenen Leerwandler. Erst dann könnt Ihr zu Eurem Lehrer zurückkehren.', },
    {'Verwendet den Leerstein, um einen Leerwandler in Goldnebel zu beschwören. Bezwingt ihn und kehrt zu Talionia in Silbermond zurück.', },
  },
  [9620] = {
    'Das vermisste Vermessungsteam',
    {'Als wir uns hier bei der Blutwacht langsam eingerichtet hatten, schickte ich Vermessungsteams aus, die zuverlässigere Karten der Insel erstellen sollten. Meistens kamen sie wieder unversehrt mit den von uns benötigten Angaben zurück, aber das Team, das ich nach Osten zu den Ruinen entsendet hatte, wird noch immer vermisst.|n|nIch mache mir Sorgen um sie, aber leider kann ich niemanden entbehren, um ein weiteres Team nach ihnen suchen zu lassen. Findet sie, $N, und helft ihnen soweit es geht, damit sie mit ihren gesammelten Informationen wieder zurückkehren können.', },
    {'Herold Mikolaas möchte, dass Ihr das Vermessungsteam findet, das er zu den Ruinen von Loreth\'Aran entsendet hatte, und dass Ihr dem Team so gut es geht zur Seite steht.', },
  },
  [9621] = {
    'Gesandter zur Horde',
    {'Unter unseren neuen möglichen Verbündeten regen sich Zweifel über unsere Fähigkeiten. Wie könnten wir ihnen helfen, wenn sie glauben, dass wir nicht einmal mit unseren Problemen zuhause fertigwerden?|n|nDas ändert alles. Wir lassen keine Zweifel an unserer Stärke zu. Wir werden der Horde als Ebenbürtige beitreten.|n|nBringt diesen Brief zu Sylvanas, Anführerin der Verlassenen. Sie war schon immer auf unserer Seite, aber die Nachricht von Dar\'Khans Tod muss wie Musik in ihren Ohren klingen. Bereitet Euch auf eine lange Reise vor, $N. Wenn alles gut geht, wird sie Euch nach Orgrimmar schicken.', },
    {'Bringt den Brief von Lor\'themar Theron zu Fürstin Sylvanas Windläufer in Unterstadt, der Hauptstadt der Verlassenen in Tirisfal.', },
  },
  [9622] = {
    'Warnt vor der Gefahr',
    {'Die Feste ist jetzt wieder sicher und schon bald werden sich meine Leute auf den Weg zurück zu ihrem Ahnenstammsitz machen. Die Prophezeiung wurde Wirklichkeit und für die Furbolgs der Tannenruhfeste beginnt eine neue Ära des Wohlstands.|n|nIch befürchte allerdings, dass die Dunkelheit für Eure eigenen Leute eine Bedrohung darstellt. Es gibt noch immer unbeantwortete Fragen - ungesehene Visionen aus der Prophezeiung.|n|nKehrt zu Euren Anführern zurück und erzählt ihnen von all dem, was Ihr hier erlebt habt.|n|nSolltet Ihr jemals die Hilfe der Tannenruhfeste benötigen, lasst es uns einfach wissen.', },
    {'Sprecht mit Exarch Menelaous bei der Azurwacht.', },
  },
  [9623] = {
    'Reifer werden',
    {'Ihr habt in der Wildnis unserer neuen Heimat überlebt und Euch als etwas Besonderes unter den anderen hervorgetan. Ich glaube, dass Ihr nun reif genug seid, um die zu unterstützen, die an der Front der Blutmythosinsel kämpfen. Die Hand von Argus könnte $Geinen:eine; wie Euch brauchen.|n|nMeldet Euch bei Torallius dem Gruppenkommandanten. Ihr findet ihn außerhalb der Exodar bei dem Elekk. Gebt ihm diese Befehle, damit er Euch neue Aufträge auf der Blutmythosinsel erteilen kann.', },
    {'Exarch Menelaous bei der Azurwacht hat Euch gebeten, die Befehle des Exarchen zu Torallius dem Gruppenkommandanten, der außerhalb der Exodar steht, zu bringen.', },
  },
  [9624] = {
    'Lieblingsleckerli',
    {'Ich habe eine wundervolle Entdeckung gemacht, $C. In den noch unberührten Gebieten dieser Insel wächst eine außergewöhnliche Frucht, die Sandbirne genannt wird. Man findet sie am Boden nahe der Bäume.|n|nIch habe sie zum Kuchenbacken verwendet, aber wenn ich nicht Acht gebe, kommen die Elekk angelaufen und stehlen mir das Obst. Ich hatte genug eingesammelt, um mit den Tieren teilen zu können, aber mein Vorrat ist aufgebraucht und nun herrscht wieder großes Verlangen nach Kuchen. Würdet Ihr mir mit dem Sammeln der Früchte helfen, damit ich eine weitere Charge Kuchen backen kann? Ich werde teilen, ich verspreche es!', },
    {'Aonar bei Kessels Wegelager möchte, dass Ihr ihm 10 Sandbirnen bringt.', },
  },
  [9625] = {
    'Elekk sind starker Tobak',
    {'Ist er verrückt geworden? Wie kann er von mir erwarten, dass ich einen meiner wertvollen Lieblinge einem namenlosen $GJüngling:jungen Ding; wie Euch überlasse!|n|nLasst Euch etwas gesagt sein, Kindchen: Ihr werdet es nie zu einem von der Hand von Argus bringen! Ihr habt nicht das Zeug dazu!|n|nIch glaube, dieses Mal muss ich ihm seinen Willen lassen. Sprecht mit Vorkhan bei Kessels Wegelager auf der Blutmythosinsel. Folgt einfach der Straße von hier aus nach Norden und geht einfach nach Norden weiter, wenn sie abzweigt.', },
    {'Sprecht mit Vorkhan dem Elekktreiber auf der Blutmythosinsel.', },
  },
  [9626] = {
    'Ein Treffen mit dem Kriegshäuptling',
    {'Wie Ihr wisst, habe ich nichts von der Liebe zu meinem Heimatland oder seinem Volk verloren. Ich habe mit Krallen und Zähnen gekämpft, damit Silbermond am Verhandlungstisch einen Platz neben Unterstadt und Orgrimmar erhält.|n|nDies sollte sämtliche Gegenstimmen zum Schweigen bringen. Bringt diesen Brief zum Kriegshäuptling in Orgrimmar. Als Anführer der Horde hat er das letzte Wort bei der Entscheidung über die Bitte Eures Volkes.|n|nIch habe den Brief als Zeichen meiner persönlichen Bekräftigung mit meinem Siegel versehen. Geht in den Nordwesten der Stadt und steigt auf dem Turm in den Zeppelin nach Durotar.', },
    {'Fürstin Sylvanas Windläufer möchte, dass Ihr den Brief mit Sylvanas\' Siegel zum Kriegshäuptling nach Orgrimmar, Hauptstadt von Durotar, bringt.', },
  },
  [9627] = {
    'Treue gegenüber der Horde',
    {'Euer Volk litt unter dem großen Verrat der Allianz. Ihr habt darnassische Angriffe zurückgeschlagen und Spione aus Eisenschmiede ausgeschaltet. Nun gelang es Euch, vor den Toren Eurer Heimat, einen der mächtigsten Anführer der Geißel zu vernichten. Euer Wert steht außer Frage.|n|nEs ist offensichtlich, dass wir einander brauchen. Kehrt zu Lor\'themar zurück. Berichtet ihm, dass ich seine Botschaft laut und deutlich vernommen habe.|n|n<Der Kriegshäuptling zerknüllt den Brief in seiner Hand.>|n|nWillkommen in der Horde!', },
    {'Kehrt nach Silbermond zurück und erstattet Lor\'themar Theron Bericht.', },
  },
  [9628] = {
    'Bergung der Daten',
    {'Es ist zu spät, um den Kartografen beim Abschluss ihrer Mission zu helfen, aber es scheint, als hätten sie die Angaben gesammelt, nach denen Herold Mikolaas gefragt hat. Der Kristall, der ihre Vermessungsdaten beinhaltet, befand sich nicht unter ihren durchwühlten Habseligkeiten, also muss er den Naga der Hasspranken in die Hände gefallen sein.|n|nIhr wisst, dass Herold Mikolaas sehr betrübt über den Verlust des Teams sein wird, aber auch, dass er die Vermessungsdaten gerne retten würde.', },
    {'Erlangt den Vermessungsdatenkristall von den Hasspranken nahe der toten Kartografen wieder und bringt ihn zu Herold Mikolaas bei der Blutwacht.', },
  },
  [9629] = {
    'Kurz geschnappt',
    {'Die Murlocs der Schwarzschlammküste an der südwestlichen Küste sind merkwürdige Kreaturen. Oft verhalten sie sich nach keinem richtigen Verhaltensmuster und manchmal legen sie ein erstaunliches Organisationsgeschick an den Tag.|n|nIch verfolge ein paar Theorien, die belegen könnten, wie sie das zustande bringen. Bis vor Kurzem konnte ich das Ganze jedoch noch nicht untersuchen. Ich habe eine Methode entwickelt, die es mir ermöglichen wird, die für mich interessanten Murlocs im Auge zu behalten, ohne ihnen dadurch längerfristig zu schaden oder ihr natürliches Verhalten zu stören. Wenn Ihr mir bei der Anbringung der Sender behilflich sein wollt, werde ich Euch gerne für Eure Unterstützung bezahlen.', },
    {'Morae bei der Blutwacht möchte, dass Ihr 6 Späher der Schwarzschlammküste mit einem Murlocsender \'markiert\'.', },
  },
  [9630] = {
    'Medivhs Tagebuch',
    {'Euer Name spricht sich herum, $N. Ihr habt es nach Karazhan und wieder heraus geschafft - das ist mehr, als die meisten Sterblichen von sich behaupten können.|n|nIhr müsst mir einen ganz besonderen Gefallen tun. Im Rahmen unserer Forschungen hat das Violette Auge versucht, an Medivhs Tagebuch zu kommen.|n|nUnglücklicherweise kam keiner der Agenten, die wir hineingeschickt haben, wieder heraus. Wravien war der letzte, den wir geschickt haben. Sucht ihn und erkundigt Euch, ob es neue Anhaltspunkte zu diesem Tagebuch gibt.', },
    nil,
  },
  [9631] = {
    'Hilfe unter Kollegen',
    {'Es gibt da ein kleines Detail, das ich vergessen habe. Die Überreste von Medivhs Essenz in diesem kleinen Knochenfragment ist völlig ohne Leben, genauso wie Arcanagos\'.|n|nEs gibt jedoch einen Weg, sie wieder zum Leben zu erwecken. Und ich weiß auch genau, wer uns dabei helfen kann.|n|nReist nach Area 52 und zeigt Kalynna Lathred das Knochenfragment. Sie wird wissen, was damit zu tun ist.', },
    {'Bringt das verkohlte Knochenfragment zu Kalynna Lathred in Area 52 im Nethersturm.', },
  },
  [9632] = {
    'Neue Verbündete',
    {'Herold Mikolaas hat bei der Sicherung der Blutwacht äußerst löbliche Arbeit geleistet, $C, allerdings sind unsere Feinde zahlreich und unsere Ressourcen gering.|n|nUnsere Gegner kennen unsere Schwäche nur zu gut, aber sie haben dabei nicht an Eure Verbindung zu den Streitkräften der Allianz gedacht. Ich habe ein Vorstellungsschreiben für Auberdine vorbereitet, der nächstgelegenen Siedlung der Allianz, in dem ich ihnen eine Zusammenarbeit beim Kampf gegen unsere Feinde vorschlage. Nehmt das Schreiben an Euch und sucht Jägerin Kella Nachtbogen auf, sie befindet sich in der Nähe der Docks westlich der Exodar.', },
    nil,
  },
  [9633] = {
    'Der Weg nach Auberdine',
    {'Wenn Ihr am Dock wartet, werdet Ihr das Schiff sehen, das aus Auberdine von der Dunkelküste hier ankommt. Sobald alle Passagiere von Bord gegangen sind, könnt Ihr einsteigen.|n|nDas Schiff wird nach einer kurzen Fahrt in Auberdine anlegen und Ihr werdet Euer Schreiben überbringen können.|n|nAm besten bringt Ihr es zu Thundris Windwirker, er ist ein alter Freund von mir und genießt überall hohes Ansehen.', },
    {'Nehmt das Schiff in der Nähe von Jägerin Kella Nachtbogen nach Auberdine. Bringt das Vorstellungsschreiben zu Thundris Windwirker, sobald Ihr in Auberdine angekommen seid.', },
  },
  [9634] = {
    'Raubtiere aus einer anderen Welt',
    {'Eine Sache, die wir auf unseren Reisen gelernt haben, ist, dass man bei der Einführung von Wildtieren aus einer anderen Welt besonders vorsichtig sein muss. Als die Exodar abstürzte, hatte sie Exemplare verschiedenster Tierarten aus der Scherbenwelt an Bord, einschließlich eines insektenartigen Raubtiers, dem Felshetzer.|n|nBei dem Absturz starben einige der Tiere, aber viele andere überlebten und suchten in der Wildnis das Weite. Wenn wir sie nicht in Schach halten, werden sie hier auf den Inseln das natürliche Gleichgewicht von Jägern und Gejagten stören.|n|nIhr findet die Hetzer westlich von Kessels Wegelager, in der Nähe der Küste.', },
    {'Tötet 10 junge Blutfelshetzer und kehrt danach zu Vorkhan dem Elekktreiber bei Kessels Wegelager auf der Blutmythosinsel zurück.', },
  },
  [9635] = {
    'Der schockdrosselnde Partikelextraktor!',
    {'Das Sumpfgas ist wirklich erstaunlich und kann sehr nützlich sein, Mann! Aber zuerst müsst Ihr in der Lage sein, es aufzusaugen, und dazu, mein Freund, braucht Ihr einen schockdrosselnden Partikelextraktor.|n|nNun, ich könnte Euch einfach die Baupläne geben, aber erst will ich etwas dafür haben. Wie wär\'s mit ein paar Ersatzteilen? Als ich das letzte Mal nachgeschaut habe, lagen eine Menge davon bei der kaputten Dampfpumpe im Todesmoor herum, ganz im Nordosten.|n|nIch habe gehört, dass die siechenden Riesen die Teile überall in dem ausgetrockneten See verteilt haben.', },
    {'Bringt 15 Dampfpumpenteile zu Mack Dyver in Zabra\'jin in den Zangarmarschen.', },
  },
  [9636] = {
    'Der schockdrosselnde Partikelextraktor!',
    {'Habt Ihr das Sumpfgas gesehen? Ist es nicht einfach klasse?|n|nMan braucht jedoch einen schockdrosselnden Partikelextraktor, um es aufzusaugen. Ich könnte Euch die Pläne dafür geben, aber zuerst brauche ich ganz dringend ein paar Ersatzteile, um ein paar Sachen hier zu reparieren.|n|nAls ich das letzte Mal nachgeschaut habe, lagen eine Menge davon bei der Dampfpumpe im Todesmoor im Nordosten herum. Ich glaube, die siechenden Riesen haben die Pumpe kaputtgemacht.|n|nWollen wir uns gegenseitig helfen?', },
    {'Bringt 15 Dampfpumpenteile zu K. Lee Kleinkram in Telredor in den Zangarmarschen.', },
  },
  [9637] = {
    'Kalynnas Bitte',
    {'Ich habe die Kirin Tor verlassen, weil ich nach Wissen strebte, das von meinem Orden verboten wurde. Es ist mehr als ironisch, dass ich nun gebeten werde, sie mit genau diesem Wissen zu unterstützen.|n|nWenn ich Euch diesen Gefallen tun soll, dann müsst Ihr erst etwas für mich tun. Beschafft mir die beiden Folianten, nach denen ich schon so lange suche.|n|nDer erste heißt Dämmerfoliant und gehört dem orcischen Hexenmeister Nethekurse. Der zweite ist als Buch der vergessenen Namen bekannt und gehört einem Arakkoa namens Dunkelwirker Syth.', },
    {'Kalynna Lathred möchte, dass Ihr den Dämmerfolianten vom Großhexenmeister Nethekurse in den Zerschmetterten Hallen der Höllenfeuerzitadelle und das Buch der vergessenen Namen von Dunkelwirker Syth in den Sethekkhallen in Auchindoun besorgt.|n|nIhr müsst diese Quest auf dem Schwierigkeitsgrad \'Heroisch\' abschließen.', },
  },
  [9638] = {
    'In guten Händen',
    {'Hätte ich nach diesem Tagebuch suchen sollen? Das kann nicht sein... Ich erinnere mich nicht daran...|n|nAber natürlich! Ihr meint Gradav. Er war auf der Suche nach dem Buch, als ich hierher kam. Er hat es bestimmt schon gefunden, warum fragt Ihr ihn nicht einmal?|n|nIch würde Euch ja helfen... aber diese Bücher sind einfach so... interessant!', },
    {'Sprecht mit Gradav in der Bibliothek des Wächters in Karazhan.', },
  },
  [9639] = {
    nil,
    {'Tagebuch? Welches Tagebuch? Ihr meint sicher Kamsis!|n|nGeht und fragt sie danach. Ich kann mein Projekt jetzt nicht allein lassen, sonst geht meine ganze Arbeit verloren!', },
    {'Sprecht mit Kamsis in der Bibliothek des Wächters in Karazhan.', },
  },
  [9640] = {
    'Arans Schemen',
    {'Lasst mich kurz nachdenken. Das Violette Auge... Medivhs Tagebuch... Oh ja, jetzt erinnere ich mich.|n|nIch glaube, ich hatte das Tagebuch, nach dem Ihr sucht, bevor ich anfing, diese Schriftrollen zu lesen...|n|nAran... genau, Aran hat mich darum gebeten. Und das auch noch so nett. Ich musste es ihm einfach geben. Schließlich ist er Medivhs Vater, wusstet Ihr das?', },
    {'Beschafft Medivhs Tagebuch und kehrt zu Kamsis in der Bibliothek des Wächters in Karazhan zurück.', },
  },
  [9641] = {
    'Bestrahlte Kristallsplitter',
    {'Der Absturz der Exodar hat auf der Blutmythosinsel überall Stücke schädlicher Kristalle verstreut, die das Wasser und den Rest des Landes verderben.|n|nWir haben sogar schon Stücke der Kristalle im Fleisch von Tieren gefunden, die uns normalerweise als Nahrungsquelle dienen. Ich habe einen Weg gefunden, wie man die Splitter reinigen und somit in zweckmäßige Kristalle verwandeln kann. Wenn Ihr mir genug Splitter besorgt, werde ich Euch einen vollständigen Kristall im Tausch dafür geben. Bislang konnte ich die Splitter in den Körpern von Bären, Felshetzern, Faltern und Treants finden, die den verderbten Teil der Insel bewohnen.', },
    {'Verteidiger Boros bei der Blutwacht möchte, dass Ihr ihm 10 bestrahlte Kristallsplitter bringt.', },
  },
  [9642] = {
    'Mehr bestrahlte Kristallsplitter',
    nil,
    nil,
  },
  [9643] = {
    'Würgeranken',
    {'Ein guter Förster findet für jede der vorhandenen Ressourcen eine Verwendung, $C. Auch die skurrilsten Kreaturen besitzen Eigenschaften, die wir zu unserem Vorteil nutzen können.|n|nDa die Blutwacht ständig von den Sonnenfalken angegriffen wird, suchen wir nach einer Vielzahl natürlicher Verteidigungsmechanismen, die auch als Fallen dienen können. Die dornigen Ranken der Peitscher eignen sich perfekt für den Bau von Fallen, die meiner Vorstellung entsprechen. Die Kombination von scharfen Dornen und tödlichem Gift wird unachtsame Angreifer ausschalten. Bringt mir Ranken von mutierten Würgern, damit ich mit der Arbeit beginnen kann.', },
    {'Fährtenleser Lyceon bei der Blutwacht möchte, dass Ihr ihm 6 dornige Würgeranken bringt.', },
  },
  [9644] = {
    'Schrecken der Nacht',
    nil,
    nil,
  },
  [9645] = {
    'Die Terrasse des Meisters',
    {'Tagebuch? Welches Tagebuch?|n|nOh, richtig. Dieses Tagebuch! Das Violette Auge hat mich deswegen hierher geschickt. Ich erinnere mich.|n|n<Kamsis zeigt auf eine Seite im Tagebuch>|n|nDies ist die Seite, an der Alturus interessiert ist. Wusstet Ihr, dass andere Leute Tagebücher benutzen, um ihre Erinnerungen aufzuzeichnen, während Medivhs Tagebuch genau seine Erinnerungen sind?|n|nProbiert es aus. Geht zur Terrasse des Meisters und lest die Seite. Ihr werdet sehen, was ich meine. Wenn Ihr schon da seid, könnt Ihr auch gleich Alturus Bericht erstatten. Ich fürchte, ich bin hier noch eine Weile beschäftigt.', },
    {'Geht zur Terrasse des Meisters in Karazhan und lest Medivhs Tagebuch.', },
  },
  [9646] = {
    'GESUCHT: Todespranke',
    {'Auf Anweisung von Herold Mikolaas: Man wird demjenigen ein Kopfgeld von 18 Silber auszahlen, der den Beweis für den Tod des räuberischen Bären Todespranke erbringen kann.|n|nTodespranke wird als besonders gefährlich eingestuft und ist für den Tod eines Vermessungsteams an der Küste im Nordwesten der Blutwacht verantwortlich. Reisende werden angehalten, diese Gegend zu meiden.|n|n', },
    {'Bringt Todesprankes Tatze zu Herold Mikolaas bei der Blutwacht.', },
  },
  [9647] = {
    'Ausmerzen der Falter',
    {'Als wir den Faltern das erste Mal auf der Insel begegneten, zeigten sie nur wenige Anzeichen von Mutation. Als sich die Verderbnis immer weiter ausbreitete, wurden die Motten und andere Arten jedoch immer mehr verseucht.|n|nEs ist jetzt sogar soweit gekommen, dass sie fast alles, mit dem sie in Berührung kommen, beschädigen. Der Schaden wird von den Kristallsplittern, die beim Absturz der Exodar zerbrochen wurden, noch verstärkt. Uns bleibt keine andere Wahl, aber wir müssen die Motten, die das Land nördlich der Blutwacht behausen, ausmerzen.', },
    {'Fährtenleser Lyceon bei der Blutwacht möchte, dass Ihr 10 königsblaue Falter tötet.', },
  },
  [9648] = {
    'Pilzsammlung von Mac\'Aree',
    {'Habt Ihr gewusst, dass das Sammeln von Pilzen gefährlicher als der Verzehr von Pilzen ist? Pilzsammler begeben sich ins Unbekannte - dazu kommen noch die Gefahren, die in der Wildnis lauern!|n|nWas wäre das Leben ohne ein paar Wagnisse? Ich benötige Pilze für meine Sammlung. In dieser unerforschten Natur werdet Ihr vier Arten finden: Wasserstinkmorchel, Blutpilz, ruinöser Birkensporling und Teufelszapfenfungus. Sie sind einzigartig in unterschiedlichen Gebieten der Blutmythosinsel. Bringt sie mir.', },
    {'Jessera von Mac\'Aree bei der Blutwacht möchte 1 Wasserstinkmorchel, 1 Blutpilz, 1 ruinösen Birkensporling und 1 Teufelszapfenfungus.', },
  },
  [9649] = {
    'Yseras Tränen',
    {'Gut, Euch wiederzusehen, $N! Ihr wart bei meiner letzten Aufgabe sehr tüchtig. Seid Ihr vielleicht an einer weiteren interessiert?|n|nIm Nordosten liegt die Insel Drachenfels, sie beheimatet eine sehr seltene Pilzart, die unter dem Namen Yseras Träne bekannt ist - benannt nach den grünen Drachlingen, die auf dieser Insel hausen. Ich brauche nicht viele von diesen Pilzen, möchte Euch aber dennoch warnen, denn die Bewohner dieser Insel mögen keine Besucher. Gebt auf Eure Schritte Acht.', },
    {'Jessera von Mac\'Aree bei der Blutwacht möchte 2 Yseras Tränen.', },
  },
  [9650] = {
    'Magische Zunahme',
    {'Lasst uns meine magischen Eigenschaften verstärken. Das macht Sinn. Schließlich war ich, als ich noch am Leben war, eine Zauberin.|n|nNur weil man in einer Waffe gefangen ist, heißt das noch lange nicht, dass man ein Rüpel sein muss.|n|nIch möchte, dass Ihr ein paar Materialien sammelt.', },
    nil,
  },
  [9651] = {
    'Magische Zunahme',
    {'Lasst uns meine magischen Eigenschaften verstärken. Das macht Sinn. Schließlich war ich, als ich noch am Leben war, eine Zauberin.|n|nNur weil man in einer Waffe gefangen ist, heißt das noch lange nicht, dass man ein Rüpel sein muss.|n|nIch möchte, dass Ihr ein paar Materialien sammelt.', },
    nil,
  },
  [9652] = {
    'Körperliche Erweiterung',
    {'Ich hätte nichts dagegen... Wir können genauso gut das Beste aus dieser Lage machen... in meinem Fall die Tatsache, dass ich eine Waffe bin. Ich könnte einfach die beste Waffe werden, die ich sein kann.|n|nJa, lasst uns das versuchen. Einen schärferen Schliff, einen stärkeren Schwertgriff... das klingt doch gut.|n|nIch möchte, dass Ihr ein paar Dinge für mich sammelt.', },
    nil,
  },
  [9653] = {
    'Körperliche Erweiterung',
    {'Ich hätte nichts dagegen... Wir können genauso gut das Beste aus dieser Lage machen... in meinem Fall die Tatsache, dass ich eine Waffe bin. Ich könnte einfach die beste Waffe werden, die ich sein kann.|n|nJa, lasst uns das versuchen. Einen schärferen Schliff, einen stärkeren Schwertgriff... das klingt doch gut.|n|nIch möchte, dass Ihr ein paar Dinge für mich sammelt.', },
    nil,
  },
  [9654] = {
    'Eine gut abgerundete Verteidigung',
    {'Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.|n|nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.', },
    {'Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.', },
  },
  [9655] = {
    'Heilende Verstärkung',
    {'Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.|n|nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.', },
    {'Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.', },
  },
  [9656] = {
    'Sterblichkeit geht vor',
    {'Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.|n|nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.', },
    {'Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.', },
  },
  [9657] = {
    'Angriffskanalisierung',
    {'Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.|n|nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.', },
    {'Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.', },
  },
  [9658] = {
    'Angriffskanalisierung',
    {'Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.|n|nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.', },
    {'Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.', },
  },
  [9659] = {
    'Heilende Verstärkung',
    {'Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.|n|nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.', },
    {'Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.', },
  },
  [9660] = {
    'Sterblichkeit geht vor',
    {'Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.|n|nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.', },
    {'Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.', },
  },
  [9661] = {
    'Eine gut abgerundete Verteidigung',
    {'Ich hatte mich auf die Angriffsmagie spezialisiert... so viel weiß ich noch. Ich werde mein Bestes geben, um meine arkanen Kanalisierungskräfte mit Euren zu vereinen.|n|nIch werde jedoch mehr ursprüngliche Macht brauchen, als ich jetzt besitze. Die Arkananomalien, die sich in den oberen Bereichen der Bibliothek des Wächters herum treiben, gäben ausgezeichnete Ziele ab. Sammelt ihre arkanen Überreste. Wir werden viele davon brauchen.', },
    {'Keannas Erscheinung in Keannas Wille möchte, dass Ihr 20 arkane Überreste von Arkananomalien in Karazhan sammelt.', },
  },
  [9662] = {
    'Keannas Freiheit',
    {'Meine Erinnerungen... ich kann mich wieder an alles erinnern! Mein Geist fühlt sich an, als würden Puzzleteile wieder zusammengefügt.|n|nIch war eine der Ersten, die nach Karazhan geschickt wurden, um hier Nachforschungen anzustellen, nachdem sich der Ort verändert hatte. Der Dämon Malchezaar hat mich entdeckt.|n|nIch habe schnell bemerkt, dass ich für ihn kein Gegner bin. Ich könnte fühlen, wie seine Magie meine Seele einfing.|n|nIm letzten Moment habe ich einen Teil meiner Selbst, meiner Erinnerungen versteckt... an dem einzigen Ort, der mir einfiel: meine Waffe. Malchezaar hat meine Seele. Ihr müsst mir helfen, sie zurück zu bekommen!', },
    {'Besiegt Malchezaar in Karazhan während Ihr Keannas Wille angelegt habt. Keannas Erscheinung muss überleben.', },
  },
  [9663] = {
    'Der Korsallauf',
    {'Ihr kommt gerade richtig, $N. Die Aktivitäten der Blutelfen haben sich in der letzten Woche fast verdoppelt. Unsere Agenten haben uns mitgeteilt, dass die Blutelfen, die sich selbst Sonnenfalken nennen, einen baldigen Angriff auf die Azurmythosinsel planen. Ihr müsst unseren Verbündeten und Landsmännern eine Warnung zukommen lassen.|n|nWarnt den Oberhäuptling bei der Tannenruhfeste, Exarch Menelaous bei der Azurwacht und Admiral Odesyus bei Odesyus\' Ankerplatz.|n|nDie Zeit drängt, deshalb werde ich Euch meinen Elekk zur Verfügung stellen. Beeilt Euch!', },
    {'Kessel bei Kessels Wegelager möchte, dass Ihr den Oberhäuptling Tannenruh bei der Tannenruhfeste, Exarch Menelaous bei der Azurwacht und Admiral Odesyus bei Odesyus\' Ankerplatz vor der unmittelbar bevorstehenden Blutelfeninvasion warnt. Ihr habt 15 Minuten. Kehrt anschließend zu Kessel zurück. Denkt daran, dass Elekk wasserscheu sind!', },
  },
  [9664] = {
    'Mehr Befestigungen',
    {'Willkommen in den Pestländern, $N. Wie Ihr wisst, behaupten sich die Verlassenen und ihre Verbündeten entgegen all unserer Anstrengungen in den von hier aus westlich gelegenen Ländern. Die Kommandanten der Allianz haben beschlossen, dass hier im Osten neue Befestigungen errichtet werden sollen, um die Schlinge um unseren Feind noch etwas enger zu schnüren.|n|nLange seit den Tagen Lordaerons verlassene und herrenlose Türme müssen für diesen Zweck erobert und wieder aufgebaut werden. Diese Länder hier sind gefährlich, wir brauchen Eure Hilfe.', },
    {'Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den Östlichen Pestländern. Kehrt anschließend zum Abgesandten Weißbart bei der Kapelle des Hoffnungsvollen Lichts zurück.', },
  },
  [9665] = {
    'Verstärkung der Verteidigung',
    {'Agenten der Verlassenen sind hinter das Vorhaben der Allianz gekommen. Sie wollen neue Stützpunkte bei verlassenen Türmen hier in den Östlichen Pestländern einrichten.|n|nWir dürfen auf keinen Fall zulassen, dass sie sich an unserer östlichen Grenze dauerhaft festsetzen, wir müssen den Einfall der Allianz abwehren. Wir beabsichtigen sie aus jeglichen Türmen, die sie bereits besetzt haben, zu vertreiben. Dann gilt es diese Türme zu verteidigen und weitere Eroberungsversuche abzuwehren.', },
    {'Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den Östlichen Pestländern. Kehrt anschließend zum Abgesandten Gormok bei der Kapelle des Hoffnungsvollen Lichts zurück.', },
  },
  [9666] = {
    'Demonstration der Macht',
    {'Habt Ihr die Schlangenwesen gesehen? Die, die sich selbst Naga nennen?|n|n<Kessel spuckt.>|n|nSie haben es vor drei Nächten gewagt, im Schutze der Dunkelheit bis zu diesem Lager vorzudringen. Denkt nur an die Dreistigkeit dieser primitiven Biester!|n|nIhr müsst ihrem Anführer eine Botschaft überbringen, $N. Im Nordosten liegt die Hassprankenzuflucht, der Sitz von Lord Xiz. Findet ihn, tötet ihn an Ort und Stelle und treibt diesen Banner durch seinen Körper.|n|nLasst sie vor Furcht erschaudern, wann immer sie diese Standarte sehen!', },
    {'Kessel bei Kessels Wegelager auf der Blutmythosinsel möchte, dass Ihr Lord Xiz bei der Hassprankenzuflucht tötet und das Banner der Draenei durch seinen Körper stoßt.', },
  },
  [9667] = {
    'Rettet die Prinzessin der Tannenruhfeste',
    {'Helft mir, $N! Die Sichelklauen haben mich gefangen genommen und wollen mich ihren üblen Göttern opfern!|n|nDer Oberhäuptling der Sichelklauen ist in Besitz der Schlüssel für den Käfig. Damit er auftaucht, müsst Ihr die bösartigen Furbolgs der Sichelklauen töten, die in der Enklave hausen. Sie liegt zwei Lager weiter im Westen. Wenn Ihr genug von ihnen niedergestreckt habt, wird er kommen, um sich zu rächen! Tötet ihn, sobald er sich zeigt, und nehmt die Schlüssel an Euch!|n|nMein Vater wird Euch reichlich entlohnen, wenn Ihr es schafft mich zu rettet!', },
    {'Befreit die Prinzessin der Tannenruhfeste aus ihrem Käfig und sprecht anschließend mit Botschafter Frasaboo der Tannenruhfeste bei der Blutwacht.|n|nIhr müsst den Oberhäuptling der Sichelklauen töten, um an den Schlüssel für den Käfig zu gelangen.', },
  },
  [9668] = {
    'Erstattet Exarch Admetius Bericht',
    {'Ein Soldat der Hand von Argus ist vielerlei: gehorsam, mutig, intelligent und vor allem ehrenhaft. Vielleicht verfügt Ihr schon jetzt über einige dieser Züge, $C.|n|nErstattet Exarch Admetius bei der Blutwacht Bericht, wenn Ihr der Hand noch immer beitreten möchtet. Er und seine Untergebenen werden Euch weiter auf dem Weg zum Draeneisoldaten ausbilden.|n|nUnd vergesst dies nicht, $N: Ehrenhafte Personen handeln nicht immer ehrenhaft. Manchmal ist es ihnen nicht möglich.|n|nIhr findet die Blutwacht ganz einfach diese Straße entlang, in Richtung Norden.', },
    {'Sprecht mit Exarch Admetius bei der Blutwacht.', },
  },
  [9669] = {
    'Forschungsreise in den Tod',
    {'Vor etwa einer Woche war ich mit meinem Forschungsteam auf einem Erkundungstrip im Westen der Blutmythosinsel, als wir plötzlich von blutdurstigen Spinnen angegriffen wurden. Die Auswirkungen der Kristallverseuchung waren unverkennbar, da diese Spinnen extrem groß und aggressiv waren.|n|nIch schaffte es zu fliehen, aber mein Team hatte nicht so viel Glück. Wir dürfen nicht zulassen, dass andere das gleiche Schicksal ereilt. Geht nach Westen zum Goldweberpass und vernichtet die Spinnen und ihre Matriarchin Zarakh.', },
    {'Tötet 8 Mythosspinner, 8 Mythosfänger und ihre Anführerin Zarakh. Kehrt anschließend zu Achelus zurück.', },
  },
  [9670] = {
    'Sie leben! Vielleicht...',
    {'Es war ein blutiges Gemetzel, $N. Wir wurden von einer ganzen Horde dieser Spinnen aus dem Hinterhalt überrascht. Ihre Anführerin fiel unglaublich schnell über uns her und spann uns in Kokons ein.|n|nNachdem wir eingesponnen waren, begann sie neben uns Eier zu legen. Wir sollten als Futter für ihre Jungen dienen! FUTTER!|n|nIch schaffte es, mich aus dem Kokon freizuschneiden und floh. Ich möchte die anderen aber nicht zurücklassen. Allerdings konnte ich mich dem Pass bis jetzt nicht erfolgreich nähern. Würdet Ihr mir helfen?|n|nZerstört diese Kokons! Hoffentlich sind noch ein paar Mitglieder unseres Teams am Leben!', },
    {'Forscher Cornelius hat Euch darum gebeten, 5 Expeditionsforscher zu befreien.', },
  },
  [9671] = {
    'Dringende Nachricht',
    nil,
    nil,
  },
  [9672] = {
    'Das Vermächtnis des Blutfluchs',
    {'Getreuer Freund,|n|nmeine Hand zittert beim Schreiben dieses Briefs. Ich hoffe, dass er Euch rechtzeitig erreicht.|n|nLetzte Nacht erschien mir Edward Hanes, Kapitän des Schiffs VERLORENE HOFFNUNG, in meinem Zelt. Derselbe Edward Hanes, der vor 20 Jahren an Skorbut gestorben ist.|n|nDie Erscheinung erzählte mir eine Geschichte, die mein Herz erschütterte. Eine Geschichte, die Ihr hören müsst, und eine Aufgabe, die Ihr erfüllen sollt. Seid Ihr dabei? Werdet Ihr nach Edward auf der Insel Drachenfels, die nordöstlich von Eurer Basis liegt, suchen?|n|nGruß,|n|nAdmiral Odesyus', },
    {'Admiral Odesyus hat Euch gebeten, nach Kapitän Edward Hanes zu suchen und mit ihm zu sprechen.', },
  },
  [9673] = {
    'Bestienausbildung',
    {'Nachdem Ihr nun alles über die Zähmung eines Tieres wisst, ist es an der Zeit, sich mit den Feinheiten der Pflege und Ausbildung Eures Begleiters vertraut zu machen. Sucht dazu Halthenis den Tierausbilder von Silbermond auf, er wird Euch alles Nötige beibringen.|n|nEr respektiert meine Schüler in höchstem Maße, solange Ihr Euch ihm gegenüber genauso respektvoll verhaltet. Enttäuscht mich also nicht.', },
    {'Sprecht mit Halthenis in Silbermond.', },
  },
  [9674] = {
    'Die Naga des Blutfluchs',
    {'Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 10 Naga des Blutfluchs tötet.', },
    {'Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 10 Naga des Blutfluchs tötet.', },
  },
  [9675] = {
    'Bestienausbildung',
    {'Oh, da wäre noch etwas! Ihr solltet mit Ganaar bei der Exodar sprechen. Er wird Euch das letzte bisschen Wissen bezüglich der Pflege und Ausbildung Eures Begleiters lehren.|n|nIhr findet ihn in der südwestlichen Ecke der Händlertreppe.', },
    {'Sprecht mit Ganaar bei der Händlertreppe der Exodar.', },
  },
  [9676] = {
    'Ausbildung zum Paladin',
    {'Mit dem Voranschreiten in Eurer Klasse, möchtet Ihr sicherlich von der Ausbildung profitieren, die Euch der Lehrer für Eure Klasse anbieten kann. Jesthenis Sonnensturm ist der Lehrer für junge Paladine hier auf der Insel der Sonnenwanderer. Sprecht mit Jesthenis und seht, welche Ausbildung er Euch anbieten kann. Es wird Euch etwas kosten, bringt also ein wenig Geld mit Euch.|n|nEuer Lehrer - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - befindet sich im unteren Teil des Sonnenturms.', },
    {'Sprecht mit Jesthenis Sonnensturm - dem Paladinlehrer - im Sonnenturm auf der Insel der Sonnenwanderer.', },
  },
  [9677] = {
    'Aufforderung des Ritterfürsten Heldenblut',
    {'$N, Ihr habt Euch in Eurer frühen Ausbildung bereits selbst übertroffen und von den anderen, die Blutritter werden möchten, hervorgehoben. Ihr seid reif für die nächste Ausbildungsphase und dazu kommt, dass Ritterfürst Heldenblut höchstpersönlich nach Euch verlangt hat.|n|nIch zweifle nicht daran, dass Ritterfürst Heldenblut Eure Fähigkeiten und Eure Ausbildung einer Prüfung unterziehen möchte. Ihr findet ihn beim Hauptsitz der Blutritter in Silbermond beim Platz der Weltenwanderer. Alles Gute, $N.', },
    {'Sprecht mit Ritterfürst Heldenblut beim Platz der Weltenwanderer in Silbermond.', },
  },
  [9678] = {
    'Die erste Prüfung',
    {'Ihr habt viel über das Kämpfen und Vergießen von Blut gelernt, Initiand, doch in unserem Orden geht es um viel mehr.|n|nDie Beherrschung des Lichts erfordert einen klaren Geist und enorme Willenskraft.|n|nOhne diese Eigenschaften seid Ihr nicht mehr wert als ein räudiger Streuner.|n|nAn den nordöstlichen Ausläufern der Geisterlande gibt es eine Insel, die Insel des Martyriums, auf der wir diese Eigenschaften formen. Versteckt in einer kleinen Höhle, steht eine Kohlenpfanne. Kniet vor ihr, entzündet sie und konzentriert Euch auf das, was Ihr vor Euren Augen seht.', },
    {'Reist zu der Insel, die Euch Ritterfürst Heldenblut beschrieben hat, sucht die Höhle und entzündet die Kohlenpfanne. Kehrt, nachdem Ihr die erste Prüfung bestanden habt, zu Ritterfürst Heldenblut in Silbermond zurück.', },
  },
  [9679] = {
    'Rückkehr zu Ritterfürst Heldenblut',
    {'Der Angreifer ist tot, doch seine letzten Worte lassen es so erscheinen, als wäre seine Anwesenheit hier kein Zufall. Wahrscheinlich war es ein Teil der Prüfung, von der Ritterfürst Heldenblut gesprochen hatte.|n|nJetzt, wo Ihr diese Feuerprobe bestanden habt, solltet Ihr Euch auf den Rückweg nach Silbermond machen und Ritterfürst Heldenblut Bericht erstatten.', },
    {'Erstattet Ritterfürst Heldenblut in Silbermond Bericht.', },
  },
  [9680] = {
    'Die Vergangenheit aufwühlen',
    {'Kamsis hatte Recht! Diese Information ist äußerst wichtig. |n|nWenn Medivh seine eigene Essenz in die Magie, die er benutzt hat, um den Drachen zu besiegen, hineingewebt hat, dann ist es ziemlich wahrscheinlich, dass wir einen schwachen Rest dieser Essenz aus den Überresten des Drachen gewinnen können. Welch großartige Erkenntnisse mögen wohl unter der Asche des Gebirgspass der Totenwinde liegen, die nur darauf warten, entdeckt zu werden.|n|nGeht zu den Bergen südlich von Karazhan und bringt mir ein Knochenfragment deutlich drachischen Ursprungs.', },
    {'Erzmagier Alturus möchte, dass Ihr zu den Bergen südlich von Karazhan im Gebirgspass der Totenwinde geht und ein verkohltes Knochenfragment besorgt.', },
  },
  [9681] = {
    'Eine Studie der Macht',
    {'Haltet mich nicht für übermäßig grausam, $N. Stillstreich hat sehr wohl gewusst, worauf er sich einlässt. Er verstand und akzeptierte seine Pflicht und wurde so ein leuchtendes Vorbild für alle aufstrebenden Blutritter.|n|nMeine Worte sind nicht als Grabesrede gedacht, $N. Stillstreichs Dienste für uns gehören noch lange nicht der Vergangenheit an und Ihr werdet das Instrument seiner Wiederauferstehung sein.|n|nEure Ausbildung in der Kunst des Ordens hat gerade erst begonnen. Angesichts Kael\'thas\' Verrat und des Verlusts unserer Energiequelle, müsst Ihr neue Wege zur Beherrschung des Lichts erlernen. Sucht Magister Astalor Blutschwur auf.', },
    {'Sprecht mit Magister Astalor Blutschwur in der Geheimen Kammer unter dem Hauptquartier der Blutelfen.', },
  },
  [9682] = {
    'Die Hoffnungslosen...',
    {'An einem Vorsprung des Riffs, noch tiefer im Wasser als die Naga des Blutfluchs, werdet Ihr die Hoffnungslosen finden: Reisende des Blutfluchs, Geister derer, die vom Blutfluch heimgesucht wurden.|n|nEs ist bedauerlich, was ich jetzt von Euch verlangen werde... aber sie müssen vernichtet und ihre Hüllen des Blutfluchs zu mir gebracht werden.|n|nIhre Seelen müssen erlöst werden. Kehrt zu mir zurück, wenn Ihr dergleichen getan habt und ich werde Euch eine letzte Aufgabe stellen.', },
    {'Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 4 Seelen des Blutfluchs zu ihm bringt.', },
  },
  [9683] = {
    'Beendigung des Blutfluchs',
    {'Im Süden findet Ihr die Insel des Blutfluchs. Oben auf der Insel befindet sich ein Schrein, der der von den Naga geliebten Königin, Azshara, gewidmet wurde. Zerstört die Statue - verbrennt das Abbild! Dies wird mit Sicherheit den Zorn von Anführer Atoph des Blutfluchs erwecken.|n|nTötet Atoph und kehrt zu mir zurück!', },
    {'Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr die Statue der Königin Azshara zerstört und Atoph des Blutfluchs tötet.', },
  },
  [9684] = {
    'Die Beherrschung des Lichts',
    nil,
    {'Wendet das schimmernde Gefäß auf die Magister der Blutelfen an, um es zu füllen und kehrt anschließend zu Ritterfürst Heldenblut zurück.', },
  },
  [9685] = {
    'Die Erlösung der Toten',
    {'Während Ihr das Gefäß vorbereitet habt, habe ich eine Gruppe von Initianden entsandt, um Sangrias Stillstreich zu bergen. Ihr findet ihn, zusammen mit einem Ordensdiener, auf der obersten Etage des Gasthauses von Silbermond. Begebt Euch ohne Verzögerung dorthin und entfesselt die magischen Kräfte des Gefäßes, um ihn ins Leben zurückzuholen.|n|nDie Zeit drängt, $N. Sollte er zu lange tot sein, können ihn nicht einmal mehr die Mächte des Lichts retten. Kehrt nach Stillstreichs Wiederbelebung zu mir zurück.', },
    {'Bringt das gefüllte schimmernde Gefäß zum Gasthaus von Silbermond und verwendet seine Magie, um Sangrias Stillstreich wiederzubeleben.', },
  },
  [9686] = {
    'Die zweite Prüfung',
    {'Ihr steht kurz davor, innerhalb des Ordens den Status eines Adepten zu erhalten, $N. Zunächst werdet Ihr jedoch beweisen müssen, dass Ihr für eine solche Ehre schon bereit seid, indem Ihr eine weitere Prüfung absolviert.|n|nDie zweite Prüfung unterscheidet sich vor allem dadurch von der Ersten, dass Euch keine unliebsamen Überraschungen mehr erwarten. Die vor Euch liegende Aufgabe ist einfach; Ihr müsst Euch gegen die vier besten Champions der Blutritter im Kampf beweisen.|n|nSobald Ihr die Herausforderung annehmt, erscheint in der Mitte des Pavillons ein Kristall. Berührt ihn, um mit Eurer Prüfung zu beginnen und entfernt Euch niemals zu weit von dem Gebäude.|n|nSeid Ihr bereit?', },
    {'Besteht die zweite Prüfung und besiegt Champion Rachblut, Champion Lichtrend, Champion Schnellklinge und Champion Sonnensturm im Pavillon in der Nähe von Meister Kelerun Blutpein.', },
  },
  [9687] = {
    'Wiederherstellung der Heiligkeit',
    {'Es ist noch nicht lange her, da kamen die einst so friedlichen Eulkin der Umgebung an die Ufer dieser Insel. Sie kamen einer nach dem anderen, um die Knochen der gefallenen Drachen zu stehlen. Ich weiß nicht, was die Kreaturen in diese Verzweiflung getrieben hat oder warum sie die Knochen der Dahingeschiedenen wollen. Allerdings ruhen die Geister der Brut seit dieser Schändung nicht mehr.|n|nGen Westen, über die Purpurbrandung hinweg, liegt der Rachfederkamm. Reist zu den Siedlungen der Eulkin und nehmt die gestohlenen Drachenknochen wieder an Euch.', },
    {'Prinz Toreth auf der Insel Drachenfels möchte, dass Ihr 8 Drachenknochen wiedererlangt.', },
  },
  [9688] = {
    'Im Traum',
    {'Die Welpen, die Ihr auf dieser Insel seht, sind die ruhelosen Geister des grünen Drachenschwarms. Sie sind wie ich an das Land gebunden, außerstande ihre letzte Ruhestätte im Traum zu erreichen.|n|nDie Wiederbeschaffung der Knochen von den Gefallenen hat sie zwar etwas beruhigt, aber Ihr müsst noch mehr unternehmen.|n|nZerstört ihre astralen Erscheinungen. Ich kann diesen Ort erst verlassen, wenn es geschehen ist. Sie müssen erlöst werden!', },
    {'Prinz Toreth auf der Insel Drachenfels hat von Euch verlangt, dass Ihr 5 Viridianwelpen und 5 Viridianbrutlinge tötet.', },
  },
  [9689] = {
    'Messerrachen',
    {'Während der Angriffe wurden viele des schwarzen Drachenschwarms getötet. Einer von ihnen, ein Offizier von Todesschwinge selbst, sucht noch immer diesen Ort heim. Blickt Ihr in den Himmel, so könnt Ihr sein spektrales Antlitz durch die Lüfte kreisen sehen. Sein Hass ist so groß, dass er sogar den Tod übersteht.|n|nNehmt die Knochen, die Ihr bereits für mich eingesammelt habt, zu der Spitze des Berges dieser Insel und platziert sie im ewig brennenden Scheiterhaufen. Dieses Signal sollte Messerrachen herabschweben lassen. Sobald er da ist, tötet sein untotes Abbild.', },
    {'Prinz Toreth auf der Insel Drachenfels hat von Euch verlangt, dass Ihr Messerrachen tötet.', },
  },
  [9690] = {
    'Die zweite Prüfung',
    {'Initiand $N, Ihr habt hart an Euch gearbeitet, um die Macht des Lichts zu beherrschen, über die wir Dank unserer Magister verfügen. Ihr wisst nun von der Quelle unserer Fähigkeiten und alles über die Pflichten eines Blutritters.|n|nDer Zeitpunkt ist nahe, da Ihr Euch der zweiten Prüfung unterziehen werdet und Ihr um den Rang eines Adepten der Blutritter kämpfen müsst. Die Prüfung findet unter der Aufsicht von Meister Kelerun Blutpein im nördlichen Teil von Silbermond statt. Reist durch die Ruinen von Silbermond nach Norden und nehmt den östlichen Pfad, der kurz vor der Brücke abzweigt, die zur Insel der Sonnenwanderer führt.', },
    {'Meldet Euch bei Meister Kelerun Blutpein.', },
  },
  [9691] = {
    'Rückkehr nach Silbermond',
    {'Kehrt umgehend nach Silbermond zurück und berichtet Ritterfürst Heldenblut. Eure Ankunft sollte ihm alles Notwendige über den Ausgang der Prüfung mitteilen.|n|nEr wird Euch Eure weiteren Aufgaben auf dem Weg zum Adepten erläutern. Ihr könnt stolz auf Euch sein, $N. Viele versuchen sich an dieser Prüfung, doch nur die Wenigsten kehren zurück, um von ihrem Erfolg zu berichten.', },
    {'Kehrt zu Ritterfürst Heldenblut nach Silbermond zurück.', },
  },
  [9692] = {
    'Der Pfad des Adepten',
    {'Bevor ein frischgebackener Adept in die Ränge der Blutritter aufgenommen wird, muss er die Materialien beschaffen, die zum Schmieden der besonderen Waffe des Ordens benötigt werden: dem blutgehärteten Ranseur.|n|nIhr müsst Euch außerdem das Recht verdienen, das Insigne unseres Ordens zu tragen. Bei der Gründung des Ordens wurde eine begrenzte Zahl dieser Insignien geschmiedet und verteilt, jeder Adept erbt sein Insigne von einem Veteran. Euer Insigne erhaltet Ihr von einem gefallenen Ritter, der einen Angriff auf die Todesfestung anführte.|n|nIch habe Notizen vorbereitet, die Euch helfen sollen.', },
    {'Bringt Ritterfürst Heldenblut in Silbermond einen verderbten Koredelstein, eine Kiste mit blutgeschmiedeten Blöcken, etwas Blut des Hasserfüllten und ein Insigne der Blutritter.', },
  },
  [9693] = {
    'Was Argus für mich bedeutet',
    {'Was bedeutet Argus für Euch, $N? Viele Draenei erinnern sich wahrscheinlich nicht mehr an unseren Heimatplaneten oder kennen ihn überhaupt nicht. Dort trennten wir uns von den Man\'ari: unseren verdorbenen dämonischen Abbildern, die von Sargeras \'bedacht\' wurden. Sie selbst nennen sich die Eredar.|n|nEredar... dieses Wort hatte einst eine Bedeutung.|n|n<Admetius scheint das Wort förmlich zu schmecken.>|n|nWiderlich.|n|nLasst uns nicht noch mehr Zeit verschwenden. Sucht nach Verteidiger Boros, damit Ihr mit Eurer Ausbildung beginnen könnt.', },
    {'Exarch Admetius bei der Blutwacht wies Euch an, mit Verteidiger Boros zu sprechen.', },
  },
  [9694] = {
    'Blutwacht',
    {'Wie Ihr wisst, ist die Blutwacht einer von zwei Vorposten, die der Hand von Argus als Operationsbasen dienen. Ihr wart bereits bei der anderen Basis, der Azurwacht; die Dinge laufen auf der Blutmythosinsel etwas anders. Als wir hier zu Beginn ankamen, war das Land genauso wunderschön und unberührt wie auf der Azurmythosinsel. Wir nannten es sogar Silberbrise, doch nun breitet sich die Seuche über das Land aus. Was noch schlimmer ist, die Blutelfen, die wir auf der Exodar bekämpften, haben den Absturz überlebt. Somit kommen wir zu Eurem ersten Auftrag: Reist nach Nordwesten zum Messerwinkel und vernichtet alle Blutelfen, die Euch über den Weg laufen.', },
    {'Verteidiger Boros bei der Blutwacht möchte, dass Ihr 10 Spione der Sonnenfalken tötet.', },
  },
  [9695] = {
    'Die Anweisung des Sonnenkönigs',
    {'Bringt die Anweisung des Sonnenkönigs zu Verteidiger Boros bei der Blutwacht.', },
    {'Bringt die Anweisung des Sonnenkönigs zu Verteidiger Boros bei der Blutwacht.', },
  },
  [9696] = {
    'Übersetzungen...',
    {'Unsere hochrangigste Vernehmungsbeauftragte Elysia spricht fließend Thalassisch. Bringt ihr dieses Dokument, mal sehen, was sie dazu zu sagen hat.', },
    {'Bringt das Schreiben der Sonnenfalken zur Vernehmungsbeauftragten Elysia bei der Blutwacht.', },
  },
  [9697] = {
    'Behüterin Leesa\'oh',
    {'Es müssen wichtige Forschungen bezüglich der Ökologie der hiesigen Lebewesen betrieben werden, besonders bei den Sporlingen und den Sumpflords der Marschen. Und vertraut mir, wenn Ihr Euch einmal mit diesem Thema befasst habt, werdet Ihr die Arbeit faszinierend finden.|n|nSucht Behüterin Leesa\'oh im Wachposten des Cenarius im westlichen Teil der südlichen Marschen. Folgt dem Pfad nach Westen, dann werdet Ihr sie sicher finden. Sie ist manchmal etwas... übereifrig..., aber lasst Euch davon nicht abschrecken.|n|nOh, und hütet Euch vor ihrer Katze.', },
    {'Sprecht mit Behüterin Leesa\'oh im Wachposten des Cenarius in den Zangarmarschen.', },
  },
  [9698] = {
    'Audienz beim Propheten',
    {'Ihr müsst das übersetzte Dokument Velen persönlich überbringen, $N. Ich vertraue diesem verstörten Boten nicht.|n|nErklärt dem Propheten, dass die Blutelfen Verstärkung aus der Scherbenwelt erhalten und dass sie einen Spion unter den Draenei bei der Exodar haben. Velen hält sich in der Halle des Lichts in der Exodar auf.|n|nBeeilt Euch!', },
    {'Bringt das übersetzte Schreiben der Sonnenfalken zum Propheten Velen bei der Exodar.', },
  },
  [9699] = {
    'Was ist wahr?',
    {'Ich danke Euch für die rasche Zustellung, $N. Ihr erweist Euch schließlich als einer der besseren Agenten der Hand.|n|nWenn wir bloß wüssten, wem sie auf der Blutmythosinsel Bericht erstattet haben und noch wichtiger, wo dieses Sonnenportal ist... Sie scheinen es streng zu bewachen - wo immer es auch sein mag.|n|nWärt Ihr an einer Erkundungsmission interessiert?|n|nWenn ja, dann bringt diese Anordnungen zu Verteidiger Boros. Er wird Euch Euren nächsten Auftrag erteilen.', },
    {'Bringt Velens Anordnungen zu Verteidiger Boros bei der Blutwacht.', },
  },
  [9700] = {
    'Licht ins Dunkel bringen',
    {'Velen erklärt, dass falls die Blutelfen Verbindungen zwischen der Insel und der Scherbenwelt hergestellt haben, Überreste oder Anomalien rund um die geöffneten Portale zurückgelassen wurden. Ihr müsst die Insel nach Gebieten absuchen, in denen diese Anomalien vorkommen.|n|nSeid gewarnt, $N, manche dieser Anomalien sind Kreaturen aus der Leere selbst. Solltet Ihr auf Anomalien der Leere treffen, tötet sie! Erstattet mir Bericht, sobald Ihr neue Informationen ausfindig gemacht habt. Beginnt mit Eurer Suche im Norden, nahe der Warpgondel.', },
    {'Verteidiger Boros bei der Blutwacht möchte, dass Ihr die Lage des Sonnenportals ausfindig macht und 5 Anomalien der Leere tötet.', },
  },
  [9701] = {
    'Sporlinge beobachten',
    {'Wir müssen alles über die Sporlinge von Sporeggar und ihre Beziehung zu den anderen Lebewesen in der Umgebung in Erfahrung bringen. Eine Möglichkeit dazu ist die, die ich anwende: passives Beobachten und ihr Verhalten notieren.|n|nIch möchte, dass Ihr für mich nach Westen in das Pilzgeflecht geht. Untersucht die gesamte Gegend dort und berichtet mir dann davon.', },
    {'Untersucht das Pilzgeflecht in den Zangarmarschen und berichtet danach Behüterin Leesa\'oh im Wachposten des Cenarius in den Zangarmarschen von Euren Beobachtungen.', },
  },
  [9702] = {
    'Eine Frage der Fressgier',
    {'Ich habe mich schon gefragt, warum die Sumpflords die Straße überqueren, um in das Pilzgeflecht zu gelangen - sie müssen aus irgendeinem Grund am verhungern sein. Das darf nicht sein!|n|nIch meine, normalerweise würde ich mich nicht einmischen, aber wenn sie weiterhin alle Kapseln essen, werden sie die Sporlinge ausrotten!|n|nHier ist mein Plan: Ich bleibe hier und Ihr geht zum Quaggkamm im Osten und seht Euch nach nahrungstechnischen Gründen um, warum sie die Sporlinge überfallen.', },
    {'Sammelt 10 Stück liegengelassene Nahrung und kehrt dann zu Behüterin Leesa\'oh im Wachposten des Cenarius in den Zangarmarschen zurück.', },
  },
  [9703] = {
    'Der Kryokern',
    {'Wir haben noch andere, die nach Spuren suchen, die zu den Sonnenportalen führen, $N. Ihr müsst Euch jetzt auf Euren bevorstehenden Einsatz konzentrieren.|n|nBoros erhielt Berichte über eine neue Absturzstelle. Wir haben herausgefunden, dass es sich bei dieser Absturzstelle eigentlich um den Kryokern der Exodar handelt. Eine Transportkammer, in der genau solche Kapseln untergebracht sind wie die, aus denen wir Draenei im Am\'mental gekrochen sind.|n|nIn diesem Bereich werden auch Heilvorräte aufbewahrt. Geht zum Kryokern genau westlich der Blutwacht. Sucht nach Vorräten und nach Überlebenden.', },
    {'Verteidiger Kuros bei der Blutwacht möchte, dass Ihr 12 Kisten mit Heilvorräten sichert.', },
  },
  [9704] = {
    'Von den Getriebenen getötet',
    {'Es ist ein hartes Stück Arbeit, ein Kundschafter zwischen der Insel der Sonnenwanderer und dem Falkenplatz zu sein. Knappe Zeitvorgaben, lange Arbeitszeiten und noch schlimmer... die Getriebenen!|n|nDie Straße im Süden führt durch die Ruinen von Silbermond... ein Ort, an dem es nur so von Getriebenen wimmelt, die darauf warten, Euch für ein paar Manakristalle töten zu können. Ich glaube, dieses Schicksal hat unsere letzte Kundschafterin ereilt. Wir hatten sie mit einem von Eronas Päckchen entsandt.|n|nWie ich sehe, brennt Ihr bereits darauf, Euch beweisen zu können. Reist zum Dämmerweg und sucht nach Spuren unserer Kundschafterin.', },
    {'Geht nach Süden zu den Ruinen von Silbermond und haltet nach der getöteten Kundschafterin beim Dämmerweg Ausschau.', },
  },
  [9705] = {
    'Bergung des Päckchens',
    {'Ihr nehmt das Päckchen und stellt noch einmal sicher, dass es wirklich von Magistrix Erona stammt. Alarion würde es sicherlich gerne entgegennehmen.', },
    {'Kehrt mit Eronas Päckchen zu Kundschafterin Alarion zurück.', },
  },
  [9706] = {
    'Galaens Tagebuch - Das Schicksal von Verteidiger Saruan',
    {'Bringt Galaens Tagebuch zu Verteidiger Kuros bei der Blutwacht.', },
    {'Bringt Galaens Tagebuch zu Verteidiger Kuros bei der Blutwacht.', },
  },
  [9707] = {
    'Das Schmieden der Waffe',
    {'Wieder habt Ihr Euch als würdig erwiesen, ein Mitglied des Ordens zu sein. Mit großer Freude verleihe ich Euch den Rang des Adepten, $N. Prinz Kael\'thas selbst wäre stolz auf Euch.|n|nEs ist eine Ehre für uns alle, an Eurer Seite auf dem Schlachtfeld zu kämpfen. Verhaltet Euch weiterhin vorbildlich, zeigt keine Gnade oder Schwäche, verteidigt unermüdlich Euer Volk und Eure Brüder und verfeinert Eure Beherrschung des Lichts.|n|nNun holt Euch die Waffe, die Eurem neuen Rang angemessen ist.', },
    {'Bringt die Kiste mit Rohmaterialien zu Bemarrin in Silbermond.', },
  },
  [9708] = {
    'Bekannter Pilz',
    {'Ja, das ist es! Ich wusste doch, dass ich diesen Pilzstamm schon woanders in den Marschen gesehen habe!|n|nIm Norden gibt es einen Ort, der Prügelsumpf genannt wird. Komischer Name für einen Sumpf, wenn Ihr mich fragt, aber ich bin noch nie dort gewesen. Ich brauche Proben von diesen Pilzen um meine Theorie zu unterstützen.|n|nAber seid vorsichtig, $C. Ich habe gehört, dass die Oger in dieser Gegend einmarschiert sind. Ihr müsst also die Proben von ihnen besorgen. Könnte das der Grund sein, warum die Sumpflords dort nicht mehr ihre Nahrung suchen?', },
    {'Sammelt 15 Pilzproben und kehrt dann zu Behüterin Leesa\'oh im Wachposten des Cenarius in den Zangarmarschen zurück.', },
  },
  [9709] = {
    'Die Pilze zurückstehlen',
    {'$C, ich habe eine Idee. Ich möchte, dass Ihr Euch wieder nach Norden aufmacht, aber dieses Mal in das Herz des Ogergebiets!|n|nNordwestlich des Prügelsumpfs gibt es einen Ort, der Festung der Ango\'rosh genannt wird. Er befindet sich auf einer Insel jenseits einer großen Pilzbrücke. Dort lagern sie bestimmt die geernteten Pilze. Ihr könnt sie sicher überall finden, wahrscheinlich haben die Oger selbst sie sogar in den Taschen!|n|nBringt mir genügend davon, und ich werde versuchen, die Sumpflords mit einer neuen Nahrungsquelle zu versorgen.', },
    {'Sammelt 10 Kisten Pilze und kehrt dann zu Behüterin Leesa\'oh im Wachposten des Cenarius in den Zangarmarschen zurück.', },
  },
  [9710] = {
    'Der blutgehärtete Ranseur',
    {'Es ist alles vorbereitet, $N. Bald werdet Ihr eine Waffe haben, die Eurem neuen Status angemessen ist.', },
    {'Wartet, während Bemarrin Eure Waffe schmiedet.', },
  },
  [9711] = {
    'Matis der Grausame',
    nil,
    {'Verteidiger Kuros bei der Blutwacht möchte, dass Ihr Matis den Grausamen gefangen nehmt.', },
  },
  [9712] = {
    'Das thalassische Schlachtross',
    {'Ihr habt Euch im Dienste des Ordens ausgezeichnet, $N. Die Euch durch Magister Astalor und seiner Brüder gewährten Fähigkeiten, die Energien des Lichts zu beherrschen und Eurem Willen nach einzusetzen, und Euer offensichtliches Talent darin, machen Euch alle Ehre. Ihr wurdet für würdig befunden, Euer Wissen noch zu erweitern.|n|nMit dem Licht unter Eurer Kontrolle seid Ihr in der Lage, ein furchterregendes Schlachtross herbeizurufen; ein treues Reittier an Eurer Seite.|n|nDient auch weiterhin so voller Eifer und Ehre, $N, und Ihr werdet belohnt werden.', },
    {'Sprecht mit Ritterfürst Heldenblut, um zu erfahren, wie Ihr Euer thalassisches Schlachtross beschwören könnt.', },
  },
  [9714] = {
    'Bringt mir ein weiteres Gebüsch!',
    nil,
    nil,
  },
  [9715] = {
    'Bringt mir ein Gebüsch!',
    {'Wir müssen unsere Vorräte an Bluthibiskus aufstocken, die wir für viele Zwecke brauchen. Früher gab es hier dicke Büsche davon, aber seitdem der Wasserspiegel der Marschen gesunken ist, findet man ihn nur noch im Tiefensumpf und im Echsenkessel, unter dem Schlangensee.|n|nMan sagt, er sei eine Delikatesse für die Schlurfer, Sumpfriesen und die Tiefenfledermaus. Wenn Ihr uns also helfen wollt, müsst Ihr die Blumen von ihnen besorgen.', },
    {'Sammelt 5 Stück Bluthibiskus und bringt sie zu Gzhun\'tt in Sporeggar in den Zangarmarschen.', },
  },
  [9716] = {
    'Anomalie am Umbrafennsee',
    {'Wir kamen in die Scherbenwelt mit der Erwartung, hier kleine Ansammlungen von Leben zu finden. Doch was wir hier in den Zangarmarschen entdeckt haben, ist eine üppige Landschaft mit einem gedeihenden Ökosystem.|n|nUnsere ursprüngliche Einschätzung der Gegend war dennoch trügerisch. Die Wasserstände der Seen und Marschen sind seit unseren ersten Messungen stetig gesunken.|n|nDies könnte verheerende Auswirkungen auf die Flora und Fauna der Gegend haben. Geht zum Umbrafennsee südwestlich von hier und seht Euch nach möglichen Gründen für das Sinken des Wasserspiegels um.', },
    {'Untersucht den Grund für die sinkenden Wasserspiegel am Umbrafennsee. Kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.', },
  },
  [9717] = {
    'Los geht´s!',
    {'Auch wenn wir ein friedliebendes Volk sind, befinden wir uns im Krieg mit den Fungusgiganten, ob uns das gefällt oder nicht. Und es gibt ein Sprichwort bei den Sporlingen, das besagt, dass im Krieg und im Pilz alles erlaubt ist!|n|nEiner der Anführer der Fungusgiganten, Hungarfenn, pflegt seit Jahrtausenden mit Hingabe eine sehr besondere Pflanze, bekannt als die Tiefenspore. Er würde daran zerbrechen, wenn dieser Pflanze etwas zustoßen würde.|n|nReist zum Tiefensumpf im Echsenkessel und stehlt einen Dorn von ihr. Vertraut mir, er wird es bemerken.', },
    {'Besorgt einen Tiefensporendorn und bringt ihn zu T\'shu in Sporeggar in den Zangarmarschen.', },
  },
  [9718] = {
    'Der Flug der Krähe',
    {'Wir müssen genau herausfinden, wie weit reichend die Aktivität der Naga wirklich ist und entsprechend reagieren.|n|nJedes Wasservorkommen in den Zangarmarschen zu untersuchen wäre ein sehr zeitaufwändiges Unterfangen. Wenn Ihr mir gestattet, werde ich meine Magie benutzen, um Euch in eine Gestalt zu verwandeln, die Euch das Erkunden der Marschen leichter machen wird.|n|nHaltet dieses Amulett über den Balkon in meiner Nähe, wenn Ihr bereit seid. Ich werde Euch zurück in die Sicherheit führen, wenn wir fertig sind.', },
    {'Ysiel Windsänger möchte, dass Ihr das Sturmkrähenamulett benutzt, um die größeren Seen in den Zangarmarschen zu erkunden.', },
  },
  [9719] = {
    'Tötet die Mutter',
    {'Geschichtlich gesehen waren die Marschenläufer die größte Gefahr für mein Volk. Jetzt, da wir mit den Problemen mit den Fungusgiganten zu kämpfen haben, können wir uns keinen weiteren Angriff unserer alten Feinde erlauben.|n|nIhr habt Euch als fähig erwiesen, $C. Meint Ihr, Ihr könntet zum Tiefensumpf im Echsenkessel reisen und die große Mutter der Marschenläufer, die als Schattenmutter bekannt ist, auslöschen?!|n|nBringt mir ihr Gehirn als Beweis.', },
    {'Bringt das Gehirn der Schattenmutter zu Khn\'nix in Sporeggar in den Zangarmarschen.', },
  },
  [9720] = {
    'Das Gleichgewicht muss erhalten bleiben',
    {'Ich kann nicht verstehen, warum die Naga ihren eigenen Lebensraum entwässern wollen. Ich weiß aber sicher, dass wir sie aufhalten müssen.|n|nDiese Samen tragen die Wut der Erde in sich. Bringt sie zu den Dampfpumpen, die von den Naga betrieben werden, und benutzt sie bei den Steuerungen.|n|nDie Ranken, die aus den Samen wachsen, werden so dick wie Euer Arm und so stark wie Eisen sein, $N. Stellt das Gleichgewicht wieder her, das die Naga zerstört haben.', },
    {'Ysiel Windsänger möchte, dass Ihr die Eisenrankensamenkörner benutzt, um die Dampfpumpensteuerungen am Schlangensee, Umbrafennsee, Sumpflichtsee und der Lagune zu zerstören. Kehrt danach mit den übrigen Samen zu ihr in die Zuflucht des Cenarius in den Zangarmarschen zurück.', },
  },
  [9721] = {
    'Aufforderung von Lord Solanar',
    {'Eure Aufopferung für den Orden und Euer rascher Aufstieg innerhalb seiner Ränge sind nicht unbeachtet geblieben. Tatsächlich erbittet Lord Solanar Blutzorn, Lady Liadrins rechte Hand und verdienter Held, Eure Gegenwart.|n|nDas ist eine seltene Ehre, $N. Normalerweise überlässt Lord Solanar mir die Verwaltung des Ordens und das damit verbundene Tagesgeschäft, doch scheint er ein besonderes Interesse an Euch zu haben. Wartet nicht zu lange, $N.', },
    {'Sprecht mit Lord Solanar Blutzorn in Silbermond.', },
  },
  [9722] = {
    'Der Pfad des Meisters',
    {'Innerhalb meines Ordens existiert ein eingeschworener Zirkel von Eliterittern. Die Mitglieder des Zirkels repräsentieren die Hingebungsvollsten, Fähigsten und Vertrauenswürdigsten aller Blutritter, allesamt handverlesen und vereidigt durch die Ordensführung. Diese Meister sind leicht an ihrem thalassischen Schlachtross zu erkennen.|n|nJeder Kandidat, der sich um die Aufnahme in diese erlesene Gemeinschaft bewirbt, benötigt einen Fürsprecher aus den Reihen des Zirkels und muss seine Hingabe für die zentralen Grundsätze des Ordens unter Beweis stellen.|n|nIch habe beschlossen, Euch als Fürsprecher zur Seite zu stehen, sollte es Euer Wunsch sein, in die Reihen der Meister der Blutritter aufgenommen zu werden.', },
    {'Sprecht nochmals mit Lord Solanar, um seine angebotene Unterstützung für Eure Aufnahme zu akzeptieren.', },
  },
  [9723] = {
    'Eine Geste der Hingabe',
    {'Die Loyalität eines Blutritters endet nicht an der Spitze seiner Klinge, $N. Der Orden verlangt mehr von seinen Mitgliedern, als schiere Ausbildung und Kampf. Ein wahrer Ritter trägt zu allen Aktivitäten des Ordens etwas bei, selbst zu denen, die nicht offensichtlich Ruhm verheißen.|n|nDiese erste Aufgabe fordert weder Eure Kampfeskunst, noch ist sie besonders ruhmreich, doch ohne solche Tätigkeiten würde der Orden auseinander fallen. Ich werde Euch eine Liste mit Gegenständen geben, die Magister Astalor Blutschwurs Männer benötigen, um uns mit Lichtenergie für unsere Magie zu versorgen.', },
    {'Bringt 40 Einheiten Runenstoff, 6 Arkanitbarren, 10 Einheiten Sonnengras, 5 Dunkelrunen und 150 Goldstücke zu Lord Solanar in Silbermond.', },
  },
  [9724] = {
    'Warnung an den Zirkel des Cenarius',
    {'Die Expedition des Cenarius ist zu einer großen, fast selbständigen Organisation geworden. Die Vorgänge hier sind so wichtig, dass wir den Zirkel des Cenarius warnen müssen.|n|nKeine Sorge, ich werde Euch nicht bitten, zur Mondlichtung zurückzureisen. Es gibt Abgesandte des Zirkels auf der Höllenfeuerhalbinsel.', },
    {'Sprecht mit Amythiel Nebelgänger beim Posten des Cenarius auf der Höllenfeuerhalbinsel.', },
  },
  [9725] = {
    'Eine Demonstration Eurer Loyalität',
    {'Wir Blutritter haben geschworen, Quel\'Thalas zu verteidigen, $N. Dies ist ein zentraler Teil unserer Ausbildung. Unsere Feinde sind wild und unbeugsam. Einzig unsere Anstrengungen und die Unterstützung unserer Verbündeten sind der Garant für die Freiheit eines jeden Bürgers von Silbermond.|n|nIch habe einige beunruhigende Berichte über die verstärkte Präsenz der Geißel, südöstlich unserer Grenze zu den Östlichen Pestländern, erhalten. Eine Kompanie Belagerungsingenieure der Geißel, mitsamt Belagerungsgerät, scheinen sich dort für einen Angriff auf die Geisterlande zu sammeln. Auf keinen Fall dürfen sie Erfolg haben.', },
    {'Lord Solanar in Silbermond möchte, dass Ihr 3 Fleischwagen der Geißel zerstört und 15 Belagerungsingenieure der Geißel tötet.', },
  },
  [9726] = {
    'Jetzt, da wir Freunde sind...',
    {'Die Naga in der Enklave der Blutschuppen im Nordosten haben angefangen, unsere Leute umzubringen. Das können wir nicht tolerieren, $C!|n|nWir schlagen vor, dass Ihr ihnen als Beweis für unsere Freundschaft eine Lektion erteilt.', },
    {'Tötet 12 Sklaventreiber der Blutschuppen und 6 Verzauberinnen der Blutschuppen und kehrt dann zu Gzhun\'tt in Sporeggar in den Zangarmarschen zurück.', },
  },
  [9727] = {
    'Jetzt, da wir immer noch Freunde sind...',
    {'Berichten zufolge töten die Naga bei der Enklave der Blutschuppen immer noch unsere Leute. Ich dachte, Ihr hättet Euch darum gekümmert, $C!|n|nIch schlage vor, dass Ihr ihnen als Beweis für unsere andauernde Freundschaft eine Lektion erteilt.', },
    {'Tötet 12 Sklaventreiber der Blutschuppen und 6 Verzauberinnen der Blutschuppen und kehrt dann zu Gzhun\'tt in Sporeggar in den Zangarmarschen zurück.', },
  },
  [9728] = {
    'Ein herzliches Willkommen',
    {'Während die Druiden der Expedition damit beschäftigt waren die Pflanzen und Seen hier zu untersuchen, habe ich es zu meiner Aufgabe gemacht, mich mit den Feinden in dieser Umgebung auseinanderzusetzen.|n|nVom ersten Moment an, als wir die Zangarmarschen betreten haben, haben die Naga uns ohne Vorwarnung angegriffen. Wir haben unser Bestes getan, um sie fern zu halten, aber unsere Mittel sind begrenzt.|n|nIch möchte, dass Ihr zu den verschiedenen Lagern der Naga in den Zangarmarschen geht und ihnen zeigt, dass man sich besser nicht mit uns anlegt. Bringt mir ihre Klauen als Beweis Eurer Siege.', },
    {'Bringt 30 Nagaklauen zu Aufseher Hamuht in der Zuflucht des Cenarius.', },
  },
  [9729] = {
    'Fhwoor zerschmettern!',
    {'Kleine Naga machen Fhwoor wütend! Sporlinge gute Freunde von Fhwoor, darum Fhwoor holt Lade von Naga.|n|nWir gehen in nahes Nagadorf. Du helfen?', },
    {'Begleitet Fwoohr in das Gebiet bei der Dampfpumpe am Sumpflichtsee, um die Lade von Ssslith zu holen. Bringt Fhwoor und die Lade sicher zurück und meldet Euch bei Gzhun\'tt in Sporeggar in den Zangarmarschen.', },
  },
  [9730] = {
    'Anführer der Dunkelkämme',
    {'Hiermit wird von der Expedition des Cenarius ein Kopfgeld auf Rajah Haghazed, Anführer der Dunkelkämme, ausgesetzt. Haghazed wurde zuletzt von den Spähern des Cenarius südlich der Lagune gesichtet, mitten im Süden der Zangarmarschen.|n|nDie Dunkelkämme werden mit einer Reihe von Angriffen auf die Expedition des Cenarius in Verbindung gebracht, und ihr Anführer gilt als sehr gefährlich.|n|nDas Kopfgeld kann bei Aufseher Hamuht eingefordert werden.', },
    {'Tötet Rajah Haghazed bei der Lagune und kehrt danach zu Aufseher Hamuht bei der Expedition des Cenarius in den Zangarmarschen zurück, um eine Belohnung zu erhalten.', },
  },
  [9731] = {
    'Kanalisationspläne',
    {'Die Pläne, die Ihr bekommen habt, zeigen ein unterirdisches System von Rohren und Pumpen, die die Seen in der Umgebung mit dem Schlangensee verbinden.|n|nWenn die Pläne korrekt sind, muss es einen riesigen Ablauf am Grund des Schlangensees geben. Bestätigt dies und bringt die Neuigkeiten zur Zuflucht des Cenarius.', },
    nil,
  },
  [9732] = {
    'Rückkehr in die Marschen',
    {'Kehrt zu Ysiel zurück und gebt ihr Bescheid, dass sie so bald wie möglich weitere Hilfe erhalten wird.|n|nUnsere Mitglieder waren bis jetzt mit Angelegenheiten in der Mondlichtung und in Silithus beschäftigt, aber wir werden unser bestes tun, um die notwendigen Mittel zur Zuflucht des Cenarius zu schicken.', },
    {'Kehrt zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.', },
  },
  [9733] = {
    'Warnung an den Zirkel des Cenarius',
    {'Die Expedition des Cenarius ist zu einer großen, fast selbständigen Organisation geworden. Die Vorgänge hier sind so wichtig, dass wir den Zirkel des Cenarius warnen müssen.|n|nKeine Sorge, ich werde Euch nicht bitten, zur Mondlichtung zurückzureisen. Es gibt Abgesandte des Zirkels auf der Höllenfeuerhalbinsel.', },
    {'Sprecht mit Mahuram Starkhuf in Thrallmar auf der Höllenfeuerhalbinsel.', },
  },
  [9734] = {
    'Rückkehr in die Marschen',
    {'Kehrt zu Ysiel zurück und gebt ihr Bescheid, dass sie so bald wie möglich weitere Hilfe erhalten wird.|n|nUnsere Mitglieder waren bis jetzt mit Angelegenheiten in der Mondlichtung und in Silithus beschäftigt, aber wir werden unser bestes tun, um die notwendigen Mittel zur Zuflucht des Cenarius zu schicken.', },
    {'Kehrt zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.', },
  },
  [9735] = {
    'Wahre Meister des Lichts',
    {'Ein Meister der Blutritter besitzt unglaubliche Fähigkeiten das Licht auf eine Art zu nutzen und zu formen, wie es die sogenannten anderen \'Paladine\' nie verstehen werden. Das hält sie jedoch nicht davon ab, uns dafür zu ächten, wie wir das wahre Potenzial des Lichts entfesseln.|n|nWir müssen ihnen klar machen, dass man mit unseresgleichen keine Spielchen spielt. Was ich mir vorgestellt habe, ist keine schnelle Angelegenheit und auch nicht einfach, doch wenn Ihr Euch dieser Aufgabe verpflichtet, wird es Euer erstes Ziel sein, den Bibliotheksflügel der Abtei von Tyrs Hand zu infiltrieren und eine Phiole heiligen Wassers von Tyrs Hand an Euch zu bringen.', },
    {'Bringt Lord Solanar in Silbermond eine Phiole heiligen Wassers von Tyrs Hand.', },
  },
  [9736] = {
    'Wahre Meister des Lichts',
    {'Jetzt, da wir das Wasser haben, benötigen wir eine Reihe von Zutaten in genau abgestimmten Mengen. Einige dieser Substanzen sind äußerst selten und wertvoll, $N, doch ich habe Quellen für zwei von ihnen ausfindig gemacht.|n|nIhr solltet einige arkane Katalysatoren bei Zalle, dem Reagenzienverkäufer in einem der Geschäfte auf dem Platz nahe der Todesschneise, bekommen. Darlia, die Giftlieferantin nahe den Schurkenausbildern in der Mördergasse, sollte über einen Vorrat an krepuskularem Pulver verfügen.|n|nUm meine Mixtur zu vervollständigen, benötige ich außerdem noch einen azerothischen Diamanten und einen makellosen schwarzen Diamanten.', },
    {'Bringt Lord Solanar in Silbermond 1 arkanen Katalysator, 1 Einheit krepuskulares Pulver, 1 azerothischen Diamanten und 1 makellosen schwarzen Diamanten.', },
  },
  [9737] = {
    'Wahre Meister des Lichts',
    {'Der einzig wahre Weg, das Licht zu nutzen, ist der unsrige, $N. Um denen, die sich schändlicherweise \'Paladine\' nennen, die Torheit ihrer Tradition zu verdeutlichen, habe ich vor, ihnen eine unmissverständliche Nachricht zukommen zu lassen.|n|nDie Alonsuskapelle, der Ort, an dem der Orden der Silbernen Hand seinen Anfang nahm, scheint gegen die Zerstörung in Stratholme immun zu sein. Die ewige Flamme der Kapelle gewährt ihr den Schutz des Lichts, doch wenn Ihr sie mit der Löschmischung erstickt, ist es aus mit dem Schutz. Die Kapelle wird brennen und die Welt wird unsere Vorherrschaft über das Licht anerkennen müssen.', },
    {'Verwendet die Löschmischung in der Nähe der ewigen Flamme in der Alonsuskapelle, um den Schutz des Lichts zu brechen. Seid bereit, jeden zu töten, der versucht, die Kapelle zu verteidigen.', },
  },
  [9738] = {
    'Bei der Arbeit verschollen',
    {'Ihr müsst mir helfen! Wir wurden von Ysiel hierher geschickt, um das Geheimnis der Dampfpumpen zu erkunden und herauszufinden, warum mit ihrer Hilfe das Wasser aus den Marschen gepumpt wird. Aber meine Freunde haben sich von mir getrennt und sind einfach ohne mich weitergegangen.|n|nDie vier können manchmal solche Dummköpfe sein! Aber ich mag sie trotzdem.|n|nDeshalb müsst Ihr mir helfen herauszufinden, was aus ihnen geworden ist, denn ich befürchte das Schlimmste. Sucht sie in den Sklavenunterkünften und im Tiefensumpf.|n|nVielen Dank, $C.', },
    {'Findet heraus, was mit Erdbinder Rayge, Naturalist Biss, Jäter Gründaum und Windrufer Klaue geschehen ist. Kehrt dann zu Behüterin Jhang im Echsenkessel in den Zangarmarschen zurück.', },
  },
  [9739] = {
    'Die Misere der Sporlinge',
    {'Ihr da! Ihr müsst uns helfen!|n|nDie Sumpflords fressen all unsere Sporenbeutel! Ihr müsst etwas tun, sonst verlieren wir unsere Jungen!|n|nDie Sporenbeutel sind zu Anfang ganz groß und werden dann kleiner, wenn die Luft darin verbraucht ist. Haltet nach den kleinen, reifen Sporenbeuteln Ausschau und rettet so viele Ihr nur könnt!', },
    {'Fahssn im Pilzgeflecht möchte, dass Ihr 10 reife Sporenbeutel sammelt.', },
  },
  [9740] = {
    'Das Sonnentor',
    {'Dank Euch und Eurer Bemühungen konnten meine Späher das Sonnentor ausfindig machen. Die Elfen sorgen dafür, dass der Standort des Portals stets mobil bleibt und jederzeit verändert werden kann. Deshalb war die Stelle, die Ihr untersucht habt, auch verlassen.|n|nDie Stärke eines solchen Systems ist ebenfalls seine größte Schwäche. Das Sonnentor wird von Portalaufsehern aufrechterhalten. Wenn es uns gelingt, die Aufseher auszuschalten, werden wir das Portal zerstören können. Der momentane Standort des Sonnentors liegt westlich von hier, südlich der Vektorspule. Findet und zerstört es!', },
    {'Verteidiger Aesom bei der Blutwacht möchte, dass Ihr das Sonnentor zerstört.', },
  },
  [9741] = {
    'Geschöpfe aus der Leere',
    {'Aesom hat meine Truppe vor ein paar Tagen auf eine Erkundungsmission geschickt, um nach dem Sonnentor zu suchen. Natürlich haben wir es gefunden...|n|n<Loryi zeigt auf Jorli.>|n|nWas auch immer die Elfen durch dieses Portal transportieren, es sorgt dafür, dass Energien der Leere freigesetzt werden. Die Gegend füllt sich mit Geschöpfen der Leere. |n|nWir müssen sie vernichten, bevor sie sich in Anomalien der Leere verwandeln. Ihr findet die Geschöpfe südwestlich von hier, nahe des Sonnentors. Tötet sie und erstattet Aesom Bericht, sobald Eure Arbeit getan ist.', },
    {'Tötet 12 Geschöpfe der Leere und erstattet Verteidiger Aesom bei der Blutwacht Bericht.', },
  },
  [9742] = {
    'Noch ein paar Sporensäcke',
    nil,
    nil,
  },
  [9743] = {
    'Natürliche Feinde',
    {'Wir Sporlinge kamen noch nie gut mit den Sumpflords aus. In der Vergangenheit haben wir sie mit Speeren und Steinen erfolgreich fernhalten können. Aber in der letzten Zeit scheinen sie aggressiver geworden zu sein... oder verzweifelter. Sie haben keine Angst vor uns oder unseren Waffen.|n|nIhr seid viel Furcht einflößender und besser bewaffnet als wir. Wenn Ihr die Sumpflords für uns bekämpfen könntet, stünden wir für immer in Eurer Schuld! Bringt mir ihre Ranken, damit ich weiß, wie viele Ihr getötet habt.', },
    {'Bringt 6 Sumpflordranken zu Fahssn im Pilzgeflecht in den Zangarmarschen.', },
  },
  [9744] = {
    'Mehr Ranken!',
    nil,
    nil,
  },
  [9745] = {
    '<DEPRECATED>Die Flamme niederhalten',
    nil,
    nil,
  },
  [9746] = {
    'Grenze der Erschöpfung',
    {'Der Sieg ist zum Greifen nah, $N. Jetzt, da wir das Sonnentor entdeckt haben, wird es nicht lange dauern, bis ihre Versorgungszufuhr total unterbrochen ist. Es ist an der Zeit ihre Zahl auszudünnen.|n|nIm Westen könnt Ihr zahlreiche Lager der Sonnenfalken finden. Die Pyromanten und Verteidiger der Sonnenfalken belagern den größten Teil der Gegend. Findet sie, tötet sie und kehrt zu mir zurück.', },
    {'Verteidiger Aesom bei der Blutwacht möchte, dass Ihr 10 Pyromanten der Sonnenfalken und 10 Verteidiger der Sonnenfalken tötet.', },
  },
  [9747] = {
    'Der Umbrafennstamm',
    {'Die Naga sind furchtbar, ja. Aber noch schlimmer sind die verräterischen Stämme der Zerschlagenen und der Verirrten, die ihnen geholfen haben!|n|nDie schlimmsten von allen sind die Verirrten des Umbrafennstamms. Sie benutzen dunkle Magie, um andere zu fangen und zu versklaven. Sie sind besonders grausam zu entflohenen Sklaven und würden mir die Kehle durchschneiden, wenn ich die Zuflucht auch nur für einen Tag verlassen würde.|n|nReist nach Umbrafenn im Süden und tötet sie und ihren Anführer, Kataru. Bis dahin werde ich jeden Tag um mein Leben bangen.', },
    {'Ikeyen in der Zuflucht des Cenarius möchte, dass Ihr nach Umbrafenn reist und Kataru, 8 Seher von Umbrafenn, 6 Hexendoktoren von Umbrafenn und 6 Orakel von Umbrafenn tötet.', },
  },
  [9748] = {
    'Trinkt nicht das Wasser',
    {'Unser Schamane bekundet, dass die Wasserelemente durch die Verschmutzung der Wasserquelle sehr stark aus dem Gleichgewicht geraten sind. Wir wissen, dass der Kraftkern der Exodar im westlich gelegenen Berg liegt. Offenbar entweicht von dort eine flüchtige Substanz in die Wasserzufuhr! Ihr müsst für mich mehr Informationen sammeln.|n|n<Aesom deutet auf einen Behälter und nickt.>|n|nNehmt diesen Behälter und folgt dem Strand Richtung Norden bis Ihr auf den Punkt trefft, an dem die Flüsse der Blutmythosinsel in das Meer fließen. Entnehmt an dieser Stelle eine Probe und kehrt zu mir zurück.', },
    {'Verteidiger Aesom bei der Blutwacht möchte, dass Ihr den Wasserprobenbehälter verwendet, um eine Wasserprobe der Blutmythosinsel zu entnehmen.', },
  },
  [9749] = {
    'Sie leben! Vielleicht...',
    {'Es war ein blutiges Gemetzel, $N. Wir wurden von einer ganzen Horde dieser Spinnen aus dem Hinterhalt überrascht. Ihre Anführerin fiel unglaublich schnell über uns her und spann uns in Kokons ein.|n|nNachdem wir eingesponnen waren, begann sie neben uns Eier zu legen. Wir sollten als Futter für ihre Jungen dienen! FUTTER!|n|nIch schaffte es, mich aus dem Kokon freizuschneiden und floh. Ich möchte die anderen aber nicht zurücklassen. Allerdings konnte ich mich dem Pass bis jetzt nicht erfolgreich nähern. Würdet Ihr mir helfen?|n|nZerstört diese Kokons! Hoffentlich sind noch ein paar Mitglieder unseres Teams am Leben!', },
    {'Forscher Cornelius hat Euch darum gebeten, 5 Expeditionsforscher zu befreien.', },
  },
  [9750] = {
    'Dringende Nachricht',
    nil,
    nil,
  },
  [9751] = {
    'Das Vermächtnis des Blutfluchs',
    {'Letzte Nacht erschien mir Edward Hanes, Kapitän des Schiffs VERLORENE HOFFNUNG, in meinem Zelt. Derselbe Edward Hanes, der vor 20 Jahren an Skorbut gestorben ist.|n|nDie Erscheinung erzählte mir eine Geschichte, die mein Herz erschütterte. Eine Geschichte, die Ihr hören müsst, und eine Aufgabe, die Ihr erfüllen sollt. Seid Ihr dabei? Werdet Ihr nach Edward auf der Insel Drachenfels, die nordöstlich der Blutwacht liegt, suchen?', },
    {'Admiral Odesyus hat Euch gebeten, nach Kapitän Edward Hanes zu suchen und mit ihm zu sprechen.', },
  },
  [9752] = {
    'Flucht aus Umbrafenn',
    {'Ihr müsst mir helfen hier rauszukommen!|n|nIch habe in der Nähe Kräuter gesammelt, als ein paar dieser Wilden mich entführten. Ich habe versucht mich loszureißen, aber es waren zu viele.|n|nHelft mir zurück zur Zuflucht des Cenarius und weg von diesen grausamen Schuften und ihrer bösen Magie zu gelangen!', },
    {'Begleitet Kayra Langmähne zur Zuflucht des Cenarius in den Zangarmarschen. Gebt Ysiel Windsänger Bescheid, sobald Ihr diese Aufgabe erledigt habt.', },
  },
  [9753] = {
    'Was wir wissen...',
    {'Wir haben in den vergangenen Tagen viel über unsere Feinde gelernt. Die Blutelfen werden von einer gewissen Sironas angeführt und haben vor, uns zu zerstören. Letztendlich wollen sie noch O\'ros versklaven und wieder die Kontrolle über die Exodar gewinnen.|n|nDem Licht sei Dank, konnten wir ihre Versorgungszufuhr abschneiden, indem wir das Sonnentor zerstörten. Sie verwenden jedoch die Verunreinigung der Vektorspule, um das Land zu vergiften, und nutzen somit dessen mutagene Eigenschaften zu ihrem Vorteil.|n|nAdmetius hat auf Grund dieser Informationen einen Plan ausgeklügelt. Geht zu ihm.', },
    {'Sprecht mit Exarch Admetius bei der Blutwacht.', },
  },
  [9756] = {
    'Was wir nicht wissen...',
    {'Unsere Vernehmungsversuche sind kläglich gescheitert, $N. Folter kommt - natürlich - nicht in Frage. Was wir brauchen, ist $Gein:eine:r; $R, $Gder:die:r; an ihn herankommen kann.|n|nIch kann einen Zauber auf Euch wirken, der Euch wie $Geinen Blutelfen:eine Blutelfe; aussehen lässt und Eure Sprache anpasst. Mit dieser List werden wir vielleicht die benötigten Informationen von dem gefangenen Agenten bekommen.|n|nIch möchte, dass Ihr Euch mithilfe dieser Verkleidung das Wissen des Gefangenen erschleicht.|n|nUnd $N, verlasst die Blutwacht nicht, solange Ihr verkleidet seid, da sonst der Zauber aufgehoben wird.', },
    {'Sprecht mit einem gefangenen Agenten der Sonnenfalken bei der Blutwacht und eignet Euch Informationen der Sonnenfalken an. Kehrt zu Admetius zurück, sobald Ihr Eure Aufgabe erfüllt habt.', },
  },
  [9757] = {
    'Sucht Jägerin Kella Nachtbogen auf',
    {'Jägerin Kella Nachtbogen hat um eine Audienz mit allen qualifizierten Jägern gebeten. Sie lehrt das Zähmen von wilden Tieren, etwas, das Ihr vor allem anderen zum jetzigen Zeitpunkt Eurer Ausbildung lernen solltet.|n|nIhr findet Kella in der Nähe von Valaars Steg, den Docks westlich der Exodar.', },
    {'Sprecht mit Jägerin Kella Nachtbogen nahe Valaars Steg.', },
  },
  [9758] = {
    'Rückkehr zu Arkanist Vandril',
    {'Nun, $Gmein Freund:meine Freundin;, wenn Ihr so nett wärt, zu Arkanist Vandril zurückzukehren? Ich weiß, er ist begierig, Euch auf Eure erste Mission hier in den Geisterlanden zu senden.|n|nWir zählen auf Euch, $N. Enttäuscht uns nicht.', },
    {'Kehrt zu Arkanist Vandril in Tristessa in den Geisterlanden zurück.', },
  },
  [9759] = {
    'Ihre Welt enden lassen',
    {'Nehmt diesen Auftrag nicht an, wenn Euch etwas an Eurem Leben liegt. Seht Ihr den gigantischen Kraftkern, der aus der Seite des Bergs dort drüben hervorragt? Wer auch immer diese Last auf sich nehmen möchte, muss sich seinen Weg durch den Berg kämpfen und eine Armee der Sonnenfalken abwehren, um mich zu beschützen, während ich die Zerstörung des Kerns vorbereite. Sironas der Eredar ist auch irgendwo dort oben.|n|nIch werde Euch nicht weniger schätzen, wenn Ihr jetzt einfach geht, $N.|n|nVielleicht seid Ihr aber genau die Person, die die Vektorspule zerstören und Sironas zu Fall bringen kann. Seid Ihr es?', },
    {'Folgt und beschützt Demolierer Legoso, während er versucht, die Vektorspule zu zerstören und tötet Sironas. Kehrt zu Exarch Admetius bei der Blutwacht zurück, sobald Ihr Eure Aufgabe erfüllt habt.', },
  },
  [9760] = {
    'Verteidigers Ruh\'',
    {'Sprecht mit Verteidigerin Corin bei Verteidigers Ruh\' auf der Blutmythosinsel.', },
    {'Sprecht mit Verteidigerin Corin bei Verteidigers Ruh\' auf der Blutmythosinsel.', },
  },
  [9761] = {
    'Den Weg frei machen',
    {'Nur die wirklich Kampferprobten, Edelmütigen und Furchtlosen werden sich Legosos Auftrag stellen. Der Exarch wird keinen Agenten der Hand damit beauftragen, die Vektorspule zu zerstören und Sironas zu stürzen. Er lehnt es ab, Draenei in ihren Tod zu schicken - genau darum geht es bei diesem Auftrag: Selbstmord...|n|n<Corin seufzt.>|n|nIch bin dafür verantwortlich, die Verteidigung der Sonnenfalken zu schwächen. Eure Aufgabe besteht darin, Sonnenfalken nahe der Vektorspule zu töten und somit den Weg für unseren Helden frei zu machen - wer immer es auch sein mag.', },
    {'Verteidigerin Corin bei Verteidigers Ruh\' möchte, dass Ihr 8 Saboteure der Sonnenfalken und 8 Agenten der Sonnenfalken tötet.', },
  },
  [9762] = {
    'Die ungeschriebene Prophezeiung',
    nil,
    nil,
  },
  [9763] = {
    'Das Versteck des Kriegsherren',
    {'Es hat Vorteile, sich heimlich am Eingang zum Versteck des Feindes zu verstecken.|n|nVor ein paar Stunden sah ich eine Gruppe von Naga durch den steinernen Torbogen am zweiten Tunnel von links gehen. Ich bin in ihrer Sprache nicht sehr bewandert, aber ein Wort habe ich sehr deutlich verstanden: Kalithresh.|n|nDas muss der Eingang zu den Dampfkammern sein, von denen aus Kriegsherr Kalithresh seine Truppen befehligt. Ihr müsst ihn finden und aufhalten! Ich bin leider zu schwach, um Euch dabei helfen zu können.', },
    {'Behüterin Jhang möchte, dass Ihr Kriegsherr Kalithresh im Echsenkessel findet und tötet.', },
  },
  [9764] = {
    'Befehle von Lady Vashj',
    {'Dieser Brief enthält genaue Anweisungen für die Naga des Echsenkessels, die die Dampfpumpen bedienen. Er enthält eine Warnung vor der Ankunft von Druiden des Cenarius in dem Gebiet und die Anweisung, sie unverzüglich zu töten. Die Geschwindigkeit, mit der das Wasser aus den Seen in den Echsenkessel abgepumpt wird, soll verdoppelt werden. Die Befehle tragen das Siegel der berüchtigten Lady Vashj.|n|nDieser Brief dürfte die Druiden der Expedition des Cenarius sehr interessieren. Bringt ihn zur Leiterin der Expedition, Ysiel Windsänger.', },
    {'Bringt die Befehle von Lady Vashj zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen.', },
  },
  [9765] = {
    'Kriegsvorbereitungen',
    {'Die Expedition des Cenarius fing einst als friedliches Projekt an, doch nun stehen wir am Rande eines ausgewachsenen Kriegs gegen die Naga.|n|nUnter uns sind einige, die zwar gerne kämpfen würden, aber nur sehr schlecht ausgerüstet sind. Bringt mir die Waffen der Naga, damit wir sie zu Gleven und Pfeilspitzen umschmelzen können.|n|nNur Waffen aus hochwertigem Material können für uns nützlich sein, $N. Ihr werdet die der Naga im Echsenkessel stehlen müssen.', },
    {'Besorgt die Waffen des Echsenkessels von den Naga im Echsenkessel und kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück.', },
  },
  [9766] = {
    'Waffen des Echsenkessels',
    nil,
    nil,
  },
  [9767] = {
    'Den Feind kennen',
    {'Um einen Feind zu besiegen braucht man weit mehr als eine Überzahl an Männern oder Kraft. Oft hängt der Sieg davon ab, ob man die Schwächen des Feindes oder seine typischen Vorgehensweisen kennt.|n|nWir wissen zwar viel über die Naga, aber ihre Magie bleibt uns immer noch fremd.|n|nIch habe vor, mich mit der Hydromantie der Naga des Echsenkessels auseinanderzusetzen. Bringt mir eines ihrer Zauberbücher, damit ich mehr darüber erfahren kann.', },
    {'Besorgt ein Zauberbuch des Echsenkessels von den Naga im Echsenkessel und bringt es zu Ashyen in der Zuflucht des Cenarius in den Zangarmarschen.', },
  },
  [9768] = {
    'Zauberbücher des Echsenkessels',
    nil,
    nil,
  },
  [9769] = {
    'Mode kann man nicht erklären',
    {'<Magasha kichert still in sich hinein.>|n|nIch wette, wenn sie wüssten, dass sie Insektenteile anhaben, wäre der Trend schnell vorbei.|n|nZuerst haben wir angefangen, die Insekten in der Umgebung zu töten, weil sie bei den Bauarbeiten im Weg waren. Eines Tages kam ein geschäftstüchtiger Händler hierher, blieb über Nacht und plötzlich fing er an alle Insektenflügel, die er bekommen konnte, aufzukaufen!|n|nSagte, er mache Kleidung daraus. Ich bleib lieber bei meiner Rüstung, danke. Aber wenn Ihr die Flügel der Glühwürmchenarten in der Umgebung sammelt, kaufe ich sie Euch gerne ab.', },
    {'Bringt 8 lichtdurchlässige Flügel von einer beliebigen Glühwürmchenart der Zangarmarschen zu Magasha im Sumpfrattenposten.', },
  },
  [9770] = {
    'Bedrohliche Marschenfänge',
    {'Manchmal wünschte ich, Denjai hätte uns einen Schamanen mitgeschickt oder uns wenigstens ein Totem gegeben, um die Marschfangreißer fernzuhalten.|n|nEs wimmelt hier nur so von diesem Ungeziefer! Das ist doch nicht gerecht. Sollte nicht irgendwas diese widerlichen Käfer auffressen?|n|nWir haben alle schon abwechselnd Kammerjäger gespielt. Ihr seid genau zur richtigen Zeit gekommen, $N. Glückwunsch! Und jetzt geht los und wischt ein paar Marschfänge auf!', },
    {'Reavij im Sumpfrattenposten möchte, dass Ihr 10 Marschfangreißer tötet.', },
  },
  [9771] = {
    'Auf der Suche nach Späher Jyoba',
    {'Jetzt, da Ihr mit dem Gelände vertraut seid, würde ich Euch gerne bei einer anderen Sache um Hilfe bitten. Das Todesmoor, so nennen wir das Gebiet im Nordwesten, ist ein schauriger Ort. Niemand hat dort je ein Lebewesen gesehen, aber es war auch nie jemand lange dort.|n|nSpäher Jyoba hat sich freiwillig gemeldet, um das Gebiet zu untersuchen und von seinen Beobachtungen zu berichten. Er hat den Posten vor drei Tagen verlassen und ist noch nicht zurückgekehrt. Er würde nie so lange wegbleiben ohne einen Bericht zu schicken. Könntet Ihr nach ihm suchen, $N?', },
    nil,
  },
  [9772] = {
    'Jyobas Bericht',
    {'Fetzen von welkem Pilz befinden sich überall auf dem Körper von Späher Jyoba. Was auch immer ihn getötet hat muss aus demselben siechenden Pilz bestehen wie die riesigen welkenden Pilze des Todesmoors. Vielleicht hat ihn einer der siechenden Riesen überrascht, als er gerade seinen Bericht schreiben wollte.|n|nOhne den Text des Berichts ist es fast unmöglich herauszufinden, was der Späher entdeckt hat. Wenn der Bericht gefunden werden könnte, sollte er unbedingt zu Zurai gebracht werden.', },
    {'Besorgt Späher Jyobas Bericht von den siechenden Riesen und kehrt dann zu Zurai im Sumpfrattenposten zurück.', },
  },
  [9773] = {
    'Keine Pilze mehr!',
    {'Pilzsuppe, Pilzeintopf, Pilzsoße!|n|nPilze, Pilze, Pilze! Was anderes bekommt man hier nicht zu essen. Wenn man sagt, dass man Hunger hat, drückt der Koch einem eine Axt in die Hand und sagt: Schlag Dir Dein Abendessen selbst!|n|nNun, ich habe Pilze satt. Ich habe Fische in den Seen hier gesehen. Klar, sie sehen aus, als würden sie sich wehren, aber sie müssen einfach besser schmecken als Pilze!|n|nWie viel würde es mich kosten Euch zu beauftragen, mir mein erstes anständiges Abendessen seit Wochen zu bringen?', },
    {'Bringt 8 Aalfilets von Umbrafennaalen zu Magasha im Sumpfrattenposten.', },
  },
  [9774] = {
    'Dicke Hydraschuppen',
    {'Es war sehr klug von Reavij Lederrüstung mitzubringen. Der Sumpf wird meine Panzerrüstung innerhalb von kurzer Zeit wertlos machen.|n|nIch habe schon so weit ich konnte nach und nach alle Schuppen ausgetauscht. Die Hydras in dem Marschen haben dicke, schützende Schuppen, die der Feuchtigkeit ihrer Heimat optimal standhalten.|n|nGeeignete Schuppen zu finden ist allerdings ziemlich langwierig. Oftmals sind sie zu kaputt, zu abgenutzt oder zu dünn um sie als Rüstung zu verwenden. Bringt mir ein paar geeignete Schuppen von den Hydras in den größeren Seen.', },
    {'Bringt 12 dicke Hydraschuppen zu Zurai im Sumpfrattenposten.', },
  },
  [9775] = {
    'Bericht an Schattenjäger Denjai',
    {'Schattenjäger Denjai erwartet sicher einen Bericht über meine Fortschritte bei der Errichtung unseres Außenpostens. Ich habe eine Zusammenfassung unserer bisherigen Errungenschaften vorbereitet, aber seit wir Späher Jyobe verloren haben, kann ich keinen Boten entbehren, um den Bericht zu Denjais Posten Zabra\'jin im Westen zu bringen.|n|nWenn Ihr in die Richtung geht, könntet Ihr ihm den Bericht vielleicht von mir geben? Schattenjäger Denjai kann auf den ersten Blick etwas einschüchternd wirken, aber wenn Ihr Euch an ihn gewöhnt habt, ist er kein übler Kerl.', },
    nil,
  },
  [9776] = {
    'Die Oreborzuflucht',
    {'Wie Ihr sicher wisst, sind viele Einwohner von Telredor Flüchtlinge aus dem Krieg, der die Draenei dezimiert hat. Es ist mein Ziel, Telredor als sicheren Hafen für all unsere Verbündeten in diesem Kampf zu gewinnen. Es gibt einige, die sich uns gerne anschließen möchten, aber spüren, dass sie noch nicht bereit sind.|n|nWir schulden ihnen jede Hilfe, die wir ihnen bieten können, $N. Eine Gruppe von Zerschlagenen unter der Führung von Ikuti hat in den Ruinen eines alten Tempels nordwestlich vom Schlangensee Zuflucht gefunden. Sucht sie und reicht ihnen Eure Hand in Freundschaft.', },
    nil,
  },
  [9777] = {
    'Fulgorsporen',
    {'Es gibt nur wenig Brennbares in diesem Sumpf, $R, daher müssen wir auf andere Mittel zugreifen, um Telredor zu erleuchten. Viele Tiere und Pflanzen in den Marschen strahlen ein schwaches Leuchten aus.|n|nEs ist schwierig und grausam die leuchtenden Tiere einzusperren, deshalb haben wir uns einen Pilz als Lichtquelle gesucht.|n|nWir bauen die Fulgorpilze hier an, aber ab und zu benötigen wir auch neue Pflanzen. Die kleinen grünen Pilze wachsen an den größeren in der Nähe von Telredor.', },
    {'Bringt 6 Fulgorsporen zu Ruam in Telredor.', },
  },
  [9778] = {
    'Aufseher Hamuht',
    {'Sprecht auf jeden Fall noch mit Aufseher Hamuht, bevor Ihr die Zuflucht des Cenarius verlasst. Er ist für die Sicherheit der Expedition verantwortlich.|n|nEr würde mir nie verzeihen, wenn ich einen erfahrenen Abenteurer wie Euch nicht zu ihm schicken würde.', },
    {'Meldet Euch bei Aufseher Hamuht in der Zuflucht des Cenarius in den Zangarmarschen.', },
  },
  [9779] = {
    'Abfangen der Nachricht',
    {'Schön, Euch wiederzusehen, $N. Ich hätte da eine heikle Aufgabe, die es zu lösen gilt.|n|nUnsere Agenten, die die Sonnenfalken ausspionieren, haben berichtet, dass Soldaten der Sonnenfalken ein ungewöhnliches Dokument untersucht haben.|n|nUnglücklicherweise konnten wir keine Kopie dieses Schreibens für uns selbst beschaffen. Ihr müsst für mich vor Ort gehen und das Dokument an Euch bringen. Ich bin mir sicher, dass Euch ein Sonnenfalke die von uns gesuchten Informationen geben wird, wenn Ihr genug Druck anwendet. Ich überlasse den Einsatz von Gewalt voll und ganz Eurem Ermessen.', },
    {'Tötet die Elfen der Sonnenfalken, bis Ihr das Schreiben der Sonnenfalken findet, und bringt es zu Verteidiger Boros bei der Blutwacht.', },
  },
  [9780] = {
    'Aalfilets von Umbrafenn',
    {'Schön, ein neues Gesicht hier zu sehen. Als Haalrun und ich nach Telredor kamen, waren wir die ersten von außerhalb, aber das scheint schon eine Ewigkeit her zu sein.|n|nTrotzdem heißen wir Neuankömmlinge immer willkommen und versuchen dafür zu sorgen, dass alle genug zu essen haben. Wir werden die Freundlichkeit der Anachoreten von Telredor niemals vergelten können, aber wir können ihrem Beispiel folgen und ebenso freundlich zu anderen sein.|n|nWenn Ihr helfen möchtet, dann fangt ein paar der Fische, die sich in den Seen in der Gegend tummeln. Sie heißen Umbrafennaale und sind Hauptbestandteil unserer Nahrung.', },
    {'Bringt 8 Aalfilets zu Noraani in Telredor.', },
  },
  [9781] = {
    'Zu viele Mäuler zu stopfen',
    {'Auf meiner letzten Jagd habe ich gesehen, dass eine Gruppe von Trollen im Begriff ist, einen neuen Außenposten zu bauen. Ohne Zweifel haben sie auch angefangen, hier zu jagen.|n|nWenn sie einen dauerhaften Standort hier errichten, wird es einen erbitterten Kampf um Nahrung geben. Wir können sie nicht direkt angreifen, ohne sie zu provozieren. Aber wir können unsere natürlichen Wettbewerber im Nahrungskampf reduzieren.|n|nJede Morasthydra, die Ihr erlegt, bedeutet drei Mäuler weniger, die gestopft werden müssen!', },
    {'Tötet 10 Morasthydras und kehrt zu Haalrun in Telredor zurück.', },
  },
  [9782] = {
    'Das Todesmoor',
    {'Ich lebe nun seit einiger Zeit bei den Anachoreten von Telredor, $N, und inzwischen kenne ich die Marschen ganz gut. In letzter Zeit habe ich eine erschreckende Veränderung des Landes im Nordosten bemerkt.|n|nFast alles Leben dort hat begonnen zu welken und zu sterben, und das scheinbar ohne Grund. Ich habe ein paar Vermutungen, was dort vorgehen könnte, aber sie sind nur sehr vage. Wenn Ihr mir eine Bodenprobe dieser Gegend bringen könntet, dann könnte ich diesem Rätsel vielleicht auf den Grund kommen.', },
    {'Bringt eine Erdprobe vom Todesmoor zu Verteidiger Idaar in Telredor.', },
  },
  [9783] = {
    'Eine unnatürliche Dürre',
    {'Die Erdprobe, die Ihr mir gebracht habt, ist fast ausgetrocknet, $N. Wenn schon der Boden seine Feuchtigkeit verliert, müssen die Lebewesen im Todesmoor furchtbar leiden.|n|nIch habe gesehen, was passiert, wenn die Fungusgiganten der Gegend anfangen zu welken und zu sterben. Der Schmerz macht sie wahnsinnig und bringt sie dazu, alles in ihrer Nähe anzugreifen.|n|nDiese Lebewesen haben nicht die leiseste Ahnung, was mit ihnen geschieht. Sie zu retten liegt außerhalb unserer Macht. Das Einzige, was wir tun können, ist ihr Leiden zu beenden.', },
    {'Verteidiger Idaar möchte, dass Ihr 12 siechende Riesen tötet.', },
  },
  [9784] = {
    'Pflanzenteile identifizieren',
    nil,
    nil,
  },
  [9785] = {
    'Der Segen der Uralten',
    {'Ihr habt Euch das Vertrauen der Expedition des Cenarius verdient, $N. Es ist an der Zeit, dass Ihr Euch mit den Urtumen unterhaltet, die sich unserer Sache angeschlossen haben, Ashyen und Keleth, und um ihren Segen bittet.|n|nDas Zeichen eines Urtums zu tragen bedeutet große Macht. Je höher Euer Ansehen bei uns steigt, umso wertvoller wird dieser Gefallen werden.|n|nGeht, $N, und bittet die Urtume um ihren Segen.', },
    {'Windrufer Stolzhuf möchte, dass Ihr mit den Urtumen Ashyen und Keleth in der Zuflucht des Cenarius sprecht und um ihren Segen bittet.', },
  },
  [9786] = {
    'Die Ruinen von Boha\'mu',
    {'Bevor mein Volk von den Orcs dezimiert wurde, diente Telredor als Zuflucht für die Anachoreten und Spiritualisten der Draenei. Ein kleiner Orden von Anachoreten und Verteidigern pflegte ein paar Schreine in dieser Region.|n|nWährend des Krieges verloren wir den Kontakt zu den Anachoreten, die für diese Schreine zuständig waren, besonders zu denen im Tempel von Boha\'mu im Südwesten. Ich habe gehört, dass ein Stamm von Verirrten sich in dieser Gegend niedergelassen hat und vielleicht sogar in den Ruinen lebt. Geht zu den Ruinen von Boha\'mu und berichtet mir, was Ihr dort findet.', },
    {'Anachoret Ahuurn in Telredor möchte, dass Ihr die Ruinen von Boha\'mu erforscht.', },
  },
  [9787] = {
    'Götzen des Wildfennstamms',
    {'Aus Eurem Bericht über die Ruinen von Boha\'mu hörte ich heraus, dass dieser Stamm der Verirrten zur Verehrung von Tiergeistern zurückgekehrt ist. Bevor wir auf sie zugehen können, müssen wir mehr über ihren Glauben in Erfahrung bringen.|n|nKehrt zurück nach Wildfenn und sammelt heimlich ein paar ihrer Götzen, damit ich sie untersuchen kann. Versucht jedoch, sie nicht wütend zu machen, sonst haben wir vielleicht keine Chance mehr, Kontakt mit ihnen aufzunehmen.', },
    {'Sammelt 6 Wildfenngötzen und kehrt dann zu Anachoret Ahuurn in Telredor zurück.', },
  },
  [9788] = {
    'Ein feuchter, düsterer Ort',
    {'Bald nachdem ich dem Umbrafennstamm entkommen war, habe ich mich in einer Höhle südlich des Dorfs verkrochen. Ich hatte ja keine Ahnung, dass die Tiere der Marschen und die Sporenmänner sich um die Höhle stritten!|n|nIch musste sehr plötzlich von dort fliehen und eine Kiste mit meinem weltlichen Besitz zurücklassen.|n|nEs grenzte schon an Ironie, dass ich mit meinem ganzen Hab und Gut aus Umbrafenn entkommen konnte, nur um es so bald darauf wieder zu verlieren. Wenn Ihr mir meine Sachen wiederbringen könntet, würde ich Euch etwas aus meinem persönlichen Besitz schenken. Seid Ihr einverstanden, $N?', },
    {'Sucht nach Ikeyens Habseligkeiten in einer Höhle südlich von Umbrafenn. Bringt sie zurück zu Ikeyen in der Zuflucht des Cenarius in den Zangarmarschen.', },
  },
  [9789] = {
    'Beherrschen der Grollhufjagd',
    {'Ihr möchtet Euch einen Platz in der Safari verdienen? Dann beweist Euch erst einmal.|n|nMir ist es völlig schnuppe, was Ihr schon alles für Kreaturen erlegt habt, bevor Ihr nicht jagt, was wir jagen, seid Ihr in meinen Augen $Gkein Jäger:keine Jägerin;. Die Grollhufe wären ein guter Anfang, sofern Ihr $GManns genug: mutig genug; seid.|n|nIch bin mir sicher, dass ich sie in der direkten Umgebung der Safari und in der Nähe im Süden gesehen habe.', },
    nil,
  },
  [9790] = {
    'Lichtdurchlässige Flügel',
    {'An so einem abgeschiedenen Ort zu leben hat uns gelehrt, einen Nutzen aus allen verfügbaren Dingen zu ziehen. Dabei muss man natürlich lernen zu vergessen, woher einige der Materialien stammen.|n|nIch habe herausgefunden, dass die Flügel der Umbraglimmstecher, die hier in der Gegend leben, sehr gut als Regenschutz dienen. Sie sind stabil, dünn und biegsam.|n|n<Haalrun kichert.>|n|nIch sehe Euren Gesichtsausruck. Wie ich sagte, man muss sich erst an die Idee gewöhnen. Wenn Ihr in der Gegend herumstreicht, könnt Ihr mir dann vielleicht ein paar solcher Flügel mitbringen?', },
    {'Bringt 8 lichtdurchlässige Flügel von einer beliebigen Glühwürmchenart der Zangarmarschen zu Haalrun in Telredor.', },
  },
  [9791] = {
    'Bedrohliche Marschenfänge',
    {'Während der Kriege der Orcs gegen mein Volk haben die Nahrungssammler Telredor aus Angst, angegriffen oder gefangen zu werden, kaum verlassen. Nun gehen sie häufiger hinaus, aber die Marschen sind nicht weniger gefährlich.|n|nEs scheint, als wären die Marschenfänge in letzter Zeit aggressiver geworden. Ich weiß nicht, ob das an der erhöhten Konkurrenz für ihre gewöhnliche Nahrung liegt, aber sie greifen regelmäßig unsere Nahrungssucher an. Vielleicht würden sie uns in Ruhe lassen, wenn wir ihren Bestand um Telredor herum etwas dezimieren könnten.', },
    {'Tötet 10 Marschenfangreißer und kehrt dann zu Noraani in Telredor zurück.', },
  },
  [9792] = {
    'Eine Botschaft für Telaar',
    {'Ihr habt Euch in unseren Geschäften als vertrauenswürdig erwiesen, $N, und das in Zeiten, in denen das Vertrauen meines Volkes nur schwer zu gewinnen ist.|n|nEine große Gruppe meiner Brüder und Schwestern hat sich in der alten Draeneistadt Telaar in Nagrand im Süden niedergelassen. Um nach Telaar zu gelangen, müsst Ihr der Straße Richtung Süden nach Nagrand folgen und dann nach Südosten gehen, bis Ihr an die Klippen östlich des Oshu\'guns gelangt.|n|nJeder, der uns so sehr geholfen hat wie Ihr, ist dort willkommen.|n|nSucht Aufseher Moi\'bff Jill und sagt ihm, dass Ihr mein Vertrauen erlangt habt.', },
    {'Sprecht mit Aufseher Moi\'bff in Telaar in Nagrand.', },
  },
  [9793] = {
    'Das Schicksal von Tuurem',
    {'Prophet Velens Suche nach Verbündeten hat die Draenei in der Scherbenwelt ermutigt, selbst eine Suche zu beginnen. Der Krieg meines Volks mit der Legion hat uns vielleicht aus unseren Städten und Tempeln vertrieben, aber er konnte nicht alle Spuren unserer Zivilisation verwischen.|n|nTuurem, mein früheres Zuhause in den Wäldern von Terokkar, war eine der Städte, die von den Orcs überrannt wurden. Ich habe schon viel zu lange nichts mehr von dort gehört. Bringt diesen Brief zu Andarl in der Festung in Terokkar und schaut, was Ihr herausfinden könnt.', },
    {'Bringt Verteidiger Idaars Brief zu Andarl in der Festung in den Wäldern von Terokkar.', },
  },
  [9794] = {
    'Keine Zeit für Neugier',
    {'$N, ich muss Euch um einen Gefallen bitten. Normalerweise würde ich das ja nicht tun, aber ich habe beide Hände bereits mehr als voll.|n|nIch habe einen Verbündeten namens Kialon in Sylvanaar im Schergrat im Norden. Er erwartet, dass ich mich in naher Zukunft bei ihm melde, obwohl ich fürchte, dass ihm nicht gefallen wird, was ich zu sagen habe.|n|nWenn Ihr ihm meine Antwort bringen könntet, wäre ich Euch sehr dankbar. Ich muss jedoch darauf bestehen, und das ist sehr wichtig, dass Ihr den Brief nicht lest. Er ist nur für Kialons Augen bestimmt.', },
    {'Bringt Timothys Brief zu Kialon in Sylvanaar im Schergrat.', },
  },
  [9795] = {
    'Die Ogerbedrohung',
    {'Als ob die Naga und ihre Verbündeten nicht schon genug wären, scheinen nun auch die Oger sich weiter in den Marschen auszubreiten. Sie haben schon weite Teile des Nordwestens erobert, und der Puffer zwischen uns und ihnen wird immer kleiner.|n|nFür jeden, den wir umbringen, sind gleich mehrere neue zur Stelle. Ich weiß nicht, wie lange wir Zabra\'jin halten können, wenn sie sich entschließen uns anzugreifen. Geht nach Norden in die Berge zum orcischen Stützpunkt in der Donnerfeste und berichtet Nekthar von unserer Bedrängnis. Jede Hilfe, die er uns zur Verfügung stellen kann, ist äußerst willkommen.', },
    {'Reist zur Donnerfeste im Schergrat und sprecht mit Nekthar.', },
  },
  [9796] = {
    'Nachricht aus den Zangarmarschen',
    {'Schattenjäger Denjai ist nicht der einzige, der auf einen Bericht von mir wartet. Mokasa in der Steinbrecherfeste in Terokkar brennt darauf, von unseren Fortschritten zu hören, besonders seit die meisten ihrer Boten hier auf ihren Reisen vorbeikommen.|n|nSie hat mich gebeten, ihr Bescheid zu geben, sobald der Sumpfrattenposten fertig ist. Wenn Ihr nichts dagegen habt, wäre ich Euch sehr dankbar, wenn Ihr ihr die Nachricht überbringen könntet. Wir haben zwar soweit schon alles aufgebaut, aber es gibt noch viel zu tun.|n|nUm zur Steinbrecherfeste zu gelangen, müsst Ihr der Straße nach Süden in Richtung Zangarmarschen folgen und Euch durch die Wälder von Terokkar an Tuurem vorbei begeben.', },
    {'Sprecht mit Mokasa in der Steinbrecherfeste in den Wäldern von Terokkar.', },
  },
  [9797] = {
    'Verstärkung für Garadar',
    {'<Immer noch nach Atem ringend bedeutet der Bote Euch, Euch hinzusetzen.>|n|nSie werden vielleicht nicht überleben, $R! Geht so schnell Euch Eure Beine tragen können nach Garadar.|n|n<Als Reaktion auf Euren fragenden Gesichtsausdruck führt der Bote näher aus.>|n|nDas Zuhause der Mag\'har liegt im Süden, in Nagrand. Wir haben ein paar Leute dort, aber es sind nur wenige, und unsere Verbündeten der Mag\'har werden von allen Seiten von Feinden angegriffen. Sucht dort unseren Kommandanten, Hauptmann Kroghan, und helft ihm, wo Ihr nur könnt! Garadar darf nicht fallen!', },
    {'Sprecht mit Hauptmann Kroghan in Garadar in Nagrand.', },
  },
  [9798] = {
    'Blutelfenpläne',
    {'Diese Pläne sehen wichtig aus. Ihr solltet sie Verteidiger Aldar bei der Absturzstelle zeigen.', },
    {'Bringt die Blutelfenpläne zu Verteidiger Aldar bei der Absturzstelle im Am\'mental.', },
  },
  [9799] = {
    'Botanische Hilfsarbeit',
    {'Die Am\'menfelder im Westen sind das wichtigste Vermehrungsgebiet der einheimischen Peitscherpopulation. Botanikerin Taerix befürchtet, dass sich die Peitscher auf Grund des verseuchten Grundwasserspiegels nicht mehr fortpflanzen können, nachdem wir den See gereinigt haben.|n|nGeht zu den Am\'menfeldern und pflückt dort ein paar der verderbten Blumen für mich, damit ich sie untersuchen und sehen kann, was es zu tun gilt. Ihr solltet sie an ihren ungewöhnlichen roten Blüten erkennen.', },
    {'Sammelt 3 verderbte Blumen und kehrt zu Lehrling Vishael bei der Absturzstelle im Am\'mental zurück.', },
  },
  [9800] = {
    'Eine seltene Bohne',
    {'Ihr seid zu schlecht ausgerüstet um den rastlosen Elementaren Nagrands gegenüber zu treten. Bevor Ihr dem Irdenen Ring helfen könnt, müsst Ihr erst Euch selbst helfen.|n|nIm Westen findet Ihr Kothaufen von den Wildtieren Nagrands. Ihr müsst den Dung nach den verdauten Überresten der Caracolibohne durchsuchen. Aus dieser Bohne kann ich eine Tablette herstellen, die Euch im Kampf gegen die ruhelosen Naturgewalten helfen wird.|n|nKehrt zu mir zurück, wenn Ihr mindestens zwei Fäuste voller Caracolibohnen gesammelt habt... Ogerfäuste!', },
    nil,
  },
  [9801] = {
    'Die Reagenzien sammeln',
    {'Ich habe das Gefühl, dass diese Verirrten nicht so gut auf $Geinen:eine; Draenei zu sprechen sein werden, aber vielleicht auf einen Arakkoa. Ich kann einen Zaubertrank herstellen, der Euch für kurze Zeit in einen Arakkoa verwandeln kann. Dazu benötige ich ein paar Reagenzien, die man nur sehr schlecht lagern kann, da man sie sofort nach dem Sammeln weiterverarbeiten muss.|n|nIhr werdet mir ein paar Sporensegleraugen und einige Fennschreitertentakel bringen müssen. Beide Arten leben in der Wildnis um Telredor herum.', },
    nil,
  },
  [9802] = {
    'Pflanzen der Zangarmarschen',
    {'Die Seen der Zangarmarschen werden langsam entwässert. Wir wissen nicht warum, aber viele Pflanzenarten drohen auszusterben.|n|nAls Katalogisiererin der Expedition ist es meine Aufgabe, diese Pflanzen zu identifizieren und zu verstehen, was mit ihnen geschieht.|n|nWenn Ihr helfen wollt, bringt mir unbekannte Pflanzenteile. Wenn Ihr kräuterkundig seid, könnt Ihr sie direkt vom Boden pflücken, aber auch die einheimischen Wesen des Sumpfs tragen Pflanzenteile bei sich.', },
    {'Bringt 10 unbekannte Pflanzenteile zu Lauranna Thar\'well in der Zuflucht des Cenarius in den Zangarmarschen.', },
  },
  [9803] = {
    'Botschaft für den Wildfennstamm',
    {'Es ist an der Zeit, dem Wildfennstamm die Hand zu reichen und sie zu lehren, dass das Licht sie nicht aufgegeben hat. Nehmt den Trank, den ich vorbereitet habe, und tragt ihn zu den Ruinen von Boha\'mu.|n|nSobald Ihr bei den Ruinen angekommen seid, trinkt den Trank um Euch in einen der Vogelgeister zu verwandeln. Sprecht mit dem Ältesten Kuruti und lasst ihn wissen, dass die Draenei bereit sind, sein Volk als verloren geglaubte Brüder und Schwestern zu empfangen.', },
    {'Trinkt Ahuurns Elixier in den Ruinen von Boha\'mu. Sprecht mit dem Ältesten Kuruti in der Form eines Arakkoas.', },
  },
  [9804] = {
    'Aufgebrachte Geister des Himmelsweisensees',
    {'Die Unruhen in den Gezeiten der Gewässer von Nagrand hat die Wassergeister des Himmelsweisensees sehr aufgebracht. Sie haben im Gegenzug damit begonnen, Verwüstungen entlang der Wasserwege anzurichten.|n|nWatoosun des Wassers ist uns in einer Vision erschienen und hat uns erlaubt, das Problem zu lösen, solange wir auch die Ursache dafür beheben...|n|nWir werden uns um die Ursache kümmern, doch zuerst müssen wir die direkten Bedrohungen für den Thron beseitigen. Zerstört die aufgebrachten Seegeister und kehrt dann zu mir zurück.', },
    nil,
  },
  [9805] = {
    'Segen des Incineratus',
    {'Die erbärmlichen Verirrten, einst verbannt in die Sümpfe der Zangarmarschen, versuchen nun, ihren Dreck auch in andere Teile der Welt zu tragen.|n|nIch habe mich an die weisen Furien gewandt und ihren Segen erhalten. Um die Ursache zu beseitigen, müssen wir die Elemente auf sie hetzen!|n|nIch gebe Euch beseeltes Feuer, entzündet an der feurigen Essenz von Incineratus selbst. Reist nach Schilftanz, südöstlich von hier, und entzündet die Hütten mit dem Feuer! Lasst sie die Wut der Elemente spüren!', },
    {'Elementarist Lo\'ap am Thron der Elemente in Nagrand möchte, dass Ihr die große Hütte, die westliche Hütte, die südliche Hütte und die östliche Hütte in Schilftanz zerstört.|n|nBringt das beseelte Feuer zurück zu Elementarist Lo\'ap, wenn Ihr fertig seid.', },
  },
  [9806] = {
    'Fruchtbare Sporen',
    {'Wenn sie zwischen den Langstielpilzen hindurchwandern, sammeln sich allerlei fruchtbare Sporen an den Gliedmaßen der Sporensegler und Marschenläufer.|n|nWie Ihr sehen könnt, ist unser Volk sehr klein, also haben wir nur wenige Möglichkeiten, diese Sporen zu sammeln. Haltet nach Sporenseglern und Marschenläufern Ausschau und sammelt die fruchtbaren Sporen. Ganz Sporeggar stünde tief in Eurer Schuld.', },
    {'Sammelt 6 fruchtbare Sporen von den Sporenseglern und den Marschenläufern und kehrt danach zu Gshaff in Sporeggar zurück.', },
  },
  [9807] = {
    'Noch mehr fruchtbare Sporen',
    nil,
    nil,
  },
  [9808] = {
    'Glühkappenpilze',
    {'Ich habe gesehen, dass Ihr glänzende runde Metallstücke benutzt, um sie gegen Dinge einzutauschen, die Ihr haben möchtet. Wir benutzen glänzende runde Pilze als Zahlungsmittel.|n|nDie Glühkappenpilze wachsen überall in den Marschen, man muss nur wissen, wie man sie richtig sammelt ohne sie zu zerstören. Ich werde Euch beibringen, wie man das tut, wenn Ihr mir versprecht, ein paar für unsere Vorräte zu sammeln. Einverstanden, $N?', },
    {'Bringt 10 Glühkappen zu Msshi\'fn in Sporeggar in den Zangarmarschen.', },
  },
  [9809] = {
    'Noch mehr Glühkappen',
    nil,
    nil,
  },
  [9810] = {
    'Der verschmutzte Geist',
    {'Watoosun konnte zwar den Seuchengestank loswerden, aber gleichzeitig erschuf er eine irrsinnige Geisteressenz. Eine Geisteressenz, die aus der übelsten Verderbnis entstanden ist, die es je unter Elementaren gegeben hat!|n|nIhr könnt diesen verschmutzten Sumpfgeist südwestlich von hier, tief im Sonnenwindsee, finden.|n|nSucht und vernichtet Watoosuns verschmutzte Essenz sowie jeglichen verseuchten Nachfahren, den sie erschaffen haben möge.', },
    nil,
  },
  [9811] = {
    'Freund der Sin\'dorei',
    {'Dies ist der Beginn eines neuen Zeitalters in der Geschichte der Blutelfen $N. Ihr habt geholfen, den Bund zwischen unserem und Eurem Volk zu festigen, $R.|n|nBringt den Kopf des Verräters nach Silbermond zum Lordregenten Lor\'themar Theron. Er wird begierig sein, die Neuigkeit zu erfahren.', },
    {'Bringt Dar\'Khans Kopf zu Lor\'themar Theron in Silbermond.', },
  },
  [9812] = {
    'Gesandter zur Horde',
    {'Unter unseren neuen möglichen Verbündeten regen sich Zweifel über unsere Fähigkeiten. Wie könnten wir ihnen helfen, wenn sie glauben, dass wir nicht einmal mit unseren Problemen zuhause fertigwerden?|n|nDas ändert alles. Wir lassen keine Zweifel an unserer Stärke zu. Wir werden der Horde als Ebenbürtige beitreten.|n|nBringt diesen Brief zu Sylvanas, Anführerin der Verlassenen. Sie war schon immer auf unserer Seite, aber die Nachricht von Dar\'Khans Tod muss wie Musik in ihren Ohren klingen. Bereitet Euch auf eine lange Reise vor, $N. Wenn alles gut geht, wird sie Euch nach Orgrimmar schicken.', },
    {'Bringt den Brief von Lor\'themar Theron zu Fürstin Sylvanas Windläufer in Unterstadt, der Hauptstadt der Verlassenen in Tirisfal.', },
  },
  [9813] = {
    'Ein Treffen mit dem Kriegshäuptling',
    {'Wie Ihr wisst, habe ich nichts von der Liebe zu meinem Heimatland oder seinem Volk verloren. Ich habe mit Krallen und Zähnen gekämpft, damit Silbermond am Verhandlungstisch einen Platz neben Unterstadt und Orgrimmar erhält.|n|nDies sollte sämtliche Gegenstimmen zum Schweigen bringen. Bringt diesen Brief zum Kriegshäuptling in Orgrimmar. Als Anführer der Horde hat er das letzte Wort bei der Entscheidung über die Bitte der Sin\'dorei.|n|nIch habe den Brief als Zeichen meiner persönlichen Bekräftigung mit meinem Siegel versehen. Geht in den Nordwesten der Stadt und steigt auf dem Turm in den Zeppelin nach Durotar.', },
    {'Fürstin Sylvanas Windläufer möchte, dass Ihr den Brief mit Sylvanas\' Siegel zum Kriegshäuptling nach Orgrimmar, Hauptstadt von Durotar, bringt.', },
  },
  [9814] = {
    'Berstkappenpilze, Mann!',
    {'Mögt Ihr Pilze, Mann? Es gibt einen ganz mächtigen hier in den Zangarmarschen, wächst gleich in der Nähe von Zabra\'jin.|n|nIhr müsst aber vorsichtig sein, Mann. Man nennt sie aus gutem Grund Berstkappenpilze. Wenn man ohne entsprechende Vorsichtsmaßnahmen zu nahe an sie herangeht, geht ihnen der Hut hoch! Puff! Und dann steht man in einer Wolke von giftigen Sporen.|n|nIch habe sie benutzt, um die Zukunft vorauszusagen, aber jetzt sind sie fast alle.', },
    {'Bringt Hexendoktor Tor\'gash 6 Berstkappen.', },
  },
  [9815] = {
    'Schlammtauchen',
    {'Die am schwersten betroffenen Wasserelementare befinden sich im Halaanibecken, südwestlich von hier unterhalb der verlassenen Stadt Halaa. Während einige der verzweifelten Elementare ohne Folgen für die Umwelt zerstört werden können, müssen die Überreste der Schlammkreaturen nach ihrer Zerstörung entfernt werden.|n|nDie Schlammkreaturen hinterlassen nämlich verseuchte Leichenteile, die der Umwelt schaden können, wenn man sie liegen lässt.|n|nVernichtet diese Schlammkreaturen und bringt mir ihre schlammbesudelten Kerne.', },
    {'Elementarist Lo\'ap am Thron der Elemente in Nagrand möchte, dass Ihr 5 schlammbesudelte Kerne besorgt.', },
  },
  [9816] = {
    'Habt Ihr so was schon mal gesehen?',
    {'In diesen Marschen fehlt was, Mann! Keine Murlocs hier.|n|nKeine Sorge, Mann, ich habe eine Lösung für dieses Problem. Seht Ihr Gargel und Gurgel da drüben? Ich habe vor, den Verirrten ein paar Murlocs zu schenken!|n|nBringt diesen Käfig nach Dolchfenn und lasst sie bei der Ansammlung von Hütten im Nordosten frei. Nun gut, ich möchte Euch nicht Gargel und Gurgel auf den Hals jagen, aber ich gebe Euch einen Käfig mit jungen bunten Murlocs. Setzt den Käfig einfach auf den flachen Stein, den Ihr dort finden werdet, und öffnet die Tür!', },
    {'Bringt den Murlockäfig nach Dolchfenn und stellt ihn auf den flachen Stein in der Nähe des Dorfs.', },
  },
  [9817] = {
    'Anführerin der Blutschuppen',
    {'Hiermit setzt die Expedition des Cenarius ein Kopfgeld auf Rajis Fyashe, Anführerin der Blutschuppennagas, aus. Die Nagazauberin wurde zuletzt am Schlangensee gesehen, im Nordwesten der Zangarmarschen.|n|nDie Blutschuppen sind als extrem gefährlich einzustufen, und ihre Anführerin sollte mit äußerster Vorsicht behandelt werden.|n|nDas Kopfgeld kann bei Aufseher Hamuht in der Zuflucht des Cenarius eingefordert werden.', },
    {'Tötet Rajis Fyashe am Schlangensee und kehrt dann zu Aufseher Hamuht in der Zuflucht des Cenarius in den Zangarmarschen zurück, um eine Belohnung zu erhalten.', },
  },
  [9818] = {
    'Im Untergrund',
    {'Etwas schändet den Untergrund. Es schlägt den Boden, als wollte es ihn bestrafen.|n|n*Rums*|n|n<Untrag schlägt sich mit der Faust auf die Brust.>|n|nSo klingt das hunderttausendmal. Endlos. Die Erde taumelt. Sie ruft nach uns.|n|nGordawg spricht mit mir. Gordawg weiß, dass etwas die Elementare hervortreibt. Etwas unter der Erde.|n|nGeht jetzt und sprecht mit Gordawg. Nein, hört ihm zu, sprecht nicht. Hört Gordawg an...', },
    {'Kommuniziert mit Gordawg.', },
  },
  [9819] = {
    'Die gequälte Erde',
    {'Bestraft den Thronräuber. Ihr werdet ihn finden. Folgt Pfad aus Erde. Zuerst bringt gequälte Erdgeister zur Ruhe. Müssen wieder schlafen.|n|n<Gordawg schlägt mit seiner Faust auf den Boden und schleudert faulig riechende Erde nach oben.>|n|nMüssen schlafen!|n|n<Gordawg zeigt nach Südosten.>|n|nSucht Geister in Nähe von Bergen. Nähe von Hügeln. Nähe von Erde.|n|nBringt zur Ruhe.|n|nTelaaribecken... Südosten.', },
    nil,
  },
  [9820] = {
    'GESUCHT: Boss Grog\'ak',
    {'Gesucht - Tot oder lebendig: Boss Grog\'ak, Vorarbeiter der Ango\'rosh Pilzsammeloperation.|n|nDiese grobschlächtigen, axtschwingenden Dummköpfe sind für das Fällen von Pilzen nördlich des Dorfs verantwortlich. Wenn er nicht aufgehalten wird, werden er und seine Leute einen Pfad bis zu den Mauern von Zabra\'jin schlagen!|n|nWer Boss Grog\'aks Kopf zu Schattenjäger Denjai bringt, soll reich belohnt werden.', },
    {'Bringt den Kopf von Boss Grog\'ak zu Schattenjäger Denjai in Zabra\'jin.', },
  },
  [9821] = {
    'Verdammnis schmecken',
    {'<Gordawg nimmt einen Stein und fängt an darauf herumzukauen.>|n|nGordawg schmeckt. Gordawg weiß wo diese Erde war.|n|n<Gordawg hebt eines seiner massiven Beine und stampft auf den Boden.>|n|nSchaut. Schaut Nagrand an.|n|n<Gordawg zeigt auf seinen Fußabdruck. Im Abdruck seht Ihr eine perfekte geologische Karte von Nagrand, auf der alle Stellen markiert sind, an denen die Elementare, die Ihr für Gordawg zerstören sollt, sich aufhalten.>|n|nZERSTÖRT SIE! Bringt Gordawg die Stücke zum Essen.|n|nNehmt die Karte.', },
    nil,
  },
  [9822] = {
    'Drohender Angriff',
    {'Die Position der Pilzsammeloperation der Oger kann kein Zufall sein. Ich werde den Verdacht einfach nicht los, dass sie einen Angriff auf Zabra\'jin planen.|n|nIch muss das genau wissen, $N. Die Oger haben einen weiteren Außenposten im Nordwesten beim Grund der Ango\'rosh. Wenn sie tatsächlich vorhaben uns anzugreifen, dann werden wir dort sicher Beweise für ihre Pläne finden. Geht dorthin, $N, und durchsucht das Lager. Bringt mir alles, was auch nur im Geringsten verdächtig sein könnte!', },
    {'Bringt die Angriffspläne der Ango\'rosh zu Schattenjäger Denjai in Zabra\'jin.', },
  },
  [9823] = {
    'Sie oder wir',
    {'Um die Bedrohung, die von den Ango\'rosh ausgeht, zu beenden, müssen wir ihren Oberanführer Schmetterfaust töten. Aber wir werden sogar noch viel mehr tun. Wir werden mit dem Oberanführer und seinem Gefolge ein Zeichen setzen.|n|nGeht zur Festung der Ango\'rosh und kümmert Euch um unsere Feinde. Die Feste befindet sich in einer Höhle auf einer kleinen Insel nordwestlich von Zabra\'jin. Dort werdet Ihr eine Brücke, die aus einem umgefallenen Pilz besteht, finden.|n|nZeigt kein Erbarmen, $N. Sie würden sicher keinen von uns verschonen.', },
    {'Tötet Oberanführer Schmetterfaust, 10 Raufer der Ango\'rosh, 10 Seelenfresser der Ango\'rosh und meldet Euch dann bei Schattenjäger Denjai in Zabra\'jin zurück.', },
  },
  [9824] = {
    'Arkane Störungen',
    {'Ich versuche, eine Aufzeichnung von Karazhans Energie zu erstellen... für ein privates Projekt natürlich. Unglücklicherweise empfange ich hier oben einfach nichts. Wenn ich in die Nähe einer unterirdischen Wasserquelle gelangen könnte, könnten meine Kristalle die Signale viel leichter empfangen.|n|nIch habe sowohl von einem unterirdischen Teich als auch von einem Brunnen in einem Keller unter uns gehört. Dieser ganze Ort ist jedoch voll von Geistern, und sich dort hinzuwagen wäre für jemanden in meinem Alter viel zu gefährlich. Was sagt Ihr? Werdet Ihr einem alten Mann helfen und das Aufzeichnen für mich übernehmen?', },
    {'Benutzt den violetten Aufzeichnungskristall in der Nähe von unterirdischen Wasserquellen im Keller des Meisters und kehrt zu Erzmagier Alturus außerhalb von Karazhan zurück.', },
  },
  [9825] = {
    'Rastlose Aktivität',
    {'Wie Ihr sicher bemerkt habt, wimmelt es außerhalb von Karazhan nur so von Geistwesen. Der Grund ihrer Existenz ist unbekannt, und Unbekanntes mag ich gar nicht leiden!|n|nBringt mir ihre geisterhafte Essenz, damit ich ihre Beschaffenheit untersuchen kann. Karazhan hat viele Geheimnisse, $N. Und ich werde sie alle lüften.', },
    {'Bringt 10 geisterhafte Essenzen zu Erzmagier Alturus außerhalb von Karazhan.', },
  },
  [9826] = {
    'Dalarankontaktpersonen',
    nil,
    nil,
  },
  [9827] = {
    'Siechendes Basidium',
    {'Bei einer genaueren Untersuchung des Basidiums lassen sich eine Zahl von Einkerbungen erkennen, in denen vielleicht mal etwas drinsteckte. Die fremdartige Pilzmasse scheint so etwas wie ein großes Rätsel zu sein. Sie sieht alles andere als gesund aus, aber Ihr habt keine Ahnung, wozu sie normalerweise dienen könnte.|n|nVielleicht kann Euch ja jemand, der sich mit den Bewohnern der Zangarmarschen besser auskennt etwas mehr darüber erzählen.', },
    nil,
  },
  [9828] = {
    'Siechendes Basidium',
    {'Bei einer genaueren Untersuchung des Basidiums lassen sich eine Zahl von Einkerbungen erkennen, in denen vielleicht mal etwas drinsteckte. Die fremdartige Pilzmasse scheint so etwas wie ein großes Rätsel zu sein. Sie sieht alles andere als gesund aus, aber Ihr habt keine Ahnung, wozu sie normalerweise dienen könnte.|n|nVielleicht kann Euch ja jemand, der sich mit den Bewohnern der Zangarmarschen besser auskennt etwas mehr darüber erzählen.', },
    nil,
  },
  [9829] = {
    nil,
    {'Alturus\' Bericht ist beunruhigend. Wir dachten, es sei ein schlechtes Zeichen, als Karazhan sich von der Umwelt abgeschottet hat. Wir hatten dort Agenten, von denen wir nie wieder gehört haben. Und nun diese... dämonische Strömung. Wir müssen das untersuchen.|n|nDie Einzigen, die Karazhan wieder öffnen könnten, hielt man für tot: Khadgar und Medivh.|n|nWährend wir hoffen, das Letzterer tatsächlich tot ist, haben wir kürzlich in Erfahrung gebracht, dass sein Lehrling, Khadgar, gesund und munter an einem Ort namens Shattrath lebt. Findet ihn und gebt ihm Alturus\' Bericht.', },
    {'Bringt Alturus\' Bericht zu Khadgar in Shattrath in den Wäldern von Terokkar.', },
  },
  [9830] = {
    'Blutergift',
    {'Wenn ich mich mit den Draenei unterhalte, habe ich immer den Eindruck, dass sie das Gefühl haben, aus ihrer natürlichen Umgebung herausgerissen zu sein. Viele scheinen meine Brüder und Schwestern, die Zerschlagenen, zu bedauern, weil sie glauben, dass wir etwas verloren haben.|n|nWir Zerschlagenen haben vielleicht unsere Verbindung zum Licht verloren, aber unsere Erfahrung hat uns enger an das Land gebunden.|n|nMein Volk erkennt Möglichkeiten, die den Draenei verschlossen bleiben. Nehmt zum Beispiel das Gift der Sumpflichtbluter, die im Süden und Westen leben. Es ist vielseitig einsetzbar, ob für die Jagd oder zur Heilung.', },
    {'Bringt 6 Einheiten Sumpflichtblutergift zu Puluu in der Oreborzuflucht.', },
  },
  [9831] = {
    'Nach Karazhan',
    {'Die Neuigkeiten in diesem Bericht beunruhigen mich sehr, $N. Es wird jedoch schwierig, sich Zugang zu Karazhan zu beschaffen.|n|nAls klar wurde, dass ich hier gestrandet bin, habe ich den Schlüssel in drei Teile zerbrochen.|n|nIch habe die Schlüsselfragmente in verzauberte Behälter gelegt, und diese dann an damals sicheren Plätzen versteckt.|n|nWegen der dunklen Veränderungen, die die Scherbenwelt durchmachen musste, sind sie heute allerdings alles andere als sicher. Das erste Fragment ist in einem Teil von Auchindoun versteckt, der nun vom Schattenrat beherrscht wird. Bringt mir dieses Fragment zurück.', },
    {'Khadgar möchte, dass Ihr das Schattenlabyrinth von Auchindoun betretet und das erste Schlüsselfragment aus einem versteckten arkanen Behälter besorgt.', },
  },
  [9832] = {
    'Das zweite und das dritte Fragment',
    {'Ich habe das zweite Fragment am Boden des Schlangensees versteckt, noch lange bevor er so hieß. Der gigantische Ablauf, der dort installiert wurde, nachdem die Naga den Ort in Beschlag genommen hatten, hat den Behälter wahrscheinlich in die Tiefen des Echsenkessels gesogen.|n|nDas dritte Fragment wird eine besonders große Herausforderung werden, da ich es in der Festung der Stürme gelassen habe, als die Naaru dort noch herrschten. Kael\'thas regiert dort jetzt, und das Zimmer, in dem sich das Fragment befindet, ist jetzt ein Gefängnis.|n|nBringt mir diese beiden Fragmente, $N. Von Eurem Erfolg hängt viel ab.', },
    {'Besorgt das zweite Schlüsselfragment aus einem arkanen Behälter im Echsenkessel und das dritte Schlüsselfragment aus einem arkanen Behälter in der Festung der Stürme. Kehrt dann zu Khadgar in Shattrath zurück.', },
  },
  [9833] = {
    'Nachrichtenwege',
    {'Einer der Gründe, warum uns Ikuti in die Zangarmarschen geführt hat, ist der Versuch, die Kommunikation zwischen den Draenei und Telaar, der Heimatstadt der Kurenai in Nagrand, zu verbessern. Damit die Boten schnell zwischen Telaar und Telredor hin- und herreisen können, müssen die Straßen sicher gemacht werden.|n|nAuf unserem Weg hierher wurden wir oft von Marschenfangschlitzern angegriffen. Wir konnten sie zwar abwehren, aber für einen einzelnen Boten wären sie eine besondere Bedrohung. Ihre Reihen etwas zu lichten würde viel zur Sicherheit unserer Boten beitragen.', },
    {'Puluu in der Oreborzuflucht möchte, dass Ihr 12 Marschenfangschlitzer tötet.', },
  },
  [9834] = {
    'Natürliche Rüstung',
    {'Maktu kann einen Draenei über Meilen hinweg an seiner schimmernden Rüstung erkennen, sogar in diesem düsteren Sumpf!|n|nMaktu will sie auslachen, aber dann erinnert er sich, dass sie nett zu den Kurenai waren, und will ihnen beibringen, wie Kurenai Rüstung herstellen.|n|nDie dunklen, schuppigen Bälge der Fennklauen ergeben die beste Rüstung, die Maktu je getragen hat. Wenn $N Maktu ein paar dieser Bälge von den Fennklauenhauern tief im Schlangensee bringen kann, teilt er gerne seine Rüstung mit $N.', },
    {'Bringt 8 Fennklauenbälge zu Maktu in der Oreborzuflucht.', },
  },
  [9835] = {
    'Vordringen der Ango\'rosh',
    {'Die kleine Gruppe von Zerschlagenen, die Ihr dort seht, sind Gesandte einer Siedlung in Nagrand. Die Kurenai, wie wir uns selbst nennen, sind Zerschlagene, die sich gerne mit den Draenei wiedervereinen möchten.|n|nMeine Gruppe ist hierhergekommen, um die Bande zwischen den Kurenai und den Draenei in Telredor zu stärken.|n|nWenn es nach den Ogern der Ango\'rosh geht, wird dieser Tempel nicht mehr lange stehen. Sie haben die hohen Pilze des Prügelsumpfs vollständig gerodet und kommen immer näher an unsere Zuflucht heran. Wenn Ihr $Gein Freund:eineFreundin; unseres Volkes sein möchtet, dann helft uns, diesen Feind zu besiegen.', },
    {'Tötet 10 Oger der Ango\'rosh und 5 Schamanen der Ango\'rosh und kehrt dann zu Ikuti in der Oreborzuflucht zurück.', },
  },
  [9836] = {
    'Die Berührung des Meisters',
    {'Ich habe den Schlüssel, den ich als Lehrling benutzt habe, wieder zusammengefügt. Er scheint völlig funktionstüchtig zu sein. Was jedoch die Öffnung von Karazhan angeht, ist er so wertlos wie ein Stück Alteisen.|n|nOhne Medivhs Einverständnis ist der Schlüssel unbrauchbar. Ja, natürlich weiß ich, dass Medivh tot ist. Das macht die Sache zwar schwieriger, aber nicht unmöglich.|n|nEs gibt einen Ort in Azeroth, der Höhlen der Zeit genannt wird. Er wird von dem bronzenen Drachenschwarm bewacht. Findet einen Weg dort hinein, reist in der Zeit zurück und bringt Medivh dazu, den Schlüssel zu aktivieren.', },
    {'Geht in die Höhlen der Zeit und überzeugt Medivh davon, den wiederhergestellten Schlüssel des Lehrlings zu aktivieren.', },
  },
  [9837] = {
    'Rückkehr zu Khadgar',
    {'Ich scheine mich an zukünftige Ereignisse, die mit Euch und diesem Schlüssel zu tun haben, zu erinnern.|n|n<Medivh schaut Euch an, als hätte er einen Geist gesehen.>|n|nEuch stehen harte Zeiten bevor, $N. Wollen wir hoffen, dass Euch Eure Stärke nicht im Stich lassen wird.|n|nDen Schlüssel werde ich Khadgar geben, wenn er zu mir geschickt wird. Ich könnte mir keinen besseren Lehrling vorstellen.|n|nMeiner Meinung nach solltet Ihr einen eigenen Schlüssel bekommen.|n|n<Medivh fasst in seine Robe und reicht Euch seinen eigenen Schlüssel.>|n|nNun zieht weiter. Und viel Glück, $C.', },
    {'Kehrt zu Khadgar in Shattrath zurück und zeigt ihm den Schlüssel des Meisters.', },
  },
  [9838] = {
    'Das Violette Auge',
    {'Ihr wurdet mit einer großen Verantwortung betraut, $N. Wenn man den Zeichen, die das Violette Auge beobachtet hat, trauen kann, müsst Ihr ihnen helfen.|n|nTrotz all meiner Unstimmigkeiten mit Cedric halte ich die Arbeit von Männern wie Alturus immer noch für sehr wichtig. Achtet jedoch darauf, dass sie Euch nicht ausnutzen. Denkt immer daran, dass der Schlüssel an Euch gebunden ist, nicht an sie. Aber wenn die Bedrohung in Karazhan wirklich echt ist, dann sind sie am besten dafür geeignet, Euch darauf vorzubereiten. Kehrt zurück zu Alturus und helft ihm, wo immer Ihr könnt.', },
    {'Sprecht mit Erzmagier Alturus außerhalb von Karazhan.', },
  },
  [9839] = {
    'Oberanführer Schmetterfaust',
    {'Das Herzstück jedes Ogerstamms ist sein Anführer. Ohne Anführer werden die Ango\'rosh sich zurückziehen und unter sich auskämpfen, wer der nächste Anführer wird.|n|nObwohl wir die Oger überall verstreut in dieser Gegend gesichtet haben, ist die Festung der Ango\'rosh im Nordwesten ihre eigentliche Machtbasis. Sie liegt in einer Höhle auf einer kleinen Insel, die nur durch einen umgestürzten Pilz mit den Marschen verbunden ist.|n|nGeht dort hin und besiegt Oberanführer Schmetterfaust. Das sollte uns eine wohlverdiente Ruhepause geben.', },
    {'Ikuti möchte, dass Ihr Oberanführer Schmetterfaust und 10 Raufer der Ango\'rosh tötet. Kehrt zur Oreborzuflucht zurück, wenn Ihr die Aufgabe erfüllt habt.', },
  },
  [9840] = {
    'Einschätzung der Situation',
    {'Jetzt, da wir - oder besser Ihr - einen Weg zurück in Medivhs\' Turm gefunden haben, müssen wir als Erstes herausfinden, wie die Situation im Inneren aussieht.|n|nEine unserer Agentinnen hat es geschafft, sich in Karazhan einzuschleusen und hielt ihre Beobachtungen in verschlüsselten Aufzeichnungen fest. Unglücklicherweise wurden wir über ihren Tod informiert, kurz bevor Karazhan geschlossen wurde. Koren, der Schmied von Karazhan, wird von uns bezahlt. Auch wenn er kein Mitglied des Violetten Auges ist, wird er uns sicher helfen können, Keannas Aufzeichnungen zu finden. Sucht ihn innerhalb von Karazhan.', },
    {'Findet Koren in Karazhan.', },
  },
  [9841] = {
    'Tückische Mücken',
    {'Ich kann mit diesem infernalen Gesumme nicht arbeiten! Könnt Ihr es hören?|n|nIch bekomme es nicht mehr aus meinem Kopf! Ich weiß genau, wer dieses Geräusch verursacht, Sumpflichtbluter! Das Geräusch kommt immer vom Süden und vom Westen des Dorfs her.|n|nSie sind zu groß, um sie mit einer Fliegenklappe zu erschlagen, sie unter dem Fuß zu zerquetschen oder fortzuwedeln. Der einzige Weg dieses fürchterliche Dröhnen zu beenden ist sie zu töten. Mir ist ganz egal, wie Ihr es tut, $N, aber bringt sie zum Schweigen!', },
    {'Tötet 8 Sumpflichtbluter und kehrt dann zu Gambarinka in Zabra\'jin zurück.', },
  },
  [9842] = {
    'Die schärfsten Klingen',
    {'Das feuchte Klima der Marschen hat meine metallenen Werkzeuge stark in Mitleidenschaft gezogen. Das macht die Holzarbeiten schwerer als sonst, weshalb ich nun ganz auf Metallklingen verzichte.|n|nEs hat sich herausgestellt, dass die Marschenfangschlitzer im Süden und im Westen über Klingen verfügen, die schärfer sind als jede Metallklinge, die ich je besessen habe. Sie rosten auch nicht und nutzen sich nicht ab. Es ist nur ein wenig schwer, sie an einem Griff zu befestigen, aber ich glaube, ich habe dieses Problem bereits gelöst. Ich wäre Euch für jede Klinge, die Ihr mitbringen könnt, sehr dankbar.', },
    {'Bringt 10 Marschenfangschlitzerklingen zu Gambarinka in Zabra\'jin.', },
  },
  [9843] = {
    'Keannas Aufzeichnungen',
    {'Wen sucht Ihr noch gleich? Keanna?|n|nIch habe einst jemanden mit diesem Namen getroffen. Sie wohnte oben in den Gästezimmern. Das hätte ich nicht verraten dürfen, oder?|n|nSagtet Ihr, Ihr gehört zum Violetten Auge? Nein, davon habe ich noch nie gehört.|n|nIch muss jetzt zurück an die Arbeit, wenn es Euch nichts ausmacht.|n|n<Koren scheint Euch schon vergessen zu haben.>', },
    {'Durchsucht die Gästezimmer in Karazhan nach Keannas Aufzeichnungen und bringt sie zu Erzmagier Alturus außerhalb von Karazhan.', },
  },
  [9844] = {
    'Eine dämonische Präsenz',
    {'Keannas letzte Einträge bestätigen unseren Verdacht, dass sich eine dämonische Präsenz in Karazhan befindet.|n|nSie hat die Ankunft eines Agenten der Brennenden Legion entdeckt, der sich in der Nähe der Turmspitze aufhalten soll.|n|nIhr Eintrag endet hier.|n|nKarazhan ist ein sehr wichtiger Ort, $C. Es ist ein Portal in den Nether, ein Leuchtfeuer, das in andere Welten scheint. Wenn es in falsche Hände gerät, sind die Folgen unvorstellbar. Das Eindringen der Dämonen muss unbedingt aufgehalten werden. Und außer Euch, $N, hat niemand einen Schlüssel.', },
    {'Erzmagier Alturus möchte, dass Ihr die dämonische Präsenz an der Turmspitze von Karazhan zerstört.', },
  },
  [9845] = {
    'Anglerunglück',
    {'Welch Erleichterung, dass ich endlich an einem Ort mit Wasser angekommen bin! Ich hatte schon Angst, dass es keine anständigen Fischgründe hier in der Scherbenwelt gibt.|n|nJetzt bin ich doch froh, dass ich meine Angelausrüstung mitgenommen habe. Und das Fischen läuft soweit auch ganz gut, wenn da nicht diese nichtsnutzigen Fennklauenhauer im Schlangensee wären.|n|nSie verscheuchen mir nicht nur die Fische, sondern sind auch noch frech genug, mir die Köder direkt vom Haken zu stehlen! Ich verbringe mehr Zeit damit, neue Köder anzubringen, als tatsächlich etwas zu fangen!', },
    {'Tötet 10 Fennklauenhauer und kehrt dann zu Zurjaya in Zabra\'jin zurück.', },
  },
  [9846] = {
    'Geister der Wildfenn',
    {'Der mächtigste Stamm der Verirrten in den Marschen, der Wildfennstamm, soll eine mächtige Medizin besitzen. Vielleicht ist an solchen Gerüchten nichts Wahres dran, aber ich muss allem nachgehen, was mir dabei helfen kann, die Geister dieser Welt zu lenken.|n|nFindet die Mystiker, Jäger und Druiden von Wildfenn, $N, und nehmt Euch ihre Totems. Alles, was ich wissen muss, werde ich aus den Schnitzereien erfahren können.', },
    {'Bringt 10 Schutztotems von Wildfenn zu Seherin Janidi in Zabra\'jin.', },
  },
  [9847] = {
    'Ein verbündeter Geist?',
    {'Wir müssen herausfinden, welche Kräfte dieser Schlangengeist von Wildfenn besitzt und ob wir sie für unsere Zwecke einsetzen können. Stellt Euch nur vor, was ich alles tun könnte, wenn ich über einen Geist der Scherbenwelt befehligen könnte!|n|nNehmt dieses Totem und begebt Euch an den Fuß der Treppe zu den Ruinen von Boha\'mu. Verankert das Totem dort in der Erde, den Rest wird es selbst erledigen. Der Geist dürfte nicht wissen, wer das Totem benutzt hat, bis er sich manifestiert hat.', },
    {'Bringt das Wildfenntotem an den Fuß der Treppe in den Ruinen von Boha\'mu und verankert es im Boden. Berichtet Seherin Janidi in Zabra\'jin von Euren Beobachtungen.', },
  },
  [9848] = {
    'Geheimnisse des Dolchfennstamms',
    {'Käfer, Käfer, Käfer! Die Marschen sind voll davon, und meine Gefährten hier scheinen ganz besessen von ihnen zu sein.|n|nNun, ich habe genug von Käfern! Etwas viel Aufregenderes hat mein Interesse geweckt. Im Westen gibt es ein Dorf der Verirrten, das Dolchfenn genannt wird.|n|nDer gesamte Stamm besteht aus hochbegabten Auftragsmördern. Ich habe gesehen, wie sie ein bestimmtes hochwirksames Gift mischen und verwenden. Ich würde liebend gerne mehr darüber erfahren, aber dazu bräuchte ich eine Abschrift des Rezepts und eine Phiole mit einer Probe des Gifts.', },
    {'Bringt das Gifthandbuch von Dolchfenn und eine Giftphiole von Dolchfenn zu Timothy Daniels in der Oreborzuflucht.', },
  },
  [9849] = {
    'Die Maskerade durchschauen',
    {'<Gordawg bricht einen ebenholzfarbenen Fels von seinem Rücken ab.>|n|nIch gewähre Euch ein Stück Wut der Erde. Nehmt Gordawgs Fels und werft ihn auf den Giftfels. Zerschlagt ihre Hüllen um die Wahrheit zu erfahren. Vernichtet die Diener des Thronräubers und kehrt mit dem Namen zu Gordawg zurück.|n|nIhr findet die zerschlagenen Elemente am Ende der Welt. Südwesten.', },
    {'Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr 30 Diener von Gurok tötet.', },
  },
  [9850] = {
    'Beherrschen der Grollhufjagd',
    nil,
    nil,
  },
  [9851] = {
    'Beherrschen der Grollhufjagd',
    {'Das Grollhufweibchen Banthar ist der meistgefürchtete und am schwersten zu fassende Grollhuf der gesamten Scherbenwelt. Sie ist außerdem das Exemplar mit dem längsten Fell ihrer Gattung.|n|nMan sagt, sie treibt sich auf den Geisterfeldern in der Nähe des Oshu\'gun herum.|n|nBringt mir ihr Horn, um mir endgültig Euer Können in den Jagdkünsten zu beweisen.', },
    {'Erlangt das Horn von Banthar und kehrt anschließend zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand zurück.', },
  },
  [9852] = {
    'Die ultimative Beute',
    {'Die Königin aller Tiere in Nagrand ist Zahna. Sie ist ein riesiger Elekk von der Sorte, wie Ihr sie woanders nie zu sehen bekommen werdet!|n|nIhr tut gut daran, Euch bei dem Namen zu erschrecken. Bach\'lor, Aaskralle und Banthar sind nichts im Vergleich zu ihr. Man sagt, dass sie sich auf einer riesigen Klippe weit im Südwesten in der Nähe des Oshu\'gun aufhält. Bringt mir ihr Herz, wenn Ihr Euch traut.|n|nWollt Ihr mir einen Brief für Eure Familie dalassen, falls Ihr, was sehr wahrscheinlich ist, nicht zurückkommt?', },
    {'Bringt das Herz von Zahna zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand.', },
  },
  [9853] = {
    'Gurok der Thronräuber',
    {'Gurok muss gerufen werden. Ihr ruft Gurok und Ihr vernichtet.|n|nIhr müsst zum Totschlägerhügel im Nordwesten gehen und suchen, wo Oger Gurok verehren. Ihr setzt Ogerschädel von Totschläger auf Guroks irdenes Brandmal. Nur dann kommt Gurok. Sieben Schädel.|n|nWenn Ihr lebt, dann bringt Guroks irdenen Kopf zu Gordawg. Gordawg zerschmettert Kopf.|n|n<Gordawg beißt die Zähne so fest zusammen, dass der Boden unter Euren Füßen bebt.>', },
    {'Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr Gurok den Thronräuber zerstört und Guroks irdenen Kopf besorgt.', },
  },
  [9854] = {
    'Beherrschen der Windrocjagd',
    {'Lebt Ihr genauso für die Jagd wie ich, $C? Sucht Ihr die Ruhe, die Euch überkommt, wenn Ihr Euch an Eure Beute heranpirscht? Wisst Ihr, was es bedeutet, die letzten Herzschläge der erlegten Beute zu ehren? Ich werde Euch helfen, dies zu erreichen.|n|nNagrand ist ein blühendes Land, voller Leben inmitten dieser zerschlagenen Welt. Erlegt ein paar Windrocs und dann unterhalten wir uns weiter.|n|nIhr könnt sie an vielen Orten um unser Lager herum finden.', },
    nil,
  },
  [9855] = {
    'Beherrschen der Windrocjagd',
    {'Ihr müsst immer im Training bleiben, wenn Ihr eines Tages die mächtigste Beute überhaupt erlegen möchtet! Jetzt seid Ihr noch nicht dafür bereit, aber ich werde Euch auf den richtigen Weg bringen.|n|nEs gibt noch eine tödlichere Art von Windrocs. Messt Euch an den gefräßigen Windrocs! Ihr findet sie im Herzen von Nagrand, im Süden und im Südwesten.', },
    nil,
  },
  [9856] = {
    'Beherrschen der Windrocjagd',
    {'Ihr seid bereit, $C. Bereit Euch der Mutter aller Windrocs zu stellen, Aaskralle! Nachdem Ihr so viele ihrer Kinder getötet habt, gebietet die Ehre, dass ihr eine Chance auf Rache gewährt wird. Ihr findet sie bei den großen Windrocs weit im Westen.|n|nWenn Ihr überleben solltet, bringt mir ihr Auge.', },
    {'Bringt das Auge von Aaskralle zu Fitz bei Nesingwarys Safari in Nagrand.', },
  },
  [9857] = {
    'Beherrschen der Talbukjagd',
    {'Ich habe heute keine Lust zu jagen. Könnt Ihr das für mich übernehmen?|n|nIch habe Hemet gesagt, dass ich mich um ein paar von den Talbuks kümmern würde, die hier überall herumlaufen. Die Böcke sind besonders gut zu jagen. Ihr könnt sie in kleinen Gruppen unter den Bäumen in der Nähe finden.|n|nDenkt Ihr, Ihr könntet das für mich tun?', },
    nil,
  },
  [9858] = {
    'Beherrschen der Talbukjagd',
    {'Diese verdammte Schramme macht mir echt zu schaffen. Also, habt Ihr Lust, nochmals...<hust>...für mich einzuspringen?|n|nDieses Mal werdet Ihr ein paar Dornzehrer erlegen. Sie sind härter und gerissener als die Hirsche, also seid auf der Hut. Sucht sie...<hust>..unter den Bäumen in den mittleren Gebieten Nagrands im Süden und Westen.|n|nAuf, geht los und...<hust>.. zeigt Hemet aus welchem Holz Ihr geschnitzt seid. Mir wird es schon gut gehen.', },
    nil,
  },
  [9859] = {
    'Beherrschen der Talbukjagd',
    {'<Schlimmer Husten.>|n|nMacht Euch keine Sorgen um...<hust>... mich. Mir geht es gut. Es ist nur ein...<hust>... Kratzer.|n|nDennoch müsst Ihr...<hust>... nochmal für mich...<hust>... einspringen.|n|nIhr müsst den großen Bach\'lor, König der Hirsche...<hust>... finden.|n|nBringt mir einen seiner Hufe...<hust>, <hust>... als Beweis.|n|nEr führt seine Herde...<hust>... weit im Westen von Nagrand.', },
    {'Besorgt den Huf von Bach\'lor und bringt ihn zu Harold Fährten bei Nesingwarys Safari in Nagrand.', },
  },
  [9860] = {
    'Neue Anweisungen',
    {'Kehrt sofort zu Cedric zurück, $N. Die Unterstützung, die Ihr dem Violetten Auge geleistet habt, wird nicht unbelohnt bleiben.|n|nHaltet von uns und unserer Organisation was Ihr wollt, $C, aber in der Gunst der Erzmagier von Dalaran zu stehen ist nichts, was Ihr je bereuen werdet.', },
    nil,
  },
  [9861] = {
    'Der heulende Wind',
    {'Die formlose Elementarluftgestalt spricht in einer Sprache zu Euch, die Ihr nicht versteht. Ihr glaubt, dass es die Sprache der Elemente ist, Kalimag. Vielleicht kann Euch jemand beim Thron der Elemente mit dieser ungewöhnlichen Entdeckung weiterhelfen.', },
    {'Sucht beim Thron der Elemente nach jemandem, der Kalimag sprechen kann und zeigt der Person den heulenden Wind.', },
  },
  [9862] = {
    'Bösewichte der Finsterblut',
    {'Der Finsterblutstamm fängt die Luftgeister ein und quält sie! Die Finsterblut gehören zu meinem Volk. Sie sind ein Stamm von Zerschlagenen, der dem bösen Musel\'ek, dem Sumpflord des Echsenkessels, dient.|n|nDer Luftgeist sagt, dass die Verderber der Finsterblut andere Luftgeister fangen und sie benutzen, um Chaos in den Reihen der Elemente zu säen. Wie es aussieht haben die Finsterblut vor Kurzem ein Orcdorf im Südwesten namens Sonnenwind geplündert und benutzen nun mächtige Elementarmagie, um den See aufzuwühlen. Sucht die Verderber und vernichtet sie!', },
    nil,
  },
  [9863] = {
    'Abscheulicher Götzendienst',
    {'Ohne Führung sind wir von allen Seiten angreifbar! Die niederträchtigen Finsterblut hätten keinen besseren Zeitpunkt auswählen können, um uns anzugreifen.|n|nIn den letzten Tagen mussten wir nicht weniger als fünf Angriffe von den Zerschlagenen ertragen! Sie haben sich sogar unserer Siedlung in dieser Gegend, Sonnenwind, bemächtigt.|n|nWir müssen zurückschlagen und ihnen zeigen, das wir ganz und gar nicht machtlos sind. Erschlagt die widerlichen Götzendiener und bringt mir ihre abscheulichen Götzen! Möge der Blitz sie treffen!', },
    nil,
  },
  [9864] = {
    'Der verschollene Kampftrupp',
    {'Nach dem letzten Angriff der Finsterblut hat eine Gruppe von Jünglingen sich aufgemacht, um uns zu rächen. Wir haben versucht sie aufzuhalten, aber ihre Wut hat sie blind werden lassen. Es ist nun eine Woche vergangen seit wir sie das letzte Mal gesehen haben.|n|nBitte, $R, Ihr müsst sie finden! Sie sind doch gerade erst erwachsen geworden. Wie können sie erwarten, diese Wilden besiegen zu können?|n|nSie haben die Straße nach Westen aus der Stadt genommen. Folgt dieser Straße und haltet nach Lebenszeichen unserer Jünglinge Ausschau.|n|nUnd $N, haltet Euch von Halaa fern, wenn Euch Euer Leben lieb ist. Dort ist Kriegsgebiet.', },
    {'Sucht den verschollenen Kriegstrupp von Garadar.', },
  },
  [9865] = {
    'Chroniken eines Kriegers',
    {'Ich kenne Euch nicht, Fremder, aber ich muss Euch um Hilfe bitten. Ich schäme mich dafür, aber ich bin nur ein einziger Orc.|n|nIn mir kochen Emotionen hoch, die ich vorher nie gekannt habe. Ich.. Ich will Rache. Blut für Blut. Kennt Euer Volk dieses Gefühl? Ich möchte meine Axt nehmen und meine Feinde in Stücke schlagen. Meine Waffe schwingen, bis meine Arme nicht mehr können und erschlaffen.|n|nDer Sonnenwindposten ist gleich südlich von dieser Prozession hier. Dort werdet Ihr unsere Feinde finden. Tötet sie... Tötet sie alle...', },
    nil,
  },
  [9866] = {
    'Weiter...',
    {'Würdet Ihr mir eine letzte Ehre erweisen, $N? Ich möchte nicht nach Garadar zurück. Ich glaube, dass mein Schicksal woanders liegt, dass ich einst höheren Zielen folgen werde.|n|nBitte geht zu Scharfseher Corhuk und sagt ihm, dass ich nicht zurückkehren werde. Dass ich nicht zurückkehren kann. Ich muss weiterziehen... Er wird es verstehen.', },
    {'Bringt die Nachricht zu Scharfseher Corhuk in Garadar.', },
  },
  [9867] = {
    'Anführer der Finsterblut...',
    {'Wir haben in den letzten Wochen viele Freunde verloren.|n|nSchon seit Jahrzehnten kämpfen wir gegen die Oger aus Nagrand, aber nun ist eine neue Bedrohung aufgetaucht. Der Finsterblutstamm der Zerschlagenen hat unser Fischerdorf im Südwesten, den Sonnenwindposten, angegriffen und alle Orcs, die dort lebten, getötet oder vertrieben.|n|nDie anderen sind der Meinung, dass man sie einfach wahllos töten sollte. Ich bin jedoch davon überzeugt, dass man ihren Anführer töten muss. Ich weiß zwar nicht, wer ihr Anführer ist, aber ich schätze, Ihr werdet es merken, wenn Ihr ihn seht.', },
    {'Bringt Ortor von Finsterbluts Kopf zu Scharfseher Margadesh in Garadar.', },
  },
  [9868] = {
    'Das Totem von Kar\'dash',
    {'Habt Dank, Fremder. Wenn Ihr nicht gewesen wärt, hätten sie mich sicherlich getötet.|n|nIch wurde vor drei Nächten von diesen Finsterblut bei einem Nachtangriff auf Garadar entführt. Was ich seitdem herausgefunden habe, wird wahrscheinlich die ganze Scherbenwelt in ihren Grundfesten erschüttern: diese Finsterlinge versuchen, das Totem von Kar\'dash wiederzuerlangen! Wir können nicht zulassen, dass das Totem in die Hände der Finsterblut fällt!|n|nIhr müsst mir helfen zu fliehen. Und Fremder, falls ich es nicht bis Garadar schaffe, müsst Ihr Garrosh erzählen, was hier passiert ist...', },
    {'Begleitet den festgehaltenen Mag\'har aus dem Sonnenwindposten hinaus. Sprecht mit Garrosh in Garadar, wenn Ihr erfolgreich wart.', },
  },
  [9869] = {
    'Der Thron der Elemente',
    {'Grüße, $R. Ich bin Ioki, Elementarist des Irdenen Rings. Ich bin nach Telaar gekommen, um die Kurenai über den Status der Elemente zu informieren.|n|nKann ich Euch um einen Gefallen bitten? Könntet Ihr zum Thron der Elemente in den nördlichen Hügeln Nagrands, hinter dem Himmelsweisensee, reisen und Elementaristin Sharvak ausrichten, dass ich heil in Telaar angekommen bin? Sie wird Euch für diesen kleinen Gefallen sicher entlohnen.', },
    {'Elementarist Ioki möchte, dass Ihr zum Thron der Elemente reist und mit Elementaristin Sharvak sprecht.', },
  },
  [9870] = {
    'Der Thron der Elemente',
    {'Grüße, $R. Ich bin Yal\'hah, Elementarist des Irdenen Rings. Ich bin nach Garadar gekommen, um die Mag\'har über den Status der Elemente zu informieren.|n|nKann ich Euch um einen Gefallen bitten? Könntet Ihr zum Thron der Elemente in den nördlichen Hügeln Nagrands, hinter dem Himmelsweisensee, reisen und Elementaristin Sharvak ausrichten, dass ich heil in Garadar angekommen bin? Sie wird Euch für diesen kleinen Gefallen sicher entlohnen.', },
    {'Elementarist Yal\'hah möchte, dass Ihr zum Thron der Elemente reist und mit Elementaristin Sharvak sprecht.', },
  },
  [9871] = {
    'Eindringlinge der Finsterblut',
    {'Auf dem Pergament ist eine grob gezeichnete Karte von Nagrand zu sehen. Anstelle von Telaar ist ein großes rotes X auf der Karte vermerkt. Es sieht aus, als planten die Feinde einen Angriff auf die Stadt. Bringt die Invasionspläne der Finsterblut zu Arechron in Telaar.', },
    nil,
  },
  [9872] = {
    'Eindringlinge der Finsterblut',
    {'Auf dem Pergament ist eine grob gezeichnete Karte von Nagrand zu sehen. Anstelle von Garadar ist ein großes rotes X auf der Karte vermerkt. Es sieht aus, als planten die Feinde einen Angriff auf die Stadt. Bringt die Invasionspläne der Finsterblut zu Garrosh in Garadar.', },
    {'Bringt die Invasionspläne der Finsterblut zu Garrosh.', },
  },
  [9873] = {
    'Mein alter Freund Ortor...',
    {'Diese Angriffpläne wurden von jemandem geschrieben, den ich einst kannte. Ortor von Finsterblut, ein adliger Zerschlagener, bewandert in der Beherrschung der Elemente, der nun den dummen, stinkenden Lakai für Sumpffürst Musel\'ek spielt.|n|nDie Pläne besagen, dass sie ein Orcdorf nordwestlich von hier, das als Sonnenwindposten bekannt ist, eingenommen haben.|n|nReist zum Sonnenwindposten und erlöst die Welt von Ortor von Finsterblut. Es geschieht zum Wohl aller...', },
    {'Arechron in Telaar in Nagrand möchte, dass Ihr Ortor von Finsterblut tötet.', },
  },
  [9874] = {
    'Die Ausbreitung eindämmen',
    {'Otonbu der Weise in Telaar in Nagrand möchte, dass Ihr die Fackel des flüssigen Feuers benutzt, um 10 Leichen von Bewohnern von Sonnenwind zu zerstören. Bringt die Fackel des flüssigen Feuers zurück, wenn Ihr fertig seid.', },
    {'Otonbu der Weise in Telaar in Nagrand möchte, dass Ihr die Fackel des flüssigen Feuers benutzt, um 10 Leichen von Bewohnern von Sonnenwind zu zerstören. Bringt die Fackel des flüssigen Feuers zurück, wenn Ihr fertig seid.', },
  },
  [9875] = {
    'Nicht katalogisierte Gattung',
    {'Lauranna muss diese besondere Pflanze übersehen haben. Ihr seid Euch sicher, dass Ihr eine Gattung gefunden habt, die noch nicht in Laurannas Buch katalogisiert ist. Ihr solltet sie ihr am besten zeigen, um zu sehen, was sie davon hält.', },
    {'Bringt die nicht katalogisierte Gattung zu Lauranna Thar\'well in der Zuflucht des Cenarius in den Zangarmarschen.', },
  },
  [9876] = {
    'Fehlgeschlagene Operation',
    {'Ich habe eine kleine Gruppe von Druiden losgeschickt, um den Ablauf, den Ihr im Schlangensee gefunden habt, zu untersuchen. Eigentlich hätten sie kurz darauf zurückkommen müssen. Nun ja, sie sind nicht zurückgekehrt.|n|nIhr zählt zu unseren stärksten Verbündeten. Bitte sucht sie und findet heraus, was ihnen zugestoßen ist.', },
    nil,
  },
  [9877] = {
    'Ein Regenerationsgebräu',
    {'Der Kampf gegen die Geißel verläuft nicht ohne Opfer. Viele fallen jeden Tag, doch einige erwartet ein noch schlimmeres Schicksal.|n|nOft nimmt sie Gefangene. Der Tod wäre dem, was sie in der Todesfestung erwartet, vorzuziehen. Sie werden verhört und gefoltert, während sie unter dem Einfluss eines schrecklichen, willensbrechenden Giftes stehen.|n|nApotheker Renzithen in Tristessa hat ein Gegenmittel entwickelt; geht zu ihm und holt das Regenerationsgebräu.', },
    {'Sprecht mit Apotheker Renzithen in Tristessa.', },
  },
  [9878] = {
    'Die Lösung des Problems',
    {'Das Auftauchen der Finsterblut in Nagrand hatte einen sehr negativen Einfluss auf unsere Umwelt. Die Elemente sind aufgebracht, was wiederum die Wildtiere stört. Und noch viel schlimmer: die Zerstörung des Sonnenwindpostens hat die Feindschaft der Orcs gegen mein Volk neu entflammt.|n|nDie Kurenai sind zwar ein ganz anderer Stamm als die Finsterblut, aber für einen Orc ist ein Zerschlagener ein Zerschlagener.|n|nWir müssen versuchen, dieses Dilemma zu lösen. Reist nach Nordwesten zum Sonnenwindposten und erledigt das Finsterblutproblem.', },
    nil,
  },
  [9879] = {
    'Das Totem von Kar\'dash',
    {'Ich wäre schon tot, wenn Ihr nicht vorbeigekommen wärt, Fremder. Sie haben schon so viele Kurenai auf der Suche nach einem verschollenen Relikt getötet.|n|nSie suchen das Totem von Kar\'dash. Ich kann nicht verstehen, warum sie glauben, dass wir etwas über dieses Totem wüssten. Ist ein Totem nicht eine typisch orcische Gerätschaft?|n|nArechron muss davon erfahren. Vielleicht weiß er, warum die Finsterblut Kurenai verschleppen und foltern, um Informationen über ein orcisches Relikt zu erfahren.|n|nLasst uns gehen bevor noch mehr kommen.', },
    {'Begleitet den gefangenen Kurenai aus dem Sonnenwindposten. Sprecht mit Arechron in Telaar, wenn Ihr erfolgreich wart.', },
  },
  [9882] = {
    'Von Dieben stehlen',
    {'Nexusprinz Haramad hat uns verboten, mit der Arbeit im Oshu\'gun loszulegen, weil er einen bestimmten mächtigen Naaru nicht verärgern will. Das hält natürlich unsere ganze Operation auf.|n|nIch glaube aber, dass ich ein Hintertürchen gefunden habe.|n|nSeht Ihr, wir sind nicht die einzigen Astralen, die von diesem riesigen Diamanten angelockt werden. Ein Dieb namens Gava\'xi hat eine Gruppe von Schurken in den Oshu\'gun geführt, und sie haben begonnen, große Teile aus dem Kristall herauszuschlagen.|n|nEure Aufgabe, $R, ist es, dorthin zu gehen und unser rechtmäßiges Eigentum zurückzufordern.', },
    {'Besorgt 10 Kristallfragmente von Oshu\'gun und bringt sie zu Gezhe beim Aerissteg in Nagrand.', },
  },
  [9883] = {
    'Noch mehr Kristallfragmente',
    nil,
    nil,
  },
  [9884] = {
    'Mitgliedervorteil',
    nil,
    nil,
  },
  [9885] = {
    'Mitgliedervorteil',
    nil,
    nil,
  },
  [9886] = {
    'Mitgliedervorteil',
    nil,
    nil,
  },
  [9887] = {
    'Mitgliedervorteil',
    nil,
    nil,
  },
  [9888] = {
    'Der unfähige Anführer',
    {'Ich bin dem sicheren Tode entronnen, habe einen feigen Angriff bei Nacht von den Felsfäusten auf mein Dorf überlebt.|n|nAber ich frage Euch, Fremder, wozu?|n|n<Jorin zeigt auf Garrosh.>|n|nEr hat uns jegliche Unterstützung verweigert. Oger toben durch meine Stadt und er sitzt nur da und heult den Mond an. Was ist aus uns geworden? Was wird aus uns werden?|n|nIch habe einen Späher, Kilrath, zum Dorf, den jetzigen Ruinen des Blutenden Auges, geschickt. Könnt Ihr ihn bitte suchen und unterstützen? Er versteckt sich an der Grenze zwischen Nagrand und Terokkar.', },
    {'Jorin Totauge möchte, dass Ihr Kilrath sucht und mit ihm sprecht.', },
  },
  [9889] = {
    'Nicht den Fetten töten!',
    {'Ich beobachte diese Kreaturen nun schon seit Tagen. Der Fette sagt, dass er auf etwas wartet. Worauf bleibt jedoch ein Geheimnis.|n|nIch habe einen Plan, aber er erfordert ein wenig Brutalität von Eurer Seite. Ihr werdet einige seiner Untertanen töten müssen und ihn dann fast tot schlagen. Wenn Ihr das tut, bin ich sicher, dass er uns alles erzählen wird, was wir wissen wollen.', },
    {'Kilrath in den Wäldern von Terokkar möchte, dass Ihr 10 Eindringlinge der Felsfäuste tötet und Unkor den Rücksichtslosen so lange schlagt, bis er redet.', },
  },
  [9890] = {
    'Erfolg!',
    {'Seit vielen Jahren hatten die Felsfäuste die Herrschaft über alle Oger der Scherbenwelt. Die Oger waren unter Krol vereint und zufrieden mit den Ländereien, die sie erhalten hatten. In den letzten Monaten haben wir jedoch viele Oger an einen Klan namens Totschläger verloren. Die Totschläger haben den größten Teil unseres Landes in Nagrand in Beschlag genommen und viele unserer Leute getötet.|n|nWir hatten keine andere Wahl als dieses Dorf einzunehmen. Wir werden ausgerottet...|n|nKrol ist verschollen und die Felsfäuste sind in Aufruhr. Lantresor von der Klinge hat in seiner Abwesenheit die Führung übernommen.', },
    {'Teilt Kilrath in den Wäldern von Terokkar die Informationen, die Ihr aus dem Oger geprügelt habt, mit.', },
  },
  [9891] = {
    'Weil Kilrath ein Feigling ist',
    {'Erzählt Jorin in Garadar, was Ihr gehört habt. Ich bin mir sicher, dass er nicht erfreut sein wird zu hören, dass unser Dorf zerstört und viele unserer Leute getötet wurden, weil die Oger mehr Platz brauchen.|n|nMögen die Ahnen über Euch wachen... Ich werde mich in den Büschen verstecken, falls Ihr mich noch braucht.', },
    {'Erzählt Jorin Totauge in Garadar in Nagrand, was Ihr aus Unkor herausprügeln konntet.', },
  },
  [9892] = {
    'Noch mehr Obsidiankriegsperlen',
    nil,
    nil,
  },
  [9893] = {
    'Obsidiankriegsperlen',
    {'Während wir hier darauf warten, dass wir endlich am Oshu\'gun graben können, verlieren wir so viel Gewinn, $N.|n|nZum Glück habe ich eine andere Einkommensquelle entdeckt. Die Oger von Nagrand tragen Kriegsperlen aus Obsidian, ein Gestein, das in vielen anderen Welten sehr wertvoll ist.|n|nZerid musste sich aus Sicherheitsgründen bereits mit diesen Rohlingen auseinandersetzen. Betrachtet die Kriegsperlen also als kleinen Bonus. Oder noch besser, betrachtet sie gar nicht und bringt sie mir einfach.', },
    {'Bringt 10 Obsidiankriegsperlen zu Gezhe beim Aerissteg in Nagrand.', },
  },
  [9894] = {
    'Schützt die Behüter',
    {'Während Eurer Reisen habt Ihr vielleicht ein paar der Behüter der Expedition getroffen. Sie kümmern sich hauptsächlich um die Feldstudien, das heißt die Dokumentation der einzigartigen Bewohner der Marschen, das Sammeln von Proben und die Kontaktaufnahme mit den vernunftbegabten Arten.|n|nDie Sicherheit der Behüter ist von äußerster Wichtigkeit, $C. Wir mussten die Behüter, die sich aufgemacht haben, um die Funggorhöhle zu erkunden, wegen Angriffen von Sumpfmonstern zurückrufen. Aufseher Hamuht ist der Meinung, dass wir ihren Angriffen ein schnelles Ende machen könnten, wenn wir ihren Anführer, Lord Klaq, töten.', },
    {'Tötet Lord Klaq und kehrt danach zu Windrufer Schwarzhuf in der Zuflucht des Cenarius zurück.', },
  },
  [9895] = {
    'Aus dem Gleichgewicht geraten',
    {'Habt Ihr die Umgebung genau betrachtet, $N? Dies ist eine dahinsiechende Landschaft, die verzweifelt versucht ihr Gleichgewicht zu halten und den Kampf verliert.|n|nWenn man weiß, worauf man achten muss, kann man die Symptome deutlich erkennen. Einige Vertreter bestimmter Gattungen überholen ihre Artgenossen, was das Wachstum angeht, bereits und werden aggressiv.|n|nEin gutes Beispiel für so ein unkontrolliertes Wachstum ist der Marschenläufer Sumpfschläger. Wenn ihr ihn selbst sehen wollt, müsst Ihr nur zu den Wasserwegen südlich der Zuflucht gehen.|n|nAber haltet Euch bereit, Euch zu verteidigen. Diese Kreatur kennt kein Erbarmen.', },
    {'Sucht und vernichtet Sumpfschläger und kehrt dann zu Lethyn Mondfeuer in der Zuflucht des Cenarius zurück.', },
  },
  [9896] = {
    'Schwarzsichels Fluch',
    {'Bei Khaz\'goroths brennendem Nabel, ist das heiß hier! Ich kann es der ersten Gruppe nicht verübeln, dass sie abgereist sind, aber wisst Ihr, es war nicht die Hitze, die sie verjagt hat. Nein, es war Schwarzsichel, auch wenn sie das natürlich nicht zugeben möchten.|n|nSie hatten ihr Lager südlich von den leuchtenden Draeneitürmen im Westen aufgeschlagen, gleich nördlich von Wildfenn, als die riesige Wespe aus dem Nichts auftauchte und sie angriff! Ich kann es kaum erwarten, ihre Gesichter zu sehen, wenn ich den Stachel des Biests nach Eisenschmiede bringe!', },
    {'Bringt Schwarzsichels Stachel zu Ausgrabungsleiter Conall in Telredor.', },
  },
  [9897] = {
    'Ich bin gerettet!',
    {'Es macht mir nichts aus zu teilen. Ich bin nur froh, dass ich vor diesem Widerling Diebus sicher bin! Und ich habe Tonnen von Tierhäuten in den Zangarmarschen gesammelt, es ist also überhaupt kein Problem!', },
    {'Gebt Harold Fährten bei Nesingwarys Safari in Nagrand das Bündel mit Tierhäuten.', },
  },
  [9898] = {
    'Liebe ist ein großer Stachel',
    {'Sie wird mir gehören. Oh ja, sie wird mir gehören.|n|nIst Magasha nicht einfach die schönste Trollfrau, die Ihr je gesehen habt? Ich muss einen Weg finden, ihr Herz zu gewinnen. Ja sicher, sie hat ein Auge auf Zurai geworfen, aber das wird sich ändern. Mein narrensicherer Plan wird schon dafür sorgen.|n|nIch muss nur einen Weg finden, ihr meine überlegenen Jagdkünste zu beweisen, und da kommt Ihr ins Spiel, mein Freund. Es gibt da eine riesige Sumpfwespe namens Schwarzsichel, die sich in der Gegend südlich der leuchtenden Draeneitürme im Westen herumtreibt. Bringt mir ihren Stachel und ich lasse meinen Charme spielen.', },
    {'Bringt Schwarzsichels Stachel zu Reavij im Sumpfrattenposten.', },
  },
  [9899] = {
    'Unerledigte Arbeit',
    {'Jemand muss Reavij zur Vernunft bringen! Er vernachlässigt seine Pflichten und verschwendet stattdessen all seine Energie darauf, meine Aufmerksamkeit zu erlangen. Ich habe versucht, ihn zu ignorieren und ihm gesagt, dass er damit aufhören soll. Aber nichts scheint zu helfen.|n|nBis er es endlich sein lässt, muss ich ständig hinter ihm aufräumen. Er hätte sich eigentlich um Sporenschwinge kümmern sollen, aber das Monster ist immer noch wohlauf. Wenn Ihr Zeit habt, könntet Ihr vielleicht in den westlichen Teil des Todesmoors gehen und den Segler töten? Ich kümmere mich in der Zwischenzeit um Reavij.', },
    {'Magasha im Sumpfrattenposten möchte, dass Ihr Sporenschwinge tötet.', },
  },
  [9900] = {
    nil,
    {'Die Anwesenheit von astralen Schurken in dieser Gegend mag Gezhe, der in allem eine Möglichkeit sieht, vielleicht erheitern, aber sie sind eine wirkliche Bedrohung für die Sicherheit unserer Unternehmung.|n|nIhr Anführer, Gava\'xi, ist ein gefährlicher Krimineller, und ich habe es zu meinem höchsten Anliegen gemacht, ihn zur Strecke zu bringen.|n|nWenn Ihr Euch nützlich machen wollt, dann zieht los und kümmert euch um Gava\'xi. Ich werde mich darum kümmern, dass Ihr angemessen entlohnt werdet.', },
    {'Tötet Gava\'xi in der Nähe des Oshu\'gun und kehrt dann zu Zerid beim Aerissteg in Nagrand zurück.', },
  },
  [9901] = {
    'Offene Rechnungen',
    {'Die erste Expedition, die die Liga losgeschickt hatte, berichtete von einem riesigen Sporensegler namens Sporenschwinge. Sie mussten sehr hastig aufbrechen, deshalb hatten sie keine Gelegenheit, das Tier umzubringen. Deshalb dachte ich mir, ich erledige das für sie.|n|nIn ihrem Bericht stand, dass die Kreatur sich im westlichen Teil des Todesmoors aufhält. Ich glaube Verteidiger Idaar erwähnte einmal, dass es sich nordöstlich von Telredor befindet.', },
    {'Ausgrabungsleiter Conall in Telredor möchte, dass Ihr Sporenschwinge tötet.', },
  },
  [9902] = {
    'Der Schrecken des Sumpflichtsees',
    {'Meine Reisen durch das Gebiet der Naga haben mir einen Eindruck vermittelt, wie schlimm es meinen unglücklichen Brüdern und Schwestern gehen muss. Am Sumpflichtsee im Südwesten habe ich beobachtet, welch tödliches Spiel einer der besonders bösartigen Zuchtmeister treibt. Er jagt seine Sklaven ins Wasser, wenn er weiß, dass Terrorklaue, ein riesiger Sumpfstrok, Hunger hat.|n|nDie Folgen brauche ich nicht weiter erläutern. Wir sind zu wenige, um die Naga direkt anzugreifen, aber wir können ihnen den Spaß verderben, indem wir ihr Haustier umbringen.', },
    {'Tötet Terrorklaue und kehrt dann zu Puluu in der Oreborzuflucht zurück.', },
  },
  [9903] = {
    'Der Größte von allen',
    {'Ihr seid zwar mit den meisten der kleineren Hydras fertiggeworden, aber ich glaube kaum, dass Mragesh von Eurer Vorstellung beeindruckt war. Er ist eine gerissene, grausame Bestie und hat schon so manchen Angler auf dem Gewissen.|n|nIch habe mir vorgenommen, die Letzte zu sein, die er je belästigt. Er soll sich tief im Schlangensee im Nordosten verstecken. Er ist schon Geschichte, aber das weiß er noch nicht.', },
    {'Tötet Mragesh und kehrt dann zu Zurjaya in Zabra\'jin zurück.', },
  },
  [9904] = {
    'Jagd auf Terrorklaue',
    {'Ich habe jeden erdenklichen Fisch in den Marschen gefangen, aber einer ist mir bisher entkommen. Sicher habe ich auch Aale und Morastflossenfrenzys gefangen. Aber als ich das letzte Mal am Sumpflichtsee war, hat einer angebissen, meine Schnur zerrissen und ist abgehauen.|n|nTerrorklaue wird er genannt, und ich werde nicht ruhen, bis er tot ist. Er ist zu groß um ihn mit einer Angel zu fangen, also müssen wir ihn wohl auf die altmodische Art umbringen.', },
    {'Tötet Terrorklaue und kehrt dann zu Zurjaya in Zabra\'jin zurück.', },
  },
  [9905] = {
    'Maktus Rache',
    {'Als Maktu letztes Mal auf Hydrajagd am Schlangensee war, wurde er von größter Hydra, die er jemals gesehen hat, angegriffen. Maktu hat nach seinem Speer gegriffen, aber es war schon zu spät. Er konnte gerade noch entkommen, bevor er zu Hydrafutter wurde.|n|nWer weiß? Vielleicht hat Maktu nächstes Mal nicht mehr so viel Glück. Maktu will, dass es kein nächstes Mal gibt. Werdet Ihr Maktu helfen, sich an Mragesh zu rächen?', },
    {'Sucht und tötet Mragesh und kehrt dann zu Maktu in der Oreborzuflucht zurück.', },
  },
  [9906] = {
    'Sag\'s mit Fäusten',
    {'Oger interessieren sich nur für das Eine: Macht. Wenn wir ihnen gegenüber Schwäche zeigen, werden sie sich das zum Vorteil machen und uns ausrotten.|n|nGarrosh ist vielleicht bereit dazu, die Hände in den Schoß zu legen und diese Hunde unser Land übernehmen zu lassen, aber ich bin es nicht! Ich möchte, dass Ihr den Totschlägern eine Nachricht zukommen lasst, die sie verstehen: Gewalt.|n|nReist zu den Ruinen der Brennenden Klinge südöstlich von hier und zeigt ihnen die Macht der Mag\'har.|n|nUnd $N, schaut bei den anderen vorbei, bevor Ihr geht.', },
    nil,
  },
  [9907] = {
    'Ein kühner Angriff',
    {'Direkt im Westen von hier findet Ihr das Halaanibecken. Im Becken befinden sich die Zwillingsschluchten von Nagrand: Nordwind und Südwind. Die Schocktruppen der Felsfäuste benutzen die Schluchten, um ihre Ogerhorte zu verstecken.|n|nIch möchte, dass Ihr diese Truppen aufspürt und sie alle im Namen der Mag\'har tötet.', },
    nil,
  },
  [9908] = {
    'Abzeichen der Ehrenfeste',
    nil,
    nil,
  },
  [9909] = {
    'Abzeichen von Thrallmar',
    nil,
    nil,
  },
  [9910] = {
    'Standarten',
    {'Wenn Ihr in die Ruinen der Brennenden Klinge reist, habe ich eine Aufgabe für Euch. Stellt diese Schlachtstandarten der Mag\'har an drei verschiedenen Orten in der Ogersiedlung auf. Vorzugsweise Orte, an denen man sie gut sehen kann. Haltet nach den großen lodernden Scheiterhaufen in den oberen Bereichen Ausschau. Stellt eine Standarte neben dem ersten, zweiten und dritten Scheiterhaufen der Brennenden Klinge auf.|n|nDie Standarten werden einen bleibenden Eindruck bei den Ogern hinterlassen, die die Schlacht verpasst haben.', },
    {'Mystiker Elakay\'gan in Garadar in Nagrand möchte, dass Ihr eine Schlachtstandarte der Mag\'har am ersten, zweiten und dritten Scheiterhaufen der Brennenden Klinge aufstellt. Bringt die übrigen Schlachtstandarten zurück, wenn Ihr fertig seid.', },
  },
  [9911] = {
    'Der Graf der Marschen',
    {'Dieses blutige Beißwerkzeug stammt von einem unglaublich großen Insekt. Der Netherrochen, zu dem es gehörte, war der größte, der je in den Zangarmarschen gesichtet wurde. Wenn man den Zustand der Beißwerkzeuge betrachtet, muss der Graf seine Nahrung von Aas auf frisches Fleisch umgestellt haben.|n|nDie Expedition des Cenarius wäre an einem solchen Objekt sicher sehr interessiert. Behüterin Leesa\'oh hat ein kleines Lager im Westen des Quaggkamms.', },
    nil,
  },
  [9912] = {
    'Die Expedition des Cenarius',
    {'Die Hauptexpedition des Zirkels des Cenarius in der Scherbenwelt ist als Expedition des Cenarius bekannt. Sie fing als kleines Projekt unter der direkten Kontrolle des Zirkels an, aber inzwischen ist sie zu einer großen und ziemlich unabhängigen Organisation herangewachsen.|n|nDie Anführerin der Expedition, Ysiel Windsänger, hat uns gebeten, Freiwillige zur Zuflucht des Cenarius in den östlichen Zangarmarschen zu schicken. Nehmt den Pfad nach Westen und Ihr werdet direkt dorthin gelangen.', },
    {'Sprecht mit Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen.', },
  },
  [9913] = {
    'Das Konsortium braucht Euch!',
    {'Meine Organisation, das Konsortium, sucht nach talentierten Personen, wie Ihr es seid. Ihr werdet kaum ehrlichere und härter arbeitende Astrale als uns in dieser Gegend hier finden.|n|nAlles, was wir Verlangen ist Loyalität, Einsatz und ein vernünftiges Maß an moralischer Flexibilität. Wenn Ihr Interesse habt, sprecht mit Gezhe, unserem Anführer hier. Ihr findet ihn beim Aerissteg, nördlich des Oshu\'guns.', },
    {'Meldet Euch bei Gezhe beim Aerissteg in Nagrand.', },
  },
  [9914] = {
    'Ein ganzer Kopf voll Elfenbein',
    {'Elfenbein ist ein heißbegehrtes Material. Ich habe Kunden von weither, die Schlange stehen, um es zu kaufen. Ich würde mich überreden lassen, meinen Gewinn mit Euch zu teilen.|n|nDie Stoßzähne der wilden Elekk in Nagrand haben genau die Qualität, die ich brauche. Bleibt jedoch von den Bullen fern, ihre Stoßzähne sind zu minderwertig.|n|nOh, und keine Sorge, das ist keine Wilderei, ich habe ein Abkommen mit den Orcs und den Draenei.|n|nAlso, sind wir uns einig?', },
    {'Sammelt 3 Paar Elfenbeinstoßzähne und kehrt dann zu Shadrek beim Aerissteg in Nagrand zurück.', },
  },
  [9915] = {
    'Noch mehr Elfenbein',
    nil,
    nil,
  },
  [9916] = {
    'Vorratskisten des Blutenden Auges',
    {'Die Totschläger haben die Vorräte, die sie aus unserem Dorf gestohlen haben, zu den Zwillingsschluchten von Nagrand gebracht, die sich westlich von hier im Halaanibecken befinden.|n|nWenn ihr Euch dort aufhalten solltet, haltet Ausschau nach den Vorratskisten. Wenn wir sie zurückbekommen könnten, würde das die Last, die die Matronen von Garadar zu tragen haben, erheblich mindern.', },
    nil,
  },
  [9917] = {
    'Kann ich meinen Augen trauen?',
    {'Kann ich meinen Augen trauen? Ist das da drüben tatsächlich eine Jagdgesellschaft von Ogern? Was treiben Oger denn so weit von Ihrem Hügel entfernt? Mir gefällt das gar nicht, $GFremder:Fremde;. Zuerst die Finsterblut und jetzt die Oger. Wir haben einfach nicht genug Leute, um mit all diesen Gefahren fertigzuwerden.|n|nKönntet Ihr die Ogersiedlung im Osten untersuchen? Ihr Lager ist etwa 200 Schritte östlich von hier. Wenn Ihr die Jäger der Felsfäuste seht, seid Ihr richtig. Tötet sie um an ihre Pläne zu kommen!', },
    {'Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr die Pläne der Felsfäuste besorgt.', },
  },
  [9918] = {
    'Nicht solange ich hier wache!',
    {'Die Schlachtpläne wurden von einem Leutnant der Oger geschrieben. Sein Name ist entweder Trocken oder Brocken.|n|n<Bintook dreht das Pergament und legt den Kopf schief.>|n|nEs könnte auch Billy sein.|n|nWie auch immer, ich denke, Ihr solltet dorthin zurückgehen und ein paar Takte mit Billy oder Trocken oder Brocken oder was weiß ich reden! Versucht diplomatisch zu sein. Wenn das nichts nützt, dann setzt eben etwas Muskelkraft ein.', },
    {'Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr mit Brocken sprecht. Kehrt zu Jägerin Bintook zurück, wenn Ihr die geforderten Informationen gesammelt habt.', },
  },
  [9919] = {
    nil,
    {'Ihr seid $Gein sehr netter:eine sehr nette:r; $R, $N. Nicht wie die anderen, die ich getroffen habe.|n|nIhr solltet den Rest meines Volkes kennenlernen, sie wären Euch für Eure Hilfe sehr dankbar. Bringt diese Sporenbeutel zu meinem Anführer, Msshi\'fn. Ihr findet ihn in Sporeggar, nördlich von hier.', },
    nil,
  },
  [9920] = {
    'Mo\'mor der Brecher',
    {'Ihr müsst sofort zu Mo\'mor! Ihr könnt ihn in der Mitte von Telaar finden, beim Springbrunnen. Erzählt ihm genau, was der Oger Euch gesagt hat!', },
    {'Jägerin Bintook in Telaar in Nagrand möchte, dass Ihr mit Mo\'mor dem Brecher redet.', },
  },
  [9921] = {
    'Die Ruinen der Brennenden Klinge',
    {'Die Jagdgesellschaften der Oger sind Vorboten für einen Angriff. Wir müssen sie schlagen, bevor sie eine Chance haben, genug Leute zu sammeln, um unsere Stadt einzunehmen.|n|nIhr werdet Euch wohl Eure Hände schmutzig machen müssen, $R.|n|nDie größte Ansammlung von Felsfäusten in dieser Gegend befindet sich in den Ruinen der Brennenden Klinge, direkt im Osten von Telaar, an der Grenze zu Terokkar. Geht dort hin und zeigt den Felsfäusten, dass Telaar sich niemals ihrem Willen beugen wird!', },
    nil,
  },
  [9922] = {
    'Die Zwillingsschluchten von Nagrand',
    {'Ihr habt eine gute Arbeit geleistet, $N. Seid Ihr bereit für noch mehr davon?|n|nIch habe Berichte über eine große Ansammlung von Felsfäusten in den zwei Schluchten von Nagrand, nordwestlich von hier im Halaanibecken.|n|nBegebt Euch zu den Schluchten und werdet mit den übrig gebliebenen Felsfäusten fertig.', },
    nil,
  },
  [9923] = {
    'Hilfe!',
    {'Findet den Schlüssel der Felsfäuste und befreit Corki. Sprecht mit Arechron in Telaar, wenn Ihr Erfolg hattet.', },
    {'Findet den Schlüssel der Felsfäuste und befreit Corki. Sprecht mit Arechron in Telaar, wenn Ihr Erfolg hattet.', },
  },
  [9924] = {
    'Corki wird schon wieder vermisst!',
    {'<Arechron seufzt.>|n|nDas ist mir so peinlich. Erinnert Ihr Euch noch an meinen Sohn Corki? Ihr habt ihn vor Kurzem aus den Ruinen der Brennenden Klinge gerettet. Nun ja, seine Neugier hat ihn mal wieder gepackt. Er sagte, er wolle die Felsfaustbedrohung für Onkel Mo\'mor untersuchen, und ist zu den Ogerhügeln im Halaanibecken gerannt, nördlich von hier.|n|nKönntet Ihr ihn vielleicht für mich ausfindig machen? Ich wäre Euch ewig dankbar.', },
    {'Arechron in Telaar bittet Euch, Corki zu suchen und zu befreien.', },
  },
  [9925] = {
    'Eine Frage der Sicherheit',
    {'Gezhe hat beschlossen, unsere Operation so nahe wie möglich am Oshu\'gun zu postieren, ohne dabei einen Gedanken an die Sicherheit der Gruppe zu verschwenden. Warum? Weil er eine Erhöhung unserer Produktivität um zehn Prozent vorausgesehen hat, wenn er uns hier anstatt in den Bergen im Süden ansiedelt.|n|nUngeachtet der durchgedrehten Ausgeburten der Leere, die sich gerade mal 10 Fuß von uns weg aufhalten. Aber das ist das Problem des Sicherheitsoffiziers, nicht Gezhes.|n|nTötet ein paar dieser Ausgeburten für mich, und ich gebe Euch ein Zehntel meines Sicherheitsetats. Freut Euch nicht zu früh, viel Geld steht mir nicht zur Verfügung.', },
    nil,
  },
  [9927] = {
    'Erbarmungslose Gerissenheit',
    {'<Lantresor reicht Euch einen Stapel Banner.>|n|nDies sind die Ogerbanner der Totschläger, die ich kürzlich erworben habe.|n|nIch möchte, dass Ihr zur Festung Kil\'sorge reist und so viele wie möglich von diesem Abschaum von Kil\'sorge tötet, wie Ihr nur könnt. Rammt ein Totschlägerbanner durch das Herz jedes gefallen Soldaten von Kil\'sorge. Kehrt zu mir zurück wenn Ihr diese und die beiden anderen Aufgaben, die zu meinem Plan gehören, erledigt habt.', },
    nil,
  },
  [9928] = {
    'Waffen zur Täuschung',
    {'Wenn mein Plan gelingen soll, müsst Ihr ein paar Waffen von Kil\'sorge in der Festung Kil\'sorge stehlen.|n|nDurchsucht die Festung nach Kisten mit Waffen von Kil\'sorge. Bringt mir alle, die Ihr finden könnt.|n|nDie Festung Kil\'sorge liegt im Süden, etwas westlich von den Ruinen der Brennenden Klinge.', },
    nil,
  },
  [9929] = {
    'Der vermisste Händler',
    {'Ich nehme an, Ihr seid noch nicht lange genug hier um Dugar zu kennen, oder? Er ist ein Händler mit Kontakten zu den verschiedenen Fraktionen hier in Shattrath.|n|nFragt mich nicht, wie er das anstellt, aber er schafft es, mit ihnen Waren zu handeln, an die nicht einmal der Rüstmeister kommt!|n|nEr ist vor drei Tagen aus Shattrath losgezogen und noch nicht zurückgekehrt. Normalerweise schafft er seine Runde in viel kürzerer Zeit. Wenn Ihr in den Wald reist, haltet Ihr dann ein Auge nach ihm offen?', },
    {'Reist nach Nordwesten entlang der Straße nach Shattrath und sucht nach Hinweisen auf den Verbleib von Dugar.', },
  },
  [9930] = {
    'Der vermisste Händler',
    {'Ich nehme an, Ihr seid noch nicht lange genug hier um Deirom zu kennen, oder? Er ist ein Händler mit Kontakten zu den verschiedenen Fraktionen hier in Shattrath.|n|nFragt mich nicht, wie er das anstellt, aber er schafft es, mit ihnen Waren zu handeln, an die nicht einmal der Rüstmeister kommt!|n|nEr ist vor drei Tagen aus Shattrath losgezogen und noch nicht zurückgekehrt. Normalerweise schafft er seine Runde in viel kürzerer Zeit. Wenn Ihr in den Wald reist, haltet Ihr dann ein Auge nach ihm offen? Meldet Euch bei Thander, wenn Ihr etwas herausfindet.', },
    {'Reist nach Nordwesten entlang der Straße nach Shattrath und sucht nach Hinweisen auf den Verbleib von Deirom.', },
  },
  [9931] = {
    'Sich für den Gefallen revanchieren',
    {'Nun müsst Ihr den Wunsch nach Krieg in den fetten, nutzlosen Köpfen der Totschläger wecken. Im Nordwesten, bei den Bergen, findet Ihr die Ruinen des Lachenden Schädels.|n|n<Lantresor zeigt auf die Kiste mit den Waffen, die Ihr ihm gebracht habt.>|n|nErkennt Ihr diese Banner? Es sind Banner von Kil\'sorge. Ich möchte, dass Ihr einen Stapel Banner von Kil\'sorge nehmt und sie in die Leichen der Totschlägeroger rammt. Denkt daran, Ihr findet sie im Nordwesten.', },
    nil,
  },
  [9932] = {
    'Beweismaterial',
    {'Euer Angriff auf die Festung Kil\'sorge hat uns eine ganz besondere Möglichkeit eröffnet. Wir haben genügend Leichen, um es so aussehen zu lassen, als hätte eine große Schlacht stattgefunden.|n|nReist zu den Ruinen des Lachenden Schädels und sucht den Hof des Lachenden Schädels. Dort solltet Ihr einen brennenden Scheiterhaufen finden. Vergewissert Euch, dass die Gegend sicher ist, und benutzt diese Decke, um Rauchzeichen zu senden. Wenn meine Oger den Rauch sehen, werden sie sich einschleichen und die Leichen der toten Soldaten von Kil\'sorge dort platzieren.|n|nDas sollte unser letzter Streich sein.', },
    {'Lantresor von der Klinge in den Ruinen der Brennenden Klinge in Nagrand möchte, dass Ihr die feuchte Wolldecke am lodernden Scheiterhaufen der Totschläger im Hof des Lachenden Schädels benutzt, um Signale an seine Oger zu senden.', },
  },
  [9933] = {
    'Nachricht für Telaar',
    {'<Lantresor zeigt auf eine unbeschriftete Kiste.>|n|nNehmt dies. Es ist mein Geschenk an Euer Volk. Ihr habt meinen Klan eigenhändig vor der Ausrottung bewahrt.|n|nIhr könnt Eurem Anführer sagen, dass Lantresor von der Brennenden Klinge und seine Felsfäuste das Friedensangebot annehmen.|n|n<Lantresor verneigt sich.>', },
    nil,
  },
  [9934] = {
    'Nachricht für Garadar',
    {'<Lantresor zeigt auf eine unbeschriftete Kiste.>|n|nNehmt dies. Es ist mein Geschenk an Euer Volk. Ihr habt meinen Klan eigenhändig vor der Ausrottung bewahrt.|n|nIhr könnt Eurem Anführer sagen, dass Lantresor von der Brennenden Klinge und seine Felsfäuste das Friedensangebot annehmen.|n|n<Lantresor verneigt sich.>', },
    {'Bringt das Friedensangebot der Brennenden Klinge zu Garrosh in Garadar.', },
  },
  [9935] = {
    'Gesucht: Giselda die Alte',
    {'Gesucht: Tot oder lebendig|n|nGiselda die Alte von Kil\'sorge und ihre Lakaien wegen Mord, rituellen Opferungen, Verbrüderung mit der Legion, Entführung und Diebstahl.|n|nAufenthaltsort in der Festung Kil\'sorge im Südosten von Nagrand, an der Grenze zu Terokkar.|n|nEine hohe Belohnung in Gold wird von Aufseher Bullrok in Garadar an denjenigen ausgezahlt, der Giselda ihre gerechte Strafe zukommen lässt.', },
    nil,
  },
  [9936] = {
    'Gesucht: Giselda die Alte',
    {'Gesucht: Tot oder lebendig|n|nGiselda die Alte von Kil\'sorge und ihre Lakaien wegen Mord, rituellen Opferungen, Verbrüderung mit der Legion, Entführung und Diebstahl.|n|nAufenthaltsort in der Festung Kil\'sorge im Südosten von Nagrand, an der Grenze zu Terokkar.|n|nEine hohe Belohnung in Gold wird von Aufseher Moi\'bff Jill in Telaar an denjenigen ausgezahlt, der Giselda ihre gerechte Strafe zukommen lässt.', },
    nil,
  },
  [9937] = {
    'Gesucht: Durn der Nimmersatte',
    {'Ihr habt eine der beiden größten Bedrohungen in Nagrand vernichtet, $N. Seid Ihr nun bereit für die Geißel der Geisterfelder?|n|nDurn der Nimmersatte regiert über das Gebiet beim Oshu\'gun und vernichtet alles, was ihm über den Weg läuft. Bis jetzt ist es noch niemandem gelungen, Nagrand von diesem blutrünstigen Gronn zu befreien. Reist zu den Geisterfeldern, weit im Südwesten von hier, und findet Durn. Tötet ihn und ich verspreche Euch eine Belohnung, die der Schwierigkeit dieser Aufgabe angemessen ist.', },
    {'Tötet Durn den Nimmersatten. Meldet Euch bei Aufseher Bullrok, wenn Ihr diese Aufgabe erledigt habt.', },
  },
  [9938] = {
    'Gesucht: Durn der Nimmersatte',
    {'Ihr habt eine der beiden größten Bedrohungen in Nagrand vernichtet, $N. Seid Ihr nun bereit für die Geißel der Geisterfelder?|n|nDurn der Nimmersatte regiert über das Gebiet beim Oshu\'gun und vernichtet alles, was ihm über den Weg läuft. Bis jetzt ist es noch niemandem gelungen, Nagrand von diesem blutrünstigen Gronn zu befreien. Reist zu den Geisterfeldern, weit im Südwesten von hier, und findet Durn. Tötet ihn und ich verspreche Euch eine Belohnung, die der Schwierigkeit dieser Aufgabe angemessen ist.', },
    {'Tötet Durn den Nimmersatten. Meldet Euch bei Aufseher Moi\'bff Jill, wenn Ihr diese Aufgabe erledigt habt.', },
  },
  [9939] = {
    'Gesucht: Zorbo der Berater',
    {'Gesucht: tot oder lebendig|n|nZorbo der Berater, gesucht für mehrere geplante Angriffe auf Garadar. Zusammen mit seinen Häschern und Schamanen hat Zorbo unzählige Orcs getötet. Zorbo ist als bewaffnet, gefährlich und erbarmungslos einzustufen.|n|nSein Zuhause befindet sich in den Ruinen des Lachenden Schädels in den nördlichen Bergen von Nagrand.|n|nDie Belohnung für den Tod oder die Gefangennahme von Zorbo dem Berater wird von Aufseher Bullrok in Garadar ausbezahlt.', },
    nil,
  },
  [9940] = {
    'Gesucht: Zorbo der Berater',
    {'Gesucht: tot oder lebendig|n|nZorbo der Berater, gesucht für mehrere geplante Angriffe auf Telaar. Zusammen mit seinen Häschern und Schamanen hat Zorbo unzählige Zerschlagene getötet. Zorbo ist als bewaffnet, gefährlich und erbarmungslos einzustufen.|n|nSein Zuhause befindet sich in den Ruinen des Lachenden Schädels in den nördlichen Bergen von Nagrand.|n|nDie Belohnung für den Tod oder die Gefangennahme von Zorbo dem Berater wird von Aufseher Moi\'bff Jill in Telaar ausbezahlt.', },
    nil,
  },
  [9941] = {
    'Die Schuldigen aufspüren',
    {'Die Arakkoaspuren, bei denen auch ein paar flache Furchen zu erkennen sind, führen nach Norden über die Straße hinweg. Es sieht aus, als hätten die Arakkoa etwas vom Schlachtfeld weggeschleift, vielleicht zu einer Siedlung in der Nähe.|n|nAuch wenn ein kaputter Wagen auf einen Kampf hinweist, sind keine Hinweise auf Deiroms Schicksal erkennbar. Folgt den Arakkoaspuren nach Norden und sucht weiter nach dem Händler. Wenn er lebend gefangen wurde, besteht vielleicht immer noch die Chance, ihn zu retten.', },
    {'Sucht weiter in der Arakkoasiedlung nördlich des kaputten Wagens nach einem Lebenszeichen von Deirom.', },
  },
  [9942] = {
    'Die Schuldigen aufspüren',
    {'Die Arakkoaspuren, bei denen auch ein paar flache Furchen zu erkennen sind, führen nach Norden über die Straße hinweg. Es sieht aus, als hätten die Arakkoa etwas vom Schlachtfeld weggeschleift, vielleicht zu einer Siedlung in der Nähe.|n|nAuch wenn ein kaputter Wagen auf einen Kampf hinweist, sind keine Hinweise auf Dugars Schicksal erkennbar. Folgt den Arakkoaspuren nach Norden und sucht weiter nach dem Händler. Wenn er lebend gefangen wurde, besteht vielleicht immer noch die Chance, ihn zu retten.', },
    {'Sucht weiter in der Arakkoasiedlung nördlich des kaputten Wagens nach einem Lebenszeichen von Dugar.', },
  },
  [9943] = {
    'Rückkehr zu Thander',
    {'Deiroms Ladung scheint nicht beschädigt oder geöffnet worden zu sein. Die Ladung hat wohl ihr Interesse geweckt, doch der Gefangene scheint ihnen wichtiger gewesen zu sein. Was die Arakkoa sich von dem Angriff und der Entführung Deiroms erhofft haben, bleibt unklar, aber hier wird der Händler sicher nicht gefangen gehalten.|n|nDa Ihr keine Ahnung habt, wo Ihr die Suche fortsetzen sollt, beschließt Ihr, dass es an der Zeit ist, Thander Eure Entdeckungen mitzuteilen.', },
    {'Kehrt mit Euren neuen Erkenntnissen zu Thander in Allerias Feste zurück.', },
  },
  [9944] = {
    'Verschollene mag\'harische Prozession',
    {'Großmutter sagt, dass wir durchhalten und unserem Volk dienen müssen. Sie sagt, dass wir Garrosh als Beispiel dienen müssen, zeigen, dass das Leben weitergeht.|n|nIch muss mich um so viele Dinge hier kümmern, besonders seit Großmutter krank ist. Würdet Ihr den Mag\'har eine Gefallen tun, indem Ihr einer ihrer Matronen helft?|n|nVor ein paar Tagen haben wir einen Begräbniszug zum Ahnengrund geschickt, der noch nicht zurückgekehrt ist. Würdet Ihr nach ihnen suchen? Sie haben die westliche Straße aus Garadar hinaus genommen. Folgt ihr und meidet Halaa.', },
    {'Sucht nach der verschollenen mag\'harischen Prozession.', },
  },
  [9945] = {
    'Krieg den Totschlägern',
    {'Wir waren auf dem Weg zum Ahnengrund, als wir in einen Hinterhalt der Totschläger geraten sind. Sie kamen von allen Seiten, haben viele der Wächter der Prozession getötet und auch viele andere. Sie haben sogar die Überreste des Ältesten im Wagen geschändet.|n|nUnd warum? Um uns zu erniedrigen und ihre Macht zu beweisen. Nicht einmal die Felsfäuste hätten sich zu so etwas herabgelassen.|n|nIch habe mich dem spirituellen Weg verschrieben, $N, aber auch ich kenne Grenzen. Sucht die Angreifer im Totschlägerhügel im Nordwesten und vernichtet sie!', },
    nil,
  },
  [9946] = {
    'Cho\'war der Plünderer',
    {'Habt Ihr je einen Ogerkönig gesehen, $R? Nur wenige haben es überlebt und können davon erzählen. Unglücklicherweise haben wir es genau jetzt mit einem zu tun.|n|nDer Anführer dieser Barbaren ist ein Oger namens Cho\'war. Gerüchten zufolge soll er die Gronn aus den Höhlen vertrieben haben. Danach hat sich Cho\'war selbst zum König ernannt und die Ogerklans, die unter den Gronn gedient haben, aufgelöst. So entstanden die Totschläger.|n|nSucht tief in den Höhlen des Totschlägerhügels nach Cho\'war. Tötet ihn und bringt mir seinen Kopf.', },
    {'Ältester Yorley bei der mag\'harischen Prozession in Nagrand möchte, dass Ihr Cho\'war den Plünderer tötet und Cho\'wars Kopf besorgt.', },
  },
  [9947] = {
    'Rückkehr zu Rokag',
    {'Dugars Ladung scheint nicht beschädigt oder geöffnet worden zu sein. Die Ladung hat wohl ihr Interesse geweckt, doch der Gefangene scheint ihnen wichtiger gewesen zu sein. Was die Arakkoa sich von dem Angriff und der Entführung Deiroms erhofft haben, bleibt unklar, aber hier wird der Händler sicher nicht gefangen gehalten.|n|nDa Ihr keine Ahnung habt, wo Ihr die Suche fortsetzen sollt, beschließt Ihr, dass es an der Zeit ist, Rokag Eure Entdeckungen mitzuteilen.', },
    {'Kehrt mit Euren neuen Erkenntnissen zu Rokag in der Steinbrecherfeste zurück.', },
  },
  [9948] = {
    'Findet die Überlebenden',
    {'Wenn ich etwas über Oger weiß, dann dass sie Ihr Essen frisch mögen. Das bedeutet, dass die Mag\'har, die sie gefangen haben, wahrscheinlich am Leben gehalten werden, bis sie verspeist werden sollen. Ich weiß, das ist ein grausamer Gedanke, aber wir müssen das zu unserem Vorteil ausnutzen.|n|nGeht zum Totschlägerhügel und sucht nach gefangenen Mag\'har. Wenn Ihr Gefangene gefunden habt, holt Euch die Schlüssel von den Totschlägern in der Nähe.|n|nTötet die Oger, um an die Schlüssel zu gelangen, und befreit die Gefangenen.', },
    nil,
  },
  [9949] = {
    'Aus der Vogelperspektive',
    {'Ohne weitere Informationen sind wir in einer schwierigen Lage. Ich werde die Suche nach Deirom nicht aufgeben. Seine Entführung war kein Zufall, $N.|n|nDie Arakkoa planen etwas, aber was?|n|nAndarl im Magierturm kennt sich ein wenig mit ihrer besonderen Magie aus. Mit den richtigen Werkzeugen kann er uns neue Informationen besorgen. Er benötigt die Augenkristalle der Arakkoadörfer nördlich der Knochenwüste - dem Skithversteck, dem Reskkversetck und dem Shienorversteck.', },
    {'Bringt das Auge des Sktihverstecks, das Auge des Shienorverstecks und das Auge des Reskkverstecks zu Andarl in Allerias Feste.', },
  },
  [9950] = {
    'Aus der Vogelperspektive',
    {'Ohne weitere Informationen sind wir in einer schwierigen Lage. Ich werde die Suche nach Dugar nicht aufgeben. Seine Entführung war kein Zufall, $N.|n|nDie Arakkoa planen etwas, aber was?|n|nKurgatok der Hexenmeister kennt sich ein wenig mit ihrer besonderen Magie aus. Mit den richtigen Werkzeugen kann er uns neue Informationen besorgen. Er benötigt die Augenkristalle der Arakkoadörfer nördlich der Knochenwüste - dem Skithversteck, dem Reskkversetck und dem Shienorversteck.', },
    {'Bringt das Auge des Sktihverstecks, das Auge des Shienorverstecks und das Auge des Reskkverstecks zu Krugatok in der Steinbrecherfeste.', },
  },
  [9951] = {
    'Es beobachtet Euch!',
    {'Schnell, versteckt Euch! Naphthal\'ars Auge beobachtet Euch... uns alle!|n|nIch traue mich nicht, auf die Spitze des Turms zu gehen, um mit ihm zu sprechen, aber Ihr... Ihr seht aus, als könntet Ihr die richtigen Worte finden. Aber seid vorsichtig, es mag keine Witze und kann Dummköpfe nicht leiden.|n|nÜberredet es, auf eine Tasse Tee hinunterzukommen. Aber bitte sorgt dafür, dass es mich nicht mehr anstarrt!', },
    {'Tötet Naphthal\'ar und kehrt dann zu Aufseher Baumlas im Cenariusdickicht in den Wäldern von Terokkar zurück.', },
  },
  [9952] = {
    'Ausgrabungsleiter Balmoral',
    {'Andarl ist also sicher, dass Deirom im Shalasversteck gefangen gehalten wird? Das ist die größte Arakkoasiedlung, die wir kennen.|n|nDas Shalasversteck liegt weit im Süden der Wälder, nahe bei der östlichen Grenze der Knochenwüste. Ich weiß leider nicht sehr viel darüber, aber dort unten gibt es ein Lager eines Mitglieds der Forscherliga, der Euch vielleicht weiterhelfen kann. Ausgrabungsleiter Balmorals Lager befindet sich am äußersten Rand des Landes südwestlich vom Shalasversteck. Befragt ihn zunächst, bevor Ihr etwas gegen die Arakkoa unternehmt.', },
    {'Findet und sprecht mit Ausgrabungsleiter Balmoral.', },
  },
  [9953] = {
    'Aufklärer Nodak',
    {'Kurgatok ist also sicher, dass Dugar im Shalasversteck gefangen gehalten wird? Das ist die größte Arakkoasiedlung, die wir kennen.|n|nDas Shalasversteck liegt weit im Süden der Wälder, nahe bei der östlichen Grenze der Knochenwüste. Ich weiß leider nicht sehr viel darüber, aber einer unserer Späher hat dort unten sein Lager. Vielleicht kann er Euch weiterhelfen. Aufklärer Nodaks Lager befindet sich am äußersten Rand des Landes südwestlich vom Shalasversteck. Befragt ihn zunächst, bevor Ihr etwas gegen die Arakkoa unternehmt.', },
    {'Findet und sprecht mit Aufklärer Nodak.', },
  },
  [9954] = {
    'Corkis Lösegeld',
    {'<Arechron zeigt Euch einen rußverschmierten Brief.>|n|nIch habe gerade diesen Brief erhalten. Er ist von einem Ogerstamm, die sich selbst Totschläger nennen. Sie herrschen über die nordwestlichen Gebiete von Nagrand. Hier steht, dass sie Corki in ihrer Gewalt haben, und sie drohen ihn aufzufressen, wenn wir nicht kooperieren. Nunja, Corki ist ein Dummkopf, aber er gehört zur Familie. Würdet Ihr ihn retten, $N?|n|nIch nehme an, dass er in einem Käfig auf dem Totschlägerhügel eingesperrt ist. Dort solltet Ihr zuerst nachsehen.', },
    {'Arechron möchte, dass Ihr Corki auf dem Totschlägerhügel findet.', },
  },
  [9955] = {
    'Cho\'war der Plünderer',
    {'Sie nennen ihn Cho\'war den Plünderer, $N. Er ist der Oger, der die Gronn, die über die Oger geherrscht hatten, vertrieben hat. Ihr könnt mir ruhig glauben, dass er mächtig ist!|n|nDer Chef hat gesagt, dass Cho\'war in der großen Höhle wohnt - wo immer das auch sein mag... Besorgt diesen Schlüssel und holt mich hier raus! Wenn wir das hier überleben, wird mein Vater Euch sicher reich belohnen! Geht zu ihm sobald ich frei bin.', },
    {'Corki möchte, dass Ihr Cho\'wars Schlüssel besorgt, um ihn aus dem Käfig zu befreien. Kehrt zu Arechron in Telaar zurück, falls Ihr Erfolg haben solltet.', },
  },
  [9956] = {
    'Die Überfallene Karawane',
    {'Ich war bei einer Karawane dabei, die Vorräte zur Oreborzuflucht in den Zangarmarschen bringen sollte. An der Grenze zu den Marschen wurden wir jedoch von einer hinterlistigen Truppe von Totschlägerogern überfallen. Sie haben die anderen getötet und mich sowie all unsere Vorräte beschlagnahmt.|n|nZum Glück haben sie vergessen, meinen Käfig zu verriegeln. Als sie eingeschlafen waren, bin ich geflohen.|n|nEs ist zwar zu spät für meine Kameraden, aber wir könnten die gestohlenen Vorräte wirklich gebrauchen. Den Totschlägerhügel findet Ihr in den nordwestlichen Bergen von Nagrand.', },
    nil,
  },
  [9957] = {
    'Was ist los mit dem Cenariusdickicht?',
    {'Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts in den Wäldern von Terokkar gehört.|n|nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Es gibt viele Wege dorthin, aber der kürzeste führt den Weg nach Süden entlang. Biegt die Straße nach Osten von Shattrath ab, wenn Ihr im Wald seid.', },
    {'Sprecht mit den Druiden im Cenariusdickicht in den Wäldern von Terokkar.', },
  },
  [9958] = {
    'Die Verteidigung ausspähen',
    {'Seit ich hier bin habe ich schon öfter mit den Arakkoa zu tun gehabt, und das war alles andere als freundlich. Sie scheinen sehr ortsgebunden zu sein, aber das sind wir ja auch, oder?|n|nDie Arakkoa verfügen über eine Art ursprüngliche Magie, die in Azeroth völlig unbekannt ist. Mit ihrer Hilfe haben sie die magische Verteidigung des Shalasverstecks gewirkt. Bevor wir gegen sie vorgehen können, wäre es klug, diese Verteidigungseinrichtungen zunächst auszuspähen, damit wir wissen, wogegen wir ankommen müssen.', },
    {'Begebt Euch in die Nähe des Shalasverstecks und beobachtet die Verteidigungseinrichtungen des Dorfes.', },
  },
  [9959] = {
    'Die Verteidigung ausspähen',
    {'Seit ich hier bin habe ich schon öfter mit den Arakkoa zu tun gehabt, und das war alles andere als freundlich. Sie scheinen sehr ortsgebunden zu sein, aber das sind wir ja auch, oder?|n|nDie Arakkoa verfügen über eine Art ursprüngliche Magie, die in Azeroth völlig unbekannt ist. Mit ihrer Hilfe haben sie die magische Verteidigung des Shalasverstecks gewirkt. Bevor wir gegen sie vorgehen können, wäre es klug, diese Verteidigungseinrichtungen zunächst auszuspähen, damit wir wissen, wogegen wir ankommen müssen.', },
    {'Begebt Euch in die Nähe des Shalasverstecks und beobachtet die Verteidigungseinrichtungen des Dorfes.', },
  },
  [9960] = {
    'Was ist los mit dem Cenariusdickicht?',
    {'Hey Ihr da, $C! Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts gehört.|n|nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Ihr findet es, wenn Ihr Richtung Nordwesten durch den Wald geht.', },
    {'Sprecht mit den Druiden im Cenariusdickicht in den Wäldern von Terokkar.', },
  },
  [9961] = {
    'Was ist los mit dem Cenariusdickicht?',
    {'$C, ich habe eine eilige Aufgabe für Euch. Wir haben schon eine Weile nichts mehr von den Druiden des Cenariusdickichts gehört. Das ist sehr merkwürdig, da sie sich normalerweise alle paar Tage bei uns melden.|n|nIch möchte, dass Ihr dort hinüber geht und nachschaut, was los ist. Ihr findet es, wenn Ihr Richtung Nordwesten durch den Wald geht.', },
    {'Sprecht mit den Druiden im Cenariusdickicht in den Wäldern von Terokkar.', },
  },
  [9962] = {
    'Der Ring des Blutes: Schmetterzehe',
    {'Seid Ihr bereit für den ersten Kampf? Wenn Ihr soweit seid, gebt mir Bescheid und ich bringe die Dinge ins Rollen. Ihr müsst nur im Ring des Blutes auf Euren ersten Gegner warten.|n|nEuer erster Herausforderer wird Schmetterzehe sein, ein grausamer Grollhuf.|n|nViel Glück! Ich hoffe, Ihr habt ein paar Freunde mitgebracht.|n|nUnd denkt daran, der Kampf ist erst zu Ende, wenn Ihr oder Euer Gegner mit dem Gesicht nach unten auf dem Boden liegt.', },
    {'Besiegt Schmetterzehe. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.', },
  },
  [9963] = {
    'Hilfe von der Geißel',
    {'Die Schutzzauber, die Ihr bemerkt habt, sind tatsächlich sehr starke Magie. Die Fertigkeiten der Arakkoa entziehen sich unserem Verständnis, weswegen wir nur hoffen können, dass wir mit ihrer Hilfe einen Gegenzauber finden können.|n|nIch weiß, was Ihr denkt. Warum sollte der Feind uns helfen wollen, seine Verteidigung zu durchbrechen? Die Antwort ist natürlich, dass er das nicht will. Habt Ihr die Geschichten über den verrückten alten Arakkoa namens Kokorek gehört? Man sagt, er hielte sich im Lithicversteck am westlichen Ende der Knochenwüste auf und warte auf die Rückkehr längst vergangener Zeiten.', },
    {'Sucht Kokorek im Lithicversteck und sprecht mit ihm.', },
  },
  [9964] = {
    'Hilfe von der Geißel',
    {'Die Schutzzauber, die Ihr bemerkt habt, sind tatsächlich sehr starke Magie. Die Fertigkeiten der Arakkoa entziehen sich unserem Verständnis, weswegen wir nur hoffen können, dass wir mit ihrer Hilfe einen Gegenzauber finden können.|n|nIch weiß, was Ihr denkt. Warum sollte der Feind uns helfen wollen, seine Verteidigung zu durchbrechen? Die Antwort ist natürlich, dass er das nicht will. Habt Ihr die Geschichten über den verrückten alten Arakkoa namens Kokorek gehört? Man sagt, er hielte sich im Lithicversteck am westlichen Ende der Knochenwüste auf und warte auf die Rückkehr längst vergangener Zeiten.', },
    {'Sucht Kokorek im Lithicversteck und sprecht mit ihm.', },
  },
  [9965] = {
    'Guten Willen zeigen',
    {'Ich möchte Euch einen Handel vorschlagen: zeigt mir, dass Ihr gute Absichten habt, indem Ihr mir bei der Lösung eines kleinen Problems helft, und ich werde Euch bei der Rettung Eures Freundes unterstützen.|n|nDie Oger sind ein uralter Feind meines Volkes, und in letzter Zeit haben sie begonnen, vom Grasland in Nagrand zurück in unsere Wälder zu ziehen.|n|nEiner dieser Oger, Mug\'gok, ist ein ziemlich abenteuerlicher Geselle, aber leider kein allzu kluger. Er reist die ganze Zeit hin und her, bereitet seinen Freunden in den Ruinen des Blutenden Auges Ärger und provoziert uns.', },
    {'Bringt Mug\'goks Kopf zu Kokorek im Lithicversteck.', },
  },
  [9966] = {
    'Guten Willen zeigen',
    {'Ich möchte Euch einen Handel vorschlagen: zeigt mir, dass Ihr gute Absichten habt, indem Ihr mir bei der Lösung eines kleinen Problems helft, und ich werde Euch bei der Rettung Eures Freundes unterstützen.|n|nDie Oger sind ein uralter Feind meines Volkes, und in letzter Zeit haben sie begonnen, vom Grasland in Nagrand zurück in unsere Wälder zu ziehen.|n|nEiner dieser Oger, Mug\'gok, ist ein ziemlich abenteuerlicher Geselle, aber leider kein allzu kluger. Er reist die ganze Zeit hin und her, bereitet seinen Freunden in den Ruinen des Blutenden Auges Ärger und provoziert uns.', },
    {'Bringt Mug\'goks Kopf zu Kokorek im Lithicversteck.', },
  },
  [9967] = {
    'Der Ring des Blutes: Die Blaumänner',
    {'Im nächsten Kampf werdet Ihr auf gleich zwei Gegner treffen, Zwillinge um genau zu sein. Sie nennen sich selbst die "Blaumänner".|n|nEs ist noch nicht zu spät, um zu kneifen, $N. Ich könnte das verstehen.|n|nAber wenn Ihr bereit seid für ein wenig Action, tretet in den Ring des Blutes und wartet auf die Zwillinge der Finsterblut.|n|nDer Letzte, der noch steht, hat gewonnen!', },
    {'Besiegt die Zwillinge der Finsterblut, die sich selbst die Blaumänner nennen. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.', },
  },
  [9968] = {
    'Fremde Energien',
    {'Etwas Merkwürdiges hat die Teromotten des Dickichts verändert.|n|nWo einst eine Vielfalt von Arten herrschte, sind jetzt nur noch die Teromotten übrig. Und während sie früher friedlich waren, sind sie jetzt sehr aufgeregt und greifen alles an, was ihnen zu nahe kommt.|n|nIch muss die bösartigen mit den normalen Motten vergleichen. Bringt mir ein paar Exemplare von beiden Sorten. Die gewöhnlichen Teromotten findet Ihr im Süden und im Norden.|n|nIch bin mir sicher, dass dies mit dem Tod der Druiden zusammenhängt.', },
    nil,
  },
  [9969] = {
    'Die letzten Reagenzien',
    {'Ich kann einen Gegenstand herstellen, der den Schutzzauber, der das Shalasversteck umgibt, aufheben kann, aber seid gewarnt, $N, die Wirkung wird nur so lange andauern, bis Ihr Euren Freund befreit habt. Ich werde Euch keine Waffe geben, mit der Ihr mein Volk wann immer Ihr wollt angreifen könnt.|n|nIch habe fast alle Zutaten, die ich für diesen Zauber brauche, aber Ihr müsst noch ein paar weitere für mich sammeln, bevor ich ihn abschließen kann. Ich brauche etwas Sphärenpirscheressenz und eine Handvoll Apfelbeeren von Terokkar. Ihr könnt beides um das Versteck herum finden.', },
    {'Bringt 5 Sphärenpirscheressenzen und 30 Apfelbeeren von Terokkar zu Kokorek im Lithicversteck.', },
  },
  [9970] = {
    'Der Ring des Blutes: Rokdar der Zerklüftete',
    {'Das wird ein harter Kampf, $N. Habt Ihr vielleicht ein paar Freunde, die Euch helfen können? Den Ogern ist es gelungen, einen Riesen namens Rokdar aus dem Schergrat hierher zu bringen! Glaubt mir, Ihr werdet ein paar Freunde brauchen, er scheint unbesiegbar zu sein! Er ist hart wie Stein - im wahrsten Sinne des Wortes!|n|nWenn Ihr immer noch gegen ihn antreten möchtet, tretet in den Ring des Blutes und er wird kommen.', },
    {'Besiegt Rokdar den Zerklüfteten. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.', },
  },
  [9971] = {
    'Hinweise im Dickicht',
    {'Ich habe keine Ahnung, was all die Druiden hier getötet hat. Ich war ein paar Tage unterwegs, um die Knochenwüste im Süden zu untersuchen.|n|nBitte, Ihr müsst mir helfen herauszufinden, was hinter dieser furchtbaren Tragödie steckt. Geht zum Dickicht und haltet nach einem Hinweis Ausschau, der uns weiterhelfen könnte. Als ich kurz dort war, hätte ich schwören können, dass ich einen toten Zerschlagenen und ein merkwürdiges Ding neben ihm gesehen habe.|n|nUnd habt keine Angst vor Baumlas - er ist vielleicht durch die Geschehnisse verrückt geworden, aber ich glaube, er ist harmlos.', },
    {'Untersucht das merkwürdige Objekt neben der Leiche eines Zerschlagenen um herauszufinden, was hinter der Tragödie beim Cenariusdickicht steckt. Kehrt dann zu Erdbinder Tavgren außerhalb des Dickichts in den Wäldern von Terokkar zurück.', },
  },
  [9972] = {
    'Der Ring des Blutes: Skra\'gath',
    {'Ihr bringt sie ja reihenweise um, $GKleiner:Kleine;! Dieses Mal haben sie einen Profi für den Kampf. Sie sagen er sei ein Leerenfürst oder so was... Sie wollen Euch auf keinen Fall gegen ihren Champion kämpfen lassen. Habt Ihr gehört wie Mogor, das Fallobst, Euch angekläfft hat? Die Wetten stehen astronomisch hoch!|n|nSteigt in den Ring und haut ihn um!', },
    {'Besiegt Skra\'gath. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.', },
  },
  [9973] = {
    'Der Ring des Blutes: Champion der Totschläger',
    {'Sie mussten den Champion aus den Gladiatorengruben im Schergrat einschiffen. Dort hat er mit den Bergriesen trainiert - mit gleich dreien auf einmal!|n|nWenn Ihr gegen ihn gewinnt, seid Ihr der neue Champion. Glaubt Ihr, Ihr habt eine Chance? Könnt Ihr das schaffen? Sagt mir nur Bescheid, dann setze ich mein Haus auf Euch.|n|nJetzt steigt in den Ring und gewinnt!', },
    {'Besiegt den Champion der Totschläger. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener, um Eure Belohnung zu erhalten.', },
  },
  [9974] = {
    'Die letzten Reagenzien',
    {'Ich kann einen Gegenstand herstellen, der den Schutzzauber, der das Shalasversteck umgibt, aufheben kann, aber seid gewarnt, $N, die Wirkung wird nur so lange andauern, bis Ihr Euren Freund befreit habt. Ich werde Euch keine Waffe geben, mit der Ihr mein Volk wann immer Ihr wollt angreifen könnt.|n|nIch habe fast alle Zutaten, die ich für diesen Zauber brauche, aber Ihr müsst noch ein paar weitere für mich sammeln, bevor ich ihn abschließen kann. Ich brauche etwas Sphärenpirscheressenz und eine Handvoll Apfelbeeren von Terokkar. Ihr könnt beides um das Versteck herum finden.', },
    {'Bringt 5 Sphärenpirscheressenzen und 30 Apfelbeeren von Terokkar zu Kokorek im Lithicversteck.', },
  },
  [9975] = {
    'Urmagie',
    {'Ich habe den Zauber in diesem Talisman aufbewahrt. Entfesselt ihn, wenn Ihr bei den Totems steht, die den Zugang zum Shalasversteck bewachen. Er sollte stark genug sein, um die Wächter außer Gefecht zu setzen.|n|n<Ihr bemerkt, dass die Figur des Talismans nicht wie ein Arakkoa aussieht.>|n|nMein Volk sah nicht immer so aus wie jetzt. Einst waren wir prächtige Wesen, aber wir... wir haben die falschen Entscheidungen getroffen und sind bei unserer heiligen Aufgabe gescheitert. Das hat uns unsere Schönheit, unsere Macht und fast unser Leben gekostet. Wiederholt unsere Fehler nicht, $N.', },
    {'Benutzt Kokoreks Talisman in der Nähe der Totems, die den Weg ins Shalasversteck bewachen, und sprecht dann mit Ausgrabungsleiter Balmoral.', },
  },
  [9976] = {
    'Urmagie',
    {'Ich habe den Zauber in diesem Talisman aufbewahrt. Entfesselt ihn, wenn Ihr bei den Totems steht, die den Zugang zum Shalasversteck bewachen. Er sollte stark genug sein, um die Wächter außer Gefecht zu setzen.|n|n<Ihr bemerkt, dass die Figur des Talismans nicht wie ein Arakkoa aussieht.>|n|nMein Volk sah nicht immer so aus wie jetzt. Einst waren wir prächtige Wesen, aber wir... wir haben die falschen Entscheidungen getroffen und sind bei unserer heiligen Aufgabe gescheitert. Das hat uns unsere Schönheit, unsere Macht und fast unser Leben gekostet. Wiederholt unsere Fehler nicht, $N.', },
    {'Benutzt Kokoreks Talisman in der Nähe der Totems, die den Weg ins Shalasversteck bewachen, und sprecht dann mit Aufklärer Nodak.', },
  },
  [9977] = {
    'Der Ring des Blutes: Die letzte Herausforderung',
    {'<Gurgthock zählt seinen riesigen Berg Gold.>|n|nIhr habt viel Geld eingebracht, $GKleiner:Kleine;. Wenn Ihr Mogor besiegt, verspreche ich, dass es sich für euch lohnen wird. Die ganzen Schmerzen, die Ihr im Ring des Blutes aushalten musstet, werden sich bezahlt machen.|n|nJetzt geht da rein und zeigt diesen Ogern, was in Euch steckt!', },
    {'Besiegt Mogor, Held der Totschläger. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.', },
  },
  [9978] = {
    'Mit allen Mitteln',
    {'Ich bin mir nicht sicher, was das zu bedeuten hat, aber ich weiß, wie wir an weitere Hinweise kommen können.|n|nEmpoor ist ein Händler der Zerschlagenen, der mit allen Arten von Waren und Informationen handelt. Wenn wir ihn zum Reden bringen könnten, bin ich mir sicher, dass er etwas Interessantes zu sagen hätte.|n|nEr reist auf der Straße zwischen Tuurem und Shattrath hin und her. Seid aber vorsichtig, er hat einen Leibwächter.', },
    nil,
  },
  [9979] = {
    'Windhändler Lathrai',
    {'Ich wurde gebeten, ein paar Kästen mit Waren bei einem Astralen in Shattrath abzuholen und auszuliefern.|n|nAls ich ihn das letzte Mal gesehen habe, stand er außerhalb der Taverne Weltenend im Unteren Viertel. Sein Name ist Windhändler Lathrai, mehr weiß ich nicht!|n|nWenn Ihr mehr wissen wollt, dann fragt ihn selbst!', },
    {'Sprecht mit Lathrai in der Nähe der Taverne Weltenend im Unteren Viertel in Shattrath.', },
  },
  [9980] = {
    'Rettet Deirom!',
    {'Macht Euch so schnell Ihr könnt ins Shalasversteck auf, $N! Zeit ist von äußerster Wichtigkeit. Wenn die Arakkoa bemerken, was Ihr mit ihrer Verteidigung angestellt habt, werden sie wahrscheinlich versuchen, Deirom wegzubringen oder gar zu töten!|n|nNehmt ein oder zwei Freunde mit, wenn Ihr könnt. Es wird wahrscheinlich hart werden. Die Vogelwesen haben alles getan, um ihren Gefangenen unter Verschluss zu halten, und sie werden ihn sicher nicht so leicht aufgeben. Wenn Ihr Deirom gefunden habt, kehrt zu Allerias Feste zurück und benachrichtigt Thander.', },
    {'Begebt Euch ins Shalasversteck, tötet Lunga und befreit Deirom. Meldet Euch bei Lady Dana Kennedy in Allerias Feste, wenn Ihr Euren Auftrag erledigt habt.', },
  },
  [9981] = {
    'Rettet Dugar!',
    {'Macht Euch so schnell Ihr könnt ins Shalasversteck auf, $N! Zeit ist von äußerster Wichtigkeit. Wenn die Arakkoa bemerken, was Ihr mit ihrer Verteidigung angestellt habt, werden sie wahrscheinlich versuchen, Dugar wegzubringen oder gar zu töten!|n|nNehmt ein oder zwei Freunde mit, wenn Ihr könnt. Es wird wahrscheinlich hart werden. Die Vogelwesen haben alles getan, um ihren Gefangenen unter Verschluss zu halten, und sie werden ihn sicher nicht so leicht aufgeben. Wenn Ihr Dugar gefunden habt, kehrt zur Steinbrecherfeste zurück und benachrichtigt Rokag.', },
    {'Begebt Euch ins Shalasversteck, tötet Lunga und befreit Dugar. Meldet Euch bei Rokag in der Steinbrecherfeste, wenn Ihr Euren Auftrag erledigt habt.', },
  },
  [9982] = {
    'Er nannte sich Altruis...',
    {'Ende letzter Woche kam ein Wesen auf einem Netherdrachen ins Dorf. Er stellte sich als Altruis vor und stellte uns ein paar Fragen über Nagrand.|n|nEr sagte, er würde die Legion jagen. Das so etwas Wahnsinniges tatsächlich sein Job wäre. Könnt Ihr Euch das vorstellen? Eine Person, die freiwillig Dämonen jagt?|n|nVor seiner Abreise bat er uns noch, angehende Helden wissen zu lassen, dass er eine Weile im Westen Nagrands bleiben würde, falls sie auf der Suche nach einer Aufgabe wären.', },
    {'Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand.', },
  },
  [9983] = {
    'Er nannte sich Altruis...',
    {'Ende letzter Woche kam ein Wesen auf einem Netherdrachen ins Dorf. Er stellte sich als Altruis vor und stellte uns ein paar Fragen über Nagrand.|n|nEr sagte, er würde die Legion jagen. Das so etwas Wahnsinniges tatsächlich sein Job wäre. Könnt Ihr Euch das vorstellen? Eine Person, die freiwillig Dämonen jagt?|n|nVor seiner Abreise bat er uns noch, angehende Helden wissen zu lassen, dass er eine Weile im Westen Nagrands bleiben würde, falls sie auf der Suche nach einer Aufgabe wären.', },
    {'Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand.', },
  },
  [9984] = {
    'Der Herr der versteckten Stadt',
    {'Auch wenn Ihr die merkwürdige Schrift auf der Rolle nicht lesen könnt, deutet das verzierte Siegel am Ende des Dokuments darauf hin, dass es von einem Arakkoa von höherem Rang geschrieben wurde. Luanga mag vielleicht hinter der Gefangennahme und dem Verhör von Deirom gesteckt haben, aber es scheint, als hätte er die Befehle einer anderen Person ausgeführt.|n|nIch erinnert Euch, dass Thander erwähnt hat, dass Andarl die Arakkoa studiert hat. Vielleicht kann er den Inhalt der Schriftrolle entziffern.', },
    {'Bringt Luangas Befehle zu Andarl in Allerias Feste in den Wäldern von Terokkar.', },
  },
  [9985] = {
    'Der Herr der versteckten Stadt',
    {'Auch wenn Ihr die merkwürdige Schrift auf der Rolle nicht lesen könnt, deutet das verzierte Siegel am Ende des Dokuments darauf hin, dass es von einem Arakkoa von höherem Rang geschrieben wurde. Luanga mag vielleicht hinter der Gefangennahme und dem Verhör von Dugar gesteckt haben, aber es scheint, als hätte er die Befehle einer anderen Person ausgeführt.|n|nIch erinnert Euch, dass Rokag erwähnt hat, dass Kurgatok die Arakkoa studiert hat. Vielleicht kann er den Inhalt der Schriftrolle entziffern.', },
    {'Bringt Luangas Befehle zu Kurgatok in der Steinbrecherfeste in den Wäldern von Terokkar.', },
  },
  [9986] = {
    'Die Arakkoa hindern',
    {'Wir müssen den Arakkoa zeigen, dass sie unsere Leute nicht ungestraft angreifen können. Wenn wir sie jetzt nicht aufhalten, werden unsere Straßen für die Händler, Kuriere oder Soldaten nicht mehr sicher sein.|n|nMeine Späher haben die Anführer der größeren Arakkoasiedlungen in der Gegend ermittelt. Sucht Ashkaz, Ayit und Urdak im Reskkversteck, im Shienorversteck und im Skithversteck und tötet sie.', },
    {'Tötet Ashkaz im Reskkversteck, Ayit im Shienorversteck und Urdak im Skithversteck und kehrt dann zu Thander in Allerias Feste zurück.', },
  },
  [9987] = {
    'Die Arakkoa hindern',
    {'Wir müssen den Arakkoa zeigen, dass sie unsere Leute nicht ungestraft angreifen können. Wenn wir sie jetzt nicht aufhalten, werden unsere Straßen für die Händler, Kuriere oder Soldaten nicht mehr sicher sein.|n|nMeine Späher haben die Anführer der größeren Arakkoasiedlungen in der Gegend ermittelt. Sucht Ashkaz, Ayit und Urdak im Reskkversteck, im Shienorversteck und im Skithversteck und tötet sie.', },
    {'Tötet Ashkaz im Reskkversteck, Ayit im Shienorversteck und Urdak im Skithversteck und kehrt dann zu Rokag in der Steinbrecherfeste zurück.', },
  },
  [9988] = {
    'Der beste Freund eines Gecken',
    {'Lasst Euch von Thander und seinem Gefolge nicht täuschen. Sie sehen vielleicht aus wie eine Gruppe von Furcht einflößenden Kriegern, aber sie sind nichts als eine Bande von Gecken!|n|nUnd sie lassen sich in der Öffentlichkeit nicht ohne ihre Hüte sehen. Das sind ganz schicke Teile aus Filz und Fell, mit den ausgefallensten Federn, die Ihr je gesehen habt.|n|nDie begehrtesten Federn stammen natürlich von den Arakkoa, und mein Vorrat geht langsam zur Neige. Ich würde Euch bezahlen, wenn Ihr sie für mich sammelt.', },
    {'Bringt 30 Arakkoafedern zu Ros\'eleth in Allerias Feste.', },
  },
  [9989] = {
    'Fremde Geister',
    {'Als ich in die Scherbenwelt kam und meine Ohren den Stimmen seiner Geister geöffnet habe, war ich erstaunt, was ich zu hören bekam. Nach einiger Zeit fand ich auch heraus, welche Geister ich nicht hören konnte.|n|nTrotz all meiner Versuche habe ich niemals mit den Geistern der Arakkoaahnen Kontakt aufnehmen können. Ihre Magie unterscheidet sich grundlegend von unserer, aber ich bin mir nicht sicher, ob ihre Geister außerhalb meiner Reichweite liegen.|n|nBringt mir die Federn vieler Arakkoa. Vielleicht kann ein Zeichen ihres Volks die nötige Verbindung herstellen.', },
    {'Bringt 30 Arakkoafedern zu Malukaz in der Steinbrecherfeste.', },
  },
  [9990] = {
    'Untersuchung von Tuurem',
    {'Wisst Ihr, jetzt, da Ihr es sagt, erinnere ich mich daran, dass ich Empoor vor etwa einem Monat mehrere Kästen mit merkwürdigen und fremdartigen Bauteilen verkauft habe. Ich weiß nicht, wozu sie gut sind, aber ich weiß, dass sie nach Tuurem geliefert werden sollten.|n|nVielleicht sind dort ja noch ein paar Kästen davon?', },
    {'Findet den versiegelten Kasten und bringt ihn zu Erdbinder Tavgren beim Cenariusdickicht in den Wäldern von Terokkar.', },
  },
  [9991] = {
    'Inspektion des Lagers',
    {'Wenn Ihr meine Augen sein wollt, müsst Ihr sehr sorgfältig sein. Nethrandamus wird Euch durch die Lager der Legion führen, aber Ihr müsst alles, was Ihr seht, katalogisieren. Selbst das kleinste Detail, und wenn Euch noch so unwichtig erscheint, kann für unsere Zwecke hilfreich sein.|n|nZuerst möchte ich, dass Ihr notiert, welchen Aufbau das Lager hat und wie seine Verteidigungsmaßnahmen aussehen.|n|nNethrandamus ist bereit, wenn Ihr es seid, $N. Habt keine Angst, er wird Euch beschützen.', },
    {'Lehnt Euch zurück und genießt Euren Flug. Sprecht mit Altruis wenn die Besichtigung abgeschlossen ist.', },
  },
  [9992] = {
    'Olembasamen',
    {'Sind die Bäume des Waldes nicht wunderschön? Ich habe mich schon oft gefragt, ob sie wohl auch in Azeroth wachsen würden.|n|nIch scheue mich jedoch davor, Keimlinge zurückzuschicken. Es ist ein anstrengender Weg und sie sind viel schwieriger zu transportieren als ein Sack mit Samen. Die Samenkörner wachsen in harten Zapfen, die von den Ästen der Bäume fallen, wenn sie reif sind.|n|nWenn Ihr auf Euren Reisen ein paar dieser Zapfen findet, könntet Ihr mir dann ein paar Samenkörner bringen?', },
    {'Sammelt 30 Olembasamenkörner und kehrt dann zu Ros\'eleth in Allerias Feste zurück.', },
  },
  [9993] = {
    'Olembaöl',
    {'Die öligen Samen der Olembabäume könnten sich als sehr wertvoll erweisen. Ich würde gern eine größere Menge davon sammeln und schauen, was ich daraus machen kann.|n|nStellt Euch nur vor, da steht ein ganzer Wald mit Bäumen, die so viele Samen produzieren, die alle ungenutzt bleiben. Mir ist egal, ob ich nur Salatöl, Waffenöl oder Lampenöl daraus herstellen kann, ich werde ihre Verschwendung nicht dulden!|n|nBringt mir alle Samen, die Ihr von den Olembazapfen sammeln könnt. Sie liegen hier überall.', },
    {'Bringt 30 Olembasamenkörner zu Rakoria in der Steinbrecherfeste.', },
  },
  [9994] = {
    'Was ist das?',
    {'Ich weiß nicht, wie es Euch geht, aber ich habe keine Ahnung, was das ist. Ich weiß nur eins: sie sehen gefährlich aus!|n|n$N, ich glaube, Ihr solltet diesen Kasten mit Ersatzteilen zu Jenai Sternwisper in Allerias Feste im Südosten bringen. Vielleicht hat sie ja eine Ahnung, was das ist.', },
    {'Bringt den Kasten mit Ersatzteilen zu Jenai Sternwisper in Allerias Feste in den Wäldern von Terokkar.', },
  },
  [9995] = {
    'Was ist das?',
    {'Ich weiß nicht, wie es Euch geht, aber ich habe keine Ahnung, was das ist. Ich weiß nur eins: sie sehen gefährlich aus!|n|n$N, ich glaube, Ihr solltet diesen Kasten mit Ersatzteilen zu Tooki in die Steinbrecherfeste im Südosten bringen. Vielleicht hat er ja eine Ahnung, was das ist.', },
    {'Bringt den Kasten mit Ersatzteilen zu Tooki in der Steinbrecherfeste in den Wäldern von Terokkar.', },
  },
  [9996] = {
    'Angriff auf den Posten der Feuerschwingen',
    {'Wir wissen, dass die Blutelfen der Feuerschwingen für Illidan arbeiten. Und nach dem, was Ihr mir erzählt habt, benutzen sie die Zerschlagenen von Tuurem als Schmuggler, um eine furchtbare Waffe herzustellen.|n|nWas immer sie vorhaben mögen, das Beste, was wir nun tun können, ist, sie zu dezimieren.|n|nDie Blutelfen der Feuerschwingen müssen vernichtet werden! Begebt Euch zum Posten der Feuerschwingen im Norden und kümmert Euch darum!', },
    {'Tötet 10 Verteidiger der Feuerschwingen, 10 Blutwärter der Feuerschwingen und 10 Hexenmeister der Feuerschwingen. Meldet Euch dann bei Leutnant Meridian bei Allerias Posten in den Wäldern von Terokkar zurück.', },
  },
  [9997] = {
    'Angriff auf den Posten der Feuerschwingen',
    {'Wir wissen, dass die Blutelfen der Feuerschwingen für Illidan arbeiten. Und nach dem, was Ihr mir erzählt habt, benutzen sie die Zerschlagenen von Tuurem als Schmuggler, um eine furchtbare Waffe herzustellen.|n|nWas immer sie vorhaben mögen, das Beste, was wir nun tun können, ist, sie zu dezimieren.|n|nDie Blutelfen der Feuerschwingen müssen vernichtet werden! Begebt Euch zum Posten der Feuerschwingen im Nordosten und kümmert Euch darum!', },
    {'Tötet 10 Verteidiger der Feuerschwingen, 10 Blutwärter der Feuerschwingen und 10 Hexenmeister der Feuerschwingen. Meldet Euch dann bei Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar zurück.', },
  },
  [9998] = {
    'Widerspenstige Nachbarn',
    {'Thander ist über die Ankunft der Höllenorcs bei den Ruinen vor Kurzem sowohl überrascht als auch besorgt. Sie haben keine Zeit verschwendet und sofort begonnen, Befestigungsanlagen zu bauen und die Gebäude zu reparieren.|n|nDie Bauarbeiten laufen Tag und Nacht, $N. Ich habe ein paar meiner zuverlässigsten Agenten losgeschickt, um die Situation zu überwachen, aber wir können uns keine Verzögerungen leisten. Geht gegen ihre Arbeiter vor und sucht dann nach Theloria Dämmermantel bei Allerias Posten nördlich der Ruinen der Knochenmalmer. Sie wird Euch weitere Anweisungen geben.', },
    nil,
  },
  [9999] = {
    'Spiel auf Zeit',
    {'Solange die Transporter noch stehen, ist nichts, was wir gegen die Konstruktionslager unternehmen, von Dauer. Wir müssen einen Weg finden, die Gebäude der Legion zu zerstören.|n|nIch brauche Zeit, um einen Angriffsplan auszuarbeiten. Wenn Ihr die Ingenieure und Tüftler eine Weile beschäftigen könntet, würde das ihre Fortschritte verlangsamen, und ich hätte die Zeit, die ich benötige.', },
    {'Altruis der Leidende im westlichen Nagrand möchte, dass Ihr 2 Legionäre der Teufelswache, 3 Ingenieure der Mo\'arg und 8 Tüftler der Gan\'arg tötet.', },
  },
  [10000] = {
    'Unangenehme Gesellschaft',
    {'Unsere Streitkräfte in Thrallmar dachten, sie hätten die Höllenorcs der Höllenfeuerzitadelle unter Kontrolle, aber die Neuankömmlinge in den Ruinen im Osten sagen etwas anderes.|n|nWir können ihnen nicht erlauben, hier Fuß zu fassen. Rokag hat Schattenpirscher Kaide zu den Ruinen geschickt, um sie zu beobachten, aber wir müssen sie aufhalten, bevor sie es sich zu bequem machen.|n|nGeht zu den Ruinen, dezimiert ihre Peons und haltet bei den Bäumen im Norden nach Kaide Ausschau. Er wird Euch sagen, wo Ihr danach hingehen sollt.', },
    {'Tötet 12 verunstaltete Peons und meldet Euch dann bei Schattenpirscher Kaide.', },
  },
  [10001] = {
    'Der Meisterplaner',
    {'Alle Konstruktionslager haben einen Meisterplaner. Der Meisterplaner bestimmt, welche Gebäude im Konstruktionslager vorhanden sein müssen, und wie sie platziert werden. Zudem werden diese Informationen auf Blaupausen festgehalten, die der Planer bei sich trägt.|n|nWir brauchen die Blaupausen des Meisterplaners. Mit solch detaillierten Informationen könnten wir einen meiner Bekannten dazu bewegen, uns etwas Unterstützung zu schicken.|n|nSucht den Meisterplaner der Mo\'arg und stehlt seine Blaupausen. Er wird sich hinter den Konstruktionen aufhalten.', },
    {'Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners besorgt.', },
  },
  [10002] = {
    'Vermittler der Feuerschwingen',
    {'In den letzten paar Tagen habe ich beobachtet, wie eine Blutelfenfrau immer wieder zur Höllenorcfeste gegangen ist, um mit dem Anführer der Höllenorcs zu reden. Ihrer Körpersprache nach verteilt sie Befehle. Aber warum? Wessen Befehle überbringt sie?|n|nDie Neugier hat über mich gesiegt, deshalb habe ich sie auf dem Weg zurück vom Höllenorclager beschattet. Sie ging nach Norden, zum Posten der Feuerschwingen. Ich musste mich zurückziehen, bevor ich den Blutelfenposten erreichte.|n|nTötet sie, bevor sie das Höllenorclager wieder verlassen kann.', },
    {'Findet und tötet Lisaile Feuerweber und kehrt dann zu Theloria Dämmermantel zurück.', },
  },
  [10003] = {
    'Vermittler der Feuerschwingen',
    {'In den letzten paar Tagen habe ich beobachtet, wie eine Blutelfenfrau immer wieder zur Höllenorcfeste gegangen ist, um mit dem Anführer der Höllenorcs zu reden. Ihrer Körpersprache nach verteilt sie Befehle. Aber warum? Wessen Befehle überbringt sie?|n|nDie Neugier hat über mich gesiegt, deshalb habe ich sie auf dem Weg zurück vom Höllenorclager beschattet. Sie ging nach Norden, zum Posten der Feuerschwingen. Ich musste mich zurückziehen, bevor ich den Blutelfenposten erreichte.|n|nTötet sie, bevor sie das Höllenorclager wieder verlassen kann.', },
    {'Findet und tötet Lisaile Feuerweber und kehrt dann zu Schattenpirscher Kaide zurück.', },
  },
  [10004] = {
    'Geduld und Verständnis',
    {'Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners zu Sal\'salabim in Shattrath bringt und ihn überredet, euch zu helfen.', },
    {'Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners zu Sal\'salabim in Shattrath bringt und ihn überredet, euch zu helfen.', },
  },
  [10005] = {
    'Erdbinder Tavgren Bescheid sagen',
    {'$N, ich glaube, Ihr solltet zum Cenariusdickicht zurückgehen und mit Erdbinder Tavgren sprechen.|n|nIch bin mir sicher, dass er wissen möchte, was hier wirklich passiert ist.', },
    {'Sprecht mit Erdbinder Tavgren außerhalb des Cenariusdickichts in den Wäldern von Terokkar.', },
  },
  [10006] = {
    'Erdbinder Tavgren Bescheid sagen',
    {'$N, ich glaube, Ihr solltet zum Cenariusdickicht zurückgehen und mit Erdbinder Tavgren sprechen.|n|nIch bin mir sicher, dass er wissen möchte, was hier wirklich passiert ist.', },
    {'Sprecht mit Erdbinder Tavgren außerhalb des Cenariusdickichts in den Wäldern von Terokkar.', },
  },
  [10007] = {
    'Die Reihen lichten',
    {'So wie ich Thander und Bertelm kenne, werden sie nicht dulden, dass eine feindliche Macht so ein großes Lager direkt vor unserer Haustüre errichtet. Aber sie zu bitten, ein paar Leute ihrer Garnison zu schicken, um das Lager anzugreifen, steht auch nicht zur Debatte. Wir wären dann viel zu leicht angreifbar.|n|nWir müssen uns also selbst darum kümmern, die Bedrohung durch die Bauarbeiten der Höllenorcs zu verringern. Tötet alle von ihnen, die Ihr könnt, und ich sehe mich solange nach Verstärkung um.', },
    {'Tötet 10 Verwüster der Knochenmalmer und 6 Kreuzbrecher der Knochenmalmer und kehrt dann zu Theloria Dämmermantel zurück.', },
  },
  [10008] = {
    'Was in Terokkar geschieht, bleibt in Terokkar',
    {'Wenn Thrallmar erfährt, dass sie es nicht geschafft haben, die Höllenorcs unter Kontrolle zu halten, werden wir hier bald viel Gesellschaft haben. Ehrlich gesagt bin ich mir nicht sicher, ob ich so viel Aufmerksamkeit möchte, deswegen behalten wir dieses kleine Problem für uns, verstanden?|n|nWenn wir den Höllenorcs genug Verluste beibringen können, besteht die Möglichkeit, dass niemand außerhalb der Steinbrecherfeste von ihrer Anwesenheit erfährt.|n|nMarschiert da rein, schwingt Eure Waffe, wedelt mit der Hand - oder was auch immer Ihr tut - und tötet die Höllenorcs!', },
    {'Schattenpirscher Kaide möchte, dass Ihr 10 Verwüster der Knochenmalmer und 6 Kreuzbrecher der Knochenmalmer tötet.', },
  },
  [10009] = {
    'Ein paar Schädel spalten',
    {'<Sal\'salabim lacht.>|n|nDas Sal\'salabims Entwurf.|n|n<Sal\'salabim zeigt auf die Architektur und die Anordnungen auf den Blaupausen.>|n|nSchaut Türme an. Dämonenjäger kann nicht sehen, oder? Armer, armer Altruis. Er weinen wenn er Augen hätte, oder?|n|nJa, Sal\'salabim helfen, aber erst Ihr helfen Sal\'salabim.|n|n<Sal\'salabim gibt Euch einen Ordner.>|n|nDiese Wesen schulden Sal\'salabim Gold. Viel Gold. Gehen für Sal\'salabim eintreiben. Sie werden nicht einfach rausrücken Sal\'salabims Gold. Müssen kämpfen, aber Ihr stark. Ihr besiegen Sal\'salabim!', },
    {'Sal\'salabim in Shattrath möchte, dass Ihr Raliqs Schulden, Kusch\'kuschs Schulden und Floons Schulden eintreibt.', },
  },
  [10010] = {
    'So einfach ist das?',
    {'<Sal\'salabim zeigt auf die Blaupause.>|n|nSeht Ihr, wo Teufelskanonen sind?|n|n<Sal\'salabim zeichnet einen Pfeil, der einen Richtungswechsel anzeigt.>|n|nIhr dreht Teufelskanone um und richtet sie auf Gebäude.|n|nWartet! Nicht durchdrehen! Ihr wisst etwas nicht. Vorarbeiter haben Schlüssel, um Kanonen zu drehen. Ihr braucht erst Schlüssel! Einer von jedem Vorarbeiter!|n|nNicht so leicht, was?|n|nBringt Information zurück zu Altruis.', },
    {'Sal\'salabim in Shattrath möchte, dass Ihr zu Altruis dem Leider im westlichen Nagrand zurückkehrt.', },
  },
  [10011] = {
    'Konstruktionslager: zerstört',
    {'Sammelt Euren Mut, $N. Ihr werdet ihn brauchen, wenn Ihr einem Vorarbeiter gegenübersteht.|n|nSobald Ihr bereit seid, sucht und tötet die Vorarbeiter in jedem Lager. Nehmt ihre Schlüssel und benutzt sie, um die Kanonen umzudrehen. Schießt damit auf die Lager. Kehrt zu mir zurück, wenn die Lager zerstört sind.', },
    {'Altruis der Leidende im westlichen Nagrand möchte, dass Ihr das Konstruktionslager: Hass und das Konstruktionslager: Furcht zerstört.', },
  },
  [10012] = {
    'Höllenorcpläne',
    {'Die Schrift auf diesen Plänen ist zu fein und genau, um von einem Höllenorc zu stammen. Ihr könnt nicht verstehen, was der Text bedeutet, aber die Zeichen sind eindeutig: die Höllenorcs erhalten Befehle von den Blutelfen im Posten der Feuerschwingen.|n|nWarum arbeiten die beiden Fraktionen zusammen? Vielleicht weiß Bertelm mehr über dieses merkwürdige Bündnis. Ihr beschließt, zu Allerias Feste zurückzukehren und ihm die Pläne zu zeigen.', },
    nil,
  },
  [10013] = {
    'Eine ungesehene Hand',
    {'Die Schrift auf diesen Plänen ist zu fein und genau, um von einem Höllenorc zu stammen. Ihr könnt nicht verstehen, was der Text bedeutet, aber die Zeichen sind eindeutig: die Höllenorcs erhalten Befehle von den Blutelfen im Posten der Feuerschwingen.|n|nWarum arbeiten die beiden Fraktionen zusammen? Vielleicht weiß Rokag mehr über dieses merkwürdige Bündnis. Ihr beschließt, zur Steinbrecherfeste zurückzukehren und ihm die Pläne zu zeigen.', },
    nil,
  },
  [10014] = {
    'Das Projekt des Postens der Feuerschwingen',
    {'Wie ich bereits erwähnt habe, haben wir einige weitere Informationen erhalten, die besagen, dass wir ein weitaus größeres Problem haben.|n|nDie Blutelfen sind im Posten der Feuerschwingen mit dem Bau einer weiteren Manabombe beschäftigt. Ich kann nicht genug betonen, dass sie eindeutig vorhaben, diese Bombe gegen Allerias Feste einzusetzen!|n|nMeine Späher berichten mir, dass sie die Codes für die Waffe in vier kleineren Gebäuden um den mittleren Hof herum aufbewahren. Geht dorthin und besorgt die Codes, bevor es zu spät ist!', },
    {'Stehlt die vier Codetabellen der Manabombe und bringt sie zu Meridian in Allerias Posten in den Wäldern von Terokkar.', },
  },
  [10015] = {
    'Das Projekt des Postens der Feuerschwingen',
    {'Wie ich bereits erwähnt habe, haben wir einige weitere Informationen erhalten, die besagen, dass wir ein weitaus größeres Problem haben.|n|nDie Blutelfen sind im Posten der Feuerschwingen mit dem Bau einer weiteren Manabombe beschäftigt. Ich kann nicht genug betonen, dass sie eindeutig vorhaben, diese Bombe gegen die Steinbrecherfeste einzusetzen!|n|nMeine Späher berichten mir, dass sie die Codes für die Waffe in vier kleineren Gebäuden um den mittleren Hof herum aufbewahren. Geht dorthin und besorgt die Codes, bevor es zu spät ist!', },
    {'Stehlt die vier Codetabellen der Manabombe und bringt sie zu Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar.', },
  },
  [10016] = {
    'Waldworgschwänze',
    {'Seid Ihr auf Euren Reisen den Waldworgs begegnet? Ich hatte die Gelegenheit, sie zu beobachten, als ich einige der nördlichen Regionen des Waldes kartografiert habe. Ich würde Euch nicht empfehlen, zu nahe an sie heranzugehen, es sei denn, Ihr seid bereit für einen Kampf.|n|nSie haben keine Angst und scheuen vor nichts zurück, um ihr Territorium zu verteidigen.|n|nEs ist nicht verwunderlich, dass diese Kreaturen solch wundervolle Schwänze haben. Ich habe versucht, ein paar von ihnen zu sammeln, um einen neuen Mantel zu schneidern, aber die Worgs entkommen meinen Fallen dauernd. Wollt Ihr mir helfen?', },
    {'Bertelm in Allerias Feste möchte, dass Ihr ihm 12 Waldworgschwänze bringt. Die Schwänze können von Waldworgs oder Waldworgalphas stammen.', },
  },
  [10017] = {
    'Schwindende Vorräte',
    {'Immer mehr Flüchtlinge kommen Tag für Tag durch die Tore von Shattrath. Viele sind so schwer verwundet, dass es an ein Wunder grenzt, dass sie es überhaupt hierher geschafft haben.|n|nAls Heiler der Aldor kann ich die meisten gewöhnlichen Wunden verarzten. Vergiftete Wunden sind jedoch problematischer, da mir langsam die Vorräte an Gegengift ausgehen.|n|nBringt mir ein paar Schreckensgiftbeutel von den Schreckensspinnen hier in der Gegend, damit ich mehr davon herstellen kann. Ihr findet eine Gruppe von diesen Spinnen im Südosten von Terokkar.', },
    {'Bringt 8 Schreckensgiftbeutel zu Sha\'nir in Shattrath.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10018] = {
    'Gewänder des Wolfgeistes',
    {'Vor Generationen, als die Orcs die Wälder von Terokkar noch ihr Zuhause nannten, spielte der Wolfgeist eine große Rolle in ihrem Leben. Als die Orcs fortgingen, brauchten sie den Wolfgeist nicht mehr und haben ihn zurückgelassen.|n|nMit der Zeit wurde der Geist einsam und verließ die Wälder ebenfalls.|n|nIch glaube, dass ich den Wolfgeist zu seinem ursprünglichen Heim zurückbringen kann, wie auch wir Orcs zurückgekehrt sind. Das Ritual erfordert, dass ich ein Gewand aus den Pelzen der Wölfe der Wälder schneidere, um den Wolfgeist zu seinem Zuhause zurück zu geleiten.', },
    {'Bringt 12 Waldworgpelze zu Malukaz in der Steinbrecherfeste.', },
  },
  [10019] = {
    'Mehr Giftbeutel',
    nil,
    nil,
  },
  [10020] = {
    'Ein Heilmittel für Zahlia',
    {'Die Frau rechts von mir hat eine schwere Kopfverletzung erlitten. Sie hat zwar überlebt, aber ihr Augenlicht verloren.|n|nEin traditionelles Heilmittel meines Volkes verlangt das Blut eines sehr alten Basilisken.|n|nUnglücklicherweise leben die Basilisken von Terokkar wegen der Wilderei verschiedener Lager in der Regel nicht sehr lange.|n|nEs gibt jedoch einen Basilisken, dessen Name ich schon als Kind kannte. Er ist als Steinstarrer bekannt und soll östlich von hier leben, in der Nähe der Landesgrenze.|n|nBringt mir sein Blut, damit Zahlia wieder sehen kann.', },
    {'Bringt Steinstarrers Blut zu Sha\'nir in Shattrath.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10021] = {
    'Das Licht wiederherstellen',
    {'Vor langer Zeit war ein Großteil dieses Gebiets von den Draenei bewohnt. Wir, die Aldor, hatten den Auftrag, unsere heiligen Stätten und Altäre zu beschützen. Doch seitdem wurden viele davon zerstört oder von unseren Feinden eingenommen.|n|nÖstlich von hier gibt es einen Außenposten der Arakkoa. Sie haben ihn mit voller Absicht auf dem Gebiet errichtet, auf dem drei unserer heiligen Altäre stehen. Die Arakkoa haben ihre üble Magie benutzt, um die ureigene Macht unserer Schreine zu verändern und zu schänden.|n|nBringt dies zum Arakkoaaußenposten und reinigt die drei Altäre.', },
    {'Ishanah möchte, dass Ihr zum Arakkoaaußenposten östlich von Shattrath geht. Benutzt die gesegnete Phiole, um den östlichen Altar, den westlichen Altar und den nördlichen Altar zu reinigen.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10022] = {
    'Der schwer zu fassende Eisenkiefer',
    {'Jetzt, da ich das Fell habe, das ich für mein Gewand benötige, dachte ich, dass der Pelz eines ganz bestimmten Wolfs eine schöne Kapuze für meinen Umhang abgeben würde. Stellt Euch nur vor, wie es wäre, Euren Feind im Pelz des gerissensten Raubtiers der Wälder zu sehen!|n|nIch habe bisher vergeblich versucht, Eisenkiefer zu fangen. Ich habe versucht ihn in die Enge zu treiben, ihn zu überlisten und ihn zu locken. Nichts hat geklappt.|n|nEr streunt in den nordöstlichen Gebieten des Waldes herum, und ich würde Euch angemessen belohnen, wenn Ihr schafft, was mir nie gelang.', },
    {'Bringt Eisenkiefers Pelz zu Bertelm in Allerias Feste.', },
  },
  [10023] = {
    'Patriarch Eisenkiefer',
    {'Ihr habt gute Arbeit beim Sammeln der ersten Pelze geleistet.|n|nDas letzte Stück der Gewandung erfordert einen ganz besonderen Pelz. Es gibt einen bestimmten Wolf, der alt und gerissen ist, und sich dadurch den Rang des Patriarchen unter den Wölfen des Waldes verdient hat. Er ist unter ihnen als Eisenkiefer, der mächtige Jäger, bekannt.|n|nIn meinen Visionen habe ich ihn im Nordosten der Wälder umherstreifen sehen. Sein Pelz in meiner Gewandung wird sicher den Pfad des Wolfgeistes erhellen.|n|nBeklagt Eisenkiefer nicht. Er wird die ihm gebührende Ehre erhalten.', },
    {'Bringt Eisenkiefers Pelz zu Malukaz in der Steinbrecherfeste.', },
  },
  [10024] = {
    'Voren\'thals Visionen',
    {'Unser Anführer, Voren\'thal der Seher, war einst ein enger Vertrauter von Kael\'thas. Seine prophetischen Visionen habe ihn gewarnt, dass Kaels Weg in der Zerstörung unseres Volkes enden würde.|n|nNormalerweise sind diese Visionen nur sehr vage und ungenau, aber unsere Alchemisten haben ein Elixier entwickelt, mit dessen Hilfe seine Visionen deutlicher werden. Unglücklicherweise erfordert das Elixier eine sehr seltene Zutat: Basiliskenaugen. Normalerweise bekomme ich sie von diesem aufgeblasenen Astralen, aber er hat mich enttäuscht.|n|nMacht Euch auf die Suche nach den Dunstschuppenbasilisken im gebirgigen Terokkar und bringt mir ihre Augen.', },
    {'Bringt 8 Augen eines Dunstschuppenbasilisken zu Arkanist Adyria in Shattrath.|n|nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10025] = {
    'Mehr Basiliskenaugen',
    nil,
    nil,
  },
  [10026] = {
    'Magische Störungen',
    {'Es ist mir ein wenig peinlich, aber mir ist hier in den Wäldern von Terokkar etwas widerfahren, was mir seit meinen Lehrjahren nicht mehr passiert ist.|n|nManchmal scheitern meine Zauber, obwohl ich genau weiß, dass ich alles richtig gemacht habe. Ich bin fast wahnsinnig geworden, als das zum ersten Mal passiert ist.|n|nIch glaube, ich habe den Grund dafür gefunden. Die Wälder sind voller Wesen, die Sphärenjäger genannt werden. Das sind dämonische Kreaturen mit einem Hang zur Magie und zur Störung magischer Ströme. Der beste Weg, um mit ihnen fertigzuwerden, ist, sie einfach zu töten.', },
    {'Andarl in Allerias Feste möchte, dass Ihr 10 Sphärenjäger tötet.', },
  },
  [10027] = {
    'Magische Störungen',
    {'Es gibt nichts Ärgerlicheres, als einen Zauber vorzubereiten, und dann von einer unsichtbaren Macht unterbrochen zu werden. Nach dem vierten Mal wusste ich, dass es kein Zufall sein konnte, und habe Keb\'ezil losgeschickt, um die Ursache herauszufinden.|n|nIch garantiere Euch, dass Ihr nie einen Wichtel treffen werdet, der widerspenstiger ist als Keb.|n|nWie auch immer, er konnte die Quelle des Problems finden, eine verteufelte Kreatur namens Sphärenjäger. Sie haben die Angewohnheit, überall, wo sie auftauchen, die magischen Energien zu stören. Ich habe genug von ihren Störungen.', },
    {'Tötet 10 Sphärenjäger und kehrt dann zu Kurgatok in der Steinbrecherfeste zurück.', },
  },
  [10028] = {
    'Gefäße der Macht',
    {'Zwischen den Ruinen von Tuurem gibt es einige Gefäße mit roher, magischer Energie. Wir können von Glück sagen, dass die Zerschlagenen, die in der Stadt eingefallen sind, keine Ahnung von dieser Machtquelle mitten unter ihnen haben, aber wir dürfen nicht hoffen, dass das so bleibt.|n|nMithilfe dieser Gefäße und ihrer Macht können die verstreuten Überlebenden meines Volkes der Verlockung der dämonischen Magie widerstehen. Jeder Quel\'dorei, den wir vor dem Wahnsinn unseres Prinzen retten können, ist einer mehr, der uns beim Wiederaufbau unseres verlorenen Ruhms helfen kann. Bringt mir die Gefäße, $C.', },
    {'Bringt 8 Draeneigefäße zu Ros\'eleth in Allerias Feste.', },
  },
  [10029] = {
    'Die Geister rufen',
    {'Anachoret Lyteera möchte, dass Ihr ihren Gehilfen Soolaveen bei der Flüchtlingskarawane in der Knochenwüste der Wälder von Terokkar findet.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
    {'Anachoret Lyteera möchte, dass Ihr ihren Gehilfen Soolaveen bei der Flüchtlingskarawane in der Knochenwüste der Wälder von Terokkar findet.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10030] = {
    'Die Knochen zurückholen',
    {'Sammelt 10 ruhelose Knochen und bringt sie zu Ramdor dem Wahnsinnigen bei der westlichen Seite des Rings der Beobachtung in Auchindoun, das sich in der Mitte der Knochenwüste in den Wäldern von Terokkar befindet.', },
    {'Sammelt 10 ruhelose Knochen und bringt sie zu Ramdor dem Wahnsinnigen bei der westlichen Seite des Rings der Beobachtung in Auchindoun, das sich in der Mitte der Knochenwüste in den Wäldern von Terokkar befindet.', },
  },
  [10031] = {
    'Den Verirrten den Weg zeigen',
    {'Tötet 10 verirrte Geister und 10 Skelette eines Zerschlagenen und kehrt dann zu Anachoret Soolaveen bei der Flüchtlingskarawane in der Knochenwüste in den Wäldern von Terokkar zurück.', },
    {'Tötet 10 verirrte Geister und 10 Skelette eines Zerschlagenen und kehrt dann zu Anachoret Soolaveen bei der Flüchtlingskarawane in der Knochenwüste in den Wäldern von Terokkar zurück.', },
  },
  [10032] = {
    'Artefakte von Tuurem',
    {'Ist Euch das Verhalten der Verirrten in Tuurem aufgefallen? Sie streifen in den Ruinen umher und suchen nach allen Überbleibseln der Draenei, die sie in die Finger bekommen können.|n|nIhre zerschlagenen Meister wissen es besser. Sie haben ihr früheres Leben abgestreift und sind zu etwas ganz anderem geworden.|n|nIch glaube, wir können die Gier der Verirrten ausnutzen und alte Draeneirelikte von ihnen sammeln. Warum sollten wir unser Leben im Kampf gegen die Zerschlagenen riskieren, wenn wir unsere Ziele weise auswählen können?', },
    {'Sammelt 6 Artefakte von Tuurem von den Strauchdieben von Tuurem und den Jägern von Tuurem und bringt sie zu Rakoria in der Steinbrecherfeste.', },
  },
  [10033] = {
    'Aufruf: Tötet die Knochenpeitscher!',
    {'Es wurde ein Kopfgeld auf die Knochenpeitscher der Knochenwüste ausgesetzt. Als Überträger der Pest müssen sie von nun an vernichtet werden!|n|nObgleich sie in der gesamten Wüste vertreten sind, ist die größte Ansammlung bekanntermaßen beim Aashügel im Norden anzutreffen.|n|nMeldet Euch bei Taela Immerlauf, um Eure Belohnung einzufordern.', },
    {'Tötet 20 Knochenpeitscher und meldet Euch dann bei Taela Immerlauf in Allerias Feste in den Wäldern von Terokkar.', },
  },
  [10034] = {
    'Aufruf: Tötet die Knochenpeitscher!',
    {'Die Knochenpeitscher der Knochenwüste haben Mawg gebissen und ihn krank gemacht. Jetzt möchte er, dass sie alle vernichtet werden!|n|nObgleich sie in der gesamten Wüste vertreten sind, ist die größte Ansammlung bekanntermaßen beim Aashügel im Norden anzutreffen.|n|nKehrt zu Mawg Grimmschlag zurück, wenn Ihr die Aufgabe erledigt habt, und er wird Euch gut belohnen.', },
    {'Tötet 20 Knochenpeitscher und meldet Euch dann bei Mawg Grimmschlag in der Steinbrecherfeste in den Wäldern von Terokkar.', },
  },
  [10035] = {
    nil,
    {'In der Knochenwüste gibt es ein Wesen, das so bösartig, so widerlich und so Furcht einflößend ist, dass nur die besten Jäger es wagen, ihm aufzulauern.|n|nIch spreche von Torgos, dem König der Knochenpeitscher, der sich beim Rhazeversteck am westlichen Ende der Weiten herumtreibt.|n|nUnglücklicherweise haben die Arakkoa eine Vogelscheuche aufgestellt, die als \'Torgos\' Fluch\' bekannt ist und ihn von dort fernhält. Ich wette, dass er trotzdem herauskommen würde, wenn Ihr den Leichnam seines Weibchens Trachela am Fuß dieser Vogelscheuche platziert. Ihr findet sie beim Aashügel im nördlichen Teil der Wüste.|n|nBringt mir eine Schwanzfeder von Torgos.', },
    {'Benutzt Trachelas Leichnam, um Torgos zu rufen. Besorgt eine Schwanzfeder von Torgos und kehrt dann zu Taela Immerlauf in Allerias Feste in den Wäldern von Terokkar zurück.', },
  },
  [10036] = {
    nil,
    {'Ich will Torgos, den König der Knochenpeitscher tot sehen!|n|nVor nicht allzu langer Zeit, als ich beim Rhazeversteck am westlichen Ende der Wüste auf Jagd war, fiel dieses Tier mich an.|n|n<Mawg tippt seine Augenklappe an.>|n|nEr hat mir mein Auge genommen, und nun will ich sein Leben dafür! Bringt mir eine seiner Schwanzfedern als Beweis und ich werde Euch gebührlich belohnen.|n|nIhr werdet den Leichnam seines Weibchens Trachela brauchen, um ihn hervorzulocken, da er Todesangst vor der alten Vogelscheuche der Arakkoa hat, die als Torgos\' Fluch bekannt ist.|n|nIhr findet sie beim Aashügel im Norden der Wüste.', },
    {'Benutzt Trachelas Leichnam, um Torgos zu rufen. Besorgt eine Schwanzfeder von Torgos und kehrt dann zu Mawg Grimmschlag in der Steinbrecherfeste in den Wäldern von Terokkar zurück.', },
  },
  [10037] = {
    'Ich würd\' lieber angeln',
    {'Da wir gerade von Seen sprechen, da gibt es einen See im Nordosten, an dem man richtig toll angeln kann. Früher bin ich da immer mit meinen Freunden hin, aber meine Mutter erlaubt es mir nicht mehr.|n|nSie sagt, es sei zu gefährlich, aber ich habe da oben noch nichts außer ein paar Spinnen gesehen. Als ob Spinnen einem irgendwas anhaben könnten...|n|nIch mochte am liebsten die Aale von da oben. Wenn Ihr zum See hoch geht, könntet Ihr mir dann ein paar dieser Aale bringen? Sie sind störrisch, aber wenn man sie einmal gebändigt hat, kann man sie ganz leicht mitnehmen.', },
    nil,
  },
  [10038] = {
    'Sprecht mit Gefreiter Wöch',
    {'Ich habe gerade einen Bericht von einem unserer Späher in der Nähe von Grangol\'var erhalten. Er sagt, dass eine schattenhafte Truppe in die Ruinen dort eingezogen ist.|n|n$N, ich möchte, dass Ihr mit Gefreiter Wöch sprecht und schaut, wie Ihr ihm dabei helfen könnt herauszufinden, was diese Unbekannten dort im Schilde führen.|n|nGeht nach Westen an der Steinbrecherfeste vorbei. Sein letzter Bericht besagt, dass er sich in der Nähe des nördlichen Eingangs zum Dorf befindet.', },
    nil,
  },
  [10039] = {
    'Sprecht mit Späherin Neftis',
    {'Ich wurde informiert, dass eine unserer Späherinnen in der Nähe von Grangol\'var zurzeit eine schattenhafte Truppe beobachtet, die vor Kurzem dorthin gezogen ist.|n|n$N, ich möchte, dass Ihr mit Späherin Neftis sprecht und schaut, wie Ihr ihr dabei helfen könnt herauszufinden, was diese Unbekannten dort im Schilde führen.|n|nGeht von hier aus nach Süden und dann nach Westen, um den Norden der Knochenwüste herum. Ihr letzter Bericht besagt, dass sie sich in der Nähe des südlichen Eingangs zum Dorf befindet.', },
    nil,
  },
  [10040] = {
    'Wer sind sie?',
    {'Ich weiß nicht, wer sie sind, aber ich weiß, dass sie uns feindlich gesonnen sind!|n|nIch werde Euch eine Verkleidung geben und möchte, dass Ihr da hinein geht und mit den Dreien sprecht, die ich für redselig halte. Sprecht mit dem Initiand, dem Hilfsarbeiter und dem Berater.|n|nSeid aber vorsichtig; es gibt dort ein paar Jäger, die Eure Verkleidung durchschauen können, und sie schauen ganz genau! Und was auch immer Ihr tut, verlasst das Dorf nicht. Die Verkleidung ist etwas dürftig. Wenn Ihr sie verliert, kommt zu mir zurück und ich gebe Euch eine neue.', },
    {'Sprecht mit dem schattenhaften Initianden, dem schattenhaften Hilfsarbeiter und dem schattenhaften Berater. Kehrt dann zu Gefreiter Wöch in Grangol\'var in den Wäldern von Terokkar zurück.', },
  },
  [10041] = {
    'Wer sind sie?',
    {'Ich weiß nicht, wer sie sind, aber ich weiß, dass sie uns feindlich gesonnen sind!|n|nIch werde Euch eine Verkleidung geben und möchte, dass Ihr da hinein geht und mit den Dreien sprecht, die ich für redselig halte. Sprecht mit dem Initiand, dem Hilfsarbeiter und dem Berater.|n|nSeid aber vorsichtig; es gibt dort ein paar Jäger, die Eure Verkleidung durchschauen können, und sie schauen ganz genau! Und was auch immer Ihr tut, verlasst das Dorf nicht. Die Verkleidung ist etwas dürftig. Wenn Ihr sie verliert, kommt zu mir zurück und ich gebe Euch eine neue.', },
    {'Sprecht mit dem schattenhaften Initianden, dem schattenhaften Hilfsarbeiter und dem schattenhaften Berater. Kehrt dann zu Späherin Neftis in Grangol\'var in den Wäldern von Terokkar zurück.', },
  },
  [10042] = {
    'Tötet den Schattenrat!',
    {'Was? Diese Kerle gehören zum Schattenrat?!|n|n$N, Ihr müsst dorthin zurückgehen und sie erledigen! Ich möchte, dass Ihr ihre Anführer und so viele Henker und Beschwörer tötet, wie Ihr nur könnt.|n|nWenn Ihr damit fertig seid, meldet Euch bei Leutnant Kieshammer in Allerias Feste.|n|nViel Glück, $C.', },
    {'Tötet 10 schattenhafte Henker, 10 schattenhafte Beschwörer und Schattenmeister Gram und kehrt dann zu Leutnant Kieshammer in Allerias Feste in den Wäldern von Terokkar zurück.', },
  },
  [10043] = {
    'Tötet den Schattenrat!',
    {'Was? Diese Kerle gehören zum Schattenrat?!|n|n$N, Ihr müsst dorthin zurückgehen und sie erledigen! Ich möchte, dass Ihr ihre Anführer und so viele Henker und Beschwörer tötet, wie Ihr nur könnt.|n|nWenn Ihr damit fertig seid, meldet Euch bei Beraterin Faila in der Steinbrecherfeste.|n|nViel Glück, $C!', },
    {'Tötet 10 schattenhafte Henker, 10 schattenhafte Beschwörer und Schattenmeister Gram und kehrt dann zu Beraterin Faila in der Steinbrecherfeste in den Wäldern von Terokkar zurück.', },
  },
  [10044] = {
    'Ein Besuch bei der Großmutter',
    {'Sprecht mit Großmutter Geyah und hört Euch an, was sie zu sagen hat.', },
    {'Sprecht mit Großmutter Geyah und hört Euch an, was sie zu sagen hat.', },
  },
  [10045] = {
    'Zutaten sammeln',
    {'Großmutter Geyah in Garadar in Nagrand möchte, dass Ihr 1 Olembawurzel, 1 Marschenbeere, 1 Telaarifarn und 1 Drachenwirbel sammelt.', },
    {'Großmutter Geyah in Garadar in Nagrand möchte, dass Ihr 1 Olembawurzel, 1 Marschenbeere, 1 Telaarifarn und 1 Drachenwirbel sammelt.', },
  },
  [10046] = {
    'Durch das Dunkle Portal',
    {'Vor zwei Wochen haben unsere Späher beobachtet, wie eine schwer bewaffnete Streitmacht der Allianz unter dem Kommando von Feldkommandant Romus aus der Burg Nethergarde aufgebrochen ist. Mit so vielen Soldaten, Vorräten und einem so erfahrenen Kommandanten können sie nur ein Ziel haben: die Scherbenwelt.|n|nDer Kriegshäuptling hat eine Vorhut durch das Portal geschickt, aber wenn die Allianz glaubt, dass so viele Truppen von Nöten sind, sollten vielleicht auch wir Verstärkung schicken.|n|nReist durch das Dunkle Portal und meldet Euch bei Nazgrel in Thrallmar.', },
    {'Reist durch das Dunkle Portal und sprecht mit Nazgrel in Thrallmar.', },
  },
  [10047] = {
    'Der Pfad des Ruhms',
    {'Sie haben sie den Pfad des Ruhms genannt, eine Straße, die vom Herzen ihrer grausamen Festung zum Dunklen Portal führt, befestigt mit den Knochen meines Volks.|n|nEs war ihnen nicht genug, uns wie Tiere zu jagen, unsere Städte zu zerstören und die Überlebenden zu quälen. Nein, sie mussten auch noch unsere Knochen als Pflastersteine verwenden, und meinen Brüdern und Schwestern ein anständiges Begräbnis unter dem Licht verweigern.|n|nDiese gequälten Seelen wandeln immer noch durch diese Lande und schreien nach Erlösung. Ich bitte Euch, $N, helft mir, sie beizusetzen.', },
    {'Reinigt 8 zertrampelte Skelette auf dem Pfad des Ruhms mit dem heiligen Wasser der Draenei und kehrt dann zu Seher Kryv in der Ehrenfeste zurück.', },
  },
  [10048] = {
    'Eine Handvoll Magiestaub',
    {'Ich brauche Staub, aber nicht irgendeinen Staub.|n|nDie königlichen Teromotten, die in den Wäldern in der Nähe leben, tragen magischen Staub auf ihren Flügeln, mit dem sie ihre Jäger betäuben. Diese Eigenschaft könnte ich mir zunutze machen. Die Arakkoaaugen, die Ihr mir gebracht habt, sind sehr widerspenstig. Mithilfe des Staubs werde ich diesen Widerstand lähmen. So kann ich dann endlich Deirom finden.|n|nIch brauche nicht viel davon, vielleicht ein halbes Dutzend oder so.', },
    {'Sammelt 7 Handvoll besänftigender Staub für Andarl in Allerias Feste.', },
  },
  [10049] = {
    'Eine Handvoll Magiestaub',
    {'Ich brauche Staub, aber nicht irgendeinen Staub.|n|nDie königlichen Teromotten, die in den Wäldern in der Nähe leben, tragen magischen Staub auf ihren Flügeln, mit dem sie ihre Jäger betäuben. Diese Eigenschaft könnte ich mir zunutze machen. Die Arakkoaaugen, die Ihr mir gebracht habt, sind sehr widerspenstig. Mithilfe des Staubs werde ich diesen Widerstand lähmen. So kann ich dann endlich Dugar finden.|n|nIch brauche nicht viel davon, vielleicht ein halbes Dutzend oder so.', },
    {'Sammelt 7 Handvoll besänftigenden Staubs für Kurgatok in der Steinbrecherfeste.', },
  },
  [10050] = {
    'Unerschütterliche Seelen',
    {'Am Ende unserer Invasion wurde das Rüstlager im Süden von den heimtückischen Todesrittern der Horde angegriffen. Diese bösartigen Schemen haben die Verteidiger des Rüstlagers verflucht und ihre Seelen zwischen dem Reich der Lebenden und dem der Toten gefangen.|n|nDiese ehrwürdigen Seelen müssen befreit werden! Ich bitte Euch, $N, beendet das Leid meiner Kameraden, denn ich bringe es nicht selbst übers Herz, sie zu töten.', },
    {'Ehrenwache Wesilow möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 10 unerschütterliche Zauberer und 5 unerschütterliche Ritter beim Expeditionsrüstlager tötet.', },
  },
  [10051] = {
    'Ausbruch aus dem Posten der Feuerschwingen!',
    {'Was für ein Glück, dass Ihr hier seid!|n|n$C, Ihr müsst mir helfen zu entkommen. Ich habe Informationen, die für die Sicherheit von Allerias Feste und vielleicht der ganzen Scherbenwelt von äußerster Wichtigkeit sind!|n|nIch bin von der Expedition des Cenarius mit einem diplomatischen Auftrag hierher geschickt worden, aber wie Ihr sehen könnt, waren sie mir nicht sehr freundlich gesonnen. Wenn Ihr mir helft in Sicherheit zu gelangen, verspreche ich Euch, dass Ihr ausreichend belohnt werdet!', },
    {'Geleitet Isla Sternenmähne in Sicherheit und meldet Euch dann bei Hauptmann Auric Sonnenjäger in Allerias Feste in den Wäldern von Terokkar.', },
  },
  [10052] = {
    'Ausbruch aus dem Posten der Feuerschwingen!',
    {'Was für ein Glück, dass Ihr hier seid!|n|n$C, Ihr müsst mir helfen zu entkommen. Ich habe Informationen, die für die Sicherheit der Steinbrecherfeste und vielleicht der ganzen Scherbenwelt von äußerster Wichtigkeit sind!|n|nIch bin von der Expedition des Cenarius mit einem diplomatischen Auftrag hierher geschickt worden, aber wie Ihr sehen könnt, waren sie mir nicht sehr freundlich gesonnen. Wenn Ihr mir helft in Sicherheit zu gelangen, verspreche ich Euch, dass Ihr ausreichend belohnt werdet!', },
    {'Geleitet Isla Sternenmähne in Sicherheit und meldet Euch dann bei Beraterin Faila in der Steinbrecherfeste in den Wäldern von Terkkokar.', },
  },
  [10053] = {
    'Zeth\'Gor bewältigen',
    {'Es ist unerlässlich, dass wir den Vorteil, den wir durch Euren Sieg über Nekrogg errungen haben, ausnutzen. Wenn wir Glück haben, hat die Führung in Zeth\'Gor noch nichts von Nekrogg erfahren.|n|nDie Knochenmalmer in Zeth\'Gor werden normalerweise von Grillok "Finsterauge" in die Schlacht geführt. Findet ihn in seinem Lager, einer Höhle im Felsen unter dem Außenposten, und tötet ihn. Durchsucht die Höhle nach den Schlachtplänen der Höllenorcs, wenn er tot ist. Wir dürfen nicht überrascht werden.', },
    {'Tötet Grillok "Finsterauge" und durchsucht seinen Unterschlupf nach den Angriffsplänen des Blutenden Auges.', },
  },
  [10054] = {
    'Drohende Verdammnis',
    {'Eine schnelle Überprüfung der Pläne zeigt, dass der Anführer von Zeth\'Gor, Kriegsherr Morkh, das Genie hinter den Angriffen, die von Knochenmagier Warlor geleitet werden, ist. Auf der Karte sind mehr als nur Morkhs Streitkräfte zu sehen.|n|nDie Pläne deuten an, dass die Streitkräfte der Knochenmalmer bewaffnet und zusammen mit den Kräften der Höllenfeuerzitadelle bereit für einen Angriff auf die Ehrenfeste sind.|n|nEs bleibt keine Zeit, um Leutnant Amadi zu informieren. Ihr müsst die Knochenmalmer aufhalten, bevor sie ihren Angriff starten können!', },
    {'Tötet 15 Grunzer des Blutenden Auges, 10 Nekrolyten des Blutenden Auges, 5 Peons des Blutenden Auges und Kriegsherr Morkh. Meldet Euch danach bei Leutnant Amadi im westlichen Turm der Ehrenfeste.', },
  },
  [10055] = {
    'Nichts verkommen lassen!',
    {'Verstärkung ist gut, aber ich sehe nicht, dass sie irgendwelche Karren mit Barren oder Holz durch die Gegend ziehen.|n|nSchaut Euch um, Freund. Die Bäume sind knapp und die Minen voller Legionsabschaum.|n|nMir gehen die Vorräte aus. Ich versuche schon, sie, wo ich kann, zu ersetzen. Aber so langsam müssen wir anfangen, alles, was wir bekommen können, wiederzuverwenden.|n|nAm südlichen Ende des Pfads des Ruhms steht ein Haufen alter Belagerungsmaschinen \'rum. Ein paar der Teile kann man immer noch verwenden. Habt Ihr Lust, mir bei einer kleinen Wiederverwertungsaktion zu helfen?', },
    {'Bringt 8 Stück gebrauchtes Metall und 8 Stück gebrauchtes Holz zu Dumphry in der Ehrenfeste.', },
  },
  [10056] = {
    'Vorräte des Blutenden Auges',
    {'Die orcischen Ruinen von Zeth\'Gor im Südosten dienen als Basislager für die immer weiter steigende Flut von Höllenorcs, die aus der Höllenfeuerzitadelle strömt.|n|nDie Söhne Lothars haben sie eine Zeitlang bekämpft, und ich würde ihre Geschichten nicht glauben, wenn ich diese Höllenorcs nicht mit eigenem Auge gesehen hätte.|n|nEtwas hat sie verändert, sie größer gemacht. Ich habe so etwas noch nie gesehen. Wir müssen alles in unserer Macht Stehende tun, um zu verhindern, dass sie noch stärker werden. Geht nach Zeth\'Gor und zerstört sämtliche Vorräte, die Ihr dort finden könnt.', },
    {'Zerstört 6 Stapel Vorräte des Blutenden Auges und meldet Euch dann bei Leutnant Amadi in der Ehrenfeste zurück.', },
  },
  [10057] = {
    'Suche nach den Anführern',
    {'Trotz Eurer Bemühungen haben wir immer noch Probleme bei der Expeditionsrüstkammer. Niemand weiß mit Sicherheit, was dort vor sich geht, was genau die Geister der gefallenen Soldaten an die Ruinen bindet.|n|nVielleicht gehen wir die Sache falsch an. In meiner Vision habe ich gesehen, dass jeder Geist eine Verbindung zu den Ruinen hat, aber was ist, wenn eine Verbindung zu ihren Anführern besteht?|n|nErzmagier Xintor und Feldkommandant Thalvos standen ihren Männern besonders nahe. Vielleicht bringt die Vernichtung ihrer Geister die anderen zur Ruhe.', },
    {'Besiegt die Geister von Erzmagier Xintor und Feldkommandant Thalvos und kehrt dann zu Ehrenwache Wesilow im Turm nordwestlich der Ehrenfeste zurück.', },
  },
  [10058] = {
    'Ein altes Geschenk',
    {'<Der Blick des Priesters wandert langsam von seiner Tasse zu Euch.>|n|nHabt Ihr nichts Besseres zu tun, als einen Mann von seiner Tasse fernzuhalten?|n|nAch, was soll\'s. Ich bin der Meinung, dass Neuankömmlinge ein gutes Zeichen sind. Was würde Turalyon davon halten?|n|nIch erinnere mich noch an den Tag unserer Abreise, als ich ihm die Geheimnisse des Lichts gab. Während des Feldzugs und den folgenden Jahren hat er nicht einen einzigen Tag vergessen, seinen Mannen einen Abschnitt daraus vorzulesen.|n|nAls er uns wieder verließ, gab er mir das Buch zurück, damit ich bis zu seiner Rückkehr darauf aufpasse, aber ich Dummkopf dachte, es sei in meinem Quartier in der Waffenkammer sicher...', },
    {'Besorgt die Geheimnisse des Lichts und bringt das Buch zu Vater Malgor Devidicus in der Ehrenfeste zurück.', },
  },
  [10059] = {
    'Zeth\'Gor bewältigen',
    {'Es ist unerlässlich, dass wir den Vorteil, den wir durch Euren Sieg über Nekrogg errungen haben, ausnutzen, $N. Wenn wir Glück haben, hat die Führung in Zeth\'Gor noch nichts von Nekrogg erfahren.|n|nDie Knochenmalmer in Zeth\'Gor werden normalerweise von Grillok "Finsterauge" in die Schlacht geführt. Findet ihn in seinem Lager, einer Höhle im Felsen unter dem Außenposten, und tötet ihn. Durchsucht die Höhle nach den Schlachtplänen der Höllenorcs, wenn er tot ist. Thrallmar darf nicht überrascht werden.', },
    {'Tötet Grillok "Finsterauge" und durchsucht seinen Unterschlupf nach den Angriffsplänen des Blutenden Auges.', },
  },
  [10060] = {
    'Drohende Verdammnis',
    {'Eine schnelle Überprüfung der Pläne zeigt, dass der Anführer von Zeth\'Gor, Kriegsherr Morkh, das Genie hinter den Angriffen, die von Knochenmagier Warlor geleitet werden, ist. Auf der Karte sind mehr als nur Morkhs Streitkräfte zu sehen.|n|nDie Pläne deuten an, dass die Streitkräfte der Knochenmalmer bewaffnet und zusammen mit den Kräften der Höllenfeuerzitadelle bereit für einen Angriff auf Thrallmar sind. Ihr müsst die Knochenmalmer aufhalten, bevor sie ihren Angriff starten können!', },
    {'Tötet 15 Grunzer des Blutenden Auges, 10 Nekrolyten des Blutenden Auges, 5 Peons des Blutenden Auges und Kriegsherr Morkh. Meldet Euch danach bei Steingardist Ambelan im Rückenbrechergrat.', },
  },
  [10061] = {
    'Die Unerschütterlichen',
    {'Als die Höllenorcs der Knochenmalmer die Expeditionswaffenkammer angegriffen haben, fiel unsere Garnison sehr schnell. Es war eine kurze, blutige und grausame Schlacht. Es gab keine Überlebenden.|n|nObwohl wir die Toten begraben und uns an den Höllenorcs gerächt haben, spuken die Geister der Gefallenen immer noch in den Ruinen. Seit Kurzem habe ich Visionen, in denen diese Geister zu einer Gefahr für Thrallmar werden.|n|nEs gibt nur einen Weg, um die Geister zur Ruhe zu bringen - Ihr müsst sie im Kampf besiegen.', },
    {'Grelag möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 10 unerschütterliche Zauberer und 5 unerschütterliche Ritter bei der Expeditionsrüstkammer südlich der Ehrenfeste tötet.', },
  },
  [10062] = {
    'Suche nach den Anführern',
    {'Trotz Eurer Bemühungen haben wir immer noch Probleme bei der Expeditionsrüstkammer. Niemand weiß mit Sicherheit, was dort vor sich geht, was genau die Geister der gefallenen Soldaten an die Ruinen bindet.|n|nVielleicht gehen wir die Sache falsch an. In meiner Vision habe ich gesehen, dass jeder Geist eine Verbindung zu den Ruinen hat, aber was ist, wenn eine Verbindung zu ihren Anführern besteht?|n|nErzmagier Xintor und Feldkommandant Thalvos standen ihren Männern besonders nahe. Vielleicht bringt die Vernichtung ihrer Geister die anderen zur Ruhe.', },
    {'Besiegt die Geister von Erzmagier Xintor und Feldkommandant Thalvos und kehrt dann zu Grelag im Rückenbrechergrat zurück.', },
  },
  [10063] = {
    'Forscherliga, für Gnome geeignet?',
    {'Kindermädchen! Glaubt Ihr das?|n|nSie haben mich von einer viel versprechenden Grabung abgezogen und mit Odesyus\' Expedition losgeschickt, um das Kindermädchen für diesen kleinen Gnom zu spielen!|n|nIch habe noch nie von einem Gnom gehört, der Ausgrabungsleiter werden wollte, Ihr etwa?|n|nAnscheinend nehmen wir jetzt auch Gnome und dieser ist wohl besonders von Murlocs fasziniert!|n|nNun gut, er ist losgezogen und hat sich in einem alten Schildkrötenpanzer an der nördlichen Küste der Insel eingerichtet. Geht und seht selbst, wenn Ihr mir nicht glaubt!', },
    {'Zieht los und sucht nach Klopper Knacksklug, der sich in einem alten Schildkrötenpanzer an der Küste nördlich der Blutwacht eingerichtet hat.', },
  },
  [10064] = {
    'Sprecht zu der Hand',
    {'Die Hand von Argus hat bei Verteidigers Ruh\' einen Vorposten eingerichtet, allerdings sind sie dort den Blutelfen und auch der Wildnis zahlenmäßig weit unterlegen. Ihrem Posten droht ohne Verstärkung bald der Fall und somit würden wir die Ereignisse bei der Vektorspule nicht länger im Auge behalten können.|n|nErstattet Späherin Jorli bei Verteidigers Ruh\' im Nordwesten Bericht und bietet ihr Eure Hilfe an, $N.', },
    {'Erstattet Späherin Jorli bei Verteidigers Ruh\' Bericht.', },
  },
  [10065] = {
    'Eine Schneise schlagen',
    {'Während unserer Mission, die Sonnenfalken und ihr Portal auszukundschaften, wurde ich ernsthaft verletzt. Späherin Loryi konnte glücklicherweise die Blutung stillen und sucht gerade nach einem Weg, um mich zur Blutwacht zu bringen.|n|nUnser Problem liegt allerdings darin, dass wir unsere Stellung hier verlassen müssen, um eine sichere Rückkehr garantieren zu können.|n|nSobald wir diesen sicheren Grund verlassen, werden uns Felshetzer anfallen. Wenn Ihr ein paar der wütenden Felshetzer aus dem Weg räumen könntet, würden wir höchstwahrscheinlich sicher an unser Ziel gelangen.', },
    {'Tötet 10 wütende Felshetzer und kehrt zu Späherin Jorli bei Verteidigers Ruh\' zurück.', },
  },
  [10066] = {
    'Alles im Griff',
    {'Wir wagen es nicht, unseren Posten zu verlassen oder uns zu weit von Verteidigers Ruh\' zu entfernen, $R. Die mutierten Kreaturen, die sich in der unmittelbaren Nähe der Vektorspule aufhielten, wurden schwerwiegend von der Energie beeinflusst, die den Kristallen entweicht.|n|nDie mutierten Greifer scheinen bis zu einem gewissen Grad Empfindungen entwickelt zu haben. Sie haben gelernt, tückische Fallen zu erschaffen, aufzustellen und zu verbergen, damit sich selbst die umsichtigsten Kämpfer darin verfangen.|n|nWir werden niemals gegen die Sonnenfalken vorgehen können, wenn wir ständig auf unsere Schritte Acht geben müssen. Packt das Problem bei der Wurzel, $N.', },
    {'Tötet 8 mutierte Greifer und meldet Euch bei Verteidigerin Corin bei Verteidigers Ruh\'.', },
  },
  [10067] = {
    'Besudelte Wassergeister',
    {'Die meisten der Kreaturen, die von der Energie der Kristalle berührt wurden, wurden auf die gleiche Art verdorben: seltsame Male auf ihrer Haut, aggressiveres Verhalten und kleine Kristallsplitter in ihren Körpern. Wie dem auch sei, die besudelten Wassergeister der Blutmythosinsel scheinen sich vollständig in Kristall zu verwandeln.|n|nIch habe bis jetzt noch nichts gesehen, was derart auf die Kristalle reagiert hat. Als wir den Besudelten Teich untersucht haben, haben sie sich als besonders gefährlich herausgestellt. Wir müssen sie loswerden, bevor die Sonnenfalken sie als neue Energiequelle missbrauchen können.', },
    {'Tötet 6 besudelte Wassergeister und kehrt zu Verteidigerin Corin bei Verteidigers Ruh\' zurück.', },
  },
  [10068] = {
    'Arkane Geschosse',
    nil,
    nil,
  },
  [10069] = {
    'Die Wege des Lichts',
    nil,
    nil,
  },
  [10070] = {
    'Zuverlässiger Schuss',
    nil,
    nil,
  },
  [10072] = {
    'Das richtige Wort',
    nil,
    nil,
  },
  [10073] = {
    'Feuerbrand',
    nil,
    nil,
  },
  [10074] = {
    'Kristallpulver von Oshu\'gun',
    {'Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.|n|nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des "diamantenen" Bergs, Oshu\'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu\'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.', },
    nil,
  },
  [10075] = {
    'Kristallpulver von Oshu\'gun',
    nil,
    nil,
  },
  [10076] = {
    'Kristallpulver von Oshu\'gun',
    {'Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.|n|nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des "diamantenen" Bergs, Oshu\'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu\'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.', },
    nil,
  },
  [10077] = {
    'Kristallpulver von Oshu\'gun',
    nil,
    nil,
  },
  [10078] = {
    'Die Unerwünschten zerstören',
    {'Jetzt, da unsere Bergungsaktion ins Rollen gekommen ist, ist es an der Zeit, die zweite Phase unseres Plans einzuläuten.|n|nAm Pfad des Ruhms hat die Horde immer noch ihre alten Klingenwerfer postiert. Lasst Euch von Ihrem Alter nicht täuschen, $N, sie sind immer noch sehr gefährlich. So sehr wir auch versuchen, alles zurückzuerobern, was wir können, können wir nicht erwarten, dass die Horde ihre Waffen einfach so abbaut.|n|nNehmt diese Fackel und zündet ihre übriggebliebene Belagerungsausrüstung an. Ich werde die Sicherheit der Ehrenfeste nicht dem Zufall überlassen.', },
    {'Zündet die Klingenwerfer der Horde mit der flammenden Fackel am Pfad des Ruhms an. Kehrt dann mit der flammenden Fackel zu Dumphry in der Ehrenfeste zurück.', },
  },
  [10079] = {
    'Bringt diese Mine zum Beben!',
    {'Die Mine wurde von diesem Gan\'argpack überrannt!|n|nSie haben nicht nur meine Arbeiter aus den Tunneln getrieben, sondern hämmern auch noch Tag und Nacht darin herum! Und jetzt sitzt mir auch noch Danath im Rücken! Sagt, er würde mir meine Bierration streichen, wenn ich mich nicht bald darum kümmere!|n|nKeiner der Minenarbeiter will dort hineingehen, und die Wächter sind zu sehr damit beschäftigt, sich vollaufen zu lassen.|n|nIch flehe Euch an, $N, helft mir! Danath mag mir meinen Stolz nehmen, aber niemals mein Bier!', },
    {'Tötet 12 Pioniere der Gan\'arg und kehrt dann zu Großknecht Biggums zurück.', },
  },
  [10080] = {
    'Konstruktionslager der Legion',
    {'Ich habe mit Humphry gesprochen. Er hat Euch sicher gesagt, dass die Heimsuchung der Mine ein kleineres Übel ist, aber ich bin der Meinung, dass es sogar ein sehr großes Übel ist.|n|nNordöstlich des Hordenpostens Thrallmar arbeiten die Diener der Legion Tag und Nacht an etwas, aber was?|n|nKeiner der Späher, die ich dorthin geschickt habe, ist je zurückgekommen. Die Zeit der Zurückhaltung ist vorbei, $N. Begebt Euch in das Konstruktionslager: Zorn und findet heraus, was die Legion vorhat.', },
    {'Tötet 10 Diener der Gan\'arg, 5 Legionäre des Konstruktionslagers und 5 Schwestern des Leids. Durchsucht danach des Konstruktionslager: Zorn nach einem Hinweis auf die Absichten der Legion.', },
  },
  [10081] = {
    'Mutter Kashur treffen',
    {'Erschreckt Euch nicht über das, was Ihr sehen werdet, wenn die Wirkung eintritt. Diese Geister sind überall um uns herum - immer. Der Trank erlaubt Euch nur, sie zu verstehen und zu sehen. Ihr werdet seine Wirkung brauchen, wenn Ihr mit Mutter Kashur sprecht.|n|nIhr findet sie ein gutes Stück im Südwesten beim Ahnengrund.', },
    {'Großmutter Geyah möchte, dass Ihr mit Mutter Kashur sprecht.', },
  },
  [10082] = {
    'Die aufgebrachten Ahnen',
    {'Seht Ihr, wie sie unter uns wandeln? Der Ahnengrund ist normalerweise sehr ruhig und friedlich.|n|nIn letzter Zeit haben sich die Geister der Ahnen jedoch erhoben und sind sehr aufgebracht. Etwas muss sie sehr stören. Wir müssen herausfinden, was das sein könnte, aber zuerst müssen wir die direkte Bedrohung beseitigen.|n|nDie Geister, die Ihr hier seht, sind nicht wirklich unsere Ahnen, sondern ein Abbild ihrer gegenwärtigen Lage. Ihr müsst die aufgebrachten Orcgeister zerstören. Tut dies und kehrt dann zu mir zurück.', },
    nil,
  },
  [10083] = {
    'Die Pläne der Legion',
    {'Ihr schreibt die leuchtenden Glyphen, die in den Boden geritzt wurden, ab, aber ohne die zweite Hälfte ergibt das Diagramm keinen Sinn.|n|nFeldmarschall Rohamus sprach von einem weiteren Konstruktionslager im Westen, dem Konstruktionslager: Bosheit. Vielleicht bewahrt die Legion dort die zweite Hälfte der Pläne auf?|n|nWenn die Legion etwas in Massenproduktion herstellt, macht es Sinn, dass die Teile in verschiedenen Lagern zusammengebaut werden.', },
    {'Besorgt die Pläne des Konstruktionslagers: Bosheit und bringt sie zu Feldmarschall Rohamus im Expeditionsposten.', },
  },
  [10084] = {
    'Angriff auf Mageddon',
    {'Mit den Fähigkeiten der Ingenieure der Mo\'arg und der endlosen Menge an Gan\'argdienern werden sie sicher schneller Teufelshäscher produzieren, als wir in Nethergarde Bescheid geben können.|n|nWir haben keine andere Wahl als sie so schnell wie möglich anzugreifen. Wir können keine Männer von der Ehrenfeste für diesen Angriff abziehen, das wäre purer Selbstmord! Die Höllenorcs und die Horde würden uns bei dem kleinsten Anzeichen von Schwäche überrennen.|n|nDie Ehrenfeste steht nun seit 20 Jahren, und wir haben nicht vor, sie jetzt zu verlieren.', },
    {'Tötet Nachtlord Malphas im Konstruktionslager: Mageddon und meldet Euch dann bei Truppenkommandant Danath Trollbann in der Ehrenfeste.', },
  },
  [10085] = {
    'Ein Besuch bei den Ahnen',
    {'Ich brauche Euch, um zu den Dörfern unserer Ahnen zu reisen, $N. Geht zu jedem einzelnen und schaut, ob unsere Vorfahren noch da sind.|n|nGeht zum Sonnenwindposten im Norden, zu den Ruinen des Lachenden Schädels ganz im Norden bei den Bergen, besucht Garadar im Nordosten und zuletzt die Ruinen des Blutenden Auges an der Grenze zwischen Nagrand und den Wäldern von Terokkar im Osten.|n|nBerichtet mir, sobald Ihr die Ahnen in ihrem Zuhause beobachtet habt.', },
    {'Mutter Kashur im Ahnengrund in Nagrand möchte, dass Ihr den Sonnenwindposten, die Ruinen des Lachenden Schädels, Garadar und die Ruinen des Blutenden Auges besucht.', },
  },
  [10086] = {
    'Ich arbeite... für die Horde!',
    {'Könnt Ihr das fassen? Diese Orcs haben mich angeheuert, um ihre beschädigten Befestigungsanlagen abzustützen und Sprengstoff herzustellen. Ist das nicht ein Traumjob? Nur zu schade, dass uns die Materialien ausgehen, aber ein gewitzter Goblin wie ich weiß sich immer zu helfen!|n|nKönntet Ihr mich dabei unterstützen? Ich benötige ein wenig gebrauchtes Holz und Metall von den zerstörten Belagerungsmaschinen entlang des Pfads des Ruhmes. Geht dorthin und sammelt, aber gebt auf diese rothäutigen Orcs Acht!|n|nWenn Ihr fertig seid, kommt zurück und holt Euch eine fette Belohnung ab!', },
    {'Bringt 8 Stück gebrauchtes Metall und 8 Stück gebrauchtes Holz zu Megzeg Knaxknöchel in Thrallmar.', },
  },
  [10087] = {
    'Zündet es an... für die Horde!',
    {'Ich bin ein glücklicher, glücklicher Goblin! Ich darf hier Sprengstoff und Killermaschinen herstellen in der Gewissheit, dass sie sofort bei wichtigen Missionen eingesetzt werden!|n|nWo wir gerade von Missionen sprechen, ich habe einen Befehl aus Thrallmar erhalten: Verbrennt die Kanonen der Allianz entlang des Pfads des Ruhms... die Kanonen, die gefährlich auf die Befestigungsanlagen der Horde gerichtet sind. Nehmt diese Fackel und begebt Euch zu jeder Kanone. Zündet die Fackel an und bestaunt den Funkenflug!', },
    {'Zündet die östliche und die westliche Kanone der Allianz mit der flammenden Fackel an und kehrt danach zu Megzeg Knaxknöchel in Thrallmar zurück.', },
  },
  [10088] = {
    'Bringt diese Mine zum Beben!',
    {'Die Mine wurde von diesem Gan\'argpack überrannt, und zu allem Übel sind die Peons der Meinung, dass jetzt die richtige Zeit für ein Schläfchen ist! Ich weiß nicht, wie sie bei all dem Lärm aus der Mine schlafen können, aber das ist mein geringstes Problem.|n|nWenn wir dieses Gan\'arggesindel nicht bald loswerden, wird Thrallmars Nachschub an Erzen und anderen Materialien abgeschnitten. Ich habe schon Wachkommandant Krunk um Hilfe gebeten, aber er sagt, dass er keine Männer schicken kann, solange die Stadt angegriffen wird. Könnt Ihr mir helfen?', },
    {'Tötet 12 Pioniere der Gan\'arg und kehrt dann zu Großknecht Razelcraz zurück.', },
  },
  [10089] = {
    'Konstruktionslager der Legion',
    {'Thrallmar steht seit seiner Gründung unter Beschuss der Lager der Legion. Bis jetzt haben wir standhalten können, aber die Situation wird von Tag zu Tag schlimmer.|n|nSchattenjäger Ty\'jin hat mehrere Versuche unternommen, mehr über die Lager herauszufinden, aber keiner seiner Späher ist je zurückgekehrt.|n|nDie Zeit für Zurückhaltung ist vorbei, $N. Begebt Euch ins Konstruktionslager: Zorn und findet heraus, was die Legion vorhat.', },
    {'Tötet 10 Diener der Gan\'arg, 5 Legionäre des Konstruktionslagers und 5 Schwestern des Leids. Durchsucht danach des Konstruktionslager: Zorn nach einem Hinweis auf die Absichten der Legion.', },
  },
  [10090] = {
    'Die Pläne der Legion',
    {'Ihr schreibt die leuchtenden Glyphen, die in den Boden geritzt wurden, ab, aber ohne die zweite Hälfte ergibt das Diagramm keinen Sinn.|n|nDie Glyphen verweisen darauf, dass ein weiteres Konstruktionslager im Westen, das Konstruktionslager: Bosheit, an dem Projekt beteiligt ist. Vielleicht bewahrt die Legion dort die zweite Hälfte der Pläne auf?|n|nWenn die Legion etwas wirklich Gewaltiges herstellt, macht es Sinn, dass die Teile in verschiedenen Lagern zusammengebaut werden.', },
    {'Besorgt die Pläne des Konstruktionslagers: Bosheit und bringt sie zu Oberanführer Hun Stümmelfaust im Häschersturz.', },
  },
  [10091] = {
    'Seeleninstrumente',
    {'Pah! Sie haben mich gefoltert und versucht, etwas über die Verteidigungsanlagen von Shattrath aus mir herauszuquetschen.|n|nIch habe mich geweigert - da haben sie die anderen Spione an Höllenschlund verfüttert, und ich sollte der Nächste sein. Aber ich habe ihnen nichts verraten!|n|nSie sind wahnsinnig! Sie sind versessen darauf, dämonische Mächte zu beschwören, die sie auf gar keinen Fall kontrollieren können!|n|nSie benutzen besondere Seeleninstrumente, um ihre Seelensplitter herzustellen und ihre Beschwörungen noch mächtiger zu machen. Ihr müsst ihnen diese Instrumente stehlen!|n|nIch würde Euch ja begleiten, aber ich muss nach Shattrath zurück um der Spionagemeisterin des Unteren Viertels zu berichten.', },
    {'Stehlt 5 Seeleninstrumente und bringt sie zu Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath.', },
  },
  [10092] = {
    'Angriff auf Mageddon',
    {'Mit den Fähigkeiten der Ingenieure der Mo\'arg und der endlosen Menge an Gan\'argdienern werden sie sicher schneller Teufelshäscher produzieren, als wir in Orgrimmar Bescheid geben können.|n|nWir haben keine andere Wahl als sie so schnell wie möglich anzugreifen. Wir können keine Männer von Thrallmar für diesen Angriff abziehen, dann wären wir zu leicht angreifbar.|n|nEs gibt zu viele, die sich, ungeachtet der Allianz, nur zu gerne auf unseren ungeschützten Außenposten stürzen würden. Versagt nicht, $N. Es hängt zu viel von Euch ab.', },
    {'Tötet Nachtlord Malphas im Konstruktionslager: Mageddon und meldet Euch dann bei Oberanführer Hun Stümmelfaust im Häschersturz.', },
  },
  [10093] = {
    'Der Tempel von Telhamat',
    {'Zum Glück ist der Pfad des Ruhms nicht das einzige Zeichen meines Volks in diesen Ländereien. Im Westen befinden sich immer noch ein paar unserer geheiligten Stätten, auch wenn einige von ihnen überrannt wurden.|n|nWährend Velen sich auf seine Reise nach Azeroth vorbereitete, haben diejenigen von uns, die hier bleiben sollten, versucht, sich wieder in unseren heiligen Orten niederzulassen.|n|nIm westlichen Teil der Höllenfeuerhalbinsel könnt Ihr beim Tempel von Telhamat eine kleine Gruppe von Draenei finden, die von Amaan dem Weisen angeführt werden. Ich bin mir sicher, dass er Euch gerne kennenlernen würde.', },
    {'Sprecht mit Amaan dem Weisen beim Tempel von Telhamat im Westen der Höllenfeuerhalbinsel.', },
  },
  [10094] = {
    'Kodex des Blutes',
    {'Es ist nun zwei Jahre her, dass die Beschwörung des Schattenrats dieses einst großartige Mausoleum explodieren und die Knochenwüste entstehen lies.|n|nJetzt befinden sie sich im Krieg mit einer unglaublich mächtigen Kraft im Inneren.|n|n$N, Ihr müsst in das Schattenlabyrinth eindringen und herausfinden, wogegen sie kämpfen und ob es eine Gefahr für uns sein könnte. Unserer Spione haben berichtet, dass sie ein verbotenes Buch mit unheiligen Beschwörungen verwenden, bekannt als der Kodex des Blutes.|n|nSucht in ihm nach Antworten.', },
    {'Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun.', },
  },
  [10095] = {
    'In das Herz des Labyrinths',
    {'Der Schattenrat hat die Kontrolle über das kosmische Wesen, das sie vor fast zwei Jahren beschworen haben, verloren! Es hat die Explosion von Auchindoun verursacht und die Knochenwüste erschaffen.|n|nJetzt nur noch als Murmur bekannt, droht es, den Schattenrat zu überrennen und zu entkommen!|n|nNun, da der Großmeister und der Rest der Führung tot sind, seid Ihr die einzige Hoffnung der Scherbenwelt im Kampf gegen dieses Monster!|n|n$N, tief in Eurem Herzen wisst Ihr, dass Ihr und Eure Freunde nicht versagen dürfen!', },
    {'Vernichtet Murmur und informiert danach Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath über die Geschehnisse im Schattenlabyrinth.', },
  },
  [10096] = {
    'Rettung der Sporloks',
    {'Ikeyen hat mir erzählt, was ihm in diesen Höhlen widerfahren ist, und ich finde es einfach nur schrecklich!|n|nWisst Ihr, vielleicht sollten wir diesen armen Sporloks helfen. Ikeyen sagt, dass sie dort in der Funggorhöhle leben, aber die Marschenbestien sind kürzlich dort eingefallen.|n|nWarum geht Ihr nicht dort hin und schaut, dass Ihr ein paar von diesen Marschenbestien erlegt? Die Höhle ist ganz nah im Südwesten.', },
    {'Tötet 10 Marschengräber und 10 Marschenlauerer und kehrt dann zu Lauranna Thar\'well in der Zuflucht des Cenarius in den Zangarmarschen zurück.', },
  },
  [10097] = {
    'Bruder gegen Bruder',
    {'Die Sethekk haben Skettis mit Fanfaren verlassen, als Auchindoun explodiert ist. Das war sicher ein Vorbote für die Ankunft unseres Meisters.|n|nMein Bruder, Syth, war einer ihrer Anführer und hat uns gesagt, dass es unsere Pflicht wäre, in die Tempelruinen zu gehen und unserem Gott zu begegnen.|n|nNachdem wir unser Lager in den Ruinen aufgeschlagen und sie die Sethekkhallen getauft hatten, kamen mir Zweifel an den Fähigkeiten meines Bruders und seines Verbündeten Ikiss.|n|nNach einiger Zeit hat mich Syth aus den Hallen geworfen und mir verboten, meine Schwester Lakka mitzunehmen. Helft Ihr mir, sie zu retten?', },
    {'Tötet Dunkelwirker Syth in den Sethekkhallen und befreit Lakka. Kehrt zu Isfar außerhalb der Sethekkhallen zurück, wenn Ihr die Aufgabe abgeschlossen habt.', },
  },
  [10098] = {
    'Terokks Erbe',
    {'Mein Volk verehrt einen uralten Helden namens Terokk. Arakkoaküken erfreuen sich an den Geschichten über seine Taten und den Beschreibungen seines prächtigen Federkleids.|n|nEr lebte für hunderte von Jahren unter meinem Volk, doch eines Tages verschwand er urplötzlich, und ließ nur seine Maske, seinen Speer und seine Schriften zurück.|n|nDiese Relikte werden von den Arakkoa hoch verehrt, und es brach ihnen das Herz, als die Sethekk die Gegenstände bei ihrem Aufbruch aus Skettis verschleppten.|n|nIch habe alles, was ich über den Verbleib der Schriftrollen in den Hallen weiß, niedergeschrieben.', },
    {'Bringt Terokks Maske, Terokks Federkiel und die Sage von Terokk zu Isfar außerhalb der Sethekkhallen.', },
  },
  [10099] = {
    'Das Genie',
    {'Diese verfluchten Gan\'arg wuseln immer noch in die Mine! Für jeden, den wir umbringen, scheinen zwei oder drei weitere aufzutauchen!|n|nIrgendwas in den Tiefen der Mine muss diese Menge steuern. Ihr scheint das letzte Mal ganz gut klargekommen zu sein, und das Licht weiß, dass Ihr $Gder:die; Einzige seid, $Gder:die; mutig genug ist, wieder in die Mine zu gehen. Findet heraus, wer für dieses Ärgernis verantwortlich ist und bestraft ihn dafür!', },
    {'Sucht und tötet Z\'kral in den Minen unter der Ehrenfeste und meldet Euch dann bei Großknecht Biggums zurück.', },
  },
  [10100] = {
    'Das Genie',
    {'Versteht mich nicht falsch, $N, ich bin sehr froh, dass Ihr Euch bereit erklärt habt, uns mit den Minen zu helfen, aber für jeden Pionier, den Ihr getötet habt, sind zwei neue dazugekommen.|n|nIch habe Wachkommandant Krunk schon die Ohren vollgeheult, aber er weigert sich immer noch, mir Hilfe zu schicken. Er murmelt immer irgendwas von Höllenebern. Wenn ich mir nicht so sicher wäre, dass er mich verprügeln würde, würde ich ihm sagen, dass jetzt nicht die Zeit ist, um an Rippchen zu denken!|n|nWie auch immer, es sieht so aus, als ob irgendjemand tief in den Minen die ganze Sache steuert. Findet ihn und tötet ihn!', },
    {'Sucht und tötet Urga\'zz in den Minen unter Thrallmar und kehrt dann zu Großknecht Razelcraz zurück.', },
  },
  [10101] = {
    'Wenn Geister sprechen',
    {'Oshu\'gun, der diamantene Berg, war einst ein heiliger Ort meines Volkes. Dort versammelten sich die Klans jedes Jahr, um das Frühlingsfest zu feiern. Dort kommunizierten unsere Schamanen mit unseren altehrwürdigen Vorfahren. Er bildete das Zentrum unserer Kultur - bis die Schatten uns übernahmen. Als die Klans zu einer Horde wurden, verstummten die Geister von Oshu\'gun. Unsere Vorfahren haben sich von uns abgewendet.|n|nDoch nun werden sie in ihrer Ruhe gestört. Reist nach Oshu\'gun und findet heraus, was die Geister beunruhigt.', },
    {'Mutter Kashur im Ahnengrund in Nagrand bittet Euch, Eurer Vision auf den Grund zu gehen. Findet K\'ure in Oshu\'gun.', },
  },
  [10102] = {
    'Ein gelüftetes Geheimnis',
    {'Sprecht mit A\'dal in Shattrath.', },
    {'Sprecht mit A\'dal in Shattrath.', },
  },
  [10103] = {
    'Bericht an Zurai',
    {'Mit der Ankunft von Feldkommandeur Romus und seinen Streitmächten sind die Allianz und ihre Draeneifreunde mutiger geworden. Sie wandeln alle alten Draeneiruinen von hier bis Shattrath in Heerlager um.|n|nAls Antwort darauf haben die Trolle einen neuen Außenposten im östlichen Teil der Zangarmarschen errichtet, südlich des Todesmoors. Sie nennen ihn Sumpfrattenposten. Ich bin froh, dass sie sich in einer solchen Umgebung ihren Humor bewahrt haben. Ich wollte jedenfalls nicht mit ihnen tauschen.|n|nDer Kommandeur des Posten hat mich gebeten, ihm alle Mann zu schicken, die ich entbehren kann.', },
    {'Meldet Euch bei Zurai im Sumpfrattenposten in den Zangarmarschen.', },
  },
  [10104] = {
    'Sorgen um Tuurem',
    {'Die Gerüchte über Tuurem sind beunruhigend. Manche sagen, die Ruinen der Stadt laufen vor verrückten Zerschlagenen und Verirrten über, während gierige Artefaktjäger Draeneirelikte stehlen.|n|nEs ist schwer zu sagen, welche wahr und welche falsch sind, aber es liegt in unserer Verantwortung, die Ruinen so gut es geht zu schützen. Sucht Andarl in der Feste in den Wäldern von Terokkar. Er ist eine Art Forscher für magische Relikte. Er weiß wahrscheinlich besser als alle anderen Bescheid, was dort vor sich geht.', },
    {'Sprecht mit Andarl in der Feste in den Wäldern von Terokkar.', },
  },
  [10105] = {
    'Nachrichten für Rakoria',
    nil,
    {'Sprecht mit Rakoria in der Steinbrecherfeste in den Wäldern von Terokkar.', },
  },
  [10106] = {
    'Höllenfeuerbefestigungen',
    {'Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.|n|nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.|n|nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, $N, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.', },
    {'Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.', },
  },
  [10107] = {
    'Diplomatische Maßnahmen',
    {'Kilrath hat Neuigkeiten über den Anführer der Felsfäuste geschickt: Es ist ein Orc! Ein uralter Orc, der in der Zeit unserer Väter das Dunkle Portal durchschritten hat und in sein Heimatland zurückgekehrt ist. Ich möchte, dass Ihr diesen Orc ausfindig macht und ihn davon überzeugt, die Felsfäuste zurückzuziehen. Er lebt auf einer der höheren Ebenen bei den Ruinen der Brennenden Klinge im Südosten, nahe der Grenze zu Terokkar. Viel Erfolg, $N!|n|nSeid auf der Hut, er ist ein Klingenmeister...', },
    {'Jorin Totauge in Garadar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht.', },
  },
  [10108] = {
    'Diplomatische Maßnahmen',
    {'Die Agenten der Jägerin haben Neuigkeiten über den Anführer der Felsfäuste geschickt: Es ist ein Orc! Ein uralter Orc, der in der Zeit unserer Väter das Dunkle Portal durchschritten hat und in sein Heimatland zurückgekehrt ist. Ich möchte, dass Ihr diesen Orc ausfindig macht und ihn davon überzeugt, die Felsfäuste zurückzuziehen. Er lebt auf einer der höheren Ebenen bei den Ruinen der Brennenden Klinge im Osten. Viel Erfolg, $N!|n|nSeid auf der Hut, er ist ein Klingenmeister...', },
    {'Mo\'mor der Brecher in Telaar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht.', },
  },
  [10109] = {
    'Ich muss sie haben!',
    {'Könnt Ihr sie sehen?? Bei Gazlows wundervollem Mundgeruch, ich muss diese Eier haben! Ihr seht aus wie jemand, den man gebrauchen kann.|n|nIch sag Euch was, $R, wenn Ihr ein paar Dinge für mich sammelt, damit ich meinen Spring-o-Mat 4000 zum Laufen bekomme, werde ich Euch einen Schlüssel geben, mit dem auch Ihr die Maschine bedienen könnt! Was man mit einem Spring-o-Mat 4000 machen kann? Wohl eher was man damit nicht machen kann...|n|nIch brauche Luftelementargas von den Luftelementaren in Nagrand. Sie sind überall, fragt mich also nicht, wo Ihr sie finden könnt!', },
    {'Wazdaz gegenüber der Klanwacht im Süden von Nagrand möchte, dass Ihr ihm 3 Einheiten Luftelementargas bringt.', },
  },
  [10110] = {
    'Höllenfeuerbefestigungen',
    {'Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.|n|nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!|n|nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.|n|nFür die Horde!', },
    {'Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.', },
  },
  [10111] = {
    'Bringt mir das Ei!',
    {'Jetzt, da Ihr initiiert wurdet, möchte ich, dass Ihr mir dieses Ei bringt! Benutzt den Spring-o-Mat und versucht, das Nest genau in der Mitte zu treffen. Aber seid vorsichtig! Schlechte Sprünge können in körperlichen Schäden oder dauerhaften schweren Wunden resultieren.', },
    {'Wazdaz in Nagrand möchte, das Ihr den Spring-o-Mat 4000 benutzt, um in das Nest in dem nahe gelegenen Baum zu springen und das geheimnisvolle Ei zu stehlen.', },
  },
  [10112] = {
    'Ein persönlicher Gefallen',
    {'Hmmm? Eine Kiste sagt Ihr? Oder waren es mehrere? Wisst Ihr aus welchem Material sie war?|n|nUnd wie heißt der Händler? Empoor? Und Ihr seid Euch sicher, dass er ein Zerschlagener ist? Ich mache nicht viele Geschäfte mit ihresgleichen.|n|nVielleicht hilft es meinem Gedächtnis ein wenig auf die Sprünge, wenn Ihr mir einen Gefallen tut.|n|nDie Arakkoa der Skith - diese primitiven Zauberer - haben neulich eine große Schiffladung meiner magischen Waren gestohlen. Ich will alles zurückhaben!|n|nIhr könnt das Skithversteck südlich von Shattrath finden.', },
    {'Holt 5 von Lathrais gestohlenen Waren zurück und bringt sie zu Windhändler Lathrai bei der Taverne Weltenend im Unteren Viertel in Shattrath.', },
  },
  [10113] = {
    'Nesingwarys Safari',
    {'"Die Flinte" Jones möchte, dass Ihr mit Hemet Nesingwary in Nesingwarys Safari am nordöstlichen Rand von Nagrand sprecht.', },
    {'"Die Flinte" Jones möchte, dass Ihr mit Hemet Nesingwary in Nesingwarys Safari am nordöstlichen Rand von Nagrand sprecht.', },
  },
  [10114] = {
    'Nesingwarys Safari',
    {'Diese Orcs haben noch nie zuvor einen Tauren gesehen, könnt Ihr das glauben? Wenn Hauptmann Kroghan nicht wäre, würden sie mich wahrscheinlich in diesem Moment zum Abendessen verschlingen!|n|nAber wo sind meine Manieren? Ich bin Ohlorn Fernreiser, herausragender Jäger! Ich gehöre zu Nesingwarys Expedition, die sich von Azeroth aus auf die Jagd nach Großwild hierher begeben hat. Wenn Ihr Euch für die Jagd interessiert, solltet Ihr meine Truppe in Nesingwarys Safari östlich von hier an den Grenzen zu den Zangarmarschen besuchen.', },
    {'Ohlorn Fernreiser möchte, dass Ihr mit Shado \'Fitz\' Fernreiser in Nesingwarys Safari in Nagrand sprecht.', },
  },
  [10115] = {
    'Dolchfennkrise',
    {'Die Kurenai und die Draenei sind nicht immer der gleichen Meinung, besonders nicht, wenn es um die Verirrten geht. Wir helfen den Verirrten, die sich an uns wenden, gerne, aber wir werden sie niemals verfolgen. Manche Draenei sind andererseits überzeugt davon, dass sie alle \'erlöst\' werden müssen.|n|nEs gibt jedoch Zeiten, in denen sogar die Verirrten zu weit gehen, wie zum Beispiel der Dolchfennstamm. In ihrem Dorf im Westen hantieren sie mit Giften herum, lügen und betrügen, was für uns sehr unnatürlich ist.|n|nWir müssen dem ein Ende bereiten, bevor der bösartige Dolchfennstamm seinen Einfluss noch weiter ausbreiten kann.', },
    {'Tötet 3 Auftragsmörder von Dolchfenn und 15 Matschwirbler von Dolchfenn.', },
  },
  [10116] = {
    'Gesucht: Häuptling Mummaki',
    {'Gesucht: Häuptling Mummaki - Anführer des verdorbenen und degenerierten Dolchfennstamms der Verirrten, wegen seiner brutalen Angriffe auf die Oreborzuflucht.|n|nDer Häuptling und seine Truppe von Auftragsmördern haben mehrere Kurenai und Draenei auf dem Gewissen. Nur erfahrene Kämpfer sollten sich an sie heranwagen.|n|nReisenden wird nahe gelegt, die Gegend um Dolchfenn westlich der Oreborzuflucht zu meiden.|n|nDas Kopfgeld kann bei Vorlage eines Beweises für das Ableben des Häuptlings bei Ikuti eingefordert werden.', },
    {'Bringt Häuptling Mummakis Totem zu Ikuti in der Oreborzuflucht.', },
  },
  [10117] = {
    'Gesucht: Häuptling Mummaki',
    {'Gesucht: Häuptling Mummaki - Anführer des verdorbenen und degenerierten Dolchfennstamm der Verirrten, wegen seiner brutalen Angriffe auf Zabra\'jin und seine Einwohner.|n|nDer Häuptling und seine Truppe von Auftragsmördern haben mehrere Späher und Boten auf dem Gewissen. Nur erfahrene Kämpfer sollten sich an sie heranwagen.|n|nReisenden wird nahe gelegt, die Gegend um Dolchfenn nordwestlich von Zabra\'jin zu meiden.|n|nDas Kopfgeld kann bei Vorlage eines Beweises für das Ableben des Häuptlings bei Schattenjäger Denjai eingefordert werden.', },
    {'Bringt Häuptling Mummakis Totem zu Schattenjäger Denjai.', },
  },
  [10118] = {
    'Nachricht für Dolchfenn',
    {'Von allen Stämmen der Verirrten in den Zangarmarschen ist der Dolchfennstamm der gerissenste und aggressivste. Er ist sehr gut organisiert und macht keinen Hehl daraus, dass er gerne die Kontrolle über alle Verirrten in den Marschen hätte.|n|nIhren Angriffen sind schon viele meiner Späher und Boten zum Opfer gefallen. Ich kann es mir nicht leisten, noch mehr Männer zu verlieren.|n|nWenn wir nicht bald handeln, werden sie die komplette Kontrolle über alle Straßen erlangen und Zabra\'jin einkesseln.', },
    {'Tötet 3 Auftragsmörder von Dolchfenn und 15 Matschwirbler von Dolchfenn und kehrt dann zu Schattenjäger Denjai in Zabra\'jin zurück.', },
  },
  [10119] = {
    'Durch das Dunkle Portal',
    {'Zwanzig Jahre lang war es ruhig um das Dunkle Portal – es wurde zu einem Symbol längst vergangener Zeiten.|n|n<Reldorn sieht sich um.>|n|nIch habe nicht geglaubt, dass ich den heutigen Tag erleben würde, aber hier stehen wir nun und schauen tief in den Abgrund.|n|nAuf der anderen Seite des Portals sind wir in einem grausamen Krieg gefangen – ein Krieg, den wir nicht ohne Hilfe gewinnen können. Ihr müsst durch das Dunkle Portal reisen und unseren Truppen helfen, $C.|n|nMeldet Euch umgehend bei Kommandant Duron. Er erwartet Euch in der Scherbenwelt...', },
    {'Reist durch das Dunkle Portal und sucht Kommandant Duron. Er wartet auf der anderen Seite auf Eure Ankunft - in der Scherbenwelt.', },
  },
  [10120] = {
    'Ankunft in der Scherbenwelt',
    {'Mit der Unterstützung der Allianz können meine Leute die Verteidigung hier aufrechterhalten, aber Ihr müsst dringend meinen Bericht zu General Krakork in Thrallmar bringen. Mit seiner Hilfe können wir diese Dämonen zurück in den Abgrund drängen, aus dem sie gekommen sind! Sprecht mit Vlagga Freyfeder auf der Anhöhe hinter uns. Sie wird Euch schnell auf den Weg dorthin bringen.', },
    {'Generalleutnant Orion beim Dunklen Portal auf der Höllenfeuerhalbinsel möchte, dass Ihr Orions Bericht zu Vlagga Freyfeder bringt.', },
  },
  [10121] = {
    'Die Brennende Legion ausrotten',
    {'Auch wenn dieses Land voller neuer, unbekannter Feinde ist, ist die Brennende Legion immer noch die größte Bedrohung für unsere Expedition. Einer meiner vertrauenswürdigsten Krieger, Unteroffizier Schädelbrecher, hat die Taktiken der Legion untersucht und versucht, das wahre Ziel der Legion in diesem Land herauszufinden. Ihr findet ihn bei der Versorgungskarawane außerhalb des südlichen Walls.|n|nUnd $N, hütet Euch vor der Legion. Ihre Bösartigkeit darf nicht unterschätzt werden.', },
    {'Sprecht mit Unteroffizier Schädelbrecher bei der Versorgungskarawane außerhalb von Thrallmar im Osten.', },
  },
  [10122] = {
    'Die Erstreckung der Zitadelle',
    {'Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.|n|nIch habe einen meiner besten Späher, Gefreiter Imarion, losgeschickt, um ihre Vorgehensweise zu erkunden, aber er ist noch nicht mit seinem Bericht zurückgekehrt.|n|nImarion sollte sich auf das nördlichste Lager entlang des Südlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet ihn, $N. Ohne seinen Bericht sitzen wir hier hilflos herum.', },
    {'Durchsucht das nördlichste Lager entlang des Südlichen Bollwerks nach einer Spur von Gefreiter Imarion.', },
  },
  [10123] = {
    'Teufelsfunkenklamm',
    {'Verdammnislord Kazzak hat das Kommando über die Brennende Legion in der Scherbenwelt. Da wir Kazzak nicht direkt angreifen können - noch nicht - müssen wir zunächst seine Leutnants, die die Truppen vom Boden aus kommandieren, auslöschen.|n|nSie haben Schreckenslords in der Teufelsfunkenklamm östlich von hier postiert. Sie sind für diese höllischen Stürme, die auf uns herabprasseln, verantwortlich. Sie und ihre Diener zu vernichten wäre ein schwerer Schlag für die Legion.', },
    {'Unteroffizier Schädelbrecher bei der Versorgungskarawane östlich von Thrallmar auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet.', },
  },
  [10124] = {
    'Vorposten: Häschersturz',
    {'Eure Fähigkeiten in der Schlacht sind dem obersten Kommando aufgefallen, $C. Sie wollen Euch an die Front zu Stümmelfausts Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...|n|nGeht etwa 200 Schritte nach Osten und biegt bei der hervorragenden Landmasse nach Süden ab. Ihr findet den Häschersturz dort, wo einst ein alter Bauernhof stand. Wenn Ihr angekommen seid, meldet euch bei Vorpostenkommandant To\'arch.|n|nUnd jetzt weggetreten!', },
    {'Meldet Euch bei Vorpostenkommandant To\'arch im Häschersturz.', },
  },
  [10125] = {
    'Mission: Die Kommunikation unterbrechen',
    {'Direkt im Osten liegt die Front der Legion. Die Front dient der Brennenden Legion als mobile Kommandobasis. Ihr könnt die Sender der Legion aus der Erde herausragen sehen. Mit ihrer Hilfe kommuniziert die Legion mit ihren Konstruktionslagern in der ganzen Scherbenwelt. Sie dienen ebenfalls als Schutzeinrichtung zur Verschlüsselung sämtlicher Übertragungen, sodass eine magische Überwachung nicht mehr möglich ist.|n|nIch möchte, dass Ihr diesen Sprengstoff nehmt und die Sender damit zerstört. Zerstört sie alle, $N! Sie sind von Süden nach Norden an der Grenze der Front der Legion aufgereiht.', },
    {'Vorpostenkommandant To\'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr To\'archs Sprengstoff benutzt, um den Sender der Legion: Bosheit, Sender der Legion: Zorn, Sender der Legion: Hass und Sender der Legion: Furcht zu zerstören.', },
  },
  [10126] = {
    'Kriegsboss Nekroggs Befehle',
    {'Die Anweisungen sind mit Kriegsboss Nekrogg unterzeichnet. Sie befehlen den Höllenorcs in diesem Lager, ihren menschlichen Gefangenen zum Verhör nach Süden zu bringen.|n|nLeutnant Amadi hat erwähnt, dass das Südliche Bollwerk über mehrere Höllenorclager verfügt. Vielleicht haben sie Gefreiter Imarion zum nächsten größeren Abschnitt des Walls Richtung Süden gebracht.|n|nDa dieser Befehl von Verhör spricht, scheint es den Höllenorcs wichtig zu sein, dass Gefreiter Imarion am Leben bleibt. Nehmt schnell ihre Spur auf, bevor sie es sich anders überlegen!', },
    {'Reist entlang der westlichen Seite des Südlichen Bollwerks nach Süden und durchsucht das nächste Lager nach einer Spur von Gefreiter Imarion.', },
  },
  [10127] = {
    'Mission: Das Band zerreißen',
    {'Es wäre Vernachlässigung meiner Pflicht, wenn ich Euch nicht befehlen würde, die Dämonen an der Front der Legion, östlich von dieser Basis, zu vernichten.|n|nBeide Seiten der Front sind nach dem selben Muster aufgebaut: Teufelstreiber wandeln zwischen den Lagern der Legion hin und her, die von Zornwächtern bewacht werden. Die ganze Operation wird von einer Unterwerferin der Shivan beaufsichtigt. Tötet sie alle und überlasst Kazzak den Rest.|n|nUnd passt auf die patrouillierenden Teufelshäscher auf. Ich weiß, dass Ihr stark seid, aber diese Biester machen mit Euch kurzen Prozess.', },
    {'Vorpostenkommandant To\'arch am Häschersturz auf de Höllenfeuerhalbinsel möchte, dass Ihr 4 Teufelstreiber, 8 Zornwächter und Unterwerferin Shi\'aziv tötet.', },
  },
  [10128] = {
    'Der Soldat Imarion',
    {'Die Spuren führen von Imarions Ausrüstung aus nach Süden, anscheinend entlang des Südlichen Bollwerks. Aus den Furchen lässt sich schließen, dass die Entführer es eilig hatten, ihn an den nächsten Ort zu bringen, aber warum?|n|nHat ihn dort jemand erwartet? Vielleicht Kriegsboss Nekrogg, der Anführer, der in den Befehlen, die Ihr weiter nördlich gefunden habt, erwähnt wurde?|n|nDas Schild und die Spuren werfen mehr Fragen auf, als sie beantworten, aber es scheint sicher, dass Ihr dort, wo Ihr Gefreiter Imarion findet, auch Kriegsboss Nekrogg finden werdet.', },
    {'Setzt Euren Weg entlang des Südlichen Bollwerks fort und sucht nach dem Ort, an dem Kriegsboss Nekrogg Gefreiter Imarion gefangen hält.', },
  },
  [10129] = {
    'Mission: Tore Murketh und Shaadraz',
    {'Wir haben die beiden Haupttransporter, mit denen die Brennende Legion ihre Verstärkung herbeiholt, ausgemacht: Tor Murketh und Tor Shaadraz.|n|nWenn Ihr den Pfad des Ruhmes nach Osten hinaufschaut, könnt Ihr sie an beiden Seiten der Straße erkennen. Ich möchte, dass Ihr sie beide in Stücke sprengt!|n|nHier sind die Bomben, die Ihr dafür benötigt. Sie wurden speziell von einem Goblin in Area 52 entworfen. Sprecht mit Schwadronskommandant Brack - er wird Euch einen Wyvern zur Verfügung stellen.', },
    {'Sprecht mit Schwadronskommandant Brack, bombardiert Tor Murketh und Tor Shaadrez und kehrt dann zu Vorpostenkommandant To\'arch im Häschersturz zurück.', },
  },
  [10130] = {
    'Die westliche Flanke',
    {'Zusätzlich zu den anderen Anweisungen werden die Orc in den Befehlen angewiesen, ihre Ausrüstung und Verpflegung für einen Angriff vorzubereiten.|n|nNach den Plänen sollen Kriegsboss Nekroggs Mannen sich zu einer westlichen Flanke formieren, um die Ehrenfeste in die Zange zu nehmen.|n|nDa die Garnison der Feste sich auf die Verteidigung der östlichen Seite konzentriert, wäre ein Angriff von Westen fatal. Die Ehrenfeste kann nur gehalten werden, wenn der Angriff von Westen niemals stattfindet.', },
    {'Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Leutnant Amadi im westlichen Wachturm der Ehrenfeste.', },
  },
  [10131] = {
    'Fluchtplan',
    {'Wie ich schon gesagt habe, hier rauszukommen wird nicht leicht. Kriegsboss Nekrogg mag vielleicht wie ein übergroßer Schläger aussehen, aber er ist kein Dummkopf.|n|nEr wird den Käfigschlüssel nicht aus den Augen lassen und kommt nicht aus seinem Turm auf dieser massiven Mauer heraus, bis er bereit ist, mich oder diese Orcfrau, die er gefangen hat, zu verhören.|n|nWir brauchen schon etwas Besonderes, um ihn aus diesen Mauern zu locken, aber ich habe einen Plan. Sucht einen der Grenadiere, die am Südlichen Bollwerk entlang patrouillieren, und bringt mir etwas von seinem Sprengstoff.', },
    {'Tötet einen Grenadier des Lachenden Schädels und bringt seine primitive Sprengladung zu Gefreiter Imarion im Außenposten von Gor\'gaz.', },
  },
  [10132] = {
    'Eine kolossale Bedrohung',
    {'Seht Ihr diesen riesigen roten Kristall im Norden? Er ist vor Kurzem vom Himmel gefallen und hat dabei ein großes Erdbeben ausgelöst.|n|nAls wir hierher kamen, um den Grund für den Aufruhr zu erforschen, haben wir all die Kolosse hier gesehen, die zuvor noch nicht da waren.|n|nEs ist eindeutig etwas faul an dem Kristall und den Energien, die er ausstrahlt, aber ich habe keine Zeit dafür. Ich muss mich zuerst um diese Bergriesen kümmern.|n|nIch möchte, dass Ihr zum Himmelssturzgrat geht und Euch um sie kümmert.', },
    {'Tötet 5 tobende Kolosse und kehrt dann zu Tola\'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.', },
  },
  [10133] = {
    'Mission: Tötet den Boten',
    {'Euer Geschick bereitet der Legion große Schwierigkeiten, $N. Meine Späher haben mich informiert, dass die Legion Kuriere benutzt, um untereinander zu kommunizieren. Wir haben es geschafft, ihre Truppen vom Hauptlager abzuschneiden!|n|nWorum ich Euch nun bitte ist mehr, als ich von einem normalen Soldaten verlangen würde.|n|nDer Kurier der Legion reist zwischen den Teichen von Aggonar und dem Konstruktionsbasis: Mageddon, nördlich von hier, hin und her. Ihr müsst den Kurier bei Mageddon abfangen, ihn erledigen und mit dem Schriftwechsel der Legion zu mir zurückkehren.', },
    {'Vorpostenkommandant To\'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr Arix\'maladish findet und tötet und den Schriftwechsel der Legion besorgt.', },
  },
  [10134] = {
    'Hinweise des purpurnen Kristalls',
    {'Als der Koloss Eurem Angriff zum Opfer fällt, bemerkt Ihr, dass er ein rotes Kristallfragment in der Hand hält.|n|nIn der Hand des Riesen schien es sehr klein und unauffällig, aber für Euch ist das Stück sehr schwer zu tragen. Es sieht sehr verdächtig nach einem Stück des riesigen roten Kristalls in der Mitte des Grats aus.|n|nDies ist ganz sicher ein Hinweis auf die merkwürdigen Dinge, die hier geschehen. Ihr seid Euch sicher, dass die Druiden beim Posten des Cenarius im Süden den Splitter sehen wollen.', },
    {'Bringt den Purpurkristallsplitter zu Tola\'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel.', },
  },
  [10135] = {
    'Mission: Seid der Bote',
    {'Ich bin nur ein Feldkommandeur, $C. Die Befugnis, auf solche Informationen hin zu handeln, fällt nur unserem Anführer, Nazgrel, zu. Ihr müsst den Schriftwechsel nach Thrallmar zu ihm bringen. Reitet schnell wie der Wind, Soldat. Lasst Euch durch nichts aufhalten!', },
    {'Bringt den Schriftwechsel der Legion zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.', },
  },
  [10136] = {
    'Grausame Pläne',
    {'Magister Blutfalke hat endlich den Schriftwechsel der Legion, den Ihr gefunden habt, entziffert. Wie es aussieht, handelt es sich dabei um Angriffspläne, die von einem Leutnant des Hochlords Kazzak geschickt wurden - Arazzius der Grausame. Offensichtlich hat Arazzius den Befehl über die Bodentruppen auf der Höllenfeuerhalbinsel. Es ist an der Zeit, dass wir seinen Befehl beenden, $N. Vernichtet ihn mit größter Vorsicht.|n|nBegebt Euch zu den Teichen von Aggonar und setzt dem so genannten \'Legionslord\' ein Ende. Heute fordert die Horde die Höllenfeuerhalbinsel zurück. Die Legion möge verdammt sein.', },
    {'Tötet Arazzius den Grausamen und kehrt danach zu Nazgrel in Thrallmar zurück.', },
  },
  [10137] = {
    'Den Kriegsboss provozieren',
    {'Der Erfolg des Plans hängt von der Qualität des Sprengstoffs ab...|n|nSo ungern ich mich auch auf etwas verlasse, das von einem Orc hergestellt wurde, ist dies meine einzige Möglichkeit hier rauszukommen. Nehmt dies und werft es gegen das Banner, das vom Turm da oben weht.|n|nWenn es explodiert wird Kriegsboss Nekrogg es sich nicht nehmen lassen, ein Exempel an dem Störenfried zu statuieren. Tötet ihn und nehmt den Schlüssel, um meinen Käfig zu öffnen. Viel Erfolg, $N.', },
    {'Benutzt die primitiven Sprengladungen um einen Tumult zu veranstalten und Kriegsboss Nekrogg aus seinem Turm zu locken. Tötet ihn, besorgt Nekroggs Schlüssel und öffnet damit Gefreiter Imarions Käfig. Wenn Ihr Gefreiter Imarion befreit habt, meldet Euch bei Leutnant Amadi.', },
  },
  [10138] = {
    'Auf wessen Befehl hin?',
    {'Eines ist klar, $N: wir können nicht so weitermachen. Die Höllenorcs haben uns eingekreist, und sobald wir sie erledigen, nehmen gleich mehrere ihren Platz ein. Wir können nicht hoffen, dass wir diesen Krieg gewinnen können, indem wir uns hinter den zerschlagenen Mauern der Ehrenfeste verstecken und die Tage bis zu unserem Tod durch die Hand der Höllenorcs zählen.|n|nIhr habt beeindruckende Arbeit geleistet und uns vor den schlimmsten Angriffen der Höllenorcs bewahrt, aber jetzt müsst Ihr Euch den Weg entlang des Pfads des Ruhmes freikämpfen und herausfinden, wer diese Angriffe steuert.', },
    {'Tötet 20 Grunzer der Zerschmetterten Hand, 10 Hexenmeister der Zerschmetterten Hand und besorgt Euch Drillmeister Zurok\'s Anweisungen. Kehrt dann zu Leutnant Amadi im westlichen Wachturm der Ehrenfeste zurück.', },
  },
  [10139] = {
    'Die Beseitigung des Kommandanten',
    {'So wie ich das sehe, war Drillmeister Zurok die rechte Hand des Anführers der Höllenorcs auf der Höllenfeuerhalbinsel, Truppenkommandant Gorax.|n|nDieser Gorax ist anders als die gewöhnlichen Schläger der Höllenorcs. Ich bewundere fast, wie er uns schon so lange in der Defensive halten konnte.|n|nZuroks Befehle deuten an, dass Gorax\' Kommandozentrale am Ende des Pfads des Ruhms liegt, dort, wo die Mauern der Zitadelle auf das Nördliche Bollwerk treffen. Ich habe keine Ahnung, was Euch dort erwartet, $N, aber Ihr solltet besser mit ein paar Gefährten reisen.', },
    {'Tötet Truppenkommandant Gorax und meldet Euch dann bei Leutnant Amadi im westlichen Turm der Ehrenfeste zurück.', },
  },
  [10140] = {
    'Reise zur Ehrenfeste',
    {'Wenn Ihr bereit seid, werde ich Euch einen Flug direkt zur Ehrenfeste besorgen.|n|nSprecht dort mit Marschall Isildor und gebt ihm Durons Bericht. Er wird sich freuen, einen weiteren Rekrut aus der Heimat zu sehen, und ich bin mir sicher, dass die Informationen in diesem Bericht sehr wichtig sind!', },
    {'Fliegt zur Ehrenfeste und übergebt Marschall Isildor Durons Bericht.', },
  },
  [10141] = {
    'Wiedergeburt der Brennenden Legion',
    {'Als die Brennende Legion in Azeroth eingefallen ist, war sie hier in der Scherbenwelt nicht untätig. Wir haben ihre Bewegungen über die Jahre verfolgt, aber ihre letzte Tat, $C, ist schlimmer als alles, was wir je gesehen haben.|n|nSprecht mit Unteroffizier Altumus in der Nähe der Östlichen Versorgungskarawane. Er hat die Eindringlinge beobachtet und weiß vielleicht mehr über ihre Pläne.|n|nSeid schnell und passt auf, $N - die Brennende Legion darf auf keinen Fall unterschätzt werden.', },
    {'Sprecht mit Unteroffizier Altumus bei der Östlichen Versorgungskarawane außerhalb der Ehrenfeste im Osten.', },
  },
  [10142] = {
    'Der Pfad der Pein',
    {'Verdammnislord Kazzak hat das Kommando über die Brennende Legion in der Scherbenwelt. Da wir Kazzak nicht direkt angreifen können - noch nicht - müssen wir zunächst seine Leutnants, die die Truppen vom Boden aus kommandieren, auslöschen.|n|nSie haben Schreckenslords am Pfad der Pein östlich von hier postiert. Sie sind für diese teuflischen Stürme, die auf uns herabprasseln, verantwortlich. Sie und ihre Diener zu vernichten wäre ein schwerer Schlag für die Legion.', },
    {'Unteroffizier Altumus bei der Östlichen Versorgungskarawane östlich der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet.', },
  },
  [10143] = {
    'Expeditionsposten',
    {'Eure Fähigkeiten in der Schlacht sind dem obersten Kommando aufgefallen, $C. Sie wollen Euch an die Front zu Rohamus\' Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...|n|nGeht etwa 400 Schritte nach Osten, durch das Tal der Knochen, bis Ihr auf einen zerstörten Teufelshäscher stoßt. Ihr findet den Expeditionsposten dort, wo einst ein Lager der Legion war. Wenn Ihr angekommen seid, meldet Euch bei Vorpostenkommandant Königstein.|n|nUnd jetzt weggetreten!', },
    {'Meldet euch bei Vorpostenkommandant Königstein im Expeditionsposten.', },
  },
  [10144] = {
    'Die Verstärkung abschneiden',
    {'Direkt im Nordosten liegt die Front der Legion. Entlang der Front befinden sich die infernalen Portale, mit deren Hilfe Verstärkung auf die Höllenfeuerhalbinsel und in die ganze Scherbenwelt gebracht wird. Wir müssen diese Portale zerstören, $N!|n|nNehmt diesen Zünder. Er wurde in Area 52 hergestellt und benutzt die eigene Macht der Dämonen als Sprengstoff! Besiegt die Legion beim Portal Grimh und Portal Kaalez und haltet nach dämonischen Runensteinen Ausschau. Wenn Ihr genug Steine beisammen habt, benutzt den Zünder, um die Steine in den Portalen zu sprengen... und dann genießt das Feuerwerk!|n|nGeht, $N, und kehrt zu mir zurück, wenn Ihr Eure Aufgabe erfüllt habt.', },
    {'Besiegt die Feinde um Portal Grimh und Portal Kaalez herum, um dämonische Runensteine zu sammeln.|n|nBenutzt Königsteins Zünder in Portal Grimh und Portal Kaalez.|n|nKehrt danach mit dem Zünder zu Vorpostenkommandant Königstein zurück.', },
  },
  [10145] = {
    'Mission: Das Band zerreißen',
    {'Es wäre Vernachlässigung meiner Pflicht, wenn ich Euch nicht befehlen würde, die Dämonen an der Front der Legion, nördlich von dieser Basis, zu vernichten.|n|nBeide Seiten der Front sind nach dem selben Muster aufgebaut: Teufelstreiber wandeln zwischen den Lagern der Legion hin und her, die von Zornwächtern bewacht werden. Die ganze Operation wird von einer Unterwerferin der Shivan beaufsichtigt. Tötet sie alle und überlasst Kazzak den Rest.|n|nUnd passt auf die patrouillierenden Teufelshäscher auf. Ich weiß, dass Ihr stark seid, aber diese Biester machen mit Euch kurzen Prozess.', },
    {'Vorpostenkommandant Königstein beim Expeditionsposten auf de Höllenfeuerhalbinsel möchte, dass Ihr 4 Teufelstreiber, 8 Zornwächter und Unterwerferin Shi\'aziv tötet.', },
  },
  [10146] = {
    'Mission: Tor Murketh und Tor Shaadraz',
    {'Westlich des Dunklen Portals befinden sich zwei riesige Transporter: Tor Murketh und Tor Shaadraz.|n|nWenn Ihr den Pfad des Ruhmes nach Osten hinaufschaut, könnt Ihr sie an beiden Seiten der Straße erkennen. Ich möchte, dass Ihr sie in Stücke sprengt!|n|nHier sind die Bomben, die Ihr benutzen sollt. Sie wurden speziell von einem Goblin in Area 52 entworfen. Sprecht nun mit Schwadronskommandant Dabir\'ee - er wird Euch einen Greifen zur Verfügung stellen und Euch losschicken.', },
    {'Sprecht mit Schwadronskommandant Dabir\'ee, bombardiert Tor Murketh und Tor Shaadraz und kehrt dann zu Vorpostenkommandant Königstein im Häschersturz zurück.', },
  },
  [10147] = {
    'Mission: Tötet den Boten',
    {'Euer Geschick bereitet der Legion große Schwierigkeiten, $N. Meine Späher haben mich informiert, dass die Legion Kuriere benutzt, um untereinander zu kommunizieren. Wir haben es geschafft, ihre Truppen vom Hauptlager abzuschneiden!|n|nWorum ich Euch nun bitte ist mehr, als ich von einem normalen Soldaten verlangen würde.|n|nDer Kurier der Legion reist zwischen den Teichen von Aggonar und dem Konstruktionsbasis: Mageddon, nördlich von hier, hin und her. Ihr müsst den Kurier bei Mageddon abfangen, ihn erledigen und mit dem Schriftwechsel der Legion zu mir zurückkehren.', },
    {'Vorpostenkommandant Königstein im Expeditionsposten auf der Höllenfeuerhalbinsel möchte, dass Ihr Arix\'maladish findet und tötet und den Schriftwechsel der Legion besorgt.', },
  },
  [10148] = {
    'Mission: Seid der Bote',
    {'Ich bin nur ein Feldkommandeur, $C. Die Befugnis, auf solche Informationen hin zu handeln, fällt nur unserem Anführer, Truppenkommandant Danath, zu. Ihr müsst den Schriftwechsel zur Ehrenfeste zu ihm bringen. Reitet schnell wie der Wind, Soldat. Lasst Euch durch nichts aufhalten!', },
    {'Bringt den Schriftwechsel der Legion zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel.', },
  },
  [10149] = {
    'Mission: Beendet alles, seid alles',
    {'Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr Arazzius den Grausamen tötet.', },
    {'Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr Arazzius den Grausamen tötet.', },
  },
  [10150] = {
    'Die Erstreckung der Zitadelle',
    {'Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.|n|nIch habe einen meiner besten Spurenleser, Späherin Makha, losgeschickt, um ihre Vorgehensweise zu erkunden, aber sie ist noch nicht mit ihrem Bericht zurückgekehrt.|n|nMakha sollte sich auf das nördlichste Lager entlang des Nördlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet sie, $N. Ohne ihren Bericht sitzen wir hier hilflos herum.', },
    {'Durchsucht das nördlichste Lager entlang des Nördlichen Bollwerks nach einer Spur von Späherin Makha.', },
  },
  [10151] = {
    'Kriegsboss Nekroggs Befehle',
    {'Die Anweisungen sind mit Kriegsboss Nekrogg unterzeichnet. Sie befehlen den Höllenorcs in diesem Lager, ihren menschlichen Gefangenen zum Verhör nach Süden zu bringen.|n|nSchattenjäger Ty\'jin hat erwähnt, dass das Nördliche Bollwerk über mehrere Höllenorclager verfügt. Vielleicht haben sie Späherin Makha zum nächsten größeren Abschnitt des Walls Richtung Süden gebracht.|n|nDa dieser Befehl von Verhör spricht, scheint es den Höllenorcs wichtig zu sein, dass sie am Leben bleibt. Nehmt schnell ihre Spur auf, bevor sie es sich anders überlegen!', },
    {'Reist entlang der westlichen Seite des Nördlichen Bollwerks nach Süden und durchsucht das nächste Lager nach einer Spur von Späherin Makha.', },
  },
  [10152] = {
    'Die westliche Flanke',
    {'Zusätzlich zu den anderen Anweisungen werden die Orc in den Befehlen angewiesen, ihre Ausrüstung und Verpflegung für einen Angriff vorzubereiten.|n|nNach den Plänen sollen Kriegsboss Nekroggs Mannen sich zu einer westlichen Flanke formieren, um Thrallmar in die Zange zu nehmen.|n|nDa die Garnison der Feste sich auf die Verteidigung der östlichen Seite konzentriert, wäre ein Angriff von Westen fatal. Thrallmar kann nur gehalten werden, wenn der Angriff von Westen niemals stattfindet.', },
    {'Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Steingardist Ambelan im Rückenbrecherposten in der Nähe von Zeth\'Gor.', },
  },
  [10153] = {
    'Die Späherin Makha',
    {'Die Spuren führen von Makhas Ausrüstung aus nach Süden, anscheinend über den Pfad des Ruhms. Aus den Furchen lässt sich schließen, dass die Entführer es eilig hatten, sie an den nächsten Ort zu bringen, aber warum?|n|nHat sie dort jemand erwartet? Vielleicht Kriegsboss Nekrogg, der Anführer, der in den Befehlen, die Ihr weiter nördlich gefunden habt, erwähnt wurde?|n|nDas Schild und die Spuren werfen mehr Fragen auf, als sie beantworten, aber es scheint sicher, dass Ihr dort, wo Ihr Späherin Makha findet, auch Kriegsboss Nekrogg finden werdet.', },
    {'Setzt Euren Weg über den Pfad des Ruhms fort und sucht nach dem Ort, an dem Kriegsboss Nekrogg Späherin Makha gefangen hält.', },
  },
  [10154] = {
    'Fluchtplan',
    {'Wie ich schon gesagt habe, hier rauszukommen wird nicht leicht. Kriegsboss Nekrogg mag vielleicht wie ein übergroßer Schläger aussehen, aber er ist kein Dummkopf.|n|nEr wird den Käfigschlüssel nicht aus den Augen lassen und kommt nicht aus seinem Turm auf dieser massiven Mauer heraus, bis er bereit ist, mich oder diese Orcfrau, die er gefangen hat, zu verhören.|n|nWir brauchen schon etwas Besonderes, um ihn aus diesen Mauern zu locken, aber ich habe einen Plan. Sucht einen der Grenadiere, die am Südlichen Bollwerk entlang patrouillieren, und bringt mir etwas von seinem Sprengstoff.', },
    {'Tötet einen Grenadier des Lachenden Schädels und bringt seine primitive Sprengladung zu Späherin Makha im Außenposten von Gor\'gaz.', },
  },
  [10155] = {
    'Den Kriegsboss provozieren',
    {'Der Erfolg des Plans hängt von der Qualität des Sprengstoffs ab...|n|nSo ungern ich mich auch auf etwas verlasse, das von einem Höllenorc hergestellt wurde, ist dies meine einzige Möglichkeit hier rauszukommen. Nehmt dies und werft es gegen das Banner, das vom Turm da oben weht.|n|nWenn es explodiert wird Kriegsboss Nekrogg es sich nicht nehmen lassen, ein Exempel an dem Störenfried zu statuieren. Tötet ihn und nehmt den Schlüssel, um meinen Käfig zu öffnen. Viel Erfolg, $N.', },
    {'Benutzt die primitive Sprengladung um einen Tumult zu veranstalten und Kriegsboss Nekrogg aus seinem Turm zu locken. Tötet ihn, besorgt Nekroggs Schlüssel und öffnet damit Späherin Makhas Käfig. Wenn Ihr Späherin Makha befreit habt, meldet Euch bei Steingardist Ambelan im Rückenbrecherposten in der Nähe von Zeth\'Gor.', },
  },
  [10156] = {
    'Auf wessen Befehl hin?',
    {'Eines ist klar, $N: wir können nicht so weitermachen. Die Höllenorcs haben uns eingekreist, und sobald wir sie erledigen, nehmen gleich mehrere ihren Platz ein. Wir können nicht hoffen, dass wir diesen Krieg gewinnen können, wenn unsere Streitkräfte zweigeteilt sind und sich im ständigen Kampf mit den Höllenorcs und den Dämonen der Legion befinden.|n|nIhr habt beeindruckende Arbeit geleistet und uns vor den schlimmsten Angriffen der Höllenorcs bewahrt, aber jetzt müsst Ihr Euch den Weg entlang des Pfads des Ruhmes freikämpfen und herausfinden, wer diese Angriffe steuert.', },
    {'Tötet 20 Grunzer der Zerschmetterten Hand, 10 Hexenmeister der Zerschmetterten Hand und besorgt Euch Drillmeister Zurok\'s Anweisungen. Kehrt dann zu Steingardist Ambelan im Rückenbrechergrat zurück.', },
  },
  [10157] = {
    'Die Beseitigung des Kommandanten',
    {'So wie ich das sehe, war Drillmeister Zurok die rechte Hand des Anführers der Höllenorcs auf der Höllenfeuerhalbinsel, Truppenkommandant Gorax.|n|nDieser Gorax ist anders als die gewöhnlichen Schläger der Höllenorcs. Ich bewundere fast, wie er uns schon so lange in der Defensive halten konnte.|n|nZuroks Befehle deuten an, dass Gorax\' Kommandozentrale am Ende des Pfads des Ruhms liegt, dort, wo die Mauern der Zitadelle auf das Nördliche Bollwerk treffen. Ich habe keine Ahnung, was Euch dort erwartet, $N, aber Ihr solltet besser mit ein paar Gefährten reisen.', },
    {'Tötet Truppenkommandant Gorax und meldet Euch dann bei Schattenjäger Ty\'jin in Thrallmar zurück.', },
  },
  [10158] = {
    'Vorräte des Blutenden Auges',
    {'Die orcischen Ruinen von Zeth\'Gor im Südosten dienen als Basislager für die immer weiter steigende Flut von Höllenorcs, die aus der Höllenfeuerzitadelle strömt.|n|nSchattenjäger Ty\'jin hat mich geschickt, um den Außenposten und seine merkwürdigen Bewohner zu beobachten.|n|nEtwas hat diese Orcs auf eine Art und Weise verändert, die ich noch nie zuvor gesehen habe. Wir müssen alles in unserer Macht Stehende tun, um zu verhindern, dass sie noch stärker werden. Geht nach Zeth\'Gor und zerstört sämtliche Vorräte, die Ihr dort finden könnt.', },
    {'Zerstört 6 Stapel Vorräte des Blutenden Auges und meldet Euch dann bei Steingardist Ambelan im Rückenbrecherposten zurück.', },
  },
  [10159] = {
    'Haltet den Dornnebelhügel sauber!',
    {'Wir kämpfen schon die ganze Zeit, um den Pass durch den Dornnebelhügel von den Verheerern freizuhalten. Es wäre schlecht, wenn wir ganz von der Zuflucht in den Zangarmarschen abgeschnitten wären.|n|nWir möchten die Tiere nicht vertreiben, aber wir haben kaum einen andere Wahl, sie werden Reisenden in dieser Gegend gegenüber immer aggressiver.|n|nLöscht ein paar von den Felshetzern aus, wenn Ihr könnt.', },
    {'Tötet 8 Dornenfangfelshetzer und 8 Dornenfanggiftspucker und kehrt dann zu Mahuram Starkhuf im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.', },
  },
  [10160] = {
    'Den Feind kennen',
    {'Es gibt Gerüchte, dass eine neue Brut von Orcs aufkommt. Größer, bösartiger und listiger als die Rüpel, mit denen wir uns sonst herumschlagen müssen. Wenn diese Gerüchte wahr sind, müssen unsere Streitkräfte, die ohnehin schon überansprucht sind, sich bis über ihre Grenzen hinaus belasten.|n|nIch habe meinen Leutnant, Amadi, damit betraut, die Sache zu untersuchen. Wenn Ihr uns in dieser dunklen Stunde beistehen wollt, dann meldet Euch bei ihr. Sie befindet sich in dem zerbrochenen Turm im Westen der Feste.|n|nUnd $N, seid vorsichtig da draußen. Ihr stürzt Euch in eine neue, gefährliche Welt.', },
    {'Sprecht mit Leutnant Amadi im alten Wachturm im Westen der Ehrenfeste.', },
  },
  [10161] = {
    'Im Notfall...',
    {'Bei einem Notfall ist es die Aufgabe des Piloten, einen kühlen Kopf zu bewahren, besonders, wenn die einzigen Befehle, die der Kopilot befolgt, die seines Magens sind.|n|nDie gute Nachricht ist, dass wir nicht tagelang darauf warten müssen, dass uns Ersatzteile geliefert werden. Die schlechte Nachricht ist, dass die Ersatzteile überall von hier bis zum Tal der Knochen im Osten verstreut sind.|n|nDie andere schlechte Nachricht? Die Ersatzteile sind nicht so leicht ersetzbar. Sie, äh, sind bei unserem schnellen Abgang abgefallen. Könntet Ihr mir vielleicht helfen, genügend davon wieder vom Boden aufzusammeln?', },
    {'Sammelt 30 Zeppelintrümmer und bringt sie zu "Schreihals" Quack Lufthans bei der Zeppelinabsturzstelle.', },
  },
  [10162] = {
    'Mission: Die Abyssische Untiefe',
    {'Jetzt, da Ihr Eure Flügel habt, habt Ihr vielleicht Interesse an einem weiteren Bombardement?|n|nDieses Mal haben wir die Hauptproduktionsstätte der Legion isoliert, hinter den Konstruktionslagern im Norden. Schwingt Euch auf einen Wyvern und zerstört das verdammte Ding!|n|nHier sind die Bomben. Sprecht mit Schwadronskommandant Brack wenn Ihr zum Abflug bereit seid.', },
    {'Vorpostenkommandant To\'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan\'arg, 5 Vorarbeiter der Mo\'arg und 5 Teufelskanonen vernichtet.', },
  },
  [10163] = {
    'Mission: Die Abyssische Untiefe',
    {'Jetzt, da Ihr Eure Flügel habt, habt Ihr vielleicht Interesse an einem weiteren Bombardement?|n|nDieses Mal haben wir die Hauptproduktionsstätte der Legion isoliert, hinter den Konstruktionslagern im Norden. Schwingt Euch auf einen Greifen und zerstört das verdammte Ding!|n|nHier sind Eure Bomben. Sprecht mit Greifnerin Heulwind wenn Ihr zum Abflug bereit seid.', },
    {'Schwadronskommandant Greifgar im Trümmerposten auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan\'arg, 5 Vorarbeiter der Mo\'arg und 5 Teufelskanonen vernichtet.', },
  },
  [10164] = {
    'Alles wird gut',
    {'Ihr habt ein ganz schönes Abenteuer hinter Euch, $N. Und das noch bevor Ihr überhaupt einen Fuß in den Auchenaikrypta gesetzt habt.|n|nIch bin einer der glücklichen Geister. Ich war nie an Levixus gebunden oder Teil eines der bösartigen Experimente in der Nekromantie von Exarch Maladaar. Während Levixus durch Eure Hand gestorben ist, lebt Maladaar immer noch weiter und quält die Geister in der Krypta.|n|nWorum ich Euch bitte ist ganz einfach. Geht in die Auchenaikrypta und tötet Exarch Maladaar, damit die gefangenen Geister endlich Frieden finden können.', },
    {'Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr in die Auchenaikrypta geht und Exarch Maladaar vernichtet.', },
  },
  [10165] = {
    'Die Konkurrenz untergraben',
    {'Dieser Shaffar ist ganz schön gerissen, das muss man ihm lassen... Er hat es geschafft, das Konsortium fern zu halten, während er in aller Seelenruhe diese Gruft all ihrer Schätze beraubt. Ich glaube nicht, dass diese Dummköpfe es tatsächlich schaffen, durch seine Verteidigung zu brechen, deshalb mache ich Euch einen Vorschlag, $R.|n|nDringt in die Managruft ein und tötet den Nexusprinzen Shaffar. Bringt mir seine Körperbandagen als Beweis Eurer Tat, und ich werde Euch fürstlich belohnen.', },
    {'Nexusprinz Haramad außerhalb der Managruft möchte, dass Ihr Nexusprinz Shaffar tötet und ihm Shaffars Bandagen bringt.', },
  },
  [10166] = {
    'Weißborkes Erinnerung',
    {'Dieser Anhänger bringt Erinnerungen an eine andere Zeit zurück. Eine bessere Zeit.|n|nLeider sind Erinnerungen das Letzte, was ich jetzt gebrauchen kann.|n|nIch möchte, dass Ihr dies beim Runenstein im Versengten Hain vergrabt. Dort habe ich den Treantältesten zum ersten Mal getroffen. Bettet die Erinnerung an meinen alten Freund in Frieden.', },
    {'Larianne Flusswind möchte, dass Ihr Weißborkes Anhänger beim Runenstein im Versengten Hain vergrabt.', },
  },
  [10167] = {
    nil,
    {'Tief in der Auchenaikrypta befindet sich ein Grab: ein Grab, dass keinesgleichen in den Zerschlagenen Weiten findet. Aus diesem Grab, dem ersten Grab, wurde das riesige Mausoleum von Auchindoun geboren.|n|nIhr müsst zu der Auchenaikrypta reisen und dieses Grab finden. Tötet den Grabwächter und befreit den Geist, der darin gefangen ist. Der Geist ist der Schlüssel...', },
    {'Reist zur Auchenaikrypta in der Knochenwüste der Wälder von Terokkar und tötet Exarch Maladaar um den Geist von D\'ore zu befreien.', },
  },
  [10168] = {
    'Was die Seele sieht',
    {'Seit mehreren Jahrhunderten verbinden sich die Geister von Auchindoun nun mit meiner getrübten Essenz. Viele der Katastrophen, die diese Krypta heimgesucht haben, sind auf meinen geschwächten Zustand zurückzuführen.|n|nUnglücklicherweise kann nichts diesen Kreis aufhalten. Das gehört zur Natur der Naaru - ohne die Leere kann das Licht nicht existieren.|n|nEure einzige Möglichkeit besteht darin, die Geister von Nagrand zu vernichten, bevor sie sich in Wesen der Leere verwandeln. Benutzt die Seelenspiegel, die sich überall in der Krypta befinden, um sie zu befreien...', },
    {'Sucht einen Seelenspiegel in der Auchenaikrypta und benutzt ihn, um einen getrübten Geist eines uralten Orcahnen zu rufen. Zerstört 15 getrübte Geister, damit die Ahnen in Frieden ruhen können.|n|nKehrt zu Mutter Kashur im Ahnengrund zurück, wenn Ihr fertig seid.', },
  },
  [10169] = {
    'In Würde verlieren',
    {'Die Aldor haben sich heute das Wohlwollen der Sha\'tar verdient. Als ob das etwas Überraschendes wäre!|n|nSchaut nur, wie sie nur ein paar Fuß von A\'dal entfernt mit ihrer tollen Beinarbeit angeben. Könnten sie sich wohl noch mehr bemühen, sich bei den Naaru einzuschmeicheln?|n|nHerold Haronems Schützen sind so engagiert, dass sie sogar ihren eigenen Kochtopf mitbringen, um keine langen Pausen zum Mittagessen machen müssen. Das kann nicht ohne Strafe vonstatten gehen, $N.|n|nIch möchte, dass Ihr diese Phiole in ihr Essen kippt. Die Folgen sollten... sehr amüsant sein.', },
    {'Magister Falris in Shattrath möchte, dass Ihr die Phiole mit Beruhigungsserum zur Terrasse des Lichts bringt und sie in den Kochtopf von Haronems Regiment schüttet.', },
  },
  [10170] = {
    'Rückkehr zur Großmutter',
    {'Kehrt zu Großmutter Geyah in Garadar zurück und berichtet ihr von Eurem Sieg, $N. Das wird den Mag\'har sicher neuen Mut geben. Vielleicht erwacht sogar der junge Höllschrei aus seiner Melancholie.', },
    {'Kehrt nach Garadar zurück und sprecht mit Großmutter Geyah.', },
  },
  [10171] = {
    'Der untröstliche Häuptling',
    {'Ihr habt so viel für die Mag\'har getan, $N. Alle wissen von Euren Taten, auch Garrosh. Geht nun zu ihm und erzählt ihm von eurem letzten Erfolg. Sagt ihm, was Ihr für ihn und sein Volk getan habt. Eure Worte werden ihn sicher trösten.', },
    {'Großmutter Geyah in Garadar möchte, dass Ihr mit Garrosh sprecht.', },
  },
  [10172] = {
    'Es gibt keine Hoffnung',
    {'Ihr seid $Gein ehrenwerter:eine ehrenwerte:r; $R, $N. Ihr habt viel für die Mag\'har getan. Niemand könnte Eure Dienste für mein Volk je leugnen. Dennoch ist die Zeit der Mag\'har abgelaufen. Ihr habt mir mehr als alles andere gezeigt, dass ich nicht in der Lage bin, diese Leute anzuführen. Zu stark ist der Fluch meines Blutes. Ich werde nicht... ich kann nicht der nächste Höllschrei sein, der die Orcs in die Verdammnis führt.|n|nBitte, $N, kehrt zur Großmutter zurück und erklärt ihr, was ich Euch gesagt habe. Ich schäme mich zu sehr, um zu ihr zu gehen... ihr in die Augen zu schauen.', },
    {'Sprecht mit Großmutter Geyah und erzählt ihr, was Garrosh Euch gesagt hat.', },
  },
  [10173] = {
    'Der Stab des Erzmagiers',
    {'Erlaubt, dass ich mich vorstelle, $C.|n|nMein Name ist Ravandwyr, Lehrling des Erzmagiers Vargoth.|n|nMein Meister ist... nennen wir es indisponiert. Ich bin hier in einer Angelegenheit von höchster Wichtigkeit.|n|nDie Ruinen von Arklon südöstlich der Stadt sind eine Brutstätte für die Aktivitäten der Brennenden Legion. Was sie mit den Ruinen vorhaben interessiert weder mich noch meinen Meister. Aber ihre Anführerin, Ekkorash, hat den Stab meines Meisters.|n|nMit diesem Beschwörungspulver könnt Ihr die Dämonin aus ihrem Versteck locken. Streut es über die Kohlenpfanne in der Mitte der Ruinen.', },
    {'Besorgt Erzmagier Vargoths Stab von Ekkorash der Inquisitorin und bringt ihn zu Ravandwyr in Area 52. Um Ekkorash aus ihrem Versteck hervorzulocken, streut das Beschwörungspulver auf die Kohlenpfanne in der Mitte der Ruinen.', },
  },
  [10174] = {
    'Der Fluch des Violetten Turms',
    {'Jetzt könnt Ihr mithilfe des Stabs Kontakt zu dem Erzmagier aufnehmen.|n|nEr lebt im Violetten Turm, auf einer Insel im Süden. Der verfluchte Turm ist sowohl eine Zuflucht als auch ein Gefängnis für ihn. Mitglieder und Verbündete der Kirin Tor können weder hinein noch hinaus, weswegen ich meinen Meister nicht sehen kann.|n|nDer Stab kann die Verteidigung des Turms durchbrechen, jedoch nur, wenn er von jemandem, der nicht zu den Kirin Tor gehört, aktiviert wird.|n|nNehmt den Stab und benutzt ihn, um ein Abbild des Erzmagiers zu erschaffen. Sagt ihm, was passiert ist und beweist ihm, dass ich ihn nicht ganz enttäuscht habe.', },
    {'Benutzt Erzmagier Vargoths Stab um Kontakt mit Erzmagier Vargoth aufzunehmen.|n|nFalls Ihr Erzmagier Vargoths Stab verlieren solltet, bittet Ravandwyr in Area 52 um Ersatz.', },
  },
  [10175] = {
    'Thrall, Sohn Durotans',
    {'Kehrt in Eure Welt zurück, $N. Sucht meinen Enkelsohn und sagt ihm, dass sein Blut hier ist - in dieser zerschlagenen Welt.|n|nSagt ihm, dass das Erbe seines Vaters weiterlebt.|n|nSagt ihm alles...', },
    {'Reist nach Orgrimmar und überbringt Thrall Geyahs Nachricht.', },
  },
  [10176] = {
    'Arkelos der Wächter',
    {'Jetzt, da Ihr alle Gegenstände, die ich benötige, um Kael\'thas Fluch zu brechen, gesammelt habt, gibt es nur noch Eines zu tun. Als Kael\'thas den Turm versiegelt hat, hat er einen arkanen Golem, der als Ar\'kelos bekannt ist, auf dem Grund des Turms platziert.|n|nIhr müsst Ar\'kelos besiegen, damit ich innerhalb des Turms wieder meine Magie wirken kann.|n|nWenn Ihr den Violetten Turm betretet, wird der Fluch Euch treffen.|n|nSobald Ihr Ar\'kelos besiegt habt, steigt den Turm hinauf und unterstützt mich bei den Vorbereitungen für das Ritual.', },
    {'Betretet den Violetten Turm in der Mitte von Kirin\'Var und besiegt Ar\'kelos. Sprecht danach mit Erzmagier Vargoth.', },
  },
  [10177] = {
    'Ärger in Auchindoun',
    {'Meine Spione in Auchindoun haben uns erschreckende Berichte geschickt. Seit seiner Explosion vor ein paar Jahren hat dieser Ort nichts als Ärger gebracht.|n|nDort ist etwas - mal wieder - ganz schön schief gegangen, und der Schattenrat bereitet sich auf einen Krieg vor. Auch wenn die Berichte viele Details verschweigen, müssen sie sich auf einen Krieg im Inneren vorbereiten.|n|nIhr müsst Euch zum Eingang des Schattenlabyrinths begeben. Mein Feldkommandeur, Mahfuun, wird Euch genau erklären, was zu tun ist.', },
    {'Meldet Euch bei Feldkommandeur Mahfuun beim Eingang zum Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar.', },
  },
  [10178] = {
    'Findet Spion To\'gun',
    {'To\'gun, dieser Narr! Wir können hier kaum die Angriffe zurückhalten und er geht wieder hinein um Informationen zu sammeln und die anderen Spione zu retten!|n|nIch weiß nicht, ob ich ihn umarmen oder töten soll!|n|nDer Schattenrat muss uns mithilfe von Magie ausfindig gemacht haben, denn all unsere Spionen mussten hastig von dort fliehen. Die meisten von uns haben es nicht geschafft.|n|nBitte, wenn Ihr mutig genug seid, um das Schattenlabyrinth zu betreten, könntet Ihr dann nach To\'gun Ausschau halten? Er ist schon eine ganze Weile fort, und ich befürchte das Schlimmste.', },
    {'Findet Spion To\'gun im Schattenlabyrinth von Auchindoun.', },
  },
  [10179] = {
    'Der Hüter von Kirin\'Var',
    {'Als klar wurde, dass unsere Expedition ohne Hoffnung auf Rückkehr nach Azeroth in der Scherbenwelt gefangen war, reisten die Kirin Tor zu den Ebenen von Farahlon und erbauten Kirin\'Var. Ich habe die Verwaltung des Dorfs Hüter Dierwert übertragen, aber als Kael\'thas und seine Streitkräfte mich hier im Violetten Turm einsperrten, ist mein Kontakt zu ihm abgebrochen.|n|nSucht ihn in Kirin\'Var und helft ihm, wo Ihr nur könnt, $N. Ich bin sicher, dass er seit dem Angriff alle Hände voll zu tun hat.', },
    {'Sprecht mit Hüter Dierwert in Kirin\'Var im Nethersturm.', },
  },
  [10180] = {
    'Kann es einfach nicht lassen',
    {'Ich habe versucht, Isfar davon zu überzeugen, hier in den sicheren Mauern von Shattrath zu bleiben, aber er wollte nicht auf mich hören. Stattdessen hat er sich entschlossen, wieder auf eigene Faust nach Auchindoun zu gehen.|n|nEr hatte zwar das Glück, den Sethekkhallen einmal zu entkommen, aber wenn sie ihn erwischen wird es kein zweites Mal geben.|n|nIch bewundere seine Entschlossenheit, seine Schwester zu befreien, aber ohne Hilfe wird er es nicht schaffen.|n|nFindet Isfar und sprecht mit ihm, $N. Wenn Ihr ihn nicht davon überzeugen könnt, zurückzukommen, könntet Ihr ihm dann vielleicht helfen Lakka zu retten?', },
    {'Sprecht mit Isfar in den Sethekkhallen in Auchindoun.', },
  },
  [10182] = {
    'Kampfmagier Dathric',
    {'Das Schwert ist von außergewöhnlicher Qualität, fein geschmiedet und perfekt für einen Kampfmagier ausbalanciert. Auf dem Knauf der Waffe sind das Siegel der Kirin Tor und der Name "Dathric" eingraviert.|n|nWährend Ihr die Waffe in den Händen hin und her dreht, bemerkt Ihr, dass etwas mit dem Schwert nicht stimmt. Es fühlt sich an, als wäre es zwischen zwei Welten hin- und hergerissen. Könnte dies der Gegenstand sein, der Kampfmagier Dathrics Geist an diese Welt bindet?|n|nVielleicht zerbricht das Band, wenn Ihr es an seinen angestammten Platz zurückbringt, und befreit Dathrics Geist endgültig.', },
    {'Sucht die Wohnung von Kampfmagier Dathric in der Zaubergasse und bringt die Klinge zurück in sein Waffenregal. Sprecht danach mit Hüter Dierwert in Kirin\'Var.', },
  },
  [10183] = {
    'Auf nach Area 52',
    {'Ich studiere hier draußen den Nether - die astralen Strömungen und so weiter. Dies ist ein idealer Platz, weit weg von den Lichtern und dem Getöse der Stadt. Wenn ich diesen Schrott doch nur am Laufen halten könnte!|n|nHey, wisst Ihr, wenn Ihr nach Arbeit sucht, solltet Ihr nach Area 52 gehen! Das liegt gleich den Pfad hoch und bei der Weggabelung rechts.|n|nWarum bringt Ihr nicht einfach meine neusten Forschungsnotizen zu Raketenchef Doppeldecker? Ich bin sicher, er hat genug Arbeit für Euch, wegen des Raketenschiffs X-52 und so.', },
    {'Bringt die Notizen des Netheorologen zu Raketenchef Doppeldecker in Area 52 im Nethersturm.', },
  },
  [10184] = {
    'Bösartige Überbleibsel',
    {'Die meisten Geister im Dorf sind nicht mehr als blasse Überbleibsel der Magier der Kirin Tor, die sie einst waren. Sie erinnern sich nicht mehr an ihr früheres Ich und streunen blind vor Wut um die Ruinen herum.|n|nDas war jedoch nicht immer so. Direkt nach dem Angriff waren die Geister zwar rastlos, aber nicht bösartig. Mit der Zeit sind sie jedoch immer aggressiver geworden. Ich traue mich nicht, in den südlichen Teil des Dorfs zu gehen, denn sie machen nicht einmal vor mir Halt. Beruhigt sie und lasst uns hoffen, dass Ihr Ärger dann verfliegt.', },
    {'Hüter Dierwert in Kirin\'Var möchte, dass Ihr 20 abtrünnige Geister auf dem Ratsplatz tötet.', },
  },
  [10185] = {
    'Schlimmer als der Tod',
    {'Nachdem die Blutelfen Kirin\'Var dem Erdboden gleichgemacht hatten, haben sie mit dem Bau eines großen Gebäudes im Nordwesten begonnen. Ohne die Kräfte des Erzmagiers können wir nicht genau sagen, was dort vor sich geht.|n|nEines ist jedoch klar. Die Anwesenheit der Blutelfen hat eine Flut von gefräßigen Manaelementaren entfesselt. Sie scheinen von den Ruinen der Zaubergasse angelockt zu werden und verursachen noch weitere Zerstörung... Wir können das nicht weiter zulassen.', },
    {'Tötet 10 Magiertöter und 10 Manasucher und kehrt zu Hüter Dierwert in Kirin\'Var zurück.', },
  },
  [10186] = {
    'Ihr seid eingestellt!',
    {'Lasst mich der Erste sein, der Euch an Bord willkommen heißt, Juniortechniker dritten Grades $N!|n|nWir bauen hier draußen mein Meisterwerk - die X-52 Netherrakete!|n|nDoch zuerst müssen wir alle Teile und den Treibstoff für sie besorgen. Und da kommt Ihr ins Spiel.|n|nZuerst brauche ich Kristalle, VIELE Kristalle, für die astrallithische Antriebsmatrix. Die Draenei hatten so viele, dass sie ihnen schon zu den Ohren herauswuchsen!|n|nBegebt Euch also zu den Ruinen von Enkaat und sammelt ein paar für mich! Und kümmert Euch nicht um die Draeneigeister.', },
    {'Sammelt 10 Astrallithiummatrixkristalle und kehrt dann zu Raketenchef Doppeldecker in Area 52 im Nethersturm zurück.', },
  },
  [10187] = {
    'Eine Nachricht für den Erzmagier',
    {'Auch wenn es hier sehr ungemütlich ist, muntert es uns ein wenig auf, dass der Erzmagier die Misere des Dorfs nicht vergessen hat.|n|n<Der Hüter schaut zum Turm hinauf.>|n|nEs ist lächerlich, oder? Manchmal scheint es, als trenne uns nur eine Wand aus einfachem Stein. Wie leicht vergisst man die Wand aus Magie.|n|nWenn Ihr so nett wärt, erklimmt den Turm und sagt Erzmagier Vargoth, dass wir Fortschritte im Dorf machen und bald einen Weg finden werden, um die Manakreaturen fernzuhalten.', },
    {'Sprecht mit Erzmagier Vargoth im Violetten Turm im Nethersturm.', },
  },
  [10188] = {
    'Das Siegel von Krasus',
    {'Bevor wir uns vor so vielen Jahren von Azeroth aus aufmachten, haben die Kirin Tor unserer Expedition ein mächtiges Artefakt anvertraut, das Siegel von Krasus. Es hat uns im Kampf gegen die Orcs große Dienste erwiesen und könnte eine wichtige Rolle beim Brechen des Zaubers, der mich gefangen hält, spielen.|n|nAls Kael\'thas mich jedoch meiner Besitztümer beraubt hat, gab er das Siegel an Zauberbinderin Maryana, die mit der Garnison zurückblieb. Hätte er gewusst, was er in seinem Besitz hatte, hätte er es nicht so einfach weggegeben.', },
    nil,
  },
  [10189] = {
    'Manaschmiede B\'naar',
    {'Vielleicht sind Euch Kaels Manaschmieden auf dem Weg hierher aufgefallen. Das sind diese großen violetten Gebäude, die Energie aus dem Himmel saugen.|n|nWir wurden von den Sha\'tar hierher geschickt, um sie zu erkunden. Ihr könnt uns dabei helfen, indem Ihr eine Stammrolle von dort besorgt. Wenn wir eine Vorstellung davon hätten, wer dort als was arbeitet, wäre uns über alle Maßen geholfen.|n|nWir glauben, dass Hauptmann Arathyn, der eine Ballistentruppe direkt außerhalb der Manaschmiede B\'naar leitet, eine solche Rolle besitzen könnte. Holt sie für uns.', },
    {'Spionagemeister Thalodien in Area 52 möchte, dass Ihr zum Rand der Manaschmiede B\'naar geht und die Stammrolle von B\'naar von Hauptmann Arathyn besorgt.|n|nDas Abschließen von Aufgaben für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10190] = {
    'Batterien aufladen',
    {'Ich habe die wichtige Aufgabe, die Maschinerie in diesen Ruinen zu sammeln, aber ich habe ein paar Probleme damit, alle meine Bots am Laufen zu halten.|n|nDie Phasenjäger - diese wurmähnlichen Dinger - stecken voller Energie! Man kann sie überall finden, wie sie aus dem Nether herausströmen.|n|nFüllt die Batterie mit diesem Ladeblaster, indem Ihr ihn bei einem Phasenjäger benutzt, wenn er sehr schwach ist, und ihm dann die restliche Energie entzieht.', },
    {'Benutzt den Batterieladeblaster bei genügend Phasenjägern, um den Batterieladestatus auf 10 zu bringen. Bringt die Batterie danach zu Bot-Spezialistin Alley in den Ruinen von Enkaat im Nethersturm zurück.', },
  },
  [10191] = {
    'Nummer V lebt!',
    {'Grüße, $R. Ich bin aufgeladen und voll einsatzfähig!|n|nIn den Ruinen gibt es ein paar zerbrechliche Draeneimaschinen, die ich wieder beschaffen muss. Ich habe sehr edle Servos in den Stellgliedern meiner Handgelenke und bin mit den neusten verbrennungspneumatischen Beulensaugern ausgestattet. Die Maschinen mit der nötigen Sorgfalt zu behandeln ist also kein Problem für mich.|n|nLeider werden die Geister, die in den Ruinen spuken, mich sehr wahrscheinlich angreifen, daher brauche ich Euch und Eure Freunde als Beschützer.', },
    {'Begleitet Maxx E. Million Nr. V durch die Ruinen von Enkaat und wieder in Sicherheit. Sprecht dann mit Bot-Spezialistin Alley außerhalb der Ruinen von Enkaat im Nethersturm.', },
  },
  [10192] = {
    'Krasus\' Kompendium',
    {'Die Kirin Tor haben unserer Expedition einen weiteren Gegenstand aus Krasus\' Besitz mitgegeben. Es handelt sich dabei um sein Zauberbuch, das Krasus\' Kompendium genannt wird. Da es alle Zauber enthält, die Krasus beherrschte, war es uns eine unersetzliche Hilfe im Krieg.|n|nBevor Kael\'thas und seine Truppen Kirin\'Var besetzt haben, wurde mir das Buch von einem rebellischen Schüler, der begierig darauf war, die Nekromantie zu erlernen, gestohlen. Der Lehrling und seine Anhänger haben sich aufgeteilt und das Buch heimlich studiert, wobei sie sich in ihren Häusern im Süden der Stadt eingeschlossen haben.', },
    nil,
  },
  [10193] = {
    'Hochrangige Ziele',
    {'Von den Informationen aus der Stammrolle wissen wir nun, dass die geistigen Führer der Manaschmieden die Warpmeister und Warpingenieure sind. Sie überwachen die Gewinnung der so genannten "Warpenergie" in den Manaschmieden und kümmern sich um ihre Lieferung an entfernte Orte über ein unterirdisches Rohrsystem.|n|nDie einzigen weiteren Spezialisten in dieser Gegend sind die Geologen. Alle anderen sind entweder Teil des Militärs oder Magister - beide sehr leicht zu ersetzen.|n|nGeht dort hinein und tötet Kaels Spezialisten. Das wird ihn am meisten treffen.', },
    {'Spionagemeister Thalodien in Area 52 möchte, dass Ihr in die Manaschmiede B\'naar geht und 2 Warpmeister des Sonnenzorns, 6 Warpingenieure des Sonnenzorns und 8 Geologen des Sonnenzorns tötet.|n|nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10194] = {
    'Heimlicher Flug',
    {'Während Ihr weg wart, haben meine Männer eine weitere Manaschmiede entdeckt. Sie befindet sich östlich von hier und ist als Manaschmiede Coruu bekannt.|n|nZwei meiner besten Spione haben einen geheimen Landeplatz außerhalb der Manaschmiede eingerichtet. Ihr sollt ihnen helfen, Kaels Truppen zu unterwandern und so viele Informationen wie möglich zu sammeln.|n|nSprecht mit Veronia außerhalb der Stadtmauer. Sie hat einen Windreiter vorbereitet, der Euch zur Manaschmiede Coruu bringen wird. Wenn Ihr dort seid, meldet Euch bei Caldis Morgenhell. Er wird Euch mit Eurer Mission vertraut machen.', },
    {'Sprecht mit Veronia außerhalb von Area 52 und fliegt zur Manaschmiede Coruu.|n|nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10195] = {
    'Söldner sieht, Söldner handelt',
    {'Seit Ihr den ersten Stapel Feder gebracht und Bertelms Hut fertiggestellt habt, wollen alle anderen Söldner auch einen haben, darunter auch Thander. Ich habe ihnen gesagt, dass ich mich gleich darum kümmern werde, aber ich werde mehr Arakkoafedern dafür brauchen.|n|nWenn Ihr auf Euren Abenteuern in den Wäldern noch mehr davon finden solltet, nehme ich sie Euch gerne ab.', },
    {'Bringt 30 Arakkoafedern zu Ros\'eleth in Allerias Feste.', },
  },
  [10196] = {
    'Mehr Arakkoafedern',
    {'Ich habe erste Erfolge darin, die Arakkoageister näher zu mir zu locken, aber sie sind immer noch sehr schüchtern. Vielleicht trauen sie sich näher, wenn ich meine Verkleidung verbessere.|n|nDazu benötige ich jedoch mehr Arakkoafedern wie die, die Ihr mir bereits gebracht habt. Wenn Ihr noch ein paar Federn bekommen könntet, würde ich sie Euch gerne abnehmen.', },
    {'Bringt 30 Arakkoafedern zu Malukaz in der Steinbrecherfeste.', },
  },
  [10197] = {
    'Eine überzeugende Verkleidung',
    {'Die Reihen von Kaels Armee zu unterwandern wird keine leichte Aufgabe. Mit meinen geringen Künsten der Illusion könnte ich einen von uns wie einen Anhänger Kaels aussehen lassen, aber es gibt einige Details in ihrer Uniform, die ich nicht nachbilden kann.|n|nBringt mir ein Set ihrer Roben, ein Paar ihrer Handschuhe und ein Gardistenmedaillon des Sonnenzorns. Das wird die Ergebnisse meiner Magie überzeugender machen. Sie tragen alle das gleiche, also solltet Ihr keine Probleme haben, diese Gegenstände zu finden.', },
    {'Bringt ein Set Roben des Sonnenzorns, ein Paar Handschuhe des Sonnenzorns und ein Gardistenmedaillon des Sonnenzorns zu Caledis Morgenhell bei der Manaschmiede Coruu im Nethersturm.|n|nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10198] = {
    'Informationen gesammelt',
    {'Ich habe aus den Teilen, die Ihr mir besorgt habt, eine Uniform hergestellt. Sie ist magisch verbessert, um die Illusion perfekt zu machen.|n|nWir haben beobachtet, wie Kommandant Morgenschmied vor ein paar Minuten hineingegangen ist, um Arkanist Ardonis zu treffen. Er hatte sein gesamtes Gefolge an Wachen bei sich, daher ist das, was sie zu besprechen haben, sicher von größter Wichtigkeit. Versucht, etwas darüber herauszufinden.|n|nAch, das hätte ich fast vergessen. Haltet Euch von den arkanen Golems fern, die in der Manaschmiede patrouillieren. Sie werden Eure Illusion mühelos durchschauen.', },
    nil,
  },
  [10199] = {
    'Der kleine Extrakick',
    {'So, nun fehlt mir noch die eine Zutat, die meinem Gebräu den entscheidenden kleinen Kick geben sollte, den wir brauchen.|n|nDer Stich der Netherrochen, die sich in der Nähe der Schieferhautschinder herumtreiben, ist ganz schön heftig. Bringt mir ein paar ihrer Stachel, damit ich das Gift aus ihnen gewinnen kann.|n|nIch bin mir sicher, dass die Ergebnisse explosiv sind!', },
    {'Besorgt 5 Netherrochenstachel und bringt sie zu Stiefels in Area 52 im Nethersturm.', },
  },
  [10200] = {
    'Rückkehr zu Thalodien',
    {'Es wäre besser, wenn diese Information so schnell wie möglich zu Thalodien gelangen würde. Ich bleibe hier und verwische unsere Spuren.|n|nEs wäre alles andere als gut, wenn Kael\'thas herausfinden würde, was wir hier getan haben. Geheime Informationen sind immer am besten, wenn der Feind nicht weiß, dass man sie hat.', },
    {'Kehrt zu Spionagemeister Thalodien in Area 52 im Nethersturm zurück.', },
  },
  [10201] = {
    'Der Moment der Wahrheit',
    {'Das Öl ist endlich für einen ersten Test bereit. Es scheint dickflüssig genug zu sein, um als hochwertiges Waffenöl zu dienen.|n|nDer einzige Weg, dies herauszufinden ist, einen Profi zu fragen. Seht Ihr Grek da drüben bei den Fahndungsanschlägen? Ich weiß, er ist nicht gerade ein Poet, aber mit Waffen kennt sich der Orc aus!|n|nBringt ihm eine Probe des Öl und bittet ihn, es an seiner Waffe auszuprobieren. Wenn er das getan hat, berichtet mir von seiner Meinung.', },
    {'Geht zu Grek und bittet ihn, das Öl an seiner Waffe auszuprobieren. Bringt das Ergebnis zu Rakoria, wenn er fertig ist.', },
  },
  [10202] = {
    'Ein Abtrünniger',
    {'Wir wurden vor Kurzem von einem Magister des Sonnenzorns kontaktiert, der uns beitreten möchte und schwört, dass er uns Informationen geben kann, die wir dringend benötigen. Wir haben uns mit unseren Informanten in Verbindung gesetzt, um zu überprüfen, ob es sich bei ihm um einen Doppelagenten handeln könnte, und er scheint sauber zu sein.|n|nEr befindet sich in der Manaschmiede Ara, was die Kommunikation etwas erschwert. Geht zu ihm und hört Euch an, was er zu sagen hat. Wenn er nur halb so hilfreich ist, wie er behauptet, können wir ihn sicher gut einsetzen.', },
    {'Geht zur Manaschmiede Ara und sprecht mit Magister Theledorn.|n|nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10203] = {
    'Unschätzbare Ausrüstung beamen',
    {'Habt Ihr den Riss gesehen, der mitten durch Area 52 verläuft? Wir waren das! <Grinsen>|n|nIm Riss befinden sich allerlei Schätze für die X-52 Netherrakete! Das einzige Problem ist nur, dass wir nicht genug Ausrüstung haben.|n|nBis die Brennende Legion dort aufgetaucht ist, führten wir eine Operation in den Ruinen von Arklon aus. Ich möchte, dass Ihr diesen ultrastarken Dekonsolidierungsstrahler zu den Ruinen bringt. Benutzt ihn, um unsere Ausrüstung zum leitenden Ingenieur Zischeldruck im Riss zu beamen.|n|nJuniortechniker dritten Grades $N, dies ist Eure Chance auf eine Beförderung. Vergeigt sie nicht!', },
    {'Benutzt den ultrastarken Dekonsolidierungsstrahler, um den Hyperdreh-Grab-o-Matik, die servopneumatische Baggerklaue, den multispektralen Geländeabtaster und den großen Wagen voller Sprengstoff zurück nach Area 52 zu beamen. Meldet Euch dann beim leitenden Ingenieur Zischeldruck beim östlichen Ende des Risses in Area 52 im Nethersturm.', },
  },
  [10204] = {
    'Blutjuwelenkristalle',
    {'Kaels Magister haben den Gebrauch von Manakristallen so weit perfektioniert, dass sie innerhalb von Sekunden große Mengen von Energie aufnehmen können.|n|nDas tun sie, indem sie kleinere Kristallsplitter von Blutjuwelen an größeren und vollen Kristallen aufladen.|n|nGeht zur Manaschmiede B\'naar und besorgt einen dieser Splitter von einem Magister des Sonnenzorns und benutzt ihn, um Energie von einem größeren Kristall aufzunehmen.|n|nKehrt zu mir zurück, damit ich die Wirkung der Aura untersuchen kann. Keine Sorge, Nebenwirkungen sollten nur temporär sein.', },
    {'Magistrix Larynna möchte, dass Ihr zur Manaschmiede B\'naar geht und einen Blutjuwelensplitter von einem Magister des Sonnenzorns besorgt. Benutzt den Splitter in der Nähe von größeren Blutjuwelenkristallen und kehrt zu ihr in Area 52 zurück.|n|nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10205] = {
    'Sphärenräuber Nesaad',
    {'Sphärenräuber Nesaad muss erledigt werden! Ich habe keine Ahnung, wie er meinen Angriff überleben konnte, aber er darf seine Taten dort auf keinen Fall fortführen.|n|nGeht zurück und vernichtet Nesaad. Er hat ein kleines Lager des Astraleums im südwestlichen Teil des Hügels.|n|nVersagt nicht, wie ich es tat, $N.', },
    {'Tötet Sphärenräuber Nesaad und kehrt dann zu Netherpirscher Khay\'ji in Area 52 im Nethersturm zurück.', },
  },
  [10206] = {
    'Wählt Eure Rolle',
    {'Diese astralen Hampelmänner sind genauso opportunistisch wie wir, das muss man ihnen lassen. Aber niemand, und ich meine NIEMAND, wagt sich auf das Gebiet von B.U.M.M.!|n|nDer Hügel im Süden gehört uns!|n|nWenn wir die X-52 Netherrakete fertigstellen wollen, brauchen wir alle neuen Technologien, die wir in die Finger bekommen können. Und da die Astralen von uns stehlen, ist es nur gerecht, wenn wir es ihnen mit gleicher Münze heimzahlen.|n|nWarum geht Ihr nicht zum Hügel und schaut, ob Ihr ihnen etwas von ihrer Technologie vor der Nase wegschnappen könnt.', },
    {'Sammelt 10 Stück Astraltechnologie und bringt sie zu Papa Mauschel in Area 52 im Nethersturm.', },
  },
  [10207] = {
    'Vorposten: Häschersturz',
    {'Eure Fähigkeiten in der Schlacht sind dem obersten Kommando aufgefallen, $C. Sie wollen Euch an die Front zu Stümmelfausts Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...|n|nGeht etwa 200 Schritte nach Osten und biegt bei der hervorragenden Landmasse nach Süden ab. Ihr findet den Häschersturz dort, wo einst ein alter Bauernhof stand. Wenn Ihr angekommen seid, meldet euch bei Vorpostenkommandant To\'arch.|n|nUnd jetzt weggetreten!', },
    {'Meldet Euch bei Vorpostenkommandant To\'arch im Häschersturz.', },
  },
  [10208] = {
    'Die Verstärkung abschneiden',
    {'Direkt im Osten liegt die Front der Legion. Entlang der Front befinden sich die höllischen Portale und Tore, mit deren Hilfe Verstärkung auf die Höllenfeuerhalbinsel und in die ganze Scherbenwelt gebracht wird. Wir müssen diese Portale zerstören!|n|nNehmt diese Zünder. Sie wurden in Area 52 hergestellt und benutzten die eigene Macht der Dämonen als Sprengstoff! Besiegt die Legion beim Portal Xilus und Portal Kruul und haltet nach dämonischen Runensteinen Ausschau. Benutzt den Zünder, um die vier Steine in den Portalen zu sprengen, sobald Ihr genug Steine beisammen habt... und dann genießt das Feuerwerk! Kehrt zu mir zurück, wenn Ihr Eure Aufgabe erfüllt habt.', },
    {'Besiegt die Feinde um Portal Xilus und Portal Kruul herum, um dämonische Runensteine zu sammeln.|n|nBenutzt To\'archs Zünder in Portal Xilus und Portal Kruul.|n|nKehrt danach mit To\'archs Zünder zu To\'arch im Häschersturz auf der Höllenfeuerhalbinsel zurück.', },
  },
  [10209] = {
    'Beschwörer Kanthins Preis',
    {'Als nächstes müssen wir meinen Vertrauten, Gletscharius, aus den Händen des Blutelfenbeschwörers, der ihn gefangen hält, befreien. Beschwörer Kanthin war einst einer der erfahrensten Magister in der Streitmacht, die Kael\'thas losgeschickt hat, um Kirin\'Var auszulöschen. Es ist ganz normal, dass er meinen Vertrauten als Trophäe haben will.|n|nIch bin mir sicher, dass Kanthin, dumm wie er ist, versucht hat, Gletscharius zu seinem Diener zu machen. Ich habe herausgefunden, dass Kanthin sich jetzt in der Manaschmiede Duro aufhält, falls dies Euch etwas sagt.', },
    nil,
  },
  [10210] = {
    nil,
    {'Willkommen in Shattrath, $C. Dies ist vielleicht der einzige Ort in der Scherbenwelt, in der Ihr so etwas wie Sicherheit empfinden könnt.|n|nEine Gruppe von Naaru, die als Sha\'tar bekannt sind, hat die Dämonen von hier fortgejagt.|n|nWenn Ihr noch nie einen Naaru gesehen habt, solltet Ihr A\'dal auf der Terrasse des Lichts besuchen. Der Anführer der Sha\'tar ist der ehrfurchtgebietendste Anblick, den ich je gesehen habe. Ganz anders, als alles andere in diesem öden Land.', },
    {'Sprecht mit A\'dal, Anführer der Sha\'tar in der Mitte der Terrasse des Lichts.', },
  },
  [10211] = {
    'Stadt des Lichts',
    {'Belästigt A\'dal nicht mit Euren unbedeutenden Fragen, $C. Er ist vielleicht das mächtigste Wesen, das Ihr je zu Gesicht bekommen werdet.|n|nIhr kommt mir nicht bekannt vor. Ich nehme an, Ihr wollt etwas über die Stadt erfahren?|n|nIhr müsst schon entschuldigen, dass ich selbst keine Führungen mache, aber ich muss einige Pläne mit A\'dal besprechen. Vielleicht wärt Ihr ja mit einem herbeigerufenen Diener an meiner statt zufrieden? Ausgezeichnet!', },
    {'Folgt Khadgars Diener und hört Euch an, was er zu erzählen hat. Kehrt nach dieser Aufgabe zu Khadgar zurück.', },
  },
  [10212] = {
    'Held der Mag\'har',
    {'Kehrt zu Großmutter Geyah in Garadar in Nagrand zurück.', },
    {'Kehrt zu Großmutter Geyah in Garadar in Nagrand zurück.', },
  },
  [10213] = {
    'Untersuchung der Absturzstelle',
    {'Als ich verwundet in der Wüste lag, habe ich gesehen, wie ein goblinscher Zeppelin abgestürzt ist. Er kam im Nordwesten runter, hinter dem Expeditionsrüstlager.|n|nDer Zeppelin hat gebrannt. Schreiende, brennende Goblins fielen wie Bomben vom Himmel. Ich hatte natürlich sehr große Schmerzen und viel Blut verloren. Vielleicht habe ich mir das alles auch nur eingebildet.|n|nWenn Ihr irgendwelche Überlebenden finden solltet, bietet ihnen eine Zuflucht hier im Rückenbrecherposten an.', },
    {'Durchsucht die Absturzstelle nach Überlebenden.', },
  },
  [10214] = {
    'Bringt diese Mine zum Beben!',
    {'Die Mine wurde von diesem Gan\'argpack überrannt, und zu allem Übel sind die Peons der Meinung, dass jetzt die richtige Zeit für ein Schläfchen ist! Ich weiß nicht, wie sie bei all dem Lärm aus der Mine schlafen können, aber das ist mein geringstes Problem.|n|nWenn wir dieses Gan\'arggesindel nicht bald loswerden, wird Thrallmars Nachschub an Kupfer und anderen Materialien abgeschnitten. Ich habe schon Wachkommandant Krunk um Hilfe gebeten, aber er sagt, dass er keine Männer schicken kann, solange die Stadt angegriffen wird. Könnt Ihr mir helfen?', },
    {'Tötet 15 Pioniere der Gan\'arg und kehrt dann zu Großknecht Razelcraz zurück.', },
  },
  [10216] = {
    'Sicherheit geht vor',
    {'Shaffars Astrale haben uns ganz aus der Managruft ausgeschlossen. Zum Glück habe ich einen Plan. Auch wenn wir nicht durch die Eingangstür können, bin ich mir sicher, dass es innen viele Transporter gibt.|n|nIch möchte, dass Ihr zuerst den Weg für meine Gruppe freiräumt und dann einen der Transporter aktiviert, damit wir hineinteleportieren können.|n|nAktiviert den Transporter in der Kammer genau vor Shaffars Kammern, wenn Ihr den Weg freigemacht habt. Keine Sorge, ich werde Euch dafür entlohnen...', },
    {'Konstrukteur Morphalius möchte, dass Ihr 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder tötet.|n|nWenn Ihr damit fertig seid, sucht den astralen Transporter in der Kammer vor Shaffars Kammer und aktiviert ihn.', },
  },
  [10217] = {
    'Fossiler Kraftstoff',
    {'Mein Schredder hat keinen Treibstoff mehr!', },
    nil,
  },
  [10218] = {
    'Jemandes Arbeit zahlt sich aus',
    {'Wen habt Ihr erwartet?! Dieser Idiot Morphalius wurde entpriorisiert. Jetzt bin ich hier, um sein Chaos aufzuräumen. Alles, was ich von Euch will, ist, dass Ihr mir den Rücken freihaltet, während ich Shaffars Astralsammler durchgehe und ihnen alles entnehme, was sie gesammelt haben. Wenn ich meinen Auftrag erfolgreich abschließe, wird Haramad selbst Euch belohnen!|n|nWas sagt Ihr? Begleitet mich durch die Managruft und sammelt ein paar unglaubliche Schätze! Die meiste Arbeit habt Ihr ohnehin schon erledigt! Hinter uns ist nichts mehr am Leben, oder?', },
    {'Begleitet Kryoingenieur Sha\'heen sicher durch die Managruft, damit er die Astralmaterie aus Shaffars Astralsammlern entnehmen kann.|n|nMeldet Euch bei Nexusprinz Haramad außerhalb der Managruft beim Lager des Konsortiums, wenn Ihr erfolgreich wart.', },
  },
  [10219] = {
    'Gassi gehen',
    nil,
    nil,
  },
  [10220] = {
    'Bringt sie zum Zuhören',
    {'Ich wurde hierher geschickt, Kontakt zu den unerschütterlichen Geistern herzustellen. Diese einst stolzen Soldaten der Allianz wurden vor langer Zeit besiegt, und nun spuken ihre Geister in den Ruinen im Westen.|n|nWenn sie sich uns anschließen würden, hätten wir einen mächtigen Verbündeten. Stellt Euch nur vor, eine Armee von untoten Kriegern, die sich unserem Feind entgegenstellt. Aber diese Untoten sind blind vor Hass und wollen sich meinen Vorschlag nicht anhören.|n|nVielleicht kann man sie zwingen, sich uns anzuschließen.', },
    {'Mordiba möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 8 unerschütterliche Krieger und 6 unerschütterliche Zauberer beim Expeditionsrüstlager westlich des Rückenbrechergrats tötet.', },
  },
  [10221] = {
    'Dr. Bumm!',
    {'$N, mein früherer Schützling, Sparky Überschub, hat sich geweigert, während seiner Arbeit hier seinen Helm zu tragen und hat sich in den berüchtigten Dr. Bumm verwandelt!|n|nEr hat sich mit einem Großteil unserer Pionierausrüstung nach Nordosten aufgemacht! Seitdem sind er und seine Bummbots eine große Bedrohung für Area 52!|n|nIch möchte, dass Ihr zu seinem Lager außerhalb der Stadt geht und ihm ein Ende macht! Benutzt diese Bummbomben um ihn auszulöschen.|n|nUnd passt auf, dass Ihr ihm oder seinen Bummbots nicht zu nahe kommt!', },
    {'Tötet Dr. Bumm und kehrt dann mit den guten Nachrichten zu dem leitenden Ingenieur Zischeldruck in Area 52 im Nethersturm zurück.', },
  },
  [10222] = {
    'Die Garnison des Sonnenzornpostens',
    {'Nachdem Prinz Kael\'thas\' Streitkräfte das Dorf zerstört und den Erzmagier im Turm eingesperrt hatten, haben sie sich zum Sonnenzornposten im Nordosten zurückgezogen. Die gleichen Männer, die unser Dorf zerstört und unsere Freunde getötet haben, stoßen nun auf ihren \'unglaublichen Sieg\' an, während wir unsere Gefallenen nicht rächen können.|n|nWir dürfen diese Verbrechen nicht ungestraft lassen! Seid unser Instrument der Rache, $N. Geht zum Sonnenzornposten und fordert das Leben der Verantwortlichen für dieses Verbrechen ein!', },
    {'Hüter Dierwert in Kirin\'Var möchte, dass Ihr 10 Bogenschützen des Sonnenzorns tötet.', },
  },
  [10223] = {
    'Nieder mit Daellis',
    {'Den Blutelf, der den Angriff geführt hat, werde ich nie vergessen. Er trug einen Wappenrock mit einem Ding, was ich noch nie zuvor gesehen habe, über einer roten Rüstung.|n|nEr war wild und erbarmungslos, und kämpfte an der Front, wo man kaum einen anderen Blutelfenoffizier je zu Gesicht bekommt. Er war an diesem Tag für den Tod vieler Kirin Tor verantwortlich, aber er blieb nicht lange im Sonnenzornposten. Kael\'thas hat ihn zur Manaschmiede Duro beordert, um bei ihrem Versuch, das Gebiet zu kontrollieren, zu helfen. Findet ihn, $N, und bringt seinen Bogen für immer zum Schweigen.', },
    {'Hüter Dierwert in Kirin\'Var möchte, dass Ihr Meister Daellis Morgenschlag tötet.', },
  },
  [10224] = {
    'Essenzen für die Motoren',
    {'Als Chefingenieur der X-52 ist es meine Pflicht dafür zu sorgen, dass die Hauptmotoren der Netherrakete tiptop in Schuss sind.|n|nUnglücklicherweise habe ich sie noch nicht gebaut.|n|n$C, ich bin hier in einer Notlage! Ich habe fast alle Teile. Ich brauche nur noch einen Antriebskern.|n|nZum Glück bin ich der Meinung, dass wir die Essenz der Managespenster in der Nähe nutzen können, um die Motoren zu überbrücken.|n|nIhr findet die Managespenster überall bei diesen komischen leuchtenden Gräben im Norden der Insel. Außer hier in Area 52 natürlich.', },
    {'Sammelt 7 Essenzen eines Managespensts und bringt sie zu Chefingenieur Trep bei Area 52 im Nethersturm.', },
  },
  [10225] = {
    'Meldung beim Chefingenieur',
    {'$N! Ich möchte, dass Ihr all diese Astrallithiumkristalle zu Chefingenieur Trep, meinem, äh, Ingenieurschef bringt.|n|nEr sollte wissen, was mit ihnen zu tun ist. Und wenn er es nicht weiß, dann sorgt dafür, dass er es herausfindet.', },
    {'Bringt die Astrallithiummatrixkristalle zu Chefingenieur Trep in Area 52 im Nethersturm.', },
  },
  [10226] = {
    'Elementarenergieextraktor',
    {'Verdammt, das hat nicht geklappt.|n|nOk, ich habe eine andere Idee. Ich habe Xyrol einen Elementarenergieextraktor herstellen lassen. Ich weiß nicht genau, was man mit dieser Energie anfangen kann, aber ich werde schon einen Verwendungszweck für sie finden.|n|nDie zerrissenen Rumpler und Sphärenentartungen auf dem Felsvorsprung der Schwindenden Weite im Süden haben genau das, was wir für die Motoren brauchen!|n|nDer Extraktor wird ihre Energie in eine feste Form bringen, die Ihr aufsammeln könnt, nachdem Ihr sie besiegt habt.', },
    {'Extrahiert 5 Einheiten Elementarenergie und bringt sie zu Chefingenieur Trep in Area 52 im Nethersturm.', },
  },
  [10227] = {
    'Ich sehe tote Draenei',
    {'Ich sehe tote Draenei. Sie sind überall.|n|nPah, niemand glaubt mir, weil ich ein Kind bin. Nichtmal meine Mama glaubt mir.|n|n<Ha\'lei zeigt auf Ramdor.>|n|nEr glaubt mir. Er sieht sie auch. Und er regt sich darüber auf!|n|nIrgendwie ist es lustig. Ich sehe Geister und die Leute lächeln mich nur an und tätscheln mir den Kopf, um mich zu beruhigen. Ramdor sieht Geister und sie halten ihn für verrückt. Ich hoffe echt, dass ich nie erwachsen werde!|n|nVielleicht solltet Ihr erst mit Ramdor reden, bevor Ihr da hinein geht. Er war einst ein Totenpriester.', },
    {'Sprecht mit Ramdor dem Wahnsinnigen auf dem Knochenhaufen außerhalb der Auchenaikrypta.', },
  },
  [10228] = {
    nil,
    {'Ich bin der Meinung, dass die Toten, um die wir uns seit den letzten 500 Jahren gekümmert haben, in Ruhe gelassen werden sollten. Aber Maladaar hat andere Pläne. Er hat sich in die Krypta des Gedenkens zurückgezogen, um seine Experimente zu beginnen... Nekromantie.|n|nIch hoffe, Ihr hattet nicht vor, dorthin zu gehen... nicht bevor Ihr mir geholfen habt, diese verdammten Geister loszuwerden. Ich weiß, wo sie ihre Schätze aufbewahren, $R. Jetzt habe ich Eure Aufmerksamkeit, was?|n|nBringt mir das Buch der Toten, das sich im Besitz des Aldors Ezekiel von Shattrath befindet.', },
    {'Sprecht mit Ezekiel von Shattrath in Shattrath.', },
  },
  [10229] = {
    'Den Folianten entziffern',
    {'Dieser Foliant scheint eine Art Geschichtsbuch zu sein, das in einer Geheimschrift der Allianz geschrieben wurde. Althen der Historiker im Rückenbrecherposten hat die Unerschütterlichen eine Zeit lang studiert. Vielleicht kann er die Geheimschrift der Allianz entziffern und das Buch lesen.', },
    {'Bringt den geheimnisvollen Folianten zu Althen dem Historiker im Rückenbrecherposten.', },
  },
  [10230] = {
    'Das Kampfhorn',
    {'Vielleicht haben wir uns ganz falsch an diese Unerschütterlichen herangewagt.|n|nDieser Foliant sagt, dass das Rüstlager der Allianz vor langer Zeit von den Orcs und den Todesrittern zerstört wurde. Die Unerschütterlichen wurden dort als rachedurstige Geister in einer ewigen Schlacht gegen die Klans der Höllenorcs gefangen.|n|nSie denken nur an Rache. Wir müssen ihnen die Chance geben, ihre meist verhassten Feinde zu besiegen. Kehrt noch einmal in die Ruinen des Rüstlagers zurück und sucht Feldkommandant Thalvos. Er trägt ein Kampfhorn, das die Unerschütterlichen rufen kann. Bringt es mir.', },
    {'Besorgt Euch das Kampfhorn der Unerschütterlichen von Feldkommandant Thalvos und bringt es zu Althen dem Historiker im Rückenbrecherposten.', },
  },
  [10231] = {
    'Welches Buch? Ich sehe kein Buch.',
    {'Ezekiel sagt, dass das Buch gestohlen wurde. Eure einzige Spur führt Euch zu den Grobianen. Schaut nach, ob sie irgendwelche Informationen haben.', },
    {'Ezekiel sagt, dass das Buch gestohlen wurde. Eure einzige Spur führt Euch zu den Grobianen. Schaut nach, ob sie irgendwelche Informationen haben.', },
  },
  [10232] = {
    'Legion in Trümmern',
    {'Die Brennende Legion ist auf unserem Grund im Trümmerfeld, den Pfad hinunter und über die Brücke nach Osten, einmarschiert!|n|nDas könnte ein großes Problem für uns sein! Die Legion in den Ruinen von Arklon und jetzt auch noch hier! Langsam sieht es für uns und das Raketenprojekt hier in Area 52 schlecht aus!|n|n$N, ich möchte, dass Ihr dorthin geht und mit den Dämonen fertigwerdet! Ich würde es ja tun, aber ich bin kein Kämpfer.|n|nJa, das riecht nach Ärger, ich fühle es.', },
    {'Tötet 5 Schicksalsschmiede der Mo\'arg und 15 Ingenieure der Gan\'arg. Kehrt danach zu Papa Mauschel in Area 52 im Nethersturm zurück.', },
  },
  [10233] = {
    'Den Sonnenzornposten anzünden',
    {'Die Garnison des Sonnenzornpostens auszulöschen ist nicht genug, um die Blutelfen davon abzuhalten, ihn erneut zu beziehen. Kael\'thas Anhänger sind eifrig und hartnäckig. Sobald im Sonnenzorn noch ein Stein auf dem anderen steht, ist dies praktisch eine Einladung für sie, zurückzukehren.|n|nNein, der Posten muss völlig zerstört werden. Sorgt dafür, dass ihre Zelte und Artillerie zu Asche zerfallen!|n|n<Der Geist ballt die Fäuste.>|n|nStehlt die Fackeln von den Flammenbewahrern des Sonnenzorns um Eure Aufgabe zu erfüllen, $N.', },
    {'Benutzt eine flammende Fackel, zerstört 4 Sonnenzornballisten und 4 Sonnenzornzelte und kehrt dann zu Zaubererleutnant Morran in Kirin\'Var zurück.', },
  },
  [10234] = {
    'Der Müll eines Dämons',
    {'Ihr seht aus, als wärt Ihr $Gein fähiger junger Mann:eine fähige junge Frau;! Ich habe mich gefragt, ob Ihr mir vielleicht zur Hand gehen könntet.|n|nIm Osten befindet sich das Trümmerfeld, auf dem die Brennende Legion Einzug gehalten hat. Es ist voller Teufelshäscherteile. Dort liegen auch ein paar kleinere Teile herum, um die sie sich nicht zu scheren scheinen.|n|nIch möchte, dass Ihr dorthin geht, und mir ein paar dieser kleineren Teile eines Teufelshäschers besorgt!', },
    {'Sammelt 10 Teile eines Teufelshäschers und bringt sie zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.', },
  },
  [10235] = {
    'Verdammnisklaue die Krallen stutzen',
    {'Wisst Ihr, was sie entmutigen würde? Wenn wir ihren Anführer erlegen!|n|nWie ich gehört habe, klappt das immer. Und wenn sie sehen, dass so $Gein knallharter:eine knallharte:c; $C wie Ihr ihren Anführer erledigt, dann ziehen sie sicher den Schwanz ein und rennen weg!|n|nGeht dorthin zurück und erlegt den Großen, den sie Verdammnisklaue nennen. Ich habe gehört, dass er sich im östlichen Teil den Trümmerfelds unter dem Rohr aufhält.|n|nBringt mir seine Klaue! Vielleicht können wir sie brauchen.', },
    {'Besorgt Euch Verdammnisklaues Hand und bringt sie zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.', },
  },
  [10236] = {
    'Die Scherbenwelt ist doof!',
    {'Ich kann es kaum fassen, dass ich Beutebucht verlassen habe, um in die Scherbenwelt zu kommen. Mein Vetter Quack Lufthans hat mir versprochen, dass ich hier ein Vermögen machen würde, aber stattdessen ist er in seinem Zeppelin auf und davon und hat mich hier zurückgelassen. Nun versuche ich, mir einen sehr bescheidenen Lebensunterhalt mit der Mine zu verdienen.|n|nAber wie soll ich denn überleben, wenn ich dauernd von Höllenebern und Dämonen und Höllenorcs angegriffen werde? Mein Schredder hier ist gestern kaputt gegangen und die Höllenorcs haben meine Ersatzteile gestohlen. Sie haben die Teile in die Große Kluft im Südwesten gebracht und vielleicht dort fallenlassen.', },
    {'Großknecht Razelcraz möchte, dass Ihr ihm 6 Schredderteile besorgt. Kehrt danach zu ihm bei der Mine nordwestlich von Thrallmar zurück.', },
  },
  [10237] = {
    'Warnt Area 52!',
    {'$N, Ihr müsst so schnell wie möglich nach Area 52 zurückkehren! Beeilt Euch!|n|nSagt dem Raketenchef, dass die Brennende Legion hinter uns her ist!', },
    {'Überbringt Raketenchef Doppeldecker in Area 52 die schlechten Nachrichten.', },
  },
  [10238] = {
    'Wie man Goblins zubereitet',
    {'Warum sollten die Höllenorcs denn meine Schredderteile stehlen wollen? Ich hasse sie so. Sie schleichen sich einfach in mein Lager hier und klauen immer meine Sachen. Vor ein paar Tagen haben sie drei meiner Peons gestohlen! Jetzt sind alle anderen Peons abgehauen, weil sie Angst hatten, von den Höllenorcs gefressen zu werden.|n|nIch kann meine Mine ohne Peons nicht betreiben. Wenn Ihr meine gestohlenen Peons retten könntet, kommen die anderen vielleicht auch wieder zurück. Die Höllenorcs haben ihre Lager entlang des Walls im Südwesten.', },
    {'Rettet Manni, Moh und Jakk aus den Lagern der Höllenorcs und bringt sie zu Großknecht Razelcraz bei der Mine nordwestlich von Thrallmar zurück.', },
  },
  [10239] = {
    'Mögliche Energiequelle',
    {'Wir sind nicht die Einzigen, die unter dem Zufluss von Manakreaturen leiden. Auch die Blutelfen sind darüber besorgt, ich weiß jedoch nicht, warum.|n|nWas immer sie da drüben tun mögen, sie scheinen nicht damit aufzuhören. Stattdessen erfinden sie immer neue Methoden, um sie zu töten. Die wirksamste davon beinhaltet eine magische Verteidigung, die von einer Art konzentrierter Energie gespeist wird.|n|nSammelt einige dieser Energiequellen und bringt sie mir. Scheut Euch nicht, die Blutelfen zu töten, wenn sich eine Gelegenheit ergeben sollte.', },
    {'Zaubererleutnant Morran in Kirin\'Var möchte, dass Ihr ihm 10 Energieisolationswürfel von den Blutelfen der Manaschmiede Coruu bringt.', },
  },
  [10240] = {
    'Eine Verteidigung errichten',
    {'Wir sind dabei, eine Verteidigung um das Dorf herum zu errichten, die mit der Energiequelle der Blutelfen gespeist wird. Ich kann nicht garantieren, dass sie funktionieren wird, aber wir müssen es versuchen.|n|nWenn nicht werden die Manakreaturen weiterhin die Geister der gefallenen Kirin Tor verspeisen.|n|nBenutzt dieses Gerät bei den kleinen Runen um die Verteidigung des Dorfes herum, um die Energie dort freizusetzen. Wenn ich das Feld korrekt gewebt habe, sollten wir die Wirkung bemerken, sobald Ihr das Gerät bei jedem Punkt benutzt habt.', },
    {'Benutzt das Gerät zur Aktivierung von Runen bei der östlichen Rune, der nordöstlichen Rune und der westlichen Rune. Die Runen befinden sich entlang der Verteidigung der Zaubergasse und des Ratsplatz von Kirin\'Var. Kehrt zu Zaubererleutnant Morran zurück, wenn Ihr die Aufgabe erfüllt habt.', },
  },
  [10241] = {
    'Ablenkung in der Manaschmiede B\'naar',
    {'Wir wurden von Sha\'tar hierher geschickt, um die Manaschmieden, die Kael\'thas\' Armee hier betreibt, zu untersuchen. Aber die Seher drohen damit, ihre Spionagearbeiten nicht durchzuführen, wenn wir sie nicht militärisch unterstützen.|n|nWir können uns nicht erlauben, dass diese Mission wegen politischen Differenzen den Bach hinunter geht, daher haben wir uns einverstanden erklärt, die Verteidigung der Manaschmiede zu schwächen, damit die Seher ihre Arbeit verrichten können.|n|nBeweist Eure Loyalität gegenüber den Aldor und tötet die Magister und Blutwärter des Sonnenzorns, die die Manaschmiede B\'naar bewachen.', },
    {'Tötet 8 Magister des Sonnenzorns und 8 Blutwärter des Sonnenzorns und kehrt dann zu Exarch Orelis in Area 52 zurück.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Ruf bei den Sehern.', },
  },
  [10242] = {
    'Der Rückenbrechergrat',
    {'$N, meine Ausrüstung hier ist leider nicht für alle Tests, die ich durchführen möchte, geeignet. Mein Kollege Apotheker Albreck im Rückenbrecherposten verfügt jedoch über alle Hilfsmittel, die man dazu braucht.|n|nIch habe eine Blutprobe des Blutenden Auges, die mir ein Agent aus Thrallmar besorgt hat. Bringt diese Probe zu Albreck und erlaubt ihm, sie zu untersuchen.|n|nSprecht mit Schwadronskommandant Brack, um zum Rückenbrecherposten zu kommen. Er befindet sich in der Nähe der Wyvern im Süden.', },
    {'Apothekerin Zelana beim Häschersturz möchte, dass Ihr mit Schwadronskommandant Brack sprecht, um auf einem Wyvern zum Rückenbrecherposten zu fliegen. Bringt die Blutprobe des Blutenden Auges zu Apotheker Albreck im Rückenbrecherposten.', },
  },
  [10243] = {
    'Die Technologie der Naaru',
    {'Die Seher haben eine Stammrolle der Manaschmiede B\'naar in die Hände bekommen und sind nun dabei, gezielt nach Anschlagsopfern zu suchen.|n|nSie haben jedoch eine kleine Information übersehen, die an den Rand der Schriftrolle gekritzelt wurde. Es scheint eine Art Passwort oder Code zu sein, wie sie für den Zugang zu von den Naaru erschaffenen Technologien wie der Exodar oder der Festung der Stürme benutzt werden.|n|nGeht in die Manaschmiede und haltet nach einer Steuerungskonsole Ausschau. Schreibt die Anzeige so gut es geht auf dieser Rolle ab. Wir müssen unseren Verdacht über die Herkunft von Kaels Technologie erhärten.', },
    {'Geht in die Manaschmiede B\'naar und sucht die Steuerungskonsole von B\'naar.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10244] = {
    'Liesmich',
    {'Ihr zerbrecht das Siegel des ziemlich großen Folianten und könnt nicht verstehen, was dort geschrieben steht. Es schein die Sprache der Dämonen zu sein.|n|nIhr könnt jedoch die Bilder erkennen, die ihre eigene Geschichte erzählen.|n|nEs handelt sich eindeutig um eine Bauanleitung für Teufelshäscher, und Ihr wisst ganz sicher, dass Mama Mauschel sich das gerne anschauen würde.', },
    {'Bringt die Bauanleitung für Teufelshäscher zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.', },
  },
  [10245] = {
    'Steuerungsabschrift von B\'naar',
    {'Ihr versucht die Formen abzuschreiben, als sie an Euren Augen vorbeiziehen. Die Ergebnisse sind nicht gerade genau, aber sie sollten genügen, um den Verdacht der Aldor zu bestätigen.', },
    {'Bringt die Steuerungsabschrift von B\'naar zu Anachoret Karja in Area 52 im Nethersturm.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10246] = {
    'Angriff auf Manaschmiede Coruu',
    {'Euer Erfolg in der Manaschmiede B\'naar war sehr bemerkenswert. Ich bin sicher, dass Anachoret Karja Euch bitten wird, Eure Leistung als Nächstes in der Manaschmiede Coruu zu wiederholen.|n|nWir haben erfahren, dass ein besonders wichtiges Regiment von Arkanisten und Forschern des Sonnenzorns dort stationiert wurde. Wir würden sie gerne angreifen. Wenn es Euch gelingt, wird das ein vernichtender Schlag für die Streitkräfte unseres Feindes sein.', },
    {'Reist zur Manaschmiede Coruu und tötet 8 Arkanisten des Sonnenzorns und 5 Forscher des Sonnenzorns. Kehrt zu Exarch Orelis zurück, wenn Ihr Eure Aufgabe erledigt habt.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10247] = {
    'Dr. h. c. tüft. Vomisa',
    {'Am Rand des Dorfes im Osten befinden sich die Versuchsgründe. Unser Spitzenobertüftler, Doktor Vomisa, hat hier ein wenig mit einer Kombination aus Teufelshäschertechnologie, Astraltechnologie und natürlich Goblintechnologie herumgespielt.|n|nDas verdanken wir nicht zuletzt Euren Sammelbemühungen, Juniortechniker dritten Grades $N!|n|nSucht ihn auf! Ich bin mir sicher, dass er einen Weg weiß, wie Area 52 gerettet werden kann.|n|nUnd weil er Euch sicher als Versuchskaninchen einsetzen möchte, würde ich an Eurer Stelle lieber ein paar Freunde mitbringen. Nur für den Fall.', },
    {'Sprecht mit Dr. h. c. tüft. Vomisa in den Versuchsgründen im Nethersturm.', },
  },
  [10248] = {
    'Du, der Roboter',
    {'Dr. h. c. tüft. Vomisa zu Euren Diensten. Hier, nehmt diese Steuerung. Ich möchte, dass Ihr sie aktiviert und meinen neu erfundenen Schrotthäscher X6000 mal ausprobiert.|n|nBleibt in der Nähe! Die Steuerung ist an meine Konsole hier gebunden, wenn Ihr zu weit weggeht, wird der Roboter aufhören zu funktionieren.|n|nProbiert alles aus... Ich schaue zu und stelle dann die Servos gemäß Eures Testlaufs ein.', },
    {'Aktiviert die Steuerung für Schrotthäscher X6000 und testet seine Fähigkeiten aus. Gebt Dr. h. c. tüft. Vomisa bei den Versuchsgründen im Nethersturm danach Eure Rückmeldung.', },
  },
  [10249] = {
    'Zurück zum Chef!',
    {'Ich bin mir sicher, dass der Raketenchef ein oder zwei Takte mit Euch reden möchte!|n|nAn Eurer Stelle würde ich mich gleich nach Area 52 aufmachen und mit ihm sprechen!', },
    {'Meldet Euch sofort bei Raketenchef Doppeldecker in Area 52 im Nethersturm!', },
  },
  [10250] = {
    'Blutige Rache',
    {'Im Osten befindet sich ein alter Belagerungsturm der Allianz. Jetzt suchen Plünderer dort nach alten Nägeln und Alteisen. Vor langer Zeit haben bei diesem Turm viele Krieger der Allianz ihr Leben gelassen. Ihr Banner wurde von einem widerlichen Orckommandanten namens Urtrak gestohlen.|n|nStoßt bei diesem Belagerungsturm in das Kampfhorn der Unerschütterlichen, um Urtraks Aufmerksamkeit zu erregen. Vielleicht ruft es auch Krieger herbei, die vor langer Zeit in der Schlacht gestorben sind.', },
    {'Stoßt am alten Belagerungsturm der Allianz in das Kampfhorn der Unerschütterlichen. Tötet Urtrak und kehrt danach zu Althen dem Historiker im Rückenbrechergrat zurück.', },
  },
  [10251] = {
    'Der große Plan des Meisters?',
    {'Gestern Abend haben uns ein paar Draenei einen Besuch abgestattet. Sie haben irgendwie erfahren, dass wir das Buch in unserem Besitz haben und uns das großzügige Angebot gemacht, es uns abzunehmen.|n|nWir haben sie nicht gefragt, was sie mit dem Buch wollen, aber der Jüngere sprach die ganze Zeit vom "großen Plan des Meisters", was immer das zu bedeuten hat.|n|nIch stelle keine Fragen, wenn es ums Geld geht. Sie haben uns viel Gold geboten und wir haben ihnen das Buch gegeben.|n|nEr sagte, er lebe in Nagrand, im alten verlassenen Rüstlager nördlich von Telaar.', },
    {'Sucht Nitrin den Gelehrten im verlassenen Rüstlager in Nagrand.', },
  },
  [10252] = {
    'Vision der Toten',
    {'Es hat schon begonnen. Levixus steht auf den Ruinen von Auchindoun und liest aus dem Buch der Toten. Er ruft die Toten beim Namen und unterwirft die gequälten Seelen durch ein dämonisches Ritual seinem Willen. Wenn er kann, wird er ganz Auchindoun erwecken!|n|nAber... Ihr müsst Euch erst vorbereiten. Ihr könnt nicht mit etwas kämpfen, dass Ihr nicht seht.|n|n<Nitrin reicht Euch ein Pergament.>|n|nBringt mir die Gegenstände, die ich für die Tinktur benötige. Sie wird Euren Geist erweitern und Euch ermöglichen, die Geisterwelt zu sehen.', },
    {'Nitrin im verlassenen Rüstlager in Nagrand möchte, dass Ihr ihm 1 Augapfel eines Berggronns, 1 fehlerloser Schnabel eines großen Windrocs und 1 Tran eines gealterten Grollhufs bringt.', },
  },
  [10253] = {
    'Levixus der Seelenrufer',
    {'Geht jetzt, $N. Ihr könnt Levixus auf den höchsten Ruinen von Auchindoun finden. Nähert Euch vom Süden der Knochenwüste. Er befindet sich mitten in einem Sturm von Seelen...|n|nVernichtet ihn und nehmt ihm das Buch der Toten ab. Wenn Ihr das verfluchte Buch in Eurem Besitz habt, dann zerstört es! Zerstört es, damit eine solche Grausamkeit nie wieder geschehen kann.', },
    {'Vernichtet Levixus und nehmt Euch das Buch der Toten aus seinem Besitz.|n|nBringt das Buch der Toten zu Ramdor dem Wahnsinnigen außerhalb der Auchenaikrypta am Eingang zu Auchindoun.|n|nIhr hattet eine Vereinbarung, erinnert Ihr Euch?', },
  },
  [10254] = {
    'Truppenkommandant Danath',
    {'<Marschall Isildor spuckt in den Staub.>|n|nNun, es ist an der Zeit, dass Ihr Euch Euren Sold verdient. Meldet Euch sofort bei Truppenkommandant Trollbann in der Feste. Er und seine Berater werden sich sicher freuen, Euch zu sehen.|n|n<Marschall Isildor salutiert teilnahmslos.>|n|nFür die Allianz!', },
    {'Marschall Isildor möchte, dass Ihr Euch bei Truppenkommandant Danath Trollbann in der Ehrenfeste meldet.', },
  },
  [10255] = {
    'Das Gegengift testen',
    {'Ich glaube, in dem Blut ist etwas, das wir als Grundlage für ein Gegengift verwenden können. Schaut mich nicht an, als hätte ich den Verstand verloren!|n|nDas ist in der Natur ganz normal. Oft kann das Heilmittel aus dem Gift selbst gewonnen werden. Und genau das habe ich vor.|n|nWenn wir die Eber von dem dämonischen Einfluss befreien können, verlieren sie hoffentlich ihre Aggressivität und können uns zeigen, wie wir auch den andern Arten helfen können.', },
    {'Probiert das cenarische Gegengift an einem bulligen Hölleneber aus und beobachtet die Folgen. Sobald Ihr die Ergebnisse des Experiments habt, kehrt zu Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.', },
  },
  [10256] = {
    'Den Schlüsselmeister finden',
    {'Wenn ich zurückblicke, hätte ich eigentlich wissen müssen, dass Kael\'thas\' Magie so widerstandsfähig ist. Er war schon immer ein talentierter Magier, aber nie zuvor habe ich etwas so Mächtiges gesehen, wie die Magie, die er beim Angriff auf den Turm gewirkt hat.|n|nDer Schutzschild verhindert, dass ich die Macht, die er aufrechterhält, ausspionieren kann, aber Ihr könnt das trotzdem.|n|nIhr werdet jedoch einen Fokus brauchen. Apex, ein Riese, der Kristalle mit sich herumträgt, streift auf den Weiten westlich der Manaschmiede Duro umher. Einer seiner Kristalle würde einen ausgezeichneten Fokus abgeben.', },
    {'Sucht Apex und besorgt Euch Apex\' Kristallfokus. Kehrt dann zum Violetten Turm zurück und benutzt Apex\' Kristallfokus in der Nähe von Erzmagier Vargoths Kugel um herauszufinden, wer den Schlüssel zum Fluch des Turms hat.', },
  },
  [10257] = {
    'Den Schlüsselstein erobern',
    {'Es überrascht mich nicht, dass Kael\'thas den Schlüssel zu diesem Schutzschild in die Hände von jemandem wie Kommandantin Sarannis gegeben hat. Prinz Kael\'thas mag vielleicht vieles sein, aber sicher kein Narr.|n|nUm diesen Fluch ein für alle Mal zu brechen, müsst Ihr in die Festung der Stürme gehen und den Schlüsselstein besorgen.|n|nWenn der Schlüsselstein zerstört ist, werde ich meine Freiheit wiedererlangen.', },
    {'Reist zur Botanika der Festung der Stürme und besorgt Euch den Schlüsselstein von Kommandantin Sarannis. Bringt ihn danach zu Erzmagier Vargoth im Violetten Turm.', },
  },
  [10258] = {
    'Die Gefallenen ehren',
    {'Hogarth, der Kommandant des Rüstlagers, befindet sich im östlichen Turm. Ihr müsst ihm von Eurem Sieg über Urtrak berichten. Vielleicht ist er dann freundlich? Natürlich könnte er auch versuchen, Eure Seele zu fressen. Bei Geistern wie diesen weiß man nie.|n|nDie Unerschütterlichen sind uns immer noch feindlich gesonnen und werden versuchen zu töten, wenn sie können. Seid vorsichtig, $N.', },
    {'Meldet Euch bei Hogarth, dem Kommandanten des Rüstlagers.', },
  },
  [10259] = {
    'In die Bresche springen',
    {'Die Kämpfe bei dem Portal nehmen kein Ende! Die Argentumdämmerung kämpft in einer verzweifelten Schlacht - sollten wir verlieren, wird das Feuer der Dämonen niemals erlöschen.|n|nHelft uns, $N. Zieht in den Kampf und helft unseren Brüdern und Schwestern. Helft ihnen, sich gegen die Welle der Dunkelheit zu erheben! Die Argentumdämmerung - und die Welt - brauchen Euch!', },
    {'Tötet 6 einfallende Teufelswachen und kehrt dann zum Argentumabgesandten Stolzbrunn zurück.', },
  },
  [10260] = {
    'Netheorologe Kupfernickel',
    {'Ihr müsst über die Hauptbrücke vom Schergrat in den Nethersturm gekommen sein. Habt Ihr dort Netheorologe Kupfernickel mit seiner verrückten Ausrüstung gesehen?|n|nMerkwürdig, ich erwarte einen Bericht von ihm, und er ist schon lange überfällig. Wahrscheinlich hat er es vergessen. Ihr kennt ja diese Wissenschaftler.|n|nGeht zurück zur Brücke und nagelt ihn fest. Lasst Euch nicht mit Entschuldigungen abspeisen, bringt mir einfach seinen Bericht.|n|nDanke!', },
    {'Sprecht mit Netheorologe Kupfernickel bei der Brücke, die vom Nethersturm zum Schergrat führt.', },
  },
  [10261] = {
    'Gesucht: Vernichterservo!',
    {'GESUCHT: 1 Vernichterservo, um den kaputten in meinem langhalsigen Spektrumanalysator zu ersetzen.|n|nIhr und Eure Freunde sollten bei den Blutelfen in der Manaschmiede B\'naar im Westen nachschauen, ob sie ein paar Ersatzteile haben. Wie es scheint, haben sie dort ein paar Arkanvernichter.|n|nBitte bringt den Servo in unbeschadetem Zustand zu Papa Mauschel in Area 52.', },
    {'Besorgt einen Vernichterservo und bringt ihn zu Papa Mauschel in Area 52 im Nethersturm.', },
  },
  [10262] = {
    'Ein Hügel voll Astraler',
    {'Es gibt noch etwas anders, bei dem ich Eure Hilfe brauche.|n|nEine Gruppe von Astralen, die als Zaxxis bekannt sind, haben ihre Verbindungen zum Konsortium abgebrochen um ihre eigenen Geschäfte zu machen. Sie machen sogar Geschäfte mit den Blutelfen! Das können wir nicht hinnehmen!|n|nIch habe ihre Gruppe bei dem Hügel im Süden unterwandert, aber als ich ihren Anführer ausgeschaltet hatte, musste ich zurück in die Sicherheit von Area 52 fliehen.|n|n$C, geht dorthin und bringt mir ihre Insignien. Natürlich tragen nicht alle Insignien, weil sie Feiglinge sind.', },
    {'Sammelt 10 Insignien der Zaxxis und kehrt dann zu Netherpirscher Khay\'ji in Area 52 im Nethersturm zurück.', },
  },
  [10263] = {
    'Dem Konsortium helfen',
    {'Die Naaru von Shattrath haben versucht, dem Konsortium beizubringen, die Dinge auf ihre Weise zu sehen.|n|nDas Glück wollte, dass die Geschäftsbeziehungen zwischen den Astralen und den Blutelfen im Nethersturm sich in letzter Zeit drastisch verschlechtert haben.|n|nIm Dorf gibt es einen Mitarbeiter des Konsortiums namens Khay\'ji, der vor Kurzem ein paar Probleme mit einer Truppe von abtrünnigen Astralen hatte. Als Mitglied der Aldor möchte ich Euch bitten, ihm zu helfen, wo Ihr nur könnt.', },
    {'Sprecht mit Netherpirscher Khay\'ji in Area 52 im Nethersturm.', },
  },
  [10264] = {
    'Dem Konsortium helfen',
    {'Die Naaru von Shattrath haben versucht, dem Konsortium beizubringen, die Dinge auf ihre Weise zu sehen.|n|nDas Glück wollte, dass die Geschäftsbeziehungen zwischen den Astralen und den Blutelfen im Nethersturm sich in letzter Zeit drastisch verschlechtert haben.|n|nIm Dorf gibt es einen Mitarbeiter des Konsortiums namens Khay\'ji, der vor Kurzem ein paar Probleme mit einer Truppe von abtrünnigen Astralen hatte. Als Mitglied der Seher möchte ich Euch bitten, ihm zu helfen, wo Ihr nur könnt.', },
    {'Sprecht mit Netherpirscher Khay\'ji in Area 52 im Nethersturm.', },
  },
  [10265] = {
    'Kristallsammlung des Konsortiums',
    {'Unser Anführer, Nexusprinz Haramad, hat mich gebeten, ein Kristallartefakt aus den Ruinen von Arklon im Südosten zu besorgen.|n|nEs sind alte Draeneiruinen. Zum Pech für mich und die Goblins hier hat die Brennende Legion beschlossen, selbst danach zu graben.|n|nWenn Ihr mir weiterhin helfen wollt, nehmt dem Schreckenslord namens Pentatharon das Kristallartefakt ab.', },
    {'Besorgt ein Kristallartefakt von Arklon und bringt es zu Netherpirscher Khay\'ji in Area 52 im Nethersturm.', },
  },
  [10266] = {
    'Bitte um Unterstützung',
    {'Während Ihr in den Ruinen von Arklon wart, habe ich eine Bitte um Unterstützung von einem unserer Mitarbeiter im Feld erhalten. Wie es scheint hat das Konsortium einige Probleme damit, Waren von den Blutelfen zurückzufordern, die sie nicht bezahlen wollen.|n|nBitte begebt Euch von Area 52 aus nach Osten und überquert die Brücke zur nächsten Insel. Ihr findet meinen Gefährten Gahruj im Mittelreichposten in der Biokuppel Mittelreich.', },
    {'Sucht Gahruj und bietet ihm Eure Hilfe an. Er befindet sich im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.', },
  },
  [10267] = {
    'Rechtmäßiger Besitz',
    {'Unsere Geschäftsbeziehungen mit den Blutelfen scheinen zu Ende zu sein. Vor ein paar Wochen wurde ihnen bei der Manaschmiede Duro eine große Ladung mit Vermessungsausrüstung geliefert. Sie haben sich geweigert, dafür zu bezahlen.|n|n$N, ich möchte, dass Ihr den Blutelfen in der Manaschmiede Duro im Osten einen Besuch abstattet. Sie scheinen ein paar Probleme mit angreifenden Manakreaturen zu haben, also nutzt aus, dass sie beschäftigt sind.|n|nMir ist egal, was mit ihnen passiert, aber ich hätte meinen rechtmäßigen Besitz gerne zurück.', },
    {'Sammelt 10 Kästen mit Vermessungsausrüstung und bringt sie zu Gahruj im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.', },
  },
  [10268] = {
    'Eine Audienz beim Prinzen',
    {'Nexusprinz Haramad hat mir zu verstehen gegeben, dass er seinen Besitz unverzüglich und persönlich zurückerhalten möchte. Ich wäre Euch sehr dankbar, wenn Ihr ihm die Waren an meiner statt zurückbringen könntet.|n|nEine Audienz beim Nexusprinzen ist eine große Ehre, und ich bin mir sicher, dass er sehr gerne etwas über Eure Abenteuer im Nethersturm erfahren würde.|n|nSucht ihn in seiner Kammer oben in der Sturmsäule im Norden auf. Er ist oft nur als holografisches Bild anwesend, dass Ihr ansprechen könnt.', },
    {'Bringt die Vermessungsausrüstung zum Bild von Nexusprinz Haramad in der Sturmsäule im Nethersturm.', },
  },
  [10269] = {
    'Triangulationspunkt Eins',
    {'Da ist noch ein anderer Grund, warum ich die Vermessungsausrüstung zurückhaben wollte. Es gibt da einen Kristall aus einer alten Draeneilegende, der mir sehr wichtig ist.|n|nMan sagt, dass der Kristall seinem Träger gottgleiche Macht verleiht! Aber es besteht die Gefahr, dass jemand anderes ihn ausgräbt, nämlich die Brennende Legion.|n|n$N, nehmt die Ausrüstung und benutzt sie, um den ersten Triangulationspunkt zu finden. Wir wissen, dass er sich irgendwo östlich der Manaschmiede Ultris befinden muss.|n|nMeldet Euch danach bei meinem Agenten, Händler Hazzin, auf der Insel der Manaschmiede Ultris.', },
    {'Benutzt das Triangulationsgerät, um den Weg zum ersten Triangulationspunkt zu bestimmen. Wenn Ihr ihn gefunden habt, meldet die Position an Händler Hazzin beim Wachposten des Protektorats auf der Insel der Manaschmiede Ultris im Nethersturm.', },
  },
  [10270] = {
    'Ein nicht-so-bescheidenes Angebot',
    {'Aus Eurem Gesicht kann ich lesen, dass Ihr $Gein:eine:r; $R mit Sinn fürs Geschäft seid.|n|nIch habe mir einen Ruf als Händler für exotische und teure Waren erarbeitet, und bin gerade dabei, ein neues Unternehmen zu starten.|n|nIch könnte einen fähigen Unterhändler brauchen, um die Waren vom Sternensturz weiterzuleiten.|n|nZuerst müsst Ihr eine Teleporterplattform wieder aufladen. Im Zugangsschacht Zeon auf der südlichen Seite der Manaschmiede Ultris findet Ihr eine Ersatzenergiezelle. Das Protektorat befindet sich zurzeit dort, deshalb könnt Ihr einfach ihren Signalgebern zu Eurem Ziel folgen.', },
    {'Besorgt Euch die Teleporterenergiezelle und bringt sie zur Astralteleportplattform im Sternensturz östlich der Manaschmiede Ultris. Aktiviert die Plattform und bringt die Teleporterenergiezelle zu Windhändler Marid, damit er sie einbauen kann.', },
  },
  [10271] = {
    'Zur Sache',
    {'Wir Ihr sicher gesehen habt, wimmelt es in dieser Gegend von Netherdrachen aller Altersstufen. Alle Netherdrachen, die jungen wie die alten, verfügen über eine Essenz, die bei K... - ähh, meinem Kunden sehr begehrt ist.|n|nDie Meisten sind nicht bereit, dafür ihr Leben aufs Spiel zu setzen, deswegen haben wir die Gegend hier ganz für uns alleine. Ihr könnt damit anfangen, die Essenz von allen Drachen hier zu sammeln, aber es ist von größter Notwendigkeit, dass wir sofort einen steten Nachschub aufbauen. Kehrt zu mir zurück, wenn Ihr eine erste Ladung zusammen habt.', },
    {'Ladet den Essenzsammler auf, indem Ihr ihn bei Netherdrachen und Nethergroßdrachen auf dem Sternensturz anwendet, und kehrt dann zu der Gegend um die Astralteleportplattform zurück.', },
  },
  [10272] = {
    'Ein viel versprechender Anfang',
    {'Wir sind hierhergekommen, um den Gerüchten über eine merkwürdige Drachenbrut, die vielleicht die Nachkommen von Todesschwinge selbst sein könnten, nachzugehen. Ganz offensichtlich handelt es sich nicht um gewöhnliche schwarze Drachen.|n|nWenn wir eine Gelegenheit hätten, ihre Eier zu untersuchen, könnten wir sicher mehr über sie herausfinden. Ihr Hass auf meinesgleichen sitzt so tief, dass ich nicht nahe genug herangehen kann, um die Eier selbst zu sammeln. Werdet Ihr mir helfen?', },
    {'Sammelt 15 Netherdrachkineier und kehrt dann zu Tyri und Jorad im Sternensturz zurück.', },
  },
  [10273] = {
    'Störende Ablenkung',
    nil,
    {'Sprecht mit Windhändler Marid und lockt ihn von seinem Handelsposten fort. Vernichtet ihn und kehrt dann zu Tyri und Jorad im Sternensturz zurück.', },
  },
  [10274] = {
    'Den Sternensturz sichern',
    {'Die Netherdrachen verfügen über dasselbe wilde Temperament wie ihre Vorfahren, die schwarzen Drachen. Etwas an ihnen ist jedoch vollkommen anders. Sie schlüpfen schnell und werden schnell reif, indem sie die fremdartigen Energien, die ihre Art zur Zerstörung Draenors getrieben hat, nutzen.|n|nEs gibt so Vieles, was ich noch über sie in Erfahrung bringen muss, aber ich glaube, dass die Mächte für meinen eigenen Schwarm von Vorteil sein könnten. Wenn wir den Anführer dieser Drachen, Veraku, als Zeichen unserer Dominanz vernichten könnten, könnten wir den Rest vielleicht so einschüchtern, dass sie sich uns unterwerfen.', },
    {'Benutzt die Herausforderung des blauen Drachenschwarms um Veraku am südlichen Ende des Sternensturzes zu provozieren. Besiegt ihn und kehrt dann zu Tyri und Jorad im Sternensturz zurück.', },
  },
  [10275] = {
    'Triangulationspunkt Zwei',
    {'Ich habe das Triangulationsgerät mit den Informationen des ersten Punkts neu eingestellt. Ihr könnt es genauso wie beim ersten Mal benutzen, um den zweiten Punkt zu bestimmen.|n|nAlles, was ich Euch sagen kann, ist, dass der zweite Punkt sich weit im Westen befindet.|n|nWenn Ihr ihn gefunden habt, sprecht mit Windhändler Tuluman, ein weiterer Agent des Nexusprinzen. Er steht als Waffenhändler getarnt in einem kleinen Handelsposten neben der Brücke, die zur Insel, auf der sich die Manaschmiede Ara befindet, führt.', },
    {'Benutzt das Triangulationsgerät, um den Weg zum zweiten Triangulationspunkt zu bestimmen. Wenn Ihr ihn gefunden habt, meldet die Position an Windhändler Tuluman auf Tulumans Landeplatz auf der anderen Seite der Brücke zu der Insel der Manaschmiede Ara im Nethersturm.', },
  },
  [10276] = {
    'Das volle Dreieck',
    {'Mit den Daten vom ersten und zweiten Punkt kann ich sicher sagen, dass der Kristall sich auf den Ruinen von Farahlon im Nordosten befindet.|n|nUnglücklicherweise sagen die Daten, dass der Kristall sich bewegt, was bedeutet, dass er bereits gefunden wurde. Wahrscheinlich von der Brennenden Legion!|n|nFalls das tatsächlich so ist, empfehle ich Euch, ein paar Freunde mitzunehmen.|n|nTötet den Dämon, der den Kristall hat, und bringt ihn zu Nexusprinz Haramad.', },
    {'Besorgt Euch den Kristall von Ata\'mal und bringt ihn zu Nexusprinz Haramad in der Sturmsäule im Nethersturm.', },
  },
  [10277] = {
    'Die Höhlen der Zeit',
    {'Grüße, $N. Bitte folgt der Bewahrerin. Sie wird ein wenig... Licht in die Angelegenheit bringen.', },
    {'Andormu in den Höhlen der Zeit möchte, dass Ihr der Bewahrerin der Zeit durch die Höhle folgt.', },
  },
  [10278] = {
    'Sphärenrisse',
    {'Ich bin lange auf der Suche nach der Wahrheit der Leere durch die Scherbenwelt gereist. Jetzt bin ich alt und schwach. Ich sehe merkwürdige Dinge und bin nicht mehr ich selbst. Vielleicht wollt Ihr mir helfen?|n|nIch muss die Geheimnisse der Leerwandler aufdecken. Westlich des Expeditionsrüstlagers befindet sich ein Ort namens Sphärenfelder. Zeit und Raum sind dort sehr schwach, da die Felder nahe beim Abgrund liegen. Geht dorthin und benutzt den instabilen Sphärenrissgenerator. Er wird einen Sphärenriss erzeugen. Ihr müsst den Sphärennether von den Kreaturen, die durch ihn herauskommen, sammeln.', },
    {'Benutzt den instabilen Sphärenrissgenerator in den Sphärenfeldern. Sammelt 3 Einheiten Sphärennether von instabilen Leerwandlern und kehrt dann zu Ogath dem Verrückten im Rückenbrecherposten zurück.', },
  },
  [10279] = {
    'Zum Hort des Meisters',
    {'Ah, $N. Wir haben Euch erwartet. Bitte erlaubt, dass einer meiner Brüder Euch zum Meister fliegt. Er wartet unten auf Euch...', },
    {'Sprecht mit Andormu in den Höhlen der Zeit.', },
  },
  [10280] = {
    'Sonderlieferung nach Shattrath',
    {'Ich bin ein Astraler, der sein Wort hält, $N. Ihr habt mich wirklich inspiriert.|n|nIch werde Euch den Kristall von Ata\'mal geben, damit Ihr ihn den Naaru überreicht. Da Euer Heldenmut dies möglich gemacht hat, soll Euch die Ehre zuteilwerden, ihn zu übergeben.|n|nIhr könnt meinen persönlichen Teleporter benutzen, um direkt nach Shattrath zu gelangen. Tretet einfach hindurch und er wird Euch dorthin bringen.|n|nGebt den Kristall dem Naaru namens A\'dal auf der Terrasse des Lichts.', },
    {'Bringt den Kristall von Ata\'mal zu A\'dal auf der Terrasse des Lichts in Shattrath.', },
  },
  [10281] = {
    'Formelle Vorstellung',
    {'Grüße, $N. Keine Angst, dies ist nur eine Projektion meiner gegenwärtigen Form. Es ist die einzige Möglichkeit, wie mein Gefährte und ich Wache halten können, ohne uns selbst zu offenbaren.|n|nDer Astrale, der Euch angesprochen hat, Marid, ist nur ein Schwindler, der sich als anständiger Händler ausgibt. Überlegt Euch daher, ob Ihr nicht lieber mit mir zusammenarbeiten wollt. Mein Ziel ist es, mehr über die ungewöhnlichen Drachkin des Sternensturzes herauszufinden. Trefft mich am nördlichen Ende des Sturzes, damit wir über die Details sprechen können.', },
    {'Sucht Tyri am nördlichen Ende des Sternensturzes und sprecht mit ihr.', },
  },
  [10282] = {
    'Das Alte Hügelland',
    {'Im Westen findet Ihr die Pfade der Zeit in das Hügelland der Vergangenheit - vor 7 Jahren um genau zu sein.|n|nDie Streitmächte kämpfen gegen den Kriegshäuptling der Horde, Thrall, um ihn davon abzuhalten, aus der Burg Durnholde zu fliehen.|n|nWenn es Thrall nicht gelingt zu fliehen, wird die Welt, wie Ihr sie jetzt kennt, aufhören zu existieren.|n|nRuft eine Gruppe von Abenteurern zusammen und reist auf dem Pfad der Zeit ins Alte Hügelland. Zwei unserer Agenten warten dort auf Euch.|n|nSprecht mit Erozion auf der anderen Seite.', },
    {'Andormu in den Höhlen der Zeit bittet Euch, ins Alte Hügelland zu reisen und mit Erozion zu sprechen.', },
  },
  [10283] = {
    'Tarethas Ablenkungsmanöver',
    {'Taretha spielte eine entscheidende Rolle bei Thralls Überleben und Erziehung und prägte Thralls Leben maßgeblich.|n|nEs war Taretha, die die Wachen von Durnholde ablenkte, damit Thrall entkommen konnte.|n|nJetzt haben die Ewigen Taretha gefangen und halten sie in Tarrens Mühle fest. Ohne unsere Einmischung wird das Ablenkungsmanöver niemals stattfinden. Ihr müsst den Brandsatz, den ich Euch gegeben habe, nehmen und die Internierungsbaracken in Durnholde anzünden. Wenn Ihr das erledigt habt, sprecht mit dem jungen Thrall im Kellergefängnis der Burg.', },
    {'Reist zur Burg Durnholde und platziert mithilfe des Bündels mit Brandbomben, das Ihr von Erozion erhalten habt, 5 Brandsätze auf den Fässern in jeder Internierungsbaracke.|n|nSprecht mit Thrall im Kellergefängnis der Burg Durnholde, wenn Ihr die Internierungsbaracken angezündet habt.', },
  },
  [10284] = {
    'Flucht aus Durnholde',
    {'Ihr schaut mich an und seht nur einen Jungen, aber tief in meinem Herz und meiner Seele halte ich meine Träume versteckt. Ich habe Pläne für mein Volk, Fremder. Eines Tages werden sie ihre Unterdrücker überwältigen und in Einheit auferstehen. Sie werden ihre Fesseln abwerfen und aus diesem Aufstand soll die orcische Horde entstehen.|n|nIch verspreche Euch, Fremder, dass ich Euch suchen werde, wenn wir heil hier herauskommen und ich die Möglichkeiten habe, Eure selbstlose Tat zu belohnen... Ich werde Euch finden.|n|n<Thrall nickt.>|n|nWir fliehen, wenn Ihr bereit seid.', },
    {'Gebt Thrall Bescheid, wenn Ihr bereit seid. Folgt Thrall aus der Burg Durnholde und helft ihm, Taretha zu befreien und sein Schicksal zu erfüllen.|n|nSprecht mit Erozion im Alten Hügelland, wenn Ihr diese Aufgabe erfüllt habt.', },
  },
  [10285] = {
    'Rückkehr zu Andormu',
    {'Diese Zeitachse wurde wiederhergestellt und der Angriff des ewigen Drachenschwarms auf das Hügelland vorerst abgewendet.|n|nKehrt sofort zu Andormu zurück. Er wartet im Hort des Meisters auf Eure Ankunft.', },
    {'Kehrt zu dem jungen Andormu in den Höhlen der Zeit in Tanaris zurück.', },
  },
  [10286] = {
    'Arelions Geheimnis',
    {'Arelions Tagebuch enthält überhaupt keine wissenschaftlichen Studien. Er beschreibt seine Eskapaden mit einer jungen Blutelfe! Wie konnte ich nur so dumm sein?|n|nUnglücklicherweise nennt das Tagebuch den Namen des Flittchens nicht. Aledis, ein Kollege von Arelion, war sein bester Freund und Vertrauter. Befragt ihn und findet heraus, mit wem er eine Affäre hatte.|n|nIch habe gesehen, wie Aledis sich vor Kurzem aus der Falkenwacht in Richtung Zangarmarschen aufgemacht hat. Folgt der Straße nach Norden aus dem Dorf heraus. Sie biegt nach einer Weile nach Westen in Richtung Zangarmarschen ab.', },
    {'Magistrix Carinda möchte, dass Ihr Magister Aledis befragt. Aledis wurde zuletzt auf einer Reise von der Falkenwacht zu den Zangarmarschen gesehen.', },
  },
  [10287] = {
    'Die enttarnte Geliebte',
    {'Ich bin Arelions Freund, aber ich werde für ihn nicht die Prügel meines Lebens einstecken. Seine Geliebte ist Viera Sonnenwisper.|n|nSagt das seinem Drachen von Ehefrau. Was will sie schon dagegen tun?', },
    nil,
  },
  [10288] = {
    'Ankunft in der Scherbenwelt',
    {'Ich möchte, dass Ihr mit Amish Wildhammer sprecht. Ihr findet ihn etwa 30 Schritt südlich von hier. Nehmt den ersten Flug zur Ehrenfeste. Wenn Ihr dort angekommen seid, werdet Ihr von Marschall Isildor begrüßt werden. Gebt ihm diese Empfehlung, in der ich notiert habe, wo Ihr meiner Meinung nach am hilfreichsten sein könntet.|n|nIch habe Euch einen Befehl erteilt, Soldat, nun fort mit Euch! Und auch wenn Ihr darauf brennt, uns im Kampf gegen den Feind hier zu unterstützen, dürft Ihr keine Zeit verschwenden. Die Ehrenfeste braucht Euch sogar noch mehr als wir.', },
    {'Kommandant Duron beim Dunklen Portal auf der Höllenfeuerhalbinsel möchte, dass Ihr Durons Bericht zu Flugmeister Amish Wildhammer bringt.', },
  },
  [10289] = {
    'Reise nach Thrallmar',
    {'Wenn Ihr bereit seid, rufe ich einen Wyvern, der Euch nach Thrallmar bringt. Wenn Ihr angekommen seid, bringt Orions Bericht zu General Karkork.|n|nLok\'tar ogar, $N - Viel Glück.', },
    {'Nehmt Vlagga Freyfeders Windreiter nach Thrallmar. Bringt Orions Bericht zu General Krakork.', },
  },
  [10290] = {
    'Auf der Suche nach Farahlit',
    {'Im Nordosten gibt es eine Region, die Netherstein genannt wird. Früher war sie unter einem fruchtbaren und grünen Land verborgen. Die neu gefundenen Kristallformationen haben uns ein Mineral gezeigt, das wir zur Ehre der früheren Identität des Landes Farahlit genannt haben.|n|nDie kleine Menge Farahlit, die wir bis jetzt abgebaut haben, erfreut sich jetzt schon großer Beliebtheit bei unseren Kunden. Das hochwertigste Mineral stammt jedoch nicht von den Ablagerungen, sondern von den Riesen, die um den Netherstein herum leben. Ich biete Euch einen Teil des Gewinns an, wenn Ihr mir helft, hochwertiges Farahlit zu besorgen.', },
    {'Sammelt 4 Stück Rohfarahlit und kehrt dann zu Zuben Elgenubi in der Sturmsäule zurück.', },
  },
  [10291] = {
    'Bericht an Nazgrel',
    {'Auch wenn unsere Krieger keine ebenbürtigen Gegner haben, ist unsere Stellung in diesem Ödland immer noch angreifbar. Meldet Euch bei Nazgrel in der Kaserne. Er braucht gute Agenten... wie Euch. Wenn wir unsere Stellung hier nicht halten können, sind wir für niemanden eine Hilfe! Geht jetzt.', },
    {'General Krakork in Thrallmar möchte, dass Ihr mit Nazgrel sprecht.', },
  },
  [10292] = {
    'Mehr Energie!',
    {'Ein wertvolles Gut in kleinen Häppchen zu sammeln hat das malerische Flair eines Familienunternehmens, aber auf dem heutigen Markt ist es einfach nicht konkurrenzfähig.|n|nNein, wir brauchen einen Weg, Farahlit in Massenproduktion zu beschaffen! Dann wäre der Hauptanteil des Marktes unser!|n|nIch habe eine Idee, aber sie erfordert eine mächtige, konzentrierte Energiequelle. Solch eine Energiequelle kann man nur an einem Ort finden. Geht zu den Lagern der Legion nördlich von hier und besorgt Euch ein paar ihrer Schusswaffen.', },
    {'Zuben Elgenubi möchte, dass Ihr 8 Schusswaffen der Legion besorgt und sie zur Sturmsäule bringt.', },
  },
  [10293] = {
    'Die Kristallader anzapfen',
    {'Jetzt, da wir ein solides Grundprodukt haben, benötigen wir etwas von höherer Qualität. Das Farahlit, das wir bisher gesammelt haben, ist zwar ganz nett, aber es gibt noch besseres da draußen.|n|nWir müssen eine Probe direkt von Felsnarbe, dem Patriarchen der Riesen von Farahlon, besorgen! Ihr solltet ihn bei den anderen Riesen in der Gegend um den Nethersteine herum finden können. Aus seinem Rücken ragen große Farahlitstücke heraus; genau was wir brauchen. Tötet den Riesen und sammelt einen Farahlitkern von ihm.', },
    {'Zuben Elgenubi in der Sturmsäule möchte, dass Ihr einen Farahlitkern besorgt.', },
  },
  [10294] = {
    'Der Leerengrat',
    {'Wir müssen meinen Sphärenrissgenerator verbessern. Ihr müsst ihn zum Leerengrat bringen. Geht von hier aus nach Osten, um die verdorbene Festung Zeth\'Gor herum. Im Osten hinter Zeth\'Gor befindet sich ein kleiner Pass durch die Berge. Hinter diesem Pass findet Ihr den Leerengrat, einen schrecklichen Ort direkt am Abgrund.|n|nIhr müsst die Wandler, die Ihr dort findet, töten und mir Splitter ihrer Seele bringen. Mit ihrer Macht werden wir den Sphärenrissgenerator verbessern und ein Portal in die jenseitige Dimension öffnen, das nicht mehr geschlossen werden kann.', },
    {'Geht zum Leerengrat und tötet die Kreaturen, die Ihr dort findet. Sammelt 40 Seelensplitter des Leerengrats und kehrt dann zu Ogath dem Verrückten im Rückenbrecherposten zurück.', },
  },
  [10295] = {
    'Aus dem Abgrund',
    {'Mein Sphärenrissgenerator ist fertig. Ihr könnt damit jetzt einen wahren Prinzen der Leere rufen, eine Kreatur, deren Seelensplitter uns deutlich mehr darüber verraten wird, was dahinter liegt.|n|nGeht nach Süden in den Leerengrat und benutzt meinen Sphärenrissgenerator in der Nähe der Steine der Leere. Haltet nach einer Gruppe von Kristallen am Ende des Abgrunds Ausschau. Ein riesiger Sphärenriss wird sich auftun, aus dem dann sicher der Baron der Leere Galaxis entsteigen wird.|n|nZerstört diese Kreatur und bringt mir seinen Seelensplitter.', },
    {'Tötet Galaxis und sammelt seinen Seelensplitter. Bringt den Splitter zu Ogath dem Verrückten im Rückenbrecherposten.', },
  },
  [10296] = {
    'Der Schwarze Morast',
    {'Der ewige Drachenschwarm versucht nun nicht einmal mehr, seine Pläne geheim zu halten. Sie haben vor, den Wächter, Medivh, zu töten und zu verhindern, dass das Dunkle Portal jemals geöffnet wird. Auf den ersten Blick scheint das ein Gefallen für die Streitkräfte der Allianz zu sein, aber tatsächlich wären die Folgen katastrophal und würden in der Zerstörung Eurer Welt enden.|n|nIhr müsst auf dem Pfad der Zeit zum Schwarzen Morast reisen. Geht zuerst nach Westen und dann nach Süden, vorbei an meinem zukünftigen Ich, bis Ihr zu dem Tunnel kommt, in dem die Sumpfwesen leben. Durchquert ihn und sprecht mit Sa\'at.', },
    {'Reist durch die Höhlen der Zeit in den Schwarzen Morast während der Öffnung des Dunklen Portals und sprecht mit Sa\'at.', },
  },
  [10297] = {
    'Die Öffnung des Dunklen Portals',
    {'Hinter diesem Pfad der Zeit, im Herzen des Schwarzen Morasts, arbeitet Medivh verbissen an der Öffnung des Dunklen Portals.|n|nÜberall im Morast werden sich Zeitlöcher öffnen, aus denen die Ewigen herausströmen werden mit dem Ziel, Medivhs Schilde und schließlich auch Medivh selbst zu vernichten.|n|nTötet die Lords des Zeitlochs und ihre Anführer, bis Medivh erfolgreich war.', },
    {'Sa\'at im Schwarzen Morast der Höhlen der Zeit möchte, dass Ihr Medivh verteidigt, bis er das Dunkle Portal geöffnet hat.|n|nKehrt zu Sa\'at zurück, wenn Ihr erfolgreich wart.', },
  },
  [10298] = {
    'Held des Schwarms',
    {'Kehrt zum Kind, Andormu, zurück, $N. Er erwartet Euch außerhalb dieser Zeitfalte im Hort des Meisters.|n|nIch höre Flügelschlagen. Die Wächter der Sande interessieren sich für Eure Fähigkeiten. Vielleicht möchten auch sie mit Euch sprechen.', },
    {'Kehrt zum Kind, Andormu, in den Höhlen der Zeit in Tanaris zurück.', },
  },
  [10299] = {
    'Manaschmiede B\'naar abschalten',
    {'Wir können die Manaschmieden nicht mit Gewalt abschalten, da wir sonst eine Explosion auslösen könnten, die die Scherbenwelt bis in den Kern erschüttern würde.|n|nLaut Eurer Abschrift gibt es einen Notschalter, der die Technologie dauerhaft abschaltet - ein Sicherheitsmechanismus, der bei der Technologie der Naaru Standard ist.|n|nFür diesen Vorgang braucht Ihr einen Kristall, der Euch die Kommunikation mit der Konsole ermöglicht. Dieser Zugangskristall befindet sich unseren Informationen zufolge im Besitz eines Vorarbeiters namens Theredis.', },
    {'Anachoret Karja möchte, dass Ihr in die Manaschmiede B\'naar geht und einen Zugangskristall von Vorarbeiter Theredis besorgt. Benutzt ihn bei der Steuerkonsole von B\'naar, um sie abzuschalten und meldet Euch danach bei Anachoret Karja zurück.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10300] = {
    'Den Stab wiederherstellen',
    {'<Ravandwyr untersucht den Stab und bemerkt, dass das Kopfstück fehlt.>|n|nDas ist einfach barbarisch! Ekkorash muss das kristallene Kopfstück abgenommen haben, um es mit einem anderen Schmuckstück zu verwenden, und hat gar nicht gemerkt, dass es zum Rest des Stabs dazugehört!|n|nSolange er nicht komplett ist, ist die Macht des Stabs stark verringert. Ich könnte ihn jedoch mit einem geeigneten Draeneikristall reparieren. Ich habe gehört, wie die Goblins von den Kristallen der Geister in den Ruinen von Enkaat im Norden gesprochen haben.', },
    {'Besorgt 4 fehlerlose Kristallsplitter von den Geistern in den Ruinen von Enkaat und bringt sie zu Ravandwyr in Area 52.', },
  },
  [10301] = {
    'Das Kompendium öffnen',
    {'Auch wenn ich froh bin, dass ich das meiste von Krasus\' Kompendium zurück habe, ist es ohne das heliotrope Oculus nutzlos. Seht Ihr, Krasus war sich der unermesslichen Macht des Buchs bewusst und hat Vorkehrungen getroffen, damit es vor gierigen Blicken geschützt bleibt.|n|nNur ein Magier mit großem Wissen kann dem Kompendium mithilfe des Oculus\' seine Geheimnisse entlocken.|n|nWährend Kael\'thas\' Angriff hat einer seiner Leutnants, Zauberhäscherin Marathelle, das Octulus aus dem Turm gestohlen und es zum Sonnenzornposten gebracht. Sie hält es sicher für ein hübsches kleines Schmuckstück.', },
    nil,
  },
  [10302] = {
    'Unberechenbare Mutanten',
    {'Die verstrahlten Kraftkerne der Exodar haben der Umwelt hier verheerenden Schaden zugefügt. Die deutlichste Auswirkung ist das Auftauchen merkwürdiger Kreaturen, die anscheinend in ihrer Nähe wie Pilze aus dem Boden schießen.|n|nVielleicht gibt es etwas, was wir für sie tun können, aber im Augenblick sind sie einfach zu viele für uns.|n|nIch möchte, dass Ihr losgeht und ihre Zahl reduziert. Vielleicht fällt mir danach eine andere Lösung ein.', },
    {'Tötet 8 unberechenbare Mutanten und kehrt dann zu Botanikerin Taerix bei der Absturzstelle im Am\'mental zurück.', },
  },
  [10303] = {
    'Die Blutelfen',
    {'Ihr müsst... die Bedrohung durch die Blutelfen... auslöschen. Findet heraus... was sie... vorhaben!|n|nSie sind auf dem... Kamm hinter mir.', },
    {'Tötet 10 Blutelfenspäher und kehrt dann zu Tolaan im Schattenkamm im Am\'mental zurück.', },
  },
  [10304] = {
    'Verteidiger Aldar',
    {'Mit Eurer Hilfe konnten wir schneller, als wir gehofft hatten, eine Lösung für unser Problem finden.|n|nIch habe keine weitere Arbeit für Euch, meine Lehrlinge schaffen den Rest alleine.|n|nIhr solltet mit Verteidiger Aldar auf der anderen Seite des Schiffs sprechen.', },
    {'Sprecht mit Verteidiger Aldar bei der Absturzstelle im Am\'mental.', },
  },
  [10305] = {
    'Bannzauberin Belmara',
    {'Dieser abgenutzte, dicke Foliant ist kein Zauberbuch, wie Ihr es vielleicht von einem Magier der Kirin Tor erwartet hättet. Die Seiten dieses Bandes sind voll von handgeschriebenen Geschichten mit bunten Zeichnungen.|n|nDer Foliant scheint viel älter zu sein, als seine Besitzerin und stammt vielleicht aus ihrem Familienerbe. Möglicherweise war das starke Band zu diesem Buch das, was Belmaras Geist an die Ruinen von Kirin\'Var gefesselt hat. Wenn Ihr es auf seinen rechten Platz im Bücherregal zurückbringt, kommt ihr Geist vielleicht zur Ruhe.', },
    {'Sucht die Wohnung von Bannzauberin Belmara in der Zaubergasse und bringt das Buch zurück auf seinen Platz im Bücherregal. Sprecht danach mit Hüter Dierwert in Kirin\'Var.', },
  },
  [10306] = {
    'Beschwörer Luminrath',
    {'Der Mantel, der ohne Zweifel von Hochelfen geschneidert wurde, ist sogar für die Verhältnisse der Kirin Tor reich verziert. Die Symbole und Zeichen ergeben für Euch keinen Sinn, aber sie scheinen die Kleidung eindeutig mit Magie zu verstärken.|n|nVielleicht bindet dieser Gegenstand seinen früheren Besitzer an diese Existenzebene. Wenn das so ist, würde die Verbindung des Geistes mit dieser Welt vielleicht zerbrechen, wenn Ihr den Mantel zurück in die Kommode in Beschwörer Luminraths Wohnung bringt.', },
    {'Sucht die Wohnung von Beschwörer Luminrath in der Zaubergasse und bringt den Mantel zurück in seine Kommode. Sprecht danach mit Hüter Dierwert in Kirin\'Var.', },
  },
  [10307] = {
    'Cohlien Frostwirker',
    {'Während Ihr die Kappe betrachtet, fragt Ihr Euch, ob ein Magier der Kirin Tor überhaupt so einen Hut besitzen würde. Der Zustand der Kappe lässt darauf schließen, dass der Gnom das Haus nie ohne sie verlassen hätte.|n|nIhr probiert den Hut kurz auf und bemerkt keine magischen Eigenschaften außer einem schwachen Zwang zu tanzen.|n|nVielleicht bindet dieser geschätzte Besitz den Geist des toten Magiers an das Dorf. Wenn Ihr die Kappe zurück in die Schließkiste in Cohliens Wohnung legen würdet, könntet Ihr den Geist des Magiers vielleicht befreien.', },
    {'Sucht die Wohnung von Cohlien Frostwirker in der Zaubergasse und bringt die Kappe zurück in seine Schließkiste. Sprecht danach mit Hüter Dierwert in Kirin\'Var.', },
  },
  [10308] = {
    'Noch ein Hügel voller Astraler',
    nil,
    nil,
  },
  [10309] = {
    'Teufelshäscher mit Herz',
    {'Seht Ihr den kaputten Teufelshäscher im Süden? Ist er nicht schön?|n|nIch möchte sein Herz!|n|nWas? Natürlich hat er ein Herz... wer hat denn keins?|n|n<N.D. sieht für einen kurzen Moment beleidigt aus.>|n|nGeht dort hinüber, öffnet ihn und bringt mir, was ich möchte, dann bekommt Ihr auch einen schönen Finderlohn.|n|nOh, und ich würde an Eurer Stelle ein oder zwei Freunde mitnehmen. Diese Astralen der Zaxxis sind eine ziemlich verschlagene Truppe!|n|nNehmt diesen Teufelsschocker, um seinem Herz einen Stromimpuls zu geben, wenn Ihr bereit seid, loszulegen.', },
    {'Besorgt das Herz des Teufelshäschers und bringt es zu N. D. Mieskamp beim Hügel im Nethersturm.', },
  },
  [10310] = {
    'Sabotage am Warptor!',
    {'Jetzt, da die Brennende Legion sich auf dem Trümmerfeld der Teufelshäscher in der Nähe befindet, müssen wir alles tun, um den Zuwachs der Dämonen in dieser Gegend aufzuhalten.|n|nSie haben ein Warptor im Süden in einer Gegend, die sie bezeichnenderweise Invasionspunkt: Zerstörer genannt haben.|n|nIch möchte, dass Ihr mit mir dorthin geht und mich beschützt, während ich das Tor sabotiere.|n|nGeht danach zum Mittelreichposten in der Biokuppel Mittelreich im Norden und meldet Gahruj unseren Erfolg.|n|nWir werden ein oder zwei Freunde von Euch für diesen Auftrag brauchen.', },
    {'Begleitet Drijya zum Warptor beim Invasionspunkt: Zerstörer und sorgt für seine Sicherheit, während er das Tor sabotiert. Sprecht danach mit Gahruj im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.', },
  },
  [10311] = {
    'Drijya braucht Eure Hilfe',
    {'$C, schön ein hilfreiches Gesicht hier zu sehen.|n|nDie Brennende Legion bei dem Teufelshäscherhügel hier in der Nähe wird immer mutiger, und ich mache mir Sorgen um unsere Sicherheit. Die Dämonen erhalten immer mehr Verstärkung aus dem Invasionspunkt: Zerstörer im Süden.|n|nMein Gefährte, Drijya, hat sich dorthin aufgemacht, um die Gegend zu erkunden und zu schauen, ob er etwas gegen die Warptore der Legion ausrichten kann.|n|nBitte findet ihn und helft ihm, wo Ihr könnt.', },
    {'Sprecht mit Drijya in der Nähe des Invasionspunkts: Zerstörer im Nethersturm.', },
  },
  [10312] = {
    'Die Annalen von Kirin\'Var',
    {'Die Geister zum Schweigen zu bringen hat leider nichts an Ihrer Aggressivität geändert. Die bösartigen Geister, die Ihr vernichtet habt, tauchen nun wieder in den Straßen des Dorfs auf.|n|nWir müssen herausfinden, was dahinter steckt. Die Zerstörung Kirin\'Vars war nur der Anfang, sonst hätten sich die Geister schon längst beruhigt.|n|nIm Rathaus im Süden von Kirin\'Var gibt es ein Stadtregister, in dem alle Einwohner eingetragen sind. Ich habe gehört, dass Kampfmagier Dathric es zuletzt hatte. Vielleicht trägt sein Geist es noch mit sich herum.', },
    {'Besorgt das Stadtregister von Kirin\'Var aus dem Rathaus von Kirin\'Var und bringt es zu Hüter Dierwert.', },
  },
  [10313] = {
    'Warpenergien messen',
    {'Wenn uns unser Instinkt nicht täuscht und diese Manaschmieden die Technologie der Festung der Stürme nutzen, könnte die ganze Scherbenwelt in großer Gefahr schweben.|n|nDie Energieauflademechanismen der Festung der Stürme waren niemals dafür gedacht, sie so nahe an bewohntem Land zu benutzen. Die Warpenergien könnten dieses Land zerstören, sogar wenn sie durch Kaels\' Rohrleitungen fließen.|n|nBringt diese Kugel zur Manaschmiede B\'naar. Sie ist so eingestellt, dass sie die Warpenergien messen kann. Benutzt sie an der Stelle, an der die Rohrleitungen in die Erde führen.', },
    {'Exarch Orelis in Area 52 möchte, dass Ihr die Warpmesskugel zur Manaschmiede B\'naar bringt und sie in der Nähe der vier Rohrleitungen benutzt.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eurer Ehre bei den Sehern.', },
  },
  [10314] = {
    'Ein hartnäckiger Verdacht',
    {'Das merkwürdige magische Gerät ähnelt nichts, was Ihr je zuvor gesehen habt. Es wurde mit Sicherheit nicht von Blutelfen hergestellt.|n|nAls Ihr bemerkt, dass die Geister sich näher an das Haus bewegen, stellt Ihr fest, dass die Kugel stärker zu leuchten beginnt, und wieder schwächer wird, als die Geister sich entfernen. Es steht außer Frage, dass sie mit der Beeinflussung der Geister in Verbindung steht.|n|nWie sie jedoch funktioniert, bleibt ein Geheimnis. Vielleicht kann Hüter Dierwert sich ja einen Reim darauf machen, wenn Ihr ihm die Überreste einiger Geister und Eure Beobachtungen zuteilwerden lasst.', },
    {'Sammelt 10 abscheuliche Überreste von den wahnsinnigen Geistern auf dem Kapellenhof in Kirin\'Var und bringt sie zu Hüter Dierwert.', },
  },
  [10315] = {
    'Die Nethermanten neutralisieren',
    {'Die Blutelfen sind Dummköpfe! Ich bin froh, dass unsere Handelsbeziehungen mit ihnen auseinander gebrochen sind. Auf all meinen Reisen durch den Kosmos habe ich nie so selbstsüchtige Wesen gesehen!|n|nSie zerstören weiterhin unser Land mit ihren Manaschmieden. Wollen wir mal schauen, ob wir ihnen bei der Manaschmiede Ara jenseits der Brücke Einhalt gebieten können.|n|nDie Nethermanten kanalisieren die Energie der Blutjuwelen, um den Energiefluss zu stabilisieren. Geht dort hin und löscht sie aus!', },
    {'Tötet 15 Nethermanten des Sonnenzorns und kehrt dann zu Netherpirscher Oazul auf Tulumans Landeplatz im Nethersturm zurück.', },
  },
  [10316] = {
    'Auf der Suche nach Beweisen',
    {'Wer auch immer hinter den Veränderungen der Geister stehen mag, hat seine Ziele mit Bedacht ausgewählt, und darauf geachtet, dass er zuerst die mächtigsten Magier erwischt. Aber warum? Die Magie, die eingesetzt wird, um die Geister der getöteten Kirin Tor zu beeinflussen, muss sehr mächtig sein.|n|nWarum würde ein mächtiger Magier all diese Mühen auf sich nehmen? Ich bin versucht zu glauben, dass dies ein weiterer teuflischer Plan von Kael\'thas ist, um hier weiteres Unheil anzurichten. Wenn es hier in der Nähe Blutelfen gibt, verstecken sie sich bestimmt in den Häusern hinter der überdachten Brücke.', },
    {'Durchsucht die Häuser auf dem Kapellenhof von Kirin\'Var nach Hinweisen darauf, wer sich hinter der Beeinflussung der Geister verbirgt.', },
  },
  [10317] = {
    'Den Großknecht erledigen',
    {'Die Blutelfen nennen die Mine unter der Manaschmiede Ara Trelleummine. Seit sie die Mine unter der Manaschmiede Ultris verloren haben, ist sie der einzige Ort, von dem sie den Nachschub zum Betrieb ihrer Schmieden bekommen.|n|nIch brauche nicht zu erwähnen, dass es ein großer Vorteil für uns wäre, wenn wir ihre Bergbauaktivitäten dort verhindern könnten. Vielleicht könnten wir sogar dort einfallen und die Mine für uns selbst nutzen?|n|nWie auch immer, ich möchte, dass Ihr Euch um Großknecht Sonnenend kümmert. Die Mine befindet sich am hinteren Ende der Insel links von uns.', },
    {'Vernichtet Großknecht Sonnenend in der Trelleummine, die sich unter der Manaschmiede Ara im Nethersturm befindet.', },
  },
  [10318] = {
    'Den Übermeister erledigen',
    {'Ich war früher hier der Großknecht. Aber jetzt, da ich degradiert wurde, geht mir auf, dass unsere ganze Pilgerreise von Quel\'Thalas in die Scherbenwelt eine einzige Lüge war!|n|nEine Lüge, die von Kael\'thas eingefädelt wurde, um seine Streitkräfte hier im Nethersturm zu stärken.|n|nIch habe versucht, meine Brüder davon zu überzeugen, dass wir fortgehen sollten, besonders wegen der Brennenden Legion, aber sie sind alle zu stur.|n|nKönnt Ihr mir einen Gefallen tun? Tötet Übermeister Grindgarr. Kehrt dann zu Eurem Astralen zurück und sagt ihm, dass ich kein Feind mehr bin.', },
    {'Tötet Übermeister Grindgarr. Kehrt dann zu Windhändler Tuluman auf Tulumans Landeplatz im Nethersturm.', },
  },
  [10319] = {
    'Das Phylakterium entwenden',
    {'Ich glaube, es wird Zeit für eine Erklärung. Ihr habt einen der Lehrlinge des Erzmagiers getroffen, Ravandwyr. Es gab jedoch noch einen weiteren mit dem Namen Naberius.|n|nEr war ein sehr fleißiger Schüler, hegte aber großes Interesse an der Nekromantie. Als Kael\'thas mit seinen Streitmächten auftauchte, nutzte Naberius die Gelegenheit, um den Erzmagier zu verraten und die geheimen Verteidigungsmechanismen des Turms preiszugeben.|n|nJetzt, so scheint es, ist er zu einem Lich geworden. Wenn wir ihn aufhalten wollen, müssen wir uns sein Phylakterium besorgen. So wie ich ihn kenne, hat er es sicher irgendwo in seinem Gebiet sicher vergraben.', },
    {'Holt Naberius\' Phylakterium vom Kapellenhof in Kirin\'Var und bringt es zu Hüter Dierwert.', },
  },
  [10320] = {
    'Vernichtet Naberius!',
    {'Erzmagier Vargoth hat die Gefahr in Naberius\' Interesse an der Nekromantie erkannt, aber ich bin mir sicher, dass er niemals geglaubt hätte, dass sein Lehrling den Kirin Tor so viel Schaden zufügen würde.|n|nIhr müsst ihn besiegen, $N, sonst wird er weiterhin die Geister unserer gefallenen Brüder versklaven, sie ihrer Ruhe berauben und das letzte bisschen, was noch von Kirin\'Var übrig ist, zerstören.|n|nOhne sein Phylakterium kann er mit den vereinten Kräften von zwei oder drei Kämpfern vernichtet werden, aber wer weiß, was seine Magie mehr Gegnern gegenüber anrichten könnte?', },
    {'Hüter Dierwert in Kirin\'Var möchte, dass Ihr Naberius auf dem Kapellenhof des Dorfes besiegt.', },
  },
  [10321] = {
    'Manaschmiede Coruu abschalten',
    {'Euer Erfolg in B\'naar hat und sehr große Hoffnung gemacht, $N.|n|nWir haben unsere Entdeckungen den Sehern mitgeteilt, und sie haben uns im Gegenzug mehr Informationen über die übrigen Manaschmieden gegeben.|n|nEs stehen immer noch drei weitere Manaschmieden, die von der Armee des Sonnenzorns kontrolliert werden.|n|nDie Manaschmiede Coruu findet Ihr im Osten. Vorarbeiterin Seylanna ist dort im Besitz des Zugangskristalls. Besorgt ihn und schaltet damit die Steuerungskonsole ab.|n|nWir zählen auf Euch, $N.', },
    {'Reist zur Manaschmiede Coruu, östlich von Area 52, und besorgt den Zugangskristall von Coruu von Vorarbeiterin Seylanna. Benutzt ihn, um die Manaschmiede abzuschalten, und kehrt dann zu Anachoret Karja zurück.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10322] = {
    'Manaschmiede Duro abschalten',
    {'Wir haben Neuigkeiten von einer der Manaschmieden, die noch in Betrieb sind, erhalten. Die Armee des Sonnenzorns ist im Begriff, die Kontrolle über die Manaschmiede Duro zu verlieren.|n|nWegen ihrer erhöhten Energieproduktion werden ganze Schwärme von Manakreaturen von ihr angelockt - die Manaschmiede versinkt im Chaos.|n|nEine Explosion von Duro könnte eine Kettenreaktion auslösen, die die ganze Scherbenwelt in Gefahr bringen würde. Vorarbeiter Athanel ist im Besitz des Zugangskristalls, mit dem Ihr die Manaschmiede abschalten könnt.', },
    {'Anachoret Karja möchte, dass Ihr zur Manaschmiede Duro geht und den Zugangskristall von Vorarbeiter Athanel besorgt. Benutzt ihn, um die Steuerungskonsole von Duro abzuschalten.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10323] = {
    'Manaschmiede Ara abschalten',
    {'Nur noch eine Manaschmiede hält die Festung der Stürme in Betrieb. Nachdem wir die Manaschmiede Ara abgeschaltet haben, muss sich Kael mit seinen gespeicherten Energien zufrieden geben.|n|nReist zur Manaschmiede Ara im Nordwesten und gebt Kael den Rest, indem Ihr sie abschaltet.|n|nDer letzte Zugangskristall befindet sich im Besitz von Vorarbeiter Azarad. Seid jedoch vorsichtig; wir erwarten heftigen Widerstand in Kaels letzter funktionierender Schmiede. Ihr werdet wahrscheinlich die Unterstützung einiger Freunde brauchen.', },
    {'Reist zur Manaschmiede Ara und besorgt Euch einen Zugangskristall von Vorarbeiter Azarad. Benutzt ihn, um die Steuerungskonsole von Ara abzuschalten.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10324] = {
    'Die große Mondweidenjagd',
    {'Gut gemacht, $N! Gut gemacht!|n|nJetzt, da Ihr Euch die Hörner an den Mondweidenhirschen abgestoßen habt, ist es an der Zeit, dass Ihr Euch einer würdigeren Beute zuwendet. Lasst Euch von der Gelassenheit der Mondweidenböcke nicht täuschen, wenn sie sich provoziert fühlen, sind sie ein gefährlicher Gegner.|n|nIhr findet die Böcke nördlich von hier. Weidmannsheil.', },
    {'Bringt 6 Bälge eines Mondweidenbocks zu Acteon in der Azurwacht.', },
  },
  [10325] = {
    'Male von Kil\'jaeden',
    {'Wie Ihr vielleicht wisst, $N, sind die Aldor die Hüter des Lichts und die Diener der Naaru.|n|nUns direkt gegenüber stehen die Agenten der Brennenden Legion - Dämonen, die die Welten zerstören und die Unschuldigen verderben wollen.|n|nWenn Ihr Euch den Aldor gegenüber beweisen wollt, bringt mir die Insignien der niederrangigen Mitglieder der Legion und ihrer Anhänger des Schattenrats. Uns ist ein Versteck des Schattenrats in der Knochenwüste bekannt. Die Lager der Legion findet Ihr in Nagrand und dem Schergrat.', },
    {'Bringt 10 Male von Kil\'jaeden zu Adyen dem Lichtwächter in Shattrath.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10326] = {
    'Mehr Male von Kil\'jaeden',
    nil,
    nil,
  },
  [10327] = {
    'Einzelne Male von Kil\'jaeden',
    nil,
    nil,
  },
  [10328] = {
    'Anweisungen des Sonnenzorns',
    {'Etwas an diesen Manaschmieden bereitet mir Kopfzerbrechen, $N. Die Naarutechnologie ist sehr fortschrittlich; Kael\'thas hätte Jahre brauchen müssen, um sie auch nur im Ansatz zu verstehen.|n|nDas Sammeln von Informationen zu diesem Thema ist sehr schwierig, da Kaels Armee sehr diszipliniert ist und jegliche schriftliche Kommunikation sofort vernichtet.|n|nWir haben gehört, dass die Manaschmiede Duro von Manakreaturen angegriffen wird. Vielleicht haben die Verteidiger ihre Anweisungen noch nicht zerstört. Besorgt sie Euch und bringt sie zu mir.', },
    {'Reist zur Manaschmiede Duro und beschafft die Truppenbefehle des Sonnenzorns und die Arkanbefehle des Sonnenzorns von den Einheiten des Sonnenzorns, die dort postiert sind. Kehrt zu Exarch Orelis zurück, wenn Ihr Eure Aufgabe erledigt habt.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10329] = {
    'Manaschmiede B\'naar abschalten',
    {'Während Ihr fort wart, hatte ich eine freundliche Diskussion mit den Aldor. Die Manaschmieden bestehen aus der Naarutechnologie der Festung der Stürme. Offensichtlich gibt es bei dieser Technologie Mechanismen, die ein dauerhaftes Abschalten im Notfall ermöglichen.|n|nAlles, was wir brauchen, um diesen Vorgang einzuleiten, ist ein Zugangskristall zur Steuerungskonsole. Der praktischen Stammrolle, die Ihr uns gebracht habt, nach, befinden sich die Kristalle im Besitz eines Typen namens Vorarbeiter Theredis. Besorgt ihn und schaut, was Ihr tun könnt.', },
    {'Geht zurück zur Manaschmiede B\'naar und besorgt Euch den Zugangskristall von Vorarbeiter Theredis. Benutzt ihn bei der Steuerungskonsole von B\'naar um sie abzuschalten und meldet Euch danach bei Spionagemeister Thalodien zurück.|n|nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10330] = {
    'Manaschmiede Coruu abschalten',
    {'Thalodien hat uns von Eurem Erfolg beim Abschalten der Manaschmiede B\'naar erzählt. Er erwartet, dass Ihr Eure Leistung hier wiederholt und hat uns gebeten, ein Auge darauf zu haben, wer einen Kristall benutzt, um Zugang zu der Konsole im Inneren zu erhalten. Vorarbeiterin Seylanna hat den Zugangskristall, da sind wir uns sicher.|n|nGeht hinein und vollendet das Werk. Es besteht kein Grund zur Heimlichkeit mehr. Besorgt Euch den Kristall, schaltet die Konsole ab, tötet alle Techniker, die Euch daran hindern wollen, und macht Euch dann aus dem Staub.|n|nBeeilt Euch, Kaels Spürhunde kommen uns sicher bald auf die Schliche.', },
    {'Besorgt den Zugangskristall von Coruu von Vorarbeiterin Seylanna. Benutzt ihn, um die Steuerungskonsole der Manaschmiede abzuschalten und meldet Euch dann bei Caledis Morgenhell.|n|nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10331] = {
    'Unverzichtbare Werkzeuge',
    {'Ihr habt hier nicht zufällig einen schweren Schmiedehammer herumliegen sehen, oder? Ich habe ihn hierher mitgenommen, um ein paar Hufeisen für das Pferd des alten Amorlin fertig zu stellen, aber ich kann ihn nicht finden.|n|nIch habe die ganze Scheune mindestens ein dutzend Mal abgesucht, aber ohne Erfolg. Vielleicht hat einer der anderen Lehrlinge ihn gefunden und ihn zurück zur Schmiede gebracht? Könntet Ihr für mich dorthin gehen und danach suchen? Sie befindet sich südöstlich des Turms auf dem Ratsplatz.', },
    {'Besorgt den Schmiedehammer von den Lehrlingen von Kirin\'Var und bringt ihn zurück zu Lehrling Andrethan in Kirin\'Var.', },
  },
  [10332] = {
    'Meisterschmied Rhonsus',
    {'Endlich ist mein Gesellenstück fertig! Ich kann es kaum abwarten, es Meister Rhonsus zu zeigen.|n|n<Der Lehrling schaut Euch an, als Ihr ihm erzählt, was passiert ist, als Ihr den Hammer zurückholen wolltet.>|n|nSie haben Euch angegriffen? Alle? Beim Licht, sie sind verrückt geworden!|n|nWas sollen wir tun, $N? Es schmerzt mich, das zu sagen, aber vielleicht müssen wir Meister Rhonsus umbringen. Dann wäre ich der einzige Schmied in Kirin\'Var, aber ich denke, dass meine Ausbildung ausreicht, um die Bedürfnisse des Dorfs zu befriedigen.', },
    {'Lehrling Andrethan in Kirin\'Var möchte, dass Ihr den Geist von Rhonsus, dem Meisterschmied des Dorfes, vernichtet.', },
  },
  [10333] = {
    'Helft Mama Mauschel',
    {'Sagt mal, $N, ich habe mich gefragt, ob Ihr mir noch einen Gefallen tun könntet.|n|nMeine Partnerin da draußen im Feld könnte sicher etwas Hilfe gebrauchen. Könnt Ihr ihr vielleicht helfen?|n|nIch bin sicher, dass Mama Mauschel dafür sehr dankbar wäre. Kümmert Euch nicht um ihre scharfe Zunge.|n|nSie bemüht sich um unsere Interessen im Osten. Ihr findet sie in der Biokuppel Mittelreich beim Mittelreichposten.', },
    {'Sprecht mit Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm.', },
  },
  [10334] = {
    'Braucht mehr Kuhglocke',
    {'Wo, oh, wo ist meine Bessy? Nach dem Angriff habe ich die Felder und den Kapellenhof nach Ihr abgesucht, aber ich konnte sie nicht finden!|n|nAlles, was ich von ihr noch habe, ist diese alte Kuhglocke. Normalerweise kommt sie gleich gerannt, wenn sie sie hört, aber vielleicht können diese alten Hände sie nicht stark genug läuten.|n|nIch leihe Euch Bessys Glocke, wenn Ihr hinaus auf die Felder geht und sie so fest Ihr nur könnt läutet. Vielleicht wartet Bessy einfach nur auf ein wenig mehr Kuhglocke.', },
    nil,
  },
  [10335] = {
    'Die Ruinen beobachten',
    {'Ich muss in die Ruinen von Farahlon gehen, um meine Ausgrabungen zu beginnen! Das Problem ist, dass dieser Ort von Dämonen heimgesucht wird.|n|nVielleicht könntet Ihr schon einmal ein wenig Vorarbeit für mich leisten?|n|nEs gibt drei Orte in den Ruinen im Nordosten, an dem Ihr für mich Vermessungsmarkierungen aufstellen sollt. Jede befindet sich in der Nähe eines Draeneibanners.|n|nKehrt zu mir zurück, wenn Ihr alle drei Markierungen erfolgreich aufgestellt habt.', },
    {'Platziert die drei Vermessungsmarkierungen und kehrt dann zu Zephyrion in der Sturmsäule im Nethersturm zurück.', },
  },
  [10336] = {
    'Diener von Culuthas',
    {'Vor ein paar Wochen hat die Brennende Legion in den Ruinen von Farahlon Einzug gehalten und damit all unsere Pläne, die Artefakte dort auszugraben, zunichtegemacht.|n|nDann habe ich heute erfahren, dass einer ihrer Schreckenslords, Culuthas, aus irgendeinem Grund alle anderen Mitglieder der Brennenden Legion dort getötet hat. Seitdem ruft er Dämonen, die ihm dienen.|n|n$C, ich möchte, dass Ihr zu den Ruinen im Nordosten geht und die Dämonen vernichtet!', },
    {'Tötet 10 Hunde von Culuthas und 5 Augen von Culuthas', },
  },
  [10337] = {
    'Almabtrieb',
    {'Als Ihr merkt, dass Bessy Euch immer noch anstarrt, deutet Ihr nach Westen, zu dem Ort, an dem Thadell sich befindet. Ihr erwischt Euch selbst dabei, wie Ihr der Kuh versprecht, sie auf ihrem Nachhauseweg zu beschützen. Als Ihr Euren Satz beendet habt, wird Euch klar, dass die Kuh gar nicht verstehen kann, was Ihr sagt.|n|nMit einem Schulterzucken bereitet Ihr Euch darauf vor, das Rindvieh zu Thadell zurückzubegleiten.', },
    {'Begleitet Bessy sicher zu ihrem Besitzer Thadell zurück.', },
  },
  [10338] = {
    'Manaschmiede Duro abschalten',
    {'Die Manaschmiede Duro wird also angegriffen und die Streitkräfte des Sonnenzorns haben die Kontrolle verloren? Was für ein Dilemma! Wenn Duro fällt, fällt die Festung der Stürme. Der einzige Nachteil ist... wenn die Festung der Stürme zerstört wird, wird die Explosion wahrscheinlich die kläglichen Überreste dieses verlassenen Landes mit sich reißen.|n|nKael\'thas Tod ist gut. Jedermanns Tod ist... nicht so gut, glaube ich. Es schmerzt mich, Euch darum zu bitten, aber geht zur Manaschmiede Duro und schaltet sie ab, bevor sie in Flammen aufgeht. Vorarbeiter Athanel hat den Zugangskristall.', },
    {'Kehrt zur Manaschmiede Duro zurück und besorgt Euch den Zugangskristall von Vorarbeiter Athanel. Benutzt ihn, um die Steuerungskontrolle von Duro abzuschalten und meldet Euch danach bei Spionagemeister Thalodien.|n|nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10339] = {
    'Das Astraleum',
    {'Direkt südlich von hier findet Ihr den Stützpunkt des Astraleums. Das Astraleum bereitet sich dort auf irgendetwas vor... Vielleicht einen Angriff auf Ultris.|n|nWir können jedoch nichts dem Zufall überlassen, $C. Durchbrecht ihre Verteidigung und zerstört ihr Trainingslager.|n|nSobald Ihr ihre Soldaten und Hauptmann Zovax vernichtet habt, sucht den Transponder des Astraleums Zeta und benutzt ihn, um mit mir Kontakt aufzunehmen. Dann werdet Ihr Eure neuen Befehle erhalten.', },
    {'Kommandant Ameer möchte, dass Ihr 5 Auftragsmörder des Astraleums, 5 Stoßtruppsoldaten des Astraleums, 2 Forscher des Astraleums und Hauptmann Zovax tötet und dann den Transponder des Astraleums Zeta aktiviert.', },
  },
  [10340] = {
    'Trümmerposten',
    {'$N, Ihr habt gute Arbeit hier an der Front geleistet und großes Talent mit den gepanzerten Greifen bewiesen... Ich glaube, ich habe eine weitere Aufgabe für Euch.|n|nStartpunkt für Eure neue Mission ist der Trümmerposten, eine Angriffsbasis der Wildhämmer auf einer schwebenden Insel in der Nähe des Portals. Es ist etwas anstrengend dort, aber Ihr habt starke Nerven. Ihr packt das schon.|n|nSprecht mit Schwadronskommandant Dabir\'ee und lasst Euch von ihm zum Trümmerposten schicken. Meldet Euch dann bei Greifenmeister Runetog Wildhammer.', },
    {'Vorpostenkommandant Königstein möchte, dass Ihr mit Schwadronskommandant Dabir\'ee sprecht, auf einem Greifen zum Trümmerposten fliegt und Euch bei Runetog Wildhammer meldet.', },
  },
  [10341] = {
    'Tretet sie, solange sie am Boden liegen',
    {'Das sind günstige Nachrichten, die Ihr bringt, $N. Ihr könnt nicht nur ungehindert in die Manaschmiede Duro reinspazieren, es eröffnet sich auch noch eine großartige Gelegenheit, Kaels Armee einen Schlag zu versetzen.|n|nNutzt den Angriff der Manakreaturen und vernichtet alle Nachzügler des Sonnenzorns, die Euch in die Arme laufen.|n|nIch habe keinen besonderen Spaß daran, mein eigenes Volk abzuschlachten, wie Tahlodien, aber diesen taktischen Vorteil dürfen wir nicht ungenutzt vorübergehen lassen.', },
    {'Tötet 8 Beschwörer des Sonnenzorns, 6 Jagdschützen des Sonnenzorns und 4 Zenturios des Sonnenzorns. Kehrt zu Magister Larynna in Area 52 zurück, wenn Ihr die Aufgabe erledigt habt.|n|nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10342] = {
    'Schieferhautschiefer',
    {'Ich verdiene gut daran, den Trunkenbolden hier Getränke zu verkaufen. Aber ich will mehr!|n|nDer Raketenchef sagt mir immer, dass er den Raketentreibstoff, den er braucht, um die X-52 abheben zu lassen, nicht verbessern kann.|n|nWir können dieses kleine Problem für ihn lösen.|n|nZuerst muss ich das Öl aus dem Schiefer der hiesigen Schieferhautschinder pressen. Daraus mache ich einen konzentrierten, wenn auch leicht entzündlichen, Grundstoff für die Mischung, die mir vorschwebt.|n|nSucht die Schinder und ihren Schiefer! Sie sind überall bei den violetten Felsen.', },
    {'Sammelt 5 Stück Schieferhautschiefer und bringt sie zu Stiefels in Area 52 im Nethersturm.', },
  },
  [10343] = {
    'Die unendliche Invasion',
    {'Kael\'thas Angriff auf Kirin\'Var begann mit einem donnernden Geräusch und einem hellen Lichtblitz im Offiziersquartier im Nordwesten. Die Zerstörung war dort am größten. Nach dem Rückzug der Blutelfen geschah etwas Merkwürdiges.|n|nWesen aus reinem Mana begannen, von überall her in das Dorf zu strömen. Bis jetzt versuchen wir, sie so gut es geht im Zaum zu halten, aber ich hoffe, dass wir den Ansturm komplett abwehren können, wenn wir mehr über die Waffe in Erfahrung bringen, die Kael\'thas benutzt hat.', },
    {'Sucht die von Manakreaturen heimgesuchte Gegend in Kirin\'Var nach einem Manabombenfragment ab und bringt sie zu Zaubererleutnant Morran.', },
  },
  [10344] = {
    'Schwadronskommandant Greifgar',
    {'Schwadronskommandant Greifgar hat die Leitung über die Wildhämmer hier. Wenn Ihr zum ersten Mal im Trümmerposten seid, solltet Ihr Euch bei ihm melden.|n|nIhr findet ihn in den Überresten des Turms da drüben.', },
    {'Sprecht mit Schwadronskommandant Greifgar im Trümmerposten.', },
  },
  [10345] = {
    'Fleisch geworden',
    {'Seht Ihr diese Leichen, $R? Arconus ist für diese Massaker verantwortlich. Er hat sie ausgesaugt, sodass nur noch eine Fleischhülle übrig geblieben ist. Aber lasst Euch von den Körpern nicht täuschen! In diesen Leichen liegen Fleischbestien, die nur darauf warten, ahnungslose Dummköpfe, die sich zu nahe heranwagen, anzufallen.|n|nIch habe meine Befehle. Ich muss hierbleiben, bis meine Verstärkung eintrifft. Das bedeutet aber nicht, dass Ihr nicht meinen Anzünder nehmen und die siechenden Leichen, die überall in den Minen herumliegen, zerstören könnt. So oder so muss diese Aufgabe erledigt werden.', },
    {'Benutzt den Anzünder des Protektorats um 12 siechende Leichen zu zerstören. Bringt den Anzünder des Protektorats zu Agent Araxes außerhalb des Zugangsschachts Zeon zurück, wenn Ihr erfolgreich wart.', },
  },
  [10346] = {
    'Rückkehr zur Abyssischen Untiefe',
    {'$N, Ihr habt Euch als fähiger Greifenreiter bewiesen. Wir könnten Euch für weitere Einsätze bei der Abyssischen Untiefe brauchen. Was sagt Ihr, $C? Wollt Ihr noch ein paar Flugstunden sammeln?', },
    {'Greifnerin Heulwind im Expeditionsposten auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan\'arg, 5 Vorarbeiter der Mo\'arg und 5 Teufelskanonen zerstört.', },
  },
  [10347] = {
    'Rückkehr zur Abyssischen Untiefe',
    {'$N, seid Ihr bereit für einen weiteren Flug zu Abyssischen Untiefe? Ich fürchte, dass uns die Dämonen der Legion von Norden her angreifen werden, wenn wir sie nicht weiter unter Druck setzen und zulassen, dass sie Ihre Festung verstärken.|n|nWas sagt Ihr, $N? Habt Ihr Lust, Euch erneut auf einen Windreiter zu schwingen und zur Abyssischen Untiefe zu fliegen?', },
    {'Schwadronskommandant Brack im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan\'arg, 5 Vorarbeiter der Mo\'arg und 5 Teufelskanonen zerstört.', },
  },
  [10348] = {
    'Neue Möglichkeiten',
    {'Ich habe gehört, dass eine Gruppe von \'Druiden\' aus Azeroth sich für die Wirkung unserer Biokuppeltechnologie interessiert.|n|nDie Expedition des Cenarius ist sehr begierig darauf, Zugang zu den Pflanzen in den Kuppeln zu erlangen, besonders zu der einen, die sie Elfenbeinglocke nennen, und die für ihre heilenden Kräfte bekannt ist. Sie wächst in der Biokuppel Mittelreich in kleinen Büschen um größere Pflanzen herum.|n|nIch teile den Gewinn mit Euch, wenn Ihr mir ein paar der Kräuter für meine erste Lieferung sammelt.', },
    {'Sammelt 15 Elfenbeinglocken und kehrt dann zu Mehrdad im Mittelreichposten zurück.', },
  },
  [10349] = {
    'Die Erdbinderin',
    {'Ihr solltet dieses Kristallstück zur Erdbinderin bringen. Sie ist wie Ihr... immer muss sie einem Geheimnis auf die Spur kommen und darüber nachgrübeln.|n|nWenn Ihr mich fragt, denkt sie zu viel.|n|nGebt ihr den Kristall und ich bin sicher, dass sie Euch beim Versuch herauszufinden, was im Grat vor sich geht, in ganz schöne Schwierigkeiten bringen wird.', },
    {'Bringt den Purpurkristallsplitter zu Erdbinderin Galandria Nachtluft im Posten des Cenarius auf der Höllenfeuerhalbinsel.', },
  },
  [10350] = {
    nil,
    {'Ihr habt viele harte Lektionen in unserer Zeit zusammen von mir gelernt, doch nun ist es an der Zeit, dass ich Euch in weisere Hände übergebe.|n|nBehomat, der mich ausbildete, als ich noch grün wie Gras hinter den Ohren war, wird Euer neuer Lehrer sein. Ich habe ihm gesagt, dass ich Euch zu ihm schicken werde, er erwartet Euch also.|n|nIhr findet ihn in der Mitte der Terrasse der Krieger, am höchsten Punkt der Händlertreppe der Exodar.', },
    {'Sprecht mit Behomat bei der Händlertreppe in der Exodar.', },
  },
  [10351] = {
    'Natürliche Heilmittel',
    {'Es müssen die bösen Strahlungen von dem riesigen roten Kristall sein, die die Bergriesen herbeirufen und sie wahnsinnig machen.|n|nEr ist zu groß, um ihn weg zu bringen, und unsere Fertigkeiten reichen nicht aus, um ihn zu zerstören, aber mir ist ein Weg eingefallen, wie wir seine Macht bezwingen können.|n|nIch habe einen Zirkel beim nordwestlichen Ende des Kristalls auf dem Grat beschworen. Bringt diesen Samen dorthin und setzt seine Macht ein, um das Land durch die natürlichen Kräfte des Regens, des Wachstums und der Insekten zu heilen.|n|nSeid vorsichtig, $N. Ich spüre, dass hier eine außenstehende Macht am Werk ist... und sie ist nicht natürlich!', },
    {'Benutzt den Samen der Wiederbelebung beim Zirkel des Erdbinders, um das Land um den Kristall herum zu heilen. Kehrt dann zu Erdbinderin Galandria Nachtluft im Posten des Cenarius auf der Höllenfeuerhalbinsel mit Euren Beobachtungen zurück.', },
  },
  [10352] = {
    'Spendet Wolle',
    nil,
    nil,
  },
  [10353] = {
    'Arconus der Unersättliche',
    {'Araxes und ich wurden vor zwei Tagen nach Ultris geschickt. Unser Auftrag: findet und vernichtet den Leerenfürsten Arconus. Wir haben ihn bis zu seiner Mine verfolgt und herausgefunden, dass er sich von den Energien der Kreaturen in dieser Gegend ernährt.|n|nEs brach ein Feuerwechsel aus, bei dem Araxes und ich getrennt wurden. Jetzt bin ich hier gefangen und schwer verletzt. Unser Auftrag ist dahin!|n|nWenn Ihr Arconus erledigen könntet, wäre die oberste Führung Euch sehr dankbar. Wenn Ihr den Auftrag annehmt, werde ich Euch eine Reflexion meiner selbst als Wächter mitschicken.', },
    {'Agent Sechs-Uhr beim Zugangsschacht Zeon im Nethersturm möchte, dass Ihr Arconus den Unersättlichen tötet und dann zu Kommandant Ameer im Wachposten des Protektorats im Nethersturm zurückkehrt.', },
  },
  [10354] = {
    'Spendet Seide',
    nil,
    nil,
  },
  [10355] = {
    'Siechendes Fleisch',
    {'Wir müssen herausfinden, wie weit der Schaden reicht. Das Basidium, das Ihr mir gebracht habt, stammt von einem Sumpfriesen. Ihre größeren, zäheren Vettern, die Sumpflords, sollten der Degenerierung, die die Riesen befallen hat, gegenüber unempfindlicher sein.|n|nEs wäre auch schön zu wissen, inwiefern die Veränderungen die anderen Kreaturen des Todesmoors betroffen haben.|n|nKehrt zum Todesmoor zurück und schaut, ob Ihr Proben von den Sumpflords und Hydras in der Gegend sammeln könnt.', },
    {'Sammelt 5 Proben einer verdurstenden Hydra und 5 Proben eines siechenden Sumpflords und bringt sie zu Ruam in Telredor.', },
  },
  [10356] = {
    'Spendet Magiestoff',
    nil,
    nil,
  },
  [10357] = {
    'Spendet Runenstoff',
    nil,
    nil,
  },
  [10358] = {
    'Noch mehr Runenstoff',
    nil,
    nil,
  },
  [10359] = {
    'Spendet Wolle',
    nil,
    nil,
  },
  [10360] = {
    'Spendet Seide',
    nil,
    nil,
  },
  [10361] = {
    'Spendet Magiestoff',
    nil,
    nil,
  },
  [10362] = {
    'Spendet Runenstoff',
    nil,
    nil,
  },
  [10363] = {
    'Noch mehr Runenstoff',
    nil,
    nil,
  },
  [10364] = {
    nil,
    {'Ihr seid in kurzer Zeit sehr weit gekommen, $N. Schneller, als ich erwartet oder gehofft hätte. Es ist an der Zeit, dass Ihr Eure Ausbildung unter der Anleitung meines Meisters, Caedmos, fortsetzt.|n|nIch habe ihm gesagt, dass er Euch in der Exodar erwarten soll. Ihr findet ihn im Sanktum der Anachoreten in der Nähe des Eingangs zur Halle des Lichts.', },
    {'Sprecht mit Caedmos in der Halle des Lichts der Exodar.', },
  },
  [10365] = {
    'Manaschmiede Ara abschalten',
    {'Ihr habt Eure Arbeit besser erledigt, als wir dachten. Die Manaschmiede Ara ist die letzte von Kaels Schmieden, die noch in Betrieb ist. Ihr findet sie nordwestlich von hier, aber Ihr müsst wahrscheinlich um sie herumgehen, um dorthin zu gelangen. Wir möchten, dass Ihr sie abschaltet.|n|nDer letzte Zugangskristall befindet sich im Besitz von Vorarbeiter Azarad. Seid jedoch vorsichtig; wir erwarten heftigen Widerstand in Kaels letzter funktionierender Schmiede. Ihr werdet wahrscheinlich die Unterstützung einiger Freunde brauchen.|n|nHmm... Azarad. Was ein komischer Name für einen Sin\'dorei.', },
    {'Reist zur Manaschmiede Ara und besorgt Euch einen Zugangskristall von Vorarbeiter Azarad. Benutzt ihn, um die Steuerungskonsole von Ara abzuschalten.|n|nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10366] = {
    nil,
    {'Der Pfad des Lichts und der Reinheit ist steinig, $N. Sogar ich habe manchmal Probleme, ihm zu folgen.|n|nIhr solltet meine Meisterin, Jol, in der Exodar aufsuchen. Sie hat mich zu Beginn meiner Reise ausgebildet. Ich bin mir sicher, dass sie in Euch ihren neuen Lieblingsschüler finden wird.|n|nIhr findet Jol in der Halle des Lichts in der Exodar beim Sanktum der Verteidiger, einem Raum, der von einem pulsierenden Lichtschein umgeben ist.', },
    {'Sprecht mit Jol im Sanktum der Verteidiger in der Exodar.', },
  },
  [10367] = {
    'Ein Verräter unter uns',
    {'Wo immer ihr einen Stamm von versklavten Zerschlagenen seht, könnt Ihr auch einen Verräter finden. Ein verachtungswürdiges Wesen, das seine Brüder für das Versprechen von Macht verkauft hat.|n|nOben an der Treppe in der Mitte der Ruinen könnt Ihr eine Hütte finden. Das ist die Hütte des Verräters.|n|nEr ist im Augenblick nicht dort, Ihr könnt Euch also hineinschleichen, wenn Ihr Geduld habt. Innen findet Ihr einen Kasten mit einem Schlüssel darin. Dieser Schlüssel passt zu den Ketten, die die Ältesten des Lumpenpacks gefangen halten. Bringt ihn mir.|n|nSeid jedoch vorsichtig, Arzeth der Erbarmungslose treibt sich in der Nähe herum.', },
    {'Naladu in den Ruinen von Sha\'naar möchte, dass Ihr den Schlüssel von Sha\'naar aus einer Hütte in der Nähe besorgt.', },
  },
  [10368] = {
    'Die Ältesten des Lumpenpacks',
    {'Der Geist des Lumpenpacks ist gebrochen, weil sich unsere Ältesten in Gefangenschaft befinden. Nehmt diesen Schlüssel und befreit sie.|n|nEs sind Morod der Windtreiber, Akoru der Feuerrufer und Aylaan der Wasserrufer. Sobald sie frei sind, werden die Geister zum Stamm des Lumpenpacks zurückkehren.', },
    {'Befreit Morod den Windtreiber, Akoru den Feuerrufer und Aylaan den Erderwecker aus den Ruinen von Sha\'naar. Kehrt zu Naladu zurück, wenn Ihr diese Aufgabe erledigt habt.', },
  },
  [10369] = {
    'Arzeths Untergang',
    {'Ja, die Elementargeister sind zu uns zurückgekehrt! Wir sind nicht mehr so stark wie einst, aber auch geringe Magie kann in den richtigen Händen weit reichen.|n|nArzeth wurde von seinem dunklen Herrn große Macht verliehen. Nehmt diesen Stab. Er war einst ein großartiges Symbol unseres Volkes. Setzt ihn gegen Arzeth ein, und seine Macht wird für kurze Zeit verschwinden. Besiegt ihn, damit mein Volk endlich frei sein kann!', },
    {'Benutzt den Ältestenstab des Lumpenpacks gegen Arzeth den Erbarmungslosen und tötet ihn, nachdem er seine Macht verloren hat. Kehrt danach zu Naladu in den Ruinen von Sha\'naar zurück.', },
  },
  [10370] = {
    'Nazgrels Befehl',
    nil,
    nil,
  },
  [10371] = {
    'Yorus Gerstenbräu',
    {'Ein Zwergenkrieger namens Yorus Gerstenbräu hat eine Herausforderung für alle tüchtigen Krieger der Allianz verkündet.|n|nEr wartet im Gasthaus von Seenhain, im sogenannten Rotkammgebirge in den Östlichen Königreichen. Es wird eine lange Reise, aber sie lohnt sich, wenn Ihr Euch selbst testen wollt, $N.', },
    {'Sprecht mit Yorus Gerstenbräu.', },
  },
  [10372] = {
    'Eine diskrete Anfrage',
    {'Eralan, eine Verbündete von mir in Tristessa, hat angefragt, ob ihr jemand bei einem eiligen Auftrag helfen könnte.|n|nIch weiß nicht, was sie vorhat, denn ich stelle keine Fragen, aber Ihr habt Euch mehr als fähig erwiesen. Ich möchte, dass Ihr nach Tristessa in den Geisterlanden reist, und mit Eralan sprecht.|n|nSie mag vielleicht ein wenig ruppig sein, aber man kann ihr vertrauen.', },
    {'Sprecht mit Eralan in Tristessa.', },
  },
  [10373] = {
    'Der Ruf zu den Waffen: Die Pestländer!',
    {'Hört her, hört her! Alle Helden werden ersucht, aufzumerken!|n|nDas Königreich Sturmwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der Östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!|n|nHelden der Welt... Sucht Kommandant Ashlam Ehrenschlag auf, der seinen Stützpunkt an der Zugwindspitze errichtet hat, nördlich des Alteracgebirges!', },
    {'Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich an der Zugwindspitze, nördlich des Alteracgebirges.', },
  },
  [10374] = {
    'Der Ruf zu den Waffen: Die Pestländer!',
    {'Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!|n|nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Östlichen Königreiche erheben! Sie lauern östlich von Unterstadt, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!|n|nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunkt am Bollwerk östlich von Tirisfal aufgeschlagen!', },
    {'Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt.', },
  },
  [10375] = {
    'Obsidiankriegsperlen',
    {'Ihr habt Euch meinem Volk gegenüber als würdig erwiesen, $N. Jetzt ist es an der Zeit, uns zu beweisen, dass Ihr bereit seid, uns jederzeit beizustehen, auch gegen unserer ärgsten Feind.|n|nDie Oger der Scherbenwelt sind', },
    nil,
  },
  [10376] = {
    'Zeichen der Hoffnung',
    nil,
    nil,
  },
  [10377] = {
    'Keine Angst',
    nil,
    nil,
  },
  [10378] = {
    'Magiegebrauch',
    nil,
    nil,
  },
  [10379] = {
    'Berührung der Schwäche',
    nil,
    nil,
  },
  [10380] = {
    'Ein dunkler Pakt',
    {'Wir waren so blind, dass wir nicht gesehen haben, dass unsere beiden größten Feinde sich verbündet haben, $N.|n|nIch wäre nicht überrascht, wenn die Seher uns diese Information absichtlich vorenthalten hätten, aber wir müssen uns nun der Wirklichkeit stellen. Die Brennende Legion und Kael\'thas Sonnenzornarmee dienen unter dem gleichen Banner.|n|nDie Dämonen sind der einzige Grund, aus dem Kael\'thas je in der Lage war, die Technologie der Festung der Stürme nutzen zu können. Ich muss Euch auf Orelis\' Befehl hin bitten, sie zu zerstören.', },
    {'Kaylaan auf Tulumans Landeplatz möchte, dass Ihr 6 Warptüftler der Gan\'arg, 3 Töchter des Schicksals und 3 Warpmeister der Mo\'arg tötet.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10381] = {
    'Nie mehr Aldor',
    {'Meine Mission hier ist zu Ende. Ich habe getan, was Orelis mir befohlen hat - nie habe ich ihn enttäuscht.|n|nNie wieder. Ich sehe ein großes Gemetzel voraus - einen Kreuzzug werden sie es nennen - das auf das neue Bündnis zwischen Kael\'thas und der Brennenden Legion folgen wird.|n|nZuerst werden sie unsere heiligste Stadt dem Feind übergeben und uns dann bitten, im Kampf gegen ihren Feind zu sterben. Geht zurück zu Orelis und sagt ihm, dass die Naaru von nun an ihre Kämpfe alleine austragen können.', },
    {'Meldet Euch bei Exarch Orelis in Area 52.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10382] = {
    'Geht zur Front',
    {'Nun, $N, ich hoffe, Ihr seid für die nächste Phase unserer Operation bereit. Die Legion schläft nicht - und wir auch nicht! Nehmt einen Greifen und fliegt zum Ehrenposten, einem kleinen Lager in der Nähe der Front der Legion.|n|nSprecht mit Feldmarschall Brock. Er wird bei Eurer Ankunft Anweisungen für Euch bereithalten. Oh, und sagt diesem teiggesichtigen Schildschmuser einen Gruß von mir.', },
    {'Nehmt einen Greifen zum Ehrenposten und sprecht mit Feldmarschall Brock.', },
  },
  [10383] = {
    'Dies ist ein Brotkrumen!',
    {'Hallo. Ihr solltet mehr über diese Kaninchen herausfinden.', },
    {'Sprecht mit Jonathan LeCraft über die Kaninchen.', },
  },
  [10384] = {
    'Daten der Astralen',
    {'Seht Euch um, Fleischling. Ganz in der Nähe des Transponders sollte sich eine Datenzelle des Astraleums befinden. Sucht sie, öffnet sie und entnehmt den Inhalt.|n|nBringt sie dann sofort zu diesem Transponder zurück!', },
    {'Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr die Datenzelle des Astraleums besorgt.', },
  },
  [10385] = {
    'Hirnschadengefahr = hoch',
    {'Sie benutzen Melder, um die Informationen im Stützpunkt zu verteilen.|n|nEs gibt nur einem Weg, wie Ihr die Melder sehen und ihre Informationen extrahieren könnt. Unglücklicherweise könntet Ihr dadurch einen irreparablen Hirnschaden erlangen.|n|nWenn Ihr immer noch interessiert seid, müsst Ihr einige der Anhänger des Astraleums hier erschlagen und ihre Essenz nehmen. Wenn Ihr eine Essenz habt, trinkt sie. Mit ihrer Hilfe werdet Ihr für kurze Zeit in der Lage sein, die Melder des Astraleums zu sehen. Die Zeit reicht aus, um einen Melder zu zerstören und seine Informationen zu extrahieren.', },
    {'Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr 15 Melderdaten des Astraleums besorgt.', },
  },
  [10386] = {
    'Der Teufelshäschertöter',
    {'Oberanführer Hun Stümmelfaust sucht immer nach Freiwilligen für seine selbstmörderischen Angriffe auf die Brennende Legion. Ihr verfügt definitiv über dem Mut für seine "Missionen".|n|nSprecht mit ihm, wenn Ihr Appetit auf noch mehr Gemetzel habt. Er feiert gerade da drüben bei dem gefallenen Teufelshäscher. Er und seine Wachen haben ihn vor ein paar Stunden vernichtet. Hätte er nicht so wild und geschickt gekämpft, wären wir jetzt alle tot.', },
    {'Sprecht mit Oberanführer Hun Stümmelfaust.', },
  },
  [10387] = {
    'Der Teufelshäschertöter',
    {'Oberanführer Hun Stümmelfaust sucht immer nach Freiwilligen für seine selbstmörderischen Angriffe auf die Brennende Legion. Ihr verfügt definitiv über dem Mut für seine "Missionen".|n|nSprecht mit ihm, wenn Ihr Appetit auf noch mehr Gemetzel habt. Er feiert gerade da drüben bei dem gefallenen Teufelshäscher. Er und seine Wachen haben ihn vor ein paar Stunden vernichtet. Hätte er nicht so wild und geschickt gekämpft, wären wir jetzt alle tot.', },
    {'Sprecht mit Oberanführer Hun Stümmelfaust.', },
  },
  [10388] = {
    'Rückkehr nach Thrallmar',
    {'Kehrt nach Thrallmar zurück und sprecht mit Nazgrel.', },
    {'Kehrt nach Thrallmar zurück und sprecht mit Nazgrel.', },
  },
  [10389] = {
    'Das Leid und die Dunkelheit',
    {'Grüße, $N. Ich habe den Schriftwechsel der Legion entziffert und ihre strategischen Pläne für die Halbinsel aufgedeckt. Offensichtlich sammelt sich in der Nähe der Teiche von Aggonar im Westen eine große Gruppe von teuflischen Terrorbestien. Das dürfen wir nicht ohne Kampf zulassen. Ihr müsst Euch dorthin begeben und ihre verfluchten Reihen ausdünnen.', },
    {'Magister Blutfalke möchte, dass Ihr 10 Terrorbestien bei den Teichen von Aggonar tötet.', },
  },
  [10390] = {
    'Konstruktionslager: Mageddon',
    {'$N, wir haben guten Grund zu vermuten, dass das Konstruktionslager, das sich am östlichsten befindet, noch nicht fertig ist. Die Gan\'argsklaven der Legion arbeiten rund um die Uhr, um die Einrichtung zum Laufen zu bringen. Das können wir nicht zulassen.|n|nBegebt Euch nach Osten zum Konstruktionslager: Mageddon und tötet 10 Gan\'arg. Bringt mir den Kopf ihres Meisters, Schmiedebestie Sägeklinge! So werden wir die Teufelshäscherproduktion der Legion zum Erliegen bringen!', },
    {'Nazgrel in Thrallmar möchte, dass Ihr das Konstruktionslager: Mageddon angreift, 10 Diener der Gan\'arg tötet und mit Schmiedebestie Sägeklinges Kopf zurückkehrt.', },
  },
  [10391] = {
    'Kanonen des Zorns',
    {'Es gibt eine weitere Produktionsstätte. Das Konstruktionslager: Zorn liegt direkt im Nordosten von Thrallmar. Die Dämonen haben eine Reihe von Teufelskanonen am Grat entlang aufgestellt - und sie zielen direkt auf uns! Ihr müsst in das Lager eindringen und diese Kanonen außer Gefecht setzen.|n|n$N, Ihr müsst sichergehen, dass Ihr alle zerstört - sonst kann die Legion nichts daran hindern, uns mit den Feuern der Hölle zu versengen!', },
    {'Zerstört 3 Teufelskanonen V1 im Konstruktionslager: Zorn und kehrt dann zu Nazgrel in Thrallmar zurück.', },
  },
  [10392] = {
    'Die Schwelle zum Abgrund',
    {'Ihr ehrt uns, $N. Aber nun müssen wir zuschlagen, bevor die Legion sich erholt! Nördlich von Thrallmar liegt der Invasionspunkt: Vernichter. Dort befindet sich ein Warpportal, durch das die Legion ihre Verstärkung bezieht.|n|nIhr müsst dieses Portal überlasten - und es zurück in den Abgrund schicken, aus dem es gekommen ist. Den Aktivierungsschlüssel trägt vermutlich der Kommandant des Punkts, Kriegshetzer Arix\'Amal, bei sich. Tötet ihn. Benutzt dann den Schlüssel bei dem Portal und tut, was getan werden muss. Möge der Segen des Kriegshäuptlings auf Euch ruhen.', },
    {'Tötet Arix\'Amal und nehmt Euch den Torschlüssel der Brennenden Legion. Benutzt den Schlüssel bei der Rune der Bosheit und kehrt danach zu Nazgrel in Thrallmar zurück.', },
  },
  [10393] = {
    'Boshafte Pläne',
    {'Der Text auf dem Brief ist in dunklem, unentzifferbarem Gekrakel geschrieben. Je mehr Ihr sie anstarrt, desto mehr Symbole scheinen sich vor Euren Augen zu drehen und zu leuchten. Es gibt nur einen in Thrallmar, der so eine bösartige Schrift entziffern kann - der Blutelfenmagister Blutfalke.', },
    {'Bringt den Schriftwechsel der Legion zu Magister Blutfalke in Thrallmar.', },
  },
  [10394] = {
    'Unterbrechung beim Konstruktionslager: Mageddon',
    {'Passt genau auf, $N. Wir haben die Lager der Legion, die entlang des Grats vor uns liegen, überwacht. Wir haben guten Grund zur Annahme, dass die Dämonen in diesen so genannten \'Konstruktionslagern\' ihre verdammten Teufelshäscher herstellen.|n|nIhr könnt das am nächsten gelegene Ziel, das Konstruktionslager: Mageddon von hier aus im Westen sehen. Unsere Geheimagenten melden, dass es sich immer noch im Bau befindet. Wenn Ihr die Gan\'argdiener und ihren Meister, Schmiedebestie Sägeklinge, tötet, können wir der Teufelshäscherproduktion der Legion ein schnelles Ende machen!', },
    {'Tötet 10 Diener der Gan\'arg und Schmiedebestie Sägeklinge im Konstruktionslager: Mageddon und kehrt danach zu Feldmarschall Brock beim Ehrenposten zurück.', },
  },
  [10395] = {
    'Der dunkle Schriftwechsel',
    {'Der Text auf dem Brief ist in dunklem, unentzifferbarem Gekrakel geschrieben. Je mehr Ihr sie anstarrt, desto mehr Symbole scheinen sich vor Euren Augen zu drehen und zu leuchten. Es gibt nur einen in der Ehrenfeste, der so eine bösartige Schrift entziffern kann - der Draeneimystiker Kryv.|n|nBringt den Schriftwechsel der Brennenden Legion zu Warpseher Kryv im Kriegsraum der Ehrenfeste.', },
    {'Bringt den Schriftwechsel zu Warpseher Kryv in der Haupthalle der Ehrenfeste.', },
  },
  [10396] = {
    'Der Feind meines Feindes...',
    {'Jetzt müssen wir uns auf unser zweites Ziel konzentrieren, das Konstruktionslager: Zorn. Es liegt direkt westlich von Mageddon. Das Problem ist, dass die Dämonen eine Reihe von Teufelskanonen direkt auf den Außenposten der Horde in Thrallmar gerichtet haben! Ich kann es zwar kaum fassen, aber wir müssen der Horde helfen, um unsere Linien beim Dunklen Portal aufrechtzuerhalten. Wir können es uns nicht erlauben, Thrallmar fallen zu lassen. Ihr müsst alle Kanonen zerstören, bevor die Legion unsere Verbündeten in die Luft jagt!', },
    {'Zerstört 3 Teufelskanonen V1 im Konstruktionslager: Zorn und kehrt dann zu Feldmarschall Brock beim Ehrenposten zurück.', },
  },
  [10397] = {
    'Invasionspunkt: Vernichter',
    {'Wir haben die letzte Basis der Legion auf dem Grat ausgemacht. Der Invasionspunkt: Vernichter liegt nordwestlich des Konstruktionslagers: Zorn. Dort befindet sich ein Warpportal, mit dessen Hilfe die Legion Verstärkung herbeiholt!|n|nIhr müsst an dieses Portal herankommen und verhindern, dass noch mehr Dämonen dadurch in unsere Welt kommen. Der Oberanführer des Punkts, Kriegshetzer Arix\'Amal, hat den Aktivierungsschlüssel für das Portal. Nehmt ihn ihm ab und schaltet dieses verdammte Tor ab!', },
    {'Tötet Arix\'Amal. Nehmt den Torschlüssel der Brennenden Legion und benutzt ihn bei der Rune der Bosheit.', },
  },
  [10398] = {
    'Rückkehr zur Ehrenfeste',
    {'Geht zu Ehrenfeste.', },
    {'Geht zu Ehrenfeste.', },
  },
  [10399] = {
    'Das Herz der Dunkelheit',
    {'Es ist genau so, wie ich befürchtet habe. Der Dämon, den Ihr unlängst getötet habt, Arix\'Amal, stand im Dienst des heimlichen Legionslords Arazzius des Grausamen. Wie es scheint hat dieser Bösewicht eine neue Streitmacht von höllischen Terrorbestien in der Nähe der Teiche von Aggonar aufgestellt.|n|nIhr müsst Euch dorthin begeben und die Terrorbestien vernichten, bevor sie uns angreifen können. Aber seid vorsichtig, Freund. Die Teiche von Aggonar liegen in einem gemarterten, giftigen Tal. Ihr findet die verfluchten Teiche nordwestlich von hier, hinter der Höllenfeuerzitadelle.|n|nDas Licht sei mit Euch, $N.', },
    {'Tötet 10 Terrorbestien bei den Teichen von Aggonar und kehrt dann zu Warpseher Kryv in der Haupthalle der Ehrenfeste zurück.', },
  },
  [10400] = {
    'Oberanführer',
    {'Tötet Arazzius den Grausamen bei den Teichen von Aggonar und kehrt danach zu Truppenkommandant Danath Trollbann in der Ehrenfeste zurück.', },
    {'Tötet Arazzius den Grausamen bei den Teichen von Aggonar und kehrt danach zu Truppenkommandant Danath Trollbann in der Ehrenfeste zurück.', },
  },
  [10401] = {
    'Mission: Beendet alles, seid alles',
    {'Wisst Ihr, was passiert wäre, wenn Ihr den Boten nicht abgefangen hättet, $N?|n|n<Nazgrel nickt.>|n|nDie gesamte Armee der Legion des Höllenfeuers hätte vor unserer Tür gestanden. Einen solchen Angriff hätten wie niemals überlebt.|n|nEs gibt nur eine Möglichkeit zu verhindern, dass diese Befehle jemals die Front erreichen. Ihr müsst zu den Teichen von Aggonar, westlich von hier, reisen und diesen Arazzius töten.|n|nWenn Ihr das tut, werde ich dafür sorgen, dass der Kriegshäuptling Euch eine Auszeichnung zukommen lässt.', },
    {'Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel möchte, dass Ihr Arazzius den Grausamen tötet.', },
  },
  [10403] = {
    nil,
    {'Vielleicht ist noch nicht alle Hoffnung für das Lumpenpack verloren. Ich bin einer der vier Ältesten, die diesen Stamm leiteten, bevor wir von den Illidari versklavt wurden. Ich dachte, dass die anderen tot seien, aber dann habe ich erfahren, dass zumindest zwei weitere noch am leben sind - angekettet und machtlos, so wie ich.|n|nIch habe Naladu noch nicht finden können und befürchte das Schlimmste. Oben in den Ruinen gibt es noch mehr Hütten, vielleicht könntet Ihr dort nach ihm suchen. Es wäre ein großes Glück für unseren Stamm, wenn alle Ältesten am Leben wären.', },
    {'Sucht Naladu in den Ruinen von Sha\'naar.', },
  },
  [10404] = {
    'Gegen die Legion',
    {'Wir haben erfahren, dass die Brennende Legion Kael\'thas mit technologischem Wissen unterstützt hat, und so die Bedrohung, die von ihm ausgeht, noch um ein Vielfaches vergrößert hat.|n|nDa die Legion in der Gegend so zahlreich vertreten ist, können wir den größten Schaden nur durch einen gezielten Angriff auf die Konstruktionsbasen im Norden erreichen.|n|nGeht zur Konstruktionsbasis: Vergessenheit und zur Konstruktionsbasis: Gehenna und zerstört unsere Feinde. Möge das Licht Eure Klinge führen, $N.', },
    {'Exarch Orelis in Area 52 möchte, dass Ihr zur Konstruktionsbasis: Vergessenheit und zur Konstruktionsbasis: Gehenna geht und 12 Feuerfäuste der Gan\'arg, 6 Konstruktionsherren der Gan\'arg und 6 Zornschaffer tötet.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10405] = {
    nil,
    {'Wir müssen die Maschinen zerstören, die diese abnormalen Dunkelpirscher hervorbringen. Ihren Protobeschleuniger anzugreifen ist sinnlos, da es sich um eine astrale Erfindung handelt. Wir müssen stattdessen die Rohre der Manaschmiede, die sie als Energieleitung verwenden, zerstören.|n|nIch habe fast alles, was ich brauche, um ein Gerät herzustellen, das die Energieleitung überlasten kann. Ich brauche nur noch die Bandagen eines Archon oder Oberanführers, der sich bald verwandeln wird, um das Gerät einzustellen.', },
    {'Das Bild von Kommandant Ameer bei dem Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr eine vorbereitete Bandage des Astraleums besorgt.', },
  },
  [10406] = {
    'Die Nachricht überbringen',
    {'Ich schicke einen meiner Demolierer los, um das Störgerät zu platzieren. Sorgt nur dafür, dass ihm kein Leid geschieht, während er den Störer aufstellt.|n|nBeschützt ihn! Er wird sich nicht wehren, wenn er von Feinden angegriffen wird, da er nur ein holografisches Bild ist, aber auch das kann zerstört werden!|n|nKehrt zu mir zurück, wenn Ihr fertig seid.', },
    {'Das Bild von Kommandant Ameer bei dem Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr den Demolierer des Protektorats zur Energieleitung der Manaschmiede Ultris begleitet und ihn beschützt, während er die Leitung sabotiert.', },
  },
  [10407] = {
    'Socrethars Schatten',
    {'Der berüchtigte Eredar, Socrethar, führt die Brennende Legion im Nethersturm an. Allein seinen Namen zu nennen lässt die meisten Draenei erzittern. Er erteilt seine Befehle von einer Insel im Nordwesten aus, die nur seine vertrauenswürdigsten Leutnants betreten können.|n|nUm dorthin zu gelangen, müsst Ihr einen Teleportationsstein besorgen, was nicht einfach wird. Die erste Hälfte des Steins befindet sich im Besitz von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit. Die zweite Hälfte hat der Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna.', },
    {'Anachoret Karja in Area 52 möchte, dass Ihr die erste Hälfte von Socrethars Stein von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit und die zweite Hälfte des Steins von Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna besorgt.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10408] = {
    'Nexuskönig Salhadaar',
    {'Ich habe einen weiteren Störer in meinem Besitz. Einer, der in der Lage ist, die drei Energieleitungen, die Salhadaar umgeben, zu zerstören. Wenn die Energieleitungen einmal vernichtet sind, werden sich Salhadaars schützende Kraftschilde senken. Für diese Tat wird er Euch mit einer Wildheit angreifen, die Ihr noch nie zuvor gesehen habt, $N.|n|nWenn Ihr bereit seid, die Welt von Salhadaar zu befreien, gebe ich Euch den Störer.', },
    {'Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr den Störer des Protektorats benutzt, um Salhadaar Kraftfelder zu senken und Nexuskönig Salhadaar zu vernichten.', },
  },
  [10409] = {
    'Todesstoß für die Legion',
    {'Wenn man mit mächtigen Eredar zu tun hat, sind große Armeen meist nutzlos. Ihre verderbte Macht über die sterblichen Seelen ist so stark, dass nur die mit einem starken Willen ihnen gegenübertreten können.|n|nBringt diesen Stein zum Invasionspunkt: Oberanführer zwischen der Konstruktionsbasis: Vergessenheit und der Konstruktionsbasis: Gehenna und nehmt Eure engsten und stärksten Freunde mit. Orelis und Karja erwarten Euch bei Socrethars Sitz. Ich werde Adyen mit ihnen losschicken.|n|nMöge das Licht sich heute behaupten, $N. Möge Socrethars Ende nahen.', },
    {'Hohepriesterin Ishanah möchte, dass Ihr zum Transporter der Legion am nordwestlichsten Ende des Nethersturms geht und Euch zu Socrethars Sitz teleportiert. Wenn Ihr dort seid, besiegt Socrethar.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10410] = {
    'Ishanahs Hilfe',
    {'Die Zeit ist gekommen, da Ihr Euch Socrethar stellen müsst, $N. Einem Eredar entgegen zu treten ist eine Aufgabe, die keiner von uns auf die leichte Schulter nimmt. Schon ein kleiner Fehler kann uns das Leben kosten, wenn wir unvorbereitet sind.|n|nBringt Socrethars Teleportationsstein zu Hohepriesterin Ishanah beim Schrein des Endlosen Lichts in Shattrath. Sie wird entscheiden, wie mit der Situation umzugehen ist.', },
    {'Bringt Socrethars Teleportationsstein zu Hohepriesterin Ishanah beim Schrein des Endlosen Lichts in Shattrath.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10411] = {
    'Elektroschock!',
    {'Forscher Navuud im Wachposten des Protektorats im Nethersturm möchte, dass Ihr 30 Leerenabschaumkugeln und 30 Sickerschlickkugeln zerstört.', },
    {'Forscher Navuud im Wachposten des Protektorats im Nethersturm möchte, dass Ihr 30 Leerenabschaumkugeln und 30 Sickerschlickkugeln zerstört.', },
  },
  [10412] = {
    'Siegel der Feuerschwingen',
    {'Es ist kein Geheimnis, dass Kael\'thas Sonnenwanderer uns als große Bedrohung sieht. Nüchtern betrachtet gibt es nicht viele Sin\'dorei, die frisch aus Silbermond kommen und bereit sind, sich der Gesellschaft, die Kael\'thas unterhält, anzuschließen.|n|nEs ist auch kein Geheimnis, dass es sich hier nicht nur um Wortgefechte handelt. Die Seher und die vielen Armeen, die Kael\'thas dienen, haben und werden sich angreifen, sobald sie sich begegnen. Der einzige Weg, wie Ihr beweisen könnt, dass Ihr auf unserer Seite steht, ist, sich dem Kampf anzuschließen, $N.|n|nKaels niederrangige Anhänger tragen Siegel der Feuerschwingen bei sich, die ihren Rang anzeigen. Bringt sie mir.', },
    {'Magistrix Fyalenn in Shattrath möchte, dass Ihr ihr 10 Siegel der Feuerschwingen bringt.|n|nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10413] = {
    'Die Schrecken der Verschmutzung',
    {'Ihr befüllt vorsichtig eine Phiole mit dem Schlamm des gefallenen Leerenschreckens.|n|nForscher Navuud im Wachposten des Protektorats wäre an einem solchen Fund sicher interessiert. Bringt ihn sofort zu ihm!', },
    {'Bringt die Phiole mit Leerenschreckensschlamm zu Forscher Navuud im Wachposten des Protektorakts im Nethersturm.', },
  },
  [10414] = {
    'Einzelne Siegel der Feuerschwingen',
    nil,
    nil,
  },
  [10415] = {
    'Mehr Siegel der Feuerschwingen',
    nil,
    nil,
  },
  [10416] = {
    'Bündelung der Macht',
    {'Arkane Folianten sind keine gewöhnlichen Bücher, die sich mit arkanen Themen befassen. Ihnen wohnt eine wesenhafte Macht inne - eine Macht, die ich in eine einzelne arkane Rune bündeln kann.|n|nSolltet Ihr auf Euren Reisen einen arkanen Folianten finden, werde ich Euch eine solche Rune geben. Nur die mächtigsten magiebegabten Wesen tragen die Bücher, die ich brauche, bei sich. In der Scherbenwelt sind das meistens Kaels Blutelfen, aber Ihr wärt überrascht, wo solche Bücher des Öfteren auftauchen.', },
    {'Voren\'thal der Seher in Shattrath möchte, dass Ihr einen arkanen Folianten besorgt.|n|nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10417] = {
    'Führt eine Diagnose durch!',
    {'Wo auch immer das Konsortium Einzug hält, bringen wir unsere Biokuppeltechnologie mit. Diese Technologie erlaubt uns, in einer kontrollierten und lebenserhaltenden Atmosphäre zu arbeiten, da wir uns meist in feindlichen Gebieten befinden.|n|nDie bösartigen Bedingungen und Kreaturen des Nethersturms haben begonnen, die Ausrüstung, die unsere Biokuppeln aufrechterhält, zu zerstören, besonders den Generator im Osten. Ich habe einen Diagnoselauf dort begonnen, damit ich hoffentlich herausfinden kann, was gegen den Schaden getan werden kann. Könntet Ihr die Resultate dort abholen und zu mir bringen?', },
    {'Beschafft die Untersuchungsergebnisse und bringt sie zu Mehrdad im Mittelreichposten.', },
  },
  [10418] = {
    'Die Saboteure ausschalten',
    {'Als ich das Gebiet nach Hinweisen auf den Schaden unserer Ausrüstung abgesucht habe, habe ich Teile der Schildgeneratoren auf dem Grund des kleinen Sees im Norden gesehen. Ich bin mir nicht sicher, warum die Krokilisken sich für unsere Ausrüstung interessieren, aber wir müssen dieses Problem beseitigen.|n|nDas Konsortium ist sich in dieser Sache einig. Wenn es zu einer Entscheidung zwischen der Ausrüstung und Krokilisken kommt, müssen die Tiere gehen. Ich werde Euch angemessen belohnen, wenn Ihr Euch darum kümmert.', },
    {'Mehrdad beim Mittelreichposten möchte, dass Ihr 8 Stachelschuppenkrokilisken tötet.', },
  },
  [10419] = {
    'Arkane Folianten',
    nil,
    nil,
  },
  [10420] = {
    'Ein reinigendes Licht',
    {'Dieser Tempel ist eine der heiligsten Stätten der ganzen Scherbenwelt. Die Macht des Lichts ist hier so stark, dass es weltliche Gegenstände sogar von der schlimmsten teuflischen Verderbnis befreien kann.|n|nFalls Ihr bei Euren Kämpfen mit den dämonischen Feinden teuflische Waffen finden solltet, bringt sie zu mir. Dann werde ich Euch die reinigende Kraft des Lichts beweisen.', },
    {'Bringt eine Ladung teuflische Waffen zu Ishanah in Shattrath.|n|nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10421] = {
    'Teuflische Waffen',
    nil,
    nil,
  },
  [10422] = {
    'Hauptmann Tyralius',
    nil,
    nil,
  },
  [10423] = {
    'Zur Sturmsäule',
    {'Meisteringenieur Ghabar möchte sicher die Ergebnisse der Diagnose erfahren. Sie zeigen uns wenigstens, dass wir die Funktionalität der Kuppelgeneratoren genau im Auge behalten müssen. Wenn die Felder immer instabiler werden, können wir ihre Auswirkungen auch immer schwerer kontrollieren. Das könnte ein Desaster für unsere Expedition und alles, was sich in den Kuppeln befindet, bedeuten.|n|nIhr findet Ghabar in der Sturmsäule. Folgt einfach der Straße nördlich dieser Biokuppel und überquert die Brücke. Sie führt Euch direkt zum Aufzug unten in der Säule.', },
    nil,
  },
  [10424] = {
    'Diagnose: kritisch',
    {'Wenn Mehrdads Ergebnisse richtig sind - und ich habe keinen Grund daran zu zweifeln - könnte der Rest der Kuppeln in Gefahr sein.|n|nIch glaube jedoch, dass Mehrdad nicht den richtigen Grund für die Defekte gefunden hat. Tiere können die Generatoren bisweilen schon beschädigen, aber niemals so schwer.|n|nUm sicher zu gehen, möchte ich, dass Ihr ein paar Diagnoseläufe bei dem Hauptkuppelgenerator der Sturmsäule am östlichen Rand in der Biokuppel Sutheron durchführt.', },
    {'Benutzt das Diagnosegerät in der Nähe des Generators der Biokuppel Sutheron und bringt die Diagnoseergebnisse zu Gabhar in der Sturmsäule zurück.', },
  },
  [10425] = {
    'Ausbruch aus dem Stützpunkt',
    {'K\'aresh sei Dank! Er hätte mich in Stücke gerissen!|n|nIch bin ein Soldat des Protektorats, Fleischling. Meine Truppe wurde vor etwa 10 Tagen auf eine Aufklärungsmission geschickt. Als wir uns über die oberen Regionen dieser Insel bewegten, wurden wir von einer Gruppe des Astraleums überfallen. Zumindest denke ich, dass es das Astraleum war. Sie hatten die gleichen Energiefarben, aber ihre Bandagen sahen irgendwie leer aus.|n|nSie haben nur Tyralius verschont. Ich glaube, sie haben ihn in ein Gefängnis eingesperrt.|n|nIch muss zurück zum Wachposten des Protektorats! Könnt Ihr mich dorthin begleiten?', },
    {'Begleitet den gefangenen Vorposten des Protektorats zurück zum Wachposten des Protektorats im Nethersturm.', },
  },
  [10426] = {
    'Flora der Biokuppel',
    {'Schaut Euch nur um, $C! Ist es nicht erstaunlich? Natürlich ist diese unglaubliche Fülle von Leben ein Nebenprodukt der Kuppeln der Astralen, aber stellt Euch nur vor, was diese Technologie in den Händen der Expedition bedeuten könnte.|n|nIch bereite mich darauf vor, mit den Astralen zu verhandeln, um Zugang zu ihrer Technologie zu bekommen, aber ich wüsste zuvor gerne genauer, welche Auswirkungen sie auf das pflanzliche Leben hat.|n|nIch habe ein Gerät gebaut, mit dem ich die Energien auf die Peitscher in dieser Gegend richten kann. Wärt Ihr so nett und würdet es für mich ausprobieren und mir die Ergebnisse mitteilen?', },
    {'Benutzt den Energiefeldmodulator bei den Farahlonpeitschern. Beobachtet die Ergebnisse und meldet Euch bei Aurine Mondflamm in der Sturmsäule zurück, wenn Ihr 10 Tests durchgeführt habt.', },
  },
  [10427] = {
    'Fauna der Biokuppel',
    {'Eure Arbeit bei den Peitschern stellte sich als erstaunliche Information heraus, aber ich frage mich, ob das auch für die Tiere gilt.|n|nIch fürchte jedoch, dass es schwieriger wird, Informationen über die Talbuks zu sammeln, als über die Peitscher.|n|nMit diesem Markierungsgerät könnt Ihr einen geschwächten Talbuk schlafen legen und ihn mit einer Markierung versehen, mit deren Hilfe ich das Tier während seiner Wachstumsphase verfolgen kann. Der Mechanismus des Markierungsgeräts funktioniert erst, wenn der Talbuk schon sehr erschöpft ist.', },
    {'Markiert 12 Talbuks für Aurine Mondflamm in der Sturmsäule. Ihr könnt mit dem Talbukmarkierer sowohl Talbukböcke als auch Talbukkühe markieren.', },
  },
  [10428] = {
    'Der vermisste Fischer',
    {'Von fiebrigen Träumen geplagt sprach unser verletzter Gast von einem Fischer, Cowlen, der auf der Silbermythosinsel im Südwesten vor der Küste der Azurmythosinsel, in Schwierigkeiten war.|n|nNach all den Geschehnissen hier hatte keiner die Gelegenheit, nachzuschauen, aber ich mache mir doch ein paar Sorgen. Vielleicht könnt Ihr etwas tun, $N?', },
    {'Sucht Cowlen bei den südöstlichen Docks der Silbermythosinsel vor der Küste der Azurmythosinsel.', },
  },
  [10429] = {
    'Wenn die Natur zu weit geht',
    {'Die Technologie der Kuppeln ist so mächtig! Sicher gibt es Grenzen, die wir nicht zu überschreiten wagen, $N.|n|nWesen, die zu schnell oder zu groß wachsen, können genauso schlimm sein wie eine unfruchtbare Landschaft.|n|nIch habe Gerüchte gehört, dass sich genau so eine Kreatur im Teich im Osten herumtreibt. Die Händler der Astralen wollen die übergroße Hydra aus Spaß erlegen, aber ich habe etwas anderes mit dem Riesen vor. Bringt mir das Herz dieser Kreatur, damit ich es untersuchen kann.', },
    {'Aurine Mondflamm in der Sturmsäule möchte, dass Ihr ihr ein titanisches Hydraherz bringt.', },
  },
  [10430] = {
    'Den Prototyp testen',
    {'Ich habe an einem tragbaren Reparatursatz für den Generator gearbeitet, der in den kälteren Regionen, in denen das Konsortium Geschäfte macht, funktioniert. Zugegeben, er war nicht für den Nethersturm entwickelt worden, aber wir sollten trotzdem keine Probleme damit haben.|n|nIch habe bereits einen Test mit einem meiner besten Techniker bei der Biokuppel Fernfeld hinter dem Netherstein im Nordosten vereinbart. Bringt diesen Prototypen zu Tashar. Er wird wissen, was damit zu tun ist. Wenn er funktioniert können wir ihn benutzen, um die Schildgeneratoren bei den größeren Kuppeln zu verstärken.', },
    nil,
  },
  [10431] = {
    'Hilfe von außen',
    {'Die Befehle des Sonnenzorns bestätigen den Verdacht, dass Kael\'thas bei dem Bau und dem Betrieb der Manaschmieden Hilfe von außen bekommen hat. Wer dahinter steckt, ist immer noch ein Geheimnis, doch wir können es wahrscheinlich in der Manaschmiede Ara herausfinden.|n|nIch habe eine Gruppe meiner Leute losgeschickt, um die Gegend zu erkunden. Geht zu Tulumans Landeplatz nördlich von hier und sprecht mit Kaylaan. Hört Euch an, was er in der Manaschmiede Ara gefunden hat. Findet heraus, wer die Armee des Sonnenzorns unterstützt, und kümmert Euch um sie.', },
    {'Geht zu Tulumans Landeplatz, nördlich von Area 52, und sprecht mit Kaylaan.|n|nDas Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.', },
  },
  [10432] = {
    'Eindeutige Beweise',
    {'Wie Ihr sicher bemerkt habt, laufen in der Manaschmiede Ara überall Diener der Brennenden Legion herum. Kael\'thas ist einen Bund mit der Brennenden Legion eingegangen. Er muss gehört haben, dass Illidan dem Wahnsinn verfallen ist, und den Meister gewechselt haben.|n|nWenn die Seher dafür einen stichhaltigen Beweis hätten, wäre das ein deutlicher politischer Vorteil für sie. Ich weiß genau, dass die Streitkräfte der Legion bei der Manaschmiede hier Befehle haben, die Kaels Siegel tragen.|n|nBesorgt diese Befehle und bringt sie zu Thalodien.', },
    {'Besorgt Euch 8 Befehle von Kael\'thas von den Dämonen bei der Manaschmiede Ara und bringt sie zu Spionagemeister Thalodien in Area 52.|n|nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.', },
  },
  [10433] = {
    'Den Schein wahren',
    {'Die Astralen sind sehr klug und aufmerksam, daher ist es kein Zufall, dass ich hier als einfacher Fellhändler auftrete. Tatsächlich wurde ich von Area 52 hierher geschickt, um die Technologie, die die Astralen in ihren Biokuppeln einsetzen, zu bewerten.|n|nIch würde gerne Eure Hilfe in Anspruch nehmen, $C. Wir wurden darum gebeten, wo es nur geht andere Völker als Goblins als Spione einzusetzen.|n|nIch möchte, dass Ihr mir als Jäger verkleidet ein paar Reißzahnpelze bringt. Ihr findet die Luchse überall bei der Biokuppel Mittelreich.', },
    {'Bringt 10 Reißzahnpelze zu Shauly Pore im Mittelreichposten.', },
  },
  [10434] = {
    'Das dynamische Duo',
    {'Ausgezeichnete Arbeit.|n|n<Shauly zwinkert Euch zu.>|n|nIch glaube, sie kaufen es uns ab. Wenn ich Euch jetzt zu meinen Verbündeten in der Sturmsäule schicke, werden sie nicht misstrauisch werden.|n|nHaltet nach Aktion Jaxon und Audi der Nadel Ausschau. Sie werden Euch alles sagen, was Ihr wissen müsst. Sagt ihnen, dass Shauly Euch geschickt hat.', },
    nil,
  },
  [10435] = {
    'Die Waren zurückholen',
    {'<Audi sieht sich um und senkt die Stimme.>|n|nIch bin sicher, dass Shauly Euch ein wenig von unserer Arbeit hier erzählt hat. Als Jaxon und ich draußen im Feld auf der Jagd waren, haben wir Teile von den Generatoren der Biokuppeln der Astralen gesammelt und sie in den Nestern unserer Beute, den Raptoren bei der Biokuppel Fernfeld, versteckt.|n|nDas ist eine abgelegene Gegend nordöstlich der Sturmsäule, in der Nähe des Nethersteins. Ich nehme nicht an, dass Ihr dort auf viele Astrale treffen werdet, aber würdet Ihr uns helfen, die Kuppelgeneratorenteile zu sammeln?', },
    {'Audi die Nadel bei der Sturmsäule möchte, dass Ihr 10 Kuppelgeneratorsegmente besorgt.', },
  },
  [10436] = {
    'Freie Bahn!',
    {'Bevor wir den Test beginnen können, müssen wir sicherstellen, dass das Gebiet frei von allem ist, was uns dabei stören könnte. In unserem Fall sind das diese zu groß geratenen Echsen.|n|n<Tashar zeigt auf die Sichelzahnraptoren.>|n|nEs ist nicht voraussehbar, was passiert, wenn einer von ihnen auf die Idee kommt, genüsslich in den Generator zu beißen, während er gerade auflädt. Ich habe in all den Jahren als Techniker schon viele merkwürdige Dinge gesehen, darunter auch ein paar Mutationen, die einst ganz normale Tiere waren.', },
    {'Tashar bei der Biokuppel Fernfeld möchte, dass Ihr 12 Sichelzahnraptoren tötet.', },
  },
  [10437] = {
    'Anleitung zur Zerstörung',
    {'Auf der Manaschmiede Ultris befindet sich der Riss im Nether, durch den Dimensius, der Leerenfürst, gekommen ist. Dieser Riss bildet eine Verbindung zwischen Dimensius und der Leere und macht ihn unverwundbar. Wenn es uns gelingt, diese Energieleitung, mit der Dimensius sich aus dieser Existenzebene zurückziehen kann, zu verschließen, können wir sie und Dimensius vernichten.|n|nDazu müsst Ihr zunächst Fragmente von Dimensius von den Leerkreaturen, die für ihn die Drecksarbeit erledigen, sammeln.', },
    {'Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr 8 Fragmente von Dimensius besorgt.', },
  },
  [10438] = {
    'Auf netherischen Schwingen',
    {'Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr den Phasenstörer bei der Leerleitung auf der Manaschmiede Ultris benutzt. Sendet so viele Störsignale wie möglich aus, um eine komplette Zerstörung zu gewährleisten. Die Entladungen des Phasenstörers werden automatisch das Ziel treffen, solange Ihr nahe genug seid, um ihn zu benutzen.|n|nKehrt zu Professor Dabiri zurück, wenn Ihr erfolgreich wart!', },
    {'Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr den Phasenstörer bei der Leerleitung auf der Manaschmiede Ultris benutzt. Sendet so viele Störsignale wie möglich aus, um eine komplette Zerstörung zu gewährleisten. Die Entladungen des Phasenstörers werden automatisch das Ziel treffen, solange Ihr nahe genug seid, um ihn zu benutzen.|n|nKehrt zu Professor Dabiri zurück, wenn Ihr erfolgreich wart!', },
  },
  [10439] = {
    'Dimensius der alles Verschlingende',
    {'Eure mutigen Taten haben Ameer zum handeln bewegt! Er hat Hauptmann Saeed und die Rächer Aufstellung nehmen lassen!|n|nJetzt müssen wir nur noch Dimensius vernichten.|n|nWenn Ihr bereit seid, lasse ich Saeed rufen. Wenn er nicht gerade einen anderen Auftrag ausführt, wartet er östlich von hier auf Eure Befehle.|n|nLasst ihn wissen, wenn Ihr bereit seid zu kämpfen, damit er seine Truppen in Bewegung setzen kann.|n|nViel Glück, Fleischling! Wir jagen Dimensius schon seit tausend Jahren!', },
    {'Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr mit Hauptmann Saeed sprecht, seiner Armee zur Manaschmiede Ultris folgt und Dimensius den alles Verschlingenden tötet!', },
  },
  [10440] = {
    'Erfolg!',
    {'Der Test war ein großer Erfolg! Wir können das Gerät benutzen, um die Kuppeln zu reparieren.|n|nBerichtet in der Sturmsäule von den Testergebnissen und lasst Ghabar wissen, dass ich ein Muster in den Schäden an den Schildgeneratoren entdeckt habe. Wichtige Teile der Generatoreinheiten sind an verschiedenen Orten verschwunden. Das ist kein Zufall, $N, kein technischer Fehler. Wir werden bestohlen.', },
    nil,
  },
  [10441] = {
    'Die Waren unters Volk bringen.',
    {'<Audi senkt die Stimme wieder.>|n|nJetzt, da wir die Waren haben, werde ich die meisten davon nach Area 52 schicken. Wir haben hier mehr, als wir für einen Generator brauchen, was uns eine perfekte Geschäftsmöglichkeit eröffnet.|n|nIch habe gesehen, dass die Vertreterin der Expedition des Cenarius verhandeln will. Ich möchte, dass Ihr sie wissen lasst, dass wir ihr das, was sie sucht, zu einem günstigen Preis geben können. Es gibt kein Grund für sie, sich weiter mit diesen betrügerischen Astralen herumzuschlagen.', },
    {'Sprecht mit Aurine Mondflamm unten in der Sturmsäule im Nethersturm.', },
  },
  [10442] = {
    'Dem Posten des Cenarius helfen',
    {'$C, es gibt hier eine Tauren namens Thiah Rotmähne, die uns ständig um Hilfe anfleht. Sie gehört zur Expedition des Cenarius, die einen kleinen Posten im Westen, auf der südlichen Seite der Straße in Richtung Zangarmarschen, errichtet hat.|n|nWenn Ihr beim Dornnebelhügel angekommen seid, seid Ihr zu weit gegangen.|n|nKönntet Ihr vielleicht dort hingehen und nachschauen, was sie braucht? Ich möchte Waldläuferhauptmann Venn\'ren nicht mit solchen Kleinigkeiten belästigen.', },
    {'Falknerin Drenna Flusswind möchte, dass Ihr Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel Eure Dienste anbietet.', },
  },
  [10443] = {
    'Dem Posten des Cenarius helfen',
    {'Der Zirkel des Cenarius hat eine Expedition in die Scherbenwelt geschickt. So weit ich verstanden habe, sind sie hier, um zu untersuchen, was passiert ist, und wenn möglich die Schäden rückgängig zu machen.|n|nSie haben einen kleinen Posten im Westen, auf der südlichen Seite der Straße in Richtung Zangarmarschen, errichtet.|n|nKönnt Ihr vielleicht dort hingehen und schauen, wie Ihr ihnen helfen könnt? Sprecht mit Thiah Rotmähne. Sie hat uns um Hilfe gebeten.', },
    {'Amaan der Weise möchte, dass Ihr Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel Eure Dienste anbietet.', },
  },
  [10444] = {
    'Meldung bei Allerias Posten',
    {'Das erfordert sofortiges Handeln!|n|nWir haben jemanden da draußen, der sich noch näher am Posten der Feuerschwingen befindet. Ich möchte, dass Ihr mit ihm sprecht. Er weiß sicher besser, was wir als Nächstes tun sollten.|n|nMeldet Euch bei Leutnant Meridian bei Allerias Posten und setzt ihn von der Lage in Kenntnis. Ihr findet den Posten im Nordosten am südlichen Ufer des Flusses, direkt südlich vom Posten der Feuerschwingen.|n|nBeeilt Euch, $N!', },
    {'Jenai Sternwisper möchte, dass Ihr Euch bei Leutnant Meridian in Allerias Posten in den Wäldern von Terokkar meldet.', },
  },
  [10445] = {
    'Die Phiolen der Ewigkeit',
    {'Illidan entnahm sieben Phiolen aus dem Brunnen der Ewigkeit. Drei davon leerte er in den See auf dem Berg Hyjal, wodurch ein zweiter Brunnen der Ewigkeit entstand. Jahrelang glaubte man den Rest verloren.|n|nSeit der Öffnung des Dunklen Portals haben wir erfahren, dass er seinen Leutnants Kael\'thas und Vashj je eine Phiole gegeben hat. Holt zurück, was von den Phiolen noch übrig ist. Wir brauchen sie als Fokus, um ein Tor zu den Geschehnissen, seien sie aktuell oder vergangen, am Berg Hyjal zu öffnen. Das Ergebnis der Schlacht um den Berg Hyjal muss erhalten bleiben.', },
    {'Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole im Echsenkessel und die Überreste von Kaels Phiole von Kael\'thas Sonnenwanderer in der Festung der Stürme besorgt.', },
  },
  [10446] = {
    'Der finale Code',
    {'Sie bauen eine zweite Manabombe im Hof! Meine Agenten berichten, dass Sharth Voldoun, der Zuständige des Projekts im Posten der Feuerschwingen, den finalen Code der Bombe haben muss.|n|n$N, Ihr müsst dorthin zurückkehren und den letzten Code von ihm besorgen. Er hält sich auf der Spitze der höchsten Säule auf.|n|nBringt den finalen Code zu der Manabombe, an der sie im mittleren Hof arbeiten, und gebt ihn ein.|n|nNur dann können wir sicher sein, dass Allerias Feste gerettet ist.', },
    {'Leutnant Meridian möchte, dass Ihr den finalen Code eingebt, um die Manabombe auszulösen. Meldet euch dann bei Jenai Sternwisper in Allerias Feste in den Wäldern von Terokkar zurück.', },
  },
  [10447] = {
    'Der finale Code',
    {'Sie bauen eine zweite Manabombe im Hof! Meine Agenten berichten, dass Sharth Voldoun, der Zuständige des Projekts im Posten der Feuerschwingen, den finalen Code der Bombe haben muss.|n|n$N, Ihr müsst dorthin zurückkehren und den letzten Code von ihm besorgen. Er hält sich auf der Spitze der höchsten Säule auf.|n|nBringt den finalen Code zu der Manabombe, an der sie im mittleren Hof arbeiten, und gebt ihn ein.|n|nNur dann können wir sicher sein, dass die Steinbrecherfeste gerettet ist.', },
    {'Unteroffizier Chawni möchte, dass Ihr den finalen Code eingebt, um die Manabombe auszulösen. Meldet euch dann bei Tooki in der Steinbrecherfeste in den Wäldern von Terokkar zurück.', },
  },
  [10448] = {
    'Meldung beim Steinbrecherlager',
    {'Das erfordert sofortiges Handeln!|n|nWir haben jemanden da draußen, der sich noch näher am Posten der Feuerschwingen befindet. Ich möchte, dass Ihr mit ihr sprecht. Sie weiß sicher besser, was wir als Nächstes tun sollten.|n|nMeldet Euch bei Unteroffizier Chawni im Steinbrecherlager und setzt sie von der Lage in Kenntnis.|n|nNehmt die Straße nach Norden aus der Feste heraus. Ab der Mitte von Tuurem müsst Ihr der Straße nach Osten folgen. Ihr findet das Lager am Ufer des Flusses, der direkt südwestlich des Postens der Feuerschwingen liegt.|n|nBeeilt Euch, $N!', },
    {'Tooki möchte, dass Ihr Euch bei Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar meldet.', },
  },
  [10449] = {
    'Apothekerin Zelana',
    nil,
    {'Vurtok Axtbrecher in Thrallmar möchte, dass Ihr die Blutprobe eines Knochenmalmers zu Apothekerin Zelana im Häschersturz bringt.', },
  },
  [10450] = {
    'Knochenmalmerblut',
    {'Knochenmalmer! Sie sollen alle sterben! Der Anblick ihrer roten Haut und ihrer Verkommenheit bringt mein Blut zum kochen!|n|nIch habe einen Auftrag für Euch, $N. Tötet die Orcs der Knochenmalmer und sammelt ihr bösartiges Blut. Es gibt eine Apothekerin, die vielleicht herausfinden kann, wie diese Orcs der Verderbnis der Dämonen anheim fallen konnten, eine Verderbnis, derer wir uns vor so kurzer Zeit erst entledigen konnten.|n|nDie Knochenmalmer streunen in der Nähe der zerstörten Kriegsmaschinerien entlang des Pfads der Ehre im Süden herum. Kehrt zu mir zurück, wenn Euer Auftrag erfüllt ist.', },
    {'Bringt 12 Phiolen mit Blut eines Knochenmalmers zu Vurtok Axtbrecher in Thrallmar.', },
  },
  [10451] = {
    'Flucht aus der Zisterne der Echsennarbe',
    {'Der Erdenmutter sei Dank! Ich habe mich vor ein paar Tagen von den anderen getrennt. Ich wollte der Quelle der Veränderung des Wassers, die wir spüren, auf den Grund gehen. Meine Suche führte mich zur Echsennarbe, wo ich herausgefunden habe, dass die Naga die Wasservorräte des Schattenmondtals verderben!|n|nUnglücklichweise hat man mich entdeckt und gefangen genommen. Nicht auszudenken, welch grausame Dinge sie mit mir vorhatten!|n|nWir müssen hier weg. Helft mir zu fliehen und sucht dann Torlok beim Altar der Verdammnis auf.', },
    {'Begleitet Erdheilerin Wilda aus der Zisterne der Echsennarbe hinaus und sucht dann Erdheiler Torlok beim Altar der Verdammnis am westlichen Rang der Hand von Guldan auf.', },
  },
  [10455] = {
    'Die nahende Wildnis',
    {'Wir haben den Lebenden Hain sehr schnell zum Wachsen gebracht, aber nun haben wir die Kontrolle über die Luchse verloren.|n|nEinst war ihre Population gleichmäßig, aber nun kommen die Hainpirscherluchse immer näher an Sylvanaar heran. In letzter Zeit gab es schon einige unerfreuliche Zwischenfälle.|n|nIch nehme an, dass die Arakkoa vom Lashhversteck dahinter stecken, aber zunächst sind die Luchse selbst unser Problem.|n|nIch wäre Euch sehr dankbar, wenn Ihr uns dabei helfen würdet, mit dieser Lage fertigzuwerden.', },
    nil,
  },
  [10456] = {
    'Marodierende Wölfe',
    {'Die abscheulichen Völker der Horde haben eine alte Siedlung im Osten eingenommen. Sie haben ein großes Rudel von Terrorwölfen mitgebracht, die sie gerne als Reittiere und Wachhunde einsetzen.|n|nDiese "Wachhunde" haben jedoch begonnen, hinter der Brücke, die uns voneinander trennt, Schaden anzurichten. Sie belästigen unsere Feendrachen, die für die Bestäubung unseres Waldes unersetzlich sind.|n|nNehmt den östlichen Ausgang, um die Brücke über der Blutschlägerklamm, die zum Zackengrat im Osten führt, zu überqueren, und bringt mir ihre Schwänze!', },
    nil,
  },
  [10457] = {
    'Die Eigenen schützen',
    {'Trotz der guten Arbeit, die Ihr geleistet habt, bin ich immer noch der Meinung, dass der Lebende Hain mehr Schutz braucht.|n|nBitte, nehmt diesen kleinen Zweig. Ich habe ihn mit der Macht der Natur verstärkt. Wenn er bei den Setzlingen, die ich im Hain gepflanzt habe, eingesetzt wird, ruft er einen Sturm herbei, der sie schnell zu großen Treantverteidigern heranwachsen lässt.|n|nDiese Treants sind für die Verteidigung des Waldes unverzichtbar, besonders, wenn man nicht für immer in Sylvanaar leben möchte.', },
    nil,
  },
  [10458] = {
    'Wütende Geister des Feuers und der Erde',
    {'Wir müssen versuchen, die Dinge zu ändern. Wir müssen mit den Elementen dieser Gegend kommunizieren und schauen, ob wir etwas tun können!|n|nIch gebe Euch das Totem der Geister, $R. Wenn Ihr einen wütenden Elementargeist in der Nähe des Totems umbringt, wird es die Seele des Elementars aufnehmen. Ihr müsst viele Seelen mithilfe des Totems einfangen, bevor Ihr zu mir zurückkehrt.|n|nSammelt zuerst die Seelen der Geister des Feuers und der Geister der Erde. Kehrt zu mir zurück, wenn das Totem voll ist.', },
    {'Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 8 Erdenseelen und 8 Feuerseelen einzufangen.', },
  },
  [10459] = {
    'Respektvoll bei der Expedition des Cenarius',
    {'Eure Erfolge sind uns aufgefallen, $N. Was Ihr für uns getan habt geht weit über das, was wir von Verbündeten erwarten, hinaus.|n|nIch habe eine besondere Bitte an Euch, aber zunächst muss ich Eure Hingabe testen.', },
    {'Ysiel Windsänger bei der Zuflucht des Cenarius möchte, dass Euch einen respektvollen Ruf bei der Expedition des Cenarius verdient.', },
  },
  [10460] = {
    'Das Versprechen des Verteidigers',
    nil,
    nil,
  },
  [10461] = {
    'Das Versprechen des Bewahrers',
    nil,
    nil,
  },
  [10462] = {
    'Das Versprechen des Helden',
    nil,
    nil,
  },
  [10463] = {
    'Das Versprechen des Weisen',
    nil,
    nil,
  },
  [10464] = {
    'Das Gelöbnis des Weisen',
    {'Ihr habt Euer Versprechen gegeben, $C. Jetzt liegt es an Euch, es einzuhalten.|n|nDient den Wächtern der Sande wohl, und Ihr werdet Euren Lohn erhalten.|n|nWenn Ihr scheitert, wird die Zeitlinie, wie wir sie kennen, zerrissen werden!', },
    {'Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen wohlwollenden Ruf bei den Wächtern der Sande erlangt habt.', },
  },
  [10465] = {
    'Das Gelöbnis des Bewahrers',
    {'Ihr habt Euer Versprechen gegeben, $C. Jetzt liegt es an Euch, es einzuhalten.|n|nDient den Wächtern der Sande wohl, und Ihr werdet Euren Lohn erhalten.|n|nWenn Ihr scheitert, wird die Zeitlinie, wie wir sie kennen, zerrissen werden!', },
    {'Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen wohlwollenden Ruf bei den Wächtern der Sande erlangt habt.', },
  },
  [10466] = {
