    nil,
    nil,
  },
  [10733] = {
    'Der violette Pfad',
    {'Ihr habt Euren Pfad gewählt, $C. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.|n|nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.', },
    {'Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.', },
  },
  [10734] = {
    'Der violette Pfad',
    {'Ihr habt Euren Pfad gewählt, $C. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.|n|nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.', },
    {'Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.', },
  },
  [10735] = {
    'Der violette Pfad',
    {'Ihr habt Euren Pfad gewählt, $C. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.|n|nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.', },
