  [13688] = {
    'Ein Recke von Gnomeregan',
    {'Ihr habt Euch als würdig erwiesen, unter dem Banner von Gnomeregan anzutreten, $N. Nun solltet Ihr mit Ambrose Bolzenfunk sprechen, der die Wettkämpfer von Gnomeregan anführt. Als Großchampion der Gnome wird er Euch in ihrem Namen für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.|n|nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, $N, und ich wünsche Euch Glück im bevorstehenden Wettkampf.', },
    {'Sprecht mit Ambrose Bolzenfunk beim Argentumturnierplatz, um ein Recke von Gnomeregan zu werden.', },
  },
  [13689] = {
    'Ein Recke von Darnassus',
    {'Ihr habt Euch als würdig erwiesen, unter dem Banner von Darnassus anzutreten, $N. Nun solltet Ihr mit Jaelyne Abendlied sprechen, die die Wettkämpfer von Darnassus anführt. Als Großchampion der Nachtelfen wird sie Euch in ihrem Namen für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.|n|nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, $N, und ich wünsche Euch Glück im bevorstehenden Wettkampf.', },
    {'Sprecht mit Jaelyne Abendlied beim Argentumturnierplatz, um ein Recke von Darnassus zu werden.', },
  },
  [13690] = {
    'Ein Recke der Exodar',
    {'Ihr habt Euch als würdig erwiesen, unter dem Banner der Exodar anzutreten, $N. Nun solltet Ihr Euch Kolosos vorstellen, dem Leiter der Delegation der Exodar. Als Großchampion der Draenei wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.|n|nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, $N, und ich wünsche Euch Glück im bevorstehenden Wettkampf.', },
    {'Sprecht mit Kolosos beim Argentumturnierplatz, um ein Recke der Exodar zu werden.', },
  },
  [13691] = {
    'Ein Recke von Orgrimmar',
    {'Ihr habt Euch als würdig erwiesen, unter dem Banner von Orgrimmar anzutreten, $N. Nun solltet Ihr mit Mokra dem Schädelberster sprechen, der Orgrimmars Wettkämpfer anführt. Als Großchampion von Orgrimmar wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.|n|nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, $N, und ich wünsche Euch Glück im bevorstehenden Wettkampf.', },
    {'Sprecht mit Mokra dem Schädelberster beim Argentumturnierplatz, um ein Recke von Orgrimmar zu werden.', },
  },
  [13692] = {
    'Das Schwert und die See',
    {'Mein Schwert ist auf See verloren gegangen. Holt es herauf und bringt es zurück!', },
    {'Der alte Barlo im Kristallsangwald möchte, dass Ihr ihm das Schwert der Ritterwürde bringt.', },
  },
  [13693] = {
    'Ein Recke von Sen\'jin',
    {'Ihr habt Euch als würdig erwiesen, unter dem Banner von Sen\'jin anzutreten, $N. Nun solltet Ihr mit Zul\'tore sprechen, der die Krieger von Sen\'jin anführt. Als Großchampion der Trolle wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.|n|nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, $N, und ich wünsche Euch Glück im bevorstehenden Wettkampf.', },
    {'Sprecht mit Zul\'tore beim Argentumturnierplatz, um ein Recke von Sen\'jin zu werden.', },
  },
  [13694] = {
    'Ein Recke von Donnerfels',
    {'Ihr habt Euch als würdig erwiesen, unter dem Banner von Donnerfels anzutreten, $N. Nun solltet Ihr mit Runok Wildmähne sprechen, der Donnerfels\' Wettkämpfer anführt. Als Großchampion von Donnerfels wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.|n|nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, $N, und ich wünsche Euch Glück im bevorstehenden Wettkampf.', },
    {'Sprecht mit Runok Wildmähne beim Argentumturnierplatz, um ein Recke von Donnerfels zu werden.', },
  },
  [13695] = {
    'Ein Recke von Unterstadt',
    {'Ihr habt Euch als würdig erwiesen, unter dem Banner von Unterstadt anzutreten, $N. Nun solltet Ihr mit Todespirscher Visceri sprechen, der Unterstadts Wettkämpfer anführt. Als Großchampion wird er Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird er Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.|n|nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, $N, und ich wünsche Euch Glück im bevorstehenden Wettkampf.', },
    {'Sprecht mit Todespirscher Visceri beim Argentumturnierplatz, um ein Recke von Unterstadt zu werden.', },
  },
  [13696] = {
    'Ein Recke von Silbermond',
    {'Ihr habt Euch als würdig erwiesen, unter dem Banner von Silbermond anzutreten, $N. Nun solltet Ihr mit Eressea Morgensänger sprechen, die Silbermonds Wettkämpfer anführt. Als Großchampion von Silbermond wird sie Euch im Auftrag der Stadt für das Turnier anmelden. Außerdem wird sie Euer Training und Eure Prüfungen beaufsichtigen, solange Ihr Recke seid.|n|nEs war mir eine Ehre, mit Euch zusammenzuarbeiten, $N, und ich wünsche Euch Glück im bevorstehenden Wettkampf.', },
    {'Sprecht mit Eressea Morgensänger beim Argentumturnierplatz, um ein Recke von Silbermond zu werden.', },
  },
  [13697] = {
    'Das Wappen des Recken',
    {'In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.|n|nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.|n|nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.', },
    {'Bringt 25 Siegel des Recken zu Mokra dem Schädelberster beim Argentumturnierplatz.', },
  },
  [13698] = {
    'Sprengstoffschreddern',
    {'Ich hasse es, Euch wieder dorthin zurückzuschicken, aber Eurer Beschreibung entnehme ich, dass wir es nicht zulassen dürfen, dass sie den ganzen Sprengstoff verwenden, den sie gelagert haben!|n|nEs ist zu gefährlich für Euch, ihn einfach so zu zerstören, aber wenn Ihr einen der Schredder stehlen könntet, bin ich mir sicher, dass er robust genug ist, den Explosionen standzuhalten.|n|nNachdem Ihr den Sprengstoff vernichtet habt, kehrt mit dem Schredder wieder hierher zurück. Es wäre närrisch, ihn wieder der Horde zu überlassen.', },
    {'Verwendet einen Kriegshymnenschredder um 8 Fässer mit Sprengstoff zu vernichten.', },
  },
  [13699] = {
    'Die Herausforderung des Recken',
    {'Ihr seid fast bereit, im Namen Sturmwinds beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, für unsere Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.|n|nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.|n|nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.', },
    {'Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Marschall Jacob Alerius beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13700] = {
    'Markierung für Champion der Allianz',
    nil,
    nil,
  },
  [13701] = {
    'Markierung für Champion der Horde',
    nil,
    nil,
  },
  [13702] = {
    'Aufstieg eines Champions',
    {'Herzlichen Glückwunsch, $N. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.|n|nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, $N, und Euch offiziell beim großen Arenakampf der Champions anzumelden.', },
    {'Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.', },
  },
  [13703] = {
    'Recke von Eisenschmiede',
    {'Seid willkommen, Champion. Ich habe schon von Euren Kampffertigkeiten gehört. Wollt Ihr der Turniersdelegation von Eisenschmiede beitreten?|n|nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion von Eisenschmiede ernannt hat, wird Euer Knappe unser Banner in die Schlacht tragen dürfen.', },
    {'Sprecht wieder mit Lana Starkhammer, falls Ihr ein Recke von Eisenschmiede werden wollt.', },
  },
  [13704] = {
    'Recke von Gnomeregan',
    {'Seid willkommen, Champion. Ich habe schon von Euren Kampffertigkeiten gehört. Gnomeregans Delegation könnte von jemandem wie Euch wirklich profitieren.|n|nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Gnomeregan ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.', },
    {'Sprecht wieder mit Ambrose Bolzenfunk, falls Ihr ein Recke von Gnomeregan werden wollt.', },
  },
  [13705] = {
    'Recke der Exodar',
    {'Seid willkommen, Champion. Ich habe schon von Euren Heldentaten gehört. Wollt Ihr der Turniersdelegation der Exodar beitreten?|n|nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion der Exodar ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.', },
    {'Sprecht wieder mit Kolosos, falls Ihr ein Recke der Exodar werden wollt.', },
  },
  [13706] = {
    'Recke von Darnassus',
    {'Seid willkommen, Champion. Ich habe von Euren Leistungen gehört und wir wären geehrt, wenn Ihr der Delegation von Darnassus beitreten würdet.|n|nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Darnassus ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.', },
    {'Sprecht wieder mit Jaelyne Abendlied, falls Ihr ein Recke von Darnassus werden wollt.', },
  },
  [13707] = {
    'Recke von Orgrimmar',
    {'Ihr seid also ein Champion geworden? Dann habt Ihr Euch als würdiger Kämpfer erwiesen und ich wäre stolz, Euch in Orgrimmars Delegation begrüßen zu dürfen.|n|nIhr werdet wie auch zuvor trainieren und die Rangleiter hochklettern, doch sobald man Euch zum Champion von Orgrimmar ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.', },
    {'Sprecht wieder mit Mokra dem Schädelberster, falls Ihr ein Recke von Orgrimmar werden wollt.', },
  },
  [13708] = {
    'Recke von Sen\'jin',
    {'Grüße, Champion. Wenn Ihr wollt, dann würde ich Euch in Sen\'jins Turniersdelegation willkommen heißen.|n|nIhr werdet wie auch zuvor trainieren und die Rangleiter hochklettern, doch sobald man Euch zum Champion von Sen\'jin ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.', },
    {'Sprecht wieder mit Zul\'tore, falls Ihr ein Recke von Sen\'jin werden wollt.', },
  },
  [13709] = {
    'Recke von Donnerfels',
    {'Willkommen, Champion. Als Großchampion der Delegation von Donnerfels wäre ich stolz darauf, Euch in unseren Reihen begrüßen zu dürfen, falls Ihr dies wünscht.|n|nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Donnerfels ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.', },
    {'Sprecht wieder mit Runok Wildmähne, falls Ihr ein Recke von Donnerfels werden wollt.', },
  },
  [13710] = {
    'Recke von Unterstadt',
    {'Seid willkommen, Champion. Die Delegation der Verlassenen könnte immer so jemanden wie Euch gebrauchen. Wollt Ihr uns beitreten?|n|nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Unterstadt ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.', },
    {'Sprecht wieder mit Todespirscher Visceri, falls Ihr ein Recke von Unterstadt werden wollt.', },
  },
  [13711] = {
    'Recke von Silbermond',
    {'Ihr seid also ein Champion geworden? Dann habt Ihr Euch als würdiger Kämpfer erwiesen und ich wäre stolz, Euch in Silbermonds Delegation begrüßen zu dürfen.|n|nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion von Silbermond ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.', },
    {'Sprecht wieder mit Eressea Morgensänger, falls Ihr ein Recke von Silbermond werden wollt.', },
  },
  [13712] = {
    'Rettungseinsatz!',
    {'Ihr kommt mit mir mit, $N.|n|nIch kann niemanden sonst erübrigen und wir können es uns nicht leisten, den Splitterholzposten zu verlieren.|n|nBereitet Euch gut vor und sprecht mich wieder an, wenn Ihr soweit seid.', },
    {'Sprecht mit Kadrak am Schutzwall von Mor\'shan und begleitet ihn zum Splitterholzposten.', },
  },
  [13713] = {
    'Die Herausforderung des Recken',
    {'Ihr seid fast bereit, im Namen von Eisenschmiede beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, für unsere Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.|n|nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen.|n|nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.', },
    {'Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Lana Starkhammer beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13714] = {
    'Das Wappen des Recken',
    {'In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.|n|nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.|n|nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.', },
    {'Bringt 25 Siegel des Recken zu Lana Starkhammer beim Argentumturnierplatz.', },
  },
