  [13782] = {
    'Der große Arenakampf',
    {'Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.|n|nEs wird helfen, Euch auf die Härte des Kampfes vorzubereiten.|n|nGeht zu den Reittieren außerhalb des Pavillon, nehmt Eure Lanze, steigt auf das Schlachtross der Verlassenen, das dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.', },
    {'Bringt 3 Male des Recken zu Tierführer Dretch beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.', },
  },
  [13783] = {
    'Eine Klinge, eines Champions würdig',
    {'Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.|n|nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, $N. Ansonsten fangt Ihr Euch Warzen ein.', },
    {'Besorgt Eschenbrand und bringt es Eressea Morgensänger beim Argentumturnierplatz.', },
  },
  [13784] = {
    'Eine würdige Waffe',
    {'Ausgerechnet jetzt so ein Unglück!|n|nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak\'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul\'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.', },
    {'Bringt Eressea Morgensänger beim Argentumturnierplatz die Klinge von Drak\'Mar.', },
  },
  [13785] = {
    'Auf Winters Schneide',
    {'Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!|n|nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.|n|nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.|n|nZeigt, was Ihr wert seid und verdient Euch die Waffe, die sie nun schon so lange bewacht, $N.', },
    {'Eressea Morgensänger beim Argentumturnierplatz möchte, dass Ihr ihr Winterschneide bringt.', },
  },
  [13786] = {
    'Feldübungen eines Recken',
    {'Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.|n|nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp\'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.', },
    {'Kethiel Sonnenlanze beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.', },
  },
  [13787] = {
    'Der große Arenakampf',
    {'Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.|n|nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.|n|nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Falkenschreiter von Silbermond, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.', },
    {'Bringt 3 Male des Recken zu Aneera Thuron beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13788] = {
    'Bedrohung von oben',
    {'Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher halt machen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.|n|nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.|n|nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur\'thar herum.', },
    {'Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.', },
  },
  [13789] = {
    'Die Schlacht zum Gegner tragen',
    {'Das Kolosseum befindet sich im gefährlichsten Teil der Welt, $N. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.|n|nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.', },
    {'Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Anhänger des Kults der Verdammten im Bereich von Eiskrone.', },
  },
  [13790] = {
    'Unter Champions',
    {'Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
    {'Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13791] = {
    'Die Schlacht zum Gegner tragen',
    {'Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.|n|nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur\'thar und Todessprechers Wacht vertreten.', },
    {'Zor\'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.', },
  },
  [13792] = {
    'Der Schattenwandler',
    {'Jetzt, wo die Dämonentore zerstört sind, muss die Kraft des Waldes wieder regeneriert werden. Das Herz des Waldes muss wiedererlangt werden!|n|nGaivan Schattenwandler, ein mächtiger Druide der Klaue ist Richtung Südwesten am Dämonenhügel vorbei zum Grabhügel von Dor\'Danil gegangen. Darin liegt das Herz des Waldes. Es wird von den Druiden von Eschental tief unter der Oberfläche beschützt.|n|nSucht nach Gaivan und erzählt ihm, was sich zugetragen hat, $N.', },
    {'Sprecht mit Gaivan Schattenwandler, der vor dem Eingang zum Grabhügel von Dor\'Danil im Eschental wandelt.', },
  },
  [13793] = {
    'Unter Champions',
    {'Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen besiegt. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.|n|nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt irgendein Euch zur Verfügung stehendes Reittier aus und fordert sie heraus.', },
    {'Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.', },
  },
  [13794] = {
    'Eadric der Reine',
    {'Ich habe meine Brüder des Argentumkreuzzugs gebeten, eng mit denjenigen zusammenzuarbeiten, die zum Champion aufsteigen. Eadric der Reine, der Großchampion unserer Bruderschaft, hilft dabei, die Trainingsübungen für Champions aller Städte zu beaufsichtigen und sie bei ihren letzten Vorbereitungen für den Turnierwettkampf zu unterstützen.|n|nBitte geht nun und stellt Euch ihm vor. Ich bin mir sicher, dass er begierig darauf sein wird, Eure Bekanntschaft zu machen und Euch auf Eurem Weg zum Wettkampf mit Azeroths größten Champions zu begleiten.', },
    {'Sprecht mit Eadric dem Reinen beim Argentumturnierplatz.', },
  },
  [13795] = {
    'Der Geißelbann',
    {'Der Delegationsanführer der Ritter der Schwarzen Klinge hat darum gebeten, mit Euch zu sprechen, $C. Crok Geißelbann ist ein äußerst furchterregender Kämpfer und ich hege keine Zweifel daran, dass er viel von Euch fordern wird.|n|nDie Ritter der Schwarzen Klinge haben auf der Nordseite des Turnierplatzes ihr Lager aufgeschlagen, westlich der Zeltbehausungen der Allianzdelegationen.', },
    {'Sprecht mit Crok Geißelbann beim Argentumturnierplatz.', },
  },
  [13796] = {
    'Das Herz des Waldes',
    {'Ihr müsst das Herz des Waldes um jeden Preis zu Knorre bringen!|n|nEs liegt tief unten im Grabhügel von Dor\'Danil - verdorben von der Horde. Nur Knorre kann es reinigen.|n|nUm es vom Fleck zu bewegen, braucht Ihr jedoch eine Kraft der Natur. Wenn Ihr ausreichend reine Erdgeister von den abtrünnigen Druiden und Bewahrern einsammelt, können die Erdgeister zu einer Kraft der Natur vereint werden.|n|nViel Glück, $N!', },
    {'Beschafft das Herz des Waldes.', },
  },
  [13797] = {
    'Gemeinheiten',
    {'Draaka benötigt eine Art von Magnet – etwas, das ihre dämonischen Geschosse anzieht.|n|n<Durak grinst verschlagen.>|n|nZufällig kenne ich eine Methode, die unserem Zwecke dienlich sein sollte.|n|nIhr sucht die Minen nach faustgroßen Erzklumpen ab, und ich bereite eine besondere... Verzauberung vor.', },
    {'Durchsucht die Haufen frischen Gerölls, um 10 Erzklumpen zu finden.', },
  },
  [13798] = {
    'Regen der Zerstörung',
    nil,
    {'Nutzt das verfluchte Erz, um Ziele für Draaka zu markieren. Ihr müsst 30 Nachtelfentruppen und 5 tobende Urtume töten.|n|nSprecht mit Durak, um die Wichtelverkleidung aufzufrischen.', },
  },
  [13799] = {
    'Wo sind meine Schlüssel?',
    {'Ich kann meine Schlüssel nicht finden! Sicher ist mein böser Zwilling schuld daran. Bitte "kümmert" Euch um ihn, $N.', },
    {'Dr. Finger möchte, dass Ihr seinen bösen Zwilling, Bösfinger, tötet und ihm seine Schlüssel abnehmt.', },
  },
  [13800] = {
    'Holt meine Schlüssel!',
    {'Packt sie!', },
    {'Findet die Schlüssel von Dr. Finger.', },
  },
  [13801] = {
    'Geisterelfen',
    {'H-habt Ihr das gehört? Geister! Ich hasse Geister!|n|nIhr schauerliches Geheul kommt aus den Grabhügeln im Süden. Ahhh! Macht, dass sie aufhören!|n|nBitte, $Gmein Herr:gnädiges Fräulein;, ich zahle gutes Geld dafür, wenn Ihr mir diese Stimmen aus dem Kopf schafft!', },
    {'Vernichtet 15 beliebige Nachtelfengeister in den Grabhügeln von Dor\'Danil.', },
  },
  [13802] = {
    'Der Goblin mit zwei Gehirnen',
    {'Seht Ihr sie dort, entlang der Küste? Was für prächtige Exemplare! Seht Euch nur an, wie Ihre primitive Gesellschaft zusammenarbeitet, wie eine gut geölte Maschine, vom niedrigsten Arbeiter bis zu ihrem Anführer, den ich "König Burgrurble" genannt habe.|n|nIch muss einfach ihre Gehirne untersuchen."|n|nKönnt Ihr mir ein intaktes Stammhirn eines Sabberzahnmurlocs beschaffen? Tötet sie - für die Wissenschaft!', },
    {'Bringt das Stammhirn eines Sabberzahnmurlocs zu Professor Flozz an der Küste.', },
  },
  [13803] = {
    'Das Blut der Schwachen',
    {'Wir wussten, dass die Elfen sich nicht kampflos ergeben würden, aber niemand hatte damit gerechnet, dass sie es fertig bringen, den Splitterholzposten zu belagern...|n|nEs wird Zeit, dass sie dafür bezahlen!|n|nIn der Nähe, im Grabhügel von Dor\'Danil, liegt etwas, das dem Feind äußerst teuer ist – das Herz des Waldes.|n|nIch brauche jemanden, der sich bis zum Herzen durchschlägt und es verderbt.|n|nDieser jemand seid Ihr, $N.|n|nDoch zunächst bringt meine Axt zu Durak hier in den Minen. Er wird mit dem Blut unserer Feinde etwas anzufangen wissen.', },
    nil,
  },
  [13804] = {
    'Wie man ein Fischding fängt',
    {'Schaut Euch nur die Ergebnisse an! Welch einzigartige elektrochemische Zusammensetzung! Ah, aber ich nehme nicht an, dass $Gein bescheidener:eine bescheidene:c; $C wie Ihr die Magnitüde meiner Entdeckung verstehen würde. Ich brauche ein lebendes Exemplar.|n|nIch würde mir ja selbst eines besorgen, aber offensichtlich sind sie bissig.|n|nHier, ich habe diese Falle so konfiguriert, dass sie sich ihren einzigartigen Hirnströmen anpasst. Stellt einfach die Falle auf und drückt diese Taste, um einen Sabberzahn einzusaugen. Doch zuerst müsst Ihr diesen Haftungsausschluss unterzeichnen. Diese Technologie ist das Neuste vom Neuen!', },
    {'Stellt die Falle auf und benutzt die Fernbedienung, um einen lebenden Sabberzahnmurloc zu fangen. Bringt die gefüllte Falle zu Professor Flozz zurück.', },
  },
  [13805] = {
    'Mitten ins Herz!',
    {'So...|n|nDas Blut der gefallenen Kaldorei hat sich gewandelt. Es kann jetzt auf das Herz des Waldes im Grabhügel von Dor\'Danil angewandt werden. Dadurch wird es gänzlich verderbt werden.|n|nDas heilige Relikt der hochmütigen Elfen wird gegen sie gerichtet. Das ist die Ironie des Lebens!|n|n<Durak lacht gehässig.>|n|nDer Grabhügel schmiegt sich in die Hügel im Südosten. Einer meiner Wichtel hat eine Blutspur gelegt, die vom Eingang bis zum Herzen führt.|n|nEilt Euch! Kadrak ist wahrscheinlich nicht besonders geduldig.|n|nFort mit Euch, $C.', },
    nil,
  },
  [13806] = {
    'Dämonendienst',
    {'Höret, $C, ich weiß, dass dieser Angriff auf den Splitterholzposten uns alle mitgenommen hat, aber falls wir die Satyrportale aus den Augen verlieren, steht uns nach dieser Krise eine noch größere bevor.|n|n<Locke starrt Euch ausdruckslos an.>|n|nIhr wisst nichts von den Portalen?|n|nIm Nordosten in der Region von Satyrnaar und Xavian unternehmen die Satyrn den Versuch, Dämonen zu beschwören, um ihre Zahl zu stärken.|n|nWir müssen diese Portale schließen, egal was sich uns dort auch in den Weg stellen mag.', },
    {'Locke Okarr im Splitterholzposten will, dass Ihr 12 Satyrportale in Satyrnaar und Xavian schließt.', },
  },
  [13807] = {
    'Kennzeichnung: Turniereinladung',
    nil,
    nil,
  },
  [13808] = {
    'In geheimer Mission',
    {'Ich habe eine besondere Aufgabe. Für sie brauche ich einen gut ausgerüsteten, sachkundigen Helfer. Da ich niemanden sonst erübrigen kann, muss ich mich wohl mit Euch begnügen...|n|nDer Feind hat das Holzfällerlager des Kriegshymnenklans angegriffen und vom Rest unserer Streitkräfte abgeschnitten. Eine wichtige Diplomatin der Blutelfen, die auf dem Weg nach Orgrimmar war, wird dort gefangen gehalten.|n|nSie muss befreit werden.|n|nNehmt die Straße nach Nordosten und schüttet dieses Pulver in die schwelende Kohlenpfanne, um unseren Geheimagenten dorthin zu rufen. Tut, was immer er von Euch verlangt.|n|nWegtreten!', },
    nil,
  },
  [13809] = {
    'Bedrohung von oben',
    {'Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.|n|nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur\'thar.', },
    {'Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.', },
  },
  [13810] = {
    'Die Schlacht zum Gegner tragen',
    {'Das Kolosseum befindet sich im gefährlichsten Teil der Welt, $N. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.|n|nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.', },
    {'Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.', },
  },
  [13811] = {
    'Unter Champions',
    {'Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.|n|nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und von Euren Gegnern lernen. Champions aller Städte üben im Ring der Champions. Nehmt Eure Lanze, steigt auf irgendeins der angebundenen Reittiere, die Euch am Silberbundpavillon zur Verfügung stehen, und fordert sie heraus.', },
    {'Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.', },
  },
  [13812] = {
    'Bedrohung von oben',
    {'Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher halt machen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.|n|nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.|n|nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur\'thar herum.', },
    {'Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.', },
  },
  [13813] = {
    'Die Schlacht zum Gegner tragen',
    {'Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.|n|nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur\'thar und Todessprechers Wacht vertreten.', },
    {'Zor\'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.', },
  },
  [13814] = {
    'Unter Champions',
    {'Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.|n|nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt Euch irgendein zur Verfügung stehendes aus und fordert die Champions zu Übungskämpfen heraus.', },
    {'Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.|n|nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.', },
  },
  [13815] = {
    'Stümpfe machen',
    {'Wie Euch bereits mitgeteilt wurde, sollen wir eine Diplomatin aus dem belagerten Holzfällerlager in Sicherheit bringen.|n|nSo wie es aussieht, ist das einfach unmöglich. Die Elfen halten tausend Pfeile auf die Ausgänge des Holzfällerlagers gerichtet.|n|nZunächst müssen wir ein Ablenkungsmanöver inszenieren – etwas, durch das sie ihren Blick eine Zeitlang vom Holzfällerlager abwenden.|n|nMeine Idee ist einfach. Nehmt diese Axt und fällt die Bäume, die sie in dieser Region pflegen.|n|nWenn Ihr damit fertig seid, verwendet das Signalpulver hier, um wieder mit mir zu sprechen.', },
    {'Krokk will, dass Ihr mit der Splitterholzaxt die Eichen des Eschentals im Holzfällerlager des Kriegshymnenklans fällt.|n|nFalls Ihr das Geheimsignalpulver verliert, sprecht mit Kadrak im Splitterholzposten.', },
  },
  [13816] = {
    'Heroisch: Das Himmlische Planetarium',
    {'Hört mal, $GKumpel:Mädel;! Das Schicksal von Azeroth steht hier auf dem Spiel.|n|nUnsere einzige Chance ist es, rechtzeitig das Himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.|n|nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.', },
    {'Ausgrabungsleiterin Loren im Archivum möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.', },
  },
  [13817] = {
    'Heroisch: Datenscheibe des Archivums',
    {'Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort "ARCHIVUM".|n|nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.', },
    {'Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.', },
  },
  [13818] = {
    'Heroisch: Algalon',
    {'Ihr habt es wirklich geschafft, $N. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum Himmlischen Planetarium erhaltet.|n|nIhr beeilt Euch besser, $GKumpel:Mädchen;. Die Zeit drängt.', },
    {'Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.', },
  },
  [13819] = {
    'Heroisch: Ende gut, alles gut',
    {'Wir sollten uns jetzt besser beeilen, $N. Wir müssen den Antwortcode von Dalaran aus übermitteln.|n|nBringt ihn zu Rhonin. Ich treffe Euch dort.', },
    {'Überbringt Rhonin in Dalaran den Antwortcode Alpha.', },
  },
  [13820] = {
    'Die Gebrüder Sprengbolz',
    {'Der Hochlord hat mich damit beauftragt, das Kolosseum so schnell wie möglich fertig zu stellen. Wir haben unsere Bauarbeiter an das Projekt gesetzt, aber wir mussten sehr schnell feststellen, dass wir Hilfe bei der Beschaffung von Materialien brauchten. Ich habe ein paar Goblins angeheuert, Stumpi Sprengbolz und seinen Bruder Stümpi.|n|nSie beaufsichtigen die Arbeiten am südöstlichen Ende des Turniergeländes. Sprecht mit Stumpi und findet heraus, ob er und sein Bruder noch weitere Hilfe dabei brauchen, das benötigte Baumaterial zu beschaffen.', },
    {'Sprecht mit Stumpi Sprengbolz am Argentumturnierplatz.', },
  },
  [13821] = {
    'Heroisch: Freyas Siegel',
    {'Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.|n|nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.|n|nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.|n|nWas soll ich sagen, $N, das ist eine ganz schöne Zwickmühle, in der wir da stecken.', },
    {'Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13822] = {
    'Heroisch: Hodirs Siegel',
    {'Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!|n|nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!', },
    {'Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13823] = {
    'Heroisch: Thorims Siegel',
    {'Thorim ist nicht er selbst, $N. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.|n|nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.|n|nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!|n|nIhr müsst ihn zur Vernunft bringen und zwar schnell.|n|nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.', },
    {'Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13824] = {
    'Heroisch: Mimirons Siegel',
    {'Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.|n|nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, um sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.', },
    {'Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.|n|nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.', },
  },
  [13825] = {
    'Muschelette Surprise',
    nil,
    nil,
  },
  [13826] = {
    'Nat Pagle, Extremangler',
    nil,
    nil,
  },
  [13827] = {
    'Schatz!',
    nil,
    nil,
  },
  [13828] = {
    'Den Nahkampf beherrschen',
    {'Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf das Streitross der Quel\'dorei, das gleich außerhalb des Pavillons abgestellt ist.|n|nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.', },
    {'Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel\'dorei außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet fünfmal die Fähigkeit \'Zustoßen\' gegen ein Nahkampfziel an. Kehrt anschließend zu Arkanist Taelis beim Argentumturnierplatz zurück.', },
  },
  [13829] = {
    'Den Nahkampf beherrschen',
    {'Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf den Falkenschreiter der Sonnenhäscher, der gleich außerhalb des Pavillons abgestellt ist.|n|nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.', },
    {'Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet fünfmal die Fähigkeit \'Zustoßen\' auf ein Nahkampfziel an. Kehrt anschließend zu Magister Edien Sonnental beim Argentumturnierplatz zurück.', },
  },
  [13830] = {
    'Der Geisterfisch',
    {'Jeder Angler in Nordend, der sein Geld wert ist, weiß über den Pygmäenschiffshalter Bescheid. Er ist nicht essbar, manchmal jedoch für Alchemisten nützlich.|n|nEs gibt jedoch einen Fisch, einen etwas verstohleneren, der sich zwischen den Schiffshaltern im Flussnabel im Sholazarbecken versteckt: der Phantomgeisterfisch. Außerhalb des Wassers werden sie zunehmend lichtdurchlässig, bis sie schließlich ganz verschwinden. Einige nehmen an, dass sie nach Sholazar zurückkehren, andere wiederum sind etwas... abergläubischer.|n|nIch möchte, dass Ihr diesen Fisch fangt und um jeden Preis hinter sein Geheimnis kommt!', },
    {'Marcia Balzer in Dalaran möchte, dass Ihr hinter das Geheimnis des Phantomgeisterfischs kommt.', },
  },
  [13831] = {
    'Besorgniserregende Rezepte',
    {'Hier steht eine einfache, hastig zusammengezimmerte Werkbank eines Apothekers, die unter der Last gekritzelter Notizen und giftigem Gebräu fast zusammenbricht. Es sieht so aus, als hätten die Verlassenen auch Faulhufs Handwerk untersucht. Ihr schnappt Euch die Notiz, die am wichtigsten aussieht und bereitet Euch darauf vor, alles zu zerstören, bevor Ihr dem Baumwahrer von Eurer Entdeckung berichtet.', },
    {'Bringt die Notizen des Apothekers zu Tharnariun Baumwahrer in Lor\'danel.', },
  },
  [13832] = {
    'Perle der Kanalisation',
    {'Schwer zu glauben, dass die meisten Leute, wenn sie zum Angeln in die Kanalisation von Dalaran gehen, nach Riesenratten und mutierten Fischen suchen. Besonders dann, wenn im Wasser Unmengen unbezahlbarer Juwelen zu finden sind - von gebrochenen Herzen, Dieben und achtlosen Trunkenbolden weggeworfen.|n|nDer Trick bei der Sache ist, Euren Haken am Boden entlang zu ziehen, und wenn Ihr etwas gefunden habt, beim Hochziehen nicht zu viel Kraft zu verwenden. Versucht es einmal, $N. Ich wäre dazu bereit, was auch immer Ihr findet gegen ein paar meiner eigenen Schmuckstücke einzutauschen.', },
    {'Marcia Balzer in Dalaran möchte, dass Ihr ihr korrodierten Schmuck bringt.', },
  },
  [13833] = {
    'Blut ist dicker',
    {'Der Blutzahnfrenzy ist ein quirliger kleiner Fisch, der für ein Rezept zur Heilung von infizierten Wunden verwendet wird. Wir könnten ein paar von ihnen gebrauchen, wenn Ihr helfen wollt.|n|nWie der Name schon sagt, trinken sie gerne Blut. Die einzige mir bekannte Art und Weise, die kleinen Teufel zu fangen, ist, Blut ins Wasser zu schütten und dann darin zu angeln.|n|nBeschmiert Euch also mit Blut... Tötet dazu einfach eine der Bestien in der Boreanischen Tundra und springt anschließend ins Wasser. Ihr werdet im Nu den perfekten Köder haben.', },
    {'Marcia Balzer in Dalaran möchte, dass Ihr ihr 5 Blutzahnfrenzys bringt.', },
  },
  [13834] = {
    'Gefährlich köstlich',
    {'Die besten Angelplätze sind oft die gefährlichsten. Für diejenigen, die dreist genug sind, bietet sich Tausendwinter an - dort sind großzügige Fänge zu machen.|n|nGenau genommen ist es der einzige Ort, wo man den sagenhaften Schreckensfisch fangen kann - ein Fisch, tödlich und köstlich zugleich. Bringt mir ein paar und wir können weiterreden.', },
    {'Marcia Balzer in Dalaran möchte, dass Ihr ihr 10 Schreckensfische bringt.', },
  },
  [13835] = {
    'Den Schildbrecherangriff beherrschen',
    {'Ihr werdet lernen müssen, wie man die Verteidigung Eures Gegners durchbrechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf das angebundene Streitross der Quel\'dorei gleich außerhalb des Pavillons.|n|nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.', },
    {'Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel\'dorei außerhalb des Pavillons. Sprecht mit Valis Windhetzer und wendet die Fähigkeit "Schildbrecher" gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.', },
  },
  [13836] = {
    'Arm dran, Arm ab!',
    {'Ich habe von einem tragischen Zwischenfall im Gefängnis von Dalaran gehört; ein besonders brutaler Insasse hat einer Wache einen Arm abgerissen und ihn ins Wasser geworfen. Die Leute von der "Ersten Hilfe"-Station haben versprochen, dass sie den Arm wieder annähen können, falls wir ihn zurückbringen.|n|nIhr angelt einfach lange genug im Wasser vor der Violetten Festung, und ich verwette meine Lieblingsangelrute darauf, dass der Arm auftaucht. Findet ihn und bringt ihn zu Olisarra der Gütigen hier in Dalaran. Sie wird wissen, was zu tun ist.', },
    {'Olisarra die Gütige in Dalaran möchte, dass Ihr ihr den abgetrennten Arm bringt.', },
  },
  [13837] = {
    'Den Ansturmangriff beherrschen',
    {'Euer stärkster Angriff im berittenen Kampf ist zweifellos \'Sturmangriff\'. Nehmt diese Lanze und steigt auf das Streitross der Quel\'dorei, das gleich außerhalb des Pavillons abgestellt ist.|n|nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist und Euch ein paar grundlegende Strategien beibringen.', },
    {'Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel\'dorei außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit \'Sturmangriff\' gegen 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Avareth Flinkstoß beim Argentumturnierplatz zurück.', },
  },
  [13838] = {
    'Den Schildbrecherangriff beherrschen',
    {'Ihr werdet lernen müssen, wie man durch die Verteidigung Eures Gegners brechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher gleich außerhalb des Pavillons.|n|nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.', },
    {'Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher. Sprecht mit Valis Windhetzer und wendet die Fähigkeit \'Schildbrecher\' gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Galathia Morgenglanz beim Argentumturnierplatz zurück.', },
  },
  [13839] = {
    'Den Ansturmangriff beherrschen',
    {'Euer stärkster Angriff im berittenen Kampf ist zweifellos \'Sturmangriff\'. Nehmt diese Lanze und steigt auf das Streitross der Quel\'dorei, das gleich außerhalb des Pavillons abgestellt ist.|n|nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist, und Euch ein paar grundlegende Strategien beibringen.', },
    {'Nehmt Eure Lanze und steigt auf den angebundenen Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit \'Sturmangriff\' gegen 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Amariel Sonnenschwur beim Argentumturnierplatz zurück.', },
  },
  [13840] = {
    nil,
    {'Gack... gack... gack... GAGGACK!|n|nGack... gack... gack.|n|nDas Huhn sieht zu Euch hinauf und beginnt dann, mit seinen Krallen am Boden zu scharren. Ihr glaubt, dass es ein Wort schreibt, aber Ihr seid Euch nicht sicher, was es ist. Könnte es das sein... S-A-L-D-E-A-N? Bevor Ihr fragen könnt, dreht sich das Huhn weg und kümmert sich um seine Angelegenheiten.', },
    {'Beschafft Euch etwas Spezialhühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezialhühnerfutter gebt.', },
  },
  [13841] = {
    'Mit der Bitte um Entschuldigung',
    nil,
    nil,
  },
  [13842] = {
    'Der Tod steht ihm gut',
    nil,
    {'Sprecht mit Durak in den Splitterholzminen.', },
  },
  [13843] = {
    'Das Konstruktionsset: Schrottbot',
    {'Ihr durchsucht die Datenbanken der Prototypenkonsole und findet dabei ein Schema für ein Schrottbotkonstruktionsset. Mit Eurer Ingenieursfertigkeit könntet Ihr lernen, Konstruktionssets wie dieses selbst herzustellen.', },
    {'Benutzt die Prototypenkonsole in der Bibliothek des Erfinders.', },
  },
  [13844] = {
    'Althalaxx plündern',
    {'Bevor Ihr Euch gleich wieder in die Schlacht stürzt, möchte ich Euch über ein paar neue Entwicklungen in Kenntnis setzen, $C. Meine Späher berichten mir, dass der Turm von Althalaxx im Süden von den Verlassenen überrannt wird.|n|nVor dem Angriff war dieser trostlose Turm die Heimat eines fanatischen Zweigs des Schattenrats, der von dem gefallenen Hochgeborenen Athrikus Narassin angeführt wurde. Narassin ist längst tot, aber wir dürfen es nicht ignorieren, falls etwas von seinem Werk weiterbesteht. Beschafft Euch seine Forschung und tötet den Kommandanten der Verlassenen, der die Ruinen plündert.', },
    {'Findet Narassins Foliant in den Ruinen von Althalaxx und tötet Teegan Holloway, den Kommandanten der Verlassenen.', },
  },
  [13845] = {
    'Versiegelte Giftphiole',
    {'Diese Giftphiole sieht besonders gefährlich aus. Womöglich könnte jemand in Dalaran daran interessiert sein.', },
    {'Bringt die versiegelte Giftphiole zu Alchemist Cinesra in die Kanalisation von Dalaran.', },
  },
  [13846] = {
    'Einen Beitrag leisten',
    {'Die besten der Champions kommen jeden Tag zur Kapelle, um der Argentumbeichtpatin zuzuhören.|n|nIhr solltet sehen, wie sehr sie von ihr inspiriert werden, $N. Sie ziehen nicht nur für den Argentumkreuzzug in den Kampf, sondern geben auch noch sehr viel Geld in den Klingenbeutel, wenn ich ihn herumtrage.|n|nWollt Ihr womöglich auch einen Beitrag leisten?', },
    {'Sprecht mit Knappe Artie, um einen Beitrag von 10 Gold an den Argentumkreuzzug zu leisten.', },
  },
  [13847] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Hauptmann Joseph Holley beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13848] = {
    'Überbringer schlechter Nachrichten',
    {'Seit Beginn der Belagerung des Splitterholzpostens hat es keine Nachricht nach dort draußen geschafft. Inzwischen muss Kommandant Grimmfang sich Sorgen machen.|n|nIch entsende Euch zum Zoramstrand, um unseren Bericht abzuliefern. Er enthält keine guten Nachrichten, aber zumindest erfährt er dann die Fakten.|n|nSprecht mit Vhulgra, wenn Ihr bereit zum Aufbruch seid.', },
    nil,
  },
  [13849] = {
    'Astranaar brennt!',
    {'$C, Astranaar steht in Flammen!|n|nSchnell, nehmt diesen Wassereimer und löscht das Feuer, bevor nichts mehr übrig ist!', },
    {'Löscht 15 Feuer.', },
  },
  [13850] = {
    'Gifttoleranz',
    {'Ihr wollt eine Gifthaut reiten? Dann hab\' ich schlechte Neuigkeiten für Euch.|n|nDie Gifthautravasaurier, die bestehen aus nichts als Gift: giftiges Blut, giftiger Speichel, giftige Haut. Ihr steigt auf einen drauf und fallt nach ein paar Stunden tot runter.|n|nIhr müsstet zuerst gegen ihre Gifte resistent werden, bevor ich Euch einen verkaufe, und das dauert ganz schön lange... Ihr müsstet mit ihrem giftigem Blut bespritzt werden, wenn Ihr sie bekämpft. Und zwar sehr oft. Wenn Ihr wirklich daran interessiert seid: Die Gifthäute bevorzugen die nördliche Gegend der Marschen nordwestlich von hier.', },
    {'Mor\'vek im Krater von Un\'Goro behauptet, dass wenn man 20-mal von dem Blut eines Gifthautravasauriers vergiftet wurde, auf einem reiten könnte, ohne zu sterben. Greift die Saurier an, um vielleicht vergiftet zu werden.', },
  },
  [13851] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Clara Torkelbräu beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13852] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Klick Radspanner beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13853] = {
    'Das Feuer erwidern',
    {'Die meisten Feuer sind unter Kontrolle, aber wir müssen etwas gegen diese Windreiter unternehmen!|n|nSchnell, $N, Ihr müsst in eine unserer Glevenschleudern klettern und das Feuer erwidern!', },
    {'Verwendet eine Schleuder von Astranaar, um 15 von Höllschreis Vandalen und ihre Wachwindreiter abzuschießen.', },
  },
  [13854] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Ranii beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13855] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Airae Sternensucher beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13856] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Morah Worgschwester beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13857] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Gahju beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13858] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Anka Klauenhuf beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache un 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13859] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Aneera Thuron beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13860] = {
    'Vor den Toren des Feindes',
    {'Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Tierführer Dretch beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.', },
  },
  [13861] = {
    'Schlacht vor der Zitadelle',
    {'Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.', },
  },
  [13862] = {
    'Schlacht vor der Zitadelle',
    {'Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.', },
  },
  [13863] = {
    'Schlacht vor der Zitadelle',
    {'Während sich einige der Kreuzfahrer auf das Turnier vorbereiten, wurden andere ausgesandt, um die Hochburg des Feindes, die Eiskronenzitadelle, anzugreifen.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.', },
  },
  [13864] = {
    'Schlacht vor der Zitadelle',
    {'Während sich einige der Kreuzfahrer auf das Turnier vorbereiten, wurden andere ausgesandt, um die Hochburg des Feindes, die Eiskronenzitadelle, anzugreifen.|n|nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp\'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.|n|nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, $N, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.', },
    {'Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.', },
  },
  [13865] = {
    'Drei Anführer sind drei zu viel',
    {'Hört gut zu, $C.|n|nIn dieser Region gibt es drei Kommandanten der Elfen, die ihre Bemühungen gezielt auf das Holzfällerlager richten. Sie zu töten, würde sicherlich Panik und ein Durcheinander anrichten. Hoffentlich ausreichend, sodass wir unsere Mission erfolgreich durchführen können.|n|nWo Ihr schon dabei seid: Die Vernichtung ihrer Späher kann unserer Sache nur dienlich sein.', },
    {'Krokk will, dass Ihr Dorinar, Arminon, Endolar und 12 Eschentalspäher tötet.|n|nSprecht mit Kadrak im Splitterholzposten, falls Ihr das Geheimsignalpulver verliert.', },
  },
  [13866] = {
    'Zum Schutzwall!',
    {'Diese Wälder mögen ruhig sein, aber unsere Feinde lauern hinter jedem Baum. Ich habe schon so manchen Orc mit Pfeilen in seinem Rücken entdeckt und die Waffe noch nicht gezückt.|n|nHier ist es tückisch hinter den feindlichen Linien, aber wir könnten starke Arme und kluge Köpfe dort unten im Schutzwall von Mor\'shan gebrauchen. Kadrak bereitet eine Offensive von dort aus vor – er zieht Taten den Worten vor. Ihr werdet Euch gut mit ihm verstehen.|n|nSprecht mich wieder an, wenn Ihr bereit seid, und ich fliege Euch dorthin.', },
    {'Sprecht mit Kulg Blutspritzer an der Grenze zwischen Eschental und Azshara, um zum Schutzwall von Mor\'shan gebracht zu werden. Meldet Euch bei Kadrak, wenn Ihr dort eintrefft.', },
  },
  [13867] = {
    'Die Eindämmung der Furbolgbedrohung',
    {'Direkt im Norden von Astranaar sind die Distelfellfurbolgs. Meine Späher berichten, dass ihre Anzahl in den letzten Monaten stark zugenommen hat. Wenn sie zu schnell anwächst, fassen sie vielleicht den Mut, Astranaar direkt anzugreifen!|n|nBegebt Euch ins Lager der Distelfelle und tötet so viele von ihnen, wie Ihr könnt.|n|nIch werde hier in Astranaar bleiben und Euren Bericht erwarten. Elune sei mit Euch, $C.', },
    {'Tötet 15 Furbolgs im Lager der Distelfelle in Eschental.', },
  },
  [13868] = {
    'Schlechter Einfluss?',
    {'Als Ihr die Habseligkeiten der toten Furbolgs durchsucht, die vor Euch liegen, fällt ein kleiner, offensichtlich von Trollen erschaffener Glücksbringer auf den Boden.|n|nAls Ihr den Glücksbringer berührt, bekommt Ihr umgehend das Gefühl, dass es im Wald nicht mit rechten Dingen zugeht. Ein Gefühl der Unruhe und Verderbtheit durchdringt das Objekt.|n|nIhr hüllt es in ein Tuch, verstaut es in Eurem Gepäck und beschließt, es Raene Wolfsläufer zu zeigen, wenn Ihr das nächste Mal in Astranaar seid.', },
    {'Überbringt den Trollglücksbringer Raene Wolfsläufer in Astranaar im Eschental.', },
  },
  [13869] = {
    'Bergt die Überreste',
    nil,
    {'Sammelt 10 Stück Holz des Kriegshymnenklans.', },
  },
  [13870] = {
    'Besser geht\'s nicht',
    {'Nun gut, $C, besser geht es nicht.|n|nDie Elfen sind dabei, sich von Euren letzten Taten zu erholen. Das ist der günstigste Augenblick, um in das Holzfällerlager vorzustoßen!|n|nBegebt Euch dorthin und sprecht mit Vorarbeiter Gorthak. Er wird Euch erklären, wie Ihr die Diplomatin am sichersten begleitet.|n|nViel Glück!', },
    {'Krokk will, dass Ihr das Holzfällerlager des Kriegshymnenklans betretet und mit Vorarbeiter Gorthak sprecht.', },
  },
  [13871] = {
    nil,
    {'Es ist nicht so, als ob ich nicht schon genug um die Ohren hätte!|n|nDiesen Ort am Laufen zu halten ist schon schwer genug, ohne dass die Elfen und Draenei uns ständig belästigen.|n|nJetzt schleicht obendrein noch ein Auftragsmörder im Lager umher, der eine wichtige Diplomatin getötet hat... Während meiner Wache!|n|nWer auch immer es war, er kann noch nicht weit sein, $C. Durchsucht das Lager, bis Ihr ihn findet und dann rächt die Diplomatin!|n|nZumindest kann ich dann den Kopf des Mörders in Händen halten, wenn ich mich vor Höllschrei rechtfertigen muss.', },
    {'Vorarbeiter Gorthak will, dass Ihr ihm den Kopf eines Assassinen der Kaldorei bringt.', },
  },
  [13872] = {
    'Die Weisheit der Worgen',
    {'Der Mann, der mir direkt gegenübersteht, ist als Hephaestus Pilger bekannt. Er ist einer der Worgen.|n|nEr und seine Schwester kamen vor nicht allzu langer Zeit nach Astranaar, als sie einen neuen Ort zum Leben suchten. Soweit ich das sagen kann, ist er daran interessiert, dem Irdenen Ring bei der Katastrophe zu helfen. Seine Schwester ist sogar noch mächtiger. Sie ist nach Osten gereist, um dem Schamanen zu helfen, sich um den Vulkan zu kümmern.|n|nVielleicht kann er helfen. Bringt den Glücksbringer zu ihm und hört, was er darüber denkt.', },
    {'Bringt den Trollglücksbringer zu Hephaestus Pilger in Astranaar im Eschental.', },
  },
  [13873] = {
    'Sheelahs Vermächtnis',
    {'Ich... Ich kann nicht glauben, dass sie von uns gegangen ist. Es ist alles so schnell gegangen...|n|nIch muss Euch wohl danken, dass Ihr meine Herrin gerächt habt. Dafür habt meinen Dank und den von Silbermond.|n|nIn Ihrer Weisheit hat meine Lady Ihr Ende vorausgesehen. Sie hat ein Sendschreiben vorbereitet für den Fall, dass ihr irgendetwas zustoßen würde.|n|nWir sollten uns einem Gefolge aus Orgrimmar anschließen, am Wegekreuz nördlich von hier. Bitte, <Volk>, trefft sie an unserer statt und sorgt dafür, dass die Nachricht übergeben wird.', },
    nil,
  },
  [13874] = {
    'Im Bann der Glücksbringer',
    {'Die Furbolgs begehren etwas, das ihnen nicht gehört.|n|n<Hephaestus dreht den Glücksbringer in seiner Hand und lässt ihn dann fallen.>|n|nDiese Schnitzerei besitzt die Eigenschaft, langsam jene zu verderben, die keine Trolle sind. Soweit ich sehen kann, haben die Furbolgs das schon einmal gemacht. Manche lernen\'s nie.|n|nZweifellos horten sie die meisten Glücksbringer in der Höhle der Distelfelle nördlich ihres Dorfes.', },
    {'Sammelt 8 Trollglücksbringer.', },
  },
  [13875] = {
    'Gurtars Bitte',
    {'Ich hätte noch eine persönliche Bitte an Euch, $C.|n|nEs ist viele Monde her, seitdem ich meine Liebste gesehen habe, Draaka. Es werden noch viele weitere verstreichen, bis wir uns wiedersehen können. Ich fürchte, dass nach so langer Zeit ihre Liebe für mich schwinden wird.|n|nDieser Zopf hat für uns beide eine besondere Bedeutung, und auch der dornige Blutkelch, die Blume, die in dieser Region wächst.|n|nIch bitte Euch, diese Blumen zu pflücken und sie mit dieser Schnur zu binden. Dann übergebt Draaka das Geschenk in meinem Namen.', },
    {'Wächter Gurtar will, dass Ihr den Blutkelchzopf an Draaka im Splitterholzposten übergebt.', },
  },
  [13876] = {
    'Zu weit entfernt',
    {'Ja, ich spreche Eure Sprache, <Volk>.|n|nWir Furbolgs waren schon einmal Opfer dieser Form von Verderbnis. Vor nicht allzu langer Zeit stahl unser Anführer den Götzen von Remulos. Das von Dämonen verderbte Ding verhexte den gesamten Stamm und unsere Erlösung wurde nur notdürftig durch einen Druiden herbeigeführt, der Broll Bärenfell heißt.|n|nAber dieses Mal haben wir nicht gestohlen. Die Trolle von Zoram\'gar gaben uns die Glücksbringer als ein Zeichen der Freundschaft. Eine tödliche Freundschaft, wie es scheint.|n|nUnser Häuptling Dal Blutklaue ist nicht mehr zurechnungsfähig. Betretet die Höhle und kehrt mit seinen Glücksbringern zurück.', },
    {'Gelangt in den Besitz von Blutklaues Sammlung.', },
  },
  [13877] = {
    'Der Tanz auf dem Vulkan',
    {'<Der Worgen starrt Euch durchdringend an, bevor er seine Bitte vorträgt.>|n|nDer Vulkan droht, ganz Eschental zu verschlingen, wenn wir nicht rasch handeln. Lasst Euch gesagt sein, dass dies kein natürlicher Ausbruch war.|n|nMeine Schwester Sabina ist mächtig. Sie ist nach Osten zur Grenze des Lavastroms am Donnergipfel direkt nördlich der Straße gegangen. Dort erbittet sie die Hilfe anderer Elemente gegen den Feuerlord, der diese Zerstörung verursacht hat.|n|n$N, begebt Euch zu ihr und helft ihr, so gut Ihr könnt.', },
    {'Sprecht mit Sabina Pilger am südlichen Rand des Lavastroms am Donnergipfel in Eschental.', },
  },
  [13878] = {
    'Durch Feuer und Flamme',
    {'Helft mir, $C! Schweinemenschen kommen und zünden Ställe an – Feuer! Feuer!|n|n<Dorak jammert etwas Unverständliches, bevor es Euch gelingt, ihn zu beruhigen.>|n|nWölfe drinnen noch angekettet. Jemand muss die kleinen Wölfe retten!', },
    {'Brecht die Ketten auf und befreit die Wölfe aus den brennenden Ställen.', },
  },
  [13879] = {
    'Der Donnergipfel',
    {'Seid gegrüßt, $C!|n|nIch gratuliere zu Eurem siegreichen Angriff auf Astranaar. Die Elfen werden diese Schmach nicht so schnell vergessen, die sie durch Eure Hand erlitten haben.|n|nAber Ihr müsst wissen, dass die Elfen nicht das einzige Hindernis sind, dass der Eroberung des Eschentals durch die Horde im Wege steht...|n|nIm Osten benötigt ein Schamane des Irdenen Rings Hilfe bei einer anderen Krise. Ihr findet ihn in der Nähe des Fußes des Vulkans Donnergipfel.', },
    {'Broyk will, dass Ihr Stikwad am Donnergipfel findet.', },
  },
  [13880] = {
    'Heiße Lava',
    {'<Der riesenhafte Erdelementar starrt auf Euch herab.>|n|nDer Lavastrom muss aufgehalten werden, wenn wir überleben wollen. Ich werde Euch einen Teil meiner Kraft übertragen. Verwendet sie, um die Lavafelsspalten zu füllen!', },
    {'Verwendet das Geschenk der Erde, um 8 Lavafelsspalten zu füllen.', },
  },
  [13881] = {
    nil,
    {'Meine größte Sorge gilt den Distelbärfamilien, die diese Wälder behausen. Südlich von hier, hinter dem Bärenschrein, ist eine gesamte Generation der Bären erkrankt. Schrecklich erkrankt.|n|n$N, ich weiß nicht, woran sie leiden, aber es scheint sie von innen aufzuzehren. Der Gedanke, dass eine gesamte Generation nicht mehr zu retten ist, ist entsetzlich, aber wir müssen sie töten, damit ihre Körper der Erde zurückgegeben werden.|n|nUnd was noch wichtiger ist, wir müssen den Ursprung der Krankheit finden. Untersucht den See, aus dem die Bären trinken.', },
    {'Tötet 6 aufgezehrte Distelbären und untersucht den See, von dem die Distelbären trinken.', },
  },
  [13882] = {
    'Die Samenkörner des Lebens',
    {'Etwas versucht, das Leben aus Dunkelküste aufzuzehren! Ich werde mich umhören, ob jemand etwas über - das Ding - weiß, das Ihr gefunden habt. In der Zwischenzeit müssen wir uns aber auch um die Wildtiere kümmern, damit ihnen nicht noch weiteres Leid geschieht.|n|nKönnt Ihr ein paar Materialien für mich besorgen? Ich brauche Leben in allen möglichen Formen. Sprecht mit Onu hier am Hain, um die Saat der Erde zu erhalten. Fangt einen Dunkelküstenirrwisch, um die Saat des Himmels zu erhalten, und besorgt die Saat des Meeres von den Seemuschelschalen an der Küste westlich von hier.', },
    {'Sammelt die Saat der Erde, die Saat des Meeres und die Saat des Himmels.', },
  },
  [13883] = {
    'Ein Wrack neben dem anderen',
    {'Stümperhaftes Handwerk! Es gibt keine andere Erklärung...|n|nDiese Schiffe müssen in großer Eile zusammengeflickt worden sein. Ganze Panzerungsplatten fallen ab, ohne jemals einen Treffer abgefangen zu haben!|n|nIch zeige ihnen, wie man es richtig macht. Aber zuerst müsst Ihr für mich die Teile vom Meeresboden bergen.|n|nKehrt mit den Teilen zu mir zurück und ich erledige den Rest.', },
    {'Bergt 10 Teile versunkenes Altmetall.', },
  },
  [13884] = {
    'Feuerlöscher',
    {'Wir müssen uns zunächst um Lord Magmathars Lakaien kümmern, wenn wir dieses Gebiet zurückerobern wollen und der hitzigen Zerstörung des Waldes Einhalt gebieten wollen.|n|nDie Lavawüter auf dem Strom im Norden werden durch ihr Element gestärkt. Ich fürchte, wenn Ihr auf Euch gestellt seid, habt Ihr keine Chance gegen sie.|n|nWenn Ihr bereit seid, sprecht mich wieder an und ich werde einen meiner Helfer für Euch beschwören.', },
    {'Tötet 10 Lavawüter. Falls Ihr einen weiteren gefrierenden Woger benötigt, sprecht mit Arctanus.', },
  },
  [13885] = {
    'Verteidigung Dunkelküstes',
    {'Nun da wir wissen, dass unsere Vorsorgemaßnahmen funktionieren, sollten wir so viel Land abdecken wie möglich.|n|nWir können einen der Hippogryphen benutzen, aber alleine kann ich nichts ausrichten. Sprecht mit meinem Freund Orseus beim Flugmeister vor dem Hain. Sagt ihm Bescheid, wenn Ihr soweit seid. Ich werde Euch dort treffen. Wir werden Dunkelküste von der Luft aus abdecken und so viele Tiere wie möglich schützen!', },
    {'Sprecht mit Orseus vor dem Hain der Uralten und besteigt einen Hippogryphen. Beschützt aus der Luft 8 Weißschwanzhirsche und -rehe, 8 ergraute Distelbären und 8 Mondpirschermatriarchinnen oder Mondpirscherpatriarchen vor der Verzehrung.', },
  },
  [13886] = {
    nil,
    {'Es ist an der Zeit, $N. Wenn Ihr Euch gewappnet habt, sprechen wir wieder miteinander und ich werde einen Wirbelnden Vortex beschwören, der Eure Schritte zu den Himmeln über dem Donnergipfel beschleunigt.|n|nLeitet die Kraft des Irdenen Rings durch den Elementar, um Lord Magmathar zu vernichten, sodass wir ihn wieder ins Gleichgewicht bringen.', },
    {'Verwendet die Kräfte des Wirbelnden Vortexes, um Lord Magmathar zu vernichten.', },
  },
  [13887] = {
    'Gifthauteier',
    {'Jetzt, da Ihr gegen das Sauriergift immun geworden seid, könnt Ihr mit den Tieren und ihren Eiern sicher umgehen. Gifthäute sind ziemlich bösartig und müssen vom Moment des Schlüpfens an trainiert werden.|n|nWenn Ihr einen reiten wollt, dann werdet Ihr ein ungeschlüpftes Ei benötigen. In den gesamten Marschen verteilt gibt es einige Ravasauriernester. Sucht nach Eiern mit helleren Schalen - das sind diejenigen, aus denen später Gifthäute schlüpfen werden.|n|nWenn Ihr mir einige Eier bringt, werde ich Euch gestatten, eins zu behalten und unter meiner Aufsicht aufzuziehen.', },
    {'Bringt Mor\'vek im südöstlichen Teil der Marschen 4 Eier von Gifthautravasauriern.', },
  },
  [13888] = {
    nil,
    {'Es ist an der Zeit, $N. Wenn Ihr Euch gewappnet habt, sprechen wir wieder miteinander und ich werde einen Wirbelnden Vortex beschwören, der Eure Schritte zu den Himmeln über dem Donnergipfel beschleunigt.|n|nLeitet die Kraft des Irdenen Rings durch den Elementar, um Lord Magmathar zu vernichten, sodass wir ihn wieder ins Gleichgewicht bringen.', },
    {'Verwendet die Kräfte des Wirbelnden Vortexes, um Lord Magmathar zu vernichten.', },
  },
  [13889] = {
    'Sooooo hungrig',
    {'Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.|n|nDie Zeichnungen sind grob, aber Ihr könnt die Umrisse von Dimetrodonten, Stegodonten und Pterrordaktylen ausmachen. Als der Raptor die Zeichnung vervollständigt hat, sieht er wieder zu Euch auf, fletscht seine Zähne und schnappt ein paar Mal mit dem Maul.|n|nAnscheinend hat Euer Gifthautjunges Hunger auf frisches Fleisch von diesen Tieren. Findet und tötet Dimetrodonten, Stegodonten oder Pterrordaktylen im Krater von Un\'Goro und füttert Euer hungriges Junges mit ihrem Fleisch.', },
    {'Euer Gifthautjunges möchte, das Ihr 15 frische Dinosaurierfleischstücke an ihn verfüttert.', },
  },
  [13890] = {
    'Schürt das Feuer',
    {'Dies ist keine leichte Aufgabe, <Volk>!|n|nEs treffen weitere Schiffe ein und ohne den Leuchtturm werden sie sich verirren – oder noch Schlimmeres! Hiermit wird Euch die Aufgabe übertragen, sein Feuer am Brennen zu erhalten.|n|nSammelt den Tran der Hydras in diesen Gewässern und bringt ihn dann zu dieser Schmiede hier, damit daraus Öl hergestellt wird.|n|nWerft Ihr dieses Öl in das Feuer des Leuchtturms, wird uns das die Zeit verschaffen, die wir benötigen.', },
    {'Kommandant Grimmfang in Zoram\'gar will, dass Ihr das Öl einer Nebelpeitscherhydra ins Feuer des Leuchtturms gießt.', },
  },
  [13891] = {
    'Der Verschlinger Dunkelküstes',
    {'Jetzt, da die Kreaturen Dunkelküstes in Sicherheit sind, sollten wir unsere Aufmerksamkeit dem Artefakt widmen, das Ihr im See gefunden habt. Ich glaube, es handelt sich dabei um die Arbeit der Diener der Alten Götter. Wir werden diese Feinde mit den lebensspendenden Energien zerstören, die Dunkelküste besitzt! Bringt den Lebensbringerschössling zum Ufer des Sees südlich von hier. Bewegt ihn über die Wasser des Sees; das sollte das alte Artefakt ausschalten.|n|nSeid vorsichtig, $N. Das Artefakt wird sicherlich von irgendetwas bewacht.', },
    {'Verwendet den Lebensbringerschössling am Ufer des flachen Sees südlich des Hain der Uralten und zerstört das verschlingende Artefakt und seinen Bewacher.', },
  },
  [13892] = {
    'Keine Spuren hinterlassen',
    {'Südwestlich von hier liegt der Leichnam eines Wesens, das in irgendeiner Verbindung zu den Alten Göttern steht, die die Schattenhammerkultisten verehren.|n|nEs wurde vor unserer Zeit besiegt - wenn nicht von den Titanen selbst, so sicherlich von einer ihrer Schöpfungen.|n|nIn der letzten Zeit haben wir zunehmend Aktivitäten der Kultisten beobachtet und das kann nur bedeuten, dass uns etwas Schreckliches bevorsteht.|n|nWir müssen herausfinden, was sie dort vorhaben, und warum. Nehmt diese Figur. Sie wird Euch dabei helfen, bei Euren Untersuchungen unbemerkt zu bleiben.', },
    {'Schleicht in die Meistergleve und beobachtet mit Hilfe der Pantherfigur die Schattenhammerkultisten.', },
  },
  [13893] = {
    'Soggoth und Kronn',
    {'Die Meistergleve ist der Ort einer uralten Schlacht, $N. Die Titanen haben zwanzig ihrer Steinriesen gegen Soggoth ausgesandt.|n|nVon diesen zwanzig Riesen hat nur einer überlebt.|n|nAuf den Tafeln steht geschrieben, dass Kronn, der größte aller Steinriesen, sich von Soggoths Ranken hat einfangen lassen - nur lange genug, um dem Schädel der Kreatur näher zu kommen - nahe genug für sein mächtiges Schwert.|n|nEs ist gut, dass er tot ist... wir haben nicht wirklich zwanzig weitere Steinriesen zur Verfügung, um ihn erneut aufzuhalten.', },
    {'Kehrt mit den neuen Informationen zu Larien beim Hain der Uralten zurück.', },
  },
  [13895] = {
    'Die schlummernden Uralten',
    {'Wir haben keine zwanzig Steinriesen, um uns des Feindes anzunehmen, aber wir Riesen aus uraltem Holz sind so stark wie jeder Fels.|n|nSeht Euch um, <Volk>. Mein Volk schläft... und doch werden sie in Zeiten der Not dem Horn des Hüters folgen.|n|nIhr könnt Aros, den Hüter des Hains, jenseits der Brücke nordöstlich von hier finden.|n|nBerichtet ihm vom Ernst der Lage.', },
    {'Findet Aros nordöstlich vom Hain der Uralten in Dunkelküste.', },
  },
  [13896] = {
    'Ausgegrabenes Wissen',
    {'Hört gut zu, $N. Wir müssen mehr über unseren Feind in Erfahrung bringen.|n|nSüdwestlich von hier, hinter der Meistergleve, sind ein paar Ausgrabungsleiter der Zwerge, die die Ruinen in der Nähe untersuchen.|n|nVielleicht haben sie Wissen zu Tage gebracht, das uns nützlich sein könnte.', },
    {'Sprecht mit Archäologe Groff bei Wirrbarts Ausgrabung.', },
  },
  [13897] = {
    'Die Schlacht um Dunkelküste',
    {'Die Urtume des Hains sind uns zu Hilfe gekommen, $N. Ich sehe selbst in diesem Augenblick durch ihre Augen.|n|nDer Schattenhammer muss sein Ritual schneller durchführen als ursprünglich geplant und bisher haben sie nur einen Teil des gefürchteten Soggoth wieder zum Leben erwecken können.|n|nZerstört diesen Teil, bevor es zu spät ist, $N. Ich werde andernorts gebraucht.|n|nKehrt zu den Druiden am Hain der Uralten zurück, wenn Ihr fertig seid. Sie werden Euch weitere Anweisungen erteilen.', },
    {'Tötet den Avatar von Soggoth in der Meistergleve.', },
  },
  [13898] = {
    'Das Blatt wendet sich gegen uns',
    {'Wir können die Naga nicht ungestraft davonkommen lassen, $N. Der Mord an dem Hüter des Hains ist eine Kriegserklärung.|n|nIhr könnt ihre Höhle auf der Insel Nazj\'vel weit im Südwesten finden.|n|nÜberbringt ihnen eine deutliche Nachricht.', },
    {'Tötet 8 Myrmidonen der Dunkelschuppen.', },
  },
  [13899] = {
    'Der Kriegsfürst der Dunkelschuppen',
    {'Wenn die Naga sich mit dem Schattenhammer verbünden wollen, so gnade ihnen Elune.|n|nBegebt Euch zu ihrer Höhle auf der Insel Nazj\'vel und findet den Anführer der Naga, den Kriegsfürst Zornrücken.|n|nVielleicht kann das Horn der Urtume noch gerettet werden.', },
    {'Tötet Kriegsfürst Zornrücken in Nazj\'vel.', },
  },
  [13900] = {
    'Das Opfer für Azshara',
    {'Der Kriegsfürst sagte, dass das Horn der Urtume als Opfergabe an Azshara oben in Nazj\'vel gegeben wurde.|n|nVielleicht ist es noch nicht zu spät, das alte Relikt vor der Zerstörung zu retten.', },
    {'Haltet die Priesterinnen der Dunkelschuppen davon ab, das Horn der Urtume oben in Nazj\'vel Azshara zu opfern.', },
  },
  [13901] = {
    'Tiefe Verzweiflung',
    nil,
    {'Tötet 6 Gezeitenpriesterinnen der Tiefschwarzen Grotte.', },
  },
  [13902] = {
    'Die Offensive festigen',
    {'Unsere Arbeit in Dunkelküste ist längst nicht vorbei. Wir haben die Landmassen vor dem Zerbersten bewahrt, aber unsere Feinde sind noch immer stark hier vertreten.|n|nIch möchte, dass Ihr südlich von hier ein paar Druiden am Hain der Uralten aufsucht. Sie werden von einem alten Freund von mir angeführt, von Balren von der Klaue.|n|nSagt ihnen, die Zeit ist reif, um die Schlacht zu unseren Feinden zu bringen. Ich werde nachkommen und sie unterstützen, sobald wir diese Gegend stabilisiert haben.', },
    {'Sprecht mit Balren von der Klaue am Hain der Uralten in Dunkelküste.', },
  },
  [13903] = {
    'Larve der Gorishi',
    {'Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.|n|nDie Zeichnungen des Jungen scheinen verschiedene Arten großer Insekten darzustellen, vielleicht die Gorishisilithiden. Das Junge beendet seine Zeichnung, zeigt mit einem kurzen Arm darauf, schnappt mit dem Kiefer und leckt sich das Mäulchen.|n|nEs möchte wohl, dass Ihr zur Wuchernden Narbe, im Zentrum des südlichen Kraters von Un\'Goro geht und Silithidenfleisch sammelt. Wenn Ihr das Fleisch habt, gebt es Eurem hungrigen Jungen zu fressen.', },
    {'Euer Gifthautjunges möchte, das Ihr 10 Stück Silithidenfleisch an ihn verfüttert.', },
  },
  [13904] = {
    'Pochiert, gerührt oder roh?',
    {'Der Magen des Gifthautjungen knurrt, als es mit seinen Ärmchen wedelt, um Eure Aufmerksamkeit zu bekommen. Es beginnt, die Umrisse von Silithiden in die Erde zu kratzen, darunter einige Ovale. Es sieht Euch hoffnugsvoll an und deutet auf die Kreise.|n|nSie können nur Silithideneier darstellen. Der Giftige Unterschlupf im westlichen Tanaris, nahe der Grenze zum Krater von Un\'Goro, wäre sicherlich ein guter Ort, um die Eier zu finden, die Euer kleines Junges haben möchte.', },
    {'Euer Gifthautjunges möchte, das Ihr 12 Silithideneier an ihn verfüttert.', },
  },
  [13905] = {
    'Sengende Rocfedern',
    {'Das Junge sieht Euch für einen Moment an, ein wenig, als ob es sich fragt, ob Ihr verstehen werdet. Es kratzt ein Bild von einem Paar Federn in die Erde, bevor es mit einer Klaue auf die Lederbänder um seine Ellbogen und Knie zeigt.|n|nEs sieht nicht hungrig aus, aber wofür könnten die Federn gut sein?|n|nEs will sie wohl als Schmuck haben, wie Ihr ihn an den anderen Raptoren gesehen habt. Die größten Federn findet man bei den sengenden Rocs, welche die großen Tierknochen in der westlichen Tanariswüste umschwärmen, nordöstlich des Disteltals.', },
    {'Euer Gifthautjunges möchte, das Ihr ihm 5 Federn von sengenden Rocs bringt.', },
  },
  [13906] = {
    'Sie werden so schnell erwachsen',
    {'Durch Eure fachmännische Fütterung und Pflege wird Euer Gifthautjunges schnell heranwachsen. Im Laufe seines Wachstums werden seine ersten Zähne durch bleibende ersetzt. Solltet Ihr die Milchzähne aufbewahren, werdet Ihr mit Leichtigkeit sagen können, wann es ausgewachsen genug sein wird, um zugeritten zu werden.|n|nEuer Junges wird Euch wissen lassen, was es braucht - gebt also genau Acht. Bringt mir Euren kleinen Ravasaurus und die Materialien für Euren Sattel, wenn er all seine Zähnchen verloren hat, und ich werde mich um den Rest kümmern.', },
    {'Bringt 20 Gifthautzähnchen, das Gifthautjunge, 20 Stück Runenstoff, 20 unverwüstliches Leder und 80 Gold zu Mor\'vek im südöstlichen Teil des Marschlands im Krater von Un\'Goro.', },
  },
  [13907] = {
    'Die Ruinen säubern',
    {'Die Großbärte aus Eisenschmiede haben mich geschickt, um nach Wirrbarts Ausgrabung zu sehen, als sie von dem Desaster erfuhren. Seht Euch nur um! Wertvolle Artefakte in das Meer geschwemmt und monatelange Ausgrabungen in wenigen Minuten zunichtegemacht.|n|nAls die Gezeitenwelle eintraf, vernichtete sie die Lager der Murlocs an der Küste. Gute Nachrichten? Nein, kein Glück für uns. Die Überlebenden suchen in den Ruinen Unterschlupf und fügen der Ausgrabung mehr Schaden zu, als es die Elemente je gekonnt hätten. Könntet Ihr Eure Watstiefel anziehen und Euch für mich um die Sache kümmern?', },
    {'Tötet 10 Orakel der Grauflossen oder Flüchtlinge der Grauflossen, die in Wirrbarts Ausgrabung Unterschlupf suchen.', },
  },
  [13908] = {
    'Aufsatteln',
    {'Euer Ravasaurus ist stark und gesund, und Ihr habt Euch wirklich gut aneinander gewöhnt. Ihr werdet ihn reiten können, sobald ich Euren Sattel und das Zaumzeug fertiggestellt habe. Genau wie Ihr müssen die Materialien speziell behandelt werden, um den Giften zu widerstehen, die der Raptor erzeugt.|n|nAlles, was Ihr tun müsst, ist mir etwas unverwüstliches Leder, Runenstoff und Geld für den Rest des Materials zu bringen. Dann werde ich den Sattel im Handumdrehen fertiggestellt haben.', },
    {'Bringt Mor\'vek im südöstlichen Teil der Marschen im Krater von Un\'Goro 20 unverwüstliche Leder, 20 Runenstoff und 80 Gold.', },
  },
  [13909] = {
    'Treibgut übrig?',
    {'Wir werden eine Lösung finden, $N. Wir brauchen nur ein bisschen zwergische Raffinesse. Denk nach, Groffy, denk schon!|n|nDie Murlocs wollen doch nur Unterschlupf, oder? Lasst uns konstruktiv sein. Das meine ich wortwörtlich.|n|nWährend der Katastrophe wurden alle möglichen Sachen an Land geschwemmt und ein paar der alten Hütten der Murlocs sind bestimmt noch benutzbar. Lauft an der Küste entlang und sucht für Murlocs geeignete Baumaterialien. Ihr werdet nicht lange suchen müssen.', },
    {'Findet 5 Stück verwertbare Grauflossentrümmer an der Küste und am Wasser in der Nähe von Wirrbarts Ausgrabung.', },
  },
  [13910] = {
    'Ein neues Zuhause',
    {'Können wir es bauen? Natürlich! Westlich von der Ausgrabung habe ich ein Banner an der Küste aufgestellt. Der Sand ist stabil und eignet sich ebenso gut als Bauort wie jeder andere. Nehmt mein Werkzeug und die Trümmerstücke und baut diesen störrischen Plagegeistern ein neues Zuhause.', },
    {'Baut eine Hütte für die Murlocs an der von Groff markierten Stelle an der Küste in der Nähe.', },
  },
  [13911] = {
    'Der geistesabwesende Ausgrabungsleiter',
    {'Und wer seid Ihr nochmal? $N? Kenne ich Euch? Wenn die Liga Euch schickt, dann könnt Ihr ihnen gleich sagen, dass ich hierbleibe! Ich gehe nicht ohne meinen Fund. Ich hielt ihn bereits in den Händen! Und dann brach plötzlich Geschrei aus. Und es wurde nass.|n|nHört gut zu, wer immer Ihr auch seid, ich habe alle Ereignisse von dem Tag der Gezeitenwelle in meinem Tagebuch aufgeführt. Und ich weiß auch, wo zu suchen ist. Nach dem Tagebuch, nicht nach dem Fund. Helft mir, eins zu finden, damit wir das andere finden können. Oder umgekehrt! Könnt Ihr mir folgen? Gut, dann folgt mir!', },
    {'Eskortiert den verwirrten Ausgrabungsleiter Wirrbart zu seinem Tagebuch. Sprecht mit Juniorarchäologe Ferd, wenn Ihr fertig seid.', },
  },
  [13912] = {
    'Schlammige Geheimnisse',
    {'Hinter Wirrbarts vergesslichem Äußeren befindet sich der Geist eines Genies, ein Mysterium im Gewand eines Senilen. Ich werde den alten Herrn nicht aufgeben. Seht hier, was ich in seinen Notizen gefunden habe... nicht hier... nein, das ist eine Einkaufsliste... Hier, auf der Seite, auf der er versucht herauszufinden, welches Jahr es ist: die Scheibe!|n|nWir glauben, dass es sich bei diesem Artefakt der Titanen um eine Art verschlüsselte Speicherscheibe handelt. Wir waren gerade dabei, es vorsichtig auszugraben, als das Desaster losbrach und nun hoffen wir, dass es sich noch immer in den Ruinen befindet. Taucht und sucht für mich danach!', },
    {'Findet eine schlammverkrustete uralte Scheibe in den Ruinen in der Nähe.', },
  },
  [13913] = {
    'Sie haben unsere Gnome',
    nil,
    nil,
  },
  [13914] = {
    'Sengende Rocfedern',
    {'Das Junge sieht Euch für einen Moment an, ein wenig, als ob es sich fragt, ob Ihr verstehen werdet. Es kratzt ein Bild von einem Paar Federn in die Erde, bevor es mit einer Klaue auf die Lederbänder um seine Ellbogen und Knie zeigt.|n|nEs sieht nicht hungrig aus, aber wofür könnten die Federn gut sein?|n|nEs will sie wohl als Schmuck haben, wie Ihr ihn an den anderen Raptoren gesehen habt. Die größten Federn findet man bei den sengenden Rocs, welche die großen Tierknochen in der westlichen Tanariswüste umschwärmen, nordöstlich des Disteltals.', },
    {'Euer Gifthautjunges möchte, das Ihr ihm 5 Federn von sengenden Rocs bringt.', },
  },
  [13915] = {
    'Sooooo hungrig',
    {'Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.|n|nDie Zeichnungen sind grob, aber Ihr könnt die Umrisse von Dimetrodonten, Stegodonten und Pterrordaktylen ausmachen. Als der Raptor die Zeichnung vervollständigt hat, sieht er wieder zu Euch auf, fletscht seine Zähne und schnappt ein paar Mal mit dem Maul.|n|nAnscheinend hat Euer Gifthautjunges Hunger auf frisches Fleisch von diesen Tieren. Findet und tötet Dimetrodonten, Stegodonten oder Pterrordaktylen im Krater von Un\'Goro und füttert Euer hungriges Junges mit ihrem Fleisch.', },
    {'Euer Gifthautjunges möchte, das Ihr 15 frische Dinosaurierfleischstücke an ihn verfüttert.', },
  },
  [13916] = {
    'Pochiert, gerührt oder roh?',
    {'Der Magen des Gifthautjungen knurrt, als es mit seinen Ärmchen wedelt, um Eure Aufmerksamkeit zu bekommen. Es beginnt, die Umrisse von Silithiden in die Erde zu kratzen, darunter einige Ovale. Es sieht Euch hoffnugsvoll an und deutet auf die Kreise.|n|nSie können nur Silithideneier darstellen. Der Giftige Unterschlupf im westlichen Tanaris, nahe der Grenze zum Krater von Un\'Goro, wäre sicherlich ein guter Ort, um die Eier zu finden, die Euer kleines Junges haben möchte.', },
    {'Euer Gifthautjunges möchte, das Ihr 12 Silithideneier an ihn verfüttert.', },
  },
  [13917] = {
    'Larve der Gorishi',
    {'Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.|n|nDie Zeichnungen des Jungen scheinen verschiedene Arten großer Insekten darzustellen, vielleicht die Gorishisilithiden. Das Junge beendet seine Zeichnung, zeigt mit einem kurzen Arm darauf, schnappt mit dem Kiefer und leckt sich das Mäulchen.|n|nEs möchte wohl, dass Ihr zur Wuchernden Narbe, im Zentrum des südlichen Kraters von Un\'Goro geht und Silithidenfleisch sammelt. Wenn Ihr das Fleisch habt, gebt es Eurem hungrigen Jungen zu fressen.', },
    {'Euer Gifthautjunges möchte, das Ihr 10 Stück Silithidenfleisch an ihn verfüttert.', },
  },
  [13918] = {
    'Die Verbindung der Titanen',
    {'Mit der Scheibe ergeben auch ein paar unserer früheren Funde jetzt mehr Sinn. Kurz nach meiner Ankunft hat Ausgrabungsleiter Wirrbart etwas gefunden, dass er für einen prähistorischen Toaster hielt.|n|nIch glaube eher, dass diese Kiste mit Öffnungen ein Lesegerät für besondere Daten ist. Leider ist es auseinandergefallen und mit dem Rest unseres Basislagers weggeschwemmt worden, als die Gezeitenwelle über uns hereinbrach!|n|nEs ist aber sicherlich nicht weit gekommen, $N. Die Einzelteile sind bestimmt im Sand vergraben. Hier, nehmt meinen einwandfrei funktionierenden Detektor für vergrabene Artefakte, um den Strand damit abzusuchen.', },
    {'Benutzt den Detektor für vergrabene Artefakte am Strand in der Nähe von Wirrbarts Ausgrabung, um 5 uralte Gerätefragmente zu finden. Fügt sie zusammen, um das uralte geschlitzte Gerät zu erhalten.', },
  },
  [13919] = {
    'Ein Ausflug zum Mondbrunnen',
    {'Es hat nicht funktioniert.|n|n<Ein besorgter und verzagter Ausdruck zeichnet Pelturas\' Gesicht, als er die Träne aus der Suppe entfernt und sie vorsichtig wäscht.>|n|nDer Ausbruch des Donnergipfels muss sie auf irgendeine Weise beeinträchtigt haben. Ihr müsst die Träne zum Mondbrunnen der Reinheit bringen. Er liegt noch immer unversehrt und von der Macht der Göttin beschützt am südöstlichen Fuß des Vulkans.|n|nDort wascht Ihr sie in den heiligen Wassern von Elune. Was danach geschieht, vermag ich nicht zu sagen. Ich fürchte um das Leben meiner Tochter. Es liegt nun in Euren Händen, $N.', },
    {'Nehmt Elunes Träne und reinigt sie in den Wassern des Mondbrunnens der Reinheit im Eschental.', },
  },
  [13920] = {
    'Bevor Ihr geht...',
    {'In Höllschreis Wacht wird jede Hilfe gebraucht, $N. Aber bevor Ihr Euch auf den Weg macht, gibt es noch etwas, das hier erledigt werden muss.|n|nDie meisten unserer verderblichen Waren sind während eines Angriffs der Allianz auf See verloren gegangen. Wir müssen genug Nahrungsmittel sammeln, um den Eschentalfeldzug durchführen zu können.|n|nReist nach Osten. Dort findet Ihr reichlich Wild. Kehrt mit dem besten Fleisch zurück, das Ihr für unsere Truppen finden könnt!', },
    {'Bringt 5 Hirschsteaks zu Kommandant Grimmfang in Zoram\'gar.', },
  },
  [13921] = {
    'Jener, der nach Vergebung sucht',
    {'<Eine Stimme aus dem Mondbrunnen durchflutet Euren Geist und gibt Euch ein Gefühl absoluten Friedens.>|n|nIhr sucht eine Heilung für das Kind, aber wisset, das alles seinen Preis hat. Im Osten liegt der Rajenbaumturm. Vor dem Turm neben dem Mondbrunnen steht jemand, welcher der Verderbnis anheimgefallen ist.|n|nAvrus Böswisper sucht Vergebung und Erlösung, $N. Werdet Ihr ihm helfen, seinen Wunsch zu erfüllen und dadurch Euer eigenes Ziel zu erreichen?', },
    {'Sprecht mit Avrus Böswisper beim Rajenbaumturm im Eschental.', },
  },
  [13922] = {
    'In den Händen des Widernatürlichen',
    {'Mein ehemaliger Klan, die Teufelshufe von Nachtflucht, hat den Himmelssturzsee vor einiger Zeit überfallen. Sie haben Mondsteine geraubt, die in dieser Gegend einzigartig sind.|n|nDiese Mondsteine sind dafür bekannt, große Heilkräfte zu besitzen und können sicherlich dafür verwendet werden, das kleine Mädchen zu heilen, das krank in Astranaar liegt.|n|nNachtflucht liegt an der Straße im Osten, die nach Norden führt. Von ihr zweigen verschiedene Pfade in Richtung Osten ab, die in die Hügel führen und dort findet ihr meine reuelosen Brüder. Sie haben, was Ihr sucht.', },
    {'Erlangt 5 gefallene Mondsteine.', },
  },
  [13923] = {
    'Zu Höllschreis Wacht',
    {'Auf ins Schlachtgetümmel, <Volk>!|n|nHöllschreis Wacht ist eine unserer am stärksten umkämpften Fronten im Eschental. Die Erfahrung wird Euch nützen... vorausgesetzt, Ihr überlebt.|n|nWenn Ihr bereit seid, sprecht mit Andruk. Ich habe mit ihm besprochen, dass er Euch direkt zu Eurem Posten bringt.|n|nSobald Ihr dort eintrefft, macht Hauptmann Goggath ausfindig. Er wird Euch weitere Anweisungen erteilen.|n|nBringt Schmerz und Tod über Eure Feinde! Für die Horde!', },
    {'Sprecht mit Hauptmann Goggath in Höllschreis Wacht.', },
  },
  [13924] = {
    'Ende gut, alles gut',
    nil,
    nil,
  },
  [13925] = {
    'Ein Stückchen Vorbeugen',
    {'Seid Ihr vertraut mit den Alten, $N? Onu und ich sind uns sicher, dass das von Euch im See gefundene Artefakt nur ihr Werk sein kann. Und es verzehrt Dunkelküste weiterhin. Irgendetwas hat die von uns lang totgeglaubten Schrecken erweckt. Schrecken, denen weder Ihr noch ich gewachsen sind. Aber zuerst müssen wir uns um die Wildtiere kümmern.|n|nHier in diesem Schössling ist die ganze Lebensessenz, die Ihr mir gebracht habt. Ich glaube, wir können damit die Fauna der Gegend retten. Versucht es zuerst an einem nicht verzehrten Bären, Hirsch oder Mondpirscher und berichtet mir, was geschieht!', },
    {'Testet den Lebensbringerschössling an einem gesunden ergrauten Distelbären, Weißschwanzhirsch, Mondpirscherpatriarchen oder einer gesunden Mondpirschermatriarchin in der Nähe.', },
  },
  [13926] = {
    'Kleines Waisenkind Roo von den Orakeln',
    {'Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, $N. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.|n|nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.|n|nBitte, $N, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.', },
    {'Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Orakelwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.', },
  },
  [13927] = {
    'Kleines Waisenkind Kekek von den Wolvar',
    {'Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, $N. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.|n|nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.|n|nBitte, $N, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.', },
    {'Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Wolvarwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.', },
  },
  [13928] = {
    'Rettet die Gefallenen',
    {'Meine Schildwachen und ich haben von Bewahrer Ordanus den Befehl erhalten, hier zu bleiben und den Turm zu verteidigen. Bisher konnten wir die Horde erfolgreich zurückschlagen, aber jetzt schlagen sie einen Bogen um uns und greifen unseren Zufluchtsort im Norden direkt an.|n|nDer Bewahrer schickt seine Dryaden aus, um die Bäume zu verteidigen, aber sie scheinen der Vorhut der Kriegshymnenorcs nicht gewachsen.|n|nIhr müsst dorthin und so viele Leichen der Lachenden Schwestern einsammeln, wie Ihr könnt. Bringt sie zu Halannia im Baum am Zufluchtsort. Sie wird wissen, was zu tun ist.', },
    {'Sammelt 10 Leichen der Lachenden Schwestern.', },
  },
  [13929] = {
    'Der grööößte Baum überhaupt!',
    {'Bevor der große Krieg passiert war und wir das Dorf verlassen haben, wir erinnern uns dran, wie Soo-say uns vom größten von allen Bäumen erzählt hat!|n|nSoo-say es nennen Grauschlund oder so. Soo-say uns erzählen, es ist in der Mitte von den Kritzlihügeln. Nein, warte. Das nicht was Soo-say gesagt hat. Soo-say sagt Grizzlyhügel. Jetzt wir uns erinnern! Großer Baum und in der Mitte von Grizzlyhügeln. Kann gar nicht übersehen!|n|nDu uns bringen dahin, oki? Wir uns anschauen den großen Baum von innen? Soo-say sagen, große Bärenleute leben auch im Baum. Vielleicht wir sie auch sehen.', },
    {'Besucht mit Eurem Waisenkind Roo den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.', },
  },
  [13930] = {
    'Heimat der Bärenleute',
    {'Hochschamane Rakjak uns immer Geschichten von mächtigen Kriegern erzählt, auch von weit weit weg. Manchmal er hat erzählt über riesige Bärenleute, wo einen großen Krieg um eine große Baumstadt kämpfen.|n|nVielleicht du bringt Kekek dort hin, Baum anschauen, Kampf anschauen! Hochschamane Rakjak erzählt Kekek, die große Baumstadt Grauschlund steht in der Mitte von den Grizzlyhügeln.|n|nKekek hat nie eine Stadt gesehen, bevor er kennengelernt hat die Waisendame, aber die Stadt hier hat keine Krieger, nur Männer in lila Kleidern. Kekek will richtige Krieger sehen, die um eine richtige Stadt kämpfen.', },
    {'Besucht mit Eurem Waisenkind Kekek den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.', },
  },
  [13931] = {
    'Ein neues Jahr, ein neues Souvernir',
    {'Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.|n|nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.', },
    {'Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.', },
  },
  [13932] = {
    'Ein neues Jahr, ein neues Souvernir',
    {'Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.|n|nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.', },
    {'Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.', },
  },
  [13933] = {
    'Der Bronzedrachenschrein',
    {'Manchmal Hochorakel Soo-say erzählt Geschichten über Schreine für Drachendinger, nicht wie großer Regenstein, aber anders. Soo-say sagt uns, vielleicht wir uns dort selbst sehen, aber nicht wie in Glitzer-Glitzer. Soo-say meint, wir uns dort sehen, wie wenn in vielen Jahren später.|n|nBringst du uns dorthin? Wir uns erinnern, Schrein für Bronzedrachendinger ist in einem Ort, der Drachenöde heißt. Soo-say sagt, großer Regenstein zeigt ihm Schrein im Nordosten vom Wyrmruhtempel, oder nordwestlich von einem Ort, den die Trockenhäute Feste Wintergarde nennen. Wir gehen?', },
    {'Besucht mit Eurem Waisenkind Roo den Bronzedrachenschrein. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.', },
  },
  [13934] = {
    'Der Bronzedrachenschrein',
    {'Als Kekek noch ein Welpe war, er hat die Ältesten oft von einem Schrein reden hören, weit weg. Manchmal sie sagen, dass die Bronzedrachendinger dort alles über die Zukunft wissen.|n|nKekek dir sagt, er wird großer Krieger sein, wir jetzt gehen nachsehen. Bronzedrachendingschrein ist irgendwo in Drachenöde, nordöstlich von Drachendingtempel, was Wyrmruh genannt wird und nordwestlich von Menschenstadt, was Wintergarde heißt.|n|nWir dort hingehen und Zukunft anschauen. Beweisen, dass Waisendame unrecht hat. Kekek sein Krieger, kein Lümmel.', },
    {'Besucht mit Eurem Waisenkind Kekek den Bronzedrachenschrein. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.', },
  },
  [13935] = {
    'Verteidigt den Baum!',
    {'Wir haben die Kraft des Herzens des Waldes dazu verwendet, um den Baum gegen die Horde zu verteidigen, aber seine Kraft ist nicht grenzenlos. Wir müssen sie dazu einsetzen, die Schlacht zu ihnen zu tragen!|n|nSchattumbra, die große Katze des Waldes, streift in der Nähe umher. Von ihr sollen wir unsere Hilfe beziehen. Ihr werdet eins mit dem Schatten von Schattumbra. Ihr werdet die Essenz des Panthers in Euch aufnehmen und diejenigen vernichten, die es wagen, die Macht des Eschentals herauszufordern.', },
    {'Sprecht mit Halannia, um den Schatten von Schattumbra zu beschwören und verwendet dessen Kraft, um 50 Feinde des Kriegshymnenklans am Rajenbaum zu vernichten.', },
  },
  [13936] = {
    'Twidels Narretei',
    {'Verspätungen, Verspätungen, Verspätungen! Ich bin mit meiner Weisheit am Ende!|n|nMir wurde gesagt, dieser Goblin sei brillant... dass er ein Gerät entwickeln würde, das die Feinde zur Unterwerfung zwingt. Bisher hat er nichts als leere Versprechen gemacht. Wenn er noch einmal mit leeren Händen zu mir kommt, werfe ich ihn persönlich von dieser Klippe!|n|nGeht zu ihm und sprecht mit ihm, $C. Lasst ihn wissen, dass mein Geduldsfaden bald reißt!', },
    {'Hauptmann Goggath will, dass Ihr mit Twidel in Höllschreis Wacht sprecht.', },
  },
  [13937] = {
    'Ein Besuch bei den Wunderwerken',
    {'Haben wir Zeit für noch einen Halt? Wir haben gehört, dass Dalaran hat einen Spielzeugladen, aber wir dürfen nie hingehen. Waisendame sagt, zu viele Waisen würden sich in Laden drängen. Vielleicht können wir gehen, nur wir?|n|nKönnen wir ein kleines Papierzeppelin haben? Wir denken, sie haben so was bei Wunderwerke in Dalaran. Wir wollten schon immer mit so was spielen. Vielleicht du uns eins zuwerfen?', },
    {'Kauft einen kleinen Papierzeppelin bei den Wunderwerken und werft ihn Eurem Waisenkind, Roo, zu.', },
  },
  [13938] = {
    'Ein Besuch bei den Wunderwerken',
    {'Du bringen Kekek zu noch einen Ort? Waisenfrau sagt, dass Dalaran Spielzeugladen hat, der Wunderwerke heißt, aber Kekek den noch nie gesehen. Sie sagt, dass, wenn ein Waisenkind hingeht, sie jeden hinbringen muss. Vielleicht du bringen Kekek dorthin?|n|nKekek hat andere Kinder gesehen, die mit kleinen Papierzeppelin spielen? Kekek gehört, dass die von Wunderwerken kommen. Vielleicht du einen besorgen und ihn gemeinsam mit Kekek herumwerfen?', },
    {'Kauft einen kleinen Papierzeppelin bei den Wunderwerken und werft ihn Eurem Waisenkind, Kekek, zu.', },
  },
  [13939] = {
    'Verderbtes Teufelsmoos',
    nil,
    {'Sammelt 6 Stück Teufelsmoos.', },
  },
  [13940] = {
    'Den Traum verlassen',
    {'Gut festhalten, $N. Die Reise zurück in die wirkliche Welt kann Geist und Körper von Unvorbereiteten etwas mitnehmen.', },
    {'Sprecht mit Malfurion beim Auge des Vortex in Dunkelküste.', },
  },
  [13941] = {
    'Abscheuliche Berührung',
    {'Githyiss die Üble war dafür bekannt, ein Gift zu besitzen, das stärker war als das Gift jeder anderen Waldweberspinne. Dirania Silberschrein am Fuße Aldrassils wäre sicherlich daran interessiert, den Giftbeutel von Githyiss zu benutzen, um ein mindestens genauso wirksames Gegengift zu brauen. Vielleicht sogar interessiert genug, um eine Belohnung ins Spiel zu bringen...', },
    {'Bringt den geschwollenen Giftbeutel zu Diriana Silberschrein am Fuße Aldrassils.', },
  },
  [13942] = {
    'Bombenbasteln',
    nil,
    nil,
  },
  [13943] = {
    'Ein Deckel für die Scharmützler',
    {'Unsere Kräfte sind noch nicht bereit, Astranaar anzugreifen, $C. Sie wissen trotzdem, dass wir kommen und sie werden sich nicht damit zufrieden geben, stillzusitzen und auf uns zu warten. Am Fuße dieser Klippen haben sie ein Lager aufgeschlagen, von wo aus sie nachts ihre lästigen Angriffe starten.|n|nBevor diese Geplänkel ihre Kühnheit weiter steigern, will ich, dass Ihr ihnen einen Besuch mit dem Zorn der Horde abstattet! Kehrt zu mir zurück, wenn Ihr den Elfen ihr Mütchen ein wenig gekühlt habt.', },
    {'Hauptmann Goggath will, dass Ihr 10 Scharmützler von Astranaar und 3 Offiziere von Astranaar tötet.', },
  },
  [13944] = {
    'Kleine Hände, schwache Nerven',
    {'<Twidel gestikuliert wie wild. Ihr seht, dass seine Handschuhe ungewöhnlich locker sitzen.>|n|nIhr habt es geschafft! Das sollte sogar Goggath zufrieden stellen!|n|nWir müssen nur noch einen Test durchführen, der den Erfolg unserer Bemühungen ausreichend demonstriert... ahh das Fuhrwerk!|n|nDer Boss will das verrottete Schrottstück schon seit Tagen loswerden. Verwendet meinen Sprengstoff, um den Schrott in Schutt zu verwandeln. Dann hört Euch an, was der Hauptmann dazu sagt.', },
    {'Probiert die improvisierte Sprengstoffstange an dem liegengebliebenen Wagen in Höllschreis Wacht aus.', },
  },
  [13945] = {
    'Gefahr vor Ort',
    {'Die Aggression der Knarzklauen begrenzt unsere Möglichkeiten. Niemand von uns ist davon begeistert, mit Klingen und Pfeilen gegen Kreaturen vorzugehen, mit denen wir einst befreundet waren, aber ich befürchte, dass sie sich bald gegen Dolanaar wenden werden.|n|nDie größere Sorge sind für mich die Furbolgs auf der Lichtung von Ban\'ethil und im Grabhügel von Ban\'ethil. Ihr müsst nach Westen reisen, in den Grabhügel vordringen und so viele der Knarzklauen töten, wie Ihr nur könnt. Wir bekommen wahrscheinlich nicht mehr viele Gelegenheiten, ihrer Stärke Einhalt zu bieten - beeilt Euch.', },
    {'Tötet 20 Knarzklauenfurbolgs auf dem Grabhügel von Ban\'ethil und in der Umgebung.', },
  },
  [13946] = {
    'Vergeltung der Natur',
    {'Ich bin froh, dass Ihr bereit wart, Eure Fehler wieder gutzumachen - das sagt viel über Euren Charakter aus.|n|nIch habe noch eine Aufgabe für Euch. Ich habe einige Zornwurzelsamen gesammelt. Sie sind Teufelszapfen ähnlich, aber viel stärker. Die Natur reagiert oft sehr negativ auf Dämonen und diese Zornwurzelsamen beinhalten hochkonzentrierte Abwehrstoffe.|n|nNördlich von hier, am Teufelsfels, sind Grellkin, die nicht mehr zu läutern sind. Benutzt die Zornwurzelsamen, um sie auszulöschen, bevor sie zu einer größeren Bedrohung werden.', },
    {'Verwendet Zornwurzelsamen, um 12 Teufelsfelsgrellkin zu töten.', },
  },
  [13947] = {
    nil,
    {'Twidel hat also endlich einen geeigneten Sprengstoff erfunden, wie?|n|nEr hätte keinen besseren Augenblick wählen können. Während wir sprechen, bereiten die Elfen von Astranaar einen vernichtenden Angriff auf unserer Lager vor.|n|nLasst unsere neue Waffe aus dem Himmel auf sie niederregnen! Die Zerstörung von Astranaar wird ein Stich ins Herz aller Nachtelfen sein!|n|nSprecht mit Thraka, wenn Ihr bereit seid, mit dem Angriff zu beginnen.|n|nZielt gut, $C.', },
    {'Hauptmann Goggath will, dass Ihr Twidels improvisierten Sprengstoff verwendet, um 20 Schildwachen von Astranaar zu töten und 10 Schleudern von Astranaar zu zerstören.', },
  },
  [13948] = {
    'Verbesserte Beobachtungen',
    {'Die Kultisten sind anscheinend dabei, die Überreste eines Wesens auszugraben, das als Soggoth der Glitschige bekannt ist.|n|nVielleicht haben die höherrangigen Kultisten mehr Informationen für uns.', },
    {'Schleicht mit Hilfe der Pantherfigur in die Meistergleve und beobachtet die Anführer der Schattenhammerkultisten auf der höheren Ebene.', },
  },
  [13949] = {
    'Karawane am Wegekreuz',
    nil,
    {'Sprecht mit Halga Blutauge in der Fernwacht, um die nächste Wegekreuz-Karawane zu Grol\'doms Hof zu begleiten.', },
  },
  [13950] = {
    'Spielgefährten!',
    {'Im Waisenhaus kann es schon sehr einsam werden, weißt du? Manchmal wollen wir mal rauskommen, neue Freunde finden.|n|nVielleicht kannst du uns irgendwohin mitnehmen, wo andere Junge sind? Wir haben von einem Ort gehört, der Zuflucht der Winterflossen genannt wird, in der großen Boreanischen Tundra. Wir glauben, dass es ganz weit drüben sein, im Nordwesten, in der Nähe der Kante der Kaltarrainsel.|n|nDie Waisendame sagen, dass jemand Tapferes dort ein paar Junge gerettet hat. Wir glauben, sie sind auch einsam. Wir glauben, sie brauchen Freunde. Bringst du uns hin?', },
    {'Nehmt Euer Waisenkind, Roo, und besucht die Zuflucht der Winterflossen. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.', },
  },
  [13951] = {
    'Spielgefährten!',
    {'Kekek ist der Meinung, es gibt nicht genügend andere Welpen, die auch bei der Waisendame leben. Vielleicht gehen wir und besuchen ein paar?|n|nKekek kennt einen Stamm, der in der Drachenöde lebt, an einem Ort, der Schneewehenlichtung heißt. Du kennst? Schneewehenlichtung ist im Norden von einer Walrossstadt, die heißt Hafen Mo\'aki, und im Süden von Rubindrachenschrein.|n|n<Kekek knurrt bei der Erwähnung der Tuskarr.>|n|nDu bringst Kekek da hin, zu ein paar von den Dörfern dort. Vielleicht treffen wir neue Wolvar und zeigen ihnen, wie stark die Wildherzen sind!', },
    {'Nehmt Euer Waisenkind, Kekek, und besucht die Schneewehenlichtung. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.', },
  },
  [13952] = {
    'Die dankbaren Toten',
    {'Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!|n|nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...|n|nIch glaube, Chapman dort drüben verkauft das Rezept.', },
    {'Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Menschengeist auf dem Friedhof von Sturmwind.|n|nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.', },
  },
  [13953] = {
    'Naga unter uns',
    {'Der Schädel dieser Kreatur wurde wohl im Kampf mit Aros gebrochen. Es handelt sich anscheinend um eine Kreatur, die Euch bislang als Naga ein Begriff war.|n|nTrotz ihrer monströsen Gestalt sind die Naga Nachtelfen, die von der arkanen Magie von Königin Azshara verformt wurden.|n|nSie haben sich wohl dazu entschlossen zu verhindern, dass Ihr das Horn der Urtume erhaltet.', },
    {'Kehrt zu Balren von der Klaue beim Hain der Uralten in Dunkelküste zurück.', },
  },
  [13954] = {
    'Die Drachenkönigin',
    {'In einer von Hochorakels Soo-says Geschichten es heißt, die Großen haben die Drachen gemacht und auch die Königin für die Drachen. Wir wollen sie sehen! Würdest du uns mitnehmen zur Spitze des Wyrmruhtempels? Wir erinnern uns, dass Soo-say uns erzählt hat, dass das Tempeldings in der Mitte der Drachenöde war.|n|nWir wollen wirklich so gerne die Drachenkönigin treffen. Sie muss so groß und schön sein. Vielleicht hilft sie uns, neue Eltern zu finden.|n|nDu uns nehmen mit?', },
    {'Nehmt Euer Waisenkind, Roo, und besucht Alexstrasza die Lebensbinderin auf der Spitze des Wyrmruhtempels. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.', },
  },
  [13955] = {
    'Die Drachenkönigin',
    {'Kekek hat Drachen immer gemocht. Wollte immer einer sein, aber Waisendame hat nein gesagt. Aber sie hat gesagt, dass vielleicht du Kekek zur Drachenkönigin bringen kannst.|n|nKekek glaubt, Waisendame hat einmal eine gute Idee. Du bringst Kekek zum Wyrmruhtempel in der Drachenöde? Fliegen ganz hoch bis zur Spitze, um Drachenkönigin zu sehen. Sie muss riesig groß sein, damit sie Königin von allen Drachen ist. Kekek kann es gar nicht erwarten, sie zu sehen!', },
    {'Nehmt Euer Waisenkind, Kekek, und besucht Alexstrasza die Lebensbinderin auf der Spitze des Wyrmruhtempels. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.', },
  },
  [13956] = {
    'Einen Großen treffen',
    {'Hochorakel Soo-say erzählt uns immer, wie die Großen Schreine gebaut haben und wir ihnen Glitzer-Glitzer geben, aber er hat Große nie gesehen. Niemand hat Große gesehen, vielleicht weißt du, wo wir einen finden?|n|nSoo-say erzählt uns, die Großen haben ein Tor gebaut und es in die Mitte vom Süden von Sholazar gestellt. Soo-say sagt nicht, wo es hinführt, aber vielleicht er führt zu einem Großen! Bringt uns durch das Tor, damit wir es rausfinden können, $N.', },
    {'Nehmt Euer Waisenkind, Roo, und besucht den Etymidian auf der Terrasse des Formers. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.', },
  },
  [13957] = {
    'Der mächtige Hemet Nesingwary',
    {'Weißt du, wen Kekek immer schon mal treffen wollte? Hemet Nesingwary.|n|nVielleicht kannst du Kekek mitnehmen, um ihn zu sehen? Der Älteste Harkek hat uns alles von ihm erzählt. Er kommt nach Sholazar, um die größten Tiere weit und breit zu jagen! Sogar Älteste der Wildherzen respektieren Hemet Nesingwary als großen Jäger.|n|nDer Älteste Harkek hat Kekek erzählt, dass Nesingwarys Basislager in der Mitte der Westseite von Sholazar, beim Fluss, der Meeresklammstrom genannt wird. Können wir ihn besuchen und lernen, wie man wie Hemet jagt?', },
    {'Nehmt Euer Waisenkind, Kekek, und besucht Hemet Nesingwary in Nesingwarys Basislager. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.', },
  },
  [13958] = {
    'Kritischer Zustand!',
    {'Wir halten den Feind gut auf Trab. Der Sieg rückt immer näher!|n|nAber es ist noch nicht Zeit zum Feiern, $C. Es bleibt noch viel zu tun, bevor die Horde das Eschental für sich beanspruchen kann.|n|nBeim Rajenbaum im Osten hat eine Schlacht begonnen. Berichten zufolge sind viele Mitglieder der Horde verwundet.|n|nBringt diese Heilvorräte dorthin und übergebt sie an Thagg. Erzählt ihm von unserem Angriff auf Astranaar. Vielleicht fördert es den dortigen Kampfgeist.', },
    nil,
  },
  [13959] = {
    'Zurück zum Waisenhaus',
    {'Wir viel Spaß mit dir hatten, $N. Wir uns wünschen so sehr, du könntest $Gunser Papa:unsere Mama; sein, aber du uns jetzt zur Waisenmatrone Aria in Dalaran zurückbringen musst.|n|nDu uns vielleicht irgendwann wieder besuchen kommen? Es toll war, Winterflossenjungen zu treffen und Drachenkönigin zu sehen. Es uns wird keiner glauben, dass wir einen Großen getroffen haben!|n|nWir dich werden vermissen, $N. Wir versprechen, dir mal einen Brief zu schreiben, oki?', },
    {'Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Orakelwaisenkindes überreicht.', },
  },
  [13960] = {
    'Zurück zum Waisenhaus',
    {'Weißt du was? So schlecht bist du gar nicht, $N. Du nimmst Kekek mit zu Orten, an denen was los ist. Kekek trifft viele neue Freunde und macht Dinge, die kein anderer Welpe macht.|n|nDu und Hemet Nesingwary und Schneewehenwelpen alle neue beste Freunde. Vielleicht du irgendwann das Grünehügelbuch bringen? Kekek verspricht, dir auch ab und zu zu schreiben, um zu sagen, wie die Dinge stehen. Vielleicht sogar nett sein zu Großzungenkindern.|n|nKekek muss jetzt zur Waisenmatrone Aria zurückkehren, zurück in Lilaleutestadt.', },
    {'Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Wolvarwaisenkindes überreicht.', },
  },
  [13961] = {
    'Quetscht sie aus',
    {'Es entspricht unserem Instinkt, einfach auf unsere Angreifer wie wild einzudreschen, aber die Weisheit gebietet einen anderen Weg. Wir sollten einen dieser Eindringlinge der Stacheleber befragen und so viel wie möglich herausfinden. Nehmt dieses Netz, $N, und fesselt einen Plünderer der Stacheleber, der unseren Hof westlich von hier angreift. Schlagt die Bestie bewusstlos und bringt sie zu mir.', },
    {'Verwendet Grol\'doms Netz, um einen Plünderer der Klingenmähnen zu fesseln und schleppt ihn zurück zu Togrik auf Grol\'doms Hof.', },
  },
  [13962] = {
    nil,
    {'Die Triagenverbandssets werden uns helfen, den Kampf weiterzuführen, aber wir befinden uns in einer Pattsituation.|n|nDie Dryaden sterben relativ schnell, aber ihr Anführer lässt sie kurz nach ihrem Fall immer wieder auferstehen. Wir stehen einem endlosen Strom dieses Ungeziefers gegenüber!|n|nBewahrer Ordanus versteckt sich in diesem mutierten Baum. Unsere Bemühungen, uns bis zu ihm durchzukämpfen, waren bisher vergeblich. Vielleicht könntet Ihr zu ihm gelangen, während wir mit seinen Dryaden kämpfen...|n|nDas ist sicherlich ein Kinderspiel für jemanden, der Astranaar erobert hat. Nein?', },
    {'Thagg im Rajenbaum will, dass Ihr Bewahrer Ordanus tötet.', },
  },
  [13963] = {
    'Jedes Mittel ist recht',
    {'Ich schätze, ein Schwung kaltes Wasser wird ihn wieder zu Bewusstsein kommen lassen. Was glaubt Ihr, wird er uns mitzuteilen haben?|n|nIch nehme ihn in dem Viehstall hinter mir in Gewahrsam. Ich glaube nicht, dass er lange bewusstlos bleiben wird. Findet so viel heraus, wie Ihr könnt bezüglich der Frage, warum die Stacheleber unsere Höfe angreifen! Die Befragungsmethoden überlasse ich Euch.', },
    {'Verhört den Gefangenen der Klingenmähnen. Falls er nicht dort oder bewusstlos ist, kann Togrik ihn für Euch wiederbeleben.', },
  },
  [13964] = {
    'Zum Turm',
    {'Wir haben die Silberwindzuflucht verloren! Alles, was ich weiß, ist, dass es einen Überraschungsangriff der Horde gab und dass sie irgendwie die Elementarwächter des Mystralsees gegen uns aufgebracht haben.|n|nDie Überlebenden sind bis zur Sternenstaubspitze zurückgefallen. $N, sie benötigen Eure Hilfe.|n|nBegebt Euch nach Südsüdost. Dort findet ihr den Turm am Eingang des Steinkrallenpasses, der Euch in das Steinkrallengebirge führt. Ich bin mir sicher, dass Ihr dort Schildwache Velene Sternenschlag findet, die dort den Gegenschlag unterstützt.', },
    {'Sprecht mit Schildwache Velene Sternenschlag auf der Sternenstaubspitze.', },
  },
  [13965] = {
    'Schaut nach den Edunes',
    {'$N, falls Ihr einen Augenblick erübrigen könnt, würde ich gerne Eure Hilfe in einer kleinen Angelegenheit in Anspruch nehmen.|n|nIch habe schon längere Zeit nichts mehr von meinen Freunden den Edunes gehört. Ich frage mich, ob Ihr auf einen Sprung nach Westen bei ihnen vorbeischauen könnt?|n|nIch danke Euch. Ihr Landhaus liegt auf einem kleinen Grundstück westlich des Schreins von Aessina.', },
    {'Sprecht mit Benjari Edune im Haus von Edune im Eschental.', },
  },
  [13966] = {
    'Ein Winterhauchgeschenk',
    nil,
    nil,
  },
  [13967] = {
    'Beim Ausdünnen der... Rotte?',
    {'Die Furbolgs sind zahlreicher, als wir es in diesen südlichen Gefilden erwartet hatten. Sie sind hier auch viel aggressiver, als wir es gerne hätten.|n|nWir müssen unsere Kräfte aufteilen, denn wir müssen Elfen jagen und gleichzeitig das dringend benötigte Holz schlagen. Das bedeutet, dass Ihr mir helfen müsst, die Belästigung durch die Furbolgs zu beenden.|n|nIch muss hier Forschungen durchführen. In der Zwischenzeit brauche ich Euch für eine etwas tatkräftigere Aufgabe. Bringt mir die Ohren der Furbolgs in der Nähe. Sie sollen Tarkan beweisen, dass wir das Problem in Angriff nehmen.', },
    {'Senani Donnerherz in der Silberwindzuflucht will, dass Ihr Euch 15 Furbolgohren von Totemikern der Fäulnisklauen und Ursa der Fäulnisklauen holt.', },
  },
  [13968] = {
    'Tortusks Untergang',
    {'Im Windschatten des Chaos\' im Süden scheint dieser Schläger \'Tortusk\' alle Flüchtlinge der Klingenmähnen unter seinem Banner versammelt zu haben. Unter seiner Führung verwandeln sie sich in dreckige, kleine Briganten. Mit dieser Sorte lässt sich nicht verhandeln. Tortusk muss vernichtet werden.|n|nWenn man unserem Gefangenen Glauben schenken kann, findet Ihr Tortusk südöstlich von hier an einem Ort namens Dornenhügel. Durchsucht die Felsen nach einer Stelle, von wo aus er einen guten Überblick über die Straße hat. Tötet ihn, $N, und die unmittelbare Gefahr wird weichen.', },
    {'Tötet den Anführer der Klingenmähnen Tortusk.', },
  },
  [13969] = {
    'Wo sind Grol\'dom Kodos?',
    {'Wenn Ihr nach Süden zum Dornenhügel reist, frage ich mich, ob Ihr unsere fehlenden Kodos ausfindig machen könntet? Nicht jede Karawane hat es über den Pass der Fernwacht geschafft. Diese Schläger der Klingenmähnen haben gestern Morgen ein Packtier entführt. Vielleicht ist es nicht mehr am Leben, aber falls es noch nicht tot ist, können wir es uns nicht leisten noch mehr Vieh zu verlieren.', },
    {'Findet den vermissten Kodo von Grol\'dom irgendwo auf dem Dornenhügel im Nördlichen Brachland.', },
  },
  [13970] = {
    'Tierpflege',
    {'Kodos sind zähe Kreaturen. Mit ein wenig Nahrung bekommen wir den Dicken vielleicht wieder auf die Beine.|n|nDie Klingenmähnen haben reichlich Getreide von früheren Karawanen geraubt. Ihr könnt das gestohlene Getreide in den nahegelegenen Lagern einsammeln.', },
    {'Sammelt 5 Säcke gestohlenes Getreide aus den Lagern der Klingenmähnen auf dem Dornenhügel.', },
  },
  [13971] = {
    'Die Rückkehr des Kodos',
    {'Das riesenhafte Reptil erhebt sich langsam, stellt sich auf die Beine, die lose Erde des Brachlandes rieselt von seinen Gliedmaßen, in die das Leben zurückgekehrt ist. Instinktiv stapft das Tier zurück zu seinem Zuhause auf Grol\'doms Hof.|n|nIhr wollt sicher mit Kranal Fiss sprechen, um sicherzugehen, dass es der Kodo geschafft hat.', },
    {'Sprecht mit Kranal Fiss auf Grol\'doms Hof, um Euch zu versichern, dass sein vermisster Kodo heil angekommen ist.', },
  },
  [13972] = {
    'Wieder unter Menschen',
    {'Endlich! Sieht aus, als ob Grennans Trank wenigstens bei einem von euch Wilden funktioniert hätte.|n|nIhr solltet in der Lage sein, zumeist die Kontrolle zu behalten - zügelt einfach Euer Temperament.|n|nMajor Armstead wird mit Euch reden wollen. Gilneas wird angegriffen und wir brauchen jeden fähigen Kämpfer, der eine Waffe halten kann.', },
    {'Sprecht mit Gwen Armstead in Grimmburg.', },
  },
  [13973] = {
    'Grol\'doms Miliz',
    {'Sie sind aus dem Nichts gekommen, $C! Stacheleber wo man auch hinsieht. Borsten, Schnauzen und Hauer. Wir haben uns auf den Hof zurückgezogen, aber es kamen immer mehr.|n|nUnsere besten Verteidiger sind auf dem Schlachtfeld gefallen und wir haben kein Lebenszeichen von Bauer Ralton. Ihr müsst sie für mich angreifen! Haltet mir diese Schweine vom Leib, während ich die Verwundeten verteidige, bis Hilfe eintrifft.', },
    {'Tötet 6 Plünderer der Klingenmähnen.', },
  },
  [13974] = {
    'Twidels winziges Paket',
    {'Woohoo!!|n|nSchaut nur, wie das brennt! Es ist revolutionär! Ein echter Durchbruch in der Explosionstechnik! Und das ist natürlich die einzige Technik, die zählt.|n|nAlle Goblins südlich von Nordend werden mich bewundern und beneiden!|n|nUnd ob Ihr es glaubt oder nicht, ich habe noch ein wenig an der Zusammensetzung gedreht, um sogar noch mehr Leistung herauszuholen!|n|nHier. Nehmt eine Probe dieses Zeugs und bringt sie nach Südosten in die Silberwindzuflucht. Mein Vetter Flooz kann es vielleicht brauchen, um die Horde bei der Eroberung dieses Ortes zu unterstützen.', },
    nil,
  },
  [13975] = {
    'Die Karawane zum Wegekreuz',
    nil,
    nil,
  },
  [13976] = {
    'Drei Männlein steh\'n im Walde',
    {'Habt Ihr Lust auf einen kurzen Abstecher in den Süden? Ich habe drei Freunde, von denen ich schon länger nichts gehört habe. Diese seltsamen Tentakel treten im Norden aus dem Boden hervor und bei all der dämonischen Aktivität wage ich es nicht, meine Familie alleinzulassen.|n|nBolyun hat sein Lager in der südwestlichen Ecke dieses Waldes aufgeschlagen - genau im Nordwesten dieses verdammten Schreins des Sengenden Feuers. Alenndaar und Harlown haben sich ihm angeschlossen, also müsste es ihnen eigentlich gut gehen, aber man kann nie wissen.|n|nHabt Dank, $N.', },
    {'Sprecht mit Bolyun in Bolyuns Lager im Eschental.', },
  },
  [13977] = {
    'Massenproduktion',
    nil,
    {'Flooz möchte, dass Ihr Twidels Bumm-Bumm-Pulver zu Jinx in den Stinkwerken bringt.', },
  },
  [13978] = {
    'Sie lauern im Nebel',
    {'Wir haben Mauern und Tore errichtet, um uns vor unseren Feinden zu schützen… und doch stehen Sie direkt auf unserer Türschwelle.|n|nDie Miliz musste ausrücken, um ihrer Hauptstreitmacht entgegenzutreten, sodass die Stadt jetzt völlig ungeschützt ist.|n|nMeine schlimmsten Alpträume sind wahr geworden. Grimmburg ist komplett von Orcs umstellt.|n|nSie warten entweder auf den Einmarschbefehl, oder erstatten einer größeren Streitmacht Bericht. So oder so, wir müssen sie erledigen.|n|nIhr seid vielleicht $Gein Wilder:eine Wilde;, aber Ihr seid $GGilneer:Gilneerin;. Vertreibt den Feind und gewinnt Eure Menschlichkeit zurück, $N.', },
    {'Gwen Armstead in Grimmburg möchte, dass Ihr 8 orcische Späher tötet.', },
  },
  [13979] = {
    'Das Expertengremium der Goblins',
    {'Wenn wir die verdammten Bombenangriffe durch diese Goblinmachwerke stoppen könnten, wären wir in der Lage, einen Gegenangriff zu starten und die Silberwindzuflucht zurückzuerobern!|n|nMeiner Erfahrung nach sind Goblins entweder faul oder unproduktiv, oder so eifrig, dass sie sich mit ihrem Sprengstoff schließlich selbst in die Luft jagen. Zu unserem Unglück werden sie von dem genialen, leitenden Bombentechniker Splodier angeführt.|n|nBegebt Euch in die Stinkwerke an der Westseite der Zuflucht und kehrt nicht zurück, bis Ihr den Kopf des leitenden Bombentechnikers in Händen haltet.', },
    {'Holt Euch Splodiers Kopf.', },
  },
  [13980] = {
    'Sie sind da draußen!',
    {'Sie sind da draußen, $C. Und sie sind uns auf den Fersen.|n|nEinige meiner Männer wurden tot aufgefunden. Elfenangriffe, ohne Zweifel.|n|nIch glaube, dass sie wegen Eurer Arbeit in Astranaar versessen darauf sind, unserem Fortschritt hier Einhalt zu gebieten. Ein letztes Aufbäumen vor der Niederlage!|n|nNehmt diese Brille. Sie hilft Euch dabei, auch den am besten getarnten Elf zu erkennen. Haltet sie mir vom Leib, während wir unsere Waffe für Euch vorbereiten.', },
    {'Jinx in den Stinkwerken möchte, dass Ihr 12 Assassinen des Eschentals tötet.', },
  },
  [13981] = {
    'Bombenlieferung gefällig?',
    {'Das ist sicherlich die größte Sprengstoffladung, die Ihr je zu Gesicht bekommen habt. Was in aller Welt würden die Goblins mit so einem Monstrum bombardieren wollen?|n|nSoweit Ihr das beurteilen könnt, ist das Werk fast vollendet. Die Goblins scheinen den Sprengsatz gut konstruiert zu haben. Es sieht so aus, als ob er gut geschützt ist gegen jeden Schaden, den Ihr ihm zufügen könntet. Und die Bombe ist sicherlich zu groß, als dass Ihr sie von hier forttragen könntet.|n|nIhr solltet die Bombe besser Jägerin Jalin auf der Sternenstaubspitze im Südwesten melden!', },
    {'Berichtet Jägerin Jalin auf der Sternenstaubspitze im Südwesten des Eschentals von der Existenz der Bombe.', },
  },
  [13982] = {
    'In Ketten gelegt',
    {'$N, Ihr müsst vorsichtig sein. Kaliva ist noch immer in der Nähe und als sie uns gefangen nahm, erwähnte sie ganz besonders Euren Namen.|n|nNur ihr Herz kann uns von diesen Ketten befreien, aber ich glaube, dies alles ist eine Falle nur für Euch!', },
    {'Beschafft Kalivas Herz.', },
  },
  [13983] = {
    'Baut Euren eigenen Sarg',
    {'Sobald sie fertig ist, müssen wir die Bombe zu Saurboz schaffen.|n|nUnd mit \'wir\' meine ich \'Ihr\'.|n|nBei all den Feinden, die sich hier herumtreiben, muss ich etwas ganz Besonderes bauen, wenn Ihr mit dieser Aufgabe Erfolg haben wollt.|n|nIch könnte einen dieser kaputten Schredder umbauen, aber dazu brauche ich ein paar Teile. In den Wäldern im Westen solltet Ihr eigentlich alles problemlos finden.|n|nBeschafft mir die Teile, während ich die Bombe fertig baue.', },
    {'Vorarbeiter Jinx möchte, dass Ihr 3 Bronzeräder, 3 Stück Kupferbeschlag und 5 Klemmbolzen sammelt.', },
  },
  [13984] = {
    'Sie sind uns immer auf der Spur',
    {'Der orcische Spähtrupp nutzt Spürwölfe. Es kann gut sein, das ihr Anführer selbst ein Wolfbändiger ist.|n|nBringt mir die Halsbänder der Wölfe. Dann können wir unsererseits einen Bluthund auf ihre Fährte schicken.', },
    {'Gwen Armstead in Grimmburg möchte, dass Ihr ihr 3 stachelige Wolfshalsbänder bringt.', },
  },
  [13985] = {
    'Leert den Schrein',
    {'Dem Bösen dieser Brennenden Legion muss ein Ende gesetzt werden!|n|n$N, Ihr habt einen ihrer Mächtigsten besiegt, aber es gibt noch immer zahlreiche Dämonen, die die Wälder im Osten im Schrein des Sengenden Feuers verseuchen.|n|nWerdet Ihr als ein Freund des Waldes diese Kreaturen vernichten und dann den Großen Baobob, das große Urtum des Krieges am Schrein von Aessina im Nordosten warnen?', },
    {'Vernichtet 12 beliebige Dämonen am Schrein des Sengenden Feuers.', },
  },
  [13986] = {
    'Ein verletzter Kollege',
    {'Es war ein harter Kampf hier oben, $C, wie Ihr sicher wisst. Wir harren aus, doch ist nicht jeder unversehrt geblieben.|n|nEine der Kriegerinnen unserer Gruppe, Aponi Lichtmähne, leidet an einer infizierten Wunde an ihrem Arm. Sie wurde zur Erholung nach Donnerfels zurückgebracht. Es scheint jedoch, als hätte sie in der ganzen Aufregung ihren Schild hier an der Front vergessen - könntet Ihr es ihr bringen, zusammen mit unseren Genesungswünschen? Uns fehlt ihr Lächeln hier sehr.|n|nIhr könnt sie auf der Anhöhe der Ältesten finden.', },
    {'Bringt Aponi Lichtmähne auf der Anhöhe der Ältesten in Donnerfels den ramponierten Stammesschild.', },
  },
  [13987] = {
    'Das letzte Gefecht',
    {'$N, ich brauche unbedingt Eure Hilfe! Ich kann gegen diesen Ansturm der Dämonen nicht ewig standhalten. Wenn ich falle, ist Astranaar als Nächstes dran!|n|nBitte helft mir!', },
    {'Tötet 30 dämonische Eindringlinge.', },
  },
  [13988] = {
    'Mit eigenen Augen',
    {'Das Leben explodiert förmlich auf diesem kargen Boden... Mein Gefährte Jerrik hat erzählt, dass sich ähnliche Dinge überall im Brachland ereignen. Ich muss es mit eigenen Augen sehen, aber ich darf meinen Posten nicht verlassen.|n|nHier, $N, ich werde Euch meine \'Augen\' leihen. Seit dem Tag, an dem ich meinen Namen erhalten habe, hat mein Adlergefährte hier mir gut gedient. Bitte begleitet ihn zum Donnerkopfgipfel, wo Jerrik Euch erwartet und wir werden uns umsehen.|n|nUm auf die Spitze zu gelangen, folgt der Straße Richtung Osten am Wegekreuz. Wendet Euch nach Süden, sobald Ihr einen großen Stein erreicht, der mit Malereien übersät ist.', },
    {'Bringt Tongas Augen zum Donnerkopfgipfel südwestlich von Ratschet.', },
  },
  [13989] = {
    'König der Fäulnisklauen',
    {'Es interessiert mich herzlich wenig, wer Ihr seid, <Volk>. Worauf es mir ankommt ist die Rettung der Furbolgs.|n|nBringt dieses Blutreißerbanner das kurze Stück in Richtung Nordosten zur Laubtatzenlichtung und platziert es auf ihrem Totemhügel. Sie werden es als einen Angriff ansehen und versuchen, das Banner zu zerstören. Haltet die Stellung. Häuptling Murgut wird auftauchen, um das Gesicht des Stammes zu wahren. Wartet auf ihn und dann tötet den Verräter!|n|nTeilt Eure Kräfte gut ein. Euch steht ein langer Kampf bevor.', },
    {'Platziert das Blutreißerbanner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören, bevor ihr Häuptling kommt. Besiegt Häuptling Murgut.', },
  },
  [13990] = {
    'Upper Deck Promo - Hühnerreittier',
    nil,
    nil,
  },
  [13991] = {
    'Die gestohlene Lohnliste',
    {'Und, $N. Ich gebe zu, dass Ihr gut in meine geliebte Horde passen würdet. Ihr habt Stärke, List und Einsatz bewiesen... Sogar Thork erwähnte Euch kürzlich namentlich, und weder er noch ich sind leicht zu beeindrucken. Gute Arbeit.|n|nJetzt wird es Zeit, dass Ihr Euch weiter in die Riemen legt. Die wöchentliche Lohnliste für die Wachen des Wegekreuzes ist verloren gegangen. Gazrog in Ratschet führt eine Untersuchung an. Sprecht mit ihm!|n|nFolgt einfach der Straße von hier Richtung Osten zur Küste.', },
    {'Sprecht mit Gazrog in der Nähe des Eingangs nach Ratschet.', },
  },
  [13992] = {
    'Eine kleine Ablenkung',
    {'Ich wurde hierher geschickt, um die Aktivitäten der Zentauren auszukundschaften. Ich habe all ihre Bewegungen seit Tagen beobachtet! Es wird Zeit für mich, mich wieder davonzuschleichen, aber sie haben diesen Ort umzingelt.|n|nIhr seht aus, als ob Ihr gefährlich seid. Könnt Ihr ein wenig Chaos für mich veranstalten? Sie aufwühlen! Metzelt sie wahllos nieder. Während sie nach Euch suchen, schleiche ich mich davon, um meinen Bericht an Regthar Totenfurt zu überbringen.', },
    {'Tötet 8 Zentauren der Kolkar.', },
  },
  [13993] = {
    'Ihr seid die Bombe!',
    {'In Ordnung, $N! Es ist alles bereit.|n|nIch habe den Weg zum Steinkrallengebirge vorprogrammiert, sodass Ihr nur darauf achten müsst, dass die Bombe unbeschädigt bleibt.|n|nVerwendet die Sägeblätter, um Feinde aus der Ferne niederzumähen, oder schließt eine Sicherung kurz, um allen einen Schlag verabreichen, die Euch zu nahe kommen.|n|nIhr könnt die Bombe nur EINMAL reparieren, wenn sie schwer beschädigt wurde. Überlegt also genau, wann Ihr das tun möchtet!|n|nSprecht mit mir, wenn Ihr bereit seid.|n|nViel Glück!', },
    {'Vorarbeiter Jinx möchte, dass Ihr den zweckendfremdeten Schredder zum Steinkrallengebirge nehmt und mit Saurboz sprecht.', },
  },
  [13994] = {
    nil,
    {'Hört zu, $N. Ihr müsst tun, was der Inquisitor von Euch verlangt.|n|nEr behauptet, dass die Horde Gilneas angreift. Wenn das wirklich stimmt, muss jemand dem Wolfsherzklan Bescheid geben, bevor es zu spät ist.|n|nAußerdem würde Balvus Wolfsherz mir bei lebendigem Leib die Haut abziehen, wenn er wüsste, dass ich Euch in Graumähnes Reserve versauern lassen würde.|n|nGeht, $N. Rettet Euch.. und wenn die Zeit gekommen ist... warnt unsere Brüder im Schwarzforst.', },
    {'Sprecht mit Inquisitor Schwarzbrunn in Grimmburg.', },
  },
  [13995] = {
    'Der König vom Berge der Zentauren',
    {'Wir wurden hierhergeschickt, um die Bewegungen der Zentauren der Kolkar zu beobachten, aber nachdem wir diesen dreckigen Tieren eine Woche dabei zugesehen haben, wie sie um die Oase galoppieren, juckt es mich, meiner Axt ihre Hälse zu schmecken zu geben. Was sagt Ihr, $C? Wollt Ihr mit mir ein wenig Chaos verbreiten?|n|nMal sehen, ob wir die Aufmerksamkeit ihres stärksten Kriegers Kurak auf uns lenken können.', },
    {'Sorgt dafür, dass Gorgal Zornesnarbe am Leben bleibt, während er sich mit den Zentauren anlegt und helft ihm, Kurak zu töten.', },
  },
  [13996] = {
    'Könnt Ihr die Quest machen, während ich kämpfe?',
    {'Eure Aufgabe, wenn Ihr diese Nachricht lesen könnt während ich mich im Kampf befinde, ist es, diese lästigen Kobolde zu bekämpfen, wegen denen ich dauernd im Kampf bin.|n|nAllein schon die Tatsache, dass Ihr das lest ist ein SIEG! Ist Dan nicht toll?', },
    {'ELM Daze Target von der Designer-Insel hat Euch aufgefordert, 5 ELM Angreifer für Dan und die Gerechtigkeit zu töten!', },
  },
  [13997] = {
    nil,
    {'Dan is the most awesome programmer in the world... the World of Warcraft!|n|nIsn\'t it weird that you used to not be able to talk with me at all while I was fighting? No longer, my friend, now that Dan has made significant improvements to one of my creature flags!|n|nCelebrate with me by snuffing out the lives of these awful creatures that perpetually have me in combat.', },
    nil,
  },
  [13998] = {
    'Operation Pilzkultur',
    {'Wir haben diese ungewöhnlichen Sporen kultiviert, die Ihr ausgegraben habt. Das gelang mir mit einer wundervollen Mischung aus... Reagenzien... auf die ich sehr stolz bin. Ich kann es nicht erwarten, zu sehen, wie meine manipulierten Sporen auf die Gewässer in den Oasen am Wegekreuz reagieren.|n|nDie Brackige Oase im Südosten bietet uns eine unverseuchte Region für unsere Experimente. Sät diese Kulturen in der feuchten Erde irgendwo in der Nähe der Oase für mich aus und dokumentiert die Ergebnisse.|n|nAchtet darauf, dass Ihr Euren Mund bedeckt, $C.|n|n<Helbrim grinst entwaffnend.>', },
    {'Pflanzt eine Pilzkultur in der Nähe der Brackigen Oase und beobachtet das Ergebnis.', },
  },
  [13999] = {
    'Wer hat meinen Zauberpilz gegessen?',
    {'Stellt Euch mal vor, was wir damit anstellen können, $N! Schnellwachsende Pilze, die jedes beliebige Gift übertragen können. Meine Gefährten in der Unterstadt wird das sicher interessieren.|n|nHier sind meine Aufzeichnungen und ein paar Proben. Wenn wir schnell sind, erwischen wir das nächste Schiff, das in Richtung der Östlichen Königreiche in See sticht. Nehmt die Straße östlich von hier und folgt ihr zur Goblinstadt Ratschet. Sucht nach der Taverne \'Zum geborstenen Kiel\' im Südteil der Stadt und übergebt dies meiner Mitarbeiterin Sashya.', },
    {'Bringt Helbrims Forschungsergebnisse zu Sashya in Ratschet im Nördlichen Brachland.', },
  },
  [14000] = {
    'Jäger oder Gejagter',
    {'Die hier sollten ausreichen, um denjenigen zu finden, der die Wölfe kontrolliert.|n|nBringt die Halsbänder zu Jäger Russell. Ich habe ihn gebeten, seine besten Bluthunde für diese Aufgabe zu reservieren.', },
    {'Bringt die stacheligen Wolfshalsbänder zu Jäger Russell in Grimmburg.', },
  },
  [14001] = {
    'Rettungskapseln der Goblins',
    {'$N, es tut mir leid. Ich dachte, Ihr wärt tot!|n|nEs ist einfach Irrsinn! Wir sind direkt in einen Kampf zwischen der Allianz und der Horde gesegelt.|n|nWir müssen unsere Brüder und Schwestern retten.|n|n<Er zeigt auf die Rettungskapseln, die um Euch herum im Wasser verstreut sind.>|n|nIch glaube, ich bleibe hier noch ein wenig sitzen und komme zu Atem. Könntet Ihr aufs Meer schwimmen und sie herauslassen? Nehmt meine thermohydraulischen Flossen, damit könnt Ihr Euch schneller fortbewegen.|n|nLasst Sassy wissen, dass ich gleich losschwimme.', },
    {'Rettet 6 überlebende Goblins.', },
  },
  [14002] = {
    'Eine Aufgabe für einen Bluthund',
    {'Bringt diese Halsbänder zu den Käfigen dort hinten. Zeigt sie einem meiner Bluthunde. Er weiß schon, was zu tun ist.|n|nSobald er gefunden hat, was Ihr sucht, solltet Ihr Euch auf einen Kampf gefasst machen. Meldet Euch bei der Bürgermeisterin, wenn Ihr fertig seid.', },
    nil,
  },
  [14003] = {
    'Wie man ein Samophlang repariert',
    {'Nun, das lief leider nicht so, wie erwartet. Ich glaube, ich habe es kaputt gemacht.|n|nAber kein Grund zur Panik. Tut mir einen Gefallen und folgt diesem Weg zu Brak hier im Lager. Er dengelt dieses Ding schnell wieder in die richtige Form!', },
    {'Bringt das zerbrochene Samophlang hinüber zu Brak Polterrohr innerhalb des Lagers.', },
  },
  [14004] = {
    'Bringt das Samophlang zurück',
    {'Nun, das hat nicht funktioniert. Ich habe ein paar zusätzliche Anzeigegeräte an dem Samophlang angebracht, die seine strukturelle Integrität messen. Sie zeigen stets einen absoluten Tiefstand an. Ich könnte einige Wählscheiben und vielleicht einen Hebel oder zwei hinzufügen und versuchen, es zu reparieren, aber... Ich glaube, das könnte alles nur noch schlimmer machen.|n|nSeht mal, was ich entdeckt habe, als ich das Ablassventil blockiert habe und die Ummantelung des Differentialgehäuses abgeflogen ist: das persönliche Gravurzeichen von \'Boss Kupferdraht\'. Bringt dies zurück zu Stotterspritter und sagt ihm, er soll dieses Genie Kupferdraht auftreiben.', },
    {'Bringt das Wrack des überarbeiteten Samophlangs zurück zu Stotterspritter in Düsentopfs Außenposten. Sprecht mit Wenikee, um direkt dorthin teleportiert zu werden.', },
  },
  [14005] = {
    'Elunes Rache',
    {'Während Teldrassil sich selbst von der Verderbnis reinigt, welche sein Wachstum all die Jahre entstellt hat, hat sich südlich von hier am Rand des Baumes eine bösartige Wucherung gebildet. Wir haben die Möglichkeit, anzugreifen und die Quelle des Teufelsmooses, das die Knarzklauen, die Bäumlinge und alles andere verdorben hat, zu säubern.|n|nMit dem Wasser, das Ihr in den Mondbrunnen gesammelt habt, und der erneuerten Kraft von Teldrassil selbst kann ich Euch eine kurze Zeit große Macht gewähren. Setzt der Verderbnis ein Ende, $N.', },
    {'Nutzt die Macht, die Tarindrella Euch gewährt hat, um Euch zum Herz der Verderbnis durchzukämpfen und es zu zerstören.', },
  },
  [14006] = {
    'Lest das Handbuch',
    {'Damals, als ich noch in der Tüftlerverbindung war, war Boss Kupferdraht der beste Ingenieur, den wir hatten. Er wurde abtrünnig und ging zur Venture Company, kurz bevor ich die Tüftlerverbindung verließ, und er nahm seine größten Technologien mit. Er hortete seine Geheimnisse und gab nur hier und da ein Geheimnis an den inneren Kreis seiner Vertrauten weiter.|n|nWenn er das Samophlang gebaut hat, dann besitzt er wahrscheinlich das Handbuch. Das Letzte, was ich von ihm gehört habe, war, dass er hier in der Nähe vor der Felsadermine im Nordosten arbeitet. Besorgt das Handbuch von ihm und sammelt die Seiten ein, die seine Anhänger noch haben.', },
    {'Sammelt die Teile des Samophlanghandbuchs ein.', },
  },
  [14007] = {
    'Zuverlässiger Schuss',
    nil,
    nil,
  },
  [14008] = {
    'Arkane Geschosse',
    nil,
    nil,
  },
  [14009] = {
    'Blitzheilung',
    nil,
    nil,
  },
  [14010] = {
    'Ausweiden',
    nil,
    nil,
  },
  [14011] = {
    'Urtümlicher Schlag',
    nil,
    nil,
  },
  [14012] = {
    'Entzünden',
    nil,
    nil,
  },
  [14013] = {
    'Anstürmen',
    nil,
    nil,
  },
  [14014] = {
    'Holt unsere Sachen zurück!',
    {'Unsere Bomben und Werkzeuge! Diese hinterhältigen Affen aus dem Osten haben sie alle im Schutz der Dunkelheit gestohlen!|n|nKönnt Ihr dorthin gehen und sie für uns zurückholen, $N? Ohne diese Werkzeuge haben wir keine Chance, von dieser Insel herunterzukommen!', },
    {'Besorgt 8 Werkzeugkisten.', },
  },
  [14015] = {
    'Unvollständiges Kartenmaterial',
    {'Ihr öffnet die Schriftrolle und erkennt eine ziemlich genaue Karte von Gilneas, bis auf eine Ausnahme. Das gesamte Gebiet zwischen der Küste und den Klippen hinter Grimmburg scheint zu fehlen.|n|nAußerdem seht Ihr Pfeile, die wohl die Bewegung der Horde tiefer in das Innere von Gilneas anzeigen. Bürgermeisterin Armstead wäre an diesen Informationen sicher interessiert.', },
    {'Bringt die nasse Karte zu Bürgermeisterin Armstead in Grimmburg.', },
  },
  [14016] = {
    'Der Fluch des Schwarzen Ritters',
    {'Ich wollte die Überreste des Schwarzen Ritters nach Eurem Sieg vom Turnierplatz entfernen lassen, aber Argentumbeichtpatin Blondlocke bestand darauf, dass er ein ordentliches Begräbnis erhält. Seither hält sich eine düstere Gegenwart hartnäckig auf dem Friedhof, und niemand wagt sich mehr dorthin, um die Gefallenen zu ehren.|n|nWürdet Ihr dem Friedhof gleich außerhalb des Turnierplatzes im Osten einen Besuch abstatten und sehen, ob Ihr herausfinden könnt, was dort vor sich geht?', },
    {'Kreuzfahrerin Rhydalla auf dem Argentumturnierplatz möchte, dass Ihr das Grab des Schwarzen Ritters untersucht.', },
  },
  [14017] = {
    'Das Schicksal des Schwarzen Ritters',
    {'Ihr sagt, dass Kultisten die Leiche entfernt haben? Mir fällt da nur ein Ort ein, zu dem sie sie gebracht haben können: Todessprechers Wacht, das Lager auf der Anhöhe westlich des Turnierplatzes.|n|nWas auch immer die Kultisten vorhaben, man muss sie aufhalten. Die Gerüchte, die ich gehört habe, können also nur wahr sein. Der berüchtigte Doktor Kohler muss unter den Kultisten sein und seine Kunst ausüben. Sucht nach einer Anhöhe oder einem Altar, von dem aus man Sicht auf das Kultistenlager hat. Tötet den Doktor und sucht nach Beweisen über seine Machenschaften. Bremst ihn bei seiner Arbeit, egal wie.', },
    {'Geht nach Todessprechers Wacht, bringt Doktor Kohlers Befehle in Euren Besitz und kehrt dann zu Kreuzfahrerin Rhydalla auf dem Argentumturnierplatz zurück.', },
  },
  [14018] = {
    'Jener, der nach Vergebung sucht',
    {'Die Stimme der Göttin hat am Mondbrunnen zu Euch gesprochen, $N. Das Heilmittel für Relara liegt im Osten beim Rajenbaumturm, der dem Verderben anheimgefallen ist.|n|nAvrus Böswisper wünscht Vergebung und Erlösung. Es liegt an Euch, ihn zu unterstützen und dabei hoffentlich auch meinem Kind zu helfen.', },
    {'Sprecht mit Avrus Böswisper beim Rajenbaumturm im Eschental.', },
  },
  [14019] = {
    'Affentheater',
    {'Wir haben immense Probleme mit den Affen im Dschungel östlich von hier. Sie haben all unseren Sprengstoff gestohlen und jetzt fangen sie an, damit durch die Gegend zu werfen.|n|nUnd manchmal sogar auf uns!|n|nIch habe Zisch Zündel befohlen, etwas von seinem Nitro in diese Bananen zu füllen. Kein Affe kann einer leckeren Banane widerstehen!|n|nIhr müsst sie nur damit füttern.', },
    {'Füttert 10 bombenwerfende Affen, indem Ihr ihnen Nitrokaliumbananen zuwerft.', },
  },
  [14020] = {
    'Der Fluch',
    {'Der Fluch hat uns vollkommen überrascht. An einem Tag war noch alles normal, doch schon am nächsten waren ganze Dörfer in heulende Worgenrudel verwandelt. Auf Lord Graumähnes Befehl hin haben wir uns Tag und Nacht abgerackert, um ein Mittel dagegen zu finden. Bis jetzt ist uns das leider nicht gelungen.|n|nWir haben jedoch etwas gefunden, was fast annähernd so gut ist. Mit der destillierten Essenz von schwarzen Alraunen können wir die Folgen des Fluchs größtenteils lindern.|n|nLeider sind mir wegen diesem Orcangriff die Vorräte ausgegangen. Bringt mir alle schwarzen Alraunen, die Ihr finden könnte, sodass ich noch mehr von dieser Essenz herstellen kann.', },
    {'Krennan Aranas in Grimmburg möchte, dass Ihr 8 schwarze Alraunen besorgt.', },
  },
  [14021] = {
    'Minenarbeiter in Not',
    {'Kluge Bergbauaffen!|n|nSie sind in der ganzen Höhle verstreut und bauen Erz ab… mit Spitzhacken! Das ist doch nicht normal. Ich bin mir sicher, dass es an dem Kaja\'mit liegt.|n|nKeiner meiner Minenarbeiter ist wieder herausgekommen. Und ich habe nicht mehr viele! Ihr könnt also meine Not erkennen, $N.|n|n<Der Vorarbeiter senkt die Stimme.>|n|nDiese Typen sind nicht mal annähernd so gut wie meine alte Dschungeltrolltruppe. Ah, das waren noch Zeiten!|n|nVielleicht könnt Ihr meinen letzten Minenarbeiter hier durch die Höhle begleiten und ihm die Affen vom Leib halten? Wir brauchen dieses Kaja\'mit!', },
    {'Eskortiert den verängstigten Minenarbeiter durch die Kaja\'mithöhle.', },
  },
  [14022] = {
    'Pilgerfreuden',
    {'Möchtet Ihr nicht vielleicht das Pilgerfreudenfest mit uns feiern, $N? Dies ist eine Zeit des Besinnens auf Eure Reisen und Euer Glück, eine Zeit des Teilens - von gutem Essen und unterhaltsamen Geschichten!|n|nIhr könnt an den wundervollen Pilgerfreudenfeierlichkeiten in der Nähe der größeren Städte teilhaben, indem Ihr an einer der Festtafeln Platz nehmt und das vorhandene Essen verteilt.|n|nWenn Ihr lernen möchtet, wie man die traditionellen Pilgerfreudenspeisen zubereitet, sucht Gregory Tabor auf. Ihr findet ihn vor den Toren von Sturmwind.', },
    {'Sprecht mit Gregory Tabor außerhalb der Tore Sturmwinds.', },
  },
  [14023] = {
    'Gewürzbrotfüllung',
    {'Unsere Gewürzbrotfüllung ist das Prunkstück der Pilgerfreudentafel. Das Rezept war schon immer besonders beliebt in Sturmwind und hat nun seinen rechtmäßigen Platz im Pilgerfreudenfest-Kochbuch eingenommen.|n|nWenn Ihr in der Kochkunst bereits bewandert seid, könnt Ihr Euer Exemplar des Kochbuchs und alle benötigten Zutaten für ein Festmahl vom Händler des Pilgerfreudenfests erstehen. Und seid Ihr es nicht, so ist jetzt die beste Gelegenheit, dies zu ändern!|n|nHabt Ihr die Gewürzbrotfüllung zubereitet, bringt sie zu Jasper Moore, in der Nähe der Festtafel.', },
    {'Bereitet 5 Portionen Gewürzbrotfüllung zu und bringt sie zu Jasper Moore an die Festtafel außerhalb der Tore Sturmwinds.', },
  },
  [14024] = {
    'Kürbiskuchen',
    {'Eure Gewürzbrotfüllung riecht ausgesprochen verlockend, doch keine Pilgerfreudentafel ist ohne einen prächtigen Kürbiskuchen komplett. Dies ist ein weiteres sehr beliebtes Gericht hier in Sturmwind, denn Kürbiskuchen wird aus den reifen Elwynnkürbissen zubereitet, die nur hier gedeihen.|n|nSolltet Ihr nicht wissen, wie man ihn zubereitet, könnt Ihr das Rezept in Eurem Pilgerfreundenfest-Kochbuch finden.|n|nWürde es Euch etwas ausmachen, einige Kuchen zuzubereiten und sie Edward Winslow zu bringen, außerhalb von Eisenschmiede? Sein Vorrat ist sicherlich schon knapp geworden.', },
    {'Bereitet 5 Kürbiskuchen zu und bringt sie Edward Winslow an die Festtafel außerhalb von Eisenschmiede.', },
  },
  [14025] = {
    'An die Front',
    nil,
    nil,
  },
  [14026] = {
    'Knall und weg',
    nil,
    nil,
  },
  [14027] = {
    'Von Angesicht zu Angesicht',
    {'Meine Männer könnten wirklich etwas Hilfe gebrauchen, $N. Wir versuchen mit aller Kraft, die Orcs zurückzuhalten, aber es reicht einfach nicht.|n|nTötet so viele Orcs, wie nötig ist, um das Blatt zu unseren Gunsten zu wenden. Wollen wir mal sehen, ob die Wildheit Eures Klans sich gegen die Orcs genauso auszeichnet, wie gegen unser Vieh.', },
    {'Leutnant Wright möchte, dass Ihr 10 orcische Eindringlinge tötet.', },
  },
  [14028] = {
    'Moosbeerenchutney',
    {'Wenn Ihr bislang noch nie Moosbeerenchutney versucht habt, dann entgeht Euch etwas! Es wird aus den frischesten, schmackhaftesten Moosbeeren des ganzen Sumpflands zubereitet. Ersteht einfach welche vom nächsten Händler des Pilgerfreudenfests, wenn Ihr Euch an der Zubereitung versuchen wollt.|n|nDas Rezept findet Ihr in Eurem Pilgerfreudenfest-Kochbuch.|n|nWenn Ihr nicht in Eile seid, würdet Ihr vielleicht etwas Chutney zubereiten und zu Jasper Moore bringen, außerhalb Sturmwinds? Ich habe ihm versprochen, es gegen den Kuchen einzutauschen, den Ihr mir gebracht habt.', },
    {'Bereitet 5 Portionen Moosbeerenchutney zu und bringt sie zu Jasper Moore an die Festtafel außerhalb Sturmwinds.', },
  },
  [14029] = {
    'Brechen der Belagerung',
    nil,
    nil,
  },
  [14030] = {
    'Darnassus darbt',
    {'Vielen Dank für das Moosbeerenchutney. Es gibt so viel zuzubereiten, ich kann kaum noch einen klaren Gedanken fassen! Und zu all dem kommt nun noch, dass Isaac Allerton in Darnassus mittlerweile praktisch alle Zutaten ausgegangen sind! Ich kann wohl kaum erwarten, dass Ihr so gut wäret, einzuspringen und etwas mehr Gewürzbrotfüllung und Kürbiskuchen zuzubereiten, oder? Der Händler sollte alle Zutaten parat haben, die Ihr benötigen würdet.|n|nIhr könnt ihn in der Nähe der Festtafel finden, auf der Wiese hinter der Terrasse der Krieger in Darnassus.', },
    {'Bringt 5 Portionen Gewürzbrotfüllung und 5 Kürbiskuchen zu Isaac Allerton in der Nähe des Eingangs nach Darnassus.', },
  },
  [14031] = {
    'Erfasst das Unbekannte',
    {'Hey, $N, da sind Höhlenmalereien und andere Artefakte überall in der Höhle.|n|nKönntet Ihr Eure am Gürtel befestigte HGK Schnappblitz verwenden, um an den markierten Orten Bilder aufzunehmen? Nehmt im hinteren Teil der Höhle ein Bild des Altars auf.|n|nIch bin sicher, Sassy würde diese Informationen gern in die Hände bekommen.', },
    {'Verwendet Eure HGK Schnappblitz, um Bilder an den springenden Kameras der drei Höhlenmalereien und dem Altar der Pygmäen aufzunehmen.', },
  },
  [14032] = {
    'Säuberung im Koboldlager',
    {'Eure erste Aufgabe ist eine Säuberung, $N. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.', },
    {'Tötet 6 von dem Koboldgezücht und kehrt dann zu Marschall McBride zurück.', },
  },
  [14033] = {
    'Kandierte Süßkartoffeln',
    {'Solange Ihr hier seid, solltet Ihr Euch einen Vorrat an Süßkartoffeln von Teldrassil zulegen. Aus ihnen werden die köstlichsten kandierten Süßkartoffeln zubereitet, die Ihr je schmecken werdet!|n|nWenn Ihr mir nicht glaubt, sucht das Rezept aus Eurem Pilgerfreudenfest-Kochbuch heraus und probiert es mal! Und solltet Ihr welche übrig haben, könntet Ihr sie mit Gregory Tabor in der Nähe der Festtafel außerhalb Sturmwinds teilen. Er liebt diese Kartöffelchen! Aber wenn man ihm so zuhört, gewinnt man den Eindruck, er liebt alles, was man essen kann.', },
    {'Bereitet 5 Portionen kandierte Süßkartoffeln zu und bringt sie zu Gregory Tabor außerhalb der Tore Sturmwinds.', },
  },
  [14034] = {
    'Foote, der Mann mit dem Plan',
    {'Wir haben von den Spannungen zwischen der Allianz und der Horde profitiert, bis Konteradmiral Hartley in MEINEM Hafen angelegt hat und angefangen hat, seine Nase in meine Angelegenheiten zu stecken. Er hat Schiffe gejagt und beschlagnahmt, die unter der Flagge der Horde gesegelt sind, mit dem Ziel, sie davon abzuhalten, einen neutralen Hafen anzulaufen.|n|nIch werde sicher keinem wurstfingrigen Menschen erlauben, meinen Profit zu schmälern! Besorgt mir die Pläne des Flaggschiffs. Hartleys Chefingenieur pichelt sich in der Taverne zum geborstenen Kiel einen an, einfach den Hügel hinauf...', },
    {'Besorgt die Schiffsschemata von Chefingenieur Foote in der Taverne \'Zum geborstenen Kiel\' in Ratschet.', },
  },
  [14035] = {
    'Langsam gerösteter Truthahn',
    {'Jedes Pilgerfreudenfestmahl benötigt einen Mittelpunkt der Tafel, und damit meine ich kein dekoratives Füllhorn. Nein, die wahre Krönung der Tafel ist ein schmackhafter gerösteter Truthahn.|n|nIhr findet ein fabelhaftes Rezept dafür in Eurem Pilgerfreudenfest-Kochbuch. Warum erlegt Ihr nicht ein paar wilde Truthähne und bereitet sie selbst zu? Diese Tierchen sind überall im Wald von Elwynn unterwegs, Ihr solltet sie leicht aufspüren können.|n|nKönnt Ihr sie zu Isaac Allerton an die Tore von Darnassus bringen, sobald sie fertig zubereitet sind?', },
    {'Bereitet 5 langsam geröstete Truthähne zu und bringt sie zu Isaac Allerton, in der Nähe der Tore von Darnassus.', },
  },
  [14036] = {
    'Pilgerfreuden',
    {'Seid Ihr hier, um mit uns das Pilgerfreudenfest zu feiern? Dies war einst eine Zeit der Einkehr und des Gedenkens an getane Reisen und das Glück, ein gutes Mahl mit Freunden teilen zu können. Noch heute feiern viele das Fest.|n|nIhr könnt an Pilgerfreudenfeierlichkeiten in der Nähe größerer Städte teilnehmen, indem Ihr an einer der Festtafeln Platz nehmt und das dort vorhandene Essen verteilt.|n|nWenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, wendet Euch an Miles Standish im Innenhof über Unterstadt.', },
    {'Sprecht mit Miles Standish im Innenhof über Unterstadt.', },
  },
  [14037] = {
    'Gewürzbrotfüllung',
    {'Unsere Gewürzbrotfüllung ist das A und O der Pilgerfreudentafel. Das Rezept stammt aus besseren Tagen in Lordaeron und hat nun seinen Platz unter den traditionellen Gerichten gefunden.|n|nSeid Ihr bereits in der Kochkunst bewandert, stattet dem Händler des Pilgerfreudenfests einen Besuch ab und Ihr erhaltet Euer eigenes Exemplar des Pilgerfreundenfest-Kochbuchs und alle hiesigen Zutaten, die Ihr benötigt, um ein Festmahl zuzubereiten. Seid Ihr noch unerfahren in der Kunst des Kochens, so ist dies die beste Gelegenheit für Euch, zu beginnen!|n|nSobald Ihr die Füllung zubereitet habt, übergebt sie William Mullins in der Nähe der Festtafel.', },
    {'Bereitet 5 Portionen der Gewürzbrotfüllung zu und bringt sie dann zu William Mullins an die Festtafel im Innenhof über Unterstadt.', },
  },
  [14038] = {
    'Minenarbeit',
    nil,
    {'Setzt eine Haftmine an den dünnsten Teil des Rumpfs der Kriegsmächtigen.', },
  },
  [14039] = {
    'Die Heimat der Kaldorei',
    {'Es war zweifellos eine große Ehre, Euch kennengelernt zu haben. Ihr seid der lebende Beweis dafür, wie nobel Euer Volk ist.|n|nGeht jetzt und beendet diese letzte Aufgabe. Bringt das Wasser zu Tyrande Wisperwind in Darnassus.', },
    {'Bringt das gefüllte Gefäß zu Tyrande Wisperwind in Darnassus.', },
  },
  [14040] = {
    'Kürbiskuchen',
    {'Eure Gewürzbrotfüllung ist einfach wunderbar, aber uns fehlt noch der ein oder andere Kürbiskuchen zum Glück. Ein weiteres traditionelles Gericht der Region, denn hierzu werden reife Tirisfalkürbisse verwendet, die nirgends sonst gedeihen. |n|nFalls Ihr nicht wisst, wie man sie zubereitet, findet Ihr das Rezept in Eurem Pilgerfreudenfest-Kochbuch.|n|nMacht es Euch etwas aus, uns ein paar zuzubereiten und sie Francis Eaton außerhalb von Orgrimmar zu bringen? Ich bin sicher, es sind nicht mehr viele übrig.', },
    {'Bereitet 5 Stücke Kürbiskuchen zu und bringt sie zu Francis Eaton an die Festtafel außerhalb von Orgrimmar.', },
  },
  [14041] = {
    'Moosbeerenchutney',
    {'Habt Ihr einmal das Moosbeerenchutney versucht? Es wird aus frischen, schmackhaften säuerlichen Moosbeeren vom Südstrom zubereitet. Besorgt Euch einfach welche vom Händler des Pilgerfreudenfests, wenn Ihr Euch mal am Rezept versuchen wollt.|n|nIhr findet es in Eurem Pilgerfreudenfest-Kochbuch.|n|nWenn Ihr nicht zu viel zu tun habt, könntet Ihr vielleicht etwas Chutney zubereiten und es zu Dokin Grasland am Fuße des Aufzugs bringen, westlich von Donnerfels?', },
    {'Bereitet 5 Portionen Moosbeerenchutney zu und bringt sie zu Dokin Grasland am Fuße des Aufzugs westlich von Donnerfels.', },
  },
  [14042] = {
    'Kabummition',
    {'Hartley muss all seine Sprengmittel am Strand entladen haben. Ziehen wir ihm diesen Zahn, $N!|n|nGeht den Strand entlang und sucht nach seinen Sprengstoffvorräten. Zündet sie an und er sitzt ohne Bewaffnung an Land fest, während die Kriegsmächtige repariert wird.|n|nIch treffe Euch wieder hier in Ratschet.', },
    {'Zerstört 5 Munitions-Vorratslager von Theramore an der Küste.', },
  },
  [14043] = {
    'Kandierte Süßkartoffeln',
    {'Da Ihr schon mal hier seid, solltet Ihr gleich Euren Vorrat an Süßkartoffeln aus Mulgore aufstocken. Sie werden für die Zubereitung kandierter Süßkartoffeln verwendet, mein absoluter Favorit auf der Festtafel.|n|nWenn Ihr meinem Urteil nicht traut, sucht Euch das Rezept heraus und probiert es einmal! Solltet Ihr unterwegs nach Orgrimmar sein, könnt Ihr sie gleich zu Francis Eaton in der Nähe der Festtafel direkt außerhalb der Stadt bringen. Ich bemühe mich, ihn ausreichend zu versorgen, aber dort geht immer alles so schnell weg!', },
    {'Bereitet 5 Portionen kandierte Süßkartoffeln zu und bringt sie zu Francis Eaton außerhalb der Tore Orgrimmars.', },
  },
  [14044] = {
    'Unterstadt ist unterversorgt',
    {'Vielen Dank für die kandierten Süßkartoffeln. Es gibt so viel zu kochen, ich komme kaum hinterher! Und jetzt schickt mir Miles auch noch eine Nachricht, dass ihm Gewürzbrotfüllung und Moosbeerenchutney ausgehen! Ihr hättet nicht zufällig Zeit, mir damit noch etwas unter die Arme zu greifen und ein wenig mehr von beidem zu kochen? Der Händler sollte alle nötigen Zutaten vorrätig haben.|n|nIhr könnt Miles Standish in der Nähe der Festtafel finden, im Innenhof in den Ruinen über Unterstadt.', },
    {'Bringt 5 Portionen Gewürzbrotfüllung und 5 Portionen Moosbeerenchutney zu Miles Standish in der Nähe des Eingangs von Unterstadt.', },
  },
  [14045] = {
    'Findet Baron Küstenschipper',
    {'Der ruchlose Pirat Baron Küstenschipper war der Schrecken dieser Meere, bevor die Allianz seine Flotte zerstört hat und die Überlebenden gefangen genommen hat. Gefällt mir das? Sehe ich aus, als ob ich vor Freude hüpfe und springe, $N?|n|nKüstenschipper hat einige meiner wertvollsten Ladungen vor seiner Gefangennahme geraubt. Man sagt, er habe sie vergraben, bevor er gefangen genommen wurde. Ich will meine Waren wieder zurück haben! Findet Küstenschipper im Lager der Allianz südlich von hier und versucht, ihm zu entlocken, wo mein Schatz ist.', },
    {'Findet den berüchtigten Piraten Baron Küstenschipper und sprecht mit ihm.', },
  },
  [14046] = {
    'Ein ehemaliger Baron',
    {'Ich werd\' sicher am Galgen landen, Kamerad. Jetzt nützt mir der Schatz nur noch herzlich wenig...|n|nEs sei denn, ich kann mir damit mein Leben erkaufen. Ich schlag Euch\'n Geschäft vor, <Volk>. Befreit mich von diesen Handschellen und ich sage Euch, wo der Schatz verbuddelt ist.|n|nUnd auf mein Wort ist Verlass. Ich war mal ein richtiger Baron, müsst Ihr wiss\'n.', },
    {'Wenn Ihr ihm traut, sprecht mit Baron Küstenschipper, um ihn von seinen Handschellen zu befreien.', },
  },
  [14047] = {
    'Langsam gerösteter Truthahn',
    {'Zu jedem Pilgerfreudenfestmahl gehört ein kulinarischer Höhepunkt - für uns ist das ein langsam gerösteter Truthahn. Es gibt nichts besseres, um ein reichhaltiges Mahl angemessen zu krönen!|n|nIhr findet ein gutes Rezept dafür in Eurem Pilgerfreudenfest-Kochbuch. Warum jagt Ihr nicht ein paar Truthähne und bereitet sie dann zu? Sie sind überall in Tirisfal zu finden.|n|nWenn sie fertig sind, könntet Ihr sie dann zu Francis Eaton außerhalb von Orgrimmar bringen?', },
    {'Bereitet 5 langsam geröstete Truthähne zu und bringt sie zu Francis Eaton, in der Nähe der Tore von Orgrimmar.', },
  },
  [14048] = {
    'Ich krieg einfach nicht genug… Truthahn',
    {'Ich hab schon vor den Feiertagen angefangen zu kochen und seitdem nicht mehr aufgehört! Und es ist trotzdem nie genug - könnte ich Euch vielleicht überreden, mir zur Hand zu gehen?|n|nTruthahn bekommt man hier schwer, wenn Ihr mir also ein paar langsam geröstete Truthähne bringen könntet, wäre das eine enorme Hilfe. Möchtet Ihr ihn selbst zubereiten, könnt Ihr die Truthähne überall im Wald von Elwynn selbst erjagen. Alle weiteren Zutaten erhaltet Ihr bei jedem Händler des Pilgerfreudenfests.', },
    {'Bringt 20 langsam geröstete Truthähne zu Caitrin Eisenkessel außerhalb von Eisenschmiede.', },
  },
  [14049] = {
    'Eine äußerst ungewöhnliche Karte',
    {'Also, es ist so, Kamerad: Um meine Schatzkarte zu beschützen, habe ich sie auf die Kopfhaut meines ersten Steuermanns tätowiert.|n|nNatürlich ist er bereits genauso tot wie der Großteil vom Rest meiner Mannschaft. Die Mitglieder der Allianz wissen nicht einmal, was sie da in Händen halten. Sein abgeschlagener Kopf hängt an einem Baum am Eingang zu diesem Lager.|n|nSchnappt Euch den Kopf und bringt ihn zu Gazlowe in Ratschet.', },
    {'Besorgt Euch den tätowierten Piratenkopf vom Eingang des Geländes der Allianz.', },
  },
  [14050] = {
    'Gazlowes Vermögen',
    {'Verteufelt noch eins, Ihr hattet recht! Auf die Kopfhaut ist eine Karte tätowiert.|n|nDieser verfluchte Baron! Er hat meinen Schatz direkt unter meiner Nase vergraben. Oder über meinem Kopf. Diese Karte deutet auf einen Ort an den Steilufern über Ratschet im Süden.|n|nFolgt der Straße nach Westen aus der Stadt, begebt Euch auf den Hügel, geht nach Süden, dann lauft zurück zur Küste und sucht nach dem riesigen Baum, von dem aus man die Bucht überblickt. Schnappt Euch meinen Schatz und ich werde ihn mit Euch teilen!', },
    {'Gazlowe will, dass Ihr seinen verscharrten Schatz an den Klippen mit Meerblick ausgrabt.', },
  },
  [14051] = {
    'Die Füllung ist alles!',
    {'Dafür zu sorgen, dass die Festtafeln gefüllt bleiben, ist kein Kinderspiel! Ich muss das Moosbeerenchutney zubereiten, die Süßkartoffeln im Auge behalten und gleichzeitig auch noch dafür sorgen, dass der Kürbiskuchen nicht anbrennt.|n|nIch glaube, ich habe alles soweit im Griff. Moment, ich habe doch irgendwas vergessen ... Oh nein, die Füllung! Jetzt bleibt mir keine Zeit mehr dafür, bevor ich nicht mit dem Rest fertig bin. Äh, vielleicht könntet Ihr mir da aushelfen? Es sollte nicht allzu lang dauern, etwas Gewürzbrotfüllung zu kaufen oder selbst zuzubereiten, die Zutaten könnt Ihr direkt hier besorgen.', },
    {'Bringt 20 Portionen Gewürzbrotfüllung zu Caitrin Eisenkessel nahe der Festtafel außerhalb von Eisenschmiede.', },
  },
  [14052] = {
    'Unter vier Augen mit Tony',
    {'Die Situation mit den Piraten behindert meine Unternehmungen erheblich. Käpt\'n Garvey greift jedes Schiff an, das er erblickt - sogar diejenigen, von deren Besitzern ich mir ein \'Schutz\'-Geld erschwindelt habe. Wir müssen diese Piraten auf frischer Tat ertappen und zwar bald!|n|nIch kenne genau den richtigen Gesellen, ein Leutnant von Garvey, der sich auf die Kungeleien vom alten Flunkerblick einlässt. Er hat mir angeboten, für mich eine kleine \'Meuterei\' anzuzetteln. Sobald diese Jungs für uns arbeiten, ist das ein Kinderspiel, nicht wahr?|n|nSprecht mit Tony Zweihauer auf Prügeleiland im Süden.', },
    {'Sprecht mit Tony Zweihauer auf Prügeleiland im Nördlichen Brachland.', },
  },
  [14053] = {
    'Schon wieder kein Moosbeerenchutney mehr?',
    {'Mein Mann Jasper wollte eigentlich noch mehr Moosbeerenchutney zubereiten, aber wie es scheint, hat er schon genug mit den kandierten Süßkartoffeln für all die Gäste zu tun. Würdet ihr vielleicht aushelfen? Wenn Ihr in der Kochkunst bewandert seid, braucht Ihr nur die säuerlichen Sumpfmoosbeeren, die Ihr beim Händler des Pilgerfreudenfests außerhalb von Eisenschmiede bekommen könnt.|n|nFalls Euch nicht nach Kochen ist, könnt Ihr auch jederzeit jemand anderen um die Zubereitung des Chutneys bitten.', },
    {'Bringt 20 Portionen Moosbeerenchutney zu Ellen Moore an die Festtafel außerhalb Sturmwinds.', },
  },
  [14054] = {
    'Kuchen versuchen',
    {'Isaac arbeitet hart, um den Feiernden die traditionellen Ursprünge des Pilgerfreudenfests und die Zubereitung aus all den geernteten Zutaten in dieser Jahreszeit näher zu bringen. Ich bemühe mich, die Festtafeln schön gefüllt zu halten, aber Isaacs Leibspeise geht langsam zur Neige - Kürbiskuchen!|n|nKönntet Ihr welchen für uns organisieren? Wenn Ihr ihn selbst zubereiten wollt, benötigt Ihr reife Elwynnkürbisse vom Händler des Pilgerfreudenfests außerhalb Sturmwinds.', },
    {'Bringt 20 Kürbiskuchen zu Mary Allerton an die Festtafel vor den Toren von Darnassus.', },
  },
  [14055] = {
    'Rein in die Kartoffeln, raus aus den Kartoffeln',
    {'Meine Frau Ellen hat mich damit beauftragt, für gedeckte Tafeln zu sorgen, doch sie ändert ständig ihre Meinung. Zuerst sollte ich Kürbiskuchen zubereiten, nun sind es plötzlich kandierte Süßkartoffeln.|n|nIch habe aber schon mit dem Kuchen angefangen! Vielleicht könntet Ihr mir ja mit den Süßkartoffeln aushelfen? Sie wird sicher angenehm überrascht sein, wenn wir alle ihre Wünsche erfüllen.|n|nSolltet Ihr die Süßkartoffeln selbst kandieren wollen, müsst Ihr sie beim Händler des Pilgerfreudenfests in Darnassus erstehen. Ich danke Euch, $N.', },
    {'Bringt 20 kandierte Süßkartoffeln zu Jasper Moore an die Festtafel außerhalb von Sturmwind.', },
  },
  [14056] = {
    'Glomp sitzt darauf',
    {'Was? Glaubt Flunkerblick etwa, dass eine Meuterei so einfach und so billig ist?|n|nEgal, Mann, das wird schon hinhauen. Zunächst brauchen wir Geld. Käpt\'n Garvey hortet gerne die Schätze, die wir erbeutet haben. Mit diesem Geld könnten wir meine handverlesenen Meuterer bezahlen.|n|nDer Schatz befindet sich direkt vor den Baracken hier. Ihr müsst Euch um Käpt\'n Garveys \'Schatzmeister\' kümmern. Allerdings lässt sich Glomp nicht so einfach herumschubsen. Glaubt mir, ich habe schon mal geschubst, und... Sagen wir, den haut nichts so schnell um.', },
    {'Tötet Glomp und schnappt Euch Glomps Beute.', },
  },
  [14057] = {
    'Gewehre. Wir brauchen Gewehre.',
    {'Für jede gute Meuterei braucht man ordentlich Feuerkraft. Käpt\'n Garvey beansprucht die besten Schusswaffen für sich: eine ganze Ladung schwerer, zwergischer Steinschlossbüchsen. Er lagert sie bei sich im anderen Gebäude auf der anderen Seite der Insel. Bringt mir sechs dieser Büchsen und ich gebe sie an meine zukünftigen Offiziere weiter...', },
    {'Besorgt 6 schwere, zwergische Gewehre.', },
  },
  [14058] = {
    'Rein in die Kartoffeln, raus aus den Kartoffeln',
    {'Roberta Carter hat mich beauftragt, eines der Festtagsgerichte zuzubereiten. Kandierte Süßkartoffeln! Normalerweise würde ich mich darum reißen, aber ich habe der Gastgeberin versprochen, mit ihr auf die Tafeln zu achten.|n|nEs wäre eine große Hilfe, wenn Ihr stattdessen für mich einige kandierte Süßkartoffeln organisieren könntet! Roberta würde mir nie vergeben, wenn ich sie im Stich lasse. |n|nWenn Ihr die Süßkartoffeln selbst kandieren wollt, müsst Ihr zunächst welche vom Händler des Pilgerfreudenfests in Donnerfels erstehen. Ich danke Euch für Eure Hilfe, $N!', },
    {'Bringt 20 kandierte Süßkartoffeln zu William Mullins an die Festtafel oberhalb von Unterstadt.', },
  },
  [14059] = {
    'Schon wieder kein Moosbeerenchutney mehr?',
    {'Ich wünschte, ich wüsste, warum das Moosbeerenchutney immer so schnell alle ist. Manchmal habe ich das Gefühl, sie verfüttern es heimlich an die Monstrositäten, wenn gerade keiner hinschaut. Würdet Ihr uns helfen, für Nachschub zu sorgen? Wenn Ihr in der Kochkunst bewandert seid, könnt Ihr die benötigten säuerlichen Moosbeeren vom Südstrom vom Händler des Pilgerfreudenfests außerhalb von Orgrimmar bekommen.|n|nSteht Euch nicht der Sinn nach Kochen, könnt Ihr auch jederzeit jemand anderen darum bitten.', },
    {'Bringt 20 Portionen Moosbeerenchutney zu Roberta Carter an die Festtafel in den Innenhof oberhalb von Unterstadt.', },
  },
  [14060] = {
    'Kuchen versuchen',
    {'Dokin und Laha bemühen sich, den Feiernden die Hintergründe des Fests und die Zubereitung der traditionellen Gerichte aus all den frisch geernteten Zutaten nahe zu bringen. Ich versuche, die Tische mit so viel Essen wie nur möglich gefüllt zu halten, aber uns geht langsam der Kürbiskuchen aus.|n|nWürdet Ihr vielleicht welchen für uns besorgen? Wenn Ihr ihn selbst zubereiten wollt, benötigt Ihr dafür reife Tirisfalkürbisse, die Ihr beim Händler des Pilgerfreudenfests oberhalb von Unterstadt bekommen könnt.', },
    {'Bringt 20 Kürbiskuchen zu Mahara Goldweizen nahe der Festtafel außerhalb von Donnerfels.', },
  },
  [14061] = {
    'Ich krieg einfach nicht genug… Truthahn',
    {'Ich hab schon vor den Feiertagen angefangen zu kochen und seitdem nicht mehr aufgehört! Und es ist trotzdem nie genug - könnte ich Euch vielleicht überreden, mir zur Hand zu gehen?|n|nTruthahn bekommt man hier schwer, wenn Ihr mir also ein paar langsam geröstete Truthähne bringen könntet, wäre das eine enorme Hilfe. Möchtet Ihr ihn selbst zubereiten, könnt Ihr die Truthähne überall in Tirisfal selbst erjagen. Alle weiteren Zutaten erhaltet Ihr bei jedem Händler des Pilgerfreudenfests.', },
    {'Bringt 20 langsam geröstete Truthähne zu Ondani Mühlenrad außerhalb von Orgrimmar.', },
  },
  [14062] = {
    'Die Füllung ist alles!',
    {'Dafür zu sorgen, dass die Festtafeln gefüllt bleiben, ist kein Kinderspiel! Ich muss das Moosbeerenchutney zubereiten, die Süßkartoffeln im Auge behalten und gleichzeitig auch noch dafür sorgen, dass der Kürbiskuchen nicht anbrennt.|n|nIch glaube, ich habe alles soweit im Griff. Moment, ich habe doch irgendwas vergessen ... Oh nein, die Füllung! Jetzt bleibt mir keine Zeit mehr dafür, bevor ich nicht mit dem Rest fertig bin. Äh, vielleicht könntet Ihr mir da aushelfen? Es sollte nicht allzu lang dauern, etwas Gewürzbrotfüllung zu kaufen oder selbst zuzubereiten, die Zutaten könnt Ihr direkt hier besorgen.', },
    {'Bringt 20 Portionen Gewürzbrotfüllung zu Ondani Mühlenrad an die Festtafel außerhalb von Orgrimmar.', },
  },
  [14063] = {
    'Meuterei, Mann!',
    {'Nun zum schönsten Teil einer Meuterei: dem Abmurksen! Piraten interessieren sich nicht so sehr für die Frage, wer das Sagen haben soll, sondern es geht ihnen nur darum, wer das Schiff beherrscht. Im Ostende dieser Insel liegt die \'Dolch der Maid\', das alte Flaggschiff von Käpt\'n Garvey. Er hat die Aufsicht dem Offizier überlassen, dem er am meisten vertraut: Alicia Cuthbert. Sobald wir sie erledigt haben, gehört das Schiff uns – und damit auch das Meer.|n|nIch gebe meinen Männern den Befehl, in die Boote zu steigen. Ihr müsst an Bord der \'Dolch\' gehen und an Deck in dieses Horn tuten. Das wird unser Signal sein, das Schiff zu kapern. Jippieh!', },
    {'Verwendet das Signalhorn der Piraten, um Tony Zweihauer und seine Mannschaft an Bord der \'Dolch der Maid\' zu rufen. Helft ihm, Alicia Cuthbert unter Deck zu besiegen.', },
  },
  [14064] = {
    'Teilen an der Festtafel',
    {'Ihr habt nicht wirklich die Pilgerfreuden genossen, wenn Ihr Euch nicht ordentlich an einem der reich gedeckten Tische den Bauch vollgeschlagen habt.|n|nBitte, setzt Euch doch und speist, so viel Ihr nur könnt! Ihr könnt selbst von Stuhl zu Stuhl rücken, oder andere darum bitten, Euch einige der Speisen weiterzureichen.|n|nSobald Ihr genug von jedem Gericht verspeist habt, kommt Ihr zu der Erkenntnis: Teilen macht Freude!', },
    {'Verspeist fünf Portionen jedes Gerichts an einem reich gedeckten Tisch, bis Ihr zu der Erkenntnis kommt: Teilen macht Freude.', },
  },
  [14065] = {
    'Teilen an der Festtafel',
    {'Ihr habt nicht wirklich die Pilgerfreuden genossen, wenn Ihr Euch nicht ordentlich an einem der reich gedeckten Tische den Bauch vollgeschlagen habt.|n|nBitte, setzt Euch doch und speist, so viel Ihr nur könnt! Ihr könnt selbst von Stuhl zu Stuhl rücken, oder andere darum bitten, Euch einige der Speisen weiterzureichen.|n|nSobald Ihr genug von jedem Gericht verspeist habt, kommt Ihr zu der Erkenntnis: Teilen macht Freude!', },
    {'Verspeist fünf Portionen jedes Gerichts an einem reich gedeckten Tisch, bis Ihr zu der Erkenntnis kommt: Teilen macht Freude.', },
  },
  [14066] = {
    'Untersuchung des Wracks',
    {'Vor nicht allzu langer Zeit wurde eine Ladung Silber auf dem Weg von hier zum Wegekreuz gestohlen. Es war als Bezahlung für die Wachen gedacht und wir wollen das Silber zurück haben.|n|nIch habe mich nach Hinweisen umgehört, aber ich will, dass Ihr den Tatort untersucht. Begebt Euch nach Westen und sucht nach einem verunglückten Wagen einer Karawane an der Straße von hier Richtung Norden auf dem Weg zum Wegekreuz. Findet heraus, wer das Silber an sich genommen hat und holt es Euch zurück!', },
    {'Findet den verunglückten Wagen in der Nähe der Straße zwischen Ratschet und dem Wegekreuz, und sucht das Gebiet nach Spuren und Hinweisen ab.', },
  },
  [14067] = {
    'Das gestohlene Silber',
    {'Offensichtlich haben diese Raptoren alleine gehandelt, als sie das Silber der Horde raubten.|n|nEs wird Zeit, diesen Bestien eine Lektion zu erteilen.', },
    {'Tötet 8 Felshetzer und 4 Sensenklauen der Sonnenschuppen und findet das gestohlene Silber.', },
  },
  [14068] = {
    'Waptorfalle',
    {'Waptoren zu fangen, ist ganz schön schwiewig, aber ich habe eine neue Waptorfalle entwickelt, die den Gwoßteil der Wisiken ausschaltet.|n|nStellt die Falle auf dem Boden auf und sie quietscht wie ein Waptor und lockt so einen andewen in die Falle.|n|nWenn ein Waptor in meine Waptorfalle twitt, schwumpft sie ihn zusammen, sodass er nicht mehr so gefährlich ist. Es ist schwecklich einfach! Ich würde es selbst machen, aber ich bin neulich König Schnitterklaue begegnet.', },
    {'Verwendet Kala\'mas "Waptorfalle", um 5 kleine Waptoren zu fangen.', },
  },
  [14069] = {
    'Gutes Personal ist schwer zu finden',
    {'Ich habe versagt! Ich habe alles versucht, um unser Kaja\'Cola-Soll zu erreichen, aber Ihr wisst doch, wie das mit den Trollsklaven heutzutage ist. Gutes Personal ist schwer zu finden!|n|nIch glaube, Ihr müsst hier selbst Hand anlegen. Ein kleiner Stromschlag mit der Batterie Eures goblinischen Alles-in-1-zigartigen Gürtels sollte Wunder wirken. Wenn Ihr die Arbeitsmoral von ein paar Trollen da unten anpasst, ziehen die anderen sicher schnell nach.|n|nDie Kaja\'Cola-Produktion muss weitergehen, sonst macht uns der Handelsprinz einen Kopf kürzer!', },
    {'Verbessert die Arbeitsmoral von 8 widerspenstigen Trollen.', },
  },
  [14070] = {
    'Selbst ist der Goblin',
    {'Wir müssen gleich mehreren Schuldnern eine Nachricht zukommen lassen. Natürlich versteckt sich dieser Abschaum im Malocherviertel. Ich weiß, wie ungern Ihr in die Slums geht, $GHerr:Frau; Boss, aber was soll man schon machen?|n|n<Sassy blättert durch einen Stapel Papiere.>|n|nIch habe alle Namen hier.|n|nDarf ich vielleicht vorschlagen, dass Ihr ihnen einen "persönlichen Besuch" abstattet? Ein paar strategisch geplante Schlägereien setzen deutliche Zeichen für die anderen Schuldner UND Eure Konkurrenten.|n|n$N ist kein Goblin, mit dem man sich anlegen sollte!', },
    {'Verprügelt Bruno Flammhemmer, Frankie Gangschalter, Jack den Hammer und Sudsy Magee.', },
  },
  [14071] = {
    'Cruisen',
    {'$N, ich habe gehört, dass Ihr die Mutter aller Firmenpartys ausrichten werdet. Laut meinen Berechnungen sollte Euer Beförderungsquotient raketenhaft in die Höhe schießen und explodieren, wenn man sieht, dass Ihr auf der Party Spaß habt!|n|nDaher schlage ich vor, Ihr unternehmt eine kleine Spritztour mit dem Hot Rod und holt Eure Freunde in der Stadt ab.|n|nVergesst mich nur nicht, wenn alles am Schnürchen läuft und Ihr $Gder neue Handelsprinz:die neue Handelsprinzessin; werdet, ja?', },
    {'Fahrt mit dem Hot Rod durch die Gegend und Holt Eure Freunde, Ass, Gobber und Izzy ab.', },
  },
  [14072] = {
    'Verog aufstöbern',
    {'Regthar Totenfurt hat mich hierhergeschickt, um die Aktivitäten der Zentauren zu beobachten, aber der Anführer der Gruppe ist schwer auszumachen. Ich habe herausgefunden, dass er \'Verog der Derwisch\' heißt, aber sein Aufenthaltsort bleibt unbekannt.|n|nKönnt Ihr mir ein wenig beim Auskundschaften helfen? Man würde bei den Zentauren eigentlich keine echten \'Geheiminformationen\' erwarten, aber häufig befinden sich in ihren Lagern massenhaft wichtige Papiere. Sucht die Zelte der Zentauren um die Brackige Oase ab und bringt mir ein paar Informationen.', },
    {'Sammelt 4 Geheiminformationen der Zentauren aus der Umgebung der Brackigen Oase.', },
  },
  [14073] = {
    'Verstärkung für Totenfurt',
    {'$N! Euer Ruf für die Horde wächst. Mir sind Berichte von den Vergessenen Teichen und der Brackigen Oase zu Ohren gekommen, dass Ihr unseren Zentauren-Feinden großen Schaden zugefügt habt. Gute Arbeit, in der Tat.|n|nRegthar Totenfurt leitet die Einsätze gegen die Zentauren im gesamten Nördlichen Brachland. Er könnte jemanden wie Euch zur Unterstützung seiner Streitkräfte gut gebrauchen. Meldet Euch bei ihm in seinem Vorposten an der Straße in Richtung Westen und lasst ihm jede Hilfe zukommen, die in Eurer Macht steht.', },
    {'Meldet Euch bei Regthar Totenfurt an seinem Vorposten westlich vom Wegekreuz im Nördlichen Brachland.', },
  },
  [14074] = {
    'Legt mal ein Bein zu',
    {'Der Argentumkreuzzug hatte ein schnelles Schiff mit einer Ladung Weitschreiterfleisch und weiteren Vorräten entsendet, die für uns hier am Turnierplatz vorgesehen waren, doch nie eingetroffen sind. Späher berichteten uns von einem Angriff der Kvaldir, räuberische Vrykul, die Angst und Schrecken auf den Meeren verbreiten.|n|nSie haben die Crew erschlagen und die Ladung auf eine Insel namens Hrothgars Landestelle gebracht. Wenn Ihr Richtung Norden blickt, könnt Ihr sie schemenhaft erkennen, verborgen im Nebel. Würdet Ihr uns helfen, das Diebesgut zurückzubeschaffen? Ohne diese Weitschreiterbeine werden wir bald hungern müssen.', },
    {'Beschafft 10 gestohlene Weitschreiterbeine zurück und bringt sie zu Narasi Schneedämmerung auf dem Argentumturnierplatz.', },
  },
  [14075] = {
    'Ärger in den Minen',
    {'Wir haben schon wieder Ärger in der Kaja\'mine, Boss. Die Tunnelwürmer sind zurück und fressen wortwörtlich den gesamten Profit der Handelsgesellschaft von Kajaro auf!|n|nWir können kein Kaja\'mit abbauen, was die Produktion von Kaja\'Cola schwer beeinträchtigt!|n|nIch habe schon versucht, den Kammerjäger zu rufen, aber er hat sich mit unserer letzten Zahlung aus dem Staub gemacht.|n|nMeint Ihr, Ihr könntet selbst in die drei Minen gehen und Euch darum kümmern? Ich würde Euch ja helfen, aber ich habe noch nicht am vom Kartell vorgeschriebenen Nahkampftraining teilgenommen.', },
    {'Tötet 6 Tunnelwürmer.', },
  },
  [14076] = {
    'Frühstück der Champions',
    {'Nun, da das Kolosseum fertiggestellt ist, haben wir vom Argentumkreuzzug die Bitte erhalten, bei der Pflege der Kreaturen zu helfen, die als Gegner für die Champions dienen werden.|n|nDie riesigen Jormungar ernähren sich womöglich auf die seltsamste Art und Weise: Sie wachsen heran, indem sie die Eier ihrer eigenen Artgenossen fressen, und die besten Eier stammen von den Tiefenjormungar.|n|nNehmt diese Trommel und begebt Euch in die Fußmarschen im Zentrum der Sturmgipfel. Spielt sie anschließend in der Nähe der Schneehügel, die Ihr dort seht. Scheucht die Tiefenjormungar auf, tötet sie und sammelt ihre Eiersäcke ein.', },
    {'Beschafft Euch 4 Eiersäcke eines Jormungars und bringt sie zu Savinia Lehrensang auf dem Argentumturnierplatz.', },
  },
  [14077] = {
    'Die Barmherzigkeit des Lichts',
    {'Ich habe Beichtpatin Blondlocke aufmerksam gelauscht, und ich sage Euch, ihre Worte gaben mir zu denken. Es genügt nicht, einfach nur an der Seite der Kreuzfahrer zu kämpfen, wir müssen uns ihre Mission zu Eigen machen.|n|nAn der Nordküste liegt Hrothgars Landestelle, wo die seefahrenden Kvaldir eine alte Tuskarrsiedlung überrannt und deren Bewohner getötet haben. Nehmt dieses Buch und lest den Leichen der Dorfbewohner ihre Sterbesakramente. So ermöglicht Ihr ihren Seelen, die Fesseln der Nebel um die Insel abzustreifen und ihren Frieden zu finden.', },
    {'Benutzt das Gebetsbuch der Beichtpatin, um 8 erschlagenen Tualiq-Bewohnern ihre Sterbesakramente zu lesen, und kehrt dann zu Narasi Schneedämmerung auf dem Argentumturnierplatz zurück.', },
  },
  [14078] = {
    'Abgeriegelt!',
    {'Was tut Ihr noch hier, $GBürger:Bürgerin;? Habt Ihr nicht gehört? Über die Stadt wurde eine vollständige Ausgangssperre verhängt.|n|nSprecht mit Leutnant Walden und befolgt seine Evakuierungsanweisungen.', },
    {'Findet Leutnant Walden am nordwestlichen Ende des Händlerplatzes.', },
  },
  [14079] = {
    'Reiten lernen im Wald von Elwynn',
    {'Dieser Handzettel bewirbt das bei Randal Weidmann erhältliche Reittraining und Angebote zum Erwerb von Reittieren.|n|nRandal Weidmann befindet sich im Holzfällerlager des Osttals im Wald von Elwynn, von Sturmwind aus östlich die Straße entlang.', },
    {'Bringt diesen Handzettel zu Randal Weidmann beim Holzfällerlager des Osttals im Wald von Elwynn.', },
  },
  [14080] = {
    'Einhalt den Aggressoren',
    {'Die Kvaldir, räuberische Vrykul, die überall Angst und Schrecken verbreiten, haben unsere Lieferungen abgefangen und sämtliche Tuskarrbewohner einer Insel im Norden ermordet. Sie haben die Insel bereits in Hrothgars Landestelle umbenannt. Wenn es ihnen gelingt, dort langfristig Fuß zu fassen, werden wir mit Sicherheit zu ihrem nächsten Ziel.|n|nDie Streitkräfte des Kreuzzugs haben jedoch alle Hände voll zu tun mit der Geißel, und wir müssen den Turnierplatz beschützen. Fliegt vom Platz aus Richtung Norden, bis Ihr die Insel erreicht und nehmt Euch der Kvaldir an, bevor sie noch mehr zerstören können!', },
    {'Narasi Schneedämmerung auf dem Argentumturnierplatz möchte, dass Ihr 10 Kvaldir tötet.', },
  },
  [14081] = {
    'Reiten lernen im Immersangwald',
    {'Dieser Handzettel bewirbt das bei Perascamin erhältliche Reittraining und Angebote zum Erwerb von Reittieren.|n|nPerascamin befindet sich bei Thurons Aufzucht, südöstlich des Hirtentors außerhalb von Silbermond.', },
    {'Bringt diesen Handzettel zu Perascamin bei Turons Aufzucht in Silbermond.', },
  },
  [14082] = {
    'Reiten lernen in der Exodar',
    {'Dieser Handzettel bewirbt das bei Aalun erhältliche Reittraining und Angebote zum Erwerb von Reittieren.|n|nAalun befindet sich am Eingang zur Exodar auf der Azurmythosinsel.', },
    {'Bringt diesen Handzettel zu Aalun außerhalb der Exodar auf der Azurmythosinsel.', },
  },
  [14083] = {
    'Reiten lernen in Dun Morogh',
    {'Dieser Handzettel bewirbt das bei Ultham Eisenhorn erhältliche Reittraining und Angebote zum Erwerb von Reittieren.|n|nUltham Eisenhorn befindet sich im Gehöft Bernruh in Dun Morogh, von Eisenschmiede aus östlich die Straße entlang.', },
    {'Bringt diesen Handzettel zu Ultham Eisenhorn beim Gehöft Bernruh in Dun Morogh.', },
  },
  [14084] = {
    'Reiten lernen in Dun Morogh',
    {'Dieser Handzettel bewirbt das bei Binjy Federpfiff erhältliche Reittraining und Angebote zum Erwerb von Reittieren.|n|nBinjy Federpfiff befindet sich bei Stahlrosts Depot, direkt nordöstlich von Kharanos in Dun Morogh.', },
    {'Bringt diesen Handzettel zu Binjy Federpfiff bei Stahlrosts Depot in Dun Morogh.', },
  },
  [14085] = {
    'Reiten lernen in Darnassus',
    {'Dieser Handzettel bewirbt das bei Jartsam erhältliche Reittraining und Angebote zum Erwerb von Reittieren.|n|nJartsam befindet sich in der Enklave des Cenarius in Darnassus.', },
    {'Bringt diesen Handzettel zu Jartsam bei der Enklave des Cenarius in Darnassus.', },
  },
  [14086] = {
    'Reiten lernen in Orgrimmar',
    {'Dieser Handzettel bewirbt das bei Kildar erhältliche Reittraining und Angebote zum Erwerb von Reittieren.|n|nKildar befindet sich im Tal der Ehre in Orgrimmar.', },
    {'Bringt diesen Handzettel zu Kildar im Tal der Ehre in Orgrimmar.', },
  },
  [14087] = {
    'Reiten lernen in Mulgore',
    {'Dieser Handzettel bewirbt das bei Kar Sturmsang erhältliche Reittraining und Angebote zum Erwerb von Reittieren.|n|nKar Sturmsang befindet sich im Dorf der Bluthufe in Mulgore.', },
    {'Bringt diesen Handzettel zu Kar Sturmsang beim Dorf der Bluthufe in Mulgore.', },
  },
  [14088] = {
    'Reiten lernen in Durotar',
    {'Dieser Handzettel bewirbt das bei Xar\'Ti erhältliche Reittraining und Angebote zum Erwerb von Reittieren.|n|nXar\'Ti befindet sich in Sen\'jin in Durotar.', },
    {'Bringt diesen Handzettel zu Xar\'Ti in Sen\'jin im südlichen Durotar.', },
  },
  [14089] = {
    'Reiten lernen in Tirisfal',
    {'Dieser Handzettel bewirbt das bei Velma Warnam erhältliche Reittraining und Angebote zum Erwerb von Reittieren.|n|nVelma Warnam befindet sich in Brill in Tirisfal.', },
    {'Bringt diesen Handzettel zu Velma Warnam in Brill in Tirisfal.', },
  },
  [14090] = {
    'Gormok will seine Schneebolde',
    {'Zwei meiner Männer kamen schon bei dem Versuch um, den Magnatauren namens Gormok den Pfähler einzusperren, doch die Kreatur treibt noch immer ihr Unwesen. Sie heult und jammert stundenlang darüber, dass ihr Lieblingsschneebold nicht da ist.|n|nIch würde sie mit eigenen Händen töten, wenn der Argentumkreuzzug dieses Monster nicht ins Kolosseum schicken wollte. Vielleicht ist es an der Zeit, der Bestie ihr Spielzeug zu bringen. Hier, nehmt dieses Netz und begebt Euch nach Garms Bann im Südosten der Sturmgipfel gleich nordöstlich von K3. Fangt ein paar dieser Schneebolde und betet zum Licht, dass Ihr den richtigen gefunden habt.', },
    {'Fangt mithilfe des beschwerten Netzes 8 schneeblinde Anhänger und bringt sie zu Savinia Lehrensang auf dem Argentumturnierplatz.', },
  },
  [14091] = {
    'Da stimmt was nicht',
    {'Der Leutnant scheint seinen schweren Wunden erlegen zu sein. Der Prinz wird die Neuigkeiten bestimmt hören wollen.|n|nIhr hört Kampfgeräusche, die aus der Richtung des Marktes kommen.', },
    {'Kehrt zu Prinz Liam Graumähne auf dem Händlerplatz zurück.', },
  },
  [14092] = {
    'Frühstück der Champions',
    {'Nun, da das Kolosseum fertiggestellt ist, haben wir vom Argentumkreuzzug die Bitte erhalten, bei der Pflege der Kreaturen zu helfen, die als Gegner für die Champions dienen werden.|n|nDie riesigen Jormungar ernähren sich womöglich auf die seltsamste Art und Weise: Sie wachsen heran, indem sie die Eier ihrer eigenen Artgenossen fressen, und die besten Eier stammen von den Tiefenjormungar.|n|nNehmt diese Trommel und begebt Euch in die Fußmarschen im Zentrum der Sturmgipfel. Spielt sie anschließend in der Nähe der Schneehügel, die Ihr dort seht. Ihr Ton wird die Tiefenjormungar aufscheuchen. Tötet sie, sammelt ihre Eiersäcke ein und bringt sie zurück zum Turnierplatz.', },
    {'Beschafft Euch 4 Eiersäcke eines Jormungars und bringt sie zu Tylos Dämmerflucht auf dem Argentumturnierplatz.', },
  },
  [14093] = {
    'Die Hölle bricht los',
    {'Worgen! Mein Vater hat mich gewarnt, dass die Schöpfungen des Erzmagiers Arugal irgendwann Amok laufen würden.|n|nAber woher kommen sie?|n|nVermutlich macht es keinen Unterschied. Helft uns, kurzen Prozess mit ihnen zu machen. Wir werden ihnen zeigen, aus welchem Holz die Bewohner von Gilneas geschnitzt sind.', },
    {'Prinz Liam Graumähne wünscht, dass Ihr 6 tobende Worgen tötet.', },
  },
  [14094] = {
    'Bergt die Vorräte',
    {'Hört zu, $N. Wir können nicht zulassen, dass unser Proviant zerstört wird.|n|nDa Gilneas von der Außenwelt abgeschottet ist, werden wir den Winter nicht überleben, wenn wir noch mehr von unseren Vorräten verlieren.|n|nBitte helft mir dabei, zu retten, was zu retten ist.', },
    {'Bergt 4 Vorratskisten.', },
  },
  [14095] = {
    'Die Überreste identifizieren',
    {'Ein ganzer Zahn eines toten Kraken ist in der Tat ein seltener Fund. Kreuzfahrer Silberdämmerung wird das sehen wollen.', },
    {'Bringt den Krakenzahn zum Beweis Eures Sieges zu Kreuzfahrer Silberdämmerung.', },
  },
  [14096] = {
    'Diesmal habt Ihr Euch wirklich selbst übertroffen, Kul',
    {'Kreuzfahrer Kul hat sich mal wieder in Schwierigkeiten gebracht, nur dieses Mal hat er noch andere mit hineingezogen. Als er sah, wie Kultisten in Todessprechers Wacht westlich des Turnierplatzes ihr Lager aufschlugen, rief er die Streiter für einen Angriff zusammen.|n|nOhne Verstärkung wurden Kul und seine Gefolgschaft schnell gefangen genommen. Ich habe keine Zweifel, dass der Kult die Gefangenen opfern wird - es sei denn, wir können einen Rettungseinsatz in Gang bringen. Jeder von diesen Kultisten könnte Schlüssel für die schwarzen Käfige bei sich haben. Findet die Schlüssel und befreit Kul und die gefangenen Streiter.', },
    {'Rettet Kul den Tollkühnen und 4 gefangene Streiter aus Todessprechers Wacht und kehrt dann zu Narasi Schneedämmerung auf dem Argentumturnierplatz zurück.', },
  },
  [14097] = {
    'Schafft diesen Händler hier raus!',
    nil,
    nil,
  },
  [14098] = {
    'Evakuiert den Händlerplatz',
    {'Die Zivilisten sind hier nicht mehr sicher. Nicht mal mehr in ihren Häusern.|n|nWir tun, was wir können, um die Worgen davon abzuhalten, in die Häuser zu gelangen, aber es sind einfach zu viele.|n|nHelft uns dabei, die Häuser der Zivilisten zu evakuieren. Die Armee meines Vaters im Gefängnisviertel wird sie besser schützen können.', },
    {'Evakuiert 3 Zivilistenhäuser.', },
  },
  [14099] = {
    'Königlicher Befehl',
    {'Es ist Zeit für Euch, uns zu verlassen, $N. Geht mit den anderen Zivilisten ins Militärviertel.|n|nMeldet Euch bei Gwen Armstead, wenn Ihr die Brücke im Südosten überquert... seht nach, ob es allen gut geht.|n|nIch werde mit den Wachen hierbleiben und den Rückzug der Zivilisten decken.|n|nGeht nun. Das ist ein Befehl!', },
    {'Sprecht mit Gwen Armstead im Militärviertel im Südosten.', },
  },
  [14100] = {
    'Relikt des Irdenen Rings',
    {'Ihr seid weit in Eurem Training vorangekommen, $N. Nun, da Ihr die vier grundlegenden Elemente voll und ganz beherrscht, müsst Ihr Euch darum bemühen, alle vier im Gleichgewicht zu halten. Diese Disziplin hat einen praktischen Vorteil: Mit etwas Übung könnt Ihr nur ein einziges Relikt tragen anstatt alle vier Totems.|n|nSprecht mit Gotura Vierwind im Tal der Weisheit in Orgrimmar und feilt an Eurer Beherrschung der Elemente.', },
    {'Bringt Eure vier Totems nach Orgrimmar zu Gotura Vierwind.', },
  },
  [14101] = {
    nil,
    {'Die Kvaldir, seefahrende Vrykul, die Schiffe und Küstensiedlungen überfallen, haben eine Tuskarrinsel auf der anderen Seite der Meerenge gen Norden überrannt. Ihr Anführer ist ein altgedienter Plünderer namens Drottinn Hrothgar, der die Kontrolle über diesen Teil der See erlangen möchte.|n|nMit ihm an der Macht werden unsere Lieferungen und Truppentransporte niemals sicher sein. Wir werden hier gestrandet und dem Lichkönig auf Gedeih und Verderb ausgeliefert sein.|n|nHier, bringt dieses erbeutete Kriegshorn der Kvaldir zum Tuskarrstatuenkreis im nordöstlichen Teil von Hrothgars Landestelle und verwendet es, um den Anführer der Kvaldir herauszufordern.', },
    {'Hochmeister Adelard auf dem Argentumturniergelände möchte, dass Ihr Drottinn Hrothgar besiegt.', },
  },
  [14102] = {
    'Nebelrufer Yngvar',
    {'Die Kvaldir sind zur Küste von Nordend zurückgekehrt und wenn sich niemand um sie kümmert, werden sie verhindern, dass Vorräte und Verstärkung hier ankommen. Einer von ihnen, bekannt als Nebelrufer Yngvar, hat sich in einer Höhle auf der Westseite von Hrothgars Landestelle eingenistet. Von dort aus beeinflusst er den Nebel, um die Kvaldir und deren Meeresbestien zu verbergen.|n|nHier, nehmt diesen Glücksbringer und überquert die Meerenge nördlich des Turnierplatzes in Richtung Hrothgars Landestelle. Findet die Höhle des Nebelrufers und bringt ihn mithilfe des Glücksbringers zum Vorschein.', },
    {'Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Nebelrufer Yngvar tötet.', },
  },
  [14103] = {
    'Titanstaub',
    nil,
    nil,
  },
  [14104] = {
    'Ornolf der Vernarbte',
    {'Ornolf der Vernarbte gilt als angsteinflößender Plünderer und ist unter seinen Kvaldirbrüdern bekannt dafür, Schiffe zu plündern und zu kapern. Vom Schiff Bors Zorn aus greifen seine Mannschaft und er unsere Schiffe an und stehlen unsere Ladung.|n|nOrnolf und seine Männer gehören zu denjenigen, die Mord an den Einwohnern einer Tuskarrinsel begangen haben und diese in Hrothgars Landestelle umbenannten. Sein Schiff liegt am östlichen Ende des Hafens der Insel vor Anker. Nehmt diesen erbeuteten Banner an Euch und stellt ihn auf diesem Schiff auf, um ihn zu provozieren und in den Kampf mit Euch zu locken.', },
    {'Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Ornolf den Vernarbten tötet.', },
  },
  [14105] = {
    'Todessprecher Kharos',
    {'Der Kult der Verdammten hat seine Anstrengungen verdoppelt, um unsere Vernichtung herbeizuführen. Sie sind mutig geworden und sammeln in Todessprechers Wacht auf dem Gebirgskamm westlich des Turnierplatzes ihre Kräfte.|n|nDer erbarmungslose Todessprecher Kharos hat seinen Männern befohlen, ihre Stellungen zu befestigen, um sich darauf vorzubereiten, alle Waffen des Kults einzusetzen.|n|nMeine Männer bereiten sich und die Recken darauf vor, den Platz zu verteidigen - ich möchte jedoch, dass Champions wie Ihr, $N, unsere Streitkräfte anführen, um den Angriff abzuschwächen. Findet Todessprecher Kharos und tötet ihn.', },
    {'Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Todessprecher Kharos tötet.', },
  },
  [14106] = {
    'Na Kada\'s Questtest',
    nil,
    nil,
  },
  [14107] = {
    'Das Schicksal der Gefallenen',
    {'Der Argentumkreuzzug ist wohl kaum die erste Streitmacht, die den Lichkönig herausfordert. Unser Feind hetzt die Geister der Gefallenen gegen uns auf.|n|nSie streifen im Tal der Gefallenen Helden südwestlich des Platzes zwischen Aldur\'thar und dem Eisenwallbollwerk umher. Die Gegend ist mit weggeworfenen Seelenkristallen, mit denen die Geißel die Geister kontrolliert, übersät. Sammelt diese Seelenkristalle und verwendet sie gemeinsam mit diesem lichtgesegneten Relikt, um den Geistern den Segen des Friedens zu verleihen. Sie haben ihre Ruhe mehr als verdient.', },
    {'Kreuzfahrer Silberdämmerung möchte, dass Ihr dafür sorgt, dass 6 Geister der gefallenen Helden Frieden finden.', },
  },
  [14108] = {
    'Kraken am Haken',
    {'Die Sonnenhäscher und der Silberbund haben Schiffe nach Norden entsandt, um die Kvaldir bei Hrothgars Landestelle anzugreifen, jedoch wurden sie von einem Seeräuberschiff der Kvaldir abgefangen und anschließend gefangen genommen. Was die Sache noch schlimmer macht, ist, dass die Kvaldir einen Weg gefunden haben, den gefürchteten Kraken aus den Tiefen des Nordmeeres hervorzurufen. Wenn irgendjemand an Bord da lebend herauskommen soll, muss der Kraken weggejagt und das Beschwörungsritual der Kvaldir... unterbrochen werden.|n|nHier $GKreuzfahrer:Kreuzfahrerin;, nehmt diese Speere. Ein Argentumhippogryph wird Euch in die Schlacht tragen.', },
    {'Kreuzfahrer Silberdämmerung möchte, dass Ihr auf einen Argentumhippogryph steigt, 8 flammende Speere auf den Nordmeerkraken werft und 6 Tiefenrufer der Kvaldir ausschaltet.|n|nIhr findet die Argentumhippogryphen gleich außerhalb des Zelts auf dem Argentumturnierplatz.', },
  },
  [14109] = {
    'Ein ganz neues Ihr',
    {'Ein neues Outfit? Was Ihr nicht sagt! Eure Party ist in aller Munde. Alles, was auf der Insel Rang und Namen hat, wird da sein.|n|nNun, dann wünsche ich Euch viel Spaß beim Einkaufen. In der Gaunergasse könnt Ihr die besten Schnäppchen ergattern!', },
    {'Kauft strahlende Klunker von Gappy Silberzahn, ein hippes neues Outfit von Szabo und eine coole Sonnenbrille von Missa Spekkies in der Gaunergasse.', },
  },
  [14110] = {
    'Ein ganz neues Ihr',
    {'Ein neues Outfit? Was Ihr nicht sagt! Eure Party ist in aller Munde. Alles, was auf der Insel Rang und Namen hat, wird da sein.|n|nNun, dann wünsche ich Euch viel Spaß beim Einkaufen. In der Gaunergasse könnt Ihr die besten Schnäppchen ergattern!', },
    {'Kauft strahlende Klunker von Gappy Silberzahn, ein hippes neues Outfit von Szabo und eine coole Sonnenbrille von Missa Spekkies in der Gaunergasse.', },
  },
  [14111] = {
    'Relikt des Irdenen Rings',
    {'Ihr seid weit in Eurem Training vorangekommen, $N. Nun, da Ihr die vier grundlegenden Elemente voll und ganz beherrscht, müsst Ihr Euch darum bemühen, alle vier im Gleichgewicht zu halten. Diese Disziplin hat einen praktischen Vorteil: Mit etwas Übung könnt Ihr nur ein einziges Relikt tragen anstatt alle vier Totems.|n|nSprecht mit Weitseher Eannu in der Nähe der Großen Schmiede in Eisenschmiede. Er wird Euch dabei helfen, Eure Beherrschung der Elemente zu verfeinern.', },
    {'Bringt Eure vier Totems nach Eisenschmiede zu Weitseher Eannu.', },
  },
  [14112] = {
    'Was fressen eigentlich Yetis?',
    {'Die Kreuzfahrer haben einen Yeti eingefangen, den sie Eisheuler nennen. Er soll an den Kämpfen im Kolosseum teilnehmen und man hat uns gebeten, bei Training und Unterhalt zu helfen.|n|nDie Kreuzfahrer waren nicht begeistert von meinem Vorschlag, der Bestie überschüssige Sonnenhäscher zum Fressen zu geben. Die Kreatur hat eine Vorliebe für Haifischfleisch, also will ich, dass Ihr zur Silberklinge hinunterfliegt, die in der Meerenge gen Norden schwimmt. Besorgt Euch ein wenig frischen Köder aus einem der Kübel auf dem Boot und schüttet ihn ins Wasser, um Haie damit anzulocken.', },
    {'Savinia Lehrensang auf dem Argentumturnierplatz möchte, dass Ihr ihr 3 Stück Fleisch eines Nordmeerhais bringt.', },
  },
  [14113] = {
    'Der Mittelpunkt der Party',
    {'Oh, meine Güte, Baby! Alle sind gekommen! Wen interessiert da schon irgendein blöder Drache?|n|nWir veranstalten die Party am Pool. Klingt so, als würden sich alle schon köstlich amüsieren. Du wirst so toll aussehen!|n|nWarum gehst Du nicht schon einmal rüber zum Pool und unterhältst die Leute? Ich bin in einer Minute bei Dir... Ich will nur kurz in etwas Aufregenderes schlüpfen.', },
    {'Zieht Eure großartige Partyausstattung an (Coole Sonnenbrille, Hippes neues Outfit und Strahlende Klunker). Begebt Euch danach auf die Party am Pool des Hauptgeschäftssitzes der HGK und unterhaltet 10 kezanische Feiernde.', },
  },
  [14115] = {
    'Ungeladene Piraten',
    nil,
    {'Tötet 12 ungeladene Piraten, um Eure Karriere zu retten.', },
  },
  [14116] = {
    'Der ungeladene Gast',
    {'Während Ihr Euch um die Piraten gekümmert habt, habe ich bemerkt, wie der Handelsprinz sich nach oben geschlichen hat. Er ist auf dem Balkon oben an der Treppe.|n|n$N, ich glaube, er hat die Piraten geschickt.|n|n<Sassy erschaudert.>|n|nIhr solltet lieber so schnell wie möglich nach oben gehen. Lasst ihn nicht warten!', },
    {'Sprecht mit Handelsprinz Gallywix oben im Hauptgebäude des Hauptgeschäftssitzes der HGK auf Kezan.', },
  },
  [14117] = {
    'Die Augen von Eschental',
    {'Unsere Feinde sind in der Überzahl, $C, sogar direkt hier an unserer Türschwelle. Die Nachtelfen haben die Talrendisspitze verstärkt, weil sie unser Vordringen im Eschental unterbinden wollten. In diesem Augenblick patrouillieren ihre Späher in den nahegelegenen Hügeln und berichten über jedes Ein- und Ausgehen an diesen Toren.|n|nWir müssen Eschental diese Augen herausreißen.|n|nGeht. Eure Beute schleicht um diese Tore herum, insbesondere im Osten. Vernichtet die Späher, die uns beschatten!', },
    {'Tötet 8 Späher der Talendrisspitze.', },
  },
  [14118] = {
    'Wildbret für die Truppen',
    {'Während wir die Ressourcen dieses Landes für unsere Kriegsmaschinerie aufbrauchen, berauben wir die einheimischen Tiere ihrer Heimat. Wenn sie ohnehin sterben müssen, sollte ihr Fleisch aber dennoch nicht verschwendet werden. Nicht wenn die Schlünde von Orgrimmar weit geöffnet und hungrig sind.|n|nTötet die geschwächten Mooshufhirsche, die sich noch in diesem Gebiet aufhalten, und bringt ihr Fleisch unseren Peons und Grunzern mit.', },
    {'Sammelt 15 Scheiben Wildbret von geschwächten Mooshufhirschen.', },
  },
  [14120] = {
    'Eine Bazillion Moneten?!',
    {'Ihr seid ein sehr ehrgeiziger junger Goblin, $N. Vielleicht ein wenig ehrgeiziger, als es für Euch gut wäre. Ich erkenne mich selbst in Euch, als ich noch jung war.|n|nIch habe einen Vorschlag. Vielleicht ist Euch ja schon aufgefallen, dass der Kajaro explodiert. Alle auf Kezan werden sterben!|n|nAber, wenn Ihr mir eine Bazillion Moneten bringt, bevor meine Yacht die Insel verlässt, werde ich dafür sorgen, dass Ihr unter den wenigen Glücklichen seid, die entkommen.|n|nWenn Ihr also leben wollt, solltet Ihr Euch lieber schnell überlegen, wo Ihr so viel Knete für mich auftreibt!', },
    {'Sprecht mit Sassy Hartzang im Hauptgeschäftssitz der HGK auf Kezan.', },
  },
  [14121] = {
    'Plündert die Plünderer',
    nil,
    {'Benutzt den Hot Rod, um 12 angeheuerte Plünderer umzufahren, und sammelt dabei 12 Einheiten gestohlene Beute.', },
  },
  [14122] = {
    'Der große Banküberfall',
    {'All Eure Besitztümer wurden eingefroren und die Erste Bank von Kezan hat geschlossen!|n|nIhr braucht wirklich einen Haufen Knete, Boss. Ich fürchte, Ihr müsst Euer eigenes Geld aus der Bank rauben! Mit den verschiedenen Apparaten in Eurem goblinischen Alles-in-1-zigartigen Gürtel solltet Ihr alles dabei haben, was Ihr braucht, um den Tresor zu knacken.|n|nIch hoffe nur, dass Ihr etwas für schlechte Zeiten gespart habt, wie ich es Euch immer geraten habe. Und falls Ihr es noch nicht gemerkt haben solltet: Die Zeiten sind gerade hundsmiserabel!', },
    {'Knackt den Tresor der Ersten Bank von Kezan, um an Eure privaten Reichtümer zu gelangen.', },
  },
  [14123] = {
    'Einfach hereinspaziert',
    {'Ich habe von unseren Geldproblemen gehört. Es gibt nur einen Weg, wie wir eine Bazillion Moneten zusammenkriegen können: Wir stehlen es von den Reichen!|n|nDieser Schleimer, der Handelsprinz, hat alle möglichen Antiquitäten und wertvolle Kunstgegenstände gestohlen. Es ist an der Zeit, es ihm zu nehmen und den Bedürftigen zu geben... natürlich vor allem uns!|n|nHobart hat eine Kappe zurückgelassen, an der er gearbeitet hat – eine Verkleidung, mit der Ihr genauso ausseht, wie einer von Gallywix\' Schergen. Ihr müsst einfach nur in seine Villa im Westen spazieren und diese Gegenstände "sicherstellen".|n|nPasst aber auf seine Schweine auf. Sie werden Euren Geruch hinter der Verkleidung erkennen!', },
    {'Beschafft Euch Maltes Falken, die Mona Goblisa und die ultimative Bombe.', },
  },
  [14124] = {
    'Schnappt Euch das Kaja\'mit',
    nil,
    {'Sammelt 12 Kaja\'mitbrocken.', },
  },
  [14125] = {
    nil,
    {'Wir kommen der Sache näher, aber wir haben immer noch nicht genug Moneten. Zu Eurem Glück, Boss, habe ich das vorausgesehen und einen Plan entwickelt. Wir werden die Versicherung des Hauptquartiers einstreichen!|n|nIch habe mir die Freiheit genommen, das übriggebliebene Feuerwerk von Eurer Party an diesem Ort zu verteilen. Alles, was Ihr tun müsst, ist dorthin zu gehen und ein wenig Sabotage zu betreiben.|n|nDarf ich vielleicht den defekten Generator, den undichten Ofen und das leicht entzündliche Bett vorschlagen? Danach geht Ihr wieder nach draußen und schickt einen Benzinbot hinein.|n|nEin narrensicherer Plan!', },
    {'Überlastet den defekten Generator, macht den undichten Ofen an und lasst eine Zigarre auf das leicht entzündliche Bett fallen. Benutzt dann den Benzinbot, um den Hauptgeschäftssitz der HGK in Brand zu setzen!', },
  },
  [14126] = {
    'Lebensersparnisse',
    {'Wir haben die ganze Knete zusammen. Jetzt müssen wir nur noch eines tun, Boss: Euch zur Yacht des Handelsprinzen schaffen. Sie legt bald ab!|n|nWir müssen uns beeilen. Springt rein! Ich fahre!', },
    {'Übergebt Handelsprinz Gallywix auf Gallywix\' Yacht auf Kezan Eure Lebensersparnisse.', },
  },
  [14127] = {
    'Die Rückkehr der Hochgeborenen?',
    {'Das Wachssiegel auf diesen Befehlen wurde erst vom Kurzen aufgebrochen. Ihr könnt die sorgfältig ausgeführte Elfenschrift nicht lesen, aber eine kleine handgemalte Karte deutet auf die nahegelegenen Ruinen. Unter der Karte stehen in einer gänzlich anderen Schrift eine Reihe von Runen in einer metallisch schimmernden Tinte.|n|nAg\'tor wird diese wichtige Geheiminformation zweifelsohne sehen wollen.', },
    {'Bringt die Befehle des Spähers zu Ag\'tor Blutfaust am Hinteren Tor von Orgrimmar.', },
  },
  [14128] = {
    'Die Rückkehr der Hochgeborenen?',
    {'Unsere Verbündeten, die Blutelfen, haben die Runen auf dieser Karte untersucht und sie können die rätselhafte Schrift vermutlich entziffern. Sucht nach Malynea Himmelshäscher. Sie leitet ihre Untersuchungen vom Umschlagplatz der Raketenbahn von Orgrimmar nördlich von hier. Es ist ein Teil des neuen Transitsystems der Goblins, das sich durch dieses Land zieht. Rasch, jetzt!', },
    {'Bringt die Befehle des Spähers zu Malynea Himmelshäscher am Umschlagplatz der Raketenbahn von Orgrimmar.', },
  },
  [14129] = {
    'Schredder außer Rand und Band',
    nil,
    nil,
  },
  [14130] = {
    'Freundschaft kennt keine Farbe',
    {'Mein Bruder und ich werden gejagt.|n|nUnser Vatertier wurde kürzlich getötet und der schwarze Drachenschwarm hetzt diejenigen von uns, die noch am Leben sind. Ich bin hier, weil ich Azuregos finden und in Sicherheit bringen will, aber er macht es mir nicht leicht.|n|nAzuregos hat nicht viele Freunde und sein diesbezüglicher Geschmack ist ein wenig... ungewöhnlich. Der Einzige, den ich hier in der Gegend kenne, ist ein Murloc mit Namen Ergll. Ihr solltet ihn an der Küste nordöstlich von hier finden.|n|nTut, was immer vonnöten ist, um Azuregos zu finden, und schickt ihn zu mir.|n|nBitte beeilt Euch.', },
    {'Findet Ergll an der Küste der Ruinen von Arkkoran.', },
  },
  [14131] = {
    'Bohnensammler',
    {'Azuregos... Azuregos... Azi? Der Großdrache? Wir sind Freunde, zweifellos! Er brachte mir das Sprechen bei. Er sagte, er mag meinen Farbton... ein Freund von Farben, oder?|n|nKann mich nicht erinnern, wo er hingegangen ist. Hmm... Vielleicht habt Ihr etwas, das meinem Gedächtnis auf die Sprünge hilft?|n|nIch ziehe hier am Strand Kahpheepflanzen. Sie mögen Sand. Ziemlich verrückt.|n|nKönntet Ihr mir ein paar ernten?', },
    {'Pflückt 10 Kahpheebohnen von den Pflanzen in den Ruinen von Arkkoran.', },
  },
  [14132] = {
    'Was für eine Frechheit!',
    {'Ich würde sie mit ihnen teilen, wenn sie fragen würden. Sie fallen einfach über meine Kahpheepflanzen her. Das ist nicht nett! Ihr könntet ihnen eine Lektion erteilen.|n|nDiese blöden Makrinnis.', },
    {'Tötet 10 Makrinnis in den Ruinen von Arkkoran.', },
  },
  [14133] = {
    'Ein Magierherz erobern',
    {'Jetzt, da Ihr mit den Boten fertig sind, sollte Ergll Euch von Azuregos erzählen. Sprecht mit ihm und findet heraus, ob Ihr hilfreiche Informationen zu Azuregos\' Aufenthaltsort in Erfahrung bringen könnt.', },
    {'Fragt Ergll nach Azuregos.', },
  },
  [14134] = {
    'Holz vor der Hütte',
    {'Jetzt, wo Ihr das Ding unter Kontrolle habt, sammeln wir das Holz ein, das ich mitbringen sollte. Sonst bauen diese Orcs das nächste Katapult aus MIR!|n|nFrisches Holz sollte bereits aufgestapelt in der Gegend sein. Verwendet den Schredder und sammelt so viel auf, wie Ihr könnt.', },
    {'Verwendet den umprogrammierten Schredder, um 6 Haufen azsharisches Holz zu sammeln. Falls Ihr Euren Schredder verliert, kann ein weiterer angegriffen und umprogrammiert werden.', },
  },
  [14135] = {
    'Auf den Baum',
    {'Haltet kurz still, ich mache die Steuerung für die Hauptmotorsäge betriebsbereit.|n|nHeckenschützen der Nachtelfen von der Talrendisspitze verstecken sich in den Bäumen und greifen meine Arbeiter an. Ich will, dass Ihr diese Heckenschützen erledigt... indem Ihr Euch zunächst um diese Bäume kümmert. Sucht nach azsharischen Schösslingen östlich des Haupttores. Euer Schredder wird wissen, was zu tun ist. Schreddert los!', },
    {'Verwendet die Motorsäge des Schredders, um die azsharischen Schösslinge niederzumähen, und tötet 9 Heckenschützen von der Talrendisspitze, sobald sie auftauchen.', },
  },
  [14136] = {
    'Rettungseinsatz auf See',
    {'Die Kvaldir haben auf Hrothgars Landestelle, der kleinen Insel im Norden, ihr Lager aufgeschlagen. Wir haben Kapitän Aerthas Feuerfalke in die Gegend geschickt, aber er und seine Mannschaft sind auf eine Seeräuberbande der Kvaldir gestoßen, die in Richtung Turnierplatz unterwegs war! Nun wird die Feuerfalke von den Seeräubern angegriffen und ihre Mannschaft ist weit in der Unterzahl. Geht dort hinaus und zeigt diesen Kvaldir, weshalb es keine gute Idee ist, die Sonnenhäscher anzugreifen.|n|nDie Feuerfalke befindet sich zwischen Hrothgars Landestelle im Norden und dem Turnierplatz, auf der westlichen Seite der Straße der Meerhäscher.', },
    {'Girana die Blutgezeichnete auf dem Argentumturnierplatz möchte, dass Ihr 8 Berserker der Kvaldir und 3 Harpunierer der Kvaldir an Bord der Feuerfalke tötet.', },
  },
  [14137] = {
    'Klassenausbildung (Verfolgenereignis)',
    nil,
    nil,
  },
  [14138] = {
    'Dienst ist Dienst und Cola ist Cola',
    {'Wir haben so viele Probleme unten in der Kaja\'mine, dass Vorarbeiter Feuchtlunte bald schon Purzelbäume schlägt, so verzweifelt wie er nach Euch sucht. Er murmelte etwas von \'widerspenstigen Trollen\'.|n|nDas Kaja\'mit, das unsere Trolle abbauen, ist ein wesentlicher Bestandteil unserer Kaja\'Cola. Dieses blubberige Zeug bringt uns ein Vermögen und Euch sicher die Beförderung $Gzum Handelsprinzen:zur Handelsprinzessin; ein!|n|nAber zunächst muss die Produktion wieder ins Rollen kommen. Ihr findet den Vorarbeiter im Osten. Hier, gebt ihm das als Motivation, damit er sich wieder zusammenreißt.', },
    {'Bringt Sassys Motivation zu Vorarbeiter Feuchtlunte im Hauptgeschäftssitz der HGK auf Kezan.', },
  },
  [14140] = {
    'Einhalt den Aggressoren',
    {'Die Kvaldir, räuberische Vrykul, die überall Angst und Schrecken verbreiten, haben unsere Lieferungen abgefangen und sämtliche Tuskarrbewohner einer Insel im Norden ermordet. Sie haben die Insel bereits in Hrothgars Landestelle umbenannt. Wenn es ihnen gelingt, dort langfristig Fuß zu fassen, werden wir mit Sicherheit zu ihrem nächsten Ziel.|n|nDie Streitkräfte des Kreuzzugs haben jedoch alle Hände voll zu tun mit der Geißel, und wir müssen den Turnierplatz beschützen. Fliegt vom Platz aus Richtung Norden, bis Ihr die Insel erreicht und nehmt Euch der Kvaldir an, bevor sie noch mehr zerstören können!', },
    {'Girana die Blutgezeichnete auf dem Argentumturnierplatz möchte, dass Ihr 10 Kvaldir tötet.', },
  },
  [14141] = {
    'Gormok will seine Schneebolde',
    {'Zwei meiner Männer kamen schon bei dem Versuch um, den Magnatauren namens Gormok den Pfähler einzusperren, doch die Kreatur treibt noch immer ihr Unwesen. Sie heult und jammert stundenlang darüber, dass ihr Lieblingsschneebold nicht da ist.|n|nIch würde sie mit eigenen Händen töten, wenn der Argentumkreuzzug dieses Monster nicht ins Kolosseum schicken wollte. Vielleicht ist es an der Zeit, der Bestie ihr Spielzeug zu bringen. Hier, nehmt dieses Netz und begebt Euch nach Garms Bann im Südosten der Sturmgipfel gleich nordöstlich von K3. Fangt ein paar dieser Schneebolde und betet zum Licht, dass Ihr den richtigen gefunden habt.', },
    {'Fangt mithilfe des beschwerten Netzes 8 schneeblinde Anhänger und bringt sie zu Tylos Dämmerflucht auf dem Argentumturnierplatz.', },
  },
  [14142] = {
    'Diesmal habt Ihr Euch wirklich selbst übertroffen, Kul',
    {'Kreuzfahrer Kul hat sich mal wieder in Schwierigkeiten gebracht, nur dieses Mal hat er noch andere mit hineingezogen. Als er sah, wie Kultisten in Todessprechers Wacht westlich des Turnierplatzes ihr Lager aufschlugen, rief er die Streiter für einen Angriff zusammen.|n|nSie wurden mit Leichtigkeit gefangen genommen und nun schmachtet Kul in einem Käfig auf der Plattform im Lager. Ich bin mir sicher, dass der Kult die Gefangenen opfern wird - es sei denn, wir können sie retten. Jeder von diesen Kultisten könnte Schlüssel für die schwarzen Käfige bei sich haben. Findet die Schlüssel und befreit Kul und die gefangenen Streiter.', },
    {'Rettet Kul den Tollkühnen und 4 gefangene Streiter aus Todessprechers Wacht und kehrt dann zu Girana der Blutgezeichneten auf dem Argentumturnierplatz zurück.', },
  },
  [14143] = {
    'Legt mal ein Bein zu',
    {'Der Argentumkreuzzug hatte ein schnelles Schiff mit einer Ladung Weitschreiterfleisch und weiteren Vorräten entsendet, die für uns hier am Turnierplatz vorgesehen waren, doch nie eingetroffen sind. Späher berichteten uns von einem Angriff der Kvaldir, räuberische Vrykul, die Angst und Schrecken auf den Meeren verbreiten.|n|nSie haben die Crew erschlagen und die Ladung auf eine Insel namens Hrothgars Landestelle gebracht. Wenn Ihr Richtung Norden blickt, könnt Ihr sie schemenhaft erkennen, verborgen im Nebel. Würdet Ihr uns helfen, das Diebesgut zurückzubeschaffen? Ohne diese Weitschreiterbeine werden wir bald hungern müssen.', },
    {'Beschafft 10 gestohlene Weitschreiterbeine zurück und bringt sie zu Girana der Blutgezeichneten auf dem Argentumturnierplatz.', },
  },
  [14144] = {
    'Die Barmherzigkeit des Lichts',
    {'Ich habe Beichtpatin Blondlocke aufmerksam gelauscht, und ich sage Euch, ihre Worte gaben mir zu denken. Zwar kämpfen wir Seite an Seite mit den Kreuzfahrern, aber wir könnten auch von ihnen lernen.|n|nAn der Nordküste liegt Hrothgars Landestelle, wo die seefahrenden Kvaldir eine alte Tuskarrsiedlung überrannt und deren Bewohner getötet haben. Nehmt dieses Buch und lest den Leichen der Dorfbewohner ihre Sterbesakramente. So ermöglicht Ihr ihren Seelen, die Fesseln der Nebel um die Insel abzustreifen und ihren Frieden zu finden.', },
    {'Benutzt das Gebetsbuch der Beichtpatin, um 8 erschlagenen Tualiq-Bewohnern ihre Sterbesakramente zu lesen, und kehrt dann zu Girana der Blutgezeichneten auf dem Argentumturnierplatz zurück.', },
  },
  [14145] = {
    'Was fressen eigentlich Yetis?',
    {'Die Kreuzfahrer haben einen Yeti eingefangen, den sie Eisheuler nennen. Er soll an den Kämpfen im Kolosseum teilnehmen und man hat uns gebeten, bei Training und Unterhalt zu helfen.|n|nDie Kreuzfahrer waren nicht begeistert von meinem Vorschlag, ein paar Mitglieder des Silberbunds an die Bestie zu verfüttern. Die Kreatur hat eine Vorliebe für Haifischfleisch, also will ich, dass Ihr zum Schiff "Scharlachroter Morgen" hinunterfliegt, das in der Meerenge gen Norden schwimmt. Besorgt Euch ein wenig frischen Köder aus einem der Kübel auf dem Boot und schüttet ihn ins Wasser, um Haie damit anzulocken.', },
    {'Tylos Dämmerflucht auf dem Argentumturnierplatz möchte, dass Ihr ihm 3 Stück Fleisch eines Nordmeerhais bringt.', },
  },
  [14146] = {
    'Verteidigt die Tore!',
    {'Du meine Güte – was ist hier los?|n|n<Schreie, Rufe und Schlachtgetöse dröhnen über Funk.>|n|n$N! Kommt sofort hierher zurück. Eilt zurück zu den Toren. Wir werden angegriffen!|n|nHelft uns, die Eindringlinge abzuwehren. Ich lade Euren Granatenwerfer!!', },
    {'Arbeitsaufseher Grabbit will, dass Ihr zurück zum Hinteren Tor von Orgrimmar eilt und dort 20 Räuber der Nachtelfen tötet.', },
  },
  [14151] = {
    'Kardinalsrubin',
    {'Man sagt, dass der Kardinalsrubin der feinste Edelstein in ganz Nordend ist. Er funkelt wie eine Kristallrose in der Sonne.|n|nBevor ich Euch die Herstellung beibringe, bitte ich Euch, fünf Transmutationen epischer Edelsteine durchzuführen, um auf diese Weise Euren Geist vorzubereiten. Welche Transmutationen Ihr wählt, das liegt bei Euch. Ihr könnt auch mehrmals dieselbe durchführen.|n|nKehrt zu mir zurück, wenn Ihr wirklich bereit seid.', },
    {'Linzy Schwarzbolz in Dalaran möchte, dass Ihr 5 erfolgreiche Transmutationen epischer Edelsteine mithilfe Eurer Alchemiefertigkeit durchführt. Für die Transmutation akzeptable Edelsteine sind Ametrine, Augen von Zul, Schreckenssteine, Königsbernsteine und Fürstenzirkone.', },
  },
  [14152] = {
    'Rettungseinsatz auf See',
    {'Champion, Kapitänin Schaumkrone und ihr Schiff wurden nach Norden entsandt, um die Kvaldir bei Hrothgars Landestelle zu behelligen, als sie von einer Seeräuberbande der Kvaldir abgefangen wurden, die in Richtung Turnierplatz unterwegs war! Unglücklicherweise sind die Kvaldir der Mannschaft an Bord zahlenmäßig um einiges überlegen und gerade dabei, das Schiff zu übernehmen.|n|nIhr müsst Euch auf nach Norden zur Schaumkrone machen, die sich in der Straße der Meerhäscher zwischen dem Turnierplatz und Hrothgars Landestelle befindet, und der Mannschaft helfen, den Angriff abzuwehren. Das Schiff sollte sich auf der Ostseite der Meeresenge befinden.', },
    {'Begebt Euch in Richtung des Nordmeers und tötet unter den Angreifern der Schaumkrone 8 Berserker der Vrykul und 3 Harpunierer der Vrykul.', },
  },
  [14153] = {
    'Der Mittelpunkt der Party',
    {'Oh, wow, Baby! Alle sind gekommen! Wen interessiert da schon so ein blöder Drache?|n|nWir veranstalten die Party am Pool. Klingt so, als würden sich alle schon köstlich amüsieren. Du wirst so toll aussehen!|n|nWarum gehst Du nicht schon einmal rüber zum Pool und unterhältst die Leute? Ich bin in einer Minute bei Dir... Ich muss nur noch meine Sachen holen.', },
    {'Zieht Eure großartige Partyausstattung an (Coole Sonnenbrille, Hippes neues Outfit und Strahlende Klunker). Begebt Euch danach auf die Party am Pool des Hauptgeschäftssitzes der HGK und unterhaltet 10 kezanische Feiernde.', },
  },
  [14154] = {
    'Mit knapper Not',
    nil,
    {'Haltet die Worgen im oberen Bereich des Stadtgefängnisses von Gilneas 2 Minuten lang auf.', },
  },
  [14155] = {
    nil,
    {'Wie steht es um den Schredder? Ich glaube, ich kann Eure Notfallenergievorräte einsatzbereit machen. Das wird Euch wiederaufladen, wenn Ihr beschädigt seid.|n|nHört gut zu. Diese Nachtelfen werden von einem Urtum des Krieges unterstützt, das sich westlich des Tores verwurzelt hat. Es ist ein gigantischer Baumriese. Ihr wisst, was zu tun ist! Legt ihn um!|n|nDafür seid Ihr wie geschaffen!!', },
    nil,
  },
  [14156] = {
    'V-Mann',
    {'Wenn der König Lord Crowley und seine Bande von Verrätern retten möchte, dann werden wir seinen Befehlen Folge leisten.|n|nEigentlich kommt mir die Sache ganz Recht… Einer meiner Männer hatte den Auftrag, Crowleys Gruppe zu unterwandern. Ich wüsste wirklich gerne, ob er diesen Vorfall überlebt hat.|n|nNähert Euch Sean Dempsey vorsichtig... Keiner darf erfahren, dass er sich unter Crowleys Männern befindet. Sie könnten sich als gefährlicher für ihn erweisen, als die Worgen.', },
    {'Findet Sean Dempsey auf dem Dach des Stadtgefängnisses von Gilneas.', },
  },
  [14157] = {
    'Alte Differenzen',
    {'Lord Darius Crowley ist schon viele Dinge genannt worden. Rebell. Verräter. Terrorist.|n|nVor dem Bürgerkrieg nannte ich ihn einen... Freund.|n|nIch habe ihn nie dafür verurteilt, einen Aufstand gegen mich angeführt zu haben. Sein Land und seine Bevölkerung waren durch eine zehn Meter hohe Mauer von Gilneas abgeschnitten... Aber wir hatten keine Wahl.|n|nWie auch immer... Crowley ist genau die Person, die wir jetzt brauchen.|n|nBetretet das Steinwallgefängnis und fragt Hauptmann Broderick, wo Crowley zu finden ist. Ich würde ja meine eigenen Männer schicken, aber es existiert immer noch böses Blut zwischen uns.', },
    {'Sprecht mit Hauptmann Broderick im Steinwallgefängnis in Gilneas.', },
  },
  [14159] = {
    'Das Arsenal des Rebellenlords',
    {'Das Arsenal, von dem Crowley spricht, befindet sich in einem Keller westlich von hier.|n|nEs gefällt mir zwar nicht, dass meine Gegner Artillerie in die Stadt geschmuggelt haben, aber sie könnte dabei helfen, gilnearische Leben zu retten.|n|nFindet Josiah Avery und requiriert die Rebellenartillerie. Wir müssen diese Waffen sinnvoll einsetzen.', },
    {'Sprecht mit Josiah Avery im Militärdistrikt in Gilneas.', },
  },
  [14160] = {
    'Leistungsurkunde',
    {'Auf diesem feinen Pergament befindet sich eine Liste mit einer großen Anzahl an Leistungen, die $N in der Tradition der Juwelierskunst errungen hat.|n|nBringt diese Urkunde zu Jonas Timotheus nach Dalaran zurück, um eine angemessene Belohnung zu erhalten.', },
    {'Liefert die Leistungsurkunde bei Jonas Timotheus in Dalaran ab.', },
  },
  [14161] = {
    'Basilisken klatschen',
    {'Wir haben diesen ganzen Berg abgetragen, um die Mineralien aus der Mine darunter abzubauen. Aber wir haben nicht bedacht, dass die Basilisken, die dort unterirdisch hausten, nun, also, oberirdisch hausen. Ihr seht so unternehmungslustig aus. Geht dorthin und tötet ein paar dieser Plagegeister und ich greife für Euch einmal tief in unsere Geldvorräte.', },
    {'Tötet 10 Grausteinbasilisken im Tagebau am Gebirgsfuß.', },
  },
  [14162] = {
    'Meldet Euch bei Horzak',
    {'Ihr habt wirklich gute Arbeit geleistet, als Ihr unsere Holzfällerei zum Laufen gebracht habt. Aber ich habe gehört, dass wir langsam zu wenig Stein haben. Man sollte meinen, wenn wir Berge versetzen können, könnten wir dabei auch ein paar Steine aufsammeln...|n|nNun, das ist nicht mein Problem, aber vielleicht könnt Ihr es zu Eurem machen. Meldet Euch bei Horzak Zignibbel oben am Umschlagplatz der Raketenbahn von Orgrimmar. Findet heraus, ob Ihr ihm dabei helfen könnt, diese Operation in den Griff zu bekommen. Folgt der Straße Richtung Nordosten und Ihr findet ihn im Turm der Raketenbahn.', },
    {'Findet Horzak Zignibbel am Umschlagplatz der Raketenbahn von Orgrimmar in Azshara.', },
  },
  [14163] = {
    'Zu den Waffen: Insel der Eroberung',
    {'Da wir dem Sieg in Eiskrone immer näher kommen, ist es deutlicher geworden, dass sich unsere Armeen mit der Horde auseinandersetzen müssen, bevor sie sich um den Lichkönig kümmern können.|n|nSie haben die Elitewache bekannt als die Kor\'kron eingesetzt, um unseren Vormarsch auf der Insel der Eroberung aufzuhalten. Die Insel ist von äußerst wichtiger strategischer Bedeutung, $N. Seht zu, dass unsere Jungs gewinnen!', },
    {'Erringt den Sieg bei einer Partie auf dem Schlachtfeld "Insel der Eroberung" und kehrt zu einem Brigadegeneral der Allianz in irgendeiner Hauptstadt, Dalaran oder Shattrath zurück.', },
  },
  [14164] = {
    'Zu den Waffen: Insel der Eroberung',
    {'Der Sieg in Nordend wird bald unser sein... doch nicht bevor wir in Eiskrone Fuß gefasst haben, um für den Transport und die Versorgung unserer Truppen zu sorgen.|n|nDie Insel der Eroberung ist ein idealer Ort. Sie ist einfach zu verteidigen und reich an Ressourcen. Die Allianz ist zu demselben Schluss gelangt und hat die 7. Legion ausgesandt, um unseren Streitkräften die Kontrolle zu entreißen.|n|nGeht, $N, und sorgt dafür, dass die Horde um jeden Preis die Oberhand gewinnt!', },
    {'Erringt den Sieg bei einer Partie auf dem Schlachtfeld "Insel der Eroberung" und kehrt zu einem Kriegshetzer der Horde in irgendeiner Hauptstadt, Dalaran oder Shattrath zurück.', },
  },
  [14165] = {
    'Kalt wie Stein',
    {'Die Arbeiter tun fast so, als bestünde Ihre Hauptaufgabe darin, sich zu beschweren. Wenn es nicht die harte Knochenarbeit, die Überstunden oder die geringe Bezahlung sind, ist es die Tatsache, dass sie von den Basilisken in Stein verwandelt werden. Irgendwas ist immer!|n|nAber ich glaube inzwischen, dass dieses ganze Arbeiter-in-Stein-Verwandeln ein echtes Geschäft für mich werden könnte. Was ist, wenn diese Leute jetzt hochwertiges Gestein sind? Meine jammernden Beschäftigten könnten für mich als Luxusbaumaterial mehr wert sein als als Arbeiter! Schnappt Euch einen versteinerten Bergfußminenarbeiter und schleppt ihn zu mir.', },
    {'Holt einen versteinerten Bergfußminenarbeiter aus dem Tagebau am Gebirgsfuß und bringt ihn zurück zu Horzak Zignibbel am Umschlagplatz der Raketenbahn von Orgrimmar.', },
  },
  [14166] = {
    'Die dankbaren Toten',
    {'Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!|n|nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...|n|nIch glaube, Chapman dort drüben verkauft das Rezept.', },
    {'Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Geist aus Dalaran auf dem Friedhof von Dalaran.|n|nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.', },
  },
  [14167] = {
    'Die dankbaren Toten',
    {'Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!|n|nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...|n|nIch glaube, Chapman dort drüben verkauft das Rezept.', },
    {'Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Zwergengeist auf dem Friedhof von Eisenschmiede.|n|nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.', },
  },
  [14168] = {
    'Die dankbaren Toten',
    {'Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!|n|nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...|n|nIch glaube, Chapman dort drüben verkauft das Rezept.', },
    {'Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Gnomengeist auf dem Friedhof von Eisenschmiede.|n|nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.', },
  },
  [14169] = {
    'Die dankbaren Toten',
    {'Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!|n|nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...|n|nIch glaube, Chapman dort drüben verkauft das Rezept.', },
    {'Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Draeneigeist auf dem Friedhof der Exodar.|n|nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.', },
  },
  [14170] = {
