  [24792] = {
    'V-Mann',
    {'Ihr wirkt, als könntet Ihr Euch nun um den Strippenzieher all dessen kümmern. In dem Geschäftsbuch steht, er hätte sich auf Burg Schattenfang verkrochen. Dorthin sollt Ihr Euch begeben.|n|nEiner unserer Leute befindet sich bereits vor Ort, doch er selbst kann nichts unternehmen. Geht jetzt, der Ermittler erwartet Euch. Und nehmt ein paar Freunde mit.', },
    {'Meldet Euch bei Ermittler Fezzen Kupferstapel auf Burg Schattenfang.', },
  },
  [24793] = {
    'V-Mann',
    {'Ihr wirkt, als könntet Ihr Euch nun um den Strippenzieher all dessen kümmern. In dem Geschäftsbuch steht, er hätte sich auf Burg Schattenfang verkrochen. Dorthin sollt Ihr Euch begeben.|n|nEiner unserer Leute befindet sich bereits vor Ort, doch er selbst kann nichts unternehmen. Geht jetzt, der Ermittler erwartet Euch. Und nehmt ein paar Freunde mit.', },
    {'Meldet Euch bei Ermittler Fezzen Kupferstapel auf Burg Schattenfang.', },
  },
  [24794] = {
    'Sprecht mit Spraggel',
    {'Meine gute Freundin Spraggel ist schon eine ganze Weile wegen einer gewissen Sache beunruhigt. Ich würde ihr ja helfen, aber wie Ihr seht, habe ich es gerade schön bequem.|n|nKönntet Ihr nicht nachsehen, was sie möchte?', },
    {'Sprecht mit Spraggel Frock in Marschalls Wehr.', },
  },
  [24795] = {
    'Ein Sieg für den Silberbund',
    {'Trotz der Angeberei Königin Lana\'thels habt Ihr Quel\'Delar wiederhergestellt, $N. Wie lange haben wir davon geträumt, Quel\'Delar wieder an uns zu nehmen.|n|nNicht nur der Silberbund, sondern alle Quel\'dorei schulden Euch ihren Dank.|n|nDas Schwert scheint zu wissen, dass Ihr als $C nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Vielleicht kann der Argentumkreuzzug helfen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen des Silberbunds an Justiziarin Mariel Treuherz.', },
    {'Bringt das wiederhergestellte Quel\'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.', },
  },
  [24796] = {
    'Ein Sieg für den Silberbund',
    {'Trotz der Angeberei Königin Lana\'thels habt Ihr Quel\'Delar wiederhergestellt, $N. Wie lange haben wir davon geträumt, Quel\'Delar wieder an uns zu nehmen.|n|nNicht nur der Silberbund, sondern alle Quel\'dorei schulden Euch ihren Dank.|n|nVereesa Windläufer, die Anführerin des Silberbunds, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel\'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, wo sie auf Euch wartet, $N.', },
    {'Bringt das wiederhergestellte Quel\'Delar zu Vereesa Windläufer in der Violetten Zitadelle in Dalaran.', },
  },
  [24798] = {
    'Ein Sieg für die Sonnenhäscher',
    {'Endlich, Quel\'Delar ist zum Ruhme der Sonnenhäscher und der Sin\'dorei wiederhergestellt!|n|nGanz Silbermond wird Euch als Helden feiern, $N.|n|nDas Schwert scheint zu wissen, dass Ihr als $C nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Noch hat sich kein würdiger Sin\'dorei gemeldet. Lasst uns den Rat des Argentumkreuzzugs suchen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen der Sonnenhäscher an Justiziarin Mariel Treuherz.', },
    {'Bringt das wiederhergestellte Quel\'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.', },
  },
  [24799] = {
    'Ein Sieg für die Sonnenhäscher',
    {'Endlich, Quel\'Delar ist zum Ruhme der Sonnenhäscher wiederhergestellt!|n|nDie gesamte Horde wird Euch als Helden feiern, $N.|n|nDas Schwert scheint zu wissen, dass Ihr als $C nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Ich kann meine Enttäuschung nicht verbergen... ich hatte gehofft, es würde ein würdiger Sin\'dorei sein. Lasst uns den Rat des Argentumkreuzzugs suchen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen der Sonnenhäscher an Justiziarin Mariel Treuherz.', },
    {'Bringt das wiederhergestellte Quel\'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.', },
  },
  [24800] = {
    'Ein Sieg für die Sonnenhäscher',
    {'Endlich, Quel\'Delar ist zum Ruhme der Sonnenhäscher und der Sin\'dorei wiederhergestellt!|n|nGanz Silbermond wird Euch als Helden feiern, ebenso wie die gesamte Horde, $N.|n|nDer Erzmagier Aethas Sonnenhäscher, der Anführer der Sonnenhäscher, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel\'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, $N. Der Erzmagier will Euch persönlich gratulieren!', },
    {'Bringt das wiederhergestellte Quel\'Delar zu Erzmagier Aethas Sonnenhäscher in der Violetten Zitadelle in Dalaran.', },
  },
  [24801] = {
    'Ein Sieg für die Sonnenhäscher',
    {'Endlich, Quel\'Delar ist zum Ruhme der Sonnenhäscher und der Horde wiederhergestellt!|n|nDies ist ein wahrer Segen für unsere Bemühungen gegen den Lichkönig.|n|nDer Erzmagier Aethas Sonnenhäscher, der Anführer der Sonnenhäscher, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel\'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, $N. Der Erzmagier will Euch persönlich gratulieren!', },
    {'Bringt das wiederhergestellte Quel\'Delar zu Erzmagier Aethas Sonnenhäscher in der Violetten Zitadelle in Dalaran.', },
  },
  [24802] = {
    'Der Zorn des Lichkönigs',
    {'Es besteht wohl kaum Hoffnung, Arthas auf den Stufen seines eigenen Thrones zu besiegen. Und wer übernimmt in diesem Fall die Krone des Lichkönigs?|n|nViele Fragen sind noch offen, doch zuerst müsst Ihr Sylvanas finden und vor dem Lichkönig fliehen, solange Zeit dazu ist.', },
    {'Findet Fürstin Sylvanas Windläufer und flieht aus den Hallen der Reflexion.', },
  },
  [24803] = {
    'Angelwettstreit der Kalu\'ak',
    nil,
    nil,
  },
  [24804] = {
    'Ungewöhnliche Düfte',
    {'Irgendetwas stimmt nicht mit dieser Chemiemanufaktur Krone. Dampfdruck hat ein Auge darauf geworfen, aber wir könnten noch ein paar mehr gebrauchen.|n|nBegebt Euch nach Sturmwind, wenn Ihr uns helfen wollt. Inspektor Snip Schnappbolz leitet die Untersuchung dort und er kann jede Hilfe gebrauchen, die er kriegen kann.', },
    {'Meldet Euch bei Inspektor Snip Schnappbolz in Sturmwind.', },
  },
  [24805] = {
    'Ungewöhnliche Düfte',
    {'Irgendetwas stimmt nicht mit dieser Chemiemanufaktur Krone. Dampfdruck hat ein Auge darauf geworfen, aber wir könnten noch ein paar mehr gebrauchen.|n|nBegebt Euch nach Orgrimmar, wenn Ihr uns helfen wollt. Detektiv Snap Schnappbolz leitet die Untersuchung dort und er kann jede Hilfe gebrauchen, die er kriegen kann.', },
    {'Meldet Euch bei Detektiv Snap Schnappbolz in Orgrimmar.', },
  },
  [24806] = {
    'Mehr Glück beim nächsten Mal',
    nil,
    nil,
  },
  [24807] = {
    'Winnoa Kiefernwald',
    {'Obwohl wir hier einiges erreicht haben, wäre es eine Tragödie, wenn ein Teil dieser Verderbnis unserer Aufmerksamkeit entgangen wäre. Die Tunnel der Höhlen des Wehklagens erstrecken sich unter dem gesamten Brachland und wenn noch ein weiterer Punkt ungezähmter Energie sich einen Weg an die Oberfläche gebahnt hat...|n|nIhr habt allerdings genug für mich getan. Ich möchte Euch nur noch darum bitten, einen Druidenfreund von mir wissen zu lassen, was hier geschehen ist. Ihr findet Winnoa Kiefernwald an der Vendettakuppe südwestlich von hier.', },
    {'Sprecht mit Winnoa Kiefernwald an der Vendettakuppe im Südlichen Brachland.', },
  },
  [24812] = {
    'Keine Gnade mehr',
    {'Die Naga haben unserem Volk Schreckliches angetan. Die Zeit, ihnen Gnade zu zeigen, ist lang vorbei.|n|nGeht in die Höhle und tötet alle Naga, die Ihr dort findet. Jeder Naga, der heute stirbt, ist einer weniger, der uns später überraschen kann. Ich vertraue darauf, dass Ihr gründlich seid.', },
    {'Tötet 12 Gallschuppennaga.', },
  },
  [24813] = {
    'Territorialer Fetisch',
    {'Das ist kein halbherziger Gegenangriff. Wir haben vor, jeden einzelnen Naga zu töten und alles zu tun, damit sie nicht zurückkehren wollen.|n|nIch will, dass Ihr diese Fetische auf jede Gallschuppenflagge setzt, die Ihr in der Höhle findet. Das sollte eine klare Aussage darüber sein, was wir von ihrer Anwesenheit hier halten. Und mehr noch: Die Magie in diesen Fetischen wird alle Gallschuppen schwächen, die sich nähern, sodass sie es sich zweimal überlegen werden, ob sie auf unserer Insel bleiben wollen.', },
    {'Platziert 8 Territorialfetische auf Gallschuppenflaggen.', },
  },
  [24814] = {
    'Ein uralter Feind',
    {'Die Meerhexe ist hier, oben auf genau dieser Insel. Wir haben lange auf diese Gelegenheit zur Rache gewartet, und Ihr werdet die Ehre haben, sie zu nutzen.|n|nTrefft Euch mit Vol\'jin auf der Rampe im Nordosten. Lasst es ihn wissen, wenn Ihr bereit seid, Euch in die Schlacht zu stürzen.', },
    {'Sprecht mit Vol\'jin in der Bucht der Gallschuppen und helft ihm, Zar\'jira die Meerhexe zu töten.', },
  },
  [24815] = {
    'Wählt Euren Weg',
    nil,
    nil,
  },
  [24816] = {
    'Wer ist jetzt an der Spitze der Nahrungskette?',
    {'Gut, gut, vielleicht war diese Sache mit den Eiern doch nicht ganz ausgereift. Wer hat Lust auf Haifleisch?|n|nEs gibt da nur ein kleines Problem. Nun, eigentlich eher ein großes Problem. Ein RICHTIG großes Problem: Den Hammer!|n|nAber natürlich habe ich eine brillante Idee. Schwimmt hinaus in die Meerenge namens Bedrängnis im Westen und besorgt uns ein paar Haiteile. Gebt Sie meiner Assistentin Greely. Ich bin viel zu wichtig, um mir die Hände an diesen Details schmutzig zu machen.', },
    {'Sammelt 5 Haiteile.', },
  },
  [24817] = {
    'Ein Goblin im Haipelz',
    {'Wir haben die Überreste des Mechahuhns mit diesen Haiteilen kombiniert und daraus das großartigste Kampftauchboot aller Zeiten gebaut: den dampfbetriebenen Mechahai-X!|n|nHobart und ich wollen, dass Ihr das Ruder übernehmt, $N. Geht nach Westen ins Wasser und aktiviert die Steuerung für den Mechahai-X. Ihr müsst den Hammer töten, wenn wir auch nur die geringste Chance haben wollen, die natürlichen Ressourcen der Meerenge im vollen Maße auszuschöpfen!', },
    {'Aktiviert die Steuerung des dampfbetriebenen Mechahai-X und benutzt ihn dann, um den Hammer zu töten.', },
  },
