  [25789] = {
    'Es hat sich ausgehammert',
    {'Der Riss, der hier war, hat dieses seltsame Gerät hinterlassen, aber wieso?|n|nVielleicht hat jemand in einer der Hauptstädte mehr Informationen darüber.', },
    {'Bringt das mysteriöse Gerät nach Orgrimmar, Unterstadt, Silbermond oder Donnerfels und zeigt es einem Botschafter des Irdenen Rings.', },
  },
  [25790] = {
    'Zurück zu Crazzle',
    {'Ich bin NICHT dumm!|n|nGeht zu Eurem Meister zurück und sagt ihm, dass es mit der Sache NICHTS wird! Falls Ihr überhaupt lebend bei ihm ankommen solltet.', },
    {'Sprecht mit Crazzle Flinkspross in Spalthufanhöhen in Tausend Nadeln.', },
  },
  [25791] = {
    'Zurück zu Riznek',
    {'Ich bin NICHT dumm!|n|nGeht zu Eurem Meister zurück und sagt ihm, dass es mit der Sache NICHTS wird! Falls Ihr überhaupt lebend bei ihm ankommen solltet.', },
    {'Sprecht mit Riznek in Spalthufanhöhen in Tausend Nadeln.', },
  },
  [25792] = {
    'Vorwärts drängen',
    {'Die meisten der Gebirgsjäger und Dampfpanzer in Dun Morogh kämpfen an der Frontlinie der Frostmähnen, die sich uns aus Südosten nähert. Wir können kaum die Trolle zurückhalten, geschweige denn, in ihr Dorf vorrücken und ihren Anführer angreifen.|n|nSie haben unseren Zugangspfad mit mysteriösen Totems blockiert, die allen sich nähernden Gebirgsjägern die Luft nehmen und ihre Opfer dadurch hilflos ihren Feinden überlassen. Auf diesem Stein ist eine Rune des Feuers eingraviert. Er sollte in der Lage sein, die Totems zu zerstören und unsere Gebirgsjäger zu befreien.', },
    {'Benutzt die Rune des Feuers, um 4 Totems der Konstriktion an der Frontlinie der Frostmähnen zu zerstören.', },
  },
  [25793] = {
    'Die Ausufernden Tiefen',
    {'Sinn und Zweck dieser Basis war es, im Steinkrallengebirge für Theramore Fuß zu fassen und eine Nachschublinie für die Nachtelfen zu eröffnen. Leider hat die Horde erbitterte Gegenwehr geleistet. Höllschreis Armeen sind mächtig und unnachgiebig. Ich habe so eine Heftigkeit von der Horde seit dem zweiten Krieg nicht erlebt.|n|nJetzt scheint es so, dass die Mine, die die Forscherliga ausgehoben hat, von der Horde dazu benutzt wird, uns zu umgehen. Wir müssen die Mine versiegeln!', },
    {'Sprecht mit Stahlzeh McGee an den Ausufernden Tiefen im Steinkrallengebirge.', },
  },
  [25794] = {
    'Zuflucht unter dem Meer',
    {'Ich glaube, ich habe den Verfasser Eurer Notiz gefunden, Freund.|n|nWie es aussieht, braucht er dringend Hilfe, um zu überleben.|n|nIch werde eine meiner Seherkugeln vorbereiten, damit Ihr ihn selbst sehen könnt.', },
    {'Benutzt Erunaks Seherkugel, um die Position der Tiefennebelgrotte zu sehen.', },
  },
  [25795] = {
    'Rückkehr zum Schrein',
    {'Avianas Ei sollte sicher am Schrein angekommen sein. Geht ruhig und seht es Euch an! Choluna weiß sicher, was zu tun ist.|n|nIch werde unsere Aufgabe hier noch abschließen und stoße dann später zu Euch.', },
    {'Kehrt zu Choluna am Schrein von Aviana auf dem Hyjal zurück.', },
  },
  [25796] = {
    'Enteignung',
    {'Es ist Schicksal, das wir dieses Öl erhalten haben. Dass die Zentauren diesen Ort gewählt haben, als das Meer über uns hereingebrochen ist, ist Pech.|n|nPech für sie, sollte ich sagen.|n|nSie haben uns ins Gesicht gespuckt, $N. Wir haben ihnen ein großzügiges Angebot unterbreitet, und es war ein Fehler, es nicht anzunehmen. Jetzt werden... werdet Ihr ihnen zeigen, worin dieser Fehler lag.|n|nVertreibt die Zentauren von den Spalthufanhöhen. Das Öl muss fließen!', },
    {'Tötet 15 Zentauren der Spalthufanhöhen.', },
  },
  [25797] = {
    'Enteignung',
    {'Es ist Schicksal, das wir dieses Öl erhalten haben. Dass die Zentauren diesen Ort gewählt haben, als das Meer über uns hereingebrochen ist, ist Pech.|n|nPech für sie, sollte ich sagen.|n|nSie haben uns ins Gesicht gespuckt, $N. Wir haben ihnen ein großzügiges Angebot unterbreitet, und es war ein Fehler, es nicht anzunehmen. Jetzt werden... werdet Ihr ihnen zeigen, worin dieser Fehler lag.|n|nVertreibt die Zentauren von den Spalthufanhöhen. Das Öl muss fließen!', },
    {'Tötet 15 Zentauren der Spalthufanhöhen.', },
  },
  [25798] = {
    'Verteidigt den Turm!',
    {'Ich werde diesen Ort nicht mit leeren Händen verlassen! Ihr etwa?|n|nIch bin mir sicher, dass Ihr Euch gefragt habt, was wohl in der riesigen Kiste ist. Nun, Ihr müsst nicht länger warten. Bringt einen unserer Bohrtürme zu den Öltümpeln, und bohrt nach Öl für uns.|n|nIhr müsst natürlich damit rechnen, dass die Zentauren angreifen werden. Verteidigt den Turm lange genug, um ein oder zwei Fässer füllen zu können.', },
    {'Verteidigt den Ölbohrturm.', },
  },
  [25799] = {
    'Verteidigt den Turm!',
    {'Ich werde diesen Ort nicht mit leeren Händen verlassen! Ihr etwa?|n|nIch bin mir sicher, dass Ihr Euch gefragt habt, was wohl in der riesigen Kiste ist. Nun, Ihr müsst nicht länger warten. Bringt einen unserer Bohrtürme zu den Öltümpeln, und bohrt nach Öl für uns.|n|nIhr müsst natürlich damit rechnen, dass die Zentauren angreifen werden. Verteidigt den Turm lange genug, um ein oder zwei Fässer füllen zu können.', },
    {'Verteidigt den Ölbohrturm.', },
  },
  [25800] = {
    'Wenn das Leben dir Krabben schenkt...',
    {'Es gibt hier viel zu tun, $C, aber wir dürfen die Augen nicht vor den Geschenken des Schicksals verschließen.|n|nAls die Flut über unsere Häuser hereinbrach, schwemmte sie viele Meeresbewohner an. Die Bucht von Menethil ist jetzt voller großer Krabben, die genau richtig sind, um sie einzusammeln.|n|nWenn das Leben dir Krabben schenkt, geh Krabbenfischen, sag ich immer. Bringt mir die größten und fleischigsten Scheren, die Ihr finden könnt und ich bezahle Euch.', },
    {'Findet 5 fleischige Kriecherklauen von Hafenkriechern.', },
  },
  [25801] = {
    'Klauen aus der Tiefe',
    {'Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.|n|nEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr, und wir sind bereit, für ihre Sicherheit zu zahlen.|n|nGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.', },
    {'Holt Euch Gobblers Kopf von Gobbler und tötet 12 beliebige Murlocs der Blaukiemen.', },
  },
  [25802] = {
    'Waren-Wiederbeschaffung',
    {'Vor nicht allzu langer Zeit wurde ein Handelsschiff, die Blinde Prinzessin, von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.|n|nDurchsucht die Hütten der Murlocs an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Statuette von Menethil und bringt sie mir wieder.', },
    {'Durchsucht die Kisten und Fässer in den Murloclagern an der Küste.', },
  },
  [25803] = {
    'Die Suche geht weiter',
    {'Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur der Statuette von Menethil.|n|nVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.', },
    {'Sucht nach der Statuette von Menethil.', },
  },
  [25804] = {
    'Suche in weiteren Hütten',
    {'Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.|n|n... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.|n|nEine der Hütten nördlich von hier muss die Statuette von Menethil enthalten!', },
    {'Sucht weiter in den Hütten der Murlocs nach der Statuette von Menethil.', },
  },
  [25805] = {
    'Rückgabe der Statuette',
    {'Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.|n|nDies kann nur die Statuette von Menethil sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.', },
    {'Bringt Karl Boran im Hafen von Menethil im Sumpfland die Statuette von Menethil.', },
  },
  [25806] = {
    'Sie haben die Assass in... ach, egal',
    {'Ah, die Forscherliga - welche glanzvolle Gruppe von Schwachköpfen. Wir haben nicht nur die Geister der Tauren am Hals, die Forscherliga hat es ebenfalls geschafft, eine Hintertür für die Hauptbasis der Horde im Steinkrallengebirge - der Feste Krom\'gar - zu öffnen.|n|nJetzt bringen Auftragsmörder von Krom\'gar alle in der Mine um, ohne dass man auch nur einen Mucks hört.|n|nIhr müsst da hineingehen und aufräumen.|n|nBeinahe hätte ich vergessen, Euch diese Brille zu geben. Setzt sie sofort auf. Damit werden alle getarnten Assassinen in der Mine sichtbar.', },
    {'Tötet 12 Auftragsmörder von Krom\'gar.', },
  },
  [25807] = {
    'Die Wiedergeburt eines Ahnen',
    {'Ich bin davon überzeugt, dass IHR der Herold Avianas seid, $N. Ihr wart es, der sie zuerst gesehen hat und ihre Essenz aus den Klauen eines Drachen errettete.|n|nJa, ich glaube, dass Aviana in diese Welt wiedergeboren wird. Und Ihr habt die Ehre, sie über die Schwelle zu führen.|n|nNehmt dieses Rauchwerk und verbrennt es vor Avianas Ei im Raum direkt über mir.|n|nDie Ahnin ist nah, $N. Unsere Errettung steht kurz bevor!', },
    {'Benutzt das Rauchwerk des Herolds vor Avianas Ei im Schrein von Aviana.', },
  },
  [25808] = {
    'Ist das Ding an?',
    nil,
    {'Tötet Meisterassassine Kel\'istra.', },
  },
  [25809] = {
    'Lasst niemanden zurück!',
    nil,
    nil,
  },
  [25810] = {
    'Die Brutstätte muss brennen',
    {'$N! Choluna hat die Wahrheit gesprochen: Die Göttin ist zurückgekehrt! Ein Wunder ist geschehen.|n|nIhr habt zwar den Zwielichtdrachen Sethria töten können, wir haben jedoch noch nicht alle Eier ausfindig gemacht, die die Harpyien ihr gebracht hatten. Thisalee und ich haben ihnen nachgespürt und sind dabei auf eine große Brutstätte in den Feuerlanden gestoßen. Sie ist nicht von dieser Welt, also kann Aviana Euch nicht begleiten.|n|nFliegt nach Süden und tretet durch das Flammentor in der Mitte des Tals. Farden Klauenwürger ist vorausgesandt worden und wird im Inneren auf Euch warten.', },
    {'Reist durch das Flammentor in der Mitte der Flammenschneise auf dem Hyjal. Sprecht mit Farden Klauenwürger, sobald Ihr hindurchgegangen seid.', },
  },
  [25811] = {
    'Stilllegung',
    {'Um diese Mine stillzulegen, müsst Ihr die tragenden Pfeiler in die Luft jagen. Ich kann Euch den benötigten Sprengstoff zur Verfügung stellen, aber Ihr müsst Euch an den Auftragsmördern von Krom\'gar vorbeischleichen, um alle Träger zu erreichen.|n|nDie gute Nachricht - wenn man das so nennen kann - ist, dass wir die tragenden Pfeiler immer mit einem großen X markiert haben. Schaut nach diesen Markierungen und befestigt das Dynamit in ihrer Nähe. Sobald ihr das Dynamit angebracht habt, kommt wieder hier hoch und ich werde die Sprengung auslösen.|n|nKabumm!', },
    {'Verankert jeweils ein Dynamitbündel am ersten, zweiten, dritten und vierten Träger.', },
  },
  [25812] = {
    nil,
    {'Schnell, $N!|n|nBegebt Euch sofort zu dieser Höhle.|n|nWir werden Euch folgen und sicherstellen, dass Euch sonst niemand folgt.', },
    {'Sprecht mit dem Gefreiten Pollard in der Tiefennebelgrotte.', },
  },
  [25813] = {
    'Das Horn erklingen lassen',
    {'Dieser alte, verbitterte Zentaur Himmelsrufer Vrakthris hat den großen Luftgeist erwähnt, ein von den Zentauren verehrtes Wesen. Uns diesem Wesen anzunehmen ist der letzte Schritt in der Sicherung der Anhöhen.|n|nIch habe gesehen, wie sie das große Horn oben auf dem Hügel erklingen haben lassen, um den Luftelementar zu rufen. Er gab ihnen Befehle und verschwand gleich darauf wieder.|n|nLasst das Horn erklingen, $N.', },
    {'Tötet Whrrrl.', },
  },
  [25814] = {
    'Das Horn erklingen lassen',
    {'Dieser alte, verbitterte Zentaur Himmelsrufer Vrakthris hat den großen Luftgeist erwähnt, ein von den Zentauren verehrtes Wesen. Uns diesem Wesen anzunehmen ist der letzte Schritt in der Sicherung der Anhöhen.|n|nIch habe gesehen, wie sie das große Horn oben auf dem Hügel erklingen haben lassen, um den Luftelementar zu rufen. Er gab ihnen Befehle und verschwand gleich darauf wieder.|n|nLasst das Horn erklingen, $N.', },
    {'Tötet Whrrrl.', },
  },
  [25815] = {
    'Die Dritte Flotte',
    {'Ich war einst Erster Maat auf der \'Herrin der Meere\', einem Linienschiff der Dritten Flotte von Kul Tiras, der Verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs geritten wurden!|n|nWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.|n|n... Bringt mir meinen Met, $C. Er ist unten im Keller des Gasthauses. Auch wenn ich ihn so weit von mir entfernt verstaut habe, ich komme doch nicht ohne aus.', },
    {'Erhaltet Fitzsimmons\' Met aus dem Keller des Gasthauses im Hafen von Menethil.', },
  },
  [25816] = {
    'Zum Umherwandeln verdammt',
    {'<Gestärkt fährt Fitzsimmons mit seiner Geschichte fort...>|n|nIch bin der einzige Überlebende der unglückseligen Dritten Flotte von Kul Tiras, die vor der Küste im Norden untergegangen ist. Auf einem unserer Schiffe war ein großer und furchtbarer Schatz versteckt und seine gespenstische Macht hält die Seelen meiner Brüder gefangen in den verrottenden Schiffsrümpfen.|n|nIch werde Tag und Nacht von ihnen verfolgt. Der Erste Maat Snellig ruft mich! Er sollte eigentlich tot sein! Bitte, $N sucht ihn bei den Schiffswracks und... sagt ihm einfach, er soll mich in Ruhe lassen!', },
    {'Sprecht mit dem Geist des Ersten Maats Snellig.', },
  },
  [25817] = {
    'Die verfluchte Crew',
    {'Die Seeleute der Dritten Flotte sind durch einen Fluch für immer dazu verdammt, an diesen Ufern voller Qualen entlangzuwandeln. Fitzsimmons Seelenqual hängt mit uns zusammen - solange wir leiden, kann auch er nicht ruhen.|n|nIhr müsst das Leiden der Geister meiner Mannschaftskameraden beenden. Löscht ihre Geister auf dieser Ebene aus und kehrt zu mir zurück.', },
    {'Tötet 5 verfluchte Seemänner und 5 verfluchte Marinesoldaten in der Verlorenen Flotte.', },
  },
  [25818] = {
    'Brechen des Fluchs',
    {'Um den Fluch zu brechen, muss abgerechnet werden. Kapitän Halyndor hat uns alle dazu verdammt, ein verbotenes Artefakt zu begehren, das Auge von Paleth. Sein Geist will es noch immer und wacht über die Schließtruhe seines alten Schiffes, der \'Kühnheit\'.|n|nVernichtet die Seele dessen, der uns einst so verfluchte, $C. Besiegt den Kapitän, nehmt seinen Schlüssel und bringt das Auge von Paleth weit weg von diesem Ort.', },
    {'Besorgt den Geldkassettenschlüssel der \'Kühnheit\' von Kapitän Halyndor.', },
  },
  [25819] = {
    'Das Auge von Paleth',
    {'In der offenen Truhe erblickt Ihr eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert. Dies muss das schändliche Auge von Paleth sein, das die Seelen dieser Seefahrer verdammt hat.|n|nSolch eine Verderbnis muss ausgemerzt werden. Vielleicht kann Euch ein Priester im Hafen von Menethil helfen.', },
    {'Bringt Glorin Stahlbraue im Hafen von Menethil im Sumpfland das verfluchte Auge von Paleth.', },
  },
  [25820] = {
    'Die Sorgen einer Mutter',
    {'Mein Sohn Gimlok ist das Licht meines Lebens. Mein Herz geht auf, wenn ich ihn mit den anderen Kindern spielen sehe.|n|nTrotzdem mache ich mir Sorgen. Nur wenige Meter entfernt, in der Bucht, gibt es Haie. Was, wenn das Wasser so tief ist, dass einer hierher schwimmt...|n|nDer Gedanke ist unerträglich! Ihr habt sicher schon Schlimmeres bewältigt als wir Stadtbewohner, <Volk>. Würdet Ihr diese schrecklichen Haie für mich beseitigen? Wenigstens ein paar?', },
    {'Tötet 10 Hafenschredderflossen.', },
  },
  [25821] = {
    'Ein ganz besonderer Auftrag',
    {'Ihr habt hier unten Bemerkenswertes geleistet, $N. Truppenkommandant Valen ist das nicht entgangen. Er möchte Euch sofort sprechen. Er hat Euch für eine besondere Mission ausgewählt - eine, mit der wir die Übergriffe der Horde im Steinkrallengebirge hoffentlich endgültig stoppen werden.', },
    {'Meldet Euch bei Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.', },
  },
  [25822] = {
    'Kriegswerkzeug',
    {'Ich muss Euch noch einmal einer Gefahr aussetzen, $N. Im Osten gibt es eine von der Horde erbeutete Ausgrabungsstelle, die reich an Mineralien ist. Kisten mit unseren Waffen befinden sich dort. Sie sind überall verstreut. Die Horde ist erst vor kurzem dort eingefallen. Es ist unwahrscheinlich, dass sie bereits all unsere Ausrüstung gefunden haben.|n|nGeht dorthin und besorgt unseren Grimmtotemfreunden ein paar Waffen!', },
    {'Sammelt 10 Waffenkisten der Allianz.', },
  },
  [25823] = {
    'Die unerbittliche Horde',
    {'Es ist zwar äußerst wichtig, dass Ihr die Waffenkisten unverzüglich sichert, aber wir müssen die Grabstätte im Osten auch von der Horde säubern. Wir müssen vollen Zugang zur Ausgrabungsstätte erhalten, sonst können wir keine Nachschublinie für die Grimmtotemverbündeten schaffen.|n|nTötet alle Angehörigen der Horde, denen Ihr an der Grabstätte begegnet, $N. Für den Ruhm der Allianz!', },
    {'Tötet 12 Angehörige der Horde an der Grabstätte.', },
  },
  [25824] = {
    nil,
    {'Dieser Soldat stand an der Schwelle zum Tod, aber ich fürchte, wir können nicht warten, bis er wieder ganz genesen ist. Er hat Informationen, die wir dringend brauchen.|n|nSeid geduldig mit ihm, aber sorgt dafür, dass er weiterredet, bis er uns alles gesagt hat.|n|nMit ein bisschen Glück erfahren wir, womit wir es hier zu tun haben.', },
    {'Sprecht mit Gefreiter Pollard und erfahrt etwas über seine Tortur.', },
  },
  [25825] = {
    'Rohstofflieferung',
    {'Also, $N, ich will, dass Ihr das Öl zu Fizzel auf dem Turbodampfer bringt und ihm von den guten Neuigkeiten erzählt!', },
    {'Bringt das Fass mit Öl zu Fizzel Kupferbolz auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.', },
  },
  [25826] = {
    'Rohstofflieferung',
    {'Also, $N, ich will, dass Ihr das Öl zu Pozzik auf dem Turbodampfer bringt und ihm von den guten Neuigkeiten erzählt!', },
    {'Bringt das Fass mit Öl zu Pozzik auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.', },
  },
  [25827] = {
    'Lo\'Gosh ist bereit für die Schlacht',
    {'Dank Eurer Bemühungen wandelt der große Wolfsahne erneut unter uns.|n|n$C, Ihr müsst für mich zum Weltenbaum zurückkehren und Ysera Bescheid geben, dass Lo\'Gosh bereit ist, an vorderster Front für uns zu kämpfen.|n|nIhr könnt Ysera auch fragen, wie Ihr die anderen Ahnen entfesseln könnt.|n|nLok\'tar Ogar, mein Freund. Ihr seid wahrlich eine Inspiration für uns alle!', },
    {'Sprecht mit Ysera am Weltenbaum auf dem Hyjal.', },
  },
  [25828] = {
    'Goldrinns Botschaft an Ysera',
    {'Goldrinn wurde entfesselt und marschiert an unserer Seite! Was Ihr getan habt, kann man nur als Wunder bezeichnen.|n|nWir müssen Ysera beim Weltenbaum benachrichtigen. Die Schläferin koordiniert unsere Bemühungen, Hyjal zurückzuerobern. Es wird sie sicher freuen, dass Goldrinns legendäre Standhaftigkeit nun zu ihrer Verfügung steht.|n|nIhr könnt Ysera auch fragen, wie Ihr die anderen Ahnen entfesseln könnt.|n|nLebt wohl, $N. Und danke. Ihr seid wahrlich eine Inspiration für uns alle!', },
    {'Sprecht mit Ysera am Weltenbaum auf dem Hyjal.', },
  },
  [25830] = {
    'Der letzte lebende Wissenshüter',
    {'Ihr habt die Ahnen erweckt, $N, aber Aessina, der Geist der Wildnis, schweigt noch immer. Mit ihrer Hilfe können wir diesen Kampf zu unseren Gunsten wenden und den Schaden, den der Schattenhammer angerichtet hat, rückgängig machen.|n|nEs mag jemanden geben, der uns dabei helfen kann. Der älteste der Bäume, Nordu, stand seit Tausenden von Jahren in der Mitte dessen, was heute die Flammenschneise ist. Seine Weisheit ist so alt wie dieser Berg. Wenn dieser alte Baum noch am Leben ist, kann er uns vielleicht dabei helfen, Aessina zu erwecken. Sucht nach ihm!', },
    {'Findet Nordu, das Urtum der Lehren, in der Flammenschneise auf dem Hyjal.', },
  },
  [25831] = {
    'Hamuuls Botschaft an Ysera',
    {'$N, wir haben den Boden vorbereitet und uns die Hilfe des rätselhaften Schildkrötenahns gesichert.|n|nBitte reist nach Nordrassil zum Weltenbaum und lasst Ysera wissen, dass ich bereit bin, den nächsten Schritt zu tun.|n|nEs ist wichtig, dass wir alle Ahnen wecken, die wir können. Sprecht mit Ysera, um zu erfahren, wo Ihr auf dem Hyjal gebraucht werdet.', },
    {'Sprecht mit Ysera am Weltenbaum auf dem Hyjal.', },
  },
  [25832] = {
    'Rückkehr zu Aviana',
    {'$N, Ihr habt hier alles getan, was Ihr tun könnt. Die ganze Höhle wird bald in sich zusammenbrechen!|n|nIch treibe die letzten schwingenbewehrten Hengste zusammen und stelle sicher, dass das Flammentor hinter mir versiegelt wird.|n|nIhr solltet losgehen und Aviana berichten, dass diese abscheuliche Brutstätte der Vergangenheit angehört!', },
    {'Kehrt zu Aviana am Schrein von Aviana auf dem Hyjal zurück.', },
  },
  [25833] = {
    'Avianas Botschaft für Ysera',
    nil,
    {'Sprecht mit Ysera am Weltenbaum auf dem Hyjal.', },
  },
  [25834] = {
    'Stellvertreterkrieg',
    {'Hört Ihr sie dort unten kämpfen, $N? Anscheinend haben sich die Tauren der Grimmtotems mit der Horde überworfen. Ich weiß nicht, wie das geschehen ist, aber wir könnten es zu unserem Vorteil nutzen.|n|nIch werde ein Treffen mit dem Botschafter der Grimmtotems arrangieren. Ich möchte, dass Ihr eine Friedensgabe zusammenstellt.|n|n<Truppenkommandant Valen zeigt auf Kräcka.>|n|nRedet mit "Kräcka", $N. Er weiß bereits, was zu tun ist.', },
    {'Sprecht mit "Kräcka" Aschebäscha im Basislager der Nordwachtexpedition im Steinkrallengebirge.', },
  },
  [25835] = {
    'Den Freiwindposten befreien',
    {'Es ist an der Zeit, dass Ihr geht. Wie schnell die Küken aus dem Nest fallen – oder so ähnlich.|n|nWie dem auch sei, Ihr habt hier gute Arbeit geleistet, aber Quentin und die Nachtelfen haben einen Hilferuf ausgestoßen und benötigen dringend Unterstützung mit den Grimmtotems im Freiwindposten nordwestlich von hier.|n|nWenn Ihr mich fragt, da ist alle Hoffnung verloren, aber wer weiß... vielleicht können sie es mit Eurer Hilfe wirklich schaffen?', },
    {'Sprecht mit Quentin im Freiwindposten in Tausend Nadeln.', },
  },
  [25836] = {
    'Den Freiwindposten befreien',
    nil,
    {'Sprecht mit Thalia Bernhaut im Freiwindposten in Tausend Nadeln.', },
  },
  [25837] = {
    'Das perfekte Dinner',
    {'Für eine ordentliche Friedensgabe brauche ich folgende Zutaten:|n|nEier eines Kalimdoradlers. Ihr findet sie in den Nestern der Kalimdoradler. Sucht in dem Wald im Westen danach. Widderkeulen! Und zwar die Keulen des Steinkrallenwidders.|n|nDie letzte Zutat ist zwar schwer zu bekommen, aber wir brauchen sie für unser Widderlett. Reist nach Südwesten zur Steinschlagklamm und macht die Koboldhöhlen ausfindig. Tötet die Kobolde und stehlt ihren besonderen Käse.|n|nBringt alle Zutaten zu mir, dann werde ich ein Meisterwerk kochen!', },
    {'Sammelt 6 Eier von Kalimdoradlern, 8 Widderkeulen und 10 Stücke Steinschlagkäse.', },
  },
  [25838] = {
    'Hilfe aus Stahlrosts Depot',
    {'Dank Eurer Hilfe sind wir näher an die Zuflucht der Frostmähnen herangerückt. Unsere Streitkräfte werden bald in Position gehen und die Reserve der Frostmähnentrolle angreifen. Dann ist ihr Dorf ungeschützt.|n|nDas ist ein Fall für das Geheimteam Gnomeregan. Seine Techniker haben eine Möglichkeit gefunden, Kämpfer hinter die feindliche Linien zu bringen, ohne dass die Frostmähnen das bemerken. Begebt Euch zu Stahlrosts Depot nordöstlich der Stadt und sprecht mit Delber Kurbeldreh. Er wird Euch mehr darüber berichten.', },
    {'Sprecht mit Delber Kurbeldreh in Stahlrosts Depot.', },
  },
  [25839] = {
    'Das ultrasichere Personalabschussgerät!',
    {'Der Kataklysmus hat unsere Feinde näher gebracht, deshalb hat mich der Chef des Geheimdienstes von Gnomeregan gebeten, ein Gerät zu konstruieren, mit dem man Personal rasch und leise in jeden Teil Dun Moroghs transportieren kann.|n|nTataa, das ultrasichere Personalabschussgerät!|n|nMit nur einem Schuss Elektrizität und dank des SPE-Fallschirmsystems, äh, sehr späte Entfaltung für Laien, bringt Euch dieses Baby direkt zur Front. Steigt ein und bereitet Euch auf den Flug vor! Slamp Wackelrad erwartet Euch in der Landezone.', },
    {'Fliegt mit dem ultrasicheren Personalabschussgerät zur Zuflucht der Frostmähnen.', },
  },
  [25840] = {
    'Eliminiert den Widerstand',
    {'Der Häuptling der Frostmähnen starb beim ersten Angriff der Troggs. Seitdem werden sie von einem sehr respektierten Krieger angeführt. Battok der Berserker war derjenige, der den Rückzug der Frostmähnen organisierte, das neue Dorf errichten ließ und die Angriffe gegen Kharanos und die Gebirgsjäger führte.|n|nWenn wir Battok beseitigen, sollte Chaos unter den Frostmähnen ausbrechen. Dann können sich die Gebirgsjäger um die Überlebenden kümmern. Battok hält sich östlich von hier im Dorf auf.', },
    {'Tötet Battok den Berserker und 5 Krieger der Frostmähnen in der Zuflucht der Frostmähnen.', },
  },
  [25841] = {
    'Angriff von oben',
    {'Delbers Techniker haben Tag und Nacht gearbeitet, um uns bei den Vorbereitungen auf den Angriff zu helfen. Seine Leute haben nicht nur das Personalabschussgerät konstruiert und eingestellt, sondern auch das geheime Fliegergeschwader für den Angriff auf die Zuflucht der Frostmähnen vorbereitet. Sie warten auf das Signal zum Beginn ihrer Angriffe.|n|nNehmt dieses Leuchtfeuer und zündet es nahe der Gebäudegruppe am Nordrand des Dorfs und neben den Gebäuden am Südrand des Dorfs. Die Flugmaschinen werden an beiden Stellen zuschlagen.', },
    {'Benutzt das Signalleuchtfeuer, um Luftangriffe am nördlichen und südlichen Rand der Zuflucht der Frostmähnen anzufordern.', },
  },
  [25842] = {
    nil,
    {'Es ist… zu spät für mich. Bis auf den Kern ist alles verbrannt. Ich habe Äonen erlebt… und doch scheint mein Ende so plötzlich zu kommen.|n|nAus altem kann neues Leben entstehen. Ich habe immer noch meine Weisheit, die ich weitergeben kann. Bitte… Lasst nicht zu, dass sie mich wegbringen, bevor meine Arbeit getan ist.|n|nHaltet meine Peiniger zurück... nur noch eine Weile, $C.|n|nGebt mir ein paar Minuten und ich werde es mit tausenden Jahren vergelten.', },
    {'Tötet 5 feurige Peiniger, um sie von Nordu fernzuhalten.', },
  },
  [25843] = {
    'Tortollas Rache',
    nil,
    {'Sprecht mit Tortolla in der Verbrannten Ebene auf dem Hyjal.', },
  },
  [25844] = {
    'Sättigt die wilde Bestie',
    {'Ihr habt den Kommandanten gehört, $N. Bringt mir das perfekte Geschenk für den Botschafter der Grimmtotems! Er wartet mit seinem Trupp am unteren Ende des südöstlichen Pfads.|n|nDas sollte unser Ansehen bei ihrem Häuptling steigern!', },
    {'Bringt Ton Windbogen am Posten der Grimmtotems die fleischige Gabe.', },
  },
  [25845] = {
    'Forderungen',
    {'Die Grimmtotems brauchen Waffen! Die Horde hat dank ihres Kriegshäuptlings und der Hilfe ihrer neuen Goblinverbündeten mächtige Waffen angehäuft. Unsere Kriegswerkzeuge haben dieser Feuerkraft nichts entgegenzusetzen. Stattet die Grimmtotems mit starken Waffen aus, dann werden wir gemeinsam die Horde vernichten!|n|nDies sind unsere Forderungen! Versorgt die Grimmtotems, dann kämpfen wir für die Allianz!', },
    {'Bringt die Forderungen der Grimmtotems zu Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.', },
  },
  [25846] = {
    'Grundig Finsterwolke, Häuptling der Grimmtotems',
    {'Der Häuptling der Grimmtotems erwartet Euch, $N. Nehmt die Waffenkisten und brecht zum Posten der Grimmtotems südlich von hier auf.|n|nViel Glück, $N. Sollte Euch etwas zustoßen, werde ich persönlich Eure Angehörigen informieren und König Wrynn wissen lassen, was Ihr für die Allianz getan habt.', },
    {'Bringt die Waffenkisten der Allianz zu Grundig Finsterwolke am Posten der Grimmtotems im Steinkrallengebirge.', },
  },
  [25847] = {
    'Die Überlegenheit der Grimmtotems',
    {'Überall im Hochwipfeltal werden Grimmtotems von der Horde angegriffen. Höllschreis Armeen kennen weder Gnade noch Mitgefühl. Sie töten jeden, der ihnen im Weg steht.|n|nDas muss ein Ende haben! Nehmt das Kriegswerkzeug, das Ihr uns gebracht habt und sucht nach Grimmtotems, die gegen die Horde kämpfen. Gebt ihnen die Waffen der Allianz und seht zu, wie sie die Angreifer der Horde vernichten! Geht. Es gibt viel zu tun, $GVerbündeter:Verbündete;.', },
    {'Bewaffnet 12 Grimmtotems mit der Waffenkiste der Allianz.', },
  },
  [25848] = {
    'Niedergang',
    {'Als wir erfuhren, dass Höllschrei einen weiteren Orc der Mag\'har ausgesandt hatte, um die Hordentruppen im südlichen Steinkrallengebirge anzuführen, war es bereits zu spät. Camp Aparaje war niedergebrannt worden, alle Grimmtotems in dem Gebiet waren in den Flammen vergangen.|n|nVier der gefürchtetsten Hordengeneräle führen die Schlacht um das Hochwipfeltal an, unter ihnen auch der Mag\'hargeneral Glubgok.|n|nReist nach Süden, zu den Ruinen von Camp Aparaje, und tötet die Generäle. Wir halten die Horde JETZT auf! Kehrt zu mir mit ihrem Zeichen zurück!', },
    {'Tötet die Hordengeneräle in Camp Aparaje und erbeutet das Insigne des Hordengenerals.', },
  },
  [25849] = {
    'Angriff der Archäologie',
    {'Hört zu, $Gmein Freund:meine Liebe;, jeder gute Archäologe kennt die Risiken seines Berufs. Wenn man nicht wenigstens einmal in seiner Karriere einen uralten Dämon ausgräbt oder von einem boshaften Geist verflucht wird, dann sucht man nur nach Plunder!|n|nWahre Archäologen wissen, dass Kleinigkeiten wie versteinerte Knochen, die zu Skelettkriegern reanimiert werden, kein Grund sind, die Arbeit einzustellen.|n|nDiese versteinerten Knochen brauche ich. Erbeutet sie von den Fossilienmonstern, die in der Gegend umherstreunen und bringt sie mir. Ich werde Euch belohnen.', },
    {'Erbeutet 20 versteinerte Knochen von lebenden Fossilien.', },
  },
  [25850] = {
    'Schlagt die Erde!',
    {'Falls es Euch entgangen sein sollte, das Land hier im Sumpfland ist ziemlich chaotisch. Überflutungen, Erdbeben... und jetzt wird auch noch der Boden wild.|n|nIch hätte nie geglaubt, dass wir einmal von unserer Grabungsstelle angegriffen werden würden, aber seit kurzem laufen Erdschollen Amok und versuchen, jeden Zwerg zu zerquetschen, den sie finden können.|n|nIhr seht jung und kräftig aus, <Volk>... würdet Ihr dort hinunter gehen und diesen Klumpen etwas Verstand einprügeln?', },
    {'Tötet 7 paläolithische Elementare.', },
  },
  [25851] = {
    'Der mit den Grimmtotems tanzt',
    {'Kehrt zu Eurem Anführer zurück und berichtet ihm, was Ihr für die Grimmtotems getan habt. Sagt ihm, dass unsere Grenzen von nun an für die Allianz geöffnet sind.', },
    {'Meldet Euch bei Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.', },
  },
  [25852] = {
    'Alles frei',
    {'Packt Eure Sachen, $N, wir werden uns jetzt den restlichen Streitkräften der Nordwacht im Südlichen Brachland anschließen. Eure erste Mission im Südlichen Brachland sollte recht unkompliziert sein.|n|nVor zwei Tagen erreichte uns ein Notruf von Kommandant Walpole. Man hat ihn und sein Bataillon auf dem Steinkrallenpass außerhalb von Ehrenwacht eingekesselt. Die Horde ist überall! Geht dorthin und helft ihm. Ich werde das Nordwachenkommando von unserer Allianz mit den Grimmtotems in Kenntnis setzen.', },
    {'Meldet Euch bei Kommandant Thomas Walpole auf dem Steinkrallenpass im Südlichen Brachland.', },
  },
  [25853] = {
    'Ohne Hut und Peitsche',
    {'Ich bin für die Ausrüstung dieser Ausgrabungsstätte verantwortlich. Das läuft ganz gut, aber die schnelle Abreise hat uns nicht gut getan!|n|nArchäologen brauchen schließlich Werkzeuge. Man kann unbezahlbare Antiquitäten nicht mit den Händen ausgraben. Wenn Ihr zur Ausgrabungsstätte reist, könntet Ihr uns das Werkzeug, das zurückgelassen wurde, mitbringen?', },
    {'Beschafft 6 Archäologenwerkzeuge.', },
  },
  [25854] = {
    'Ich nenne ihn Bisschen',
    {'Wusstet Ihr, dass manche Raptoren so intelligent sind, dass man sie zähmen kann? Das stimmt! Ich habe Jäger gesehen, die das getan haben.|n|nEs ist hier draußen ziemlich einsam, auch wenn Wenna mir Gesellschaft leistet... ein Haustier würde vielleicht meine Stimmung heben. Ein kleines Raptorbaby wäre toll!|n|nWenn Ihr ohnehin gerade dort draußen die Erwachsenen abschlachtet, könntet Ihr mir einige ausgebrütete Eier mitbringen? Die Eier wackeln, wenn die Babys schlüpfbereit sind.', },
    {'Beschafft sechs wackelnde Raptoreneier.', },
  },
  [25855] = {
    'Dingsdabumse',
    {'In letzter Zeit fehlen mir ständig Teile für meine Ingenieurskunstprojekte, und nun habe ich den Grund dafür entdeckt. Die Moosfellgnolle stehlen sie!|n|nIch weiß nicht, was sie damit wollen, aber ich muss diese Dingsdas wiederhaben. Wahrscheinlich liegen sie überall in den Sümpfen herum. Würdet Ihr sie mir mitbringen, wenn Ihr welche seht?', },
    {'Findet 7 Dingsdas der Schnellschalts.', },
  },
  [25856] = {
    'Krokiliskenbälge',
    {'Seit Jahren häute ich Krokis im Sumpfland, $C. Es hat sich jedoch viel verändert.|n|nIch will nicht auf die Tränendrüse drücken, aber als der Kataklysmus den Hafen von Menethil überflutete, riss er auch unser Haus mit sich. Meine Frau und meine Kinder wissen nicht, wo sie bleiben sollen, und ich muss so viel Geld wie möglich verdienen, damit wir bald wieder ein Dach über dem Kopf haben.|n|nIch habe Krokis gehäutet, bis ich vor Müdigkeit umgefallen bin, aber ich brauche noch mehr Häute für den Verkauf. Bringt mir ein paar Krokibälge. Ich zahle Euch auch ein wenig dafür.', },
    {'Erbeutet 10 Marschenkrokiliskenbälge von Sumpflandkrokilisken.', },
  },
  [25857] = {
    'Jagt Horrorkiefer',
    {'Es juckt mir in den Fingern, eine große Beute zu jagen... Horrorkiefer, den größten Krokilisken dort draußen. Mit seinem Balg könnte ich meine Familie aus diesem Loch holen.|n|nAber ich bin kein Narr. Ein Fehler reicht, um ein Bein oder gar mein Leben zu verlieren. Was würden meine Frau und Kinder dann tun? Sie wären immer noch obdachlos und die Kinder hätten keinen Vater mehr, der sich um sie kümmert.|n|nIch bin nicht stolz darauf, aber für die Sicherheit meiner Familie schlucke ich meinen Stolz hinunter. Bitte, $C... jagt Horrorkiefer für mich. Er lauert im Norden, in seinem schattigen Tümpel.', },
    {'Tötet Horrorkiefer und erbeutet Horrorkiefers Haut.', },
  },
  [25858] = {
    'Im Namen der Lady',
    {'Lady Sira\'kess hat mit den Vorbereitungen für das Beschwörungsritual begonnen, aber der Schmelztiegel von Nazsharin wurde uns gestohlen. Sicher haben die Kvaldir ihn mit sich genommen, als sie sich in flachere Gewässer zurückgezogen haben.|n|nSprecht mit den Anführern der Kasten, um einen Kriegstrupp zusammenzustellen. Führt sie dann zum Biel\'arangrat im Osten, um das Artefakt wiederzuholen.|n|nIch vertraue Euch, meine Kriegsmaid, denn Ihr habt mich noch nie enttäuscht, ganz gleich, welche Aufgabe ich Euch gab. So sehr die Königin mich schätzt, so sehr schätze ich Euch. Geht mit meinem Segen.', },
    {'Sprecht mit Tiefenlord Zin\'jatar, Lady Sira\'kess und Aufseher Idra\'kess.|n|nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz\'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz\'jar an einem Zeitfokus.', },
  },
  [25859] = {
    'Keine Vergebung',
    {'Ich weiß, dass Ihr genau wie unsere ehrwürdige Lady gelegentlich leider Anflügen von Mitleid unterliegt. Am heutigen Tage möchte ich Euch jedoch raten, diese Freundlichkeiten zu unterlassen. Die Kvaldir sind stolz. Wenn wir sie nicht komplett vernichten, werden sie ganz sicher Rache nehmen. Tötet alle, die Ihr finden könnt.|n|nLeider habe ich die ruhmlose Aufgabe sicherzustellen, dass keiner in die Stadt zurückkehrt, sodass ich Euch den ganzen Spaß überlassen muss. Ich werde Euch aber natürlich anfeuern.', },
    {'Tötet 20 Kvaldir auf der Vrykulklippe.|n|nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz\'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz\'jar an einem Zeitfokus.', },
  },
  [25860] = {
    'Koste es, was es wolle',
    {'Wir beginnen sofort mit dem Ritual. Ihr werdet Euch darum kümmern, dass niemand uns unterbricht.|n|nErschlagt alle Kvaldir, die den Tempel betreten. Achtet darauf, dass meine Priesterinnen überleben, um ihre Aufgabe zu Ende zu bringen. Koste es, was es wolle.', },
    {'Tötet 20 Angreifer der Kvaldir im Tempel von Quel\'Dormir.|n|nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz\'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz\'jar an einem Zeitfokus.', },
  },
  [25861] = {
    'Ein Exempel statuieren',
    {'Die Hochschamanen befinden sich in den Gebäuden in der Nähe und singen und spotten, trauen sich aber nicht, näher zu kommen. Diese Kvaldir sind nur mutig, wenn sie sich im Nebel verstecken können. Ein erbärmliches Ärgernis unter den Wellen.|n|nIch bringe eine Nachricht. Wenn Ihr die Zeit fändet, gnädige Frau, dann bringt mir einen Hochschamanen und werft ihn mir zu Füßen, auf dass ich ihm und seinem Volk meine Nachricht überbringen kann.', },
    {'Bringt einen Hochschamanen der Kvaldir zu Henker Verathress\' Füßen.|n|nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz\'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz\'jar an einem Zeitfokus.', },
  },
  [25862] = {
    'Gestohlenes Eigentum',
    {'Unsere ehrwürdige Lady hat mich geschickt, um Euch bei Eurer Aufgabe zu helfen. Sie möchte, dass Ihr den gestohlenen Schmelztiegel von Nazsharin wiederbeschafft und so schnell wie möglich hierher bringt.|n|nSie kann es kaum erwarten, das Beschwörungsritual durchzuführen, damit wir endlich voll und ganz mit unseren Kriegsvorbereitungen beginnen können.', },
    {'Besorgt den Schmelztiegel von Nazsharin.|n|nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz\'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz\'jar an einem Zeitfokus.', },
  },
  [25863] = {
    'Freiwillige Last',
    {'Jetzt, da Ihr den Schmelztiegel von Nazsharin an Euch gebracht habt, müsst Ihr nur noch Lady Naz\'jar von Eurem Erfolg berichten.', },
    {'Kehrt mit Euren Nachrichten vom Schmelztiegel von Nazsharin zum westlichen Ende des Biel\'arangrats zurück.|n|nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz\'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz\'jar an einem Zeitfokus.', },
  },
  [25864] = {
    'Dinosaurierkrise',
    {'Ständig erreichen uns Berichte über Raptorangriffe in der Gegend. Ich muss hier für Sicherheit sorgen, damit mehr Siedler kommen. Aus diesem Grund habe ich ein Kopfgeld auf diese Viecher ausgesetzt.|n|nViele wurden bereits beseitigt, aber die Hochlandraptoren im Norden vermehren sich stark. Aber das wird sich bald ändern, nicht wahr?|n|nErledigt ein paar Hochlandraptoren, dann gebe ich Euch eine hübsche Belohnung.', },
    {'Tötet 8 beliebige Hochlandraptoren.', },
  },
  [25865] = {
    'Die Moosfellmission',
    nil,
    {'Beschafft 8 Barren von Eisenschmiede von den Gnollen der Moosfelle.', },
  },
  [25866] = {
    'Fallensteller der Dunkeleisenzwerge',
    {'Der Klan der Dunkeleisenzwerge ist in diesem Gebiet gesehen worden. Vielleicht sind sie Euch schon über den Weg gelaufen. Sie führen nie Gutes im Schilde, und dieses Mal scheinen sie aus irgendeinem Grund Moosfellgnolle zu entführen.|n|nIch weiß nicht, was das soll, aber wir müssen sie aufhalten, bevor noch üblere Dinge geschehen. Haltet sie auf.|n|nWenn Ihr Euch Sorgen macht, weil das unfair ist, könnt Ihr sie ja zuerst höflich fragen. Mal sehen, wie weit Ihr damit kommt.', },
    {'Tötet 10 Fallensteller der Dunkeleisenzwerge.', },
  },
  [25867] = {
    'Die Flucht der Gnolle',
    {'Ich weiß, dass wir selbst gerade die Gnolle angegriffen haben, aber ich werde nicht zulassen, dass die Dunkeleisenzwerge sie als Sklaven halten. Zum einen haben wir die Diebe gefunden und unseren Besitz zurückerhalten, also wurde der Gerechtigkeit Genüge getan. Zum anderen werden die Dunkeleisenzwerge sie bestimmt nicht für gemeinnützige Arbeiten einsetzen... |n|nAlso müssen die Gnolle befreit werden. Die Fallensteller sollten die Schlüssel, mit denen man die Käfige öffnen kann, bei sich tragen.', },
    {'Erbeutet den Schlüssel des Fallenstellers von Fallenstellern der Dunkeleisenzwerge und befreit damit 6 Gnolle aus den Gnollkäfigen.', },
  },
  [25868] = {
    'Yorla Dunkelschlinge',
    {'Ich habe herausgefunden, wer bei dieser Operation im Hintergrund die Fäden zieht. Yorla Dunkelschlinge führt die Dunkeleisenzwerge von einem Lager im Osten an. Wahrscheinlich hat sie den Gnollen befohlen, das Gold aus Eisenschmiede zu stehlen.|n|nAußerdem ist sie eine gesuchte Kriminelle... Schon als Magni noch lebte, schürte sie Rebellionen und Angriffe gegen Eisenschmiede.|n|nDieses Mal wird sie uns nicht durch die Lappen gehen, $N. Schnappt sie Euch!', },
    {'Tötet Yorla Dunkelschlinge.', },
  },
  [25869] = {
    'Grimmtotems im Freiwindposten',
    {'Die Reise, die vor uns liegt, beginnt damit, dass Ihr alle Eindringlinge der Grimmtotems im Freiwindposten tötet. Wenn Ihr sie hier nicht aufhalten könnt, werden wir nicht in der Lage sein, bis zu ihrem Territorium vorzudringen.', },
    {'Tötet 10 Eindringlinge der Grimmtotems.', },
  },
  [25870] = {
    'Grimmtotems im Freiwindposten',
    {'Ihr müsst die Eindringlinge der Grimmtotems im Freiwindposten loswerden. Das haben sie sich aber selbst zuzuschreiben, diese Feiglinge!|n|nWir können nicht zulassen, dass die Schlacht in ihre eigenen Gebiete verlagert wird, und wir sprichwörtlich mit dem Rücken zu ihnen stehen. Bitte helft uns, unsere Heimat zurückzuerlangen, $C.', },
    {'Tötet 10 Eindringlinge der Grimmtotems.', },
  },
  [25871] = {
    'Rettet die Schildwache',
    {'<Brienna wedelt mit einer Notiz, die Markierungen in Taurahe aufweist.>|n|nDiese Monster haben eine unserer Schildwachen gefangen! Sie drohen damit, sie zu töten, wenn wir uns nicht zurückziehen!|n|nWir verhandeln nicht mit feigen Bestien! Bitte $C, könnt Ihr versuchen, die Schildwache zu retten, bevor es zu spät ist?', },
    {'Rettet die Schildwache von Feralas.', },
  },
  [25872] = {
    'Der Kriegerheld und die Wagemütigen',
    {'<Rau wedelt verärgert mit einer Notiz, die Markierungen in Taurahe aufweist.>|n|nDiese Monster haben einen unserer Kriegerhelden gefangen! Sie drohen damit, ihn zu töten, wenn wir uns nicht zurückziehen!|n|nWir werden diesen feigen Grimmtotems nie gestatten, den Freiwindposten zu behalten! Bitte $C, rettet ihn, bevor es zu spät ist.', },
    {'Retten den Kriegerheld des Freiwindpostens.', },
  },
  [25873] = {
    'Das Horn des Verräters',
    {'Hier liegt der gebrochene Leichnam von Montarr, dem Bewahrer der Lehren des Freiwindpostens. Der Körper des alten Tauren ist gebrochen und in einer Pfütze seines eigenen Blutes.|n|nBlutspuren führen zurück zum Gasthaus...', },
    {'Erhaltet Langhorns Horn.', },
  },
  [25874] = {
    'Das Horn des Verräters',
    {'Hier liegt der gebrochene Leichnam von Montarr, dem Bewahrer der Lehren des Freiwindpostens. Der Körper des alten Tauren ist gebrochen und in einer Pfütze seines eigenen Blutes.|n|nBlutspuren führen zurück zum Gasthaus...', },
    {'Erhaltet Langhorns Horn.', },
  },
  [25875] = {
    'Der eingeschleuste Gnom',
    {'Am Mirkfallonsee wimmelt es von der Horde. Die Goblins haben sich dort eingenistet, und sie werden erst wieder abziehen, wenn sie das gesamte Öl unter dem Steinkrallengebirge ausgesaugt haben.|n|nZum Glück konnte ich einen Gnom einschleusen, der Informationen für uns sammelt. Wenn irgendjemand weiß, was es mit dieser Bombe auf sich hat, dann mein eingeschleuster Gnom.|n|nGeht zu den Schlickwerken im Norden und findet Minx. Sie hat sich als "Goblin" Pumpenkontrolleur getarnt.', },
    {'Sucht in den Schlickwerken im Steinkrallengebirge nach Minx. Sie hat sich als "Goblin" Pumpenkontrolleur getarnt.', },
  },
  [25876] = {
    'Sie ist da oben!',
    {'Ich folge dieser Bombe, seit Ihr mich in Eschental gerettet habt. Was auch immer sie damit vorhaben, wird bald geschehen.|n|nGanz oben auf der großen Ölplattform gibt es einen Kontrollraum. Im Kontrollraum werdet Ihr das Logbuch von Krom\'gar finden. Dieses Logbuch ist der Schlüssel zum Ziel der Bombe. Geht nach oben und holt das Logbuch! Bringt es hierher. Ich werde es für Euch dechiffrieren.', },
    {'Stehlt das Logbuch von Krom\'gar.', },
  },
  [25877] = {
    'Keine Zeit für Verabschiedungen!',
    {'LAUFT! Verschwindet hier, $N. Sucht Barus auf und sagt ihm, was Ihr herausgefunden habt. Er wird dafür sorgen, dass Ihr sicher durch das Kriegsnarbental zur Aussicht von Thal\'darah gelangt.|n|nFür diese jungen Druiden ist es noch nicht zu spät!', },
    {'Kehrt zu Späherkommandant Barus am Mirkfallonposten im Steinkrallengebirge zurück.', },
  },
  [25878] = {
    'Anleitung zur Sabotage',
    {'Goblins... Was wäre die Welt ohne Goblins? Das kann ich Euch sagen: SAUBER!|n|nDiese schmutzigen kleinen Unholde haben überall auf dem See Ölpumpen errichtet, mit denen sie das Öl im Streinkrallengebirge bis auf den letzten Tropfen abzapfen wollen. An jeder Ölpumpe steht ein Ölpumpenkontrolleur, der darauf achtet, dass die Pumpe läuft und nichts schief geht.|n|nAber etwas wird schiefgehen.|n|nBeseitigt die Goblinpumpenkontrolleure und nehmt ihre Pumpensteuerung. Überlastet damit die Pumpen!', },
    {'Zerstört 4 Goblinölpumpen mit der Goblinpumpensteuerung.', },
  },
  [25879] = {
    'Ärger mit den Trampeln',
    {'Schon mal einen Hobgoblin gesehen? Das ist wieder so eine eklige Schöpfung der Goblins. Nehmt einen Goblin, macht ihn noch hässlicher, fetter, größer und dümmer, und heraus kommt ein Hobgoblin. Fügt dem noch einen miesen Charakter hinzu, dann versteht Ihr das Problem.|n|nDiese Trampel lungern an den Schlickwerken und am Mirkfallonsee herum. Die Goblins setzen sie als Wächter ein.|n|nGeht dorthin und dünnt sie etwas aus. Unwiderruflich.', },
    {'Tötet 10 Trampel.', },
  },
  [25880] = {
    'Warnt Meister Thal\'darah',
    {'Im Hain von Thal\'darah leben Dutzende Schüler. Die meisten können sich nicht wehren. Man wird sie abschlachten.|n|nInformiert Meister Thal\'darah über die Pläne der Horde. Er wird Euch erklären, was als Nächstes zu tun ist.|n|nFiora Mondsegler hat Euch ihren schnellsten Hippogryph gegeben. Fliegt damit zur Aussicht von Thal\'darah! Seht nicht zurück, $N! Die Horde muss aufgehalten werden!', },
    {'Meldet Euch bei Meister Thal\'darah an der Aussicht von Thal\'darah im Steinkrallengebirge.', },
  },
  [25881] = {
    'Verschollene Wächter',
    {'Wir haben so lange durchgehalten wie es ging, $C. Aber die Flammen… die Hitze… Wir haben die Stadt ganz verloren.|n|nHauptmann Eisenstamm hat sich geweigert, zum Rückzug zu blasen, als die Flammen uns eingeschlossen haben. Unsere Truppen sind überall verstreut. Vielleicht haben ein paar der anderen überlebt? Wir könnten einen Gegenangriff starten!|n|nReist in die Verbrannte Ebene und rettet alle verschollenen Wächter, die von ihrer Gruppe getrennt wurden. Dann sucht nach Hauptmann Eisenstamm. Er befindet sich wahrscheinlich mitten im Kampfgetümmel.', },
    {'Findet und rettet 8 verschollene Wächter.', },
  },
  [25882] = {
    'Hilfe für das Gehöft',
    {'Hauptmann Tharran hat mich gebeten, Euch seinen Dank für Eure Hilfe und seine Glückwünsche zur erfolgreichen Mission auszurichten. Er kümmert sich mit seinen Männern um die letzten Trolle und versorgt die Verwundeten.|n|nEr hat mich auch gebeten, Euch zu fragen, ob Ihr Berichten über Trollüberfälle auf dem Gehöft Bernruh im Norden nachgehen könntet. Fragt nach Unteroffizier Flinthammer, wenn Ihr dort eintrefft.', },
    {'Sprecht mit Unteroffizier Flinthammer auf dem Gehöft Bernruh.', },
  },
  [25883] = {
    'Entwaffnend',
    {'Nagawaffen…|n|nAls Ihr Euren Blick über die Pferche streifen lasst, seht Ihr Dutzende ähnlicher Dreizackstapel, die strategisch positioniert zu sein scheinen.|n|nIhre Waffen zu zerstören behindert sicher die bösen Pläne, die sie in dieser Gegend verfolgen...', },
    {'Zerstört 6 Dreizackstapel der Naga.', },
  },
  [25884] = {
    'Auf Biegen und Brechen',
    {'Himmeldonnerwetter nochmal...|n|nIch weiß, dass unser Schiffbrüchiger hier es gut meint, aber der Junge ist doch schwerst traumatisiert.|n|nEs gibt nur eine Methode, wie man mit diesen verflixten Biestern fertig wird, und zwar indem man ihnen eine anständige Zwergenaxt bis zum Anschlag in den Schädel rammt.|n|nJe mehr Leichen ihrer Kameraden man vor ihnen aufstapelt, desto genauer werden sie es sich überleg\'n, einem ans Leder zu geh\'n.|n|nDas könnt Ihr mir glaub\'n, $GKumpel:Mädel;, die Burschen mög\'n den Anblick ihres eigenen Blutes genausowenig wie Ihr oder ich.|n|nUnd jetzt ab mit Euch und zeigt denen, was \'ne Harke ist!', },
    {'Tötet 12 Naga des Zin\'jatar in der Umklammerung im Tang\'tharwald.', },
  },
  [25885] = {
    'Keine Macht den Algen',
    {'Wa… was IST das?!|n|nIch habe so starke Schmerzen… tief in meinem Bauch.|n|nIch glaube… uff… Sie müssen mich vergiftet haben!|n|nSie haben uns merkwürdig leuchtende Algen zu essen gegeben, die sie um ihre Festung herum anbauen…|n|nIch glaube, diese Krämpfe werden immer schlimmer, wenn ich nicht bald mehr davon bekomme...|n|nBitte, <Volk>. Bringt mir etwas davon!', },
    {'Sammelt 7 Schlängelgrassprösslinge von Erntern der Schimmerrücken in der Umklammerung.', },
  },
  [25886] = {
    'Den Vorteil nutzen',
    {'Wie es scheint, hat ein Großteil des Schattenhammers sich zurückfallen lassen, um sich für einen weiteren Angriff neu zu formieren. Nur ihre besten Kämpfer halten noch die Front. Dies ist unsere Gelegenheit, um ihren Anführern den Garaus zu machen.|n|nSchwärmt aus über die Verbrannte Ebene und vernichtet die Zwielichtfeldhauptmänner. Wir werden sie von dieser Welt tilgen!', },
    {'Tötet 4 Zwielichtfeldhauptmänner.', },
  },
  [25887] = {
    'Welle der Zerstörung',
    {'Unsere Zeit hier neigt sich dem Ende zu. Ich muss diesen Nagaflüchtlingen irgendwie folgen, wenn wir herausfinden wollen, was sie in dieser Gegend vorhaben.|n|nAber bevor ich weiterziehe will ich sehen, wie dieser Ort hier vernichtet wird!|n|nEgal, wie viele es sind, ich habe einen Plan, der für Chancengleichheit sorgen wird.|n|nAußerhalb der Höhle suchen ausgemergelte große Haie, die von den Naga vertrieben wurden, nach Nahrung.|n|nIn ihrem geschwächten Zustand sind sie für Anregungen sehr empfänglich. Benutzt diese Kugel, um sie zu unterwerfen und hetzt sie dann direkt auf unseren Feind.', },
    {'Benutzt die Kugel der Anregung, um einen ausgemergelten großen Hai zu unterwerfen und benutzt ihn dann, um 12 Gefolgsleute des Zin\'jatar in der Umklammerung zu töten.', },
  },
  [25888] = {
    nil,
    {'Ich kann den Gedanken einfach nicht ertragen, dass so viele andere wie dieser Soldat inmitten von Naga eingesperrt sind.|n|nWir müssen etwas unternehmen, um sie zu retten!|n|nNehmt dies, $N. Wendet es an den Gefängniszellen an, um ihnen Auftrieb zu verleihen.|n|nWenn wir sie an die Oberfläche bringen können, haben sie wenigstens eine Hoffnung auf Rettung.', },
    {'Benutzt Moanahs Atemstein an 10 eingekerkerten Soldaten in der Umklammerung.', },
  },
  [25889] = {
    'Rettet die Kinder!',
    {'Meine armen, hilflosen Schüler sitzen im Hain von Thal\'darah fest. Wegen der Schlacht, die im Kriegsnarbental tobt, können sie nicht entkommen. Wir müssen die Kinder retten, bevor die Horde ihre Bombe abwirft!|n|nNehmt meinen Hippogryph und rettet damit die jungen Druiden im Hain von Thal\'darah. Setzt sie am Hippogryphenposten hier in der Stadt ab.|n|nRettet sie alle, $N! Ihr seid wahrlich unsere einzige Hoffnung.', },
    {'Rettet mit Meister Thal\'darahs Hippogryph 5 hilflose junge Druiden aus dem Hain von Thal\'darah.', },
  },
  [25890] = {
    nil,
    {'Jetzt ist mir klar, was wir tun müssen, $N.|n|nDie Naga können diese Perlen nur von einem Ort haben: Nespirah, das uralte Schalenwesen, das außerhalb dieser Höhle ruht. Warum Nespirah sich den Naga unterwirft, ist mir allerdings schleierhaft.|n|nWir können durch eine kleine Röhre in der Nähe des Ausgangs dieser Höhle in Nespirahs Körper eindringen. Ich muss zuerst noch meinen Meister holen, danach können wir uns im Inneren treffen. Wir werden Nespirah durch den nordwestlichen Eingang betreten.', },
    {'Betretet Nespirahs nordwestlichen Eingang und findet dann einen Weg, um mit ihr zu sprechen.', },
  },
  [25891] = {
    'Eine Letzte Anstrengung',
    {'Die Horde signalisiert den Rückzug. Seht, wie sie das Schlachtfeld verlassen - das ist der Vorbote einer Katastrophe.|n|nWir müssen ein letztes Mal im Hain von Thal\'darah landen. Ich würde es nicht ertragen, wenn auch nur ein junger Druide zurückbleiben müsste.|n|nHelft mir, $GHeld:Heldin;. Ich nehme die Zügel. Sucht Ihr nach Druiden, die vielleicht zurückgelassen wurden.|n|nWir brechen auf, wenn Ihr bereit seid.', },
    {'Helft Meister Thal\'darah bei der Suche nach Druiden, die im Hain von Thal\'darah zurückgelassen wurden.', },
  },
  [25892] = {
    'Haltlos',
    {'Ihr müsst mich später auf den neusten Stand bringen. Im Augenblick müssen wir hier verschwinden, bevor weitere Naga vorrücken. Begebt Euch zum Vorposten auf der Ebene unter uns.|n|nNehmt mein Seepferdchen. Wir treffen uns dort in Kürze.', },
    {'Benutzt Wellensprecherin Valorens Seepferd, um zu Admiral Dvorek unter der südlichen Terrasse in den Ruinen von Vashj\'ir zurückzukehren.', },
  },
  [25893] = {
    'Ein verzweifelter Plan',
    {'Jorlan und Hexasept sind aufgebrochen, um Hilfe zu holen. Die Handelsrouten sind nicht weit entfernt, daher besteht die Chance, dass sie Erfolg haben. Ich wage es jedoch nicht, den anderen zu viel Hoffnung zu machen.|n|nOffen gestanden haben wir keine andere Wahl. Früher oder später werden die Naga uns finden und... nun... Ihr habt selbst gesehen, wie viele es sind.|n|nIhr solltet die beiden auf dem Biel\'arangrat im Südosten suchen. Ich kümmere mich solange so gut es geht um die Sicherheit der anderen hier.', },
    {'Trefft Euch mit Ingenieur Hexasept auf dem Biel\'arangrat.', },
  },
  [25894] = {
    'Feindliche Gewässer',
    {'Hexasept kam mit einer Art Ballon hierher, den er von einem unserer Schiffe gerettet hat. Er hat versucht, damit nach oben zu schweben, aber diese Schlickhautschnorrer kamen aus dem Nichts und haben das Ding umschwärmt.|n|nJetzt hat er eine Idee für einen weiteren Ballon, aber wir müssen sicherstellen, dass es nicht wieder genauso abläuft. Ihr müsst diese Kiemengoblins töten. Oder zumindest so viele, dass sie etwas mehr Angst vor uns haben.', },
    {'Tötet 10 Schlickhautschnorrer.', },
  },
  [25895] = {
    'Immer vorbereitet',
    {'Wir müssen immer vorbereitet sein. Wir müssen Ausrüstung haben. Wir müssen Pläne haben!|n|nAlle Schiffe in der Flotte der Allianz sind mit einer Überlebensausrüstung ausgestattet. Viele unserer Werkzeuge stammen aus so einer Überlebensausrüstung. Mein Ballon war auch in so einer Überlebensausrüstung enthalten! Aber jetzt ist sie aufgebraucht. Ich brauche noch eine Überlebensausrüstung!|n|nSüdöstlich von hier liegt ein Schiff. Wollen wir hoffen, dass die Überlebenden dumm genug waren und die Überlebensausrüstung nicht mitgenommen haben. Mehr zum Überleben für uns!', },
    {'Besorgt eine Überlebensausrüstung der Allianz.', },
  },
  [25896] = {
    'Andächtige Versammlung',
    {'Ah, Kriegsmaid. Das Wort und der Wille unserer Lady sind mit Euch. Ich möchte Euch um einen Gefallen bitten…|n|nTiefenrufer Azrajar und meine Gezeitenpriesterinnen müssen zurückkehren, damit wir mit dem Ritual beginnen können. Könnt Ihr ihnen meinen Wunsch überbringen? Ihr solltet sie auf der Tempelterrasse und den Treppen unten finden. Azrajar hält sich an der Treppe im Norden auf.', },
    {'Sucht Tiefenrufer Azrajar in der Mitte der nördlichen Treppe sowie 6 Gezeitenpriesterinnen der Sira\'kess auf der oberen Ebene der Ruinen und tragt ihnen auf, zum Tempel zurückzukehren.|n|nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz\'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz\'jar an einem Zeitfokus.', },
  },
  [25897] = {
    'Seilakrobatik',
    {'In Überlebensausrüstungen sind nie Seile enthalten. Das ergibt doch keinen Sinn! Überhaupt keinen!|n|nIch wette, diese Kvaldir haben Seile. Sie fahren immer in Booten herum, knüpfen Knoten und ziehen sich sogar Netze an. Geht und stehlt ihnen ein paar Seile! Ich brauche dringend welche für meinen Plan. Unbedingt!', },
    {'Sammelt 8 Kvaldirseile.', },
  },
  [25898] = {
    'Ehre und Privileg',
    {'Fertig! Ich bin mir ganz sicher, dass es funktionieren wird. Und nicht ein Schnorrer in Sicht, der wieder ein Loch hineinstoßen könnte! Welch günstiger Zufall.|n|nJorlan ist bereits nach oben geschwommen, um ihn zu packen. Ist hochgeschwommen und wartet jetzt dort. Er meinte aber, er würde Euch die Ehre überlassen. So ist Jorlan eben.|n|nSchwimmt zum Ballon an der Oberfläche, nehmt die Leuchtpistole aus der Kiste und haltet am Horizont nach Schiffen der Allianz Ausschau. Wenn Ihr welche seht, schießt das Leuchtfeuer in ihre Richtung. Das war es auch schon!|n|nAuftauchen, Schwimmen, Signalfeuer, Rettung! Der letzte Teil gefällt mir am besten.', },
    {'Schwimmt zur Oberfläche, holt die Leuchtpistole und feuert ein Rettungsleuchtfeuer in Richtung der Allianzschiffe.', },
  },
  [25899] = {
    nil,
    {'Die flammende Armee, die oben auf dem Hügel so viel Verwüstung angerichtet hat, hat sich in den Osten zurückgezogen. Nur die sengenden Fürsten sind noch zugange. Wenn wir ihre Reihen durchbrechen könnten, um uns mit Hauptmann Eisenstamms Truppen zusammenzutun, könnte ihre gesamte Offensive scheitern.|n|n$C, ich bin nicht in der körperlichen Verfassung, noch weiter zu kämpfen, aber Ihr seht aus, als könntet Ihr ihnen noch die ein oder andere Blessur zufügen. Tötet diese sengenden Fürsten und formiert Euch mit Hauptmann Eisenstamm neu!', },
    {'Tötet 10 sengende Zwielichtfürsten.', },
  },
  [25900] = {
    'Kontaktaufnahme',
    {'Ich kann mir kaum vorstellen, dass Nespirah freiwillig zulässt, dass diese Naga in ihrer Schale ihr Lager aufschlagen. So wie ich das sehe, ist eines von zwei Dingen geschehen: Entweder haben sie sie überzeugt, sich ihrer Sache anzuschließen, oder sie haben sie so geschwächt, dass sie sich nicht wehren kann. Beide Möglichkeiten sind nicht gut.|n|nHier in diesem Raum sollte ich direkt mit Nespirah kommunizieren können. Finden wir es also selbst heraus. Sprecht mit mir, wenn Ihr bereit seid, $C.', },
    {'Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.', },
  },
  [25901] = {
    'Wiederverwertung auf dem Hyjal',
    {'Verstärkung! Ich dachte, wir müssen hier bis zum bitteren Ende kämpfen.|n|nEs sind nur noch wenige Wächter des Hyjal übrig. Zudem gehen uns langsam aber sicher die Vorräte aus. Auf dem Schlachtfeld um unsere letzte Bastion herum sollte eine Unmenge noch funktionstüchtiger Pfeile herumliegen.|n|nIch weiß, dass es für jemanden mit Euren Fähigkeiten fast schon lächerlich einfach ist, aber könntet Ihr unsere gebrauchte Munition aufsammeln? Nur so können wir unsere Vorräte aufstocken.', },
    {'Sammelt 15 Pfeile des Aufsehers.', },
  },
  [25902] = {
    'Euer erstes Totem!',
    nil,
    nil,
  },
  [25904] = {
    'Der Hammer und der Schlüssel',
    {'Meine Nemesis. Ist noch am Leben.|nDie Diener des Feuers noch auf dem Vormarsch.|nWir müssen ihnen folgen. In ihren Bau.|n|nDie Oger kennen den Weg.|nTötet die Feldhauptmänner.|n|nBergt die Glyphe des Öffnens.|n|nSo soll es sein.', },
    {'Tötet einen Zwielichtfeldhauptmann und besorgt Euch die Glyphe des Öffnens.', },
  },
  [25905] = {
    'Widder auf der Flucht',
    {'Die Widder, die wir hier auf dem Gehöft Bernruh züchten und ausbilden, werden von den Gebirgsjägern von Dun Morogh als Reittiere verwendet. Ja, es sind ein paar hier, aber nicht genug, um meine Familie und all die Tiere zu schützen.|n|nEinige mutige Frostmähnenräuber stehlen in letzter Zeit unsere Widder im Schutz der Nacht und bringen sie nach Süden in die Tundridhügel. Würdet Ihr uns helfen, sie zurückzuholen? Geht nah an sie heran und stoßt einen schrillen Pfiff aus, um ihre Aufmerksamkeit zu erregen. Den Rest erledigt ihre Ausbildung.', },
    {'Benutzt /pfeifen, um 6 gestohlene Widder aus den Tundridhügeln zurückzuholen.', },
  },
  [25906] = {
    'Das dritte Flammentor',
    {'Prägt Euch die Glyphe ein.|nNehmt sie mit Euch.|nZeichnet sie auf den Boden vor dem Flammentor.|nÖstlich von hier.|nBetretet die Feuerlande.|n|nIch kann nicht mit Euch kommen.|nAber meine Kinder erwarten Euch.|n|nSucht Garunda Bergkuppe im Reich der Flammen.', },
    {'Reist durch das Flammentor in der Verbrannten Ebene und sucht nach Garunda Bergkuppe.', },
  },
  [25907] = {
    'Sklavenarbeit',
    {'Ich werde ein wenig Zeit benötigen, um diese Barriere zu durchbrechen und mit Nespirah zu kommunizieren. In der Zwischenzeit könnt Ihr einige der Männer retten, die die Naga in den Gruben unter uns versklavt haben.|n|n<Duarn holt ein langes Seil aus seinen Roben hervor.>|n|nDas wird Euch sicher gute Dienste leisten.', },
    {'Benutzt Duarns Seil, um 8 versklavte Perlenminenarbeiter zu retten.', },
  },
  [25908] = {
    'Bestraft sie',
    {'Ich kann vielleicht nicht direkt mit Nespirah kommunizieren, aber ich kann zumindest indirekt etwas spüren. Zum Beispiel fühle ich deutlich, dass Nespirah alles andere als glücklich über die Anwesenheit der Naga hier ist.|n|nAls wir in Nespirahs Körper eingedrungen sind, sah ich Dutzende von Schildwachen und Verzauberinnen, die im zentralen Raum patrouillieren. Vielleicht könnt Ihr das Leid der Ahnin lindern, indem Ihr ihre Zahlen verringert.', },
    {'Tötet 7 Schildwachen des Idra\'kess und 7 Verzauberinnen des Idra\'kess.', },
  },
  [25909] = {
    'Fang den Krebs',
    {'Jede Faser meines Körpers sagt mir, dass Nespirah versucht, mit mir zu sprechen, aber ich kann sie nicht hören. Vielleicht haben die Naga etwas mit ihrer Stimme angestellt.|n|n<Duran grübelt einen Moment vor sich hin.>|n|nNespirahs Stimme wird vielleicht unterdrückt... das bedeutet... dass wir eine Stimme für sie finden müssen!|n|nIch hab\'s! Idra\'kess\' Naga richten Tiefensucherkrebse als Schlachtgefährten ab. Benutzt dieses Netz, um einen Krebs zu fangen und bringt ihn mir. Wahrscheinlich findet Ihr sie am äußeren Rand der Kammer herumkrabbeln.', },
    {'Benutzt Duarns Netz, um einen Tiefensucherkrebs in Nespirah zu fangen.', },
  },
  [25910] = {
    'Die Zeit für Gnade ist vorbei',
    {'Diese Höhle ist der reinste Höllenschlund, $N. Sie ist voller abscheulicher Schrecken aus der Tiefe.|n|nIch möchte nicht, dass diese… Kreaturen… durch das Portal in die Außenwelt gelangen. Tötet sie alle!', },
    {'Tötet 10 geschmolzene Peiniger und 4 Meister der Schattenflamme.', },
  },
  [25911] = {
    'Willkommene Nachrichten',
    {'Sie schicken bestimmt ein Ruderboot. Das kann ein bisschen dauern. Ich bleibe hier, um mich mit ihnen in Verbindung zu setzen.|n|nIhr müsst sofort zur Höhle zurückkehren und Bescheid geben, dass Rettung auf dem Weg ist. Wir können nur hoffen, dass die Naga sie noch nicht gefunden haben.|n|nGeht. Schwimmt schnell, $N.', },
    {'Kehrt zu Kapitän Taylor am Stillen Strand zurück.', },
  },
  [25912] = {
    'Gute alte Zeit',
    {'Die Welt gerät aus den Fugen, $N. Vertraute Feinde versuchen uns an einer Seite zu zerstören, während uralte Kräfte uns von der anderen bedrängen.|n|n<Urahnin Sareth\'na seufzt.>|n|nIch habe bessere Zeiten erlebt - hellere Tage, und ich sehne mich nach ihnen...|n|nHinter dem Steinkrallengipfel stehen die Ruinen unseres alten Außenpostens - die Dunkelheit hat ihn überrannt. Solltet Ihr Euch in dieser Gegend aufhalten, könntet Ihr dann nach meinem Zeichenbuch suchen? Es steckt voller glücklicher Erinnerungen. Ich würde Euch gut für seine Rückgabe belohnen.', },
    {'Findet das Zeichenbuch der Urahnin Sareth\'na.', },
  },
  [25913] = {
    'Die letzte Ruhe',
    {'Als die Horde ins Steinkrallengebirge einmarschierte, fiel mir auf, dass einige der Schildwachen krank wurden. Kurz darauf verhielten sie sich seltsam. Als der erste Tentakel aus dem Boden schoss, griffen die kranken Schildwachen uns an. Wir verloren den Außenposten kurz danach...|n|nDie Schildwachen im Gipfel sind nur noch Hüllen. In ihnen steckt etwas Böses. Bettet die Schildwachen zur letzten Ruhe und bringt ihre Gleven an Euch. Mit jeder zurückgebrachten Gleve kann eine gefallene Schwester identifiziert werden.', },
    {'Bergt 8 Schildwachengleven.', },
  },
  [25914] = {
    'Zurück in die Tiefe!',
    {'Ranken schießen aus dem Boden und terrorisieren den Steinkrallengipfel. Meine Schildwachen werden ihrer nicht Herr.|n|nIch vermute, dass es im Herzen des Steinkrallengipfels eine Macht gibt, die diese Ranken kontrolliert. Wenn wir diese Macht aufhalten, werden die Ranken vielleicht in die Tiefen zurückkehren, aus denen sie gekommen sind.', },
    {'Tötet Aph\'lass und 10 einfallende Tentakel.', },
  },
  [25915] = {
    'Tortollas Stärke',
    {'Der dunkle Usurpator Nemesis floh hierher, als die Feuer des Hyjal verglommen. Wir sind noch nicht stark genug, um Nemesis zu besiegen, $N, aber wir können vielleicht seine eigene Stärke gegen ihn verwenden.|n|nIch werde einen Abkömmling Tortollas mit Euch entsenden, eines der Kinder, das Ihr aus der Verderbnis des Zwielichts errettet habt.|n|nSucht in den Tiefen dieser Höhle nach einem Nemesiskristall und erlaubt der jungen Schildkröte, ihn zu untersuchen.|n|nFalls Ihr Euren Begleiter verliert, meldet Euch bei mir!', },
    {'Begleitet einen Abkömmling von Tortolla zu einem Nemesiskristall. Falls Ihr Euren Begleiter verliert, meldet Euch bei Garunda Bergkuppe.', },
  },
  [25916] = {
    'Durchbruch',
    {'Ein ausgebildeter Schamane kann mit den vier Elementen der Erde, des Feuers, der Luft und des Wassers kommunizieren. Das ist kein Geheimnis.|n|nWas jedoch viele nicht wissen ist, dass es noch ein fünftes Element gibt. Dieses Element ist nicht so eindeutig definiert wie die anderen vier, aber es hat etwas mit der... Gemeinsamkeit zwischen allen lebenden Wesen zu tun.|n|nIch bin der Meinung, dass der Krebs als Wesen des Meeres eng genug mit Nespirah verbunden ist. Mit ein wenig Überredungskunst der Elemente können wir ihn vielleicht dazu bringen, als Nespirahs Sprachrohr zu dienen.', },
    {'Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.', },
  },
  [25917] = {
    'Wir sind nicht allein',
    {'<Duarn schließt die Augen, hält einen Moment inne und nickt.>|n|nNespirah hat mir gerade berichtet, dass wir nicht die Einzigen sind, die in dieser Schale kämpfen. Eine kleine Gruppe von Allianzsklaven ist entkommen und wehrt gerade die Naga auf der anderen Seite der Schale ab, oben auf dem Vorsprung über Nespirahs Herz.|n|nGeht und findet sie, $N. Schaut, wie Ihr sie unterstützen könnt. Mit ihrer Hilfe können wir Nespirah vielleicht aus ihrer Starre erwecken.|n|nIhr findet mich hier, falls Ihr etwas braucht.', },
    {'Findet die Überlebenden der Allianz in Nespirah in Vashj\'ir.', },
  },
  [25918] = {
    'Hoffnungslos ausrüstungslos',
    {'Ich habe wirklich keine Ahnung, wie wir so lange hier überleben konnten. Die Naga haben mir meine Rüstung und meine Waffen genommen. Alles, was sie mir gelassen haben, sind Lumpen und eine Spitzhacke… und DIE ist schon vor einer halben Ewigkeit zerbrochen.|n|nWenn wir eine Chance haben wollen, das Blatt zu unseren Gunsten zu wenden, brauche ich etwas, mit dem ich kämpfen kann. Meinen Kameraden geht es genauso, aber sie sind sicher zu stolz, um es zuzugeben.|n|nIch habe in den Lagerbereichen der Naga Waffenregale gesehen. Ich bin zwar im Umgang mit einem Dreizack nicht sonderlich geübt, aber alles ist besser, als mit bloßen Händen zu kämpfen.', },
    {'Besorgt 4 entwendete Stangenwaffen aus den Waffenregalen in Nespirah.', },
  },
  [25919] = {
    'Voller Körpereinsatz',
    {'<Kapitän Taylor lauscht aufmerksam, als Ihr das Gespräch zwischen Duarn und Nespirah wiedergebt.>|n|nIch verstehe. Also möchte das Wesen, dass wir ihm helfen, es zu wecken?|n|nWenn man bedenkt, dass Hunderte von Sklaven seine Perlen abbauen, muss es aber ganz schön fest schlafen. Vielleicht habt Ihr ja mehr Glück.|n|nMein Vorschlag? Sucht am Fleisch des Wesens nach Schwachstellen. Vielleicht finden Eure Waffen ja eine empfindliche Stelle. Dann wird es sicher zur Besinnung kommen.', },
    {'Greift 7 Abszesse von Nespirah an den Wänden von Nespirahs Körperkammer an.', },
  },
  [25920] = {
    'Immer noch wertvoll',
    {'Auch wenn ich nur wenig Zeit in den Perlenminen verbracht habe, bin ich doch neugierig, was die Naga vorhaben. Ja, ich weiß, dass die Naga Nespirah als Kriegsmaschine nutzen wollen, aber wenn das der Fall ist, warum verwenden sie dann Sklavenarbeiter, um ihre Perlen abzubauen?|n|nWenn wir es je schaffen, den Rumpf dieses Tiers zu verlassen, würde ich diese Gegenstände gerne untersuchen. Die Perlen, die wir in den Minen gefunden haben, waren zu groß, um sie zu tragen. Ich habe jedoch Kriegsherren und Propheten gesehen, die kleinere bei sich hatten.', },
    {'Besorgt 5 mysteriöse Perlen von Kriegsherren des Idra\'kess und Prophetinnen des Idra\'kess in Nespirah.', },
  },
  [25921] = {
    'Aufseher Idra\'kess',
    {'Meine Männer lassen nach, $N. Ich fürchte, wir können diesen Naga nicht mehr lange standhalten. Mit diesen Waffen des Idra\'kess und Nespirahs Perlen sollten wir bereit sein, von hier zu flüchten.|n|nFolgt der Wand in Richtung Südosten und haltet nach einer Rampe Ausschau, die in die obere Kammer führt. Ich schätze, dass ihr Anführer sich dort aufhält. Vielleicht ist dort auch der Schlüssel zu Nespirahs Erweckung versteckt. Wenn wir Glück haben sogar beides.|n|nWenn Ihr Euch stark genug fühlt, geht in die Spitze und sucht nach Antworten.', },
    {'Geht zur Spitze Nespirahs und tötet Aufseher Idra\'kess.', },
  },
  [25922] = {
    'Die Erweckung der Bestie',
    {'Dank Euch und dem Kapitän hat Nespirah wieder die volle Kontrolle über ihren Körper… aber der Großteil der Naga weiß das noch nicht. Sobald wir geflüchtet sind, wird sie ihre biologischen Verteidigungsmechanismen aktivieren und die Naga von innen heraus vernichten.|n|nMacht Euch bereit... Ich sage Nespirah, dass sie die Verteidigung einleiten soll.', },
    {'Sprecht mit Erdheiler Duarn in Nespirah, um ihre biologische Verteidigung zu aktivieren und flieht dann aus Nespirahs Körper.', },
  },
  [25923] = {
    'Vernichtet Nemesis',
    {'Euer Schildkrötenfreund kann diese neu gefundene Macht nutzen, um Euch beide für einen kurzen Augenblick unverwundbar zu machen. Ihr könnt Euch also in Euren "Panzer" verkriechen, um Nemesis\' schlimmsten Zorn zu entgehen. Ruft dazu einfach dieses Totem herbei.|n|nDas ist alles, was ich für Euch tun kann. Ihr und ein Abkömmling von Tortolla müsst gemeinsam Nemesis besiegen, ein für alle Mal. Vernichtet den Usurpator!|n|nFalls Ihr Euren Schildkrötenfreund verliert, kehrt zu mir zurück.', },
    {'Benutzt das Totem von Tortolla, um einem Abkömmling von Tortolla dabei zu helfen, Nemesis zu besiegen. Falls Ihr Euren Schildkrötenfreund verliert, sprecht mit Garunda Bergkuppe.', },
  },
  [25924] = {
    'Die Pflicht ruft',
    {'Hört zu, <Volk>!|n|nAn der Küste der Östlichen Königreiche ist eine neue Landmasse aufgetaucht! Eine wichtige Schlacht um die Kontrolle dieser Insel ist bereits im vollen Gange.|n|nWenn wir hier gewinnen, ist Sturmwind komplett unverteidigt!|n|nJetzt ist die Zeit, um zuzuschlagen!|n|nMeldet Euch sofort an den Docks, damit man Euch zur Schlacht bringt.|n|nAll unsere Kriegsschiffe befinden sich bereits im Kampf, also werdet Ihr ein Söldnerboot nehmen, das vom Kriegshäuptling selbst angeheuert wurde.', },
    {'Fahrt mit dem Söldnerboot zur Schlacht.', },
  },
  [25925] = {
    'Thal\'darahs Rache',
    {'Wir müssen versuchen, Kontakt zum Weitblicktal im Süden herzustellen. Unsere darnassischen Glevenwerfer stehen Euch zur Verfügung, $N. Schlagt mit ihnen eine Schneise in die anrückenden Hordenstreitkräfte und räumt einen Weg ins Weitblicktal frei.|n|nHoffentlich ist es noch nicht zu spät, um das Tal zu retten. Sollte das Weitblicktal unversehrt sein, dann sucht dort nach Hierophant Malyk und informiert ihn über unsere Lage.', },
    {'Tötet 20 Soldaten der Horde und zerstört 3 Verwüster von Krom\'gar im Kriegsnarbental.', },
  },
  [25926] = {
    'Modernder Hass',
    {'Die Morastbestien im Westen sind nicht meine Brüder... sie sind Symptome der gestörten Erde, eine modernde, Gestalt gewordene Verderbtheit.|n|nIhr würdet es nicht verstehen... sie nehmen die Gestalt meines Volkes an, sind jedoch mit verrottenden Sporen durchsetzt. Sie vertreiben das blühende Leben aus dem Sumpf. Sie nehmen alles und lassen nur Verderbtheit zurück. Nichts bleibt zurück! Nichts!|n|nTröstet mich, <Volk>. Tötet die Morastbestien und reinigt das Land. Vielleicht bringt mir das Frieden.', },
    {'Tötet 10 modernde Morastbestien.', },
  },
  [25927] = {
    'Brennende Bedrohung',
    {'Die Flammen bedrohen mich schon seit langer Zeit... zu langer Zeit... aber es sind keine kleinen mehr, nicht mehr nur noch Funken...|n|nDie Felder brennen! Die Hügel und Hochlande schreien, <Volk>, sie schreien. Die Elementare, die hierher gebracht wurden, lassen nur Tod zurück.|n|nDas darf nicht so weitergehen. Haltet sie auf. HALTET SIE AUF! Vernichtet die Flammenboten...', },
    {'Tötet 8 zügellose Feuerelementare.', },
  },
  [25928] = {
    'Tortollas Triumph',
    {'Ich werde die Abkömmlinge von Tortolla hier heraus begleiten und dieses verfluchte Portal versiegeln.|n|nIch überlasse es Euch, Tortolla von unserem Sieg zu berichten. Tretet einfach wieder durch das Flammentor. Der Ahn wird begeistert sein!', },
    {'Geht erneut durch das Flammentor und kehrt zu Tortolla auf der Verbrannten Ebene auf dem Hyjal zurück.', },
  },
  [25929] = {
    'Seetauglich',
    {'Grüße, $C. Ich bin Erunak, einer der Überlebenden dieses Unglücks.|n|nIch fürchte, die Mühen haben für Euch gerade erst begonnen. Die Naga durchstreifen die Gewässer und greifen alles an, was noch am Leben ist.|n|nIhr seid an die hiesigen Bedingungen noch nicht ausreichend angepasst, um zu überleben, aber das kann ich ändern.|n|nDirekt außerhalb dieses Schiffes lebt eine besondere Art von Seestern. Bringt mir einige davon und ein Tritonshorn. Ich werde eine Verzauberung vorbereiten, die Euch dabei helfen wird, Euch an die neue Umgebung zu gewöhnen.', },
    {'Sammelt 3 Salzwasserseesterne und ein Tritonshorn am Meeresgrund im Verhängnis der Legion.', },
  },
  [25930] = {
    'Talstürmer',
    {'Man hat mir erzählt, dass das Verbrannte Tal vor dem großen Umbruch eine Mulde war, ohne Zugang zum Meer. Doch wenn man nun nach Süden blickt, wird deutlich, dass das Verbrannte Tal längst kein Tal mehr ist, sondern ein Gebiet mit großer vulkanischer Aktivität.|n|nSalsbury hat ein Gerät konstruiert, mit dem wir den Vulkan erklimmen können. Benutzt es, um zum Gipfel zu gelangen. Findet heraus, was dort vorgeht.|n|nIch werde mit dem Gnomcordergerät, das Salsbury mir freundlicherweise geschenkt hat, in Kontakt bleiben.', },
    {'Erklimmt mit Salsburys Raketenpack den Vulkan im Verbrannten Tal.', },
  },
  [25931] = {
    'Die Brut von Seldarria',
    {'<Der Gnomcorder summt.>|n|nSeid sehr vorsichtig, $N. Weckt bloß nicht den schwarzen Drachen auf.|n|nSeht Euch um. Wenn dies ein Nest ist, dann sollte es in der Nähe schwarze Dracheneier geben. Sucht das Gebiet nach Eiern ab und zerstört alle, die Ihr seht.|n|nKehrt zu mir zurück, wenn Ihr Seldarrias Eier gefunden und zerstört habt.|n|nMöge Goldrinn über Euch wachen.', },
    {'Zerstört 5 Eier von Seldarria.', },
  },
  [25932] = {
    'Jede Nacht ein Überfall',
    {'Die Berichte, die ich Hauptmann Tharran schicke, spiegeln das Ausmaß des Ärgers, den uns die Frostmähnen bereiten, nicht richtig wider. Euer Angriff auf das Dorf hat etwas Druck von uns genommen. Die Überfälle finden immer noch häufig statt, aber es gibt nicht mehr so viele Trolle wie früher.|n|nTrotzdem sind meine Männer erschöpft. Die Moral sinkt. Würdet Ihr uns im Kampf gegen die Frostmähnenräuber unterstützen? Sie können jederzeit auftauchen.', },
    {'Helft Unteroffizier Flinthammer und seinen Gebirgsjägern, das Gehöft Bernruh gegen die Frostmähnenräuber zu verteidigen.', },
  },
  [25933] = {
    'Hilfe für den Steinbruch',
    {'Ich möchte Euch noch einmal für Eure Hilfe danken, $N.|n|nMein Cousin hat früher in den Minen unter dem Steinbruch Gol\'Bolar gearbeitet, aber seit die Troggs dort eingedrungen sind und die Kontrolle übernommen haben, geht das nicht mehr. Der Steinbruch und sein Lager liegen südöstlich des Gehöfts. Würdet Ihr Euch dort bei dem Großknecht melden und herausfinden, ob man etwas unternehmen kann?', },
    {'Sprecht mit Großknecht Steinbraue im Steinbruch Gol\'Bolar.', },
  },
  [25934] = {
    'Weltneuheit: Gnomgen',
    {'Guten Tag, Bürger, ich möchte mich Euch vorstellen. Ich bin Salsbury, bald der welterste Gnomgen. Malyk hat mir versichert, dass er mir nach Beendigung meiner Arbeit das Geschenk des Worgen machen wird.|n|nSo, da wir uns jetzt kennen, möchte ich eine Bitte äußern!|n|nSüdlich von hier, im Verbrannten Tal, treiben neu erschaffene Feuerelementare ihr Unwesen. Ich brauche dringend ein seltenes flammendes Herz des Feuers von einem der Unholde. Beschafft es für mich, dann komme ich dem Leben eines Gnomgen einen Schritt näher!', },
    {'Beschafft 1 flammendes Herz des Feuers.', },
  },
  [25935] = {
    'Hungrige Welpen',
    {'Ah, ein Neuankömmling! Gut, dass Ihr hier seid $GJunge:Schwester;! Die Welpen sind hungrig, aber uns ist die Nahrung ausgegangen.|n|nZum Glück lieben sie Drachenfleisch, was es in rauen Mengen im Verbrannten Teil südlich von hier gibt.|n|nSeid ein $Gguter Junge:gutes Mädchen; und besorgt mir ein paar Pfund Schwarzdrachenwelpenfilet.', },
    {'Beschafft 6 Schwarzdrachenwelpenfilets.', },
  },
  [25936] = {
    'Wie ich Euch, so Ihr ihnen',
    {'Jetzt seid Ihr in der Lage, Euch in diesem Reich freier und ohne Angst vor Ertrinken zu bewegen.|n|nUnd jetzt beginnt unsere Arbeit.|n|nZunächst gibt es viele Verbündete von Euch in der Nähe, die in diesem Augenblick im Wasser um ihr Leben ringen. Ich habe Euch gerettet und nun müsst Ihr sie retten.|n|nIch habe die Muschel verzaubert, die Ihr mir gebracht habt. Benutzt sie, um Eure Freunde zu retten.|n|nSchnell!', },
    {'Benutzt das verzauberte Tritonshorn, um 6 ertrinkende Soldaten zu retten.', },
  },
  [25937] = {
    'Unermessliche Reichtümer',
    {'In dem Steinbruch wurde nicht nur geschürft. Ich leitete ein Ausgrabungsteam der Forscherliga. Wir suchten nach wertvollen alten Artefakten.|n|nMir gelang die Flucht, aber meine Kollegen hielten sich tiefer in der Mine auf und überlebten den ersten Angriff der Troggs nicht.|n|nSie waren sehr stolz auf ihre Arbeit und riskierten ihr Leben, um mehr über unsere Geschichte herauszufinden. Wenn Ihr in die Minen geht, dann nehmt diese Spitzhacke mit. Vielleicht findet Ihr ja etwas in den Stollen, die von den Ausgräbern begonnen wurden.', },
    {'Bergt 8 gefrorene Artefakte aus der Mine des Steinbruchs Gol\'Bolar.', },
  },
  [25938] = {
    'Hilfe für Desolace',
    {'Ich habe eine verstörende Nachricht aus Nijelspitze in Desolace erhalten. Der große Umbruch hat anscheinend neue Probleme mit sich gebracht, auf die sie nicht vorbereitet waren. Mehr weiß ich nicht.|n|nMeldet Euch bei Offizierin Jankie in Desolace. Sie wird Euch den Weg nach Nijelspitze weisen.|n|nViel Glück, $N.', },
    {'Meldet Euch bei Jankie in Tethris Aran in Desolace.', },
  },
  [25939] = {
    'Feuerteufel',
    {'Die Elementare, die auf dem Hügel der Düsterschmiede randalieren, stecken das Land unter sich in Brand. In einem Sumpf wie diesem findet das Feuer im tiefen Moos und Torf ausreichend Nahrung.|n|nLöscht die Feuer, bevor sie sich ausbreiten. Nehmt diese Blume... sie wurde mit dem Regen der Natur gesegnet und wird Euch ermöglichen, die Feuer zu löschen.|n|nIhre Blüten könnten sich außerdem als nützlich gegen die Elementare erweisen.', },
    {'Löscht 7 Moorfeuer mit der gesegneten Flutlilie.', },
  },
  [25940] = {
    'Letztes Gefecht am Rauschenden Hain',
    {'Möglicherweise habe wir jetzt eine Chance, die Flammen dank Eurer Arbeit in dem Inferno zu besiegen.|n|nDennoch sind weitere Wildtiere bedroht. Hüter Taldros rannte Richtung Norden durch die Flammen zum Rauschenden Hain.|n|nSeht, ob Ihr ihm helfen könnt!', },
    {'Meldet Euch bei Hüter Taldros im Rauschenden Hain auf dem Hyjal.', },
  },
  [25941] = {
    'Rast für die Erschöpften',
    {'Ihr habt Eure Aufgabe gut gemacht, <Volk>, aber es gibt noch viel mehr zu tun und ich bin langsam erschöpft.|n|nIch habe sehr viel Energie darauf verwendet, ein Notsignal an die Anführer des Irdenen Rings zu senden und sie um Hilfe zu bitten.|n|nWenn ich uns hier noch weiter von Nutzen sein möchte, muss ich mich ausruhen.|n|nSprecht mit dem Anführer der Männer, die Ihr gerettet habt und tut was Ihr könnt, um ihnen bei den Schlachtvorbereitungen zu helfen.|n|nDie Naga durchkämmen das Wasser nach uns. Es ist nur eine Frage der Zeit, bis sie zurückkehren. Und dann werden sie ganz sicher noch zahlreicher sein.', },
    {'Sprecht mit Legionär Nazgrim.', },
  },
  [25942] = {
    'Verschafft uns Zeit',
    {'Viele gute Krieger mussten heute ihr Leben lassen.|n|nWenn das, was der Schamane sagt, stimmt, dann haben wir keine Zeit zu verlieren. Die Naga durchkämmen die Gewässer auf der Suche nach Überlebenden.|n|nWir sind noch nicht bereit, um zu kämpfen. Ihr müsst uns Zeit für die Vorbereitung verschaffen. Findet die Naga, die uns jagen und verlangsamt ihre Fortschritte.', },
    {'Tötet 8 Räuber des Zin\'jatar im Verhängnis der Legion.', },
  },
  [25943] = {
    'Siege gehen durch den Magen',
    {'Wenn ich diese Orcs für die Schlacht bereit machen möchte, brauche ich Eure Hilfe.|n|nJeder anständige Anführer weiß: Leerer Bauch reist und kämpft nicht gern. Kein Mampf, kein Kampf.|n|nDiese Krieger sind von den kürzlichen Strapazen vollkommen erschöpft. Sie brauchen etwas Nahrhaftes für den Fall, dass die Naga angreifen.|n|nWo wir gerade von leeren Mägen sprechen, da draußen auf dem Meeresboden habe ich einige Krebse gesehen...', },
    {'Sammelt 8 Stück saftiges Krebsfleisch von Spaltscherenhuschern.', },
  },
  [25944] = {
    'Der Horde alte Kleider',
    {'In unserem Kampf gegen das Ertrinken waren meine Orcs und ich gezwungen, unsere Waffen und einen Großteil unserer Rüstungen zurückzulassen.|n|nErunak sagt, dass er bald einen großangelegten Angriff der Naga erwartet und ich glaube ihm.|n|nWenn wir siegen wollen, müsst Ihr uns dabei helfen, unsere verlorene Ausrüstung zurückzuholen.|n|nEs sollte alles auf dem Meeresboden in der Nähe unserer Schiffswracks hier und im Norden liegen.|n|nSchnell, <Volk>. Der Feind könnte jeden Moment eintreffen.', },
    {'Sammelt 5 Äxte von Orgrimmar, 5 Brustplatten von Orgrimmar und 5 Helme von Orgrimmar am Meeresboden oder von Strauchdieben der Gilblin im Verhängnis der Legion.', },
  },
  [25945] = {
    'Wir haben hier nur eine Aufgabe, vielleicht auch zwei...',
    {'Ihr seid jetzt in Höllschreis Armee, $N, und in Höllschreis Armee treten wir anderen in den Hintern und sind verdammt nachtragend. Die Zeiten, in denen Leute auf den Straßen Orgrimmars verhungerten, während wir Verträge mit den Elfen schlossen, sind vorbei. Wir holen uns jetzt, was wir brauchen. Kalimdor gehört der Horde!|n|nDie Allianz versucht bei jeder Gelegenheit, unsere Expansion aufzuhalten. Diesen Schweinslutschern gehört bereits ein Großteil der Östlichen Königreiche, aber das reicht ihnen nicht!|n|nOberanführer Krom\'gar will mehr Truppen ins Steinkrallengebirge verlegen. Schließt Euch der Karawane westlich von hier an. Geht!', },
    {'Reist mit dem Wagen von Krom\'gar zum Bruch im Steinkrallengebirge.', },
  },
  [25946] = {
    'ScHELMenstück',
    {'<Dieser Helm und das passende Zubehör sind mit dem Siegel von Sturmwind gekennzeichnet. Er stammt ohne Zweifel von einem Allianzschiff, dass ein ähnliches Schicksal wie Euer Schiff erlitten hat.>|n|n<Wenn Ihr den Helm genauer betrachtet, fällt Euch auf, dass er viel zu gut verarbeitet und stabil ist, um zu einer normalen Tauchausrüstung zu gehören. Vielleicht weiß Nazgrim ja, was es damit auf sich hat...>', },
    nil,
  },
  [25947] = {
    'Wer es findet, darf es behalten',
    {'Ich erkenne diesen Helm, <Volk>. Es war klug von Euch, ihn mir zu bringen.|n|nDie Allianz hat eine Spezialeinheit, die für Erkundungen und Kampfeinsätze unter Wasser ausgebildet und ausgerüstet wurde.|n|nWie es scheint, haben sie in dieser Gegend weitaus mehr vor, als sich gegen unseren Angriff zu verteidigen.|n|nEs muss da unten noch mehr davon geben. Wenn Ihr sie findet, könnte sich das Blatt für unseren Vorposten schnell wenden.', },
    {'Sammelt 5 Teile einer Kampfschwimmerausrüstung von Sturmwind.', },
  },
  [25948] = {
    'Zeigt, was Ihr drauf habt!',
    {'Es ist an der Zeit, $C.|n|nWir sind so bereit wie es nur geht!|n|nIch werde zu den Truppen sprechen und dann schwimmen wir ins Meer, dem Schicksal entgegen.', },
    {'Sprecht mit Legionär Nazgrim an Bord der "Ewiger Kreislauf".', },
  },
  [25949] = {
    'Blut und Donner!',
    {'Die Zeit ist gekommen, um uns zur Wehr zu setzen, <Volk>.|n|nWir werden dieses Schiff bis zum letzten Atemzug verteidigen und dafür sorgen, dass dieser Nagaabschaum es sich zweimal überlegt, bevor er sich ihm erneut nähert!|n|nFür die Horde!', },
    {'Helft Legionär Nazgrim dabei, die "Ewiger Kreislauf" zu verteidigen.', },
  },
  [25950] = {
    'Tod den Sira\'kess',
    {'Ihr seid also $Gder:die; berühmte $N, von $Gdem:der; alle reden? Schön, Euch kennenzulernen, Schätzelchen. Kommt, lasst mich mal ein Auge riskieren.|n|nGenug Geplauder, kommen wir zur Sache, ja? Ich will, dass Ihr für mich nach Nordwesten zu der Frontlinie der Sira\'kess schwimmt und den Naga ordentlich einen vor den Latz knallt.|n|nNix Wildes. Die sind nur auf Streit aus und den sollen sie kriegen!', },
    {'Tötet 10 Naga der Sira\'kess.', },
  },
  [25951] = {
    'Schlussurteil',
    nil,
    nil,
  },
  [25952] = {
    'Überraschungsangriff',
    {'Unsere Flucht aus der Muschel blieb sicher nicht unbemerkt, aber entweder wurden die Naga in den Ruinen nicht informiert oder sie sehen in uns keine Bedrohung. Ich habe nicht vor, diese Gelegenheit ungenutzt zu lassen. Wir werden jetzt gleich zuschlagen.|n|nIhr müsst Euch für mich in den unteren Bereich der Ruinen im Westen schleichen und so viele ihrer Patrouillen ausschalten, wie Ihr nur könnt. Wir können nicht riskieren, dass diese Patrouillen herausfinden, dass wir diese Höhle besetzt haben. Stellt sicher, dass keiner entkommt.', },
    {'Tötet 10 Patrouillen der Azsh\'ir.', },
  },
  [25953] = {
    'Schnelles Handeln',
    {'Ich habe mir die Freiheit genommen, schon vorab die Lage auszuspähen. Die Naga wissen vielleicht nicht, wo wir sind, aber sie sind dennoch auf Eindringlinge vorbereitet.|n|nAbgesehen von ihren Patrouillen haben sie magische Überwachungsgeräte aufgestellt, die sie vor ungebetenen Gästen warnen. Zum Glück scheinen sie Quantität der Qualität vorzuziehen. Daher habt Ihr Zeit, sie zu zerstören, bevor jemand auf ihren Alarm reagieren kann.|n|nIch vertraue darauf, dass Ihr das erledigt, bevor unsere Soldaten eintreffen.', },
    {'Zerstört 8 Überwacher der Azsh\'ir.', },
  },
  [25954] = {
    'Suche nach der Vergangenheit',
    {'Hört mal... $N, richtig? Ich brauche Eure Hilfe. Ich weiß schon, fast alle in dieser Höhle denken, dass wir uns im Augenblick um nichts als unser eigenes Überleben kümmern sollten, aber ich bin nicht bereit, meine Ahnen so einfach außer Acht zu lassen.|n|nZu der Zeit als Azshara regierte, war dies eine königliche Stadt der Elfen. Tief in dieser Stadt liegen die Schlüssel zu lange verschollenem Wissen und Artefakten von unermesslichem historischen Wert. Bitte, haltet doch nach interessanten Gegenständen Ausschau, wenn Ihr ohnehin schon in der Stadt seid.', },
    {'Untersucht die 4 unversehrten Statuen in den Gärten von Vashj\'ir.', },
  },
  [25955] = {
    'Ein besserer Standort',
    {'Diese Höhle ist unsere einzige Zuflucht. Es ist keine Hilfe unterwegs. Was immer geschieht, diese Höhle muss geschützt bleiben, sonst werden wir alle hier unten sterben.|n|nWir brauchen einen Vorposten, von dem aus wir die Angriffe starten können. Etwas, das wir verteidigen können.|n|nIm östlichen Teil der Ruinen auf der untersten Ebene solltet Ihr die nördlichen Gärten, die Passage unter der Hauptstruktur im Westen der Gärten und die Gebäudegruppe in der südöstlichen Ecke der Ruinen unter den Brücken erkunden.|n|nBringt mir alle Informationen, die Ihr finden könnt.', },
    {'Späht den nördlichen Teil der Gärten von Quel\'Dormir, den Tunnel unter den Ruinen im Westen der Gärten und die Gebäude im Südosten der Gärten aus. Bleibt auf der untersten Ebene der Ruinen.', },
  },
  [25956] = {
    'Auf dem Schlachtfeld',
    {'<Überall um Euch herum liegen Relikte der wilden Schlacht. Die Nagaskelette überraschen Euch nicht, aber die Waffen und Überreste ihrer offensichtlichen Gegner dafür viel mehr.>|n|n<Inmitten der Knochen entdeckt Ihr ein auffälliges Stück Metall, das aus einem der Schädel herausragt. Es ist schwer zu sagen, zu welcher Art Waffe das Metall einst gehört haben mag, aber es steht weit genug hervor, dass Ihr es als Beweis mitnehmen könnt.>|n|n<Irgendjemand in der Höhle ist an dieser Erkenntnis sicher interessiert.>', },
    {'Bringt das Bruchstück zurück zur Ruhestatt der Legion.', },
  },
  [25957] = {
    'Visionen der Vergangenheit: Die Invasion von Vashj\'ir',
    {'Das Bruchstück, das Ihr gefunden habt, scheint von Nagahand geschaffen zu sein. Ich hatte gehofft, ein starkes Fokusobjekt wie dieses für einen Zauber zu finden, an dem ich gerade arbeite. Mit diesem Zauber könnten wir einen Blick in die kürzliche Vergangenheit werfen.|n|nIch habe die Klinge verzaubert, aber Ihr müsst sie an einen Ort bringen, von dem wir wissen, dass ihr Besitzer sich dort aufgehalten hat. Ich möchte, dass Ihr zurück an die Stelle reist, wo Ihr die Klinge gefunden habt und sie dort benutzt.|n|nVielleicht können wir so mehr über die Pläne der Naga hier erfahren. Oder noch besser: Vielleicht finden wir einen ihrer Schwachpunkte, sodass wir eine bessere Chance haben, sie zu besiegen.', },
    {'Benutzt die Klinge der Kriegsmaid der Naz\'jar auf dem Schlachtfeld am südöstlichen Ende der Ruinen.', },
  },
  [25958] = {
    'Ein Blick nach vorne',
    {'Der Hauptmann hat die Informationen, die Ihr für ihn gesammelt habt, genutzt, um einen Vorposten unter der Terrasse im Westen einzurichten. Er trifft dort Vorbereitungen für eine Art Angriff auf die Naga.|n|nIhr solltet sofort zu ihm gehen und ihn über das Ausmaß dessen, was Ihr beobachtet habt, unterrichten. Unsere Streitmacht ist klein. Ich mache mir Sorgen um unsere Soldaten, wenn wir uns in einen waghalsigen Angriff stürzen.|n|nNehmt mein Seepferdchen. Es kennt den Weg.', },
    {'Sprecht mit Hauptmann Übeldorn nördlich der Gärten von Quel\'Dormir.|n|nBenutzt das Seepferdchen von Wellensprecherin Tulra, um den Vorposten schnell zu erreichen.', },
  },
  [25959] = {
    'Deutliche Ziele',
    {'Ich verstehe. Eure Nachrichten sind düster, aber ich bin nicht ganz unvorbereitet auf eine solche Lage. Ich wusste, dass unser Plan riskant ist, solange wir die genauen Zahlen der Naga nicht kennen, aber zu diesem Zweck haben wir ja diesen Vorposten eingerichtet.|n|nIch will Euch nicht belügen, $C. Wenn wir die Naga nicht beschäftigt halten, werden sie uns angreifen. Wir haben weder die Anlagen noch die Männer, um eine geeignete Verteidigung zu errichten, daher kommt das für uns nicht in Frage.|n|nWir brauchen mehr Zeit. Könnt Ihr ihre Reihen im Süden, unter der Terrasse, ein wenig ausdünnen?', },
    {'Tötet 10 Naga der Streitmächte, die sich unter der südwestlichen Terrasse auf der Grundebene zusammenziehen.', },
  },
  [25960] = {
    'Nicht ganz unvorbereitet',
    {'Ich habe Euer Gespräch mit dem Hauptmann gehört. Ich weiß, dass das, was wir tun, wahnsinnig klingt, aber wir haben einfach keine andere Wahl. Dort in der Höhle sind Leute, die sich auf uns verlassen.|n|nIch habe Aufklärer auf den verschiedenen Klippen in der Gegend aufstellen lassen. Bei den ganzen verstreuten Nagaspähern in der Gegend geht ihnen die Munition rasend schnell aus. Bringt ihnen mehr Armbrustbolzen, um uns etwas Zeit zu verschaffen.', },
    {'Bringt 8 Schachteln mit Armbrustbolzen zu den Aufklärern der Horde auf den Felsvorsprüngen um das nördliche Ende der Gärten von Quel\'Dormir.', },
  },
  [25961] = {
    'Spannende Ablenkung',
    {'Ha! Habt Ihr gesehen, wie der Hauptmann mir böse Blicke zuwirft und mich herablassend behandelt? Ich habe offen gestanden alle Hoffnung verloren, dass er versteht, welch gute Gelegenheit die Ruinen uns bieten, diesem ganzen Schlamassel etwas Positives abzugewinnen.|n|nIch habe gehofft, dass Ihr wieder auftauchen würdet. Ihr scheint $Gder Einzige zu sein, dem:die Einzige zu sein; der; ich vertrauen kann. Ich habe ein paar Tafeln wie diese verstreut in den Ruinen in der Nähe gesehen und ein Abpausset zusammengestellt, um sie zu abzuschreiben. Habt Ihr Lust?', },
    {'Schreibt die 4 Tafeln der Hochgeborenen ab.', },
  },
  [25962] = {
    'Ausreichende Inspiration',
    {'Ich war schon überall. Habe alle möglichen Dinge in die Luft gejagt. Ich dachte, ich hätte vielleicht Probleme damit, den neusten Entwicklungen zu folgen. Ihr wisst schon, wegen dem Wasser und so, aber es ist alles nur eine Frage der Inspiration.|n|nIch habe etwas gefunden, das explosiv genug ist, um Bomben daraus zu bauen. Unter der Terrasse im Südwesten hängen ein paar Tangblasen herab. Normalerweise speichert Tang Gas, das ihn zum schweben bringt, doch dieses schwere Gas ist ganz anders. Es bringt ihn dazu, hängen zu bleiben. Außerdem eignet es sich perfekt für Explosionen.|n|nKönnt Ihr mir etwas davon sammeln?', },
    {'Sammelt 8 aufgedunsene Tangblasen, die unterhalb der südwestlichen Terrasse hängen.', },
  },
  [25963] = {
    'Blitzangriff',
    {'Wir haben alles, was wir für den Angriff brauchen.|n|nWenn das, was Ihr sagt, wahr ist, solltet Ihr Euch während des Angriffs lieber fest an Euer Reittier klammern. Es ist sehr unwahrscheinlich, dass jemand von uns, der auf das offene Meer gerät, den Naga davonschwimmen kann.|n|nTötet so viele wie möglich. Wir werden den Angriff führen und treffen uns dann oben auf der südlichen zerbrochenen Terrasse, sobald wir die Sprengsätze aufgebraucht haben. Hoffentlich sind dann nur noch so wenige übrig, dass wir sie auf die altmodische Art erledigen können.', },
    {'Sprecht mit Fiasco Siedefeix, um Euch dem Überfall anzuschließen. Benutzt dann Euren improvisierten Sprengstoff, um 100 Soldaten der Azsh\'ir, 20 Wellenkreischer der Azsh\'ir und 12 Archaeen der Azsh\'ir zu töten.', },
  },
  [25964] = {
    'Gefallen, aber nicht vergessen',
    {'Das war ein Desaster! Die meisten unserer Männer sind Speeren zum Opfer gefallen, noch bevor sie überhaupt in der Nähe des Treffpunkts waren!|n|nWir werden diese Position sicher nicht mehr lange halten können, bevor die Naga uns überrennen. Wir müssen uns in den Südwesten begeben und so viele der Männer retten, wie wir nur können. Geht und tut alles, was in Eurer Macht steht.|n|nLange halten sie nicht mehr durch. Bitte, beeilt Euch!', },
    {'Rettet 6 verletzte freiwillige Angreifer.', },
  },
  [25965] = {
    'Einschätzung des Erfolgs',
    {'Boshafte Rüpel… Sie haben mit diesen Speeren einen ganz schönen Schaden angerichtet.|n|n<Der Hauptmann zuckt ein bisschen, als er sich die Wunde an der Seite hält.>|n|nWir werden hier so lange wie möglich durchhalten, damit alle Männer es schaffen. Ich brauche jemanden, der ausspioniert, wie viele es noch sind. Ich möchte wissen, wie viel Schaden wir ihnen zugefügt haben.|n|nEine ihrer größten Gruppen befand sich im nordwestlichen Teil dieser runden Terrasse und die andere ein wenig weiter im Norden, in dem kleinen Tunnel, ebenfalls auf der mittleren Ebene der Ruinen.|n|nInterressiert an ein wenig Arbeit als Kundschafter?', },
    {'Späht den Rand der runden Terrasse im Nordwesten und den Tunnel unter der Haupttreppe im Norden aus. Beides befindet sich auf der Terrasse von Nar\'shola, in der mittleren Ebene der Ruinen.', },
  },
  [25966] = {
    'Visionen der Vergangenheit: Das Massaker von Biel\'aran',
    {'Ja, ich weiß, es ist in Zeiten wie diesen viel verlangt, aber Ihr müsst Euch einen Moment lang von dieser Niederlage losreißen.|n|nIch werde mich um diese Soldaten kümmern. Ihr müsst jedoch den Ort im Westen finden, an dem die Schlacht mit dem General der Kvaldir ausgetragen wurde, von der Ihr mir erzählt habt. Von dort aus solltet Ihr mehr über die Erlebnisse der Kriegsmaid erfahren können. Ich habe das untrügliche Gefühl, dass der Schlüssel zum Sieg über die Naga in dieser Kriegsmaid liegt.|n|nBitte, beeilt Euch. Ich tue alles, was ich kann, um Euch Zeit zu verschaffen.', },
    {'Werdet Zeuge des weiteren Verlaufs der Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge am Sterbeort des Generals der Kvaldir benutzt.', },
  },
  [25967] = {
    'Haltlos',
    {'Ihr müsst mich später auf den neusten Stand bringen. Im Augenblick müssen wir hier verschwinden, bevor weitere Naga vorrücken. Begebt Euch zum Vorposten auf der Ebene unter uns.|n|nNehmt mein Seepferdchen. Wir treffen uns dort in Kürze.', },
    {'Benutzt das Seepferdchen von Wellensprecherin Tulra, um zu Hauptmann Übeldorn nördlich der Gärten von Quel\'Dormir zurückzukehren.', },
  },
  [25968] = {
    'Ein verzweifelter Plan',
    {'Toldrek und Fiasco sind aufgebrochen, um Hilfe zu holen. Die Handelsrouten sind nicht weit entfernt, daher besteht die Chance, dass sie Erfolg haben. Ich wage es jedoch nicht, den anderen zu viel Hoffnung zu machen.|n|nOffen gestanden haben wir keine andere Wahl. Wir werden hier nicht viel länger aushalten. Früher oder später werden die Naga uns finden und... nun... Ihr habt selbst gesehen, wie viele es sind.|n|nIhr solltet die beiden auf dem Biel\'arangrat im Südosten suchen. Ich kümmere mich solange so gut es geht um die Sicherheit der anderen hier.', },
    {'Trefft Euch mit Fiasco Siedefeix auf dem Biel\'arangrat.', },
  },
  [25969] = {
    'Feindliche Gewässer',
    {'Fiasco kam mit einer Art Ballon hierher, den er von einem unserer Schiffe gerettet hat. Er hat versucht, damit nach oben zu schweben, aber diese Schlickhautschnorrer kamen aus dem Nichts und haben das Ding umschwärmt.|n|nJetzt hat er eine Idee für einen weiteren Ballon, aber wir müssen sicherstellen, dass es nicht wieder genauso abläuft. Ihr müsst diese Gilblins töten. Oder zumindest so viele, dass sie etwas mehr Angst vor uns haben.', },
    {'Tötet 10 Schlickhautschnorrer.', },
  },
  [25970] = {
    'Immer vorbereitet',
    {'Es ist nicht weit bis zur Oberfläche. Eigentlich alles kein Problem. Doch es ist nicht leicht, Ausrüstung nach da oben zu bringen. Sie ist einfach zu schwer.|n|nAlle Schiffe in der Flotte der Horde sind mit einer Überlebensausrüstung ausgestattet. Ich hatte einen Ballon aus so einer Überlebensausrüstung, aber er musste sich leider den Widrigkeiten geschlagen geben. Ich brauche noch eine Überlebensausrüstung.|n|nSüdöstlich von hier liegt ein Schiff. Wollen wir hoffen, dass die Überlebenden dumm genug waren, die Überlebensausrüstung nicht mitzunehmen. Mehr zum Überleben für uns!', },
    {'Besorgt eine Überlebensausrüstung der Horde.', },
  },
  [25971] = {
    'Seilakrobatik',
    {'In Überlebensausrüstungen sind nie Seile enthalten. Das ergibt doch keinen Sinn! Seile und Bomben, das ist alles, was sie enthalten sollten. Der Rest des Krams ist einfach nur Platzverschwendung.|n|nBis auf den Ballon vielleicht. Der kommt uns jetzt gerade gelegen.|n|nIch wette, diese Kvaldir haben Seile. Sie fahren immer in Booten herum, knüpfen Knoten und ziehen sich sogar Netze an. Geht und stehlt ihnen ein paar Seile! Ich brauche dringend welche für meinen Plan. Seile sind nicht optional!', },
    {'Sammelt 8 Kvaldirseile.', },
  },
  [25972] = {
    'Ehre und Privileg',
    {'Fertig! Ich bin mir ganz sicher, dass es funktionieren wird. Und nicht ein Schnorrer in Sicht, der wieder ein Loch hineinstoßen könnte! Gut gemacht.|n|nToldrek ist bereits nach oben geschwommen, um ihn zu packen. Er macht sich Sorgen um die Strömung und all so was. Er meinte aber, er würde Euch die Ehre überlassen. Netter Kerl - Keine Ahnung, wie er am Leben bleibt.|n|nSchwimmt zum Ballon an der Oberfläche, nehmt die Leuchtpistole aus der Kiste und haltet am Horizont nach Schiffen der Horde Ausschau. Wenn Ihr welche seht, schießt das Leuchtfeuer in ihre Richtung. Das war es auch schon!|n|nAuftauchen, Schwimmen, Signalfeuer, Rettung! Der letzte Teil gefällt mir am besten.', },
    {'Schwimmt zur Oberfläche, holt die Leuchtpistole und feuert ein Rettungsleuchtfeuer in Richtung der Hordenschiffe.', },
  },
  [25973] = {
    'Willkommene Nachrichten',
    {'Sie schicken bestimmt ein Ruderboot. Das kann ein bisschen dauern. Ich bleibe hier, um mich mit ihnen in Verbindung zu setzen.|n|nIhr müsst sofort zur Höhle zurückkehren und Bescheid geben, dass Rettung auf dem Weg ist. Wir können nur hoffen, dass die Naga sie noch nicht gefunden haben.|n|nGeht. Schwimmt schnell, $N.', },
    {'Kehrt zu Legionär Nazgrim an der Ruhestatt der Legion zurück.', },
  },
  [25974] = {
    'Tod den Sira\'kess',
    {'Ihr seid also $Gdieser:diese; $N, von $Gdem:der; alle sprechen? Schön, Euch endlich zu treffen.|n|nNun, genug der Worte. Lasst uns zur Sache kommen. Ihr müsst für mich nach Nordwesten zur Frontlinie der Sira\'kess schwimmen und schnell diese Naga erledigen.|n|nNichts Aufregendes. Sie sind auf einen Kampf aus und wir werden ihnen einen bieten. Mit \'wir\' meine ich natürlich Euch.', },
    {'Tötet 10 Naga der Sira\'kess.', },
  },
  [25975] = {
    'Einforderung der Schätze',
    {'Wir haben unsere ersehnte Verstärkung, aber immer noch keine Ahnung, wie wir sie bezahlen sollen. Und diese Art von Hilfe ist nicht ganz billig.|n|nAuf dem Tiefenflossengrat im Nordwesten gibt es ein paar schleimige Gilblins, die die verschiedensten Schätze zusammengerafft haben. Es ist an der Zeit, ihnen ein wenig davon für unsere Zwecke zurückzustehlen.', },
    {'Sammelt 6 Stück Tiefenflossenbeute.', },
  },
  [25976] = {
    'Einforderung der Schätze',
    {'Blut und Donner! Wir haben unsere ersehnte Verstärkung, aber wir müssen sie leider auch bezahlen. Das wird sicher nicht billig.|n|nAuf dem Tiefenflossengrat im Nordwesten gibt es ein paar schleimige Gilblins, die die verschiedensten Schätze zusammengerafft haben. Es ist an der Zeit, ihnen ein wenig davon für die Horde zurückzustehlen.|n|nHöllschreis Augen ruhen auf Euch, $N!', },
    {'Sammelt 6 Stück Tiefenflossenbeute.', },
  },
  [25977] = {
    'Ein standartenmäßiger Tag für Azrajar',
    {'$N, die Schlangen sind hinter unserer Armee her. Geht nach Nordwesten zum Tiefenflossengrat und steckt dem Futzi, den sie ihren Boss nennen, ein bisschen Holz zwischen die Rippen.|n|nWenn sie das sehen, werden sie Angst bekommen und abhauen mit dem Schwanz zwischen den Bei... ach nee, Beine haben sie ja gar keine.', },
    {'Rammt die Standarte der Allianz in Tiefenrufer Azrajars Leichnam.', },
  },
  [25978] = {
    'Im Eis eingeschlossen',
    {'Khurgorn sagt, der Kataklysmus habe das Gleichgewicht der Elemente auf der ganzen Welt erschüttert. Der Helmsbettsee im Süden war einmal wunderschön und ruhig, doch nun wimmelt es dort von wütenden Wasserelementaren. Als sie begannen, den See zu verlassen, schickte ich Truppen dorthin, um sie abzulenken, aber die meisten wurden in Eisblöcken eingefroren.|n|nWenn wir sie befreien können, werden sie sich wahrscheinlich erholen. Ich kann niemanden für eine zweite Expedition zum See entbehren. Würdet Ihr es versuchen?', },
    {'Öffnet sechs eisige Gräber, um die gefrorenen Gebirgsjäger am Helmsbettsee zu befreien.', },
  },
  [25979] = {
    'Glättet die Wogen',
    {'Die Elemente sind aufgewühlt, $C. Der Kataklysmus hat die schlafenden Wassergeister im Helmsbettsee südlich von hier geweckt. Sie sind wütend, verwirrt und nicht gewillt, sich meine Bitten anzuhören.|n|nIch habe alles versucht, um sie zu beruhigen und davon zu überzeugen, die Gebirgsjäger des Unteroffiziers nicht mehr anzugreifen.|n|nIch sage das nur ungern, aber uns bleibt keine andere Wahl -- wir müssen die Elementare töten.', },
    {'Tötet 6 Woger des Helmbettsees am Helmbettsee.', },
  },
  [25980] = {
    'Ein standartenmäßiger Tag für Azrajar',
    {'$N, die Naga sind hinter unseren Streitmächten her. Ihr müsst für mich zurück nach Nordwesten zum Tiefenflossengrat gehen und unsere Standarte in ihren General, Tiefenrufer Azrajar stechen.|n|nSie werden vor Angst davon schwimmen, mit dem Schwanz zwischen den… äh. Na ja, Beine haben sie ja wohl nicht, oder?', },
    {'Rammt die Standarte der Horde in Tiefenrufer Azrajars Leichnam.', },
  },
  [25981] = {
    'Das sind gar keine Masken',
    {'$N, da draußen sind dämonische Tintenfische, die die Köpfe der Gilblins fressen und ihre Körper übernehmen! Auch eine Art, an Sklaven zu kommen.|n|nKönntet Ihr nach Nordwesten in den Tiefenflossengrat oder die Frontlinie der Sira\'kess schwimmen und mir ein paar von diesen Gnadenlosen bringen?', },
    {'Sammelt 6 Köpfe eines Gnadenlosen.', },
  },
  [25982] = {
    'Das sind gar keine Masken',
    {'$N, da draußen sind dämonische Tintenfische, die die Köpfe der Gilblins fressen und ihre Körper übernehmen! Wir müssen verhindern, dass sie hierher kommen!|n|nKönntet Ihr nach Nordwesten in den Tiefenflossengrat oder die Frontlinie der Sira\'kess schwimmen und mir ein paar von diesen Gnadenlosen bringen? Bevorzugt tote Exemplare, schätze ich.', },
    {'Sammelt 6 Köpfe eines Gnadenlosen.', },
  },
  [25983] = {
    'Das Kap',
    {'Wir müssen diese Informationen zu Kapitän Taylor am Kap bringen. Er befindet sich im Nordwesten mit Erunak Steinsprecher und den Mitgliedern des Irdenen Rings.', },
    {'Sprecht mit Kapitän Taylor am Kap in Vashj\'ir.', },
  },
  [25984] = {
    'Das Kap',
    {'$N, ich möchte, dass Ihr diese Informationen zu Legionär Nazgrim am Kap bringt. Er befindet sich im Nordwesten mit Erunak Steinsprecher und diesen Leuten vom Irdenen Ring.', },
    {'Sprecht mit Legionär Nazgrim am Kap in Vashj\'ir.', },
  },
  [25985] = {
    'Schwingen über dem Hyjal',
    {'$N, ist es wahr, dass Ihr versuchen werdet, mit den Ahnen zu sprechen?|n|nSüdwestlich von hier befindet sich der Schrein von Aviana, der Mutter aller fliegenden Lebewesen. Dort lebt meine Lieblingslehrerin, Choluna. Ich habe noch nie jemanden kennengelernt, der so eins mit den Geistern dieser Welt war. Ihr könntet viel von ihr lernen!|n|nWegen der kürzlichen Angriffe ist der Schrein von der Außenwelt abgeschnitten. Aber aus der Luft könnt Ihr ganz einfach dorthin gelangen. Haltet nach dem größten Baum auf dem Hyjal Ausschau. Viel Glück!', },
    {'Findet Choluna im Schrein von Aviana auf dem Hyjal.', },
  },
  [25986] = {
    'Ärger am See',
    {'Ihr wart eine große Hilfe bei der Sicherung der Minen und der Rettung der gefangenen Minenarbeiter.|n|nEs wird den Senat freuen, dass Ihr und Hauptmann Tharrans Gebirgsjäger Fortschritte bei der Sicherung Dun Moroghs gemacht habt.|n|nMich besorgt allerdings, dass ich keine Berichte von Unteroffizier Bahrum und seiner Abteilung erhalten habe. Sie wurden nach Osten geschickt, auf die Straße, die zum Helmsbettsee führt. Dort sollten sie einen kleinen Außenposten errichten. Würdet Ihr zu Bahrums Posten reisen und nach dem Unteroffizier sehen?', },
    {'Sprecht mit Unteroffizier Bahrum an Bahrums Posten.', },
  },
  [25987] = {
    'Setzt es auf',
    {'He, $N! Ich habe eine tolle Idee für eine Verkleidung. Nehmt einen dieser gnadenlosen Wasauchimmers und setzt ihn Euch auf den Kopf.|n|nWas kann dabei schon schiefgehen?|n|nSeid Ihr bereit, ihn aufzusetzen?', },
    {'Beobachtet, was passiert, wenn Ihr einen Gnadenlosen auf Euren Kopf setzt.', },
  },
  [25988] = {
    'Setzt es auf',
    {'Ich habe eine tolle Idee für eine Verkleidung, aber ich brauche Eure Hilfe dabei, $N. Nehmt einen dieser gnadenlosen Leichname und setzt ihn Euch auf den Kopf.|n|nIch weiß, ich weiß, aber es ist tot. Was kann dabei schon schiefgehen, außer dass Ihr ein, zwei Tage übel riecht?|n|nSeid Ihr bereit, ihn aufzusetzen?', },
    {'Beobachtet, was passiert, wenn Ihr einen Gnadenlosen auf Euren Kopf setzt.', },
  },
  [25989] = {
    'Fang den Krebs',
    {'Jede Faser meines Körpers sagt mir, dass Nespirah versucht, mit mir zu sprechen, aber ich kann sie nicht hören. Vielleicht haben die Naga etwas mit ihrer Stimme angestellt.|n|n<Duran grübelt einen Moment vor sich hin.>|n|nNespirahs Stimme wird vielleicht unterdrückt... das bedeutet... dass wir eine Stimme für sie finden müssen!|n|nIch hab\'s! Idra\'kess\' Naga richten Tiefensucherkrebse als Schlachtgefährten ab. Benutzt dieses Netz, um einen Krebs zu fangen und bringt ihn mir. Wahrscheinlich findet Ihr sie am äußeren Rand der Kammer herumkrabbeln.', },
    {'Benutzt Duarns Netz, um einen Tiefensucherkrebs in Nespirah zu fangen.', },
  },
  [25990] = {
    'Durchbruch',
    {'Ein ausgebildeter Schamane kann mit den vier Elementen der Erde, des Feuers, der Luft und des Wassers kommunizieren. Das ist kein Geheimnis.|n|nWas jedoch viele nicht wissen ist, dass es noch ein fünftes Element gibt. Dieses Element ist nicht so eindeutig definiert wie die anderen vier, aber es hat etwas mit der... Gemeinsamkeit zwischen allen lebenden Wesen zu tun.|n|nIch bin der Meinung, dass der Krebs als Wesen des Meeres eng genug mit Nespirah verbunden ist. Mit ein wenig Überredungskunst der Elemente können wir ihn vielleicht dazu bringen, als Nespirahs Sprachrohr zu dienen.', },
    {'Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.', },
  },
  [25991] = {
    'Wir sind nicht allein',
    {'<Duarn schließt die Augen, hält einen Moment inne und nickt.>|n|nNespirah hat mir gerade berichtet, dass wir nicht die Einzigen sind, die in dieser Schale kämpfen. Eine kleine Gruppe von Hordesklaven ist entkommen und wehrt gerade die Naga auf der anderen Seite der Schale ab, oben auf dem Vorsprung über Nespirahs Herz.|n|nGeht und findet sie, $N. Schaut, wie Ihr sie unterstützen könnt. Mit ihrer Hilfe können wir Nespirah vielleicht aus ihrer Starre erwecken.|n|nIhr findet mich hier, falls Ihr etwas braucht.', },
    {'Findet die Überlebenden der Horde in Nespirah in Vashj\'ir.', },
  },
  [25992] = {
    'Hoffnungslos ausrüstungslos',
    {'Ich habe wirklich keine Ahnung, wie wir so lange hier überleben konnten. Die Naga haben mir meine Rüstung und meine Waffen genommen. Alles, was sie mir gelassen haben, sind Lumpen und eine Spitzhacke… und DIE ist schon vor einer halben Ewigkeit zerbrochen.|n|nWenn wir eine Chance haben wollen, das Blatt zu unseren Gunsten zu wenden, brauche ich etwas, mit dem ich kämpfen kann. Meinen Kameraden geht es genauso, aber sie sind sicher zu stolz, um es zuzugeben.|n|nIch habe in den Lagerbereichen der Naga Waffenregale gesehen. Ich bin zwar im Umgang mit einem Dreizack nicht sonderlich geübt, aber alles ist besser, als mit bloßen Händen zu kämpfen.', },
    {'Besorgt 4 entwendete Stangenwaffen aus den Waffenregalen in Nespirah.', },
  },
  [25993] = {
    'Voller Körpereinsatz',
    {'<Legionär Nazgrim lauscht aufmerksam, als Ihr das Gespräch zwischen Duarn und Nespirah wiedergebt.>|n|nIch verstehe. Also möchte das Wesen, dass wir ihm helfen, es zu wecken?|n|nWenn man bedenkt, dass Hunderte von Sklaven seine Perlen abbauen, muss es aber ganz schön fest schlafen. Vielleicht habt Ihr ja mehr Glück.|n|nMein Vorschlag? Sucht am Fleisch des Wesens nach Schwachstellen. Vielleicht findet Euer Schwert ja eine empfindliche Stelle. Dann wird es sicher zur Besinnung kommen.', },
    {'Greift 7 Abszesse von Nespirah an den Wänden von Nespirahs Körperkammer an.', },
  },
  [25994] = {
    'Immer noch wertvoll',
    {'Auch wenn ich nur wenig Zeit in den Perlenminen verbracht habe, bin ich doch neugierig, was die Naga vorhaben. Ja, ich weiß, dass die Naga Nespirah als Kriegsmaschine nutzen wollen, aber wenn das der Fall ist, warum verwenden sie dann Sklavenarbeiter, um ihre Perlen abzubauen?|n|nWenn wir es je schaffen, den Rumpf dieses Tiers zu verlassen, würde ich diese Gegenstände gerne untersuchen. Die Perlen, die wir in den Minen gefunden haben, waren zu groß, um sie zu tragen. Ich habe jedoch Kriegsherren und Propheten gesehen, die kleinere bei sich hatten.', },
    {'Besorgt 5 mysteriöse Perlen von Kriegsherren des Idra\'kess und Prophetinnen des Idra\'kess in Nespirah.', },
  },
  [25995] = {
    'Aufseher Idra\'kess',
    {'Meine Männer lassen nach, $N. Ich fürchte, wir können diesen Naga nicht mehr lange standhalten. Mit diesen Waffen des Idra\'kess und Nespirahs Perlen sollten wir bereit sein, von hier zu flüchten.|n|nFolgt der Wand in Richtung Nordosten und haltet nach einer Rampe Ausschau, die in die obere Kammer führt. Ich schätze, dass ihr Anführer sich dort aufhält. Vielleicht ist dort auch der Schlüssel zu Nespirahs Erweckung versteckt. Wenn wir Glück haben sogar beides.|n|nWenn Ihr Euch stark genug fühlt, geht in die Spitze und sucht nach Antworten. Höllschreis Augen ruhen auf Euch!', },
    {'Geht zur Spitze Nespirahs und tötet Aufseher Idra\'kess.', },
  },
  [25996] = {
    'Die Erweckung der Bestie',
    {'Dank Euch und dem Legionär hat Nespirah wieder die volle Kontrolle über ihren Körper… aber der Großteil der Naga weiß das noch nicht. Sobald wir geflüchtet sind, wird sie ihre biologischen Verteidigungsmechanismen aktivieren und die Naga von innen heraus vernichten.|n|nMacht Euch bereit... Ich sage Nespirah, dass sie die Verteidigung einleiten soll.', },
    {'Sprecht mit Erdheiler Duarn in Nespirah, um ihre biologische Verteidigung zu aktivieren und flieht dann aus Nespirahs Körper.', },
  },
  [25997] = {
    'Die Heimtücke der Dunkeleisenzwerge',
    {'Eine Gruppe Dunkeleisenspione hat Eisenbands Truppenlager im Süden, hinter dem Helmsbettsee übernommen. Die Gebirgsjäger wären normalerweise in der Lage, sie aus Dun Morogh herauszuhalten, aber es herrscht gerade Chaos.|n|nDie Dunkeleisenzwerge wären Narren, wenn sie das nicht zu ihrem Vorteil nutzen würden. Wir müssen herausfinden, was sie planen und sie aufhalten, bevor sie Schaden anrichten.|n|nKönntet Ihr versuchen herauszufinden, was sie in Eisenbands Truppenlager machen?', },
    {'Tötet 5 Spione der Dunkeleisenzwerge und erbeutet die Angriffspläne der Dunkeleisenzwerge von Hauptmann Beld in Eisenbands Truppenlager.', },
  },
  [25998] = {
    'Auf zum Flugplatz',
    {'Laut der Pläne, die Ihr erbeutet habt, planen die Dunkeleisenzwerge einen großangelegten Angriff auf den Flugplatz von Eisenschmiede! Der Rat hat einen Großteil unserer Streitkräfte nach Dun Morogh verlegt. Sie sollen sich dort um die Instabilität, die durch den Kataklysmus entstanden ist, kümmern. Die Verteidigungslinien des Flugplatzes sind geschwächt.|n|nWir müssen Euch so schnell wie möglich zum Flugplatz bringen. Nehmt die Straße zurück nach Westen, in Richtung des Steinbruchs Gol\'Bolar und findet Mathel Rostzange. Er sollte eine Flugmaschine für Euch haben. Geht!', },
    {'Steigt in Mathels Flugmaschine im Steinbruch Gol\'Bolar.', },
  },
  [25999] = {
    'Schritt für Schritt',
    {'Den schmutzigen, nichtsnutzigen Nachtelfen ist es gelungen, unser ganzes Minenfeld auf dem Steinkrallenpass zu entschärfen. Jemand muss dorthin zurückgehen und die Minen wieder scharf machen! Diese Aufgabe ist perfekt für einen wertlosen Grunzer wie Euch geeignet, $N. Hoffentlich jagt Ihr Euch dabei nicht selbst in die Luft.|n|nUnsere "Elfentöter" liegen überall auf dem Steinkrallenpass, unmittelbar nördlich von hier. Nehmt diesen Schraubenschlüssel und macht Euch an die Arbeit, Made.', },
    {'Macht 8 Krom\'gar "Elfentöter" scharf.', },
  },
  [26000] = {
    nil,
    {'Schnell, $N!|n|nBegebt Euch sofort zu dieser Höhle.|n|nWir werden Euch folgen und sicherstellen, dass Euch sonst niemand folgt.', },
    {'Sprecht mit Gurrok in der Tiefennebelgrotte.', },
  },
  [26001] = {
    'Der vermisste Sprengenieur',
    {'Ihr seid wohl doch nicht völlig nutzlos. Vielleicht bewältigt Ihr sogar eine etwas wichtigere Aufgabe.|n|nVor rund zwei Tagen habe ich Sprengenieur Fusselpfiff zur Scherwindmine geschickt. Er sollte sich dort davon überzeugen, dass alles mit der Bombe nach Plan läuft und sich dann wieder hier melden. Zwei Tage und nichts...|n|nBegebt Euch in den Wald südlich von hier und findet ihn. Wenn er Glück hat, ist er tot.', },
    {'Findet Sprengenieur Fusselpfiff.', },
  },
  [26002] = {
    'Angriffspläne der Allianz',
    {'<Ihr zieht die Notiz aus Fusselpfiffs toten Fingern.>|n|nSie wissen Bescheid! Sie wissen von der Bombe. Planen Angriff auf Feste Krom\'gar! Ich glaube, sie suchen mich. Werde nicht sterben wie ein Feigling. Ich werde kämpfen.|n|nIch glaube, da kommen sie! Ihre Anführerin ist eine Hochelfenjägerin namens Davinia. Sie sprach von den Angriffsplänen. Rächt mich, indem Ihr sie tötet und Euch die Pläne holt! Ihr Zelt steht östlich von hier, ganz in der Nähe.|n|nMöge Höllschrei über Euch wachen...', },
    {'Erbeutet die Angriffspläne der Allianz von Jägerin Davinia.', },
  },
  [26003] = {
    'Lehren von den Verlorenen Inseln',
    {'In den Wäldern südlich von hier lauern große Gefahren. Sie wimmeln von darnassischen Spähern - Assassinen, die aus Darnassus geschickt wurden, um uns zu töten. Vielleicht können wir den Spieß umdrehen.|n|nAls ich auf den Verlorenen Inseln festsaß, gab mir ein Goblin diese Infrarot-Hitzebrille. Mit ihr kann der Träger die Wärmesignatur bestimmter Kreaturen sehen. Nehmt die Brille und setzt sie in den Wäldern im Süden auf. Auf diese Weise werdet Ihr die Späher leicht entdecken können. Tötet so viele Ihr könnt! Für die Horde!', },
    {'Tötet 12 Späher von Darnassus.', },
  },
  [26004] = {
    'Feste Krom\'gar',
    {'Feste Krom\'gar ist unsere Hauptoperationsbasis im Steinkrallengebirge. Von hier aus überwacht Oberanführer Krom\'gar die militärischen Aktionen der Horde in dieser Region. Krom\'gar leitet die Berichte aller Ereignisse direkt an den Kriegshäuptling weiter.|n|nDie Angriffspläne, die Ihr uns gebracht habt, beschreiben einen Angriff, der bald gegen die Feste Krom\'gar geführt werden soll. Nehmt die Pläne und brecht zur Feste südwestlich von hier auf. Gebt sie dem Oberanführer.|n|nLebt wohl, $N. Höllschrei wacht wahrlich über Euch.', },
    {'Bringt die Angriffspläne der Allianz zu Oberanführer Krom\'gar in der Feste Krom\'gar im Steinkrallengebirge.', },
  },
  [26005] = {
    'Ein Hauch frischer Luft',
    {'Kapitän Taylor und viele der anderen Überlebenden sind bereits auf dem Weg an die Oberfläche. Ich bin mir sicher, dass viele davon einfach nur nach einem Weg suchen, diesem Ort für immer zu entfliehen, aber wir haben immer noch viel zu tun, wenn wir die Naga an ihrem Einmarsch in die Ebene des Wassers hindern wollen.|n|nZunächst müssen wir uns um das tentakelbewehrte Monster kümmern, das unsere Schiffe zerstört hat.|n|nHexasept hat die hier für Euch zurückgelassen. Sie sollten Eure Reise etwas beschleunigen.', },
    nil,
  },
  [26006] = {
    'Ein Hauch frischer Luft',
    {'Legionär Nazgrim und viele der anderen Überlebenden sind bereits auf dem Weg an die Oberfläche. Ich bin mir sicher, dass viele davon einfach nur nach einem Weg suchen, diesem Ort für immer zu entfliehen, aber wir haben immer noch viel zu tun, wenn wir die Naga an ihrem Einmarsch in die Ebene des Wassers hindern wollen.|n|nZunächst müssen wir uns um das tentakelbewehrte Monster kümmern, das unsere Schiffe zerstört hat.|n|nFiasco hat das hier für Euch zurückgelassen. Sie sollten Eure Reise etwas beschleunigen.', },
    nil,
  },
  [26007] = {
    nil,
    {'Dieser Krieger stand an der Schwelle zum Tod, aber ich fürchte, wir können nicht warten, bis er wieder ganz genesen ist. Er hat Informationen, die wir dringend brauchen.|n|nSeid geduldig mit ihm, aber sorgt dafür, dass er weiterredet, bis er uns alles gesagt hat.|n|nMit ein bisschen Glück erfahren wir, womit wir es hier zu tun haben.', },
    {'Sprecht mit Gurrok und erfahrt etwas über seine Tortur.', },
  },
  [26008] = {
    nil,
    {'Ich kann den Gedanken einfach nicht ertragen, dass so viele andere wie dieser Krieger inmitten von Naga eingesperrt sind.|n|nWir müssen etwas unternehmen, um sie zu retten!|n|nNehmt dies, $N. Wendet es an den Gefängniszellen an, um ihnen Auftrieb zu verleihen.|n|nWenn wir sie an die Oberfläche bringen können, haben sie wenigstens eine Hoffnung auf Rettung.', },
    {'Benutzt Moanahs Atemstein an 10 eingekerkerten Kriegern in der Umklammerung.', },
  },
  [26009] = {
    'Suchen und zerstören',
    {'Die Allianz rückt auf unsere Territorien im Steinkrallengebirge vor. Die Streitkräfte von Nordwacht haben unsere Blockade im Süden durchbrochen und besetzen nun das Scherwindtal westlich von hier. Im Norden werden wir von Nachtelfensoldaten angegriffen. All das muss aufhören!|n|nBegebt Euch ins Steinkrallengebirge und vernichtet alle Allianzsoldaten, die Euren Weg kreuzen. Ihr Tod soll als Warnung dienen.|n|nDas Steinkrallengebirge gehört der Horde!', },
    {'Tötet 20 beliebige Soldaten der Allianz im Steinkrallengebirge.', },
  },
  [26010] = {
    'Asche zu Asche',
    {'Die Allianz wird immer unverschämter. Westlich von hier, im Scherwindtal, haben Truppen der Nordwacht ein Lager aufgeschlagen. Zweifellos bereiten sie sich auf den Angriff vor, den Ihr uns gemeldet habt, $N. Soweit wird es nicht kommen!|n|nNehmt diesen Flammenwerfer. Den gleichen Flammenwerfer setzten meine Verbrenner ein, um unsere Feinde aus den Wäldern zu jagen. Zerstört damit die Zelte der Nordwacht. Lasst nur Asche zurück!', },
    {'Zerstört 8 Zelte der Nordwacht mit Krom\'gars Flammenwerfer.', },
  },
  [26011] = {
    'Feind der Horde: Marschall Paltrow',
    {'Meine Späher haben die Ursache dieses neuesten Fiaskos gefunden: Marschall Paltrow. Er kommandiert das Vorauslager der Nordwacht im Scherwindtal westlich von hier. Eliminiert ihn. Damit entfernt Ihr einen wichtigen Feldkommandanten der Allianz aus der Gleichung.|n|nPaltrow muss sterben, $N.', },
    {'Tötet Marschall Paltrow.', },
  },
  [26012] = {
    'Ärger im Wyrmruhtempel',
    {'Mein alter Freund Krasus berichtet von grässlichen Vorkommnissen im Wyrmruhtempel in der Drachenöde. Sein Schreiben war kurz, doch es scheint, dass eine Art Angriff auf das Rubinsanktum unterhalb des Tempels stattgefunden hat.|n|nDringende Angelegenheiten hier in Dalaran halten mich davon ab, mich persönlich um die Sache zu kümmern, doch sind mir Berichte Eurer Heldentaten in der Zitadelle des Lichkönigs zu Ohren gekommen und Ihr seid zweifellos dieser Aufgabe gewachsen - vielleicht könntet Ihr an meiner statt Krasus behilflich sein?', },
    {'Sprecht mit Krasus im Wyrmruhtempel in der Drachenöde.', },
  },
  [26013] = {
    'Angriff auf das Sanktum',
    {'$R, etwas Schreckliches ist im Rubinsanktum unterhalb des Tempels geschehen.|n|nDer Eingang zum Sanktum liegt in Ruinen und seine Wächter sind auf grausame Art und Weise erschlagen worden. Wir haben Kundschafter ausgesandt, um der Sache auf den Grund zu gehen, aber sie sind nicht zurückgekommen. Nun befürchte ich das Schlimmste.|n|nBetretet das Rubinsanktum und bringt in Erfahrung, was in der Heimat meines Schwarmes passiert ist. Sobald wir mehr Informationen haben, können wir unsere nächsten Schritte entsprechend planen.', },
    {'Untersucht das Rubinsanktum unterhalb des Wyrmruhtempels.', },
  },
  [26014] = {
    'Die Gebrüder Grabungslied',
    {'Stillgestanden, $GGefreiter:Gefreite; $N! Wir chaben kleine Problem!|n|nWir chaben geschickt Humphrey und Oskar Grabungslied zur Tiefenlichtkluft im Njordwesten, aber sie sind nicht zurückgekommen. Sie sollten ausspähen Umgebung, aber wir chaben verloren jeden Kontakt zu ihnen.|n|nEure Aufgabe, $GGefreiter:Gefreite; $N, ist zu finden unsere Genossen und, falls sie noch ljeben, sie zu mir zurückzubringen!', },
    {'Meldet Euch bei Humphrey Grabungslied in der Tiefenlichtkluft in Vashj\'ir.', },
  },
  [26015] = {
    'Phosphorajagd',
    {'Oskars letzter Wunsch, bevor er im Rachen dieses Großaals verschwand, war, dem Käpt\'n Nahrung zu bringen. Also werden wir ihm diesen Wunsch erfüllen.|n|nMein Bruder hatte einen genialen Plan. Er hat beobachtet, wie diese Murlocs mit phosphoreszierenden Antennen Fische aus dem Schilf locken. Daraufhin hat er einen Weg gefunden, ein eigenes Gerät zu bauen. Ihr braucht nur etwas, das leuchtet.|n|nTötet die Krebse und Barsche am Grund der Kluft. Sie selbst sind nicht essbar, aber ihr Phosphora ist weitaus wertvoller als ihr Fleisch.', },
    {'Besorgt Euch 6 Tiefenlichtphosphora von den Pyropanzerkrabblern und Luxschuppenbarschen in der Tiefenlichtkluft.', },
  },
  [26016] = {
    'Befehle aus dem Basislager',
    {'Paltrow, errichtet einen Stützpunkt im Scherwindtal. Ein starker Bodenangriff ist lebenswichtig für unseren Feldzug! Wenn wir Krom\'gar angreifen, werden Eure Männer für das Chaos und die Verwirrung sorgen, die unsere Gnomflugmaschinen brauchen, um nahe genug für einen Bombenangriff an die Orcfestung zu kommen.|n|nDie Flugmaschinen werden die Bombe von Krom\'gar zünden, während sie noch in ihrer Basis steht und damit die gesamte Festung auslöschen.|n|nNach dem Lesen verbrennen.|n|n-Truppenkommandant Valen|n|nBasislager der Nordwachtexpedition', },
    {'Bringt die Befehle des Stützpunkts zu Oberanführer Krom\'gar in der Feste Krom\'gar im Steinkrallengebirge.', },
  },
  [26017] = {
    'Ein Köder',
    {'Bringt dieses Gerät an Eurem Kopf an und schwimmt dann durch den Tang und die Korallen am Rand der Kluft. Es sollte dort haufenweise kleine Fische geben, die Eure neue Antenne ganz unwiderstehlich finden werden.|n|nWenn wir zur Dämmerbucht zurückkehren, werden wir Berge von Fischen für alle haben!', },
    {'Setzt die Phosphorafedora auf und schwimmt durch die Korallen in der Tiefenlichtkluft, um 30 Tiefenlichtknabberfische anzulocken.', },
  },
  [26018] = {
    'Licht aus für die Tiefenlichter',
    {'Ach, stimmt! Ich sollte ja einen Bericht erstellen! Fast hätte ich es vergessen!|n|nSieht eigentlich nach größtenteils harmlosen Wildtieren aus hier… Bis auf diese verdammten Aale. Und ein paar Murlocs. Ich schätze, der Käpt\'n wird sich wohl eher für die Murlocs interessieren.|n|nFordert ein paar von ihnen zum Kampf raus und schaut, was sie so drauf haben. Soweit ich weiß jagen die großen im Tang nach Fischen und die kleinen praktizieren irgendeine Art von Magie oder so... aber mehr weiß ich auch nicht.', },
    {'Tötet 4 Tiefenlichtjäger und 4 Tiefenlichtorakel.', },
  },
  [26019] = {
    'Enormes Aalei',
    {'<Dies scheint ein Ei eines dieser verschlagenen Großaale zu sein, die über der Kluft umherschwimmen. Ihr fragt Euch, ob Humphrey vielleicht daran interessiert sein könnte.>', },
    {'Bringt das enorme Aalei zu Humphrey Grabungslied am Grund der Tiefenlichtkluft in Vashj\'ir.', },
  },
  [26020] = {
    'Meldet Euch bei Bombgutz',
    {'Wir müssen uns auf den bevorstehenden Angriff vorbereiten. Unsere Soldaten sollen die Bombe für den Transport bereitmachen. Ihr meldet Euch bei Obersprengenieurin Bombgutz. Sie versucht, unsere Luftabwehrkanonen zu reparieren, bislang jedoch erfolglos. Stellt sicher, dass ihre Motivation für die Reparatur der Kanonen ausreicht, $N.', },
    {'Meldet Euch bei Obersprengenieurin Bombgutz in der Feste Krom\'gar im Steinkrallengebirge.', },
  },
  [26021] = {
    'Die Gebrüder Grabungslied Teil 2: Der Eier-Aal-Trick-Blues',
    {'Diese Aale haben meinen Bruder gefressen. Meinen Bruder, $N! Es ist Zeit, dass ihnen jemand zeigt, wer hier der Boss ist.|n|n<Humphrey nimmt mehrere Dynamitstangen aus seiner Weste und schiebt sie durch die Außenhaut des Eis.>|n|nDiese Großaale im Süden sind zu stark, um alleine gegen sie anzutreten, aber mit diesem Ei sollten wir für Chancengleichheit sorgen können. Legt es in der Nähe dieser Biester ab und dann... Kabumm!|n|nWenn die Bombe den Aal nicht sofort tötet, sollte er zumindest dem Tod nahe sein, sodass Ihr ihm leicht ein Ende setzen könnt.', },
    {'Benutzt das aal-splosive Gerät in der Nähe eines verschlagenen Großaals in der Tiefenlichtkluft und besiegt dann den geschwächten Großaal.', },
  },
  [26022] = {
    'Das erste Blut',
    {'Seid bereit, $N. Ihr werdet für uns das erste Blut auf diesem Land vergießen.|n|nDas Syndikat, so nennen sie sich, besteht aus feigen Menschen, die sogar ihr eigenes Volk verraten. Ihre Isolation macht sie zu einer leichten Beute.|n|nReist nach Norden, tötet alle Syndikatssöldner, die Ihr findet und erobert Nordhof im Namen der Verlassenen. Bringt mir die Blutsteinamulette, die sie tragen, als Zeichen Eurer Eroberung.', },
    {'Erbeutet 10 Blutsteinamulette von Mitgliedern des Syndikats.', },
  },
  [26023] = {
    'Der Trollbann der Verlassenen',
    {'Ich werde Euch eine Geschichte erzählen.|n|nEs gab einmal einen einfältigen Troll namens Zengu. Man befahl ihm, das Schwert Trol\'kalar zu finden, die legendäre Klinge der menschlichen Trollbannlinie. Das gelang ihm. Er dachte, seine Aufgabe sei erfüllt und wollte Arathi allein verlassen. Dabei wurde er von den Menschen getötet, die das Schwert einfach wieder an sich nahmen.|n|nWir werden nicht so einfältig sein. Unsere Apotheker haben uns jemanden gebracht, der uns helfen wird, Trol\'kalar wiederzubeschaffen: den Prinzen, der es einst besaß.|n|nEr wartet darauf, Euch zu führen, $N. Sprecht mit ihm.', },
    {'Sprecht mit Galen Trollbann.', },
  },
  [26024] = {
    'GESUCHT: Marez Schattenkutte',
    {'Es wurde ein Kopfgeld auf Marez Schattenkutte ausgesetzt, einer hochrangigen Beraterin und Agentin des Syndikats. Sie wurde zuletzt in dem vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.|n|nDas Kopfgeld kann von Hauptmann Nials abgeholt werden.|n|nIch warne Euch: Marez ist eine geschickte und gerissene Hexenmeisterin und bekannt dafür, dass sie sich mit Dämonen abgibt. Bei ihrer Verfolgung ist äußerste Vorsicht geboten.', },
    {'Bringt Marez\' Kopf zu Hauptmann Nials bei der Zuflucht.', },
  },
  [26025] = {
    'Der verräterische Orc',
    {'Ich bin mir sicher, dass eine mächtige Hexenmeisterin in den Mauern von Burg Stromgarde haust. Von Zeit zu Zeit beschwört diese Hexenmeisterin mit Hilfe eines arkanen magischen Relikts schreckliche Dämonen in großer Anzahl. Wir müssen die Quelle ihrer Energie entfernen.|n|nFindet und tötet die Hexenmeisterin. Bringt mir das magische Objekt, das sie bei sich trägt. Dann werde ich dafür sorgen, dass es zerstört wird und dass ihre Macht nie wieder unser Land besudelt.', },
    {'Erbeutet Marez Schattenkuttes beschmutzte Blutsteinkugel.', },
  },
  [26026] = {
    'Traum von einer besseren Zukunft',
    {'Herr Rosie ist krank, $Gehrenwerter:ehrenwerte:r; <Volk>. Könnt Ihr ihm helfen? Ihr müsst nur seinen Hut und seine Batterien finden, dann wird es ihm wieder gut gehen. Ich würde sie selbst holen, aber ich kann Herrn Rosie nicht allein lassen!|n|nDie gemeinen Kerle der Venture Company, hinten am Wasserrad, haben seinen Hut gestohlen und seine Batterien sind irgendwo an der Scherwindklippe versteckt. Ihr werdet richtig gut nach ihnen suchen müssen!|n|nWürdet Ihr bitte Herrn Rosies Besitz zurückbringen, damit er den Fieslingen von der Allianz eine Lektion erteilen kann?', },
    {'Bergt die BD-816 Kriegsmaschine, das mechanisierte Feuer, das mechanisierte Eis und die mechanisierte Luft.', },
  },
  [26027] = {
    'Zu den Waffen',
    {'Unser nächster Schlag gegen die Oger wird Euch tiefer in den Osten nach Burg Stromgarde führen. Die Lebenden klammern sich weiter an diese verfallenen Ruinen. Ihre Sentimentalität ist widerwärtig!|n|nFür uns ist Burg Stromgarde nicht mehr als ein verdorbener Bau voller Oger, die auf ihr Ende warten. Reist dorthin. Tötet ihre Schamanen und ihre Lords und sorgt dafür, dass das, was bei den Ogern als Führung durchgeht, vernichtet wird.', },
    {'Tötet 7 Schamanen der Felsfäuste und 3 Lords der Felsfäuste in Stromgarde.', },
  },
  [26028] = {
    'Herr Rosies wilder Ritt',
    {'Herr Rosie braucht jetzt einen Engel, der ihm bei der Navigation hilft. Werdet Ihr dieser Engel sein, $Gehrenwerter:ehrenwerte:r; <Volk>? Mit Eurer Hilfe können wir es bis zur Klippe schaffen und viele, viele Allianzkämpfer töten. Was meint Ihr? Och bitte, <edler/edle:c> $C! BITTE BITTE BITTE BITTE?|n|nWenn wir genügend Allianzler umbringen, kauft Herr Krom\'gar uns allen ein Eis!', },
    {'Tötet 20 Gnomingenieure und 5 Gnomklopfer.', },
  },
  [26029] = {
    'Die echte Bedrohung',
    {'Or\'Kalar führt die Oger hier an. Seit Jahren entgeht er seinen Schlächtern. Seine Existenz ist eine Beleidigung der Dunklen Fürstin. Mug\'thol, Verräter der Verlassenen, kommandiert ihn aus der Ferne!|n|nWir tolerieren weder Oger noch Verräter im Gebiet der Verlassenen. Bringt mir den Kopf des Ogers. Dann sorge ich dafür, dass er dieses Mal richtig verbrannt wird.', },
    {'Tötet Or\'Kalar und nehmt seinen Kopf.', },
  },
  [26030] = {
    'Siegelzeichen von Strom',
    {'In grauer Vorzeit führte Lord Ignaeus von Strom, den sie Trollbann nannten, die erste menschliche Zivilisation von Arathor in den Krieg gegen die Trolle. Seine Klinge hieß Trol\'kalar – was in ihrer alten Sprache Trolltöter heißt.|n|nIch war einer der letzten seines Geblüts und hatte die Aufgabe, Trol\'kalar zu hüten... eine Aufgabe, bei der ich versagt habe. Aber jetzt werden wir die Klinge für meinen neuen Meister erneut in unseren Besitz bringen.|n|nDas Schwert wird von drei Siegelzeichen beschützt. Der erste befindet sich in den Händen der Verräter des Syndikats, die in den Ruinen von Stromgarde herumlungern. Tötet sie und bringt das Siegelzeichen zu mir.', },
    {'Erhaltet das Siegelzeichen von Strom von den Mitgliedern des Syndikats in Burg Stromgarde.', },
  },
  [26031] = {
    'Siegelzeichen des Thoradin',
    {'Als ich noch lebte, zerbrach ich das Siegelzeichen des Thoradin in fünf Teile, um es zu schützen. Ich gab sie meinen loyalsten Männern. Das schlug ebenfalls fehl, aber mein Nachfolger wird dasselbe getan haben.|n|nDie Verteidiger von Burg Stromgarde tragen die Teile des Siegelzeichens wieder bei sich. Tötet sie und bringt mir die Scherben; ich werde sie zusammensetzen.', },
    {'Erbeutet 5 Siegelzeichenfragmente von Vollstreckern von Stromgarde in Burg Stromgarde.', },
  },
  [26032] = {
    'Siegelzeichen von Arathor',
    {'Ich habe dieses Siegelzeichen Leutnant Heldenruf, dem Anführer meiner Kavallerie, anvertraut. Er hätte beinahe sein Leben verloren, als es gestohlen wurde.|n|nDieses Mal wird er wohl weniger Glück haben. Heldenruf patrouilliert zwischen Burg Stromgarde und der Zuflucht. Findet ihn und nehmt ihm noch einmal das Siegelzeichen ab.', },
    {'Nehmt Leutnant Heldenruf das Siegelzeichen von Arathor ab.', },
  },
  [26033] = {
    nil,
    {'Ich habe das letzte Siegelzeichen... und mit ihm vereine ich die vier zum Siegelzeichen von Trollbann, dem Schlüssel zur Gruft. Wir sind bereit.|n|nTrol\'kalar wurde gemeinsam mit den Überresten seines Herrn eingeschlossen. Es liegt in Trollbanns Grabmal in den Katakomben von Burg Stromgarde. Es wird schwer bewacht sein... aber dass ich vor Euch stehe, beweist, dass die Vollstrecker besiegt werden können.|n|nBetretet das Grabmal, bergt Trol\'kalar und bringt es her.', },
    {'Bergt Trol\'kalar aus Trollbanns Grabmal in Burg Stromgarde.', },
  },
  [26034] = {
    'Der Zwielichtzerstörer',
    {'Dies war kein leichtfertiger Angriff, sondern vielmehr ein sorgsam inszenierter Schlag gegen das Herz des roten Drachenschwarms.|n|nZarithrian, der sich auf dem Felsvorsprung dort drüben befindet, überwacht den Angriff, doch ist der wahre Anführer ein dreister und mächtiger Zwielichtdrache namens Halion. Seit Dargonax ist kein ausgewachsenes Exemplar der Brut aus Sinestras verdorbenen Experimenten mehr gesichtet worden.|n|nTötet ihn, $N. Sobald es Euch gelungen ist, diese Invasion zurückzudrängen, meldet Ihr Euch bei Krasus und berichtet ihm, was Ihr hier gesehen habt.', },
    {'Besiegt Halion und drängt die Invasion des Rubinsanktums zurück.', },
  },
  [26035] = {
    'Sein Gewicht in Gold',
    {'Erzmagier Malin hat mich hierher geschickt, um Reagenzien für ihn zu sammeln. Ich habe mich gefragt, wie ich ihm die Gegenstände besorgen soll, aber nun, da Ihr hier seid, könnte sich dieses Problem erledigt haben.|n|nIch benötige Hauer der Bleichborken und Medizinbeutel der Bleichborken.|n|nWürdet Ihr sie für mich holen? Die Bleichborken leben südöstlich von Arathi.', },
    {'Erbeutet 10 Hauer der Bleichborken und 4 Medizinbeutel der Bleichborken von Trollen der Bleichborken.', },
  },
  [26036] = {
    'Zauberstab gegen Faust',
    {'He, $N. Tut mir leid, dass ich früher Euch gegenüber so kurz angebunden war... und nein, das sollte jetzt kein Wortspiel sein.|n|nIch habe herausgefunden, wo Trelanes erster Gegenstand gelandet ist: Kor\'gresh in der Halle der Felsfäuste hat ihn. Und so wie er seinen Leuten die Hölle heiß gemacht hat, damit sie nicht aus der Reihe tanzen, muss er wohl kurz davor sein herauszufinden, wie man seine gesamte Macht nutzen kann.|n|nDie Halle der Felsfäuste liegt südlich von hier und östlich vom Thandolübergang. Findet diesen Oger und holt den Zauberstab.|n|nWährend Ihr weg seid, werde ich versuchen herauszufinden, was wir wegen Stromgarde unternehmen können.', },
    {'Sucht Trelanes Zauberstab der Herbeirufung und bringt ihn Skuerto bei der Zuflucht.', },
  },
  [26037] = {
    'Trelanes Verteidigung',
    {'Na, erholt?|n|nDas hier ist der nächste Schritt: Um den Turm von Arathor in Stromgarde herum wimmelt es nur so von Ogern. Wir müssen Euch gegen die Verteidigungsanlagen des Turms einsetzen. Dazu brauchen wir ein paar Edelsteine, an denen der Schamane der Felsfäuste Gefallen gefunden hat. Sie nahmen die aus dem Turm, aber sie werden nicht mehr lang in ihrem Besitz bleiben.|n|nHolt einen dieser Edelsteine und bringt ihn Kryten - er kennt den Zauber, mit dem man sie verzaubern kann.', },
    {'Sucht einen azurblauen Achat und bringt ihn Lehrling Kryten in Burg Stromgarde.', },
  },
  [26038] = {
    'Angriff auf den Turm',
    {'Hier ist das, wonach Ihr suchen müsst: Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat.|n|nAlle drei liegen in Kisten innerhalb des Turms. Die Kisten solltet Ihr allein problemlos öffnen können, passt nur auf die Oger auf.|n|nHaltet Eure Waffen bereit. Wenn die Oger herausfinden, dass Ihr dort seid und sie bestehlen wollt, dann werden sie nicht zimperlich mit Euch umgehen.|n|nSeid vorsichtig und viel Glück.', },
    {'Sucht Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat und bringt ihn Skuerto bei der Zuflucht.', },
  },
  [26039] = {
    'Die gefangene Prinzessin',
    {'Mein Name ist Myzrael. Ich bin eine Prinzessin der Erde und meine Häscher, die Riesen, halten mich tief unterhalb des Arathihochlandes fest. Diese Kristallsplitter sind meine einzige Möglichkeit, mit der oberen Welt zu sprechen.|n|nBitte helft mir! Kobolde der Trockenstoppel, die Verbündete der Riesen sind, haben einen Splitter wie diesen hier in ihrer Schlucht im Osten. Um die Gruppe zu aktivieren, müsst Ihr die Körner von Myzrael von den Kobolden holen und sie an der Gruppe anwenden.|n|nIch flehe Euch an, $N, helft mir!', },
    {'Sammelt 12 Körner von Myzrael von Kobolden der Trockenstoppel.', },
  },
  [26040] = {
    'Keine Macht den Algen',
    {'Wa… was IST das?!|n|nIch habe so starke Schmerzen… tief in meinem Bauch.|n|nIch glaube… uff… Sie müssen mich vergiftet haben!|n|nSie haben uns merkwürdig leuchtende Algen zu essen gegeben, die sie um ihre Festung herum anbauen…|n|nIch glaube, diese Krämpfe werden immer schlimmer, wenn ich nicht bald mehr davon bekomme...|n|nBitte, <Volk>. Bringt mir etwas davon!', },
    {'Sammelt 7 Schlängelgrassprösslinge von Erntern der Schimmerrücken in der Umklammerung.', },
  },
  [26041] = {
    'Steine der Bindung',
    {'Vier Steine der Bindung sind in ganz Arathi verteilt. Diese Steine halten mich unter der Erde fest.|n|nUm sie zu öffnen, müsst Ihr den stärksten öffnen: den Stein der Inneren Bindung. Um das tun zu können, müsst Ihr Schlüssel von den drei Übrigen sammeln.|n|nDiese Steine werden von Wächtern bewacht, aber wenn Ihr es geschickt anstellt oder Glück habt, findet Ihr vielleicht einen Weg, sie auszuschalten.', },
    {'Holt den brennenden Schlüssel, den schäumenden Schlüssel und den donnernden Schlüssel vom Stein der Westlichen Bindung, dem Stein der Östlichen Bindung und dem Stein der Äußeren Bindung.', },
  },
  [26042] = {
    'Den Hauptstein zerbrechen',
    {'Das Öffnen der Steine der Bindung hat den Großteil meiner Fesseln gelöst, aber ein Schloss hält mich immer noch gefangen. Es ist der Hauptstein, den Ihr in diesem Kreis von Steinen sehen könnt. Und der Schlüssel wird von einem meiner Häscher bewahrt, dem Steinbehüter Fozruk.|n|nIhr müsst diesen Schlüssel, den die Steinbehüter die Rute der Ordnung nennen, von Fozruk in Besitz nehmen und mit ihm den Hauptstein öffnen.|n|n$N, Ihr habt schon so viel für mich getan. Nur noch eine kleine Hilfe... und meine Dankbarkeit wird die Erde in ihren Grundfesten erschüttern!', },
    {'Beschafft die Rute der Ordnung von Fozruk.', },
  },
  [26043] = {
    'HÜTET EUCH VOR FELSKIEFER!',
    {'Auf Befehl von Oberanführer Krom\'gar ist das Betreten des Felskesselsees VERBOTEN!|n|nDie wilde Bestie, die Felskiefer genannt wird, hat den See in eine Todesfalle verwandelt. Solltet Ihr Felskiefer beseitigen, nehmt seinen riesigen Zahn als Trophäe und bringt ihn zur Herrin der Spione Anara. Sie wird Euch belohnen.', },
    {'Tötet Felskiefer und nehmt Euch Felskiefers riesigen Zahn.', },
  },
  [26044] = {
    'Wo sind die Teile?',
    {'Ich warte seit Tagen auf Teile für diese Waffen! Ich habe einen meiner besten Sprengenieure und zwei Dutzend Minenarbeiter vor fünf Tagen in die Ausufernden Tiefen geschickt, um die Teile zu besorgen. Als ich drei Tage später noch nichts von ihnen gehört hatte, begann ich mir Sorgen zu machen. Der Oberanführer schickte zwei seiner besten Orcs hinterher. Seitdem haben wir nichts gehört...|n|nBegebt Euch in die Ausufernden Tiefen, unmittelbar unter dieser Festung, und findet heraus, was los ist! Ich brauche die Teile!', },
    {'Sprecht mit Unteroffizier Dontrag in den Ausufernden Tiefen im Steinkrallengebirge.', },
  },
  [26045] = {
    'Eure Teile sind schon hier...',
    {'Mein Dilemma sieht so aus: Ich habe zwei Möglichkeiten. Entweder lasse ich mich wie alle anderen hier unten umbringen oder ich werde in der Feste Krom\'gar umgebracht, wenn Krom\'gar erfährt, dass wir die Mine verloren haben. Ich wähle die dritte Möglichkeit: nichts tun. Klappt bisher ganz gut.|n|nIhr braucht Teile? In der Mine liegt eine Menge Schrott herum. Ihr müsst ihn nur holen.|n|nViel Glück! Wenn Ihr diese Teile holt, können wir uns vielleicht wieder in der Feste Krom\'gar blicken lassen.', },
    {'Sammelt 10 Ersatzteile.', },
  },
  [26046] = {
    'Was immer wir tun...',
    {'Dontrag kann das besser erklären als ich. Was auch immer wir tun, es ist das Falsche. Wir können hier unten nichts tun wegen all der Dinge, die uns umbringen wollen und können nicht zur Basis zurückkehren wegen all der Dinge, die uns umbringen wollen - verstanden?|n|nVielleicht können wir dieses Problem ja gemeinsam lösen. Beseitigt Ihr doch schon mal ein paar dieser Elementare, die anscheinend alles in der Mine umgebracht haben, einverstanden?', },
    {'Tötet 12 tobende Erdelementare.', },
  },
  [26047] = {
    'Deshalb nennt man sie Peons...',
    {'Die beiden sind NUTZLOS! Als sie eintrafen, dachte ich, wir wären gerettet. Aber nein! Stattdessen warfen Dontrag und Utvoch einen Blick in die Mine und dachten sich einen idiotischen Plan aus, der vor allem aus Herumstehen besteht... wahrscheinlich, bis wir alle tot sind. |n|nIhr seht nicht ganz so nutzlos aus. Wollt Ihr uns helfen, $GFreund:Freundin;? In den Ausufernden Tiefen verstecken sich Dutzende von Peons, die nur noch Angst in der Birne haben. Findet sie und holt sie raus!', },
    {'Rettet 10 verängstigte Peons.', },
  },
  [26048] = {
    'Ersatzteile hier herauf!',
    {'Puh, das war hart. Ich dachte, wir würden es nicht schaffen, $N. Am besten bringen wir diese Teile zurück zu Obersprengenieurin Bombgutz. Ich glaube, ich höre draußen schon das Summen der Gnomflugmaschinen. Wir haben keine Zeit zu verlieren!', },
    {'Bringt die Kiste mit Ersatzteilen zu Obersprengenieurin Bombgutz in der Feste Krom\'gar im Steinkrallengebirge.', },
  },
  [26049] = {
    'Die entfesselte Prinzessin',
    {'Myzrael ist keine unschuldige Prinzessin. Sie ist unglaublich gefährlich. Die Riesen hatten sie aus gutem Grund dort unten angekettet. Man hat Euch leider betrogen.|n|nGerrig sagt, dass Ihr sie bei den Splittern von Myzrael, dort, wo Ihr zuerst mit ihr gesprochen habt, beschwören müsst. Besiegt sie und nehmt Euch ihre geisterhaften Fesseln. Bindet sie damit an die Splitter.|n|nIhr werdet diese Schriftrolle brauchen. Geht sorgsam mit ihr um; ich habe ein paar Zähne riskiert, um sie zu bekommen. Viel Glück, $N.', },
    {'Ruft Myzrael an den Splittern von Myzrael herbei und besiegt sie.', },
  },
  [26050] = {
    'Leuchtbrille',
    {'Da wir jetzt richtige Schwarzmeerräuber sind, ist es nun unsere Aufgabe, Herrn O\'Breen bei der Suche nach dem verlorenen Elfenschatz behilflich zu sein.|n|nEs ist fast unmöglich, die Edelsteine ohne Hilfe im dunklen Meer zu finden. Der Doktor hat eine Schutzbrille konstruiert, die dabei hilft. Er muss die Schutzbrille mit der Energie aufladen, die von dem verzauberten Stein in der Höhle auf dem Hügel dort ausgeht.|n|nAber die Höhle ist verflucht! Sobald wir uns ihr nähern, werden wir überfallen. Wenn Ihr mich verteidigt, kann ich die Energie vom Stein in die Schutzbrille leiten.', },
    {'Begleitet Professor Prasseltrop zur Höhle und zurück.', },
  },
  [26051] = {
    'Versunkener Schatz',
    {'Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.|n|nEin wenig gnomischer Einfallsreichtum ist schon was Schönes!|n|nAlso nehmt Euch die Edelsteinjagdschutzbrille, $N, und versucht, ein wenig vom verlorenen Schatz für Kapitän O\'Breen einzusammeln.|n|nIch würde ja selbst hinuntertauchen, aber... ähem... ich, nun ich muss mich um äußerst wichtige wissenschaftliche Dinge kümmern, oben auf dem sicheren, trockenen Land... ähem, ja.', },
    {'Doktor Drechselknacks in der Faldirbucht will, dass Ihr 10 Elfenedelsteine einsammelt und die Edelsteinjagdschutzbrille zurückgebt, sobald Ihr fertig seid.', },
  },
  [26052] = {
    'Sprecht mit Wank',
    {'Wir sollten Kapitän O\'Breen nicht warten lassen. Er wird diese Edelsteine sofort sehen wollen. Darum sind wir ja schließlich hier!|n|nUnd nach ein paar Wochen Zusammenleben mit diesen Piraten sind der Professor und ich zum Schluss gekommen, dass es ganz und gar nicht gut für unsere Gesundheit ist, wenn sie denken, dass wir uns ihre Schätze einverleiben wollen.|n|nHier, $N, bringt das zu O\'Breen.', },
    {'Bringt die Elfenedelsteine zu Kapitän O\'Breen in die Faldirbucht im Arathihochland.', },
  },
  [26053] = {
    'Säuberung des Hochlands',
    {'Wir werden keine Bedrohung übersehen. Um dieses Land zu sichern und der Dunklen Fürstin zu unterwerfen, müssen wir alles, was auf ihm lebt, herausreißen, Stück für Stück, Meter für Meter.|n|nIm Nordosten, weniger als einen Steinwurf von diesem Lager entfernt, befindet sich ein Ogerhügel. Die Oger der Felsfäuste, die dort leben, müssen ausgelöscht werden, $C.|n|nSie stehen uns im Weg. Zögert nicht und seid nicht gnädig.', },
    {'Tötet 8 Oger der Felsfäuste und 10 Vollstrecker der Felsfäuste.', },
  },
  [26054] = {
    'Wasser haben die vor?',
    {'Die Sandwütertrolle und der Schattenhammer stecken unter einer Decke?!|n|nGanz gleich. Diese schändliche Hexe wird ihr Monster nicht über MEINE Stadt herfallen lassen.|n|nAuf, ihr Mutigen! Wir werden den Sand mit ihrem Blut tränken und siegreich nach Hause zurückkehren. Berichtet General Marcus Jonathan von den Vorfällen hier, wenn wir zurückgekehrt sind. Ich muss mich um die Rückkehr der Bürgerschaft, Reparaturen und dergleichen kümmern.', },
    {'Tötet Kai\'ju Gahz\'rilla und informiert General Marcus Jonathan in Sturmwind darüber.', },
  },
  [26055] = {
    'Ertrunkene Trauer',
    {'Grr, \'s ist ein elendes Leben. Ich sollte in meinem nassen Grab liegen und nicht hier am Feuer sitzen und frische Luft atmen.|n|nDie Crew hat ihr Bestes gegeben um meine wunderschöne Tolle Minna zu retten. Gesegnet seien die Jungs, gesegnet ihre Herzen.|n|nO\'Breen hat es sicher ans Ufer geschafft, aber wir hatten nicht so viel Glück. Das Meer sank einfach auf uns herab, ich schwöre es!|n|nIn der einen Sekunde lagen wir auf dem Wasser und in der nächsten stürmte das Wasser auf uns ein. Und diese Bestien! Haben alle Überlebenden getötet. Elender Nagaabschaum. Mir gingen die Lichter aus und ich kam hier oben wieder zu mir, gerettet.|n|nIch will diese Biester tot sehen.', },
    {'Kapitän Stahlmagen in der Faldirbucht will, dass Ihr 10 Räuber der Säbelflossen und 3 Zauberinnen der Säbelflossen tötet.', },
  },
  [26056] = {
    'Die Wellensprecherin',
    {'Ein Mitglied des Irdenen Rings, Wellensprecherin Valoren, ist in die Alptraumtiefen im Nordosten hinab geschwommen. Wir haben schon eine ganze Weile nichts mehr von ihr gehört.|n|nSchwimmt dorthin und schaut, ob Ihr sie finden könnt.', },
    {'Findet Wellensprecherin Valoren in den Alptraumtiefen in Vashj\'ir.', },
  },
  [26057] = {
    'Die Wellensprecherin',
    {'Ein Mitglied des Irdenen Rings, Wellensprecherin Valoren, ist in die Alptraumtiefen im Nordosten hinab geschwommen. Wir haben schon eine ganze Weile nichts mehr von ihr gehört.|n|nSchwimmt dorthin und schaut, ob Ihr sie finden könnt.', },
    {'Findet Wellensprecherin Valoren in den Alptraumtiefen in Vashj\'ir.', },
  },
  [26058] = {
    'Die Verteidigung der Feste Krom\'gar',
    {'Wir haben keine Zeit mehr. Sie kommen! Übernehmt die Kontrolle über eine schwere Kanone und holt die Gnome vom Himmel! Die Bombe wird explodieren, wenn sie zu oft getroffen wird, und wir mit ihr!|n|nVerteidigt die Basis, $N! Ihr seid unsere einzige Hoffnung!|n|nMeldet Euch bei Oberanführer Krom\'gar, sollten wir das wider Erwarten überleben.', },
    {'Zerstört 15 gnomische Flugmaschinen oder Gnomenbomber und 25 Gnomenschwadronskommandanten.', },
  },
  [26059] = {
    'Augen und Ohren: Malaka\'jin',
    {'Ehrenwacht ist gefallen. Der Griff, in dem die Horde das Brachland hielt, wurde aufgesprengt, ebenso wie das Land. Nun erhalte ich Berichte, in denen es heißt, ein gemeinsamer Angriff der Allianz und der Grimmtotems würde Malaka\'jin bedrohen. Wenn Malaka\'jin fällt, fällt auch das halbe Steinkrallengebirge!|n|nIhr habt Euch als $Gfähiger Soldat:fähige Soldatin; der Horde erwiesen. Wollt Ihr meine Augen und Ohren in Malaka\'jin sein? Hexendoktor Jin\'Zil erwartet Euch.|n|nMalaka\'jin befindet sich weit im Süden.', },
    {'Meldet Euch bei Hexendoktor Jin\'Zil in Malaka\'jin im Steinkrallengebirge.', },
  },
  [26060] = {
    'Der Voodoo: Stürmerherz',
    {'Mit Voodoo könnte es unseren Truppen gelingen, den Angriff der Grimmtotems zurückzuschlagen. Allerdings brauche ich verschiedene Zutaten, um diese schwarze Magie zu wirken.|n|nDie erste Zutat auf meiner Liste ist das Herz eines Klippenstürmers. Die Bestien sind fast ausgerottet, aber in dieser Gegend gibt es noch ein paar. Findet eine und erbeutet ihr klopfendes Herz!', },
    {'Besorgt ein Klippenstürmerherz.', },
  },
  [26061] = {
    'Der Voodoo: Widderhörner',
    {'Um den Voodoo zu wirken, brauche ich besondere Reagenzien. Bringt mir Hörner der Steinkrallenwidder in dieser Gegend, $N! Ohne die Hörner sind wir erledigt!', },
    {'Besorgt 6 Hörner eines Steinkrallenwidders.', },
  },
  [26062] = {
    'Der Voodoo: Resonitkristall',
    {'Die letzte Zutat für das Voodooritual ist eine spezielle Kristallart namens Resonit. Man findet sie nur in den Steinschlaghöhlen westlich von hier. Passt auf die Kobolde auf! Sie beschützen das Resonit mit ihrem Leben!', },
    {'Besorgt 8 Resonitkristalle.', },
  },
  [26063] = {
    'Die Königin und ihr Hofstaat',
    {'<Scholli grunzt.>|n|nHrmph.|n|nDinge brechen auseinander. Scholli unglücklich. Jetzt Schollis Gefährtin umgebracht von Spinnen in Weberkuhle. Scholli will Rache!|n|nHelft Scholli? Tötet Königin Silith und ihre kleinen Spinnlinge? Für Scholli? Für Schollis Gefährtin!|n|nWeberpass ist im Nordwesten, den Weg hoch. Geht!', },
    {'Tötet Königin Silith und 10 beliebige Spinnen in der Weberkuhle.', },
  },
  [26064] = {
    'Kein Kampf auf leeren Magen',
    {'Die Truppen sind hungrig, $N. Seit unsere Nachschublinien abgeschnitten wurden, gehen uns die Vorräte aus. Ich kann den Soldaten ein Festmahl zubereiten, wenn Ihr mir einige Zutaten besorgt.|n|nBegebt Euch in die Wälder westlich von hier und sucht nach Nestern der Kalimdoradler. Stehlt die Eier aus den Nestern und bringt sie mir.', },
    {'Beschafft 8 Eier des Kalimdoradlers.', },
  },
  [26065] = {
    'Freiheit für Willi',
    {'Diese Tentakelschrecken haben das arme Tier eingefangen. Bitte, $N, könnt Ihr es nicht retten, indem Ihr diese Abscheulichkeiten tötet?|n|nWürdet Ihr Willi seine Freiheit zurückgeben?|n|nHier, nehmt mein Totem und stellt es in der Nähe der Tentakel auf. Die Kälte, die es verströmt, bringt diese Monster zum Schrumpfen, sodass Ihr sie einfach besiegen könnt.', },
    {'Tötet alle Tentakelschrecken, um Willi zu befreien.', },
  },
  [26066] = {
    nil,
    {'Anscheinend haben wir fast keine großen, dummen Orcs mehr, die wir dem Feind entgegenschicken können. Das ist ein Problem. Zum Glück habe ich möglicherweise eine Lösung.|n|nNehmt diese Peitsche und geht nach Westen zur Steinschlaghöhle. In der Höhle werdet ihr ein schmutziges Koboldnest finden. Bändigt die Bestien mit meiner Peitsche. Wenn sie erst einmal gebändigt sind, werden sie tun, was wir wollen.|n|nKehrt zurück, wenn ihr eine anständig große Koboldarmee zusammen habt.', },
    {'Bändigt 6 Steinschlagkobolde mit der Peitsche von Unterwerfer Devo.', },
  },
  [26067] = {
    'Jin\'Zils Segen',
    {'Ah, es ist vollbracht! Nun müssen wir ihn ausprobieren.|n|nReist zum größten Konfliktherd im Hochwipfeltal und setzt meinen Voodoostecken bei den Marodeuren von Krom\'gar ein, die gegen die Grimmtotems kämpfen. Dank meiner Voodoomagie sollten sie ihre Schlagkraft zurückerhalten und unsere Feinde vernichten!|n|nGeht jetzt, $N!', },
    {'Benutzt Jin\'Zil\'s Voodoostecken, um 12 Marodeure von Krom\'gar mit Voodoo zu erfüllen.', },
  },
  [26068] = {
    'Die Wut der Kobolde!',
    {'Jetzt kommandieren wir die Koboldarmeen des Steinkrallengebirges! Klingt fast schon beeindruckend. Fast.|n|n<Devo seufzt.>|n|nDas Basislager der Allianz, nördlich von hier, wird streng bewacht. Es ist fast uneinnehmbar. Nur nordöstlich von hier, an der Grabstätte, gibt es einen Eingang. Nehmt das Koboldkriegshorn und brecht zur Grabstätte auf. Betretet sie von Osten, $N! Von dort aus reist Ihr nach Westen, bis Ihr den Punkt erreicht, den ich auf Eurer Karte markiert habe. Benutzt das Horn und bringt die Wut der Kobolde über die Allianz!', },
    {'Benutzt das Koboldkriegshorn nahe des Banners der Horde an der Grabstätte, um die Koboldarmee loszulassen!', },
  },
  [26069] = {
    'Nura Pfadfinder',
    {'Das Südliche Brachland wird von der Allianz angegriffen. Die Tauren bitten um Hilfe. Wir können sie nicht abweisen. Alle gesunden Soldaten der Horde sollten ihnen helfen.|n|nWenn Ihr sie unterstützen wollt, dann nehmt den Weg zum Höhenpfad. Ihr findet ihn im Dorf. Sucht nach Nura Pfadfinder.', },
    {'Meldet Euch bei Nura Pfadfinder auf dem Höhenpfad im Südlichen Brachland.', },
  },
  [26070] = {
    'Läuterung der Entweihten',
    {'Unsere Freunde des Irdenen Rings hier haben uns gefragt, ob wir ihnen nicht zur Hand gehen könnten. Wie es scheint treiben im Brühgraben ein paar Gesichtslose ihr Unwesen und verderben alle Wildtiere dort.|n|nKönnt Ihr Euch für mich darum kümmern?', },
    {'Tötet eine beliebige Kombination aus 8 Schmetteraalen, Tiefenschiffshaltern oder Schluchtpirschern.', },
  },
  [26071] = {
    'Läuterung der Entweihten',
    {'Diese Leute vom Irdenen Ring wollen, dass wir das Töten für sie übernehmen. Im Brühgraben treiben einige Gesichtslose ihr Unwesen und verderben alle Wildtiere dort.|n|nSchwimmt mal runter und kümmert Euch darum.', },
    {'Tötet eine beliebige Kombination aus 8 Schmetteraalen, Tiefenschiffshaltern oder Schluchtpirschern.', },
  },
  [26072] = {
    'In das Totem',
    {'Ihr müsst mein Totem nach unten in den Brühgraben bringen. Benutzt es, um die Energien der Gesichtslosen einzufangen, wenn sie sterben. Das Totem wird sie davon abhalten, dahin zurückzukehren, wo sie herkamen.|n|nWenn das Totem ganz gefüllt ist, bringt es zu mir zurück. Wir werden es verwenden, um ihren Anführer aus der tiefsten Tiefe hervorzulocken.', },
    {'Tötet 5 gesichtslose Entweiher, während sie sich in der Reichweite des Totems der Einsperrung befinden.', },
  },
  [26073] = {
    'Im Süden nichts Neues',
    {'Kehrt jetzt zu Oberanführer Krom\'gar zurück, $N. Teilt ihm unsere Lage mit und berichtet, was Ihr getan habt, um Malaka\'jin vor dem Fall zu bewahren.|n|nWir danken Euch für alles, was Ihr getan habt. Vielleicht werdet Ihr eines Tages Eure eigene Region kommandieren.', },
    {'Meldet Euch bei Oberanführer Krom\'gar in der Feste Krom\'gar im Steinkrallengebirge.', },
  },
  [26074] = {
    'Der Anfang vom Ende',
    {'Champion, wir haben ein neues Ziel anvisiert. Unsere Späher im Kriegsnarbental melden, dass die Nachtelfen an ihrer eigenen Massenvernichtungswaffe arbeiten und sie in einem uralten Baum verbergen. Sie werden nie die Gelegenheit bekommen, sie gegen uns einzusetzen.|n|nIhr werdet die Bombe zum Auftanken zu den Schlickwerken begleiten und danach zum Klippenläuferposten. Von dort aus werden wir die Bombe zünden und all unsere Feinde vernichten.|n|nGeht jetzt, $N. Meldet Euch bei Jibbly Rakit, wenn ihr an den Schlickwerken eintrefft.', },
    {'Fahrt im Heißluftballon von Krom\'gar zu den Schlickwerken im Steinkrallengebirge.', },
  },
  [26075] = {
    'Ein Haufen Probleme',
    {'Wir haben ein kleines Problem...|n|n<Jibbly zeigt auf die großen Kothaufen, die überall in der Basis liegen.>|n|nWir haben die Schlickwerke in der Nähe eines Wyvernhabitats errichtet. Die Risszeichnungen der Schlickwerke wurden mit großer Sorgfalt erstellt, damit die Wyvernhabitate nicht gestört werden. Anscheinend verehren die Tauren und Orcs die Bestien. Wisst Ihr, was ich verehren würde? Einen Tag ohne Koteinschläge!|n|nGanz im Vertrauen, die Wyvern müssen sterben!', },
    {'Tötet 6 beliebige Prachtschwingenwyvern.', },
  },
  [26076] = {
    'Spionageplage',
    {'Wir haben noch ein Problem, $N. Es wimmelt hier von Allianzspionen! Ihr habt keine gesehen? Weil sie unsichtbar sind! Getarnt! Ich habe eine Lösung, aber dafür brauche ich jemanden, der die Kraft und das Geschick hat, meinen Plan umzusetzen.|n|nBenutzt diese Gasbombe, dann werdet Ihr die getarnten Spione sehen können. Schickt sie zu ihrem Schöpfer, wenn Ihr sie enttarnt habt.|n|nIhr erkennt einen getarnten Spion an dem Effekt, den sie auf die Luft haben. Seht genau hin!', },
    {'Tötet 8 Allianzspione. Enttarnt die Spione mit Jibblys Gasbombe!', },
  },
  [26077] = {
    'Letzte Lieferung',
    {'Oberanführer Krom\'gar hat einen Befehl aus der Basis übermittelt. Fahrt mit dem Heißluftballon von Krom\'gar zum Klippenläuferposten. Der Plan sieht vor, von dort aus mit der Bombe die Allianz im Kriegsnarbental zu vernichten.|n|nMacht Euch auf, $N. Man sollte Krom\'gar nicht warten lassen.|n|nSprecht mit General Grebo, wenn Ihr Euer Ziel erreicht habt. Er wird Euch über Eure nächste Mission informieren.', },
    {'Fahrt mit dem Heißluftballon von Krom\'gar zum Klippenläuferposten im Steinkrallengebirge.', },
  },
  [26078] = {
    'Löscht die Feuer',
    {'Der Angriff der Dunkeleisenzwerge hat uns überrascht. Ihre Saboteure haben viele unserer Flugzeuge, Dampfpanzer und Vorräte beschädigt. Wir konnten nur noch ein paar Bomber rechtzeitig starten.|n|nJeder Techniker, jeder Rekrut und jede Wache, die ich entbehren kann, versucht verzweifelt, die anderen zu reparieren und startklar zu machen. Unsere Infanterie kann nicht mehr lange ausharren. Nehmt diese Ausrüstung und helft bei der Löschung der brennenden Bomber.', },
    {'Löscht 6 Feuer auf dem Flugplatz von Eisenschmiede mit Eurer Feuerwehrausrüstung.', },
  },
  [26079] = {
    'GESUCHT: Falkenstein und Otto',
    {'Die Miliz von Stromgarde hat Kopfgelder auf Lord Falkenstein und seine Leibwache Otto ausgesetzt. Falkenstein ist für die Bemühungen des Syndikats im Arathihochland verantwortlich und sein Tod wäre eine erhebliche Störung dieser Bemühungen.|n|nSeine Leibwache Otto ist zwar kein strategisch wichtiges Ziel, aber er ist ein starker Gegner und hat Dutzende unserer Verteidiger auf dem Gewissen.|n|nIhre Kopfgelder können bei Hauptmann Nials abgeholt werden.', },
    {'Bringt Ottos und Falkensteins Köpfe zu Hauptmann Nials bei der Zuflucht.', },
  },
  [26080] = {
    'Ein letzter Gefallen',
    {'$N, Ihr müsst das hier zu Käpt\'n Glovaal bringen. In meinem Zustand bräuchte ich sicher eine Woche, um zur Dämmerbucht zu gelangen. Aber wir haben keine Zeit zu verlieren!', },
    {'Bringt Grabungslieds Fisch und Tipps zu Kapitän Glovaal in der Dämmerbucht.', },
  },
  [26081] = {
    'Alinas Belohnung',
    {'Hier endet also die Geschichte von Trol\'kalar. Diese Waffe wird im Namen der Dunklen Fürstin den Lebenden den Tod bringen.|n|nVerlasst mich jetzt, $N. Es obliegt mir erneut, die Klinge zu bewachen. Berichtet Alina von Eurem Sieg. Sie wird Euch sicherlich belohnen', },
    {'Sprecht mit der dunklen Waldläuferin Alina.', },
  },
  [26082] = {
    'Auf nach Kriegsnarbe!',
    {'Ich werde dem alten Narr erlauben, seinen Fall vorzutragen. Er behauptet, er könne Beweise dafür bringen, dass die Nachtelfen keine Massenvernichtungswaffe besitzen. Wir werden sehen.|n|nWährend wir auf diesen Beweis warten, werdet Ihr unsere Armee im Tal unterstützen. Zu diesem Zweck haben wir eine große Anzahl Belagerungspanzer vorbereitet. Unsere Verwüster sind angriffsbereit.|n|nNehmt den Fahrstuhl hinunter zum Boden des Außenpostens und übernehmt einen Verwüster von Krom\'gar. Vernichtet damit unsere Feinde im Kriegsnarbental.', },
    {'Benutzt den Verwüster von Krom\'gar, um 5 darnassische Glevenschleudern und 20 beliebige Soldaten der Allianz im Kriegsnarbental zu vernichten.', },
  },
  [26083] = {
    'Hallo Lolo',
    {'Gichtdarm war geschickt spähen. Guckt viele Dinge. Groß Abenteuer!|n|nGichtdarm findet geheim Piratschiff. Piraten viel Angst, laufen weg. Aber Oger Lolo nicht laufen. Lolo macht gut Freund mit Gichtdarm!|n|nGichtdarm muss weg, aber vermissen Lolo. Ihr sagen hallo zu Lolo von Gichtdarm.', },
    {'Findet Lolo den Ausguck in der Faldirbucht.', },
  },
  [26084] = {
    nil,
    {'Ihr habt uns hier gut gedient, $N. Wir haben ein Zeichen gesetzt, aber die nächste Phase unseres Eroberungsfeldzugs wird Monate brauchen, nicht nur Minuten.|n|nEs gibt noch viel zu tun. Ich werde Euch den langweiligen Teil - das Warten auf das Eintreffen der Wehrbefestigungen - ersparen. Reist gen Osten nach Hammerfall. Die Orcs dort werden Eure Hilfe gebrauchen können.', },
    {'Meldet Euch bei Gor\'mul in Hammerfall im Arathihochland.', },
  },
  [26085] = {
    'Sammelt die Verteidiger',
    {'Während unsere Ingenieure dafür sorgen, dass die Bomber bald wieder fliegen, kämpfen unsere Wachen und Gebirgsjäger gegen die Eindringlinge.|n|nSeit Beginn des Einmarschs sind sie dort draußen, ohne Zeit für Schlaf oder Essen. Die Verteidiger von Eisenschmiede gehören zu den besten Azeroths, aber selbst sie haben Grenzen.|n|nNehmt diese Banner und platziert sie in Verwehungen aus losem Schnee. Erinnert die Soldaten an das, wofür sie kämpfen und stärkt ihre Moral.', },
    {'Platziert 8 Banner von Eisenschmiede in Hügel aus losem Schnee überall auf dem Flugplatz von Eisenschmiede.', },
  },
  [26086] = {
    nil,
    {'<Kapitän Verne sieht auf seine Uhr.>|n|nWo ist dieser Jäger? Ich habe Orako vor einer Woche in die Tiefenlichtkluft geschickt, um einen Bericht zu schreiben! Ja, er ist schon ganz schön anstrengend und ich hätte nichts dagegen, ihn vom Hals zu haben, aber ich brauche seinen Bericht.|n|nIhr da! Wie heißt Ihr? $N? Würdet Ihr ihn für mich ausfindig machen? Es scheint zwar merkwürdig, dass <ein/eine:c> $C einen Jäger suchen soll, aber mir bleibt keine andere Wahl.', },
    {'Meldet Euch bei Orako bei der Tiefenlichtkluft in Vashj\'ir.', },
  },
  [26087] = {
    'Leuchtsaft',
    nil,
    nil,
  },
  [26088] = {
    'Hierher, Fischlein Fischlein!',
    {'<Orako formt einen Ball aus dem Leuchtsaft und bringt ihn dann an einem Gerät an, an dem er offensichtlich schon lange bastelt.>|n|nHier, ich habe einen Hut für Euch. Er hat ein Licht, das Fische anlockt. Genau wie bei den Murlocs!|n|nDie Murlocs jagen gerne im Tang und in den Korallen an den Seiten der Kluft. Wenn Ihr diesen Hut aufsetzt und durch den Tang schwimmt, könnt Ihr vielleicht genauso Fische fangen, wie sie.', },
    {'Setzt den Fischerhut auf und schwimmt durch die Korallen in der Tiefenlichtkluft, um 30 Tiefenlichtknabberfische anzulocken.', },
  },
  [26089] = {
    'Stirb, Fischmann, stirb',
    {'Ein Fisch hat meinen Wolf gefressen, und Murlocs sehen aus wie Fische. Diese Murlocs werden bezahlen!|n|nGeht zurück in die Kluft und tötet diese Fischmänner! Mein Wolf wird seine Rache bekommen!', },
    {'Tötet 4 Tiefenlichtjäger und 4 Tiefenlichtorakel.', },
  },
  [26090] = {
    'Hier, ein Ei!',
    {'<Dies scheint ein Ei eines dieser verschlagenen Großaale zu sein, die über der Kluft umherschwimmen. Ihr fragt Euch, ob Orako vielleicht daran interessiert sein könnte.>', },
    {'Bringt das enorme Aalei zu Orako bei der Tiefenlichtkluft in Vashj\'ir.', },
  },
  [26091] = {
    'Hierher, Fischlein Fischlein, Teil 2: Der Eier-Aal-Trick-Blues',
    {'<Orako nimmt eine Sprengfalle aus seiner Tasche und schiebt sie durch die äußere Hülle des Eis.>|n|nJetzt wird das Ei explodieren. Legt es in der Nähe eines dieser gigantischen Aale ab und wartet, bis er näher kommt. Wenn das Ei explodiert, ist der große Fisch schon halbtot und Ihr könnt ihn leicht erledigen.|n|nRettet meinen Wolf! Mit diesem Ei wird es Euch gelingen.', },
    {'Benutzt das aal-splosive Gerät in der Nähe eines verschlagenen Großaals in der Tiefenlichtkluft und besiegt dann den geschwächten Großaal.', },
  },
  [26092] = {
    'Orakos Bericht',
    {'<Ihr erinnert Orako daran, dass er einen Bericht an Kapitän Verne senden sollte.>|n|nStimmt, ein Bericht. Alles, was ich hier gesehen habe, sind Fische. Fische, Fische und nochmals Fische.|n|n<Orako wirft einen Blick auf den Sack Fische, den Ihr ihm mitgebracht habt.>|n|nBringt das zurück zum Kapitän. Das ist mein Bericht.', },
    {'Bringt Orakos Bericht zu Kapitän "Juwel" Verne in der Schattenhöhle.', },
  },
  [26093] = {
    'Nordhof',
    {'Wir kämpfen in einem Krieg um Stromgarde und wir verlieren. Die Oger, das Syndikat und wir selbst haben unsere einst mächtige Stadt zerrissen und jede Fraktion kämpft mit der anderen bis zu einem blutigen Patt.|n|nAber unsere Truppen werden dezimiert, während die Zahl der Feinde ansteigt.|n|nAuch wenn Süderstade gefallen ist, dürfen wir unseren Feinden keinen Fußbreit unseres Bodens mehr überlassen.|n|nGeht zum Hauptquartier des Syndikats im Nordhof und tötet ihre Mitglieder. Wir müssen das Land für uns zurückerobern, bevor die Horde die Gelegenheit hat, sich weiter auszubreiten.', },
    {'Tötet 10 Mitglieder des Syndikats beim Nordhof.', },
  },
  [26094] = {
    'Zurückschlagen',
    {'Mein Chefingenieur sagt, dass er einen der Bomber repariert hat. Er ist startbereit. Nehmt diese Bomben und sucht den reparierten Bomber am Anfang der Rollbahn.|n|nSetzt die Bomben ein, sobald Ihr in der Luft seid, und richtet unter den angreifenden Dunkeleisenzwergen so viel Schaden wie möglich an. Ich habe Gerüchte gehört, laut derer sie eine neue Art von Kriegsgolem einsetzen wollen. Sucht nach diesen Golems. Sie sind Eure wichtigsten Ziele.', },
    {'Steigt in den reparierten Bomber und tötet 30 Angreifer der Dunkeleisenzwerge mit der Eisenhammerbombe. Ihr könnt beliebige Dunkeleisenzwerge oder ihre Verbündeten auf dem Flugplatz töten.', },
  },
  [26095] = {
    'Abzeichen von Stromgarde',
    {'Das Syndikat in Stromgarde bekämpft das Kontingent unserer Miliz dort. Um diesen Pöbel dazu zu bringen, sich mit unseren disziplinierteren Streitkräften zu schlagen, haben die Syndikatsanführer ein Kopfgeld auf unsere Soldaten ausgesetzt und belohnen jedes Abzeichen von Stromgarde, das toten Milizleuten abgenommen wurde, mit Gold.|n|nWir wollen diese Abzeichen zurück - wir dürfen es diesen Halsabschneidern nicht erlauben, Trophäen von unseren mutigen Gefallenen zu rauben!|n|nBegebt Euch in das vom Syndikat kontrollierte Gebiet von Stromgarde und jagt ihnen unsere Abzeichen ab.', },
    {'Erbeutet 7 Abzeichen von Stromgarde vom feindlichen Syndikat in Burg Stromgarde.', },
  },
  [26096] = {
    'Verbrühende Pilze',
    {'Wir glauben, dass wir eine gute Verwendung für die Gnadenlosen gefunden haben, die Euer Freund aus der Höhle uns gebracht hat. Ich benötige jedoch ein Konservierungsmittel dafür.|n|nUnten im Brühgraben findet Ihr Pilze, die genau die Eigenschaften haben, die ich brauche. Bringt mir ein paar davon und ich schaue, was ich tun kann.', },
    {'Sammelt 5 Verbrühende Pilze.', },
  },
  [26097] = {
    'Beweis für eine Lüge',
    {'Im Herzen des Kriegsnarbentals steht ein uralter Baum - ein Baum, der den Zeitaltern widerstanden hat und seit Generationen als ein Ort des Friedens und der Lehre genutzt wird. Solange ich denken kann, hat meine Familie in diesem Hain zusammen mit den Nachtelfen das Druidentum studiert. Und jetzt soll ich glauben, dass sich in diesem Baum eine Massenvernichtungswaffe der Allianz befindet?|n|nKrom\'gar irrt sich. Das werde ich beweisen!|n|nIch habe meinen Sohn Orthus in den Hain von Thal\'darah geschickt. Er soll nach der Waffe suchen. Geht dorthin und trefft ihn.', },
    {'Findet Orthus im Hain von Thal\'darah im Steinkrallengebirge.', },
  },
  [26098] = {
    'Verrat im Hain',
    {'Der Raum ist voller toter Druiden. Etwas stimmt nicht, denn Ihr seht keine Anzeichen eines Kampfes. Von der Tür führen blutige Schleifspuren ins Innere.|n|nIhr öffnet Orthus\' erstarrte Faust und findet etwas verstörendes: ein Insigne des Generals von Krom\'gar.|n|nBringt das Insigne des Generals von Krom\'gar zurück zu Oberhäuptling Klippenläufer.', },
    {'Bringt das Insigne des Generals von Krom\'gar zurück zu Oberhäuptling Klippenläufer am Klippenläuferposten im Steinkrallengebirge.', },
  },
  [26099] = {
    'Das soll Gerechtigkeit sein?',
    {'Er war ein guter Junge, $N. Jung, liebevoll. Niemals hätte er einen der jungen Druiden getötet. Sie waren seine Freunde! Nein... Nicht Orthus.|n|nDer General muss sich für dieses Verbrechen verantworten. Ich verlange Gerechtigkeit!', },
    {'Verteidigt Euch.', },
  },
  [26100] = {
    'Der General ist tot',
    {'Würdet Ihr mit Oberanführer Krom\'gar reden, $N? Vielleicht hört er ja auf Euch. Ihr seid schließlich ein Champion in seiner Armee. Ihr habt alles gesehen. Bitte helft uns, $N. Wir wollen doch nur in Frieden gelassen werden.|n|nSprecht mit Oberanführer Krom\'gar und versucht ihm zu vermitteln, dass wir nicht wollten, was geschehen ist.', },
    {'Sprecht mit Oberanführer Krom\'gar in der Feste Krom\'gar im Steinkrallengebirge.', },
  },
  [26101] = {
    'Über dem Gesetz',
    {'Es war richtig, dass Ihr mir dieses Verbrechen gemeldet habt. Die Täter werden für dieses feige Verbrechen bezahlen. Blut wird fließen.|n|nOhne Grebo fehlt mir ein General. Ihr werdet seinen Platz einnehmen.|n|nTrefft mich am Klippenläuferposten, General. Zusammen werden wir diesen Schwachsinn beenden.', },
    {'Trefft Oberanführer Krom\'gar am Klippenläuferposten im Steinkrallengebirge.', },
  },
  [26102] = {
    'Grimmaxts Ende',
    {'Dank eures Einsatzes ist der Angriff der Dunkeleisenzwerge ins Stocken geraten. General Grimmaxt, der Anführer der Dunkeleisenzwerge, versucht, seine Truppen aus ihren Reihen auf dem gefrorenen See im Süden anzutreiben.|n|nEr steht auf einem ihrer neuen Dunkeleisengolems und ruft seinen Soldaten Befehle zu. Wenn es ihm gelingt, sie zu motivieren, überrennen sie uns vielleicht doch noch. Das müsst Ihr verhindern, $N. Zerstört den Golem, der General Grimmaxt beschützt, dann ihn selbst. Er ist der Schlüssel zu unserem Sieg.', },
    {'Tötet General Grimmaxt auf dem Flugplatz von Eisenschmiede.', },
  },
  [26103] = {
    nil,
    {'Unterseeboottreibstoff ist teuer!|n|nDie Machthaber in Gnomeregan waren so freundlich, uns mehrere Treibstofffässer zur Verfügung zu stellen, aber wir verbrauchen sie schneller als erwartet. Das bedeutet, dass wir improvisieren müssen.|n|nEs ist kein Geheimnis, dass die Meereslebewesen allerlei interessante Chemikalien enthalten... wie zum Beispiel Öl. Bringt dieses Gerät zu Korthuns Ende und benutzt es an Kadavern von Schildkröten, Schiffshaltern und Hammerhaien. Wenn wir nicht mehr Unterseeboottreibstoff beschaffen können, ist ihr Öl vielleicht unsere einzige Hoffnung.', },
    {'Benutzt die Ölextraktionspumpe an den Kadavern von Meeresdickichtschildkröten, Kolkschiffshaltern und Dornenschuppenhammerhaien in Korthuns Ende, um 4 Einheiten Schildkrötenöl, 4 Einheiten Schiffshalteröl und 4 Einheiten Hammerhaiöl zu sammeln.', },
  },
  [26104] = {
    'Holt das Lasso raus',
    {'Seid gegrüßt, $GGenosse:Genossin;.|n|nEndlich ist eingetroffen Verstärkung und bringt Nahrung, Männer und neue Reittiere. Einzige Problem ist, dass unsere Reittiere unter Wasser nicht so gut vorankommen.|n|nDirekt über dieser Chöle findet Ihr chohe Säulen mit roten, blättrigen Tang obenauf. In dem Tang verstecken sich Seepferdchen. Werft dieses Lasso in den Tang und cholt uns ein paar Reittiere, die wir benutzen können chier unter Wasser.', },
    {'Benutzt das Seepferdchenlasso in der Nähe des Tangs auf den Säulen in Korthuns Ende, um 5 panische Seepferdchen zu fangen.', },
  },
  [26105] = {
    'Erobert Korthuns Ende',
    {'Die Horde hat Spione in dieser Gegend? Die Dämmerbucht ist ganz in der Nähe und die Zange X2 befindet sich dort! Die Horde darf auf keinen Fall in ihre Nähe gelangen!|n|nIhr müsst jemanden in der Dämmerbucht darüber informieren… nachdem Ihr mehr von diesen dreckigen Spionen der Horde den Garaus gemacht habt!', },
    {'Tötet 7 von Höllschreis Seebären in Korthuns Ende.', },
  },
  [26106] = {
    'Treibstoffologie leicht gemacht',
    {'Wie viel wisst Ihr über Treibstoff, $N? Den perfekten Treibstoff herzustellen ist eine anspruchsvolle Aufgabe. Es gibt einfach viel zu viele Faktoren, die exakt ausgeglichen sein müssen: Chrono-Pyroxidationsparameter, Tempero-Inflammationsvariablen, ignifaktorische Rußifizierungskriterien... Und das sind nur die wichtigsten!|n|nHoffentlich kann ich die Proben, die Ihr mir gebracht habt, in das richtige Verhältnis bringen, um... den perfekten Biotreibstoff herzustellen. Benutzt den Tisch dort drüben und versucht, ein paar Proben miteinander zu kombinieren. Bringt mir die Ergebnisse, wenn Ihr fertig seid.', },
    {'Benutzt die Treibstofftestanlage in der Dämmerbucht, um den perfekten Biotreibstoff herzustellen.', },
  },
  [26107] = {
    'Mut machen',
    {'Dank der Schamanenkünste unseres Volkes konnte ich Jahre der Lethargie hinter mir lassen. Jetzt sorge ich für alle hier und stelle den Segen her, der auch mir neue Kraft schenkte.|n|nDie Hochlandraptoren sind tückische und wilde Bestien. Ihre Geister können unseren Kriegern große Stärke geben. Bringt mir Raptoraugen, damit ich die Amulette herstellen kann, so wie es mich Tor\'gan lehrte.', },
    {'Erbeutet 10 Hochlandraptoraugen von Hochlandschreitern oder Hochlandhauern.', },
  },
  [26108] = {
    'Arglist des Raptors',
    {'Die Hochlandfleischpirscher im Süden sind noch wilder als ihre Artgenossen. Sie besitzen nicht nur Stärke, sondern auch große List.|n|nAls ich in der Lethargie gefangen war, konnten mich selbst Amulette der Stärke nicht bewegen. Doch Tor\'gan benutzte die Herzen der Fleischpirscher, um mich mit einem Geist zu erfüllen, der meine Zweifel besiegte und mich befreite.|n|nUnsere Soldaten verdienen die List des Raptors. Sammelt Fleischpirscherherzen für mich, $N.', },
    {'Sammelt 12 Raptorherzen von Hochlandfleischpirschern.', },
  },
  [26109] = {
    'Land in Sicht!',
    {'Lolo sieht was Winziges, es ist $Gein:eine:r; $R! Immerzu Ausschau halten, ja, ja, das tut Lolo!|n|nWillkommen in der Faldirbucht. Kapitän O\'Breen hat gesagt, dass wir nur für ein paar Stunden hier wären. Grad lang genug, um den Schatz einzusammeln und zurück nach Beutebucht zu segeln.|n|nAber Lolo denkt, dass wir noch sehr lange hier bleiben werden. Wir haben die anderen beiden Schiffe von unserer Formation verloren. Die arme Silbergeist und die arme Tolle Minna. Sie ruhen jetzt auf dem Grund des Meeres!|n|nLolo schlägt vor, dass Ihr mit Kapitän O\'Breen sprecht, wenn Ihr länger hier bleiben wollt.', },
    {'Sprecht mit Kapitän O\'Breen in der Faldirbucht im Arathihochland.', },
  },
  [26110] = {
    'Wie in alten Zeiten',
    nil,
    {'Nehmt der Kurierin der Verlassenen den versiegelten Ordner ab.', },
  },
  [26111] = {
    '… und er wird kommen',
    {'Ich erfülle Euch nun mit den Energien des verderbenden Gesichtslosen.|n|nSchwimmt hinunter zu meinem Ködertotem im Graben im Nordosten. Nutzt das Totem, um die Energien zu entfesseln. Bringt mir das Gehirn ihres Anführers.|n|nRuft Ick\'thys den Unergründlichen… und er wird kommen!', },
    {'Besorgt Euch das Gehirn des Unergründlichen.', },
  },
  [26112] = {
    'Überfällige Antworten',
    {'Wie genau ist es den Kriegern der Dunkeleisenzwerge gelungen, bis hierher vor die Tore Eisenschmiedes zu kommen und beinahe unsere Stadt zu erobern?|n|nHerrscht nicht \'Kaiserin\' Moira, Mitglied unseres hochgeschätzten Rates der Drei Hämmer, über die Dunkeleisenzwerge? Ohne ihr Wissen und ihre Zustimmung konnte das nicht geschehen. Das war keine zusammengewürfelte Gruppe rebellischer Zwerge, sondern eine gut ausgerüstete Invasionsstreitmacht.|n|nIch habe einen Bericht über die Schlacht um den Flugplatz zusammengestellt. Bringt ihn zum Hohen Sitz nach Eisenschmiede und konfrontiert sie damit!', },
    {'Bringt Steinbrechers Bericht zu Moira Thaurissan im Hohen Sitz von Eisenschmiede.', },
  },
  [26113] = {
    'Quae und Kinelory',
    nil,
    {'Findet Quae auf dem Hügel über Go\'sheks Hof.', },
  },
  [26114] = {
    'Quae vertraut Euch',
    {'<Quae sieht die Unterlagen durch.>|n|nAusdehnung...Gebietskontrolle... diese Untoten planen nichts neues, aber sie wollen ganz Arathi einnehmen. Wir müssen ihre Pläne stören.|n|nIch halte hier oben Wache. Ihr geht mit Kin und besorgt die Invasionspläne. Diese wandelnden Kadaver werden nicht einmal erfahren, welchen Tag wir haben.|n|nUnd passt auf sie auf, verstanden?', },
    {'Sprecht mit Kinelory in der Nähe von Go\'Sheks Hof im Arathihochland.', },
  },
  [26115] = {
    'Sehen ist verstehen',
    {'Bleibt bei mir, $N und seht zu, wie unsere mächtige Waffe den Feind vernichtet!|n|nVersteht, was es bedeutet, zur Horde zu gehören!', },
    {'Versteht, was es bedeutet, zur Horde zu gehören.', },
  },
  [26116] = {
    'Kinelory schlägt zu',
    {'Nun gut, $N. Bereit, wenn Ihr es seid.|n|nSollen wir?', },
    {'Beschützt Kinelory, bis sie zu Quae zurückkehrt.', },
  },
  [26117] = {
    'Für Süderstade',
    {'Es gab Abende in der Taverne, nach denen Kinelory schlimmer aussah als jetzt. Ihr habt sie anscheinend gut beschützt.|n|nDie Zuflucht sollte von unserem Erfolg erfahren. Ich bleibe mit Kin hier, damit sie sich ausruhen kann. Geht ohne uns los.', },
    {'Kehrt zu Kommandantin Amaren in der Zuflucht zurück.', },
  },
  [26118] = {
    'Fasst den Botschafter',
    {'Der Verrat des Botschafters wird mich noch lange verfolgen. Ihr müsst ihn verhaften, bevor er noch weiteren Schaden anrichtet oder schlimmer noch, bevor er entkommt und mit der Planung des nächsten Angriffs beginnt. Eisenschmiede wird erst sicher sein, wenn Botschafter Schlackenhammer sich nicht mehr frei in der Stadt bewegt.|n|nNehmt diese Fesseln und geht zur Botschaft der Dunkeleisenzwerge. Sie befindet sich nördlich des Hohen Sitzes, am Rand der Großen Schmiede. Verhaftet Botschafter Schlackenhammer und kehrt mit ihm zurück.', },
    {'Geht zur Botschaft der Dunkeleisenzwerge und verhaftet Botschafter Schlackenhammer mit Hilfe der stabilen Handfesseln.', },
  },
  [26120] = {
    'Der wahnsinnige Orc des Drachenmals',
    {'Die Orcs des Drachenmals werden immer mehr zur Plage. Ihre waghalsigen Angriffe auf den Hain sind zwar lästig, verhelfen meinen Wachen aber wenigstens zu einigen nützlichen Übungseinheiten.|n|nMeine Späher haben jedoch beobachtet, dass sie schwarze Großdrachenwelpen mit Netzen einfangen. Das Letzte, was dieses Land gebrauchen kann, ist ein primitives Wiederaufleben der Drachenzähmung. Macht Euch auf den Weg nach Osten, $C, und tötet die Welpendiebe. Sorgt dafür, dass ihre Dummheit uns nicht teuer zu stehen kommt.', },
    {'Tötet 12 Welpendiebe des Drachenmals.', },
  },
  [26121] = {
    'Erobert Korthuns Ende',
    {'Ihr seht Spione da oben? Das ist nix gut… gar nix gut, $GGenosse:Genossin;.|n|nKehrt zurück zu Korthuns Ende und vernichtet sie, mein Freund.', },
    {'Tötet 7 von Höllschreis Seebären in Korthuns Ende.', },
  },
  [26122] = {
    'Umweltbewusstsein',
    {'Habt Ihr je Unterseeboottreibstoff gerochen, $N? Widerliches Zeug. Leider müssen wir große Mengen davon verbrennen, um die Verne anzutreiben. Und es riecht nicht nur abstoßend, sondern ist auch tödlich für die Tiere hier. Wir müssen bewusster mit unserer Umwelt umgehen.|n|nDie Meereswesen hier in der Gegend haben besonders öliges Fleisch. Bringt dieses Gerät zum Meeresdickicht direkt über dieser Höhle und benutzt es an den Kadavern von Schildkröten, Schiffshaltern und Hammerhaien. Ihr Öl kann vielleicht das Leben Hunderter anderer Meereslebewesen retten.', },
    {'Benutzt die Ölextraktionspumpe an den Kadavern von Meeresdickichtschildkröten, Kolkschiffshaltern und Dornenschuppenhammerhaien in Korthuns Ende, um 4 Einheiten Schildkrötenöl, 4 Einheiten Schiffshalteröl und 4 Einheiten Hammerhaiöl zu sammeln.', },
  },
  [26123] = {
    'Unterwasserwölfe',
    {'Willkommen, Freund!|n|nUnsere Verstärkung ist eingetroffen und bringt uns Nahrung, Orcs und neue Reittiere. Moment mal… Reittiere?!|n|nWie sollen wir uns denn unter Wasser auf einem WOLF fortbewegen?!|n|n<Kapitän Verne seufzt.>|n|nDirekt über dieser Höhle, im Meeresdickicht, findet Ihr hohe Säulen mit rotem, blättrigem Tang obenauf. In diesem Tang verstecken sich Seepferdchen besonders gerne. Werft dieses Lasso in den Tang und fangt uns ein paar NÜTZLICHE Reittiere.', },
    {'Benutzt das Seepferdchenlasso in der Nähe des Tangs auf den Säulen im Meeresdickicht, um 5 panische Seepferdchen zu fangen.', },
  },
  [26124] = {
    'Sichert das Meeresdickicht',
    {'Die Allianz hat Spione in dieser Gegend? Die Schattenhöhle ist ganz in der Nähe und das neue Unterseeboot der Horde, die Verne, befindet sich dort! Die Allianz darf auf keinen Fall in ihre Nähe gelangen!|n|nIhr müsst jemanden in der Höhle darüber informieren… nachdem Ihr mehr von diesen hinterhältigen Spionen der Allianz den Garaus gemacht habt!', },
    {'Tötet 7 Meeresspäher der Allianz im Meeresdickicht.', },
  },
  [26125] = {
    'Sichert das Meeresdickicht',
    {'Ihr habt da oben Spione gesehen? Das ist nicht gut… Das lasse ich nicht zu!|n|nKehrt zum Meeresdickicht zurück und werdet sie los, bevor sie sich in unser Versteck einschleichen können.', },
    {'Tötet 7 Meeresspäher der Allianz im Meeresdickicht.', },
  },
  [26126] = {
    'Der perfekte Treibstoff',
    {'Wie viel wisst Ihr über Treibstoff, $N? Den perfekten Treibstoff herzustellen ist eine anspruchsvolle Aufgabe. Es gibt einfach viel zu viele Faktoren, die exakt ausgeglichen sein müssen: Chrono-Pyroxidationsparameter, Tempero-Inflammationsvariablen, ignifaktorische Rußifizierungskriterien... Und das sind nur die wichtigsten!|n|nHoffentlich kann ich die Proben, die Ihr mir gebracht habt, in das richtige Verhältnis bringen, um... den perfekten Biotreibstoff herzustellen. Benutzt den Tisch dort drüben und versucht, ein paar Proben miteinander zu kombinieren. Bringt mir die Ergebnisse, wenn Ihr fertig seid.', },
    {'Benutzt die Treibstofftestanlage in der Schattenhöhle, um den perfekten Biotreibstoff herzustellen.', },
  },
  [26127] = {
    'Die Enthüllung des Schattenhammers',
    {'Ich dachte ebenso wie alle anderen, dass es sich bei diesen Narren nur um nichtsnutzige Dunkeleisenzwerge handelte, aber diese Wahnsinnigen sind überzeugte Kultisten!|n|nDer Schattenhammer will nichts anderes als die Zerstörung der ganzen Welt. Sie haben sich Todesschwinge und Ragnaros angeschlossen und sind eng mit den Dunkeleisenzwergen verbunden.|n|nAber es ist egal, wer sie sind, wichtig ist nur, dass sie sich in Dun Modr aufhalten und entfernt werden müssen! Ich werde keinen von ihnen durchlassen. Geht zu ihnen und zertrümmert ein paar Schädel!', },
    {'Tötet 12 Mitglieder des Schattenhammers in Dun Modr.', },
  },
  [26128] = {
    'Die Schlacht um den Thandolübergang',
    {'Ich habe den Thandolübergang schon einmal vor der Zerstörung bewahrt. Damals kämpfte ich gegen die Dunkeleisenzwerge. Das gleiche tat mein Vater und dessen Vater vor ihm...|n|nDie einzigen Dunkeleisenzwerge, die mir entkamen, liefen direkt auf die Brücke zu. Etwas stimmt nicht. Ich befürchte, dass wir bei unserer Ankunft in eine üble Falle stürmen werden.|n|nIch könnte Eure Hilfe brauchen, $N. Für Eisenschmiede. Seid Ihr dabei?', },
    {'Besiegt Calamoth Aschbart am Thandolübergang.', },
  },
  [26129] = {
    'Waffenbrüder',
    {'Hört zu, $N. Zum ersten Mal seit dem Bürgerkrieg bin ich mit Graumähne einer Meinung. Es ist an der Zeit, unsere Fehde endlich beizulegen.|n|nDiesen Bestien scheint es egal zu sein, ob man Rebell oder Königstreuer ist.|n|nÜberbringt Graumähne meine Antwort. Meine Männer werden sich seinen Leuten anschließen.|n|nNicht weit von hier gibt es ein sicheres Versteck, in Josiahs Keller. Meine Jungs haben dort ein wenig schwere Artillerie gelagert.|n|nSagt dem König, dass er sich jederzeit in unserer Waffenkammer bedienen kann.', },
    {'Sprecht mit König Genn Graumähne im Militärviertel in Gilneas.', },
  },
  [26130] = {
    'Keine Verbindung zu L\'ghorek',
    {'L\'ghorek ist der Ahn, der auf der Klippe gegenüber von uns ruht. Er wird kontrolliert. Etwas Riesiges unter uns verschlingt seine Lebensenergien.|n|nUnter L\'ghorek gibt es eine Höhle, die als Muscheltiefe bekannt ist. In dieser Höhle befinden sich drei mächtige Ogermagier, die ein Ritual abhalten, das das Ding aus der Tiefe mit dem Ahnen verbindet. Ihr müsst die drei töten, um die Verbindung zu L\'ghorek zu unterbrechen.', },
    {'Tötet Ur\'Goz, Sku\'Bu und Neph\'Lahim.', },
  },
  [26131] = {
    'Verstärkung für Loch Modan',
    {'Seit Stunden warte ich darauf, dass sich der Rat meine Bitte anhört, aber es sieht nicht gut aus. Moira scheint darauf versessen zu sein, den Rat lahmzulegen.|n|nWährenddessen leidet Loch Modan. Wir haben viele Feinde, aber nur wenige Ressourcen. Würdet Ihr mich vielleicht anhören, $N, wenn der Rat nicht dazu gewillt ist? Sprecht mit Gryth Thurden, dem Greifenmeister von Eisenschmiede. Er hält sich im östlichen Teil der Großen Schmiede auf. Er wird Euch kostenlos zum Südtorpass fliegen lassen. Stellt Euch nach Eurer Ankunft Pilot Hammerfuß vor.', },
    {'Bittet Gryth Thurden in der Großen Schmiede um einen Flug nach Loch Modan. Sprecht bei Eurer Ankunft mit Pilot Hammerfuß.', },
  },
  [26132] = {
    'Scheusale aus der Netherwelt',
    {'Die Ogermagier in der Muscheltiefe haben sich selbst ein paar Beschützer beschworen: Fleischlingscheusale aus der Netherwelt.|n|nWir können nicht riskieren, dass sie diese Entartungen später gegen unsere Streitmächte einsetzen. Wenn Ihr schon da drin seid, zerstört so viele von den Dingern, wie Ihr könnt.', },
    {'Tötet 8 Netherscheusale.', },
  },
  [26133] = {
    'Scheusale aus der Netherwelt',
    {'Die Ogermagier in der Muscheltiefe haben sich selbst ein paar Beschützer beschworen: Fleischlingscheusale aus der Netherwelt.|n|nIch will nicht miterleben, dass sie diese Entartungen gegen unsere Streitmächte einsetzen. Wenn Ihr schon da drin seid, vernichtet sie alle!', },
    {'Tötet 8 Netherscheusale.', },
  },
  [26134] = {
    'Nichts mehr für Euch hier',
    {'Es gibt hier nichts mehr für Euch, $N. Was mich betrifft, ich muss nur noch Mashas Leiche begraben. Wenn ich das getan habe, werde ich zur Bombenabwurfstelle gehen und das Nachwachsen einleiten. Vielleicht wird eines Tages ein neuer Hain erblühen - ein Hain erfüllt mit dem Geist meines Kindes und denen der gefallenen jungen Nachtelfen.|n|nIch habe von einem Blutelf namens Furien in Desolace gehört, der nach gleichgesinnten Abenteurern sucht. Vielleicht solltet Ihr ihn aufsuchen.|n|nLebt wohl, $GFreund:Freundin;, ich werde Euch nie vergessen.', },
    {'Sprecht mit Furien in Tethris Aran in Desolace.', },
  },
  [26135] = {
    'Visionen der Vergangenheit: Aufstieg aus der Tiefe',
    {'Was Ihr mir vorhin von den Naga erzählt habt, lässt mir keine Ruhe mehr. Wer sind diese Verbündeten, die sie rufen? Denken sie wirklich, sie könnten den Gezeitenjäger besiegen?|n|nDie Flucht aus dieser Höhle ist eine ganz schöne Erleichterung, aber unser Ziel hier bleibt das gleiche. Ich hoffe, dass Ihr bereit seid, ein letztes Mal die Antworten bei der Kriegsmaid zu suchen.|n|nEs kann nur einen Ort geben, an den sie das Artefakt gebracht haben: den Tempel oben auf den Ruinen. Sicher wird er gut beobachtet. Seid daher vorsichtig.', },
    {'Werdet Zeuge der letzten Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge im Tempel von Quel\'Dormir benutzt.', },
  },
  [26137] = {
    'Auf der Suche nach den Jungs',
    {'Ihr habt sicher gesehen, wie stark der Loch mittlerweile geschädigt ist. Die Schäden dehnen sich leider sogar noch weiter aus. Das ganze Wasser musste ja irgendwo hin, und es floss hinunter ins Sumpfland.|n|nDa unten unterstützen uns viele mutige Zwerge. Sie brauchen Vorräte. Aus diesem Grund habe ich zwei meiner Gebirgsjäger mit einem Fass voller Bier auf den Weg ins Sumpfland geschickt.|n|nSeit sie die Straße nach Dun Algaz erreicht haben, gab es keine Nachricht mehr von ihnen. Würdet Ihr nachsehen, ob es ihnen gut geht?', },
    {'Reist ins Sumpfland und sprecht mit Gebirgsjäger Rharen nahe Dun Algaz.', },
  },
  [26138] = {
    'Ferilon Laubkind',
    {'Eine Gruppe von Nachtelfen hat sich im Sumpfland niedergelassen. Ein paar von ihnen sind aus Kalimdor eingetroffen, um das Land hier zu untersuchen, sich die Pflanzen anzusehen und all so etwas.|n|nEiner der Druiden - er heißt Ferilon - kam hier vor einer Weile vorbei. Er war so nett, uns mit den Raptoren zu helfen und erwähnte, dass er Leute braucht, die ihn bei seinen Aufgaben unterstützen.|n|nWenn Ihr Zeit habt, könntet Ihr ihn an einem Ort im Nordosten namens Hain des Sumpfhüters aufsuchen.', },
    {'Findet Ferilon Laubkind im Hain des Sumpfhüters.', },
  },
  [26139] = {
    'Nach Arathi',
    {'Geht vor und warnt die andere Seite des Übergangs, $N.|n|nHinter der Brücke im Norden werdet Ihr die Zuflucht finden, die Festung der Allianz in Arathi. Sagt Hauptmann Nials, er solle sich vor den Hundesöhnen des Schattenhammers in Acht nehmen.', },
    {'Reist ins Arathihochland und sprecht mit Hauptmann Nials in der Zuflucht.', },
  },
  [26140] = {
    'Mit dem Ahnen reden',
    {'Setzt den toten Gnadenlosen auf Euren Kopf und gebt Euch als einer ihrer Sklaven aus.|n|nBetretet L\'ghorek. Kommuniziert mit dem Ahnen.', },
    {'Bringt das Gehirn des Unergründlichen zu L\'ghorek im Cerebrillum in L\'ghorek in Vashj\'ir.', },
  },
  [26141] = {
    'Runensteine der Bindung',
    {'AUF DER ANDEREN… SEITE MEINES… RAUMS SIND… KANDIDATEN FÜR DEN AUFSTIEG.|n|nWIR BENÖTIGEN… IHRE RUNENSTEINE DER BINDUNG… UM EINEN... WEG ZU FINDEN... EINEN GEBUNDENEN ELEMENTAR... ZU KONTROLLIEREN.', },
    {'Sammelt 7 Runensteine der Bindung.', },
  },
  [26142] = {
    'Aufstieg verboten!',
    {'UM IHRE… RITUALE DES AUFSTIEGS… AUFZUHALTEN… MÜSST IHR DIE… URALTEN LEITUNGEN ZERSTÖREN.|n|nSIE VERWENDEN… DIE LEITUNGEN, UM… MEINE ENERGIEN… ABZUZAPFEN UND… ASZENDENTEN ZU ERSCHAFFEN.|n|nEIN KAMPF MIT… NEPTULON IST UNVERMEIDBAR. DER SCHATTENHAMMER… DARF DIESE WESEN... NICHT HABEN.', },
    {'Zerstört 5 uralte Leitungen.', },
  },
  [26143] = {
    'Alles, was aufsteigt',
    {'<Die Stimme des Ahnen drückt gegen Euren Geist.>|n|nJETZT, DA IHR… DIE ENERGIEN… DER GETREUEN… GESTOHLEN HABT… BETRETET DEN TEMPEL UND… VERNICHTET… HALLAZEAL DEN AUFGESTIEGENEN!', },
    {'Tötet Hallazeal den Aufgestiegenen.', },
  },
  [26144] = {
    nil,
    {'Der Kultist des Schattenhammers hat diesen Schlüssel fallenlassen. Benutzt ihn, um die Gefangenen der Allianz in den Käfigen in L\'ghorek zu befreien.|n|nSchnell, bevor die Gefangenen dem geopfert werden, was dort in der Tiefe lauert!', },
    {'Rettet 5 Gefangene der Allianz.', },
  },
  [26145] = {
    'Die Bedrohung durch die Troggs',
    {'$C, Ihr seid Euch vielleicht nicht unbedingt der Bedrohung durch die Troggs bewusst, die ihren Schatten über das Land der Zwerge wirft. Nachdem die Reserve von Eisenschmiede zur Front der Allianz gerufen wurde, bleibt uns nur ein Bruchteil der Verteidigungskräfte, die nötig wären, um dieses Land zu schützen. Meinem Regiment wurde aufgetragen, über die Stadt hier zu wachen und wir können unseren Posten aufgrund der Gefahr einer Invasion nicht verlassen.|n|nEs muss aber etwas Druck auf diese verdammten Troggs ausgeübt werden, die in den Hügeln lauern. Wenn Ihr Euch dem gewachsen fühlt, startet einen Angriff auf die Troggs. Bringt mir acht Troggsteinzähne als Beweis.', },
    {'Sammelt 8 Troggsteinzähne.', },
  },
  [26146] = {
    'Verteidigung der Länder des Königs',
    {'Wir müssen den Loch beschützen, $N! Da so viele Soldaten des Königs tapfer auf entlegenen Schlachtfeldern kämpfen, wurden wir an der Heimatfront überrannt. Troggs schlüpfen aus jeder Spalte! Der Troggbefall stellt die größte Bedrohung für Eisenschmiede dar.|n|nWir brauchen Euch, $Gtapferer Abenteurer:tapfere Abenteurerin;, damit Ihr Euch vorwagt, um dieser Bedrohung durch die Troggs ein Ende zu bereiten. Tötet zwölf Splittersteintroggs und kommt zurück.', },
    {'Tötet 12 Splittersteintroggs oder Späher der Splittersteintroggs.', },
  },
  [26147] = {
    'Größer und ekliger',
    {'Die Gebirgsjäger haben mir erzählt, dass Ihr recht mutig und fähig seid, $N. $GEin:Eine:r; <Volk> wie Ihr ist hier vonnöten. Das Problem mit den Troggs wird nicht besser. Unsere Reservekräfte wurden an die Front gerufen und nun sind wir hier alleine. Doch jetzt, wo <ein erfahrener/eine erfahrene:c> $C hier ist, können wir sicher mehr erreichen.|n|nGeht und tötet acht Schamanen der Splittersteintroggs und acht Knochenknacker der Splittersteintroggs. Ihr könnt sie in und in der Nähe der Höhle im südlichen Teil der Berge finden.|n|nNun lasst uns sehen, ob Ihr Eurem Ruf als Trogg-Schreck gerecht werdet.', },
    {'Tötet 8 Schamanen der Splittersteintroggs und 8 Knochenknacker der Splittersteintroggs.', },
  },
  [26148] = {
    'Ein Entscheidungsschlag',
    {'Die Bestien in Loch Modan scheinen einem Häutpling namens Grawmug zu folgen. Er ist der größte aller Troggs und hält sich tief in der Dunkelheit der Höhlen nördlich von hier auf.|n|nWenn Ihr meint, Ihr seid einer solchen Aufgabe gerecht, so würde ich Euch gerne mit der Ermordung Grawmugs beauftragen.', },
    {'Tötet Grawmug.', },
  },
  [26149] = {
    nil,
    {'Der Kultist des Schattenhammers hat diesen Schlüssel fallenlassen. Benutzt ihn, um die Gefangenen der Horde in den Käfigen in L\'ghorek zu befreien.|n|nSchnell, bevor die Gefangenen dem geopfert werden, was dort in der Tiefe lauert!', },
    {'Rettet 5 Gefangene der Horde.', },
  },
  [26150] = {
    'Ein Besuch bei Maybell',
    {'Ihr scheint mir vom hilfsbereiten Schlag zu sein, $N. Würdet Ihr einem alten Mann einen Gefallen tun?|n|nDas letzte Mal, als ich drüben in den Weinbergen der Maclures war, habe ich Maybell in ihrer Hütte weinen hören. Wärt Ihr so nett und würdet nach ihr sehen? Ich mache mir Sorgen um sie.', },
    {'Sprecht mit Maybell Maclure in den Weinbergen der Maclures in den Wäldern von Elwynn.', },
  },
  [26151] = {
    'Dunkler Brief',
    {'Mir wurde aufgetragen, Euch so bald wie möglich nach Eurer Rückkehr aus den Koboldlagern hierauf aufmerksam zu machen, $N. Es scheint sich um einen Brief zu handeln, der mit dem Siegel der Leere verschlossen ist - zweifellos von unserem Hexenmeisterlehrer. Ich würde keine Zeit verlieren und ihn sofort lesen, bevor Ihr hier in der Abtei irgendetwas anderes macht.', },
    {'Lest den dunklen Brief und sprecht mit Drusilla La Salle auf dem Friedhof von Nordhaintal.', },
  },
  [26152] = {
    'Gesucht: James Clark',
    {'Auf Geheiß der Armee von Sturmwind wurde ein Kopfgeld auf James Clark ausgesetzt.|n|nClark wird gesucht wegen Raubes, Einbruchs, Brandstiftung und Mordes. Er wird auch verdächtigt, Brackbrunns preisgekröntes Schwein Prinzessin entführt zu haben und versteckt zu halten.|n|nJames Clark wurde zuletzt auf dem Weg zum Holzfällerlager des Osttals gesehen.|n|nFührt James Clark der Gerechtigkeit zu und meldet Euch dann bei Marschall McCree im Holzfällerlager des Osttals.', },
    {'Tötet James Clark und nehmt James Clarks Kopf.', },
  },
  [26153] = {
    'Pennys Kürbiskuchen',
    {'Meine Tochter liebt Kürbispuffer, aber hier in Elwynn gab es dieses Jahr wegen des kalten Winters nur wenig Kürbisse. Ich habe aber von einem Kürbisfeld bei Sturmwind gehört, auf dem die Früchte nun reif sein sollen. Erntet für mich ein paar reife Kürbisse und ich werde Euch meinen Dank beweisen.', },
    {'Sammelt 6 Sturmwindkürbisse und bringt sie Robby Flay in Sturmwind.', },
  },
  [26154] = {
    'Schattenkammerjäger',
    {'NUN… NEHMT DEN… ABGESTIMMTEN RUNENSTEIN… UND BENUTZT IHN… UM VON EINEM… GEBUNDENEN STROM… IM MITTLEREN TEMPEL… BESITZ ZU ERGREIFEN. SIE WERDEN… EUCH… IGNORIEREN. KEINER WIRD… EUCH BEMERKEN.|n|nNUTZT... DIE MACHT DES ELEMENTARS… UM ZWIELICHTVEREHRER... UND IHRE GESICHTSLOSEN AUFSEHER... ZU TÖTEN.', },
    {'Ergreift Besitz von einem gebundenen Strom und tötet dann 50 Zwielichtverehrer und 10 gesichtslose Aufseher.', },
  },
  [26155] = {
    'Erinnerungen an eine dunkle Bedrohung',
    {'Vor Jahren versuchten die Dunkeleisenzwerge den Steinwerkdamm zu zerstören. Moira mag zwar in Eisenschmiedes affigem neuen Senat sitzen, aber ich werde die Vergangenheit nicht vergessen... Nicht, wenn ein ganzer Trupp von ihnen hier im Loch herumläuft|n|nIhr müsst für mich dort hineingehen und herausfinden, was sie wirklich im Schilde führen. Findet ihre wahren Pläne. Zweifellos befinden sie sich mitten in ihrem Lager.|n|nVersucht, nicht entdeckt zu werden... Doch wenn man Euch bemerkt, verteidigt Euch, $N. Ich würde nur sehr ungern $Geinen guten:eine gute:r; <Volk> dort draußen verlieren.', },
    {'Besorgt Euch die Baupläne des Steinwerkdamms von den Dunkeleisenzwergen mitten im Loch.', },
  },
  [26156] = {
    'Der König mit seinem Heer',
    {'Der Steinwerkdamm mag schon zerborsten sein, $N, aber er hält mehr als nur Wasser zurück. Das Ganze hängt nur noch am seidenen Faden. Das Land ist ohnehin schon völlig instabil - wenn sie den verbliebenen Teil des Damms in die Luft jagen...|n|n... könnte halb Loch Modan einstürzen! Der Schaden wäre noch katastrophaler. Wenn wir nicht schnell handeln, stehen wir auf einem gigantischen Krater.|n|nBegebt Euch zu dem Steinwerkdamm und haltet die Pioniere der Dunkeleisenzwerge auf! Lasst keinen von ihnen davonkommen!', },
    {'Tötet 6 Pioniere der Dunkeleisenzwerge.', },
  },
  [26157] = {
    nil,
    {'Ich möchte, dass Ihr eine Nachricht für mich überbringt.|n|nKasim Sharim ist ein alter Blutmagier, der viel über die Dämonen in den Verwüsteten Landen weiß. Man sieht es ihm zwar nicht an, aber er ist recht alt und sehr mächtig... aber auch ein wenig exzentrisch. In letzter Zeit hält er sich meistens im hinteren Teil der Schlangenschlinge auf, einer Höhle in der Nähe des Ortes, an dem ihr die Kultisten getötet habt.|n|nBitte überbringt ihm diese Nachricht. Er wird ihre Bedeutung verstehen.', },
    {'Meldet Euch bei Kasim Sharim im hinteren Teil der Schlangenschlinge in den Verwüsteten Landen.', },
  },
  [26158] = {
    'Stimmt den Blutstein ab',
    {'Haben die Kämpfe auf dem Weg durch die Höhle Spaß gemacht? Zugegebenermaßen habe ich nicht die... praktischste Stelle für meine Studien ausgesucht, vor allem nicht für vorbeiziehende $GAbenteurer:Abenteuerinnen;, die nach Belieben kommen und gehen wollen.|n|nAllerdings kann ich Euch an meine Blutsteinteleporter anpassen. Legt einfach Eure Hände auf den Stein in der hinteren Ecke, dann werdet Ihr vor die Höhle versetzt. Benutzt den Stein draußen, um wieder hinein zu kommen!', },
    {'Stellt euch auf die Blutsteinteleporter in der Schlangenschlinge ein.', },
  },
  [26159] = {
    'Der erste Schritt',
    {'Wie jeder gute Blutmagier wirke ich meine Magie mit Blut. Jedes Blut ist anders. In den Verwüsteten Landen gibt es mehrere nützliche Geschmacksrichtungen, wenn man weiß, wo man suchen muss.|n|nFür unsere Zwecke? Basilisken und Hyänen zu gleichen Teilen. Wir werden viel Blut brauchen. Geht nach Westen ins Herz der Verwüsteten Lande. Und vergesst nicht, den Teleporter zu benutzen!', },
    {'Beschafft 9 Phiolen mit Blut einer Kicherfanghyäne und 9 Phiolen mit Blut eines Rotsteinbasilisken.', },
  },
  [26160] = {
    'Blutritual',
    {'Ihr wollt wahrscheinlich wissen, was wir tun. Hier ist die Kurzfassung - eine Fassung, in der ich Experte bin:|n|nDie Kultisten der Schattenanbeter wollen den Dämon Razelikh beschwören und in die Verwüsteten Lande holen. Das können wir nicht zulassen. Deshalb werden wir ihn selbst beschwören und umbringen. Das klingt leichter als es ist...|n|nLasst mich wissen, wenn Ihr für das Blutritual bereit seid und tretet dann zurück.', },
    {'Sprecht mit Kasim Sharim, um das Blutritual einzuleiten.', },
  },
  [26161] = {
    'Nicht irgendeine Leiche',
    {'Wir brauchen Loramus Thalipedes, den Dämonenjäger. Er kennt Razelikhs wahren Namen und wie Ihr wisst, braucht man den Namen eines Dämons, um Macht über ihn zu gewinnen. Das Problem ist nur, dass Loramus getötet und seine Leiche zerrissen wurde.|n|nWenn Ihr mir die Teile bringt, lässt sich noch etwas ausrichten. Alle drei Teile befinden sich im Westen... die Schreckensfelsoger verstecken sie in ihren Höhlen. Beeilt Euch, denn ebenso wie Grimeo, schuldet mir auch Loramus etwas...', },
    {'Findet Loramus\' Kopf, Loramus\' Torso und Loramus\' Beine.', },
  },
  [26162] = {
    'Der Altar der Stürme',
    {'Auf den Klippen westlich von hier steht ein mächtiger Altar. Ein mächtiger, DÄMONISCHER Altar, der von Kultisten bewacht wird, aber trotzdem mächtig ist. Wenn Ihr ihn erreichen könnt, dann wäret Ihr in der Lage, Loramus zu uns zurückzubringen.|n|nDer Altar wird sich Euch wahrscheinlich widersetzen, deshalb müsst Ihr Loramus\' Leichnam bis zur Vollendung des Rituals beschützen. Bringt den Dämonenjäger anschließend zu mir zurück.', },
    {'Bringt Loramus\' Leichnam zum Altar der Stürme und beschützt ihn während des Rituals.', },
  },
  [26163] = {
    'Die Zeit ist knapp',
    {'Razelikh will in die Verwüsteten Lande zurückkehren und Azeroth mit seinen Dämonen überrennen. Er bereitet bereits die Beschwörung der Legionen vor, die uns vernichten sollen. Mit diesen drei Amuletten können wir ihn zwar beschwören... aber nicht zerstören.|n|n<Der Gnom zeichnet rasch eine Rune in die Luft und reicht sie Euch.>|n|nBringt dies zu Grimeo am Dunklen Portal im Südosten. Er wird Euch führen. Beeilt Euch! Eure Zeit ist knapp bemessen! So wie meine Größe!', },
    {'Bringt die disharmonische Rune zu Behüter Grimeo am Dunklen Portal in den Verwüsteten Landen.', },
  },
  [26164] = {
    'Der verkohlte Granit des Dunklen Portals',
    {'Kasim möchte, dass Ihr Granitsplitter von den Felsen rund um das Dunkle Portal sammelt. Ich weiß nicht, was er mit den Felsen vorhat, aber ich habe einen Verdacht und der ist nicht angenehm.|n|nBenutzt diese Spitzhacke und sucht nach kleinen, zutage getretenen Steinen am Rand des Explosionskraters um das Portal', },
    {'Besorgt 24 verkohlte Granitsplitter.', },
  },
  [26165] = {
    'Das abscheuliche Blut der Dämonen',
    {'Sharim will Dämonenblut. Für mich persönlich sieht das Zeug nicht einmal aus wie Blut - eher wie flüssige Verwesung - aber das ist ohne Belang.|n|nZum Glück für Euch ist das Gebiet um das Dunkle Portal voller Dämonen. Höllenbestien, Teufelshunde und Teufelswachen - sie alle haben das, was Ihr benötigt, in reichlichen Mengen.', },
    {'Besorgt 7 Flaschen mit abscheulichem Dämonenblut.', },
  },
  [26166] = {
    'Verbesserung des Steins',
    {'<Grimeo packt die letzten Materialien in ein ordentlich umwickeltes Päckchen.>|n|nDas ist alles, was der Gnom von uns verlangt hat. Wenn Ihr ihn seht, sagt ihm bitte, dass meine Schuld mit dieser Aufgabe beglichen ist. Ich werde seine Bitten nicht länger erfüllen.', },
    {'Bringt Grimeos Paket zu Kasim Sharim in der Schlangenschlinge in den Verwüsteten Landen.', },
  },
  [26167] = {
    'Das Amulett von Allistarj',
    {'Um unseren Dämon zu beschwören, brauchen wir drei Amulette. Das erste ist das Amulett von Allistarj.|n|nAllistarj selbst ist tot, aber er hat sein Amulett in einer Schatzgrube in dieser Höhle eingeschlossen. Zusammen mit anderen Amuletten wird dieses Relikt uns Zugang zu Razelikhs Behausung verschaffen.|n|n<Kasim konzentriert sich einen Moment.>|n|nDas Amulett befindet sich nahe des Eingangs. Ich würde vorschlagen, den Teleporter zu benutzen.', },
    {'Besorgt das Amulett von Allistarj aus der Schlangenschlinge in den Verwüsteten Landen.', },
  },
  [26168] = {
    'Das Amulett von Sevine',
    {'Das zweite Amulett, Sevines Amulett, befindet sich weit im Süden in Händen eines Murlocs, auf einer Klippe mit Ausblick über die Havarieküste. Wie es in den Besitz dieses Murlocs gelangt ist, entzieht sich meiner Kenntnis, aber ich kann mit Sicherheit sagen, dass Ihr es dort finden werdet.|n|nBringt mir ihr Amulett, zusammen mit dem Rest.', },
    {'Besorgt das Amulett von Sevine von Salzflopper nahe der Havarieküste in den Verwüsteten Landen.', },
  },
  [26169] = {
    'Das Amulett von Grol',
    {'Grol... der Oger.|n|n<Kasim lacht.>|n|nGrols Leichnam ruht wohl nicht länger bei den Ogern. Seine Leiche ist zusammen mit seinem Amulett der Macht in einem Schiffswrack vor der Havarieküste im Osten. Sein Amulett ist das letzte - sobald sie vereint sind, werden die drei uns Zugang zu Razelikh gewähren und darin liegt unsere Chance, diesen Wahnsinn zu beenden.', },
    {'Besorgt das Amulett von Grol von der Havarieküste in den Verwüsteten Landen.', },
  },
  [26170] = {
    'Das letzte Ritual',
    {'Das Messer ist fertig. Loramus ist anwesend und weiß, was er zu tun hat. Ich werde nun die drei Amulette nehmen und ihre Verzauberung nutzen, um Euch Zugang zu Razelikh, dem Erschaffer des Amuletts, zu verschaffen.|n|nIch bin bereit, dieses Ritual an Euch und Loramus durchzuführen. Sprecht noch einmal mit mir, wenn Ihr beide ebenfalls bereit seid.', },
    {'Sprecht mit Kasim Sharim, um an seinem Ritual teilzunehmen.', },
  },
  [26171] = {
    'Ihr seid Rakh\'likh, Dämon',
    {'$GHeld:Heldin;, hört gut zu.|n|nZunächst müssen wir nach Nordwesten zum tödlichen Pförtner reisen, der auf uns am nördlichen Fuß der Anhöhe des Entweihers wartet. Der Pförtner wird uns dann oben auf die Anhöhe schicken. Sobald wir dort sind, brauche ich Eure Hilfe, um Razelikh zu besiegen, denn ich fürchte, dass ich nicht stark genug bin, um ihn alleine zu schlagen.|n|nWas noch wichtiger ist - Ihr müsst das Steinmesser halten und nicht benutzen, bevor ich es Euch sage. Dieses Messer wird Razelikhs Seele in ihrem neuen, ewigen Gefängnis festsetzen.|n|nWenn wir Erfolg haben, sprecht mit Grimeo, dem Draenei.', },
    {'Sprecht mit dem tödlichen Pförtner nördlich der Anhöhe des Entweihers. Wenn Ihr oben auf der Anhöhe angelangt seid, zerstört Razelikhs Körper und benutzt dann das Steinmesser des Versiegelns, um seine Seele gefangen zu nehmen.', },
  },
  [26172] = {
    'Auch Blutmagier müssen essen',
    {'Entgegen der landläufigen Vorstellung trinken uralte und mächtige Blutmagier KEIN Blut. Wir essen normale Speisen so wie jeder andere auch - etwas, was in der hintersten Ecke einer feindlichen Kultistenfeste schwer zu bekommen ist.|n|nDie Aschmähneneber im zentralen Tal der Verwüsteten Lande sind eine praktische Speise, da man ihr Fleisch nicht kochen muss. Würdet Ihr diese Eber jagen und meine schwindenden Nahrungsvorräte wieder aufstocken?', },
    {'Besorgt 5 Aschmähnensteaks von Aschmähnenebern in den Verwüsteten Landen.', },
  },
  [26173] = {
    'Rückendeckung',
    {'Der einzige Grund, warum Ihr mich neben Soldaten der Horde stehen seht, ist der, dass unsere Pflicht unsere Feindschaft überwiegt - wenn auch knapp. Man hat uns die Aufgabe übertragen, das Dunkle Portal vor unerwünschten Reisenden zu schützen. Der kürzlich aufgetretene Kataklysmus hat uns besonders verwundbar für Angriffe gemacht. Wir haben bereits Berichte über schwarze Drachen in der Gegend gehört...|n|nDa meine Leute sich auf ihre Pflichten konzentrieren müssen, brauchen wir jemanden, der die Dämonen im Zaum hält. Um das Portal herum werdet Ihr drei Hauptleute der Dämonen finden. Tötet sie.', },
    {'Tötet Jarroc Flügelriss, Shahandana und Gomegaz.', },
  },
  [26174] = {
    'Nachhut',
    {'<Wachkommandant Reldorn Netherschwund schlägt einen verschwörerischen Ton an.>|n|nIch habe Befehle von... oben... für die Ihr bestens geeignet seid. Ich habe gesehen, dass die Horde regelmäßig einen Blick in den Stapel Papiere dort auf dem Fass wirft. Ich möchte, dass Ihr Euch diese Papiere anschaut und herausfindet, was sie vorhaben. Meine Pflicht und mein Posten erlauben mir nicht, solch eine fragwürdige Aufgabe durchzuführen - aber Ihr seid ein Neuankömmling und könntet unbemerkt hineinschlüpfen...', },
    {'Untersucht die Pläne der Horde am Dunklen Portal, ohne erwischt zu werden.', },
  },
  [26175] = {
    nil,
    {'Abgesehen von dem, was Ihr gesehen habt, ist das Portal überraschend ruhig. Leider kann ich Euch kaum noch Arbeit geben.|n|nWenn Ihr nach Ärger sucht, könntet Ihr es im Fischerdorf der Gilneer im Südwesten versuchen. Surwich, so heißt es, glaube ich.|n|nIch weiß, dass wir eigentlich mit den Gilneern befreundet sein sollten, aber mal ehrlich? Worgen? Es fiel mir schon schwer, mich an die Draenei zu gewöhnen.', },
    {'Meldet Euch bei Bürgermeister Carl Connisport in Surwich in den Verwüsteten Landen.', },
  },
  [26176] = {
    'Auf nach Thelsamar',
    {'Ihr habt uns hier sehr geholfen. Falls Ihr aufbrechen wollt, würde ich Euch gerne bitten, diesen Statusbericht nach Thelsamar zu bringen.|n|nFolgt der Straße in Richtung Norden und Ihr könnt es nicht verfehlen. Der Statusbericht muss zu Gebirgsjäger Kadrell.', },
    {'Bringt den Statusbericht von Hauptmann Rugelfuß zu Gebirgsjäger Kadrell in Thelsamar.', },
  },
  [26177] = {
    'Lust auf Krebs?',
    {'Frische Krabbenbeine waren schon immer eine der Lieblingsspeisen des Königs. Wir hatten in den letzten Wochen viel Erfolg beim Krebsfangen in den Kanälen. Könnt Ihr mir helfen und ein paar für mich fangen? Sie müssen lebendig gefangen werden, tot nützen sie mir nichts - für den König ist nur der frischeste Fang gut genug.', },
    nil,
  },
  [26178] = {
    'Zukunftsplanungen',
    {'Um unser Überleben zu sichern, müssen wir entschlossen gegen die Wolvar vorgehen. Ich mache mir jedoch Sorgen, dass wir in unserem Eifer zu viele von ihnen erschlagen werden.|n|nDie Schneewehenwolvar haben genauso wie wir das Recht zu überleben – also werden wir beide dafür sorgen, dass sie dieses Recht auch bekommen.|n|nWenn er es nicht schon längst getan hat, dann wird Euch Ältester Ko\'nani darum bitten, mit den Wolvar fertigzuwerden. Und aus diesem Grund möchte ich auch, dass Ihr ihre Jungen einfangt und sie zu mir bringt, wenn Ihr Euch auf der Lichtung im Norden befindet.', },
    {'Sammelt 12 Schneewehenwelpen und liefert sie anschließend bei Fallensteller Mau\'i im Hafen Moa\'ki ab.', },
  },
  [26179] = {
    'Die Venture Company',
    {'Das erklärt auch die Aufstockung von Angestellten und Ausrüstung der Venture Company, die wir in Mulgore gesehen haben. Diese Goblins... ihre Firma wächst viel zu schnell, als dass es gut für sie wäre. Es heißt doch, zeigt man einem Goblin etwas, kann man gleich im Hintergrund die Registrierkasse klingeln hören.|n|nGierige kleine Teufel. Bedauerlich für ihre geschäftlichen Vorhaben, aber wir Tauren können es nicht zulassen, dass sie ihre Arbeiten hier in unserem Land durchführen. Begebt Euch zu ihrer Mine nordöstlich der Überfallenen Karawane und schickt ihnen eine Nachricht.', },
    {'Tötet 7 Tagelöhner der Venture Co. für Morin Wolkenpirscher in der Nähe des Dorfs der Bluthufe.', },
  },
  [26180] = {
    'Vorsteher Zischelspross',
    {'Laut der Dokumente, die Ihr von der Karawane geborgen habt, hat die Venture Company viele Pläne parat, um zu versuchen, uns aus unserer Heimat hier zu vertreiben und damit freie Bahn zur Ausbeutung des Landes zu haben.|n|nIch bin entsetzt und es stößt mich ab, auf welches Niveau man sich herablassen kann, um seine Ziele durchzusetzen. Ich will, dass der führende Kopf hinter ihren Plänen vernichtet wird. Er heißt Vorsteher Zischelspross, Ihr findet ihn in der Mine der Venture Co. östlich der Überfallenen Karawane. Bringt mir sein Klemmbrett, vielleicht finden wir damit ja etwas Nützliches heraus.', },
    {'Tötet Vorsteher Zischelspross und nehmt sein Klemmbrett an Euch.', },
  },
  [26181] = {
    'Rückkehr zur Dämmerbucht',
    {'IHR MÜSST ZURÜCK… ZUR… DÄMMERBUCHT. ERUNAK STEINSPRECHER ERWARTET… EUCH DORT.|n|nICH STERBE JETZT...', },
    {'Sprecht mit Erunak Steinsprecher in der Dämmerbucht in Vashj\'ir.', },
  },
  [26182] = {
    'Rückkehr zur Schattenhöhle',
    {'IHR MÜSST ZURÜCK… ZUR… SCHATTENHÖHLE. ERUNAK STEINSPRECHER ERWARTET… EUCH DORT.|n|nICH STERBE JETZT...', },
    {'Sprecht mit Erunak Steinsprecher in der Schattenhöhle in Vashj\'ir.', },
  },
  [26183] = {
    'Des Königs Apfelwein',
    {'Ich stehe für immer in der Schuld des Königs. Für alles, was er für uns getan hat. Ich kann ihm nicht viel anbieten, aber sein Lieblingsgetränk kann ich ihm brauen! Glücklicherweise wachsen die Zutaten für dieses köstliche Getränk hier in Sturmwind. In jedem Distrikt stehen Apfelbäume. Die Bäume sind zu hoch, um die Äpfel zu pflücken, aber die, die auf den Boden gefallen sind kann man leicht aufsammeln.', },
    {'Sammelt 12 saftige Äpfel und bringt sie zu Robby Flay in Sturmwind.', },
  },
  [26184] = {
    'Wurmdorns Traum',
    {'Es wird Euch nicht überraschen, dass die meisten Einwohner von Surwich nicht wegen der angenehmen Atmosphäre in die Verwüsteten Lande gekommen sind. Sie kamen, weil sie dem Traum eines idealistischen Druiden folgten: Marl Wurmdorn. Wurmdorn glaubte, dass die Faulende Narbe geheilt werden könnte und versuchte, sie wachsen zu lassen.|n|nEr hat sich wohl geirrt. Er ließ seinen Wald wachsen, aber das Land wird immer noch von Dämonen heimgesucht und sein großer Baum ist verwachsen und knorrig.|n|nTrotzdem hoffe ich noch. Wenn wir uns in den Besudelten Wald begeben und einen Teil der Besudelung entfernen könnten...', },
    {'Tötet 5 Zerstörer der Verdammniswache, 5 Schreckenslordschänder, 5 verderbte Dunkelwaldtreants und 3 Teufelssporensumpflords im Besudelten Wald.', },
  },
  [26185] = {
    'Rat vom Zirkel des Cenarius',
    {'Ich glaube, dass die Besudelung der Verwüsteten Lande ihren Einfluss auf meinen Freund Wurmdorn ausgeweitet hat. Sein Experiment ist gescheitert und sein großer Baum dient nur noch den Dämonen als Versammlungsort.|n|nDer Baum muss fallen und Wurmdorn mit ihm. Sprecht mit der cenarischen Beobachterin auf der anderen Seite des Orts. Sie sollte wissen, was als Nächstes zu tun ist.|n|n$N: Die Einwohner von Surwich dürfen nichts von unseren Plänen erfahren. Ihre Stimmung ist schon schlecht genug.', },
    {'Meldet Euch bei der cenarischen Beobachterin Shayana in Surwich in den Verwüsteten Landen.', },
  },
  [26186] = {
    'Dämonisches Gefäß',
    {'Wir müssen Wurmdorns Aufmerksamkeit erregen. Wir brauchen etwas, das ihn aus seiner Trance holt. Etwas, das garantiert funktioniert.|n|nDie wenigen Wildtierarten, die es geschafft haben, sich im Besudelten Wald anzusiedeln, sind zweifellos von den latenten Energien des Landes in Mitleidenschaft gezogen worden. Eure Aufgabe ist es, ihre Kadaverteile einzusammeln und eine Möglichkeit zu finden, sie in ein Gefäß umzuwandeln. Egal, ob Wurmdorns Trance druidischer oder dämonischer Natur ist, ein Gefäß mit besudeltem Tierfleisch, das groß genug ist, sollte in der Lage sein, diese zu durchbrechen.', },
    {'Tötet besudelte Schwarzbären, besudelte Nachtpirscher und besudelte Kreischer im Besudelten Wald und versucht, ihre Kadaverteile zu einem dämonischen Gefäß zusammenzusetzen.', },
  },
  [26187] = {
    'Der Fall des Marl Wurmdorn',
    {'Wenn sich herumspricht, was wir getan haben... kann niemand sagen, wie die Bürger von Surwich reagieren werden. Sie klammern sich an Wurmdorns Traum...|n|n...aber trotzdem müssen wir es tun. Nehmt das dämonische Gefäß und benutzt es gegen Marl Wurmdorn, um ihn aus seiner Trance zu holen. Kehrt zu mir zurück, wenn er nicht mehr unter uns weilt.', },
    {'Tötet Marl Wurmdorn bei Maldraz in den Verwüsteten Landen. Ihr könnt das dämonische Gefäß benutzen, um ihn aus seiner Trance zu holen.', },
  },
  [26188] = {
    nil,
    {'Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranach. Er erzählte mir von seinen dämonischen roten Augen, seinen rasiermesserscharfen Krallen und seinem giftigen Biss.|n|nWie der Zufall so spielt, stieß ich auf einer meiner Reisen durch die Ebene auf ihn und trug eine üble Bisswunde an meiner Schulter davon. Er war so Furcht erregend, wie ihn mein Großvater beschrieben hatte. Ich habe alle Zutaten für das Gegengift, das ich für meine Heilung benötige, zusammen... bis auf einen Knochen eines Flachlandpumas.|n|nIch werde von Minute zu Minute schwächer... bitte helft mir.', },
    {'Bringt einen Knochen eines Flachlandpumas zu Maur Regenrufer im Dorf der Bluthufe.', },
  },
  [26189] = {
    'Die Grollhauerbedrohung',
    {'Als wir uns hier oben hin zurückzogen, um den Raptoren zu entgehen, landeten wir genau neben jeder Menge Drachenmalorcs!|n|nIn Menethil habe ich Geschichten gehört - dass die Orcs des Drachenmals noch barbarischer als andere Orcs sind, dass sie schwarze Drachen mit bloßen Händen erwürgen... Ich weiß nicht, was davon stimmt, aber wir können sie nicht in den Hügeln sitzen lassen.|n|nIhr habt genug Mut dafür, $N. Geht nach Osten zum Lager der Grollhauer, kümmert Euch um diese Orcs und vor allem um ihren Anführer!', },
    {'Tötet Gorfax Grollhauer und 16 Orcs des Drachenmals im Lager der Grollhauer.', },
  },
  [26190] = {
    'Ein Fischerschmaus',
    {'Wenn der König ein Lieblingsessen hat, dann ist es frischer Wels. Wels ist leicht zuzubereiten aber schwer zu fangen. Genau - hier kommt Ihr ins Spiel. Wir haben in Sturmwind viele gigantische Welse und der Wettbewerb, sie zu fangen, ist sehr intensiv, um es vage zu formulieren. Findet für mich einen Weg, diese feinen Welse für den König zu erhaschen. Ihr werdet am Ufer des Kanals überall in der Stadt Fischer finden. Den Rest des Planes findet Ihr sicherlich selber heraus.', },
    {'Bringt 5 gigantische Welse in Euren Besitz und bringt sie zu Robby Flay in Sturmwind.', },
  },
  [26191] = {
    'Der Gipfel unserer Bemühungen',
    nil,
    nil,
  },
  [26192] = {
    'Auch Waisen mögen Kekse!',
    {'Die Waisenkinder Sturmwinds werden oft vergessen, aber nicht heute. Der König hat nach einer Sonderlieferung Kekse gefragt, die umgehend zum Waisenhaus geschickt werden soll. Mit der letzten Ladung war ich fast fertig, aber dann ging mir der Puderzucker aus. Könnt Ihr schnell los und mir welchen besorgen? Jeder Gemischtwarenladen in der Stadt oder auch die Gasthäuser sollten welchen haben.', },
    {'Bringt 4 Säcke Puderzucker zu Robby Flay in Sturmwind.', },
  },
  [26193] = {
    'Verteidigung des Abgrunds',
    nil,
    nil,
  },
  [26194] = {
    'Verteidigung des Abgrunds',
    nil,
    nil,
  },
  [26195] = {
    'Wer hütet den Sumpfhüter',
    nil,
    {'Sprecht mit Ferilon Laubkind im Hain des Sumpfhüters im Sumpfland.', },
  },
  [26196] = {
    'Langzopf der Grimmige',
    {'Die Zwerge von Dun Modr kämpfen Tag und Nacht gegen die Dunkeleisenzwerge, die in ihre alte Heimat eingedrungen sind. Wir können es zwar unseren Wächtern nicht erlauben, ihr Leben für sie zu riskieren, aber wir schicken ihnen dringend benötigte Vorräte, damit sie ihre Wache fortsetzen können.|n|nWenn es geht, könntet Ihr Langzopf dem Grimmigen nördlich von hier dieses Paket bringen? Seine Leute können den Inhalt sicherlich gut gebrauchen.', },
    {'Bringt Ferilons Überlebenspaket zu Langzopf dem Grimmigen in Dun Modr.', },
  },
  [26197] = {
    'Die Zukunft von Gnomeregan',
    {'Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.|n|nBipsi Frostschleuder wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Sie erwartet Euch im Erdgeschoss des großen Gebäudes im Nordosten.', },
    {'Trefft Bipsi Frostschleuder in Neu-Tüftlerstadt.', },
  },
  [26198] = {
    'Die Künste eines Magiers',
    nil,
    nil,
  },
  [26199] = {
    'Die Zukunft von Gnomeregan',
    {'Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen. |n|n"Doc" Raddreh wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Sie erwartet Euch neben der Gebäudeansammlung im Norden.', },
    {'Trefft "Doc" Raddreh in Neu-Tüftlerstadt.', },
  },
  [26200] = {
    'Das richtige Wort',
    nil,
    nil,
  },
  [26201] = {
    'Die Macht eines Hexenmeisters',
    nil,
    nil,
  },
  [26202] = {
    'Die Zukunft von Gnomeregan',
    {'Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Wir werden all die Hilfe brauchen, die wir kriegen können, um unsere Heimat von den Troggs und den bestrahlten Gnomen zu befreien. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure, ähem... Künste zu erlernen.|n|nAlamar Grimm hält sich in dem Gebäude westlich von diesem hier auf. Er besitzt Kräfte, die den Euren gleichen. Er wird Euch helfen, Euch einzugewöhnen.', },
    {'Sucht Alamar Grimm in Neu-Tüftlerstadt auf.', },
  },
  [26203] = {
    'Die Zukunft von Gnomeregan',
    {'Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.|n|nAusbildungsoffizier Dampfkurbel wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Er erwartet Euch auf dem kleinen Übungsfeld auf der anderen Straßenseite.', },
    {'Sucht Ausbildungsoffizier Dampfkurbel in Neu-Tüftlerstadt auf.', },
  },
  [26204] = {
    'Die Künste eines Kriegers',
    nil,
    nil,
  },
  [26205] = {
    'Eine Aufgabe für den Multi-Bot',
    {'Der Multi-Bot wird uns bei all den Aufgaben helfen, die für uns Gnome unangenehm oder gefährlich sind... sollte er funktionieren.|n|nAls Thermadraht seinen Verstrahler am Ende von Operation: Gnomeregan zündete, entstanden giftige Wolken. Giftschlamm begann unter dem alten Flugplatz südlich der Stadt hervorzubrodeln.|n|nWenn wir das nicht unter Kontrolle bekommen, könnte sich die Kontaminierung auf den Rest unseres Landes ausdehnen. Nehmt den Multi-Bot und bringt ihn in die Nähe der Geysire in den grünen Becken auf dem Toxischen Flugplatz. Der Bot sollte automatisch anspringen.', },
    {'Benutzt den GS-9x Multi-Bot, um 5 toxische Geysire auf dem Toxischen Flugplatz zu säubern. Wenn Ihr nahe genug an einen Geysir herangekommen seid, wird der GS-9x Multi-Bot automatisch mit seiner Arbeit beginnen.', },
  },
  [26206] = {
    'Die Zukunft von Gnomeregan',
    {'Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.|n|nKelsey Stahlfunken, ein wichtiges Mitglied des Geheimteams Gnomeregan, wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Ihr findet sie nordwestlich von hier im Ratszelt.', },
    {'Sucht Kelsey Stahlfunken in Neu-Tüftlerstadt auf.', },
  },
  [26207] = {
    'Die Künste eines Schurken',
    nil,
    nil,
  },
  [26208] = {
    'Der Kampf wird fortgesetzt',
    {'Die Zwerge von Eisenschmiede nahmen uns freundlicherweise auf, als die Trogginvasion und die Strahlung uns zum ersten Mal zwangen, Gnomeregan zu verlassen. Doch selbst die Hilfsbereitschaft von Freunden, kann das Heimweh nicht unterdrücken.|n|nIch habe um die Hilfe mutiger Gnome und anderer Mitglieder der Allianz gebeten. Gemeinsam wird es uns gelingen, die Kontrolle über Gnomeregan wiederzuerlangen und den Thronräuber Thermadraht ein für alle Mal zu besiegen.|n|nWir konnten mit Operation: Gnomeregan nicht alles erreichen, was wir uns vorgenommen hatten, aber Thermadraht ist auf der Flucht und wir sind unserer Heimat einen Schritt näher.', },
    {'Betrachtet den Holo-Tisch vor Hochtüftler Mekkadrill, um mehr über Operation: Gnomeregan zu erfahren.', },
  },
  [26209] = {
    'Der Mordfall war der Fall, den sie mir gaben',
    {'So sieht\'s aus, $GJunge:Mädchen;, wir haben es mit einem ausgewachsenen Mordfall zu tun. Doppelter Homizid... Einfacher Pferd... izit.|n|nUnd was noch schlimmer ist, wir befinden uns hier in Westfall. Hier kann man mit einem einzigen Steinwurf haufenweise Landstreicher erwischen, die ein Motiv gehabt hätten, die Leute (und das Pferd) um die Ecke zu bringen.|n|nIch habe keine Ahnung, wer es war und ich bin ganz bestimmt nicht gerne hier in diesem Loch, um den Tod von ein paar Landbesetzern aufzuklären, aber ich möchte verdammt sein, wenn ich den Täter nicht dingfest machen kann. Ihr wollt helfen? Dann sprecht mit den Landstreichern. Die Vagabunden... kriegen alles mit.', },
    {'Sprecht mit den verschiedenen Obdachlosen, die auf Jansens Hof leben, um Hinweise über die Brauenwirbelmorde zu sammeln.', },
  },
  [26210] = {
    'Gammerita, Alter!',
    {'Yo! Da is ne Schildkröte da draußen, die nicht wie die anderen is\'. Das is\' die Gammerita, Anführerin der Salzwasserschnappkiefer, \'ne richtig fiese Diebin!|n|nAlter, die hat mir meinen besten Köder geklaut. Einfach so abgebissen, hatse den! Seitdem beißen die Fisch nichmehr so an wie vorher.|n|nFinde Gammerita und hol\' mir den Köder aus ihrem Bauch.', },
    {'Katoom, der Angler aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Gammerita tötet und Katooms besten Köder aus ihrem Kadaver holt.|n|nKatoom meinte, dass Gammerita sich an der Küste bei den anderen Schildkröten aufhält.', },
  },
  [26211] = {
    'Schnappkiefer, Alter!',
    {'Lass dich ja nicht von ihren großen Augen täuschen, Alter! Die Schnappkiefer da sind ne Bedrohung. Ich kann nicht mal für fünf Minuten angeln, ohne dass einer von diesen überdimensionalen Fisch-Staubsaugern mir meinen Köder klaut.|n|nTut mir und den Bruchhauern einen Gefallen und bringt sie um, Alter.|n|nBringt sie alle um!', },
    {'Katoom, der Angler aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 10 Salzwasserschnappkiefer tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.', },
  },
  [26212] = {
    'Lards vergessene Brotzeit',
    {'Lard Picknick gemacht hat, an geheimen Geheimplatz, als hässlicher, fieser Blutfratzentroll Lard mit großem Stock geschlagen hat. Lard zurück ins Dorf der Bruchhauer gerannt sein, aber Lard Brotzeit vergessen hat. Lard hungrig. Ihr vielleicht zurück gehen zu geheimen Geheimplatz und holen Brotzeit von Lard? Lard hat Angst. Gehen Norden! Insel dort im Norden seien geheimer Geheimplatz.', },
    {'Lard aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück.|n|nLard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Blutfratzen.', },
  },
  [26213] = {
    'Auf heißer Spur: Der Flusspfotenklan',
    {'Da wir keine anderen Anhaltspunkte haben, können wir genauso gut auch den Informationen nachgehen, die Ihr erhalten habt.|n|nEs gibt einige Lager der Flusspfotengnolle hier in der Nähe. Macht sie ausfindig und sucht nach Hinweisen. Bringt mir was Ihr finden könnt. Beschränkt Eure Suche auf die Gnolle und die Späher der Flusspfoten.', },
    {'Erhaltet den Hinweis der Flusspfotengnolle.', },
  },
  [26214] = {
    'Auf der Spur: Murlocs',
    {'Egal für wie sinnlos ich diese Sache halte, wir müssen allen unseren Anhaltspunkten auf den Grund gehen.|n|nIch möchte, dass Ihr Euch hinaus zur Endlosen Küste im Westen begebt und den Murlocs dort ein wenig einheizt. Versucht einen Hinweis oder Informationen aufzuspüren, die etwas Licht in diesen Mordfall bringen können.|n|nKehrt zu mir zurück, falls Ihr Erfolg habt.', },
    {'Findet den Murlochinweis.', },
  },
  [26215] = {
    'Ein Treffen mit Lou Zweischuh',
    {'Anscheinend haben wir hier einen echten Fall, Grünschnabel. Leider wollen die Anwohner offenbar nicht reden und die Anhaltspunkte, die Ihr von den Gnollen und Murlocs gewonnen habt, sind so gut wie wertlos. Wir müssen auf Plan... "Haltet nach Lou Zweischuh Ausschau" zurückgreifen.|n|nLou Zweischuh ist ein alter Informant von mir, der sich auf dem alten Kürbishof der Brauenwirbels niedergelassen hat. Geht nach Westen zu dem Gehöft und findet heraus, was Lou weiß.|n|nFalls er Euch irgendwelchen Mumpitz erzählt, sagt ihm, dass Horatio Euch schickt.', },
    {'Sprecht mit Lou Zweischuh auf Brauenwirbels Kürbishof in Westfall.', },
  },
  [26218] = {
    'Weit hergeholt',
    nil,
    nil,
  },
  [26219] = {
    'Der Kreis schließt sich',
    {'Wir haben die Bestie gefunden, die unsere Schiffe zerstört hat. Sie hat ihr Nest in der Dämmerbucht, einer riesigen Unterwasserhöhle am Rand des Abgrunds.|n|nDieses Mal sind wir bereit. Die Gnome haben in Sturmwind eine wahre Schönheit für uns gebaut. Sie steckt so voller Feuerkraft, dass das Scheusal sich in die Hosen machen wird vor Angst.|n|nWenn die Zange X2 an das Schiff andockt, begebt Euch an Bord und schaut, wie Ihr helfen könnt. Wir sind direkt hinter Euch.', },
    {'Geht von der Voldrins Mut aus an Bord der Zange X2 und helft dabei, Dämmerbucht zu sichern.', },
  },
  [26220] = {
    'Speck macht alles besser',
    {'Eine Armee hungriger Orcs zu füttern ist nie einfach. Wir haben hier glücklicherweise gute Vorräte an Fleisch von ausgewachsenen Schweinen von den Schweinehöfen südlich von Orgrimmar. Tut mir einen Gefallen und schlachtet ein paar dieser Schweine für ihre köstlichen Schweinebäuche. Ich werde sie schneiden und gebratenen Speck für das Frühstück der Truppen vorbereiten.', },
    {'Schlachtet einige der ausgewachsenen Schweine südlich von Orgrimmar und bringt mir 6 Schweinebäuche. Ich werde hier in der Gasse auf Euch warten.', },
  },
  [26221] = {
    'Der Kreis schließt sich',
    {'Wir haben die Bestie gefunden, die unsere Schiffe zerstört hat. Sie hat ihr Nest in der Schattenhöhle, einer riesigen Unterwasserhöhle im Wirbelnden Abgrund.|n|nDieses Mal sind wir bereit. Die Goblins haben sich als wertvolle Verbündete erwiesen und im Bilgewasserhafen eine bösartige Maschine für uns gebaut. Sie steckt so voller Feuerkraft, dass das Scheusal sich in die Hosen machen wird vor Angst.|n|nWenn die Verne an das Schiff andockt, begebt Euch an Bord und schaut, wie Ihr helfen könnt. Wir sind direkt hinter Euch.', },
    {'Geht von der Höllenjuwel aus an Bord der Verne und helft dabei, die Schattenhöhle zu sichern.', },
  },
  [26222] = {
    'Verteilte Teile',
    {'Es gibt so viel zu tun und so wenige Gnome, die in der Lage sind, mir zu helfen! Der Hochtüftler hat mich gebeten, einige alte Bots und Teile der Operation: Gnomeregan auszuschlachten. Mit ein wenig Glück kann ich eine neue Reihe Multi-Bots demnächst in der Praxis testen!|n|nHättet Ihr vielleicht Zeit, um mir zu helfen? Es liegen alle möglichen Teile hier herum. Hebt alles auf, was Ihr findet, und bringt es mir. Wer weiß, was sich davon als nützlich erweist!', },
    {'Bringt 7 Ersatzteile zu Ingenieur Schleiffunke in Neu-Tüftlerstadt.', },
  },
  [26223] = {
    'Die Pirsch auf die Pirscher',
    {'Viele mutige Trolle haben wir in der rauen Wildnis der Hinterlands verloren, $R. Die Silbermähnenwölfe stellen eine der größten Bedrohungen für unsere Jäger dar. Sie lauern versteckt in den Büschen und schlagen zu, sobald sie eine Möglichkeit dazu sehen.|n|nDiese Art von Gewalt wird nicht länger geduldet!|n|nIhr müsst wie die Silbermähnen denken. Lauert den Pirschern auf! Tötet sie alle!', },
    {'Tötet 8 Silbermähnenpirscher.', },
  },
  [26224] = {
    'Jagt die Wilden',
    {'Unter all den bösartigen Tieren der Wildnis des Hinterlandes, sind auch die Eulenbestien zu finden. Schon so manche gute Krieger der Bruchhauer verloren wir an die grausamen Krallen und die Schnäbel der Biester.|n|nTötet jede wilde Eulenbestie, die Ihr finden könnt, $R. Kehrt zu mir zurück, sobald Ihr von dem Blutbad genug habt. Euer Beitrag wird dann genau gewogen, abgemessen und bewertet.', },
    {'Tötet 10 Wilde Eulenbestien.', },
  },
  [26225] = {
    'Pupellyverbos\' Portwein',
    {'Ihr da! Wusstet Ihr, dass am Strand nördlich von hier dutzende Flaschen, wenn nicht hunderte Flaschen feinen Weins angeschwemmt wurden?|n|n...nun, jetzt wisst Ihr es!|n|nIch würde so viele nehmen, wie ich mit beiden Armen packen kann, wenn die Schildkröten nicht immer hinter mir her wären. Ich könnte schwören, sie wollen mein Blut!|n|nDa bezahle ich Euch doch lieber. Bringt mir 12 Flaschen Pupellyverbos\' Portwein und ich werde ihn Euch "abkaufen", $C.', },
    {'Sammelt 12 Flaschen mit Pupellyverbos\' Portwein.', },
  },
  [26226] = {
    'Flusskrebs à la Créole',
    {'Um Orgrimmar herum befinden sich mehrere kleine Seen. In den Seen wimmelt es jedes Jahr von Flusskrebsen. Hier kommt Ihr ins Spiel, $N. Ihr müsst für mich diese köstlichen Krustentiere fangen und sie mir bringen, wenn Ihr fertig seid. Wenn Ihr erfolgreich seid, wird unsere Armee heute abend ein Festmahl genießen.', },
    {'Fangt 10 schlammige Flusskrebse in Orgrimmar und bringt die Krustentiere zu Marogg, wenn Ihr fertig seid.', },
  },
  [26227] = {
    'Achtung, die Frucht beißt zurück.',
    {'Manchmal wollen unsere Streitkräfte auch etwas Süßes. Ich geben ihnen nicht immer, was sie wollen, aber heute werde ich eine Ausnahme machen. Sicherlich habt Ihr schon die einheimischen Kakteen gesehen, die in Orgrimmar wachsen. Die Kakteen tragen eine sehr leckere Delikatesse, die Kaktusfeigenfrucht. Das Problem ist, dass die Frucht voller Kaktusnadeln ist! Passt auf Eure Hände auf und bringt mir ein paar Früchte.', },
    {'Sammelt 8 Kaktusfeigen und bringt sie zu Marogg in Orgrimmar.', },
  },
  [26228] = {
    'Wie die Made im Speck',
    {'Hört zu, eigentlich sollte ich gar nich\' mit Euch reden, aber ich schulde Horatio den einen oder anderen Gefallen. Ich weiß eigenlich gar nichts darüber, was mit den Brauenwirbels passiert is\', aber vielleicht kann ich Euch trotzdem weiterhelfen.|n|n<Lou reicht Euch eine große Kiste.>|n|nDiese Kiste war mein Zuhause, bevor ich reich geworden bin. Jetzt führ\' ich ein Leben, von dem jeder Landstreicher träumt!|n|nAlso, Ihr schnappt Euch jetzt mal diese Wohnkiste hier und macht Euch auf zum Jangoschacht südwestlich von hier. Dringt bis ans Ende der Mine vor und versteckt Euch dort in der Kiste.', },
    {'Benutzt Lou Zweischuhs altes Haus am Ende des Jangoschachtes in Westfall.', },
  },
  [26229] = {
    '&quot;Ich NEHMEN Kerze!&quot;',
    nil,
    nil,
  },
  [26230] = {
    'Festmahl oder Hungersnot',
    {'Das Leben in Westfall ist schwer, $GSöhnchen:Mädchen;! Jeder Tag ist ein Kampf. Manchmal vergehen Wochen zwischen anständigen Mahlzeiten. Deswegen ist es so wichtig, dass wir uns gegenseitig beistehen. Vielleicht könnt Ihr ja mit anpacken, hm? Ich backe Matschkuchen und benötige noch ein paar Zutaten.|n|nBesorgt mir etwas frischen Matsch vom Kürbisbeet vor dem Haus und ein paar Kojotenschwänze. Ihr könnt überall in der Wildnis von Westfall Kojoten finden.|n|nAn die Arbeit! Wir haben Mägen zu füllen.', },
    {'Sammelt 6 Kojotenschwänze und 5 Handvoll frischen Matsch.', },
  },
  [26231] = {
    'Enterkommando',
    nil,
    nil,
  },
  [26232] = {
    'Lous Abschiedsworte',
    {'So ein paar Rohlinge sind vor kurzem auf dem Gehöft aufgetaucht und haben \'ne Menge Ärger verursacht. Keine Ahnung, wo die herkommen oder für wen die arbeiten, aber ich bin mir SICHER, dass sie nichts Gutes im Schilde führen. Ich hab\' sie vielleicht über so ein paar Dinge sprechen hören, die Euch interessieren könnten.|n|nWenn Ihr Interesse habt, findet ihr die Rohlinge hinter\'m Bauernhaus. Wenn man Euch ertappt oder umbringt, ich weiß nichts von Euch. Hab Euch noch nie im Leben gesehen!|n|nViel Glück, $GJunge:Mädel;.', },
    {'Belauscht die Rohlinge hinter dem Bauernhaus auf Brauenwirbels Kürbishof in Westfall.', },
  },
  [26233] = {
    'Aus den eigenen Reihen stehlen',
    nil,
    {'Bringt 6 Fässer mit Dunkelspeerreis in Euren Besitz und bringt sie zu Marogg in Orgrimmar.', },
  },
  [26234] = {
    'Aus den eigenen Reihen stehlen',
    nil,
    {'Bringt 6 Fässer mit Kezanreis in Euren Besitz und bringt sie zu Marogg in Orgrimmar.', },
  },
  [26235] = {
    'Auch Diebe bekommen Hunger',
    {'Seit ein paar Wochen haben wir hier in Orgrimmar Probleme mit Dieben, die die Rationen der Infanterie stehlen. Vor Kurzem habe ich Informationen darüber erhalten, wo diese Diebstähle stattfinden. Wenn Ihr irgendwo Kisten und Vorräte seht, könnt Ihr davon ausgehen, dass die Diebe nicht weit sind. Ich möchte, dass Ihr diese Diebe ausfindig macht und die gestohlenen Rationen findet. Kehrt zu mir zurück, wenn Ihr fertig seid.', },
    {'Findet 3 Infanterierationen der Horde und bringt sie zu Marogg in Orgrimmar.', },
  },
  [26236] = {
    'Die Vernehmung der Saldeans',
    {'Was wissen wir also bisher? Wir müssen unseren Anhaltspunkten folgen.|n|nDrüben auf Jansens Hof habt Ihr einen durchnässten Brief und ein paar rote Stofffetzen gefunden. Hier auf dem Hof der Brauenwirbels habt Ihr ein Gespräch zwischen einer merkwürdigen Gestalt und einem Ogermagier belauscht. Ihr habt außerdem die Geständnisse von ein paar Schlägern, den Mord begangen zu haben - woraufhin Ihr die Schläger getötet habt.|n|nDa passt Einiges nicht zusammen, Grünschnabel.|n|nSüdöstlich von hier lebt ein älteres Ehepaar auf Saldeans Hof. Macht Euch auf den Weg dorthin und sprecht mit Bauer Saldean. Findet heraus, was er weiß.', },
    {'Sprecht mit Bauer Saldean auf Saldeans Hof in Westfall.', },
  },
  [26237] = {
    'Die Zeiten sind schwer',
    {'Das sind schwere Zeiten, $GBruder:Schwester;. Da jetzt die geknechteten Massen aus Sturmwind hierher nach Westfall auswandern, sind unsere Vorräte knapper denn je. Das Volk ist unruhig und braucht Hilfe.|n|nUnser Farmhaus dient schon seit Jahren als Behelfsunterkunft. Salma gibt sich alle Mühe, unsere Gäste am Leben zu erhalten, aber manchmal werden sie von den Erntebehütern erwischt. Das sind diese missratenen Ungetüme, die sich auf meinem Feld herumtreiben - ein kleines Geschenk, das die Defias zurückgelassen haben, als sie vertrieben wurden. Helft uns!', },
    {'Tötet 10 Erntebehüter.', },
  },
  [26238] = {
    'Die wilden Zwerge',
    {'Die Horde hat für uns Bruchhauer viel getan und Trittbrettfahrer sind wir sicherlich nicht. Die anderen Waldtrollstämme wurden zurückgedrängt und wir sind dabei, im Namen der Horde neue Ländereien zu sichern.|n|nJetzt sind uns aber die Wildhammerzwerge in den Weg gekommen. Wenn sie Krieg wollen, so werden sie Krieg bekommen... und ich habe nicht vor, einen Krieg gegen jemanden zu verlieren, der nur halb so groß ist wie ich.|n|nGeht los und tötet ein paar Zwerge für mich.', },
    {'Tötet 10 Krieger der Wildhämmer oder Schamanen der Wildhämmer.', },
  },
  [26239] = {
    '&lt;PH&gt;Totem der Wildhämmer',
    nil,
    nil,
  },
  [26240] = {
    'Im Takt',
    {'Unsere Krieger kämpfen hart, um die üblen Wildhammerzwerge auszuschalten, damit wir hier im Dorf wieder in Sicherheit sind. Wir müssen tun, was wir können, um sie zu unterstützen.|n|nEs gibt etwas, das bei jedem Troll seine besten Kampfkünste herauskommen lässt: der hämmernde Rhythmus der Trommeln lässt sie fester zuschlagen und ruft die Geister dazu auf, über die Krieger zu wachen. Nehmt meine Trommeln mit auf das Schlachtfeld. Spielt sie für unsere Krieger und zeigt den Wildhammerzwergen, wem dieses Land gehört!', },
    {'Spielt die Kriegstrommeln der Bruchhauer für 6 Krieger der Bruchhauer.', },
  },
  [26241] = {
    'Westfalleintopf',
    {'Hallo, $Gmein Lieber:meine Liebe;. Willkommen in unserem Zuhause. Hmm, Ihr seht aber nicht aus, als ob Ihr obdachlos wärt. Seid Ihr hier, um uns zu helfen? Wenn das so ist, dann kommt Ihr gerade rechtzeitig! Ich plane ein Abendessen für die Kinder und ich brauche ein paar einfache Zutaten.|n|nWenn Ihr mir ein paar Okraschoten, Geiferzahnflanken und sehniges Fleischreißerfleisch bringt, kann ich meinen berühmten Westfalleintopf zubereiten. Ihr könnt all diese Zutaten in der Nähe unserer Farm finden. Nehmt Euch nur vor den Erntebehütern in Acht. Das sind gnadenlose Vernichtungsmaschinen.', },
    {'Sammelt 6 Okraschoten, 6 Stück sehniges Fleischreißerfleisch und 6 Geiferzahnflanken.', },
  },
  [26242] = {
    'Tiefenheim, Ebene der Erde',
    nil,
    nil,
  },
  [26243] = {
    'Die Weltensäule',
    {'Die Säule in diesem Zimmer stützt mehr als nur den Tempel der Erde.|n|nDiese gesamte Existenzebene stürzt bald in unsere Welt, wenn wir sie nicht wieder aufbauen.|n|nEs ist schon bald Zeit zu handeln. $N. Aber zunächst müsst Ihr Euch anhören, was ich Euch zu sagen habe.', },
    {'Befragt Maruut Steinbinder zur Weltensäule.', },
  },
  [26244] = {
    'Die Erde nimmt sich alles',
    {'Wir befinden uns auf der Ebene der Erde, $N. Nach und nach wird das Land alles in sich aufnehmen.|n|nDie Sturmfuror wird bald nichts als Staub sein. Dann können wir keine Erkenntnisse aus ihren Resten mehr gewinnen.|n|nGeht und vernichtet die Elementare, die das Schiff auseinandernehmen. Wir zögern das Unvermeidliche nur heraus, aber wir müssen uns etwas Zeit verschaffen, wenn wir alle Teile der Weltensäule finden wollen.', },
    {'Vernichtet 5 Tiefensteinelementare.', },
  },
  [26245] = {
    'Luftschiff am Boden',
    {'Der Abschlussstein wurde in einem Luftschiff der Horde namens Sturmfuror transportiert.|n|nDas Luftschiff ist südlich von hier abgestürzt. Laut unseren Untersuchungen befindet sich der Abschlussstein nicht mehr an Bord.|n|nDurchsucht das Schiff nach Hinweisen darauf, was passiert sein könnte.', },
    {'Sucht im Wrack der Sturmfuror in Tiefenheim nach Hinweisen.', },
  },
  [26246] = {
    'Das Logbuch des Kapitäns',
    {'<Ihr blättert zum letzten, abgebrochenen Eintrag.>|n|n… nähern uns dem Tempel der Erde bei 300 Knoten und beginnen die Landemanöver gemäß der neuen Route. Wir haben ein Niedrigdrucksystem im Norden notiert und ziehen jetzt unser…|n|nBLUT UND DONNER! ABSCHAUM DER ALLIANZ NÄHERT SICH!', },
    {'Bringt das Logbuch des Kapitäns zu Maruut Steinbinder beim Tempel der Erde in Tiefenheim.', },
  },
  [26247] = {
    'Diplomatie hat Vorrang',
    {'Der Irdene Ring ist eine neutrale Gemeinschaft, $N. Wir können uns im Krieg zwischen der Horde und der Allianz auf keine Seite schlagen.|n|nSeht Euch um. Wir haben Mitglieder verschiedenster Herkunft. Wenn wir die Spannungen zwischen den einzelnen Völkern über unser Ziel stellen würden, wäre unsere Mission in Gefahr. Lasst uns dies also vertraulich behandeln, bis wir weitere Informationen gesammelt haben.|n|nWir dürfen keine voreiligen Schlüsse ziehen. Ich schicke Euch zusammen mit einem unserer neuen Mitglieder los, um das Kanonenboot der Allianz zu suchen.|n|nFindet heraus, was Ihr könnt, ohne uns in den Konflikt hineinzuziehen.', },
    {'Trefft Euch mit Sturmruferin Mylra auf dem Kanonenboot der Allianz.', },
  },
  [26248] = {
    'All unsere Freunde sind tot',
    {'Irgendwas ist hier nicht in Ordnung, $N.|n|nDie Besatzung des Schiffes wurde erschlagen. Und doch sehe ich kein vergossenes Blut oder Schäden am Schiffskörper.|n|nDas war nicht das Werk der Horde.|n|nWir müssen mit den Geistern der Toten sprechen, um Antworten zu finden. Sie haben diese Welt noch nicht verlassen.|n|nNehmt dieses Totem und stellt es neben den Leichnamen der Gefallenen auf. Dann könnt Ihr ihre letzten Gedanken hören.|n|nAber seid vorsichtig! Es ist schwer zu sagen, wie die Geister der Toten auf unsere Nachforschungen reagieren werden.', },
    {'Benutzt das Geistertotem in der Nähe von 6 Leichnamen erschlagener Besatzungsmitglieder.', },
  },
  [26249] = {
    'Die Kajüte des Admirals',
    {'Möglicherweise finden wir in der Kajüte des Admirals weitere Spuren. Sie befindet sich direkt unter uns.|n|nSchaut, ob es dort unten irgendwelche Überlebenden oder Informationen gibt, die uns nähere Hinweise zum Verbleib des Weltensäulenfragments geben können. Seid vorsichtig, $N. Wer auch immer die Besatzung auf dem Gewissen hat, könnte noch dort sein.', },
    {'Haltet in der Kajüte des Admirals auf dem Kanonenboot der Allianz nach Hinweisen Ausschau.', },
  },
  [26250] = {
    'Ach, einen Gefangenen sollten wir doch nehmen',
    {'Es ist nicht zu spät, $N. Die Kultisten sind bestimmt immer noch hier.|n|nGeht unter Deck, findet heraus, wer das Sagen hat und unterwerft ihn.|n|nWir werden Antworten auf unsere Fragen bekommen, auf die eine oder andere Art.', },
    {'Unterwerft Mor\'norokk den Hasserfüllten auf dem Kanonenboot der Allianz in Tiefenheim.', },
  },
  [26251] = {
    'Macht keine Gefangenen',
    {'Sieht aus, als wäre der Schattenhammer noch immer auf dem Schiff. Geht unter Deck und macht kurzen Prozess mit ihnen.|n|nSeid vorsichtig, $N. Ich habe das Gefühl, dass sie nicht hier sind, um ihr spirituelles Gleichgewicht zu finden, wenn Ihr versteht, was ich meine.', },
    {'Tötet 6 Zwielichtsaboteure.', },
  },
  [26252] = {
    'Herz des Behüters',
    {'Ihr habt etwas gefunden, das offenbar das Herz eines Erntebehüters ist.|n|nDem Geräusch nach zu urteilen, das von dem Gerät ausgeht, ist es noch immer voll funktionsfähig. Vielleicht solltet Ihr es zu Bauer Saldean zurückbringen.', },
    {'Bringt das Herz eines Erntebehüters zurück zu Bauer Saldean auf Saldeans Hof.', },
  },
  [26253] = {
    'Sichert die Spuren',
    nil,
    nil,
  },
  [26254] = {
    'Erklärt Euch!',
    {'Springt auf, $N. Mal sehen, was Herr Ogervisage hier zu seiner Verteidigung zu sagen hat.|n|nNur keine Scheu. Sturmschnabel hat erst ein paar Mal einen Reiter fallenlassen.', },
    {'Springt auf Sturmschnabel und beobachtet Mor\'norokks Befragung.', },
  },
  [26255] = {
    'Rückkehr zum Tempel der Erde',
    {'Ihr müsst die anderen am Tempel informieren. Wahrscheinlich bringen sie das Fragment gerade an einen sicheren Ort.|n|nBerichtet Maruut, was Ihr wisst. Ich werde diesen Zwielichtrat in der Zwischenzeit unter die Lupe nehmen.', },
    {'Sprecht mit Maruut Steinbinder im Tempel der Erde in Tiefenheim.', },
  },
  [26256] = {
    'Lasst die Blutformer bluten',
    {'Der Schattenhammer wirkt hier bösartige Magie, $N. Sie beleben die Überreste von Todesschwinges Blut und erfüllen sie mit Energie. Statt auszutrocknen und zu verschwinden gedeiht es und wird immer mehr.|n|nErledigt einen ihrer Blutformer und presst Informationen aus ihm heraus, wo wir diesen "Schmiedemeister" finden.', },
    {'Besorgt Euch die Schattenhammerbefehle von einem der Zwielichtblutformer in Todesschwinges Sturz.', },
  },
  [26257] = {
    'Es lebt!',
    nil,
    nil,
  },
  [26258] = {
    'Todesschwinges Sturz',
    {'Dass der Schattenhammer etwas mit dem Verschwinden der Weltensäule zu tun hat, ist nicht verwunderlich. Hoffentlich können wir schnell genug handeln, um sie zurückzuholen.|n|n<Maruut legt seine Hand auf Eure Schulter.>|n|nIch habe ein spirituelles Band zu Euch gewirkt. Wir sollten miteinander kommunizieren können, solange Ihr in Tiefenheim seid.|n|nGeht zu Todesschwinges Sturz im Südosten und untersucht, was der Schattenhammer vorhat.', },
    {'Geht zu Todesschwinges Sturz in Tiefenheim.', },
  },
  [26259] = {
    'Blut des Erdwächters',
    {'Als Todesschwinge nach Tiefenheim geflohen ist, war seine Verderbtheit stark ausgeprägt, aber vielleicht noch nicht vollständig.|n|nDie Kultisten in Todesschwinges Sturz ernten sein übrig gebliebenes verderbtes Blut und formen es in lebende Wesen, um deren Energie aufzunehmen.|n|nWas, wenn eine kleine Spur der Essenz des Erdwächters geblieben ist? Schließlich war Neltharion der Aspekt der Erde, bevor er zum Aspekt des Todes wurde.|n|nSammelt Proben des lebenden Blutes, das die Kultisten erschaffen, und wir überprüfen, ob eine Spur des Erdwächters darin verblieben ist.', },
    {'Sammelt 5 Proben des Blutes von Neltharion vom lebenden Blut in Todesschwinges Sturz.', },
  },
  [26260] = {
    'Das Logbuch des Schmiedemeisters',
    {'Geht zu dem Turm, von dem der Sklave gesprochen hat. Ihr solltet ihn am nordöstlichen Ende des Lagers finden.|n|nWenn wir schnell genug handeln, können wir vielleicht das Treffen des Schmiedemeisters belauschen.', },
    {'Findet das Logbuch des Schmiedemeisters in Todesschwinges Sturz in Tiefenheim.', },
  },
  [26261] = {
    'Befragt die Sklaven',
    {'Laut den Befehlen, die Ihr gefunden habt, soll sich in einem Zelt am südöstlichen Ende von Todesschwinges Sturz ein Schlüssel befinden.|n|nBesorgt ihn Euch und befreit die Sklaven im Steinbruch im Süden.', },
    {'Besorgt Euch den Schlüssel des Zwielichtsklavenhändlers und befreit 6 versklavte Minenarbeiter.', },
  },
  [26262] = {
    'Zwielichtwaffen',
    nil,
    nil,
  },
  [26263] = {
    'Thornar Donnerknall',
    {'Wir haben versucht, den Kommandanten der eindringenden Wildhammerzwerge auszuschalten – bisher jedoch ohne Erfolg.|n|nThornar Donnerknall befindet sich in der Sicherheit seines Kommandopostens und man kann nur seine Stimme hören, die die Zwerge auf dem Schlachtfeld donnernd antreibt. Wir glauben, dass wir ihn zum Schweigen bringen müssen.|n|nErledigt Thornar und wir werden mit dem Rest seiner Truppen problemlos fertigwerden.', },
    {'Tötet Thornar Donnerknall.', },
  },
  [26264] = {
    'Die Zurückgelassenen',
    {'Die meisten von uns haben die kranken und irren Gnome gesehen, die unter den Folgen der Gifte und der Strahlung in Gnomeregan leiden. Ihr Niedergang ist erst vollendet, wenn aus ihnen hirnlose, aber größtenteils harmlose Pfützen aus toxischem Schlick werden.|n|nMeine Nachforschungen lassen darauf schließen, dass wir sie selbst in diesem Zustand noch retten können. Reist zum Toxischen Flugplatz im Süden, unterwerft den toxischen Schlick, von dem ich Euch erzählt habe, und bringt mir den Besitz der Gnome, die sie einst waren.', },
    {'Beschafft 6 zurückerlangte Besitztümer von toxischem Schlick auf dem Toxischen Flugplatz.', },
  },
  [26265] = {
    'Stoppt die Verseuchung',
    {'Tock Flinkspross hat eine verrückte Theorie. Er glaubt, bei den toxischen Schlickpfützen handele es sich um die Überreste von Gnomen, deshalb haben meine Männer Befehl, sie erst einmal nicht anzugreifen.|n|nAllerdings wimmelt es auf dem Toxischen Flugplatz südlich von hier von lebenden Verseuchungen. Dabei handelt es sich um Elementare, die aus verseuchtem Wasser und anderen toxischen Materialien bestehen. Wenn wir uns nicht um sie kümmern, werden sie die Stadt überrennen. Würdet Ihr uns helfen, sie loszuwerden?', },
    {'Zerstört 6 lebende Verseuchungen auf dem Toxischen Flugplatz.', },
  },
  [26266] = {
    'Hoffnung für das Volk',
    {'Vor ungefähr vier Jahren stolperte ein kleines Mädchen mitten in der Nacht in unser Farmhaus und brach zusammen. Niemand kannte sie. Das arme, kleine Ding hatte keine Erinnerung daran, wer sie sein könnte oder woher sie kam - wahrlich eine verirrte Seele.|n|nBald darauf adoptierten wir die Kleine und nannten sie Hope - denn für uns bedeutete sie Hoffnung.|n|nJetzt ist sie eine junge Dame und kümmert sich um die Obdach- und Mittellosen von Westfall. Bringt meinen Westfalleintopf zu ihr zur Späherkuppe südlich von hier.', },
    {'Bringt den Westfalleintopf zu Hope Saldean an der Späherkuppe.', },
  },
  [26267] = {
    'Den Lauerfels aufräumen',
    nil,
    nil,
  },
  [26268] = {
    'Lauerfelsvorräte',
    {'Ich war im Zweiten Krieg in Lauerfels stationiert. Ich war jung, noch Jahre davon entfernt, meine Partnerin kennenzulernen, und erinner mich noch gut an das Chaos, das ausbrach, als die Allianz uns angriff. Wir sind mit den Orcs geflohen und haben keine Zeit damit verschwendet, unsere Besitztümer zu packen.|n|nWir haben alles hinter uns gelassen. In Lauerfels sind noch immer viele unserer alten Vorräte. Wir könnten sie hier im Dorf gut gebrauchen... und vor allem sollten die Wildhammerzwerge sie nicht in ihre dreckigen Hände bekommen.', },
    {'Sammelt 5 schlammbedeckte Vorratskisten ein.', },
  },
  [26269] = {
    'Die Grünen Hügel des Schlingendorntals',
    {'Eine Seite! Ich brauche nur noch eine Seite!|n|nMit dem Schmöker von Meister Nesingwary gab es einen kleinen... Unfall <Barnil blickt vorwurfsvoll zu Klaps>... und wir haben ein paar der Seiten verloren.|n|nIch habe die anderen Abenteurer bereits um Hilfe gebeten und sie konnten auch ein paar der Seiten wiederfinden, aber eine Seite fehlt immer noch.|n|nIhr seid sicher furchtbar beschäftigt mit anderen Sachen, aber falls Ihr sowieso im Dschungel sein solltet, würde es Euch sicherlich nicht stören, ein wenig nach der Seite Ausschau zu halten?', },
    {'Findet Seite 14 von Die Grünen Hügel des Schlingendorntals.', },
  },
  [26270] = {
    'Unser Dank ist Euch gewiss',
    nil,
    nil,
  },
  [26271] = {
    'Die Hungrigen und die Hoffnungslosen speisen',
    {'Ja, ich habe von den Brauenwirbelmorden gehört. Es ist sehr tragisch, aber solche Tragödien sind in Westfall an der Tagesordnung. Hier gibt es viele Leute, die einfach nicht mehr die Mittel oder den Willen haben, sich selbst zu versorgen. Sie haben die Hoffnung aufgegeben. Könnt Ihr Euch vorstellen, wie es ist, so hoffnungslos zu sein, dass man sich seines Lebens nicht mehr erfreuen kann? Wir müssen uns gemeinsam darum bemühen, ihnen zu zeigen, dass es noch Hoffnung gibt. Dass jeder neue Tag ein besseres Leben bringt.|n|nNehmt den Westfalleintopf meiner Mutter und helft dabei, die Obdachlosen an der Späherkuppe zu versorgen.', },
    {'Benutzt den Westfalleintopf, um 20 Obdachlose an der Späherkuppe in Westfall zu speisen.', },
  },
  [26272] = {
    'Aufstieg der Dunkelspeere',
    {'Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.|n|nVol\'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.|n|nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.|n|nEs ist Zeit, mit Eurer Ausbildung zu beginnen, $N. Sprecht mit Voldreka im Osten.', },
    {'Trefft Voldreka auf dem Ausbildungsgelände der Dunkelspeere.', },
  },
  [26273] = {
    'Die Grundlagen: Dinge schlagen',
    {'Okay, Mann. Fangen wir klein an. Ich weiß, dass Ihr die Grundlagen der dunklen Künste beherrscht.|n|nGeht und macht diese Tikiziele fertig. Nehmt Euch Zeit. Bleibt ganz natürlich. Ich sehe zu, wie Ihr Eure Zauber formt. Dann sehen wir weiter.', },
    {'Zerstört 6 Tikiziele.', },
  },
  [26274] = {
    'Die Künste eines Hexenmeisters',
    nil,
    nil,
  },
  [26275] = {
    'Aller Anfang ist schwer',
    {'Woll\'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.|n|nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich\' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.|n|nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!', },
    {'Sammelt 6 Felle einer Wildmähnenkatze.', },
  },
  [26276] = {
    'Grube der Bewährung',
    {'Ihr habt Euch ganz schön gemausert, $C. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.|n|nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.', },
    {'Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.', },
  },
  [26277] = {
    'Mehr als erwartet',
    {'Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.|n|nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.', },
    {'Meldet Euch bei Vol\'jin in der Dunkelspeerfeste.', },
  },
  [26278] = {
    'Die Verteidigung von Grom\'gol: Raptorenrisiko',
    {'Throm\'ka, $C!|n|nEure Ankunft in Grom\'gol kommt zu einer guten Zeit. Unsere Aufgabe, einen sicheren Weg für die Vorräte für Steinard zu finden, wird von den Ortsansässigen verhindert.|n|nIch werde Euch damit beauftragen, die Raptoren nördlich von Grom\'gol für immer zu beseitigen. Macht Euch um die Raptoren selber keine Sorgen... diese jämmerlichen Jäger von Nesingwary werden sich um sie kümmern.|n|nIhr sollt die Eier der Raptoren zerstören.', },
    {'Zerstört 12 Schmetterschwanzeier.', },
  },
  [26279] = {
    'Die Verteidigung von Grom\'gol: Ogerunterdrückung',
    {'Als wir in diesem Dschungel ankamen, hatten wir nicht vor, die hier ansässigen Stämme zu bekämpfen. Unsere Mission, Steinard zu versorgen, hat höchste Priorität. Aber es gibt Komplikationen. Eine hier ansässige Gruppe von Ogern hat die Ruinen von Mizjah im Südosten von Grom\'gol besetzt. Trotz unserer Warnungen überfallen sie weiterhin unsere Nachschubkarawanen.|n|nIch beauftrage Euch hiermit, Euch mit diesen unkooperativen Ogern auseinander zu setzen.|n|nReist zu den Ruinen und versucht, sie aus diesem Gebiet zu vertreiben. Das sollte ihnen zumindest ein eindeutiges Zeichen setzen.', },
    {'Tötet 4 Schläger der Mosh\'Ogg und 4 Hexendoktoren der Mosh\'Ogg.', },
  },
  [26280] = {
    'Die Verteidigung von Grom\'gol: Murlocbedrohung',
    {'Die Murlocs der Düsterkiemen wurden von den Salzschuppen aus dem Ozean vertrieben und nun suchen sie in den Ruinen von Kal\'ai nordöstlich von hier Zuflucht. Früher war das kein Problem, aber inzwischen ist es nicht länger tragbar.|n|nWeit entfernt von dem Ozean, ihrer Heimat, wurden die Düsterkiemen unruhig und schicken Futterwühler aus, um die Versorgungskarawanen zu überfallen. Vermittelt ihnen folgende Nachricht: solches Verhalten wird von Höllschreis Horde NICHT geduldet.', },
    {'Tötet 15 Murlocs der Düsterkiemen.', },
  },
  [26281] = {
    'Die Verteidigung von Grom\'gol: Trolldiebstähle',
    {'Die Trolle lassen uns eigentlich in Ruhe hier in Grom\'gol. Die meisten Trolle wissen genau, dass die Horde sie leicht zerschmettern kann, wenn es sein muss, und auch die Trolle hier im Schlingendorntal sind sich dessen bewusst.|n|nDie Blutskalpe wurden in der letzten Zeit aber immer aktiver. Erst letzte Woche haben sie einen Trupp nach Grom\'gol geschickt und mehrere Rationen gestohlen.|n|nDem Stehlen von Nahrung kann von jeder Art des Diebstahls noch am ehesten vergeben werden, aber ich kann trotzdem nicht zulassen, dass es vorkommt während ich das Sagen habe. Begebt Euch nach Norden zu den Ruinen von Bal\'lal und holt unser Eigentum zurück.', },
    {'Holt die Rationen aus Grom\'gol aus den Ruinen von Bal\'lal.', },
  },
  [26282] = {
    'Die Gunst Akil\'darahs',
    nil,
    nil,
  },
  [26283] = {
    'Erstklassiger Schleim',
    {'Die Schleime, die in Lauerfels zu finden sind, interessieren mich mehr und mehr. Sie kommen immer wieder, egal, wie oft man sie entfernt, aber sie scheinen sich von einem einzigen Schleim selber nicht vermehren zu können.|n|nIch glaube, das in Lauerfels etwas wächst. Eine Quelle, aus der der Schleim kommt. Ich möchte sie untersuchen - findet diese Quelle und bringt mir eine Probe.', },
    {'Beschafft eine Terrorklumpenprobe vom Terrorklumpen.', },
  },
  [26284] = {
    'Vermisst',
    nil,
    nil,
  },
  [26285] = {
    'Bringt meinen Sprengstoff zurück!',
    {'Wir werden jede Menge Pulver brauchen, um die Höhlen zum Einsturz zu bringen. Keine Ahnung, ob die verdammten Troggs das wussten, als sie meine Vorräte stahlen und meine Demolierer entführten! Das Ergebnis ist dasselbe.|n|nKann nichts in die Luft jagen, wenn ich kein Pulver habe.|n|nGeht nach Süden zur Höhle der Frostmähnen und tötet alle Troggs, die Ihr seht. Jeder von ihnen könnte meine Pulverfässer dabei haben.', },
    {'Beschafft 7 gestohlene Pulverfässer von Knochenpflückern der Felsenkiefertroggs oder von Marodeuren der Felsenkiefertroggs bei der Höhle der Frostmähnen.', },
  },
  [26286] = {
    'Die Verteidigung Westfalls',
    {'Nachdem meine Dienstzeit in den Grizzlyhügeln beendet war, bin ich nach Westfall zurückgekehrt und musste das Land in einem schlimmeren Zustand als vor meinem Einsatz vorfinden.|n|nWir haben den Krieg mit tausenden von obdachlosen Bürgern bezahlt. Jetzt wandern sie hierhin aus und lassen sich auf den verlassenen Bauernhöfen und Siedlungen dieser Gegend nieder.|n|nZu allem Überfluss werden wir jetzt auch noch von den Gnollen angegriffen. Die Westfallbrigade braucht Eure Hilfe, $N. Tötet die angreifenden Gnolle und nehmt ihnen ihre Befehle ab. Da zieht jemand im Hintergrund die Fäden und wir müssen herausfinden, wer das ist!', },
    {'Erhaltet die Angriffsbefehle der Gnolle.', },
  },
  [26287] = {
    'Die Westfallbrigade',
    nil,
    {'Tötet 12 beliebige Gnolle der Flusspfoten, die die Späherkuppe angreifen.', },
  },
  [26288] = {
    'Jango Fleckfell',
    {'Südlich von hier befindet sich ein Landstrich von Westfall, den wir Staubebenen nennen. Soweit wir wissen, haben die Gnolle der Region die Staubebenen zu ihrem inoffiziellen Hauptquartier erklärt. Wie bei jedem Hauptquartier gibt es auch bei diesem einen Anführer. Wenn wir diesen Angriffen einen Riegel vorschieben wollen, dann müssen wir den Gnoll ausfindig machen, der den Ton angibt, und ihm das Handwerk legen.|n|nBegebt Euch zu den Staubebenen, findet den Anführer der Gnolle, Jango Fleckfell, und tötet ihn. Erledigt auch sämtliche Gnolle, die sich Euch in den Weg stellen.', },
    {'Tötet 5 Mystiker der Flusspfoten, 5 Zuchtmeister der Flusspfoten und Jango Fleckfell.', },
  },
  [26289] = {
    'Findet Agentin Kearnen',
    {'Der SI:7 hat die Bewegungen von Helix Ritzelbrecher genau beobachtet, seit er vor zwei Wochen seinen Fuß auf Allianzboden gesetzt hat. Der Brief, den ich von Mathias Shaw erhalten habe, erklärt, dass er eine Agentin namens Kearnen nach Westfall entsandt hat, um Helix zu beschatten. Findet Agentin Kearnen, dann werdet Ihr auch Helix Ritzelbrecher finden.|n|nKearnen war vor zwei Tagen in der Stadt, um Vorräte zu besorgen. Sie hat erwähnt, dass sie in der Nähe von Jagdrufs Turm südöstlich von hier in den Staubebenen zu finden sein würde.|n|nAbmarsch, $N.', },
    {'Findet Agentin Kearnen.', },
  },
  [26290] = {
    'Geheimnisse des Turms',
    {'Helix hat sich oben im alten Turm von Klaven Jagdruf verschanzt. Ich werde Euch nicht belügen, $N, er wird schwer bewacht. Ich habe allein im Freien sechs bewaffnete Söldner gezählt. Ihr schafft es nie allein in den Turm. Zu Eurem Glück sind Claire und ich hier.|n|n<Kearnen tätschelt ihr Heckenschützengewehr.>|n|nIch gebe Euch Deckungsfeuer.|n|nNehmt diesen Verschleierungstrank; Ihr werdet ihn brauchen, wenn Ihr es ins Innere geschafft habt. Trinkt ihn, sobald Ihr den Turm betretet und steigt dann den Turm hinauf. Findet heraus, was Helix dort oben versteckt!', },
    {'Betretet Jagdrufs Turm und macht Helix Ritzelbrecher ausfindig.', },
  },
  [26291] = {
    'Viel Ärger in Mondbruch',
    {'Ich werde bald meinen Bericht schreiben und nach Sturmwind zurückkehren. Der SI:7 muss über die Situation in Westfall informiert werden. Ich schlage vor, Ihr tut das gleiche und erstattet Gryan Bericht.', },
    {'Berichtet Marschall Gryan Starkmantel an der Späherkuppe in Westfall, was Ihr herausgefunden habt.', },
  },
  [26292] = {
    'Auf nach Mondbruch!',
    {'Wir haben schon eine ganze Weile ein Lager in der Nähe von Mondbruch, $N. Einer meiner besten Soldaten ist zusammen mit einer Kompanie von der Späherkuppe in diesem Gebiet stationiert. Meldet Euch umgehend bei Hauptmann Alpert und findet heraus, ob er irgendwelche Neuigkeiten über die Vorgänge in Mondbruch hat.|n|nEin weiterer Verbündeter von mir ist auch in dem Mondbrucher Lager. Sein Name ist Thoralius. Ich habe Thoralius in Nordend während meiner Dienstzeit in Valgarde kennengelernt. Er ist ein weiser und mächtiger Schamane. Vielleicht können uns seine Fähigkeiten dabei helfen, diesen Fall zu lösen.', },
    {'Meldet Euch bei Hauptmann Alpert in Mondbruch in Westfall.', },
  },
  [26293] = {
    'Kriegsmaschinen',
    nil,
    {'Sprecht mit Großknecht Glibbs am Hinteren Tor von Orgrimmar in Orgrimmar.', },
  },
  [26294] = {
    'Massenversagenswaffen',
    nil,
    {'Untersucht Höllschreis Verwüster, bis Ihr einen fehlerhaften Verwüster findet, und erteilt dem Chefingenieur dann eine Lektion.', },
  },
  [26295] = {
    nil,
    {'Uns ist ein Anstieg der Gewalttaten unter den Obdachlosen in dieser Gegend aufgefallen. Irgendetwas oder irgendjemand versetzt sie ganz schön in Aufruhr. Wer auch immer dahinter steckt, organisiert sich immer besser. Erst vor Kurzem ist eine Gruppe Schläger hier durchgekommen und hat Flugblätter verteilt.|n|nGeht nach Mondbruch und sucht nach Beweisen. Propaganda, Handzettel, egal was... Bringt mir alles, was Ihr finden könnt. Vielleicht können wir ja den Ursprung der Schriften finden.', },
    {'Erhaltet ein Informationsflugblatt, ein geheimes Tagebuch, eine Ausgabe des Mondbrucher Blatts und mysteriöse Propaganda.', },
  },
  [26296] = {
    'Beweissammlung',
    {'Dieses Kopftuch besteht aus dem gleichen Stoff, der auch am Tatort des Brauenwirbelmordes gefunden wurde. Ihr solltet noch mehr rote Kopftücher als Beweis sammeln und Euren Fund zu Hauptmann Alpert bringen.', },
    {'Sammelt 6 rote Kopftücher.', },
  },
  [26297] = {
    'Der Anbruch eines neuen Tages',
    {'Sieht so aus, als fängt die Versammlung, von der die merkwürdige Gestalt sprach, bald an. Die Obdachlosen setzen sich in Bewegung. Ich möchte, dass Ihr an der Kundgebung teilnehmt und Informationen sammelt, $N.|n|nBegebt Euch zur Stadtmitte Mondbruchs und hört Euch die Ansprache an. Kehrt zu mir zurück und berichtet, was Ihr herausfinden konntet.', },
    {'Sammelt Informationen bei der Versammlung von Mondbruch.', },
  },
  [26298] = {
    'Die Suche nach Yenniku',
    {'Unheil droht. Unheil für den jüngsten Sohn meines Häuptlings, Yenniku. Der Sitte unseres Volkes nach wurde er den Gurubashitrollen von Zul\'Gurub gegeben, aber nachdem mein Stamm, der Dunkelspeerstamm, mit dem Orc Thrall gegangen ist, war der arme Yenniku für uns verloren. Ich wurde aus dem fernen Orgrimmar zurück ins Schlingendorntal geschickt, um nach dem Sohn meines Häuptlings zu suchen.|n|nUnd ich glaube, dass der Blutskalpstamm ihn hat.|n|nWenn Ihr mir helfen wollt, dann jagt die Blutskalpe. Ihr könnt sie im Norden finden. Sammelt ihre Hauer und kehrt zu mir zurück.', },
    {'Beschafft 6 Hauer der Blutskalpe von Blutskalptrollen in den Ruinen von Bal\'lal.', },
  },
  [26299] = {
    'Kopfjägerei',
    {'Wir müssen herausfinden, ob Yenniku tot ist.|n|nErschlagt die Kopfjäger der Blutskalpe und nehmt ihnen ihre Schrumpfköpfe ab. Ihr müsst viele, viele Köpfe sammeln und ich werde sie überprüfen, um sicherzugehen, dass Yennikus Kopf nicht dabei ist.|n|nSollte Yenniku von den Blutskalpen getötet worden sein, möge ein Fluch für 600 Jahre auf den Geist ihres Häuptlings, Gan\'zulah, kommen!|n|nGeht, $N. Ihr könnt die Köpfe bei den Ruinen von Zuuldaia an der Küste im Norden finden.', },
    {'Beschafft 25 Schrumpfköpfe von Blutskalptrollen in den Ruinen von Zuuldaia.', },
  },
  [26300] = {
    'Nezzliok wird es wissen',
    {'Yennikus Kopf war nicht dabei und ich danke der großen Schlange dafür. Wir sind aber noch keinen Schritt weiter, ihn zu finden.|n|nWir müssen die Wahrheit erfahren und ich fürchte, nur der Hexendoktor der Blutskalpe wird uns helfen können. Als Feind der Dunkelspeere wird er nicht offen sprechen wollen und daher müssen wir die Wahrheit aus seinen toten Lippen zwingen!|n|nBringt mir den Kopf von Nezzliok dem Düsteren und platziert ihn hier im Kessel.|n|nIhr werdet ihn tief in Zul\'Kunda finden. Bringt mir seinen Kopf... wir werden ihn schon zum Sprechen bringen.', },
    {'Erhaltet Nezzlioks Kopf von Nezzliok dem Düsteren in Zul\'Kunda.', },
  },
  [26301] = {
    'Mit Nezzliok sprechen',
    {'<Der Kopf von Nezzliok spricht.>|n|nEs stimmt. Ich weiß, wo das Kind der Dunkelspeere hingebracht wurde. Ihr habt mich besiegt und meinen Geist gebunden, aber ohne Gegenleistung sage ich nichts!|n|nDie Blutskalpe streiten mit den Schädelspaltern. Um mein Wohlwollen zu erhalten, stehlt zwei der meist geschätzten Trophäenschädel von den Schädelspaltern östlich des Flusses. Legt sie hierher zu uns, sodass mein Geist im Nether Sklaven zur Verfügung hat. Ein Schädel muss aus ihrem Trophäenstapel in Balia\'mah und der zweite von Ziata\'jai stammen.', },
    {'Erhaltet eine Trophäe von Balia\'mah und eine Trophäe von Ziata\'jai aus den Ruinen der Schädelspalter im Nördlichen Schlingendorntal.', },
  },
  [26302] = {
    'Yennikus Schicksal hinterher',
    {'<Nezzliok spricht.>|n|nIhr habt mich und meinen Meister beschwichtigt und ich werde Euch die Informationen geben, nach denen es Euch verlangt...|n|nDer junge Yenniku ist verloren.|n|nEr wurde von Hexendoktor Zanzil dem Ausgestoßenen entführt. Jetzt sind sein Geist und sein Körper in Zanzils Kontrolle und nur die stärkste aller Magien kann ihn davon befreien.|n|nMagie, die Euch nicht zur Verfügung steht, $C.|n|nVielleicht können Eure Verbündeten der Dunkelspeere in Bambala östlich von einen Hoffnungsschimmer zur Erlösung Yennikus darstellen. Aber das bezweifle ich.', },
    {'Sprecht mit Kin\'weelay in Bambala.', },
  },
  [26303] = {
    'Das Gedankenauge',
    {'Das Gedankenauge befindet sich bei einem Ogermagier, im Ogerhügel der Mosh\'Ogg südlich von hier. Sein Name ist Mai\'Zoth. Ich kenne ihn noch von der Zeit, als sich die Dunkelspeere im Schlingendorntal aufhielten - er ist bösartig und seine Magie ist stark.|n|nUnd wenn er im Besitz des Gedankenauges ist, dann ist seine Magie noch stärker.|n|nIhr müsst gegen Mai\'Zoth antreten und ihm das Gedankenauge abnehmen. Es ist eine gefährliche Aufgabe, aber es ist die einzige Hoffnung, die wir haben, Yenniku zu retten.', },
    {'Nehmt Mai\'Zoth das Gedankenauge ab.', },
  },
  [26304] = {
    'Wenn es Nacht wird im Dschungel',
    {'Vor einem Jahr wurde meine Mutter - die Trollfrau, die mich großzog - von den Schädelspaltern Zul\'Mamwes gefangen genommen. Jung und eigen wie ich war machte ich mich auf, um sie zu retten, nur um zu sehen, wie sie von einem Dutzend Krieger auf eine riesige brennende Kohlenpfanne zugestoßen wurde. Ich versteckte mich hinter einem Baum und sah zu, wie sie sie packten und.. und..|n|n<Kil\'karil senkt seinen Blick.>|n|nWenn es Nacht wird wird das Licht der Kohlenpfannen von den Bäumen reflektiert und hält mich wach. Bitte, $N... reist nach Süden nach Zul\'Mamwe und löscht die Kohlenpfannen.', },
    {'Löscht 8 Kohlenpfannen von Zul\'Mamwe in Zul\'Mamwe im Nördlichen Schlingendorntal.', },
  },
  [26305] = {
    'Yennikus Rettung',
    {'Ich habe das Gedankenauge in einen Seelenedelstein umgeformt. Somit hat er zweierlei Zwecke: Erst verwendet Ihr ihn, um Yenniku zu betäuben, und sobald er betäubt ist, legt Ihr den Seelenedelstein auf seinen Kopf, um seine Seele einzufangen.|n|nMeine anfänglichen Vermutungen waren korrekt: die Geister sagen mir, dass Yenniku nicht bei Zanzil dem Ausgestoßenen ist, sondern in den Ruinen von Zul\'Mamwe im Südwesten. Kehrt zu Nimboya in Grom\'gol zurück, sobald Ihr Yennikus Seele befreit habt.', },
    {'Bringt den gefüllten Seelenedelstein zu Nimboya.', },
  },
  [26306] = {
    'Anfang der Zurückeroberung',
    {'Heute fangen wir mit dem ersten Angriff auf das Herz des wilden Blutfratzenstamms an. Zeigt ihnen keine Gnade, $N. Hier geht es um mehr als Rivalität unter Trollen. Jeder Sieg der Bruchhauer ist ein Sieg für die Horde!|n|nDie Kopfjäger der Blutfratzen und Hexendoktoren müssen zuerst beseitigt werden. Greift die unteren Terrassen an und erstattet mit Blut an Eurer Waffe Bericht bei mir.', },
    {'Tötet 5 Hexendoktoren der Blutfratzen und 5 Kopfjäger der Blutfratzen in Jintha\'Alor.', },
  },
  [26307] = {
    'Tod den Blutfratzen',
    {'Wir werden ihnen nicht erst die Gelegenheit geben, auf unseren Angriff zu reagieren. Ihr müsst zurück nach Jintha\'Alor und Euch den Weg zu den höheren Ebenen freikämpfen.|n|nDie Berserker und Schattenzauberer der Blutfratzen sind gefährliche Gegner, $N. Wenn die anderen sehen, wie ihre Leichen über die Mauern geworfen werden, so werden sie wissen, WIE ernst wir es meinen.|n|nIch möchte kein Blutfratzenherz mehr schlagen hören!', },
    {'Tötet 5 Berserker der Blutfratzen und 5 Schattenzauberer der Blutfratzen in Jintha\'Alor.', },
  },
  [26308] = {
    'Das gehört jetzt uns',
    {'Nur die stärksten und bösartigsten Blutfratzen sind übrig geblieben. Die Seelenfresser und Bluttrinker, die verkommenen Anhänger des bösen Gottes Hakkar.|n|nSie sind NARREN! Sie halten an altem, falschem Glauben fest. Ich werde ihre Verbrechen gegenüber den Bruchhauern nicht länger dulden.|n|nMacht Euch zum finalen Angriff auf. Nehmt Jintha\'Alor für die Bruchhauer ein... nehmt es für die Horde ein!', },
    {'Tötet 5 Bluttrinker der Blutfratzen und 5 Seelenfresser der Blutfratzen in Jintha\'Alor.', },
  },
  [26309] = {
    'Dunkle Gefäße',
    {'Die Trolle der Blutfratzen hier haben früher das verdorbene Blut des Gottes Hakkars getrunken, um Macht zu erlangen. Sie haben es, bevor sie es tranken, in primitiven Kesseln gekocht - dunkle Gefäße voller unheiliger Stärke.|n|nHakkar wurde natürlich vor langer Zeit schon getötet. Doch das Interessante ist... Ich sehe immer noch Kessel, die hier oben blubbern. Bringt mir einige her und dann sehen wir, was sie so zusammenbrauen.', },
    {'Besorgt 5 Gefäße mit besudeltem Blut aus Jintha\'Alor.', },
  },
  [26310] = {
    'Alles, was krabbelt',
    {'Bevor Ihr dort hoch geht, $C...|n|nIch kenne ein paar Verkäufer, die sehr interessiert an starken Giften sind. Mir sind die Spinnen in der Gegend natürlich nicht entgangen... sie sind nicht riesig, aber ungefähr so groß wie Euer Hand.|n|nSie haben eine Färbung, die ich noch nie zuvor in der Gegend gesehen habe. Könntet Ihr ein paar sammeln und mir bringen?', },
    {'Sammelt 8 huschende Spinnlinge in Jintha\'Alor.', },
  },
  [26311] = {
    'Unbekannte Gewässer',
    {'Der Kriegshäuptling plant einen großangelegten Angriff auf das Schattenhochland. Wir hoffen, dass wir uns dort mit den Orcs des Drachenmals verbünden können.|n|nMeine Quellen haben mir berichtet, dass ein Orc des Drachenmalklans hier in Orgrimmar lebt. Er ist als Herezegor Flammenhauer bekannt und führte einst ihre Krieger an.|n|nSein Wissen als einer von ihnen ist für uns von größtem Wert. Findet Flammenhauer und besorgt uns eine Karte der Wasserwege im Schattenhochland.|n|nLaut meinen letzten Informationen hielt er sich in einer Kneipe im Tal der Ehre auf...', },
    {'Findet Herezegor Flammenhauer in der Kneipe "Zum Wyvernschweif" im Tal der Ehre in Orgrimmar und besorgt Euch eine Küstenkarte des Schattenhochlands.', },
  },
  [26312] = {
    'Bröckelnde Verteidigung',
    {'Als der Angriff begann, sind wir nach vorne geprescht, um das Feld so schnell wie möglich einzunehmen. Ihre Streitkräfte waren schier unerschöpflich... wir haben sie unterschätzt. Nun sitzen einige unserer besten Schamanen da draußen fest, gestrandet, erschöpft und weit entfernt von unserer Verteidigung.|n|nBegebt Euch auf das Feld und entlastet unsere gestrandeten Brüder. Selbst eine kleine Pause vom Kampf sollte ihnen die Gelegenheit geben, endlich einmal durchzuatmen.|n|nBeeilt Euch, $C.', },
    {'Entlastet Tawn Winterfels, Sturmruferin Mylra und Hargoth Trübflamm, indem Ihr ihnen helft, ihre Gegner zu besiegen.', },
  },
  [26313] = {
    'Der Kern unserer Sorgen',
    {'Elementare sind von Natur aus chaotisch, doch diese organisierte Aggressivität passt einfach nicht zu ihnen. Besonders hier unten, wo ihr Tod ein bisschen dauerhafter ist. Ich vermute, die Steinmutter Therazane steckt dahinter, aber ich muss Gewissheit haben.|n|nVernichtet die Zornsteinrumpler und bringt mir ihre Kerne. Wenn wir es mit dem Hass der Steinmutter zu tun haben, werden wir die Sache hier und jetzt erledigen.', },
    {'Sammelt 6 Zornsteinkerne.', },
  },
  [26314] = {
    'Fest auf dem Boden',
    {'Wir können von Glück sagen, dass diese Riesen so schlecht zielen. Doch irgendwann wird das Glück auf ihrer Seite sein.|n|nWir müssen sie aus dem Kampfgeschehen nehmen, aber ihnen direkt gegenüberzutreten ist wohl keine gute Idee.|n|nNehmt dieses Wurfleine, werft sie ihnen um einen Knöchel und zieht ihnen die Füße weg. Sobald sie am Boden liegen, sollten sie leicht zu besiegen sein.', },
    {'Benutzt die Elementiumwurfleine, um 3 Diener von Therazane von den Füßen zu holen.', },
  },
  [26315] = {
    'Ein imposantes Aufeinandertreffen',
    {'Habt Ihr den Riesen gesehen, der bedrohlich im Nordosten aufragt? Das ist Boden der Imposante, einer der Steinlords von Therazane der Steinmutter.|n|nWir wissen nicht viel über die Steinlords, aber Boden zählt nicht gerade zu den Sanftmütigen seiner Art. Leider führt ausgerechnet er den Angriff an, also müssen wir ihm gegenübertreten.|n|nBringt diese Proklamation zu ihm und lest sie im Namen des Irdenen Rings laut vor. Ich weiß, es ist ganz schön optimistisch zu hoffen, dass Worte dies beilegen können, aber wir müssen es versuchen. Seid vorsichtig.', },
    {'Lest Boden dem Imposanten die Proklamation des Irdenen Rings vor.', },
  },
  [26316] = {
    'Worauf wartet Jessup?',
    {'Der Kataklysmus öffnete tiefe Spalten unter der Höhle der Frostmähnen. Troggs stürmten daraufhin aus ihren Bauten. Es gelang ihnen, die Trolle, die dort lebten, zu verjagen und das gleiche Schicksal blüht uns auch, wenn wir nicht handeln.|n|nHochtüftler Mekkadrill hat den bekannten Demolierer Jessup McCree angeheuert, um die Spalten zu versiegeln und den Ansturm der Troggs zu beenden. Er hat uns noch nicht mitgeteilt, ob es ihm gelungen ist, die Troggs aufzuhalten. Würdet Ihr in seinem Lager nahe der Höhle der Frostmähnen, südlich des Toxischen Flugplatzes nach ihm suchen?', },
    {'Findet Jessup McCree in seinem Lager nahe der Höhle der Frostmähnen.', },
  },
  [26317] = {
    'Ein Schmetterschwanzjunges',
    {'Als Ihr das letzte der Schmetterschwanzeier zerstört habt, seht Ihr, wie ein neugeborenes Schmetterschwanzjunges Euch anschaut. Ihr seht, wie es Euch genau betrachtet, Eure Gesichtszüge untersucht und alle Eure Bewegungen aufmerksam verfolgt.|n|nDas Schmetterschwanzjunge hat Euch in sein Herz geschlossen.|n|nEigentlich solltet Ihr die Bevölkerung der Raptoren ausmerzen, aber Ihr habt alle Eier zerstört, die von Euch zerstört werden sollten, und dieser Raptor ist ein unschuldiges Jungtier. Vielleicht weiß jemand im Basislager Grom\'gol, was man mit einem Raptorenjungen anfangen kann.', },
    nil,
  },
  [26318] = {
    'Eine unvollendete Aufgabe',
    {'Mein Team hat die Pulverfässer und den Zünder bereits am Ende der Höhle im westlichen Teil der Höhle der Frostmähnen angebracht. Ihr müsst nur dorthin vordringen und den Zünder aktivieren, dann explodiert das Pulver und die Tunnel brechen ein.|n|nDann werden die Troggs die Tiefen der Erde nicht mehr verlassen. Mekkadrill wird mit den restlichen Troggs leichter fertigwerden, wenn Ihr ihren Anführer, der sich selbst Boss Bruggor nennt, ausschaltet. Viel Glück, $N.', },
    {'Dringt zum Ende der Höhle in der Höhle der Frostmähnen vor, tötet Boss Bruggor und aktiviert den Zünder, um die Troggtunnel zum Einsturz zu bringen.', },
  },
  [26319] = {
    'Gelöste Geheimnisse',
    {'Es gibt hier einen Schamanen, Thoralius, der uns vielleicht helfen kann. Er ist ein Freund von Gryan und ist vor Kurzem nach Westfall gekommen, um die elementare Verwüstung zu untersuchen, die über uns hereingebrochen ist.|n|nSprecht mit Thoralius und seht, ob er etwas Licht auf die Identität dieser merkwürdigen Gestalt werfen kann.', },
    {'Sprecht mit Thoralius dem Weisen in Mondbruch in Westfall.', },
  },
  [26320] = {
    'Eine Vision aus der Vergangenheit',
    {'Dieser Weihrauch wird Euren Körper und Euren Geist in tiefe Meditation versetzen. Sobald die Trance beginnt, werdet Ihr in die Geisterwelt übertreten. Wehrt Euch nicht gegen die Trance, sobald sie begonnen hat, $N. Erlaubt den Geistern, Euch zu zeigen, was sie wissen.|n|nIhr müsst nun aufbrechen. Begebt Euch zu den Todesminen, ein Ort, der angeblich eine große Rolle in der Geschichte Westfalls gespielt hat. Sobald Ihr im Inneren seid, benutzt den Weihrauch.|n|nIhr gelangt durch das alte Bauernhaus südlich von hier in die Todesminen. Folgt den Obdachlosen.|n|nKehrt zu Gryan zurück und berichtet ihm von dem, was Ihr erfahren habt.', },
    {'Betretet das Versteck der Defias und folgt der Spur der Obdachlosen in die Todesminen. Betretet den Dungeon "Die Todesminen" und benutzt das Räuchergefäß, um in die Vergangenheit zu blicken.', },
  },
  [26321] = {
    'Ich glaube, sie hat Hunger',
    {'Ich glaube, Euer Raptorenjunges ist hungrig. Wenn Ihr sie behalten wollt, solltet Ihr Essen für sie finden, nicht wahr? Schmetterschwänze greifen oft das Lager der Düsterkiemen nördlich von hier an.|n|nSie ist wahrscheinlich noch nicht stark genug, um selbst zu jagen, aber frisches Murlocfleisch kann sie sicher schon essen.', },
    {'Tötet Murlocs der Düsterkiemen im Nördlichen Schlingendorntal und gebt Eurem Schmetterschwanz 40 Bissen Murlocfleisch.', },
  },
  [26322] = {
    'Aufstieg der Bruderschaft',
    {'Ich hatte ja keine Ahnung, dass van Cleef eine Tochter hatte, $N. Wenn es etwas gab, in dem der Mann außerordentlich gut war, dann war es, Geheimnisse zu bewahren.|n|nWie tragisch. Das arme Ding hat eine schreckliche Tat mit angesehen. Hätte ich doch nur etwas geahnt.|n|nWas war das? Habt Ihr etwas gehört? Scheint so, als ziehen sich die Gnolle zurück... wo sind meine Wachen?|n|nPASST AUF, $N!', },
    {'Werdet Zeuge des Aufstiegs der Bruderschaft.', },
  },
  [26323] = {
    'Lieblingsschädel',
    {'Euer Raptor scheint ein neues Spielzeug gefunden zu haben: einen Schädel aus einem Haufen von Trollschädeln.|n|nIhr wisst nicht, warum sie diesen Schädel allen anderen bevorzugt, aber aus irgendeinem Grund lässt sie nicht von ihm ab.|n|nNimboya im Basislager Grom\'gol ist eine Art Schädelexperte, wenn man von dem Schädelhaufen ausgeht, den er hat. Vielleicht weiß er, was an diesem Schädel so besonders ist.', },
    nil,
  },
  [26324] = {
    'Wo ist meine Kriegsflotte?',
    nil,
    {'Sprecht mit Kriegsfürst Krogg am Bilgepier in Azshara.', },
  },
  [26325] = {
    'Ein Gespür für solche Dinge',
    {'<Der Schädel spricht zu Euch.>|n|nIch lebe? Nein, ich lebe nicht... aber ich kann leben.|n|nEuer Raptor ist sehr schlau, wenn er meinen Schädel in einem Haufen so vieler Schädel gefunden hat. Zu Lebzeiten war ich ein starker, mächtiger Troll, ein Fürst unter den Trollen. Mit Eurer Hilfe kann ich wieder ein Fürst sein.|n|nDie Blutskalpe in Zuuldaia haben magische Fetische, die mir zur Rückkehr verhelfen können. Sie verstecken die Artefakte unter dem Sand. Euer Schmetterschwanzjunges wird diese Artefakte finden können, $N... wenn Ihr sie habt, werft sie in den Kessel.', },
    {'Lasst Euer Schmetterschwanzjunges 8 Fetische von Zuuldaia aufspüren.', },
  },
  [26326] = {
    'Die Erde unter unseren Füßen',
    {'Nur noch ein Teil der Weltensäule fehlt, und der befindet sich in den Händen der Steinmutter selbst. Schlimmer noch, der Tempel wird von Elementaren und Riesen belagert. Selbst einem Narr dürfte klar sein, dass sie auf ihren Befehl hin handeln.|n|nGeht und stellt Euch den Elementaren im Nordwesten im Kampf. Beratet Euch mit Torunskar und Norsala und findet einen Weg, um mit ihren Anführern zu sprechen und die Weltensäule zu finden. Wir ziehen eine friedliche Beilegung vor, aber wir werden alles tun, was nötig ist, um den Riss zu schließen.', },
    {'Sucht nach Erdenrufer Torunskar direkt nordwestlich des Tempels der Erde in der Zackenwüste.', },
  },
  [26327] = {
    'Ambossar der Held',
    {'Ihr verschwendet nur Eure Zeit, wenn Ihr jetzt mit mir reden wollt, $GJunge:Mädchen;. Thargas Ambossar hält sich auf der anderen Seite dieser Wagen auf.|n|nIhr habt von ihm gehört, oder? Er hat an der Seite des Königs von Sturmwind den Thandolübergang gegen die Dunkeleisenzwerge verteidigt! Er ist einer der größten Helden von Eisenschmiede.|n|nAber jetzt steckt er bis zum Hals in Ärger! Geht zu ihm und lasst ihn wissen, dass Ihr helfen wollt. Aber haltet Abstand; er holt weit aus.', },
    {'Redet mit Thargas Ambossar.', },
  },
  [26328] = {
    'Steinige Beziehungen',
    {'<Norsala legt die Hand auf den Boden, um Diamants Aufenthaltsort herauszufinden, springt jedoch sofort schockiert zurück.>|n|nMeine Güte! Das habe ich nicht erwartet. Diamant ist gar nicht weit entfernt. Als ich eine Verbindung zu ihm aufbaute, hat er geantwortet und mir gesagt, wo wir ihn finden können. Geht zum nordöstlichen Rand der Zackenwüste. Diamant erwartet Euch.|n|n$N, seid vorsichtig. Es sieht Erdgeschöpfen zwar nicht ähnlich, einen Hinterhalt zu planen, aber es sah ihnen auch nicht ähnlich, den Tempel überhaupt zu belagern.', },
    {'Findet Diamant den Geduldigen am nordöstlichen Rand der Zackenwüste.', },
  },
  [26329] = {
    'Und noch etwas',
    {'So, dann werde ich meine Sachen packen und mich der nächsten Aufgabe widmen. Irgendwo gibt es immer etwas zu sprengen. Irgendwo gibt es einen Berg, der bewegt werden muss oder eine Schlucht, die gegraben werden muss. Dafür bin ich da.|n|nWürdet Ihr mir vielleicht noch einen Gefallen erweisen? Würdet Ihr diesen Bericht zu Hochtüftler Mekkadrill in Neu-Tüftlerstadt bringen? Er sollte wissen, dass die Troggs seinem Volk in nächster Zeit keine Probleme mehr machen werden.', },
    {'Bringt Jessups Bericht zu Hochtüftler Mekkadrill in Neu-Tüftlerstadt.', },
  },
  [26330] = {
    'Wer ist ein großer Troll?',
    {'<Der Schädel spricht erneut.>|n|nMeine Seele ist bereit, doch mein Körper ist es nicht. Die Blutskalpe haben meinen alten Körper vor langer Zeit entweiht. Die Schrecken, die sie mir zugefügt haben... mein Geist sah dabei zu, als sie meinen Körper in Stücke rissen und... und... ich kann es nicht erzählen.|n|nIhr Häuptling, Gan\'zulah, leitete diese grauenvollen Taten. Wenn ich mich recht erinnere, so war er ein starker, mächtiger Troll... ungefähr so groß wie ich. Was für ein interessanter Zufall.|n|nIhr wisst, was Ihr zu tun habt, $N. Beeilt Euch.', },
    {'Holt Gan\'zulahs Leiche aus Zul\'Kunda.', },
  },
  [26331] = {
    'Ritzelstoß\' Handlanger',
    {'Unser alter Feind Thermadraht versucht uns mit allen Mitteln vom Wiederaufbau und der Rückeroberung Gnomeregans abzuhalten. Er hat einen seiner loyalsten Schergen, Razlo Ritzelstoß und einen Trupp bestrahlter Gnome ausgesandt, um uns zu terrorisieren.|n|nSie haben sich in einem alten Arsenal auf der Straße nach Norden verschanzt. Ritzelstoß\' Techniker reparieren die Waffen dort. Wir müssen sie aufhalten, bevor die Mechanopanzer einsatzbereit sind. Geht zu Ritzelstoß\' Arsenal und eliminiert alle Techniker, die Ihr findet.', },
    {'Tötet 8 von Ritzelstoß\' Handlangern in Ritzelstoß\' Arsenal. Ihr könnt wahlweise bestrahlte Techniker oder Ritzelstoß\' Kampfanzüge töten.', },
  },
  [26332] = {
    'Mojo der Schädelspalter',
    {'<Der Schädel spricht wieder.>|n|nDank Euch und Eurem Raptor habe ich meinen Körper. Wenn ich mich recht erinnere, so braucht Ihr und Euer Freund, der Hexendoktor, Mojo, um das Ritual abzuschließen.|n|nDie Blutskalpe haben Mojo in Zul\'Kunda, aber es ist schwach. Das Mojo der Dunkelspeere wird auch nicht ausreichen. Nein... wir brauchen das Mojo der Schädelspalter. Ihr könnt sie auf der anderen Seite des Flusses östlich von hier finden.|n|nBeeilt Euch, <Volk>. Ich werde Euch zusehen...', },
    {'Erhaltet 6 Mojos der Schädelspalter von Trollen der Schädelspalter in den Ruinen von Ziata\'jai und den Ruinen von Balia\'mah.', },
  },
  [26333] = {
    'Keine Panzer!',
    {'Wir haben bereits einige Späher bei dem Versuch verloren, herauszufinden, was Razlo Ritzelstoß mit all den Mechanopanzern vorhat, die seine bestrahlten Techniker reparieren.|n|nWir dürfen nicht noch mehr Zeit verlieren. Wir müssen handeln, bevor Ritzelstoß seine Anhänger und seine Waffen auf uns hetzt.|n|nIn dieser Techno-Granate befindet sich genügend Sprengkraft, um die Mechanopanzer zu zerstören. Dann wird Ritzelstoß sie nicht mehr verwenden können. Nehmt sie mit nach Norden, auf die Straße, die zu Ritzelstoß\' Arsenal führt, und vernichtet diese Panzer!', },
    {'Benutzt die Techno-Granate, um 5 reparierte Mechanopanzer in Ritzelstoß\' Arsenal zu vernichten.', },
  },
  [26334] = {
    'Blutfürst Mandokir',
    nil,
    {'Bringt das Eierfragment eines Schmetterschwanz\' zu Blutfürst Mandokir im Basislager Grom\'gol.', },
  },
  [26335] = {
    'Macht die Marine startklar',
    {'Höllschrei erwartet eine Armada von Schiffen für seinen Einmarsch, aber die Arbeiten hier hinken dem Zeitplan um Wochen hinterher. Die Kosten sind himmelhoch und die Qualität erbärmlich. Das Problem hier ist Korruption, $N! Und ich brauche Euch, um dieses Übel auszumerzen.|n|nDie Feindbrecher, ein Kriegsschiff, das am nordwestlichen Pier liegt, sollte schon vor Tagen ausgestattet werden. Da ist etwas faul. Geht dorthin und überwacht den Bau selbst.|n|nFindet heraus, wer unsere Schiffsvorbereitungen unterbricht und setzt dem ein Ende!', },
    {'Untersucht den Rumpf der Feindbrecher.', },
  },
  [26336] = {
    nil,
    {'Ihr seid in Ordnung, $N. Man trifft nur selten sogenannte Helden, die so weit entfernt von der Heimat tatsächlich wissen, was sie tun. Ich würde Euch gern etwas mehr Arbeit überlassen. |n|nIch habe einen Freund namens Wank O\'Breen. Er kommandiert eine Piratenbesatzung, die Schwarzmeerräuber; das sind gute Jungs, respektabel für Piraten. Sie haben in Faldirs Bucht angelegt, die versteckt am Südstrand liegt.|n|nO\'Breen wird Euch sicherlich einige lukrative Angebote machen können, wenn Ihr interessiert seid.', },
    {'Findet Wank O\'Breen in Faldirs Bucht im Arathihochland.', },
  },
  [26337] = {
    'Schlagfertige Überredungskunst',
    {'<Es ist offensichtlich, warum die Feindbrecher im Zeitplan hinterherhinkt. Alle zwei Tage nimmt ein Großknecht Änderungen an den Blaupausen vor.>|n|n<Am beunruhigendsten sind die letzten Änderungen. Den Arbeitern wurde befohlen, Nieten zu entfernen, um Kosten zu sparen!>|n|n<Ihr solltet einen der Bilgewässer Großknechte finden, die dafür verantwortlich sind und ein Exempel statuieren. Ansonsten kommen noch Mitglieder der Horde wegen der fehlerhaften Schiffe ums Leben!>', },
    {'Sucht einen Bilgewässer Großknecht im Bilgewasserhafen und mischt ihn ein wenig auf.', },
  },
  [26338] = {
    'Bevölkerungskon-Trolle',
    {'Ich habe gehört, dass Ihr bald nach Zul\'Kunda aufbrechen werdet. Ich habe eine kleine Aufgabe für Euch, wenn Ihr dort seid.|n|nDie Bevölkerung der Trolle ist zu groß für Schlingendorntal geworden. Die Blutskalpe im Westen, die Schädelspalter im Osten... sie kommen aus den Ruinen und machen sich im Dschungel breit. Das stört das natürliche Gleichgewicht der Gegend. Dieses Gleichgewicht muss jetzt wiederhergestellt werden.|n|nZul\'Kunda ist die Hochburg der Blutskalpe. Dort werdet Ihr die hochrangigsten Blutskalpe finden. Reduziert ihre Zahlen und kehrt zu mir zurück.', },
    {'Tötet 7 Mystiker der Blutskalpe, 7 Jäger der Blutskalpe, 7 Späher der Blutskalpe und 1 Bestienmeister der Blutskalpe.', },
  },
  [26339] = {
    'Vorbereitungen in Bräuhall',
    {'Während Hochtüftler Mekkadrill, seine militärischen Berater und ich die Pläne für den Angriff auf Razlo Ritzelstoß durchgehen, ist mein Assistent schon einmal nach Bräuhall gereist, um mit den Vorbereitungen zu beginnen.|n|nFolgt der Straße nach Südosten aus der Stadt hinaus, um nach Bräuhall zu gelangen. Findet Jarvi Schattenschritt nach Eurer Ankunft und findet heraus, ob er Hilfe benötigt. Unsere Zwergencousins haben einen Trupp Gebirgsjäger aus Eisenschmiede abgestellt, um uns im Kampf gegen Ritzelstoß zu unterstützen.', },
    {'Sprecht mit Jarvi Schattenschritt in Bräuhall.', },
  },
  [26340] = {
    'Die Jagd',
    {'Von allen Plätzen in Azeroth stecke ich ausgerechnet hier in Grom\'gol fest. Es ist ein Wunder, dass ich noch am Leben bin, mit den gefährlichen Wildtieren, den Überfällen auf Karawanen und der dauernden Bedrohung durch Angriffe der Trolle.|n|nEs könnte schlimmer sein. Hier in Grom\'gol gibt es wenigstens Mauern und Wächter. Eine Gruppe Jäger hat nördlich von hier mitten im Dschungel ihr Lager errichtet!|n|nIch sehe die ganze Zeit, wie Leute dort hingehen. Wenn Ihr nach Ärger sucht, solltet Ihr in diese Richtung aufbrechen. Ich bleibe in Grom\'gol.', },
    {'Meldet Euch bei Barnil Steinkrug bei Nesingwarys Expedition im Nördlichen Schlingendorntal.', },
  },
  [26341] = {
    'Die Steinsplitter',
    nil,
    {'Untersucht die Splitter von Myzrael.', },
  },
  [26342] = {
    'Schwarzmalerei',
    {'Uns liegen verlässliche Informationen vor, laut derer Razlo Ritzelstoß eine Verteidigungsstellung auf der Insel in der Mitte des gefrorenen Eiswellensees errichtet hat. Hinzu kommt, dass er sich mit zahlreichen Späh-o-Bots umgibt, die mögliche Angreifer entdecken sollen.|n|nWir können uns Ritzelstoß erst stellen, wenn diese Späher zerstört worden sind. Dieses Gerät schießt eine dunkle, klebrige Farbe ab. Sie wird die optischen Sensoren von Ritzelstoß\' Späh-o-Bots verdecken. Schaltet sein Frühwarnsystem damit aus.', },
    {'Benutzt den Farbinator, um 5 von Ritzelstoß\' Späh-o-Bots die Sicht zu nehmen.', },
  },
  [26343] = {
    'Angebot und Nachfrage',
    {'Der beste Ledermacher der Südlichen Meere und der Alten wie der Neuen Welt. So nennen sie mich. Mich! Drizzlik! Der beste Le... ähem. Nun ja.|n|nMeine Lederwaren sind nah und fern als absolut vorzüglich bekannt, erste Wahl der wahren Kenner!|n|nGerade habe ich eine Bestellung von Direktor Quizvox vom Tüftlerverband über ein Dutzend seiner Lieblingsstiefel aus der Exzelsiorlinie erhalten. Unsere Verkaufsschlager, ehrlich gesagt.|n|nFür die Grundform benötige ich Krokiliskenhäute von den Krokis entlang des Flusses im Norden des Schlingendorntals.', },
    {'Bringt 2 große Flusskrokiliskenhäute zu Drizzlik bei Nesingwarys Expedition.', },
  },
  [26344] = {
    'Etwas Zusammenbau benötigt',
    {'Nun, ich habe die Grundform der Stiefel so weit und sie werden auch sehr gut, aber die Häute, die Ihr mir gebracht habt, werden leider nicht für die inneren Schichten ausreichen.|n|n"Was sollen wir tun, Drizzlik?" Diese Frage brennt Euch zweifelsohne auf den Lippen und Ihr habt wirklich Glück, dass Ihr mit Drizzlik sprecht, denn er wird Euch genauestens erklären, was wir zu tun gedenken!|n|nDie inneren Schichten sieht sowieso nie jemand, also werden wir uns zum Ausfüllen der Stiefel einige der billigeren, dickeren Häute der Krokis holen, die um den Nazferitisee leben.', },
    {'Bringt 5 Schnappkieferkrokiliskenhäute zu Drizzlik bei Nesingwarys Expedition.', },
  },
  [26345] = {
    'Exzelsior',
    {'Die Innenseiten sind fertig gestellt, jetzt fehlt nur noch die äußere Schicht. Dafür verwende ich nur die besten Häute der alten Krokilisken. Sie sind widerstandsfähiger und eine bessere Leinwand - wenn Ihr es so nennen wollt - für die Muster und Akzente, die Drizzliks Exzelsiorlinie ausmachen.|n|nEs ist allerdings äußerst schwierig, diese vollkommene Haut zu finden; die Einzige, die meinen Plänen gerecht wird, ist die eines alten Salzwasserkrokilisken. Ihr findet sie im Süden, in der der Nähe der Grenze am Kap.', },
    {'Bringt die Haut eines alten Krokilisken zu Drizzlik bei Nesingwarys Expedition.', },
  },
  [26346] = {
    'Myzraels Geschichte',
    {'Als der Stein verstummt, hallt ein ungutes Gefühl in Euch nach. Etwas stimmt nicht.|n|nVielleicht solltet Ihr Skuerto erzählen, was Ihr bis jetzt getan habt.', },
    {'Kehrt zu Skuerto in der Zuflucht im Arathihochland zurück.', },
  },
  [26347] = {
    'Bewahrer der Flamme',
    {'Die Nacht, als die Leuchtturmwärterfamilie starb, war schrecklich. Ich musste hilflos zusehen, während Trübauge der Alte den Angriff anführte. Aber die Vergangenheit lässt sich nicht ändern und meine Hauptsorge gilt jetzt den Leben der Seeleute auf dem Großen Meer. Ihre Schiffe kommen den gefährlichen Felsen entlang der Küste oft zu nahe. Da niemand mehr auf das Leuchtfeuer aufpasst, fällt diese Aufgabe jetzt mir zu.|n|nHelft mir, die Flamme am Leben zu erhalten, indem Ihr mir Schluchtenschlamm von den Schleimen im Rasenden Schlund im Nordosten bringt.', },
    {'Bringt 5 Schluchtenschlamme zu Kapitän Grausohn am Leuchtturm von Westfall.', },
  },
  [26348] = {
    'Ärger an der Küste',
    {'Die vielen Schiffswracks entlang der Küste sind Euch ja vermutlich schon aufgefallen. Das Große Meer ist überaus tückisch. Die Küste von Westfall muss freigehalten werden, damit die Seeleute sicher sind, wenn sie unsere Ufer erreichen. Aber die Murlocs sind ein Problem.|n|nTötet Gezeitenjäger und Orakel, dann sorge ich dafür, dass Ihr belohnt werdet.', },
    {'Tötet 7 Murlocgezeitenjäger und 7 Murlocorakel.', },
  },
  [26349] = {
    'Bedrohung an der Küste',
    {'Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Trübauge der Alte die Familie des Leuchtturmwärters vertrieben hatte. Die Familie kehrte zurück und zündete die Flamme wieder an, doch Trübauge brachte die willensschwächeren Murlocs dazu, den Leuchtturm noch einmal mit ihm zusammen anzugreifen. Beim zweiten Mal hatte die Familie nicht so viel Glück. Vor meinen Augen starben sie alle, ohne sich wehren zu können.|n|nTötet Trübauge den Alten, wenn Ihr ihn am Ufer seht, und bringt mir eine seiner Schuppen, dann werdet Ihr eine Belohnung erhalten.', },
    {'Bringt Kapitän Grausohn am Leuchtturm von Westfall eine Schuppe von Trübauge dem Alten.', },
  },
  [26350] = {
    'Priesterin Hu\'rala',
    {'Ich danke Euch, $N. Ich weiß, Ihr hättet mich nicht retten müssen und... nun, ich bin Euch sehr dankbar.|n|nDie Rückkehr von Blutfürst Mandokir ist eine schreckliche Nachricht. Er wurde vor vielen Jahren in Zul\'Gurub getötet und wir dachten, es wäre das Ende von ihm und seinesgleichen. Die Trolle von Zul\'Gurub haben versucht, ein abscheuliches, furchtbares Ritual durchzuführen. Wenn Mandokir lebt, so gibt es Grund zur Annahme dass er nicht der Einzige ist.|n|nDie Trolle in Bambala östlich von hier könnten mehr wissen. Sprecht mit der Priesterin.', },
    {'Sprecht mit Priesterin Hu\'rala in Bambala im Nördlichen Schlingendorntal.', },
  },
  [26351] = {
    'Gedankensicht',
    {'Um Mandokir zu erkennen, müsst Ihr Mandokir sehen.|n|nUm Mandokir zu sehen, müsst Ihr Augen von Raptor nutzen.|n|nIhr habt Euch angefreundet mit Raptor: Ohgan\'aka: Tochter von Ohgan.|n|nUm Freundschaft zu stärken, brauchen wir Federn.|n|nGeht nach Westen und Ihr werdet Federn finden, ja.', },
    {'Erbeutet 5 Dschungelpirscherfedern von Dschungelpirschern im Nördlichen Schlingendorntal.', },
  },
  [26352] = {
    'Cozzles Vorhaben',
    {'Ich mag von den Dunkelspeeren abstammen, aber ich habe meine Kindheit hier im Schlingendorntal verbracht. Ich habe jedes Fleckchen des Schlingendorntals gesehen; es gibt jedoch nichts Schlimmeres als die Zerstörung, die die Venture Company dem Flussbett zugefügt hat.|n|nUnd es wird noch schlimmer, weil Großknecht Cozzle und seine Arbeiter ihre Aktivität gesteigert haben. Ich fürchte, sie haben etwas Neues vor. Schließt die Aufgabe ab, an der ich gescheitert bin, $N: tötet Cozzle, nehmt seinen Schlüssel und stehlt die Blaupausen aus seinem Heim.', },
    {'Nehmt Cozzles Schlüssel dem Großknecht Cozzle ab und erhaltet die Treibstoffreglerblaupausen.', },
  },
  [26353] = {
    'Käpt\'n Sanders\' versteckter Schatz',
    {'Wenn Ihr das hier lesen tut, dann heißt das, dass der alte Käpt\'n Sanders in den Fluten begraben is\'. Also tut mein Schatz jetz\' Euch gehör\'n, Ihr braucht bloß den Hinweisen folgen. |n|nErst müsst Ihr ma\' meine Schließkiste finden. Wahrscheinlich is\' die jetz\' da an der Westküste von Westfall in der Nähe von dem Schiffswrack schon halb im Sand verschwunden. \'s gibt da an der Küste massig Schiffswracks, aber bloß einen rostigen Anker. Wenn Ihr den Anker finden tut, dann habt Ihr auch meine Schließkiste gefunden. Da müsst ihr reingucken, denn da steht der nächste Hinweis drin.', },
    {'Findet Käpt\'n Sanders Schließkiste und durchsucht sie, um den nächsten Hinweis zu erhalten.', },
  },
  [26354] = {
    'Käpt\'n Sanders\' versteckter Schatz',
    {'Der Hinweis auf den Schatz lautet folgendermaßen: Gut gemacht, Kumpel! Jetz\' müsst Ihr Euch imma nach Osten halten. Im Osten die Steilhänge hoch, dann weiter nach Osten bis zur Straße. Schaut Euch nach so \'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr \'n altes Fass mit Eurem nächsten Hinweis drin.', },
    {'Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis.', },
  },
  [26355] = {
    'Käpt\'n Sanders\' versteckter Schatz',
    {'Als Ihr das Fass durchsucht, findet Ihr ein weiteres Stück Pergament. Darauf steht: Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un\' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so \'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt. Wenn Ihr Euch den Henkelkrug mal genau anguckt, dann findet Ihr vielleicht sogar, was Ihr sucht.', },
    {'Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis.', },
  },
  [26356] = {
    'Käpt\'n Sanders\' versteckter Schatz',
    {'Findet Käpt\'n Sanders\' Truhe und öffnet sie. Darin befindet sich Eure Belohnung.', },
    {'Findet Käpt\'n Sanders\' Truhe und öffnet sie. Darin befindet sich Eure Belohnung.', },
  },
  [26357] = {
    'Gesichter des Bösen',
    {'Die Blutfratzen haben ihre Tikimasken überall in Jintha\'Alor an die Mauern gehangen. Die Geister werden nicht mehr lange über sie wachen.|n|nNehmt die Fackel und kämpft Euch durch die Blutfratzen, $C. Zündet ihre Tikimasken an. Ich werd zusehen, wie ihre Abwehr- und Schutzzauber vergehen und ihr ketzerischer dunkler Voodoo in Rauch aufgeht.', },
    {'Zündet mit der Tikifackel 8 Tikimasken in Jintha\'Alor an.', },
  },
  [26358] = {
    'Macht die Luftwaffe startklar',
    {'Ich habe Höllschrei persönlich garantiert, dass seine Luftflotte diese Woche fertig wird, aber unser Flaggschiff, die Speer von Durotar, hat immer noch keine Haupttriebwerke.|n|nFliep hat mir letzte Woche ein niegelnagelneues Triebwerk versprochen. Geht zu ihrem Schrottplatz hinter der Bank und findet den Grund für die Verzögerung heraus.|n|nDie Luftflotte erwartet uns, $N!', },
    {'Sucht nach Fliep auf ihrem Schrottplatz im Bilgewasserhafen in Azshara.', },
  },
  [26359] = {
    'Seht Raptor',
    {'Federn? Haben wir.|n|n$C? Haben wir.|n|nSprecht mit Priesterin, wenn bereit.', },
    {'Sprecht mit Priesterin Hu\'rala in Bambala, um am Ritual der Gedankensicht teilzunehmen.', },
  },
  [26360] = {
    'Gedankenkontrolle',
    {'Gedankensicht nicht genug, nein.|n|nGedankenkontrolle viel mächtigere Magie, ja.|n|nMächtige Magie braucht mächtige Reagenzien und Trollhirn ist mächtiges Reagenz.|n|nBraddok in Zul\'Mamwe sehr intelligent, ja.|n|nGeht nach Süden und untersucht Braddoks großes Gehirn.', },
    {'Erbeutet Braddoks Riesengehirn von Braddok in Zul\'Mamwe.', },
  },
  [26361] = {
    'Smoots Samophlang',
    {'Es war der Kapitän, der darauf bestanden hat, dass die neuen Triebwerke ein Induktionssamophlang haben.|n|nSo etwas wurde noch nicht einmal erfunden!|n|nIch habe Smoot damit beauftragt, ein Induktionssamophlang auf Basis von gestohlenen Zeichnungen der Venture Company zu entwerfen. Endlich ist es ihm auch gelungen, ein funktionierendes Modell zu bauen.|n|nDoch jetzt, wo er das Samophlang hat, ist er vor lauter Macht ganz berauscht. Er schleift es in der ganzen Stadt mit sich herum, wie ein Besessener.|n|nVersetzt Smoot eine Tracht Prügel und schnappt Euch mein Samophlang, $N.', },
    {'Findet Smoot im Bilgewasserhafen. Stellt ihn und besorgt Euch das Induktionssamophlang.', },
  },
  [26362] = {
    'Seid Raptor',
    {'Gedankenkontrolle sehr mächtig, ja.|n|nMit Glück könnt Ihr Ohgan\'aka helfen, aus Zul\'Gurub zu fliehen.|n|nDann wird Ohgan\'aka wieder $N\'aka werden!|n|nSprecht mit Priesterin, ja, und helft $N\'aka bei Flucht.', },
    {'Sprecht mit Priesterin Hu\'rala und helft dem gefangenen Schmetterschwanzjungen bei der Flucht aus Zul\'Gurub.', },
  },
  [26363] = {
    'Schicksalsgipfel',
    {'Ihr wart im Vorgehen gegen ihre Krieger sehr erfolgreich, $N. Ich möchte, dass Ihr den Gipfel von Jintha\'Alor untersucht.|n|nWir waren auf den härtesten Kampf vorbereitet, darauf, ihren dunklen Altar zu stürmen, aber es ist zu leise. Kein Geräusch weit und breit. Es könnte eine furchtbare Falle sein und jemand, der stark genug ist, sollte sich dort umsehen, bevor wir alle gesammelt einlaufen.|n|nWenn es keine Falle sein sollte... würde es mich auf jeden Fall auch interessieren, was dort los ist. Bringt mir jegliche Hinweise, die Ihr finden könnt.', },
    {'Sammelt 8 Spinnengötzen der Blutfratzen auf dem Gipfel von Jintha\'Alor.', },
  },
  [26364] = {
    'Nieder mit Ritzelstoß!',
    {'Unsere Cousins, die Zwerge von Eisenschmiede, haben sich bereit erklärt, uns im Kampf gegen Razlo Ritzelstoß zu unterstützen. Gebirgsjäger Steinschleifer ist ein Veteran, der Dun Morogh gut kennt. Er und Hochtüftler Mekkadrill halten sich auf einer kleinen, schneebedeckten Insel im Eiswellensee nördlich von hier bereit. Trefft sie dort und sagt dem Hochtüftler Bescheid, wenn Ihr bereit seid, dem Verräter Ritzelstoß entgegenzutreten.|n|nNehmt dieses orbitale Zielgerät und benutzt es während der Schlacht. Es wird die Spezialwaffen des Hochtüftlers zum Ziel führen.', },
    {'Besiegt Razlo Ritzelstoß. Sprecht mit Hochtüftler Mekkadrill auf dem Eiswellensee, wenn Ihr bereit seid, den Kampf zu beginnen.', },
  },
  [26365] = {
    'Heldenaufruf: Rotkammgebirge!',
    {'Die Lage hier ist zwar schlimm, aber in anderen Gegenden bebt es wortwörtlich nach dem großen Aufruhr immer noch.|n|nIch habe hier einen Bericht von Wachhauptmann Parker aus dem Rotkammgebirge, eines unserer Gebiete östlich vom Wald von Elwynn. Er ersucht die Hilfe eines Helden.|n|nSo, wie wir im Moment aufgestellt sind, kann ich keine weiteren Truppen losschicken. Könnt Ihr Parker aufsuchen und sehen, was er braucht? Ihr könnt Wachhauptmann Parker auf dem Turm bei den Drei Ecken finden.', },
    {'Meldet Euch bei Wachhauptmann Parker an der Turmwacht im Rotkammgebirge.', },
  },
  [26366] = {
    'Kopfprämie',
    {'Umboda von den Blutfratzen ist einer ihrer stärksten Krieger und ein kranker Schlächter.|n|nEr sammelt und benutzt die Köpfe aller, die vor ihm fallen, als Schmuck, Belohnungen... und sogar Waffen! Es ist an der Zeit, dass er fällt.|n|nFindet Umboda Dreikopf, tötet ihn und bringt mir SEINEN Kopf! Wir werden sehen, wie die Blutfratzen kämpfen, wenn wir seinen Kopf über ihre Mauern werfen!', },
    {'Besiegt Umboda Dreikopf und holt Euch seinen Kopf.', },
  },
  [26367] = {
    'Ongo\'longos Rache',
    {'Ongo\'longo war einer von uns. Außenseiter mögen ihn einen Terrortroll nennen, aber er war ein Bruchhauer und ein stolzer Krieger, so wie wir auch!|n|nDann haben die Blutfratzen ihn gefangen genommen. Sie halten ihn gefesselt in einer Grube oben in Jintha\'Alor und zwingen ihn, zu ihrer kranken Unterhaltung zu tanzen.|n|nKeine Ketten können Ongo\'longo halten. Ihr müsst nur sein Temperament aufwecken. Bekämpft ihn, bis er sich genug ärgert, um sich an sein wahres Ich zu erinnern und die Fesseln sprengt... und dann geht ihm schnell aus dem Weg!', },
    {'Kämpft gegen Ongo\'longo, bis er seine Ketten sprengt.', },
  },
  [26368] = {
    'Giftige Geheimnisse',
    {'Von diesem interessanten Gift wird es noch mehr geben, wenn Shadra gerufen wurde.|n|nSeid nicht so überrascht... Die Verlassenen haben diese Länder schon seit längerem untersucht und wir haben die Königin des Gifts hier mindestens einmal gesehen. Ihre Gifte haben sich in der Vergangenheit als recht nützlich herausgestellt.|n|nUnd sie werden sich der Horde erneut als nützlich erweisen. Seid so nett und holt so viel Gift, wie Ihr von der Brut von Shadra erhalten könnt, die in der Höhle auf dem Gipfel sind... Ihr werdet ohnehin voll davon sein, wenn Ihr die Höhle betretet.', },
    {'Erhaltet 6 Giftprobe der Shadrabrut von der Brut von Shadra in Jintha\'Alor.', },
  },
  [26369] = {
    'Jagt die Bewahrerin',
    {'Kotonga hat mir von Shadra berichtet. Sie ist die Giftkönigin, die Loa der Spinnen, in der Dunkelheit verehrt. Falls die Blutfratzen vorhaben, Rituale durchzuführen, so werde ich dies zu verhindern wissen.|n|nUntersucht die Höhle hinter dem Altar oben auf Jintha\'Alor. Tief in der Höhle könnte sich noch eine Bewahrerin Shadras verstecken. Tötet sie und nehmt alles, was sie bei sich hat, damit wir herausfinden können, was dort vor sich geht.', },
    {'Tötet Morta\'gya die Bewahrerin und bringt die Tafel von Shadra an Euch.', },
  },
  [26370] = {
    'Rückkehr zur Späherkuppe',
    {'Die Bruderschaft der Defias sollte man nicht auf die leichte Schulter nehmen, $N. Was Ihr da gesehen habt, war die Geburtsstunde einer skrupellosen Verbrecherorganisation, die vor nichts Halt machen wird, bevor Sturmwind nicht in Schutt und Asche liegt.|n|nIch möchte, dass Ihr zur Späherkuppe zurückkehrt und Gryan wissen lasst, dass ich ihm Truppen schicke. Ich hoffe, es ist noch nicht zu spät.', },
    {'Erstattet Marschall Gryan Starkmantel an der Späherkuppe in Westfall Bericht.', },
  },
  [26371] = {
    'Die Legende des Kapitän Grausohn',
    {'Habt Ihr von Kapitän Grausohn gehört? Einige sagen, er ist die Erfindung eines betrunkenen Seemannsgehirns, aber jeder in Westfall wird Euch sagen, dass Grausohn existiert! Er ist ein Geist, der den Leuchtturm von Westfall ganz im Westen, vor der Endlosen Küste, heimsucht.|n|nWagt Ihr es, das zu untersuchen?', },
    {'Findet Kapitän Grausohn beim Leuchtturm von Westfall in Westfall.', },
  },
  [26372] = {
    'Letzte Tests vor dem Flug',
    {'Dieses neue Triebwerk ist extrem schnell. Und gefährlich. Ich würde es "brisant" nennen.|n|nGenau so mag der Kapitän es.|n|nRennt schnell den Hügel hinauf und sagt ihm Bescheid, dass ich dieses Schätzchen jetzt einbaue und er sich auf der Baustelle mit mir treffen soll.', },
    {'Sprecht mit Kapitän Krazz im Bilgewasserhafen in Azshara.', },
  },
  [26373] = {
    'Weiter nach Kharanos',
    {'Einige der Gebirgsjäger unter Steinschleifers Kommando haben mir von den Problemen draußen in Kharanos berichtet. Als die Troggs die Höhle der Frostmähnen eroberten, sind die überlebenden Trolle anscheinend nach Westen, bis ins Herz der Zwergenheimat geflohen.|n|nJetzt bedrohen sie die Zwergenstadt Kharanos. Die Zwerge dort brauchen wohl dringend Hilfe. Warum reist Ihr nicht nach Kharanos und stellt Euch Hauptmann Tharran vor? Folgt der Straße, die nach Osten aus Bräuhall herausführt und folgt ihr, bis Ihr die Stadt seht.', },
    {'Sprecht mit Hauptmann Tharran in Kharanos.', },
  },
  [26374] = {
    'Macht die Bodentruppen startklar',
    {'Es war keine gute Idee, die Truppen in dieser pulsierenden Goblinmetropole einzuberufen. Jedes Laster, das man mit Gold kaufen kann, ist nur eine Armlänge entfernt. Unsere mächtigen Veteranen sind völlig zügellos und hauen ihren über Jahre mühsam in Nordend verdienten Sold auf den Kopf. Die Stadt droht, zusammenzubrechen!|n|nKönntet Ihr durch die Stadt streifen und die fahnenflüchtigen Nachzügler einsammeln?|n|nMeine Krieger der Axtbeißer sind auf dem Schlachtfeld unschlagbar, aber ich lasse nicht zu, dass sie ihren Uniformen während ihres Landgangs Schande bringen.', },
    {'Durchsucht den Bilgewasserhafen und überzeugt 12 fahnenflüchtige Grunzer, sich zum Dienst zu melden.', },
  },
  [26375] = {
    'Lose Steine',
    {'Die Schattenhammerkultisten rauben meine Steinlinge. Sie stehlen ihre Energie und foltern sie. Sie nehmen ihnen die Essenz, die dem Stein Leben einhaucht.|n|nBitte, <Volk>, befreit meine Steinlinge. Weder Diamant noch ich verfügen über das Fingerspitzengefühl, ihre Ketten zu zerschlagen, ohne sie zu verletzen. Aber wir haben ein Werkzeug, das Ihr vielleicht verwenden könnt.|n|nNehmt dies. Sprengt ihre Ketten und befreit sie.', },
    {'Benutzt den filigranen Kettensprenger, um 6 Quarzsteinlinge zu befreien.', },
  },
  [26376] = {
    'Tiefsitzender Hass',
    {'Ich würde mich ja für Boden entschuldigen, aber Stein ist stur.|n|nOhne den nagenden Zahn der Zeit weicht er nicht von seinen Gewohnheiten ab.|n|nDie Steinlords, darunter Boden und ich, haben die Aufgabe, die Weltensäule zurückzuholen.|n|nDoch wir sind uns uneinig.|n|nIch möchte Euch gerne meine Geduld zuteilwerden lassen, <Volk>.|n|nBeweist, dass Ihr kein Verbündeter des Schattenhammerkults oder Todesschwinges seid...|n|nTragt unseren Hass zu ihnen.|n|nSchlagt schnell zu, wo wir es nicht können.|n|nHabt Ihr Erfolg, werde ich Euch zuhören.', },
    {'Tötet Dragul Riesenschlächter und 12 Schattenhammerkultisten an Lorthunas Tor.', },
  },
  [26377] = {
    'Loser Grund',
    {'Der Schattenhammerkult baut in der Nähe seines Lagers Jadekristalle ab.|n|nDumm…|n|nWaghalsig…|n|nSammelt die abgebauten Kristalle. Bringt sie in die Mitte ihres Lagers. Verteilt sie auf dem Boden.|n|nDie Schwingungen und der aufgeladene Kristall werden die Tunnelgräber auf sie hetzen.|n|nSie werden lernen, die Erde zu respektieren...|n|nStück für Stück...|n|nFels für Fels...|n|n... mit der Zeit.', },
    {'Sammelt 6 Jadekristallformationen und kombiniert sie miteinander. Verteilt sie dann im Lager an Lorthunas Tor.', },
  },
  [26378] = {
    'Heldenaufruf: Westfall!',
    {'In Westfall herrschen harte Zeiten. Jetzt, da die Bedrohung durch die Defias beseitigt ist, ist das Gebiet zu einer Zuflucht für Obdachlose und Unterdrückte geworden. Die Verbrechensrate in dieser Region ist astronomisch in die Höhe geschossen, da die Leute sich um Unterschlupf und Nahrung zanken. Und jetzt hört man sogar von Mord!|n|nWenn Ihr der Allianz helfen wollt, dann beginnt in Westfall. Meldet Euch bei Leutnant Horatio Laine auf Jansens Hof. Ihr findet Westfall direkt westlich des Waldes von Elwynn.', },
    {'Meldet Euch bei Leutnant Horatio Laine auf Jansens Hof in Westfall.', },
  },
  [26379] = {
    'Hilfe für die Flüchtlinge',
    {'Ich hoffe, Ihr seid hier, um zu helfen! Ihr habt keine Ahnung, wovon ich spreche, oder?|n|nIch habe keine Zeit, um Euch alle Details zu erläutern, aber hier in Dunkelküste gab es einen Ort namens Auberdine, der vom Kataklysmus übel zugerichtet wurde. Wir sind dabei, einige der Überlebenden zu retten, aber ich brauche jemanden mit etwas mehr Erfahrung, der nach dem Flüchtlingslager sieht, das sich im Süden befinden soll. Jemanden wie Euch!|n|nÜberlasst uns die Dinge im Norden. Geht direkt nach Süden und helft den Flüchtlingen, wo Ihr nur könnt.', },
    {'Schildwache Lendra in Lor\'danel möchte, dass Ihr mit Priesterin Alinya im Flüchtlingslager sprecht.', },
  },
  [26380] = {
    'Lieferung für Kharanos',
    {'Ich sollte diese Bierfässer zum Gasthaus von Kharanos bringen. In den Fässern befindet sich ein mysteriöses neues Bier, das von einer neuen Brauerei in Bräuhall hergestellt wird. Als ich die Stadt verließ, wurde ich von Trollen der Frostmähnen überfallen. Ich werde Tage brauchen, um den Wagen zu reparieren!|n|nWürdet Ihr mir vielleicht einen Gefallen erweisen? Die großen Fässer lassen sich nicht bewegen, aber ich habe hier ein paar kleine Probefässer. Würdet Ihr die für mich nach Kharanos bringen? Folgt einfach nur der Straße nach Südosten.', },
    {'Bringt die Probefässer zu Gastwirt Belm in der Brauerei Donnerbräu in Kharanos.', },
  },
  [26381] = {
    'Das Auge von Shadra',
    {'Shadra muss gerufen werden, das ist sicher. Uns diese Gelegenheit entgehen zu lassen, wäre schlicht und ergreifend dumm. Die Apotheker finden sicher Verwendung für das Gift der Göttin, aber von Ritualmagie haben sie nicht viel Ahnung.|n|nGlücklicherweise bin ich mit der Vorbereitung dunkler Beschwörungen recht vertraut. Bringt mir die verstreuten Teile Shadras und ich werde sie auf diese Ebene beschwören.|n|nZuerst brauchen wir das Auge von Shadra. Es wird in Agol\'watha im Norden bewacht.', },
    {'Besorgt das Auge von Shadra aus Agol\'watha.', },
  },
  [26382] = {
    'Eiertanz',
    {'Marnal liegt mir schon seit Tagen mit seinem Shadravorhaben in den Ohren. Ich bereue schon fast, die Tafel wirklich gefunden zu haben – zu dem Zeitpunkt hätte er meiner Meinung nach schon den Mund halten können.|n|nUnd trotz seiner Erfahrung mit Ritualmagie braucht er meine Hilfe genauso sehr wie ich seine. Ich muss ein Basismedium mit ähnlichen...|n|n...wisst Ihr was, ich werde Euch die Einzelheiten ersparen. Bringt mir die Eier der Shadrabrut aus Agol\'watha. Ihr solltet dort viele finden – sie werden von den Trollen der Blutfratzen bewacht.', },
    {'Besorgt 5 Eier der Shadrabrut aus Agol\'watha.', },
  },
  [26383] = {
    'Unaufhaltsame Veränderungen',
    {'Ihr da! Ihr seht fähig aus. Und vielleicht sogar hilfsbereit?|n|nAuberdine ist letztendlich gefallen. Zwar haben viele Einwohner bereits vor langem die Stadt verlassen, als der Kataklysmus uns heimsuchte, doch einige der hartnäckigeren Bewohner wurden noch nicht gefunden. Und jetzt scheint die Stadt auch noch von Elementaren überrannt zu werden.|n|nMeine Schwestern brauchen Hilfe bei der Rettung der Überlebenden. Bitte, $C, benutzt den westlichen Teleportbaum, um nach Rut\'theran zu gelangen, sprecht mit Vesprystus und sichert einen Flug nach Lor\'danel. Beeilt Euch!', },
    {'Benutzt den Teleportbaum im westlichen Teil von Darnassus und reist nach Rut\'theran. Sprecht dort mit Vesprystus, um einen Flug nach Lor\'danel zu sichern.', },
  },
  [26384] = {
    'Der dunkle Kleriker Marnal',
    {'Wir können die Tafel noch nicht einfach wegschmeißen, $N. Wir können sie benutzen...|n|nWisst Ihr, mir geht es in erster Linie um das Gift der Spinnen. Es ist eindeutig magisch und wahrscheinlich gibt es eine Verbindung zur Spinnengöttin, mit der die Trolle etwas zu tun haben. Und wenn man die Tafel zur Beschwörung nutzen kann...|n|nNa ja, ich glaube, Ihr wisst, worauf ich hinaus will. Die Horde kann sich diese Gelegenheit nicht entgehen lassen. Bringt die Tafel zu den Verlassenen. Sie sind westlich von hier in der Forschungsstation in den Ruinen von Hiri\'watha.', },
    nil,
  },
  [26385] = {
    'Unaufhaltsame Veränderungen',
    nil,
    {'Sprecht mit Vesprystus in Rut\'theran, um nach Lor\'danel zu fliegen.', },
  },
  [26386] = {
    nil,
    {'Priesterin spricht nicht gut Orcisch, nein.|n|nVielleicht sprecht Ihr mir Surkhan, er ist oben.|n|nSagt ihm, was Ihr in Zul\'Gurub gesehen habt, ja.', },
    {'Meldet Euch bei Surkhan in Bambala im Nördlichen Schlingendorntal.', },
  },
  [26387] = {
    'Hungerdiät',
    {'Die Spinnen, die die Gruselruinen östlich von hier heimsuchen, sind nutzlos. Wir nennen sie zwar Shadrabrut und sie sind auch ganz offensichtlich mit der Spinnengöttin verwandt, aber das ändert auch nichts an der Tatsache, dass sie mehr Ärger machen als Nutzen bringen. Mir wäre es lieber, wenn wir die kleinen Plagegeister einfach ausmerzen könnten.|n|nFalls Ihr Euch zu den Gruselruinen aufmachen solltet, tötet alle Kokons, die Ihr finden könnt. Sie ernähren sich tagelang von den Leichen - die Nahrung der Biester zu zerstören wird effektiver sein, als der Versuch, sie alle zu zerquetschen.', },
    {'Zerstört 6 eingesponnene Opfer in den Gruselruinen.', },
  },
  [26388] = {
    'Zwielichthimmel',
    {'In Ordnung, Ihr seid also bereit. Wartet hier, bis Kapitän Krazz den Zeppelin gewendet hat und begleitet dann die Luftflotte. Admiral Steinfaust erwartet Euch beim Hafen des Drachenmals!', },
    {'Begleitet die Luftflotte der Horde ins Schattenhochland. Nehmt den Zeppelin vom Turm an der Südlichen Endhaltestelle der Raketenbahn in Azshara.', },
  },
  [26389] = {
    'Schwarzfelsinvasion',
    {'Die Orcs haben begonnen, den Wald niederzubrennen, $N! Sie haben den Weinberg im Osten übernommen und planen ihren Entscheidungsangriff auf uns! Sie müssen aufgehalten werden!|n|nGeht nach Osten, überquert den Fluss und tötet die wildgewordenen Orcs des Schwarzfelsklans. Sammelt als Beweis ihres Ablebens ihre Waffen ein und kehrt zu mir zurück.|n|nIhr seid unsere einzige Hoffnung, $N!', },
    {'Bringt 8 Waffen der Orcs des Schwarzfelsklans an Euch.', },
  },
  [26390] = {
    'Setzt der Invasion ein Ende!',
    {'Die wütende Orchorde wird von einem Ungeheuer angeführt, das als Kurtok der Schlächter bekannt ist. Kurtok ist für den vor Kurzem erfolgten Einmarsch verantwortlich und muss getötet werden, wenn wir Frieden im Tal haben wollen.|n|nGeht vorsichtig nach Osten zurück, überquert den Fluss und begebt Euch durch den Weinberg. Haltet Ausschau nach der Passage, die in die Berge führt. Dort wird Kurtok sich aufhalten und einen weiteren Angriff vorbereiten. Tötet ihn und kehrt zurück zu mir.', },
    {'Tötet Kurtok den Schlächter.', },
  },
  [26391] = {
    'Die Hoffnung ersticken',
    {'Tage wie diese lassen mich die Zeiten zurücksehnen, in denen die Defias noch da waren. Der Kataklysmus hat einen Weg aus der Brennenden Steppe geöffnet, und jetzt überlaufen Schwarzfelsorcs das Nordhaintal! Sie haben mein Weingut übernommen und brennen es nieder! SIE BRENNEN ES NIEDER!|n|nBitte, $N, dieses Weingut ist alles, was ich habe. Nehmt meinen Feuerlöscher und löscht die Flammen im Weingut. Vielleicht besteht noch Hoffnung für dieses Land!', },
    {'Benutzt Millys Feuerlöscher, um 8 Brände im Weingut zu löschen.', },
  },
  [26392] = {
    'Tapferkeitsbelobigung',
    {'Ihr habt die Schwarzfelsorcs vertrieben, und dafür sind wir Euch sehr dankbar! Obwohl die Weinberge bis auf den Grund niedergebrannt sind, ist der Rest Nordhains dank Euch sicher.|n|nBitte nehmt diese Belobigung an, die Euren außergewöhnlichen Mut würdigt, und bringt Sie zu Marschall McBride. Er ist für die Sicherheit Nordhains verantwortlich und wird sich freuen, von Euren Taten zu hören.', },
    {'Bringt die Tapferkeitsbelobigung zu Marschall McBride im Nordhaintal im Wald von Elwynn.', },
  },
  [26393] = {
    'Eine eilige Nachricht',
    {'Wir bekommen zwar nicht viel Unterstützung von Sturmwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Sturmwind.|n|nUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?|n|nDer schnellste Weg nach Sturmwind führt über Bartlett den Tapferen, unseren Greifenmeister. Er ist direkt bei der Schmiede; bringt ihm meine Notiz und nehmt dann einen Greifen nach Sturmwind.', },
    {'Bringt Argus\' Notiz zu Bartlett dem Tapferen, dem Greifenmeister.', },
  },
  [26394] = {
    'Weiter nach Sturmwind',
    {'Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Sturmwind nehmen und so Argus\' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.|n|nWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!', },
    {'Bucht einen Greifenritt bei Greifenmeister Bartlett dem Tapferen, dann bringt Argus\' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in der Altstadt von Sturmwind.', },
  },
  [26395] = {
    'Dungar Trinkfest',
    {'$N, ich habe alles, worum Argus gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?|n|nWenn Ihr bereits mit Bartlett in Goldhain gesprochen habt, dann könnt Ihr einen Greif zurück zu ihm nehmen. Dungar Trinkfest ist unser Greifenmeister drüben im Handelsdistrikt.|n|nSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Argus. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Goldhain ohne neue Ausrüstung sind!', },
    {'Bringt Osrics Kiste zu Dungar Trinkfest dem Greifenmeister.', },
  },
  [26396] = {
    'Rückkehr zu Argus',
    {'Der Name des Greifenmeisters in Goldhain ist Bartlett. Wenn Ihr bereits mit ihm gesprochen habt, könnt Ihr auf einem meiner Greifen zu ihm fliegen.|n|nVergesst nicht: Greifen sind so ausgebildet, dass sie jederzeit in ihre Hauptstadt fliegen können, bringen Euch aber nur zu anderen Greifenmeistern, wenn Ihr schon einmal dort wart.|n|nIhr habt Euch schon einmal mit Bartlett unterhalten, daher sprecht mich einfach erneut an, wenn Ihr auf einem Greifen nach Goldhain fliegen wollt. Sobald Ihr da seid, könnt Ihr Osrics Kiste zu Schmied Argus bringen.', },
    {'Bucht einen Greifenritt nach Goldhain bei Greifenmeister Dungar Trinkfest, dann bringt Osrics Kiste zu Schmied Argus in Goldhain.', },
  },
  [26397] = {
    'Geht mit der Erdenmutter',
    nil,
    nil,
  },
  [26398] = {
    'Geht mit der Erdenmutter',
    nil,
    nil,
  },
  [26399] = {
    'Die Schatzkiste der Mosh\'Ogg',
    nil,
    {'Erbeutet die Schatzkiste der Mosh\'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh\'Ogg.', },
  },
  [26400] = {
    'Der Universalschlüssel',
    {'Wir brauchen etwas Stärkeres als Eure fleischigen Hände, um das hier zu öffnen. Und die Trottel der Venture Company im Nordwesten haben möglicherweise genau das Richtige.|n|nDas letzte Mal, als ich da drüben war, sah ich Schredder herumlaufen, die riesige, rotierende Klingen an den Händen hatten. Das wäre eine Möglichkeit, einen Kasten zu öffnen.|n|nWenn Ihr keine Schredder findet, könnt Ihr auch die riesige Sägeklinge in ihrem Sägewerk am See ausprobieren.', },
    {'Öffnet die Belohnung der Mosh\'Ogg, indem Ihr gegen einen Schredder der Venture Co. kämpft, oder die Sägeklinge im Sägewerk der Venture Company benutzt.', },
  },
  [26401] = {
    'Rückkehr zu Vestia',
    {'Das sanfte Leuchten des Podests wird stärker. Ihr seht eine schlichte Kette, die zurückgelassen wurde. War es das, wonach der Lehrling gesucht hatte?', },
    {'Bringt das Graunebelamulett zu Vestia Mondspeer im Turm von Estulan.', },
  },
  [26402] = {
    'Generalin Shandris Mondfeder',
    {'Wir Druiden haben nicht besonders viel mit den Schildwachen zu tun, aber wir arbeiten bereitwillig zusammen, um unser Land zu verteidigen. Jetzt, da Ihr mir geholfen habt, wäre es äußerst nachlässig, wenn ich Euch nicht bitten würde, auch ihnen zu helfen.|n|nShandris Mondfeder, Generalin der Schildwachen, hat den Oberbefehl über alle militärischen Vorgänge in Kalimdor. Sie hält sich in der neu errichteten Mondfederfeste im Süden auf. Sagt Ihr, dass ich Euch schicke. Ich bin mir sicher, dass sie Eure Fähigkeiten benötigt.', },
    {'Sprecht mit Shandris Mondfeder in der Mondfederfeste in Feralas.', },
  },
  [26403] = {
    'Venture Company-Bergbau',
    {'Mann, ich hasse die Venture Company. Sie haben eine ganze Reihe von Operationen überall im Schlingendorntal, die hart arbeitende Goblins wie mich davon abhalten, ehrliches Gold zu verdienen!|n|nWie ich das mache? Durch Diebstahl. Die Geologen der Venture Co. in der Nähe des Nazferitisees im Nordwesten sind sehr an diesen merkwürdigen blauen Kristallen interessiert, die sie in den Minen finden. Bringt mir Proben dieses Gesteins von ihren Geologen. Mir ist egal, was Ihr tun müsst, um sie zu erhalten.', },
    {'Bringt 5 gerommelte Kristalle zu Skeezy Whillzap in Bambala im Nördlichen Schlingendorntal.', },
  },
  [26404] = {
    'Höhere Lohngruppe',
    {'Hey, seid Ihr schon in Hartzangs Versteck gewesen? Oh, das MÜSST Ihr sehen. Das ist alles, was ein Goblin sich je erträumen kann.|n|nIch sag Euch was... Ihr seht aus, wie $Gein überzeugter:eine überzeugte:c; $C. Rashka, die da drüben in Weste und Rock, kann Euch einen Flug verschaffen, wenn Ihr den Weg nicht bereits kennt.|n|nDer Flug geht auf mich.', },
    {'Sucht Sassy Hartzang in Hartzangs Versteck am Schlingendornkap auf.', },
  },
  [26405] = {
    'Mambo in Zul\'Mamwe',
    {'Die Schädelspalter sind eine Schande für das ganze Trollreich. Ihre kindischen Zankereien mit den Blutskalpen haben das Nördliche Schlingendorntal zerrissen. Während Stämme wie die Dunkelspeere und die Zandalari erblühen, kämpfen die Schädelspalter um Ruinen.|n|nIch wurde ermächtigt, allen Söldnern eine Belohnung zu bezahlen, die bereit sind, den Schädelspaltern eine Lektion zu erteilen. Ich ermutige daher Euch und alle, die Ihr kennt, nach Zul\'Mamwe im Süden zu reisen und ihrem abtrünnigen Stamm ein Ende zu setzen.', },
    {'Tötet 16 Schädelspaltertrolle im Inneren von Zul\'Mamwe.', },
  },
  [26406] = {
    'Der Fangzahn von Shadra',
    {'Als nächstes brauchen wir den Fangzahn von Shadra.|n|nShadras eigene Brut bewacht ihn in den Gruselruinen im Osten. Ihr Gift ist stark, $N... werdet nicht unvorsichtig.', },
    {'Besorgt den Fangzahn von Shadra aus den Gruselruinen.', },
  },
  [26407] = {
    'Die Handschrift von Mosh\'Ogg',
    {'Dieser Oger hatte einen ungewöhnlichen Gegenstand bei sich: die abgetrennte Hand eines anderen Ogers, die er an einer Schnur befestigt um den Hals trug Die Hand selbst weist viele Narben auf, die in einem schwachen lila leuchten.|n|nEine Narbe, die nach dem Tod leuchtet, ist höchst ungewöhnlich. So einen Gegenstand bei einem Oger zu finden, ist noch merkwürdiger. Vielleicht weiß jemand in Grom\'gol etwas mit dieser Kuriosität anzufangen.', },
    {'Bringt die entstellte Hand eines Mosh\'Ogg zu Scharfseher Mok\'thardin im Basislager Grom\'gol im Nördlichen Schlingendorntal.', },
  },
  [26408] = {
    'Asche im Eschental',
    {'Dunkelküste mag zerschlagen und zerschmettert sein, aber dank Euch haben wir hier ein gewisses Maß an Sicherheit erlangt. Ein gewisses Maß an Frieden. Wir müssen noch viel wieder aufbauen.|n|nIhr solltet weitermachen, $Gmein Freund:meine Liebe;. Garrosh hat die geballte Macht seiner Horde gegen uns im Eschental aufgefahren. Sie werden uns alle töten und den Wald roden, wenn wir nicht gegen sie vorgehen.|n|nUm Hoffnung zu bewahren, diese Wälder nicht vollständig aufgeben zu müssen, benötigen wir Eure Hilfe. Folgt der Straße in Richtung Süden und sucht Schildwache Shyela auf.', },
    {'Sprecht mit Schildwache Shyela bei Orendils Zuflucht im Eschental.', },
  },
  [26409] = {
    'Wo ist Goldmine?',
    {'Mein goblinischer Initiand ist schon eine ganze Weile fort. Sein Name ist Goldmine.|n|nIch habe ihn losgeschickt, um die Felsklauen im Südwesten im Quarzitbecken zu beobachten. Wärt Ihr bereit, ihn zu suchen? Wenn Ihr ihn findet, bittet ihn, zum Tempel zurückzukommen.', },
    {'Findet Initiand Goldmine am Quarzitbecken in Tiefenheim.', },
  },
  [26410] = {
    'Explosive Verbundmasse',
    {'Dieser Kerl ist der Sohn des Anführers der Irdenen! Er hatte es schon fast zurück in den Tempel geschafft, als er von mehr Felsklauen angegriffen wurde, als ich zählen konnte!|n|nWir wissen, dass der Steinvater der Irdenen das mittlere Fragment der Weltensäule besitzt. Wenn wir seinen Sohn heilen, gibt er uns vielleicht das Fragment.|n|nMeine Heilzauber funktionieren bei Flint hier nicht. Aber wenn wir an etwas Quarzitharz von diesen Monstern kommen könnten, könnte ich eine explosive Verbundmasse herstellen, die seine Wunden schließt und kauterisiert.', },
    {'Sammelt 5 Einheiten Quarzitharz.', },
  },
  [26411] = {
    'Ausgebrannt',
    {'In Ordnung, nehmt dies und gebt es auf seine Wunden. Wenn die blitzartige Kauterisation ihn nicht in Stücke reißt, sollte er dadurch vollständig heilen.|n|nGlaube ich…', },
    {'Behandelt Flint Erzmantel mit der explosiven Verbundmasse.', },
  },
  [26412] = {
    'Die Schatzkiste der Mosh\'Ogg',
    {'Sagt, habt Ihr von den Ogern gehört? Ich hab\' \'nen heißen Tipp von \'nem Typen namens Mok\'thardin bekommen, dass sie ein ganz besonderes, magisches Artefakt in ihrer Höhle verstecken. Skeezy weiß das aber besser. Ich rieche Geld aus einer Mulgoremeile Entfernung und ich wette, das Ogerdingsbums ist ein Vermögen wert.|n|nHier ist ein Hinweis: Ich habe gesehen, dass sie eine Kiste in den Ruinen hinter ihrem Hügel bewachen. Habt Ihr Lust, sie für mich zu holen?', },
    {'Erbeutet die Schatzkiste der Mosh\'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh\'Ogg.', },
  },
  [26413] = {
    'Bringt ihn zur Erdenruferin',
    {'Er scheint mir immer noch etwas wackelig auf den Beinen zu sein. Sein Kopf muss dröhnen.|n|nAm besten bringt Ihr ihn in den Tempel zur Erdenruferin und schaut, was sie für ihn tun kann.|n|nIch werde noch ein Weilchen hier draußen bleiben und diese Felsklauen "beobachten".', },
    {'Bringt Flint Erzmantel zu Erdenruferin Yevaa im Tempel der Erde.', },
  },
  [26414] = {
    'Einen Zander erwischen',
    {'Manchmal fische ich zum Spaß. Dann wieder, um zu entspannen, aber manchmal brauche ich eine Herausforderung. Da kommt der verhärtete Zander ins Spiel. Dieser wertvolle Fisch wird nicht als Speise gefangen, sondern wegen der Herausforderung. Ihr werdet den Zander im Sturmwindsee nördlich der Stadt finden. Glaubt Ihr, Ihr seid der Herausforderung gewachsen?', },
    {'Catherine Leland in Sturmwind möchte, dass Ihr ihr 8 verhärtete Zander bringt.', },
  },
  [26415] = {
    'Questflag für Logbuch des Kapitäns',
    nil,
    nil,
  },
  [26416] = {
    'Auf in den Dschungel',
    {'Mein Kommandant hat mich ausgeschickt, um nach Rekruten Ausschau zu halten, die bei der Verteidigung des Basislagers von Grom\'gol im Nördlichen Schlingendorntal helfen. Kennt Ihr das Schlingendorntal? Es ist sehr weit weg... Man muss das Große Meer überqueren, und dann befindet es sich an der südlichen Spitze der Östlichen Königreiche. Ihr passt auf die Beschreibung, die er mir gegeben hat... Seid Ihr daran interessiert, Kalimdor für eine Weile zu verlassen?|n|nWenn ja, sprecht mit meinem Kollegen Bort in Orgrimmar. Er wird Euch behilflich sein, an Bord des Zeppelins zu gehen.|n|nUnd sagt ihm von mir "Wusel-Dusel". Er weiß schon, was das bedeutet.', },
    {'Meldet Euch bei Bort in Orgrimmar.', },
  },
  [26417] = {
    'Das Nördliche Schlingendorntal: Das Gefallene Reich',
    {'Kommandant Aggro\'gosh sucht nach ergebenen Hordenmitgliedern, um ihm bei seiner Mission in Grom\'gol zu helfen. Wenn Ihr interessiert seid, geht einfach oben auf den Zeppelinturm und besteigt den Zeppelin nach Grom\'gol. So einfach ist das!|n|nIm Ernst, das Schlingendorntal ist momentan genau der richtige Aufenthaltsort... Dort gibt es reichlich Action und nicht annähernd so viel Schäden durch den Kataklysmus wie im... sagen wir... Steinkrallengebirge. Ich wünschte, ich könnte mit Euch kommen.', },
    {'Meldet Euch bei Kommandant Aggro\'gosh im Basislager Grom\'gol im Nördlichen Schlingendorntal.', },
  },
  [26418] = {
    'Der Panzer von Shadra',
    {'Wir müssen noch einen weiteren Teil finden und dann haben wir alles, was wir brauchen.|n|nDer Panzer von Shadra wird von der letzten lebenden Priesterin der Spinnengöttin bewacht, von Qiaga der Bewahrerin. Sie ist auf dem Altar von Zul und wird von anderen fanatischen Zeloten bewacht.|n|nEin Kinderspiel, oder? Steigt die Treppen des Altars hoch und lasst ihren Kopf die Treppen runter rollen. Bringt mir den Panzer und wir können Shadra endlich beschwören.', },
    {'Tötet Qiaga die Bewahrerin und bringt den Panzer von Shadra an Euch.', },
  },
  [26419] = {
    'Shadra, Königin des Giftes',
    {'<Der Boden wackelt als der Götze auf den Altar gesetzt wird und der See beginnt zu schäumen! Shadra erscheint!>', },
    {'Tötet Shadra die Königin des Giftes.', },
  },
  [26420] = {
    'Nach Würmern graben',
    {'He da, Angler! Arnold hier sagt, dass Ihr nach einem neuen Angelpunkt sucht und ich glaube, ich kenne genau den richtigen Ort. Nördlich von Sturmwind gibt es ein kleines Fleckchen Erde, das Olivias Teich heißt.|n|nDer Teich wird jedes Jahr mit neuen Kristallbarschen bestückt, aber sie sind schwer zu fangen. Sie beißen nur bei einem bestimmten Köder... Übergroße Regenwürmer. Wenn Ihr das Ufer des Teichs absucht, solltet Ihr ausreichend Würmer finden, die Ihr als Köder benutzen könnt.', },
    {'Findet einen übergroßen Regenwurm in der Nähe von Olivias Teich und benutzt ihn als Köder, um einen Kristallbarsch zu fangen. Kristallbarsche findet man in Olivias Teich, nördlich von Sturmwind.', },
  },
  [26421] = {
    'Der Hochtüftler',
    {'Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.|n|nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.', },
    {'Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.', },
  },
  [26422] = {
    'Der Hochtüftler',
    {'Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.|n|nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.', },
    {'Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.', },
  },
  [26423] = {
    'Der Hochtüftler',
    {'Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.|n|nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.', },
    {'Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.', },
  },
  [26424] = {
    'Der Hochtüftler',
    {'Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.|n|nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.', },
    {'Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.', },
  },
  [26425] = {
    'Der Hochtüftler',
    {'Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.|n|nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.', },
    {'Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.', },
  },
  [26426] = {
    'Ein grausamer Sturm',
    {'Es gibt eine Aufgabe, die ich Euch anvertrauen kann.|n|nEs ist eine gefährliche Aufgabe. Wenn Ihr sie erfüllt, könnt Ihr weitere der sturen Steinlords beeindrucken.|n|nIm Nordwesten findet Ihr den Geschliffenen Schlund. Harte Winde schlagen dort gegen die Felsen und verbergen die wahre lebende Bedrohung darunter.|n|nIn den Geschliffenen Weiten leben die Schleifwürmer. Sie fressen sich durch die Felsen, als wären sie aus Wasser. Dasselbe tun sie auch mit unserer Steinhaut.|n|nSucht Felsen den Ausdauernden. Er wird Euch sagen, wie Ihr in die Bruchtiefen gelangt. Ich werde mit Euch sprechen, sobald Ihr dort angelangt seid.', },
    {'Findet Felsen den Ausdauernden und folgt seinen Anweisungen, um in die Bruchtiefen zu gelangen.', },
  },
  [26427] = {
    'Ohne Kapitän oder Besatzung',
    {'Ich weiß nicht, zu wem Ihr gehört, aber Ihr seht nicht aus wie einer von… ihnen.|n|nIch weiß nicht, was geschehen ist. Ich habe das Abendessen verschlafen und bin dann auf einem Schiff voller Toter und Mörder aufgewacht.|n|nIch weiß nicht, ob Ihr mich töten wollt, aber ich erspare Euch die Mühe.|n|n<Mürrisch zeigt auf eine Wunde in seinem Bauch. Seine Innereien sind nicht mehr da, wo sie sein sollten.>|n|nIch kann das Schiff noch eine Weile steuern. Von einer Bauchwunde stirbt man nicht sofort. Bringt mir einfach ein Stück Seil und etwas Rum... nein, Whiskey.', },
    {'Bringt dem Ersten Maat Mürrisch eine Whiskeyflasche und eine Seilspule.', },
  },
  [26428] = {
    'Von Dieben stehlen',
    {'Die Hure! Das Flittchen! Kenata lebt noch; ihre Familie blüht und gedeiht, während ich leide. Verlassene, wahrhaftig!|n|nMeine Familie ist tot, Opfer der Seuche. Unser Besitz ebenfalls dahin, während des Kriegs geplündert und niedergebrannt. Und nach alldem haben sie und ihre lausigen Kinder die Stirn, das einzig Kostbare zu stehlen, das ich noch hatte.|n|nMir sind die Sachen, die sie gestohlen haben, längst einerlei. Ich will ihre Köpfe!|n|nTötet sie für mich! Geht zum Bauernhof der Dabyries in Arathi, nordöstlich der Zuflucht.', },
    {'Enthauptet Kenata Dabyrie, Fardel Dabyrie und Marcel Dabyrie.', },
  },
  [26429] = {
    'Zerschmettert die Bleichborken',
    {'Die Trolle der Bleichborken und die Felsfaustoger von Arathi arbeiten zusammen daran, uns von diesem Land zu vertreiben, aber unser Schicksal liegt weder in ihren noch in irgendwessen anderen Händen. Wir werden sie erledigen und ihnen zeigen, dass dies auch unsere Heimat ist. |n|nDie Trolle haben sich von uns abgewandt, die Oger würden uns als Nahrung und Bettvorleger benutzen, wenn wir es zuließen - das darf nicht sein.|n|nWir werden unseren Angriff auf die Trolle der Bleichborken südlich von hier beginnen. Erschlagt sie in Scharen und kehrt erst zurück, wenn ihre Lager dick mit Blut bedeckt sind.', },
    {'Tötet 10 Axtwerfer der Bleichborken, 10 Kopfjäger und 8 Hexendoktoren.', },
  },
  [26430] = {
    'Dorf der Bruchhauer',
    nil,
    {'Reist zum Dorf der Bruchhauer im Hinterland und sprecht mit dem Ältesten Stumpfhauer.', },
  },
  [26431] = {
    'Archäologie',
    {'Nehmt diese Quest an, um Archäologiepunkte auf Eurer Landkarte zu finden!', },
    {'Nehmt diese Quest an, um Archäologiepunkte auf Eurer Landkarte zu finden!', },
  },
  [26432] = {
    'Der Fall von Jintha\'Alor',
    {'Wir müssen uns um weit mehr kümmern, als nur Zwerge, Mann. Während ich das Dorf bewache, führt meine Freundin Ura Stumpfhauer unsere Krieger gegen den gemeinen Blutfratzenstamm.|n|nSie haben unsere Brüder getötet und ich wurde sogar einmal von ihnen gefangen genommen. Jetzt ist es genug! Dieses Mal fällt die Stadt Jintha\'Alor in unsere Hände.|n|nGeht nach Jintha\'Alor und sprecht mit meiner Freundin. Sie hat ein Lager nahe des Eingangs zur Stadt erobert.', },
    {'Findet Ura Stumpfhauer bei Jintha\'Alor im Hinterland.', },
  },
  [26433] = {
    'Das heilige Wasser der Klarheit',
    {'Skeezy hat schon gesagt, dass Ihr kommen würdet. Dann lasst uns dieses... Ding mal identifizieren.|n|nZunächst müsst Ihr das heilige Wasser der Klarheit besorgen. Die Naga im Südosten unterhalten einen heiligen Schrein, aus dem köstliches klares und pures Wasser fließt. Sobald man auch nur einen Schluck von diesem heiligen Wasser schlürft, wird der Geist geläutert und der beste Weg liegt dem Trinkenden klar vor Augen.|n|nHört sich gut an, nicht wahr?|n|nBeschafft es aus dem Nek\'maniquellbrunnen, der sich an dem höchsten Punkt des Nagacamps befindet. Viel Glück!', },
    {'Beschafft das heilige Wasser der Klarheit aus dem Nek\'maniquellbrunnen am Schlingendornkap.', },
  },
  [26434] = {
    'Ursprüngliche Reagenzien der Macht',
    {'Ich sehe es jetzt ganz deutlich... Der Schlüssel, um diesen mysteriösen Talisman zu identifizieren, liegt bei einigen sehr seltenen und wertvollen Gegenständen. Diese ursprünglichen Reagenzien der Macht werden uns den Ursprung des Schatzes enthüllen, wenn sie richtig kombiniert werden.|n|nReist nach Norden auf die Westseite der Arena der Gurubashi und jagt die Katzen, die den Dschungel durchstreifen. Ihre flauschigen Felle werden uns zur Wahrheit führen!', },
    {'Beschafft 4 geschmeidige Tigerinnenfelle und 4 samtige Pantherfelle.', },
  },
  [26435] = {
    'Ich bin ein gewaltiger Lügner und Betrüger',
    {'Ich habe keine Ahnung, was dieses Artefakt ist. Ich habe auch keine Ahnung, wo ich überhaupt ANFANGEN sollte, herauszufinden, was das ist.|n|nUm genau zu sein habe ich keine Ahnung, warum überhaupt jemand auf die Idee kam, dass ICH in der Lage sein könnte, es zu identifizieren.|n|nIch habe um Wasser gebeten, weil ich Durst hatte. Ich habe um Juwelen und Felle gebeten... nun, für meine Freundin.|n|nHoffentlich kann ich Euch wenigstens die richtige Richtung weisen. Garley Lichtreiter in Beutebucht ist ein Mitglied der Archäologischen Akademie und könnte möglicherweise hilfreicher sein, als ich es war.|n|nTut mir leid.', },
    {'Bringt die geöffnete Schatzkiste der Mosh\'Ogg zu Garley Lichtreiter in Beutebucht am Schlingendornkap.', },
  },
  [26436] = {
    nil,
    {'Eure Absichten scheinen ehrlich zu sein.|n|nIch werde den anderen Steinlords von meinem vorsichtigen Vertrauen erzählen.|n|nDanach sollten sie gewillt sein, mit Euch zu sprechen.|n|nUnd was noch wichtiger ist, sie sollten gewillt sein, zuzuhören.|n|nIhre Gunst zu erlangen, wird Zeit in Anspruch nehmen. Die Gunst der Steinmutter zu erringen, wird wohl noch länger dauern. Zeit ist ein wirksames Geschenk, geht also großzügig damit um.|n|nBei den Berstenden Säulen, weit im Nordwesten, findet ihr Kor den Unbeweglichen. Er hat ein ausgeglichenes Gemüt. Aufgrund seiner Lage ist er auf Hilfe von anderen angewiesen.|n|nGeht zu ihm.', },
    {'Findet Kor den Unbeweglichen bei den Berstenden Säulen.', },
  },
  [26437] = {
    'Kristallklar',
    {'Bei den Berstenden Säulen befinden sich Kristalle. Weiße, kalkhaltige Kristalle. Wir können diese Kristalle in unsere Haut absorbieren. Um uns zu reinigen. Uns zu läutern.|n|nIch wandle nicht mehr zwischen den Steinen. Ich bin eins mit der Erde. Das hat viele Vorteile, doch ich kann mir die Kristalle nicht mehr selbst beschaffen.|n|nBringt mir die Kristalle, so dass ich stärker werde. Nehmt sie den Felsklauen weg. Nehmt sie meinen Söhnen weg. Diese Ehre sollte nur mir vorbehalten sein.', },
    {'Sammelt 8 kalkhaltige Kristallformationen.', },
  },
  [26438] = {
    nil,
    {'Die Felsklauen sind wahnsinnig vor Hunger. Einst gruben sie mit Bedacht und Mäßigung. Jetzt ist ihr Hunger jedoch unersättlich. Sie sind blutrünstig und gewalttätig geworden.|n|nSie haben sich gegen meine Söhne gewandt. Sie überwältigen sie. Tötet sie. Es muss aufhören.|n|nTötet die Felsklauen. Sie erfüllen keinen Zweck auf dieser Welt. Niemand wird sie vermissen. Rettet meine Söhne. Tötet alle Felsklauen, die Ihr finden könnt.', },
    {'Tötet 12 Jaspisspitzenfelsklauen.', },
  },
  [26439] = {
    'Die Teile zusammenfügen',
    nil,
    {'Helft 6 schlafenden steingebundenen Elementaren dabei, sich neu zusammenzufügen.', },
  },
  [26440] = {
    nil,
    {'<Ein winziger Elementar scheint Gefallen an Euch gefunden zu haben.>|n|nKiris… Krissi… Kristall? <Kieselchen schaut Euch erwartungsvoll an.>|n|n<Erst jetzt bemerkt Ihr die riesige Kristallformation in der Mitte der Berstenden Säulen. Vielleicht solltet Ihr ihn dorthin bringen?>', },
    {'Bringt Kieselchen zur großen Kristallformation in den Berstenden Säulen.', },
  },
  [26441] = {
    'So groß, so rund…',
    {'<Kieselchen schaut sich um und scheint über etwas ganz aufgeregt zu sein. Nach ein paar Sekunden der Verwirrung bleibt er stehen und starrt Euch mit großen leuchtenden Edelsteinaugen an.>|n|nHug-nrig… Hungrig…|n|n<So sehr Ihr es auch versucht, gegen diesen Blick seid Ihr einfach machtlos. Vielleicht weiß Kor ja, was Mini-Elementare gerne essen.>', },
    {'Sprecht mit Kor, um herauszufinden, was Kieselchen gerne isst.', },
  },
  [26442] = {
    'Felshummer',
    {'Wenn ich meine Henkersmahlzeit selbst aussuchen könnte, dann würde ich mich auf jeden Fall für frische Hummerschwänze entscheiden. Irgendetwas an dem leckeren Krustentier ist unwiderstehlich! Vor Kurzem haben wir begonnen, Hummer hier in Sturmwind zu fangen. Würde es Euch etwas ausmachen, hinauszugehen und die Fallen für mich zu überprüfen?|n|nEins noch... Passt auf die Haie auf. Die können ziemlich grausam sein.', },
    {'Sammelt 6 Felshummer aus den Käfigen unter den Docks im Hafen von Sturmwind auf. Achtet auf Haie!', },
  },
  [26443] = {
    'Teuflische Pläne',
    {'Der Dämon hat dieses Pergament fallengelassen, das erstaunlicherweise in Gemeinsprache verfasst ist! Die darin erwähnten Namen, Diathorus und Gorgannon, gehören zwei berüchtigten Schreckenslords, die in dieser Gegend die Dämonen kontrollieren.|n|nDie Pläne beschreiben genau die Vorbereitungen auf einen Angriff der Dämonen auf Waldeslied im Norden. Das ist der Ort, an dem eine neue Siedlung der Draenei erbaut wird. |n|nMöglicherweise interessiert sich Verteidiger Vedaar am Holzfällerlager des Kriegshymnenklans hierfür?', },
    {'Liefert die teuflischen Pläne bei Verteidiger Vedaar am Holzfällerlager des Kriegshymnenklans in Eschental ab.', },
  },
  [26444] = {
    'Zerstört die Legion',
    {'Ich werde ihre Existenz in dieser Welt nicht dulden! Die Brennende Legion hat unser Volk so gut wie zerstört, und wir haben uns zurückgezogen, um in einer neuen Welt eine neue Heimat zu erschaffen. Dann kehrten sie zurück, und wir haben uns erneut zurückgezogen, wieder und wieder.|n|nNicht länger!|n|nIm Süden und im Westen befinden sich noch Überreste der Legion. Die Regionen heißen Dämonenhügel, Dämonensturz und Dämonenstieg. Das ist von der Streitmacht, die einst in diese Welt einfiel, noch übrig.|n|nGeht und vernichtet so viele von ihnen, wie möglich, bevor es zu spät ist!', },
    {'Tötet 15 beliebige Dämonen am Dämonenhügel, am Dämonensturz und am Dämonenstieg.', },
  },
  [26445] = {
    'Nie wieder!',
    {'$N, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Geht und erschlagt diese Schreckenslords. Ohne sie sind Dämonen nur ein Haufen geistloser Untiere.|n|nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.|n|nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz. Um dort hinaufzugelangen, sucht nach einem Stieg in der Nähe des Denkmals für Grom Höllschrei.|n|nBringt mir ihre Waffen.', },
    {'Besorgt Gorgannons flammende Klinge und den Teufelsspeer des Suchers.', },
  },
  [26446] = {
    'Die Rückeroberung des Dämonenhügels',
    {'Kleines Wesen. Im Südwesten gibt es ein Gebiet im Nachtweisenwald, das seit kurzer Zeit Dämonenhügel genannt wird. Es ist sehr traurig zu sehen, wie die Dämonen auf ihm herumkrabbeln und ihre Verderbnis verbreiten.|n|nIch habe ein paar Samen, die ich für eine solche Gelegenheit aufgehoben habe. Bringt sie zum Dämonenhügel und pflanzt sie in fruchtbare Erdhaufen.', },
    {'Pflanzt 8 Baumsetzlinge in die fruchtbaren Erdhaufen.', },
  },
  [26447] = {
    'Teuflische Pläne',
    {'Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise auf Orcisch geschrieben wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend anführen.|n|nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf den Splitterholzposten im Nordwesten.|n|nIhr seid Euch sicher, dass Valusha im Splitterholzposten daran interessiert ist.', },
    {'Bringt die teuflischen Pläne zu Valusha im Splitterholzposten im Eschental.', },
  },
  [26448] = {
    'Zerstört die Legion',
    {'Die Überreste der Brennenden Legion sind uns schon zu lang ein Dorn im Auge!|n|nEs ist an der Zeit, sie dafür bezahlen zu lassen!|n|nDie Dämonen greifen von den Gebieten im Osten, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind, an.|n|nGeht und zerstört so viele von ihnen, wie Ihr könnt, und erlangt Ruhm für Euch selbst und für die Horde!', },
    {'Tötet 15 beliebige Dämonen am Dämonenhügel, am Dämonensturz und am Dämonenstieg.', },
  },
  [26449] = {
    'Nie wieder!',
    {'$N, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Geht und erschlagt diese Schreckenslords. Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.|n|nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.|n|nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz.|n|nKehrt mit ihren Waffen als Beweis Eurer Taten zurück.', },
    {'Besorgt Gorgannons flammende Klinge und den Teufelsspeer des Suchers.', },
  },
  [26450] = {
    'Wenn sie sie einfach herumliegen lassen...',
    {'Mir kam gerade ein Gedanke, $N. Diese Naga haben mehr als nur Schilfrohr dort unten. Sie haben kleine Statuen auf ihren Schreinen im Sand unter den Bäumen herumliegen. Sie scheinen sie nicht zu benutzen.|n|nIch könnte diese Statuen gebrauchen. Ich könnte... sie überall im Lager aufstellen, damit es sich hier etwas heimeliger anfühlt. Alles ist besser als eine blutige Dinosaurierleichenpumpe. Ich könnte sie als Andenken verkaufen.|n|nIch könnte sie an die Naga zurückverkaufen!|n|nWarum holt Ihr nicht ein paar, während ich mir etwas ausdenke.', },
    {'Beschafft 6 Nagaikonen von der Südlichen Ungezähmten Küste am Schlingendornkap.', },
  },
  [26451] = {
    'Gurubashiherausforderung: Jeder gegen jeden in der Arena',
    {'Die Arena ist ein Kampfort wie kein anderer. Darin habt Ihr keine Freunde. Bündnisse, die eingegangen werden, sind kurzlebig und Eure Verbündeten können sich von einem Augenblick zum anderen gegen Euch wenden. Horde gegen Allianz, Allianz gegen Allianz, Horde gegen Horde - alles ist möglich.|n|nNehmt diese Schlachtstandarte, <Volk>, und platziert sie auf dem Arenaboden. Besiegt den herbeigerufenen Kämpfer und kehrt zu mir zurück.|n|nSeid jederzeit wachsam, <Volk>. In der Arena der Gurubashi ist alles möglich.', },
    {'Stellt die Herausforderungsflagge der Gurubashi in dem Kampfring ab und besiegt dann den Herausforderer der Arena der Gurubashi.', },
  },
  [26452] = {
    'Gurubashiherausforderung',
    {'Ihr seid zurückgekehrt, <Volk>. Das bedeutet, dass Ihr den Ruf der Arena erneut verspürt habt. Also gut.|n|nNehmt diese Schlachtstandarte, <Volk>, und platziert sie auf dem Arenaboden. Besiegt den herbeigerufenen Kämpfer und kehrt zu mir zurück.|n|nSeid jederzeit wachsam, <Volk>. In der Arena der Gurubashi ist alles möglich.', },
    {'Stellt die Herausforderungsflagge der Gurubashi in dem Kampfring ab und besiegt dann den Herausforderer der Arena der Gurubashi.', },
  },
  [26453] = {
    'Eine helfende Hand',
    {'Meine Leute haben im Osten des Eschentals mithilfe der Kaldorei eine wichtige Entdeckung gemacht.|n|nUnter der Aufsicht von Architekt Nemos und Verteidiger Vedaar erneuern sie einen alten elfischen Außenposten. Der Wiederaufbau wird nicht leicht werden, $N, denn sie stehen vielen Herausforderungen und Feinden gegenüber. Ich weiß, dass Architekt Nemos und seine Landsleute in Waldeslied jede Hilfe, die sie bekommen können, zu schätzen wissen, und er hat mich gebeten, $Gjeden Mann, der:jede Frau; die; Interesse hat, zu ihm zu schicken.|n|nSprecht mich erneut an und ich werde dafür sorgen, dass Ihr schnell zu ihrer Stellung gebracht werdet.', },
    {'Geht nach Waldeslied im Eschental und sprecht mit Architekt Nemos.|n|nVerteidigerin Palanaar kann Euch ein Reittier anbieten, um schneller dorthin zu gelangen.', },
  },
  [26454] = {
    'Eine schändliche Verschwendung',
    {'Willkommen in Waldeslied, $C. Wo Ihr jetzt noch Zelte seht, werden einst Gebäude stehen, aber dieses Ziel erfordert einen ständigen Nachschub an Baumaterial. Ich bringe es nicht übers Herz, unseren Arbeitern zu befehlen, die uralten Bäume dieses Hains zu fällen, aber unsere Nachbarn im Süden und Westen haben keine so große Ehrfurcht vor dem Wald.|n|nWir werden das verdorbene Holz aus der Festung der Satyrn im Westen zurückfordern. Bringt das Holz zu Knorre im Holzfällerlager des Kriegshymnenklans. Er ist ein Urtum, der es für unsere Zwecke reinigen wird.', },
    {'Sammelt 5 Stück verdorbenes Satyrnaarholz.', },
  },
  [26455] = {
    'Elunes Kelch',
    {'Das Gebiet westlich von hier, das nun Satyrnaar heißt, war einst ein bedeutender Schrein meines Volkes. Dort befand sich ein Relikt von unschätzbarem Wert, Elunes Kelch, der den Hütern des Schreins von den Priestern Elunes anvertraut wurde. Einst reisten Pilger zu dem Schrein, um die heilenden Kräfte, die dem Kelch nachgesagt wurden, am eigenen Leib zu erfahren.|n|nVielleicht sind diese Geschichten nur Ammenmärchen, aber wenn nur ein Körnchen Wahrheit in ihnen steckt, könnte der Kelch vielleicht der Schlüssel zur Wiederherstellung unseres leidenden Waldes sein. Ich muss es wissen, $N.', },
    {'Bringt Elunes Kelch in Euren Besitz.', },
  },
  [26456] = {
    'Bericht von der Nordfront',
    {'Die Schlacht gegen das Holzfällerlager des Kriegshymnenklans wird nicht nur vom Rajenbaumturm aus geführt, $N. Eine beträchtliche Anzahl von Schildwachen der Silberschwingen hat sich im Hain der Silberschwingen im Südosten, in der Nähe der Grenze zum Brachland, postiert. Schildwache Weltensang ist für unsere Bemühungen gegen die, die unser Land zerstören wollen, verantwortlich.|n|nIch bin mit meinem Bericht an Schildwache Weltensang etwas spät dran, möchte aber den Turm nur ungern unbewacht lassen. Wenn Eure Reisen Euch in die Nähe des Silberschwingenhains bringen, könntet Ihr dann meinen Bericht abgeben?', },
    {'Bringt Schildwache Melyrias Bericht zu Schildwache Weltensang im Hain der Silberschwingen im Eschental.', },
  },
  [26457] = {
    'Agenten der Zerstörung',
    {'Das Holzfällerlager des Kriegshymnenklans ist ein Schandfleck in unserer Landschaft. Wann immer wir Fortschritte dabei machen, ihre Arbeiten zu stoppen, befiehlt Vorarbeiter Gorthak seinen Holzarbeitern, ihre Anstrengungen noch zu verdoppeln!|n|nJetzt fällen die Orcs mehr Holz, als sie je verbrauchen können und lassen es verrotten, während ihre Klingen schon wieder in frisches Holz schlagen! Dies ist eine Beleidigung gegenüber allem, für das wir einstehen, $N, und wir werden ihnen zeigen, dass wir uns eine weitere Zerstörung unseres Landes nicht gefallen lassen!|n|nGeht, und ruht nicht, bevor Vorarbeiter Gorthak und seine Lakaien tot sind!', },
    {'Tötet Vorarbeiter Gorthak und 12 weitere, beliebige Mitglieder der Horde im Holzfällerlager des Kriegshymnenklans.', },
  },
  [26458] = {
    'Die Stunde der Finsternis',
    {'Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder des Schattenhammerklans, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.|n|nWir glauben, dass der Schattenhammerklan sich mit den Naga verbündet hat und sie sich in der Tiefschwarzen Grotte zusammenrotten.|n|nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.|n|nFührt Krieg gegen den Schattenhammerklan und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.', },
    {'Bringt 10 Zwielichtanhänger zu Schildwache Aluwyn am Stützpunkt an der Grotte.', },
  },
  [26459] = {
    'Erforschung der Verderbnis',
    {'Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?|n|nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.|n|nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. In der Tiefschwarzen Grotte unweit von hier im Westen werdet Ihr sowohl Satyrn als auch Naga finden.', },
    {'Relwyn Schattenstern im Stützpunkt an der Grotte möchte 8 verderbte Hirnstämme.', },
  },
  [26460] = {
    'Auf der Suche nach Thaelrid',
    {'Heutzutage kursieren viele Gerüchte über die Vereinigung des Schattenhammers mit den Naga in der Tiefschwarzen Grotte im Westen.|n|nMeine Rolle hier besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.|n|nEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Tiefschwarzen Grotte auszuspähen. Späher Thaelrid hat sich noch nicht zurückgemeldet.|n|nMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.|n|nSucht nach Thaelrid für mich, $N.', },
    {'Sucht Späher Thaelrid in der Tiefschwarzen Grotte auf.', },
  },
  [26461] = {
    'Schurkerei in der Tiefschwarzen Grotte',
    {'Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!|n|nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.|n|nAku\'mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.|n|nDie Kultisten des Schattenhammers haben sich mit den Naga verschworen, um diese Anlage zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku\'mai, um Macht zu erlangen.|n|nBitte, erschlagt Kelris und bringt Ashelan im Stützpunkt an der Grotte seinen Kopf, $N.', },
    {'Bringt den Kopf von Zwielichtfürst Kelris zu Ashelan Nordwald im Stützpunkt an der Grotte.', },
  },
  [26462] = {
    'Die bösen Bruchhauer',
    {'Die Trolle der Bruchhauer meinen etwas Besonderes zu sein, weil sie Teil der Horde sind. Da kann ich nur lachen!|n|nWisst Ihr, das wirklich Witzige ist, dass es egal ist, ob sie der Horde angehören oder nicht, ob sie ein Trollimperium besitzen oder die Brennende Legion selbst sind. Wir haben Trolle in diesen Ländern seit Urzeiten bekämpft.|n|nUm genau zu sein werde ich Euch dabei sogar helfen lassen, $GJunge:Mädchen;! Nehmt Euch eine Waffe und begebt Euch zum Schlachtfeld, um unsere Jungs östlich von hier zu unterstützen.', },
    {'Tötet 10 Pirscher der Bruchhauer oder Verhexer der Bruchhauer.', },
  },
  [26463] = {
    'Findet Teronis',
    nil,
    {'Sucht am Falathimsee im Eschental nach Teronis.', },
  },
  [26464] = {
    'Der verlorene Stein',
    {'Während Ihr Teronis\' Habseligkeiten durchstöbert, stoßt Ihr auf ein durchnässtes Tagebuch.|n|nIhr blättert schnell durch die letzten noch lesbaren Seiten und lest, dass Teronis erwähnt, wie er den Edelstein gefunden hat, ihn dann aber in der Umgebung des Falathimsees verloren hat.|n|nJetzt müsst Ihr nur noch eines tun: den Edelstein finden. Vielleicht haben ihn die Tentakel...', },
    {'Findet den leuchtenden Edelstein.', },
  },
  [26465] = {
    'Die antiken Statuetten',
    {'Ich möchte Euch mit einer Aufgabe betrauen, $C.|n|nIch war auf meinem Boot und dümpelte über die versunkenen Ruinen von Zoram, als Naga mich angriffen. Sie sprangen aus dem Wasser und griffen mit ihren Klauen nach mir! Ich flüchtete, und der Rest ist - wie man so schön sagt - Geschichte.|n|nIch bin eine Art Archäologe und ich versuche, die Artefakte der verlorenen Stadt wiederzufinden.|n|nWürdet Ihr Euch hinaus zum Zoramstrand im Südwesten begeben und alle antiken Statuetten, die Ihr finden könnt, bergen? Sie sind der Grund, dass ich den Gefahren des Zoramstrandes getrotzt habe.', },
    {'Besorgt 10 antike Statuetten.', },
  },
  [26466] = {
    nil,
    {'Ich fürchte, die Geheimnisse der antiken Statuetten werden für immer verborgen bleiben, wenn Ihr nicht den Schlüssel zu ihren antiken Schlössern findet.|n|nDieser Schlüssel ist ein Ring, der Ring von Zoram. Er gehörte einst den Herrschern dieser Stadt, bevor sie in den Wellen der Großen Zerschlagung unterging.|n|nÜber Jahre hinweg war der Ring verloren, aber die Naga haben ihn vor Kurzem gefunden.|n|nRuuzel, ihre Anführerin, haust auf einer Insel am nördlichen Ende des Zoramstrands. Bitte, $N, beschafft mir den Ring!', },
    {'Nehmt den Ring von Zoram an Euch.', },
  },
  [26467] = {
    'Elende Satyrn! Die Dryaden sind in Gefahr!',
    {'Ich weiß zwar nicht, wer Ihr seid, aber ich brauche Eure Hilfe. Meine Schwestern wollten den Satyrn den Zweig des Cenarius abnehmen. Sie sagten, dass sie bald zurück sein werden, aber das war vor zwei vollen Tagen!|n|n$N, Ihr müsst sie finden! Sie wollten nach den Ruinen eines Nachtelfentempels in Xavian im Nordwesten suchen. Ich weiß nicht, was ich davon halten soll. Sucht nach Anilia, sie wollte sie bei der Suche führen.', },
    {'Sucht in Xavian im Eschental nach Anilia.', },
  },
  [26468] = {
    'Der Zweig des Cenarius',
    {'Anilia legt Euch die Hände auf die Schultern und zieht Euch zu sich heran. Nach Luft ringend zeigt sie in Richtung des Bogens im Norden, bevor sich ihre Augen schließen und sie einen letzten, keuchenden Atemzug ausstößt. "Er hat ihn... Geltharis..." In Eurem Herzen wisst Ihr, dass es Anilias letzter Wunsch war, den Zweig des Cenarius wieder in den Händen der Dryaden zu sehen.', },
    {'Erhaltet den Zweig des Cenarius.', },
  },
  [26469] = {
    'Satyrn schlachten!',
    {'Ich kann nicht glauben, dass Anilia von uns gegangen ist... Wir haben doch immer zusammen in den Wäldern gespielt. Ich fühle beinahe so etwas wie... Trauer.|n|nEs gibt aber etwas, das mich vielleicht aufheitern könnte! Bitte, erschlagt die Satyrn, die mir Anilia genommen haben! Bringt mir ihre Hörner als Beweis Eurer Taten und Ihr könnt Euch auf ewig meines Dankes gewiss sein.', },
    {'Erhaltet 16 Satyrhörner.', },
  },
  [26470] = {
    'Die Rückeroberung des Mystralsees',
    {'Wir hätten die Silberwindzuflucht ohne Weiteres gegen den Ansturm der Horde halten können, wenn sie uns nicht die Kontrolle über unsere Wasserelementarverteidiger im Mystralsee entrissen hätten.|n|nEiner ihrer Schamanen hat Tideress heraufbeschworen, einen alten, wütenden Wassergeist des Waldes, der unsere Elementare besudelt und gegen uns aufgebracht hat. Da sowohl der See als auch die Horde über uns hereingebrochen sind, hatten wir keine andere Wahl, als uns hierher zur Spitze zurückzuziehen.|n|nBegebt Euch nach Osten. Erobert den See zurück, sodass eine Chance besteht, dass wir eines Tages die Zuflucht wieder einnehmen können.', },
    {'Tötet 12 beschmutzte Wasserelementare und Tideress.', },
  },
  [26471] = {
    'Wissen in der Tiefe',
    {'Wie Ihr vielleicht wisst, trage ich Lehren zusammen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die schlafenden Alten Götter erwecken können.|n|nEs kursieren Gerüchte um einen alten Text, das \'Manuskript von Lorgalis\', das sich tief unten in der Tiefschwarzen Grotte im Westen. Dieser Ort ist die ehemalige Heimat unserer längst verstorbenen Ahnen. Elfen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.|n|nSucht in der Tiefschwarzen Grotte nach dem Manuskript. Wenn Ihr das tut, werde ich Euch das nie vergessen. Auch nicht... nach dem Ende aller Tage.', },
    {'Bringt das \'Manuskript von Lorgalis\' zu Schildwachenschülerin Issara zum Stützpunkt an der Grotte.', },
  },
  [26472] = {
    'Irrsinnige Druiden',
    {'Die Druiden sind tot. Ihre Anführer haben sie getötet - sie wurden von der Horde, die das Herz des Waldes verderben, in den Wahnsinn getrieben. Ich kann die Verderbnis sogar von hier spüren und wage es nicht, weiterzugehen.|n|nIch stehe zu sehr im Einklang mit Eschental und dem Herz des Waldes - aber Ihr... Ihr könntet in den Grabhügel hinabsteigen und das tun, was getan werden muss. Ich habe dort eine Spur für Euch gelegt.|n|nObwohl es mir das Herz zerreißt, muss ich Euch darum bitten, die einstmals großartigen Anführer der Druiden zur ewigen Ruhe zu betten: Taneel Finsterwald, Uthil Mondweise und Mavoris Wolkenbruch.', },
    {'Tötet die irrsinnigen Druiden: Taneel Finsterwald, Uthil Mondweise und Mavoris Wolkenbruch.', },
  },
  [26473] = {
    'Bathranshaar',
    {'In den alten Ruinen von Bathrans Schlupfwinkel, der sich auf der anderen Seite der Straße im Osten befindet, wächst eine Pflanze. Diese Pflanze heißt Bathranshaar und man sagt ihr nach, dass sie Leiden des Geistes heilen kann.|n|nJetzt erntet die Horde diese Pflanze für ihre eigenen, finsteren Pläne.|n|nIn Astranaar befindet sich ein krankes Kind. Wir glauben, dass seine Krankheit nicht nur körperlicher Natur ist. Ich habe meinem Herrn versprochen, dass ich helfen werde, ein Heilmittel zu suchen, aber ich bin kein Kämpfer. |n|nWürdet Ihr zu Bathrans Schlupfwinkel gehen und die Pflanzen sammeln?', },
    {'Sammelt 8 Büschel Bathranshaar.', },
  },
  [26474] = {
    'Orendils Heilung',
    {'$N, nun da es von Elunes gesegnetem Licht durchflutet wurde, glaube ich, dass das Gebräu dem kranken Kind helfen wird. Bitte bringt es nach Astranaar und gebt es dem Vater des Kindes, Pelturas Weißmond.|n|nUm nach Astranaar zu gelangen, folgt ihr der Straße nach Süden und dann nach Osten. Wenn Ihr aber schneller dorthin gelangen wollt, sprecht mit Schildwache Avana.', },
    {'Bringt Orendils Heilung zu Pelturas Weißmond in Astranaar im Eschental.', },
  },
  [26475] = {
    'Elunes Träne',
    {'Ich hatte gehofft, Orendils Heilmittel würde Relara retten, aber ich fürchte, es hat die Krankheit, die in meinem Kind wütet, nur gedämpft. Wir müssen eine stärkere Medizin finden! Zum Glück hat mir Orendil von weiteren Arzneien erzählt, sollte seine Erste versagen.|n|nElunes Träne ist eine Gesteinsart, die nur an einem Ort vorkommt: den Überresten des Irissees, der durch den Ausbruch des Donnergipfels nordöstlich von Astranaar zerstört worden ist. Orendil sagte, der Stein könne Verderbnis wegwaschen.|n|nBitte, $N, bringt mir eine Träne Elunes und betet, dass sich die Erkrankung meiner Tochter damit heilen lässt!', },
    {'Erhaltet eine Träne Elunes.', },
  },
  [26476] = {
    'Dryadenlieferung',
    {'Ah, da seid Ihr ja, $N. Ich habe mich in die Anmerkungen vertieft, die Teronis gemacht hat, und es sieht so aus, als ist Euer nächster Schritt, die Teile von Dartols Rute zu finden.|n|nIch würde zunächst nach Osten reisen, zum Rajenbaumturm.|n|nDort findet Ihr eine Dryade namens Shael\'dryn, die Euch eine bessere Führerin sein wird. Sucht sie auf.|n|nBehaltet den Edelstein bei Euch - Shael\'dryn wird ihn brauchen, um Euch bei der Wiederherstellung der Rute zu helfen.', },
    {'Liefert den leuchtenden Edelstein bei Shael\'dryn beim Rajenbaumturm im Eschental ab.', },
  },
  [26477] = {
    'Durchsucht den Baumstamm',
    {'Ich wünschte, Ihr hättet bessere Nachrichten.|n|nRaene hat Recht, ich weiß von Dartols Werk und den Treants, den Baumwesen in diesem Gebiet - zumindest wusste ich es einst. Heute sind sie verderbt, ihre Natur verzerrt.|n|nFalls es Euer Ziel ist, das nächste Teil der Rute zu finden, solltet Ihr zunächst den Schlüssel suchen, mit dem die Truhe geöffnet werden kann, in der es sich befindet.|n|nEiner der Treants nordöstlich von hier in der Nähe des Teufelswalds hat ihn. Sobald Ihr ihn habt, sucht nach einem kleinen Tal westlich der Straße nahe der Grenze zum Teufelswald am Heulenden Tal. Wenn Ihr es gefunden habt, sucht nach einer kleinen Lichtung hinter dem Tunnel in diesem Tal. Die Truhe ist dort irgendwo versteckt.', },
    {'Sucht den hölzernen Schlüssel und benutzt ihn, um den Eisenschaft von Dartols Rute zu finden.', },
  },
  [26478] = {
    'Sich tot stellen',
    nil,
    {'Erhaltet das letzte Teil von Dartols Rute, den Eisenschwertknauf.', },
  },
  [26479] = {
    'Rückkehr zu Raene',
    {'Ich schlage vor, dass Ihr Raene aufsucht und sie wissen lasst, dass die Rute fertiggestellt ist. Sie weiß bestimmt, was Ihr als Nächstes tun solltet.|n|nSeid vorsichtig damit... ich spüre eine große Macht darin, zum Guten wie auch zum Bösen. Ich hoffe nur, dass Raene und Ihr wisst, was Ihr tut.|n|nViel Glück, $N.', },
    {'Liefert Dartols Rute bei Raene Wolfsläufer in Astranaar im Eschental ab.', },
  },
  [26480] = {
    'Dartols Rute',
    {'Leider bin ich mir nicht ganz sicher, was er als Nächstes vorhatte.|n|nWenn es wahr ist, was er über die Macht der Rute sagte, könnt Ihr mit ihrer Hilfe eine völlig andere Gestalt annehmen, vermutlich die eines Furbolgs.|n|nVielleicht wollte er ihre Kräfte nutzen, um näher an die besudelten Furbolgs heranzukommen, aber selbst die nicht verderbten Kreaturen hätten ihn getötet, wäre er nicht vorsichtig gewesen. Durch die Rute verwandelt, hätte Dartol wahrscheinlich mit einem Furbolg gesprochen, der noch unverderbt war.|n|nIch würde meine Suche bei dem Furbolg beginnen, der als Krolg bekannt ist. Sucht nach seiner Hütte südöstlich vom Mystralsee.', },
    nil,
  },
  [26481] = {
    'Eine neue Verzierung',
    {'Ich bin mir sicher, dass der seit langem tote Zauberer Dartol diese Rute dazu benutzen wollte, uns zu unterwerfen und zu zerstören, genauso wie es die Nachtelfen und Orcs versucht haben. Jetzt aber werden wir dieses Ding einem unvorhergesehenen Zweck zuführen.|n|nRan Blutreißer ist König über alle Furbolgs im Eschental. Sein Stamm, die Blutreißer, sind am mächtigsten und grenzen sich in einem Lager im Osten ab.|n|nTötet sie alle und bringt mir seinen Schädel. Wollen wir doch einmal sehen, ob wir nicht einen guten Verwendungszweck dafür finden können.', },
    {'Erhaltet Ran Blutreißers Schädel und Dartols Rute.', },
  },
  [26482] = {
    'Die wahre Macht der Rute',
    {'Nehmt jetzt die Rute und sprecht, während Ihr unter ihrem Effekt steht, mit meinem Bruder Ota Wen.|n|nOta ist bei den anderen Furbolgs, die von den Orcs gefangen genommen und in den riesigen Käfig nördlich der Silberwindzuflucht gesperrt worden sind. Die Rute wird es Euch erlauben, Ota und die anderen Furbolgs dazu zu bringen, sich gegen die Horde aufzulehnen.|n|nDanach dürft Ihr Eures Weges ziehen. Wisst nur, dass Ihr mit Euren Taten einen neuen Freund gefunden habt.', },
    {'Benutzt Dartols Rute und sprecht mit Ota Wen. Überzeugt ihn, sich gegen die Unterdrücker der Horde aufzulehnen. Bringt dann Dartols Rute zu Raene Wolfsläufer.', },
  },
  [26483] = {
    nil,
    {'So viel Spaß es ja auch macht, die Trolle auf die Hörner zu nehmen, wir haben hier unten noch anders zu tun. Es wäre doch schöner, diesen Kampf endlich zu beenden, nicht wahr?|n|nIhr Kommandant, Gan\'dranda, sitzt zwischen den eingestürzten Mauern im Südosten des Schlachtfelds. Unsere Jungs sind zum größten Teil unabkömmlich, also möchte ich, dass Ihr Euch dort hinschleicht und Gan\'dranda beseitigt. Wenn sie dort sehen, wie $Gein:eine:r; <Volk> über der Leiche ihres größten Helden steht, sollte ihnen das den Schneid abkaufen.', },
    {'Tötet Gan\'dranda.', },
  },
  [26484] = {
    'Hilfe für Steinruh',
    {'Die Irdenen und die Steintroggs haben vor mehr als fünfzehntausend Jahren einen Weg durch Uldum nach Tiefenheim gefunden. Seitdem befinden sie sich im Krieg.|n|nWenn wir das mittlere Fragment der Weltensäule wiedererlangen wollen, muss der Steinvater gerettet werden.|n|nBitte geht nach Steinruh und tut alles, was in Eurer Macht steht, um den Irdenen im Kampf gegen die Steintroggs zu helfen.|n|nIhr seid unsere größte Hoffnung, $N.', },
    {'Sprecht mit Spalt Steinbrecher in Steinruh in Tiefenheim.', },
  },
  [26485] = {
    'Schnappkiefer, Bursche!',
    {'Ich habe mir vorgenommen, für diese lästigen Trolle etwas ganz Besonderes zusammenzubrauen. Ja, ich sagte für sie... ein Gebräu, das sie niemals vergessen werden! Nach dem Genuss dieses Gebräus werden sie ihre Hauer aus den Abhängen sammeln können.|n|nEinige Zutaten weiche ich hier bereits ein, aber ich könnte Hilfe dabei gebrauchen, noch mehr zu beschaffen. Am Fuße der Aussichtsklippen im Osten in der Nähe des Ufers sind eine ganze Menge Schnappkiefer. Ich brauche frische, intakte Muskelmägen für mein Kawummbräu.', },
    {'Beschafft 8 Schnappkiefermuskelmägen von Salzwasserschnappkiefern.', },
  },
  [26486] = {
    '99 Flaschen Wein am Strand',
    {'Ich weiß ja, dass hier ein kleiner Kampf tobt, aber unten an diesen Aussichtsklippen sind überall Flaschen verteilt, die sehr verführerisch aussehen. Ich kann nicht zulassen, dass so ein gutes Tröpfchen der Horde in die Finger fällt!|n|nWenn Ihr zufällig dort vorbeikommt, dann sammelt die Flaschen für mich ein und bringt sie her. Ich werde Euch dafür bezahlen, als hättet Ihr sie selbst abgefüllt.', },
    {'Sammelt 12 Flaschen mit Pupellyverbos\' Portwein.', },
  },
  [26487] = {
    'Bündelweise Akiris',
    {'Es ist nicht einfach, eine Kombination aus 5-Sterne-Exotikhotel und Verwertungsanlage für Dschungelmaterial zu führen! Zumindest wäre es nicht einfach, wenn ich nicht das Organisationstalent der persönlichen Assistentin eines Handelsprinzen hätte!|n|nDer erste Trick ist, mehrere Dinge auf einmal zu erledigen. Zum Beispiel: Die Forscher der Naga im Süden tragen wertvolles Seeschilf bei sich, Akiris. Wir können dieses Schilf an unsere Kunden in Übersee verkaufen und gleichzeitig die Matratzen unserer Kunden damit polstern! Wenn ich so darüber nachdenke, könnten wir es sicher auch für andere Zwecke verwenden.', },
    {'Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.', },
  },
  [26488] = {
    'Ein großer Schluck',
    nil,
    {'Fischt einen königlichen Seeteufel aus dem Burggraben im Tal der Helden in Sturmwind. Wenn Ihr einen Seeteufel angelt, filetiert ihn und seht nach, ob er das Medaillon verschluckt hat.', },
  },
  [26489] = {
    'Ihr hier?!',
    {'Ja, wie kann ich Euch…|n|n<Sassy fällt die Kinnlade herunter.>|n|n$N! Seid Ihr das wirklich?! Wie groß und stark Ihr geworden seid! Lasst mich mal Euren Bizeps fühlen.|n|nIch? Ich habe versucht, hier im Dschungel ein wenig Gold zu scheffeln. Wir sind hauptsächlich in der Materialbeschaffung tätig, aber auch im Tourismus.|n|nIch weiß, genial, oder?|n|nHe, hört mal. Da fällt mir gerade was ein. Die Forscher der Naga im Süden tragen wertvolles Akirisschilf bei sich, das wir verkaufen und gleichzeitig als Polsterung für unsere Gästematratzen verwenden können. Habt Ihr Lust, ein paar Naga zu töten? Es wäre ganz wie in alten Zeiten!', },
    {'Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.', },
  },
  [26490] = {
    'Erstklassiger Schleim',
    {'Nicht viele Zwerge wissen das, aber um meinem Gebräu noch einen richtigen Schub zu verleihen, füge ich noch ein wenig von dem Schlamm hier aus der Gegend hinzu. Ja, von den riesigen, grünen, zwergenfressenden Schlammhaufen.|n|nDieses Gebräu braucht allerdings einen RIESIGEN Extraschub, also brauchen wir einen großen Schlamm! Im Lauerfels befindet sich die Mutter aller Schlamme, sie ist wirklich riesig... Wir nennen sie den Terrorhaufen.|n|nWenn Ihr das Zeug dazu habt, geht dorthin und bringt mir einen Brocken von dem Terrorklumpen!', },
    {'Beschafft eine Terrorklumpenprobe vom Terrorklumpen.', },
  },
  [26491] = {
    'Den Lauerfels aufräumen',
    nil,
    nil,
  },
  [26492] = {
    'Lauerfelsvorräte',
    {'Ich hatte einen Cousin, der im Zweiten Krieg gekämpft hat! Er hat mir immer davon erzählt, dass sie einen Schlachtzug gegen Lauerfels geführt haben. Sie sind dort hineingestürmt und haben die Trolle wie Ratten aus ihrem Nest vertrieben. Sie haben sie den ganzen Weg bis nach Alterac gejagt!|n|nKurz darauf haben die Schleime Einzug gehalten, aber dort drin gibt es immer noch ganze Kisten voller Waren der Horde. Ich sage, wir lassen nicht zu, dass die Trolle sich das zurückholen!|n|nBringt mir einige Kisten vom Lauerfels im Nordwesten.', },
    {'Sammelt 5 schlammbedeckte Vorratskisten ein.', },
  },
  [26493] = {
    'Jemand dort draußen will es haben',
    {'Also, da Ihr ohnehin schon von der Erledigung der ganzen anderen Sachen schwitzt, dachte ich, Ihr könntet noch eine Aufgabe für mich erledigen. Das macht Euch doch nichts aus, oder?|n|nDas neueste Wissenschafts- und Explosionsjournal ist gerade aus Bilgewasserhafen eingetroffen und darin ist dieser Artikel über dieses heiße, neue Reagenz. Die Preise für dieses Reagenz schießen in den Himmel und wir haben beste Voraussetzungen, daraus Kapital zu schlagen!|n|n<Sassy beugt sich zu Euch und flüstert Euch die Einzelheiten ins Ohr.>|n|nVerstanden? Gut. Ihr findet die Basilisken in einer Höhle, weit im Osten.', },
    {'Beschafft 7 Einheiten von Sassys Geheimzutat von Donnerschwanz- und Eisenkieferbasilisken in der Kristalladermine.', },
  },
  [26494] = {
    'Mischmeister Jasper',
    {'Würde es Euch etwas ausmachen, ein bisschen von dem Zeug hier Jasper zu bringen? Er ist bei den luxuriösen Wohnungen. Ich bin sicher, er wird dafür Verwendung haben.|n|nDanke, $N!', },
    {'Bringt Sassys Proben zu Mischmeister Jasper in Hartzangs Versteck.', },
  },
  [26495] = {
    nil,
    {'Chabal, der Troll drüben am botanischen Garten/biologischen Waffenlabor, ist ein ganz besonderer Gast. Er ist ein Repräsentant der Zandalari-Trolle und hat eine weite Reise hinter sich, um bei uns zu sein.|n|n<Sassy packt einige der Gegenstände, die Ihr gesammelt habt, in ein kleines Paket und übergibt es Euch.>|n|nHier, gebt ihm das. Sagt ihm, dass die Zandalari in Hartzangs Versteck immer willkommen sind. Und erwähnt, dass Empfehlungen der Schlüssel zur Aufrechterhaltung unserer Geschäftsbeziehungen sind!', },
    {'Bringt Sassys großzügige Gabe zu Chabal in Hartzangs Versteck.', },
  },
  [26496] = {
    'Nieder mit den Blutfratzen',
    {'Die Bruchhauer sind nicht der einzige Stamm schändlicher Trolle, um die wir uns kümmern müssen! Die Blutfratzen haben dieses Land seit Jahren aus ihrer Festung Jintha\'Alor heraus verdorben.|n|nWir sitzen nicht länger am Nistgipfel und drehen Däumchen, falls es Euch entgangen sein sollte. Doran Stahlschwing führt den Sturmangriff gegen die Blutfratzen von einem Lager im Süden, das die Jungs gerade eingenommen haben. Sprecht mit ihm und schließt Euch dem Kampf an!', },
    {'Findet Doran Stahlschwing bei Jintha\'Alor im Hinterland.', },
  },
  [26497] = {
    'Blutfratzenabschaum',
    {'Die Blutfratzen sind ein anderer Stamm als die Bruchhauer, aber die Unterschiede sind kaum wahrnehmbar. Soweit es uns betrifft ist nur ein toter Troll eine guter Troll!|n|nAber täuscht Euch nicht, die Blutfratzen sind auch ohne die Ketten der Horde um ihre Hälse ausgesprochen bösartig. Sie werden das ganze Land vergiften, wenn wir uns nicht erheben und sie loswerden.|n|nIhr könnt mit ihren Hexendoktoren und Kopfjägern auf der unteren Etage beginnen. Sagt mir Bescheid, wenn Ihr eine ansehnliche Zahl von ihnen vernichtet habt.', },
    {'Tötet 5 Hexendoktoren der Blutfratzen und 5 Kopfjäger der Blutfratzen in Jintha\'Alor.', },
  },
  [26498] = {
    'Tod den Blutfratzen',
    {'Wir machen gute Fortschritte. Rückt weiter vor und lasst nicht nach!|n|nDie Berserker der Blutfratzen kämpfen wie wilde Tiere und peitschen sich in einen wahren Blutrausch. Ihre Schattenzauberer rufen widerwärtige Geister aus dem Jenseits herbei. Das ist der Grund, warum wir uns dieser verdorbenen Kreaturen entledigen, $N, vergesst das nicht.|n|nBegebt Euch auf die mittlere Stufe und tötet Berserker und Schattenzauberer!', },
    {'Tötet 5 Berserker der Blutfratzen und 5 Schattenzauberer der Blutfratzen in Jintha\'Alor.', },
  },
  [26499] = {
    'Der Segen des Steinvaters',
    {'Solange der Steinvater gefangen gehalten wird, ist die Moral meiner Truppen am Boden. Normalerweise nimmt es jeder von meinen Leuten mit mindestens fünf Steintroggs auf einmal auf. Aber jetzt…|n|nGeht hinaus auf das Feld um das Dorf herum. Stellt Steinvater Erzmantels Banner in der Nähe meiner Verteidiger auf. Schenkt ihnen seinen Segen und erinnert sie daran, wofür sie kämpfen.', },
    {'Gewährt 12 Irdenen Verteidigern den Segen des Steinvaters.', },
  },
  [26500] = {
    'Wir sind umzingelt',
    {'Unser Krieg tobte schon, bevor die Zeitrechnung Eures Volkes begann. Mal sehen, ob Ihr etwas verändern könnt, <Volk>.|n|nDie Steintroggs sind ein Fehler der Titanen. Auf Eurer Welt sind sie dem Fluch des Fleisches erlegen. Doch hier in Tiefenheim seht Ihr sie in ihrer wahren Gestalt.|n|nWir sind hier umzingelt. Warum geht Ihr nicht hinaus und zertrümmert ein paar Troggs für uns? Seht Euch an, was in ihnen steckt.', },
    {'Tötet 12 Wegelagerer der Steintroggs.', },
  },
  [26501] = {
    'Versiegelung des Eingangs',
    {'Den Steintroggs ist es gelungen, sich unter unseren Häusern nach oben zu graben!|n|nIch habe Geomanten ausgesandt, die alle Gebäude versiegeln sollen. Sie benötigen jedoch Reagenzien und genügend Zeit außerhalb des Kampfes, um ihre Felssturzrituale zu vollenden.|n|nMeldet Euch bei General Kies Langfels, wenn Ihr fertig seid. Ihr findet ihn gen Norden an der Zerrissenen Front.', },
    {'Helft den Irdenen Geomanten, sich aus dem Kampfgeschehen auszuklinken und gebt ihnen dann die Felssturzreagenzien, damit sie das Rüstlager, das Gasthaus, die Baracken und den Schrein versiegeln können.', },
  },
  [26502] = {
    'Donnersteine',
    {'Die Zerrissene Front liegt im Norden. Dort finden die schwersten Gefechte statt.|n|nBegebt Euch ins eigentliche Steinruh und besorgt so viele Donnersteine, wie Ihr könnt. Unsere Ingenieure benötigen sie für die Katapulte.|n|nBringt sie zu Klei Lehmachse, wenn Ihr genug gefunden habt. Stört Euch nicht an seinem Ton. Er ist alt und griesgrämig und hätte schon vor Tausenden von Jahren in die Erde zurückkehren sollen.', },
    {'Besorgt 12 Donnersteine.', },
  },
  [26503] = {
    'Weitere Einschätzung der Gefahr',
    {'Diese verdammten, wertlosen Gnolle führen nichts Gutes im Schilde. Ich spüre es in meinen Knochen. Die Gnollaktivität hat sich in den letzten zwei Wochen verdreifacht. Ich befürchte, dass sie einen Angriff auf Seenhain vorbereiten.|n|nIch möchte, dass Ihr die Lager der Gnolle in dieser Gegend aufsucht und dort alle Informationen sammelt, die Ihr finden könnt. Durchsucht die Lager unmittelbar nördlich von hier, östlich von hier und südöstlich von hier. Bringt mit, was Ihr dort findet.', },
    {'Stehlt die Schlachtpläne der Gnolle, die Befehle der Gnolle und den Strategieführer der Gnolle.', },
  },
  [26504] = {
    'Gesucht: Rotkammgnolle',
    {'Auf Befehl der Königswache von Sturmwind sollen alle Gnolle in dem Drei Ecken genannten Gebiet in der südwestlichen Ecke des Rotkammgebirges getötet werden.|n|nWenn Ihr die Gnolle in dieser Gegend beseitigt habt, dann meldet Euren Sieg Wachhauptmann Parker an der Turmwacht.', },
    {'Tötet 15 beliebige Rotkammgnolle in der Drei Ecken genannten Gegend des Rotkammgebirges.', },
  },
  [26505] = {
    'Parkers Bericht',
    {'<Wachhauptmann Parker händigt Euch einen Bericht aus.>|n|nHier ist er, $N. Bringt meinen Bericht nach Seenhain nördlich dieses Turms und übergebt ihn Magistrat Solomon. Erklärt ihm, dass wir eine umfassendere Lösung für den Umgang mit den Gnollen benötigen. Schlagt Sprengstoff vor. Viel Sprengstoff.|n|nUnd bleibt auf der Straße, wenn Ihr wisst, was gut für Euch ist. Zu überleben ist gut für Euch, nebenbei bemerkt. Falls Ihr Euch gefragt hattet, was gut für Euch ist. Jetzt wisst Ihr es... Ach, vergesst es!', },
    {'Bringt Parkers Bericht zu Magistrat Solomon nach Seenhain im Rotkammgebirge.', },
  },
  [26506] = {
    'Würstchen mit Bohnen',
    {'Ich brauche Eure Hilfe, <Volk>! Unsere Rationen sind verbraucht und die Wachen werden hungrig. Sie sehnen sich nach meinen weltberühmten Würstchen mit Bohnen, aber mir fehlen die Zutaten. Seid ein Schatz und helft mir, bitte.|n|nIch brauche ein paar Geiferzahnnieren, Kondorinnereien und TarantelaugenI. Ihr findet Greiferzähne, Kondore und Taranteln nahe dieses Turms. Seht Euch nur um!', },
    {'Besorgt 4 Tarantelaugen, 4 Kondorinnereien und 4 Geiferzahnnieren.', },
  },
  [26507] = {
    'Versteinerte Delikatessen',
    {'Versteinerte Fledermäuse.|n|nElementare dieser Größe sind wählerisch. So leicht werdet Ihr nichts Besseres finden.|n|nIm Osten gibt es Basilisken. Sie lassen Steinfledermäuse zu Stein werden, die ihnen zu nahe kommen und essen sie als Zwischenmahlzeit. Ihr solltet Fledermäuse in ihrem Territorium finden.|n|nIch muss Euch jedoch warnen... wenn Ihr diesem kleinen Elementar zu viel Aufmerksamkeit schenkt, werdet Ihr ihn möglicherweise nie wieder los. Er kann sehr aufmerksamkeitsbedürftig sein.', },
    {'Besorgt 12 erstarrte Steinfledermäuse für Kieselchen.', },
  },
  [26508] = {
    'Nidas Halskette',
    {'Meine Freundin Nida hat ihre Halskette verloren. Wir finden sie nicht mehr. Wir haben den ganzen Tag hier geangelt und auch schon die Umgebung abgesucht. Ich befürchte, dass sie in den See gefallen ist. Unsere Eltern wollen nicht, dass wir im See schwimmen gehen... meine Mama sagt, Unterwasser gäbe es fiese Wesen, aber Ihr seht nicht aus, als ob Ihr Angst vor fiesen Wesen hättet.|n|nKönntet Ihr die Kette für Nida finden, bitte?', },
    {'Findet Nidas Halskette.', },
  },
  [26509] = {
    'Ein ungebetener Gast',
    {'Mein Garten ist schon wieder zertrampelt und verwüstet worden. Und ich weiß genau, was für ein Tier das getan hat. Das war dieser elende Eber, der, den Marschall Marris seit einer Weile immer Stopfwanst nennt.|n|nJetzt kann ich die Narzissen erst nächsten Herbst wieder anpflanzen. Hin! Alle hin, und das nur wegen dieses einen gefährlichen Ebers. Bereitet dieser Plage ein Ende! Zeigt mir seinen Hauer und ich werde Euch nur zu gern belohnen. Die meiste Zeit scheint er damit zu verbringen, in den Feldern südwestlich von Seenhain nach Futter zu suchen, doch gelegentlich verirrt er sich auch hierher und in meinen Garten.', },
    {'Tötet Stopfwanst und nehmt Stopfwansts Hauer an Euch.', },
  },
  [26510] = {
    'Wir müssen uns vorbereiten!',
    {'Jeden Tag verschwinden weitere Bürger. Wir glauben, dass die Gnolle dafür verantwortlich sind, aber wir wissen nicht, wo sie unsere Bürger hinbringen! Wenn Ihr uns helfen wollt, die Gnolle zu besiegen und unsere Bürger zu finden, müsst Ihr ordentlich ausgerüstet sein. Leider haben wir keine Gnomcorder mehr. Ohne einen Gnomcorder können wir während Eures Einsatzes nicht mit Euch kommunizieren.|n|nUnseren letzten funktionstüchtigen Gnomcorder haben die Murlocs letzte Woche bei einem Überfall gestohlen. Begebt Euch östlich von hier zum Immerruhsee und bringt ihn an Euch!', },
    {'Findet den Gnomcorder.', },
  },
  [26511] = {
    'Säuberung des Immerruhsees',
    {'Auf dem Weg zum Immerruhsee? Es wird Euch sicher freuen, dass wir gerade eine Belohnung auf Murlocs ausgesetzt haben. Tötet so viele Ihr könnt, dann wird man Euch belohnen. Es ist egal, welche Murlocs. Tötet sie einfach wahllos.|n|nDer Immerruhsee liegt genau östlich von Seenhain. Es ist der See. Ist Wasser drin... Kommt Euch das bekannt vor?', },
    {'Tötet 10 beliebige Murlocs im Immerruhsee.', },
  },
  [26512] = {
    'Einstellung des Gnomcorders',
    {'Der Gnomcorder scheint zu funktionieren. Ich habe ihn Euch angelegt, aber wir müssen noch die Empfangsfrequenz einstellen.|n|nVerlasst Seenhain in Richtung Norden und folgt der Straße bis zum Friedhof. Wenn Ihr am Friedhof angekommen seid, versuche ich zu senden.', },
    {'Geht zum Friedhof von Seenhain, um die Frequenz des Gnomcorders einzustellen.', },
  },
  [26513] = {
    'Wie ein Furz im Wind',
    {'Wir wurden letzte Nacht überfallen oder war es die Nacht davor? Ich weiß es nicht mehr genau. Seit drei Tagen kriege ich kein Auge zu. Wahrscheinlich verliere ich schon den Verstand.|n|nGnolle haben unsere Vorratslager geplündert. Alles haben sie mitgenommen! Rein und raus, lautlos wie ein Furz im Wind! Meine Soldaten sahen sie zu den Schluchten nordwestlich von hier laufen. Bringt unsere Vorräte zurück, $C!', },
    {'Bergt 8 Vorratskisten des Rotkammgebirges.', },
  },
  [26514] = {
    'Schluchtenspringen',
    {'<Der Gnomcorder summt.>|n|nAls erstes steht ein flotter Marsch durch die Rotkammschlucht direkt im Norden von Seenhain an. Tötet jeden Gnom, den Ihr seht... huch, habe ich Gnom gesagt? Ich meinte Gnoll. Tötet jeden GNOLL, den Ihr seht und nehmt ihnen zum Beweis Eurer Tat das Halsband ab.|n|nEine Warnung, $N; hütet Euch dort draußen vor den Ettins. Meine Kundschafter haben in letzter Zeit riesige blutdürstige Ettins in den Schluchten gesehen. Geht ihnen aus dem Weg, wenn Ihr weiterleben wollt.|n|nSolomon Ende. Ich melde mich.', },
    {'Sammelt 10 Halsbänder der Rotkammgnolle.', },
  },
  [26515] = {
    'Ongo\'longos Rache',
    {'Ich hab vor, Troll auf Troll zu hetzen.|n|nDie Blutfratzen halten einen miesen, alten Terrortroll in einer Grube gefangen. Seine Ketten sehen nicht sehr stabil aus. Ich weiß, wie so ein Unhold kämpft. Sie werden ihn nicht halten können, wenn er richtig wütend wird und loslegt.|n|nFindet den Terrortroll und kämpft gegen ihn, $N. Bringt ihn nicht um... schlagt nur ein wenig auf ihn ein, bis er rot sieht und ausbricht. Dann geht ihm aus dem Weg. Der wird den Blutfratzen ordentlich Beine machen.', },
    {'Kämpft gegen Ongo\'longo, bis er seine Ketten sprengt.', },
  },
  [26516] = {
    'Das gehört jetzt uns',
    {'Nur die stärksten und bösartigsten Blutfratzen sind übrig geblieben. Die Seelenfresser und Bluttrinker, die verkommenen Anhänger des bösen Gottes Hakkar.|n|nDenkt daran, dass Ihr hier nicht nur gegen Trolle kämpft, $N. Ihr kämpft gegen dunkle und böse Kräfte, die dieses Land zu Asche verbrennen werden, wenn wir sie leben lassen!|n|nZeigt keine Gnade!', },
    {'Tötet 5 Bluttrinker der Blutfratzen und 5 Seelenfresser der Blutfratzen in Jintha\'Alor.', },
  },
  [26517] = {
    'Schicksalsgipfel',
    {'Geht jetzt zum Gipfel, $N. Unsere Krieger wagen sich nur bis zu den letzten Toren vor. Sie sagen, dort es sei still wie in einem Grab; kein Geräusch, kein Atemzug, nichts rührt sich.|n|nSie halten es für eine Falle, aber das, was Ihr mir gebracht habt, lässt mich befürchten, dass etwas weit Böseres dort lauert. Geht zum Altar, findet heraus, was geschehen ist... und bringt mir ALLE mystischen Gegenstände oder dunklen Götzen, die Ihr dort findet! Habt Ihr mich verstanden?', },
    {'Sammelt 8 Spinnengötzen der Blutfratzen auf dem Gipfel von Jintha\'Alor.', },
  },
  [26518] = {
    'Kopfprämie',
    {'Es gibt kaum einen größeren Troll als Umboda Dreikopf. Er ist ein grausamer Schlächter, der die Köpfe von Zwergen und Trollen sammelt! Wird langsam Zeit, dass er bekommt, was er verdient.|n|nFindet den großen Schläger auf den unteren Terrassen und kommt mit seinem Kopf zurück!', },
    {'Besiegt Umboda Dreikopf und holt Euch seinen Kopf.', },
  },
  [26519] = {
    'Wer die Ettins beherrscht',
    {'Ihr seid über ein Dokument der Gnolle gestolpert. Der Gnoll, von dem diese Propaganda stammt, kann ein wenig schreiben:|n|nBRÜDER VON JAULER, HÖRT SCHMUTZPRANKE AN! ORCS GEBEN SCHMUTZPRANKE KUGEL! SCHMUTZPRANKE BEHERRSCHT ETTIN-VIECHER! SCHMUTZPRANKE ZERMALMT MENSCHIES! HOLT EUCH SCHMUTZPRANKES PRANK-O-GRAPH IN DEN RETHBANHÖHLEN. HÖHLE IM WESTEN, IN SCHLUCHT VERSTECKT!|n|n<Die Unterschrift besteht aus einem Prankenabdruck.>|n|n<Anscheinend hat jemand auch ein Stück aus der Schriftrolle gebissen.>|n|nIhr solltet dem vielleicht nachgehen.', },
    {'Tötet Ardo Schmutzpranke.', },
  },
  [26520] = {
    'Rettet Großknecht Oslow',
    nil,
    {'Benutzt die Ettinsteuerungskugel, um einen Ettin zu unterwerfen. Setzt die Ettinsteuerungskugel dann bei Eurem gebändigten Schluchtettin ein und bringt ihn dazu, Großknecht Oslow in Seenhain von dem riesigen Felsbrocken zu befreien.', },
  },
  [26521] = {
    'Gesichter des Bösen',
    {'Die Blutfratzen haben ihre Tikimasken überall in Jintha\'Alor an die Mauern gehangen. Wir werden ihre widerlichen Zauber und ihre dunkle Magie nicht dulden.|n|nDiese Botschaft werden wir ihnen überbringen und gleichzeitig ihre Abwehr durchbrechen! Nehmt diese Fackel, $C. Zündet ihre Tikimasken an und lasst sie brennen. Wenn ihre dunklen Idole zu Asche zerfallen, werden sie erkennen, dass sie den Wildhämmern nicht willkommen sind!', },
    {'Zündet mit der Tikifackel 8 Tikimasken in Jintha\'Alor an.', },
  },
  [26522] = {
    'Gesichter des Bösen',
    {'Die Blutfratzen haben ihre Tikimasken überall in Jintha\'Alor an die Mauern gehangen. Die Geister werden nicht mehr lange über sie wachen.|n|nNehmt die Fackel und kämpft Euch durch die Blutfratzen, $C. Zündet ihre Tikimasken an. Ich werd zusehen, wie ihre Abwehr- und Schutzzauber vergehen und ihr ketzerischer dunkler Voodoo in Rauch aufgeht.', },
    {'Zündet mit der Tikifackel 8 Tikimasken in Jintha\'Alor an.', },
  },
  [26523] = {
    'Alles, was krabbelt',
    {'Da oben hab ich noch was bemerkt... Jintha\'Alor ist voller Spinnen. Kleine, nicht größer als Eure Hand. Nicht ungewöhnlich für das Hinterland, aber etwas daran ist seltsam.|n|nIch vertraue den Trollen nicht, wenn sie Haustiere halten. Sie haben was vor. Bringt mir ein paar dieser Spinnen. Haltet sie am Leben, wenn es geht, dann werden wir sehen, was mir die Geister zu erzählen haben...', },
    {'Sammelt 8 huschende Spinnlinge in Jintha\'Alor.', },
  },
  [26524] = {
    'Dunkle Gefäße',
    {'Die Blutfratzentrolle hier beten seit jeher den verderbten Gott Hakkar, Loa des Blutes, an. Er war ein krankes, pervertiertes Wesen. Vor langer Zeit wäre er beinahe in unsere Welt vorgedrungen, konnte jedoch besiegt werden.|n|nDie Blutfratzen rühren immer noch in ihren dunklen Kesseln, die sie vor Jahren mit Blut gefüllt haben. Entweder hoffen sie auf einen längst verstorbenen Geist oder sie haben einen neuen, ebenso düsteren Plan.|n|nBesorgt mir diese Gefäße, $N. Wir müssen sie gemeinsam mit den Spinnen untersuchen, um zu verstehen, was hier vorgeht!', },
    {'Besorgt 5 Gefäße mit besudeltem Blut aus Jintha\'Alor.', },
  },
  [26525] = {
    'Giftige Geheimnisse',
    {'Wenn das Opfer bereits vollbracht wurde, wird Shadra diese Welt langsam vergiften. In der Höhle wimmelt es wahrscheinlich schon von ihrer Brut.|n|nLasst sie nicht entkommen, $N. Bringt alle Spinnen um, die Ihr finden könnt!', },
    {'Tötet 8 Bruten von Shadra.', },
  },
  [26526] = {
    'Jagt die Bewahrerin',
    {'Shadra, die Spinnenloa... die Königin des Giftes, ein Geist der Dunkelheit und des Todes! Wenn es ein Opfer gegeben hat, werden die Trolle einen letzten verzweifelten Versuch unternehmen, um sie heraufzubeschwören.|n|n Sollten die Blutfratzen Rituale begonnen haben, dürfen sie nicht vollendet werden.|n|nÜberprüft die Höhle hinter dem Altar an der Spitze von Jintha\'Alor. In ihrem Inneren verbirgt sich vielleicht noch eine von Shadras Bewahrerinnen. Tötet sie und bringt mir, was sie bei sich trägt, damit wir herausfinden können, was dort los ist.', },
    {'Tötet Morta\'gya die Bewahrerin und bringt die Tafel von Shadra an Euch.', },
  },
  [26527] = {
    'Greifenmeister Krallenaxt',
    {'Ich würde diese Tafel in Stücke schlagen, wenn ich das Recht dazu hätte. Doch diese Entscheidung darf ich nicht fällen. Greifenmeister Krallenaxt muss sie sehen.|n|nKehrt mit der Tafel zum Nistgipfel zurück. Greifenmeister Krallenaxt kümmert sich im Greifenhorst um die Tiere.|n|nBeeilt Euch... aber lasst die Tafel bloß nicht aus den Augen!', },
    {'Bringt die Tafel von Shadra zu Greifenmeister Krallenaxt.', },
  },
  [26528] = {
    'Das Auge von Shadra',
    {'Greifenmeister Krallenaxt hat mich hierher geschickt, damit ich mich um Shadra, die Königin des Giftes, kümmere. Jintha\'Alor zu erobern, ist nicht genug... die Trolle könnten sich neu formieren und die Kreatur zu einem späteren Zeitpunkt beschwören, wenn wir es am wenigsten erwarten.|n|nZuerst sammeln wir die Artefakte, dann holen wir Shadra unter unseren eigenen Bedingungen in diese Welt. Wir werden die verdorbene Kreatur mit unseren Hämmern vernichten. Ihr müsst dabei helfen, die Artefakte zu finden, und wenn Ihr schon dabei seid, dann fügt den restlichen Trollen ordentlich Schaden zu.|n|nDazu benötigen wir zuerst das Auge von Shadra, das in Agol\'watha im Norden bewacht wird.', },
    {'Besorgt das Auge von Shadra aus Agol\'watha.', },
  },
  [26529] = {
    'Der Fangzahn von Shadra',
    {'Als nächstes brauchen wir den Fangzahn von Shadra.|n|nShadras eigene Brut bewacht ihn in den Gruselruinen im Osten. Abscheuliche Spinnen, groß wie Zwerge und doppelt so stark. Ihr Gift ist stark, $N... seid nicht nachlässig.', },
    {'Besorgt den Fangzahn von Shadra aus den Gruselruinen.', },
  },
  [26530] = {
    'Der Panzer von Shadra',
    {'Wir brauchen nur noch dieses letzte Stück, um Shadra endgültig auszuräuchern.|n|nDer Panzer von Shadra befindet sich im Besitz von Quiaga der Bewahrerin, der letzten Hohepriesterin der Spinnengöttin. Sie hält sich an der Spitze des Altars von Zul auf und wird von anderen fanatischen Zeloten bewacht.|n|nErklimmt den Altar bis zur Spitze und vernichtet sie. Sie wird den Panzer bei sich tragen. Bringt ihn hierher.', },
    {'Tötet Qiaga die Bewahrerin und bringt den Panzer von Shadra an Euch.', },
  },
  [26531] = {
    'Die Beschwörung von Shadra',
    {'Unsere besten Kämpfer stehen bereit, das Idol wurde zusammengesetzt... es ist soweit, $N.|n|nWir werden wie folgt vorgehen. Ihr reist mit dem Idol uns voran in Richtung Südwesten, nach Shadra\'Alor. Ihr müsst das Idol an allen drei Tempeln einsetzen und Euch durch die Trolle, die sie bewachen, kämpfen.|n|nWenn Ihr das getan habt, wird Shadra in unsere Welt eindringen. Wir erwarten sie mit Zorn in unseren Herzen. Sagt meinen Jungs in Eurer Nähe Bescheid, sobald Ihr das Ritual vollendet habt.', },
    {'Benutzt den Götzen von Shadra am nordwestlichen, südwestlichen und östlichen Tempel in Shadra\'Alor.', },
  },
  [26532] = {
    'Shadra, Königin des Giftes',
    {'Keine Zeit verschwenden, $N! Sie kommt schon aus dem Wasser!|n|nGreifenmeister Krallenaxt ist bereits mit den Jungs unterwegs. Zeigen wir es dem Achtbein!', },
    {'Tötet Shadra die Königin des Giftes.', },
  },
  [26533] = {
    'Zanzils Geheimnis',
    {'Vor vielen Jahren verstießen die Gurubashi einen der ihren aus Zul\'Gurub: Einen Troll namens Zanzil. Die Gründe dafür sind unklar, aber ich nehme an, dass es mit den starken, verhaltensverändernden Drogen zusammenhing, die er jedem, dem er begegnete, verabreichte. Wie dem auch sei, die Priester der Gurubashi und ihr Blutgott sind vernichtet worden, aber Zanzil der Ausgestoßene existiert noch...|n|n...ebenso wie seine starken, verhaltensverändernden Drogen.|n|nIch würde sie gern in die Finger bekommen, <Volk>. Überprüft die Zombies im Südosten.', },
    {'Beschafft 5 Phiolen mit Zanzils Mixtur.', },
  },
  [26534] = {
    'Was hast du zu bieten, Zanzil?',
    {'Besucher von Hartzangs Versteck müssen bei ihrer Ankunft einige Verzichtserklärungen unterschreiben. Eine davon erlaubt es uns, einfache Tests an ihnen vorzunehmen. Diese Klausel werden wir wohl wieder aktivieren.|n|nDoch dieses Mal sollten wir versuchen, unsere Kunden nicht zu vergiften. Ist besser fürs Geschäft.|n|n<Jasper füllt eine Karaffe mit Zanzils Mixtur und gestoßenem Eis.>|n|nDer südöstliche Turm des Verstecks dient als provisorisches Gefängnis. Wir nennen es "Hartzangs Zuchthaus". Lasst die Gefangenen trinken und sagt mir, was passiert.', },
    {'Bietet Jaspers Dschungelschorle Gmurgl, Orgus und Kapitän Bartholomäus Weichbart an.', },
  },
  [26535] = {
    'Zutaten für eine Katastrophe',
    {'Ich brauche Zanzils Rezept mehr als je zuvor. Einer von Zanzils Lakaien in den Ruinen von Aboraz müsste es haben. Reist nach Osten, zur anderen Küste des Kaps und stehlt es für mich!', },
    {'Beschafft Zanzils Rezeptur von einem seiner Anhänger in den Ruinen von Aboraz.', },
  },
  [26536] = {
    'Donnerfälle',
    {'Arnold und ich angeln schon seit Jahren in der Gegend um Sturmwind. So lange braucht man, um eine gute Stelle zu finden. Einer meiner Lieblingsorte wird Donnerfälle genannt.|n|nEr liegt südlich von Sturmwind im Wald von Elwynn. Das Beste an den Donnerfällen ist der violette Flussbarsch. Man findet ihn nur dort oben an den Wasserfällen. Arnold und mir fällt der lange Weg in letzter Zeit schwer, deshalb möchte ich Euch bitten, für uns dorthin zu gehen und einige Barsche zu fangen.', },
    {'Fangt 4 violette Flussbarsche bei den Donnerfällen südlich von Sturmwind. Kehrt mit Eurem Fang zu Catherine Leland zurück.', },
  },
  [26537] = {
    'Zerschmettert sie!',
    {'Geht hinaus und erledigt sie für mich.|n|nBerserker, Erdberster, Todesreiter... mir egal! Zerschmettert diese Steintroggs!', },
    {'Tötet 12 beliebige Steintroggs an der Zerrissenen Front.', },
  },
  [26538] = {
    'Soforthilfe',
    {'Viele unserer Krieger sind bei dem Zwielichtangriff auf unsere Luftflotte gefallen. Die Überlebenden schwimmen den Überresten der Flotte entgegen. Sie bluten und haben schwere Verbrennungen erlitten. Ich brauche Unterstützung vom Ufer, um diese Männer zu retten!|n|nIm Hafen des Drachenmals wird es doch wohl einen Arzt oder Medizinmann geben, der gewillt ist, anderen Orcs zu helfen. Geht ans Ufer und versucht, Heilvorräte aufzutreiben und zur Flotte zu bringen!', },
    {'Sucht einen Medizinmann im Hafen des Drachenmals, nahe des Ufers.', },
  },
  [26539] = {
    'Festgefahrene Verhandlungen',
    {'Der Aufenthaltsort des Kriegshäuptlings ist unbekannt! Aber sein Plan muss fortgeführt werden. $N, Ihr seht aus wie jemand, der weiß, was er tut.|n|nUnsere Verhandlungen mit dem Drachenmalklan sind festgefahren. Ihr Kriegshäuptling ist... anders als erwartet. Sorgt dafür, dass die Verhandlungen fortgeführt werden.|n|nTrefft Euch mit Ornak am Ufer. Er wird Euch alles erklären.|n|nRedet mit Horzog hier an Deck. Er wird für einen raschen Transport zum Ufer sorgen.', },
    {'Sprecht mit Ornak im Hafen des Drachenmals. Horzog wird für einen raschen Transport zum Ufer sorgen.', },
  },
  [26540] = {
    'Gefährliches Mitleid',
    {'Der rote Drachenschwarm stellt den Aspekt des Lebens dar. Deshalb hat sein Blut heilende Wirkung.|n|nDie Verbände in dieser Kiste wurden in rotes Drachenblut getränkt. Das sind meine letzten Vorräte. Mögen sich Eure Krieger dank ihnen rasch erholen.|n|nEs ist egal, wie Eure Verhandlungen hier ausgehen, Ihr werdet immer Freunde im Drachenmalklan haben.', },
    {'Bringt die Kiste mit Bandagen des Drachenmals zurück zu Kriegsfürst Krogg auf See vor dem Hafen des Drachenmals.', },
  },
  [26542] = {
    'Heldenaufruf: Das Hinterland!',
    nil,
    {'Reist zum Nistgipfel im Hinterland und sprecht mit Greifenmeister Krallenaxt.', },
  },
  [26543] = {
    'Muscheln meucheln',
    {'Nichts schmeckt so gut wie frisches monströses Muschelfleisch, $N. In den letzten Wochen hatte ich so viel zu tun, dass ich keine Zeit hatte, mich zu den örtlichen Muschelgründen zu begeben. Könntet Ihr mir vielleicht einige dieser Delikatessen besorgen?|n|nIhr findet die Muscheln in der Nähe des Strandes an der Ostküste von Durotar. Rund um den Hafen von Orgrimmar sollte es jede Menge geben.', },
    {'Besorgt 10 Stücke Fleisch einer monströsen Muschel von den Muscheln an der Ostküste Durotars, südlich von Orgrimmar. Kehrt danach zu Razgar zurück.', },
  },
  [26544] = {
    'Sie werden schlauer...',
    {'<Der Gnomcorder kracht und knackt.>|n|nDie Schwarzfelsorcs scheinen doch noch klug zu werden. Man hat mir gemeldet, dass sie sich mit den Gnollen verbündet haben und einen Angriff planen, Ich brauche Einzelheiten. $N!|n|nÜberprüft die Rethbanhöhlen im westlichen Teil der Rotkammschlucht für mich. Sucht nach Orcs mit dunkler Haut. Tötet alle, denen Ihr begegnet und durchsucht ihre Leichen nach Informationen.|n|nSolomon Ende.', },
    {'Besorgt das Sendschreiben der Orcs des Schwarzfelsklans.', },
  },
  [26545] = {
    'Jauler muss sterben!',
    {'<Der Gnomcorder summt.>|n|nIhr müsst Jauler finden, $N. Er hält sich irgendwo im nördlichen Teil der Rotkammschlucht auf. Tötet den räudigen Hund und durchsucht seine Leiche nach den Invasionsplänen des Schwarzfelsklans. Sollte das gelingen, bringt die Pläne zu mir in das Rathaus von Seenhain.|n|nSolomon Ende.', },
    {'Tötet Jauler und bergt die Invasionspläne des Schwarzfelsklans.', },
  },
  [26546] = {
    'Klingenschnabelfreunde',
    {'Für unseren Klan sind Greifen heilige Tiere. Wir verehren sie. Es sind majestätische Himmelswesen, mehr als nur Tiere. Sie sind intelligent und listig.|n|nManche behaupten, wir würden sie halten, aber es ist eher wie eine Freundschaft. Wenn Ihr Euch mit den Wildhämmern anfreunden wollt, dann freundet Euch zuerst mit unseren Greifen an! Nehmt diesen Futtersack. Alles darin ist frisch und gut. Ihr findet unsere ausgebildeten Klingenschnabelgreifen in den Wäldern südlich des Greifenhorsts. Würdet Ihr einige von ihnen für mich füttern?', },
    {'Füttert 7 ausgebildete Klingenschnabelgreifen mit dem Greifenfutter.', },
  },
  [26547] = {
    'Räudige Bedrohung',
    {'Wir beschützen unser Volk und unsere Greifen mit allen Mitteln. Dazu gehört, dass wir Räuber verjagen, und zwar die aus dem Wald und die der Horde.|n|nErst einmal werde ich Euch noch nicht bitten, uns vor den zweibeinigen Ungeheuern zu schützen. Räudige Silbermähnen streunen durch die Wälder im Süden. Sie attackieren die Greifen, die zu niedrig fliegen. Jagt einige Silbermähnen, damit sie erkennen, dass Greifen keine Beute sind.', },
    {'Tötet 8 räudige Silbermähnen.', },
  },
  [26548] = {
    'Auf zur Front',
    {'Wir benötigen Eure Hilfe nun in dringenderen Angelegenheiten, $N.|n|nDie Horde wird dort draußen immer dreister. Sie sind in unserer Territorium eingedrungen und greifen uns hemmungslos an. Die Waldtrolle der Bruchhauer attackieren den Sturmfederaußenposten sogar bei Tage!|n|nIch brauche Eure Hilfe. Sprecht draußen mit Guthrum Donnerfaust. Er wird Euch einen Greifen zum Sturmfederaußenposten geben. Kerr Eisenblick wird Euch alles erklären, wenn Ihr dort eintrefft.', },
    {'Sprecht mit Kerr Eisenblick im Sturmfederaußenposten.', },
  },
  [26549] = {
    nil,
    {'Unsere letzten beiden Verhandlungsführer sind von den Gesprächen mit dem Kriegshäuptling des Drachenmalklans noch nicht zurückgekehrt. Ich glaube, wir müssen unsere Muskeln spielen lassen.|n|nDeshalb möchte ich, dass IHR dieses Mal den Unterhändler begleitet. Ihr Kriegshäuptling wird seine Haltung vielleicht ändern, wenn er erkennt, dass die Horde voll von kampferprobten Helden wie Euch ist.|n|nIhr müsst den Unterhändler nur in das Hauptlager im Hafen des Drachenmals begleiten und bedrohlich aussehen.', },
    {'Begleitet den Hordenunterhändler in den Hauptsaal im Hafen des Drachenmals und trefft Euch mit Kriegshäuptling Mor\'ghor vom Drachenmalklan. Sprecht mit Ornak an der Küste, sollte Euch der Unterhändler abhanden kommen.', },
  },
  [26550] = {
    'Durch die Hintertür',
    {'Zanzil der Ausgestoßene, der vom Gurubashistamm verbannt wurde, soll meine Beute werden. Vor kurzem habe ich von meinen Brüdern im Norden erfahren, dass er in die Gesellschaft zurückkehren will. Aus diesem Grund hat er einen Abgesandten zu den Schädelspaltern geschickt. Das sind keine guten Nachrichten.|n|nIch möchte, dass Ihr Euch Zanzils Pläne einmal anseht. Nehmt diesen Weihrauch und stellt ihn vor dem Fledermaustotem in den Ruinen von Jubuwal östlich von hier ab. Hir\'eek wird Euch von dort an führen.', },
    {'Legt den Weihrauch der Gurubashi vor das Totem von Hir\'eek und lauscht dann Zanzils Verschwörung.', },
  },
  [26551] = {
    'Beseitigt den Ausgestoßenen',
    {'Ihr müsst Zanzil töten. Ihr seid auf Hir\'eeks Schwingen geritten und habt durch Hir\'eeks Augen gesehen; Ihr wisst, wo Zanzil sich in den Ruinen von Aboraz versteckt hält. Begebt Euch dorthin und tötet ihn.|n|nOh, und <Volk>... Falls wir getrennt werden, solltet Ihr diesen Fetisch benutzen. Er funktioniert nur innerhalb von Schlingendorn, aber er wird Euch schnell zu mir zurückbringen, falls es notwendig sein sollte.|n|nViel Glück, <Volk>. Zanzil ist kein gewöhnlicher Gegner.', },
    {'Begebt Euch zu den Ruinen von Aboraz am Schlingendornkap und nehmt Euch Zanzil den Ausgestoßenen vor.', },
  },
  [26552] = {
    'Durch das Trollloch',
    {'Zanzils Portal nach Zul\'Gurub ist noch geöffnet. Zul\'Gurub ist ein gefährlicher Ort, aber Chabal glaubt, dass Ihr diese Aufgabe erfüllen könnt.|n|nDas Portal erwartet Euch.', },
    {'Benutzt Zanzils Portal und betretet Zul\'Gurub.|n|nSolltet Ihr Euch verlaufen oder nach Zul\'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.', },
  },
  [26553] = {
    'Hohepriesterin Jeklik Sichtbare Transformation',
    {'Vor Euch ragt eine Rampe auf, die zu einer der vielen Terrassen der Stadt führt. Vor Euch befinden sich Totems, die wie Fledermäuse aussehen. Sie deuten an, dass Ihr Euch in der Hochburg der Hohepriesterin Jeklik befindet, einer Anhängerin von Hir\'eek.|n|nJeklik betete Hakkar an und ist eine der Priesterinnen, die Zanzil wiederbeleben will. Wenn Ihr Euch beeilt, könnt Ihr die Wiederbelebung vielleicht verhindern.', },
    {'Vernichtet die Leiche der Hohepriesterin Jeklik, bevor Zanzil sie wiedererwecken kann.|n|nSolltet Ihr Euch verlaufen oder nach Zul\'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.', },
  },
  [26554] = {
    'Hals über Kopf nach Zul\'Gurub',
    {'Zanzil der Ausgestoßene ist erneut durch eines seiner Portale geflohen. Folgt ihm!', },
    {'Geht durch Zanzils Portal.|n|nSolltet Ihr Euch verlaufen oder nach Zul\'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.', },
  },
  [26555] = {
    'Hohepriester Venoxis Sichtbare Transformation',
    {'Venoxis war der Zweite der beiden Priester, die Zanzil von den Toten erwecken wollte. Es ist Euch bereits gelungen, Hohepriesterin Jekliks Leiche zu vernichten... Venoxis muss der Nächste sein.', },
    {'Kümmert Euch um Zanzil den Ausgestoßenen und Hohepriester Venoxis.|n|nSolltet Ihr Euch verlaufen oder nach Zul\'Gurub zurückkehren müssen, sprecht mit Chabal in Hartzangs Versteck.', },
  },
  [26556] = {
    'Müll abladen verboten',
    {'Seit die Goblins in Orgrimmar Schutz gesucht haben, werfen sie all ihren Unrat in unsere Wasserspeicher.|n|nIch weiß nicht, welche Konsequenzen das für unseren Fischbestand haben wird, aber es sind bestimmt keine guten. Ich habe Berichte über eine neue mutierte Fischart erhalten, die in der toxischen Pfütze nahe ihres Lagers gesichtet worden ist. Einige Exemplare würden mir dabei helfen herauszufinden, was genau dort vorgeht.|n|nWürdet Ihr mir aushelfen?', },
    {'Angelt 6 giftige Pfützenfische und kehrt zu Razgar ins Tal der Ehre zurück, wenn Ihr fertig seid.', },
  },
  [26557] = {
    'Augen auf beim Angeln',
    {'Seit Jahren angle ich im Wasser von Orgrimmar Sandkarpfen. In letzter Zeit ist mir aufgefallen, dass meine Köder nicht mehr so gut funktionieren wie früher. Ich vermute, dass dies etwas mit den Tauren zu tun hat, die ins Tal der Weisheit gezogen sind.|n|nIch habe mit einigen ihrer Angler gesprochen. Anscheinend hat sich der Geschmack der Fische geändert. Heutzutage beißen sie wohl bei Hirschaugen an. Ihr solltet nördlich von Orgrimmar, unmittelbar hinter dem nördlichen Tor, jede Menge Hirsche finden.', },
    {'Erlegt einen Hirsch nördlich von Orgrimmar und benutzt sein Auge als Köder, um einen Sandkarpfen im Tal der Weisheit zu fangen. Kehrt danach zu Razgar ins Tal der Ehre zurück.', },
  },
  [26558] = {
    'Die Beschwörung von Shadra',
    {'Der Götze ist bereit, $N. Ich hoffe, Ihr seid es auch.|n|nReist mit dem Götzen vor uns nach Shadra\'Alor im Südwesten. Ihr müsst den Götzen an jedem der drei Tempel einsetzen.|n|nWenn Ihr das tut, wird Shadra in dieses Reich beschworen. Die Todespirscher und ich werden rasch zu Euch stoßen, sie überwältigen und ihren Körper verwerten. Sprecht mit dem Späher, den ich vorangeschickt habe, wenn das Ritual vollendet ist, und wartet auf mein Eintreffen.', },
    {'Benutzt den Götzen von Shadra am nordwestlichen, südwestlichen und östlichen Tempel in Shadra\'Alor.', },
  },
  [26559] = {
    '[NYI] Der Schlüssel zum Erfolg',
    nil,
    nil,
  },
  [26560] = {
    nil,
    {'Ich weiß nicht, wo Krakauer oder Danforth sind, aber Jorgensen wurde nordwestlich von hier, in Renders Lager festgehalten. Wir saßen im gleichen, verdreckten Käfig, bevor man mich nach Althers Mühle verlegte.|n|nUm ihn zu befreien, brauchen wir den Schlüssel. Eine eiskalte Hexe aus der Hölle namens Utroka die Schlüsselmeisterin hält ihn fest in den Klauen. Wir müssen sie töten, wenn wir Jorgensens Käfigschlüssel haben wollen. Sie hält sich nördlich von hier in dem Tal auf, das zur Brennenden Steppe führt.|n|nAuf geht\'s, $GJunge:Mädchen;.', },
    {'Besorgt Jorgensens Käfigschlüssel.', },
  },
  [26561] = {
    nil,
    {'Krakauer steht schon auf dem Richtblock! Die Orcs haben einen Hexendoktor der Gurubashi geholt, der ein dunkles Ritual über ihn sprechen soll. Wir müssen den Troll töten und Krakauer befreien!|n|nLos! Er ist in der Höhle dort. Geht nach rechts an der ersten Gabelung.', },
    {'Tötet Ritualist Tarak.', },
  },
  [26562] = {
    'Der Nachzügler... Danforth',
    {'Danforth wird auf der anderen Seite der Höhle gefoltert. Wer weiß, in welchem Zustand er mittlerweile ist! Wir müssen zu ihm und ihn retten!|n|nOberanführer Barbarius trägt den Schlüssel zu dem Hebel, der Danforth oben hält, bei sich. Wenn wir zusammen arbeiten, können wir Barbarius, dieses Schwein, töten. Wenn Barbarius tot ist, holen wir Danforth mit seinem Schlüssel herunter und hauen ab!|n|nBereit?', },
    {'Tötet Oberanführer Barbarius und bergt den Hebelschlüssel des Schwarzfelsklans. Befreit Danforth mit dem Hebelschlüssel des Schwarzfelsklans.', },
  },
  [26563] = {
    'Rückkehr der Kompanie Bravo',
    {'Ich weiß nicht, wer Ihr seid, $GFreund:Schwester;, aber Ihr habt Euch den Respekt und die Bewunderung der Kompanie Bravo verdient. Ihr habt unsere Haut gerettet und auch noch eine Bootsladung voller Orcs getötet. Wir werden den Gefallen erwidern.|n|nReist zurück nach Seenhain und meldet Euch bei Oberst Trottmann. Wir werden Johnny finden und die gute Nachricht persönlich überbringen. Wenn die Kompanie Bravo loslegt, haben diese Orcs keine Chance.', },
    {'Meldet Euch bei Oberst Trottmann in Seenhain im Rotkammgebirge.', },
  },
  [26564] = {
    'Heimwerker',
    {'<Klei sieht Euch verächtlich an und macht ein Geräusch, das klingt, als reibe man zwei Steine aneinander.>|n|nSie haben all unsere Katapulte zerschlagen. Das hier versuche ich zu reparieren, aber bis jetzt ohne Erfolg.|n|nIhr könntet Euch nützlich machen. Reist zur Front und bringt mir alle Ersatzteile, die Ihr findet.|n|nKriegt Ihr das hin, Fleischsack?', },
    {'Besorgt 6 Katapultteile.', },
  },
  [26565] = {
    'Ein wütender Fang',
    {'Steht Euch der Sinn nach einer Herausforderung, $N? Gut, das hatte ich gehofft. Der Südstrom führt westlich an Orgrimmar vorbei. Eure Herausforderung schwimmt in seinen mächtigen Wassern.|n|nWir suchen nach einem riesigen, wütenden Hecht. Dieser geschätzte Fisch war früher zahlreich in dieser Gegend vertreten, doch seit der Flut sieht man ihn nur noch selten. Begebt Euch zum Fluss, dann werden wir sehen, wie gut es wirklich um Eure Angelkünste bestellt ist.', },
    {'Fangt einen riesigen wütenden Hecht im Südstrom. Ihr findet den Südstrom vor dem westlichen Tor von Orgrimmar. Kehrt danach ins Tal der Ehre zu Razgar zurück.', },
  },
  [26566] = {
    'Ein Triumph gnomischer Erfindungsgabe',
    {'Wir werden alle Waffen, Erfindungen und Soldaten brauchen, die wir kriegen können, wenn wir Razlo Ritzelstoß und seine Anhänger besiegen wollen.|n|nIm Nordosten werdet Ihr Ingenieur Schleiffunke finden, der einer neuen Generation brillanter Gnomendenker angehört. Stellt Euch vor: er hatte seit mehr als drei Prototypen keine Explosion mehr!|n|nGenug angegeben. Ingenieur Schleiffunke arbeitet an einem Bot, mit dessen Hilfe er den Toxischen Flugplatz reinigen will. Stellt Euch ihm vor. Vielleicht könnt Ihr ihm bei den Tests des Bots helfen.', },
    {'Sprecht mit Ingenieur Schleiffunke in Neu-Tüftlerstadt.', },
  },
  [26567] = {
    nil,
    {'Habt Ihr mal von John Keeshan gehört, $N? Ich war in allen drei großen Kriegen sein Kommandant. Ich sage Euch, dieser Mann hat mehr Orcs getötet als jeder andere. Wenn jemand die Invasion der Schwarzfelsorcs aufhalten kann, dann JOHN J. KEESHAN. Wir müssen ihn dazu bringen, uns zu helfen. Wenn die gewaltige Schwarzfelsarmee auf ihrem Weg nach Elwynn durch Seenhain marschiert, wird sie das ganze Land in Schutt und Asche legen.|n|nIch habe gehört, dass er dem geheimen Kampfclub angehört, der sich im Gasthaus von Seenhain trifft. Findet ihn und erzählt ihm alles, was Ihr wisst.', },
    {'Bemüht Euch um die Hilfe von John J. Keeshan im Gasthaus Seenhain in Seenhain.', },
  },
  [26568] = {
    'Is\' nich\' mein Krieg',
    {'Sie verlangten von mir, in diesen Kriegen zu kämpfen. Ich habe sie nicht darum gebeten! Ich tat, was ich tun musste, um zu siegen. Irgendwann wurde ich von diesen schmutzigen, mit Unrat beschmierten, verlausten Orcs gefangen genommen. Fünf lange Jahre benutzten sie mich als ihre Toilette. Schließlich brach ich aus, kehrte in meine Heimatstadt zurück... und was geschah? Die Leute spuckten mich an, beschimpften mich und nannten mich einen Babyorcmörder und andere üble Verleumdungen.|n|nNein, ich werde Euch wohl eher nicht helfen. Geht zurück zu Trottmann und sagt ihm, das sei nicht mein Krieg.', },
    {'Kehrt zu Oberst Trottman zurück.', },
  },
  [26569] = {
    'Vermessungsausrüstung',
    {'Ah, meine Rettung! Ich habe gehört, dass Ihr Euch auf einer Mission zur Rettung von Seenhain... und meiner Brücke... befindet. Hab viel zu lang daran gearbeitet, um zuzusehen, wie das verdammte Ding von plündernden Orcungeheuern zerstört wird!|n|nSolltet Ihr auf dem Weg nach Norden, zu Renders Lager, sein, könntet Ihr mir einen Gefallen erweisen. Besorgt ein paar Teleskope von den Fährtenlesern des Schwarzfels. Könnte ich gut für meine neue Vermessungsausrüstung gebrauchen.', },
    {'Beschafft 5 Teleskope des Schwarzfelsklans.', },
  },
  [26570] = {
    'Renders Armee',
    {'Hey, auf dem Weg nach Norden? Hättet Ihr Lust, Euren eigenen kleinen Krieg gegen diese Schwarzfelsmonster anzuzetteln? Was sagt Ihr dazu, $N?|n|nTötet jeden Schwarzfelsorc, der Euch rund um Althers Mühle oder Renders Lager begegnet. Tötet, bis sich Eure Haut von ihren Blutspritzern rot färbt und kommt dann zu mir zurück. Ich werde Euch großzügig belohnen.|n|nDas wird die Invasion des Schwarzfelsklans wahrscheinlich nicht aufhalten, aber es wird ihre Pläne empfindlich stören.', },
    {'Tötet 25 beliebige Schwarzfelsorcs in Althers Mühle oder Renders Lager.', },
  },
  [26571] = {
    'Kriegswaffen',
    {'Das, worum ich Euch bitten möchte, wird nicht leicht zu erfüllen sein, $N. Keeshan hat alles in diesem Orcgefängnis zurückgelassen, und damit meine ich nicht nur seine Seele und seinen Lebenswillen.|n|nWenn Johnny für uns kämpfen soll, müssen wir seinen wertvollsten Besitz bergen. Die Orcs haben Keeshans Bogen und sein Überlebensmesser an sich gebracht.|n|nReist nach Althers Mühle östlich von hier und sucht nach den beiden Orcleutnants Murdunk und Homurk. Sie haben Keeshans Ausrüstung. Holt sie Euch.|n|nIch bleibe mit dem Gnomcorder in Verbindung.', },
    {'Bergt Keeshans Bogen und Keeshans Überlebensmesser.', },
  },
  [26572] = {
    'Elektrisierender Einfall',
    nil,
    {'Schneidet im Donnergrat, südlich von Orgrimmar, den Schwanz einer ertrunkenen Donnerechse mit Razgars Filetiermesser ab. Benutzt den Schwanz nahe eines goldenen Steinfischs, um ihn damit zu töten. Kehrt danach zu Razgar ins Tal der Ehre zurück.', },
  },
  [26573] = {
    'Er muss mit ganzem Herzen dabei sein',
    {'<Der Gnomcorder klickt.>|n|nSeine Ausrüstung allein reicht nicht, $N. Er muss diese Schlacht von ganzem Herzen wollen. Um das zu erreichen, benötigen wir Gegenstände von sentimentalem Wert. Die Schwarzfelsorcs von Renders Lager im Norden besitzen zwei solcher Gegenstände, die Keeshan gehören.|n|nBegebt Euch dorthin und durchsucht ihre Kisten nach Keeshans Stirnband und einem Jadeamulett, das ihm seine Frau - die bei einer Invasion der Schwarzfelsorcs brutal ermordet wurde - hinterlassen hat.|n|nBringt sie zu mir, solltet Ihr fündig werden.', },
    {'Findet Keeshans rotes Stirnband und Keeshans Jadeamulett.', },
  },
  [26574] = {
    'Adellas geheimes Lager',
    {'Lady Shandris hat Euch bereits darum gebeten, uns noch mehr zu helfen.|n|nAdella hat sich in Richtung Osten aufgemacht, zu den Waldpfotengnollen, und ein kleines Lager südlich von Camp Mojache errichtet. Wenn Ihr Lady Shandris und der Allianz weiter dienen wollt, so solltet Ihr Euch bei Adella melden.|n|nBegebt Euch nicht zu nahe an Camp Mojache heran... die Horde wird mit einem Angriff nicht zögern. Haltet Euch südlich und haltet nach unseren Bannern Ausschau.', },
    {'Meldet Euch bei Adella im Schattengeäst in Feralas.', },
  },
  [26575] = {
    'Steinalt',
    {'Ich muss Euch um einen weiteren Gefallen bitten, Fleischling.|n|nEs dreht sich um einen Basilisken, der viel größer und älter als die anderen ist. Normalerweise fürchten wir sie nicht, doch dieser Basilisk ist mittlerweile so stark, dass er sogar einige meiner Söhne versteinert hat. Das dürfen wir nicht hinnehmen.|n|nSucht Gorgonit im Osten und erschlagt ihn. Er hat bereits viel länger gelebt als nötig.', },
    {'Tötet Gorgonit.', },
  },
  [26576] = {
    'Ruhige Hand',
    {'Im Norden, ganz in der Nähe, werdet Ihr Terrath den Beständigen finden. Er hat die Aufgabe angenommen, die Steindrachen zurückzugewinnen. Alle paar hundert Jahre muss das wiederholt werden... die Steindrachen sind launisch und beugen sich nur der Stärke.|n|nTerrath ist ausgeglichen und vernünftig, doch seine Ziele werden schwer zu erreichen sein. Geht zu ihm. Appelliert an die ausgeglichenere Seite der Steinmutter.', },
    {'Sprecht mit Terrath dem Beständigen vor dem Bleichen Hort.', },
  },
  [26577] = {
    'Felserhebung',
    {'Auf der Rubinspanne im Osten werdet Ihr Gorsik finden. Er steht für den instabilen und gewalttätigen Teil des Naturells unseres Volkes. Er ist weder freundlich noch offenherzig, aber seine Stimme hat Gewicht.|n|nBeweist Euch Gorsik, dann wird es Euch leichter fallen, Euch auch der Steinmutter zu beweisen.', },
    {'Sprecht mit Gorsik dem Tosenden auf der Rubinspanne.', },
  },
  [26578] = {
    nil,
    {'Die Spalte, die in Eure Welt führt, hat unsere Heimat vergiftet. Korrumpiert. Verschmutzt.|n|nDiese Spanne schwärt und wächst. Unter dem ganzen Dreck kann man die Reinheit des Steins kaum noch erkennen.|n|nWenn Ihr uns zur Seite stehen wollt, dann beseitigt diese Überwucherung. Sucht nach hell leuchtenden Pilzen, die schneller wachsen als die anderen. Das sind die schlimmsten Übeltäter.', },
    {'Zerstört 10 Verdammnispilze.', },
  },
  [26579] = {
    'Verweichlicht',
    {'Die Fungusungetüme um uns herum sind einer Schwäche erlegen, die der Eurer Art sehr gleicht. Ihre Haut ist weich geworden. Sie gehören nicht mehr zum Stein.|n|nTötet sie. Wir wollen nicht, dass diese Krankheit sich ausbreitet.', },
    {'Tötet 8 Fungusungetüme.', },
  },
  [26580] = {
    'Vertraute Eindringlinge',
    {'Fleischling. Einige Eurer Art huschen über die Felsen. Zu scheu, um näher zu kommen, zu schnell, um sie zu zerschmettern.|n|nWenn Ihr meine Gunst erlangen wollt, kümmert Euch um sie. Ich bin diese Spielchen leid.', },
    {'Sprecht mit den "Fleischlingeindringlingen" auf der Rubinspanne.', },
  },
  [26581] = {
    'Den Kopf in den Wolken',
    {'Ich bin zwar kein Druide, aber ein paar dieser Pilze sehen nicht so aus, als seien sie natürlich gewachsen. Ich weiß, dass unser Freund, der Steinlord da hinten, Azeroth die Schuld an diesem Befall geben will, aber ich glaube, die Ursachen sind hausgemacht.|n|nIm Nordosten sah ich einige Wolken aus rotem Nebel am Wasser, die anscheinend neue Wucherungen nach sich zogen. Nehmt einen meiner Windteufel und besorgt mir eine Probe aus diesen Wolken. Es kann sein, dass Ihr in Bodennähe bleiben müsst, um sie zu sehen.', },
    {'Bringt Lorvarius\' Windteufel zu den Wolken aus rotem Nebel in der Rubinspanne und bringt eine Probe davon mit.', },
  },
  [26582] = {
    'Unnatürliche Ursachen',
    {'Der Ursprung ist definitiv magisch. Nicht einmal druidisch. Ich habe einen der Steintroggs im Norden unter Verdacht.|n|nGeht zu Gorsik und weist ihn auf sie hin. Hoffentlich gewinnt Ihr dadurch seine Unterstützung.', },
    {'Sprecht mit Gorsik dem Tosenden in der Rubinspanne.', },
  },
  [26583] = {
    'Der Zorn der Fungumanten',
    {'Ihr Anführer versteckt sich in seinem Loch dort vorn. Er hat diese Plage über die Rubinspanne gebracht.|n|nEr muss sterben.|n|nEine Eurer Begleiterinnen vom Irdenen Ring befindet sich bereits im Inneren. Ihr solltet mit ihr sprechen.', },
    {'Sprecht mit Erdheilerin Norsala und tötet dann Fungumant Glop.', },
  },
  [26584] = {
    'Geschüttelt und gerührt',
    {'Ich habe meine Brüder ausgesandt. Sie werden Verlok von oben angreifen. Die Verlok werden sich wie immer auf ihren Felsvorsprüngen versammeln, um unserem Zorn zu entgehen. Sobald sie das tun, werden wir dafür sorgen, dass die Erde bebt, bis sie zu Boden gehen.|n|nDann könnt Ihr Euch nützlich machen. Sorgt dafür, dass sie sich nicht mehr erheben, wenn sie zwischen meinen Brüdern am Boden liegen.', },
    {'Tötet 8 Säulenbrecher von Verlok im unteren Teil der Wacht Verlok.', },
  },
  [26585] = {
    'Zerstörung der Verderbnis',
    {'Wenn dieses abscheuliche Wachstum wirklich von den Einwohnern Verloks stammt, dann bewahren sie ihre Vorräte sicher im Dorf im Norden auf. Bringt sie mir, damit ich Eure Behauptung überprüfen kann.', },
    {'Besorgt 8 Taschen des Wunderwachstumsmittels von Verlok.', },
  },
  [26586] = {
    'Die Suche nach der Kompanie Bravo',
    {'Wenn Ihr und Keeshan Seenhain verteidigen wollt, müssen wir sein altes Bataillon finden. Das Letzte, was ich hörte, war, dass Messner, Jorgensen, Krakauer und Danforth von den Schwarzfelsorcs gefangen genommen wurden. Ich weiß zwar nicht, wo sie sein könnten oder ob sie noch leben, aber ich wäre ein verdammter Narr, wenn ich Euch nicht bitten würde, sie zu suchen.|n|nSucht in Althers Mühle östlich von hier nach Hinweisen.', },
    {'Sucht in Althers Mühle nach einem Mitglied der Kompanie Bravo.', },
  },
  [26587] = {
    'Der Schlüssel zum Erfolg',
    {'Der Schlüssel zu diesem Käfig befindet sich in einem Beutel nördlich von diesem Ort im Höhlenbau der Worgen. Das Problem ist, dass dieser Beutel sicher auf einem Baumstumpf inmitten blutdürstiger, mordgieriger Worgs liegt. Holt den Schlüssel, ohne die schlafenden Worgs aufzuwecken.|n|nIhr habt nur einen Versuch. Reist zum Höhlenbau der Worgs und findet einen Weg zur Mitte. Seid vorsichtig und nehmt Euch vor dem Worghauptmann des Schwarzfels in Acht. Holt den Schlüssel und kehrt zu mir zurück.|n|nSolltet Ihr einen Begleiter haben, wäre es besser, ihn zurückzulassen!', },
    {'Besorgt Messners Käfigschlüssel.', },
  },
  [26588] = {
    'Ein wütender Fang',
    nil,
    {'Fangt einen riesigen wütenden Hecht im Südstrom. Ihr findet den Südstrom vor dem westlichen Tor von Orgrimmar. Kehrt danach zu Razgar ins Tal der Ehre zurück.', },
  },
  [26589] = {
    'Die Wildnis von Feralas',
    {'Ihr habt heldenhaften Mut, uns dabei helfen zu wollen, diese Länder zu beschützen. Wenn Ihr der Wildnis noch mehr helfen wollt, so werden sich noch andere finden, die Eure Hilfe gebrauchen können.|n|nDer üppige Wald von Feralas liegt südlich von hier. Sucht in den Schatten der mächtigen Zwillingskolosse Konu Runentotem auf. Er hat Hinweise auf eine beunruhigende Krankheit gefunden.|n|nFolgt der Straße nach Westen, vorbei an den Zwillingskolossen, bis Ihr Camp Ataya erreicht. Geht in Frieden, $N, und mit der Erdenmutter.', },
    {'Reist nach Feralas und sprecht mit Konu Runentotem in Camp Ataya.', },
  },
  [26590] = {
    'Das heilige Wasser der Klarheit',
    {'Hey, hört mich an. Ihr seht nicht wie ein gewöhnlicher Tourist aus, und ich stecke ein wenig in der Klemme. Mein Cousin im Norden hat mir dieses seltsame Artefakt geschickt und ich brauche Eure Hilfe, um es zu... äh... identifizieren.|n|nAls erstes müsst Ihr mir das heilige Wasser der Klarheit besorgen. Es heißt, dass jeder, der aus dieser Quelle trinkt, eine Vision der Klarheit erhält. |n|nKlingt recht vielversprechend, oder?|n|nSchöpft es aus dem Nek\'maiquellbrunnen am Gipfel des Nagalagers. Viel Glück!', },
    {'Beschafft das heilige Wasser der Klarheit aus dem Nek\'maniquellbrunnen am Schlingendornkap.', },
  },
  [26591] = {
    'Rettung an vorderster Front',
    {'Ihr scheint schnell zu Fuß zu sein, <Volk>. Ich brauche jemanden, der sich in das Chaos der Front stürzt und unsere Verletzten versorgt.|n|nNehmt meine Rettungsausrüstung. Sie ist ganz einfach zu verwenden.|n|nHeilt sie, bevor die Steintroggs sie endgültig erwischen.', },
    {'Versorgt 10 verletzte Irdene.', },
  },
  [26592] = {
    'Diffraktorisches Chromaskop',
    {'Ich benötige Analysewerkzeuge, um dieses Artefakt zu identifizieren. Ein diffractorisches Chromaskop sollte ausreichen, glaube ich.|n|nIch habe das Mithrilgehäuse bereits, was seltsamerweise am schwierigsten zu finden ist. Wir brauchen nur noch zwei andere Teile, einen Rubin und einen Saphir.|n|nIn der Nähe lagern Piraten, unmittelbar im Süden von hier und etwas weiter entfernt im Osten. Piraten lieben Schätze... seht doch mal nach, ob Ihr ein paar Edelsteine für mich findet.', },
    {'Besorgt einen Blutsegelrubin und einen Blutsegelsaphir.', },
  },
  [26593] = {
    'Zitterhand Angst einjagen',
    {'Wenn ich etwas nicht leiden kann, dann sind das Leute, die ihre Spielschulden nicht bezahlen! Und es gibt \'ne Menge Leute, die mir was schulden. Ob Ihr mir wohl beim Eintreiben helfen könnt?|n|nDa ist zuerst mal "Zitterhand" Phillipe unten bei den Docks. Er schuldet mir eine Menge nach dem Spiel letzte Woche und ich will mein Geld jetzt! Aber um da dranzukommen, müssen wir ihm gehörig Angst einjagen.|n|nVerlasst die Stadt und jagt alte Nebeltalgorillas. Sucht Euch ein paar nette Innereien heraus und bringt sie zu Zitterhand. Sagt ihm ja nicht, dass sie von einem Tier stammen, er soll ruhig das Schlimmste annehmen.', },
    {'Erhaltet 5 Nebeltalinnereien von alten Nebeltalgorillas.', },
  },
  [26594] = {
    'Rückkehr zu MacKinley',
    {'Hier, nehmt diesen Beutel und gebt ihn Seewolf. Und sagt ihm, dass ich ihm alles zurückzahlen wollte! Ich schwöre!!|n|nIch hab nur ein bisschen viel getrunken und mich verlaufen, und... Ihr wisst ja, wie es so geht. Er wird es verstehen - Ihr müsst nicht erst grob werden!', },
    {'Bringt Zitterhands Bezahlung zu "Seewolf" MacKinley.', },
  },
  [26595] = {
    nil,
    {'Es gibt drei Phasen bei der Schuldeneintreibung: höflich fragen, energisch fragen und etwas, das ich als "Phase Drei" bezeichne.|n|nLeider bin ich alter Hund zu Phase Drei nicht mehr in der Lage. Deshalb muss ich so viele Kumpane, Handlanger, Angeber, Schläger und edle Abenteurer wie Euch einstellen!|n|nJans Fitzpünktchen, Ephram Mondsturz and Maury Wilkins verstecken sich an der östlichen Küste. Ihr solltet alle drei problemlos bei einem Ausflug abklappern können... Bringt mir ihren wertvollsten Besitz.', },
    {'Besorgt Maurys Klumpfuß, Fitzpünktchens Drehmomentschlüssel mit Ratsche und Ephrams juwelenbesetzten Spiegel.', },
  },
  [26596] = {
    'Der Ruf von Kalimdor',
    {'Ich wurde von den guten Leuten von Theramore geschickt, um loyale Mitglieder der Allianz zu finden, die Lady Jaina mit einigen Problemen in den Düstermarschen aushelfen kann.|n|nIhr wart doch nicht wirklich hier, um für die Goblins zu arbeiten, oder?|n|nDer Weg in die Düstermarschen führt durch Ratschet. Sprecht dort mit Gazlowe. Er wird euch von dort aus die richtige Richtung zeigen.|n|nIgitt... ich glaube, ich bin auf einen Fisch getreten! Und er hat gezappelt!', },
    {'Nehmt das Schiff von Beutebucht nach Ratschet und sprecht dort mit Gazlowe.', },
  },
  [26597] = {
    'Schlingendornfieber',
    {'Krank... so... furchtbar k-k-krank... |n|n... habe mich mit Schlingendornfieber angesteckt... |n|n...um genau zu sein, SchlingendornKAPfieber...|n|n...tödliches V-v-virus... |n|n... einziges Heilmittel... wäre... wäre es... das Herz von M-m-m-mokk dem Wilden zu essen... schwer zu fassendes, weißes Wildtier... |n|n... Hexendoktor Unbagwa... Einziger, der es b-b-beschwören kann...|n|n... sucht Unbagwa... versteckte Höhle am südlichen Kap...|n|n... schnell... sterbe... sterbe...', },
    {'Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizrackett.', },
  },
  [26598] = {
    'Das Herz von Mokk',
    nil,
    nil,
  },
  [26599] = {
    'Die Truhe des Kapitäns',
    {'Früher hab ich ein Schiff von hier bis ganz nach Ratschet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf.|n|nBis...|n|nDiese verfluchten Meeresriesen mich ruinierten! Sie haben mein Schiff zerschmettert, meine Crew umgebracht und mich in ein Rettungsboot nach Beutebucht gesteckt. Ich werde nicht ruhen, bis ihre Leichen auf dem Meeresboden verstreut liegen!|n|n Einer dieser Riesen, Gorlash, hat meine Kapitänstruhe gestohlen. Ich habe gehört, dass Gorlash an der Küste östlich von hier sein Unwesen treibt. Findet ihn und bringt mir meine Truhe zurück! Tut das, und Ihr habt Euch die Dankbarkeit eines Kapitäns verdient!', },
    {'Erhaltet Smotts\' Truhe von Gorlash am Schlingendornkap.', },
  },
  [26600] = {
    'Ein riesiges Bankett',
    {'Der nächste Riese auf meiner Liste nennt sich Negolash. Ich sehe noch vor mir, wie er aus der Gischt sprang und den armen Poopdeck-Paul aus dem Krähennest riss.|n|nVerschlang ihn in einem Bissen... Auf dem Weg nach unten brach er noch meinen Kreuzmast in zwei Teile.|n|nKeines meiner Besatzungsmitglieder hat einen so schrecklichen Tod verdient. Also werden wir Negolashs Appetit gegen ihn verwenden. Kelsey Yance verkauft Euch bestimmt etwas Fleisch, und Klein Whiskeys Schnaps reicht aus, um einen... nun, einen Meeresriesen umzuhauen. Ihr werdet beide in der Stadt finden.', },
    {'Kauft eine Kiste mit Fleisch der Güteklasse E von Kelsey Yance und eine Kiste mit Pupellyverbos Portwein von Klein Whiskey.', },
  },
  [26601] = {
    'Mok\'rash der Spalter',
    {'Mok\'rash der Spalter ist der letzte Riese. Und der größte, wenn ich mich recht entsinne. Größer als eine Welle im Orkan, mit einem Bart wie ein Tangwald und einem Hammer mächtig wie eine Eiche.|n|nEr verhöhnt mich von der Janeirospitze, der Insel kurz vor diesem Pier. Nur wegen ihm sitze ich immer noch hier fest und friste mein Dasein als Landratte.|n|nWenn Ihr schwimmen könnt, dann macht Euch auf den Weg zur Janeirospitze und tötet Mok\'rash.|n|nSeid vorsichtig, $N. Mok\'rash wird sich nicht so leicht geschlagen geben wie seine Brüder.', },
    {'Tötet Mok\'rash den Spalter auf der Janeirospitze.', },
  },
  [26602] = {
    'Riesenportionen erwünscht',
    {'Nehmt das Essen und legt es in unser altes Rettungsboot südöstlich von hier an der Küste. Wenn Negolash das ganze Essen riecht, wird er angerannt kommen!|n|nUnd dann erwartet ihn bereits $Gein beherzter:eine beherzte:c; $C, $Gder:die:c; seinen Kadaver zurück in die salzige Tiefe schleudern wird.', },
    {'Legt die Riesenkiste Riesenessen in Captain Smotts\'Rettungsboot. Beschwört Negolash damit und tötet ihn.', },
  },
  [26603] = {
    'Flaschenpost',
    {'In der Flasche findet Ihr eine Notiz, auf der Folgendes, in recht guter Handschrift, steht:|n|n<An alle, die mir helfen können:>|n|n<Bitte, ich benötige dringend Hilfe. Eine große Bestie hält mich auf einer Insel in den Südlichen Meeren gefangen.>|n|n<Die Sternbilder am Nachthimmel sind mir nicht vertraut und von Dschungelbäumen verdeckt, aber an klaren Tagen kann ich die Küstenlinie im Nordwesten erkennen und im Südwesten etwas, das große Segelschiffe sein könnten.>|n|n<Ich flehe Euch an, mein möglicher Retter, bitte helft mir.>', },
    {'Sucht den Schreiber der Nachricht auf der Insel Jaguero am Schlingendornkap.', },
  },
  [26604] = {
    'Der Schutz ihrer königlichen Hoheit, Prinzessin Poobah',
    {'Diese teuflischen Dschungelkatzen umkreisen mich bereits seit einiger Zeit. Ich beobachte sie so gut ich kann, aber sie scheinen... im Gras zu verschwinden.|n|nHört, wie sie knurren und zischen!|n|nVersteht mich nicht falsch... Ihr sollt mich immer noch retten, aber beseitigt zuerst diese Katzen. Ich muss nicht gerettet werden, wenn ich danach als Abendessen ende.', },
    {'Tötet 5 Jagueropirscher.', },
  },
  [26605] = {
    'Bahaarte Diebe',
    {'Ich verstehe ja, dass Ihr mich retten wollt, aber der richtige Zeitpunkt ist noch nicht gekommen. Zuerst benötige ich etwas von meinem Besitz.|n|nDie Gorillas und Affen auf der anderen Seite der Insel haben das meiste davon gestohlen. Ich brauche meine Tiara, mein Szepter, meine Pantoffeln und mein Tagebuch, dann bin ich bereit zur Abreise.|n|nWas? Seht mich nicht an, als wäre ich irgendeine Verrückte. Ihr versteht nicht, was es bedeutet, Prinzessin zu sein.', },
    {'Sucht nach Poobahs Tiara, Poobahs Szepter, Poobahs Pantoffeln und Poobahs Tagebuch bei den Affen auf der Insel Jaguero.', },
  },
  [26606] = {
    'Muklas Ende',
    {'$N, ich setze all mein Vertrauen in Euch. Befreit mich. Der große Himmelsmähnenkönig Mukla hält mich gefangen. Er herrscht über die wilden Tiere auf der Insel. Mit Hilfe dieser Fessel halten sie mich hier gegen meinen Willen fest. Wenn es Euch gelingen sollte, ihn zu töten und den Schlüssel zu dieser Kette zu finden, würde ich tief in Eurer Schuld stehen.|n|nIch höre ihn oft an der Südostseite der Insel, aber seid bitte vorsichtig. Nehmt ihn nicht auf die leichte Schulter.', },
    {'Tötet König Mukla, findet den Fesselschlüssel.', },
  },
  [26607] = {
    'Sie haben zuerst Blut vergossen',
    {'Nehmt dieses Bündel mit Keeshans Habseligkeiten und kehrt in den Keller des Gasthauses in Seenhain zurück. Die Kompanie Bravo ist bereits dort und redet mit Keeshan. Erinnert ihn daran, wer als erstes Blut vergossen hat, $N. Seenhain braucht Keeshan. Die Allianz braucht Keeshan.|n|nWegtreten, Soldat!', },
    {'Bringt Keeshans Habseligkeiten zu John J. Keeshan im Gasthaus von Seenhain im Rotkammgebirge.', },
  },
  [26608] = {
    'Abgebrochene Verhandlungen',
    {'Geht nun, geht zurück zu Eurer Flotte. Sagt ihnen, was für ein Ungeheuer die Herrschaft über das Drachenmal für sich beansprucht.|n|nUnser "Kriegshäuptling" ist ein Verräter an seinem Blut. Seit seiner Rückkehr von der Scherbenwelt stinkt er nach Dämon und führt die Überreste unseres Klans ins Verderben.|n|nHelft dem Drachenmal, sich von Mor\'ghor zu befreien, dann werden die unter uns, die reinen Blutes sind, für immer Eure Verbündeten sein. Das kann ich versprechen.', },
    {'Kehrt zu Admiral Steinfaust vor der Küste der Drachenmalfestung im Schattenhochland zurück.', },
  },
  [26609] = {
    'Die Blutsegelbukaniere',
    {'Ihr scheint ja sehr erpicht auf Arbeit zu sein, Kumpel. Bin nicht sicher, warum eine Landratte wie Ihr, <Volk>, und <ein/eine:c> $C noch dazu, den Schwarzmeerräubern Hilfe anbietet, aber ich werd Euch nicht fortschicken.|n|nWir haben Beutebucht zu unserem gemütlichen zweiten Zuhause auf dem Festland gemacht, aber Gerüchten zufolge, hecken die Blutsegelbukaniere wieder etwas aus. Meine Jungs sind aber zu beschäftigt, sich einen anzusaufen und Mädchen nachzugaffen! Was ich brauch, ist ein Späher.|n|nBegebt Euch zur Bucht im Norden von Beutebucht an der Ungezähmten Küste und schaut, was Ihr so findet.', },
    {'Erster Maat Krazz will, dass Ihr die Bucht nördlich von Beutebucht überprüft.', },
  },
  [26610] = {
    'Blutsegelverrat',
    {'Auf der Karte hat jemand ein rotes "X" in Beutebucht eingezeichnet, genau dort, wo Ihr gerade steht.|n|nDaneben hat jemand gekritzelt:|n|n"Errichtet Euren Kommandoposten hier und wartet ab. Der Flottenmeister wird sich bei Euch melden, wenn die Zeit reif für Taten ist."|n|n"Ich übertrage Leutnant Bruce hier das Kommando. Dieses Mal wird alles anders sein. Dieses Mal werden wir Beutebucht endgültig erobern."|n|nDie Karte wird von einem Dolch gehalten, der mitten in Beutebucht steckt.', },
    {'Berichtet dem Ersten Maat Krazz in Beutebucht von Euren Funden.', },
  },
  [26611] = {
    'Der Baron muss davon erfahren',
    {'Beim Klabautermann! Also planen die Blutsegelbukaniere irgendeinen Angriff auf Beutebucht? Diese Schurken haben vielleicht Nerven. Die Schwarzmeerräuber werden Beutebucht niemals preisgeben!|n|nDas ist größer, als ich vermutet hatte. Meldet Baron Revilgaz sofort Eure Entdeckung! Ihr findet ihn hier in Beutebucht.', },
    {'Berichtet Baron Revilgaz von den geplanten Blutsegelangriffen.', },
  },
  [26612] = {
    'Einzelheiten des Angriffs',
    {'Ich brauche Details, $N. Wir sind den Blutsegeln hauptsächlich wegen unseres Bollwerks hier in Beutebucht überlegen, aber Informationen spielen ebenfalls eine wichtige Rolle.|n|nDie Blutsegelbukaniere haben nur ein paar kleine Lager im Süden errichtet, die sie als "Südkommando" bezeichnen. Nun, dieses so genannte Südkommando werdet Ihr überfallen. Findet ihre Pläne und tötet ihre Männer. Kehrt mit allen Informationen, die Ihr findet, zu mir zurück.', },
    {'Tötet 8 Seebären der Blutsegelbukaniere und 8 Hochmagi der Blutsegelbukaniere und erbeutet die Blutsegelkarten und Blutsegelbefehle.', },
  },
  [26613] = {
    'Auf dem Schnupftabak',
    {'Ah, das Leben auf See. Ich sag nicht, dass es das wahre Leben ist, aber es ist mein Leben.|n|nWenn ich in den Hafen komme, such ich mir eine gute Flasche Grog und sehr guten Schnupftabak. Schlechte Angewohnheiten, ich weiß, aber irgendein Laster muss\'n Pirat ja nun mal haben, nich?|n|nAlso könnt Ihr Euch vielleicht vorstellen, wie niedergeschlagen ich war, als ich herausfand, dass der Kräuterkundige nichts von dem Zeug mehr da hatte. Erzählte mir, dass seine Lieferung von den verdammten Räubern der Blutsegelbukaniere geklaut worden ist.|n|nIch wette, $Gein furchtloser:eine furchtlose:c; $C wie Ihr könnte sie überreden, die Ware zu teilen, nich?', },
    {'Deeg in Beutebucht möchte, dass Ihr ihm 15 winzige Haufen Schnupftabak bringt.', },
  },
  [26614] = {
    'Ein Auge offen halten',
    {'Haltet ein! Wer da?|n|nGrrr, ich bin so gut wie nutzlos ohne mein verzaubertes Spezialauge. Als ob es nich\' schon schlimm genug is\', dass ich meine Augen im Kampf verlor\'n hab! Aber zum Glück haben wir in Menethil angelegt und ein reisender Hexer hat \'n Spezialglasauge verzaubert, mit dem ich wieder was sehen kann.|n|nGestern Nacht hab\'n mir aber \'n paar von den Blutsegelbukanier\'n auf\'m Weg nach Haus aufgelauert. Die ham mir doch echt mein Auge geklaut! Scheint, als hätt\'n die Burschen Beutebucht gefunden.|n|nKönnt\'er \'nem alten Seebären helfen und mir mein Auge zurückholen?', },
    {'Besorgt Torkels Auge von den Blutsegelbukanieren.', },
  },
  [26616] = {
    'Es ist nie vorbei',
    {'Diese Schwarzfelsorcs werden eine Armee brauchen, wenn sie gegen die Kompanie Bravo und Euch etwas ausrichten wollen, $N. Trefft Euch mit uns an den Docks, die auf den Immerruhsee hinausgehen, wenn Ihr bereit seid. Wir segeln auf meinem Flussboot zum Immerruhlager auf der anderen Seite des Sees.|n|nBis später, $N.', },
    {'Fahrt auf Keeshans Flussboot zum Immerruhlager im Rotkammgebirge.', },
  },
  [26617] = {
    'Ein alter Seebär',
    {'Diese alte, verwitterte Münze wurde bei der Leiche des Piraten "Guter Junge" Bruce gefunden. Auf der Vorderseite ist das Abbild eines großen, unbekannten Piratenschiffs eingestanzt; auf der Rückseite der Begriff "Mannschaft der Trümmerflut".|n|nJemand, der schon lange im Pirateriegeschäft ist, konnte wissen, um was es sich bei dieser Münze handelt und was sie bedeutet.', },
    {'Bringt die verwitterte Münze zu Flottenmeister Seehorn in Beutebucht.', },
  },
  [26618] = {
    'Wölfe sind uns auf den Fersen',
    {'Die Stadtbewohner werden in erster Linie von den Terrorwölfen bedroht. Sie lauern in den Wäldern um uns herum, die meisten findet man jedoch am Nordufer des Flusses.|n|nSie sind anders als die räudigen Hunde, die Ihr aus Elwynn, oder wo immer Ihr auch herkommt, gewöhnt seid. Sie sind mannsgroß und zweimal so teuflisch.|n|nWenn Ihr den Einwohnern von Dunkelhain wirklich helfen wollt, dann jagt die Wölfe, damit wir auf unseren Straßen endlich wieder sicher sind.', },
    {'Tötet 12 Terrorwölfe.', },
  },
  [26619] = {
    'Ihr wollt also eine Revolution',
    {'Wenn es stimmt, was Ihr sagt, $N, dann haben wir Freunde innerhalb des Drachenmalklans. Wir könnten einen Aufstand in ihren eigenen Reihen unterstützen. Das würde viel Blutvergießen auf beiden Seiten verhindern.|n|nIch kann dabei helfen, aber den gefährlichsten Teil muss ich Euch überlassen.|n|nMeine Krieger der Axtbeißer werden mit ihrer Offensive an den Küstenstreifen beginnen. Nutzt diese Ablenkung und schleicht Euch hinter die feindlichen Linien. Sprecht dort mit Zaela, Eurem Kontakt zu den Rebellen.|n|nWir werden den Drachenmalklan bewaffnen und seine teuflischen Herrscher stürzen!', },
    {'Schleicht Euch hinter die Frontlinie am Hafen des Drachenmals und sprecht mit Zaela.', },
  },
  [26620] = {
    'Gewürzte Wolfkebabs',
    {'Gewürzter Wolfkebab ist eine Spezialität des Hauses! Natürlich kann ich Euch einige machen. Doch zuerst brauche ich die Zutaten.|n|nBringt mir fünf Wolfskronfleischsteaks. Die Terrorwölfe nahe dem Fluss nördlich der Stadt, lassen sich gut jagen, aber ich würde an Eurer Stelle nicht zu tief in die Wälder vordringen.', },
    {'Sammelt 5 Wolfskronfleischsteaks von Terrorwölfen.', },
  },
  [26621] = {
    nil,
    {'Die Waffen, die wir von der Horde bekommen haben, sind mehr als ausreichend. Wir vier sollten uns aufteilen und so viele Arbeiter und Händler des Drachenmals bewaffnen wie möglich.|n|nUnterschätzt uns nicht, $N. Selbst unsere Kaufleute sind im Kampf gnadenlos.|n|nLasst uns so viel Schaden wie möglich anrichten. Bewaffnet eine Truppe des Drachenmalklans und mäht die Teufelsvollstrecker und Hexenmeister nieder, die mein Volk schon so lange einschüchtern. Danach treffen wir uns hier, um unseren letzten Schlag einzuleiten!', },
    {'Bewaffnet 3 Arbeiter oder Händler des Drachenmals und tötet 10 Vollstrecker des Drachenmals und 4 Hexenmeister des Drachenmals.', },
  },
  [26622] = {
    'Tötet Mor\'ghor',
    {'Die Zeit ist gekommen. Heute stirbt Mor\'ghor.|n|nEine Warnung, $C. Dämonenblut fließt durch seine verfluchten Adern. Er bedient sich unnatürlicher Kräfte. Er wird sterben, das ist sicher. Doch es wird kein leichter Kampf. Ihr wisst ja noch, dass sich Mor\'ghor an der Spitze des Lagers aufhält. Dort werde ich Euch treffen. Erledigt ihn!|n|nVergesst nicht, 3 Anhänger des Drachenmals zu rekrutieren, solltet Ihr zu wenig Kämpfer haben - Ihr werdet unsere Hilfe brauchen.', },
    {'Tötet Kriegshäuptling Mor\'ghor im Hafen des Drachenmals. Ihr könnt immer noch Händler und Arbeiter des Drachenmals rekrutieren. Sie werden Euch helfen.', },
  },
  [26623] = {
    'Schwärzliche Krebsküchlein',
    {'Ich verrate Euch ein kleines Geheimnis - Schwärzliche Krebsküchlein werden in Wirklichkeit aus Spinnenfleisch gemacht! Ist ein bisschen eklig, aber die Küchlein haben einen würzigen Beigeschmack und eignen sich gut als Zwischenmahlzeit!|n|nAber wenn Ihr immer noch welche probieren möchtet, muss ich leider gestehen, dass ich kein Fleisch mehr habe. Ich brauche ein paar Fleischklumpen, dann kann ich die Küchlein backen.|n|nJagt am besten Giftweberspinnen. Sie nisten im Norden zwischen dem Vorgebirge und dem Fluss.', },
    {'Erbeutet 6 schwärzliche Klumpen von Giftweberspinnen.', },
  },
  [26624] = {
    'Auf Tuchfühlung mit den Blutsegeln',
    {'Diese Pläne sind... interessant. Firallon, so dumm kannst du doch nicht sein!|n|nSeht, alle seine Schiffe sollen sich auf das Feuern ihrer Kanonen konzentrieren. Nur ein paar Männer kommen durch die Tunnel rein. Mit drei Schiffen und einem Dutzend Kämpfer wird er Beutebucht nie einnehmen. Und das weiß er auch.|n|nNein, sie haben etwas anderes vor... und Ihr werdet herausfinden, was. Sprecht mit Yancey Grillsen, dem Anwerber der Blutsegelbukaniere, der sich nördlich der Stadt aufhält.|n|nRichtig, $N. Hofft, dass sie Euch nicht wiedererkennen.', },
    {'Meldet Euch bei Yancey Grillsen am Wasserfall nördlich von Beutebucht.', },
  },
  [26625] = {
    'Troggzor der Erdinator',
    {'Ihr müsst das sofort beenden!|n|nKehrt zur Front im Nordwesten zurück und tötet ihren Schlachtenführer, Troggzor den Erdinator. Bringt mir zum Beweis seinen Knüppel.', },
    {'Erbeutet den Knüppel des Erdinators.', },
  },
  [26626] = {
    'Wir haben ein Problem',
    {'Eine von Kleis Katapulteinheiten auf dem Schlachtfeld ist beschädigt. Ihr müsst ein paar Teile bei ihm abholen und das Katapult wieder einsatzfähig machen, $N.', },
    {'Sprecht mit Klei Lehmachse an der Zerrissenen Front in Tiefenheim.', },
  },
  [26627] = {
    'Der Einsiedler',
    {'Ich habe gehört, dass etwas im Bettlerschlupfwinkel vor sich geht. Man sieht Lichter im Turm östlich der Stadt.|n|nNur wenige haben den Mut, sich so nahe am Gebirgspass der Totenwinde aufzuhalten. Ihr seid $Gder:die; erste, $Gder:die; sich hier meldet, seit ich davon erfahren habe. Seht es Euch an und stellt sicher, dass das, was dort haust, menschlich ist.', },
    {'Findet den Bewohner des Turms im Bettlerschlupfwinkel.', },
  },
  [26628] = {
    'Tod von unten',
    {'Das ist übel. Es scheint, als ob die Säbelflossen sich zum Angriff sammeln.|n|nNaga sind bekannt für ihre Ruchlosigkeit im Kampf. Sie werden so lange angreifen, bis ich tot bin.|n|nIch schätze mein eigenes Leben nicht höher als das meiner Crew, aber Ihr müsst helfen, mich zu verteidigen. Die Crew ist nicht in der Lage, ohne meine Kenntnisse des Meeres nach Beutebucht zurückzufinden.|n|nDie Naga werden vom Meer her kommen. Ihr müsst mit mir hier oben bleiben, um den Angriff abzuwehren. Bemannt die Kanone und treibt sie zurück.|n|nSeid Ihr bereit, $N?', },
    {'Beschützt Wank O\'Breen während des Angriffs.', },
  },
  [26629] = {
    'Feststellung Eurer Loyalität',
    {'Da is\' nur eine Sache...|n|nYancey hört einiges. Ein paar Kumpel von mir hatten schon ziemlich tief ins Glas geschaut, als sie mir erzählten, dass sich $Gein:eine:c; $C durch das Südkommando gekloppt un\' nach Karten und Befehlen gesucht hat. $GEr:Sie; hat sogar ein paar anständige Piraten über die Klinge springen lassen.|n|nWie ich schon sagte, denen kam der Grog aus den Augen raus, aber... ein Bukanier muss seinen Ohren trauen. Deshalb hat mich Firallon selbst gefragt, ob ich Euch nich\' ne kleine Aufgabe stellen könnte...|n|nBringt mir den Kopf von Flottenmeister Seehorn.', },
    {'Besorgt den Kopf von Flottenmeister Seehorn in Beutebucht.', },
  },
  [26630] = {
    'Sieht doch wie ein Taurenpirat aus',
    {'Firallon will MEINEN Kopf? Das ist wirklich interessant. Aber wir finden schon einen Ausweg.|n|nDieser Yancey weiß wahrscheinlich nicht so genau, wie ich aussehe. Den meisten Nicht-Tauren fällt es schwer, uns Tauren auseinanderzuhalten. Den meisten Nicht-Tauren fällt es sogar schwer, uns von einem gewissen... vierbeinigen Nutztier zu unterscheiden.|n|nRikqiz, der Lederverarbeiter, hält eine solche Kreatur hier in Beutebucht, und Narkk versorgt mich mit Piratenhüten. Besorgt Ersatz für meinen Kopf und meinen Hut und kehrt mit beidem hierher zurück.', },
    {'Besorgt einen Kuhkopf und einen übergroßen Piratenhut. Bringt beides zu Flottenmeister Seehorn.', },
  },
  [26631] = {
    'Euer erster Tag als Pirat',
    {'Ihr habt zwar den Flottenmeister erledigt, aber Regeln sind Regeln und Befehle Befehle. Und meine Befehle besagen, dass alle neuen Piraten als Deckhelfer anfangen. Das sind die Regeln.|n|nIhr werdet für Käpt\'n Kielhol, den Kommandanten der Springflut, arbeiten. Es is\' das westlichste Schiff der Flotte, die südlich der Kapspitze liegt.|n|nSucht ihn in seiner Kapitänskajüte auf un\' bringt ihm Eure Papiere.', },
    {'Bringt Käpt\'n Kielhol Eure Papiere.', },
  },
  [26632] = {
    'Geleitschutz',
    {'Gut, ich glaube, das funktioniert wieder. Ihr müsst das Katapult nach Nadelfelsbruch, der Stadt der Steintroggs, nördlich der Front bringen.|n|nDer Fahrer wird Euch begleiten. Ich werde mich auf den Rückweg machen und Kies darüber informieren.|n|nDie Steintroggs werden zweifellos versuchen, Euch aufzuhalten. Haltet sie vom Katapult fern. Es hat eine ziemliche Durchschlagskraft.|n|nLasst mich wissen, wenn Ihr bereit seid, $N.', },
    {'Geleitet das Katapult der Irdenen sicher nach Nadelfelsbruch.', },
  },
  [26633] = {
    'Putzdienst',
    {'Die Decks der Springflut sollten leuchten wie ein Sternrubin, $GDeckhelfer:Deckhelferin; $N. Ich führe \'n ordentliches Schiff, dafür sorgen Deckhelfer wie Ihr!|n|nNa, worauf wartet Ihr denn noch, Ihr miesmuscheldämliche Schiffsratte? Ans Deck mit Euch! Nehmt den Mopp in die Hand!', },
    {'Nehmt Euch einen Deckhelfermopp vom Deck der Springflut und haltet das Deck 2 Minuten lang sauber.', },
  },
  [26634] = {
    'Der Fluch vieler Piraten',
    {'Zahnfleischerkrankung. Das ist ein großes Problem, <Volk>.|n|nIch weiß, dass Ihr neu seid und Euch wahrscheinlich noch nie jemand das Zahnfleisch aufgeschnitten hat, aber wir anderen Piraten müssen uns mit etwas herumschlagen, dass sich SKORBUT nennt. Deshalb lagern wir hier so viele Limonen.|n|nNa ja... lagerten hier so viele Limonen. Jemand hat unsere letzte Lieferung geklaut, aber sie können nicht weit gekommen sein - vielleicht bis zu den nahegelegenen Inseln? Schafft sie wieder her, dann überlege ich mir vielleicht, was ich tun kann, um für Eure Beförderung vom Deckhelfer zu sorgen.', },
    {'Besorgt 5 Scheffel Limonen.', },
  },
  [26635] = {
    'Schwimmen mit Kanonenkugeln',
    {'Würdet Ihr \'nem Deckhelferkameraden helfen?|n|nKielhol hat mir befohlen, ein paar Kanonenkugeln vom Meeresboden aufzusammeln. Ich erklär\' Euch, wieso ich das nicht kann.|n|nErstens: Ich habe winzige Arme. Seht sie Euch doch an! Glaubt Ihr wirklich, ich könnte damit eine Kanonenkugel aufheben, selbst, wenn sie Unterwasser liegt?|n|nZweitens: Ich habe sehr schwache Atmungsorgane. Mir wird schon schwindlig, wenn ich den Atem länger als zehn Sekunden anhalten muss.|n|nDrittens: Da sind Haie.|n|nIhr müsst mir helfen, $N! Eine weitere Degradierung würde ich nicht aushalten... Will gar nicht wissen, was als Nächstes käme!', },
    {'Bergt 6 Blutsegelkanonenkugeln aus dem Wasser unter der Springflut.', },
  },
  [26636] = {
    'Fernmeldeausrüstung der Bravo-Kompanie: Tarnung',
    {'Wir werden einiges an Ausrüstung brauchen, bevor wir die Schwarzfelsarmee ausschalten und das Rotkammgebirge retten können. Dabei könnt Ihr Euch nützlich machen, Grünschnabel.|n|nKeeshan hat mir befohlen, dafür zu sorgen, dass die Fernmeldeausrüstung der Bravo-Kompanie getarnt wird. Ich möchte, dass Ihr nach Süden geht und Euch ein wenig "gärtnerisch" betätigt. Bei diesem kleinen Abenteuer gibt es zwei Zutaten, über die Ihr Bescheid wissen solltet: (1) Blätter und (2) Fuchskot. Wir brauchen beides.|n|nHabt Ihr Euch nie gefragt, woraus Tarnung besteht?|n|nGeht nach Süden und findet, worum ich Euch gebeten habe, $GFreund:Lady;.', },
    {'Sammelt 5 Blätterhaufen und 5 Portionen Fuchskot.', },
  },
  [26637] = {
    'Fernmeldeausrüstung der Bravo-Kompanie: Chloroform',
    {'Der erste Teil unserer Mission findet verdeckt statt, $N. Deshalb müssen wir in der Lage sein, unseren Feind lautlos auszuschalten. Um das zu erreichen, brauchen wir Chloroform.|n|nDie Drüsen der Matschwirbler am Grund des Immerruhsees enthalten Chloroform. Schwimmt hinunter und besorgt mir Matschwirblerdrüsen. Kriegt Ihr das hin?|n|nKehrt zu mir zurück, wenn Ihr genügend Drüsen gefunden habt.|n|nIhr wollt wissen, wo der See ist? Macht die Augen auf, Trottel. Unmittelbar westlich.', },
    {'Sammelt 8 Matschwirblerdrüsen.', },
  },
  [26638] = {
    'Jagd auf die Jäger',
    {'Südlich von hier, entlang des Uferpfads, lauern Schwarzfelsorcs in den Wäldern. Im Schutz der Dunkelheit überfallen sie die Ahnungslosen. Diese Orcs bilden die erste Verteidigungslinie der Schwarzfelsarmee. Es sind Kundschafter, die alles, was sie sehen, ihrem Oberkommando melden. Sie müssen AUSGESCHALTET werden, sonst könnten sie unsere Mission gefährden.|n|nGeht nach Süden und tötet alle Jäger des Schwarzfels, die Ihr seht.', },
    {'Tötet 8 Jäger des Schwarzfels.', },
  },
  [26639] = {
    'Kontaktpunkt: Brubaker',
    {'Wir müssen unser Marschgepäck zusammen bekommen, vorher sind wir verdammt unnütz. Dabei werdet Ihr helfen, $N. Kundschafter benötigen wir ebenfalls. Zum Glück haben wir Unterstützung aus Sturmwind erhalten. Brubaker, ein alter Kriegskamerad von mir, ist vom SI:7 geschickt worden, um uns als Kundschafter zu dienen. Trefft ihn im Kampfgebiet südlich von hier.|n|nTrefft Euch mit Brubaker und findet heraus, was er weiß.', },
    {'Findet Brubaker.', },
  },
  [26640] = {
    'Unaussprechliche Gräuel',
    {'<Ihr faltet die Notiz auseinander und beginnt zu lesen.>|n|nKeeshan, wenn Ihr diese Nachricht lest, werde ich tot sein. Wahrscheinlich wurde meine Position kompromittiert.|n|nDie Orcs begehen unaussprechliche Gräuel an ihren Gefangenen. Ja, Gefangene, Keeshan. Sie haben Käfige voll mit Kriegsgefangenen. Bevor Ihr dieses Tal in die Luft sprengt, müsst Ihr die Gefangenen befreien.|n|nSagt meiner Frau, dass ich sie liebe und dass sie den verdammten Müll rausbringen soll.|n|n-Brubaker|n|nPS - Sie haben schwarze Drachen.|n|nBringt Keeshan Brubakers Report.', },
    {'Bringt Brubakers Report zu John J. Keeshan im Immerruhlager im Rotkammgebirge.', },
  },
  [26641] = {
    'Eiertanz',
    {'Die Brutwachen der Blutfratzen im Nordosten bewachen die Eier von Shadras Brut. Auch wenn wir die Blutfratzen töten, werden diese schrecklichen Kreaturen irgendwann aus ihren Eiern schlüpfen und in die Wildnis entkommen.|n|nDas müssen wir verhindern. Reißt alle Eier, die Ihr findet, aus ihren Eiersäcken und bringt sie mir. Versucht nicht, sie selbst zu zerstören; die Kleinen könnten herauskommen.|n|nWenn Ihr wieder hier seid, sorge ich dafür, dass sie vernünftig entsorgt werden!', },
    {'Besorgt 5 Eier der Shadrabrut aus Agol\'watha.', },
  },
  [26642] = {
    'Erhaltung des Brachlands',
    {'Seit Jahren bildet das Brachland das Herz des Hordengebiets in Kalimdor. Es ist eine wichtige Verbindung zwischen den Orcs von Durotar und den Taurensiedlungen in Mulgore.|n|nIm Chaos des Kataklysmus drohen wir durch Überflutungen, Erdbeben und sogar einer Invasion der Stacheleber von diesem wichtigen Grasland abgeschnitten zu werden.|n|nIhr wirkt, als wärt Ihr bereit für eine Herausforderung. Meldet Euch bei Kargal Schlachtnarbe in der Fernwacht und stellt sicher, dass der Weg ins Brachland frei bleibt! Reist ins nahe gelegene Klingenhügel und von dort aus gen Westen. Überquert den Südstrom, dann werdet Ihr ihn finden.', },
    {'Meldet Euch bei Kargal Schlachtnarbe in der Fernwacht im Nördlichen Brachland.', },
  },
  [26643] = {
    'Hungerdiät',
    {'In den Gruselruinen östlich von hier wimmelt es von ausgewachsenen Spinnen der Shadrabrut. Sie sind so groß, dass sie einen ganzen Zwerg nachts davonschleppen können. Die Beweise dafür werdet Ihr sehen, wenn Ihr dort ankommt... eingesponnene Körper überall in den Ruinen.|n|nSie halten sie nicht lange am Leben, $N, aber von den Leichen ernähren sie sich tagelang. Den Opfern kann niemand mehr helfen, aber diese Spinnen dürfen nicht noch fetter und kräftiger werden. Sorgt dafür, dass diese Kokons verschwinden.', },
    {'Zerstört 6 eingesponnene Opfer in den Gruselruinen.', },
  },
  [26644] = {
    'Aufmerksamkeit erregen',
    {'$GDeckhelfer:Deckhelferin; $N! Das ist ein trauriger Tag für den alten Käpt\'n Kielhol. Heute verliere ich meinen besten Deckhelfer.|n|nIch habe einen Brief von Flottenmeister Firallon erhalten. Anscheinend hat er von Eurer guten Putzleistung gehört. Ihr sollt an Bord der Purpurschleier kommen und als $Gsein Bootsmann und Dritter Maat:seine Bootsfrau und Dritte Maatin; dienen. Sie liegt direkt neben der Springflut.|n|nDas ist \'n großer Schritt in Eurer Piratenkarriere, $GDeckhelfer:Deckhelferin; $N. Ich würde vorschlagen, sein Angebot anzunehmen.|n|nWegtreten!', },
    {'Meldet Euch bei Flottenmeister Firallon im Inneren der Purpurschleier am Schlingendornkap.', },
  },
  [26645] = {
    'Die Nachtwache',
    {'Ihr seid leider $Gder Einzige, der:die Einzige; die; mir hier helfen kann, $N. Die Streitkräfte Sturmwinds werden von weit größeren Gefahren bedroht. Sie können keinen einzigen Soldaten zum Schutz von Dunkelhain abstellen. Ich und die anderen aus der Nachtwache müssen uns um die Sicherheit unserer Heimat kümmern.|n|nLeider bedrohen uns nicht nur Wölfe. Verrottende Schrecken treiben nahe dem Spukhaus der blinden Mary am südöstlichen Stadtrand ihr Unwesen. Wenn wir sie nicht in Schach halten, werden sie in der Nacht unsere Häuser besuchen.|n|nKümmert Euch um die Untoten und meldet Euch bei mir, um belohnt zu werden.', },
    {'Tötet 8 verrottende Schrecken nahe dem Spukhaus der blinden Mary, südöstlich von Dunkelhain.', },
  },
  [26646] = {
    'Kriegsgefangene',
    {'Die Fernmeldeausrüstung der Bravo-Kompanie ist fertig, $N. Ich werde Euch damit ausrüsten. Ihr werdet Renders Tal, südöstlich von hier, betreten und unsere Kriegsgefangenen befreien. Ich gebe Euch Jorgensen mit. Er wird Euch den Rücken freihalten.|n|nDie Gefangenen sitzen im Nordosten des Tals in einem großen Käfig, aber der Schlüssel zu diesem Käfig befindet sich in einer Höhle im Süden des Tals. Ihr müsst den Schlüssel stehlen, für Ablenkung sorgen und die Bürger befreien.|n|nViel Glück, $N! Wir bleiben über den Fernmeldeapparat in Verbindung.', },
    {'Befreit die Kriegsgefangenen, die im Gefängnis von Renders Tal sitzen.', },
  },
  [26647] = {
    'Dicke Emma',
    {'Wir haben viel Arbeit vor uns. Wie viel Erfahrung habt Ihr mit Kanonen? Hmm... wirklich? Und wie sieht es mit uralten, zusammenbrechenden Piratenkanonen aus?|n|nAuf den Decks gibt es noch ein paar Kanonen, die auf die altmodische Weise funktionieren: Man lädt immer nur eine Kanonenkugel, zielt, arretiert und feuert. Funktioniert gut, wenn man die Seite eines Dreimasters treffen will... nicht so gut bei Ruderbooten und ähnlichem.|n|nGeht doch mal nach oben und feuert ein paar Schuss auf Timmy Grinsezweig ab.', },
    {'Übt die Benutzung der Kanone, indem Ihr Timmy Grinsezweig mit 5 Kanonenkugeln von der Dicken Emma trefft.', },
  },
  [26648] = {
    'Unsere Todfeinde',
    {'Hey, Neuling, seht Euch das mal an.|n|n<Der Zwerg hebt seine Augenklappe und enthüllt einen echten, funktionierenden Augapfel.>|n|nIch trage die Klappe nicht wegen eines verlorenen Auges. Ich trage sie, weil das ANDERE Auge so stark ist, dass es von dem normalen ausgebremst wurde.|n|nMit diesem Auge kann man alles Mögliche sehen, zum Beispiel die maskierten Schlägertypen, die uns folgen. Der Flottenmeister sagt, dass sie auf der Insel Jaguero aufgetaucht sind. Feuert diese Leuchtpistole ab, wenn Ihr dort eintrefft, und ich werde Euch helfen, sie auch zu sehen.', },
    {'Tötet 15 Ninjas auf der Insel Jaguero.', },
  },
  [26649] = {
    'Schießbudenpiraterie',
    {'Ihr wisst ja jetzt, wie man mit unseren Kanonen umgeht, also wird es Zeit, dass Ihr echte Ziele trefft!|n|nDie Venture Company hat nördlich von hier Gold gefunden... eine seltene Art, die sie "schwarzes Gold" nennen. Sieht für mich eher wie ein schwarzer Fleck aus.|n|nWir werden uns dieses Gold holen, aber zuerst müssen wir die Trottel der Venture Company los werden. Ein Ruderer wird Euch dort hinaus bringen. Verlasst das Schiff über die Laufplanke und sprecht mit ihm am Nordstrand der kleinen Insel.', },
    {'Sprecht mit dem Ruderer der Blutsegelbukaniere außerhalb der Purpurschleier und tötet dann 75 Ölarbeiter der Venture Co. mit der Kanone.', },
  },
  [26650] = {
    'Die "Maid im Glück"',
    {'Ich weiß ja, dass Ihr erst vor Kurzem auf der Purpurschleier angekommen seid, aber ich könnte Euch für \'ne andere Aufgabe gebrauchen. Die Maid im Glück ist das dritte Schiff in meiner Flotte. Sie liegt östlich von hier. Ihr Skipper, Kapitän Stillwasser, weilt nicht mehr unter uns.|n|nVerdammt seien diese maskierten Strolche!|n|nIn jedem Fall hat mir Stahlauge von Euren Heldentaten auf See erzählt, und mir gehen langsam die qualifizierten Briganten aus. Ich denke, dass Ihr mehr als nur in der Lage sein werdet, Eure neuen Pflichten zu erfüllen.|n|nHerzlichen Glückwunsch, $GKumpel:Mädchen;. Ihr seid $Gder neue Kapitän:die neue Kapitänin; der Maid im Glück.', },
    {'Meldet Euch in Eurer Kapitänskajüte im Inneren der Maid im Glück am Schlingendornkap.', },
  },
  [26651] = {
    'Um einen Krieg zu gewinnen, müsst Ihr zum Krieg werden',
    {'<Das Funkgerät der Kompanie Bravo piept.>|n|nVersteht Ihr es schon, $N? Wisst Ihr jetzt, was wir tun müssen, um einen Krieg gegen diese Ungeheuer zu gewinnen? IHR MÜSST ZUM KRIEG WERDEN! KEINE GNADE!|n|nDie Kriegsgefangenen sind befreit. Ihr könnt das Zephyrium anbringen. Betretet vorsichtig die Gebäude dort draußen und bringt je einen Sprengsatz an.|n|nBringt je eine Zephyriumladung an der Munitionshütte des Schwarzfels und am Turm des Schwarzfels an. Trefft Euch mit mir und dem Rest der Kompanie Bravo in der Schieferwindschlucht östlich von Renders Tal.', },
    {'Bringt mit der Fernmeldeausrüstung der Bravo-Kompanie je eine Zephyriumladung am Turm des Schwarzfels und an der Munitionshütte des Schwarzfels an.', },
  },
  [26652] = {
    'Geisterhaarfaden',
    {'Es gibt da einen armen, traurigen Geist, die blinde Mary, die in einem alten Bauernhaus in den Hügeln südlich von Dunkelhain spukt.|n|nHier, nehmt diesen spektralen Kamm und bittet die blinde Mary, sich die Haare zu kämmen. Bringt mir anschließend den Kamm zurück, dann entnehme ich ihm das Geisterhaar, das ich für den Faden brauche.|n|nUnd seht Euch vor, denn in der Nähe dieses Hauses lauern üble Dinge...', },
    {'Bringt der blinden Mary den spektralen Kamm.', },
  },
  [26653] = {
    'Lieferung aus Dunkelhain',
    {'Ach, was soll ich armer, alter Mann nur machen? Ich brauche einige Vorräte aus Dunkelhain, aber das Dorf ist so weit weg und ich bin so alt und schwach... ich würde die Reise niemals überstehen.|n|nKönnt Ihr nach Dunkelhain reisen und mir etwas Geisterhaarfaden mitbringen? Den bekommt Ihr im Haus von Madame Eva am Dorfplatz von Dunkelhain.', },
    {'Sprecht mit Madame Eva in Dunkelhain.', },
  },
  [26654] = {
    'Rückkehr mit dem Kamm',
    {'NEIN!!!!!|n|nNehmt ihn weg, nehmt diesen Kamm weg!|n|nIch bin ein Monster und niemand wird mich jemals wieder für schön halten!', },
    {'Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain.', },
  },
  [26655] = {
    'Abliefern des Fadens',
    {'Hier ist Euer Faden, $N. Man kann tausend Dinge damit machen, zum Beispiel böse Geister binden oder unbelebte Gegenstände mit Leben erfüllen.', },
    {'Bringt den Geisterhaarfaden zu Calvinius in seinem Turm im Bettlerschlupfwinkel.', },
  },
  [26656] = {
    'Immer. In. Bewegung. Bleiben.',
    {'Als Todesschwinge kam, sind die Steindrachen zu ihm geschwärmt. In seiner Abwesenheit fehlt ihnen jegliche Bestimmung. Sie streifen durch die Gegend und fressen unseresgleichen.|n|nIch habe Dutzende von opalschimmernden Wächtern gebunden, aber ich kann sie nicht aus der sicheren Deckung führen. Ich brauche jemanden, der schneller ist, und ich glaube, Ihr seid genau richtig für diese Aufgabe.|n|nFührt sie am Boden Richtung Therazanes Thron im Osten. Einige werden es sicher nicht schaffen, aber solange Ihr nicht stehenbleibt, solltet Ihr einige von ihnen zu unseren Truppen führen können.', },
    {'Hetzt mindestens 5 opalschimmernde Wächter nach Osten aus dem Bleichen Hort hinaus, zum Steinkreis in der Nähe von Therazanes Thron.', },
  },
  [26657] = {
    'Ein harter Fall',
    {'Steindrachen lassen sich nur von Stärke beeindrucken. Wenn wir sie ausreichend bestraft haben, werden sie sich unserem Willen unterwerfen.|n|nIch habe eine Vielzahl meiner stärksten Riesen auf die Felder im Westen geschickt. Sie werden die Drachen zu Boden befördern. Ihr kümmert Euch dann darum, dass sie sich nach ihrem Fall nicht wieder in die Lüfte schwingen.', },
    {'Tötet 6 Steindrachen.', },
  },
  [26658] = {
    'Zerbrechliche Werte',
    {'Jetzt ist es an der Zeit, die Aufmerksamkeit der Brutmutter zu erregen. Dazu benötigen wir einen Hammer, den die Troggs während der Opferzeremonie für sie benutzen.|n|nSucht die Bestienzähmer der Steintroggs, die im südlichen Teil des Bleichen Horts versuchen, Basilisken zu zähmen. Einer von ihnen trägt einen Hammer bei sich.', },
    {'Beschafft einen Mauerhammer.', },
  },
  [26659] = {
    'Nachhallender Schlag',
    {'Ihr werdet einen Resonanzkristall am westlichen Rand des Bleichen Horts finden. Schlagt mit dem Hammer darauf, dann wird die Brutmutter kommen.|n|nMacht Euch für einen Kampf bereit. Ich werde dort sein, um Euch zu helfen, aber sie wird sich nicht leicht geschlagen geben.', },
    {'Besiegt Aeosera.', },
  },
  [26660] = {
    'Zombiesaft',
    {'Ich brauche eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Schankwart Smitts aus der Taverne "Zum Roten Raben" in Dunkelhain sollte welchen haben.|n|nUnd bitte sputet Euch, $N. Die Nächte sind kalt und ich brauche den Schnaps, um meine Adern wieder mit Feuer zu erfüllen!', },
    {'Sprecht mit Schankwart Smitts.', },
  },
  [26661] = {
    'Das Sammeln von Faulblüten',
    {'Wenn Ihr mir einige Fäulnisblüten bringt, kann ich Zombiesaft für Euch brauen.|n|nFäulnisblüten wachsen an seltsamen Orten. Sie wachsen besonders gut auf Dingen, die tot sind. Im Dämmerwald gibt es jede Menge davon!|n|nIch habe einige im Friedhof "Stille Gärten" gesehen. Sucht in der Nähe der Gräber... aber achtet auf die Toten, die dort umherwandern.', },
    nil,
  },
  [26662] = {
    'Die Mannschaft der Trümmerflut',
    {'Auf den Karten wird eine Gruppe namens Mannschaft der Trümmerflut erwähnt. Der Name ist Euch nicht bekannt, obwohl Ihr schon von einigen anderen neuen Bukanieren gehört habt.|n|nBesucht sie doch mal und findet heraus, was sie wissen.', },
    {'Sprecht mit Long John Copper auf der Maid im Glück, Shawn Stooker dem Koloss auf der Purpurschleier und der klagenden Mary Smitts auf der Springflut.', },
  },
  [26663] = {
    'Versenkung aus dem Inneren',
    {'Der Angriff auf Beutebucht steht kurz bevor. Kehrt rasch nach Beutebucht zurück und informiert den Baron.|n|nSo lange Ihr bei den Piraten noch angesehen seid, wäre es aber gut, wenn Ihr deren Vorräte sabotieren würdet. Die Piraten bewahren die meisten ihrer Vorräte unter Deck auf. Sie sind auf die ganze Flotte verteilt.', },
    {'Sabotiert das Fass mit Grog, das Fass mit Schießpulver und die Kiste mit Kanonenkugeln.', },
  },
  [26664] = {
    'Meutereimacher',
    {'Bevor Ihr nach Beutebucht zurückkehrt, solltet Ihr alles tun, um die Blutsegelbukaniere zu schwächen. Leider ist es Euch selbst als $GKapitän:Kapitänin; verboten, andere Bukaniere kaltblütig zu töten. Das darf nur ein Flottenmeister.|n|nAllerdings dürft Ihr Meuterer zu Tode bringen... und Meuterei lässt sich nur schwer widerlegen.|n|nApropos, diese Blutsegelkorsaren, die auf den untersten Decks der Schiffe herumhängen, benehmen sich in letzter Zeit wirklich sehr verdächtig...', },
    {'Beschuldigt 9 Korsaren der Blutsegel der Meuterei und tötet sie dann.', },
  },
  [26665] = {
    'Der Ruf der Beute',
    {'Ihr habt den Eindruck, dass Ihr genug Schaden angerichtet habt. Ihr kennt außerdem die Schlachtpläne der Blutsegelbukaniere. Ihr habt alles getan, um das Euch Baron Revilgaz gebeten hat.|n|nEs ist Zeit, den Piratenhut an den Nagel zu hängen und nach Beutebucht zurückzukehren. Der Moment der Schlacht naht.', },
    {'Meldet Euch bei Baron Revilgaz in Beutebucht am Schlingendornkap.', },
  },
  [26666] = {
    'Die Legende von Stalvan',
    {'Ich bin hier, weil mein Bruder Stalvan, den ich seit Jahren nicht gesehen habe, mir einen Brief geschickt hat. Als ich hier eintraf, sagte man mir, er sei tot...|n|nDie ganze Stadt weigert sich, mir mehr zu erklären. Sie reagieren misstrauisch und ängstlich, wenn ich seinen Namen erwähne. Als ob ich mich nicht selbst schon so fühlen würde!|n|nIch habe Angst vor dem, was passieren könnte, wenn mein Ärger und mein Frust zunehmen. Bitte helft mir, der Sache auf den Grund zu gehen. Fragt Amtmann Daltry nach allen Informationen, die er über meinen Bruder besitzt.', },
    {'Sucht Amtmann Daltry im Rathaus von Dunkelhain auf.', },
  },
  [26667] = {
    'Die gestohlenen Briefe',
    {'Ihr wollt etwas über Stalvan wissen...|n|nIhr seid nicht $Gder:die; erste, wisst Ihr das? Fremde kommen ab und zu hier durch und fragen nach ihm. Immer nur Fremde. Alle, die hier leben, wissen es besser.|n|nWie dem auch sei, Ihr habt Pech. Die Hälfte meiner Archive ist weg. Wilde Worgen sind vor ein paar Nächten ins Rathaus eingebrochen und haben alles in Stücke gerissen. Die Dokumente, nach denen Ihr sucht, sind mittlerweile wahrscheinlich in ganz Schattenhain verstreut, tief in den Wäldern im Westen. Sind die Suche nicht wert, wenn Ihr mich fragt.', },
    {'Findet das Bündel zerrissener Briefe in Schattenhain.', },
  },
  [26668] = {
    nil,
    {'Der Sprengstoff, den Ihr angebracht habt, ist hochexplosiv, $N. Wenn ich diesen Knopf an der Fernmeldeausrüstung der Bravo-Kompanie drücke, wird das ganze Tal in einem gigantischen Feuerball des Todes vergehen.|n|nWisst Ihr was? Ich glaube, die Ehre gebührt Euch. Die ganze harte Arbeit ist schließlich an Euch hängen geblieben.|n|nBereit?', },
    {'Sprengt Renders Tal in die Luft.', },
  },
  [26669] = {
    'In einer dunklen Ecke',
    {'Wenn es Euch wirklich ernst ist, helfe ich Euch, $N. Ich weiß, wo die anderen Dokumente sein müssen. Ich habe zu viel Angst, um etwas zu unternehmen.|n|nEs gibt nur wenige Orte, an denen sich diese furchtbaren Schrecken der Nacht versammeln, wenn sie nicht gerade den Wald durchstreifen. Einer davon ist der Verrottende Obstgarten im Süden. Sie benutzen die Gebäude als Schlupfwinkel. Wenn sie die Dokumente nicht einfach gefressen haben, werdet Ihr sie wahrscheinlich dort finden... aber ich wette, dass Ihr ihre Verstecke gründlich durchsuchen müsst.', },
    {'Durchsucht den Verrottenden Obstgarten nach der zerrissenen Tagebuchseite.', },
  },
  [26670] = {
    'Rolands Verdammnis',
    {'Das ist nicht alles...|n|nLasst es sein, $N. Eure Suche kann Euch nur noch nach Rolands Verdammnis führen. Das ist eine Mine südlich der Stadt und der größte Worgenbau in ganz Dämmerwald. Niemand in Dunkelhain hat diesen Ort je lebend verlassen. Einige der Berichte, die ich hier habe, weisen daraufhin, dass diese Ungeheuer dort ihren Ursprung haben... wer weiß, welches Böse sich darin verbirgt?|n|nBitte gebt auf, $N. Lasst uns die ganze Sache vergessen und nie wieder davon sprechen.', },
    {'Sucht in Rolands Verdammnis nach den restlichen Seiten von Stalvans Tagebuch.', },
  },
  [26671] = {
    'Das Schicksal von Stalvan Dunstmantel',
    {'Ihr habt alles gefunden. Alles, bis auf die letzte Seite...|n|n...die ich hier habe. Seht mich nicht so an. Ihr werdet alles verstehen, wenn Ihr sie gelesen habt. Einige behaupten sogar, sie sei verflucht. Um ehrlich zu sein, war ich erleichtert, als die Worgen eingebrochen sind und die Seiten gestohlen haben!|n|nNehmt sie. Ach nein, nehmt alle. Ich danke Euch dafür, dass Ihr meine Archive wiederbeschafft habt, aber ich will nichts mehr mit der Sache zu tun haben. Lasst mich bitte in Ruhe.', },
    {'Bringt die Legende von Stalvan zurück zu Tobias Dunstmantel.', },
  },
  [26672] = {
    'Der Wahrheit auf den Grund gehen',
    {'Das kann nicht sein. Mein Bruder hatte einen starken Willen, aber eine solche Boshaftigkeit... so etwas brutales, blutiges, krankes...|n|n<Tobias hebt eine Hand vor sein Gesicht und wendet den Blick ab.>|n|nIch brauche Antworten. Ich muss wissen, wie mich dieser Brief erreicht hat. Ich muss wissen, ob Stalvan das wirklich getan hat.|n|nIch muss wissen, warum...|n|nNehmt meinen Ring, $N. Bringt ihn zu Madame Eva. Diese Frau ist eine Anhängerin der alten Künste und verbirgt das auch nicht... es ist vielleicht verrückt, aber ich bin soweit, alles zu versuchen.', },
    {'Bringt Madama Eva den Familienring der Dunstmantels.', },
  },
  [26673] = {
    'REUSE - BREADCRUMB#',
    {'Das kann nicht sein. Mein Bruder hatte einen starken Willen, aber eine solche Boshaftigkeit... so etwas brutales, blutiges, krankes...|n|n<Tobias hebt eine Hand vor sein Gesicht und wendet den Blick ab.>|n|nIch brauche Antworten. Ich muss wissen, wie mich dieser Brief erreicht hat. Ich muss wissen, ob Stalvan das wirklich getan hat.|n|nIch muss wissen, warum...|n|nNehmt meinen Ring, $N. Bringt ihn zu Madame Eva. Diese Frau ist eine Anhängerin der alten Künste und verbirgt das auch nicht... es ist vielleicht verrückt, aber ich bin soweit, alles zu versuchen.', },
    {'Bringt Madama Eva den Familienring der Dunstmantels.', },
  },
  [26674] = {
    'Dunstmantels Rache',
    nil,
    nil,
  },
  [26675] = {
    'Der Wert des Vertrauens',
    {'Die Probleme dieser Welt scheinen nie zu vergehen. Sie verschieben und verändern sich, bilden sich neu, aber sind doch stets vorhanden.|n|nDer Wind hat uns Gerüchte über einen Verräter in unserer Mitte zugeflüstert. Wir haben eine unserer besten Schildwachen mit den Nachforschungen betraut, doch sie wurde tot aufgefunden. Ich habe das zu verantworten, da ich annahm, der Verräter wisse nichts von unserem Vorgehen... Ich handelte unüberlegt, und sie musste den Preis für meine Dummheit bezahlen.|n|nIch brauche ein fremdes Gesicht, um die Spur wieder aufzunehmen. Jemanden, den die Leute in der Stadt nicht kennen. Das ist eine gefährliche Bitte. Werdet Ihr mir helfen?', },
    nil,
  },
  [26676] = {
    'Saftlieferung',
    {'Hier habt Ihr Euren Zombiesaft...|n|n... aber passt mir mit dem Zeug auf. Es ist stark genug, um die Toten zu erwecken!', },
    {'Bringt Calvinius den Zombiesaft im Bettlerschlupfwinkel.', },
  },
  [26677] = {
    'Ein Ghulbildnis',
    {'Es ist ein Wunder, dass die lebenden Toten mich hier draußen am Stadtrand noch nicht gefressen haben! Erst gestern hat eine Horde Ghule beinahe die Wände meines Turms eingeschlagen!|n|nIch möchte ein Abbild herstellen - eine Art "Vogelscheuche" für Ghule. Dafür benötige ich einige Ghulrippen. Rund um das Anwesen der Dunstmantels, nördlich von Dunkelhain, wandern stinkende Leichname umher, bei denen ihr jede Menge finden solltet...|n|nBesorgt mir die Rippen, dann werde ich Euch mit einigen Münzen belohnen.', },
    {'Sammelt 7 Ghulrippen von Stinkenden Leichnamen auf dem Anwesen der Dunstmantels.', },
  },
  [26678] = {
    'Doppelrolle',
    {'<Baron Revilgaz seufzt.> Ich habe zwar Teile von Firallons Plan erahnt, aber trotzdem sind wir nicht auf die beiden Frontalangriffe der Blutsegel und der Trümmerflut vorbereitet. Wir werden ein kleines Wunder brauchen, um Beutebucht an diesem Tag zu halten.|n|nIch habe ein Fass Doppelrum in meinem Quartier. Steigt die Treppe drei Stockwerke hinunter und nehmt die erste Tür zu Eurer Rechten. Ihr könnt die Warnungen auf dem Fass ignorieren... sie sollten Eure geringste Sorge sein.', },
    {'Findet Baron Revilgaz\' Fass mit Doppelrum in Beutebucht.', },
  },
  [26679] = {
    'Kehrt zu Revilgaz zurück',
    {'Draußen geschieht etwas. Sind die Blutsegelbukaniere etwa schon hier?|n|nBringt Revilgaz seinen Doppelrum. Schnell.', },
    {'Bringt Baron Revilgaz in Beutebucht den Doppelrum.', },
  },
  [26680] = {
    'Ogerdiebe',
    {'Vor ein paar Wochen wurde ich von einer Bande Ogern angegriffen, als ich draußen Kräuter sammelte, ziemlich weit von meinem Haus entfernt. Ich lief davon und musste eine Kiste mit wertvollen Werkzeugen und Kräutern zurücklassen.|n|nNachdem sie mich vertrieben hatten, stolzierten die Oger zurück zum Ogerhort im südlichen Dämmerwald. Ich bin mir sicher, dass meine Kiste irgendwo in der Nähe des Hügels sein muss.|n|nBitte, $N, beschafft mir diese Kiste wieder, denn sie fehlt mir sehr.', },
    {'Bringt Calvinius\' Kiste zu Calvinius.', },
  },
  [26681] = {
    'Ein Brief für den Bürgermeister',
    {'Bringt diese Nachricht zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.|n|nEr und ich sind alte Freunde, und wenn er den Zettel liest und herausfindet, was Ihr für mich getan habt... dann freut er sich bestimmt genauso sehr, wie ich das tue! Hahahaha!', },
    {'Bringt Calvinius\' Brief zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.', },
  },
  [26682] = {
    'Eine torkelnde Bedrohung',
    {'Düstermarschen ist das Gebiet der Horde, $N. Die Menschen haben ihre kleine Insel und ihre heißgeliebte Sandbank, aber die Sümpfe gehören uns.|n|nIrgendwann werden wir diese Pattsituation mit den Menschen auch noch klären. Doch erst einmal müssen wir unser eigenes Gebiet beherrschen. Die Moderrankenmorastbestien im Norden tauchen aus dem Sumpf auf und greifen jedes Lebewesen an, das sich ihnen nähert. Wenn wir diese Marschen beherrschen wollen, dann darf sich unser Land nicht gegen uns wenden!|n|nTötet die Morastbestien, wenn Ihr der Horde dienen wollt. Man wird Euch belohnen.', },
    {'Tötet 7 Moderrankenkrabbler oder Moderrankenwüteriche im Sumpf nördlich von Brackenwall.', },
  },
  [26683] = {
    'Der Blick zu den Sternen',
    {'Mein Gnomenfreund Zinken hat versprochen, mir beim Bau eines Geräts zu helfen, mit dem man zu den Sternen blicken kann. Laut Zinkens Blaupause muss ich zuerst eine Möglichkeit finden, das Licht zu reflektieren.|n|nIch erinnere mich an eine Frau namens Mary, die in dieser Gegend rasch bekannt wurde, weil sie stets einen Handspiegel bei sich trug. Könntet Ihr vielleicht Mary suchen und sie fragen, ob sie uns eine reflektierende Oberfläche für dieses Projekt leihen würde? Ich glaube, sie lebte früher im südlichen Dämmerwald...', },
    {'Findet Mary und überredet sie, einen Gegenstand mit reflektierender Oberfläche zu Viktoris Projekt beizusteuern.', },
  },
  [26684] = {
    'Der irrsinnige Ghul',
    {'Der Handspiegel war eines meiner wertvollsten Besitztümer bis zu... dem Vorfall. Danach warf ich den Spiegel hinter der Scheune fort. Es gab da einen irrsinnigen Ghul, der sich früher dort hinten herumgetrieben hat. Vielleicht hat der ihn aufgehoben und mitgenommen. Gerüchten zufolge haust die teuflische Bestie im Friedhof Stille Gärten.', },
    {'Erbeutet Marys Handspiegel von dem irrsinnigen Ghul.', },
  },
  [26685] = {
    'Feines Glas',
    {'Jetzt brauchen wir nur noch einen weiteren Gegenstand, um das Gerät fertig zu stellen. Laut Cogs Blaupause wird eine Linse oder etwas in der Art benötigt. Die einzige Linse, von der ich weiß, dass sie groß genug wäre, wird sehr schwierig zu beschaffen sein.|n|nEs gibt da einen Oger namens Zzarc\'Vul, der im Ogerhort im Süden des Dämmerwalds haust. Wenn Ihr könnt, bringt mir sein Monokel, dann werde ich das als unsere Linse verwenden.', },
    {'Tötet Zzarc\'Vul auf dem südlichen Ogerhügel in Dämmerwald und erbeutet sein Ogermonokel.', },
  },
  [26686] = {
    'Wandelnde Knochen',
    {'Ihr werdet Euch mit noch fauligeren Untoten herumschlagen müssen, $N.|n|nDer Friedhof "Stille Gärten" etwas weiter südlich der Stadt ist ein Ort, an dem man sich nachts nicht blicken lassen sollte. Die Knochen, die sich dort aus dem Boden erheben, sind klug genug, um sich daran zu erinnern, wie man eine Axt schwingt oder einen Zauber wirkt.|n|nIch muss wohl nicht erklären, wie gefährlich sie das macht. Seid vorsichtig, aber denkt daran, dass das Volk von Dunkelhain leiden wird, wenn Ihr scheitert.', },
    {'Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass ihr 5 Skelettkrieger und 5 Skelettmagier vernichtet.', },
  },
  [26687] = {
    'Verstärkung aus Theramore',
    {'Hawthorne tot... mein eigener Sohn ermordet... die Lage im Brachland ist außer Kontrolle, $N.|n|nIch werde das Kommando über die Triumphfeste übernehmen und versuchen, für Ruhe zu sorgen. Doch dazu benötige ich Verstärkung. Verstärkung, die man mir in Theramore schon vor Wochen versprochen hat!|n|nReist nach Theramore in den Düstermarschen und blast Hauptmann Garran Mumm den Marsch. Welchen Zweck erfüllt diese verdammte Straße durch den Sumpf, wenn Soldaten und Material trotzdem nicht kommen?', },
    {'Reist zur Insel Theramore in den Düstermarschen und sprecht mit Hauptmann Garran Mumm in der Hauptkaserne.', },
  },
  [26688] = {
    'Worgen in den Wäldern',
    {'Es scheint, als würden dunkle Dinge unaufhaltsam in den Dämmerwald gezogen. Meister Treuwein hat sich der Aufgabe verschrieben, das Böse und die Ketzerei zu vertreiben. Dank unserer Anstrengungen lebt das Volk von Dunkelhain in Sicherheit.|n|nIhr glaubt, Ihr seid würdig, Euch unserer Gruppe anzuschließen?|n|nEinst dachte ich wie Ihr. Die Selbstzufriedenheit der Wache hatte mich meiner Illusionen beraubt und so schloss ich mich Meister Treuwein an. Wenn Ihr Euch beweisen möchtet, so kann dies nicht durch Worte geschehen.|n|nMesst Eure Fertigkeiten an den Worgen der Nachtheuler im Schattenhain. Wir werden sehen, ob Ihr in der Lage seid, es mit diesen Monstern aufzunehmen.', },
    {'Tötet 7 Worgen der Nachtheuler im Schattenhain.', },
  },
  [26689] = {
    'Der Verrottende Obstgarten',
    {'Die Worgenplage erstreckt sich über Schattenhain hinaus. Im Süden, ganz am Rand von Dunkelhain, liegt der Verrottende Obstgarten. Dort findet man noch wildere Bestien.|n|nDie Worgen dort sind listiger, $N, aber ebenso grausam und böse. Sie beschwören verdorbene Schatten, die ihre Feinde aus der Entfernung in Stücke reißen. Geht zum Verrottenden Obstgarten und tötet die Schattenwirker, um die Stadt zu beschützen!', },
    {'Tötet 10 Schattenwirker der Nachtheuler im Verrottenden Obstgarten.', },
  },
  [26690] = {
    'Faulig und besudelt',
    {'Eure früheren Leistungen haben mich überzeugt, dass Ihr in der Lage seid, Euch mit den zähesten Worgen zu messen, die sich in den Wäldern eingenistet haben.|n|nVon all den Worgen, die plötzlich hier zu finden sind, haben sich die Faulreißer und die Besudelten als die gefährlichsten herausgestellt. Sie haben sich in der Nähe einiger Höhlen und in der Mine im Süden niedergelassen.|n|nNoch aus weiter Entfernung sieht man die Lichter ihrer Feuer...', },
    {'Tötet 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler in Rolands Verdammnis.', },
  },
  [26691] = {
    'Worgen in den Wäldern',
    {'Hier, bitte schön, $N. Bringt Meister Treuwein diese Nachricht.|n|n<Schnell zieht er ein Stück verblasstes Pergament hervor und reicht es Euch.>|n|nNoch ein paar mehr wie Ihr, dann sind wir bald mehr Kämpfer als die Nachtwache! Vielleicht können wir dann das Werk vollenden, an dem wir wenigen uns heute noch vergebens abmühen.', },
    {'Bringt Calors Notiz zu Jonathan Treuwein.', },
  },
  [26692] = {
    'Ausrottung der Schattenfelle',
    {'Da von den Schwarzfelsorcs südlich vom Immerruhsee nichts außer Asche und Kohle übrig geblieben ist, können wir unsere Aufmerksamkeit auf die Armee der Schattenfellgnolle im Galardelltal unmittelbar nördlich von hier richten.|n|nGeht hinaus und bringt sie alle um, $N! Beginnt mit der Operation: Ausrottung, Soldat. Für die Kompanie Bravo und für die Allianz!', },
    {'Tötet 20 beliebige Gnolle der Schattenfelle.', },
  },
  [26693] = {
    'Der dunkle Turm',
    {'Wir hatten Glück. Die Bewohner dieses Tals haben uns wichtige Informationen gegeben. Die beiden hinter uns, die Ranthals, haben mir berichtet, dass die Gnolle im Galardelltal von einem mächtigen Magus im Turm von Ilgalar kontrolliert werden. Das Problem ist, dass dieser Turm durch ein magisches Kraftfeld versiegelt wird.|n|nAls erstes brauchen wir den Schlüssel, damit Ihr ins Innere vorstoßen könnt. Fangor, der Gnollgeneral, besitzt Eure Fahrkarte ins Innere. Tötet General Fangor und holt Euch den Schlüssel.|n|nIch melde mich.', },
    {'Erbeutet den Schlüssel von Ilgalar.', },
  },
  [26694] = {
    'Der Großmagus Doane',
    {'<Die Fernmeldeausrüstung der Bravo-Kompanie vibriert.>|n|nGute Arbeit, Grünschnabel. Ich habe wichtige Informationen für Euch. Der Magus in dem Turm ist ein Mensch namens Doane. Der verdammte Verräter arbeitet für die Schwarzfelsorcs. Ich will seinen Tod.|n|nVerschafft Euch mit dem Schlüssel von Ilgalar einen Weg ins Innere des Turms. Arbeitet Euch bis zur Spitze vor und zeigt Doane, was die Kompanie Bravo mit Verrätern macht.|n|nKehrt zum Treffpunkt Schieferwindschlucht zurück, wenn die Tat vollbracht ist.|n|nKeeshan Ende und aus.', },
    {'Tötet Großmagus Doane.', },
  },
  [26695] = {
    'Startvorbereitungen',
    {'Ich habe eine Idee, die etwas Laufarbeit von Euch erfordert. Die Schwarzmeerräuber sind ein Kartell der Goblins. Deshalb haben sie Zugang zu jeder Menge Sprengstoff. Ich weiß sogar, dass unser alter Freund Narkk eine ganze Kiste hinten in seinem Laden in der Alten Hafenbehörde aufbewahrt.|n|nHolt sie Euch und bringt sie her, wenn sie noch nicht hochgegangen ist.', },
    {'Besorgt Narkks Handbomben aus der Alten Hafenbehörde in Beutebucht.', },
  },
  [26696] = {
    'Der Ruf von Kalimdor',
    {'Sagt mal, Ihr habt nicht zufällig einen etwa so großen Fisch gesehen? Kurze Flossen? Hört auf den Namen Steve?|n|nEgal, ich such\' einfach weiter.|n|nAber... es gibt einen anderen Grund, aus dem ich nach Beutebucht gekommen bin. Boss Krog, drüben in den Düstermarschen, sucht neue Arbeiter.|n|nWartet am Ende des Piers auf das nächste Schiff, dann fahrt nach Ratschet. Gazlowe sollte Euch von da aus weiterhelfen können.|n|nSteve? Steve!', },
    {'Nehmt das Schiff von Beutebucht nach Ratschet und sprecht dort mit Gazlowe.', },
  },
  [26697] = {
    'Die letzte Reise der Trümmerflutpiraten',
    {'Wir werden diesen Angriff nicht überstehen, wenn all diese Worgenpiraten von Norden in den Hafen einfallen. Zum Glück sieht es so aus, als wären sie nicht mit Kanonen bewaffnet. Wenn es uns gelingt, Euch aus dem Hafen zu bringen, könnt Ihr sie aus der Luft angreifen.|n|nIhr findet Kebok, den Assistenten des Windreitermeisters der Horde, gleich um die Ecke. Erklärt ihm, dass Ihr seinen mutigsten Windreiter benötigt.|n|nNehmt all die Handbomben mit, die Ihr tragen könnt. Ihr werdet sie brauchen, um die Landungsboote aufzuhalten!', },
    {'Sprecht mit Kebok in Beutebucht und schwingt Euch auf einen tapferen Windreiter. Tötet dann mit den Handbomben 85 Crewmitglieder der Trümmerflutpiraten und zerstört 6 Landungsboote der Trümmerflutpiraten.', },
  },
  [26698] = {
    'Auf der Suche nach Seehorn',
    {'Als die Trümmerflutpiraten ankamen, griff Seehorn nach der ersten Waffe, die er in die Hände bekam und sprang von diesem Vorsprung. Ihr werdet ihn da unten finden. Wahrscheinlich schlägt er ein paar neue Löcher in diese Worgenschädel.|n|nHelft ihm. Um die Motivation kümmere ich mich von hier oben.', },
    {'Meldet Euch bei Flottenmeister Seehorn in Beutebucht.', },
  },
  [26699] = {
    'Die Abwehr der Trümmerflutpiraten',
    {'Die Trümmerflutpiraten sind überall! Die Haudraufs von Beutebucht, die der Baron angeworben hat, haben einer solchen Überzahl nichts entgegen zu setzen.|n|nWährend Ihr dort unten seid, könntet ihr mir helfen, ein paar von ihnen los zu werden?|n|nWenn Ihr fertig seid, macht Euch nicht die Mühe wieder heraufzukommen. Ich werde wahrscheinlich ziemlich beschäftigt sein.', },
    {'Tötet 10 Räuber der Trümmerflutpiraten in Beutebucht.', },
  },
  [26700] = {
    'Die Maid im (Un)Glück',
    {'Ich habe gehört, dass dieses Schiff hier Die Maid im Glück heißt. Wart Ihr nicht mal $Gder Kapitän:die Kapitänin; von diesem Kahn? Dann kennt Ihr Euch dort ja aus.|n|nDie Trümmerflutpiraten sind unsere Hauptsorge, aber wir können auch nicht einfach zusehen, während wir mit diesen Kanonen beschossen werden. Ergreift das Seil hinter mir und erledigt ein paar dieser wütend aussehenden Korsaren. Meldet Euch beim Baron, wenn Ihr fertig seid.', },
    {'Tötet 8 Korsaren der Blutsegelbukaniere in Beutebucht.', },
  },
  [26701] = {
    'Flug nach Brackenwall',
    {'Hört mal, die Horde liegt mir nicht gerade am Herzen... aber andererseits hasse ich Euch auch nicht unbedingt.|n|nEuer Gold ist so gut wie das jedes Anderen.|n|nDieser zweiköpfige Oger und sein Fisch haben etwas Gold für Eure Reisespesen dagelassen. Ich glaube, die Person, die Ihr dort sucht, heißt Krog. Und die beste Art, dort hinzugelangen, ist unser Flugmeister Bragok. Er lässt Euch hinfliegen, wenn Ihr wollt. Dank Eures Freundes ist der Flug kostenlos.', },
    {'Sprecht mit Bragok in Ratschet, um nach Brackenwall zu fliegen. Meldet Euch dann bei Krog.', },
  },
  [26702] = {
    'Flug nach Theramore',
    {'Hört mal, die Allianz liegt mir nicht gerade am Herzen... aber andererseits hasse ich Euch auch nicht unbedingt.|n|nEuer Gold ist so gut wie das jedes Anderen. Manchmal besser.|n|nJeyne hat etwas Gold für Eure Reisespesen dagelassen. Ich glaube, die Person, die Ihr dort sucht, heißt Calia Hastings. Und die beste Art, dort hinzugelangen, ist unser Flugmeister Bragok. Er lässt Euch hinfliegen, wenn Ihr wollt. Dank Eures Freundes ist der Flug kostenlos.', },
    {'Sprecht mit Bragok in Ratchet, um nach Theramore zu fliegen. Meldet Euch dann bei Calia Hastings.', },
  },
  [26703] = {
    'Streicht die Blutsegel',
    {'Dass der Sieg zum Greifen nah ist, haben wir fast allein Euch zu verdanken. Es bleibt jedoch noch eine letzte Aufgabe... tötet Flottenmeister Firallon.|n|nEin Großteil von Firallons Mannschaft scheint bereits tot zu sein, aber ich kenne den alten Seebären nur zu gut. Er ist noch nicht erledigt. Nein, er hat sich bestimmt in seiner Kajüte verbarrikadiert, um mit seinem Schiff unterzugehen.|n|nSprecht noch einmal mit Kebok. Er wird Euch einen Windreiter geben. Ich versuche den Kanonenbeschuss zu unterbrechen, während Ihr an Bord seid.', },
    {'Sprecht mit Kebok in Beutebucht, lasst Euch einen Windreiter geben und tötet Flottenmeister Firallon.', },
  },
  [26705] = {
    'Ein Verfolgerereignis in Instastadt!',
    nil,
    nil,
  },
  [26706] = {
    nil,
    {'Wir müssen dieses fliegende Kanonenboot loswerden, wenn unser Volk eine Chance auf Flucht haben möchte.|n|nSo lautet der Plan. In Kielwasser trieben sich früher einige sympathisierende Rebellen herum. Ich konnte eine beträchtliche Menge Sprengstoff aus einem unserer Lager besorgen.|n|nWir werden den Feind mit einer Kraft überrumpeln, die so klein ist, dass sie sich unentdeckt durch die Luft bewegen kann. Die Hippogryphen der Nachtelfen eignen sich perfekt dafür.|n|nTobias gibt Euch das Signal, wenn wir bereit sind.', },
    {'Springt auf einen Hippogryphen, wenn Tobias Euch das Zeichen dazu gibt, und zerstört das Kanonenboot der Horde.', },
  },
  [26707] = {
    'Eine tödliche Rebe',
    {'Ich brauche jede Menge Leichengras für Meister Harris\' Gebräu. Es ist schwer zu kriegen, aber unsere Vorräte dürfen nicht abnehmen. Leichengras ist ziemlich hartes Zeug...|n|nDie Pflanze macht Euch fertig, wenn Ihr nicht aufpasst! Aber wenn Ihr trotzdem helfen wollt, dann werde ich Euch gern für alles bezahlen, das Ihr selbst gesammelt habt.|n|nIhr werdet jede Menge auf Yorgens Bauernhof im Südosten finden.', },
    {'Sammelt 5 Stück Leichengras.', },
  },
  [26708] = {
    nil,
    {'Ich bin hier, um Euch und der Kompanie Bravo bei der Beseitigung dieses Schlamassels zu helfen. Steigt in den Belagerungspanzer der Kompanie Bravo und räumt den Weg zu Keeshans Posten auf der anderen Seite des Tals, nördlich von hier, frei.|n|nDie Situation ist hochgradig gefährlich, Soldat. Den Schwarzfelsorcs ist Eure Position mittlerweile bekannt. Sie sind mit einer großen Streitmacht auf dem Weg zu Euch.|n|nEliminiert sie alle ohne Gnade. Wir sehen auf der anderen Seite. Möge das Licht Eurer Seele gnädig sein.', },
    {'Tötet 200 Schwarzfelsorcs mit dem Belagerungspanzer der Kompanie Bravo.', },
  },
  [26709] = {
    'Der Steinthron',
    nil,
    {'Sucht nach Therazane bei Therazanes Thron.', },
  },
  [26710] = {
    'In den Tiefen verloren',
    {'Kieselchen hat es schon wieder geschafft, sich zu verlaufen, irgendwo in den Bruchtiefen.|n|nEr hat Glück, dass er so klein und dadurch für die Schleifwürmer uninteressant ist. Es ist aber nur eine Frage der Zeit, bevor er zu nah an einem von ihnen vorbeikommt und doch aufgefressen wird. Warum auch immer er da unten ist, es kann einfach nicht so wichtig sein.|n|nEr scheint Euch zu mögen. Zieht bitte los, um ihn zu finden, und bringt ihn aus diesen Tunneln zu einem sichereren Spielplatz.', },
    {'Findet Kieselchen in den Bruchtiefen und geleitet ihn sicher aus den Tunneln.', },
  },
  [26711] = {
    'Ab zur Bank',
    {'Jo, Schätzchen. Was geht? Schon bereit für die Party?|n|nNein?! Du weißt doch, dass ich Dich heiß und innig liebe, also weiß ich nicht ganz, wie ich es sagen soll, aber… Ich glaube, Du solltest mal in der Stadt nach einem neuen Outfit für die Party suchen.|n|nGuck mich nicht so an... Du willst doch klasse für mich aussehen, ooooder? Willst Du für mich nicht superschick sein?|n|nSchau erst bei der Bank vorbei und hol Dir ausreichend Moneten. Du willst ja schließlich keinen Billigkram kaufen!', },
    {'Sprecht mit dem Kassierer der EBvK in der Ersten Bank von Kezan auf Kezan.', },
  },
  [26712] = {
    'Ab zur Bank',
    {'Hey, mein Süßer. Schon bereit für die Party?|n|nNein?! Du weißt doch, dass ich Dich heiß und innig liebe, hm? Ich finde, Du solltest mal in die Stadt gehen und ein neues Outfit für die Party kaufen.|n|nGuck mich nicht so an... Du willst doch sicher gut aussehen? Willst Du nicht gut für mich aussehen? Ich bin schließlich Deine Freundin!|n|nSchau unbedingt erst bei der Bank vorbei und hol Dir ausreichend Moneten. Kauf\' nichts von diesem Billigkram!', },
    {'Sprecht mit dem Kassierer der EBvK in der Ersten Bank von Kezan auf Kezan.', },
  },
  [26713] = {
    'Endkampf in Steinwacht',
    {'Es ist nur noch das Oberkommando des Schwarzfels übrig, $N. Sie haben sich in der Burg Steinwacht verbarrikadiert, unmittelbar südlich unserer Position hier an Keeshans Posten. Begleitet die Kompanie Bravo zur Steinwacht und beendet die Invasion der Schwarzfelsorcs.|n|n$N, keine Überlebenden.', },
    {'Tötet Tharil\'zun und Gath\'Ilzogg.', },
  },
  [26714] = {
    'Dunkelflamme, Brut des Weltenbrechers',
    {'Als Trottmann verstummt, wird die Welt um Euch herum plötzlich unheimlich still. In einiger Entfernung seht Ihr einen ausgewachsenen schwarzen Drachen!', },
    {'Ruft Dunkelflamme mit dem Horn der Beschwörung. Besiegt Dunkelflamme.', },
  },
  [26715] = {
    'Malfurion Sturmgrimm',
    {'Ich habe Malfurion Euer Kommen angekündigt. Er schien sehr daran interessiert zu sein, Euch persönlich zu treffen.|n|nIhr solltet ihn im Tempel des Mondes aufsuchen. Er steht neben unserer geliebten Tyrande Wisperwind. Seit seiner Rückkehr ist er nicht von ihrer Seite gewichen.|n|nAber ich muss Euch warnen... Malfurion hat seine Zweifel. Es könnte sein, dass Euer Volk Euch eine große Last aufgebürdet hat, als es Euch auswählte, sich mit ihm zu treffen.', },
    {'Sprecht mit Malfurion Sturmgrimm im Tempel des Mondes in Darnassus.', },
  },
  [26716] = {
    'Ein wenig Privatsphäre',
    {'Ich möchte unbedingt mit Euch reden, aber lieber in einer etwas vertraulicheren Umgebung. An einem Ort, wo wir vor neugierigen Ohren sicher sind.|n|nTrefft mich doch gleich im Tempelgarten.', },
    {'Trefft Malfurion Sturmgrimm im Tempelgarten von Darnassus.', },
  },
  [26717] = {
    'Worgen auf Yorgen',
    {'Meinesgleichen in Rabenflucht versuchen, die wilden Worgen in diesen Wäldern zu heilen. Der Zustand selbst lässt sich nicht aufheben, doch denjenigen, die sich noch nicht zu sehr verloren haben, kann man den Verstand zurückgeben.|n|nDen meisten kann man zwar nicht mehr helfen, aber wir achten auf die, die noch Überreste ihres Verstandes besitzen... eine Verbindung zu ihrem früheren Leben.|n|nAuf Yorgens Bauernhof habe ich einen einzelnen Worgen gesehen, der in einem Erdhaufen zwischen den Gebäuden grub... könntet Ihr Euch diesen Erdhaufen ansehen? Vielleicht hat er dort etwas zurückgelassen.', },
    {'Untersucht den Haufen lockerer Erde auf Yorgens Bauernhof.', },
  },
  [26718] = {
    'Brotkrumen zum Ödland',
    {'Etwas schlimmes ist geschehen.', },
    nil,
  },
  [26719] = {
    'Lieferung an Meister Harris',
    {'Meister Harris muss sofort davon erfahren.|n|nHier, bringt dieses Paket mit Leichengras die Straße hinunter zum Lager in Rabenflucht. Erzählt ihm, was wir auf Yorgens Bauernhof gesehen haben.', },
    {'Bringt Oliver Harris in Rabenflucht das Bündel Leichengras.', },
  },
  [26720] = {
    'Ein Fluch, den wir nicht brechen können',
    {'Was wir hier machen, bringt keine Heilung. Die Verwandlung kann nach ihrer Vollendung nicht rückgängig gemacht werden.|n|nDoch der Verstand... Die Alchemie kann den Verstand zurückbringen, wenn noch genug davon übrig ist. Der Worgen, dem Ihr begegnet seid, kämpft anscheinend um seinen, $N. Wir müssen ihn wiederfinden.|n|nEr ist von Yorgens Hof geflohen, also durchsucht Addles Siedlung im Süden; vielleicht lauert er in einem der Gebäude.|n|nInjiziert ihm den Inhalt dieser Ampulle, er wird ihn betäuben. Ihr müsst ziemlich nah herankommen.', },
    {'Durchsucht Addles Siedlung nach dem lauernden Worgen und betäubt ihn mit Harris\' Ampulle.', },
  },
  [26721] = {
    'Bibbers Spinnen',
    {'M-Meister Harris benötigt viele Reagenzien für seine Seren. Ich muss sie für ihn sammeln.|n|nDie meisten sind nicht so schlimm... Leichengras ist natürlich schlimm, aber nicht halb so schlimm wie Witwengift. Habt Ihr Euch die Witwen hier in der Gegend mal angesehen? Schon die Jungen sind mannsgroß. Selbst mit einem Gewehr halte ich die Jagd auf sie nicht aus!|n|nSie jagen mir zu viel Angst ein. Wenn Ihr sie für mich jagt, werde ich Euch gern dafür bezahlen! Bringt nur etwas Witwengift mit! Ihr findet sie in den Wäldern im Osten, direkt nördlich der Straße.', },
    {'Erbeutet 8 Witwengiftbeutel von schwarzen Witwen.', },
  },
  [26722] = {
    'Tief vergraben',
    {'<Ihr befestigt den Bogen am Stab. Das Artefakt ist fast komplett. Doch es gibt eine große Lücke mitten im Kopf des heiligen Symbols.>|n|n<Erneut scheint es an Eurem Arm zu ziehen und Euch zu einem Loch in der Wand und den verschlungenen Tunneln dahinter zu führen. Dort muss sich das letzte Teil befinden.>', },
    {'Sucht im Tunnel unter den Katakomben des Morgenrotwaldes nach dem lichtgeschmiedeten Wappen.', },
  },
  [26723] = {
    'Das Schicksal von Morbent Teufel',
    {'Der letzte, an den ich mich erinnere, bevor ich mich in den Wäldern verlor, ist Morbent Teufel. Er war ein abscheulicher Totenbeschwörer und der Grund dafür, dass so viele widerwärtige Untote dieses Land heimsuchen.|n|nIch habe einen Abenteurer gebeten, ihm ein Ende zu machen. Ich hatte angenommen, dass das auch geschehen sei! Aber Schwester Elsington hat mir gesagt, das Land sei immer noch voller Ghule und Schreckgespenster, die aus dem Grab gerissen wurden.|n|nMorbent Teufel hätte seinen letzten Atemzug in dem Haus auf dem Verlassenen Gut, nördlich des Friedhofs von Rabenflucht tun sollen. Seht nach, was aus ihm geworden ist...', },
    {'Sucht auf dem Verlassenen Gut nach Hinweisen auf Morbent Teufel.', },
  },
  [26724] = {
    'Der lauernde Lich',
    {'Die anderen teilen meinen Verdacht. Morbent Teufel lebt im Untod weiter... und ist vielleicht noch mächtiger als zuvor. Ein Totenbeschwörer wurde getötet, doch an seine Stelle könnte ein Lich getreten sein. Und er wird dieses Land weiter zerstören.|n|nIch erinnere mich daran, wie der Dämmerwald vor all dem war, $N. Ich erinnere mich an einen hellen Himmel und friedliche Wälder. Das kann nicht so weitergehen! Morbent Teufel muss endlich gestoppt werden.|n|nSprecht mit Schwester Elsington. Ihre Vision verrät Euch vielleicht, wo sich Morbent Teufel aufhält und wie man ihn besiegen kann.', },
    {'Sprecht mit Schwester Elsington.', },
  },
  [26725] = {
    'Vom Lichte geführt',
    {'Sven hat Recht. Ich fühle etwas Mächtiges und Böses tief unter dem Friedhof von Rabenflucht. Das Böse verbirgt sich in seinen Katakomben. Morbent Teufel könnte die Ursache dafür sein.|n|nIhr werdet die Macht des Lichts brauchen, um ihn zu besiegen, $N. Sven sagte mir, dass die Helden, die Morbent Teufel ursprünglich töteten, ein Artefakt aus lichtgeschmiedetem Eisen benutzten, das von heiliger Macht erfüllt war. Das Artefakt ist immer noch hier!|n|nIch fühle es ebenfalls. Es ist ein schimmerndes Licht in der Dunkelheit. Sucht in Rabenflucht danach und lasst Euch vom Licht führen.', },
    {'Findet die lichtgeschmiedete Rute auf dem Friedhof von Rabenflucht.', },
  },
  [26726] = {
    'Triumphale Rückkehr',
    {'Kehrt nach Seenhain zurück und meldet Solomon, dass die Invasion des Schwarzfels vereitelt wurde. Sorgt dafür, dass er den Preis für unsere Freiheit begreift - dass wir fünf unserer größten Helden verloren haben, um das Rotkammgebirge und letzten Endes auch Sturmwind zu retten.|n|nIhr seid der letzte Überlebende der Kompanie Bravo, $N. Sorgt dafür, dass ihr Vermächtnis weiterlebt.|n|nWegtreten.', },
    {'Meldet Euch bei Magistrat Solomon in Seenhain im Rotkammgebirge.', },
  },
  [26727] = {
    'Die Rache des Einbalsamierers',
    {'Ihr seid nicht der erste Narr, der von Calvinius manipuliert wurde! Wir nennen diesen tüdeligen alten Mann den Einbalsamierer. Er ist ein abscheulicher Totenbeschwörer und der Fluch dieser Stadt.|n|nUnd nun nähert sich uns seine schreckliche Schöpfung, die mit den Materialien, die Ihr ihm gebracht habt, zusammengenäht und ins Leben gerufen wurde!|n|nDiese schreckliche Kreatur wird in wenigen Momenten über uns kommen! Wenn Ihr ein Herz habt, $N, dann werdet Ihr der Nachtwache helfen, diese Monstrosität zu vertreiben und unsere Stadt zu retten!', },
    {'Tötet Kleiner in Dunkelhain.', },
  },
  [26728] = {
    'Heldenaufruf: Dämmerwald!',
    {'$N, die Bürger von Dämmerwald benötigen dringend Eure Unterstützung! Ich habe hier einen Brief von Kommandantin Althea Schwarzhaupt, der Anführerin der Nachtwache. Sie bittet um Hilfe.|n|nUm nach Dunkelhain zu kommen, solltet Ihr die Brücke benutzen, die sich in der südwestlichen Ecke des Rotkammgebirges befindet. Auf der anderen Seite der Brücke beginnt Dämmerwald. Dann müsst Ihr nur noch der Straße nach Dunkelhain folgen. Hütet Euch vor den wilden Bestien, die außerhalb der Ortschaften lauern!', },
    {'Meldet Euch bei Kommandantin Althea Schwarzhaupt in Dunkelhain im Dämmerwald.', },
  },
  [26729] = {
    'Wasserelementare',
    {'Ich kam ins Schlingendorntal, um etwas zu untersuchen, das Altar von Naias genannt wird, doch dummerweise widersetzte ich mich Colonel Kurzens Annährungsversuchen, was mir einige Jahre in diesem Käfig dort einbrachte. Jetzt bin ich wieder draußen, also spricht nichts dagegen, meine ursprünglichen Studien fortzusetzen.|n|nDer Altar steht auf einer Insel im Westen, südlich von Zul\'Kunda. Besorgt mir einige Armschienen von den Wasserelementaren der Insel.|n|nOh, und Ihr könnt dieses Gerät benutzen, wenn Ihr fertig seid. Dann müsst Ihr den ganzen Weg hierher zurück nicht laufen.', },
    {'Holt 6 Armschienen eines Wasserelementars.', },
  },
  [26730] = {
    'Man kann den Murloc aus dem Ozean holen...',
    {'Ich brauche etwas, um an die reine, elementare Kraft dieser Armschienen zu kommen... etwas starkes und abschleifendes, was aber dennoch zum Meer gehört.|n|nDie Murlocs der Düsterkiemen sind vom Meer ins Landesinnere gezogen, tragen aber immer noch Phiolen mit Meersalz bei sich. Ich weiß nicht, wofür sie das Salz benötigen, aber es eignet sich gut für unsere Studien. Ihr findet die Düsterkiemen im Tal südlich des Rebellenlagers und östlich der Ruinen von Bal\'lal.', },
    {'Holt 6 Phiolen mit Meersalz von den Murlocs der Düsterkiemen im Nördlichen Schlingendorntal.', },
  },
  [26731] = {
    'Der Altar von Naias',
    {'Das Salz, das Ihr gebracht habt, reichte aus, um die Verzauberungen im Inneren der Armschienen zu aktivieren. Ich habe diese Verzauberungen gesammelt und zu einem Beschwörungsstein zusammengefügt... eine Gabe, könntet Ihr sagen.|n|nKehrt zur Insel Naias zurück und legt die Gabe auf Naias\' Altar. Ruft mich, wenn Ihr Naias\' Herz habt.', },
    {'Beschwört Naias mit Naias\' Gabe und holt das Herz von Naias.', },
  },
  [26732] = {
    'Schlechte Medizin',
    {'Ich habe den Verdacht, dass Kurzens Medizinmänner nicht nur Medizin verteilen. Kurzen benötigt etwas, um aufkeimenden Ungehorsam zu ersticken. Ein Elixier getarnt als "Medizin", wäre dafür sehr gut geeignet.|n|nWir brauchen diese Arzneien für unsere Studien. Durchsucht Kurzens Truppenlager im Südosten - seine Medizinmänner und Dschungelkämpfer sollten die Heilmittel bei sich tragen.', },
    {'Besorgt 7 Dschungelarzneien aus Kurzens Truppenlager.', },
  },
  [26733] = {
    'Kontrollprobe',
    {'<Bruder Nimetz analysiert die Proben, die Ihr ihm gegeben habt.>|n|nDas... das ist nur Basiliskenblut!|n|nNein, es besteht größtenteils aus Basiliskenblut. Sie haben jedoch etwas hinzugefügt. Für einen vernünftigen Vergleich brauche ich eine Kontrollprobe.|n|nWahrscheinlich stammt das Blut von Kristallrückenbasilisken, die östlich des Truppenlagers vorkommen. Bringt mir einige reine Proben, dann kriege ich schon heraus, was in dem Elixier ist.', },
    {'Besorgt 7 Proben Kristallrückenbasiliskenblut.', },
  },
  [26734] = {
    'Die Quelle des Wahnsinns',
    {'Ich habe das Basiliskenblut aus dem Elixier reduziert. Dabei habe ich einen ungewöhnlichen Bestandteil gefunden. Es scheint sich um eine Art blauen Kristall zu handeln...|n|n<Bruder Nimetz betrachtet seine Notizen.>|n|nEs ist kein singender blauer Kristall... und auch kein pulsierender blauer Splitter...|n|n<Er blättert einige Seiten vor.>|n|n... kein Stück des Gedankenauges. Nein, so etwas haben wir im Schlingendorntal noch nie gesehen. Jemand muss doch noch etwas von dieser Substanz besitzen. Ich will sie haben. Seht bei Kurzens hochrangigen Truppen hinten in ihrer Höhle nach.', },
    {'Erbeutet einen flüsternden blauen Stein von Kurzens Truppen im Vorratslager.', },
  },
  [26735] = {
    'Kurzens Schicksal',
    {'Hallo, $C.|n|nWir sind Soldaten aus Sturmwind und haben in Kurzens Truppenlager rebelliert. Der große Außenposten liegt südöstlich von hier. Wir standen unter dem Kommando von Colonel Kurzen, bis er und seine Vertrauten begannen, den Verstand zu verlieren...|n|nWir lehnten uns auf, errichteten hier unser Lager und wehrten uns gegen Kurzen. Nun habe ich von meinen Kontakten erfahren, dass Kurzen verschwunden ist. Ich traue dieser Quelle, aber ich möchte das noch einmal von einem Außenstehenden hören. Bitte begebt Euch in das Lager und sucht nach Belegen für sein Schicksal.', },
    {'Findet das Gefängnisregister von Kurzens Truppenlager und die Offiziersakten von Kurzens Truppenlager.', },
  },
  [26736] = {
    'Vom Wahnsinn verschont',
    {'Kurzens Tod ist eine Erleichterung, aber interessanter und momentan wesentlicher ist, dass dies ein Zeichen dafür sein könnte, dass es potentielle Verbündete im Lager gibt.|n|nMich interessiert nicht, was in dem Gefängnisregister steht. Ich weiß GENAU, weshalb die 3 eingesperrt wurden: weil sie sich weigerten, Befehle zu befolgen. Der Wahnsinn muss sie verschont haben, so wie meine Rebellenkameraden hier. Sie wurden eingesperrt, weil sie aufbegehrten.|n|nFindet sie, $N. Findet sie und schickt sie hierher.', },
    {'Rettet Berrin Brennfeder, Emerine Junis und Osborn Widrikus aus Kurzens Truppenlager.', },
  },
  [26737] = {
    'Beendet Kurzens Vermächtnis',
    {'Unsere Verbündeten wurden aus Kurzens Truppenlager evakuiert, nun müssen wir es ein letztes Mal angreifen. Sie werden nie wieder so schwach sein wie gerade und mit Eurer Hilfe können wir sie vielleicht so weit schwächen, dass sie sich nicht mehr davon erholen.|n|nDiese vier Namen, die in den Offiziersakten erwähnt werden - Anders, Gaulus, Miranda und Esquivel - sind die höchstrangigen übrig gebliebenen Soldaten. Sucht nach ihnen in der Höhle im hinteren Teil des Truppenlagers. Sollten diese vier verschwinden, werden die Konsequenzen für Kurzens Streitkräfte verheerend sein.|n|nGehet mit Ehre, $N.', },
    {'Tötet Oberstabschef Anders, Oberstabschef Gaulus, Oberstabschef Miranda und Oberstabschef Esquivel im Vorratslager.', },
  },
  [26738] = {
    'Frisch geschlüpft',
    {'Als Ihr die Sachen des Soldaten durchsucht, bemerkt Ihr ein frisch geborenes, weibliches Raptorjunges, das zu Euch aufsieht. Ist es Kurzens Milizsoldaten die ganze Zeit über gefolgt?|n|nIhr seht, wie es Euch mustert, sich Euer Gesicht einprägt und Eure Bewegungen beobachtet.|n|nDas Schmetterschwanzjunge geht eine Bindung mit Euch ein.|n|nVielleicht weiß jemand im Rebellenlager etwas mit einem Raptorjungen anzufangen.', },
    nil,
  },
  [26739] = {
    'Ich glaube, sie hat Hunger',
    {'Euer junges Raptorweibchen scheint hungrig zu sein. Wenn Ihr sie behalten wollt, solltet Ihr vielleicht etwas zu fressen für sie finden. Die Schmetterschwänze greifen häufig die Basilisken des Schlingendorntals an. Man findet sie im Osten hinter Kurzens Truppenlager.|n|nWahrscheinlich ist sie noch nicht stark genug, um allein auf die Jagd zu gehen, aber ich bin mir sicher, dass sie frisches Basiliskenfleisch fressen wird.', },
    {'Tötet Kristallrückenbasilisken im Nördlichen Schlingendorntal und lasst Euren Schmetterschwanz 40 Bissen ihres Fleisches fressen.', },
  },
  [26740] = {
    'Kochen mit Krazek',
    {'Meistens bin ich es, der hier im Lager kocht. Und das war auch immer ganz schön viel Arbeit, bis ich von einem Goblinhändler in Beutebucht einen mechanischen Kochtopf gekauft habe. Der Topf ist einfach unglaublich. Er hat mir unzählige Stunden Arbeit erspart – bis er kaputtgegangen ist!|n|nKönnt Ihr den Topf dem Goblin zurückbringen, damit er ihn mir repariert? Der Händler heißt Krazek. Das Letzte, was ich gehört habe, war, dass er bei Nesingwary Unterschlupf gefunden hat, im Jägerlager im Süden.', },
    {'Bringt Krazeks Spezialtopf zu Krazek.', },
  },
  [26742] = {
    'Erkenntnisse über die Blutskalpe',
    {'Ich habe mich nie richtig bei Euch für meine Rettung bedankt.|n|nDanke, $N.|n|nIch bin immer noch etwas erschöpft von meiner Gefangenschaft, deshalb dachte ich, Ihr könntet mir vielleicht bei meinen Studien helfen. Als ein Schamane des Wildhammerklans interessiere ich mich natürlich sehr für die schamanistischen Methoden des Blutskalpklans.|n|nIhre Magie scheint sich in eine interessante Richtung entwickelt zu haben. Hätte ich eines der Totems, die ihre Schamanen benutzen, könnte ich mit meinen Studien beginnen. Ihr findet sie in den Ruinen von Bal\'lal, an der Küste im Südwesten.', },
    {'Besorgt ein Totem der Blutskalpe von einem Schamanen der Blutskalpe.', },
  },
  [26743] = {
    'Den Blutskalpen heilig',
    {'Ahh... das müssen die Namen ihrer Totemwesen sein - der Tiere, die sie den Geistern zuordnen. Mal sehen... Mahamba als Wasser, Tsul\'Kalu als Erde, Pogeyan als... Luft? Feuer? Diesen Teil kann ich nicht entziffern.|n|nIch würde gern mehr über ihre Geister erfahren. Hier in der Nähe, in den Ruinen von Tkashi, haben die Blutskalpe ein Lager errichtet. Vielleicht könnt Ihr dort Einzelheiten herausfinden.', },
    {'Besorgt eine Ikone von Tsul\'kalu, eine Ikone von Mahamba und eine Ikone von Pogeyan aus dem Lager der Blutskalptrolle in den Ruinen von Tkashi.', },
  },
  [26744] = {
    'Tiefe Wurzeln',
    {'Doch nun zu etwas anderem: Ich stelle gerade eine Sammlung von Trollgeschichten und -legenden für ein... persönliches Projekt zusammen. Vielleicht könntet Ihr mir helfen, einige davon zu finden.|n|nDie Blutskalpe in den Ruinen von Bal\'lal, an der Küste im Südwesten, besitzen eine große Schrifttafel, auf der einige ihrer Geschichten festgehalten sind. Ich würde Euch natürlich für die Geschichten, die Ihr mir bringt, entschädigen.', },
    {'Holt die Schrifttafel der Blutskalpe aus den Ruinen von Bal\'lal im Nördlichen Schlingendorntal.', },
  },
  [26745] = {
    'Lieblingsschädel',
    {'Euer zahmes Raptorweibchen scheint ein neues Spielzeug gefunden zu haben: Einen Schädel von einem nahegelegenen Trollschädelhaufen.|n|nIhr wisst nicht, was diesen Schädel von den anderen unterscheidet, aber aus irgendeinem Grund lässt sie ihn nicht wieder fallen.|n|nOsborn Widrikus, der Gnom, den Ihr aus Kurzens Truppenlager gerettet habt, ist ein Experte für Trollgeschichte und Trollphysiologie. Vielleicht weiß er, warum dieser Schädel etwas besonderes ist.', },
    nil,
  },
  [26746] = {
    'Ein Gespür für solche Dinge',
    {'<Osborn wirft noch einen Blick auf den Schädel.>|n|nAls er noch lebte, war er stark und mächtig, ein Fürst der Trolle. Mit unserer Hilfe kann er wieder ein Fürst werden.|n|nDie Strauchdiebe der Blutskalpe, die durch die Ruinen im Südwesten ziehen, sammeln magische Fetische, die wir gebrauchen könnten. Sie vergraben diese Artefakte, um sie zu verstecken. Findet diese Artefakte mit Hilfe Eures Jungen, $N... und bringt sie dann her.', },
    {'Lasst Euer Schmetterschwanzjunges 8 Tkashifetische erschnüffeln.', },
  },
  [26747] = {
    'Ein Exemplar aus Fleisch und Blut',
    {'Die Seele ist bereit, der Körper jedoch nicht. Für einen Schädel, der so wohlgeformt, so wunderbar und so schön wie dieser ist, brauchen wir einen passenden Körper.|n|nGan\'zulah, der Häuptling der Blutskalpe, ist durch brutale Gewalt auf den Thron gekommen. Sollte er noch leben, werdet Ihr ihn in Zul\'Kunda im Westen finden.|n|nSeinen Körper zu rauben, wird nicht leicht sein, aber $Gein kräftiger:eine kräftige:c; $C wie Ihr wird das schon schaffen. Bringt ihn hierher, wenn Ihr fertig seid.', },
    {'Holt Gan\'zulahs Leiche aus Zul\'Kunda.', },
  },
  [26748] = {
    'Blutfürst Mandokir',
    nil,
    {'Bringt Blutfürst Mandokir im Rebellenlager das Schmetterschwanzeifragment.', },
  },
  [26749] = {
    'Priesterin Thaalia',
    {'Danke, $N. Ich weiß, dass Ihr mein Leben nicht hättet retten müssen.|n|nEs ist schlimm, dass Blutfürst Mandokir zurückgekehrt ist. Er wurde vor einigen Jahren in Zul\'Gurub getötet. Wir dachten, wir würden ihn und sein Volk nie wiedersehen. Die Trolle von Zul\'Gurub versuchten sich an einem schrecklichen, widerwärtigen Ritual. Wenn Mandokir lebt, dann ist es nur logisch anzunehmen, dass er nicht der einzige ist.|n|nDie Forscher in Fort Livingston, weit im Süden, wissen vielleicht mehr. Sprecht mit ihrer Priesterin.', },
    {'Sprecht mit Priesterin Thaalia in Fort Livingston im Nördlichen Schlingendorntal.', },
  },
  [26750] = {
    'Auf Geheiß der Steinmutter',
    {'Es ist Zeit. Die Steinmutter wird mit Euch sprechen. Ihr findet ihren Thron im Norden Tiefenheims, über dem Geschliffenen Schlund.', },
    {'Sprecht mit Therazane der Steinmutter.', },
  },
  [26751] = {
    'Bevölkerungskon-Trolle',
    {'Ich habe gehört, dass Ihr bald nach Zul\'Kunda aufbrechen werdet. Ich habe eine kleine Aufgabe für Euch, wenn Ihr dort seid.|n|nDie Bevölkerung der Trolle ist zu groß für Schlingendorntal geworden. Die Blutskalpe im Westen, die Schädelspalter im Osten... sie kommen aus den Ruinen und machen sich im Dschungel breit. Das stört das natürliche Gleichgewicht der Gegend. Dieses Gleichgewicht muss jetzt wiederhergestellt werden.|n|nZul\'Kunda ist die Hochburg der Blutskalpe. Dort werdet Ihr die hochrangigsten Blutskalpe finden. Reduziert ihre Zahlen und kehrt zu mir zurück.', },
    {'Tötet 7 Mystiker der Blutskalpe, 7 Jäger der Blutskalpe, 7 Späher der Blutskalpe und 1 Bestienmeister der Blutskalpe.', },
  },
  [26752] = {
    'Audienz bei der Steinmutter',
    {'Bleibt wo Ihr seid, Champion. Ich habe noch nicht entschieden, was ich mit Euch und Eurem Irdenen Ring anstelle.', },
    {'Nehmt an der Audienz bei der Steinmutter teil.', },
  },
  [26753] = {
    'Die Hallen der Toten',
    {'<Vor Euch neigt sich die nackte Erde dem dunklen Eingang zu den Grüften entgegen.>|n|n<Ihr spürt, wie das lichtgeschmiedete Artefakt Euch darauf zuzieht. Ist das andere Teil vielleicht dort unten?>', },
    {'Findet den lichtgeschmiedeten Bogen in den Katakomben des Morgenrotwaldes.', },
  },
  [26754] = {
    'Morbents Bann',
    {'<Die Teile passen. Ihr habt das geheiligte Artefakt zusammengesetzt. Es strahlt ein heiliges Licht aus. Damit solltet Ihr in der Lage sein, Morbent Teufels dunkle Magie zu besiegen.>|n|n<Tiefer im Tunnel, entgegengesetzt der Richtung, aus der Ihr gekommen seid, ertönt ein verstörendes Kichern. Es ist das rasselnde Lachen eines Lich. Morbent Teufel ist direkt vor Euch!>', },
    {'Schwächt Morbent Teufel mit Morbents Bann und besiegt ihn.', },
  },
  [26755] = {
    'Weg von der Front',
    {'Oh, gut! Ihr habt noch ein Katapult mitgebracht! Klei mag älter als Staub sein, aber er weiß, wie man eine schreckliche Kriegsmaschine baut.|n|nNun, Ihr habt es sicher nicht den weiten Weg bis hierher gebracht, weil Ihr ein wenig Bewegung wolltet, Fleischsack. Schwingt Euch in eines dieser Dinger und bombardiert die Fungusschrecken und ihre Verstärkung, die aus Nadelfelsbruch herausströmen.|n|nWir müssen sie von der Front fernhalten!', },
    {'Bombardiert 30 Fungusschrecken und/oder Mitglieder der Verstärkung der Steintroggs.', },
  },
  [26756] = {
    'Nessa Schattensang',
    {'Eine Freundin von mir, Schwester Aquinne, ist in der Ausbildung zur Mondpriesterin in Darnassus. Sie hat Dolanaar letztes Jahr verlassen, um im Tempel zu lernen. Laut ihren Briefen geht es ihr gut und sie lernt viel, aber sie vermisst ihr Zuhause und ihre alten Freunde. Ich habe ein Buch mit ihren Lieblingsrezepten aus Dolanaar zusammengestellt.|n|nWenn Ihr die Zeit findet, könntet Ihr es ihr nach Darnassus bringen? Ihr könnt einen Hippogryphen von Fidelio mieten. Er befindet sich in der Mitte der Stadt, gegenüber vom Gasthaus.', },
    {'Bringt die Rezeptsammlung von Dolanaar zu Fidelio in Dolanaar.', },
  },
  [26757] = {
    'Auf nach Darnassus',
    {'Alle in Dolanaar sind so stolz auf Schwester Aquinne. Ich bin sicher, sie wird sich sehr freuen, dieses aufmerksame Geschenk von Nyoma zu erhalten.|n|nWenn Ihr bereit seid, nach Darnassus zu reisen, sprecht einfach wieder mit mir und für ein paar Münzen könnt Ihr einen Hippogryphen mieten, der Euch dorthin bringt. Man sagte mir, Schwester Aquinne genießt die Abgeschiedenheit eines kleinen Platzes südlich vom Hippogryphenmeister in Darnassus. Sucht dort nach ihr, wenn Ihr angekommen seid.', },
    {'Sprecht mit Fidelio, um einen Flug nach Darnassus zu erstehen, und bringt dann die Rezeptsammlung von Dolanaar zu Schwester Aquinne in Darnassus.', },
  },
  [26758] = {
    'Ein unerwartetes Geschenk',
    {'Das ist wundervoll! Genau das Richtige, um mich während meiner Studien im Tempel des Mondes an mein Zuhause zu erinnern. Ich werde eins der Rezepte heute Abend ausprobieren. Ich kann es kaum abwarten!|n|nWürdet Ihr diese kurze Dankesnachricht zu Nyoma zurückbringen? Ihr könnt einen Hippogryphen zurück nach Dolanaar mieten. Besucht einfach unsere Hippogryphenmeisterin, Leora, wenn Ihr zum Abflug bereit seid. Sie wird Euch mit einem Rückflug nach Dolanaar helfen.', },
    {'Bringt Schwester Aquinnes Notiz zu Leora, der Hippogryphenmeisterin in Darnassus.', },
  },
  [26759] = {
    'Rückkehr zu Nyoma',
    {'Euch einen Flug zurück nach Dolanaar zu besorgen, wird einfach sein. Da Ihr Fidelio in Dolanaar bereits kennt, könnt Ihr ohne Probleme dorthin zurückfliegen.|n|nImmer wenn Ihr in einer neuen Stadt ankommt, solltet Ihr daran denken, mit dem Flugmeister zu sprechen, damit Ihr zu und von diesem neuen Ort fliegen könnt.|n|nSprecht mit mir, wenn Ihr bereit seid, einen Hippogryphen für den Rückflug nach Dolanaar zu mieten.', },
    {'Sprecht mit Leora, um einen Hippogryphen zu mieten, der Euch nach Dolanaar zurückbringt. Sobald Ihr in Dolanaar angekommen seid, bringt Schwester Aquinnes Nachricht zu Nyoma.', },
  },
  [26760] = {
    'Das Unmögliche möglich machen',
    {'Ich bin optimistisch, aber wir sollten professionell bleiben. Wir behandeln ihn wie alle anderen.|n|nAb in die Guillotine mit ihm... und wenn die Alchemie nicht wirkt, kommt er nicht wieder heraus.|n|nBibbers und ich kümmern uns darum. Bitte bleibt zurück und seht aus sicherer Entfernung zu.', },
    {'Seht zu, wie Oliver Harris und Bibbers versuchen, den lauernden Worgen zu heilen.', },
  },
  [26761] = {
    'Eine Bedrohung für das Königreich',
    {'Es besteht kein Zweifel, dass die Defias eine ernsthafte Bedrohung für das Königreich darstellen, aber wir können nicht einfach so deren Versteck betreten und hoffen, dass sich alles zum Guten wendet. Nein, ein Angriff auf die Defias erfordert Zeit und Planung. Überlasst die Logistik mir. Unser Königreich hat auch noch andere Sorgen, gegen die umgehend etwas unternommen werden muss!|n|nReist nach Osten, über Elwynn ins Rotkammgebirge und meldet Euch bei Magistrat Solomon in Seenhain. Ich lasse nach Euch schicken, wenn wir bereit sind, die Defias anzugreifen.', },
    {'Meldet Euch bei Magistrat Solomon in Seenhain im Rotkammgebirge.', },
  },
  [26762] = {
    'Reaktiviert die Konstrukte',
    {'Wir haben eine ganze Reihe unserer Kriegskonstrukte gen Norden nach Nadelfelsbruch geschickt, aber keines ist je zurückgekehrt. Wir wissen, dass die Mystiker der Steintroggs dafür verantwortlich sind.|n|nWir befürchten nun, dass die Mystiker die Kontrolle übernehmen und unsere Konstrukte gegen uns verwenden werden, so wie sie es mit den Fungusgiganten getan haben.|n|n$N, betretet die Stadt der Steintroggs und reaktiviert die Konstrukte.', },
    {'Reaktiviert 5 deaktivierte Kriegskonstrukte.', },
  },
  [26763] = {
    'Venture Company-Bergbau',
    {'Um diesen Topf zu reparieren, werde ich Reagenzien brauchen. Und um die zu bekommen, werdet Ihr ein ganz klein bisschen töten müssen. Ich hoffe, das stört Euch nicht.|n|nDiese lästigen Geologen der Venture Company haben einige gerommelte Kristalle gesammelt, die für meine Zwecke genügen würden. Ihr findet sie rund um ihr Basislager im Osten, auf der anderen Seite des Nazferitisees.|n|nIst mir egal, was Ihr tun müsst, um sie zu bekommen.', },
    {'Besorgt 5 gerommelte Kristalle von Angehörigen der Venture Co. beim Nazferitisee.', },
  },
  [26764] = {
    'Moralischer Bankrott',
    {'Euch ist vielleicht aufgefallen, dass die Venture Company den Wald rund um ihr Basislager im Osten komplett gerodet hat. Ihr Vorarbeiter wittert Profit, deshalb hat er Druiden versklavt, die er zwingt, den Wald neu wachsen zu lassen, damit er ihn wieder abholzen kann!|n|nIch persönlich finde das abscheulich, nicht nur, weil ich nicht als erster auf die Idee gekommen bin.|n|nBefreit einige dieser Druiden aus ihrer Gefangenschaft. Sie werden Euch bestimmt dankbar sein.', },
    {'Befreit 3 versklavte Druiden aus dem Basislager der Venture Co.', },
  },
  [26765] = {
    'Kehrt zu Korporal Kaleb zurück',
    {'So, dieser Kessel ist repariert. Ich habe sogar eine zweite Dampfpfeife eingebaut. Und seht! Am Boden gibt es einen neuen Zerhacker, der sogar durch Beinknochen schneidet!|n|nJa, ja, Krazeks Spezialtopf stellt Köche zu 100%zufrieden! Ich bin sicher, dass er dem Besitzer gefallen wird.', },
    {'Bringt Krazeks reparierten Topf zu Korporal Kaleb im Rebellenlager im Nördlichen Schlingendorntal.', },
  },
  [26766] = {
    'Großes Ziel, großer Köder',
    {'Wir haben nur eine Chance, Abyssion zu fangen, $N. Wir müssen sie gut nutzen.|n|nWir testen die Falle am größten Steindrachen am Alabasterschelf.|n|nUm die Steinmatriarchin anzulocken, benötigen wir ausreichende Köder.|n|nNehmt dieses Messer und besorgt Euch 5 Basiliskenfleischstücke. Das sollte sogar für ihren Appetit genügen.', },
    {'Benutzt Mylras Messer, um 5 Basiliskenfleischstücke aus toten Kristallrückenbasilisken zu schneiden.', },
  },
  [26767] = {
    'Anleitung zur Questerstellung',
    {'Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als Nächstes zu tun ist.', },
    {'Erstellt eine Schnitzeljagdquest.', },
  },
  [26768] = {
    'Drachenfangen leicht gemacht',
    {'Das Fragment von einem Drachen bewachen zu lassen, war ein cleverer Schachzug. Sie können es immer an einen anderen Ort bringen, wenn wir uns ihm nähern.|n|nAbyssion zu fangen wird sehr schwer, aber ich habe einen guten Plan.|n|nDer Schattenhammer benutzt magische Fallen, um die Steindrachen an den Boden zu fesseln, während sie ihnen ihre Energie rauben.|n|nWenn wir an eine solche Falle kämen, könnten wir den Zwielichtdrachen vielleicht lange genug festhalten.|n|nGeht nach Osten zum Alabasterschelf und besorgt Euch eine Falle.', },
    {'Besorgt Euch eine Drachenschlinge von den Zwielichtdrachenjägern.', },
  },
  [26769] = {
    'Wilde Flussfahrt',
    {'Genießt Euren Anteil an der Beute, $N!|n|nIch teile nicht gern, aber Geschäft ist Geschäft. Und diesem Betrüger Düsentopf stehen 10%dieses Schatzes zu. Könntet Ihr das zu ihm in seinem Außenposten nördlich von hier bringen?|n|nEr leitet eine kleine Forschungsstation stromaufwärts am Fluss. Verlasst die Stadt in Richtung Nordosten und sucht Horton Hornbläser auf. Er wird Euch kostenlos auf einem seiner Flussschiffe mitnehmen. Sagt ihm, ich hätte Euch geschickt!', },
    {'Geht an Bord von Horton Hornbläsers Flussschiff nordöstlich von Ratschet und macht eine Flussfahrt zu Düsentopfs Außenposten.', },
  },
  [26770] = {
    'Mystische Meister',
    {'Die Mystiker der Nadelfelsen haben die Kontrolle über die Fungusgiganten, die tief unten in ihrer Schlucht entstanden sind, übernommen. Jetzt wollen sie auch noch unsere Kriegskonstrukte übernehmen.|n|nGeht Richtung Norden nach Nadelfelsbruch und unternehmt etwas dagegen. Deswegen seid Ihr doch hier, oder?', },
    {'Tötet 5 Mystiker der Nadelfelsen.', },
  },
  [26771] = {
    'Fallenprobe',
    {'Legt nun die Falle für die Matriarchin aus.|n|nGeht zum westlichen Ende des Alabasterschelfs und platziert die Falle mit dem Basiliskenfleisch in die Mitte des Futterplatzes.', },
    {'Legt die Falle mit dem Fleisch am westlichen Ende des Alabasterschelfs aus.', },
  },
  [26772] = {
    'Gedankensicht',
    {'Um Mandokir zu erkennen, müsst Ihr Mandokir sehen.|n|nUm Mandokir zu sehen, müsst Ihr Augen von Raptor nutzen.|n|nIhr habt Euch angefreundet mit Raptor: Ohgan\'aka: Tochter von Ohgan.|n|nUm Freundschaft zu stärken, brauchen wir Federn.|n|nGeht nach Nordosten und Ihr werdet Federn finden, ja.', },
    {'Erbeutet 5 Dschungelpirscherfedern von Dschungelpirschern im Nördlichen Schlingendorntal.', },
  },
  [26773] = {
    'Seht Raptor',
    {'Federn? Haben wir.|n|n$C? Haben wir.|n|nSprecht mit Priesterin, wenn bereit.', },
    {'Sprecht mit Priesterin Thaalia in Fort Livingston, um am Ritual der Gedankensicht teilzunehmen.', },
  },
  [26774] = {
    'Gedankenkontrolle',
    {'Gedankensicht nicht genug, nein.|n|nGedankenkontrolle viel mächtigere Magie, ja.|n|nMächtige Magie braucht mächtige Reagenzien und Trollhirn ist mächtiges Reagenz.|n|nBraddok in Zul\'Mamwe sehr intelligent, ja.|n|nGeht nach Süden und untersucht Braddoks großes Gehirn.', },
    {'Erbeutet Braddoks Riesengehirn von Braddok in Zul\'Mamwe.', },
  },
  [26775] = {
    'Seid Raptor',
    {'Gedankenkontrolle sehr mächtig, ja.|n|nMit Glück könnt Ihr Ohgan\'aka helfen, aus Zul\'Gurub zu fliehen.|n|nDann wird Ohgan\'aka wieder $N\'aka werden!|n|nSprecht mit Priesterin, ja, und helft $N\'aka bei Flucht.', },
    {'Sprecht mit Priesterin Thaalia und helft dem gefangenen Schmetterschwanzjungen aus Zul\'Gurub zu fliehen.', },
  },
  [26776] = {
    nil,
    {'Priesterin spricht Gemeinsprache nicht gut, nein.|n|nVielleicht redet besser mit Ghaliri, vor diesem Zelt.|n|nSagt ihm, was Ihr in Zul\'Gurub gesehen, ja.', },
    {'Kehrt zu Ghaliri in Fort Livingston im Nördlichen Schlingendorntal zurück.', },
  },
  [26777] = {
    'Beruhigt die Geister',
    {'Dies ist ein tragisches Land mit einer Geschichte voller Gewalt und Verzweiflung. Viele Tote streifen in ihren Körpern durch das Land, aber manche sind nur verlorene Seelen, die verwirrt umherirren.|n|nSie verdienen Trost.|n|nViele dieser Seelen versammeln sich im Süden in Addles Siedlung und erscheinen Reisenden. Nehmt diesen Schwenker mit heiligem Weihrauch. Schwenkt ihn vor den verlorenen Seelen. Sein sanfter Duft wird ihnen Frieden bringen.', },
    {'Beruhigt 5 verlorene Geister in Addles Siedlung.', },
  },
  [26778] = {
    'Die Schreie der Toten',
    {'Könnt Ihr sie hören, $N? Es sind so viele. Sie wandern an ihren Gräbern entlang, stolpern auf verwesenden Gliedmaßen über den kalten Boden.|n|nDie Toten schreien in der Stille. Sie leiden in ihrem eigenen Fleisch und wurden aus ihrem Schlaf gerissen! Jede Nacht gehe ich auf den Friedhof, um mehr von ihnen Frieden zu bringen, aber es sind nie genug.|n|nHelft mir, $N. Erlöst die Ghule, die über den Friedhof von Rabenflucht ziehen, von ihrem Leid. Tötet so viele Ihr könnt.', },
    {'Tötet 20 beliebige Ghule auf dem Friedhof von Rabenflucht.', },
  },
  [26779] = {
    'Mambo in Zul\'Mamwe',
    {'Das ganze Trollreich schämt sich für die Schädelspalter. Ihr lächerliches Gezanke mit den Blutskalpen hat das Nördliche Schlingendorntal entzweit. Während Stämme wie die Dunkelspeere und die Zandalari ein gutes Leben führen, kämpfen die Schädelspalter um Ruinen.|n|nMan hat mir erlaubt, Söldner zu belohnen, die gewillt sind, die Schädelspalter zu bestrafen. Ich fordere Euch und jeden, den Ihr kennt, auf, nach Zul\'Mamwe im Osten zu reisen und diesen abtrünnigen Stamm zu vernichten.', },
    {'Tötet 16 Schädelspaltertrolle im Inneren von Zul\'Mamwe.', },
  },
  [26780] = {
    'Wenn es Nacht wird im Dschungel',
    {'Die Nächte sind im Schlingendorntal besonders schön. Der Himmel ist voller Sterne und das Mondlicht dringt durch diese Blätter hier. Die ganze Nacht könnte ich den Himmel betrachten.|n|nLeider stören die Trolle in den Ruinen von Zul\'Mamwe meine astronomischen Studien. Tag und Nacht brennen ihre Kohlenpfannen. Sie berauben mich der Dunkelheit, die ich brauche.|n|nBitte geht nach Zul\'Mamwe östlich von hier, $N und löscht sie.', },
    {'Löscht 8 Kohlenpfannen von Zul\'Mamwe in Zul\'Mamwe im Nördlichen Schlingendorntal.', },
  },
  [26781] = {
    'Das Gedankenauge',
    {'Einer der zahlreichen Schätze dieses Tals befindet sich ganz in der Nähe, auf UNSERER Seite des riesigen Wirbelstroms. Ein Ogermagier auf dem Ogerhügel der Mosh\'Ogg, nordöstlich von hier, besitzt es. Sein Name ist Mai\'Zoth. Ich habe gehört, er sei boshaft und seine Magie stark.|n|nWenn er das Gedankenauge besitzen sollte, wird seine Magie noch stärker sein.|n|nBisher ist es mir nicht gelungen, nahe genug an ihn heranzukommen, um es ihm abzunehmen. Würdet Ihr es versuchen?', },
    {'Nehmt Mai\'Zoth das Gedankenauge ab.', },
  },
  [26782] = {
    'Die Schatzkiste der Mosh\'Ogg',
    {'Es gibt Neuigkeiten aus dem Rebellenlager im Norden. Ich habe gerade von einem Soldaten namens Nimetz erfahren, dass $Gein:eine:c; $C dort oben entschlüsselt hat, was die anderen in den Wahnsinn getrieben hat. Das wart nicht zufällig Ihr, oder?|n|nWie dem auch sei, er hat mir eine Probe dieser Steine geschickt und sie sehen genauso aus wie die, die ich auf dem Ogerhügel der Mosh\'Ogg im Nordosten entdeckt habe.|n|nSo wie ich gehört habe, bewachen die Oger eine Truhe in irgendwelchen Ruinen hinter ihrem Hügel. Ich vermute einen Zusammenhang. Würdet Ihr sie für mich holen?', },
    {'Erbeutet die Schatzkiste der Mosh\'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh\'Ogg.', },
  },
  [26783] = {
    'Die Schatzkiste der Mosh\'Ogg',
    {'Es gibt Neuigkeiten aus dem Rebellenlager im Norden. Ich habe gerade von einem Soldaten namens Nimetz erfahren, dass $Gein:eine:c; $C dort oben entschlüsselt hat, was die anderen in den Wahnsinn getrieben hat. Das wart nicht zufällig Ihr, oder?|n|nWie dem auch sei, er hat mir eine Probe dieser Steine geschickt und sie sehen genauso aus wie die, die ich auf dem Ogerhügel der Mosh\'Ogg im Nordosten entdeckt habe.|n|nSo wie ich gehört habe, bewachen die Oger eine Truhe in irgendwelchen Ruinen hinter ihrem Hügel. Ich vermute einen Zusammenhang. Würdet Ihr sie für mich holen?', },
    {'Erbeutet die Schatzkiste der Mosh\'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh\'Ogg.', },
  },
  [26784] = {
    'Schlammiges Wasser',
    {'Die Elementarkräfte sind stark hier im Hochland, $N. Deshalb hat der Schattenhammer hier seine Festung errichtet.|n|nIn den richtigen Händen kann diese Energie für etwas Produktives genutzt werden... zum Beispiel für ein Portal nach Orgrimmar.|n|nNordwestlich von hier, an der Mündung des Verralls sind Wasserelementare durch die Taten unserer Feinde flussaufwärts aufgeschreckt worden. Zerstört sie und sammelt 5 Strudelkerne. Ihr werdet nicht nur den Fluss beruhigen, sondern auch unser Portal mit Energie versorgen.', },
    {'Tötet matschige Wasserelementare, um 5 Strudelkerne zu sammeln.', },
  },
  [26785] = {
    'Mitglied der Meute',
    {'Ich habe immer versucht, mein wahres Ich vor den Einwohnern Dunkelhains zu verbergen... Sie scheinen Worgen nicht zu mögen. Es gibt allerdings außerhalb der Stadt noch mehr von uns.|n|nMeine Begleiter, mit denen ich zuerst hier angereist bin, durchsuchen die Wälder nach wilden Worgen. Sie glauben, dass einige von ihnen - die mit den verräterischen Zeichen - wieder zur Vernunft gebracht werden können.|n|nIch bin noch nicht soweit, mich ihnen wieder anzuschließen. Bitte lasst Lehrling Fess an der Kreuzung westlich der Stadt wissen, dass ich noch eine Weile länger in Dunkelhain verweilen werde.', },
    {'Sprecht mit Lehrling Fess an der Kreuzung westlich von Dunkelhain im Dämmerwald.', },
  },
  [26786] = {
    'Den Landungspunkt sichern',
    nil,
    {'Sprecht mit Artesh im Hafen des Drachenmals im Schattenhochland.', },
  },
  [26787] = {
    'Bärendienst',
    {'Ich habe Angst, dass... nun ja, ich habe einfach nur Angst. Außerdem tut es mir leid, dass ich um einen weiteren Gefallen bitten muss.|n|nMeister Harris benötigt Gehirne. Bärengehirne. Offenbar sind sie Teil des Serums - oder ein gleichwertiger Ersatz.|n|nEs gibt viele Schwarzbären in den Wäldern im Westen und entlang des Flussufers, aber... Ich kann das nicht! Ich habe sogar mit einem Gewehr viel zu viel Angst, um dort hinauszugehen und diesen riesigen Ungeheuern gegenüberzutreten. Bitte, lasst mich Euch bezahlen, damit Ihr mir einige bringt!', },
    {'Sammelt 8 Gehirne von Schwarzbären.', },
  },
  [26788] = {
    'Unseren Sieg untermauern',
    {'Unsere Allianz mit dem Drachenmalklan ist unter Dach und Fach, aber dieser Hafen ist für Kämpfe immer noch ungeeignet. Diese hauchdünnen Holzwände sind des Kriegshäuptlings unwürdig.|n|nWenn Wasserelementare sich ihren Weg durch Gestein bahnen, wie sie es im Verrall getan haben, entsteht ein seltsamer Schlamm. Er lässt sich problemlos verstreichen und wenn er trocknet, ist er härter als der härteste Stein. Er ist der perfekte Mörtel für große Bauvorhaben.|n|nGeht zur Flussmündung nordwestlich von hier und sammelt Verrallschlamm ein. Selbst eine kleine Menge wird lange reichen.', },
    {'Sammelt 10 Haufen Verrallschlamm.', },
  },
  [26789] = {
    'Die Axt im Walde',
    nil,
    {'Tötet 5 Test-Kobolde.', },
  },
  [26790] = {
    'Magmadar muss sterben!',
    nil,
    {'Bringt Magmadars Kopf zu Thrall im Steinkrallengebirge.', },
  },
  [26791] = {
    'Wie Pilze aus dem Boden',
    {'Die Mystiker der Steintroggs erschaffen diese Fungusmissgeburten aus den Riesenpilzen im Norden.|n|nIch möchte, dass Ihr einen Kriegswächter mitnehmt, damit er Euch bei den Riesen und den Steintroggs hilft. Macht Euch auf den Weg zu den Riesenpilzen und zielt auf sie. Ich und meine Geomanten werden sie in Grund und Boden stampfen, noch bevor die Mystiker ihr Ritual vollenden.', },
    {'Interagiert mit einem Kriegswächter und benutzt ihn, um 5 Riesenpilze zu vernichten.', },
  },
  [26792] = {
    'Fungusmissgeburten',
    {'Schnappt Euch einen Kriegswächter und vernichtet die Fungusmissgeburten, während Ihr da draußen seid.', },
    {'Tötet 5 Fungusmissgeburten.', },
  },
  [26793] = {
    'Das verwitterte Grab',
    {'Auf dem verwitterten Grabstein steht einfach:|n|nMORGAN LADIMORE|n|n<Als Ihr den Ort weiter untersucht, stellt Ihr fest, dass die Erde über dem Grab kürzlich umgegraben wurde und dass ein guter Teil der Erde entfernt worden zu sein scheint...>', },
    {'Sprecht in Dunkelhain mit Sirra Von\'Indi.', },
  },
  [26794] = {
    nil,
    {'<Er sucht in den Regalen und kommt mit einem ledergebundenen Buch zurück.>|n|nWenn Ihr mehr wissen wollt, dann fragt Althea. Sie ist diejenige, die in letzter Zeit von dem... Ärger... mit ihm am meisten mitbekommen hat.', },
    {'Sprecht in Dunkelhain mit Kommandantin Althea Schwarzhaupt.', },
  },
  [26795] = {
    nil,
    {'Meine Späher berichten mir, dass Mor\'Ladim durch den ganzen Dämmerwald wandert und auf dem Friedhof einen seltsamen, gewundenen Weg einschlägt. Wir haben ihn hinter dem Haus auf dem Hügel begraben, wisst Ihr, wo das ist?|n|nEs gibt nichts, was ich tun könnte, um Euch zu helfen, aber ich wünsche Euch viel Glück.', },
    {'Tötet Mor\'Ladim und bringt seinen Schädel nach Dunkelhain zu Kommandantin Althea Schwarzhaupt.', },
  },
  [26796] = {
    'Die überlebende Tochter',
    {'Ich hätte Euch dies schon früher sagen sollen...|n|nWie soll ich sagen...|n|nMorgan dachte zwar, dass seine ganze Familie umgekommen sei, aber seine Tochter Sarah Ladimore lebt noch: Sie ist jetzt eine Behüterin. Die... Umstände... unter denen ihr Vater zu Tode gekommen ist, haben sie immer sehr aufgewühlt. Vielleicht könntet Ihr zu ihr gehen und ihr mitteilen, was geschehen ist.', },
    {'Sprecht in Dunkelhain mit Behüterin Sarah Ladimore.', },
  },
  [26797] = {
    'Die Liebe einer Tochter',
    {'Hier, nehmt dies und legt es auf sein Grab. Vielleicht... vielleicht weiß er dann irgendwie, dass es mir gut geht und dass keiner von uns ihn für das verantwortlich macht, was geschehen ist.|n|n<Jetzt hat sie Tränen in den Augen, als sie einen Ring von der rechten Hand zieht und ihn Euch übergibt.>|n|nUnd... danke, $N.', },
    {'Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab.', },
  },
  [26798] = {
    'Das wird Saurfang freuen',
    nil,
    nil,
  },
  [26799] = {
    'Die nicht gerettet werden konnten',
    {'Die Val\'kyr erwecken jeden Tag hunderte von Leichen. Agatha hat Euch vor nur wenigen Momenten erweckt. Aber nicht alle haben Euer Glück.|n|nEinige behalten ihren freien Willen, leben aber in ewiger Angst und Verwirrung. Sie laufen normalerweise in die Wälder und schrecken vor ihrem eigenen Anblick zurück.|n|nAndere werden völlig wahnsinnig und ziehen ziellos umher. Sie werden oft gewalttätig und müssen zerstört werden.|n|nDas ist Eure Aufgabe, $N. Zerstört sie, auch wenn sie einst unsere Brüder und Schwestern waren.', },
    {'Tötet 6 hirnlose Zombies.', },
  },
  [26800] = {
    nil,
    {'Wir haben Leichen aus dem Silberwald, aus dem Hügelland... ach, von überall herbringen lassen, wo wir sie bekommen konnten. Wir können es uns jedoch nicht leisten, die Leichen zu ignorieren, die direkt vor unserer Tür liegen.|n|nDie letzten Überbleibsel des Scharlachroten Kreuzzuges treiben sich hier in Tirisfal herum. Wir haben sie zwar aus Todesend vertreiben können, aber mehrere ihrer Leichen liegen um die Gebäude im Norden und Osten herum.|n|nGeht und findet sie... und nehmt diesen Darnell mit. Er sieht stark genug aus, um ein paar Leichen tragen zu können.', },
    {'Durchsucht Todesend und die Umgebung nach 6 Leichnamen der Scharlachroten, dann zeigt auf sie, damit Darnell sie einsammelt.', },
  },
  [26801] = {
    'Geißel an unseren Grenzen',
    {'Wenn Ihr den Verlassenen nützlich sein wollt, müsst Ihr lernen, wie man kämpft. Und es gibt keine besseren Ziele als die Geißeldiener, die uns immer noch belästigen.|n|nDie elenden Ghule und klappernden Skelette, die im Norden und Osten herumlaufen, sind ehemalige Kämpfer der gefallenen Geißel. $GEin neuer:Eine neue:c; $C wie Ihr sollte dieser Herausforderung gewachsen sein.|n|nTrödelt nicht herum – sprecht erneut mit mir, wenn Ihr fertig seid.', },
    {'Tötet 8 Untote außerhalb von Todesend. Ihr könnt sowohl elende Ghule als auch klappernde Skelette töten.', },
  },
  [26802] = {
    'Die Verdammten',
    {'Zuerst... schaut mal Eure Rüstung an. Ihr seht ganz zerlumpt aus, $C.|n|nWenn Ihr in einem Stück bleiben wollt - und das wollt Ihr ganz sicher - kann ich vielleicht helfen. Wenn Ihr mir Pfoten und Flügel von den Wölfen und Fledermäusen in der Nähe bringt, besorge ich Euch vielleicht etwas Rüstung. Ihr findet diese Kreaturen nördlich und westlich von hier.', },
    {'Besorgt 4 Aasfressertatzen und 4 Nachtsaugerflügel.', },
  },
  [26803] = {
    'Fehlende Berichte',
    nil,
    {'Sprecht mit Windreitermeister Doras in Orgrimmar.', },
  },
  [26804] = {
    'Flug nach Klingenhügel',
    {'Wenn Ihr bereit seid, einen Windreiter nach Klingenhügel zu nehmen, sprecht mich einfach erneut an. Verschwendet keine Zeit, wenn Ihr angekommen seid, und meldet Euch sofort bei Gar\'Thok. Er ist für die Berichte zu den aktuellen Aktivitäten der Allianz in Durotar verantwortlich.', },
    {'Sprecht mit Doras, um einen Windreiterflug nach Klingenhügel zu erwerben. Sobald Ihr angekommen seid, sprecht mit Gar\'Thok.', },
  },
  [26805] = {
    'Auf zum Kap!',
    {'Die Forscherliga entwickelt sich ständig weiter, $N. Sie haben nicht nur Worgen wie mich aufgenommen, sondern sie haben auch ihre Suche nach Artefakten ausgeweitet. Einer unserer Besten, Bronwyn Hackschlag, hat im Süden ein Lager aufgeschlagen. Er glaubt, dass dort ein Gegenstand verborgen liegt, der von den Titanen stammt.|n|nBronwyn hat mich darum gebeten, einige Aufgaben hier im Norden zu übernehmen. Eine dieser Aufgaben ist es, mögliche Rekruten zu finden. Ihr scheint aus dem richtigen Holz geschnitzt zu sein. Sprecht mit Robert Rhodes, dem Flugmeister. Er wird dafür sorgen, dass Ihr dorthin gelangt. Auf Bronwyns Kosten.', },
    {'Sprecht mit Robert Rhodes, um einen Flug zu der Grabungsstätte der Forscherliga am Schlingendornkap zu bekommen.', },
  },
  [26806] = {
    'Berichte für Orgrimmar',
    {'Etrigg muss sich mit dem Teil des Berichts zufriedengeben, den ich schon fertig habe. Sagt ihm, dass ich bald noch mehr schicke.|n|n<Gar\'Thok reicht Euch einen Stapel unordentlich gefalteter Papiere.>|n|nDie hier sollten eigentlich die wichtigsten Details zum Anstieg der Allianztruppen in Nordwacht enthalten. Bitte sagt Etrigg, dass es mir leid tut und lasst ihn wissen, dass wir hier alle Hände voll zu tun hatten. Schließlich mussten wir Klingenhügel sichern. Wenn Ihr bereit seid, nach Orgrimmar zurückzukehren, sprecht einfach mit Burok und leiht Euch einen Windreiter.', },
    {'Bringt Gar\'Thoks Berichte zu Burok in Klingenhügel.', },
  },
  [26807] = {
    'Rückkehr zu Etrigg',
    {'Da Ihr bereits mit Doras gesprochen habt, könnt Ihr einen Windreiter für den Rückflug nach Orgrimmar mieten. Jedes Mal, wenn Ihr in einer neuen Stadt ankommt, solltet Ihr Euch mit dem ansässigen Flugmeister unterhalten. Danach könnt Ihr seine Dienste in Anspruch nehmen, um weite Strecken schnell zurückzulegen.|n|nSprecht erneut mit mir, wenn Ihr bereit seid, einen Rückflug nach Orgrimmar zu erwerben. Bringt diese Berichte zu Etrigg im Tal der Stärke, sobald Ihr gelandet seid.', },
    {'Sprecht mit Burok und erwerbt einen Flug zurück nach Orgrimmar. Sobald Ihr gelandet seid, bringt Gar\'thoks Berichte zu Etrigg im Tal der Stärke.', },
  },
  [26808] = {
    nil,
    {'<Linzi sieht besorgt aus.>|n|nWisst Ihr, hinter dem Kistenstapel verbirgt sich ein Troll. Sie muss furchtbar traurig sein, wenn sie nicht herauskommen und mit niemand reden will.|n|n<Linzi legt einige Akirisschilfrohre in ein Halstuch und bindet sie zusammen.>|n|nHier, gebt sie ihr. Sie sind sehr weich. Vielleicht ist es damit dort hinten ein wenig gemütlicher für sie.', },
    {'Bringt Linzis Geschenk zu Maywiki von Zuldazar, die sich an der Grabungsstätte der Forscherliga befindet.', },
  },
  [26809] = {
    'Durch die Hintertür',
    {'Ich verfolge einen Vertriebenen der Gurubashi. Er heißt Zanzil der Ausgestoßene. Vor Kurzem berichteten meine Brüder aus dem Norden mir, dass er plant, sich wieder in die Gesellschaft einzugliedern. Sein erster Schritt war, einen Abgesandten zu den Schädelspaltern zu schicken. Das sind keine guten Nachrichten.|n|nIch möchte, dass Ihr versucht, Einblick in Zanzils neueste Pläne zu erhalten. Nehmt diesen Weihrauch und stellt ihn vor das Fledermaustotem in den Ruinen von Jubuwal, die sich nördlich von hier befinden. Dann wird Hir\'eek Euch führen.', },
    {'Legt den Weihrauch der Gurubashi vor das Totem von Hir\'eek und lauscht dann Zanzils Verschwörung.', },
  },
  [26810] = {
    'Beseitigt den Ausgestoßenen',
    {'Ihr müsst Zanzil töten. Ihr seid auf Hir\'eeks Schwingen geritten und habt durch Hir\'eeks Augen gesehen; Ihr wisst, wo Zanzil sich in den Ruinen von Aboraz versteckt hält. Begebt Euch dorthin und tötet ihn.|n|nOh, und <Volk>... Falls wir getrennt werden, solltet Ihr diesen Fetisch benutzen. Er funktioniert nur innerhalb von Schlingendorn, aber er wird Euch schnell zu mir zurückbringen, falls es notwendig sein sollte.|n|nViel Glück, <Volk>. Zanzil ist kein gewöhnlicher Gegner.', },
    {'Begebt Euch zu den Ruinen von Aboraz am Schlingendornkap und nehmt Euch Zanzil den Ausgestoßenen vor.', },
  },
  [26811] = {
    'Durch das Trollloch',
    {'Es sieht so aus, als ob Zanzils Portal nach Zul\'Gurub immer noch offen ist. Zul\'Gurub ist ein gefährlicher Ort, aber Maywiki hat Euch mit dieser Aufgabe betraut.|n|nDas Portal liegt einladend vor Euch und wartet.', },
    {'Benutzt Zanzils Portal und betretet Zul\'Gurub.|n|nWenn Ihr Euch verirrt oder nach Zul\'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.', },
  },
  [26812] = {
    'Hohepriesterin Jeklik Sichtbare Transformation',
    {'Vor Euch ragt eine Rampe auf, die zu einer der vielen Terrassen der Stadt führt. Vor Euch befinden sich Totems, die wie Fledermäuse aussehen. Sie deuten an, dass Ihr Euch in der Hochburg der Hohepriesterin Jeklik befindet, einer Anhängerin von Hir\'eek.|n|nJeklik betete Hakkar an und ist eine der Priesterinnen, die Zanzil wiederbeleben will. Wenn Ihr Euch beeilt, könnt Ihr die Wiederbelebung vielleicht verhindern.', },
    {'Zerstört den Leib von Hohepriesterin Jeklik, bevor Zanzil sie wiederbeleben kann.|n|nWenn Ihr Euch verirrt oder nach Zul\'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.', },
  },
  [26813] = {
    'Hals über Kopf nach Zul\'Gurub',
    {'Zanzil der Ausgestoßene ist erneut durch eines seiner Portale geflohen. Folgt ihm!', },
    {'Benutzt Zanzils Portal.|n|nWenn Ihr Euch verirrt oder nach Zul\'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.', },
  },
  [26814] = {
    'Hohepriester Venoxis Sichtbare Transformation',
    {'Venoxis war der Zweite der beiden Priester, die Zanzil von den Toten erwecken wollte. Es ist Euch bereits gelungen, Hohepriesterin Jekliks Leiche zu vernichten... Venoxis muss der Nächste sein.', },
    {'Kümmert Euch um Zanzil den Ausgestoßenen und Hohepriester Venoxis.|n|nWenn Ihr Euch verirrt oder nach Zul\'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.', },
  },
  [26815] = {
    'Zanzils Geheimnis',
    {'Vor vielen Jahren haben die Gurubashi einen der Ihren aus Zul\'Gurub verbannt: einen Troll namens Zanzil. Die Gründe dafür sind nicht ganz klar. Ich vermute aber, es hatte etwas damit zu tun, dass er gerne jedem, der ihm über den Weg lief, starke, verhaltensändernde Mittel verabreichte. Die Gurubashi Priester und ihr Blutgott wurden vernichtet, aber Zanzil der Ausgestoßene existiert immer noch...|n|n... ebenso wie sein starkes, verhaltensänderndes Mittel.|n|nIch benötige diese Mixtur für meinen nächsten Test. Sucht bei den Zombies im Norden.', },
    {'Beschafft 5 Phiolen mit Zanzils Mixtur.', },
  },
  [26816] = {
    'Zutaten für eine Katastrophe',
    {'Habt Ihr die Explosion gesehen, die ich verursacht habe? Ich muss 10 Zoll in die Höhe geflogen sein!|n|nJetzt muss ich nur noch an Zanzils Rezept kommen, damit ich herausfinden kann, warum das passiert ist. Einer von Zanzils Lakaien in den Ruinen von Aboraz muss es bei sich haben. Begebt Euch nach Osten, zu der Küste des Kaps, und ergattert es für mich!', },
    {'Beschafft Zanzils Rezeptur von einem seiner Anhänger in den Ruinen von Aboraz.', },
  },
  [26817] = {
    'Das Reinheitsgebot',
    {'Diese Körperflüssigkeit allein wird nicht reichen. Sie ist zu dickflüssig. VIEL zu dickflüssig.|n|nDie Naga im Westen behüten einen Schrein, aus dem das einzig klare Wasser diesseits vom Dämmerwald fließt. Für die meisten Tränke verwende ich Flusswasser, aber Bronwyn verlangt Präzision!|n|nBeschafft Wasser aus dem Nek\'maniquellbrunnen, der sich an dem höchsten Punkt des Nagalagers befindet. Viel Glück.', },
    {'Beschafft das heilige Wasser der Klarheit aus dem Nek\'maniquellbrunnen am Schlingendornkap.', },
  },
  [26818] = {
    'Plüschpelze',
    {'Hallo, ich bin die Händlerin der Stadt! Und Bronwyn ist mein Vater!|n|nTut mir leid, ich sollte nicht so aufgeregt sein. Mein Vater sagt, das ist nicht professionell.|n|nWie auch immer... Die Leute kommen immer zu mir und fragen mich nach schwerem Leder oder rauem Balg. Doch ich glaube, es würde ihnen gefallen, wenn ich auch einige weiche Materialien hätte... wie Tigerfell! Glaubt Ihr, Ihr könntet mir welches besorgen?|n|nIhr findet einige Panther hier in der Nähe, aber wenn Ihr die großen Tiger sucht, müsst Ihr Richtung Nordwesten gehen. Sie sind nördlich des großen Trollgebiets.', },
    {'Beschafft 4 geschmeidige Tigerinnenfelle und 4 samtige Pantherfelle.', },
  },
  [26819] = {
    'Bündelweise Akiris',
    {'Die Forscher der Naga, die sich westlich von hier befinden, haben ein wertvolles Ozeanschilf bei sich: Akirisschilfrohr. Händler stellen daraus Arzneien und Verpackungen her; Handwerker füttern Rüstungen oder umwickeln Zigarren damit.|n|nWenn wir mit dem Graben fertig waren, hat mein Vater mir abends gezeigt, wie man es verwendet. Leider haben wir keins mehr. Würde es Euch etwas ausmachen, uns noch mehr davon zu holen?', },
    {'Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.', },
  },
  [26820] = {
    'Wenn sie sie einfach herumliegen lassen...',
    {'Vater sagt, dass ein verantwortungsvoller Händler immer nach lohnenden Geschäften Ausschau hält. Ich versuche, auf Schritt und Tritt nach guten Geschäften Ausschau zu halten, und ich glaube, jetzt habe ich eins gefunden!|n|nDie Naga, die sich westlich von hier befinden, haben Dutzende Statuen, die sie dort, wo sie leben, überall auf den Boden stellen. Sie können unmöglich alle gebrauchen - also dachte ich, dass wir ein paar für uns nehmen!|n|nStatuen, ganz umsonst! Das ist doch ein gutes Geschäft, oder nicht?', },
    {'Beschafft 6 Nagaikonen von der Südlichen Ungezähmten Küste am Schlingendornkap.', },
  },
  [26821] = {
    nil,
    {'Nun, wir haben keine Ahnung, was dieses Artefakt ist. Es ist alt, älter als der Staub... aber nicht titanischen Ursprungs. Ich bin absolut sprachlos.|n|nAirwyn Bantamflax in Beutebucht ist meine direkte Vorgesetzte. Als nächstes sollten wir sie über diesen Fund informieren. Würdet Ihr ihn bitte zu ihr bringen?', },
    {'Bringt die geöffnete Schatzkiste der Mosh\'Ogg zu Airwyn Bantamflax in Beutebucht am Schlingendornkap.', },
  },
  [26822] = {
    'Nichtsnutzige, züngelnde Kriecher',
    {'Ahem! Hrm, hrm...|n|n<Der Zwerg räuspert sich einige Sekunden lang.>|n|nIhr sucht nach einer Beschäftigung? Und da kommt Ihr zu MIR? Dem kleinen, alten Goris?!|n|nNun, äh... das ist das erste Mal. Ah, ich hab\'s!|n|nDas Tal im Norden ist voll nutzloser Basilisken, die nur ihre Wampe auf dem Boden schleifen. Sie sind zu rein gar nichts nutze und man sagt, sie hätten einmal jemand in Stein verwandelt.|n|nWenn Ihr sie tötet, gebe ich Euch etwas von meinem Zeug.', },
    {'Tötet 12 Donnerschwanz- oder Eisenkieferbasilisken.', },
  },
  [26823] = {
    'Den Mund zu voll genommen',
    {'Was immer Ihr tun wollt: Ich habe genau das richtige Rezept dafür. Ihr wollt einen Sprengstofftrank? BUMM!! Ihr wollt einen Blitztrank? BRITZEL!! Ihr wollt einen Schrumpftrank? Flupp!|n|nAlso Bronwyn sagt, er will einen Kohlenstoffdatierungstrank? Nichts leichter als das. Den könnte ich im Schlaf machen. Das Problem ist... wenn wir wollen, dass er präzise funktioniert, dann brauche ich einige hochwertige Zutaten.|n|nFangen wir mit ein wenig Körperflüssigkeit von einem Basilisken im Norden an. Es muss ein ziemlich großer Basilisk sein...', },
    {'Beschafft eine Phiole mit Eisenkieferkörperflüssigkeit vom Eisenkieferungetüm in der Kristalladermine.', },
  },
  [26824] = {
    'Ergebnisse: Nicht eindeutig',
    {'Ich habe getan, was ich konnte, $N. Ich hatte die richtigen Tränke... Ich hatte die richtigen Rezepte... Aber der Ursprung dieser Probe entzieht sich meiner Kenntnis. Sie ist zehntausende Jahre alt, aber wir haben bewiesen, dass sie nicht titanischen Ursprungs ist. Und ein Blick genügt, um festzustellen, dass es nicht Saronit ist. Also... um was in Branns Namen handelt es sich?|n|nSagt Bronwyn, dass ich mein Bestes gegeben habe. Tut mir leid.', },
    {'Bringt die geöffnete Schatzkiste der Mosh\'Ogg zu Bronwyn im Lager der Forscherliga am Schlingendornkap zurück.', },
  },
  [26825] = {
    'Dask &quot;Der Kolben&quot; Fusselmaul',
    nil,
    nil,
  },
  [26826] = {
    'Dask &quot;Der Kolben&quot; Fusselmaul',
    nil,
    nil,
  },
  [26827] = {
    'Den Irdenen Ring zusammenrufen',
    {'Wir müssen den Irdenen Ring für diesen Kampf zusammenrufen. Unsere zahlenmäßige Unterlegenheit gleichen wir durch unsere Stärke aus.|n|nGeht zum Tempel und versammelt die ruhenden Schamanen aus den hinteren Räumen. Norsala, Lorvarius und ich treffen uns mit ihnen an Lorthunas Tor.', },
    {'Versammelt 5 Schamanen im hinteren Teil des Tempels der Erde und sprecht dann mit Maruut Steinbinder.', },
  },
  [26828] = {
    'Unser Teil der Vereinbarung',
    {'Leider muss ich hierbleiben und auf den Riss aufpassen, also müsst Ihr ohne mich kämpfen. Geht jetzt zu Therazane und schließt Euch wie versprochen dem Kampf an. Ihr solltet Sie am Halcyonaufstieg nördlich von Lorthunas Tor und östlich des Geschliffenen Schlunds vorfinden.|n|nWenn unser Teil der Abmachung erfüllt ist, bringt das letzte Stück der Weltensäule so schnell wie möglich hierher.', },
    {'Sprecht mit Therazane auf dem Halcyonaufstieg.', },
  },
  [26829] = {
    'Der Steinmarsch',
    {'Meine Streitkräfte haben den Angriff bereits begonnen. Schließt Euch ihnen an. Vergießt das Blut dieser Kultisten, damit ich spüren kann, wie sie leiden.', },
    {'Tötet 15 Kultisten des Zwielichthangs.', },
  },
  [26830] = {
    'Köder für den Verräter',
    nil,
    {'Befragt Peons des Himmelpfads von Orgrimmar in der Nähe des Zeppelinturms. Haltet Ausschau nach verdächtigen Peons. Versucht, Sauranok den Mystiker aufzuscheuchen und tötet ihn.', },
  },
  [26831] = {
    'Flug ins Zwielicht',
    {'Terrath braucht Euch auf der anderen Seite des Abgrunds, um Zoltrik Drachenbann zu bekämpfen. Er ist ebenfalls unterwegs, aber er fürchtet, Zoltrik wird sich in die Luft erheben.|n|nWie es scheint, habt Ihr ziemlichen Eindruck hinterlassen, Kleinling. Ist Euch jemals der Gedanke gekommen, dass all dies nie geschehen wäre, wenn ich bei unserem ersten Zusammentreffen auf Euch getreten wäre? Das Schicksal geht seltsame Wege.', },
    {'Besiegt Zoltrik Drachenbann.', },
  },
  [26832] = {
    'Therazanes Gnade',
    {'Der Schattenhammer hat zwei Führungspersönlichkeiten, die getötet werden müssen.|n|nDie eine ist ein Mensch namens Boldrich. Er ist klein, so wie Ihr. Aber dennoch gefährlich, ebenfalls so wie Ihr.|n|nDie andere ist eine Priesterin namens Lorthuna. Sie ist gerissen und nur schwer in die Enge zu treiben. Schlagt schnell zu und lasst sie nicht entkommen, sonst werdet Ihr es später bereuen - das verspreche ich Euch.', },
    {'Besiegt Boldrich Steinreißer und Hohepriesterin Lorthuna.', },
  },
  [26833] = {
    'In Stein gemeißelt',
    {'Ihr habt getan, worum ich Euch gebeten habe, <Volk>. Ich werde zu meinem Wort stehen. Gorsik wird Euch mit unserem Stück der Weltensäule am Tempel treffen.|n|nBeendet Euer Ritual und schließt den Riss. Wenn Ihr das getan habt, sagt Eurem Irdenen Ring, er möge diesen Ort verlassen. |n|nIhr allerdings... Ihr dürft noch eine Weile bleiben, wenn Ihr möchtet. Das habt Ihr Euch verdient.', },
    {'Sprecht mit Maruut Steinbinder am Tempel der Erde.', },
  },
  [26834] = {
    'Hinein in den Abgrund',
    {'Tief in der Nadelfelsschlucht lassen die Mystiker all diese Fungusmissgeburten sprießen. Ich habe Schiefer Treibsand und eine kleine Truppe hingeschickt, damit sie sich darum kümmern, aber sie sind auf Schwierigkeiten gestoßen.|n|nErinnert Ihr Euch noch an den Erzgeomanten? Würdet Ihr im Nordosten hinunterfliegen und ihm behilflich sein?', },
    {'Sprecht mit Schiefer Treibsand in der Nadelfelsschlucht in Tiefenheim.', },
  },
  [26835] = {
    'Ein kleines Problem',
    {'Während Ihr dort draußen wart, hat sich Pyrium Leitstein mit mir in Verbindung gesetzt. Er meinte, dass es eine Angelegenheit höchster Dringlichkeit gäbe und dass man umgehend Eure Unterstützung bräuchte. Kehrt zum Eingang am Nadelfelsbruch im Südwesten zurück.|n|nIch wünsche Euch viel Glück bei der Rettung des Steinvaters und der Bergung des zweiten Fragments.', },
    {'Kehrt zu Pyrium Leitstein im Nadelfelsbruch in Tiefenheim zurück.', },
  },
  [26836] = {
    'Rettet den Steinvater... und Flint',
    {'Wir haben herausgefunden, wo der Steinvater gefangen gehalten wird, und prompt ist der junge Flint losgerannt, um ihn zu befreien!|n|nIch muss Euch nicht sagen, dass das gar nicht gut ist. Flint könnte ebenfalls gefangen genommen werden - oder noch Schlimmeres!|n|nDer Häuptling der Steintroggs, Felsmagen, befindet sich am äußersten Ende der Felssimse über der Nadelfelsschlucht im Norden. Bitte, $N, Ihr müsst Flint folgen und den Steinvater befreien, bevor wir sie beide verlieren!', },
    {'Befreit Steinvater Erzmantel.', },
  },
  [26837] = {
    'Die Grabungsstätte der Forscherliga',
    {'Hört einmal, $N... Ihr scheint genau richtig zu sein.|n|nBronwyn Hackschlag von der Forscherliga sucht neue Rekruten für seine Grabungsstätte am Schlingendornkap. Ich persönlich verstehe ja nicht, warum er nicht einfach nach Beutebucht geht und dort seine Rekruten sucht... Piraten kann man leicht mit ein paar Goldstücken überreden.|n|nWie auch immer - gerüchteweise hört man, dass er endlich etwas dort im Dschungel gefunden hat. Ich frage mich, was das sein könnte?', },
    {'Sprecht mit Bronwyn Hackschlag an der Grabungsstätte der Forscherliga am Schlingendornkap.', },
  },
  [26838] = {
    'Wenn man keine Ahnung hat...',
    {'Vor einigen Jahren hat Captain Kurzen aus Sturmwind eine Brigade ins Schlingendorntal gebracht. Die Einzelheiten seiner Mission sind immer noch unklar. Kurzen fiel schnell dem Wahnsinn anheim, genau wie seine Männer... außer einigen Rebellen, die es sich zur Aufgabe gemacht haben, das Böse, das Kurzen angerichtet hat, ungeschehen zu machen.|n|nWie ich bereits sagte, das war vor vielen Jahren. Jetzt ist mir zu Ohren gekommen, dass Kurzen tot ist. Doch diese Rebellen bestehen immer noch auf ihrer Rebellion. Wenn Ihr Ermittlungen anstellen wollt, findet Ihr sie in einem Lager an der nördlichen Grenze von Schlingendorntal.', },
    {'Meldet Euch bei Leutnant Doren im Rebellenlager im Nördlichen Schlingendorntal.', },
  },
  [26839] = {
    'Eine Auszeit nehmen!',
    {'Sagt einmal, $C, Ihr seht erschöpft aus. Diese schwere Geldbörse... äh, ich meine... schwere Ausrüstung mit sich herumzuschleppen muss doch eine große Belastung für Euren armen Rücken sein.|n|nSassy Hartzang hat vor Kurzem ein erstklassiges Fünf-Sterne Erholungszentrum am Schlingendornkap eröffnet. Ballonfahrten, Ruderboottouren, Tagesausflüge nach Beutebucht... es ist alles vorhanden.|n|nIhr solltet dem Zentrum wirklich einen Besuch abstatten. Ich muss Euch nur anschauen und weiß, dass Ihr nach so vielen schwierigen, lukrativen Abenteuern eine Erholung braucht.', },
    {'Sucht Sassy Hartzang in Hartzangs Versteck am Schlingendornkap auf.', },
  },
  [26840] = {
    'Rückkehr ins Hochland',
    {'Jetzt, da Orgrimmar sicher ist und wir unsere Verbündeten des Drachenmalklans hinter uns wissen, können wir unsere Aufmerksamkeit dem Schattenhochland und der Vernichtung der Truppen von Todesschwinge zuwenden.|n|nIch brauche die Besten der Horde an der Front. Damit meine ich Euch. Und all Eure Freunde.|n|nDas Hochland wird UNS gehören!|n|nBenutzt das neue Portal, das Ihr erschaffen habt, um in den Hafen des Drachenmals zurückzukehren. Meldet Euch bei Zaela, um zu sehen, wo sie Euch am meisten braucht.', },
    {'Benutzt das Portal des Drachenmals in Orgrimmar, um in den Hafen des Drachenmals im Schattenhochland zurückzukehren und sprecht mit Zaela.', },
  },
  [26841] = {
    'Das verbotene Siegelzeichen',
    {'Dieses Siegelzeichen wurde mir durch einen Boten überbracht und stammt von unserer Magierlehrerin Rhyanda. Wie es aussieht, möchte Rhyanda mit Euch sprechen, wenn Ihr einen Moment erübrigen könnt. Lest es und bringt es ihr danach bitte.', },
    {'Sprecht mit Rhyanda in Aldrassil im Laubschattental.', },
  },
  [26842] = {
    'Hier ein Gnoll, dort ein Gnoll',
    {'Seid gegrüßt, $C. Wir haben ein Problem und ich würde Euch bitten, uns zu helfen.|n|nEs handelt sich um Gnolle. Westlich der Stadt streift ein ganzer Haufen dieser Viecher durch die Hügel. Eigentlich ist das kein Grund, beunruhigt zu sein, aber normalerweise haben wir hier keine Gnolle in Loch Modan.|n|nMich interessiert, wo sie herkamen, allerdings bin ich nicht neugierig genug, um diese räudigen Dinger zu fragen. Ich bin der Meinung, wir sollten sie loswerden. Bringt mir Beweise, dass Ihr sie getötet habt und ich werde Euch ein beachtliches Kopfgeld zahlen.', },
    {'Sammelt 12 Gnollohren von Spähern und Schlägern der Moosfelle.', },
  },
  [26843] = {
    'Ein winziger, cleverer Kommandant',
    {'Wir schlagen uns in diesem Land schon seit Jahren mit Kobolden herum. Bisher waren sie kaum mehr als ein Ärgernis. Aber sie werden bei ihren Diebstählen immer geschickter.|n|nIch glaube, einer von ihnen ist irgendwie klüger als üblich. Aber das wird nicht mehr lange der Fall sein!|n|nIch möchte, dass Ihr zu ihrem Lager im Süden geht und sicherstellt, dass sich dort kein "Obermotz" Kobold befindet, der die anderen aufwiegelt. Achtet darauf, auch die Höhle zu untersuchen. Das wäre mit ziemlicher Sicherheit ein guter Ort.|n|nAch ja, und übt keine Zurückhaltung, wenn es darum geht, die Kobolde, die Euch unterwegs begegnen, zu beseitigen.', },
    {'Tötet "Kommandant" Nazrim.', },
  },
  [26844] = {
    'Vom Regen in die Traufe',
    {'Jetzt, da wir diese kleinen Quälgeister erledigt haben, müssen wir uns um weitere Dinge kümmern.|n|nDie Tunnelratten schwärmen durch die ganze Silberbachmine. Sie schlagen Lager auf und schnüffeln überall herum. Dabei ziehen sie immer weitere Kreise. Die gierigen kleinen Viecher suchen bestimmt nach Beute.|n|nVermessen und nach Futter wühlen ist ja schön und gut, solange es nicht auf Zwergenland stattfindet! Kümmert Euch um diese Tunnelratten und meldet Euch dann wieder bei mir.', },
    {'Tötet 5 Feldmesser der Tunnelratten und 5 Futterwühler der Tunnelratten.', },
  },
  [26845] = {
    'Wer hat hier das Sagen?',
    {'Dorli hat mir von diesem verrückten Troggsklaven-Vorhaben erzählt, das bei den Kobolden im Gange ist. Wenn Ihr bisher noch nicht mit ihr gesprochen habt, schlage ich vor, dass Ihr das nachholt. Ich möchte dieser Sache auf den Grund gehen.|n|nIm wahrsten Sinne des Wortes! Wer immer hier die Fäden zieht, sitzt garantiert ganz unten in der Mine und gibt von dort die Befehle. Ich will, dass er zur Strecke gebracht wird.|n|nFindet den gerissenen Schlauberger, der die Geomanten und Gräber dirigiert und bringt mir seinen Kopf.', },
    {'Bringt mir den Kopf von Vorarbeiter Scharfspott.', },
  },
  [26846] = {
    'Ein fieser Plan',
    {'Ich habe herausgefunden, was diese Ratten im Schilde führen. Der Grund, warum so viele von ihnen draußen herumlaufen, ist, dass sie Troggs dazu gebracht haben, für sie in der Mine zu schürfen!|n|nDie Geomanten der Tunnelratten haben irgendeinen Taschenspielertrick ersonnen, mit dem sie die Troggs kontrollieren können. Irgendwas mit Kreaturen der Erde oder so ähnlich.|n|nFaszinierend, aber wir können ihnen das nicht durchgehen lassen. Beseitigt diese Geomanten so schnell wie möglich.', },
    {'Tötet 5 Geomanten der Tunnelratten.', },
  },
  [26847] = {
    'Die Bebenden Felder',
    {'Der König ist nach Süden zu den Bebenden Feldern direkt hinter Steinruh gegangen. Viel Glück bei der Suche nach dem mittleren Weltensäulenfragment. Doch nehmt Euch vor den Riesen und anderen Kreaturen auf dem Feld in Acht, $N.', },
    {'Sprecht mit König Erzmantel auf den Bebenden Feldern in Tiefenheim.', },
  },
  [26848] = {
    'X kennzeichnet den Schatz',
    {'<Der König kennzeichnet einen Punkt auf Eurer Karte.>|n|nDa habe ich es vergraben. Geht dorthin und grabt es für mich aus.|n|nIhr solltet nur den Riesen aus dem Weg gehen. Ich kann Euch aus Erfahrung sagen, dass sie wie ... naja, wie Riesen zuschlagen.', },
    {'Begebt Euch an den Ort, an dem König Erzmantel das zweite Weltensäulenfragment vergraben hat.', },
  },
  [26849] = {
    'Die Axt der irdischen Trennung',
    {'Die Smaragdkolosse müssen von dem Feld entfernt werden. Es ist denkbar, dass einer von ihnen das Fragment hat. Dessen ungeachtet hat Therazane ihre Truppen in unmittelbarer Nähe von Steinruh zusammengezogen und sie bilden eine Bedrohung. Zerhackt die Riesen mit meiner Axt. Dadurch stutzen wir sie auf eine leichter zu handhabende Größe zurecht. Dann könnt Ihr sie töten.', },
    {'Tötet 5 gespaltene Smaragdkolosse.', },
  },
  [26850] = {
    'Elementarerz',
    {'Wir müssen ein Ritual durchführen, um herauszufinden, wo das Weltensäulenfragment hingebracht wurde.|n|nGeht hinaus aufs Feld und sammelt Elementarerz von den Jadewütern. Wenn wir genug davon haben, sollte ich in der Lage sein, Euch eins mit der Erde werden zu lassen, damit Ihr herausfindet, was wir wissen müssen.', },
    {'Sammelt 6 Elementarerze.', },
  },
  [26851] = {
    'Eins mit der Erde',
    {'Ich kenne ein Ritual der Erde, das Euch eins mit ihr werden lässt. Da ich das Fragment bereits berührt habe, werden die Geister der Erde Euch in seine Nähe bringen.|n|nKonzentriert Euch auf die Weltensäule und lasst mich wissen, wenn Ihr bereit seid, $N.', },
    {'Entdeckt das zweite Weltensäulenfragment durch das Ritual \'Eins mit der Erde\'.', },
  },
  [26852] = {
    'Das Fragment im Inneren',
    {'Das zweite Fragment der Weltensäule befindet sich in Lavinius Gewölbe. Begebt Euch hinein und holt es.', },
    {'Bringt das zweite Fragment der Weltensäule in Euren Besitz.', },
  },
  [26853] = {
    'Das mittlere Fragment',
    {'Fliegt. Fliegt, so schnell Ihr eben könnt, $N!|n|nBringt das zweite Fragment zum Tempel der Erde in Tiefenheim zurück.', },
    {'Überbringt das zweite Fragment der Weltensäule Erdenrufer Yevaa im Tempel der Erde in Tiefenheim.', },
  },
  [26854] = {
    'Der vermisste Pilot',
    {'Mein Freund Mori Hangflug, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt. Wir haben nach einem seltenen Erz gesucht, das man für hochwertiges Sprengpulver benötigt, und während unserer Suche hat er seine Maschine einen steilen Hügel hinaufgefahren und sie dabei kaputt gemacht!|n|nImmer noch überzeugt davon, dass es in diesen Bergen Erz gibt, hat er mich beauftragt, unsere Maschinen zu bewachen, während er zu Fuß weitersuchen wollte.|n|nDas ist jetzt mehrere Tage her, und ich habe des Nachts nördlich des Helmsbettsees und westlich des Tunnels das Knurren von Raubtieren gehört. Mori ist ein zäher Bursche, aber ich mache mir Sorgen.|n|nBitte, $N. Sucht ihn.', },
    {'Findet Pilot Hanglug nördlich des Helmsbettsees.', },
  },
  [26855] = {
    'Pilotenrache',
    {'Hangflug schrieb in sein Tagebuch, dass er von Marterklaue, einem "gewaltigen Eisklauenbären", angegriffen wurde. Er hat die Bestie verjagt, aber nicht, ohne vorher übel zugerichtet zu werden.|n|nWenn man sich den Zustand von Hangflugs Leiche so ansieht, muss Marterklaue später wiedergekommen sein und ihn getötet haben.|n|nJedenfalls schrieb Hangflug in sein Tagebuch einen letzten Wunsch:|n|nRache an Marterklaue.', },
    {'Tötet Marterklaue.|n|nBringt Pilot Hammerfuß am Südtoraußenposten die räudige Klaue des Bären und Hangflugs Tagebuch.', },
  },
  [26856] = {
    'Schlagt die Invasion zurück',
    {'Diese Höhle war einst ein Ort großer Ehre. Man brachte junge Krieger hierher, damit sie zum ersten Mal in ihrem Leben einen Erdbohrerwurm erlegen. Daran erinnern wir Orcs uns das ganze Leben lang.|n|nDie Agenten der Brennenden Klinge haben die Einwohner der Höhle versklavt und wollen nun Orgrimmar mit ihren Troggverbündeten angreifen.|n|nWenn Ihr ihre Leutnants zur Strecke bringt, könntet Ihr sie unvorbereitet erwischen und diese Invasion verhindern, bevor sie überhaupt beginnt.', },
    {'Tötet Flintauge, Bazzalan und Jergosh den Herbeirufer.', },
  },
  [26857] = {
    'Abyssions Diener',
    {'Wenn der Drache das Fragment hat, müssen wir seine Aufmerksamkeit auf seinen Hort lenken.|n|nGeht zu Abyssions Hort gleich östlich von hier und besiegt seine Untergebenen. Das wird ihn früher oder später dazu veranlassen, mit dem Weltensäulenfragment aufzutauchen.', },
    {'Besiegt 8 Zwielicht- oder Drachkineinheiten in Abyssions Hort.', },
  },
  [26858] = {
    'Taragaman der Hungerleider',
    {'Der Sengenden Klinge ist es gelungen, einen widerlichen Dämonen zu beschwören, den sie Taragaman den Hungerleider nennen. Er soll bei der Übernahme von Orgrimmar den ersten Angriff leiten.|n|nBeeilt Euch und tötet Taragaman im Namen des Kriegshäuptlings! Lok\'tar ogar!', },
    {'Holt das Herz von Taragaman dem Hungerleider.', },
  },
  [26859] = {
    'Die Suche nach dem verloren gegangenen Ranzen',
    {'Die Troggs sind nicht das Einzige, das Magatha im Flammenschlund interessierte. Sie hatte gehört, dass einer ihrer Diener, ein gewisser Maur Grimmtotem, im Abgrund etwas Sonderbares gefunden haben soll, nur leider schaffte er es nicht mehr, lebend herauszukommen, um ihr davon zu berichten. Sie möchte, dass Maurs Leiche - falls sie noch existiert - geborgen wird...und auch jegliche Hinweise auf das, was er entdeckt haben könnte, als er versuchte, mit den Troggs zu sprechen.|n|nBringt Magatha Gegenstände, die sie interessieren könnten, dann wird sie sich bestimmt mit einer Belohnung nicht kleinlich zeigen.|n|nBegebt Euch noch einmal in den Abgrund im dunkelsten Teil von Orgrimmar.', },
    {'Sucht im Flammenschlund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen.', },
  },
  [26860] = {
    'Blutwurst aus Thelsamar',
    {'Es gibt hier in Thelsamar immer genug Mäuler zu stopfen, mit all den Kindern, die ein und aus gehen, und den Arbeitern von den Ausgrabungsstätten, die nach einem arbeitsreichen Tag hereinkommen. Wir sind berühmt für unsere Blutwurst, Ihr habt sie nicht zufällig schon einmal probiert?|n|nNein? Nun, hierzulande muss man für seine Mahlzeiten arbeiten, und glaubt nur nicht, dass Ihr eine Ausnahme seid, nur weil Ihr $Gein toller:eine tolle:c; $C seid.|n|nBringt mir frische Bärenrücken und überlasst das Kochen nur mir!', },
    {'Sammelt 8 Bärenrücken von Schwarzbären in Loch Modan.', },
  },
  [26861] = {
    'Blockiert die Tore',
    {'Wenn wir eine Chance gegen Abyssion haben wollen, müssen wir sicherstellen, dass ihn keine Verstärkung zur Unterstützung erreicht.|n|nIn seinem Hort gen Osten werdet Ihr zwei Tore vorfinden. Benutzt diesen Sturmstein, um ihre Funktion zu unterbinden.|n|nWenn alles so läuft wie geplant, werden wir Abyssion angreifen können, ohne dass er viel Unterstützung bekommt.', },
    {'Benutzt den Sturmstein am Zwielichttor und Elementartor in Abyssions Hort.', },
  },
  [26862] = {
    'Verpfuschte Elementare',
    {'Die Hexenmeister der Sengenden Klinge haben die Geister der Elementare in Flammenschlund versklavt, $N. Solange mein Zauber sie im Zaum hält, stellen sie keine Bedrohung für die Stadt dar, aber ich kann ihn nicht mehr lange aufrecht halten.|n|nBringt mir sechs der sengenden Bindungen, mit denen sie unter Kontrolle gehalten werden und ich werde ihre Geister im Flammenschlund wieder freisetzen.', },
    {'Beschafft 6 sengende Bindungen.', },
  },
  [26863] = {
    'Schmutzige Pfoten',
    {'Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!|n|nWir werden dieses Ungeziefer noch früh genug ausmerzen, aber der Bund wünscht, dass jemand ihre Gerätschaften aus der Mine schafft, bevor wir Krieger da reinstürmen und was kaputtmachen. Das wird ein harter Abstieg – Ihr solltet vielleicht Unterstützung mitnehmen.|n|nDie Ausstattung wird in Kisten des Bergarbeiterbunds über die Mine verteilt aufbewahrt. Viel Glück.', },
    {'Sucht in der Silberbachmine 6 Sätze Minenarbeiterausstattung zusammen.', },
  },
  [26864] = {
    'Kopflos',
    {'Ihr müsst das hier zu Gebirgsjäger Kadrell bringen. Zeigt es ihm und sagt ihm, dass die fiesen Plagegeister hier möglicherweise eine Art Versammlung abhalten werden.', },
    {'Bringt den Kopf von Vorarbeiter Scharfspott zu Gebirgsjäger Kadrell.', },
  },
  [26865] = {
    'Der Feind tief unten',
    {'Unter dieser Stadt, befinden sich Feinde der Horde, $C.|n|nDie Angehörigen der Sengenden Klinge planen, Orgrimmar für sich zu übernehmen und sie haben bereits den Flammenschlund überrannt! Wir müssen gegen ihre Truppen anstürmen und zurückerobern, was uns gehört!|n|nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Er hat weitere Instruktionen für Euch.', },
    {'Sprecht mit Steingardist Kurjack.', },
  },
  [26866] = {
    'Der Feind tief unten',
    {'Der Flammenschlund in Orgrimmar wurde von der Sengenden Klinge übernommen. $N, wir können das nicht ungestraft durchgehen lassen, sonst richten sie ihren Blick als Nächstes auf Donnerfels.|n|nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Helft ihm auf jede erdenkliche Art und Weise, da unsere Schicksale miteinander verknüpft sind.', },
    {'Sprecht mit Steingardist Kurjack.', },
  },
  [26867] = {
    'Der Feind tief unten',
    {'Kriegshäuptling Garrosh hat unter Aufbietung all seines wohlbekannten Liebreizes freundlich um Eure Anwesenheit im Flammenschlund gebeten, damit Ihr ihm helfen könnt, diesen von der Sengenden Klinge zurückzuerobern. Offensichtlich ist seine verstärkte Stadt nicht so uneinnehmbar, wie er dachte.|n|nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Ich bin sicher, dass er über fähige Hilfe sehr froh sein wird.', },
    {'Sprecht mit Steingardist Kurjack.', },
  },
  [26868] = {
    'Die Achse des Grässlichen',
    {'So, also nun haltet mal die Klappe und lasst mich reden. Der Plan sieht so aus...|n|nDiese Gnolle und Murlocs werden sich wahrscheinlich hier draußen irgendwo treffen. Also nehmt Ihr dieses clevere Pflanzenverkleidungsset von mir, zieht es an und seht wie eine Pflanze aus. Dann schleicht Ihr Euch an sie heran und werft die Geruchspheromone, die ihr gesammelt habt, über die Moosfelle, die bei den Murlocs stehen.|n|nDann brennen bei den Murlocs die Sicherungen durch und die Moosfelle werden es sich zweimal überlegen, ehe sie wieder mit diesen verrückten kleinen Nervensägen zusammenarbeiten.', },
    {'Benutzt das clevere Pflanzenverkleidungsset, um Euch an den Repräsentanten der Moosfelle heranzuschleichen. Dann bestäubt ihn mit den starken Murlocpheromonen.', },
  },
  [26869] = {
    'Tiefe der Tiefen',
    {'<Der Boden unter Euren Füßen erzittert leicht und die tiefe, bekannte Stimme von Diamant scheint aus dem Stein selbst zu sprechen.>|n|nGut gemacht, <Volk>.|n|nIn den unterirdischen Tunneln werdet Ihr den Stein, den Ihr sucht, finden. Painit.|n|nDie Gefahren, die vor Euch liegen sind mannigfaltig...|n|nGefahren, die sogar die Steinlords selbst fürchten.|n|nBleibt ruhig.|n|nBleibt stark.|n|nDie Stärke des Felsens ruht unter Euren Füßen.', },
    {'Findet das Painit in den Bruchtiefen.', },
  },
  [26870] = {
    'Säuberung der Höhlen',
    {'Naralex hatte ein edles Ziel.|n|nUnser großer Anführer hatte sich vorgenommen, den Smaragdgrünen Traum zu betreten und dabei zu helfen, dieses unwirtliche Land wieder zu dem üppigen Wald zu machen, der es einst gewesen war. Aber etwas ging furchtbar schief.|n|nDie treuen Verbündeten von Naralex, die Druiden des Giftzahns, wandten sich gegen ihn! Ihr Ziel ist es nicht, das Brachland zu heilen, sondern es zu beherrschen. $N, bevor wir Naralex erwecken und das Gleichgewicht an diesem wichtigen Ort wiederherstellen können, müsst Ihr die Giftzahnlords auslöschen. Ihr Einfluss ist viel zu groß geworden.', },
    {'Ebru in den Höhlen des Wehklagens möchte, dass Ihr die Giftzahnlords Cobrahn, Anacondra, Pythas und Serpentis vernichtet.', },
  },
  [26871] = {
    'Ein Fels unter vielen',
    {'<Der Boden unter Euren Füßen erzittert leicht und die tiefe, bekannte Stimme von Diamant scheint aus dem Stein selbst zu sprechen.>|n|nIhr habt das getan, worum ich gebeten hatte.|n|nGeht zurück und verlasst die Höhle unverletzt.|n|nVergesst den Edelstein nicht.', },
    {'Kehrt mit dem Painitbrocken zu Diamant an Lorthunas Tor zurück.', },
  },
  [26872] = {
    'Deviatbälge',
    {'Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.|n|nDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Ihre bloße Existenz verursacht der Welt große Schmerzen. Ich glaube, dass ihr Tod unseren Versuchen, den Höhlen Heilung zu bringen, sehr helfen wird.|n|nWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen hinab, tötet so viele wie möglich und bringt mir ihre Bälge als Beweis ihres Ablebens.', },
    {'Nalpak möchte 10 Deviatbälge.', },
  },
  [26873] = {
    'Vorbeugende Maßnahmen',
    {'In diesen Höhlen befindet sich ein Kraut mit unvorstellbaren Kräften, $N. Möchtet Ihr mir helfen, es zu sammeln?|n|nEs handelt sich um eine seltene Blume mit Namen Schlangenflaum. Ich glaube, dass große Mengen davon weitere Alpträume, wie den von Naralex in Zukunft verhindern können.|n|nLeider findet man Schlangenflaum nur in den dunkelsten Ecken dieses Ortes.', },
    {'Nalpak möchte, dass Ihr 5 Schlangenflaum sammelt.', },
  },
  [26874] = {
    'Die Auferstehung von Naralex',
    {'Jetzt, da die Giftzahnlords tot sind, sprecht mit Muyoh. Er wird Euch dabei helfen, Naralex aufzuwecken und diesen Alptraum zu beenden.', },
    {'Sprecht mit Muyoh.', },
  },
  [26875] = {
    'Unsterbliches Zwielicht',
    {'Die Schattenhammerkultisten sind hier! Sie versuchen, das Ritual zu verhindern! Geht zurück in die Kammern und wehrt sie ab!', },
    {'Tötet 12 Zwielichteindringlinge und 1 entweihten Erdwüter.', },
  },
  [26876] = {
    'Das Weltensäulenfragment',
    {'Es wird Zeit, $N. Wir haben Abyssion erspäht, auf dem Weg zu seinem Hort.|n|nDer Schattenhammer dachte wahrscheinlich, dass das Fragment sicher ist, wenn ein Drache es bewacht, aber ich habe genug Drachen gesehen und kenne ihre einzige Schwäche. Stolz.|n|nAbyssion wird nicht vor einem Kampf mit uns kläglichen Sterblichen davonlaufen.|n|nStellt das Banner des Irdenen Rings in die Mitte seines Horts. Wenn wir ihn besiegt haben, bringt das Fragment zu Maruut. Wir müssen die Weltensäule so bald wie möglich reparieren.', },
    {'Stellt das Banner des Irdenen Rings in der Mitte von Abyssions Hort auf, tötet ihn und nehmt das erste Weltensäulenfragment an Euch.', },
  },
  [26877] = {
    'Das Fragment im Inneren',
    {'$N, Ihr müsst Lavinius Gewölbe im Südosten betreten und das zweite Weltensäulenfragment bergen.', },
    {'Bringt das zweite Fragment der Weltensäule in Euren Besitz.', },
  },
  [26878] = {
    'Jünger von Naralex',
    {'$C, das Brachland war einst einer der schönsten Orte in ganz Kalimdor. Es war vielversprechend und voller Leben.|n|nWie Ihr seht, ist das nicht länger der Fall. Es ist ein Land voller Qual und Zwietracht.|n|nDie Jünger von Naralex wollen die Höhlen des Wehklagens säubern und sie in ihrer früheren Schönheit wiederherstellen. Sprecht in den Höhlen des Wehklagens hinter dem Eingang mit Nalpak.', },
    {'Sprecht in den Höhlen des Wehklagens mit Nalpak.', },
  },
  [26879] = {
    'Jünger von Naralex',
    {'$C, dieser Ort ist für meine Geschäftsvorhaben... sagen wir... suboptimal. Wenn ich noch besser zu Fuß wäre, hätte ich eine Idee, die mich zum reichsten Goblin aller Zeiten machen würde!|n|n$GEin:eine:c; $C von Eurem Format müsste doch erkennen, welche Möglichkeit sich $Gihm:ihr; da eröffnet - oder sich wenigstens um die Umwelt sorgen oder so was...|n|nGeht und sprecht in den Höhlen des Wehklagens mit Nalpak. Er ist ein Jünger von Naralex und ganz unter uns - ich glaube, die wollen diesen verfluchten Ort endgültig in Ordnung bringen! Das ist mein Durchbruch!', },
    {'Sprecht in den Höhlen des Wehklagens mit Nalpak.', },
  },
  [26881] = {
    'Auf der Suche nach Thaelrid',
    nil,
    nil,
  },
  [26882] = {
    'Schurkerei in der Tiefschwarzen Grotte',
    {'Meine Kräfte haben mich verlassen. Ich brauche Eure Hilfe!|n|nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporkroch und den heiligen Mondbrunnen besudelte.|n|nAku\'mai, eine Dienerin der Alten Götter, erhob sich aus den Wassern.|n|nDie Kultisten des Schattenhammers haben sich mit den Naga verbündet, um diesen Ort zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku\'mai, um Macht zu erlangen.|n|nErschlagt Kelris und bringt seinen Kopf zu Ashelan.', },
    {'Holt den Kopf von Zwielichtfürst Kelris.', },
  },
  [26883] = {
    'Die Stunde der Finsternis',
    {'Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder des Schattenhammers, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.|n|nWir glauben, dass der Schattenhammer sich mit den Naga verbündet hat und sich ihre Anhänger hier zusammenrotten.|n|nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.|n|nFührt Krieg gegen den Schattenhammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.', },
    nil,
  },
  [26884] = {
    'Erforschung der Verderbnis',
    {'Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?|n|nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.|n|nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. Versucht die Hirnstämme nicht zu beschädigen während Ihr sie tötet, ich brauche ausschließlich makellose Exemplare.', },
    {'Sammelt 8 verderbte Hirnstämme.', },
  },
  [26885] = {
    'Wissen in der Tiefe',
    {'Wie Ihr vielleicht wisst, ist es meine Pflicht als Auszubildende, Lehren für meine Vorgesetzten zusammenzutragen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die schlafenden Alten Götter erwecken können, wenn sie missbraucht werden.|n|nEs kursieren Gerüchte um einen alten Text, das \'Manuskript von Lorgalis\', das sich tief auf dem Boden des Teichs von Ask\'ar befindet, in einer eingedellten Eisentruhe. Dieser Ort ist die ehemalige Heimat unserer längst verstorbenen Ahnen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.|n|nSucht das Manuskript, bitte. Ich verfüge nicht über genug Fähigkeiten, um weiter voranzuschreiten!', },
    {'Findet das Manuskript von Lorgalis.', },
  },
  [26886] = {
    'Genug gebrüllt',
    {'Das fiese Schiff auf der Ostseite der Bucht feuert ständig seine Kanonen auf uns ab. Es ist ja ganz lustig zuzusehen, wie die Goblins von Kanonenkugeln getroffen werden, aber einige meiner Gnomfreunde werden auch getroffen!|n|nEs wäre wirklich sehr nett, wenn Ihr es schafft, Euch an den Kanonen vorbei auf das Schiff zu begeben. Da ist ein gemeiner alter Zuchtmeister, der die anderen Deckmatrosen anschreit. Ich bin sicher, wenn Ihr ihn verprügelt oder tötet, werden sie nicht länger auf uns schießen!', },
    {'Tötet den Zuchtmeister der Südmeerfreibeuter.', },
  },
  [26887] = {
    'Wir füllen uns die Taschen',
    nil,
    {'Sammelt 20 Goldfüllungen von Musketieren oder Schlägern der Südmeerfreibeuter.', },
  },
  [26888] = {
    'Alptraum in der Tiefe',
    {'In den dunkelsten Winkeln der Tiefschwarzen Grotte ist ein Monster dort erschienen, wo die Alten Götter lauern. Wir kennen es nur als Aku\'mai.|n|nDie Alten Götter und ihre Diener sind eine große Gefahr für unsere Welt. Vor langer Zeit herrschten sie über Azeroth und ich fürchte, dass sie diese Herrschaft erneut anstreben, auch wenn sie Azeroth bei dem Versuch zerstören würden.|n|n$N, Aku\'mai ist eine Kreatur unbeschreiblicher Alpträume. Wir können einfach nicht dulden, dass sie weiter existiert. Vernichtet sie.', },
    {'Tötet Aku\'mai.', },
  },
  [26889] = {
    'Genug der Fröhlichkeit',
    {'Meine Güte, wir haben hier ganz schön aufgeräumt!|n|n<Kelsey räuspert sich.>|n|nHört mal, $N, ich freue mich darauf, diese Tötungskiste zu verlassen, damit ich endlich von diesen Goblins wegkomme und die aufgesetzte Fröhlichkeit ablegen kann. Wenn Ihr hier in der Gegend die Interessen von Gnomeregan weiter vertreten möchtet - und damit auch die der Allianz -, geht vom Außenposten der Schmuggler nach Süden.|n|nSprecht dort mit Zeke Scheuerschuh und denkt daran, dass jegliche Arbeit für die Dampfdruckgoblins uns dabei helfen wird, die Bilgewassergoblins endgültig aus Tanaris zu vertreiben.', },
    {'Sprecht am Außenposten der Schmuggler mit Zeke Scheuerschuh.', },
  },
  [26890] = {
    'Die Essenz von Aku\'mai',
    {'Im Eingangsbereich der Tunnel der Tiefschwarzen Grotte findet man überall an den Höhlenwänden große Saphiransammlungen. Uns ist aufgefallen, dass die Naga zur selben Zeit angefangen haben, diese Kristalle abzubauen, als sich auch ihre Waffen stark verbessert haben.|n|nDie Kristalle besitzen offenbar große Elementarkraft und wenn man sie zweckentfremdet, könnten sie eine mächtige Komponente für meine Schmiedekunst sein.|n|nWerdet Ihr mir helfen, $N? Die Tiefschwarze Grotte liegt am Zoramstrand nördlich unseres Außenpostens.', },
    {'Sammelt 20 Saphire von Aku\'mai.', },
  },
  [26891] = {
    'Inmitten der Ruinen',
    {'Die Anhänger des Schattenhammers sind hier in die Mondschreinruinen eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen.|n|n$N, findet die Zwielichtagenten hier, dann sucht den Tiefenstein der Ruinen. Er dürfte sich irgendwo unter Wasser befinden, wahrscheinlich direkt vor ihren Nasen. Darin ist ein Tiefenkern - ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten von Elementaren liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.', },
    {'Findet den Tiefenkern.', },
  },
  [26892] = {
    'In den tiefsten Tiefen',
    {'Die Naga und der Schattenhammer arbeiten zusammen, um all den Fortschritt, den wir in dieser Gegend erzielt haben, zunichtezumachen. Schlimmer noch, Je\'neu sagte mir, dass er die Gegenwart eines Alten Gottes tief unter uns spürt.|n|nWenn sie Chaos haben wollen, dann werden wir ihnen genau das geben.|n|n$N, schlagt ihre stärksten Krieger und dann werden wir sehen, wie ihnen das gefällt.|n|nSeid bei Eurer Suche vorsichtig, die Tiefschwarze Grotte ist voller Unterwasserpassagen und Seitengänge, in denen sich Eure Ziele verbergen können.', },
    {'Vernichtet Ghamoo-Ra, Lady Sarevess und Gelihast.', },
  },
  [26893] = {
    'Tiefschwarze Grotte',
    nil,
    {'Sprecht mit Je\'neu Sancrea.', },
  },
  [26894] = {
    'Tiefschwarze Grotte',
    nil,
    {'Sprecht mit Je\'neu Sancrea.', },
  },
  [26895] = {
    'Die Donnerkuppel!',
    {'Hey, Freund, sucht Ihr Aufregung? Abenteuer? Geld? Gewalt? |n|nNun, Ihr solltet Gewalt schon mögen, denn die Donnerkuppel in Gadgetzan wurde gerade wieder eröffnet. Es war schon traurig, dass sie so lange nicht genutzt werden konnte, wegen der ganzen Schmerzensgeldklagen, Anklagen wegen Gaunereien und Urheberrechtsverletzungen... Aber nun ist sie wieder da und wartet nur darauf, dass stattliche, wilde Typen wie Ihr kommt und Euch mit den garstigsten Gegnern aller Zeiten anlegt!|n|nMacht Euch auf den Weg nach Gadgetzan und sprecht mit Dr. Haudenlukas, um Euch einzuschreiben. Und sagt es all Euren Freunden!', },
    {'Sprecht in Gadgetzan mit Doktor Haudenlukas.', },
  },
  [26896] = {
    'Die Donnerkuppel!',
    {'Hey, Freund, sucht Ihr Aufregung? Abenteuer? Geld? Gewalt? |n|nNun, Ihr solltet Gewalt schon mögen, denn die Donnerkuppel in Gadgetzan wurde gerade wieder eröffnet. Es war schon traurig, dass sie so lange nicht genutzt werden konnte, wegen der ganzen Schmerzensgeldklagen, Anklagen wegen Gaunereien und Urheberrechtsverletzungen... Aber nun ist sie wieder da und wartet nur darauf, dass stattliche, wilde Typen wie Ihr kommt und Euch mit den garstigsten Gegnern aller Zeiten anlegt!|n|nMacht Euch auf den Weg nach Gadgetzan und sprecht mit Dr. Haudenlukas, um Euch einzuschreiben. Und sagt es all Euren Freunden!', },
    {'Sprecht in Gadgetzan mit Doktor Haudenlukas.', },
  },
  [26897] = {
    'Tiefschwarze Grotte',
    nil,
    {'Sprecht mit Schildwache Aluwyn.', },
  },
  [26898] = {
    'Tiefschwarze Grotte',
    {'Ich mache mir sehr viel aus diesen Wäldern, $C. Es sieht wirklich nicht gut aus hier, aber ich würde mich lieber der Horde allein entgegenstellen, als zuzusehen, wie sie sich ihren Weg durch die Bäume hacken und schneiden.|n|nReist nach Westen zur Tiefschwarze Grotte. Sobald Ihr sie betretet, sucht Schildwache Aluwyn auf. Sie ist eine enge Vertraute, die Hilfe benötigt. Die |n|nOrcs im Außenposten von Zoram\'gar bedrohen ihre Position in diesem Augenblick. Wenn sie die Tiefschwarze Grotte einnehmen, werden sie bestimmt jeden Baum fällen, um ihren Wahnsinn zu schüren.', },
    {'Sprecht mit Schildwache Aluwyn.', },
  },
  [26899] = {
    'Der Feind meines Feindes',
    {'Kultisten...Opfer...Macht...|n|nFeind...erwacht...|n|nAlter Gott...sperrt...mich ein...|n|nLord...Kelris...|n|nBringt Kopf...Rache...|n|nAUSLÖSCHEN!!!', },
    {'Verschafft Euch den Kopf von Zwielichtfürst Kelris.', },
  },
  [26900] = {
    nil,
    {'Ich spüre eine ungeheure Macht in diesen gewundenen Dornen, $N. Die ganze Gegend wird durch ihre Gegenwart belebt.|n|nEs muss der Geist von Agamaggan sein! Er war eins der ersten und mächtigsten Wesen, die je gelebt haben - die Stacheleber verehren ihn zutiefst.|n|nJede Ranke, die Ihr im Lande seht, stammt von seinem Blut - von dem Opfer, das er brachte, um Azeroth während des Kriegs der Ahnen zu retten.|n|nWenn ein Wesen die Stacheleber wieder zu ihren edlen Wurzeln führen kann, dann er.|n|nIhr müsst ihn finden.', },
    {'Findet den Geist von Agamaggan.', },
  },
  [26901] = {
    'Go, Go, Guano!',
    {'Die Fledermäuse aus dem Kral der Klingenhauer produzieren eine äußerst seltsame, natürliche Substanz. Der Gestank ihres Guano scheint die Stacheleber in mörderische Raserei zu versetzen - und hier stinkt es gewaltig danach!|n|nIhr müsst die Fledermaushöhle finden und mir eine passende Probe bringen. Wenn wir die Auswirkungen umkehren und ein Gegengift herstellen können, können wir die Stacheleber vielleicht retten.', },
    {'Sammelt 1 Häufchen Kralguano.', },
  },
  [26902] = {
    'Zurück zur Stadt akzeptiertes Verfolgungsereignis',
    nil,
    nil,
  },
  [26903] = {
    'Willix der Importeur',
    {'Endlich ist Hilfe eingetroffen!|n|nIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.|n|nWisst Ihr, ich bin Unternehmer. Immer auf die schnelle Mark aus, wie man so sagt. Ich habe Wind davon bekommen, dass sich Schweineschnauzen unglaublich gut auf dem Markt verkaufen lassen. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!|n|nWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, soll es Euer Schaden nicht sein.', },
    {'Führt Willix den Importeur aus dem Kral der Klingenhauer hinaus.', },
  },
  [26904] = {
    'Verderbnis',
    nil,
    nil,
  },
  [26905] = {
    'Agamaggans Auftrag',
    {'Hört gut zu, Sterblicher.|n|nDie Stacheleber sind meine Kinder. Dieses Land ist von meinem Blut durchzogen.|n|nCharlga Klingenflanke hat meine Kinder in die Dunkelheit geführt, nachdem sie von der Geißel in den Wahnsinn getrieben wurde.|n|nTötet sie, $N. Tötet sie und öffnet meinen Kindern die Augen.|n|nGebt den Stachelebern die Chance, wieder zu ihren edlen Wurzeln zurückzukehren.|n|nLasst sie meinen Segen wieder verdienen. Bringt mir ihr Herz!!!|n|n', },
    {'Nehmt Charlga Klingenflanke das Herz.', },
  },
  [26906] = {
    nil,
    {'Ich spüre eine ungeheure Macht in diesen gewundenen Dornen, $N. Die ganze Gegend wird durch ihre Gegenwart belebt.|n|nEs muss der Geist von Agamaggan sein! Er war eins der ersten und mächtigsten Wesen, die je gelebt haben - die Stacheleber verehren ihn zutiefst.|n|nJede Ranke, die Ihr im Lande seht, stammt von seinem Blut - von dem Opfer, das er brachte, um Azeroth während des Kriegs der Ahnen zu retten.|n|nWenn ein Wesen die Stacheleber wieder zu ihren edlen Wurzeln führen kann, dann er.|n|nIhr müsst ihn finden.', },
    {'Sprecht mit dem Geist von Agamaggan.', },
  },
  [26907] = {
    'Macht sie nieder!',
    nil,
    nil,
  },
  [26908] = {
    'Dorn im Auge',
    {'Mankriks Wut über seine tote Frau bietet Anlass zu weiterer Sorge, $C.|n|nDie Stacheleber im Kral der Klingenhauer sind weitaus skrupelloser und hasserfüllter, als Mankrik sich je vorstellen konnte.|n|nIhr solltet nach Süden reisen und mit meinem alten Freund Auld Steinkeil sprechen. Er arbeitet daran, ihrer Raserei ein Ende zu bereiten, bevor das ohnehin geschwächte Land noch mehr leidet.', },
    {'Sprecht mit Auld Steinkeil.', },
  },
  [26909] = {
    'Die Steinsplitter',
    {'Uralte Steine sind über das ganze Land verstreut. Die Elemente strömen in Scharen zu ihnen und umringen sie schützend.|n|nEs handelt sich um Orte großer Macht. Der größte von ihnen liegt westlich von Hammerfall. Keine Seele dringt dort widerrechtlich ein, aber wenn Ihr alleine dort hingeht, hört ihr das Flüstern der Erde.|n|nIch bin schon lange nicht mehr dort gewesen, aber unsere Grunzer berichteten mir, dass das Flüstern wieder begonnen hat. Würdet Ihr für mich nachsehen? Werdet ihr nachsehen, ob die Steine immer noch sprechen?', },
    {'Untersucht die Splitter von Myzrael.', },
  },
  [26910] = {
    'Geätzter Brief',
    {'Mir wurde aufgetragen, Euch so bald wie möglich, nachdem Ihr von der Angelegenheit mit den Spionen des Schwarzfels zurückgekehrt seid, hierauf aufmerksam zu machen, $N. Es scheint sich um einen Brief zu handeln, der mit dem Siegel von Ashley Blank, unserer Jägerlehrerin, versehen ist. Ich würde keine Zeit verlieren und ihn sofort lesen, bevor Ihr hier in der Abtei irgendetwas anderes macht.', },
    {'Lest den geätzten Brief und sprecht im Nordhaintal mit Ashley Blank.', },
  },
  [26911] = {
    'Myzraels Geschichte',
    {'Als der Stein in Schweigen verfällt, bleibt Ihr mit einem vagen Unbehagen zurück. Etwas stimmt nicht.|n|nVielleicht solltet Ihr Zaruk erzählen, was Ihr bis jetzt getan habt.', },
    {'Kehrt in das Arathihochland nach Hammerfall zu Zaruk zurück.', },
  },
  [26912] = {
    'Die entfesselte Prinzessin',
    {'Myzrael ist eine Betrügerin. Sie ist eine uralte Macht, die vor langer Zeit unter Verschluss genommen wurde und da sollte sie auch bleiben.|n|nIhr müsst an den Splittern von Myzrael, wo Ihr zuerst mit ihr gesprochen habt, die Konfrontation mit ihr suchen. Ruft sie mit dieser Schriftrolle herbei. Wenn sie dann in voller Größe an der Oberfläche angelangt ist, besiegt sie. Dann nehmt die geisterhaften Fesseln von ihrem Körper und legt sie auf die Splitter, damit sie wieder vollkommen gebunden ist.|n|nViel Glück, $N... Möge die Vergangenheit Euch nicht mehr beunruhigen.', },
    {'Ruft Myzrael an den Splittern von Myzrael herbei und besiegt sie.', },
  },
  [26913] = {
    'In den Kampf stürmen',
    nil,
    nil,
  },
  [26914] = {
    'Feuerbrand',
    nil,
    nil,
  },
  [26915] = {
    'Tiefe Einschnitte',
    nil,
    nil,
  },
  [26916] = {
    'Beherrschung des Arkanen',
    nil,
    nil,
  },
  [26917] = {
    'Der Weg des Jägers',
    nil,
    nil,
  },
  [26918] = {
    'Die Macht des Lichts',
    nil,
    nil,
  },
  [26919] = {
    'Das richtige Wort',
    nil,
    nil,
  },
  [26920] = {
    'Die Schlacht um Andorhal',
    {'Beeilt Euch, $N... Wir haben keine Zeit zu verschwenden.|n|nDie Stadt Andorhal steckt mitten in einem dreiseitigen Krieg zwischen den Verlassenen, der Allianz und der Geißel. Fürstin Sylvanas hat einen ihrer besten Todesritter entsandt, um den Sturmangriff für ihre Sache zu leiten. Dennoch bin ich sicher, dass er jede Hilfe gebrauchen kann. Arthas ist tot, deshalb ist jetzt der perfekte Zeitpunkt für die Verlassenen, Andorhal einzunehmen.|n|nSprecht mit dem Fledermausführer Timothy Cunningham, wenn Ihr bereit seid, und er wird Euch den nächsten Flug dorthin verschaffen.', },
    {'Meldet Euch in den Westlichen Pestländern innerhalb Andorhals bei Koltira Todesweber.', },
  },
  [26921] = {
    'Erst die Geißel... dann die Allianz',
    {'Dunkelmeister Gandling vom Kult der Verdammten führt die Offensive der Geißel hier in Andorhal an. Mein alter Widerpart, Thassarian, führt die Streitkräfte der Allianz an. Wenn wir Andorhal für uns gewinnen wollen, müssen wir beide besiegen. Doch wir werden sicherlich nicht beide gleichzeitig angreifen können.|n|nIch kenne Thassarian gut genug, um zu wissen, dass er sich zuerst auf die Geißel konzentrieren wird. Wir werden dasselbe tun.|n|nSchaltet die schwächeren ausgedörrten Geißeldiener aus, damit sie zahlenmäßig unterlegen sind. Die Allianz wird unsere Rache erst später zu spüren bekommen.', },
    {'Tötet 15 ausgedörrte Geißeldiener in Andorhal.', },
  },
  [26922] = {
    'Der unendliche Fluss',
    {'Araj der Beschwörer verstärkt die Verteidigung der Geißel mit einfachen Skeletten... eine Armee von Schwächlingen, die Euch eher überrennen als übermannen wird. Er hat Animi in den nördlichen Türmen Andorhals versammelt, die diese Skelette in einer erschreckenden Geschwindigkeit hervorrufen können. Ich habe aber eine Lösung!|n|n<Jearl reicht Euch ein paar Granaten.>|n|nIhre Funktion ist einfach. Wenn diese Granaten auf einen Knochenanimus - oder in unserem Fall einen Haufen Skelette - geworfen werden, wird nicht mehr als Splitter von ihnen übrig bleiben.', },
    {'Benutzt Jearls Handgranaten und tötet 5 Berserker der Klapperknochen und zerstört einen Knochenanimus der Geißel.', },
  },
  [26923] = {
    'Kriegsmaschinen',
    {'Ihr Narren werdet die Geißel niemals besiegen, solange diese Monstrositäten herumlaufen. Koltira quasselt ständig davon, sie zahlenmäßig unterlegen zu machen, aber die beste Waffe der Geißel hier in Andorhal findet man unter diesen herumtorkelnden Schlägern, die meine Todeswachen wie Puppen umherschleudern.|n|nDas hat jetzt ein Ende.|n|n$N, geht auf das Schlachtfeld und vernichtet diese Monster.', },
    {'Zerstört 6 aufgeschlitzte Ungetüme in Andorhal.', },
  },
  [26924] = {
    nil,
    {'Scholomance ist eine der letzten verbleibenden Bastionen der Geißel im Westen des Thondroril. Der Direktor von Scholomance, ein Kultist namens Dunkelmeister Gandling, ist auf dem Schlachtfeld erschienen.|n|nDas wird der letzte Fehler sein, der ihm unterläuft.|n|nIhr werdet Gandling auf einem Platz in der Nähe des südlichen Stadtrands finden. Ich möchte, dass Ihr mit Gandling kämpft und ihn schwächt. Ich werde Euch beistehen, damit er sein Ende findet.', },
    {'Tötet Dunkelmeister Gandling in Andorhal.', },
  },
  [26925] = {
    'Araj der Beschwörer',
    {'Nun da der Animus besiegt ist, ist der nächste logische Schritt die Auslöschung Arajs und der Erhalt einer Scherbe seines Phylakteriums. Ihr habt ihn wahrscheinlich schon am Brunnen in der Stadtmitte herumlümmeln sehen.|n|nNehmt meine Granaten mit. Sie werden Araj keinen Schaden zufügen, aber Ihr könnt sie benutzen, wenn er auf die Idee kommt, Skelette zu beschwören, und diese damit in die Luft jagen. Ihr wisst ja, wie das geht.', },
    {'Tötet Araj den Beschwörer. Ihr könnt Jearls Handgranaten benutzen, um die Berserker der Klapperknochen zu zerstören.', },
  },
  [26926] = {
    'Sieg, im Moment',
    {'Die Verlassenen haben gesiegt und unsere Streitmächte sind immer noch stark. Gemäß unserer strategischen Kriegsführung müssten wir die Allianz jetzt angreifen, solange man sich dort noch vom Kampf erholt und nicht mit einem Angriff rechnet. Ich habe allerdings andere Pläne...|n|nWir werden warten. Wir greifen Thassarian und seine Truppen an, wenn der richtige Zeitpunkt gekommen ist. Sprecht in der Zwischenzeit mit Rhonda Molver und nehmt einen Flug Richtung Bollwerk an der westlichen Grenze der Pestländer. Hochexekutor Derrington wird Euch mit Eurer nächsten Aufgabe vertraut machen.|n|nVon mir werdet Ihr wieder hören, sobald Ihr in Andorhal gebraucht werdet.', },
    {'Meldet Euch in Tirisfal am Bollwerk bei Hochexekutor Derrington.', },
  },
  [26927] = {
    '...und plötzlich Murlocs!',
    {'Also, wir haben Troggs, die für Kobolde arbeiten und Kobolde, die für Gnolle arbeiten. Die Gnolle müssen aus dem Sumpfland hergezogen sein.|n|nWas weiß ich denn? Nun, sie haben Freunde mitgebracht, denn die Murloc der Blaukiemen schwärmen überall am Loch herum, oder an dem, was von ihm übrig geblieben ist.|n|nPlagegeister sind Plagegeister, aber die Koordination ist besorgniserregend. Ihr müsst mit Kanari Zielwasser reden. Sie ist eine der besten Jägerinnen im Umkreis und sie wird wissen, wie man mit den Murlocs umgeht - wenn es Euch gelingt, sie lange genug von ihrem Krug wegzuzerren.', },
    {'Sprecht mit Kanari Zielwasser.', },
  },
  [26928] = {
    'Das riecht nach \'nem Plan',
    {'Murlocs, die mit Gnollen zusammenarbeiten? Das ist lachhaft! Nun, sie einfach nur zu töten wird Euch auch nicht weiterhelfen. Es gibt zu viele von den Quälgeistern.|n|nAber ich habe einen Plan - ich benutze mein Köpfchen, müsst Ihr wissen. Diese Murlocs sondern einen Geruch ab, den sie überall hinterlassen. Wenn andere Murlocs das riechen, werden sie irre! Damit kann man sie prima ködern.|n|nWie auch immer, sie haben kleine Drüsen, in denen sich der Geruchsstoff befindet. Geht und holt mir ein paar davon.', },
    {'Sammelt am Loch 7 Stinkdrüsen eines Murlocs von beliebigen Murlocs der Blaukiemen.', },
  },
  [26929] = {
    'Ein Haufen Kroki',
    {'Während Ihr herumlauft und das tut, was immer ihr da auch tut - würde es Euch da etwas ausmachen, mir ein wenig zu helfen?|n|nSchaut, normalerweise gehe ich unten am Loch Krokilisken jagen, aber unter den gegebenen Umständen ziehe ich es vor, hier zu sitzen. Es ist sehr höflich von Euch, mir deshalb keine Vorwürfe zu machen. Danke!|n|nDa ihr $Gsolch ein feiner Herr:so eine feine Dame; seid, warum bringt Ihr mir nicht ein paar Krokiliskenkiefer mit und ich gebe Euch im Gegenzug ein bisschen fast sauberes Geld?', },
    {'Sammelt 6 Krokiliskenkiefer.', },
  },
  [26930] = {
    'Nach dem Kreuzzug',
    {'Unsere Siege häufen sich, $N. Der Scharlachrote Kreuzzug, der die Verlassenen schon seit Langem verfolgt, pfeift aus dem letzten Loch. Sie halten immer noch ihr Kloster hier in Tirisfal, aber sie haben Herdweiler und Tyrs Hand im fernen Osten verloren.|n|nErst letzte Woche gab es Berichte von Aktivitäten des Scharlachroten Kreuzzugs in einem kleinen Lager östlich vom Teufelssteinfeld, aber ich habe guten Grund anzunehmen, dass auch sie ausgelöscht wurden. Reist dorthin und überprüft für mich diese Information.', },
    {'Späht östlich vom Teufelssteinfeld in den Westlichen Pestländern das Lager des Scharlachroten Kreuzzugs aus.', },
  },
  [26931] = {
    'Füchse und Hunde',
    {'Die Streitkräfte der Allianz laufen in den Pestländern herum, als ob die Gegend ihnen gehört. Nun, dem ist nicht so. Dieses Land gehört rechtmäßig der Dunklen Fürstin!|n|nAls der Kampf um Andorhal zum Ende kam, zerstreuten sich die Kräfte der Allianz, die die Pestländer besetzten. Einige von ihnen sind genau östlich von hier und jagen Füchse. Beweist ihnen, dass das hier das Gebiet der Verlassenen ist.|n|nTötet die Jäger. Tötet ihre Jagdhunde. Und wenn Ihr gerade dabei seid, tötet die Füchse noch obendrein.', },
    {'Tötet 4 Fuchsjäger der Allianz, 4 Bullenmastiffs und 4 Weißschwanzfüchse in den Westlichen Pestländern.', },
  },
  [26932] = {
    'Ausgeflattert',
    {'Als der Steinwerkdamm brach, legte er fast den ganzen See trocken. Eine verheerende Umweltkatastrophe.|n|nUnd wagt es nicht, zu denken, dass das keine Auswirkungen auf uns Zwerge hatte! Wir haben nicht nur absolut keine Fische mehr, sondern da draußen liegen über viele Morgen verstreut tote Dreschadon und verrotten in der Sonne. Die Bussarde sind hinter ihnen her und verbreiten dabei Dreck und Krankheiten an den Außenbezirken der Stadt.|n|nIch kann Euch nicht darum bitten, das alles zu säubern, aber könntet Ihr Euch der Bussarde annehmen? Es wird schon helfen, nur ein paar zu töten.', },
    {'Tötet 8 Lochbussarde.', },
  },
  [26933] = {
    'Feind oder Bauer?',
    {'Die Männer, die das Teufelssteinfeld bestellen, sind keine Bauern. Sie sind Soldaten.|n|nThassarians Streitkräfte benötigten Nahrung, also hat er einige Allianzler aus Andorhal nach Norden entsandt, damit sie sich um das Teufelssteinfeld kümmern. Der Kampf um Andorhal mag vorüber sein, aber es droht bereits die nächste Schlacht... Verlassene gegen Menschen. Wenn die dort auf dem Teufelssteinfeld arbeitenden Soldaten getötet werden, wird das den Streitkräften der Dunklen Fürstin einen entscheidenden Vorteil verschaffen.', },
    {'Tötet 9 Allianzarbeiter auf dem Teufelssteinfeld.', },
  },
  [26934] = {
    'Verborgene Krankheit',
    {'Ich brauche verseuchtes Gras für ein... ein Experiment sozusagen. Diese Argentumkreuzfahrer und die höllischen Cenarischen Druiden haben bei der Heilung der Pestländer wirklich ganze Arbeit geleistet. Ich kann keine brauchbaren Reagenzien in erreichbarer Nähe finden.|n|nAllerdings tragen einige der hiesigen Wildtiere noch die Seuche in sich. Tötet einen kranken Schwarzbär und pflückt dann das Gras, das dort wächst, wo sein verfallender Körper liegt. Das ist nicht optimal, aber es wird genügen.', },
    {'Tötet kranke Schwarzbären in den Westlichen Pestländern und pflückt dann 20 Pesttentakel, die in der Nähe ihrer Körper wachsen.', },
  },
  [26935] = {
    'Sägewerk des Nordkamms',
    {'Wir sind nicht die einzigen Argentumkreuzfahrer hier in den Pestländern. Unser Hauptquartier, Herdweiler, liegt im Norden. Noch etwas näher im Norden ist ein kleines Sägewerk, das ebenfalls unter unserer Kontrolle steht.|n|nNathaniel Dumah ist mein Kontaktmann im Sägewerk. Sprecht ihn ruhig an, wenn Ihr dort einmal in der Nähe seid.', },
    {'Meldet Euch bei Nathaniel Dumah im Sägewerk des Nordkamms in den Westlichen Pestländern.', },
  },
  [26936] = {
    'Weniger Bumm',
    nil,
    nil,
  },
  [26937] = {
    'Wenn der Tod nicht ausreicht',
    {'Derrington und seine Männer wissen es nicht, aber ich habe die Verseuchung vom Teufelssteinfeld angeordnet. Wir brauchen das Gebiet zum Üben. Wenn wir diesen Krieg für Andorhal gewinnen wollen, müssen wir unsere neueste und vielseitigste Waffe einsetzen:|n|nVal\'kyr.|n|nNehmt diese bezauberte Val\'kyr mit, $N, und tötet den jämmerlichen Abschaum der Allianz, der auf dem Teufelssteinfeld noch zu finden ist. Sobald einer tot ist, wird er von ihr in diese Welt zurückgeholt... als einer von uns.|n|nDie Verlassenen werden nicht aussterben!', },
    {'Tötet 8 Allianzarbeiter auf dem Teufelssteinfeld, damit Eure bezauberte Val\'kyr sie in Verlassene umwandeln kann.', },
  },
  [26938] = {
    'Kampftraining',
    {'Der einzige Lebenszweck einer Val\'kyr ist zu dienen - und diese dient Euch. Ich werde Euch jetzt volle Kontrolle über ihre Fähigkeiten geben, $N.|n|nWenn Ihr in den Außenbereichen des Hofs herumlauft, solltet Ihr einige der Verlassenen finden, die Ihr gerade erschaffen habt. Ich möchte, dass Ihr Eure Val\'kyr benutzt, um mindestens fünf von ihnen einzusammeln. Wenn Ihr das getan habt, nehmt Eure neue Soldatenkolonne, bringt sie in die Teufelssteinscheune und tötet die Bestie darin. Heute werdet Ihr lernen, was es heißt, für die Dunkle Fürstin zu kämpfen.', },
    {'Benutzt die Fähigkeit Eurer bezauberten Val\'kyr, um 5 Gardisten der Verlassenen auf dem Teufelssteinfeld zu mobilisieren. Dann tötet die aufgeschlitzte Monstrosität in der Teufelssteinscheune.', },
  },
  [26939] = {
    'Das G-Team',
    {'Wie seid Ihr hier reingekommen?|n|nAch, ist auch egal. Ich bin Mör\'dok vom G-Team. Wir sind die Besten, die es gibt, und wir sind hier, um Gnomeregan zurückzuerobern!|n|nAls niemand anders ihm helfen konnte, kam der Hochtüftler zu uns und hat uns angeheuert.|n|nAber das kriegen wir nicht alleine hin! Ihr seid jetzt $Gein G-Team-Kommandosoldat:eine G-Team-Kommandosoldatin; ehrenhalber, $N.|n|nNehmt diesen Fallschirm, springt geradeaus in die Halle der Zahnräder und tötet die verflüssigte Ablagerung. Wenn Ihr fertig seid, meldet Euch bei Kommandosoldat Bi\'ay Bäräkuss im westlichen Korridor. Ihr beide werdet Euch mit Sicherheit gut verstehen.', },
    {'Tötet die verflüssigte Ablagerung.', },
  },
  [26940] = {
    'Arkane Geschosse',
    nil,
    nil,
  },
  [26941] = {
    'Das G-Team',
    {'Dieser Mör\'dok ist verrückt, $C. Passt bloß auf, dass Ihr niemals mit diesem Gnom in einem Flugzeug sitzt.|n|nVerstohlenheit ist normalerweise nicht mein Ding, und sie wird ganz bestimmt auch nicht Eures sein. Geht diesen Flur entlang bis zur Abschussrampe und entledigt Euch des Elektrokutor 6000.|n|nDer Elektrokutor ist verantwortlich für die Luftfahrzeuge...|n|n... und ich hasse Luftfahrzeuge. Mich bekommt man in kein Luftfahrzeug!|n|nBenutzt diesen Fallschirm, um anschließend abzuspringen und sprecht mit Kommandosoldat Fähs über Eure nächste Aufgabe.', },
    {'Vernichtet den Elektrokutor 6000.', },
  },
  [26942] = {
    'Das G-Team',
    {'Ich würde mich von Bi\'ay Bäräkuss und Mör\'dok geflissentlich fernhalten - die sind beide nicht ganz dicht.|n|nAber Ihr seid es, also an die Arbeit! Geht diesen Tunnel entlang, bis Ihr zum Tüftlerhof kommt. Hoffentlich wisst Ihr, was zu tun ist, wenn Ihr Robogenieur Thermadraht begegnet.|n|nUnser Anführer, Kommandosoldat Hann Ibal möchte Euch irgendwo da drin treffen. Er wird Euch reich für Eure Bemühungen belohnen.|n|nWahrscheinlich.', },
    {'Tötet Robogenieur Thermadraht.', },
  },
  [26943] = {
    'Trautes Heim, Gnom allein',
    nil,
    {'Sprecht mit Mör\'dok.', },
  },
  [26944] = {
    'Gnomeregan erforschen',
    nil,
    {'Sprecht mit Mör\'dok.', },
  },
  [26945] = {
    'Neue Techniken lernen',
    nil,
    nil,
  },
  [26946] = {
    'Der Vorteil eines Schurken',
    nil,
    nil,
  },
  [26947] = {
    'Ausbildung eines Waldhirten',
    nil,
    nil,
  },
  [26948] = {
    'Mondfeuer',
    nil,
    nil,
  },
  [26949] = {
    'Das richtige Wort',
    nil,
    nil,
  },
  [26950] = {
    'Die dunkle Seite des Lichts',
    {'Der Scharlachrote Kreuzzug lockt junge Krieger mit dem Versprechen an, die Untoten auszulöschen. Was sie nicht sehen, ist die Schattenseite der ganzen Operation.|n|nBefrager Vishas ist der grausamste Mann, den ich je das Missvergnügen hatte zu treffen - er hat aus meiner Mutter Informationen "herausgeholt", als die Seuche zum ersten Mal ausbrach. Der gnadenlose Blutmagier Thalnos bewacht den Friedhof.|n|nDer heilige Zorn der Kreuzfahrer macht sie blind gegenüber ihrer eigenen Dunkelheit. Sorgt dafür, dass sie ihre Scheinheiligkeit bereuen.', },
    {'Tötet Befrager Vishas und Blutmagier Thalnos.', },
  },
  [26951] = {
    'Aufräumen auf der E. Insel',
    {'Der Kampf, um die Echoinseln zurückzuerobern, ist uns teuer zu stehen gekommen. Aber er war es wert, $C. Der große Geist, Bwonsamdi, hat unseren Kriegern geholfen, den widerlichen Zalazane zu besiegen. Er hat unsere Krieger mit den Geistern der Insel beschützt. Aber einige dieser Geister sind im Kampf gefallen. Helft dabei, diesen Geistern die ewige Ruhe zu verschaffen. Ihr werdet auf den Echoinseln herumliegende Masken finden. Sammelt sie auf und bringt sie hierher.', },
    {'Sammelt 8 entzauberte Tikimasken.', },
  },
  [26952] = {
    'Die Stätte der Heiler',
    {'Es gefällt mir nicht, was die Verlassenen hier am Bollwerk anrichten. Bomben, Kessel, sinnloses Blutvergießen... Nichts davon verkörpert das, wofür der Argentumkreuzzug steht. Außerdem gefällt mir die Tatsache nicht, dass sie Söldner wie Euch anheuern.|n|nNichts gegen Euch persönlich, $C. Nur könntet Ihr so viel mehr aus Euch machen. Wenn Ihr Euch eher für die Heilung der Pestländer interessiert als dafür, sie erneut zu verseuchen, dann meldet Euch in der Stätte der Heiler bei Außenagent Kaartish. Die Stätte liegt gen Osten.', },
    {'Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.', },
  },
  [26953] = {
    'Zen\'Kiki, der Druide',
    {'Ich bin Adrine Wergfell, ein Druide des Zirkels des Cenarius. Ihr könnt Euch bei uns für die Heilung dieses Landes, wo einst nur Tod zu finden war, bedanken.|n|nWir nehmen alle auf, die dem Weg des Druiden folgen möchten ungeachtet ihres Volkes, ihrer Fraktion oder ihrem Talent. Hin und wieder bedeutet das die Aufnahme eines Druiden, der mehr Hilfe benötigt als andere.|n|nIch möchte Euch Zen\'Kiki vorstellen. Er ist noch recht neu und lernt immer noch sein Handwerk. Würde es Euch etwas ausmachen, wenn Ihr ihn eine Weile mit hinaus nehmt? Ihr könnt an den verseuchten Tieren, die in der Nähe herumstreunen, kämpfen üben.', },
    {'Tötet mit Zen\'Kiki an Eurer Seite 20 verseuchte Wildtiere. Ihr könnt schwerfällige Seuchenbären, kranke Wölfe, Giftnebellauerer oder Seuchenlauerer töten.|n|nKehrt zur Stätte der Heiler zurück, wenn Ihr von Zen\'Kiki getrennt werdet.', },
  },
  [26954] = {
    'Eine andere Lösung',
    {'Zen\'Kiki muss unter anderem an der Genauigkeit seiner Zauber arbeiten. Ich konnte sogar von hier aus sehen, wie sein Zorn Zauber vollkommen außer Kontrolle geriet. Ich konnte ihn sogar als Markierung nutzen, um Euren Fortschritt in den Wäldern zu verfolgen.|n|nVielleicht können wir Zen\'Kiki anderweitig einsetzen. Nehmt ihn mit hinauf auf den Hügel im Osten. Die kranken Falken, die über diesem Hügel kreisen, müssen vernichtet werden. Bittet Zen\'Kiki, auf diese Falken zu schießen. Selbst, wenn er sie nicht trifft, wird er sie ablenken, damit Ihr sie erledigen könnt.', },
    {'Bringt Zen\'Kiki auf den Hügel östlich der Stätte der Heiler und lasst ihn 7 kranke Falken herbeirufen und töten.', },
  },
  [26955] = {
    'Zen\'Kiki und die Kultisten',
    {'Während Eurer Abwesenheit habe ich versucht, für unseren Freund eine neue Verwendung zu finden. Ich glaube, er könnte eine Zukunft als Heiler haben. Das liegt hauptsächlich daran, dass man mit Heilungszaubern nicht danebenschießen kann.|n|nWie Außenagent Kaartish mir mitteilt, kommen die verseuchten Tiere aus dem Lager der Kultisten im Osten. Ich hoffe, es macht Euch nichts aus, Zen\'Kiki dorthin zu begleiten... Vielleicht kann er in dem Lager dort einige der verseuchten Tiere heilen.', },
    {'Bringt Zen\'Kiki in den Westlichen Pestländern zu Malicias Außenposten, holt 4 gefangene Seuchenbären aus ihren Käfigen und lasst Zen\'Kiki sie heilen.', },
  },
  [26956] = {
    'Die Guten ins Töpfchen...',
    nil,
    {'Entfernt 6 verdorbene Maispflanzen, 4 verfaulte Äpfel und 3 ungesund aussehende Kürbisse von Dalsons Hof in den Westlichen Pestländern.', },
  },
  [26957] = {
    'Der lange Heimweg',
    {'Ich bin in meinem Leben schon an vielen Orten gewesen, $C. Ich habe den Kampf um Ahn\'Qiraj mitgemacht, bin durch das Dunkle Portal in die Scherbenwelt getreten und habe mich den Argentumkreuzfahrern angeschlossen, um die Geißel im kalten Nordend niederzuschlagen.|n|nDoch vor all dem war ich ein Bauer hier in Lordaeron. Jetzt bin ich hier in Herdweiler, nur wenige Meilen von zu Hause weg. Es wird Zeit, dass ich meinen Respekt erweise.|n|nIch bin unterwegs zur Stätte der Heiler bevor ich nach Hause zurückkehre. Ich würde mich freuen, wenn wir uns nach meiner Ankunft dort wiedertreffen.', },
    {'Trefft Euch erneut mit Del Gahrron in den Westlichen Pestländern in der Stätte der Heiler.', },
  },
  [26958] = {
    'Die erste Lektion',
    nil,
    nil,
  },
  [26959] = {
    'Beraubt sie ihrer Verteidigung',
    {'Wir müssen die Verteidigung des Scharlachroten Klosters ausschalten, bevor eine richtige Invastion stattfinden kann. Stoßt bis in ihre Bibliothek vor und bringt Hundemeister Loksey und Arkanist Doan um. Sie halten die mächtige Verteidigung ihrer Kameraden aufrecht.|n|nMeine Magie wird sicherstellen, dass der Rest des Klosters Euch nicht bemerken wird. Sobald sie tot sind, kann ich weitere Verstärkung herbeirufen, die uns bei unserem Angriff unterstützen wird.|n|nWir müssen erfolgreich sein, $N. Die Dunkle Fürstin wird ein Versagen nicht im Mindesten tolerieren.', },
    {'Tötet Hundemeister Loksey und Arkanist Doan.', },
  },
  [26960] = {
    'Mein Sohn, der Prinz',
    {'Mein Sohn musste in seinem kurzen Leben bisher schon viele Bürden schultern und ich fürchte, er wird noch mehr Verantwortung übernehmen müssen.|n|nEr wird nie lernen, ein Anführer zu sein, wenn er sich nur in der Burg aufhält, doch ich hasse es, ihn ohne Begleitung hinauszuschicken.|n|n$N, Eure Taten in der Zeit nach dem Kataklysmus sind bereits legendär. Ihr wärt bestimmt $Gein ausgezeichneter Mentor:eine ausgezeichnete Mentorin; für den jungen Prinz Anduin.|n|nBitte, stellt Euch ihm vor. Es gibt dringende Geschäfte für die Stadt, die ihr beide für mich wahrnehmen könnt.', },
    {'Stellt Euch in Burg Sturmwind Prinz Anduin vor. Sprecht mit König Wrynn, wenn Ihr Euch bekannt gemacht habt.', },
  },
  [26961] = {
    'Götzen sammeln',
    {'Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, fanden wir eine große Anzahl merkwürdiger, verzierter Götzen Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt! Und diese Götzen haben eine seltsame Wirkung auf die Troggs. Sie verfallen dadurch in Raserei!|n|nBringt mir 8 Götzen - ich möchte sie studieren, und ich will sie nicht mehr in den Händen der Troggs sehen! Ihr könnt die Götzen bei den Troggs finden, die die Stätte heimsuchen.', },
    {'Bringt Magmar Todesstreich an der Eisenband Ausgrabungsstätte 8 verzierte Steingötzen.', },
  },
  [26962] = {
    'Beraubt sie ihres Angriffs',
    {'Wie Ihr seht, $N, ist unser erster Angriff auf die Waffenkammer nicht wie geplant verlaufen. Wir hatten bereits den nahegelegenen Hof eingenommen, da tauchte der Scharlachrote Champion Herod auf.|n|nWir müssen unseren Angriff fortsetzen. Der Scharlachrote Kreuzzug darf hier niemals wieder Krieger ausbilden, geschweige denn, einen Angriff auf Unterstadt starten.|n|nEure Aufgabe ist wohl klar. Nieder mit dem Scharlachroten Held.', },
    {'Tötet Herod.', },
  },
  [26963] = {
    'Verfeinerung Eurer Schüsse',
    nil,
    nil,
  },
  [26964] = {
    'Auf Befehl des Kriegshäuptlings: Der Silberwald!',
    {'Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald zu melden.|n|nMehr denn je wird Eure Hilfe benötigt, um die Heimsuchung durch unsere Feinde in dieser Region zu beenden und den Hafen von Gilneas zu erobern!|n|nIhr müsst nach Süden durch Tirisfal reisen und Euch in den Silberwald begeben, um die Kommandozentrale der Verlassenen zu erreichen. Folgt der Straße im Silberwald nach Süden, bis Ihr die Kommandozentrale der Verlassenen erreicht.|n|nVorwärts, $GBruder:Schwester;! Das Schicksal ruft!', },
    {'Meldet Euch bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald.', },
  },
  [26965] = {
    'Der Kriegshäuptling kommt',
    {'Ihr kommt gerade rechtzeitig, $Nnub. Ihr heißt doch $Nnub, stimmt\'s?|n|n<Großexekutor Mortuus betrachtet ein Blatt Papier.>|n|nJa, das steht hier in den Papieren: "$Nnub".|n|n<Großexekutor Mortuus zeigt auf dem Blatt Papier auf Euren Namen.>|n|nWo war ich noch gleich? Ach ja, Ihr kommt gerade rechtzeitig! Der Kriegshäuptling müsste jeden Moment hier eintreffen, um sich mit unserer Anführerin und Retterin höchstpersönlich zu treffen - der Dunklen Fürstin. Wartet einfach ab und benehmt Euch anständig. Ich bin davon überzeugt, dass wir alle Belobigungen bekommen, wenn diese Kundgebung vorbei ist!', },
    {'Wartet auf die Ankunft von Kriegshäuptling Garrosh Höllschrei.', },
  },
  [26966] = {
    'Die Macht des Lichts',
    nil,
    nil,
  },
  [26967] = {
    'Der Kampf um das Scharlachrote Kloster',
    {'Blicket auf die Macht der Verlassenen! Der unaufhaltsame Wille der Dunklen Fürstin durchfließt unsere Körper!|n|nDie meisten der verbliebenen Truppen des Kreuzzugs sind geflohen. Einige leisten allerdings immer noch Widerstand.|n|nIhr habt eine wichtige Rolle beim Erfolg dieser Kampagne gespielt. Sylvanas lässt Euch die Ehre zuteilwerden, ihre letzten noch verbleibenden Feinde zu töten, $N.|n|nLasst keine Gnade walten.', },
    {'Tötet den Scharlachroten Kommandant Mograine und Hochinquisitorin Weißsträhne.', },
  },
  [26968] = {
    'Arkane Geschosse',
    nil,
    nil,
  },
  [26969] = {
    'Urtümlicher Schlag',
    nil,
    nil,
  },
  [26970] = {
    'Das richtige Wort',
    nil,
    nil,
  },
  [26971] = {
    'Die Bindung',
    {'Ein Geräusch in der Hauptkammer des Tempels erregt Eure Aufmerksamkeit. Ihr hört ein wohlbekanntes Lachen... Lorthuna. Sie ist zurückgekommen, um das Ritual zu unterbrechen - Ihr müsst sie aufhalten!', },
    {'Tötet Hohepriesterin Lorthuna.', },
  },
  [26972] = {
    'Die dunkle Seite des Lichts',
    {'Ich habe mich dem Scharlachroten Kreuzzug als junger Paladin voller Eifer angeschlossen, um das Böse aus der Welt zu tilgen. Wie wenig wusste ich doch über die dunkle Wahrheit dieser Fanatiker.|n|nBefrager Vishas und Blutmagier Thalnos überwachen diesen Friedhof. Es bereitet ihnen großes Vergnügen, neue Rekruten endlos zu quälen, um sicherzustellen, dass sie \'rein\' sind. Das ist eine Beleidigung des Lichts, $C!|n|nIch kann nicht länger Teil dieser verdorbenen Organisation sein. Ihr müsst sie beide töten, damit andere nie wieder die Qualen erdulden müssen, die ich ertragen musste.', },
    {'Tötet Befrager Vishas und Blutmagier Thalnos.', },
  },
  [26973] = {
    'Der einzig wahre Weg',
    {'Ich glaube, dass die Wurzel der Verderbnis des Kreuzzugs hier zu finden ist. Arkanist Doan überwacht die Bibliothek und lehrt viele junge Rekruten, wie man mit den arkanen Künsten umgeht.|n|nDas Licht ist der einzig wahre Weg! Ihr müsst ihn töten, $C, und diese glorreiche Bewegung rehabilitieren!|n|n<Josef der Erweckte bewegt sich unruhig.>|n|nIhr werdet Euch auch Lokseys entledigen müssen. Seine Hunde scheinen etwas gegen unsere noble Absicht zu haben.', },
    {'Tötet Hundemeister Loksey und Arkanist Doan.', },
  },
  [26974] = {
    'Der falsche Champion',
    {'Wir...wir...wir mussten sie töten! Sie waren hinter uns her!|n|nIhr glaubt mir doch, nicht wahr, $N?|n|nHerod ist nicht der wahre Champion des Scharlachroten Kreuzzugs. Ich bin es! Er hat das, was rechtmäßig mir gehört, an sich gerissen!|n|nIhr solltet ihn töten. Er ist...eine Bedrohung! Er bildet Soldaten aus, die jeden töten und nicht nur die Untoten.|n|nIch werde Euch fürstlich belohnen...', },
    {'Tötet Herod.', },
  },
  [26975] = {
    'Die Flotte zusammenrufen',
    {'Ich rufe eine Kriegsflotte zusammen, um das Schattenhochland anzugreifen und den Lakaien von Todesschwinge ihr Ende zu bereiten.|n|nMeine Soldaten sind bereit, aber die Vorbereitungen der Flotte verzögern sich. Meine Männer an den Docks brauchen Inspiration und Motivation. Ein Besuch des Prinzen sollte sie aufmuntern und ihnen erneut die glorreiche Zukunft vor Augen führen, für die sie kämpfen.|n|nGeht mit Prinz Anduin zu den Docks und sprecht mit Nachschuboffizier Graves. Ich möchte, dass Anduin sieht, wie ein geborener Anführer mit der Situation umgeht.', },
    {'Begleitet Prinz Anduin zu den Docks in Sturmwind und sprecht mit Nachschuboffizier Graves. Wenn Ihr und der Prinz Euch aus den Augen verliert, findet Ihr ihn im Thronzimmer von Sturmwind.', },
  },
  [26976] = {
    'Der Kampf um das Scharlachrote Kloster',
    {'Oh, schön, Euch wiederzusehen, $N! Ich fürchte, ich brauche Eure Hilfe.|n|nWisst Ihr, Mograine ist hier der Befehlshabende zusammen mit Hochinquisitorin Weißsträhne. Sie haben versucht, mir einzureden, dass ich eigentlich nicht der neue Scharlachrote Champion bin. Die Jungs und ich finden das gar nicht gut.|n|nWir werden jetzt das Scharlachrote Kloster selbst übernehmen und die Ordnung so wieder herstellen, wie sie immer hätte sein sollen - mit mir an der Spitze! Ich werde mich der Verlassenen und der Geißel endgültig entledigen.|n|nHelft Ihr einem alten Freund?', },
    {'Tötet den Scharlachroten Kommandant Mograine und Hochinquisitorin Weißsträhne.', },
  },
  [26977] = {
    'Untersuchung im Zwielicht',
    {'Die Verräterischen Taten des Schattenhammers in den letzten Monaten haben die Stadt in Aufruhr versetzt. Sie haben es auf die Ängste der Bauern abgesehen und korrumpieren unsere wichtigsten Bürger. Wir müssen herausfinden, wie tief diese Verschwörung bereits sitzt.|n|nIch habe Major Samuelson von der Stadtwache von Sturmwind beauftragt, eine Untersuchung zu leiten. Er ist hier im Thronraum. Seht, ob Ihr ihn bei seinen Bemühungen unterstützen könnt.', },
    {'Sprecht in Burg Sturmwind mit Major Samuelson.', },
  },
  [26978] = {
    'Wer braucht Kessel?',
    {'Habt Ihr den Zustand vom Teufelssteinfeld gesehen? Die Streitkräfte der Allianz aus Andorhal haben das Gebiet übernommen und benutzen es, um...um...FELDFRÜCHTE anzubauen!|n|nDa gefiel es mir fast schon besser, als die Geißel das Gebiet noch besetzt hielt. Wenigstens hatten sie so viel Verstand, einen riesigen Seuchenkessel mitten aufs Feld zu stellen.|n|nWir werden uns den Hof von diesen Menschen zurückholen, $N. Nehmt diese Fässer und stellt sie an Schlüsselpositionen um das Feld herum auf. Ich werde hier am Bollwerk warten.', },
    {'Stellt Zitters Seuchenfässer in der Nähe der Windmühle, bei den Getreidesilos, am Farmhaus und bei der Scheune am Teufelssteinfeld auf.', },
  },
  [26979] = {
    'Merkwürdige neue Gesichter',
    {'Jetzt, da Teufelsstein uns gehört, können wir seine Äcker - und alle Leichen, die wir finden - für unsere Zwecke nutzen. Ich habe von oben den Befehl erhalten, dass Ihr dabei helfen sollt.|n|nVielleicht habt Ihr Lindsay Rabensonn bereits auf dem Schlachtfeld bei Andorhal kennengelernt. Ich habe sie noch nie getroffen, aber sie scheint einige hohe Tiere als Freunde zu haben, denn sie übernimmt das Kommando hier in Teufelsstein. Ihr sollt sie bei dem niedergebrannten Scharlachroten Lager treffen, das ihr vor Kurzem ausspioniert habt.', },
    {'Meldet Euch in den Westlichen Pestländern am Niedergebrannten Außenposten bei Lindsay Rabensonn.', },
  },
  [26980] = {
    'Schnellschalts Station',
    {'Ihr habt hier gute Arbeit geleistet, $N. Euch jetzt zu bitten, Sandsäcke zu schleppen, wäre die reine Verschwendung. Um ehrlich zu sein, schicke ich Euch lieber dahin, wo Eure Fähigkeiten gebraucht werden.|n|nWir haben im Marschengebiet weiter nördlich einen kleinen Außenposten. Schnellschalt ist der Gnom, der ihn gebaut hat, aber Ihr solltet mit Shilah Fliesmeißel sprechen und ihr bei Angelegenheiten für Eisenschmiede helfen.|n|nIch gebe zu, sie sieht echt gut aus... aber ich würde nicht den Fehler machen, mir bei ihr irgendwelche Freiheiten herauszunehmen! Die Familie heißt nicht umsonst Fliesmeißel.', },
    {'Sprecht an der Station Schnellschalt nördlich vom Hafen von Menethil mit Shilah Fliesmeißel.', },
  },
  [26981] = {
    'Whelgars Zuflucht',
    {'Ausgrabungsleiter Whelgar hat südöstlich von hier in diesen Bergen seit geraumer Zeit die Ausgrabungen geleitet. Früher einmal hatte er Probleme mit Raptoren, aber in letzter Zeit hatte sich die Lage gebessert.|n|nVor ein paar Tagen haben wir nun erfahren, dass er die ganze Ausgrabungsstätte evakuieren musste. Ich weiß nicht, was dort vor sich geht, aber ich kann mir nicht vorstellen, dass der Kataklysmus einen Steinbruch sicherer gemacht hat als vorher.|n|nDort arbeiten gute Zwerge, $N. Würdet Ihr hingehen und nachsehen, was dort los ist und vielleicht auch helfen?', },
    {'Sprecht bei Whelgars Zuflucht südöstlich der Station Schnellschalt mit Ausgrabungsleiter Whelgar.', },
  },
  [26982] = {
    'Das Scharlachrote Kloster',
    {'Das Kloster in Tirisfal, das die Scharlachroten Kreuzfahrer jetzt besetzt halten, war früher einmal die Ausbildungsstätte für unsere Paladine. Jetzt lauern dort die Verlassenen aus Unterstadt und der Kreuzzug verhindert, dass wir es für die Ausbildung der Soldaten nutzen, die wir so dringend benötigen, um mit den Verlassenen fertigzuwerden.|n|nHört zu, ich traue ihm zwar nicht über den Weg, aber Josef der Erweckte wartet auf dem Friedhof. Geht und sprecht mit ihm - obwohl er ein Kreuzfahrer ist, sagt er, dass er sich gegen sie auflehnt und uns die Gelegenheit gibt, das zurückzuholen, was uns gehört.', },
    {'Besucht Josef den Erweckten.', },
  },
  [26983] = {
    'Gerade nah genug',
    {'Täuscht Euch nicht - es gibt hier noch viel zu tun! Dennoch müssen wir auch dort gegen die Verlassenen zurückschlagen, wo wir sie empfindlich treffen können. Das Scharlachrote Kloster in Tirisfal liegt in perfekter Entfernung zu Unterstadt und Brill.|n|nMeldet Euch bei Josef dem Erweckten in der Bibliothek. Er ist ein aufständischer Kreuzfahrer, der uns vielleicht dabei helfen kann, das Kloster als unsere Basis für alle Operationen in dem Gebiet zu übernehmen. Wenn Ihr schon dabei seid, könnt Ihr auch gleich Arkanist Doan eliminieren, einen ihrer mächtigsten Magier.', },
    {'Besucht Josef den Erweckten.', },
  },
  [26984] = {
    'Ein alter, verrückter Freund',
    {'Josef der Wahnsinnige war hier einer meiner guten Freunde, bevor er sich dem Scharlachroten Kreuzzug im Scharlachroten Kloster in Tirisfal anschloss. Ich hörte, dass er in der Waffenkammer dort ist und einen lächerlichen Versuch unternimmt, Herods Position als Scharlachroter Champion zu übernehmen.|n|nEs ist reiner Selbstmord, Herod so herauszufordern! Geht dort hinauf und versucht, ihm das auszureden.', },
    {'Besucht Josef den Wahnsinnigen.', },
  },
  [26985] = {
    'Wahnsinn gegen Irrsinn ausspielen',
    {'Unsere frisch verstärkten Streitkräfte kommen mit der Situation hier für eine Weile ohne Euch zurecht. Ich habe Berichte erhalten, dass Josef der Irrsinnige, eine früherer Offizier des Scharlachroten Kreuzzugs, sich im Scharlachroten Kloster aufhält und mit seiner Gruppe Abtrünniger gegen den Scharlachroten Kommandanten Mograine losschlagen will.|n|nDas ist eine ausgezeichnete Gelegenheit. Geht dort hin und helft ihm bei seinem irrsinnigen Vorhaben. Vielleicht können wir dann das Kloster als Festung genau auf der Türschwelle von Sylvanas benutzen.', },
    {'Besucht Josef den Rasenden.', },
  },
  [26986] = {
    'In das Scharlachrote Kloster',
    nil,
    nil,
  },
  [26987] = {
    'Der rechte Weg',
    {'Meine Leute sind generell nicht sehr von den arkanen Künsten, die von anderen Völkern missbraucht werden, angetan. Glücklicherweise sind wir weit von den Zauberen in der Bücherei des Scharlachroten Klosters entfernt, doch ihre Fähigkeit, sich über die materielle Welt hinwegzusetzen, bereitet mir Sorgen und stellt letztendlich eine Gefahr für das Überleben meines Stammes dar.|n|nReist weit nach Westen zur Bücherei des Klosters und sprecht dort mit der dunklen Waldläuferin Velonara. Ihre Streitkräfte stehen schon kurz davor Arkanist Doan, den führenden Magus des Kreuzzugs, höchstpersönlich anzugreifen.', },
    {'Sprecht mit der dunklen Waldläuferin Velonara.', },
  },
  [26988] = {
    'Die Sache in Schwung bringen',
    {'Ich warte auf einige sehr mächtige Reagenzien, die ich vor Kurzem aus Unterstadt bestellt habe. Wie ich höre, verzögert sich die Lieferung, weil die Kreuzfahrer des Scharlachroten Klosters den Weg versperren. Der Scharlachrote Champion Herod ist wahrscheinlich für diese Unannehmlichkeit verantwortlich.|n|nBitte geht und sprecht mit der dunklen Waldläuferin Velonara in der Waffenkammer des Scharlachroten Klosters. Sie wird sich um Herod kümmern, was bedeutet, dass meine Lieferung sicher ankommt!', },
    {'Besucht die dunkle Waldläuferin Velonara.', },
  },
  [26989] = {
    'Die Gilnearische Befreiungsfront',
    {'Der Kampf um die Region tobt immer noch, $Nnub. Obwohl wir die Verteidiger von Gilneas vernichtend geschlagen und Gilneas für die Horde eingenommen haben, ist es einer kleinen Gruppe Rebellen gelungen, zu entkommen. Die "Gilnearische Befreiungsfront" - wie sie sich selbst nennen - ergreift jede Gelegenheit, unsere Truppen draußen anzugreifen. Den Rebellen sind einige kleinere Siege gelungen und jetzt werden sie bei ihren Angriffen immer dreister! Es ist an der Zeit, zurückzuschlagen, $Nnub.|n|nGeht nach Süden in die Wildnis von Silberwald und tötet jeden Rebellen, dem Ihr begegnet.', },
    {'Tötet 10 Worgenrenegaten.', },
  },
  [26990] = {
    'Wasser haben die vor?',
    {'Anscheinend arbeiten die Sandwütertrolle mit dem Schattenhammer zusammen.|n|nDoch ohne Belang. Diese üble Hexe wird ihr Monster nicht in MEINE Stadt schicken.|n|nKommt, ihr Tapferen! Wir werden den Sand mit ihrem Blut tränken und siegreich heimkehren. Berichtet Hamuul Runentotem von den Vorfällen hier, wenn wir zurückgekehrt sind. Ich muss mich um die Rückkehr der Bürgerschaft, Reparaturen und dergleichen kümmern.', },
    {'Tötet Kai\'ju Gahz\'rilla und erstattet Hamuul Runentotem in Donnerfels Bericht.', },
  },
  [26991] = {
    'Feinde vor den Toren',
    {'Manchmal müssen wir die Notwendigkeit, unsere Verbündeten zu beschützen, anerkennen, damit sie uns beschützen können. Dies ist eine solche Gelegenheit, <Volk>.|n|nReist zum Scharlachroten Kloster in der Nähe von Unterstadt in Tirisfal. Sobald Ihr dort eintrefft, geht zur Kathedrale und sprecht mit der dunklen Waldläuferin Velonara. Sie führt den letzten Schlag gegen den Kreuzzug dort und es würde uns allen sehr zum Vorteil gereichen, wenn wir sicherstellen, dass unsere untoten Verbündeten das Kloster übernehmen, bevor die Kreuzfahrer eine Chance haben, ihre Hauptstadt anzugreifen.', },
    {'Findet die dunkle Waldläuferin Velonara.', },
  },
  [26992] = {
    'Schmerz im Überfluss',
    {'Zweifellos habt Ihr von dem Vorfall gehört, der sich am Zornestor in Nordend abgespielt hat, nicht wahr? Wegen dieser unglückseligen Vorkommnisse ist es uns strengstens verboten, den Erregerstamm der todbringenden Krankheit, den wir endlich perfektioniert hatten, zu verwenden. Jetzt gibt es Regeln und Vorschriften und anderen Unsinn!|n|nMan hat uns eine entschärfte Version der perfekten Krankheit gegeben und erwartet nun, dass wir daraus eine Waffe basteln.|n|nWenn ich diesen Mist zum Funktionieren bringen soll, dann brauche ich einige Taschen voll mit wildem Verdammniskraut. Ihr findet es überall im Silberwald.', },
    {'Sammelt 8-mal Wildes Verdammniskraut.', },
  },
  [26993] = {
    'Kompendium der Gefallenen',
    {'Keine Angst, ich diene keinem Herrn, <Volk>. In diesen Hallen liegt ein Buch, genannt Kompendium der Gefallenen. Es enthält Unmengen von Forschungsergebnissen, die der Scharlachrote Kreuzzug im Laufe der Jahre über meinesgleichen zusammengetragen hat.|n|nEinfach gesagt möchte ich, dass Ihr es findet und zu mir zurück bringt, ohne Fragen zu stellen.', },
    {'Findet das Kompendium der Gefallenen.', },
  },
  [26994] = {
    'Ohne Sinn und Verstand',
    {'Wie ich höre, möchte Joseph der Wahnsinnige, dass Ihr Herod tötet. Wenn Ihr schon dabei seid, warum bringt Ihr dann auch nicht gleich ihre besten Soldaten um? Ich werde Euch für Eure Arbeit gut bezahlen.|n|nZerbrecht Euch über das \'Warum\' nicht den Kopf, nur über das \'Wie\'.', },
    {'Tötet 3 scharlachrote Myrmidonen, 3 scharlachrote Beschützer, 3 scharlachrote Gardisten und 3 scharlachrote Rufer.', },
  },
  [26995] = {
    'Innereien und Blut',
    {'Wenn wir diese neue Krankheit in die Gänge bringen wollen, brauchen wir saubere Tierinnereien. Das Problem ist, dass saubere Tierinnereien im Silberwald ausgesprochen selten sind. Die meisten Tiere sind von Krankheiten befallen und haben daher nur kranke Innereien.|n|nDurchsucht das Waldgebiet östlich von hier nach Worgs und ergrauten Bären. Tötet nur die, die nicht von Krankheiten befallen sind und reißt ihnen die Innereien heraus. Bringt mir so viele saubere Eingeweide, wie Ihr in Euren Rucksack stopfen könnt.', },
    {'Findet 6 "saubere" Tierinnereien.', },
  },
  [26996] = {
    'Genau vor ihren Nasen',
    {'In dem rechten Seitenraum der verfluchten Kathedrale ist an der Wand eine Fackel. Bewegt sie und eine Geheimtür wird sich öffnen. Dahinter befindet sich Hochinquisitor Schönufer. Er ist jetzt ein Untoter.|n|nJemand muss ihn erledigen. Wenn möglich, tötet ihn in seinem Zimmer. Ich ziehe es vor, wenn die Kreuzfahrer ihn nicht sehen. Ihr kennt das ja - tötet ihn und ich gebe Euch eine Belohnung. Wir müssen nichts weiter sagen.', },
    {'Tötet Hochinquisitor Schönufer..', },
  },
  [26997] = {
    'Die üblichen Verdächtigen',
    {'<Samuelson kratzt sich gedankenverloren das Kinn.>|n|nMeine Untersuchungen haben ergeben, ähm, es ist möglich, dass sich unter den Dockarbeitern von Sturmwind Ärger zusammenbraut. Durchtriebene Bande. Ich traue denen nicht!|n|nIhr solltet dahin gehen und alles mal ordentlich auf den Kopf stellen. Fühlt diesen Hafenarbeitern auf den Zahn. Das sollte Euch eine Weile beschäftigen.|n|nGeht und eliminiert diese Ungläubigen des Schattenhammers!', },
    {'Fühlt im Hafen von Sturmwind 6 Dockarbeitern von Sturmwind auf den Zahn.', },
  },
  [26998] = {
    'Den Erfolg fortsetzen',
    {'Das Gebräu ist endlich fertig, aber bevor ich diesem Erregerstamm mein Gütesiegel verleihe, müssen wir einen Feldversuch unternehmen.|n|nSprecht hier in der Kommandozentrale mit Fledermausführer Madenhauch und verschafft Euch eine Fledermaus. Die Fledermaus bringt Euch nach Osten zu den Morgeninseln auf der anderen Seite des Lordameresees, mitten ins Herz der Verderbnis – zu den Höhlen der Murlocs der Finsterflossen.|n|nBenutzt dieses Gebräu gegen die Murlocs und berichtet mir über die Ergebnisse.|n|nDie Ergebnisse sollten natürlich so aussehen, dass Ihr sie alle wie befohlen getötet habt!', },
    {'Tötet 50 Murlocs der Finsterflossen.', },
  },
  [26999] = {
    'Eine neue Ära für die Pestländer',
    {'Die Geißel hat die Macht über dieses Gebiet verloren. Wir, die Lebenden, übernehmen Lordaeron wieder.|n|nWir haben bereits große Fortschritte gemacht, wie Ihr gesehen habt. Die Erde erblüht, die Bäume wachsen immer höher und sind grün und die Tierwelt kehrt langsam zurück. Dennoch sind eine Handvoll Untote zurückgeblieben.|n|nDie Bäume und das Gras gedeihen, aber die Tiere haben Schwierigkeiten. Etwas hindert sie an ihrer Heilung und ich gedenke herauszufinden, was das ist. Bringt mir Proben von den verseuchten Tieren, damit ich sie mir genauer ansehen kann.', },
    {'Sammelt Proben von 4 Seuchenlauerern, 4 Giftnebellauerern, 4 schwerfälligen Seuchenbären und 4 kranken Wölfen.', },
  },
  [27000] = {
    'Komm, hol das Lasso raus',
    {'Ah, schön wieder auf dem Nordkamm zu sein! Ich habe mein Sägewerk, meine hübsche Frau, meinen quietschfidelen kleinen Jungen... Ich habe mich sogar dem Argentumkreuzzug angeschlossen. Wir werden Tirions Streitkräfte mit Holz versorgen.|n|nMeine Holzfäller waren ausgesprochen produktiv... bis die Spinnen kamen. Jetzt weigern sie sich, tiefer in den Wald zu gehen.|n|nVielleicht könntet Ihr mir helfen. Schwingt Euch auf eins meiner Pferde und jagt den Spinnen Angst ein. Vielleicht können wir Blutvergießen vermeiden und sie einfach fortjagen.', },
    {'Steigt am Sägewerk des Nordkamms auf einen Herdweiler Mustang und benutzt seine Fähigkeit \'Wiehern\', um 25 Nordkammspinnen Angst einzujagen.', },
  },
  [27001] = {
    'Hier ist WoW (Wald ohne Wildspinnen)',
    {'Der Hochlord war so großzügig, einige seiner Rekruten zu entsenden, damit sie uns hier am Sägewerk unterstützen. Mit Eurer Reitkunst und ihren Kampfkünsten können wir uns dieses Spinnenproblems mit Leichtigkeit entledigen.|n|nSteigt wieder auf den Mustang und macht den Spinnen Angst. Diesmal müsst Ihr sie aber bis zum Sägewerk vor Euch hertreiben. Die Rekruten aus Herdweiler können sich dann hier der Dinge annehmen.', },
    {'Besteigt am Sägewerk des Nordkamms einen Herdweiler Mustang und benutzt seine Fähigkeit \'Wiehern\', um 10 Nordkammspinnen zu den Rekruten von Herdweiler an der Nordkamm Sägemühle zu treiben. Ihr könnt mehrere Spinnen auf einmal zusammentreiben.', },
  },
  [27002] = {
    'Eine Audienz mit dem Hochlord.',
    {'Oh, bevor Ihr geht, $N... Ich habe eine Nachricht für Euch. Jemand in Herdweiler möchte Euch gerne kennenlernen. Er sagte, dass er bereits einige Male über Euren Namen gestolpert ist.|n|nIhr könnt Euch glücklich schätzen, $N. Nicht jeder bekommt eine persönliche Audienz mit Hochlord Tirion Fordring.|n|nOh - und Ihr dürft gerne einen meiner Mustangs für den Ritt dorthin nehmen. Sie sind die schnellsten, die man für Geld kaufen kann.', },
    {'Meldet Euch bei Hochlord Tirion Fordring in Herdweiler in den Westlichen Pestländern.', },
  },
  [27003] = {
    'Leichtverdientes Geld',
    {'Wen haben wir denn da!|n|nWie auch immer Ihr hergekommen seid, ich bin so froh, dass Ihr hier seid!|n|nMeine Freunde hier würden es nie zugeben, aber wir können wirklich Hilfe gebrauchen.|n|nDie uralte Region von Uldum ist freigelegt worden! Dort gibt es Schätze, die Eure kühnsten Träume übertreffen, und man kann sie einfach mitnehmen!|n|nDas Einzige, was wir brauchen, ist eine kleine Eskorte, bei den ganzen Banditen und so...|n|nIhr werdet uns begleiten, oder?|n|nIhr dürft auch so viele Schätze mitnehmen, wie Ihr tragen könnt!', },
    {'Begleitet Adarrahs Karawane hinein nach Uldum.', },
  },
  [27004] = {
    'Zwielichtpläne',
    {'Wir sind hierhergekommen, um Gerüchten über ein Artefakt der Titanen am Tor der Meister gen Südwesten nachzugehen.|n|nEiner dieser Kultisten vom Schattenhammer muss doch die Pläne für das, was sie hier vorhaben, bei sich haben. Ihr müsst sie für uns holen, $N.|n|nDurchsucht die Kultisten, bis Ihr sie findet.', },
    {'Sammelt die Pläne für das Tor der Meister.', },
  },
  [27005] = {
    'Zwielichtpläne',
    {'Wir sind hierhergekommen, um Gerüchten über ein Artefakt der Titanen am Tor der Meister gen Südwesten nachzugehen.|n|nEiner dieser Kultisten vom Schattenhammer muss doch die Pläne für das, was sie hier vorhaben, bei sich haben. Ihr müsst sie für uns holen, $N.|n|nDurchsucht die Kultisten, bis Ihr sie findet.', },
    {'Sammelt die Pläne für das Tor der Meister.', },
  },
  [27006] = {
    'Überflieger',
    {'Ich hab versucht, die Terrasse zu überfliegen und mir selbst \'n Bild zu machen, aber diese toastfressenden Weicheier ha\'m auf mich geschossen und ich kam nicht dran.|n|nIhr seht so aus, als ob Ihr mit Zügeln umgehen könnt. Warum nehmt Ihr nicht Euer Flugtierchen und fliegt hoch nach Südwesten, mal nachsehen, was der ganze Wirbel soll?', },
    {'Untersucht den mittleren Bereich im hinteren Teil des Tors der Meister.', },
  },
  [27007] = {
    'Stelldichein in den Silbermarschen',
    {'Ausgezeichnete Arbeit, $N. Wir wissen genau, wo der Treffpunkt ist.|n|nDie Oberen Silbermarschen sind ein Quecksilbersumpf östlich von hier. Normalerweise hausen dort Elementare und gelegentlich auch Steintroggs, aber unsere Späher haben in der Region Aktivität des Schattenhammers beobachtet.|n|nMacht Euch auf den Weg dorthin und findet eine Möglichkeit, das Treffen des Schmiedemeisters zu belauschen.', },
    {'Geht zu den Oberen Silbermarschen in Tiefenheim.', },
  },
  [27008] = {
    'Überflieger',
    {'Ich bin ziemlich geschickt im Umgang mit dem fliegenden Teppich. Doch als ich versucht habe, herauszufinden, was diese Kultisten auf der Zwielichtterrasse entdeckt haben, haben sie mich fast vom Himmel geschossen.|n|nIhr seht aus, als wärt auch Ihr ein Meister der Lüfte. Würdet Ihr für mich nach Südwesten fliegen und herausfinden, was sie da ausgegraben haben?', },
    {'Untersucht den mittleren Bereich im hinteren Teil des Tors der Meister.', },
  },
  [27009] = {
    'Der Kältebringer',
    {'Amnennar der Kältebringer regiert die Hügel der Klingenhauer mit dunkelster und mächtiger Geißelmagie. Es ist mir gelungen, eine Öffnung in die Dornen oberhalb seines Machtsitzes zu schlagen, aber seine Zauberkraft verwehrt es mir, einen Angriff zu starten.|n|nWenn Ihr die Dornenspirale hinaufgeht und ihn angreift, wird ihn das ablenken, bis ich ihn angreifen und schwächen kann, damit er seine tödlichen Zauber nicht wirken kann. Wenn er erst geschwächt ist, tötet ihn, ohne Gnade zu zeigen.', },
    {'Tötet Amnennar den Kältebringer.', },
  },
  [27010] = {
    'Untertauchen im Quecksilber',
    {'Die Troggs in Tiefenheim sind genauso feindselig wie die in Azeroth. Dennoch, ihre Anwesenheit könnte für unsere Bemühungen von Vorteil sein.|n|nDie Kisten, die sie benutzen, um in dem Quecksilber herumzufischen, können Euch perfekt tarnen, wenn Ihr in den Marschen auf Tauchstation geht.|n|nBenutzt sie, um das Lager des Schattenhammers am östlichen Ende der Oberen Silbermarschen unentdeckt zu erreichen.', },
    {'Verschafft Euch eine Troggkiste und versteckt Euch darunter. Dann belauscht das Lager des Schattenhammers im Osten.', },
  },
  [27011] = {
    'Rotkieferdiebstahl',
    {'Weiter im Süden findet Ihr Gnolle der Rotkiefer...Neuankömmlinge in diesem Gebiet. Ihr seid wahrscheinlich auf dem Weg hierher an ihnen vorbeigekommen. Nathaniel tut so, als ob sie kein Problem darstellen, aber ich weiß es besser.|n|nIch habe gesehen, wie sie nachts mit unserem Holz weggerannt sind. Ich weiß gar nicht, was sie mit dem Holz vorhaben - sie scheinen keine guten Handwerker zu sein - aber das hält sie nicht davon ab, es zu stehlen. Geht hinunter zu ihren Lagern und stehlt das Holz zurück.', },
    {'Holt aus dem Rotkieferlager in den Westlichen Pestländern 10 Stapel Nordkammholz zurück.', },
  },
  [27012] = {
    'Lösung des Gnollproblems',
    {'Ich habe so meine Zweifel, was die Absichten dieser Gnolle angeht. Bisher haben sie uns noch nicht angegriffen, aber es werden immer mehr und sie scheinen immer ihre Waffen im Anschlag zu haben. Ich bin kein Militärexperte, aber das erscheint mir ein wenig aggressiv.|n|nWenn wir ihnen einige ihrer Waffen wegnehmen, werden sie vielleicht nicht zur Bedrohung für unser Sägewerk. Ich würde mich viel besser fühlen, wenn Ihr dort hinunter geht und einige ihrer Waffen zu mir bringt.', },
    {'Beschafft 6 Rotkieferstäbe und 6 Rotkieferkeulen von den Gnollen der Rotkiefer.', },
  },
  [27013] = {
    'Zu knapp für meinen Geschmack',
    nil,
    nil,
  },
  [27014] = {
    'Geheiligte Notiz',
    {'Gerade war ein Bote hier und hat Euch gesucht, $N. Ich glaube, er wurde von der Priesterlehrerin Seherin Rabenfeder geschickt. Wenn diese Nachricht von der Seherin ist, würde ich sie sofort aufsuchen.', },
    {'Sprecht im Camp Narache mit Seherin Rabenfeder.', },
  },
  [27015] = {
    'Geweihte Notiz',
    nil,
    {'Sprecht im Camp Narache mit Sonnenwandler Helaku.', },
  },
  [27016] = {
    'Die Freuden der Eberjagd',
    {'Versucht, Eure Aufregung zu zügeln, $N, denn Ihr befindet Euch in der Gesellschaft des besten Eberjägers in Azeroth!|n|nIhre Durchtriebenheit, ihre rasende Geschwindigkeit, die extreme Stärke und die widerstandfähigen Bälger... ja, Eber sind nur die Beute der meisterlichsten Jäger. Anfänger brauchen sich gar nicht erst bewerben!|n|nIch wette, Ihr habt noch nie so ein exotisches Tier gejagt. Ich halte jede Wette, dass Ihr meinen Rekord von zehn getöteten Ebern nicht einstellen könnt. Versucht es mit denen an der Ostseite des Loch, aber tut Euch nicht weh, Grünschnabel!', },
    {'Tötet 10 Schlammbaucheber.', },
  },
  [27017] = {
    'Erinnerungen an längst vergangene Zeiten',
    {'Schon komisch, an was man sich so erinnert. Ich habe 16 Stunden am Tag auf den Feldern gearbeitet und an jedem siebten Tag bin ich in das geschäftige Andorhal gegangen, um das, was ich angebaut hatte, zu verkaufen. Es war ein hartes Leben, aber wir kamen zurecht.|n|nDoch ich erinnere mich kaum daran. Wenn ich an die Zeit zurückdenke, fällt mir Glorias Lächeln ein - oder wie Andrea mir aus dem Fenster zugewinkt hat, wenn ich von dem Pflug aufsah.|n|nDer Hof ist etwas östlich von hier, aber ich bin nicht sicher, ob ich schon bereit bin, dorthin zurückzukehren, $N. Ich möchte nur diese Erinnerungen nicht verlieren.', },
    {'Begebt Euch zum Hof in Gahrrons Trauerfeld und sammelt alle Erinnerungsstücke, die Ihr finden könnt.', },
  },
  [27018] = {
    'Der Herold &lt;NYI&gt;',
    nil,
    nil,
  },
  [27019] = {
    'Geißel der Hügel',
    {'Phantastisch! Mein Name ist Belnistrasz und ich danke Euch für meine Rettung. Ich hatte mich schon tot gewähnt... oder schlimmer, als Mahlzeit für dieses von der Geißel befallene Gezücht.|n|nHört mir zu... anstatt einfach wegzulaufen, möchte ich doch uns allen zuliebe versuchen, etwas zu ändern. Könntet Ihr mir dabei helfen? Es ist wahrscheinlich gefährlich, aber irgendjemand muss es ja tun und ich bezweifle ernsthaft, dass noch andere Abenteurer ihren Weg an diesen hoffnungslosen Ort finden werden.', },
    {'Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab.', },
  },
  [27020] = {
    'Die erste Lektion',
    nil,
    nil,
  },
  [27021] = {
    'Der Weg des Jägers',
    nil,
    nil,
  },
  [27022] = {
    'Ausschalten des Götzen',
    {'In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die Stacheleber fungiert; sie... sie verzehren buchstäblich die aus dem Brachland Entführten. Ich kann den Götzen außer Funktion setzen und ihn unbrauchbar machen, aber ich benötige dabei Eure Hilfe. Mein Plan: Begleitet mich zum Götzen. Wenn wir dort angekommen sind, werde ich das Ritual einleiten. Ich werde kaum in der Lage sein, mit Euch zu kommunizieren, geschweige denn, mich zu verteidigen. Schützt mich, während ich den Götzen außer Funktion setze. |n|nSteht Ihr mir bei? Kann ich auf Eure Hilfe zählen, um diesen Gräßlichkeiten ein Ende zu bereiten?', },
    {'Beschützt Belnistrasz.', },
  },
  [27023] = {
    'Der Weg des Sonnenwandlers',
    nil,
    nil,
  },
  [27024] = {
    'Komplizen',
    {'Obwohl Amnennar hier die größte Bedrohung darstellt, ist er beileibe nicht die einzige. Ihr müsst auch seine Leutnants erschlagen, wenn ihre Umklammerung der Niederungen aufhören soll.|n|nNimmersatt bewacht den Anfang der Dornenspirale.|n|nMordesh steht oben auf dem Knochenhaufen und wiegelt die Geißel zu blinder Wut auf.|n|nTuten\'kash befindet sich unter der Erde. Um ihn herauszulocken, müsst Ihr den Gong in der Kammer des Rufers drei Mal schlagen.|n|nViel Glück, tapferer Held.', },
    {'Tötet Nimmersatt, Mordresh Feuerauge und Tuten\'kash.', },
  },
  [27025] = {
    'Disteln im Dickicht',
    {'Es ist die Jahreszeit der Dolchdisteln! Dolchdistelsamen sind für 89%der durch Samen verursachten Verletzungen bei Jägern verantwortlich.|n|nIhr werdet Dolchdistelsamen zum größten Teil in den unteren Waldländern nördlich der Jagdhütte finden. Man findet sie gewöhnlich auf dem Boden bei Bäumen und sie werden Euch stechen und Schmerzen zufügen.|n|nIch würde Euch ja den Rat geben, einen Bogen um sie zu machen, aber ich brauche jemanden, der mir hilft, sie aus Sicherheitsgründen zu entfernen. Bringt mir Dolchdistelsamen, damit andere sich nicht verletzen.', },
    {'Sammelt 6 Dolchdistelsamen.', },
  },
  [27026] = {
    'Alarmstufe: Rotluchs',
    {'Lasst alles stehen und liegen! Es ist mir zu Ohren gekommen, dass in der Nähe der Jagdhütte Rotluchse gesehen wurden. Rotluchse!|n|nIch habe zwar noch nie einen Rotluchs gesehen, aber sie sind bestimmt gefährlich. Sie sind wie Berglöwen oder so ähnlich. Ich will nicht, dass jemand fortgeht, bevor die Gegend nicht gesichert ist.|n|nAußer Euch, heißt das. Ich werde Euch dafür bezahlen, die Gegend zu sichern, $C. Aber lasst Euch nicht in Stücke reißen.', },
    {'Tötet 8 Rotluchse.', },
  },
  [27027] = {
    'Urtümlicher Schlag',
    nil,
    nil,
  },
  [27028] = {
    'Hornissenjagd',
    {'Wir suchen hier immer nach neuem Wild. Daryl mag seine Eber ja lieben, aber der Rest von uns bevorzugt etwas exotischere Dinge.|n|nNun, ich würde niemals behaupten, dass es gut war, den Loch trockenzulegen, aber es gab einen Lichtblick. Der sumpfige Untergrund hat neue Beute hervorgebracht: Hornissen!|n|nUnd obendrein noch riesige Hornissen. Nicht viele Jäger haben sich mit so riesigen Insekten gemessen. Das ist ziemlich neu.|n|nIch möchte gerne, dass Ihr es versucht - ich biete Euch eine Wette an. Bringt mir einige dieser wunderschön glänzenden Flügeln von ihnen und ich bezahle Euch.', },
    {'Erbeutet 6 glasige Hornissenflügel.', },
  },
  [27029] = {
    'Die Geißel heilen',
    {'Viel wirksamer, als eine Welle der Geißel nach der anderen zu töten, wäre es, einen Weg zu finden, wie man lebende Kreaturen davor bewahrt, sich in sie zu verwandeln. Ich habe eine Idee für ein tolles Pulver. Wenn man es einatmet, könnte es den ganzen Prozess unterbinden.|n|nIch benötige verwitterte Hauer von den untoten Stachelebern hier, um dieses Pulver herzustellen. Bringt mir eine ausreichende Menge und wir sind vielleicht in der Lage, das Wachstum der Geißel endgültig aufzuhalten.', },
    {'Besorgt 20 verwitterte Hauer.', },
  },
  [27030] = {
    'Eine Handvoll Fuchsschwänze',
    {'Wir haben in letzter Zeit mehr Füchse hier in den Hügeln gesehen. Sie sind gerissene Wesen. Sie sind ein guter Test für die Fähigkeiten eines Jägers - und sie bringen einen schönen Profit!|n|nWegen ihrer Schwänze, $Gmein Freund:meine Liebe;. Die sind schön und buschig - man kann sie an seinen Gürtel hängen, um Flöhe abzuwehren, oder man kann mit ihnen die Handschuhe eines modebewussten Edelmannes füttern.|n|nAber ich plappere nur daher. Ich bin zwar kein Goblin und die Spannung liegt in der Jagd. Doch wenn Ihr mir ein paar Fuchsschwänze bringt, werde ich Euch gerne dafür bezahlen. Ihr findet die Füchse nördlich der Jagdhütte in den unteren Waldländern.', },
    {'Erbeutet 7 flauschige Fuchsschwänze.', },
  },
  [27031] = {
    'Verrückt nach Flügeln',
    {'Ich habe die Nase von Gyrokoptern voll. Klar, sie erfüllen ihren Zweck, aber seit wann hat das einem Gnom jemals gereicht? Ich will richtig fliegen, mit FLÜGELN!|n|nIch beobachte seit Jahren Vögel und versuche, hinter das Geheimnis zu kommen, wie man eine Maschine baut, die genau wie sie fliegen kann. Dieses elegante Aufschwingen und Herabstoßen, der Wind, der über die Flügel streicht... ahh.|n|nIhr! Ihr könnt mir helfen. Ich brauchte die besten Flugfedern, die ihr auftreiben könnt. Die goldenen Adler, die in der Nähe der Jagdhütte kreisen, wären eine ausgezeichnete Wahl.', },
    {'Besorgt 3 makellose Flugfedern von Goldadlern.', },
  },
  [27032] = {
    'Ein schräger Vogel',
    nil,
    {'Findet den verrosteten Himmelsschreiter in der Eisenschwingenhöhle.', },
  },
  [27033] = {
    'Herz der Himmelsstreiter',
    {'Ihr öffnet die Klappe und findet ein beeindruckendes, mechanisches Gerät, das an einige Kabel, Zahnräder und wer-weiß-was noch angeschlossen ist.|n|nEs lässt sich ohne Schwierigkeiten lösen. Zeit, es zu Bingles zurückzubringen.', },
    {'Bringt Bingles Blastenheimer in der Jagdhütte der Weltenwanderer das supermechanische Robodings.', },
  },
  [27034] = {
    'Er ist in dem Alter',
    {'ich baue den Himmelsschreiter nicht für mich, $N. Ich baue ihn nicht mal für die Gnomwelt. Ich möchte, dass mein Sohn derjenige ist, der ihn fliegt.|n|nIch bin alt und meine Reflexe sind nicht mehr das, was sie mal waren. Aber mein Junge Ando könnte der beste Pilot werden, den Azeroth je gesehen hat, wenn er nur seine Teenager-Launenhaftigkeit ablegen würde!|n|nEr sitzt draußen am See und starrt den ganzen Tag den Himmel an. Irgendetwas bedrückt ihn, aber er weigert sich, mit seinem Vater darüber zu sprechen. Ich bin mit meinem Latein am Ende!|n|nBitte, $N, könntet Ihr nicht mit ihm reden? Sagt ihm, ich brauche ihn, um den Himmelsschreiter zu fliegen.', },
    {'Sprecht mit Ando Blastenheimer auf der Ostseite des Loch.', },
  },
  [27035] = {
    'Stellung beziehen',
    {'Schaut sie Euch an. Der Schattenhammer hat dieses Land ruiniert!|n|nDieser Kult hat diesen Kataklysmus ausgelöst, den Steinwerkdamm zerstört und den ganzen Loch trockengelegt. Und jetzt laufen sie in den Trümmern herum, als ob hier ihr Zuhause wäre!|n|nWenn es in dieser Welt Gerechtigkeit gäbe, würde jemand in ihr Lager marschieren und ihr Artefakt in Stücke brechen. Aber ich bin zu schwach, um auch nur an einen Versuch zu denken.|n|nUnd niemand hat genug Mut dazu! Nicht einmal Ihr! Seht Ihr? Es ist alles so sinnlos...', },
    {'Zerstört den Zwielichtumweltgestalter in der Mitte des Schattenhammerlagers.', },
  },
  [27036] = {
    'Vyrins Rache',
    {'Ihr seid nicht zufällig daran interessiert, es unserem ach so kühnen Kühnen ein wenig heimzuzahlen? Es schmerzt mich, das zu sagen, aber Daryl hat ein gewisses Talent.|n|nVor einem Jahr war ein großer Bär das Ziel der Jagdhütte der Weltenwanderer, aber keiner der Jäger hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Das Einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge.|n|nErlegt den Bären und ich bin mir sicher, dass sogar Daryl mal sprachlos wäre.|n|nAlte Rußtatze, der Bär, hält sich irgendwo in der Nähe seines Baus nördlich von hier auf.', },
    {'Tötet alte Rußtatze und bringt seinen Kopf an Euch.', },
  },
  [27037] = {
    'Vyrins Rache',
    {'Licht! Bringt solche Dinge nicht in die Jagdhütte... das ist unhygienisch, unaussprechlich, un... un... unhygienisch!|n|nBringt es bitte einfach nur raus hier, ja? Niemand will Eure kleine blutige Trophäe sehen, aber wirklich nicht!', },
    {'Bringt den Kopf der alten Rußtatze zu Vyrin Flinkwind in die Jagdhütte der Weltenwanderer.', },
  },
  [27038] = {
    'Fehlende Teile',
    {'<Der Unteroffizier wendet seine Aufmerksamkeit Euch zu.>|n|nHört zu, wenn Ihr helfen wollt, dass alles hier etwas schneller geht, dann haltet mir Flintlocke vom Leib. Eine ganze Ladung Belagerungsmaschinenteile ist verlegt worden und jetzt über das ganze Dock verteilt.|n|nSammelt die fehlenden Teile auf und bringt sie zu Flintlocke, damit er den Bau beenden kann. Er ist auf der anderen Seite der Straße und wartet.', },
    {'Hebt 5 fehlende Teile im Hafen von Sturmwind auf.', },
  },
  [27039] = {
    'Unter Feinden',
    {'Wisst Ihr, warum Mortuus \'nub\' an Euren Namen anhängt, $N? Weil er ein inkompetenter Kriecher ist, der kaum aus seinem übergroßen Helm hervorschauen kann. \'NUB\' ist Eure Bezeichnung. Ihr seid jetzt nämlich Teil des NEUEN UNTERSTÄDTER BATAILLONS.|n|nDoch genug der Witze! Ich habe Todespirscherin Yorick vor zwei Tagen auf eine Überwachungsmission geschickt. Ihr Ziel war es, Informationen über die Gilnearische Befreiungsfront zu sammeln und zurückzukehren. Jetzt habe ich schon drei Tage lang nichts mehr von ihr gehört.|n|nGeht nach Südwesten zum Ivarfeld und sucht nach Yorick, $N.', },
    {'Findet Todespirscherin Yorick auf dem Ivarfeld im Silberwald.', },
  },
  [27040] = {
    'Entschlüsselung leichtgemacht',
    {'Wir haben nicht die Werkzeuge, um diese chiffrierten Pläne zu entschlüsseln. Doch der Schattenhammer hat sie.|n|nWärt Ihr so gut, mit den Plänen dort hinaufzugehen und sie durch die Einweg-Dechiffrierungsmaschine laufen zu lassen?', },
    {'Entschlüsselt 6 Pläne.', },
  },
  [27041] = {
    'Entschlüsselung leichtgemacht',
    {'Wir haben nicht die Werkzeuge, um diese chiffrierten Pläne zu entschlüsseln. Doch der Schattenhammer hat sie.|n|nWärt Ihr so gut, mit den Plänen dort hinaufzugehen und sie durch die Einweg-Dechiffrierungsmaschine laufen zu lassen?', },
    {'Entschlüsselt 6 Pläne.', },
  },
  [27042] = {
    'Mächte des Feuers, des Wassers und der Luft',
    {'Habt Ihr da oben diesen plappernden Idioten gehört? Das ist kein Geringerer als Haethen Kaul, ihr Anführer.|n|nDie Macht hat ihn in den Wahnsinn getrieben. Er entzieht sie den gebundenen Elementaren, was ihn nahezu unbesiegbar macht.|n|nDie einzige Chance, wie Ihr ihn im Kampf besiegen könnt, besteht darin, die Elementare zu töten und jeweils ihren Zauberschutz erlangen. Das sollte Euch vor Haethens Magie beschützen.|n|nNun, zumindest vor einem Großteil davon.', },
    {'Erhaltet den Feuerzauberschutz, Wasserzauberschutz und Windzauberschutz und tötet dann Haethen Kaul.', },
  },
  [27043] = {
    'Mächte des Feuers, des Wassers und der Luft',
    {'Habt Ihr da oben den Mann und sein unaufhörliches Geschrei gehört? Das ist Haethen Kaul, ihr Anführer.|n|nEs ist kein Geheimnis, dass die Macht, die er den gebundenen Elementaren entzieht, ihn in den Wahnsinn getrieben hat. Leider macht sie ihn auch nahezu unbesiegbar.|n|nWenn Ihr gegen ihn kämpfen wollt, müsst Ihr erst die Elementare töten und jeweils ihren Zauberschutz erlangen. Das sollte Euch vor Haethens Magie beschützen.|n|nNun, zumindest vor einem Großteil davon.', },
    {'Erhaltet den Feuerzauberschutz, Wasserzauberschutz und Windzauberschutz und tötet dann Haethen Kaul.', },
  },
  [27044] = {
    'Die Sorgen der Bauern',
    {'Ich möchte noch nicht zur Burg zurückkehren. Würdet Ihr mir bei etwas helfen?|n|nEinige der hiesigen Bauern haben vor Kurzem beim König eine Eingabe gemacht, bei der es um vermisstes Nutzvieh ging. Mein Vater hat versprochen, dass jemand der Sache nachgeht, aber die Stadtwache ist so ausgelastet, dass das Wochen dauern würde.|n|nIch dachte, ich könnte doch helfen! Es wird den Bauern Mut machen, wenn sie sehen, dass jemand sich darum kümmert, besonders, wenn es jemand der königlichen Familie ist. Außerdem geht es ja nur um paar vermisste Kühe. Nichts Gefährliches.|n|nBringt mich hier in der Stadt zu Bauer Wollerton!', },
    {'Begleitet Prinz Anduin zu Bauer Wollerton auf Wollertons Bauernhof in Sturmwind. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.', },
  },
  [27045] = {
    'Lauschangriff',
    {'Der Anführer der Gilnearischen Befreiungsfront, Darius Crowley, hält jetzt schon seit drei Tagen ein Treffen mit einem anderen Worgen in diesem Landhaus ab. Ich bin mir nicht sicher, was da los ist, aber wir müssen in das Haus gelangen und einen guten Platz finden, von dem aus wir sie belauschen können.|n|nJetzt oder nie, <Volk>. Eine zweite Chance werden wir wohl kaum bekommen.|n|nAber falls ich es nicht schaffe, müsst Ihr mir versprechen, zur Kommandozentrale der Verlassenen zurückzukehren und Belmont von unseren Erkenntnissen zu berichten.', },
    {'Betretet das Landhaus auf dem Ivarfeld und sucht oben nach einem geeigneten Versteck. Belauscht dann Lord Darius Crowley.', },
  },
  [27046] = {
    'Bohrende Angst',
    {'Die Tunnelgräber haben den Fels befallen und fressen die ganze Zeit daran; eines Tages wird unser Heim zusammenbrechen. Für jeden, den man tötet, brechen zweimal so viele hervor und wir müssen immer weiterkämpfen. Sie müssen ausgerottet werden.|n|nGeht zu den Bruchtiefen und vernichtet alle Würmer, die Ihr finden könnt.', },
    {'Tötet 10 Schleifwürmer.', },
  },
  [27047] = {
    nil,
    {'Einige der seltensten Kristalle entstehen an den gefährlichsten Orten. In den Bruchtiefen werdet Ihr Painitformationen finden. Das ist viel besser als das Gold, das Eure Rassen so schätzen.|n|nDa Ihr ein fleischliches Wesen von kleinem Wuchs seid, könnt Ihr die Bruchtiefen betreten und Painitpartikel für mich holen. Würdet Ihr Euch dieser Gefahr für mich aussetzen?', },
    {'Holt 10 Painitpartikel.', },
  },
  [27048] = {
    'Untergrundwirtschaft',
    {'Hey! Ich versuche, einige dieser Kristalle zu sammeln. Die Elementare zahlen gut für das Zeug... wenn Ihr mir helft, die ganzen verschiedenen Sorten zu sammeln, bekommt Ihr einen Anteil vom Gewinn.|n|nBenutzt diese Bomben, um Teile aus den größeren Kristallformationen herauszusprengen.|n|nIch hab\' die dumme Angewohnheit, mit Sprengstoff ein wenig zu dick aufzutragen. Nehmt Euch vor dem Rückstoß in Acht.', },
    {'Benutzt Rickets Ticker, um 3 Tiefenalabasterkristalle, 3 Tiefencoelestinkristalle, 3 Tiefenamethystkristalle und 3 Tiefengranatkristalle zu sammeln.', },
  },
  [27049] = {
    'Weicher Fels',
    {'Die Verderbnis der Rubinspanne hat nicht nachgelassen. Zerstört die Fungusungetüme, die unser Land mit ihrem Schmutz besudeln. Wenn sie sich weiterhin erheben, werden wir sie weiterhin vernichten.', },
    {'Tötet 8 Fungusungetüme.', },
  },
  [27050] = {
    'Der Zorn der Pilze',
    {'Etwas auf der Rubinspanne ruft ständig neue, widerliche Gewächse auf dem Felsen hervor. Neue Pilze wachsen und müssen zerstört werden, bevor sie sich noch weiter verbreiten.', },
    {'Zerstört 10 der neu gesprossenen Pilze in der Rubinspanne.', },
  },
  [27051] = {
    'Beharrlichkeit zahlt sich aus',
    {'Die Troggs haben sich nicht zerstreut, nachdem Ihr Glop getötet habt. Seine Diener haben den Wachstumsbeschleuniger gefunden, der zurückgelassen wurde, und säen die Samen der Verderbnis überall auf der Rubinspanne.|n|nBringt sie zur Strecke und findet alles, was vom Wunderwachstumsmittel von Verlok noch übrig ist. Es muss entsorgt werden.', },
    {'Nehmt einen Beutel mit Wunderwachstumsmittel von Verlok von den Verloks auf der Rubinspanne an Euch.', },
  },
  [27052] = {
    'Anhaltendes Zwielicht',
    {'In Tiefenheim gibt es immer noch Zwielichtdrachenreiter. Sie sind versprengt! Besiegt. Dennoch bleiben sie.|n|nSchwingt Euch mit Aeoseras Geschwader in die Lüfte und spürt sie auf. Die Steindrachen warten auf Euch auf der Klippe im Südwesten.|n|nWir werden sie bis auf den letzten vernichten. Im Namen der Steinmutter.', },
    {'Bringt einen Zwielichtdrachenreiter zur Strecke während Ihr auf einem Steindrachen der Kristallschwingen reitet.', },
  },
  [27053] = {
    'Der Kessel von Gahrrons Trauerfeld',
    {'Meine Analyse ist abgeschlossen! Die Verseuchung, die die Tiere hier befallen hat, ist keine Resterkrankung. Nein, sie ist etwas Neues... und ich glaube, ich weiß, was es ist.|n|nDer Kult der Verdammten unterhält einen Seuchenkessel auf einem Hof, der Gahrrons Trauerfeld heißt.|n|nDer Hof ist genau im Südosten von uns, kurz vor den Östlichen Pestländern. Ich brauche eine Probe von diesem Kessel, um meinen Verdacht zu bestätigen.|n|nBeseitigt den Kessellord, der dort zugegen ist, um an seinen Schlüssel zu gelangen. Dann werdet Ihr Zugang zu dem Kessel erhalten und könnt eine Probe für mich entnehmen.', },
    {'Geht zu Gahrrons Trauerfeld in den Westlichen Pestländern. Findet und besiegt den dort anwesenden Kessellord und benutzt seinen Schlüssel, um Zugang zu dem Kessel zu erlangen.', },
  },
  [27054] = {
    'Verzweifelte Taten',
    {'Der Kult der Verdammten unterhält ein kleines Lager im Osten, Malicias Außenposten. Dort trainieren sie außerhalb von Scholomance. Möglicherweise haben wir ihnen schon viel zu lange erlaubt, unkontrolliert dieses Training auszuüben.|n|nWenn Kultisten wirklich diese Seuche benutzen, um die Tierwelt zu infizieren, dann muss diese Infizierung an Malicias Außenposten stattfinden.|n|nAusbilder Malicia leitet den Außenposten. Findet sie, tötet sie und findet heraus, von wem sie ihre Befehle empfängt.', },
    {'Tötet Instrukteurin Malicia und nehmt ihre Befehle für den Kult an Euch.', },
  },
  [27055] = {
    'Krastinovs Schüler',
    {'Laut der Befehle für den Kult soll Seuche aus dem Kessel bei Gahrrons Trauerfeld für ZWEI Zwecke benutzt werden. Der erste dient zur Übung, wie man Krankheiten über die Tiere der Pestländer verbreitet, das kennt Ihr ja bereits.|n|nDer Rest der Seuche wird für düstere Experimente in die Weinende Höhle transportiert, die nördlich von Malicias Außenposen liegt. Schüler der Scholomance verwenden die Seuche, um die Toten zu reanimieren!|n|nDas muss unbedingt aufhören.', },
    {'Tötet in der Weinenden Höhle, die in den Westlichen Pestländern liegt, 2 Schüler Krastinovs, 2 Schläger aus Formfleisch, 2 Reißer aus Formfleisch und 4 unheilige Korpuskel.', },
  },
  [27056] = {
    'Belmonts Bericht',
    {'<Belmont reicht Euch einen versiegelten Umschlag.>|n|nBringt diesen Bericht zu Fürstin Sylvanas Windläufer. Es ist meine Einschätzung der Lage im Silberwald basierend auf Eurer und Yoricks Feldarbeit.|n|nWenn wir diese rebellischen Worgen nicht aufhalten, werden sie uns überrennen! Jetzt ist es Zeit zu handeln!', },
    {'Bringt Belmonts Bericht zu Fürstin Sylvanas Windläufer in der Kommandozentrale der Verlassenen im Silberwald.', },
  },
  [27057] = {
    'Rückkehr zum heimischen Hof',
    {'Sorgfältig verschließt Ihr den Zapfhahn auf dem Bedienfeld und beobachtet, wie das faulige Sekret in die leere Flasche tropft.|n|nJetzt, da Ihr das Gift in Händen haltet, ist es Zeit zu Außenagent Kaartish in die Stätte der Heiler zurückzukehren.', },
    {'Bringt die Gefüllte Flasche: Gahrrons Trauerfeld zu Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.', },
  },
  [27058] = {
    'Die falsche Folge',
    {'Wir müssen den Schattenhammer daran hindern, das Tor zu benutzen. Es gibt nur einen Weg.|n|nGebt die falsche Aktivierungsfolge ein und zerstört es.|n|nHmm, mal sehen. Ja, damit öffnet man das Tor zu den explosiven Tiefen der Feuerlande, der Elementarebene des Feuers. Das sollte funktionieren.', },
    {'Benutzt den Torwächter, um die falsche Aktivierungsfolge einzugeben und so das Tor zu zerstören.', },
  },
  [27059] = {
    'Die falsche Folge',
    {'Wir müssen den Schattenhammer daran hindern, das Tor zu benutzen. Es gibt nur einen Weg.|n|nGebt die falsche Aktivierungsfolge ein und zerstört es.|n|nHmm, mal sehen. Ja, damit öffnet man das Tor zu den explosiven Tiefen der Feuerlande, der Elementarebene des Feuers. Das sollte funktionieren.', },
    {'Benutzt den Torwächter, um die falsche Aktivierungsfolge einzugeben und so das Tor zu zerstören.', },
  },
  [27060] = {
    'Unheilige Kuh',
    {'<Bauer Wollerton versucht, sich zusammenzureißen.>|n|nKühe? Erkundigt Ihr Euch nach dem vermissten Vieh?|n|nNormalerweise lasse ich die Kühe nördlich vom Haus grasen. Ab und zu wird eine weggezaubert. Da bleibt dann nur eine Blutspur zurück. Wer macht denn so was?|n|nIch habe Angst, dieser Spur zu folgen... etwas Krankes geht hier in Sturmwind vor!', },
    {'Begleitet Anduin Wrynn und folgt der Blutspur von Wollertons Bauernhof zum Tatort. Haltet Anduin am Leben. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.', },
  },
  [27061] = {
    'Die Zwielichtwarte',
    {'Der Drache, von dem sie reden, ist Abyssion, $N. Es wird nicht einfach sein, das Fragment von ihm zu erhalten.|n|nTrefft Euch erneut mit Mylra. Sie lenkt ihre Einsätze von der Zwielichtwarte hier in der Nähe aus.|n|nSie wird Euch sagen, was wir als Nächstes tun werden.', },
    {'Sprecht mit Sturmruferin Mylra an der Zwielichtwarte in Tiefenheim.', },
  },
  [27062] = {
    'Lauernde Gefahr',
    {'Die Stacheleber im Hügel der Klingenhauer scheinen sich mit der Geißel zusammengetan zu haben. Das sind düstere Nachrichten für uns, $C. Wir haben genug ernsthafte Probleme damit, uns mit den Grimmtotems auseinanderzusetzen, wir können nicht noch einen Angriff der Geißel überstehen. Begebt Euch in den Hügel der Klingenhauer, der im Osten liegt, und seht, ob Ihr jemanden findet, der Euch dabei hilft, sie aufzuhalten, bevor sie uns hier angreifen.', },
    {'Sucht im Hügel der Klingenhauer nach Hilfe.', },
  },
  [27063] = {
    'Lauernde Gefahr',
    {'Die Geißel ist eine Beleidigung für die Natur. Sie haben es geschafft, die Stacheleber im Hügel der Klingenhauer zu verderben. Jetzt drohen sie sich noch weiter in den Tausend Nadeln auszubreiten und - wie ich fürchte - schlussendlich auch nach Westen nach Feralas. Ihr müsst dorthin gehen und alles tun, um sie festzusetzen. Vielleicht könnt Ihr jemand in dem Gebiet dort finden, der Euch hilft? Die Winde flüstern von einer mächtigen Präsenz in der Gegend.', },
    {'Sucht im Hügel der Klingenhauer nach Hilfe.', },
  },
  [27064] = {
    'Er hält uns hin',
    {'$N, es scheint beinahe so, als ob Samuelson absichtlich unsere Zeit verschwendet. Die Dockarbeiter wissen gar nichts. Was noch wichtiger ist - Sprengstoff aus dem Hafen von Sturmwind ist verschwunden.|n|nWisst Ihr, was ich denke? Ich wette, Samuelson weiß mehr, als er zugibt. Er hat wahrscheinlich eine Spur, den Schattenhammer betreffend, und will die Lorbeeren selbst einheimsen.|n|nWir sollten uns seine Akten im SI:7 Hauptquartier mal ansehen. Bringt mich dorthin, denn ich müsste Einblick in seine Akten bekommen, um herauszufinden, was er wirklich weiß.', },
    {'Begleitet Anduin Wrynn in den dritten Stock des SI:7 Hauptquartiers in der Altstadt von Sturmwind. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.', },
  },
  [27065] = {
    'Die Flotte des Kriegshäuptlings',
    {'Unsere Verstärkung aus Kalimdor ist letzte Nacht eingetroffen. Drei Kanonenboote der Orcs voller Vorräte, Waffen und Soldaten. Drei Kanonenboote der Orcs, die wir an die verdammten Worgen von Blutfang verloren haben.|n|nWie kann eine ganze Orcflotte gegen eine kleine Truppe feindlicher Kämpfer verlieren, die noch nicht einmal Belagerungswaffen besitzen? Diese wichtige Frage werdet Ihr mir beantworten. Sucht Eure Sachen zusammen und meldet Euch bei der orcischen Admiralin Hatchet an der Rückendeckung der Verlassenen, südwestlich von hier.|n|nMacht diesen Orcs Beine, $N.|n|nIch erwarte Euren vollständigen Bericht.', },
    {'Meldet Euch bei Admiralin Hatchet bei der Rückendeckung der Verlassenen im Silberwald.', },
  },
  [27066] = {
    'Das richtige Wort',
    nil,
    nil,
  },
  [27067] = {
    'Mondfeuer',
    nil,
    nil,
  },
  [27068] = {
    'Häuptling Ukorz Sandskalp',
    {'Schaut genau hin, Mann. So läuft das hier, Verrat folgt auf Verrat. Erst trickse ich Euch aus, um das Schwert zu krieg\'n, und dann kommt Häuptling Ukorz und legt mich so richtig aufs Kreuz.|n|nSo is\' das Leben, ja! Oder war es...|n|nNa ja, ich weiß, dass Ihr Mazoga gar nie nich\' leiden konntet. Aber ich weiß, dass Ihr trotzdem macht, worum ich Euch bitte. Tötet ihn für mich. Vergießt noch mehr Blut auf dem Sand und gebt Häuptling Ukorz Sandskalp was alle Sandwüter verdien\'n...einen blutigen Tod.|n|nVielleicht überlasse ich Euch was von mir, auf dem kein Fluch liegt, ja?', },
    {'Tötet Häuptling Ukorz Sandskalp.', },
  },
  [27069] = {
    'Der stählerne Donner',
    nil,
    {'Bergt 5 Seebärenkisten.|n|nFalls Ihr unerwartet Euren orcischen Süßwassermatrosen verlieren solltet, dann sprecht mit Admiralin Hatchet, um einen neuen zu bekommen.', },
  },
  [27070] = {
    'Vergebliche Mühe',
    nil,
    {'Beschafft Euch die Tiara der Tiefen und Gahz\'rillas elektrisierte Schuppe.', },
  },
  [27071] = {
    'Zorn der Sandwüter',
    {'Die Sandwüter sind ein widerstandsfähiger Stamm. Sie hab\'n Sandstürme überlebt und über die Jahre hinweg noch ganz andere Sachen, die inzwischen längst von Sand bedeckt sind. Es wäre dumm zu glauben, dass die einzige Macht hier die Trolle sind. Wir hab\'n Skarabäen gezähmt, Sul\'lithuz gezüchtet und unsere Toten wiederaufersteh\'n lassen, damit sie bis in alle Ewigkeit als Zombies kämpfen.|n|nRuuzlu, die rechte Hand von Häuptling Ukorz Sandskalp, hat vor, mit ihrer Hilfe Tanaris für die Sandwüter zurückzuerobern. Ihr solltet die Trolle, die dafür verantwortlich sind, töt\'n, wenn Ihr leben wollt, Mann.', },
    {'Tötet Theka den Märtyrer, Hexendoktor Zum\'rah, Antu\'sul und Ruuzlu.', },
  },
  [27072] = {
    'Die Alte Kaserne',
    {'Das Symbol auf diesen Abzeichen ist mir schon aufgefallen, bevor Todesschwinge die Stadt angegriffen hat. Die Soldaten in der Alten Kaserne, die im Westen der Stadt den Hafen überblickt, haben sie getragen.|n|nIhr hättet kaum zu einer besseren Zeit hier auftauchen können. Einer meiner Topagenten, Jack Bauden, ist in meinem Namen mit der Infiltration des Schattenhammers beschäftigt. Er wird seit gestern Nacht vermisst. Wenn Anduin und Ihr Recht habt, dann haben sich die Kultisten in der Alten Kaserne verkrochen. Die Zeit drängt! Greift die Alte Kaserne an, schaltet die Kultisten aus und rettet Jack Bauden.', },
    {'Geht zur Alten Kaserne und tötet 6 wahnsinnige Kultisten, dann findet Jack Bauden.', },
  },
  [27073] = {
    'Macht ihnen die Hölle heiß!',
    {'Die Goblins sind schuld, <Volk>!|n|n<hicks!>|n|nWisst Ihr, wir sind vom Bilgewasserhafen aus über Azshara zum Silberwald aufgebrochen. Ein riesiger Fehler! In unserem gesamten Imperium habe ich noch nie einen sündigeren und schmächlicheren Haufen erlebt! Diese verdammten Goblins haben uns zu jedem möglichen Laster verführt und uns mit Fässern voller Bier aufs Meer geschickt!|n|n<hicks!>|n|nDie Scham, die wir dafür empfinden, sitzt tiefer als jede Narbe. Unsere Ehre muss wiederhergestellt werden! Tötet die Blutfangworgen, die uns aufgelauert haben. Sie plündern gerade das Wrack im Südwesten.', },
    {'Tötet 10 Blutfangplünderer.', },
  },
  [27074] = {
    'Bekämpft den Hammer',
    {'Ihr habt das Unmögliche möglich gemacht! Ich habe die Nase voll davon, hier herumzuschmollen. Es wird Zeit, sich aufzugnomen.|n|nIch muss meinen Vater finden. Aber Ihr! Befasst Euch nicht länger mit mir. Ihr müsst weiter gegen diese Kultisten kämpfen.|n|nGeht und sprecht mit Ashlan Schmunzelstein im Osten. Er versucht, den Schattenhammer aufzuhalten, aber er hat niemanden, der ihm hilft. Ihr seid seine einzige Hoffnung!|n|nGebt nicht auf, $N. Ich werde es auch nicht tun.', },
    {'Sprecht in Loch Modan in der Nähe der Festung Mo\'grosh mit Ashlan Schmunzelstein.', },
  },
  [27075] = {
    'Diener von Cho\'gall',
    {'Der Schattenhammer war zunächst ein Klan der wilden Horde. Ihr Anführer - Cho\'gall - formte aus seiner Bande Oger nach und nach einen tödlichen Kult, der jeden willkommen hieß, der verrückt genug war, sich das Ende allen Lebens zu wünschen. Wie Ihr seht, gibt es immer noch viele Oger unter ihnen. Sie sind verwirrt, fanatisch und immer noch so stark wie früher.|n|nDiese primitiven Monster besitzen die Frechheit, hierherzukommen und ihren Schmutz über unser Land auszubreiten. Je mehr Ihr tötet, desto besser wird Loch Modan dastehen, $N.', },
    {'Tötet 7 Oger der Mo\'grosh in der Festung Mo\'grosh.', },
  },
  [27076] = {
    'Einbruch mit schwerem Werkzeug',
    {'Ein guter Kumpel von mir, Weegli Lunte, hat sich mit Unteroffizier Bly und seiner Gruppe Gesetzloser zusammengetan, um in Zul\'Farrak einzumarschieren und das legendäre Sul\'thraze zu erbeuten. Natürlich haben sie den Stamm der Sandwüter unterschätzt und jetzt sind sie alle festgesetzt und warten auf ihre Hinrichtung, um den Halbgott Gahz\'rilla zufriedenzustellen.|n|nWenn Ihr Weegli befreit, wird er Euch helfen, den Weg zu Ukorzs Privatgemächern freizusprengen, wo er mindestens einen Teil der Klinge aufbewahrt.|n|nTötet Nekrum den Ausweider und Schattenpriester Sezz\'ziz, die ihn gefangen genommen haben, als Rache...Ich werde Euch belohnen.', },
    {'Befreit Weegli Lunte und tötet Nekrum den Ausweider und Schattenpriester Sezz\'ziz.', },
  },
  [27077] = {
    'Ans Chaos klammern',
    {'Die Kultisten vom Schattenhammer benutzen ihre Kräfte, um Elementiummetall aus den Tiefen der Erde zu gewinnen. Sie locken es als verdrehte Stacheln heraus, um damit ihre Gebäude zu formen, die in dem entweihten Boden verwurzelt sind.|n|nDie Oger hier scheinen dabei kräftig mitzumischen und wir müssen zuschlagen, solange sie es noch in Form drehen.|n|nReißt die Stacheln aus dem Boden, solange sie noch biegsam sind und bringt sie zu mir. Wir werden diesen Hundesöhnen nicht einen Zoll unseres Landes überlassen.', },
    {'Reißt 10 entstehende Elementiumstacheln aus dem Boden der Festung Mo\'grosh.', },
  },
  [27078] = {
    nil,
    {'Der Oger, der über diese primitiven Narren wachen soll, heißt Gor\'kresh. Er ist groß genug, um selbst diese Schläger herumzukommandieren - und obendrein ist er gerissen. Setzt niemals voraus, dass ein Oger dumm ist, denn dann erwischt er Euch.|n|nWenn Ihr ihn beseitigt, dann werden wir dem Schattenhammer schon zeigen, dass Loch Modan kein Sprungbrett für sie ist. Stellt Euch Gor\'kresh entgegen und treibt diese Narren zurück in das Hochland!', },
    {'Besiegt Gor\'kresh.', },
  },
  [27079] = {
    'Das Zwielichttor aufspüren',
    nil,
    nil,
  },
  [27080] = {
    'Das Zwielichttor aufspüren',
    nil,
    nil,
  },
  [27081] = {
    'Dem Verräter trauen',
    {'Diese beiden sind nutzlos. Kann ich wenigstens auf Euch zählen, um hier etwas Arbeit getan zu bekommen, $Gjunger Abenteurer:junge Abenteurerin;? Wir sind auf Mazoga gestoßen, einen Verräter der Sandwüter. Er sagt, dass er uns helfen kann, das legendäre Schwert Sul\'thraze zu finden, damit wir die Sandwüter endgütlig loswerden können!|n|nUm ehrlich zu sein, werden wir es wahrscheinlich hinterher meistbietend versteigern. Dieser Ort bezahlt nicht für sich selbst. Geht und tut, was er möchte...aber behaltet ihn im Auge. Ein Verräter bleibt immer ein Verräter. Er befindet sich in unserem Lager östlich von Zul\'Farrak.', },
    {'Sprecht mit Mazoga.', },
  },
  [27082] = {
    'Unfaire Methoden',
    {'Habt Ihr die großen, schwerfälligen Ettins gesehen, die durch die Wälder streifen? Die verfluchten Dinger kamen aus Gilneas. Jetzt vagabundieren sie durch das Land und suchen ihre nächste, saftige Mahlzeit. Wir haben es geschafft, einige von ihnen zu unterwerfen und sie nutzbar zu machen, um unsere Wagen zu ziehen, aber die anderen... nun, sie müssen getötet werden.|n|nLeider können wir keine Soldaten erübrigen, um das zu erledigen. Da kommt Ihr ins Spiel, $C.|n|nIch habe einen Plan, aber dafür brauchen wir noch Materialien. Geht hinaus in die Wälder, die diese Basis umgeben und beschafft die Organe kranker Tiere.', },
    {'Beschafft 8 verseuchte Organe von ergrauten Riesenbären und tollwütigen Worgs.', },
  },
  [27083] = {
    'Die Schlacht geht weiter!',
    {'Es gibt Nachrichten aus Andorhal, $N. Die Schlacht hat wieder angefangen.|n|nUnter den Streitkräften der Verlassenen ist es wohl bekannt geworden, dass Ihr Euch in der ersten Schlacht um Andorhal als einer der Helden hervorgetan habt. Koltira verlangt umgehend nach Eurer Anwesenheit.', },
    {'Meldet Euch in den Westlichen Pestländern in Andorhal bei Koltira Todesweber.', },
  },
  [27084] = {
    'Die Bauernmiliz',
    {'Der Kampf begann, als sie uns von hinten angriffen. Ich habe kurz nicht aufgepasst und eine Gruppe schlecht bewaffneter Bauern und Milizen stieß vom Trostlosen Feld in unsere Flanke vor.|n|nSie mögen schwach sein, aber wenn sie so ungehindert angreifen, besteht die Gefahr, dass sie uns allein durch ihre zahlenmäßige Überlegenheit überwältigen.|n|nLindsays domestizierte Monstrositäten können sich um den Nahkampf kümmern. Nehmt dieses Halsband, bleibt hinten und benutzt es, um meinen schwarzen Gargoyle auf diese Bauern zu hetzen.', },
    {'Benutzt das ebenhölzerne Gargoylehalsband auf 6 Provinzmilizen in Andorhal.', },
  },
  [27085] = {
    'Die Truppen unterstützen',
    {'Auch wenn diese Bauern uns zu überrennen drohen, dürfen wir die Hauptstreitmacht der Allianz nicht vergessen.|n|nReist in den Westen nach Andorhal und tötet die menschlichen Soldaten, die gegen unsere Todeswachen kämpfen. Wir können alle Hilfe gebrauchen, die wir bekommen können.', },
    {'Tötet 15 Verteidiger von Andorhal.', },
  },
  [27086] = {
    'Asche zu Asche',
    {'Im Westen, tief in dem von der Allianz gehaltenen Andorhal, findet Ihr ihre Kommandanten. Sie kämpfen nicht, sondern befehligen nur von den Rücken ihrer Pferde.|n|nJagt und tötet diese Kommandanten, $N. Die Menschen werden machtlos sein.', },
    {'Tötet 3 Streitkräftekommandanten von Andorhal.', },
  },
  [27087] = {
    'Die Entlarvung der Lindsay Rabensonn',
    {'Man hat mir gesagt, dass dieses nutzlose Weib, Lindsay Rabensonn, hier wäre, um mich in diesem Kampf zu unterstützen. Bisher hat sie noch nichts anderes getan, als im Keller des Haupthauses hinter mir dumpf vor sich hin zu brüten. Ist wohl auch besser so. Sie war eine Ablenkung.|n|nDennoch, ich kann und werde keine Befehlsverweigerung dulden. Findet sie und bringt sie zu mir.', },
    {'Meldet Euch in den Westlichen Pestländern in Andorhal bei Lindsay Rabensonn.', },
  },
  [27088] = {
    'Es ist nur giftig, wenn man es einnimmt',
    {'Nehmt diesen Käfig, $C. Darin befindet sich eins meiner mutierten Buschhühner, mit einigen leichten Veränderungen. In dem Hintern des Buschhuhns befindet sich eine Dynamitstange, die mit Schleim von den verseuchten Organen, die Ihr mir gebracht habt, versetzt ist.|n|nBringt den Käfig in den Wald und findet den Waldettin, der dort herumläuft. Lasst das Huhn frei und lehnt Euch zurück, während dieses Meisterstück seine Arbeit tut. Die folgende Explosion dürfte ausreichen, um den Ettin zu töten oder ihn so sehr zu schwächen, dass Ihr die Möglichkeit bekommt, ihn zu erlegen.', },
    {'Benutzt das mutierte Buschhuhn, um den Waldettin zu töten.', },
  },
  [27089] = {
    'Versteckter Trumpf',
    {'Ihr habt ja keine Ahnung, wie schwer es war, die Tarnung aufrecht zu halten, während ich zusah, wie Koltira diesen Krieg entgleiten ließ. Es ist so weit gekommen, dass diese lästigen Bauern uns zu überwältigen drohen. Und all das nur, weil er sich geweigert hat, einen Freund zu töten.|n|nNehmt noch einmal meine Val\'kyr, $N. Tötet die Bauern mit ihr an Eurer Seite, macht sie zu Verlassenen und lasst sie ausrücken. Dann geht mit einer Gruppe von ihnen in den von der Allianz gehaltenen Westteil von Andorhal und bringt diesen Todesritter Thassarian zur Strecke.|n|nWir werden diesen Krieg doch noch gewinnen.', },
    nil,
  },
  [27090] = {
    'Andorhal, für Immer und Ewig',
    {'Sylvanas wird alles über die Abreise von Thassarian aus Andorhal wissen wollen. Ihr beschließt, zu der Seite der Stadt, die von den Verlassenen gehalten wird, zurückzukehren.', },
    {'Meldet Euch in den Westlichen Pestländern in Andorhal bei Fürstin Sylvanas Windläufer.', },
  },
  [27091] = {
    'Greift an!',
    nil,
    nil,
  },
  [27092] = {
    'Kataklysmus in den Katakomben',
    {'Sorgt Euch nicht um mich, $C. Ich habe den Plan des Schattenhammers aufgedeckt. Sie haben im Hafen von Sturmwind eintreffenden Sprengstoff gesammelt und aufgeschichtet. Irgendwie haben sie sich Zutritt zu den Katakomben unter der Kathedrale des Lichts verschafft. Ich hörte von jemandem namens "Der Schwarze Bischof".|n|nWir haben nicht genug Zeit, um die Wache zu warnen. Es bleiben Euch nur noch Minuten, um in die Katakomben vorzudringen und die Bombe zu entschärfen! Geht! Schnell! Oder TAUSENDE MENSCHEN werden STERBEN!', },
    {'Betretet die Kathedrale des Lichts und steigt hinab in die Katakomben darunter. Tötet den Schwarzen Bischof und entschärft den Sprengstoffhaufen in der Nähe.', },
  },
  [27093] = {
    'In der Dunkelheit verlaufen',
    {'Einige würden sagen, dass wir Glück haben, am Leben zu sein. Diese Leute wären Idioten. Wenn wir gestorben wären, müssten wir uns nicht dem Zorn des Kriegshäuptlings stellen. Aber nun, was geschehen ist, ist geschehen. Jetzt müssen wir versuchen, unsere verlorene Ehre wiederherzustellen.|n|nDas dritte Schiff in unserer Flotte ist direkt vor der Huschdunkelküste nordwestlich von hier gesunken. Diejenigen, die es an Land geschafft haben, wurden von riesigen Spinnen der Gegend umzingelt und in Spinnweben gehüllt.|n|nWenn es dort Überlebende gibt, müssen wir sie befreien! Geht, $N. Auf ins Huschdunkel!', },
    {'Rettet 6 orcische Seebären aus dem Huschdunkel.', },
  },
  [27094] = {
    'Tiefer in die Dunkelheit',
    {'Die Netzhuschermatriarchin ist in der Nähe! Ihr könnt der Bedrohung durch die Netzhuscher ein Ende bereiten, indem Ihr sie erlegt!|n|nFindet sie am Ende der Höhle im Huschdunkel und vernichtet sie!', },
    {'Tötet die Netzhuschermatriarchin.', },
  },
  [27095] = {
    'Die Netzhuscherbedrohung',
    {'Rache ist allumfassend, $N! Unser drittes Schiff ist direkt vor der Huschdunkelküste nordwestlich von hier gesunken. Die Männer, die es von dem Schiff herunter geschafft haben, wurden entweder gefangen genommen, oder von den Netzhuscherspinnen der Region getötet. Dafür müssen die Spinnen sterben! ALLE!|n|nBegebt Euch zum Huschdunkel und zermalmt diese Spinnen!|n|nHaltet Ausschau nach ihrer Matriarchin. Wenn wir sie finden, können wir diese Bedrohung vielleicht beenden!', },
    {'Tötet 12 Netzhuscherspinnen.', },
  },
  [27096] = {
    'Alles klar bei den Orcs',
    nil,
    {'Liefert das Empfehlungsschreiben des Admirals bei Fürstin Sylvanas Windläufer bei der Kommandozentrale der Verlassenen im Silberwald ab.', },
  },
  [27097] = {
    'Erhebt Euch, Verlassene',
    {'Die Insel Fenris ragt trotzig im Herzen des Lordameresees auf - eine grausame Erinnerung an eine längst vergangene Zeit.|n|nObwohl sie nicht länger von Gnollgezücht befallen ist, hat sich eine neue Bedrohung aufgetan. Menschenflüchtlinge, die aus ihren Behausungen im Hügelland vertrieben wurden, sind in der Hoffnung auf die Insel Fenris geflohen, einer Niederlage durch uns zu entgehen. Da irren sie sich gewaltig.|n|nNehmt Agatha mit Euch zur Insel Fenris und tötet alle Menschen. Sie wird die Gefallenen als Verlassene wiedererwecken und so unsere Streitkräfte verstärken.|n|nEnttäuscht mich nicht, $N.', },
    {'Erweckt 15 Verlassene, indem Ihr Menschen auf der Insel Fenris tötet.', },
  },
  [27098] = {
    nil,
    {'Kommt mit mir zum Grabmal, $N. Ich möchte vieles mit Euch besprechen. Es ist unabdingbar, dass Ihr die Geschichte von Lordaeron und die Zwangslage der Verlassenen versteht.', },
    {'Begleitet Fürstin Sylvanas Windläufer zum Grabmal im Silberwald.', },
  },
  [27099] = {
    'Kein Entkommen',
    nil,
    nil,
  },
  [27100] = {
    'Zwielichtige Forschungen',
    {'Das Buch, das Ihr gefunden habt, scheint irgendeine Forschung zu beschreiben, die ein Mitglied des Schattenhammers durchgeführt hat.|n|nEs hat irgendwas mit Schlamm zu tun, aber es fehlen mehrere Seiten.|n|nVielleicht könntet Ihr zusätzliche Notizen finden, damit das Ganze einen Sinn ergibt.', },
    {'Findet in den Oberen Silbermarschen 4 Zwielichtforschungsnotizen über Quecksilberschlamm.', },
  },
  [27101] = {
    'Maziels Enthüllung',
    {'Die Notizen führen Maziels Forschungsgeschwafel über die Zusammensetzung von Quecksilber und Quecksilberschlamm fort.|n|nOffenbar hat er eine wichtige Entdeckung gemacht. Er erwähnt, dass er sein Tagebuch in den Unteren Silbermarschen gen Südwesten versteckt hat.', },
    {'Geht zu den Unteren Silbermarschen in Tiefenheim und findet Maziels Tagebuch.', },
  },
  [27102] = {
    'Maziels Aufstieg',
    {'Maziels Tagebuch enthält Aufzeichnungen über ein Aufstiegsritual, das seinen Körper in pures Quecksilber verwandeln würde.|n|nDas Ritual soll in einer Höhle in der Nähe der Unteren Silbermarschen stattfinden, wo Maziel sich von Quecksilberschlamm ernähren will, bis er die volle Stärke erreicht hat.|n|nVielleicht ist es noch nicht zu spät, seinem Wahnsinn Einhalt zu gebieten.', },
    {'Tötet Maziel in der Silberlichthöhle in Tiefenheim.', },
  },
  [27103] = {
    'Die Splitter der Teufelsranke',
    {'Der Satyr Alzzin der Wildformer übt seine verdorbene Herrschaft über diesen Teil von Eldre\'Thalas aus. Die korrumpierte Frucht des Gedeihens - die Teufelsranke - sollte sich in Alzzins Nähe befinden. Sie könnte der Schlüssel sein, um diesen uralten Ort zu reinigen.|n|nWenn der große Satyr fällt, versucht so viel wie möglich von der Essenz der Teufelsranke zu erlangen. Versiegelt sie dann in diesem Reliquiar der Reinheit und bringt es zu mir.|n|nViel Glück und Cenarius\' Kraft sei mit Euch!', },
    {'Benutzt das Reliquiar der Reinheit, um einen Teufelsrankensplitter einzufangen.', },
  },
  [27104] = {
    'Alzzin der Wildformer',
    {'Das Monster, das für die Zerstörung, die Ihr vor Euch seht, verantwortlich ist, heißt Alzzin der Wildformer. Um an ihn heranzukommen, müsst Ihr allerdings Zevrim Dornhuf töten, den Satyr, der den immer noch edlen alten Eisenborke der Große in seinen Klauen hält.|n|nSobald Eisenborke frei ist, wird er Euch helfen, Alzzins Herrschaftsgebiet zu betreten. Geht hinein und tötet ihn, ohne Gnade zu zeigen, denn es gibt keine andere Möglichkeit.', },
    {'Tötet Zevrim Dornhuf und Alzzin den Wildformer.', },
  },
  [27105] = {
    'Ein ungebetener Gast',
    {'Ihr werdet sehen, dass Düsterbruch voller Natur- und Arkanelementaren ist. Irgendwie hat ein Wasserelementar seinen Weg in diese Gegend gefunden. Bitte beschafft Euch seine Essenz und bringt sie zu mir. Ich bin neugierig, wie es hierhergekommen ist und welche Pläne es in Bezug auf die natürlich vorkommenden Elementare von Eldre\'Thalas hat.', },
    {'Findet die Hydrobrutessenz.', },
  },
  [27106] = {
    'Entlarvung eines Schurken',
    {'<Ihr findet eine vollständige Liste aller Kultisten des Schattenhammers in Sturmwind.>|n|n<Was noch wichtiger ist, Ihr entdeckt einen Brief von Major Samuelson an seine Komplizen, der den ganzen Plan darlegt. Der Prinz hatte Recht: Samuelson ist der wahre Verbrecher hier, der seine Verbindungen als Kommandant der Stadtwache dazu nutzt, die Aktivitäten des Kults zu verschleiern.>|n|n<Es wird Zeit, nach Burg Sturmwind zurückzukehren und Samuelson zur Rechenschaft zu ziehen!>', },
    {'Enttarnt und tötet Major Samuelson im Thronraum von Burg Sturmwind.', },
  },
  [27107] = {
    'Pusillin der Dieb',
    {'Ich nur kurz Nickerchen vorhin gemacht und blöder schneller Wichtel hat gestohlen Buch! Dagg\'thol braucht Buch, um Befehle zu befolgen und Meister braucht Buch zum Erobern! Bah!|n|nIhr <Volk> helft mir, Buch von Wichtel zurückzuholen und ich gebe etwas Glänzendes. Geht, Wichtel ist da links! TÖTEN!!!', },
    {'Überredet Pusillin, das Buch der Zauberformeln herauszugeben.', },
  },
  [27108] = {
    'Lethtendris\' Netz',
    {'Blutelf Lethtendris hat Netz zum Fangen von Magie hier. Sie benutzt selbst, aber Meister will benutzen um der ganzen Welt gut zu tun. Helft, Netz von dummer Elfe zu holen und Dagg\'thol wird Euch belohnen. Dann Ihr seht, wie Meister es viel besser benutzt!', },
    {'Beschafft Lethtendris\' Netz.', },
  },
  [27109] = {
    'Windschiefe Verteidiger',
    {'Eisenborke und Wucherborke waren einst die mächtigen Beschützer von Eldre\'Thalas. Schaut, was aus ihnen geworden ist! Ihr Schicksal liegt letztendlich in meinen Händen und denen der anderen Hochgeborenen. Wir sind mit unserer Macht unachtsam umgegangen, <Volk>.|n|nAber Ihr, Ihr könnt das Unrecht wieder ungeschehen machen! Geht hinaus und bettet Tendris Wucherborke zur Ruhe. Er war der mächtigste und letzte Verteidiger dieses Gebiets und er verdient es, dass sein Geist freigelassen wird. Seid vorsichtig, denn wenn Ihr Euch nicht der Beschützer von Eisenborke entledigt, bevor Ihr Tendris angreift, wird er sie zu Hilfe rufen.', },
    {'Tötet Tendris Wucherborke.', },
  },
  [27110] = {
    'Der innere Wahnsinn',
    {'Dieser Wahnsinn muss ein Ende haben. Das Zeitalter der Unsterblichen ist lange vergangen. Vernichtet die Wächter rings um die Pylonen herum, um das Kraftfeld zu senken. Wenn das erledigt ist, vernichtet Immol\'thar. Die Macht des Prinzen wird durch das Dahinscheiden des Dämons stark geschwächt sein. Greift ihn an und beendet seine Existenz. Gewährt den Geistern dieser Stadt ihre letzte Ruhe, Abenteurer, und lasst den Prinzen für seine Schandtaten bezahlen.', },
    {'Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol\'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol\'thar umgibt, auflösen.|n|nBetretet Immol\'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.|n|nKehrt nach Abschluss der Aufgabe zur uralten Shen\'dralar im Hof zurück.', },
  },
  [27111] = {
    'Der Schatz der Shen\'dralar',
    {'In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe was Ihr wollt.', },
    {'Kehrt in das Athenaeum zurück und sucht den Schatz der Shen\'dralar. Nehmt Euch Eure Belohnung!', },
  },
  [27112] = {
    'Verfluchte Überreste',
    {'Es gibt immer noch einige Wesen, die eine Gefahr darstellen, sollten wir diese heilige Stadt zurückerobern wollen. Magister Kalendris und Illyanna Rabeneiche sind beide äußerst gefährlich und wir müssen uns ihrer so schnell wie möglich entledigen.|n|nSeid vorsichtig, denn jetzt, da nur noch so wenige sich von Immol\'thars Energien nähren, sind sie wahrscheinlich stärker, als es auf den ersten Blick scheint.', },
    {'Tötet Magister Kalendris und Illyanna Rabeneiche.', },
  },
  [27113] = {
    'Der Uralte Shen\'dralar',
    {'Einige Wesen haben es auf wundersame Weise geschafft, der Dunkelheit zu entgehen, die hier ihr Unwesen treibt. Auf der zweiten Etage am Hof der Hochgeborenen ruht ein Uralter Shen\'dralar. Sucht ihn auf, er ist möglicherweise ein unerschöpflicher Quell der Weisheit und kennt vielleicht sogar das Geheimnis, wie man Eldre\'Thalas befreit.', },
    {'Sprecht mit dem Uralten Shen\'dralar.', },
  },
  [27114] = {
    'Der Gordokgeschmackstest',
    nil,
    nil,
  },
  [27115] = {
    'Andos Ruf',
    {'Ihr habt hier großartige Arbeit geleistet, $N. Als Ihr fort wart, hat dieser junge Bursche Ando nach Euch gesucht. Sagte was von einem Metallvogel.|n|nVielleicht solltet Ihr zu den Ufern des Loch zurückkehren und nachsehen, was er wollte.', },
    {'Sprecht mit Ando Blastenheimer.', },
  },
  [27116] = {
    'Die Winde von Loch Modan',
    {'Vater hat den Himmelsschreiter fertiggestellt. Er ist großartig! Wenn wir erst einmal die Kinderkrankheiten ausgemerzt haben, werde ich ihn benutzen, um für die Gerechtigkeit zu kämpfen - genau, wie Ihr.|n|nIch weiß, Ihr müsst weiterziehen und anderen Menschen helfen. Schließlich seid Ihr ein Held und so, aber wie wäre es mit einem Probeflug? Ich will den Himmelsschreiter gerade zu seinem Jungfernflug hinausbringen und es wäre mir eine Ehre, wenn Ihr Euch mir anschließen würdet. Ich setze Euch bei der Station Algaz ab.|n|nWas meint Ihr?', },
    {'Fliegt mit dem Himmelsschreiter zur Station Algaz und sprecht dann mit Gebirgsjäger Sturmlanze.', },
  },
  [27117] = {
    'Rohe Gewalt',
    {'Gandling hat seinen Leutnant, den Ravenier, zur Unterstützung mitgebracht. Dieser trampelnde Rohling ist viel gefährlicher als jede andere Geißel und Monstrosität, die Euch auf dem Schlachtfeld begegnen wird.|n|nDer Ravenier befindet sich in einem Turm am südlichen Ende des Orts. Ich empfehle Umsicht, bevor Ihr mit ihm kämpft, $N. Er ist kein leichter Gegner.', },
    {'Tötet den Ravenier in Andorhal.', },
  },
  [27118] = {
    'Eine beschädigte Falle',
    nil,
    nil,
  },
  [27119] = {
    'Der Ogeranzug der Gordok',
    {'Wenn Ihr vorhabt, gegen den König der Gordok zu kämpfen, dann werden Ihr es erstmal an Hauptmann Krombruch vorbei schaffen müssen. Sicher könnt Ihr ihn einfach töten. Doch vielleicht wollt Ihr diesen Oger ja am Leben lassen. |n|nEs stellt sich nur die Frage, wie? Ich glaube ich weiß, wie! Ein Ogeranzug! Ich kann Euch einen herstellen, der ausreicht, um diese Kerle zu täuschen, wenn Ihr mir Ogergerbemittel von oben herbringt. So wie die Dinge stehen, gehe ich nirgendwohin.', },
    {'Bringt etwas Ogergerbemittel zu Knot Zwingschraub.', },
  },
  [27120] = {
    'Der Ogeranzug der Gordok',
    nil,
    nil,
  },
  [27121] = {
    'Befreit Knot!',
    nil,
    nil,
  },
  [27122] = {
    'Fix und fertig und doch nicht bereit',
    {'Überlasst es den Dunkeleisenzwergen, mit den Krötengesichtern von Ragnaros und den schlimmeren Übeln zu arbeiten. Ihr könnt Euch sicher sein, dass die Verrückten vom Kult des Schattenhammers viel damit zu tun haben!|n|nEs ist an der Zeit, ihre Angriffe auf Eisenschmiede ein für alle Mal zu beenden. Oh, berichtet Kommandant Klippenfaust von den Vorfällen hier, wenn wir zurückgekehrt sind; Ich muss mich erst einmal darum kümmern, die Stadt und ihre guten Einwohner wieder auf Vordermann zu bringen.', },
    {'Tötet den höchsten Botschafter Flammenschlag und informiert Kommandant Klippenfaust in Eisenschmiede.', },
  },
  [27123] = {
    'Tiefenheim, Reich der Erde',
    {'Ich wusste, Ihr würdet unserem Ruf Folge leisten, $N. Als Todesschwinge das erste Mal von den anderen Drachenaspekten besiegt wurde, zog er sich nach Tiefenheim, im Reich der Erde, zurück.|n|nTodesschwinges Rückkehr in unsere Welt hinterließ einen Riss zwischen Azeroth und Tiefenheim.|n|nWenn wir die Lücke nicht schließen, wird dieses Land auseinandergerissen werden. Wir tun unser Bestes, um den Schaden, der diesseits des Risses entsteht, in Grenzen zu halten. Aggra wird Euch durch den Riss mitnehmen, damit Ihr helfen könnt, den Schaden von der anderen Seite aus zu reparieren.|n|nSchwingt Euch auf ihren Wyvern, wenn Ihr bereit seid.', },
    {'Springt auf Aggras Wyvern und fliegt in die Bresche am Mahlstrom. Wenn Ihr auf der anderen Seite ankommt, sprecht mit Maruut Steinbinder.', },
  },
  [27124] = {
    'Die offene Rechnung der Gordok',
    {'Nun Ihr de\' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von Wächter Mol\'dar! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de\' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!|n|nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur de\' wahre König de\' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, de\' gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!', },
    {'Sprecht mit Wache Mol\'dar in Düsterbruch.', },
  },
  [27125] = {
    'König der Gordok',
    {'Bei den Gordok, ist der stärkste Krieger der König. Wenn jemand, egal ob Oger oder sonstwer, den amtierenden König tötet, wird er automatisch als neuer König begrüßt.|n|nDer neue König erhält Tribut von allen lebenden Wachen, Stampfer Kreeg und Hauptmann Krombruch. Findet und tötet König Gordok, aber tötet so wenig der anderen Anführer wie möglich. Ihr werdet nicht nur eine reiche Belohnung erhalten, sondern könnt Eure Macht als König benutzen, um die Invasion der Gordok ohne Konflikt zu verhindern!', },
    {'Tötet König Gordok.', },
  },
  [27126] = {
    'Eilige Lieferung',
    {'Spitz Schleifsteins Team hatte irgendwo im Westen eine Panne.|n|nMeint Ihr, Ihr könnt Euch zur Abwechslung mal nützlich machen und einige Ersatzteile zu ihnen hinausbringen, <Volk>?', },
    {'Liefert die Katapultteile bei Spitz Schleifstein an der Zerrissenen Front in Tiefenheim ab.', },
  },
  [27127] = {
    'Fix und fertig und doch nicht bereit',
    {'Dunkeleisenzwerge? Cho\'gall? Wir werden ihnen zeigen, was mit Angreifern Orgrimmars passiert.|n|nLasst uns angreifen! Wir werden ihre verstümmelten Leichen in das Magma schmeißen, das ihnen so gut gefällt.|n|nIhr berichtet Blutwache Kang von den Vorfällen hier, wenn wir fertig sind, ja? Ich werde zweifellos einige Zeit brauchen, um die Aufräumarbeiten in der Stadt zu organisieren.', },
    {'Tötet den höchsten Botschafter Flammenschlag und meldet Euch bei Blutwache Kang in Orgrimmar.', },
  },
  [27128] = {
    'König der Gordok',
    {'Du tötest Anführer der Gordok, du neuer Ogerkönig. Wenn du König, dann überlebende Ogeranführer wie Kromcrush und Kreeg zahlen großen Tribut und du beendest Gordokinvasion. Wenn du das tust, dann ich sehr glücklicher Oger und wir nehmen Düsterbruch FÜR DIE HORDE!!!|n|nGeht, $Gkleiner:kleine:r; <Volk>! Tötet hässlichen Gordok Ogerkönig und vielleicht das hier neue Steinbrecherfestung! Yar!', },
    {'Tötet König Gordok.', },
  },
  [27129] = {
    'Wucherborke retten',
    {'Direkt im Ostflügel von Düsterbruch lebt eines der Urtume der Wucherborken, Furugs Wucherborke, noch vollkommen unverdorben. Ihr müsst dorthin reisen und ihm helfen, die furchtbaren Kreaturen zu vertreiben, die alles für sich einnehmen. Düsterbruch einzunehmen wäre ein Riesenfortschritt, Feralas für unser Volk wieder zurückzuerobern.|n|nIhr findet Düsterbruch südöstlich von hier.', },
    {'Sprecht mit Furgus Wucherborke.', },
  },
  [27130] = {
    'Wucherborke retten',
    {'Direkt im Ostflügel von Düsterbruch lebt eines der Urtume der Wucherborken, Furugs Wucherborke, noch vollkommen unverdorben. Ihr müsst dorthin reisen und ihm helfen, die furchtbaren Kreaturen zu vertreiben, die alles für sich einnehmen bevor sie Camp Mojache entdecken. Vielleicht können wir uns seiner Hilfe für später versichern, um unsere Anwesenheit in Feralas zu sichern, wo wir doch von Feinden umzingelt sind.', },
    {'Sprecht mit Furgus Wucherborke.', },
  },
  [27131] = {
    'Die Hochgeborenen',
    {'Estulan, ein mächtiger und unverdorbener Hochgeborener, hat sich Zutritt zum westlichen Flügel von Düsterbruch verschafft und bittet um Mithilfe, diesen zu säubern. Ungeachtet Eurer persönlichen Ansichten über die Hochgeborenen, muss ich diese Bemühung zum Wohle von Feralas gutheißen. Möge der Wind Euren Geist mit großer Geschwindigkeit dorthintragen.|n|nIhr findet Düsterbruch südöstlich von hier.', },
    {'Sprecht mit Estulan.', },
  },
  [27132] = {
    'Die Hochgeborenen',
    {'Estulan, ein mächtiger und unverdorbener Hochgeborener, hat sich Zutritt zum westlichen Flügel von Düsterbruch verschafft und bittet um Mithilfe, diesen zu säubern. Ungeachtet Eurer persönlichen Ansichten über die Hochgeborenen, muss ich diese Bemühung zu unserem Wohle gutheißen. Bitte beeilt Euch - wir brauchen jeden Fuß in der Tür von Feralas, den wir bekommen können.|n|nIhr findet Düsterbruch im Westen.', },
    {'Sprecht mit Estulan.', },
  },
  [27133] = {
    'Blick zum Himmel',
    {'Die schlimmste und am besten organisierte Gefahr in Feralas stellen für uns die Oger der Gordok am nördlichen Flügel von Düsterbruch dar. Ich habe einen Druiden der Kralle beauftragt, sich dorthin zu begeben und die Lage zu erkunden. Meldet Euch bei ihm, falls er noch am Leben ist. Er wird Euch befehligen, um die Gordok aufzuhalten, bevor sie sich zum Angriff entscheiden.|n|nDas ist ein Befehl, $C.', },
    {'Sprecht mit dem Druiden der Kralle.', },
  },
  [27134] = {
    'Oger im Feld',
    {'Die schlimmste und am besten organisierte Gefahr in Feralas stellen für uns die Oger der Gordok am nördlichen Flügel von Düsterbruch dar. Wenn wir sie auslöschen und Düsterbruch für die Horde in Anspruch nehmen, könnten wir unsere Machtposition in dieser artefaktreichen Gegend enorm stärken. Ich habe vor kurzer Zeit eine kleine Truppe Oger der Steinbrecher losgeschickt. Sprecht mit möglichen Überlebenden und beendet, was begonnen wurde.|n|nDas ist ein Befehl, $C.', },
    {'Sprecht mit dem Oger der Steinbrecher.', },
  },
  [27135] = {
    'Etwas, das brennt',
    {'Also, wir brauchen etwas, mit dem das Präparat in die Luft fliegt - KABUMM!|n|nIch habe kein Schießpulver mehr, aber ich habe eine Idee, was wir stattdessen verwenden können... das Herz meines Feuerelementars!|n|nHier, nehmt mein Feuertotem mit nach Osten auf Eurem Weg zum Blutpfad. Betätigt es dort in der Nähe der Lavaseen, und Magmazahn sollte erscheinen. Bringt mir sein Herz, dann unterhalten wir uns weiter.', },
    {'Erhaltet das brennende Herz.', },
  },
  [27136] = {
    'Elementarenergie',
    {'Wir müssen unsere ganze Kraft aufbringen, um die Stabilität des Reichs in der Abwesenheit der Weltensäule sichern zu können.|n|nAls Schamanen können wir direkt die Energien der Elementare von Tiefenheim anzapfen und zur Heilung für vom Riss verursachten Schaden nutzen.|n|nNehmt dieses Totem und platziert es außen auf dem Boden. Alle aufgeladenen Geoden oder zerstörten Leitsteinelementare in der Nähe werden es mit der Energie füllen, die wir benötigen.', },
    {'Zerstört 8 aufgeladene Geoden oder Leitsteinelementare in der Nähe des erschöpften Totems.', },
  },
  [27137] = {
    'Erdmädchen sind nicht einfach',
    nil,
    nil,
  },
  [27138] = {
    'Erdmädchen sind nicht einfach',
    nil,
    nil,
  },
  [27139] = {
    'Hobart braucht Euch',
    {'He da, Boss! Hobart Wurfhammer möchte mit Euch sprechen. Er sagt, es wäre eine Angelegenheit von höchster Dringlichkeit!', },
    {'Sprecht mit Hobart Wurfhammer in Instastadt auf den Verlorenen Inseln.', },
  },
  [27140] = {
    'Alexis Gambit',
    {'Ich benötige Eure Hilfe, $C. Findet den Untoten Magier Vectus und den Krieger Marduk hier in den Tiefen. Sie sind mit der Operation des verseuchten Drachen der Geißel beschäftigt und müssen aufgehalten werden.|n|nPlatziert das Gambit in dem Vorführraum, in dem sie sich befinden. Hoffentlich entsteht eine Reaktion mit ihren Kräften und zerstört sie!|n|nOh, Vectus und Marduk danach zu bewältigen dürfte auch kein Problem darstellen, oder?', },
    {'Platziert das Gambit im Vorführraum und tötet Vectus und Marduk.', },
  },
  [27141] = {
    'Verfrühte Explosionierung',
    {'Was für ein Fund!|n|nGenau hier... genau an der Stelle, die in meinen Notizen vorhergesagt wurde.|n|nMit ein wenig Glück werden sich in dieser Kammer Hinweise zum Verbleib der legendären Lade der Verheißung finden lassen.|n|nJa, das stimmt, $N. Es ist nicht nur eine Legende. Ich glaube, dass es die Lade wirklich gibt.|n|nIch werde Euch später mehr erklären. Helft mir jetzt erstmal mit diesen Sprengsätzen.', },
    {'Helft Harrison Jones am Grab des Khartut.', },
  },
  [27142] = {
    'Der Lich Ras Frostraunen',
    {'Einer der Studenten, denen Kel\'Thuzad viel Vertrauen schenkt, leitet die Operationen in Scholomance. Tretet dem Lich Ras Frostraunen in seinem Unterschlupf gegenüber. Die hintere Tür im Vorführraum führt in seine Kammer.|n|nZerstört ihn, $N. Löscht jeglichen Nachweis seiner Existenz aus, so dass er nie wieder solche Schrecken in unsere Welt bringen kann.', },
    {'Vernichtet Ras Frostraunen.', },
  },
  [27143] = {
    'Das Familienvermögen der Barovs',
    {'Das Familienvermögen der Barovs liegt in Scholomance. Alexi und ich sind die beiden letzten verbliebenen Erben des Hauses Barov.|n|nIch bin jedoch der letzte Barov, der am Leben ist, und somit ist das ganze Reich der Barovfamilie mein! Findet die Besitzurkunden für Darrowehr, Brill, Tarrens Mühle und Süderstade, und ich werde Euch mit großem Reichtum belohnen. Der Besitz der Barov wird endlich wieder in voller Blüte stehen!', },
    {'Findet die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade.', },
  },
  [27144] = {
    'Die Abrechnung',
    {'Ihr habt eine vortreffliche Leistung vollbracht. Ihr erfüllt die Verlassenen mit Stolz, was ich von Kriegsherr Koltira Todesweber nicht behaupten kann.|n|nIch habe vor, ein ernstes Wörtchen mit diesem Todesritter zu wechseln. Er hat Schande über sich und das, wofür er steht, gebracht.', },
    {'Wartet, bis Fürstin Sylvanas Windläufer mit Koltira Todesweber gesprochen hat.', },
  },
  [27145] = {
    'Verseuchte Jungtiere ... im Moment',
    {'Eines der aktuellen \'Projekte\' ist der verseuchte Drachenschwarm. Glücklicherweise handelt es sich dabei um Jungtiere, aber wenn wir noch länger warten, werden sie zu einer der mächtigsten Waffen im Arsenal der Geißel und eine ernst zu nehmende Gefahr für Azeroth, und vor allem für die Ländereien meiner Familie.|n|nErschlagt zehn der Jungtiere und vergesst nicht, Euch auch um Blutrippe zu kümmern. Ihr findet ihn in der Nähe der Behausung der Jungtiere, wo er Nahrungsergänzungen zubereitet, die das Wachstum ankurbeln sollen. Beeilt Euch - bevor sie noch größer werden!', },
    {'Tötet 10 verseuchte Jungtiere und Blutrippe.', },
  },
  [27146] = {
    'Doktor Theolen Krastinov, der Schlächter',
    {'Doktor Theolen Krastinov ist für die Tode Tausender verantwortlich. Seinen Spitznamen \'der Schlächter\' hat er sich mit den Gräueltaten, die ihm so viel Freude bereiten, redlich verdient. Er muss im Namen der Gerechtigkeit bestraft werden.|n|nSucht ihn und bringt jene Qual über ihn, die er über zahllose Unschuldige wie mich und meinem Ehemann gebracht hat. Wenn er vernichtet ist, verbrennt unsere Überreste. Verwandelt sie in Asche, $N. Befreit unsere schmerzenden Seelen.', },
    {'Vernichtet Doktor Theolen Krastinov, und verbrennt die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff.', },
  },
  [27147] = {
    'Kirtonos der Herold (Zauber - Bild)',
    nil,
    nil,
  },
  [27148] = {
    'Hurra, hurra, die Schule brennt!',
    {'Dunkelmeister Gandling ist der Direktor von Scholomance und daher für die zahllosen Tode verantwortlich, die seine Schüler für ihn ausführten. Dafür muss er bestraft werden.|n|nEr wird nicht so einfach aus seinem Arbeitszimmer kommen. Lockt ihn heraus, indem Ihr die sechs Professoren tötet, deren Zimmer zum Arbeitszimmer des Direktors führen. Seid vorsichtig, denn wenn der letzte Professor erledigt ist, wird er mehr als erzürnt erscheinen und mit überwältigender Magie angreifen. Seht zu, dass er es nicht aus dem Arbeitszimmer schafft.', },
    {'Tötet Dunkelmeister Gandling.', },
  },
  [27149] = {
    'Schule der Verdammten',
    {'Seid gegrüßt! Wie Ihr sehen könnt, sind die Westlichen Pestländer von beinahe allen Restposten der Geißel befreit. Allerdings ist Scholomance, die Schule der Totenbeschwörung, noch voller junger Seelen, die nur darauf warten, ihre Ausbildung zu Zauberern der Geißel abzuschließen. Unsere Arbeit wird umsonst gewesen sein, wenn wir dem ständigen Nachrücken immer neue - und vorallem auch mächtiger - Totenbeschwörer kein Ende setzen.|n|nReist südöstlich nach Scholomance und sucht Weldon Barov. Er ist der letzte lebende Nachkomme der Familie Barov, der einst alle diese Ländereien gehörten, und er ist unser Kontakt vor Ort.', },
    {'Sprecht mit Weldon Barov in Scholomance.', },
  },
  [27150] = {
    'Die Stätte der Heiler',
    {'Wahrscheinlich wird die Schlacht um Andorhal bald wieder wüten. In der Zwischenzeit solltet Ihr Eure Fähigkeiten als $C verfeinern.|n|nÖstlich von hier befindet sich ein großer Bauernhof, der von der Argentumdämmerung und dem Zirkel des Cenarius eingenommen worden ist. Ich bezweifle nicht, dass Ihr dort Arbeit finden werdet.', },
    {'Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.', },
  },
  [27151] = {
    'Taelan Fordrings Vermächtnis',
    {'Seid gegrüßt. Wie geht es Euch? Mein Name ist Daria.|n|nIch bin eine der Priesterinnen, die für den Erhalt des Friedens hier in Herdweiler zuständig ist. Eine meiner Aufgaben ist die Verwaltung des Turms entlang des Wegs südöstlich von Herdweiler. Dieser Turm ist von persönlicher Bedeutung für den Hochlord. Sein Sohn wurde dort getötet.|n|nDie Verwaltung des Turms bereitet jedoch aufgrund des feindlichen Einfalls der Gnolle vor Kurzem zunehmend Schwierigkeiten. Könnt Ihr mir helfen, den Weg von den Vandalen der Gnolle zu räumen, sodass ich meinen Pflichten nachkommen kann?', },
    {'Tötet 10 Plünderer der Rotkiefer.', },
  },
  [27152] = {
    'Ungewöhnliches Verhalten... selbst für Gnolle',
    {'Ich muss mich kurz konzentrieren.|n|n<Ihr fühlt, wie Darias Gedankensicht einen anderen Ort aufsucht, und dann wieder zu Euch zurückkehrt.>|n|nSüdlich des Turm von Taelan haben die Gnolle einen Ort der Zusammenkunft errichtet - folgt dem Weg, und haltet Euch östlich der Hauptstraße. Dort geht etwas vor sich... aber ich bin nicht sicher, was es ist. Wir sollten mehr darüber in Erfahrung bringen. Ich werde nach ungewöhnlichen Ereignissen Ausschau halten... Ihr solltet Euch damit beschäftigen, Euch zu schützen.', },
    {'Erkundet das Versteck der Gnolle entlang des Wegs nach Herdweiler in den Westlichen Pestländern.', },
  },
  [27153] = {
    'Die braven Bürger von Herdweiler',
    {'Seht Ihr die Reagenzien dort drüben? Und diese Ladungen hier? Es handelt sich dabei um das Eigentum der Argentumkreuzfahrer.|n|nGnolle sind für das Stehlen von Gütern bekannt, aber meines Wissens gab es in Herdweiler seit dem Einfall der Rotkiefer keine Vorfälle mehr. Das ist sehr merkwürdig.|n|nIch habe ein paar Kontakte in Herdweiler, die Euch helfen könnten: Morris Vant, Ausstatter Mendelev, Bree Eisenstock und der Hohe Kleriker Alphus. Ihr könnt ihnen vertrauen, und sie haben gute Verbindungen. Befragt sie, um herauszufinden, ob sie etwas über die verlorengegangenen Ladungen wissen.', },
    {'Sprecht mit Morris Vant, Ausstatter Mendelev, Bree Eisenstock und dem Hohen Kleriker Alphus in Herdweiler.', },
  },
  [27154] = {
    'Bisp festsetzen',
    {'Magus Bisp ist einer der renommiertesten Arkanisten von Herdweiler. Die Vorstellung, dass er sich mit Gnollen abgibt... und sich in der Totenbeschwörung versucht? Undenkbar.|n|nIhr werdet Ihn oben im Turm in der Nähe des Haupttors von Herdweiler finden können. Hoffentlich hat er eine Erklärung für das Ganze. Falls nicht, dann... In jedem Fall solltet Ihr den Magierturm nicht unvorbereitet betreten, $N.', },
    {'Sprecht mit Magus Bisp im oberen Teil des Magierturms in Herdweiler.', },
  },
  [27155] = {
    'Sich stellen',
    {'So... Ihr habt also einen Argentumkreuzfahrer getötet, mitten in Herdweiler. Normalerweise wird so was nicht so einfach abgetan, selbst wenn es sich um Selbstverteidigung handelt.|n|nIch schlage vor, Ihr folgt mir nach Burg Mardenholde und stellt Euch Hochlord Fordring. Wenn Ihr Glück habt, wird er Euch anhören und Verständnis für Eure Situation zeigen. Ich hoffe, ich habe Euch nicht in Schwierigkeiten gebracht.', },
    {'Meldet Euch bei Hochlord Tirion Fordring in Herdweiler in den Westlichen Pestländern.', },
  },
  [27156] = {
    'Es wird langsam Zeit!',
    {'Endlich! Ihr seid hier! Fangt mit der Arbeit an!|n|nMeine Männer haben schon zu lange nur mit diesen hölzernen Trainingsattrappen gekämpft. Sicherlich lässt sich das Schwingen eines Schwertes auch mit einer Trainingsattrappe erlernen, doch für den Kampf bedarf es eines echten Kämpfers.|n|nHmmm... Ich hatte ausdrücklich nach jemand mit einer eindrucksvollen Statur gefragt, aber in diesem Fall muss wohl $Gein:eine:r; <Volk> mit dünnen Ärmchen herhalten.|n|nKommt her und zeigt meinen Männern, wie man kämpft!', },
    {'Fordert 7 Lehrlinge von Herdweiler zum Kampf heraus und besiegt sie.', },
  },
  [27157] = {
    'Akkordarbeiter... &lt;Seufz&gt;',
    {'Oh, mir ist Euer Name entgangen. $N? Es freut mich, Eure Bekanntschaft zu schließen, $N.|n|nIch habe noch ein anderes Problem, bei dem ich Hilfe gebrauchen könnte, und Ihr habt etwas an Euch, dass gerade danach schreit, nach Hilfe gefragt zu werden.|n|nAm nördlichen Rand von Herdweiler ist eine kleine Mine, aus der wir den Großteil des für unsere Stadt benötigten Erz beziehen. Die Akkordarbeiter in der Mine verrichten normalerweise gute Arbeit.|n|nAllerdings scheint es leider, als habe eine überdurchschnittlich große Spinne sich in der Höhle häuslich eingerichtet. Meint Ihr, Ihr könnt Euch der Sache annehmen?', },
    {'Tötet Shadril in der Mine in Herdweiler.', },
  },
  [27158] = {
    'Die Schlacht um Andorhal',
    {'Beeilt Euch, $N... es gilt, keine Zeit zu verlieren.|n|nDie Stadt Andorhal befindet sich inmitten eines Krieges zwischen den Verlassenen, der Allianz und der Geißel. König Wrynn hat den Stein ins Rollen gebracht und einen Todesritter geschickt, um den Angriff in die Wege zu leiten. Ich bin aber sicher, dass er alle Hilfe brauchen wird, die er kriegen kann. Mit dem Tod von Arthas ist die Zeit für die Allianz gekommen, Lordaeron zurückzuerobern.|n|nMeldet Euch bei Greifenmeister Bibilfaz Federpfiff, wenn Ihr bereit seid, und er wird Euch mit dem nächsten Greifen losschicken.', },
    {'Meldet Euch bei Thassarian in Andorhal in den Westlichen Pestländern.', },
  },
  [27159] = {
    'Erst die Geißel... dann die Horde',
    {'Dunkelmeister Gandling vom Kult der Verdammten führt die Offensive der Geißel hier in Andorhal an. Mein ehemaliger Mitstreiter Koltira leitet die Streitkräfte der Verlassenen. Um Andorhal einzunehmen, müssen wir beide Streitmächte besiegen. Eine Niederlage ist gewiss, wenn wir versuchen, uns beiden auf einmal zu stellen.|n|nIch kenne Koltira gut genug, um zu wissen, dass er sich zuerst auf die Geißel konzentrieren wird. Wir werden es ihm gleichtun.|n|nSetzt die schwächeren, vertrockneten Geißeldiener außer Gefecht, um ihre Zahlen zu schwächen. Die Verlassenen werden darauf warten müssen, unseren Zorn zu spüren.', },
    {'Tötet 15 ausgedörrte Geißeldiener in Andorhal.', },
  },
  [27160] = {
    'Kriegsmaschinen',
    {'Vertrocknete Geißel... schwach. Monstrositäten... stark.|n|nWir besiegen starke Monstrositäten... wir gewinnen Krieg.', },
    {'Zerstört 6 aufgeschlitzte Ungetüme in Andorhal.', },
  },
  [27161] = {
    'Der unendliche Fluss',
    {'Araj der Beschwörer verstärkt die Verteidigung der Geißel mit einfachen Skeletten... eine Armee von Schwächlingen, die Euch eher überrennen als überwältigen wird. Er hat Animi in den nördlichen Türmen Andorhals versammelt, die diese Skelette in einer erschreckenden Geschwindigkeit hervorrufen können. Ich habe aber eine Lösung!|n|n<Lang reicht Euch ein paar Granaten.>|n|nIhre Funktion ist einfach. Wenn diese Granaten auf einen Knochenanimus - oder in unserem Fall einen Haufen Skelette - geworfen werden, wird nicht mehr als Splitter von ihnen übrig bleiben.', },
    {'Benutzt Langs Handgranaten und tötet 5 Berserker der Klapperknochen und zerstört einen Knochenanimus der Geißel.', },
  },
  [27162] = {
    nil,
    {'Scholomance ist eine der letzten verbleibenden Bastionen der Geißel im Westen des Thondroril. Der Direktor von Scholomance, ein Kultist namens Dunkelmeister Gandling, ist auf dem Schlachtfeld erschienen.|n|nDas wird der letzte Fehler sein, der ihm unterläuft.|n|nIhr werdet Gandling auf einem Platz in der Nähe des südlichen Stadtrands finden. Ich möchte, dass Ihr mit Gandling kämpft und ihn schwächt. Ich werde Euch beistehen, damit er sein Ende findet.', },
    {'Tötet Dunkelmeister Gandling in Andorhal.', },
  },
  [27163] = {
    'Rohe Gewalt',
    {'Gandling hat seinen Leutnant Blutrippe zur Unterstützung mitgebracht. Dieser rasselnde Schrecken ist viel gefährlicher als jede andere Geißel und Monstrosität, die Euch auf dem Schlachtfeld begegnen wird.|n|nBlutrippe befindet sich im alten Rathaus, in der Nähe der Stadtmitte. Ich empfehle Umsicht, bevor Ihr mit ihm kämpft, $N. Er ist kein leichter Gegner.', },
    {'Tötet Blutrippe in Andorhal.', },
  },
  [27164] = {
    'Araj der Beschwörer',
    {'Nun da der Animus besiegt ist, ist der nächste logische Schritt die Auslöschung Arajs und der Erhalt einer Scherbe seines Phylakteriums. Ihr habt ihn wahrscheinlich schon am Brunnen in der Stadtmitte herumlümmeln sehen.|n|nNehmt meine Granaten mit. Sie werden Araj keinen Schaden zufügen, aber Ihr könnt sie benutzen, wenn er auf die Idee kommt, Skelette zu beschwören, und diese damit in die Luft jagen. Ihr wisst ja, wie das geht.', },
    {'Tötet Araj den Beschwörer. Ihr könnt Langs Handgranaten benutzen, um die Berserker der Klapperknochen zu zerstören.', },
  },
  [27165] = {
    'Sieg, im Moment',
    {'Die Allianz hat gesiegt und unsere Streitmächte sind noch immer stark. Im Rahmen unserer Kriegsplanung müssen wir die Verlassenen jetzt angreifen, da sie sich noch vom Kampf erholen und nicht mit einem Angriff rechnen. Ich habe allerdings ein Abkommen geschlossen...|n|nWir werden warten. Wir greifen Koltira und seine Truppen an, wenn der richtige Zeitpunkt gekommen ist. Sprecht in der Zwischenzeit mit Ginny Siegesfroh und begebt Euch zum Zugwindlager südlich von hier. Kommandant Ashlam Ehrenschlag wird Euch über Eure nächste Aufgabe unterrichten.|n|nVon mir werdet Ihr wieder hören, sobald Ihr in Andorhal gebraucht werdet.', },
    {'Meldet Euch bei Kommandant Ashlam Ehrenschlag in Zugwindlager in den Westlichen Pestländern.', },
  },
  [27166] = {
    'Pfeile machen!',
    {'Wir müssen immer auf den Kampf vorbereitet sein, $N. Ob dieser Kampf gegen die Verlassenen in Andorhal, gegen die Geißel im Osten, oder gegen einen noch unbekannten Feind ausgetragen wird, steht noch in der Zukunft geschrieben. Wir wissen nur, dass wir bereit sein müssen.|n|nUns gehen die Pfeile aus. Ich kann Schäfte und Pfeilspitzen besorgen, aber ich benötige Federn. Die Vögel, die nordwestlich von hier kreisen, sind zu dieser Jahreszeit normalerweise in der Mauser. Könntet Ihr Euch dorthin begeben und für unser Lager einige dieser Federn sammeln?', },
    {'Erhaltet 9 Braunfederkiele.', },
  },
  [27167] = {
    'Magenknurren',
    {'Ich komme aus Westfall, weit im Süden. Auch diese Männer, die mit mir reisen, sind von dort. Wir sind nicht mehr als Bauersleute.|n|nMir wurde gesagt, dass Lordaeron geheilt wurde und der Boden bestellt werden kann. Dieser "Kommandant" meint jetzt allerdings, dass es zu gefährlich ist, diese Arbeit vorzunehmen. Er meint, es tobe ein Krieg, und dass die Pestländer noch nicht geheilt sind.|n|nWie dem auch sei, was ich wirklich brauche, ist Essen in den Mägen meiner Männer. Es ist egal, was. Es scheint, als seien Bären hier reichlich vorhanden.', },
    {'Beschafft Euch 5 Stücke Bärenfleisch von struppigen Schwarzbären in den Westlichen Pestländern.', },
  },
  [27168] = {
    'Wer nicht loslassen kann',
    {'Trauerhügel nordöstlich von hier war einer der ersten Orte, den die Argentumkreuzfahrer und der Zirkel des Cenarius heilen konnten. Dieses Gebiet ist nun von der Geißel befreit.|n|nAllerdings finden sich dort immer noch Schreckgespenster der Vergangenheit, die aus irgendwelchen Gründen den Weltenübergang nicht vollbracht haben. Vielleicht trauern sie, oder sie haben noch eine Aufgabe zu erledigen... oder sie haben sich einfach nur verirrt.|n|nNehmt mein Weihrauchfass und läutert sie mit dem heiligen Weihrauch. Auf die eine oder andere Weise wird ihnen das beim Weltenübergang helfen.', },
    {'Benutzt das Heilige Weihrauchfass bei 12 zurückgezogenen Geistern in Trauerhügel, und tötet sie, falls ihre Reaktion dies verlangt.', },
  },
  [27169] = {
    'Uthers Segen',
    {'Diese Bauern aus dem Süden wollen sich der Bauernhöfe annehmen, aber ich kann nicht zulassen, dass sie die Pestländer unvorbereitet betreten. Auch jetzt, wo die Geißel nicht mehr hier ist, lauert immer noch Gefahr - durch die Verlassenen. Nein, wir müssen bereit sein, zu kämpfen, und das schließt unsere Besucher ein.|n|nBevor wir irgendetwas anderes tun, würde ich allerdings vorschlagen, dass Ihr nach Osten zu Uthers Grabmal reist und diesen Tribut vor seiner Statue niederlegt, um seinen Segen zu erbitten. Sprecht danach mit dem Priester, der sich um das Grabmal kümmert.', },
    {'Begebt Euch zu Uthers Grabmal und verwendet den Eiswindtribut vor seiner Statue.', },
  },
  [27170] = {
    'Die verlassene Gruft',
    {'Wenn Ihr die Schlacht um Andorhal wirklich vorantreiben möchtet, kann ich Euch vielleicht helfen.|n|nÖstlich von hier befindet sich eine große Gruft. Der untere Teil der Gruft wurde einst für die Aufbewahrung von Waffen und Rüstung benutzt - bis die Geißel kam. Jetzt, da die Untoten nicht mehr hier sind, können diese Waffen benutzt werden.|n|nDie meisten Waffen sind wohl rostig und alt, aber trotzdem besser für unsere Zwecke geeignet als Tuniken und Heugabeln.', },
    {'Findet die Waffenkiste unten in der Gruft in den Westlichen Pestländern.', },
  },
  [27171] = {
    'Hinterhalt!',
    {'Als Ihr Euch umdreht, seht Ihr die Silhoutten der torkelnden Skelette auf den Stufen.|n|nDie Untoten haben die Gruft nicht verlassen. Sie haben hier gewartet! Außerdem scheinen sie die Waffen zu tragen, wegen denen Ihr hier seid.|n|nIhr müsst aus der Gruft fliehen. Versucht, auf dem Weg nach draußen so viel Ausrüstung wie möglich zu ergattern.', },
    {'Erhaltet 4 abgenutzte Brustplatten und 4 verrostete Schwerter.', },
  },
  [27172] = {
    'Das Trostlose Feld',
    {'Die Bauern haben sich aufgemacht zum Trostlosen Feld, einem alten Bauernhof nordöstlich von hier, auf der anderen Seite des Flusses. Jemand muss sie im Auge behalten.|n|nBringt ihnen diese rostigen Waffen und die Rüstungen, die Ihr gefunden habt. Wir können nicht zulassen, dass sie mit Heugabeln kämpfen.', },
    {'Bringt die ramponierten Waffen und Rüstungen zu Thurman Grant zum Trostlosen Feld in den Westlichen Pestländern.', },
  },
  [27173] = {
    'Dies ist unsere Armee',
    {'Ich habe Kommandant Ehrenschlag darüber unterrichtet, dass wir uns selbst verteidigen können, und das haben wir auch vor. Ich hatte auf meinem Weg hierher ein kurzes Gespräch mit Thassarian, diesem Kriegsherrn der Todesritter. Wir Bauern haben vor, auf unsere eigene Art und Weise zu helfen.|n|nWir werden diesen Bauernhof einnehmen, das Land kultivieren... und wenn die Schlacht um Andorhal beginnt, werden wir die Verlassenen vom Hinterland aus angreifen. Damit werden sie nicht rechnen.|n|nZuerst müssen wir uns der Vorhut der Verlassenen widmen. Tötet einige von ihnen, und kommt dann wieder zu mir.', },
    {'Tötet 10 Streitkräfte der Vorhut der Verlassenen.', },
  },
  [27174] = {
    'Kampftraining',
    {'Vielleicht könnt Ihr tatsächlich ein paar meiner Männer ausbilden. Ihr habt wahrscheinlich die Monstrosität da draußen bemerkt. Wir haben zuerst versucht, sie zu bekämpfen, aber sie hat sich nicht gewehrt. Es scheint, als ob sie auf dem Bauernhof helfen möchte.|n|nNehmt vier meiner Männer und fordert die Monstrosität zum Kampf heraus. Sie scheint stark zu sein, aber eine Monstrosität gegen fünf von Euch sollte Euch doch Chancen auf einen Sieg geben.', },
    {'Sprecht mit Gory im Trostlosen Feld und fordert ihn zum Kampf heraus.', },
  },
  [27175] = {
    'Die Stätte der Heiler',
    {'Die Männer und Frauen in Zugwindlager haben ehrenhafte Ziele, doch letztendlich ist der Krieg ihre Absicht. Ich möchte Euch die Möglichkeit geben, friedlichere Ziele zu verfolgen.|n|nNördlich vom kriegsgebeutelten Andorhal befindet sich die Stätte der Heiler. Der Argentumkreuzzug hat sich dort mit dem Zirkel des Cenarius verbündet. Zusammen arbeiten wir daran, das Land von der Seuche zu heilen, die hier so lange herrschte.|n|nSeid Ihr daran interessiert, Euch unserer Sache zu widmen, $C?', },
    {'Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.', },
  },
  [27176] = {
    'Nur die Spitze',
    {'Die Ätztechnik, die auf der Oberfläche des Objektes verwendet wurde, weist auf jahrtausendealte Arbeit hin. Und doch ist kein Verschleiß erkennbar.|n|nDieses Loch am Rand, das voller Holzsplitter ist, verrät, dass es wahrscheinlich auf einem Holzstab oder etwas in der Art angebracht wurde.|n|nMacht Euch auf den Weg, um den fehlenden Stab zu finden, bevor wir diesen Fund Doktor Jones zeigen.', },
    {'Erhaltet den Stab des Sultans und benutzt die aufwendige Scheibe, um den Schaft der Sterne zu erstellen.', },
  },
  [27177] = {
    'Bergungsaktion',
    {'Unsere Flotte wurde durch die Horde und die Naga stark geschwächt. Wir können die Männer, die ihr Leben dem Meer gelassen haben, nicht zurück zum Leben erwecken, aber nur über meine ertrunkene Leiche werde ich zulassen, dass alle unsere Ladungen auf immer verloren gehen.|n|nSchwimmt zum Obsidianbrecher südwestlich von Hochufer und bergt die Ladungen der gesunkenen Schiffe vom Meeresboden.', },
    {'Bergt 8 wiedergefundene Vorräte aus den durchnässten Kisten in Obsidianbrecher.', },
  },
  [27178] = {
    'Verstärkung der Naga',
    {'Sie kommen aus der Tiefe des Ozeans angeglitscht, $N. Die Naga. Ich denke, sie haben vor, die Bastion des Zwielichts zu verstärken, und werden wahrscheinlich den Verrall nutzen, um weiter ins Land vorzudringen. Wir dürfen das nicht geschehen lassen!|n|nZeigt ihnen, dass die Ufer nun die unseren sind, und sorgt dafür, dass sie schnell wieder zurück in die dunklen Tiefen huschen.|n|nTötet die Schwarzschuppen-Naga, die sich ihren Weg durch Obsidianbrecher bahnen!', },
    {'Tötet 10 Myrmidonen der Schwarzschuppen oder Seeruferinnen der Schwarzschuppen.', },
  },
  [27179] = {
    'Feldarbeit',
    {'Dieser bedauernswerte Pygmäe war zur falschen Zeit am falschen Ort.|n|nAls Ihr über sein Unglück sinniert, bemerkt Ihr die Symbole auf seinem Schild. Sie sind viel zu aufwendig für Pygmäengekritzel.|n|nIhr seid davon überzeugt, dass Doktor Jones ein Objekt wie dieses hochinteressant finden wird, und macht Euch auf, um weitere Fragmente wie dieses zu finden.', },
    {'Sammelt 10 uralte Tafelfragmente.', },
  },
  [27180] = {
    'Ehret die Toten',
    {'Ein Konvoi erfahrener Truppen und Katapulte der Verlassenen wurden heute aus dem Hinterhalt angegriffen, als sie Olsens Acker südlich von hier überqueren wollten. Ein Totalschaden: alle Einheiten wurden getötet und alle Katapulte vernichtet.|n|nDas Rudel von Blutfang ist für den Hinterhalt verantwortlich, allerdings sind sie wohl längst wieder in die Hügel geflüchtet, um sich auf ihren nächsten feigen Angriff vorzubereiten. Ihre Zeit wird kommen. Jetzt allerdings möchte ich, dass Ihr zu Olsens Acker geht und die Gefallenen ehrt.|n|nFindet die Insignien der Verlassenen.', },
    {'Findet 6 Insignien der Verlassenen bei den Leichnamen der Veteranengardisten der Verlassenen.', },
  },
  [27181] = {
    'Der Schmach ein Ende bereiten',
    {'Es scheint, als sei ein Teil der Wegelagerer hier geblieben. Lasst sie für diese Anmaßung teuer bezahlen! Tötet die Blutfangpirscher auf Olsens Acker. Für Sylvanas! Für die Horde!', },
    {'Tötet 10 Blutfangpirscher.', },
  },
  [27182] = {
    'Der Einsiedler des Hexenhügels',
    {'Die Marschen scheinen seltsame Auswirkungen auf die Menschen zu haben. So mancher wurde schon wahnsinnig, nur weil er dort lebte.|n|nJeder, der sich im Irrlichtanwesen niedergelassen hat, wurde auf ganz besondere Weise verrückt. Bei dem jetzigen Besitzer, man nennt ihn "Sumpfauge" Jarl, machen sich bereits einige Anzeichen bemerkbar.|n|nIch weiß zwar nicht genau, was dort vor sich geht, aber ich wäre Euch sehr dankbar, wenn Ihr dort nach dem Rechten sehen würdet.|n|nDas Anwesen liegt am östlichen Ende des Sumpfs. Lauft Richtung Osten durch das Blaumoor und vorbei an der Nordwacht. Die Gegend, in der das Anwesen liegt, ist ein verwunschener Flecken und heißt Hexenhügel.', },
    {'Sprecht mit "Sumpfauge" Jarl beim Irrlichtanwesen.', },
  },
  [27183] = {
    'Marschenfroschschenkel',
    {'Ich koche gern. Leckere Sumpfküche. Frittierte grüne Froschschenkel und dergleichen.|n|nLeider habe ich keine Froschschenkel mehr. Beim Anwesen wimmelt es nur so von Fröschen, riesigen Marschenfröschen. Könntet Ihr mir vielleicht ein paar dieser Schenkel bringen? Das ist halb so wild, ehrlich. Haut ihnen einfach auf den Kopf und bringt mir die Schenkel.|n|nDann mache ich einen Eintopf und topfe ihn ein und schlabber ihn aus und geb Euch auch was ab.|n|nMögt Ihr Eintopf?', },
    {'Sammelt 10 Marschenfroschschenkel von riesigen Marschenfröschen.', },
  },
  [27184] = {
    'Jarl braucht Augen',
    {'Augensaft ist ein leckeres Getränk. Leider haben die meisten Tierwesen nur zwei Augen.|n|nAber Spinnen haben eine Menge Augen. Jede Menge. Und Graunebelaugensaft ist lecker. Samtig und salzig! Unzerplatzte Spinnenaugen... Ich schmecke sie schon förmlich.|n|nGraunebelspinnen leben westlich von hier in den Graunebelhöhlen. Glaubt Ihr, die Spinnen wurden nach der Höhle benannt... oder ist es umgekehrt?', },
    {'Sammelt 20 unzerplatzte Graunebelaugen von Graunebelspinnen.', },
  },
  [27185] = {
    'Die Wettstreiter ausmerzen',
    {'Ich werd\' keine Spielchen mit Euch spielen. Der purpurrote Hammerschmied des scharlachroten Kreuzzugs war bisher nicht wirklich erwähnenswert, aber nun, da er zu einem von Balnazzars Auferstandenen geworden ist, hat der Schreckenslord ihm beigebracht, alle möglichen mächtigen und dämonischen Waffen herzustellen.|n|nDie Aufgabe ist einfach. Findet die Schmiedepläne und tötet den purpurroten Hammerschmied, wenn er kommt, um sie zu holen. So können wir sicherstellen, dass ihre Armee die dämonischen Waffen nicht in die Hände bekommt. Sie sind jetzt schon viel zu stark!', },
    {'Tötet den purpurroten Hammerschmied.', },
  },
  [27186] = {
    'Jarl braucht eine Klinge',
    {'Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... Ich brauche eine Klinge. Eine ganz bestimmte Klinge...|n|nManche Leute sprechen von einem Schwert. Ich nenne es eine Schwingklinge.|n|nHelft Ihr mir? Diese Fischmenschen, Murlocs, oder wie auch immer die heißen... Einer von ihnen wird Messerwirbel genannt, hat ständig so ein großes Schwert bei sich, lebt nördlich von hier am Strand. Ich brauche sein Schwert!|n|nAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...', },
    {'Besorgt Messerwirbels Schwert.', },
  },
  [27187] = {
    'Ein Gefallen für die Welt',
    {'Hyänen sind im besten Fall ein Ärgernis.|n|nDiese finsteren Wesen sind bösartig veranlagt, haben alle möglichen Krankheiten und sind nicht mehr als eine Seuche auf dem Antlitz der Hundewelt.|n|nTut der Welt einen Gefallen und befreit die Wüsten von Uldum von dieser räudigen Bedrohung.', },
    {'Tötet 12 räudige Hyänen.', },
  },
  [27188] = {
    'Was sucht den Hexenhügel heim?',
    {'Ich bin hierher gereist, um Jarl in seinem neuen Zuhause zu besuchen, aber seit meiner Ankunft nahm der Schrecken hier kein Ende! Hier stimmt etwas nicht... überhaupt nicht. Ich kann nicht der Einzige sein, der diese Dinge sieht.|n|nHabt Ihr die Geister und Leichname gesehen, die um den Hexenhügel umherstreifen? Wenn einer weiß, was hier vor sich geht, so befürchte ich, dass sie es sind. Haltet nach den auferstandenen Gebeinen und auferstandenen Geistern in der Umgebung Ausschau. Bekämpft sie und gewährt ihnen dadurch ihren verdienten Frieden. Verschafft Euch so viele Informationen wie möglich von ihnen, bevor Jarl dem Bösen vollends verfällt!', },
    {'Sammelt Informationen, indem Ihr 10 auferstandene Gebeine oder auferstandene Geister besiegt.', },
  },
  [27189] = {
    'Der Hexenfluch',
    {'In meiner Zeit als Kräuterkundiger habe ich oft feststellen können, dass die Natur stets raffinierte Heilmethoden für die ärgerlichsten Probleme bereithält. Ich habe gelesen, dass die unabhängigen Magier und Hexendoktoren häufig den Rauch einer Pflanze, die als Hexenfluch bekannt ist, verwenden, um das Böse aus seinem Versteck zu locken.|n|nFalls dem wirklich so ist, dann müsste Hexenfluch nahe der seichten Gewässer des Hexenhügels wachsen. Ihr solltet die Pflanze an ihren breiten Blättern und rötlichen Stängeln in der Mitte erkennen. Bringt mir so viele Pflanzen, wie Ihr finden könnt, $N. Es könnte unsere letzte Hoffnung sein.', },
    {'Sammelt 9 Zweige Hexenfluch am Hexenhügel.', },
  },
  [27190] = {
    'Die Reinigung des Hexenhügels',
    {'Die Fackel ist fertig. Stellt sie am Ende des Docks auf und seid auf alles gefasst.|n|nIch weiß wirklich nicht, was der Rauch der Fackel bewirken wird... falls überhaupt etwas geschieht. Eigentlich hege ich für gewöhnlich Zweifel an dererlei Hokuspokus, aber wir haben keine andere Wahl. Viel Glück, Ihr und Jarl könnt es brauchen.', },
    {'Platziert die Hexenfluchfackel am Ende des Anlegstegs und besiegt das Böse, das Hexenhügel heimsucht.', },
  },
  [27191] = {
    'Hungrig wie ein Oger!',
    {'Hier trifft man schon ab und an jemanden. Nette Leute. Hab mal einen Oger getroffen. Oger werden hungrig, genau wie ich.|n|nIch werde nie vergessen, was er gesagt hat. Er sagte: "Patsch großer Oger. Ich hungrig. Geht Fische hauen. Bringt Patsch Essen. Ihr füttert Patsch oder Patsch frisst Euch."|n|nIch hab ihm also Fische besorgt, und er hat die Fische gegessen. Und seitdem esse ich auch Fisch. Die Köpfe schmecken am besten, die sind so schön glitschig.|n|nZermalmt die Köpfe nicht. Das macht die Fische unglücklich. Traurige Köpfe schmecken nicht gut. Bringt mir glückliche Fischköpfe, und ich werde die Fischköpfe essen und auch glücklich sein.', },
    {'Sammelt 8 Schlammflossenköpfe von den Murlocs der Schlammflossen.', },
  },
  [27192] = {
    'Der große Fras Siabi',
    nil,
    nil,
  },
  [27193] = {
    'Suchen und zerstören',
    {'<Die Stimme der Bansheekönigin dringt erneut in Eure Gedanken ein.>|n|nSucht in den nahegelegenen Bauernhäusern nach Nachzüglern der Allianz. Haltet Eure Augen offen nach Informationen, die uns zu Crowley und Blutfang führen könnten. Sucht und zerstört alle, die sich Euch in den Weg stellen, $N!', },
    {'Durchsucht die Bauernhäuser auf Olsens Acker.', },
  },
  [27194] = {
    'In die Ecke gedrängt und zermalmt!',
    {'<Die Stimme der Bansheekönigin spricht zu Euch.>|n|nWir müssen schnell handeln, $N. Sie dürfen nicht die Gelegenheit bekommen, zu fliehen. Ich werde ein Geschwader meiner mächtigsten Soldaten zur Tiefenfelsmine schicken. Der Reiter wird sie begleiten, um sicherzustellen, dass alles nach Plan verläuft. Trefft ihn in der Tiefenfelsmine, östlich von Olsens Acker und ZERMALMT diese Ratten.', },
    {'Meldet Euch bei Meister Forteski in der Tiefenfelsmine im Silberwald.', },
  },
  [27195] = {
    'Es gibt keinen Ausweg',
    {'Die Herrin hat mich beauftragt, die Bande bei dieser Aufgabe zu führen. Unser Hauptziel ist es, in die Mine einzudringen, die Ratten in die Enge zu treiben und sie alle zu töten, auch Blutfang.|n|nIhr habt uns mit der Beschaffung dieser Informationen gute Dienste geleistet, $N. Habt am Ruhm teil und helft uns dabei, unsere Schwerter durch ihre elenden Schädel zu jagen.|n|nLasst mich wissen, wenn Ihr bereit seid, und ich werde zum Angriff rufen.', },
    {'Begleitet Meister Forteski durch die Tiefenfelsmine.', },
  },
  [27196] = {
    'Irgendetwas geht vor sich',
    {'Ihr habt bemerkenswerte Arbeit geleistet! Vor allem für jemanden, der nie einen meiner Kurse besucht hat.|n|nDiese Tafeln geben uns neue Informationen zu verschiedenen Themen.|n|nSie weisen darauf hin, dass diese Obelisken Teil eines riesigen, uralten Mechanismus sind, der diese Gegend einst vor dem Rest der Welt versteckt hielt.|n|nAußerdem zeigen sie auch auf, wie der Mechanismus wieder in Gang gebracht werden kann. Hier kommt der Schaft der Sterne ins Spiel...|n|nMacht Euch bereit, $N. Es gilt, Geschichte zu schreiben!', },
    {'Begleitet Harrison Jones zur Kammer der Sterne.', },
  },
  [27197] = {
    'Die Schlacht geht weiter!',
    {'Es gibt Nachrichten aus Andorhal, $N. Die Schlacht hat wieder angefangen.|n|nUnter den Streitkräften der Allianz ist es wohl bekannt geworden, dass Ihr Euch als einer der Helden der ersten Schlacht um Andorhal hervorgetan habt. Thassarian verlangt umgehend nach Eurer Anwesenheit.', },
    {'Meldet Euch bei Thassarian in Andorhal in den Westlichen Pestländern.', },
  },
  [27198] = {
    'Die Truppen unterstützen',
    {'Ich bin kein Militärexperte, aber diese Schlacht scheint zu unseren Gunsten zu stehen. Unsere Verteidiger sind nicht besser als die Todeswachen unserer Gegner, aber die Bauernmiliz hat sie mit dem Angriff aus dem Hinterland überrascht. Für die Allianz!|n|nWir müssen trotzdem alles tun, was in unserer Macht steht, um einen Sieg zu sichern. Reist nach Andorhal östlich von hier und tötet die Todeswachen der Verlassenen, die mit unseren Männern kämpfen. Je schneller sie sterben, umso eher können wir Andorhal wieder unser Eigen nennen!', },
    {'Tötet 15 Todeswachen von Andorhal.', },
  },
  [27199] = {
    'Asche zu Asche',
    {'Östlich von hier, tief im von den Verlassenen gehaltenen Andorhal, werdet Ihr ihre Kommandanten anfinden. Sie kämpfen nicht, sondern befehligen nur von den Rücken ihrer Pferde.|n|nJagt und tötet diese Kommandanten, $N. Die Verlassenen werden machtlos sein.', },
    {'Tötet 3 Kriegshauptmänner der Todeswache.', },
  },
  [27200] = {
    'Sirenenlied',
    {'Sie ist immer noch anzutreffen... Ophelia, die Sirene des Hochlands! Ihr schreckliches Lied wird Euch in die Tiefen locken. Ich habe geschworen, hier zu bleiben und meine gefallenen Besatzungsmitglieder zu rächen, $C. Wenn Ihr mich unterstützen wollt, müsst Ihr nur den Mund aufmachen.|n|nWir werden uns an den Mast binden, oh ja. Wir werden unsere Augen schließen. Wir werden unsere Ohren mit Wachs ausstopfen. Und wenn ihre schöne Illusion vergeht... werden wir angreifen.|n|nKann ich auf Euch zählen?', },
    {'Tötet Ophelia, die Sirene des Hochlands.', },
  },
  [27201] = {
    'Angriff der Val\'kyr',
    {'Die Val\'kyr waren einst die mächtigste Waffe der Geißel. Sie waren nicht nur fähig im Kampf, sondern konnten auch benutzt werden, um Leichen in Diener der Geißel zu verwandeln. Es fällt mir schwer zu glauben, dass Sylvanas sich um der Verlassenen willen zu solchen Methoden herablässt... |n|nWir müssen die Val\'kyr aufhalten, bevor sie uns ausschalten und unsere Armee gegen uns wenden. Tötet so viele, wie Ihr finden könnt. Nehmt ein paar dieser Freiwilligen mit Euch. Wenn sie bis jetzt überlebt haben, haben sie wohl doch etwas Kampfgeschick.', },
    {'Tötet 9 niedere Val\'kyr in Andorhal.', },
  },
  [27202] = {
    'Bruder gegen Bruder',
    {'Unsere Miliz wurde fast vollständig ausgemerzt. Nur ich und diese paar Bauern sind noch übrig.|n|nDiese beflügelten Kreaturen... sie haben die Leichen unserer Männer genommen... und sie in laufende, untote Leichname verwandelt! Mit jedem einzelnen, den sie von uns genommen haben, haben sie ihre eigenen Ränge verstärkt.|n|nEs fällt mir schwer es zuzugeben, aber Ihr werdet auch sie bekämpfen müssen, zusammen mit den Todeswachen und den Val\'kyr. Wie sie es auch in ihrem früheren Leben gemacht haben, jagen sie in Gruppen. Nehmt ein paar der Freiwilligen mit Euch.', },
    {'Tötet 20 Reitersoldaten der Verlassenen in Andorhal.', },
  },
  [27203] = {
    'Der Mahlstrom',
    {'Dank den Geistern, dass Ihr hier seid, $N.|n|nWir wissen nicht, wie lange wir den Riss im Mahlstrom noch erhalten können.|n|nUnsere mächtigsten Mitstreiter, die von Thrall angeführt werden, können den Einriss kaum aufhalten.|n|nDer letzte Stand ist, dass unsere einzige Hoffnung darin liegt, durch die Öffnung zu steigen und zu versuchen, sie von der anderen Seite aus zu stabilisieren.|n|nIch werde ein Portal herbeizaubern. Benutzt es und meldet Euch bei Thrall, so bald Ihr könnt.', },
    {'Geht durch das Portal in den Mahlstrom und sprecht mit Thrall.', },
  },
  [27204] = {
    nil,
    {'Unsere letzte Hoffnung auf einen Sieg ist die Bezwingung der Val\'kyr. Bisher habt Ihr gute Arbeit geleistet... Ihr seid aber auch nur $Gein Mann:eine Frau; gegen wortwörtlich Dutzende, die Zerstörung auf das Schlachtfeld bringen.|n|nEine riesige Val\'kyr sitzt auf einem Turm südlich von hier... Ihr könnt sie von hier sehen. Wenn wir sie beseitigen, werden die restlichen Val\'kyr sich vielleicht zerstreuen.|n|nEs ist unsere einzige Hoffnung. Nehmt ein paar von Grants Männern mit. Ihr werdet für diesen Kampf Schutz benötigen.', },
    {'Tötet Aradne auf dem Turm im westlichen Teil von Andorhal.', },
  },
  [27205] = {
    'Die Verderbtheit der Verlassenen',
    {'Wir haben diese Schlacht fast gewonnen, $N. Ich kann den Sieg förmlich schmecken. Die Verlassenen hatten nie ein...|n|nWas zum Teufel ist das!?', },
    {'Findet heraus, was Thassarian anschaut.', },
  },
  [27206] = {
    'Weh dir, Andorhal',
    {'Begebt Euch nach Süden, nach Zugwindlager. Berichtet Kommandant Ashlam Ehrenschlag von allem, was hier vorgefallen ist.|n|nIch? Ich gehe nach Westen, nach Tirisfal.|n|nMeine Schlacht ist noch nicht abgeschlossen. Ich habe ein Treffen mit einer Harpyie, die sich die Bansheekönigin nennt... und ich werde herausfinden, was sie Koltira angetan hat.', },
    {'Berichtet Kommandant Ashlam Ehrenschlag von den Ereignissen der Schlacht von Andorhal.', },
  },
  [27207] = {
    'Es ist windig',
    {'DAS ist also der Grund für die Stürme, die meine Stadt heimsuchen?|n|nLasst uns dagegen vorgehen. Dieser riesige Schaumschläger kann brüllen und pusten, so viel er mag; sein Ende ist nahe. Berichtet General Marcus Jonathan von den Vorfällen hier, wenn wir zurückgekehrt sind. Ich muss mich um die Rückkehr der Bürgerschaft, Reparaturen und dergleichen kümmern.', },
    {'Tötet Prinz Sarsarun und erstattet General Marcus Jonathan in Sturmwind Bericht.', },
  },
  [27208] = {
    'Der Schreckenslord Balnazzar',
    {'Mit dem Untergang des Scharlachroten Kreuzzugs entließ der getarnte dämonische Anführer Balnazzar den besessenen Körper des Obersten Kreuzfahrers Dathrohan und begab sich auf einen Amoklauf, bei dem er auch den letzten überlebenden Kreuzfahrer in den Tod riss. Dann nutzte er seine nekromantischen Kräfte, um sie zu widerwärtigen untoten Sklaven zu machen.|n|nBalnazzar nennt diese neue Armee die Auferstandenen. Wir können nicht zulassen, dass diese Armee noch größer wird. Diese Krieger sind äußerst mächtig, und im Gegensatz zu Arthas\' Geißel wird Balnazzar seine Streitmächte nicht zurückhalten. Tötet ihn, solange wir noch in der Lage dazu sind, $C.', },
    {'Tötet Balnazzar.', },
  },
  [27209] = {
    'Es ist windig',
    {'Nun wissen wir, welches Übel hinter den Angriffen auf Donnerfels liegt.|n|nLasst uns etwas unternehmen. Es ist an der Zeit, dieser Monstrosität ein Ende zu bereiten.|n|nBerichtet Hamuul Runentotem von den Vorfällen hier, wenn wir zurückgekehrt sind. Ich muss mich um die Rückkehr der Bürgerschaft, Reparaturen und dergleichen kümmern.', },
    {'Tötet Prinz Sarsarun und erstattet Hamuul Runentotem in Donnerfels Bericht.', },
  },
  [27210] = {
    'Verräter unter uns',
    {'Schön, Euch zu sehen, $C. Ich bin nach Theramore gekommen, um bei der Lösung des Problems mit den Deserteuren zu helfen. Einige der Männer haben nicht nur ihren Posten verlassen, nein, sie haben sich zurück in die Stadt geschlichen.|n|nDiese Agenten der Deserteure verbreiten Lügen und Propaganda. Sie erhoffen sich davon, andere von ihrer Sache zu überzeugen, damit sie sich ihnen anschließen.|n|nSie sind nahezu bei jedem Wachposten der Stadt und bei den Docks. Findet sie, entlarvt sie und diskreditiert sie. Im Moment würde alles andere nur dazu führen, dass sie an Sympathie gewinnen.', },
    {'Konfrontiert 5 Aufwiegler der Deserteure in Theramore.', },
  },
  [27211] = {
    'Propagandakrieg',
    {'Die Agenten der Deserteure haben weitaus mehr getan, als nur die Wachen zu beschwatzen. Wir haben eine Reihe von Handzetteln gefunden, die die Deserteure scheinbar auf einem Schiff zu den Docks geschmuggelt haben.|n|nDas Schiff, auf dem die Handzettel geladen waren, liegt noch immer in Theramore bei dem am weitesten entfernten Dock vor Anker. Wenn Ihr Euch heimlich an Bord schleichen und das restliche Propagandamaterial in Beschlag nehmen könntet, würden die Agenten ihre wichtigste Waffe verlieren. Seid auf der Hut! Das Schiff ist mit erfahrenen Freibeutern bemannt und die Fracht befindet sich womöglich in der Kajüte des Kapitäns.', },
    {'Erhaltet das Propagandamaterial der Deserteure vom Schiff am Ende der Docks in Theramore.', },
  },
  [27212] = {
    'Diskreditierung der Deserteure',
    {'Ich habe die Handzettel, die Ihr den Söldnerkumpanen der Deserteure beim Dock abgenommen habt, verfälscht. Jeder, der diese Zettel jetzt lesen wird, erhält mit Sicherheit einen ganz anderen Eindruck von den Deserteuren und ihren Absichten.|n|nWenn wir genug davon an die Wachen verteilen, wird es den Deserteuren einfach zu peinlich sein, hier jemals wieder Fuß zu fassen.|n|n<Calia überreicht Euch einen Stapel verfälschte Handzettel.>|n|nFangt doch schon einmal an, während ich den nächsten Schritt plane.', },
    {'Verteilt verfälschte Handzettel an 6 Wachen von Theramore.', },
  },
  [27213] = {
    'Das Ende der Deserteure',
    {'Jetzt, da wir die Deserteure aus Theramore vertrieben haben, ist es an der Zeit, unseren Plan zu Ende zu bringen. Meine Kontakte vor Ort haben mir berichtet, dass die Operationsbasis der Deserteure ein Schiff ist, das bei einer kleinen Insel südöstlich der Docks vor Anker liegt.|n|nDie Festnahme ihres Anführers, Gavis Grauschild, wird die anderen entmutigen. Macht ihn innerhalb des Schiffs ausfindig und überzeugt ihn davon, zu kapitulieren. Es würde mich nicht überraschen, wenn er sich mit einem spektakulären Kampf zur Wehr setzt, aber aufgibt, sobald er verstanden hat, dass er nicht gewinnen kann.', },
    {'Besiegt Gavis Grauschild auf dem Schiff südöstlich von Theramore.', },
  },
  [27214] = {
    'Beunruhigende Berichte',
    {'Unsere Spähpatrouillen haben in letzter Zeit Beunruhigendes zu Tage gefördert. Sie berichten von Männern mit roten Kopftüchern der Defias, die entlang der Schreckensmoorküste nördlich von Theramore umherwandern.|n|nWrackteile in dieser Gegend lassen darauf schließen, dass es sich um Überlebende eines Schiffbruchs handelt, aber uns mangelt es an Informationen. Hauptmann Wymor bei der Späherwacht, einem Wachturm nördlich der Stadt, sucht nach einem Helfer, der diesen Berichten nachgeht.', },
    {'Erstattet Hauptmann Wymor bei der Späherwacht Bericht.', },
  },
  [27215] = {
    'Der Einsiedler beim Irrlichtanwesen',
    {'Es gibt da einen Burschen, die Einheimischen nennen ihn "Sumpfauge" Jarl, der alleine draußen im Sumpf lebt. Vor nicht allzu langer Zeit hat er sich im Irrlichtanwesen einquartiert, nachdem die vorherigen Bewohner unter geheimnisvollen Umständen verschwunden sind.|n|nVon Zeit zu Zeit schicke ich jemanden aus, um dort nach dem Rechten zu sehen. Wisst Ihr, irgendwie erinnert er mich an meinen Großvater. Manche sagen, dass er nicht alle Tassen im Schrank hat.|n|nDas Irrlichtanwesen befindet sich in der Gegend beim Hexenhügel. Folgt der Straße von Theramore aus in Richtung Nordwesten, Ihr werdet das Anwesen finden, bevor die Straße in Richtung Westen abbiegt.', },
    {'Sprecht mit "Sumpfauge" Jarl beim Irrlichtanwesen.', },
  },
  [27216] = {
    'Der alte Leuchtturm',
    {'Der alte Leuchtturm draußen im Osten ist schon seit langem nicht mehr funktionstüchtig. Babs Zischeldrill hat es sich allerdings in den Kopf gesetzt, den ganzen Betrieb wieder zum Laufen zu bringen.|n|nIch weiß zwar nicht, wie sie das alleine bewerkstelligen will, aber sie behauptet, dass die Schiffe und ihre Fracht dann wesentlich sanfter zu den Docks gelangen. Was kann ich dagegen noch einwenden? Man sollte sich nicht über die Arbeit auf den Docks beschweren, wenn man bedenkt, dass man genauso gut an vorderster Front stehen könnte, oder?', },
    {'Sprecht mit Babs Zischeldrill bei dem Leuchtturm auf der Insel östlich von Theramore.', },
  },
  [27217] = {
    'Drescheröl',
    {'Im alten Logbuch des Leuchtturms steht, dass die Lampe mit dem Öl von Dreschern, die entlang der Küste hier leben, betrieben wurde.|n|n<Babs rümpft bei der Erwähnung dieser veralteten Technologie ihre Nase.>|n|nIch vermute, dass es sich hierbei um eine praktische, wenn auch unelegante Lösung handelt. Im Logbuch wurde vermerkt, dass das Öl von jungen Düsterdreschern am besten funktioniert. Man findet sie genau unterhalb der Docks von Theramore.|n|nWürdet Ihr mir helfen, den Leuchtturm wieder mit Öl zu versorgen?', },
    {'Sammelt 4 Behälter mit Drescheröl von den Düsterdreschern unter den Docks von Theramore.', },
  },
  [27218] = {
    'Heimtückische Bewohner der Tiefe',
    {'Wisst Ihr was? Es ist erstaunlich, was man alles in diesem alten Leuchtturm finden kann. Nachdem ich die Lampe angezündet hatte, bemerkte ich dieses Buch in einem dieser alten Koffer da oben.|n|n<Babs hält das Buch in die Höhe und liest den Titel mit lauter und dramatischer Stimme vor.>|n|n"Heimtückische Bewohner der Tiefe!"|n|nBeim Anblick einer dieser Bestien wäre ich bestimmt in Ohnmacht gefallen! Sicherlich ist es den einen oder anderen Lacher wert, aber mir fehlt momentan einfach die Zeit zum Lesen.|n|nIch kenne da aber jemanden, dem diese Lektüre gefallen könnte... der alte Fischhändler bei den Docks, Michael "Schmutz" Fink. Er sammelt alte Bücher.', },
    {'Bringt das Buch "Heimtückische Bewohner der Tiefe" zu Michael "Schmutz" Fink bei den Docks von Theramore.', },
  },
  [27219] = {
    'Ist das wahr?',
    {'Oh, ich bin mir sicher, dass Ihr und Babs bei einigen der haarsträubenden Beschreibungen und Zeichnungen im Buch laut aufgelacht habt. Aber habt Ihr Euch auch mal überlegt, dass an diesen Legenden etwas Wahres dran ist?|n|nWenn Ihr gut genug aufpasst, dann könnt Ihr die Seefahrer mit Sicherheit noch über Tethyr reden hören, die Meereskreatur, die laut dem Buch genau hier lebt! Wenn Ihr ganz sicher gehen wollt, dann könnt Ihr natürlich den alten Nat Pagle fragen.|n|nIhr findet ihn bei seinem Angelplatz auf einer kleinen Insel in der Tidenbucht, welche südwestlich jenseits der Bucht der Düstermarschen liegt.', },
    {'Sprecht mit Nat Pagle bei Nats Angelplatz in den Düstermarschen.', },
  },
  [27220] = {
    'Nats Abmachung',
    {'Ihr habt also eine Kopie von "Heimtückische Bewohner der Tiefe", ist das so? Nun, aus meiner Erfahrung heraus kann ich Euch sagen, dass alles wahr ist. Ich habe sogar ein paar dieser Biester mit meinen eigenen Augen gesehen.|n|nIhr wollt aber etwas über Tethyr erfahren. Ich sagte ja bereits, dass ich Euch ein Angebot machen würde, also hört gut zu. Ich arbeite an einer neuen Art von Köder, habe diesen hier aber noch nicht getestet.|n|nNehmt diese Paste - ja, sie stinkt etwas faulig - beschmiert Euch damit selbst und schwimmt rüber zu dem Schiffswrack im Südwesten. Solltet Ihr überleben, dann lasst mich wissen, wie es war!', },
    {'Schmiert Euch mit Pagles Fischpaste, extra stark ein und schwimmt dann hinaus in die Tidenbucht.', },
  },
  [27221] = {
    'Oh, es ist wahr!',
    {'Ja, Tethyr gibt es wirklich. Das Monster lebt in den Gewässern rund um Theramore.|n|nEs mag sehr gerne helle Lichter, deshalb hat man den Leuchtturm überhaupt erst geschlossen, versteht Ihr...|n|nWenn Ihr den Turm wieder in Betrieb nehmt, wird das Biest sofort wieder auftauchen. Natürlich würde niemand mit einem klugen Menschenverstand dergleichen tun.|n|nDas ist also Euer Plan! Es war schön, bei einem Bierchen mit Euch plaudern zu können, aber gebt dem alten Nat bloß nicht die Schuld, wenn Tethyr Euch WIRKLICH in einen Fischköder verwandelt. Bevor Ihr Euren Plan in die Tat umsetzt, sprecht auf jeden Fall mit Major Mühlens bei den Docks von Theramore.', },
    {'Sprecht mit Major Mühlens bei den Docks von Theramore.', },
  },
  [27222] = {
    'Bezwingt Tethyr!',
    {'Meeresungeheuer hin oder her, wir werden auf keinen Fall die Sicherheit unserer Schiffe aufs Spiel setzen. Ich habe unsere besten Schützen angewiesen, sich auf eine Begegnung mit Tethyr vorzubereiten. Die Artilleristen haben die Verteidigung der Docks mit drei Mörsern verstärkt.|n|nIch werde den Befehl zum Entzünden der Leuchtturmlampe erteilen. Falls Tethyr angreift, müsst Ihr die Mörser bedienen und das Biest bezwingen, bevor es alle Schützen tötet. Ich würde nicht zu lange an einer Stelle bleiben. Die Verwendung der Mörser wird mit Sicherheit die Aufmerksamkeit des Ungeheuers erregen.', },
    {'Benutzt die Mörser, um Tethyr zu besiegen.', },
  },
  [27223] = {
    'Vergeltung',
    {'Dort, wo die Marktgasse auf die Feststraße trifft, werdet Ihr auf den Unverziehenen treffen. Wenn Ihr alle auf dem Kreuzzüglerplatz tötet, werdet Ihr auch Timmy den Grausamen erwischen. Diese beiden ehemaligen Champions haben den Unschuldigen hier gegenüber schreckliche Taten vollbracht, um unheilige Macht zu erlangen.|n|nIhr müsst sie beide besiegen, um Stratholme von ihrer finsteren Anwesenheit zu befreien. Seid wachsam, denn sie waren zu Lebzeiten mächtige Kämpfer, und durch den Erhalt ihrer neuen dunklen Kräfte wurden sie nur noch stärker.', },
    {'Tötet den Unverziehenen und Timmy den Grausamen.', },
  },
  [27224] = {
    'Andorhal, Phase: Flagge',
    nil,
    nil,
  },
  [27225] = {
    'Aufforderung von Ander Germaine',
    {'Ander Germaine hat verlauten lassen, dass er Euch für Euren meisterhaften Umgang mit den Waffen und Eurer Zuschreibung zur Allianz ehren möchte. Macht Euch auf nach Sturmwind und verlasst das Altstadtviertel durch den südlichen Ausgang. Ihr werdet ihn in seiner Kommandozentrale finden. Ich weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.', },
    {'Sprecht mit Ander Germaine in der Kommandozentrale von Sturmwind.', },
  },
  [27226] = {
    'Um ein Seebärenhaar',
    {'Dem Kriegshäuptling sei Dank, dass Ihr hier seid, $N. Mir ist ein schwerwiegender Fehler mit den Seebären unterlaufen und ich brauche Eure Hilfe, um die Sache wieder gerade zu biegen.|n|nIch habe sie stocknüchtern losgeschickt, um gegen die Worgen zu kämpfen, die von der Insel Fenris kamen. Sie haben die Bestien angegriffen und haben ordentlich was einstecken müssen. Viele sind gefallen, aber ein paar leben noch und kämpfen nun um ihr Leben.|n|nBringt dieses Bierfass zu den Verfallenen Feldern östlich von hier und seht zu, dass kein Schluck übrig bleibt.', },
    {'Weckt 8 orcische Seebären auf.', },
  },
  [27227] = {
    'Baron Aurius Totenschwur',
    {'Diese Kapelle ist das letzte Licht in der wachsenden Dunkelheit. Ras Frostraunen nahm sich auf dem Schlachthof sein Leben und schlitzte vor dem Lichkönig sein Gesicht in ein makabres Lächeln. Der Lichkönig nahm sich seiner an und machte ihn zu dem Lich, der jetzt Scholomance heimsucht.|n|nDer Ort, an dem diese Gräueltat geschah, ist nun heiliger Boden der Geißel, und wurde vom Lichkönig mit der dunkelsten aller Magie gesegnet. Baron Aurius Totenschwur, der neue Herrscher von Stratholme, bewacht diesen Ort und führt die grausame Arbeit seines Meisters fort. Tötet ihn, ohne zu zögern.', },
    {'Tötet Baron Aurius Totenschwur.', },
  },
  [27228] = {
    'Mann gegen Monstrosität',
    {'Tief im Inneren werdet Ihr Ramstein den Verschlinger finden. Ich wage es kaum, Euch von den Gräueltaten zu erzählen, die dieses Monster vollbracht hat. Ihr müsst nur wissen, dass er den gesammelten Zorn zahlloser verirrter Seelen zu Gesicht bekommen soll; Zorn, den Ihr über ihn bringen werdet.|n|nHabt keine Gnade. Seid standhaft in Eurer Wut.', },
    {'Tötet Ramstein den Verschlinger.', },
  },
  [27229] = {
    'ZERMATSCHT DIE BRUTKÖNIGIN',
    {'<Der folgende Text ist in sehr großer Schrift geschrieben.>|n|nSPINNEN IN NORDHÖHLE BÖSE. VERGIFTEN OGER. OGER WERDEN KRANK. SCHLECHT!|n|nGROSSE RIESENSPINNE IN HÖHLE MACHT MEHR SPINNEN. MEHR SPINNEN SCHLECHT!|n|nTÖTET GROSSE SPINNE, AUFHALTEN NEUE SPINNEN. TÖTET GROSSE SPINNE, GROSSE BELOHNUNG! GUT!|n|n<Eine primitive Skizze wurde unter der Nachricht geschmiert.>', },
    {'Beschafft den Pedipalpus der Brutkönigin.', },
  },
  [27230] = {
    'Waffen für den Krieg',
    {'Die Geißel sind Meister im Schmieden mächtiger Waffen für ihre Krieger, und das macht es für unsere Männer schwieriger, sie zu töten! In der Nähe der Ziggurat von Baroness Anastari sind Schmiedekunstpläne, die der Oberste Schwertschmied nutzen wird, um eine äußerst mächtige Waffe für Lord Aurius zu schmieden.|n|nWir werden verhindern, dass diese Waffe geschmiedet wird, und gleichzeitig dafür sorgen, dass sie auch keine normalen Waffen mehr herstellen werden! Nehmt die Schmiedekunstpläne an Euch, und tötet den Schwertschmied der schwarzen Wache, wenn er kommt, um die Pläne zu verteidigen. Das wird unsere Aufgabe erleichtern.', },
    {'Tötet den Schwertschmied der schwarzen Wache.', },
  },
  [27231] = {
    'Verstärkung aus Fenris',
    nil,
    {'Tötet 10 Worgen des Hügellands.', },
  },
  [27232] = {
    'Rot gefärbte Gewässer...',
    {'<Das Kommunikationsgerät brummt.>|n|nDie Worgen, die Ihr getötet habt, waren der Spähtrupp. Hunderte von ihnen sind auf dem Weg! Es scheint, als haben Crowley und Blutfang allen Menschen in Lordaeron das Blutopfer angeboten.|n|nNehmt eine von diesen Kanonen der Horde und schickt sie dorthin zurück, wo sie herkommen. Färbt die Wasser des Lordameresees rot mit ihrem Blut!', },
    {'Tötet 50 Worgen des Hügellands mit der Kanone der Horde.', },
  },
  [27233] = {
    'Die Stätte der Heiler',
    {'Nun kann ich die Ausbildung selbst in die Hand nehmen. Falls Ihr nach Arbeit sucht, kann ich Euch empfehlen, der Straße nach Nordwesten zu folgen. Die Cenarischen Druiden und der Argentumkreuzzug haben dort auf Dalsons altem Hof ihr Lager aufgeschlagen. Vielleicht können sie Euch beschäftigen, bis wir hier wieder Hilfe benötigen.', },
    {'Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.', },
  },
  [27234] = {
    'Defias in den Düstermarschen?',
    {'Meine Späher haben von einem Schiffswrack nahe des Strands im Nordosten berichtet. Schiffswracks sind hier draußen zwar nichts Ungewöhnliches, aber den Berichten zufolge tragen die Überlebenden alle rote Kopftücher. Das ist das Symbol der Defias!|n|nAnscheinend hält sich ihr Anführer auf einer großen Insel in der Nähe der Küste nordöstlich des Turms auf. Tötet ihn, und nehmt alle Unterlagen an Euch, die Ihr bei ihm findet.', },
    {'Erhaltet die Befehle der Defias von Garn Mathers.', },
  },
  [27235] = {
    nil,
    {'Die von Euch erlangten Befehle weisen darauf hin, dass die Defias besonders erpicht darauf sind, ihre Fracht auszumachen und zu bergen.|n|nDer SI:7 arbeitete rund um Theramore eine Zeit lang mit dem Bergungstaucher Renn McGill zusammen. Als er von dem Schiffswrack erfuhr, machte sich Renn sofort auf den Weg nach Norden, um in der Nähe der Inseln, die von den Defias besetzt werden, zu tauchen.|n|nWenn wir vor den Defias an die Fracht gelangen wollen, werden wir seine Hilfe benötigen. Haltet in den Gewässern nordöstlich einer kleinen Insel nach ihm Ausschau. Sie liegt im Norden der Insel, die Ihr zuvor schon einmal besucht habt.', },
    {'Bringt die Befehle der Defias zu Renn McGill in den Gewässern nahe der Schreckensmoorküste.', },
  },
  [27236] = {
    'Tauchausrüstung aus zweiter Hand',
    {'Zwischen hier und der Insel Alcaz liegen zahlreiche Wrackteile auf dem Meeresgrund. Die Defias haben bereits Taucher entsandt, die die Gewässer absuchen. Mithilfe einiger ihrer Ausrüstungsteile könnten wir Euch so ausstatten, dass Ihr Euch der Jagd anschließen könnt. Ihr müsstet allerdings erst einen Weg finden, wie Ihr an diese "Leihgabe" kommt.|n|nSucht diese Insel nach einer Kiste mit einer Tauchausrüstung und etwas zum Reparieren ab. Wenn Ihr das Material gefunden habt, bringt es zu mir und ich werde es in null Komma nichts einsatzbereit machen!', },
    {'Bringt den Werkzeugsatz und die beschädigte Tauchausrüstung zu Renn McGill in den Düstermarschen.', },
  },
  [27237] = {
    'Bergt die Fracht!',
    {'Nun, ich konnte die Ausrüstung so reparieren, dass Ihr eine Weile damit tauchen könnt. Allerdings würde ich das Ganze nicht allzu lange auf die Probe stellen.|n|nDie Wrackteile des Schiffs sind auf dem Meeresgrund zwischen der Ostküste dieser Insel und der Insel Alcaz verstreut. Solange dieser Taucherhelm funktioniert, solltet Ihr versuchen, Teile des Wracks auszumachen. Verwendet diese Bergungsausrüstung, um die Wrackteile nach Spuren der Fracht zu durchsuchen. Gebt Acht, dass Ihr der Insel Alcaz nicht allzu nahe kommt. Diese Hydras sind gefährlich.', },
    {'Sammelt 1 geborgene Geldkassette.', },
  },
  [27238] = {
    'Jaina muss davon erfahren',
    {'Ihr müsst Lady Jaina sofort von Eurem Fund berichten! Wenn die Defias einen Gefangenen an Bord hatten, dann stellt sich die Frage, wer es war und ob diese Person noch am Leben ist!|n|nEines ist jedoch sicher, $N. Die Defias würden all diese Schwierigkeiten nicht aus bloßer Gehässigkeit auf sich nehmen. Ihr Gefangener muss jemand von Wichtigkeit sein. Lady Jaina kann mit Sicherheit mehr als jeder andere mit diesen Fundstücken anfangen. Ihr findet sie hoch oben im Magierturm im Zentrum von Theramore.', },
    {'Sprecht mit Lady Jaina Prachtmeer in Theramore.', },
  },
  [27239] = {
    'Insel Alcaz beobachten',
    {'Offenbar hatte Renn mit seinen Vermutungen über die Insel Alcaz Recht. Wir müssen diese Insel beobachten. Um dort hinein zu kommen, bräuchten wir allerdings eine ganze Brigade von Soldaten.|n|nTheramores Verteidigung könnte einen derartigen Schlag nicht überstehen, also habe ich mich mit Cassa Purpurschwinge, dem Greifenmeisterlehrling von Theramore, abgesprochen. Sie wird uns eines ihrer Tiere für die Beobachtung der Insel Alcaz aus der Luft überlassen.|n|nDie Insel birgt den Schlüssel zum Geheimnis darüber, in wie fern die Defias in dieser Entführung verwickelt sind.', },
    {'Sprecht mit Cassa Purpurschwinge und nutzt einen ihrer Greifen, um die Insel Alcaz zu beobachten.', },
  },
  [27240] = {
    'Beweis des Verrats',
    {'Onyxia wurde zwar entlarvt und vom Hofe entfernt, doch noch müssen diejenigen, die ihren Plan ausgeführt haben, die Defias, bestraft werden. Bringt König Varian Wrynn in Burg Sturmwind die Nachricht, dass die Defias für seine Entführung verantwortlich sind. Ich hege kaum Zweifel daran, dass der König die darin Verwickelten schnell und grausam bestrafen lassen wird.|n|nIch kann Euch mithilfe meiner Magie schneller nach Sturmwind bringen. Sagt einfach Bescheid, sobald Ihr bereit seid, $N.', },
    nil,
  },
  [27241] = {
    'Rückkehr zu Jaina',
    {'Ich muss mich darum kümmern, die Reste der Defias zu beseitigen. Bitte überbringt Lady Jaina in Theramore meinen Dank. Sie ist schon immer eine treue Freundin und loyale Verbündete gewesen.|n|nGeht zum Magierviertel im Westen der Stadt und sprecht dort am Fuße des Turms mit Erzmagier Malin. Er wird Euch rasch wieder nach Theramore bringen.', },
    {'Kehrt zu Lady Jaina Prachtmeer in Theramore zurück.', },
  },
  [27242] = {
    'Raptorenfänger',
    {'Im nordöstlichen Sumpfgebiet lebt eine ganz besonders gefährliche Raptorenart. Wir haben schon mehr als einen unachtsamen Soldaten an sie verloren. Ich denke jedoch, dass wir sie gegen unsere unliebsamen Nachbarn, die Grimmtotem, einsetzen könnten.|n|nNehmt dieses Seil und fangt damit Blutsumpfraptoren oder Blutsumpfkreischer ein, die Ihr zuvor überwältigt habt. Ich an Eurer Stelle würde sie zunächst im Kampf schwächen, bevor ich versuchen würde, sie einzufangen. Das wird ein ganz schön harter Kampf.', },
    {'Benutzt den strapazierfähigen Strick, um 6 Blutsumpfraptoren oder Blutsumpfkreischer zu fangen.', },
  },
  [27243] = {
    'Lasst die Raptoren los',
    {'Jetzt, da wir unsere Raptoren haben, besteht unser nächster Schritt darin, sie für einen Angriff auf die Grimmtotem im Dorf der Schwarzhufe im Nordwesten zu "animieren".|n|nIch habe hier noch eine übriggebliebene Lende von einem... nun, eigentlich ist es ja auch völlig egal, was es ist. Ihr werdet dieses Fleisch als Köder verwenden. Platziert es in der Nähe der Windmühle im Zentrum des Dorfes der Schwarzhufe. Die Raptoren werden sich um den Rest kümmern.', },
    {'Platziert den Raptorköder in der Nähe der Windmühle im Dorf der Schwarzhufe.', },
  },
  [27244] = {
    'Der verlorene Bericht',
    {'Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.|n|nDas Pergament ist ein Bericht von einem Orc, der die Stadt Theramore über Wochen ausspionierte.|n|nAls Ihr das Pergament überflogen habt, ist klar, dass es zum orcischen Spionagemeister in Brackenwall gebracht werden muss.', },
    {'Bringt den Bericht des Spions zu Nazeer Blutlanze in Brackenwall.', },
  },
  [27245] = {
    'Gefangene der Grimmtotem',
    {'Wir tun, was wir können, um die Räuber der Grimmtotem in Schach zu halten, aber sie greifen den Turm immer wieder an. Was noch viel schlimmer ist, die Späher unserer Patrouillen, die vom Hauptmann entsandt werden, um Informationen zu sammeln und die Straße zu sichern, wurden von ihnen entdeckt und entführt.|n|nIch vermute, dass die Gefangenen zum Dorf der Schwarzhufe im Nordwesten gebracht wurden. Wie ich die Grimmtotem kenne, tragen die Verteidiger des Dorfes die Schlüssel zu den Käfigen der Gefangenen bei sich. Mir ist egal wie, $C, aber bringt mir meine Männer lebend zurück.', },
    nil,
  },
  [27246] = {
    'Der Orcbericht',
    {'Beim Durchsuchen der lockeren Erde findet sich die abgetrennte Hand eines Orcs. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.|n|nDas Pergament ist in der Sprache der Orcs verfasst... und sieht wichtig aus.', },
    {'Bringt den Bericht des Spions zu Leutnant Aden in Theramore.', },
  },
  [27247] = {
    'Hauptmann Mumm',
    {'Hauptmann Mumm sollte den Orcbericht sehen, den Ihr gefunden habt, $N. Er kennt die Sprache der Orcs besser als die meisten. Und er sollte wissen, dass sich Spione der Horde bei Theramore aufhalten!|n|nDer Hauptmann befindet sich in der Kaserne auf der nordöstlichen Seite der Insel Theramore.', },
    {'Bringt den Bericht des Spions zu Hauptmann Garran Mumm.', },
  },
  [27248] = {
    'Mission nach Morastwinkel',
    {'Das Dampfdruckkartell hat vor Kurzem im südlichen Teil der Düstermarschen einen neuen Außenposten errichtet. Man taufte ihn Morastwinkel und er befindet sich entlang der Hauptstraße, südlich von Tabethas Hof und den Ruinen der Steinbrecher.|n|nDas ist eine hervorragende Gelegenheit für uns, neue Handelskontakte zu knüpfen, und Lady Jaina möchte, dass ich einen Abgesandten dorthin schicke, um Kontakt aufzunehmen. Würdet Ihr für uns dorthin reisen?', },
    {'Sprecht mit Drazzit Tropfhahn in Morastwinkel.', },
  },
  [27249] = {
    'Untersuchung der Ruinen',
    {'Der arme James, er ist nie ganz über die Zerstörung des Gasthauses "Zur Süßen Ruh" und den Tod seiner Familie hinweggekommen. Die Jungs und ich versuchen unser Bestmögliches, um die Monster, die dafür verantwortlich sind, zu finden.|n|nIch habe unseren besten Ermittlungsbeamten, Inspektor Tarem, zu den Ruinen geschickt. Einer allein wird mit dieser Aufgabe aber wohl kaum fertigwerden. Wir würden es wirklich zu schätzen wissen, wenn Ihr Tarem helfen würdet. Beim Licht, wir würden alle gern da draußen sein und mithelfen.|n|nDie Hauptstraße führt Euch direkt zum Gasthaus, aber seid vorsichtig, auf Eurer Reise seid Ihr auf Euch selbst gestellt. Meine Soldaten können Euch keinen Schutz bieten.', },
    {'Untersucht das Gasthaus "Zur Süßen Ruh" an der Grenze zwischen dem Brachland und den Düstermarschen.', },
  },
  [27250] = {
    'WIEDERVERARBEITUNG - SCHLECHTE KOPIE',
    {'Bevor ich hier im Blauen Eremiten arbeitete, wurde ich von einem der besten Küchenchefs und Gastwirte ausgebildet, die ich kenne. Sein Name war James Hyal. Alles, was ich besitze und im Leben erreicht habe, verdanke ich ihm.|n|nIch frage mich, was er wohl so treibt... Sein Bruder Vincent und er wollten in einer Taverne im Hafen von Menethil arbeiten, aber ich habe lange nichts von ihm gehört.|n|nWenn Ihr jemals in diese Gegend kommen solltet, könntet Ihr ihm dann Grüße von mir bestellen?', },
    {'Sprecht mit Vincent Hyal im Hafen von Menethil.', },
  },
  [27251] = {
    'Sie nennen ihn den lächelnden Jim',
    {'Ich kann nicht anders, der alte Jim da tut mir leid. Er war nicht immer so. Hatte eine Zeitlang ein Gasthaus im Sumpf, wunderbares Lokal.|n|nHört zu, ich will wirklich nicht darüber sprechen. Besprecht es mit Hauptmann Mumm, wenn es sein muss. Ihr findet ihn auf der obersten Etage der Wehrzitadelle, der großen Kaserne östlich von Lady Jainas Turm.', },
    {'Sprecht mit Hauptmann Garran Mumm auf der obersten Etage der Wehrzitadelle in Theramore.', },
  },
  [27252] = {
    'Der schwarze Schild',
    {'Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus "Zur Süßen Ruh" war.|n|nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.', },
    {'Bringt den geschwärzten Eisenschild zu Hauptmann Garran Mumm in Theramore.', },
  },
  [27253] = {
    'Untersuchung der Ruinen',
    {'Wenn Ihr der Straße vom Dorf aus nach Süden und dann westlich in Richtung Brachland folgt, werdet Ihr auf die Ruinen des Gasthauses "Zur Süßen Ruh" stoßen.|n|nTheramore hat einen Ermittlungsbeamten entsandt, um herauszufinden, von welchem Schicksal das Gasthaus heimgesucht wurde. Ich habe in dem Gasthaus einen Spion untergebracht und ich vertraue nicht darauf, dass diese Menschen kompetent genug sind, um in Erfahrung zu bringen, was damals passiert ist.|n|nEgal was Ihr findet, seht zu, dass der Ermittlungsbeamte es nicht in die Hände bekommt. Wir werden uns der Sache selbst annehmen.', },
    {'Erforscht das Gasthaus "Zur Süßen Ruh" an der Grenze Brachlands in Düstermarschen.', },
  },
  [27254] = {
    'Der schwarze Schild',
    {'Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus "Zur Süßen Ruh" war.|n|nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.', },
    {'Bringt den geschwärzten Eisenschild zu Krog in Brackenwall.', },
  },
  [27255] = {
    'Der schwarze Schild',
    {'Hmm... Ich sehe nichts Ungewöhnliches an diesem Schild. Do\'gol, der Schmied, sollte ihn sich ansehen. Vielleicht kann er uns mehr sagen, aber große Hoffnungen würde ich mir nicht machen...', },
    {'Zeigt den geschwärzten Eisenschild Do\'gol in Brackenwall.', },
  },
  [27256] = {
    'Der schwarze Schild',
    {'Hmmm, hier am Rand des Schildes steht etwas geschrieben, aber durch die Brandspuren kann man es kaum lesen.|n|nIch brauche Säure, um ihn zu reinigen. Das Gift der Graunebelspinnen sollte dafür ausreichen. Die Spinnen haben sich in einer alten Mine in den Graunebelhöhlen nordwestlich der Siedlung eingenistet. Bringt mir ihre Giftsäcke und ich reinige diesen Schild.', },
    {'Sammelt 5 Säuregiftbeutel von Graunebelspinnen.', },
  },
  [27257] = {
    'Der schwarze Schild',
    {'Oh, ich glaube, ich habe zu viel Säure auf den Schild geschüttet. Lasst mich ein wenig rubbeln...|n|nHm, schwer zu lesen, sieht aber wie der Name Mosarn aus. Nie von ihm gehört. Vielleicht weiß Krog etwas. Krog kennt viele Leute.', },
    {'Sprecht mit Krog in Brackenwall.', },
  },
  [27258] = {
    'Der schwarze Schild',
    {'Ah, jetzt erinnere ich mich! Mosarn ist ein angesehener Schmied in Donnerfels. Ich wusste, ich habe den Namen schon einmal gehört.|n|nAls Dank belohnte mich der Irdene Ring mit einem von Mosarn hergestellten Satz Rüstungen. Sehr gute Arbeit.|n|nVielleicht kann er Euch mehr über den Schild sagen, den er anfertigte.|n|nEs ist nicht viel, aber da wir aus Reethe nichts Nützliches herausbekamen, bleibt uns wohl nichts anderes übrig.', },
    {'Bringt den geschwärzten Eisenschild zu Mosarn in Donnerfels.', },
  },
  [27259] = {
    'Verdächtige Hufabdrücke',
    {'Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses "Zur Süßen Ruh" weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.', },
    {'Berichtet Krog in Brackenwall von den verdächtigen Abdrücken beim Gasthaus "Zur Süßen Ruh".', },
  },
  [27260] = {
    'Leutnant Paval Reethe',
    {'Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.|n|nUnter dem Anker ist der Name "Leutnant Paval Reethe" eingeprägt.', },
    {'Bringt Reethes Abzeichen zu Krog in Brackenwall.', },
  },
  [27261] = {
    'Befragt Reethe',
    {'Es hat lange gedauert, aber ich fand Reethe. Für einen Menschen hatte er sich gut versteckt.|n|nOgron hatte Angst, nach der langen Zeit im Sumpf könnte er verrückt sein. Ihr kommt mit mir, denn wir brauchen Antworten von ihm.', },
    {'Folgt Ogron und sprecht mit Reethe.', },
  },
  [27262] = {
    'Verdächtige Hufabdrücke',
    {'Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses "Zur Süßen Ruh" weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.', },
    {'Berichtet Hauptmann Garran Mumm in Theramore von den verdächtigen Abdrücken beim Gasthaus "Zur Süßen Ruh".', },
  },
  [27263] = {
    'Leutnant Paval Reethe',
    {'Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.|n|nUnter dem Anker ist der Name "Leutnant Paval Reethe" eingeprägt.', },
    {'Bringt Reethes Abzeichen zu Hauptmann Garran Mumm in Theramore.', },
  },
  [27264] = {
    'Leutnant Paval Reethe',
    {'Ich kenne den Namen Leutnant Paval Reethe nicht. Am besten erkundigt Ihr Euch bei Adjutant Tesoran. Er hat alle Aufzeichnungen über die Wachen von Theramore, vom Personal bis hin zur Ausrüstung.|n|nEr sollte Euch nach einem Blick in seine Bücher sagen können, wer dieser Reethe ist.', },
    {'Findet bei Adjudant Tesoran in Theramore mehr über Reethe heraus.', },
  },
  [27265] = {
    'Lord Grayson Schattenbruch',
    {'Lord Grayson Schattenbruch, einer der führenden Paladine des Reiches, hat Euch zu einem persönlichen Gespräch aufgefordert. Ich weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.|n|nIhr solltet Euch umgehend nach Sturmwind aufmachen und ihn in der Kathedrale des Lichts aufsuchen.', },
    {'Sprecht mit Lord Grayson Schattenbruch in der Kathedrale des Lichts in Sturmwind.', },
  },
  [27266] = {
    'Wulf ruft',
    {'Wulf Hansreim beaufsichtigt die Ausbildung und Koordination der Jäger im Dienst von Sturmwind. Er hat Euch zu einem persönlichen Gespräch gebeten. Reist nach Sturmwind, sobald es Euch möglich ist, und verlasst das Altstadtviertel durch das südliche Tor, um zu seinem Quartier zu gelangen.|n|nIch weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.', },
    {'Sprecht mit Wulf Hansreim in Sturmwind.', },
  },
  [27267] = {
    'Nehmt zum SI:7 Kontakt auf',
    nil,
    nil,
  },
  [27268] = {
    'Eilt zur Kathedrale',
    {'Ich habe eine dringende Nachricht aus Sturmwind für Euch, $N. Es scheint, als wünsche Hohepriesterin Laurena Euch in der Kathedrale des Lichts am Kathedralenplatz in Sturmwind zu sprechen. Der Botschafter lies nicht verlauten, um welches Anliegen es gehe, doch er gab den Rat, die Reise nach Sturmwind nicht aufzuschieben.', },
    {'Sprecht mit Hohepriesterin Laurena in der Kathedrale des Lichts in Sturmwind.', },
  },
  [27269] = {
    'Der Tempel des Mondes',
    {'Ich habe eine dringende Nachricht aus Darnassus für Euch. Die Nachricht ist von der Hohepriesterin Elunes, Tyrande Wisperwind, persönlich! Der Botschafter lies nicht verlauten, um welches Anliegen es gehe, doch er gab den Rat, die Reise zum Tempel des Mondes in Darnassus nicht aufzuschieben und die Hohepriesterin so schnell wie möglich zu treffen.', },
    {'Sprecht mit Tyrande Wisperwind im Tempel des Mondes in Darnassus.', },
  },
  [27270] = {
    'Eine Audienz bei der Scharfseherin',
    {'Ich habe eine dringende Nachricht aus Sturmwind für Euch, $N. Es sieht aus, als würde Scharfseherin Umbrua darum bitten, mit Euch zu sprechen, wenn Ihr das nächste Mal in der Stadt seid.|n|nDer Bote hat mir keine Erklärung für die Einladung der Scharfseherin gegeben, aber Ihr solltet nach Sturmwind reisen und Scharfseherin Umbrua im Goldenen Fass im Zwergenviertel treffen, sobald Ihr könnt.', },
    {'Sprecht mit Scharfseherin Umbrua im Gasthaus Zum Goldenen Fass im Zwergendistrikt in Sturmwind.', },
  },
  [27271] = {
    'Reise zum Sanktum des Magiers',
    {'Soeben kam eine Nachricht aus Sturmwind an, $N. Einer der angesehensten Magier Sturmwinds, Maginor Dumas, hat Euch zu einem Besuch im Magierviertel in Sturmwind eingeladen. Ihr werdet ihn im Sanktum des Magiers oben auf dem großen Turm im Herzen des Magierviertels finden.|n|nIch weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.', },
    {'Sprecht mit Maginor Dumas im Sanktum des Magiers in Sturmwinds Magierviertel.', },
  },
  [27272] = {
    'Demisette schickt Kunde',
    {'Es scheint, als haben die Ältesten in unseren Rängen von Euren Fortschritten und Eurer Hingabe erfahren, $N. Demisette Cloyce, eine der ältesten und geachtetsten Mitglieder unseres Kreises, hat Kunde geschickt, dass Sie Euch sprechen möchte. Ihr solltet eine Einladung wie diese sehr ernst nehmen. Die Meisten sprechen nur während ihrer Kurse mit ihr, aber wenn Sie Euch zu einem persönlichen Gespräch lädt, muss es sich um etwas Wichtiges handeln.|n|nEilt zurück nach Sturmwind und sucht sie im Gasthaus "Zum Geschlachteten Lamm" im Magierviertel auf.', },
    {'Sprecht mit Demisette Cloyce im Gasthaus "Zum Geschlachteten Lamm" in Sturmwinds Magierviertel.', },
  },
  [27273] = {
    'Eine Einladung aus Mondlichtung',
    {'Ihr habt den Botschafter aus Mondlichtung gerade verpasst, $N. Er hat wenig Preis gegeben, meinte aber, er habe eine dringende Nachricht von Loganaar, einem der ehrwürdigen Ausbilder des Zirkels des Cenarius. Brecht umgehend nach Mondlichtung auf, $N. Es scheint sich um eine wichtige Angelegenheit zu handeln.|n|nIhr werdet Loganaar in dem Dorf Nachthafen auffinden.', },
    {'Sprecht mit Loganaar in Nachthafen in Mondlichtung.', },
  },
  [27274] = {
    'Die Chefchirurgin',
    {'Ich habe eine dringende Nachricht aus Sturmwind für Euch, $N. Chefchirurgin Schnittschweißer hat Euch gebeten, sie in Sturmwind aufzusuchen. Die Nachricht gibt keinerlei Informationen über das Anliegen der Chefchirurgin, Ihr solltet die Reise nach Sturmwind jedoch nicht aufschieben. Sucht Chefchirurgin Schnittschweißer im Zwergendistrikt der Stadt auf.', },
    {'Sprecht mit Chefchirurgin Schnittschweißer im Zwergendistrikt in Sturmwind.', },
  },
  [27275] = {
    'Wiedervereint',
    {'Wir haben uns darum gekümmert, die Schildwache zu heilen und neu auszustatten. Ich habe sie bereits wieder zum Einsatz geschickt.|n|nGeht zurück nach Düsterwolkengipfel. Sie wird Euch dort treffen.', },
    {'Sprecht mit der Schildwache von Feralas in Düsterwolkengipfel in Tausend Nadeln.', },
  },
  [27276] = {
    'Wiedervereint',
    {'Wir haben uns darum gekümmert, den Kriegerhelden zu heilen und neu auszustatten. Ich habe ihn bereits wieder zum Einsatz geschickt.|n|nGeht zurück nach Düsterwolkengipfel. Er wird Euch dort treffen.', },
    {'Sprecht mit dem Kriegerheld des Freiwindpostens in Düsterwolkengipfel in Tausend Nadeln.', },
  },
  [27277] = {
    'Eine Audienz bei Ureda',
    {'Ich habe eine dringende Nachricht aus Orgrimmar für Euch, $N. Die berühmte Magierin Ureda wünscht, Euch in Orgrimmar zu empfangen. Ich bin mir nicht sicher, worum es hier geht, aber wenn ich Ihr wäre, würde ich so schnell wie möglich in die Hauptstadt reisen und Ureda in der Kluft der Schatten aufsuchen.', },
    {'Sprecht mit Ureda in der Kluft der Schatten.', },
  },
  [27278] = {
    'Ruf der Grimmschlag',
    {'Ein Bote aus Orgrimmar hat gerade eine Nachricht für Euch gebracht. Ich soll Euch ausrichten, dass Ormak Grimmschlag, der Jägerlehrer aus Orgrimmar, Euch treffen möchte.|n|nReist schnell nach Orgrimmar und sucht Ormak im Tal der Ehre auf.', },
    {'Sprecht mit Ormak Grimmschlag im Tal der Ehre.', },
  },
  [27279] = {
    'Die Zerschmetterte Hand',
    {'Ein Bote aus Orgrimmar kam gerade mit einer Mitteilung für Euch an. Gordul, der leitende Schurkenlehrer aus Orgrimmar, schickt nach Euch. Ihr müsst Euch sofort nach Orgrimmar begeben und ihn in der Kluft der Schatten aufsuchen.|n|nWenn Gordul ein Treffen einberuft, ist es weise, der Aufforderung zu folgen. Lasst ihn nicht warten, $N.', },
    {'Sprecht mit Gordul in der Kluft der Schatten in Orgrimmar.', },
  },
  [27280] = {
    'Der Erdenbrecher ruft',
    nil,
    nil,
  },
  [27281] = {
    'Grezz Zornfaust',
    {'Soeben kam die Nachricht, dass Ihr in Orgrimmar gebraucht werdet, $N. Grezz Zornfaust, der ehrenhafte Kriegerlehrer der Stadt, hat nach Euch verlangt. Diese Aufforderung zu ignorieren wäre unklug.|n|nReist schnell nach Orgrimmar zum Tal der Ehre, wo Grezz auf Eure Ankunft wartet.', },
    {'Sprecht mit Grezz Zornfaust im Tal der Ehre.', },
  },
  [27282] = {
    'Im Auftrag von Kranosh',
    nil,
    nil,
  },
  [27283] = {
    'Eine Reise nach Mondlichtung',
    {'Wie Ihr sicher wisst, ist Mondlichtung die Heimat des Zirkels des Cenarius, der Bruderschaft der Druiden. Alle Bewohner leben dort unter dem Frieden des Cenarius. Ausbilder Loganaar hat die Einladung nach Mondlichtung unter Anbetracht dieser Tatsache ausgesprochen.|n|nIhr werdet ihn in dem Dorf Nachthafen auffinden.', },
    {'Sprecht mit Loganaar in Nachthafen.', },
  },
  [27284] = {
    'Der schwarze Schild',
    {'Ich kann Euch leider nicht weiterhelfen, $N, schicke Euch aber zu jemandem, der es kann. Caz Doppelspross, einer unserer besten Schmiede, arbeitet in der Schmiede.|n|nBringt ihm den Schild und hört Euch an, was er zu sagen hat.', },
    {'Zeigt den geschwärzten Eisenschild Caz Doppelspross in Theramore.', },
  },
  [27285] = {
    'Der schwarze Schild',
    {'Ah, das hätte ich fast übersehen... Der Ledergurt an der Rückseite muss verbrannt sein, aber er war offenbar für eine große Person gemacht. Ich schätze, für einen Tauren.|n|nMehr kann ich Euch nicht sagen. Sagt Hauptmann Mumm, es tut mir leid, dass ich nicht mehr helfen konnte.', },
    {'Sprecht mit Hauptmann Garran Mumm in Theramore.', },
  },
  [27286] = {
    'Daelins Männer',
    {'Reddon... Oh, da haben wir ihn! Leutnant Paval Reethe.|n|nTrat den Wachen von Theramore zusammen mit den meisten Rekruten bei, die mit Lady Prachtmeer über das Meer kamen. Trat mit sechzehn Jahren den Marinesoldaten von Kul Tiras bei. Herausragende Dienste, Beförderungen...|n|nIst als vermisst eingetragen.', },
    {'Kehrt mit den Informationen über Reethe zu Hauptmann Garran Mumm in Theramore zurück.', },
  },
  [27287] = {
    'Die Deserteure',
    {'Es war ein ständiger Kampf, in den Marschen präsent zu bleiben, aber durch die Kraft unserer Entschlossenheit konnten wir mehrere Wachtürme in diesem Gebiet zur Verteidigung halten.|n|nDie aktuellsten Informationen und Späherberichte, die ich bekam, deuten darauf hin, dass eine Gruppe Deserteure sich in unserem alten Turm bei der Verlassenen Wacht, südöstlich des Gasthauses, eingenistet hat.|n|nDer örtliche Anführer der Deserteure ist ein Mann namens Balos Jacken. Seht zu, ob Ihr Informationen über ihn bekommt.|n|nSeid gewarnt, $N. Er könnte sich als harte Nuss erweisen.', },
    {'Sammelt Informationen über Reethe von Balos Jacken und den Deserteuren in den Düstermarschen.', },
  },
  [27288] = {
    'Die Deserteure',
    {'Reethe? Dieser Feigling?|n|nWir warfen ihn aus dem Lager hinaus, weil er dauernd die Vorräte der Oger in Brackenwall plündern wollte. So viele sind wir nicht, dass wir es mit diesen hirnlosen Schlägern aufnehmen könnten.|n|nEr hat das Fass zum Überlaufen gebracht, daher haben wir ihn sich selbst überlassen.|n|nAlso ich habe Euch geholfen... Warum helft Ihr jetzt nicht uns und vergesst, dass Ihr uns gefunden habt?', },
    {'Sprecht mit Hauptmann Garran Mumm in Theramore über Reethe.', },
  },
  [27289] = {
    'Mumms Bericht',
    {'Ihr habt gute Arbeit geleistet, $N, die Beste, die ich je von einem Amateur sah.|n|nLady Prachtmeer bat mich, sie über diese delikate Situation auf dem Laufenden zu halten, aber ich habe eine Weile nicht mit ihr gesprochen.|n|nIch wollte ihr meinen Bericht später bringen, aber es scheint mir passender, wenn Ihr mit ihr darüber sprecht. Ihr könnt ihre Fragen wahrscheinlich besser beantworten als ich.', },
    {'Bringt Mumms Bericht zu Lady Jaina Prachtmeer in Theramore.', },
  },
  [27290] = {
    'Zum Gefechtsstand der Verlassenen',
    {'Die Zeit, Crowley, Blutfang und jeden Hund unter ihrem Kommando zu töten, ist gekommen. Dazu muss man so gerissen und genau planen, wie wir es uns nie haben träumen lassen!|n|nAls einer der Soldaten, denen ich am meisten vertraue, müsst Ihr, $N, zum Gefechtsstand der Verlassenen in Gilneas gehen und Euch bei Todespirscherkommandant Belmont melden. Ich habe Belmont bereits mit meinen Plänen vorausgeschickt. Er erwartet Eure Ankunft.|n|nArthura wird Euch zum Gefechtsstand der Verlassenen begleiten. Sagt mir, wenn Ihr bereit seid, und ich werde Euch auf den Weg bringen.', },
    {'Meldet Euch in Gilneas am Gefechtsstand der Verlassenen bei Todespirscherkommandant Belmont.', },
  },
  [27291] = {
    'Endlich Frieden',
    {'Ich wünschte, wir könnten James Hyals Ehefrau und Sohn wissen lassen, dass ihre Mörder Gerechtigkeit erfahren haben.|n|n<Hauptmann Mumm holt einen kleinen Blumenkranz hervor.>|n|nManche sagen, dass ihre Geister dennoch die Wahrheit erfahren, auch, wenn wir sie nicht selbst kontaktieren können. Es ist nicht viel, aber könntet Ihr diesen Kranz beim Monument der Familie Hyal niederlegen? Es ist einer der größeren Grabsteine auf dem Friedhof nördlich der Tore von Theramore.', },
    {'Hauptmann Garran Mumm bei der Wehrzitadelle möchte, dass Ihr den Kranz bei dem Monument der Familie Hyal niederlegt.', },
  },
  [27292] = {
    'Rückkehr zu Krog',
    {'Hoffentlich konnte ich Euch weiterhelfen. Es tut mir leid, dass ich Euch keine bessere Auskunft geben konnte. Meine Lehrlinge und ich fertigen solch eine große Menge an Waffen und Rüstungen an, dass es fast unmöglich ist, detaillierte Informationen zu jedem Stück zu behalten.|n|nWir statten nicht nur die mutigen Verteidiger der Taurenländer aus, nein, die Grimmtotem hegen auch eine besondere Vorliebe für meine Arbeit. Ein erfahrener Krieger erkennt gutes Handwerk, wenn er es sieht.', },
    {'Sprecht mit Krog in Brackenwall.', },
  },
  [27293] = {
    'Die Verschwörung der Grimmtotem',
    {'Nachdem die Aktivitäten der Grimmtotem in Tausend Nadeln ans Licht gekommen sind, werden sie von mehr und mehr Tauren mit Argwohn betrachtet. Hochrangige Vertreter der Grimmtotem hießen bereits Morde und Entführungen gut, um ihre eigenen Interessen voranzutreiben. Ich fürchte, wir könnten Ihr nächstes Ziel sein.|n|nDas Dorf der Schwarzhufe im Nordosten, in der Nähe des Blaumoors, ist eine große neue Siedlung der Grimmtotem. Ihre Anführer, die Ältesten, dürften alle Anordnungen von Donnerfels bei sich tragen. Versucht an die Pläne heranzukommen und setzt sie zusammen, um mehr über die Verschwörung der Grimmtotem zu erfahren.', },
    {'Erlangt 4 Notizen der Grimmtotem von den Ältesten der Grimmtotem. Setzt die Teile zusammen, um die Schlachtpläne der Grimmtotem ganz zu sehen.', },
  },
  [27294] = {
    'Kein bloßer Zufall',
    {'Wir haben die Ruinen des Gasthauses so gut es geht nach Beweisen abgesucht. Ich bin beunruhigt, was die Ergebnisse unserer Ermittlungen betrifft, aber wir müssen die Wahrheit erfahren.|n|nDie Hufabdrücke und der Schild mit Mosarns Prägung deuten darauf hin, dass die Grimmtotem ihre Finger im Spiel haben. Sie haben erst kürzlich eine Siedlung im Sumpf errichtet, das Dorf der Schwarzhufe im Nordosten. Reist zum Dorf der Schwarzhufe und sucht nach weiteren Waffen, die von Mosarn angefertigt wurden.', },
    {'Sammelt 7 Waffen der Schwarzhufe im Dorf der Schwarzhufe.', },
  },
  [27295] = {
    'Sucht Tabetha auf',
    {'Die Waffen, die Ihr im Dorf der Schwarzhufe gefunden habt, wurden außer zum Üben noch nie im Kampf eingesetzt. Dies bedeutet, dass die Grimmtotem, die für den Angriff auf das Gasthaus verantwortlich sind, noch immer auf freiem Fuß sind.|n|nIm Süden, im Herzen des Morasts, lebt die Hexe Tabetha. Sie ist zwar ein Mensch, doch in der Vergangenheit hat sie uns treue Dienste geleistet und einige unserer Magier ausgebildet.|n|nBittet sie, Euch beim Aufspüren der Grimmtotem, die für den Überfall auf das Gasthaus "Zur Süßen Ruh" verantwortlich sind, zu helfen. Die Allianz soll nicht auf den Gedanken kommen, dass wir etwas damit zu tun hätten.', },
    {'Sprecht mit Tabetha auf ihrem Hof im Morast.', },
  },
  [27296] = {
    'Brennt den Grollhornposten nieder!',
    {'Man muss nicht hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen "Nachbarn" hier heraufbeschwören. Falls es sich bei ihnen wirklich um diejenigen handelt, die das Gasthaus "Zur Süßen Ruh" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.|n|nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt nördlich von meinem Hof, in der Nähe der Straße. Ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotems haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totem förmlich angekündigt.', },
    nil,
  },
  [27297] = {
    'Das Walten der Gerechtigkeit',
    {'Ich bezweifle, dass die Grimmtotems ihren Plan, die Menschen aus den Marschen zu vertreiben, aufgeben werden – allerdings habe ich den Eindruck, dass Euch das nicht weiter stört. Zumindest haben wir die Schuldigen für ihre Verbrechen am Gasthaus "Zur Süßen Ruh" bestraft.|n|nGeht und berichtet Eurem Anführer, dass seine Rache vollstreckt wurde.', },
    {'Kehrt zu Krog in Brackenwall zurück.', },
  },
  [27298] = {
    'Sucht Meister Pyreanor auf',
    {'Meister Pyreanor, ein erfahrener Blutritter und Berater des Kriegshäuptlings, verlangt nach Eurer Anwesenheit in Orgrimmar. Er zeigt Interesse an Eurer Ausbildung, $N, und es ist von äußerster Wichtigkeit, dass Ihr sofort mit ihm sprecht.|n|nDie Nachricht, die ich erhalten habe, gibt keinen Grund für Euren Besuch an, aber Ihr solltet Euch umgehend nach Orgrimmar aufmachen. Ihr könnt Meister Pyreanor in der Burg im Zentrum vom Tal der Stärke finden.', },
    {'Sprecht mit Meister Pyreanor im Tal der Stärke in Orgrimmar.', },
  },
  [27299] = {
    'Zerrissener Boden',
    nil,
    {'Tötet 3 Tentakel von Iso\'rath.', },
  },
  [27300] = {
    'Zurückstoßen',
    {'Die Schattenhammerkultisten haben \'ne Siedlung des Drachenmals im Süden zerstört und halten von dort aus Beschwörungsrituale ab. Gebt ihnen keine Gelegenheit, zur Ruhe zu kommen und zu ihren Zaubern zurückzukehren. Bringt die Schlacht zu ihnen!', },
    {'Tötet 12 Schattenhammer in den Ruinen des Lagers der Drakgor.', },
  },
  [27301] = {
    nil,
    {'Wir bereiten ein Ritual vor, dass dabei helfen könnte, Iso\'rath zu zerstören, die alte, von den Göttern gezüchtete Monstrosität, die vom Schattenhammer aus den Tiefen geholt wurde. Die Zeit läuft uns jedoch davon, denn unsere mächtigste Mitstreiterin wurde bei dem Angriff auf ihr Lager festgehalten.|n|nErdenruferin Yevaa befindet sich in den Ruinen südlich von hier. Sie ist noch am Leben, davon bin ich überzeugt. Bitte, rettet sie. Wenn einer von uns Eure Hilfe verdient, dann ist sie es.', },
    {'Findet Erdenruferin Yevaa in den Ruinen von Drakgor.', },
  },
  [27302] = {
    'Einfache Lösungen',
    {'Ich bin neu hier. Ganz neu. Aber wisst Ihr was? Ich hab wenigstens Aussichten!|n|nIch hab ein paar Freunde, Schamanen, die haben Großes vor sich, aber die sind so festgefahren; sie vertrauen gänzlich auf Elemente und vergessen, die normalen Rohstoffe in ihrer Umgebung zu nutzen.|n|nBei den Ruinen südlich von hier habe ich gesehen, wie die Schläger des Schattenhammers Fass um Fass entflammbares Öl abtransportiert haben. Sie haben das Öl benutzt, um unsere Siedlung niederzubrennen. Ich schlage vor, wir tun es ihnen gleich.', },
    {'Sammelt 10 Scheiterhaufenbrandölfässer.', },
  },
  [27303] = {
    'Mitleid mit den Gebundenen',
    {'Natürlich hatte ich kein Bedürfnis, dort zu bleiben, aber es gab dort ein paar Materialien, die wir für das Ritual brauchen... Ich war nicht schnell genug, alles einzusammeln, und das hat dann dazu geführt, dass sie mich geschnappt haben.|n|nIch werde zum Kreis zurückkehren, aber ich wäre Euch sehr dankbar, wenn Ihr an meiner Stelle diese Aufgabe abschließen könntet. Wir brauchen die Herzen der gebundenen Feuerelementare, die die Schattenhammerkultisten im westlichen Teil des Lagers gefangen halten.|n|nDie Elementare können nicht gerettet werden, aber durch dieses Opfer können sie Rache ausüben.|n|nTrefft mich im Lager.', },
    {'Sammelt 5 Fleischbrennerherzen.', },
  },
  [27304] = {
    'Der Sonne hinterher',
    {'Sonnenläufer Atohmo schickt Kunde aus Orgrimmar. Er möchte Euch sprechen, wenn Ihr in der Stadt seid. Ich muss Euch wohl kaum daran erinnern, dass Atohmo ein ehrenhaftes Mitglied unseres Orden ist und seine Aufforderung nicht ignoriert werden sollte.|n|nWenn Ihr das nächste Mal in Orgrimmar seid, begebt Euch zum Tal der Weisheit und sprecht mit ihm.', },
    {'Sprecht mit Sonnenläufer Atohmo im Tal der Weisheit in Orgrimmar.', },
  },
  [27305] = {
    'Von Liebe und Familie',
    {'In der Scharlachroten Bastion befindet sich ein Gemälde, dass für Hochlord Tirion Fordring persönlich äußerst wertvoll ist. Sucht nach einem Gemälde unseres Zwillingsmondes. Wenn Ihr die oberste Farbschicht abkratzt, werdet Ihr darunter das Meisterwerk \'Von Liebe und Familie\' vorfinden.|n|nMöge das Licht Euch den Weg weisen. Oh, bitte seid äußerst vorsichtig mit dem Gemälde.', },
    {'Findet \'Von Liebe und Familie\'.', },
  },
  [27306] = {
    'Sprecht mit Ogron',
    {'Ich kenne diesen Menschen, Paval Reethe. Lächerlich, selbst für einen seiner Art. Er ist ein Deserteur und hat seine Kameraden hintergangen. Jetzt versteckt er sich in den Wäldern.|n|nIch habe Ogron geschickt, um ihn ausfindig zu machen. Ein paar von den anderen glauben, dass er von unseren Vorräten gestohlen hat. Ich glaube, Ogron ist in Richtung Südosten unterwegs.', },
    {'Findet Ogron südöstlich von Brackenwall.', },
  },
  [27307] = {
    'Die Elemente schreien auf',
    {'Könnt Ihr das fühlen, $C? Die Elemente sind unruhig. Wir Mitglieder des Irdenen Rings versuchen, den Ursprung dieser Unruhe zu finden. Bisher waren wir jedoch erfolglos und wenden uns nun anderen Hilfe suchend zu. Sprecht mit Erunak Steinsprecher in Sturmwind und findet heraus, wie Ihr helfen könnt.', },
    {'Sprecht mit Erunak Steinsprecher in Sturmwind.', },
  },
  [27308] = {
    'Die Elemente schreien auf',
    {'Könnt Ihr das fühlen, $C? Die Elemente sind unruhig. Wir Mitglieder des Irdenen Rings versuchen, den Ursprung dieser Unruhe zu finden. Bisher waren wir jedoch erfolglos und wenden uns nun anderen Hilfe suchend zu. Sprecht mit Erdheilerin Norsala in Orgrimmar und findet heraus, was für Aufgaben sie für Euch hat.', },
    {'Sprecht mit Erdheilerin Norsala in Orgrimmar.', },
  },
  [27309] = {
    'Die Verschwörung der Grimmtotem',
    {'Nachdem die Aktivitäten der Grimmtotem in Tausend Nadeln ans Licht gekommen sind, werden sie von mehr und mehr Tauren mit Argwohn betrachtet. Hochrangige Vertreter der Grimmtotem hießen bereits Morde und Entführungen gut, um ihre eigenen Interessen voranzutreiben. Ich fürchte, wir könnten Ihr nächstes Ziel sein.|n|nDas Dorf der Schwarzhufe im Nordosten, in der Nähe des Blaumoors, ist eine große neue Siedlung der Grimmtotem. Ihre Anführer, die Ältesten, dürften alle Anordnungen von Donnerfels bei sich tragen. Versucht an die Pläne heranzukommen und setzt sie zusammen, um mehr über die Verschwörung der Grimmtotem zu erfahren.', },
    {'Erlangt 4 Notizen der Grimmtotem von den Ältesten der Grimmtotem. Setzt die Teile zusammen, um die Schlachtpläne der Grimmtotem ganz zu sehen.', },
  },
  [27310] = {
    'Keine Waffen für Grimmtotems!',
    {'Nun gut, diese Feiglinge wollen kämpfen? Mal sehen, wie sie das ohne jegliche Waffen anstellen wollen.|n|nIhr habt doch sicherlich eine Fackel oder etwas in der Art.|n|nBrennt ihre Waffenregale nieder. Brennt sie alle nieder!', },
    {'Brennt 8 Grimmtotemwaffenständer nieder.', },
  },
  [27311] = {
    'Keine Waffen für Grimmtotems!',
    {'Die Grimmtotems wollen kämpfen? Mal sehen, wie sie das ohne ihre Waffen anstellen wollen. |n|nIhr habt doch sicherlich irgendwas, das brennt. Brennt ihre Waffenständer nieder, $C.|n|nLasst die Natur die Arbeit verrichten.', },
    {'Brennt 8 Grimmtotemwaffenständer nieder.', },
  },
  [27312] = {
    'Grimmtotems in Düsterwolkengipfel',
    {'Es geht nicht anders. Wenn man einen Kampf gewinnen will, muss Blut vergossen werden. Und in diesem Fall viel Blut.|n|nIhr wisst, was zu tun ist.', },
    nil,
  },
  [27313] = {
    'Grimmtotems in Düsterwolkengipfel',
    {'Es gibt keine Alternative; wenn man einen Kampf gewinnen will, muss man das Blut des Feindes vergießen. Und in diesem Fall leider viel Blut.|n|nIhr wisst, was zu tun ist.', },
    nil,
  },
  [27314] = {
    'Häuptlinge der Grimmtotem: Isha Düsteraxt',
    {'Grundlagen der Schildwachenausbildung: Wenn der Anführer ausgelöscht ist, wird der Rest der Streitmacht bald zerfallen. Und genau das werden wir tun, $C.|n|nIsha Düsteraxt ist von den Häuptlingen der Grimmtotems am wenigsten weit entfernt. Mal sehen, ob wir es mit ihr aufnehmen können.', },
    {'Tötet Isha Düsteraxt.', },
  },
  [27315] = {
    'Häuptlinge der Grimmtotem: Isha Düsteraxt',
    nil,
    nil,
  },
  [27316] = {
    'Die Rassel der Knochen',
    {'Eine Rassel der Tauren liegt hier und strahlt übernatürliche Macht aus. Ohne seine Hüter ist das Artefakt ungeschützt.|n|nVielleicht kann die Schildwache uns Einblicke in seine Bedeutung geben?', },
    {'Gebt die Rassel der Knochen der Schildwache von Feralas in Düsterwolkengipfel in Tausend Nadeln.', },
  },
  [27317] = {
    'Die Rassel der Knochen',
    {'Eine Rassel der Tauren liegt hier und strahlt übernatürliche Macht aus. Ohne seine Hüter ist das Artefakt ungeschützt.|n|nVielleicht kann der Kriegerheld uns Einblicke in seine Bedeutung geben?', },
    {'Gebt die Rassel der Knochen dem Kriegerheld des Freiwindpostens in Düsterwolkengipfel in Tausend Nadeln.', },
  },
  [27318] = {
    'Häuptlinge der Grimmtotem: Ältester Sturmhuf',
    {'Der Älteste Sturmhuf ist ein Schamane mit ernormer Macht. Anscheinend ist er die rechte Hand von Magatha Grimmtotem, der Ältestengreisin und Anführerin des Grimmtotemklans.|n|nWir wissen, dass er hier ist und damit beschäftigt ist, Geomanten auszubilden. Wir müssen ihn töten, $C.', },
    {'Tötet den Ältesten Sturmhuf.', },
  },
  [27319] = {
    'Häuptlinge der Grimmtotem: Ältester Sturmhuf',
    {'Der Älteste Sturmhuf ist ein Schamanenhäuptling mit ernormer Macht. Er wurde von Magatha Grimmtotem unterrichtet, der Ältestengreisin und Anführerin des Grimmtotemklans.|n|nWir wissen, dass er hier ist und damit beschäftigt ist, Geomanten auszubilden. Wir müssen ihn töten, $C.', },
    {'Tötet den Ältesten Sturmhuf.', },
  },
  [27320] = {
    'Die Niederschrift der Geschichte',
    {'In der Mythologie der Shu\'halo ist die Rassel der Knochen eng mit der Niederschrift der Geschichte und den Trommeln des Krieges verknüpft. Es handelt sich dabei anscheinend um wertvolle Artefakte der Tauren.|n|nWir müssen unsere Augen offen halten, wenn wir die anderen zwei Artefakte finden wollen. Wenn man den Geschichten Glauben schenken will, sieht die Niederschrift wohl aus wie eine Schriftrolle mit Piktogrammen.', },
    {'Findet die Niederschrift der Geschichte.', },
  },
  [27321] = {
    'Die Niederschrift der Geschichte',
    {'Die Rassel der Knochen ist Teil der uralten Mythologie der Shu\'halo. Sie wurde schon immer mit der Niederschrift der Geschichte und den Trommeln des Krieges in Verbindung gebracht. Es handelt sich dabei anscheinend um wertvolle Artefakte der Tauren, Geschenke von der Erdmutter, wenn man den Geschichten Glauben schenken soll. Allerdings kann ich mir nicht vorstellen, dass die Erdmutter mit den Trommeln wirklich etwas zu tun hat.|n|nWir müssen aufmerksam sein, wenn wir die anderen zwei Artefakte finden wollen. Wenn ich mich recht erinnere, sieht die Niederschrift wohl aus wie eine Schriftrolle mit Piktogrammen.', },
    {'Findet die Niederschrift der Geschichte.', },
  },
  [27322] = {
    'Korok der Koloss',
    {'Das Monster ist gefallen und hat den Soldaten der Verlassenen an der Front so eine kurze Atempause verschafft.|n|nBringt Koroks zweiten Kopf zu Vorpostenkommandant Ansturm am Gefechtsstand der Verlassenen.', },
    {'Bringt Koroks zweiten Kopf zu Vorpostenkommandant Ansturm am Gefechtsstand der Verlassenen in den Ruinen von Gilneas.', },
  },
  [27323] = {
    'Häuptlinge der Grimmtotem: Grundig Finsterwolke',
    {'Einer der berüchtigten Anführer der Grimmtotems von Steinkrallengebirge ist zurückgekehrt.|n|nWir sollten diese Gelegenheit nutzen und sicherstellen, dass er nirgendwo anders hingeht.', },
    {'Tötet Grundig Finsterwolke.', },
  },
  [27324] = {
    'Häuptlinge der Grimmtotem: Grundig Finsterwolke',
    {'Einer der versiertesten Anführer der Grimmtotems vom Steinkrallengebirge ist zurückgekehrt.|n|nWir müssen das Beste aus dieser Situation machen und seiner Schreckensherrschaft ein für alle Mal ein Ende setzen.', },
    {'Tötet Grundig Finsterwolke.', },
  },
  [27325] = {
    'Die Trommeln des Krieges',
    {'Was auch immer die Grimmtotems mit diesen Trommeln des Krieges machen, wir wollen nicht, dass sie noch länger in ihrem Besitz bleiben.|n|nSorgt Euch nicht, $N, wir werden eine Lösung finden. Zuerst müssen wir aber alle Teile dieses Rätsels erlangen.', },
    {'Findet die Trommeln des Krieges.', },
  },
  [27326] = {
    'Die Trommeln des Krieges',
    {'Was auch immer die Grimmtotems mit den Trommeln des Krieges machen, wir wollen nicht, dass sie sie behalten.|n|nSorgt Euch nicht, $N, wir werden herausfinden, was hier vor sich geht. Zuerst müssen wir aber alle Artefaktteile finden.', },
    {'Findet die Trommeln des Krieges.', },
  },
  [27327] = {
    'Häuptlinge der Grimmtotem: Der Häuptling aller Häuptlinge',
    {'Die Zeit ist gekommen, dem Anführer aller Grimmtotems in Düsterwolkengipfel ein Ende zu bereiten: Arnak Grimmtotem.|n|nEs wird gesagt, dass er der in Ungnade gefallene Neffe von Magatha Grimmtotem ist, der Ältestengreisin und Matriarchin des Grimmtotemklans. Seine Taktlosigkeit hat wohl dazu geführt, dass sie ihm gegenüber nicht wohlgesinnt ist.|n|nAll dies ist aber jetzt nicht wichtig. Nur sein Tod ist für uns von Wichtigkeit. Sein endgültiger Tod.', },
    {'Tötet Arnak Grimmtotem.', },
  },
  [27328] = {
    'Häuptlinge der Grimmtotem: Der Häuptling aller Häuptlinge',
    {'Die Zeit ist gekommen, um uns dem Anführer aller Grimmtotems in Düsterwolkengipfel zuzuwenden: Arnak Grimmtotem.|n|nEr ist der in Ungnade gefallene Neffe von Magatha Grimmtotem, der Ältestengreisin und Matriarchin des Grimmtotemklans. Seine Taktlosigkeit hat dazu geführt, dass sie ihm gegenüber nicht wohlgesinnt ist.|n|nAll dies ist aber jetzt nicht wichtig. Von Wichtigkeit ist nur, dass wir uns seiner annehmen. Ein für alle Mal.', },
    {'Tötet Arnak Grimmtotem.', },
  },
  [27329] = {
    'Die Windnatter entfernen',
    {'Ich kenne diese Artefakte. Ich glaube, sie wurden von Magatha Grimmtotem persönlich hierher gebracht. Sie ist aber nicht bei den Grimmtotems in Düsterwolkengipfel. Sie ist gleich nach ihrer Ankunft wieder aufgebrochen, und niemand weiß, wo sie jetzt ist.|n|nVielleicht können wir es herausfinden.|n|nNehmt die Rassel, die Niederschrift, und die Trommeln mit zu Arikaras Steinkreis. Wenn ich richtig liege, wird die Windnatter wieder auftauchen. Ihr müsst sie besiegen, um über Magathas Versteck Hinweise zu erhalten.', },
    {'Bezwingt Arikara.', },
  },
  [27330] = {
    'Die Windnatter entfernen',
    {'Ich kenne diese Artefakte. Ich glaube, sie wurden von Magatha Grimmtotem persönlich hierher gebracht. Sie ist aber nicht bei den Grimmtotems in Düsterwolkengipfel. Sie ist gleich nach ihrer Ankunft wieder aufgebrochen, und niemand weiß, wo sie jetzt ist.|n|nVielleicht können wir es herausfinden.|n|nNehmt die Rassel, die Niederschrift, und die Trommeln mit zu Arikaras Steinkreis. Wenn ich richtig liege, wird die Windnatter wieder auftauchen. Ihr müsst sie besiegen, um über Magathas Versteck Hinweise zu erhalten.', },
    {'Bezwingt Arikara.', },
  },
  [27331] = {
    'Der Ruf der Seherin',
    {'Soeben kam die Nachricht, dass Ihr in Orgrimmar gebraucht werdet, $N. Seherin Liwatha bittet Euch, so schnell wie möglich in die Stadt zurückzukehren. Ihre Nachricht enthielt keine weiteren Informationen, aber es schien dringlich zu sein.|n|nSucht Seherin Liwatha im Tal der Weisheit in Orgrimmar auf.', },
    {'Sprecht mit Seherin Liwatha im Tal der Weisheit in Orgrimmar.', },
  },
  [27332] = {
    'Sucht den Schattenläufer auf',
    {'Der Schattenläufer Zuru fordert Eure sofortige Anwesenheit in Orgrimmar, $N. Lasst ihn nicht warten, denn es klang, als sei es eine wichtige Angelegenheit.|n|nIhr werdet den Schattenläufer im Tal der Geister in Orgrimmar vorfinden.', },
    {'Sprecht mit der dunklen Klerikerin Cecille in der Feste Grommash im Tal der Stärke in Orgrimmar.', },
  },
  [27333] = {
    'Haltlos',
    {'Ich weiß nicht, wie lange wir die Stellung noch halten können, $N. Die Worgen von Crowley und Blutfang kennen jedes noch so kleine Versteck und jeden sicheren Ort in Gilneas. In der einen Minute stehen sie vor Euch und in der nächsten Minute sind sie schon wieder weg! Wir werden diesen Krieg durch ihre Gelegenheitsangriffe verlieren, obwohl wir zahlenmäßig gesehen die Oberhand haben.|n|nMami hat aber keinen Aufgeber aus mir gemacht! Ich bin ein Verlassener bis zum bitteren Ende.|n|nBegebt Euch in die Mark im Westen und helft unseren Soldaten an vorderster Front. Tötet die angreifenden Rebellen der Worgen!', },
    {'Tötet 12 Rebellen der Worgen.', },
  },
  [27334] = {
    'Dunkle Klerikerin Cecille',
    {'Ich habe soeben eine Nachricht von der Dunklen Klerikerin Cecille aus Orgrimmar erhalten. Sie fordert Euch auf, sie in ihrem Audienzgemach in der Feste Grommash aufzusuchen. Sie empfängt dort eine Delegation aus Unterstadt. Die Klerikerin hat nicht gesagt, worum es bei Eurem Besuch geht, aber es ist ganz offensichtlich wichtig. Beeilt Euch, $N.', },
    {'Sprecht mit der dunklen Klerikerin Cecille in Feste Grommash im Tal der Stärke in Orgrimmar.', },
  },
  [27335] = {
    'Reise nach Orgrimmar',
    {'Ein Botschafter hat mich gebeten, Euch diese Einladung zu geben. Sie ist von Tyelis, einem Priesterlehrer und Abgesandten von Silbermond.|n|nEr fordert Euch auf, ihn in der Feste Grommash in Orgrimmar zu treffen. Ihr solltet sofort aufbrechen, $N. Die Einladung klingt wichtig.', },
    {'Sprecht mit Tyelis in der Feste Grommash im Tal der Stärke in Orgrimmar.', },
  },
  [27336] = {
    'Die Waffe der Grimmtotem',
    {'Bevor ich während des letzten Angriffs der Grimmtotem verwundet wurde, hatte ich noch ein recht seltsames Totem an mich bringen können, welches unsere Feinde gegen uns eingesetzt haben.|n|nAnscheinend verschießt es im Gefecht Blitze aus wilder Energie. Leider konnte ich mit keinem meiner Experimente herausfinden, wie es funktioniert. Wenn Ihr versprecht, mir zu helfen, werde ich Euch das Totem leihen.|n|nDie Wasserflächen, die den Hof umgeben, beherbergen eine ganze Reihe aggressiver, scheckiger Staubsuhlerkrokilisken und Staubsuhlerdolchrachen. Versucht die Krokilisken in Reichweite des Totems zu bekämpfen.', },
    {'Platziert das erbeutete Totem auf dem Boden und tötet 10 scheckige Staubsuhlerkrokilisken oder Staubsuhlerdolchrachen, um den Effekt des Totems zu testen.', },
  },
  [27337] = {
    'Eine passende Waffe',
    {'Schon zu Beginn haben Eure Lehrer Euch für ein Naturtalent gehalten, $N. Euer rascher Fortschritt und Eure Hingabe haben Euch zu einem wahren Vorbild gemacht.|n|nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.|n|nDen Legenden zufolge ist die verfluchte Burg Schattenfang im Silberwald der Ort, an dem einige der Materialien zu finden sind, die Ihr dafür benötigt. Reist dorthin und findet das verlorene Schwert der Familie Silberlein, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke, die die Burg heimsuchen.', },
    {'Reist zu Burg Schattenfang und erhaltet das Schwert der Familie Silberlein vom Baron, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.', },
  },
  [27338] = {
    'Unsere Jungs an der Küste',
    {'Die Lage hier in Hochland ändert sich minütlich. Unser Ziel ist es, die Bastion des Zwielichts zu stürmen, aber ich kann nicht mal eine Landezone an der Küste sichern, ohne dass die verfluchte Horde Ärger macht.|n|nIch brauche Männer, die hier am Strand die Landung sichern, während ich die Überreste der Flotte zusammensuche.|n|nMeldet Euch bei Leutnant Emry an der Küste und helft seinen Marinesoldaten, die Horde zurückzudrängen!', },
    {'Meldet Euch bei Leutnant Emry in Zwielichtufer im Schattenhochland.', },
  },
  [27339] = {
    'Der Reagenziendieb',
    {'Wenn es eine Sache gibt, auf die man sich bei Lehrling Morlann verlassen kann, dann ist es sein ewiges Genörgel über fehlende Reagenzien.|n|nNormalerweise versuche ich ihn einfach zu ignorieren, meistens vergebens. Dieses Mal möchte ich etwas anderes versuchen.|n|nVielleicht lässt er mich in Ruhe, wenn ich fehlende Reagenzien ersetze, bevor ihm überhaupt auffällt, dass etwas fehlt. Das von uns am häufigsten genutzte Reagenz ist Marschengift. Ihr findet es bei Dunkelzahnkrabblern und giftigen Schreddern in den Marschen nördlich des Hofs. Sobald Ihr mir das Gift bringt, werde ich Morlanns Vorräte auffrischen, noch bevor er irgendetwas merkt.', },
    {'Sammelt 6 Phiolen Marschengift von Dunkelzahnkrabblern oder giftigen Schreddern.', },
  },
  [27340] = {
    'Räuber des Grollhornpostens',
    {'Die Grimmtotem beim Grollhornposten im Norden werden mit jedem Tag dreister. In der Nacht kann man sie oft von ihren Taten singen hören, wie sie diejenigen vertrieben haben, die sich hier niederlassen wollten.|n|nSie haben fest vor, uns von Tabethas Hof zu vertreiben, obwohl sie schon Generationen von Schülern hier ausgebildet hat. Wir haben den Hof so gut es geht verteidigt, aber Lehrling Garion wurde bei dem letzten Angriff verletzt.|n|nGeht zum Grollhornposten und tötet alle Grimmtotem, die Ihr finden könnt! Die Überfälle müssen ein Ende nehmen.', },
    {'Tötet 12 Grimmtotems im Grollhornposten.', },
  },
  [27341] = {
    'Späht den Strand aus',
    {'Es ist ganz einfach, wir oder sie, $C. Nur eine Fraktion kann diesen Strand einnehmen.|n|nNördlich von hier ist ein kleiner Hügel, von dem man die ganze Küstenlinie überblicken kann. Wer diesen Hügel einnimmt, erlangt sofort die Oberhand an der ganzen Küste.|n|nIch muss wissen, was die aktuelle Lage ist. Späht den Brückenkopfkontrollpunkt aus. Ihr erkennt ihn an den großen Flaggen. Kehrt anschließend zu mir zurück.|n|nIhr müsst nicht versuchen, ihn einzunehmen, es sei denn, Ihr dürstet nach einem Kampf...', },
    {'Späht den Brückenkopfkontrollpunkt am Zwielichtufer aus. Ihr müsst ihn nicht einnehmen, doch wenn Ihr dies tut, erhält Eure Fraktion einen Vorteil im Kampf und Ihr werdet für den PvP-Kampf markiert.', },
  },
  [27342] = {
    'Die Zeit löst alle Rätsel',
    {'Die Dunkle Fürstin hat Euch und Arthura für eine ganz besondere Aufgabe einberufen. Bevor ich Euch jedoch mehr verrate, müssen wir erst einige Vorbereitungen treffen.|n|nBegebt Euch zum Wald von Gilneas östlich von hier und sucht in der Nähe der Bäume und Steine in der Gegend nach einer besonderen Pflanze, die als Wolfsbann bekannt ist. Sammelt so viel Wolfsbann, wie Ihr tragen könnt und kehrt zu mir zurück.|n|nUnsere Aufgabe hier übersteigt die Aufgaben auf dem Schlachtfeld, $N. Ich werde Euch zu gegebener Zeit mehr verraten.', },
    {'Sammelt 6 Wolfsbann.', },
  },
  [27343] = {
    'Die Hand des Lichts',
    {'Ich habe Eure Fortschritte verfolgt, $N, und ich kann nur schließen, dass das Licht strahlend auf Euch scheint. Ihr seid wahrhaftig $Gein vorbildlicher:eine vorbildliche:c; $C.|n|nUm Eurer Hingabe Anerkennung zu zollen, hat König Wrynn den königlichen Waffenschmied beauftragt, eine besondere Waffe für Euch anzufertigen.|n|nDie Materialien zur Herstellung dieser Waffe sind einzigartig und können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren, und 5 ewige Sehnen.', },
  },
  [27344] = {
    'Eine wohlverdiente Belohnung',
    {'Nicht nur ich bin von Eurem Fortschritt beeindruckt, $N. Wie Ihr Bogen und Begleiter meistert, und auch Eure Hingabe zur Allianz, sind König Wrynn zu Ohren gekommen.|n|nIn Anerkennung Eurer Dienste hat der König seinen königlichen Bogenmacher beauftragt, eine besondere Waffe für Euch anzufertigen.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der Ort, an dem Ihr die einzigartigen Bestandteile finden könnt, die für diese Waffe benötigt werden. Reist dorthin und findet das Zielfernrohr von Lord Godfreys Gewehr, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und erhaltet Godfreys Kristallzielfernrohr von Lord Godfrey, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.', },
  },
  [27345] = {
    'Das K.d.V.',
    {'Die Kommunikation zu allen unseren Außenposten an der Front ist abgebrochen, $N. Jetzt gerade habe ich nicht die leiseste Ahnung, wie es unseren Truppen in Gilneas ergeht. Wir müssen die Kommunikation wieder herstellen.|n|nBegebt Euch nach Westen in die Mark und findet unseren Außenposten an der Küste. Die Soldaten dort sind wahrscheinlich alle tot, aber ihr K.d.V. könnte noch funktionieren. Nehmt das Gerät an Euch und kehrt zu mir zurück.', },
    {'Findet die Kommunikationsvorrichtung der Verlassenen.', },
  },
  [27346] = {
    'Der Zeppelinabsturz',
    {'Vor Kurzem ist östlich von hier ein Zeppelin der Goblins abgestürzt. Erst vor ein paar Tagen kam hier eine Abgesandte des Dampfdruckkartells wegen dieser Sache vorbei.|n|nSie war auf der Suche nach Informationen über die Fracht des Zeppelins und dessen Piloten Beezil, aber keiner von uns hat den Absturz wirklich beobachtet. Ich bezweifle, dass sie die Aufräumarbeiten am Wrack und die Bergung der Fracht alleine bewältigen kann.|n|nWenn Ihr etwas Zeit habt, solltet Ihr mal bei Beezils Wrack vorbeischauen. Ihr findet es östlich von hier, in der Nähe der Berge.', },
    {'Sprecht mit Moxie Stahlgrill bei Beezils Wrack.', },
  },
  [27347] = {
    'Korrosionsschutz',
    {'Seht Euch nur um! Alles ist voller Schlamm. Wenn wir nicht bald eine Möglichkeit finden, sie unter Kontrolle zu halten, werden sie das Wrack und die gesamte Zeppelinladung zersetzen und unbrauchbar machen!|n|nIch kann auf keinen Fall mit leeren Händen zurückkehren, $C! Ihr müsst mir helfen, diese Schlamme aufzulösen, bevor sie alles zerstören!|n|nDieses Gerät feuert, sofern es aufgeladen ist, konzentrierte Energie auf einen Schlamm ab und bringt ihn so zur Explosion. Die Kraftkernfragmente des Zeppelins sollten über ausreichend Energie verfügen, um es anzutreiben. Der Kern beim Hauptwrack funktioniert einwandfrei, doch die anderen Kraftkerne laufen nur gelegentlich.', },
    {'Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 10 Schlamme auflöst.', },
  },
  [27348] = {
    'Bergt die Fracht!',
    {'Der Zeppelin hatte Morastwinkels Vorräte für die nächsten sechs Monate geladen! Glücklicherweise konnte Morastwinkel sich bisher mit Tauschgeschäften über Wasser halten, doch auf Dauer ist das keine Lösung.|n|nIch wurde hierher geschickt, um so viele Vorräte wie möglich zu bergen, doch leider sind die Wrackteile über die gesamten Marschen verteilt, was die Sache ziemlich erschwert. Ohnehin denke ich, dass nur die wenigsten Vorräte den Absturz heil überstanden haben. Würdet Ihr mir bei der Bergung helfen?', },
    {'Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 8 Teile der Zeppelinfracht bergt.', },
  },
  [27349] = {
    'Kommunikationsabbruch: Außenposten von Schreckenswacht',
    {'Ich werde Euch nicht anlügen, $N. Was ich von Euch verlange ist mehr oder weniger Selbstmord. Die Wahrscheinlichkeit einer Niederlage beträgt 95%.|n|nAlle Kommunikation zum Außenposten der Schreckenswacht ist abgebrochen. Durch die ständigen Angriffe der Worgen haben wir keine Möglichkeit, zur Schreckenswacht aufzubrechen und nach unseren Soldaten zu schauen. Macht Euch auf den Weg in Richtung Süden zum Außenposten und seht nach unseren Soldaten. Ich werde von jetzt an mit Euch über die Kommunikationsvorrichtung der Verlassenen - dem K.d.V. - in Verbindung bleiben.|n|nHALTET EUCH VON DER HAUPTSTRASSE FERN.', },
    {'Erkundet den Außenposten von Schreckenswacht.', },
  },
  [27350] = {
    'Kommunikationsabbruch: Rutsaks Wacht',
    {'<Das K.d.V. brummt.>|n|nUnser nächster Außenposten ist Rutsaks Wacht, östlich von Schreckenswacht. Sucht Rutsak auf und seht zu, dass Ihr den Stürmern der Worgen entgeht, $N. Diesen Monstern wollt Ihr nicht allein begegnen.|n|nWenn Ihr es in einem Stück dorthin schafft, sucht nach Hauptmann Rutsak.|n|nMacht Euch auf das Schlimmste gefasst.', },
    {'Findet Hauptmann Rutsak in Rutsaks Wacht in den Ruinen von Gilneas.', },
  },
  [27351] = {
    'Eine königliche Belohnung',
    {'Der SI:7 hat Eure Fortschritte mit Interesse beobachtet. Eure Dienste für die Allianz sind bekannt und Geschichten über Eure Taten sind dem König zu Ohren gekommen.|n|nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der Ort, an dem Ihr die fremdartigen Bestandteile finden könnt, die für Eure Waffe benötigt werden. Reist dorthin und beschafft Euch Kommandant Grüntals Wetzstein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.', },
    {'Reist zu Burg Schattenfang und erhaltet Grüntals Wetzstein von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.', },
  },
  [27352] = {
    'Flüssiges Gold',
    {'Nachdem die Geißel wie eine Krankheit durch Stratholme fegte, stellten die Ritter der Silbernen Hand Weihwasser her, um es gegen die Eindringlinge zu nutzen. Sie haben es in kleinen Kisten zusammen mit anderen wichtigen Vorräten gelagert und in der ganzen Stadt verteilt. Leider wurden die Einwohner der Stadt zu Geißeln, bevor die Vorräte je genutzt werden konnten!|n|nDie Vorratskisten werden sich für unsere Zwecke als äußerst nützlich erweisen. Bringt eine Phiole mit Weihwasser von Stratholme zu mir, damit ich es in größeren Mengen herstellen kann.', },
    {'Findet eine Phiole mit Weihwasser von Stratholme.', },
  },
  [27353] = {
    'Segen der Elemente',
    {'Euer Talent hat in den Kreisen der Schamanen viel Aufsehen erregt, $N. Geschichten von Eurer Beherrschung der Elemente und Eurer Hingabe zur Allianz können selbst im Palast vernommen werden.|n|nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.|n|nDie Materialien für Eure Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und erlangt den Talisman von Lord Walden, das Buch der verlorenen Seelen und Essenzen der Geister, die das Schloss heimsuchen.', },
    {'Reist nach Burg Schattenfang und erhaltet den Waldens Talisman, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.', },
  },
  [27354] = {
    'Beherrschung des Arkanen',
    {'Ihr habt Euch als $Gausgezeichneter Student und engagierter Diener:ausgezeichnete Studentin und engagierte Dienerin; der Allianz herausgestellt. Selbst der König hat schon von Euren Leistungen gehört.|n|nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Verzauberer beauftragt, eine besondere Waffe für Euch anzufertigen.|n|nDie Materialien, die für Euren Stab benötigt werden, können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene Erbe der Familie Silberlein, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und erlangt Silberleins verzauberten Kristall von Baron Silberlein, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.', },
  },
  [27355] = {
    'Ein Segen für die Mächtigen',
    {'Dank Eurer Taten bemerkt der König langsam unsere Macht und unseren Wert für die Allianz. Vielleicht werden die Unsrigen langsam akzeptiert.|n|nKönig Wrynn hat in Anerkennung Eurer Dienste den königlichen Verzauberer beauftragt, eine mächtige Waffe für Euch anzufertigen.|n|nDie Materialien dafür sind nur in Burg Schattenfang im Silberwald zu bekommen. Reist dorthin und erlangt die finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen, und Essenzen der Geister, die das Schloss heimsuchen.', },
    {'Reist nach Burg Schattenfang und erhaltet die Finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.', },
  },
  [27356] = {
    'Die Zukunft des Zirkels',
    {'Der Zirkel des Cenarius ist zufrieden mit Eurem Fortschritt, $N. Ihr seid von Wert für alle Druiden. Wir sehen in Euch und Euren Verbündeten die Zukunft unserer Bruderschaft.|n|nDer Zirkel hat entschieden, Euch mit der Herstellung eines einzigartigen Stabs zu ehren.|n|nDie seltenen und mächtigen Materialien für diesen Stab können nur in Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet Lord Waldens Elixiersammlung, eine Ladung mondbestrahltes Holz, und Sehnen der Ghule und Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und erhaltet Waldens Elixiere von Lord Walden, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.', },
  },
  [27357] = {
    'Die gefangene Braut',
    {'Natürlich! Lakota Windweise! Warum ist mir das nicht früher eingefallen?|n|nArnak hat Lakota vor Jahren entführt und versucht, sie in eine Ehe zu zwingen. Sie konnte fliehen, aber in dem Chaos durch die Angriffe auf den Freiwindposten in letzter Zeit konnte er sie wieder schnappen.|n|nSie muss hier irgendwo in der Nähe sein. Sie ist in den letzten Jahren recht mystisch geworden. Ich glaube, dass sie weiß, was man mit den Artefakten der Tauren machen kann.', },
    {'Sprecht mit Lakota Windweise in Düsterwolkengipfel in Tausend Nadeln.', },
  },
  [27358] = {
    'Die gefangene Braut',
    {'Lakota Windweise! Warum ist mir das nicht früher eingefallen?|n|nArnak hat Lakota vor Jahren entführt und mit Gewalt versucht, sie zu seiner Braut zu machen. Sie konnte mit etwas Hilfe fliehen, aber in dem Chaos durch die Angriffe auf den Freiwindposten in letzter Zeit konnte er sie wieder schnappen.|n|nSie muss in der Nähe sein. Sie hat in den letzten Jahren viel Schamanenwissen erworben. Ich bin mir sicher, dass sie uns sagen kann, inwiefern die Rassel, die Niederschrift und die Trommeln wichtig sind.', },
    {'Sprecht mit Lakota Windweise in Düsterwolkengipfel in Tausend Nadeln.', },
  },
  [27359] = {
    'Verstärkung der Argentumdämmerung',
    {'Die Geißel haben eine Art Zauber gewirkt, der mich daran hindert, ein Portal zu öffnen. Daher kann uns auch unsere Verstärkung nun nicht dabei helfen, die Stadt einzunehmen! Es ist wie ein nicht enden wollender Schrei in meinem Kopf! Argh!|n|nIch versuche mein Bestes, um durch die Geräusche dieser Barriere nicht verrückt zu werden. Meine Vermutung ist, dass dieser Schutzwall von den Banshees aufrechterhalten wird. Bringt mir ihre Essenzen – ich glaube, ich kann sie benutzen, um einen Gegenzauber zu wirken, damit die Verstärkung eintreffen kann!', },
    {'Erhaltet 4 Essenzen einer Banshee.', },
  },
  [27360] = {
    'Rache für unsere Soldaten',
    {'Die 7. Legion… Sie haben uns mitten in der Nacht überrannt. Ihr Hauptmann hat Befehle gebrüllt, während die Besatzung des U-Boots meine Männer abgeschlachtet hat. Dann kam er zu mir, sah mir direkt in die Augen und sagte etwas, das ich nie vergessen werde:|n|n"Ich bin Hauptfeldwebel Pietro Zaren, Offizier der 7. Legion. Wenn Ihr in Euren Alpträumen seht - wenn Ihr überhaupt noch schlafen könnt - wie Eure Soldaten massakriert werden, dann erinnert Euch an meinen Namen und zittert!"|n|nRächt meine Soldaten! Tötet die 7. Legion, die das Kathedralenviertel von Gilneas südwestlich von hier besetzt.', },
    {'Tötet 10 Unterseebootmatrosen der 7. Legion.', },
  },
  [27361] = {
    'Vom Licht begünstigt',
    {'Das Licht scheint wirklich hell auf Euch und Eure Hingabe zur Allianz, $N. Ihr seid wahrhaftig ein gutes Beispiel für Eure Priesterkameraden und Kampfgenossen.|n|nIn Anerkennung Eurer Taten hat König Wrynn den königlichen Verzauberer beauftragt, einen besonderen Stab für Euch anzufertigen.|n|nDie Materialien für diese Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.', },
  },
  [27362] = {
    'Elunes Liebling',
    {'Ihr seid ein echter Diener Elunes, ein Beispiel für unser Volk, und ein tapferer Diener der Allianz. Der Tempel des Mondes und der Hof von Sturmwind möchten Eure Leistungen ehren.|n|nWir haben den königlichen Verzauberer beauftragt, einen Stab für Euch zu fertigen.|n|nDie Materialien für Euren Stab können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.', },
  },
  [27363] = {
    'Vielversprechend für den Chirurgenberuf',
    {'Ihr habt Euch als fähig in den Reihen der Priester und als wertvoll für die Leute von Gnomeregan erwiesen. Der Hochtüftler und der König von Sturmwind möchten Eure Arbeit für die Allianz ehren.|n|nSie haben den königlichen Verzauberer beauftragt, einen besonderen Stab anzufertigen.|n|nDie Materialien für diese Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.', },
  },
  [27364] = {
    'Auf wessen Befehl?',
    {'<Das K.d.V. summt.>|n|nDie 7. Legion sind besondere Eliteeinheiten. Sie waren hinter den Kulissen für fast alle größeren Offensiven und Militäreingriffe der Allianz zuständig. Das sind schlechte Neuigkeiten. Wie sind sie nur an unseren Kriegsschiffen vorbei gekommen? Und auf wessen Befehl agieren sie?|n|nWir müssen ihre Befehle irgendwie in die Hände bekommen. Dieser Pietro hat sicherlich wichtige Informationen. Findet ihn im Kathedralenviertel von Gilneas und erledigt ihn. Durchsucht danach seinen Leichnam nach Hinweisen.', },
    {'Findet die Befehle des Oberkommandos.', },
  },
  [27365] = {
    'Eine passende Waffe',
    {'Schon zu Beginn haben Eure Lehrer gewusst, dass Ihr Euch bei der Horde einen Namen machen werdet. Ihr habt mutig gekämpft und Euren Feinden Grund zur Angst gegeben.|n|nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Schmied eine besondere Waffe in Auftrag gegeben.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene Schwert der Familie Silberlein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.', },
    {'Reist zu Burg Schattenfang und erhaltet das Schwert der Familie Silberlein vom Baron, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.', },
  },
  [27366] = {
    nil,
    {'Die Marinesoldaten der Axtbeißer der Horde sind überall an meinem heiß geliebten Strand.|n|n<Der Leutnant deutet in Richtung Norden, entlang der Küste.>|n|nTötet sie.', },
    {'Tötet 12 Marinesoldaten der Axtbeißer am Zwielichtufer im Schattenhochland.', },
  },
  [27367] = {
    'Gidwin Goldzopf',
    {'Meine Jungs sind mir viel wert, versteht mich nicht falsch. Aber ich habe ihnen GESAGT, dass ich FÜNF MINUTEN brauche, um die Pferde zu versorgen und was machen sie? Schließen eine blöde Wette ab und weg sind sie! Ich hätte es besser wissen müssen... es ist immer das Gleiche.|n|nGidwin ist der kurz Gewachsene. Er hat sich in Richtung Norden aufgemacht, den Fluss entlang. Wenn Ihr in diese Richtung unterwegs sein solltet, könnt Ihr ihm sagen, er soll zurückkommen? Wir müssen zur Kapelle des Hoffnungsvollen Lichts und ich habe kein Problem damit, ihn zurückzulassen.', },
    {'Findet Gidwin Goldzopf in den Östlichen Pestländern.', },
  },
  [27368] = {
    'Nur eingehüllt',
    {'Ihr hättet mich im Kampf sehen sollen! Ich hab bestimmt sechs dieser Biester getötet, als...|n|nOh, stimmt, Ihr könnt ja die Leichen sehen. Na gut. Vier der Biester habe ich getötet und dann kam das fünfte an und hat dieses Netz auf mich geschossen. Und noch viel schlimmer: Als es seinen Netzsaft abgeschossen hat, war mein Mund offen!|n|nIch kann dieses Netz nicht zerstören und Ihr werdet es wohl auch nicht können. Aber die Magensäfte von den untoten Spinnendingern könnten das Netz auflösen. Das funktioniert sicher.', },
    {'Erhaltet 8 Phiolen Kryptengalle von den Nerubern im Schreckenstunnel.', },
  },
  [27369] = {
    'Das Rad schmieren',
    {'Entschuldigt mein Verhalten von eben. Ich war einfach sicher, Ihr wärt eines dieser Spinnenbiester, das sich als <Volk> ausgeben wollte.|n|nWie geht es Euch? Gidwin Goldzopf, zu Euren Diensten. Ich bin ein bisschen in Eile, weil ich schnell zurück zu meinem Karawanenwagen muss, aber... könntet Ihr mir vielleicht noch einen Gefallen tun? Meine Freundin Fiona hat einen kleinen Laden und ich glaube, dass einige der Pflanzen, die hier am Flussufer wachsen, für sie von Interesse wären.|n|nIch glaube, wenn ich ihr ein paar tolle Pflanzen mitbringe, wird sie VIEL weniger sauer auf mich sein. Das ist zumindest der Plan.', },
    {'Pflückt 10 Bansheeglocken vom Ufer des Thondroril.', },
  },
  [27370] = {
    'Tarenar Sonnenhieb',
    {'Kaum hatten wir Halt gemacht, haben sie eine Wette abgeschlossen, wer die meisten Untoten in fünf Minuten töten könne.|n|nDas ist jetzt eine Stunde her und ich warte immer noch darauf, dass sie wieder herkommen.|n|nIch habe gesehen, wie Tarenar in Richtung Südosten losgelaufen ist. Aber leider kann ich den Wagen nicht unbeaufsichtigt lassen. Wenn Ihr zufällig in diese Richtung unterwegs sein solltet, könntet Ihr ihn suchen und zu mir zurückschicken?', },
    {'Findet Tarenar Sonnenhieb an der Treppe des Schnitters in den Östlichen Pestländern.', },
  },
  [27371] = {
    'Was ich am besten kann',
    {'Ich erinnere mich an die Zeit zurück, als ich jung war und mich oft in die Geisterlande geschlichen habe, um stundenlang Zombies zu verprügeln. Ich habe nicht einmal eine BEZAHLUNG dafür erhalten. Ich hab es einfach so gemacht.|n|nAber jetzt schaut Euch mal um. Das sind ernst zu nehmende Zombies. Ich wollte gerade damit anfangen, sie zu verprügeln, so wie früher. Wollt Ihr mir helfen?', },
    {'Tötet 5 Missgeburten der Treppe des Schnitters an der Treppe des Schnitters in den Östlichen Pestländern.', },
  },
  [27372] = {
    'Ein Geschenk für Fiona',
    {'Meine Reisegefährtin, Fiona, hat in ihrem Karawanenwagen einen kleinen Laden. Wir beide und unser Freund Gidwin sind auf dem Weg zur Kapelle des Hoffnungsvollen Lichts. Ihr könnt sicher mit uns reisen, wenn Ihr wollt... obwohl Fiona womöglich ein wenig sauer auf mich sein wird.|n|nFiona vergisst aber immer, dass sie sauer ist, wenn man ihr ein Geschenk macht. Tötet nördlich von hier für mich ein paar dieser Seuchenhunde und bringt ihr Blut zu Fiona bei der Karawane unten am Fluss. Sie wird sich über alle Maßen freuen. Wir sehen uns dann dort!', },
    {'Erhaltet 10 Proben des Bluts eines Seuchenhundes.', },
  },
  [27373] = {
    'Auf zur Kapelle des Hoffnungsvollen Lichts',
    {'Jetzt, da die Jungs wieder hier sind, können wir endlich los. Ihr seid in Richtung Osten unterwegs?|n|nEs wäre uns eine Freude, wenn Ihr mit uns reisen würdet. Ich bestehe darauf! Erst gestern bei der Stätte der Heiler habe ich zu Tarenar gesagt: "Wir haben zwei Paladine und mich, um auf den Laden aufzupassen, aber weißt du, was wir wirklich brauchen? $GEinen echten Helden:Eine echte Heldin;!"|n|nSeht mich nicht so an! Ehrlich! Kommt schon, springt auf!', },
    {'Steigt auf Fionas Karawanenwagen am Thondroril in den Östlichen Pestländern.', },
  },
  [27374] = {
    'Der Schlund des Wahnsinns',
    {'Ich kann es nicht glauben, $N. Mein eigener Sohn - mein eigen Fleisch und Blut! Tut sich mit diesen Unholden vom Schattenhammer zusammen. Habt Ihr gesehen, was aus ihm wurde, als er versuchte, die Hochzeit zu zerstören? Oh... warum? Warum?|n|nEs ist diese Bestie, $N. Der gigantische Schlund, der im Westen aus der Erde ragt. "Der Schlund des Wahnsinns!" Mein Sohn sagte, er würde mit ihm sprechen, aber ich dachte, es wären nur Alpträume.|n|nDer Irdene Ring versucht, ihn zu zerstören. Geht zu Erdenrufer Torunskar, westlich von hier, und schaut, ob Ihr helfen könnt!', },
    {'Sprecht am Kreis der Elemente mit Erdenrufer Torunskar.', },
  },
  [27375] = {
    'Die Schwärende Wunde',
    {'Eine Bestie, $N! Ich habe eine Bestie gesehen. Ein riesiger Schlund, ein noch größerer Hunger. Ich kann nicht glauben, dass sie wissen, was sie da losgelassen haben.|n|nEs ist hier. Sein schrecklicher formloser Körper bricht in diesem Augenblick in das Hochland herein.|n|nIch habe Euch in meiner Vision gesehen, $N. Ihr kämpft zusammen mit dem Irdenen Ring, um das Biest zurückzudrängen. Ihr werdet der Dunkelheit gegenübertreten.|n|nGeht jetzt, bevor die Bestie an Macht gewinnt. Sprecht mit Erdenrufer Torunskar am Kreis der Elemente, nordwestlich von hier auf dem Gebirgskamm, hinter dem zerstörten Drakgorlager. Schnell!', },
    {'Sprecht mit Erdenrufer Torunskar am Kreis der Elemente.', },
  },
  [27376] = {
    'Das Maul von Iso\'rath',
    {'Wir sind bereit, die Bestie anzugreifen. Erst müssen wir ihre Tentakel zerstören, dann wird Yevaa ein Ritual durchführen, um einen mächtigen Feuerelementar zu beschwören, den wir in den Schlund werfen werden.|n|nIch möchte, dass Ihr mit unserer ersten Gruppenattacke ausfliegt. Tut nichts, bis sich eine Gelegenheit bietet, dann tretet dem Kampf bei, indem Ihr mit den anderen Schamanen die Tentakel abschneidet.|n|nNehmt einen unserer Greifen, wenn Ihr für den Angriff bereit seid.', },
    {'Steigt auf einen Greifen, um dem Angriff auf Iso\'rath beizutreten.', },
  },
  [27377] = {
    nil,
    {'Wir wussten, dass das eine Möglichkeit war, aber wir hatten keine Ahnung, wie sich die Bestie verteidigen würde. Iso\'raths Körper reagiert schnell auf unsere Bedrohung.|n|nIch kann die Beschwörung von hier aus beendet, aber nur, wenn Ihr Iso\'raths Verteidigung zurückhalten könnt. Beschäftigt sie! Wir werden überleben!', },
    {'Schützt Euch und Erdenruferin Yevaa vor Iso\'raths körperlicher Verteidigung.', },
  },
  [27378] = {
    'Der Weltenbrecher',
    {'Wir haben keine Zeit! Todesschwinge hat zugeschlagen, bevor wir uns gegen ihn aufstellen konnten. Wenn Ihr ihn nicht aufhaltet, endet der Irdene Ring hier und jetzt!', },
    {'Bezwingt Todesschwinge, den Aspekt des Todes.', },
  },
  [27379] = {
    'Die Schrecken des Iso\'rath',
    {'Wir brauchen Euch! Ihr wart in einer Art Alptraum gefangen. Viele der anderen Schamanen sind das immer noch.|n|nEgal... unser Plan fällt auseinander. Einige unserer Schamanen kanalisieren schützende Auren, die die Verdauungsflüssigkeiten bekämpfen und Euch am Leben halten, aber wir müssen die anderen Schamanen vor den Tentakeln retten. Wir können Iso\'rath nicht ohne sie besiegen!|n|nBleibt nicht ohne die anderen Schamanen im Magen, oder Ihr werdet bei lebendigem Leib verdaut!', },
    {'Rettet Hargoth Trübflamm, Erdheiler Duarn, Sturmruferin Jalara und Sturmruferin Mylra.|n|nKehrt in den Schutz der anderen Schamanen zurück, wenn Iso\'raths Verteidigung Euch zusetzt.', },
  },
  [27380] = {
    'Nachtmahr',
    {'Iso\'raths Hirn liegt frei! Der Schamane, den Ihr gerettet habt, sollte Euch in seiner Verteidigung einigermaßen sicher halten.|n|nGreift das Hirn an und zerstört Iso\'rath!', },
    {'Zerstört Iso\'raths Gehirn.', },
  },
  [27381] = {
    'Reisegefährten',
    {'Jetzt wo wir schon hier an diesem Turm sind, können wir auch schauen, ob außer uns noch jemand zur Kapelle des Hoffnungsvollen Lichts unterwegs ist. Je mehr, desto besser, nicht wahr?|n|nFragt doch in der Umgebung, ob uns jemand auf der Reise begleiten möchte. Ich bin sicher, dass wir jemand finden werden, der auch zur Kapelle unterwegs ist.', },
    {'Findet jemanden am Turm der Kronenwache, der sich Eurer Reisegruppe anschließen möchte.', },
  },
  [27382] = {
    'Verseuchte Straßen',
    {'Der Argentumkreuzzug hat diese Türme als Lichter in der Dunkelheit der Pestländer errichtet. Ich bin auf den Pfaden zwischen den Türmen unterwegs, um sie zu schützen und instand zu halten.|n|nIn letzter Zeit wurden die Straßen aber immer gefährlicher. Verseuchte Wildtiere laufen frei herum und die Fledermäuse greifen nichtsahnende Reisende an. Es würde den nächsten Teil meiner Reise sehr erleichtern, wenn Ihr für mich die wilden Tiere aus dem Weg schaffen könntet.', },
    {'Tötet 13 Seuchenfledermäuse entlang des Wegs zum Lichtschildturm.', },
  },
  [27383] = {
    'Klein-Pamela',
    {'Die Schlacht von Darroheim verfolgt mich immer noch, <Volk>. Ich wache in kaltem Schweiß auf, felsenfest davon überzeugt, dass ich noch dort bin. Diese Träume holen mich immer und immer wieder ein.|n|nMit dem Tod meiner Kameraden komme ich einigermaßen klar, aber der Tod meiner Familienmitglieder schmerzt immer noch gnadenlos. Eine meiner Verwandten, die ich bei dem Angriff verloren habe, war meine kleine Nichte Pamela.|n|nWenn Ihr mutig genug seid, Darroheim aufzusuchen, könnt Ihr nach einem Zeichen von meiner kleinen Pammy suchen? Die Ruinen von Darroheim sind südlich von hier.', },
    {'Sucht Pamela Rotpfad in Darroheim.', },
  },
  [27384] = {
    'Pamelas Puppe',
    {'Meine Tante Marlene hat gesagt, ich soll in unserem Haus bleiben, weil mein Vater in den Kampf ziehen muss. Mein Vater ist der mutigste Mann auf der ganzen Welt!|n|nAber ich bin schon so lange hier und er ist nicht gekommen, um mich abzuholen. Manchmal kommen böse Leute und flüstern mir etwas zu und ich will, dass mein Vater sie wegjagt, aber er ist nicht hier!|n|nUnd manchmal, wenn es dunkel wird, möchte ich mit meiner Puppe spielen, aber das kann ich nicht, weil ich sie in der Stadt gelassen habe.|n|nKönnt Ihr vielleicht meine Puppe für mich suchen?', },
    {'Sucht Pamelas Puppe.', },
  },
  [27385] = {
    'Onkel Carlin',
    {'Ich werde mit meiner Puppe spielen, aber mit Papas Schwert will ich doch nicht spielen. Ihr könnt es haben.|n|nOder könnt Ihr es vielleicht doch lieber Onkel Carlin geben? Ich weiß nicht, wo er ist, aber manchmal höre ich ihn weinen. Es klingt, als ob er in der Nähe ist, nördlich von hier. Ich hoffe, er weint nicht wegen mir! $N, könnt Ihr meinen Onkel suchen und ihm sagen, dass es mir gut geht? Wenn Ihr ihn findet, sagt ihm, ich warte auf ihn und ich will die Geschichte hören, die er mir immer erzählt hat... die von den Kaninchen und der Beerenmarmelade! Die Geschichte ist so witzig!', },
    {'Kehrt zu Carlin Rotpfad am Turm der Kronenwache in den Östlichen Pestländern zurück.', },
  },
  [27386] = {
    'Ein seltsamer Historiker',
    {'Dieses Schwert hat Joseph Rotpfad gehört, Pamelas Vater - aber das wisst Ihr wahrscheinlich schon. Ich wünschte, Joseph könnte wieder bei seiner Tochter sein, aber das ist unmöglich. Seine Seele wurde von der Geißel verdreht und er wurde zu einem Monster.|n|nPamelas Schicksal ist besiegelt, aber vielleicht können wir sein Schicksal ändern.|n|nEine komische Gnomin kam hier vor Kurzem am Turm an. Sie heißt Chromie. Bringt dieses Schwert zu ihr. Ich habe das Gefühl, dass sie uns helfen kann.', },
    {'Bringt Josephs Jagdklinge zu Chromie.', },
  },
  [27387] = {
    'Bösewichte von Darroheim',
    {'Die \'Annalen von Darroheim\' berichten von den Bösewichten dieser Schlacht. Sie berichten, wie der Ghulfürst Horgus der Verheerer von Allianztruppen während der Schlacht vernichtet wurde. Er wurde im Vorgebirge nördlich von hier getötet und dort liegt sein Schädel noch heute.|n|nMarduk der Schwarze wurde nie besiegt, aber sein sagenhaftes Schwert verrostet nun herrenlos... Man kann es in der Nähe der Straße südöstlich von uns finden.|n|nStellt diese Gegenstände sicher, $N. Ich weiß nicht, warum, aber ich bin sicher, dass ihr Schicksal in Euren Händen liegt.', },
    {'Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Chromie am Turm der Kronenwache in den Östlichen Pestländern.', },
  },
  [27388] = {
    'Helden von Darroheim',
    {'Die Helden von Darroheim hatten ebenfalls Relikte und darin sind weitere wertvolle Erinnerungen gefangen. Sprecht zunächst mit Carlin und erhaltet die erweiterten Annalen von Darroheim. In diesem Folianten findet sich die Geschichte, die Eure Reise durch die Zeit führen wird.|n|nDanach müsst Ihr westlich reisen, um zu Marris\' Siedlung zu gelangen. Der ehemalige Besitzer von Marris\' Siedlung sammelte Relikte aus der Schlacht um Darroheim. Warum er das tat, kann ich nicht mit Sicherheit sagen. Sammelt diese Relikte und kehrt zu mir zurück.', },
    {'Erhaltet die Erweiterten Annalen von Darroheim von Carlin Rotpfad sowie Davils Buchband und Rotpfads Schild in Marris\' Siedlung.', },
  },
  [27389] = {
    'Marodeure von Darroheim',
    {'Ich benötige ein seltenes Reagenz für den mächtigen Zauberspruch, den zu wirken ich vorhabe: Schädel der Geißelschergen, die an der Schlacht von Darroheim teilnahmen.|n|nNehmt diesen Kristall und jagt Champions der Geißel, um an ihre Schädel zu gelangen. Der Kristall ist verzaubert: Er wird widerhallen, wenn Ihr ihn über den Schädel eines Champions haltet, der an der Schlacht teilgenommen hat. Bringt mir die Schädel der Krieger, bei denen der Kristall widerhallt.|n|nGeht, $N. Ihr werdet die Champions der Geißel im Fungustal nördlich von hier finden. Geht.', },
    {'Bringt 5 widerhallende Schädel zu Chromie am Turm der Kronenwache in den Östlichen Pestländern.', },
  },
  [27390] = {
    'Die Schlacht um Darroheim',
    {'Nun, $N, Ihr werdet an der Schlacht von Darroheim teilnehmen und Joseph Rotpfad retten.|n|nPlatziert dieses Reliktbündel auf dem Marktplatz von Darroheim, und die Geister von Darroheim werden sich erheben. Nehmt an der Schlacht teil und sorgt dafür, dass die folgenden zwei Dinge eintreten: Davil muss den Tod von Horgus überleben und Rotpfad muss überleben, um erst verdorben und dann besiegt zu werden.|n|nNachdem Ihr den verderbten Rotpfad besiegt habt, wird seine Seele gerettet sein. Sprecht mit ihm und kehrt dann zu seiner Tochter Pamela zurück.', },
    {'Legt das Reliktbündel auf den Marktplatz von Darroheim.|n|nVerhindert Davil Lichterscheins Tod, bis Horgus stirbt.|n|nVerhindert Hauptmann Rotpfads Tod, bis Rotpfad der Verderbte erscheint.|n|nBesiegt Rotpfad den Verderbten.|n|nSprecht mit dem Geist von Joseph Rotpfad, sobald er auf dem Marktplatz erscheint.', },
  },
  [27391] = {
    'Versteckte Schätze',
    {'Papa sagte, ich solle Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe draußen hinter dem Haus.|n|nEr wollte außerdem, dass ich Euch danke. Habt Ihr ihm einen Gefallen getan? Habt Ihr ihm gesagt, dass Ihr meine Puppe gefunden habt?|n|nNun, hier ist jedenfalls der Schlüssel. Und habt Dank, $N. Danke! Ihr seid $Gein sehr netter Mann:eine sehr nette Dame;!', },
    {'Bringt Josephs Schlüssel zu Josephs Truhe.', },
  },
  [27392] = {
    'Ich soll Euch das eigentlich nicht verraten',
    {'Mein Papa hat immer zwei Schwerter gehabt: eines für den Kampf und eines für die Jagd. Ich sollte eigentlich die Schwerter nicht anfassen, aber ich wusste, wo er sie versteckt.|n|nEines Tages hat er meiner Mama gesagt, dass er einen "einsamen Jäger" in den Hügeln östlich von hier bekämpfen würde, aber er hat sein Schwert für die Jagd von Tieren mitgenommen! Als er zurückkam, hatte er kein Schwert bei sich.|n|nWenn Papa zurückkommt, wird er sich so freuen, wenn ich sein Jagdschwert für ihn habe! Könnt Ihr es für mich finden?', },
    {'Erhaltet Josephs Jagdklinge von dem Einsamen Jäger in den Östlichen Pestländern.', },
  },
  [27393] = {
    'Der Ruf der Klinge',
    {'Ich spüre, wie eine starke Macht in den Ruinen nach mir ruft. Könntet Ihr noch einmal auf dem südlichen Schlachtfeld für mich nachsehen? Ich bin mir sicher, dass dort etwas sein muss.', },
    {'Untersucht das Schlachtfeld am südlichen Ende der Ruinen von Vashj\'ir.', },
  },
  [27394] = {
    'Der Ruf der Klinge',
    {'Ich spüre, wie eine starke Macht in den Ruinen nach mir ruft. Könntet Ihr noch einmal auf dem südlichen Schlachtfeld für mich nachsehen? Ich bin mir sicher, dass dort etwas sein muss.', },
    {'Untersucht das Schlachtfeld am südlichen Ende der Ruinen von Vashj\'ir.', },
  },
  [27395] = {
    'Die Waffe eines Schützen',
    {'Ihr habt die Wege der Jäger schnell erlernt, $N. Eure Fähigkeiten sind für die Horde äußerst wertvoll und Ihr seid beispielhaft für den Nachwuchs.|n|nAls Belohnung für Eure Fortschritte und Eure harte Arbeit hat der Kriegshäuptling bei seinem Bogenmacher die Herstellung einer besonderen Waffe in Auftrag gegeben.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt das Zielfernrohr von Lord Godfreys Gewehr, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und erhaltet Godfreys Kristallzielfernrohr, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.', },
  },
  [27396] = {
    'Klinge der Zerschmetterten Hand',
    {'Viele Mitglieder der Zerschmetterten Hand überleben ihre Ausbildung nicht, $N. Ihr habt nicht nur überlebt, sondern werdet bald auch eine gefürchtete Klinge für die Horde darstellen.|n|nAls Belohnung für Euren Fortschritt hat der Kriegshäuptling bei seinem eigenen Schmied eine Waffe in Auftrag gegeben.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und beschafft Euch Kommandant Grüntals Wetzstein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und erhaltet Grüntals Wetzstein von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.', },
  },
  [27397] = {
    'Tergas Aufgabe',
    nil,
    nil,
  },
  [27398] = {
    'Die Schlacht ist gewonnen, der Krieg geht weiter',
    {'Wir haben die Truppen des Feindes hier besiegt, $N. Aber der Hyjal ist nicht der einzige Ort, an dem unsere Feinde gegen uns vorrücken.|n|nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.|n|nErdsprecher Naraat am Östlichen Erdschrein in Sturmwind wird Euch weitere Anweisungen erteilen.', },
    {'Sprecht mit Erdsprecher Naraat am Östlichen Erdschrein in Sturmwind.', },
  },
  [27399] = {
    'Die Schlacht ist gewonnen, der Krieg geht weiter',
    {'Wir haben die Truppen des Feindes hier besiegt, $N. Aber der Hyjal ist nicht der einzige Ort, an dem unsere Feinde gegen uns vorrücken.|n|nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.|n|nScharfseher Krogar am Westlichen Erdschrein in Orgrimmar wird Euch weitere Anweisungen erteilen.', },
    {'Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.', },
  },
  [27400] = {
    'Beherrschung des Arkanen',
    {'Alle Eure Lehrer sind sich einig, $N, dass Ihr für einen Gesellen unglaubliches Talent zeigt. Selbst der Kriegshäuptling hat von Eurem schnellen Fortschritt gehört.|n|nAls Belohnung für Eurer Verständnis für das Erlernte hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines besonderen Stabs in Auftrag gegeben.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das magische Erbe der Familie Silberlein, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und erlangt Silberleins verzauberten Kristall von Baron Silberlein, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.', },
  },
  [27401] = {
    'Was uns morgen erwartet',
    {'<Das K.d.V. summt.>|n|nSeht Euch im Kathedralenviertel um. Dort sollte irgendwo ein Teleskop sein, das die 7. Legion zur Beobachtung benutzt. Findet es und benutzt es, um den Hafen auszuspähen. Wir müssen herausfinden, wie die 7. Legion an unserer Flotte vorbeigekommen ist.|n|nBeeilt Euch, $N. Wir können diese Bestien nicht sehr viel länger zurückhalten.|n|nWas uns morgen wohl erwartet?', },
    {'Benutzt das Teleskop der 7. Legion, um den Hafen auszuspähen.', },
  },
  [27402] = {
    'Zeichen der Macht',
    {'Ihr erlernt unsere Wege in einem atemraubenden Tempo, $N, und ich bin bei Weitem nicht der Einzige, der von Eurem Fortschritt beeindruckt ist. Der Kriegshäuptling selbst hat Eure Taten schon zur Kenntnis genommen.|n|nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Verzauberer die Herstellung eines Stabes in Auftrag gegeben.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und erlangt die finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und Essenzen der Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und erhaltet die Finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.', },
  },
  [27403] = {
    'Ein echter Sonnenläufer',
    {'Ich habe Eure Ausbildung beobachtet, $N. Ihr habt den Weg eines beispielhaften Sonnenläufers eingeschlagen und seid ein mutiger Verteidiger der Horde und ein Anhänger unserer Wege.|n|nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Schmied eine besondere Waffe in Auftrag gegeben.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren, und 5 ewige Sehnen.', },
  },
  [27404] = {
    'Die Zukunft des Zirkels',
    {'Der Zirkel des Cenarius ist zufrieden mit Eurem Fortschritt, $N. Ihr seid von Wert für alle Druiden. Wir sehen in Euch und Euren Verbündeten die Zukunft unserer Bruderschaft.|n|nDer Zirkel hat entschieden, Euch mit der Herstellung eines einzigartigen Stabs zu ehren.|n|nDie seltenen und mächtigen Materialien für diesen Stab können nur in Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet Lord Waldens Elixiersammlung, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und erhaltet Waldens Elixiere von Lord Walden, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.', },
  },
  [27405] = {
    'Rückzug!',
    {'<Das K.d.V. summt.>|n|n<Im Hintergrund ist Worgengeheul zu vernehmen.>|n|n$N, hört Ihr mich? Kommen, $N. Das ist wahrscheinlich meine letzte Übertragung. Die Worgen haben den Gefechtsstand der Verlassenen überrannt. Es ist nur eine Frage der Zeit, bis wir den Stützpunkt verlieren. Belmont und die Val\'kyr Arthura sind weg. Belmont meinte, er wird Euch in Glutstein treffen, nordöstlich von hier. Findet Belmont, $N. Unsere Mission - unsere Existenz - hängt davon ab.|n|nIhr seid unsere letzte Hoffnung.', },
    {'Findet Todespirscherkommandant Belmont in Glutstein in den Ruinen von Gilneas.', },
  },
  [27406] = {
    'Ein Mann namens Godfrey',
    {'Lord Vincent Godfrey hat sein Leben mit der Verteidigung des Königreich Gilneas verbracht. Als der Fluch der Worgen sein Land verheerte, war Godfrey der Erste in Gilneas, der die Waffen gegen die Bestien erhob. Es wird gesagt, dass Godfrey sein Leben nahm, als er herausfand, dass sein König dem Fluch zum Opfer gefallen war. Lieber sei er tot, als dass er den Kreaturen diene, gegen die er sein Land verteidigt hatte.|n|nWir werden ihm eine zweite Chance geben, $N. Zusammen werden wir die Schlacht nach Südosten vorantreiben, nach Witterfront, und dort seinen Leichnam einholen.', },
    {'Findet die Leiche von Lord Vincent Godfrey.', },
  },
  [27407] = {
    'Blutsumpffedern',
    {'Überrascht Euch Broggs Anwesenheit, $R? Keine Sorge! Die Goblins von Morastwinkel sind Broggs Freunde und Ihr könntet es auch werden.|n|nBrogg hat Brackenwall verlassen, nachdem der neue Oberanführer nicht Rache an den Drachkin geübt hatte, die für die Zerstörung unserer alten Heimat und den Tod vieler alter Freunde von Brogg verantwortlich sind. Brogg ist hierhergekommen, um die Geister seiner Freunde zur letzten Ruhe zu betten und für sie Rache zu üben, doch Brogg braucht Hilfe. Für das Ritual braucht Brogg Federn mit mächtiger Magie, Federn wie die der Raptoren aus dem Blutsumpfbau.', },
    {'Sammelt 5 Blutsumpffedern von Blutsumpfraptoren.', },
  },
  [27408] = {
    'Das Banner der Steinbrecher',
    {'Als die Drachen über Broggs alte Heimat herfielen, flohen die Steinbrecheroger und ließen alles zurück, sogar das Klanbanner.|n|nBrogg weiß, dass das Banner tief im Ogerhort, dem heutigen Flammenbau, aufbewahrt wurde. Brogg braucht das Klanbanner für seine Rache an den Drachen, die seine Freunde auf dem Gewissen haben.|n|nDer alte Hort von Broggs Klan, der Flammenbau, befindet sich nordwestlich von Morastwinkel und überall treiben sich Drachkin herum. Das Banner befindet sich tief in der Höhle. Seid vorsichtig, $N.', },
    {'Beschafft das Banner der Steinbrecher aus Flammenbau.', },
  },
  [27409] = {
    'Die Essenz der Feindschaft',
    {'Damit Brogg das Totem für sein Ritual herstellen kann, benötigt er die Essenzen der Kreaturen, die seine Freunde getötet haben. Der Hass und die Wut von Broggs Feinden wird die Magie seiner Rache verstärken.|n|nTötet Aschenschweife, Späher oder Bannschuppen der Feuermähnen und wendet Broggs Totem auf ihren Leiche an. Denkt daran, dass nur tote Drachkin ihre Essenzen freigeben!|n|nDie Kreaturen, die Ihr sucht, befinden sich im Flammenbau im Nordwesten und in den Ruinen der Steinbrecher im Norden.', },
    {'Bringt 10 Essenzen eines schwarzen Drachkin zu Brogg in Morastwinkel.', },
  },
  [27410] = {
    'Geister der Festung der Steinbrecher',
    {'Brogg hat das Totem fertig gestellt, mit dem Ihr den Geistern seiner Freunde Frieden geben könnt. Als die Drachkin über uns herfielen, töteten sie alle Steinbrecher, die nicht rechtzeitig fliehen konnten. Brogg entkam zusammen mit Oberanführer Mok\'Morokk. Seitdem hoffte er auf einen gemeinsamen Gegenangriff aller überlebenden Steinbrecher.|n|nDoch der Gegenangriff fand nie statt und die Geister der Gefallenen verfolgen Brogg und die anderen noch immer. Nehmt das Totem und begebt Euch zu den Ruinen der Steinbrecher im Norden. Verwendet es in der Nähe von Ogerskeletten, um ihre Geister anzulocken. Besiegt die Geister und ermöglicht ihnen und ihren Knochen die letzte Ruhe.', },
    {'Gebt 10 Geistern der Steinbrecher bei den Ruinen der Steinbrecher ihre letzte Ruhe.', },
  },
  [27411] = {
    'Herausforderung für den schwarzen Drachenschwarm',
    {'Brogg kann es kaum erwarten, endlich Rache an dem schwarzen Drachenschwarm der Marschen zu üben. $N, Ihr habt mir sehr dabei geholfen, mich auf diesen Moment vorzubereiten. Werdet Ihr mir auch weiterhin zur Seite stehen?|n|nNehmt Broggs Klanbanner und reist in Richtung Osten, bis Ihr auf eine Höhle trefft, die wie das Maul eines Drachen aussieht. Stellt das Banner der Steinbrecher direkt vor dem Höhleneingang auf und überbringt Onyxia Broggs Herausforderung.|n|nBrogg und die Steinbrecher werden Ihr Land zurückerobern!', },
    {'Platziert das Banner der Steinbrecher am Eingang zu Onyxias Hort und besiegt alle, die reagieren.', },
  },
  [27412] = {
    'GESUCHT: Schlächterklaue der Gefräßige',
    {'Reisende und Mitarbeiter des Dampfdruckkartells werden gebeten, den Blutsumpfbau westlich der Siedlung weiträumig zu umgehen.|n|nDas gesamte Areal wird von äußerst gefährlichen Raptoren bewohnt. Das Leittier, Schlächterklaue der Gefräßige, ist für den Tod von mindestens zwei Ingenieuren des Dampfdruckkartells verantwortlich.|n|nDrazzit Tropfhahn wurde autorisiert, jeden, der der Bedrohung durch Schlächterklaue ein Ende setzt, großzügig zu entlohnen.', },
    {'Tötet Schlächterklaue den Gefräßigen und meldet Euch anschließend bei Drazzit Tropfhahn in Morastwinkel.', },
  },
  [27413] = {
    'Entwindet den Drachen',
    {'Nachdem der Zeppelin mitsamt unseren Vorräten abgestürzt ist, gehen uns langsam die Medikamente und Verbände aus.|n|nWir tun, was wir können, aber inmitten all dieser Insekten, umgeben von Feinden, bleiben Verletzungen nicht aus. Ich habe kürzlich eine Pflanze entdeckt, welche die Wundheilung unterstützt und Schmerzen lindern kann, doch unser Pflanzenvorrat geht ebenfalls zur Neige.|n|nMan nennt sie Drachenwinde und sie wächst im Drachendüster und im Drachensumpf östlich der Siedlung. Die Pflanze besteht aus gewundenen Stängeln und wenn man sie ansieht, scheint sie zu pulsieren.', },
    {'Sammelt 8 Stängel der Drachenwinde in Drachendüster oder in Drachensumpf.', },
  },
  [27414] = {
    'Die Brut identifizieren',
    {'Während der törichte Narr Mok\'Morokk seine Macht genießt und Tharg mit den Dämonen des Kummers und der Rache ringt und um die Führerschaft des Klans buhlt, scheine ich der Einzige zu sein, der die Ursache der Aggression in unserer alten Heimat herausfinden möchte.|n|nWarum der verwirrte Blick, $N? Erwartet Ihr, dass ich wie ein tumber Grobian spreche, nur weil ich ein Oger bin?|n|nDoch zurück zum Geschäft, bringt mir die Herzen und Zungen der Welpen und Jungtiere. Ich werde die Wurzel dieses Übels finden...', },
    {'Draz\'Zilb in Brackenwall hätte gern, dass Ihr ihm 7 sengende Zungen und 7 sengende Herzen bringt.', },
  },
  [27415] = {
    'Die Brut von Onyxia',
    {'Onyxias Brut wurde über das Drachendüster verstreut. Es dürfen auf keinen Fall weitere Welpen schlüpfen.|n|nBegebt Euch eilig zum Drachensumpf in den Düstermarschen. Gewiss hat sie dort einen Hort angelegt. Sucht die Eier der bösen Großdrachen und vernichtet sie.|n|nWir können das Dorf der Steinbrecher nie zurückerobern, wenn das Umland eine Brutstätte bleibt.|n|nWas Mok\'Morokk angeht... für den Jammerlappen habe ich andere Pläne.', },
    {'Zerstört 5 Eier von Onyxia.', },
  },
  [27416] = {
    'Die Brut von Onyxia',
    {'Das Dorf der Steinbrecher wurde von der Brut von Onyxia überrannt. Aber warum sollte die Tochter des schwarzen Drachenlords Todesschwinge über unser Land herfallen?|n|nDas ist sehr beunruhigend. Gewiss wurde Onyxia aus einem anderen Grund hergeschickt, als eine kleine Schar von Ogern zu belagern.|n|nVerständigt unverzüglich Mok\'Morokk! Es muss gehandelt werden.', },
    {'Sprecht mit Oberanführer Mok\'Morokk in Brackenwall.', },
  },
  [27417] = {
    'Die Brut von Onyxia',
    {'Ihr lasst mich jetzt in Ruhe. Sagt Draz\'Zilb, wir bleiben hier. Keine schwarzen Großdrachen hier.', },
    {'Sprecht mit Draz\'Zilb in Brackenwall.', },
  },
  [27418] = {
    'Fordert Oberanführer Mok\'Morokk heraus',
    {'Ihr wagt es, Oberanführer Mok\'Morokk herauszufordern?|n|nHa!|n|nIch zerschmettern einen Winzling von $R!|n|nIhr mir sagen, wenn bereit für ordentliche Tracht Prügel.', },
    {'Besiegt Mok\'Morokk und bringt die Nachricht zu Draz\'Zilb in Brackenwall.', },
  },
  [27419] = {
    'Armee des schwarzen Großdrachen',
    {'Mok\'Morokk wurde von Rexxar zum Oberanführer gemacht. Ihm liegt mehr an Macht als an den Ogern.|n|nSchwarze Großdrachen töten viele Oger. Töten Thargs Frau. Mok\'Morokk sagt uns, wir müssen fliehen. Lässt uns hierher kommen.|n|nOger sollten kämpfen. Oger nicht gut im Weglaufen. Mok\'Morokk schert sich nur um Mok\'Morokk.|n|nFür mich die Ruinen der Steinbrecher Heimat. Mir gefallen im Süden. Dieser Ort nicht Heimat.|n|nHelft Ogern, Armee der schwarzen Großdrachen zu bekämpfen. Ich wollen Rache. Ich wollen nach Hause.', },
    {'Tharg in Brackenwall möchte, dass Ihr 10 Späher der Feuermähnen, 10 Aschenschweife der Feuermähnen und 5 Bannschuppen der Feuermähnen tötet.', },
  },
  [27420] = {
    'Das Unvermeidliche hinauszögern',
    {'Ihr habt ein gutes Auge, wenn Ihr mich hier in meinem Versteck im Gras sehen konntet.|n|nDas Fungustal liegt vor uns, eine Gegend, an die sich die Geißel noch immer klammert. Sie benutzen schwebende Konstrukte, um das Land ständig neu zu verseuchen, damit es so abstoßend bleibt, wie es jetzt ist.|n|nDie Konstrukte werden von Runen der dunklen Adepten und der Schattenmagier gesteuert. Nehmt die Kontrollrunen der Kultisten an Euch, zielt damit auf die Seuchenverbreiter und erzeugt mit diesem Partikel eine Überlast. Das Ergebnis sollte recht amüsant sein.', },
    {'Erhaltet Kontrollrunen von den dunklen Kultisten und Schattenmagiern und benutzt das überladene Partikel, um 3 Seuchenverbeiter zu zerstören.', },
  },
  [27421] = {
    'Mitten im Tod ist Leben',
    {'Die Streitmächte der Geißel haben es geschafft, jeglichem Leben im Fungustal ein Ende zu bereiten. Das Einzige, was noch zu finden ist, sind die Überreste verfaulter Pilze und versengte Gräser. In den drei Ecken des Tals sind drei große Ziggurats zu finden, in denen die Geißel ihre Toten reanimiert und neue Soldaten für das Schlachtfeld einberuft.|n|nDoch selbst an diesem bösen, leblosen Ort kann Leben gedeihen. Nehmt diese Samen und planzt sie in die Zentren der Ziggurats. Beweist ihnen, dass sich das Leben durchsetzen wird.', },
    {'Pflanzt Raynes Samenkörner in den Zentren der drei Ziggurats im Fungustal.', },
  },
  [27422] = {
    'Eine Stadt unter Belagerung',
    {'Wir werden die Östlichen Pestländer nie unter Kontrolle bekommen, wenn wir Stratholme nicht im Besitz haben. Stratholme ist nicht nur ein strategisch unglaublich wichtiger Ort, sondern auch die Heimat der Anführer unserer Feinde - Balnazzar und Baron Aurius Totenschwur. Ihre Armeen der Auferstandenen und der Geißel drohen jedoch, alle unsere Fortschritte nichtig zu machen.|n|nDer Argentumkreuzzug ist wie geschaffen, sich dieser Aufgabe anzunehmen. Reist nach Westen, betretet Stratholme durch das Haupttor, und sprecht mit Rottenkommandant Steinberster. Er wird Euch weitere Anweisungen geben.', },
    {'Sprecht mit Rottenkommandant Steinberster.', },
  },
  [27423] = {
    'Widerstand ist zwecklos',
    {'<Das K.d.V. summt.>|n|nHier spricht Kommandantin Lorna Crowley von der Gilnearischen Befreiungsfront. Wenn Ihr diese Nachricht hört, bedeutet das, dass die Allianz Gilneas wieder eingenommen hat. Legt Eure Waffen nieder und kapituliert. Wenn Ihr dieser Aufforderung nicht nachkommt, steht Euch der sichere Tod bevor.|n|nUnsere Streitmächte sind über Euren Standort informiert und werden in Kürze eintreffen. Widerstand ist zwecklos.', },
    {'Tötet 20 Kämpfer der Worgen.', },
  },
  [27424] = {
    'Oberanführer Mok\'Morokks Sorgen',
    {'Verbeugen Euch vor Oberanführer Mok\'Morokk!|n|nRexxar mich machen zu mächtigem Anführer von Steinbrecherklan!|n|nIch gut Anführer. Ich Klan sicher machen.|n|nGroße Drachen kommen und machen Feuer in alte Heimat. Ich klug Oger. Finden neu Heimat für Klan hier.|n|nAlte Heimat so schnell verlassen, ich Sachen vergessen. Winzig $R, gehen mein Sachen holen. Gehen nach Süden und suchen mein lecker Grog, mein Schnupftabak und mein Geldkassette. Ich Euch mögen, wenn Ihr das tun. Ihr in Flammenbau und Ruinen der Steinbrecher schauen... sie dort sein, ich sicher!', },
    {'Holt Oberanführer Mok\'Morokks Grog, Mok\'Morokks Schnupftabak und Mok\'Morokks Geldkassette aus Düstermarschen.', },
  },
  [27425] = {
    'Der entscheidende Grimmweis',
    {'Ich habe mich mit Inspektor Tarem über die Beweise, die Ihr bei den Ruinen des Gasthauses "Zur Süßen Ruh" gefunden habt, unterhalten. Er ist sich sicher, dass die Hufabdrücke und der Schild auf den Taurenklan der Grimmtotem hindeuten.|n|nBedenkt man die jüngsten Berichte über die zunehmenden Aktivitäten der Grimmtotem in den Marschen, so handelt es sich sicherlich nicht um einen Zufall. Bitte geht und sprecht mit Hauptmann Darill, er ist so eine Art Experte in Sachen Grimmtotem. Folgt der Straße aus dem Dorf Richtung Norden zur Nordwacht. Es ist der zweite Außenposten entlang der Straße.', },
    {'Erstattet Hauptmann Darill bei der Nordwacht Bericht.', },
  },
  [27426] = {
    'Bestätigung des Verdachts',
    {'Die Grimmtotem sind vielleicht der kriegerischste Klan der Tauren, aber sie sind keineswegs unorganisiert. Sollten sie das Gasthaus "Zur Süßen Ruh" wirklich in Brand gesteckt haben, dann nur auf Befehl von einem der Klanältesten.|n|nIm Nordwesten liegt eine große Siedlung der Grimmtotem, das Dorf der Schwarzhufe. Sie haben sie als Ausgangsbasis für ihre Angriffe auf den Turm genutzt, ich bin mir jedoch ganz sicher, dass Ihr dort auch die Befehle finden werdet. Sucht bei den Ältesten im Dorf nach dem Verbleib der Pläne.', },
    {'Erlangt 4 Notizen der Grimmtotems von den Ältesten der Grimmtotems. Setzt die Teile zusammen, um die Schlachtpläne der Grimmtotems zu sehen.', },
  },
  [27427] = {
    'Waffen der Grimmtotem',
    {'Wenn die Ausrüstung, die Ihr bei den Ruinen des Gasthauses gefunden habt, zu einem Angriffstrupp der Grimmtotem gehörte, dann gibt es vermutlich noch mehr davon in ihrem Lager im Nordwesten.|n|nBis jetzt konnten wir noch nicht viel über das Dorf der Schwarzhufe in Erfahrung bringen. Ausgehend von der Größe ihrer Angriffstrupps, schätzen wir jedoch, dass sich dort eine größere Streitmacht aufhält.|n|nTut, was auch immer Ihr tun müsst, um einige ihrer Ausrüstungsgegenstände zu erbeuten, damit wir sie mit Eurem Fund beim Gasthaus vergleichen können.', },
    {'Hauptmann Darill bei der Nordwacht möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.', },
  },
  [27428] = {
    'Tabethas Unterstützung',
    {'Ich kann keine Männer mehr entbehren, um Euch bei der Suche nach einem zweiten Außenposten der Grimmtotem zu helfen. Ich wüsste aber jemanden, der Euch behilflich sein könnte.|n|nTief im Morast, im Süden, liegt ein kleines Gehöft, das Tabetha gehört. Sie mag zwar wie eine alte Einsiedlerin erscheinen, aber in Wirklichkeit ist sie eine Magierin und angesehene Wahrsagerin. Folgt der Straße Richtung Süden bis zu ihrem Hof und bittet sie, Euch bei der Suche nach den Tätern, die für das Massaker beim Gasthaus "Zur Süßen Ruh" verantwortlich sind, zu helfen.', },
    {'Sprecht mit Tabetha auf ihrem Hof.', },
  },
  [27429] = {
    'Brennt den Grollhornposten nieder!',
    {'Man muss nicht hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen "Nachbarn" hier heraufbeschwören. Falls es sich bei ihnen wirklich um diejenigen handelt, die das Gasthaus "Zur Süßen Ruh" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.|n|nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt nördlich von meinem Hof, in der Nähe der Straße. Ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotems haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totem förmlich angekündigt.', },
    {'Benutzt Tabethas Fackel, um das nördliche Zelt, das östliche Zelt und das nordöstliche Zelt am Grollhornposten in Flammen zu setzen.', },
  },
  [27430] = {
    'Gerechtigkeit im Namen der Familie Hyal',
    {'Die Grimmtotem waren zwar lediglich eine Plage für mich, aber dennoch sollte Hauptmann Mumm von Euren Taten erfahren. Berichtet ihm, dass Ihr diejenigen, die für den Anschlag auf das Gasthaus "Zur Süßen Ruh" verantwortlich sind, gefunden und bestraft habt.|n|nEs ist zwar zu spät, um Jim Hyals Familie zu retten, aber vielleicht denken die Grimmtotem demnächst zweimal nach, bevor sie jemanden aus Theramore angreifen.', },
    {'Sprecht mit Hauptmann Garran Mumm bei der Wehrzitadelle in Theramore.', },
  },
  [27431] = {
    'Aus dem Gleichgewicht gebracht',
    {'<Harrison grinst.>|n|nDas ist es, $N. Die Teile, die wir brauchen, sind in diesen Statuen versteckt!|n|nSie sehen aus, als wären sie sowieso ein wenig aus dem Gleichgewicht... Ein kleiner Stupser vielleicht...|n|nEure Untersuchungen schreiten ordentlich voran, muss ich sagen. Wenn Ihr Euch bewerben würdet, könnte aus Euch eines Tages <ein feiner Archäologe/eine feine Archäologin> werden.', },
    {'Sprecht mit Harrison Jones in der Kammer der Sterne.', },
  },
  [27432] = {
    'Zaeldarr der Ausgestoßene',
    {'Könnt Ihr Euch vorstellen, dass wir uns nach dem ganzen Ärger in den Pestländern... jetzt auch noch um Diebe sorgen müssen? Nicht einfach gewöhnliche Diebe, Trolldiebe.|n|nUnd nicht einfach gewöhnliche Trolldiebe. Tote Trolldiebe!|n|nSie werden von diesem großen toten Troll namens Zaeldarr dem Ausgestoßenen angeführt, kommen nachts hierher und stehlen Leichen von unseren Friedhöfen. Dann schaffen sie sie zu ihrem üblen Versteck für tote Trolle - dem Tiefgewölbe im Südwesten.|n|nGeht dorthin und schaltet Zaeldarr aus, $N. Ich habe seine Schandtaten satt!', },
    {'Besorgt Zaeldarrs Kopf von Zaeldarr dem Ausgestoßenen.', },
  },
  [27433] = {
    nil,
    {'Unsere Panzer müssen zurückgezogen werden, und das bedeutet, dass wir Arbeiten auf dem Schlachtfeld verrichten müssen.|n|nZerstört ein paar von den Diamantklingenschreddern, die diese kleinen Monster benutzen, um die Bäume an der Küste zu fällen, und bringt mir einen Haufen der Schredderteile, die noch verwendbar sind. Wir basteln damit etwas, um die Panzer wieder einsatzbereit zu machen.', },
    {'Zerstört Diamantenklingenschredder, um 5 misshandelte Schredderteile zu erlangen.', },
  },
  [27434] = {
    'Der Pfad der Adepten',
    {'Eure Lehrlingszeit neigt sich dem Ende zu, $N. Ihr seid bereit, den Rang Adept innezuhalten und ein richtiger Blutritter im Dienste Silbermonds zu werden.|n|nUm Eure Leistungen zu ehren, hat der Kriegshäuptling bei seinem Schmied die Herstellung einer Waffe für Euch in Auftrag gegeben.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke dort.', },
    {'Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren, und 5 ewige Sehnen.', },
  },
  [27435] = {
    'Der Stab eines Sehers',
    {'In den Augen der Erdmutter seid Ihr bereit, den Rang des Sehers zu erlangen. Ihr habt Eure Grundausbildung mit Können und Hingabe absolviert.|n|nZu diesem Anlass hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines Stabs für Euch in Auftrag gegeben.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.', },
  },
  [27436] = {
    'Die Aufgabe des Schattenläufers',
    {'Dies ist ein besonderer Anlass, $N. Ihr habt viel gelernt und seid an der Macht gewachsen. Im Stamm der Dunkelspeere und in der Horde steht Euch eine großartige Zukunft bevor.|n|nIch habe den Verzauberkunstmeister des Kriegshäuptlings gebeten, einen Stab zu erstellen, um Eure Leistungen anzuerkennen.|n|nUm die dafür benötigten Materialien zu erlangen, müsst Ihr zur verfluchten Burg Schattenfang im Silberwald reisen. Findet das heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz, und die Essenzen der Geister, die die Burg heimsuchen, und bringt alles zu Godan.', },
    {'Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.', },
  },
  [27437] = {
    'Die Aufforderung des dunklen Klerikers',
    {'Ihr habt gewissenhaft gelernt und uns gedient. Wenn Ihr Eure Talente übereinstimmend mit den Wünschen von Fürstin Sylvanas benutzt, wird Euch der Schatten segnen.|n|nUnsere Königin hat beim Verzauberkunstmeister von Orgrimmar die Herstellung eines mächtigen Stabes zur Anerkennung Eurer Dienste in Auftrag gegeben.|n|nDie Materialien, die dafür benötigt werden, sind nur in Burg Schattenfang inmitten von Silberwald zu bekommen. Findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.', },
  },
  [27438] = {
    'Die große Flucht',
    {'Das Ziel unserer Mission ist erfüllt. Nun können wir unsere Flucht planen. Obwohl wir Gilneas verloren haben, werden wir es mit der Hilfe von Godfrey und seinen Leutnants schnell wieder zurückerobern können.|n|nGeht nun, $N. Fliegt mit Arthura zurück zur Frontlinie der Verlassenen im Süden von Silberwald. Die Bansheekönigin erwartet Eure Ankunft.', },
    {'Flieht aus den Ruinen von Gilneas mit Arthura und der Leiche von Lord Godfrey.', },
  },
  [27439] = {
    'Stab des Lichts',
    {'Ihr seid durch Euer Talent schnell zu einem guten Diener des Lichts und Silbermonds geworden, $N. Eure Loyalität gegenüber unserem Volk und der Horde sind beispielhaft.|n|nIn Anerkennung Eurer Hingabe hat der Kriegshäuptling bei seinem Verzauberkunstmeister die Herstellung eines Stabs für Euch in Auftrag gegeben.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.', },
  },
  [27440] = {
    'Trolls, Oger und Orcs, oh weh!',
    {'Dem großen Schwarzdrachen Oberanführer Wyrmthalak unterstehen die Streitmächte der unteren Schwarzfelsspitze, die schon bald bereit für ihren Angriff auf die Dunkeleisenzwerge sein werden. Wir können nicht zulassen, dass die schwarzen Großdrachen die Kontrolle über den Berg erlangen!|n|nIhr müsst Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak töten. Ihre Tode werden den Kampfgeist der Armee beeinträchtigen und uns so wertvolle Zeit verschaffen.', },
    {'Tötet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak.', },
  },
  [27441] = {
    'Der Stab eines Sehers',
    {'Man sagt, dass sogar der Kriegshäuptling von Euren Taten für die Horde erfahren hat. Bestimmt wird er jetzt erkennen, dass er uns falsch eingeschätzt hat.|n|nEr hat sich bereiterklärt, dem Verzauberkunstmeister von Orgrimmar zu gestatten, einen Stab für Euch zu fertigen.|n|nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.', },
    {'Reist nach Burg Schattenfang und besorgt Euch das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.', },
  },
  [27442] = {
    'Der Krieg hat viele Fronten',
    {'Jetzt sieht unsere Lage dem Feind in Vashj\'ir gegenüber viel besser aus als vor Eurer Ankunft. Versteht mich nicht falsch, wir brauchen immer noch Eure Hilfe, aber vielleicht sind unsere anderen Fronten in noch größerer Bedrängnis.|n|nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.|n|nScharfseher Krogar am Westlichen Erdschrein in Orgrimmar wird Euch weitere Anweisungen erteilen.', },
    {'Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.', },
  },
  [27443] = {
    'Der Krieg hat viele Fronten',
    {'Jetzt sieht unsere Lage dem Feind in Vashj\'ir gegenüber viel besser aus als vor Eurer Ankunft. Versteht mich nicht falsch, wir brauchen immer noch Eure Hilfe, aber vielleicht sind unsere anderen Fronten in noch größerer Bedrängnis.|n|nMan hat mir berichtet, dass unsere Verbündeten des Irdenen Rings in einer Angelegenheit um Hilfe gebeten haben, die keinen Aufschub duldet.|n|nErdsprecher Naraat am Östlichen Erdschrein in Sturmwind wird Euch weitere Anweisungen erteilen.', },
    {'Sprecht mit Erdsprecher Naraat am Östlichen Erdschrein in Sturmwind.', },
  },
  [27444] = {
    'Der falsche Kriegshäuptling',
    {'Rend Schwarzfaust war der Sohn eines Kriegshäuptlings der Orcs. Sein Vater wurde von Orgrim Schicksalshammer umgebracht, der daraufhin zum neuen Kriegshäuptling anstelle des jungen Rends wurde. Rend hat sich nun zum Anführer der Schwarzfelsorcs emporgeschwungen, einer Möchtegern"horde", und wird dabei von Nefarian und seiner Drachenarmee unterstützt.|n|nRend, der Narr, behauptet auch, dass er das Geburtsrecht auf die Horde innehält, und droht, dieses Recht mit Gewalt geltend zu machen. Wir können nicht zulassen, dass dies unter dem Einfluss seines Meisters geschieht. Findet ihn in der oberen Schwarzfelsspitze und bringt diesen falschen Kriegshäuptling zu Fall, <Volk>.', },
    {'Tötet Kriegshäuptling Rend Schwarzfaust.', },
  },
  [27445] = {
    'General Drakkisath, Nefarians rechte Hand',
    {'Nefarian weitet seinen Herrschaftsbereich weiter oben im Pechschwingenhort aus. Obwohl man dort von der oberen Schwarzfelsspitze aus hinkommt, könnten wir dort mit weitaus mehr Streitmächten einfallen, wenn wir die Kugel der Teleportation in der Nähe benutzen. Wir können uns erst teleportieren, wenn wir durch eine andere Kugel gekennzeichnet sind.|n|nDie zweite Kugel wird von Drakkisath, dem General von Nefarians Armee, persönlich bewacht. Schaltet ihn aus und sichert die zweite Kugel, damit wir sie nutzen können. Ihr werdet ihn im Spitzenthron in der oberen Schwarzfelsspitze finden.', },
    {'Tötet General Drakkisath.', },
  },
  [27446] = {
    'Tanaris ruft',
    {'Hey, $N! Kelsey Stahlfunken aus Tanaris hat eine Nachricht für Euch gebracht. Sie meint, die Gnome dort in Gadgetzan hätten von Euren Leistungen gehört.|n|nDer Kataklysmus hat sie auch dort unten nicht verschont. Uns hat er zwar härter getroffen, aber sicherlich können sie Eure Hilfe gebrauchen.', },
    {'Sprecht mit Kelsey Stahlfunken in Gadgetzan in Tanaris.', },
  },
  [27447] = {
    'Tanaris ruft',
    {'Hey, $N! Megs Schredderschreck aus Tanaris hat eine Nachricht für Euch hinterlassen. Sie sagt, die Goblins dort in Gadgetzan haben von Euren Leistungen gehört.|n|nDer Kataklysmus hat sie auch dort unten nicht verschont. Uns hat er zwar härter getroffen, aber sicherlich können sie Eure Hilfe gebrauchen.|n|nAußerdem sieht diese Megs verdammt gut aus!', },
    {'Sprecht mit Megs Schredderschreck in Gadgetzan in Tanaris.', },
  },
  [27448] = {
    'Die Reise geht weiter',
    {'Ich glaube, die Pferde sind startklar. Argus Leuchtfeuer, der Herr, der mit dem Argentumkreuzzug zusammenarbeitet, hat sich vorhin mit mir unterhalten. Wie ich höre, wird er uns wohl begleiten - großartig! Ich werde Platz für ihn machen.|n|nIch weiß, dass Ihr beschäftigt seid, also nur keine Hektik. Sobald Ihr soweit seid, springt einfach auf den Karawanenwagen auf und wir machen uns auf den Weg zum nächsten Turm.', },
    {'Steigt auf Fionas Karawanenwagen, wenn Ihr bereit seid, um zum nächsten Turm aufzubrechen.', },
  },
  [27449] = {
    'Ehre und Stärke',
    {'Mein Name lautet Vex\'tul und ich habe Euch im Kampf beobachtet, <Volk>. Ihr seid stark.|n|nIhr habt meinen Meister Zaeldarr getötet, aber das stört mich nicht. Stärke ist mir wichtiger als die Loyalität, die ich ihm gegenüber empfand. Stärke ist mir wichtiger als alles andere.|n|nBeweist mir Eure Stärke ein letztes Mal, <Volk>. Wenn Ihr sie beweisen könnt, werde ich Euch MEINE Stärke leihen und Ihr werdet sie für all die Zwecke einsetzen können, die Euch vorschweben.', },
    {'Besteht Vex\'tuls Stärketest.', },
  },
  [27450] = {
    'Fredericks Vorliebe für Fisch',
    {'Ich liebe das Meer. Ich, Frederick Calston, war es, der die Meeresbewohner in den See im Südwesten gebracht hat. Ich hatte gehofft, den Kreuzzug so mit frischer Nahrung direkt aus den Pestländern versorgen zu können.|n|nAllerdings haben sich einige als Raubfische herausgestellt und jetzt versetzen sie alle anderen Tiere in Angst und Schrecken. Wenn wir nicht aufpassen, werden sie alle töten!|n|nSchwimmt zum Boden des Sees und rettet ein paar der Schnecken, Krabben und Kugelfische, bevor es zu spät ist.', },
    {'Erhaltet 8 Pestkugelfische, 8 Infektkriecher und 8 Infektkrabbler aus der Infektnarbe.', },
  },
  [27451] = {
    'Töten zu einem bestimmten Zweck',
    {'Seid gegrüßt, Fremdling! Ihr seid im Herzen der Pestländer angelangt. Ich hoffe, Ihr habt Eure Untote-Töten-Ausrüstung dabei.|n|nDieser Tage verbreitet sich die Seuche immer langsamer und daher hat der Kult der Verdammten die Herstellung hochgeschraubt, damit das Land braun und tot bleibt, so, wie es ihnen am liebsten ist. Ich habe einen Plan, sie aufzuhalten. Nehmt meinen Mörser und den Stößel; zerstoßt damit die lebendige Fäulnis der untoten Kreaturen in Corins Kreuzung südöstlich von hier. Wir werden für diese Kultisten ein kleines Geschenk vorbereiten.', },
    {'Reist zu Corins Kreuzung im Süden und tötet die Geißelsoldaten, die dort hausen. Sammelt 7 Stück lebendige Fäulnis. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis.', },
  },
  [27452] = {
    'Dunkle Gewänder',
    {'Einige meiner Mitstreiter haben berichtet, dass das Land heilen möchte. Allerdings lassen das viele hochrangige Untote - und auch der Kult der Verdammten - nicht zu. Das bedeutet, dass wir sie aufhalten müssen! Ich habe einen Plan, aber zuerst brauche ich eine Kultistenverkleidung.|n|nBegebt Euch nach Südosten, zu Corins Kreuzung und nehmt einem der menschlichen Kultisten die Gewänder ab. Ihr werdet sie durch den Ort streifen sehen. Ich werde mich mit Euch in Verbindung setzen, wenn Ihr das Gewand erhalten habt.', },
    {'Erhaltet die Kopfbedeckung eines Todeskultisten und die Roben eines Todeskultisten von Kultisten in Corins Kreuzung.', },
  },
  [27453] = {
    nil,
    {'Geronnene Fäulnis ist allein schon sehr wirksam, aber wir brauchen etwas, um die versteckten Kräfte hervorzurufen... einen Katalysator. Ein guter Katalysator findet sich südlich von hier, im Mereldarsee.|n|nWenn Ihr in Eure Taschen seht, werdet Ihr bemerken, dass ich ein paar Fläschchen hineingeschmuggelt habe, als Ihr nicht aufgepasst habt. Benutzt diese Fläschchen bei den Wasserelementaren im See. Das lebende, verderbte Wasser, aus dem ihre Körper bestehen, wird einen perfekten Katalysator abgeben!', },
    {'Verwendet Betinas Fläschchen gegen lebende Elementare im Mereldarsee, um 8 flüssige Seuchenwirkstoffe zu erhalten.', },
  },
  [27454] = {
    'Nur ein Tropfen im Eimer',
    {'Gebt nun eine kleine Menge Fäulnis zum Wasser und gut verrühren. So, das war es schon. Diese Lösung wird sehr aggressiv sein und wir brauchen nur ganz wenig davon.|n|nAm südöstlichen Ufer des Sees befindet sich ein Seuchenkessel, in dessen Nähe sich mehrere Kultisten aufhalten. Tragt die Kultistenverkleidung, geht zum Kessel und fügt nur EINEN TROPFEN dieser Lösung hinzu. Wenn Ihr mehr in den Kessel schüttet, ist Euer Leben in großer Gefahr!', },
    {'Benutzt Eure Todeskultistenverkleidung, um das Basislager der Todeskultisten zu betreten und fügt Betinas Mischung dem Mereldar Seuchenkessel zu.', },
  },
  [27455] = {
    'Jungs bleiben Jungs',
    {'Direkt nach unserer Ankunft hier am Lichtschildturm sind die beiden Paladinschwachköpfe zur Kapelle des Hoffnungsvollen Lichts davongerannt. Sie ist noch recht weit entfernt, aber wenn wir Argus auf seiner Turmrundreise folgen wollen, dann ist das hier wohl noch am nächsten.|n|nSchaut einmal nach ihnen und stellt sicher, dass es ihnen gut geht. Ich weiß, dass sie auf sich selbst aufpassen können, aber dennoch... Mir wäre wohler, wenn ich wüsste, dass Ihr über sie wacht, während ich hier mit dem Wagen festsitze.', },
    {'Findet Gidwin Goldzopf vor der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.', },
  },
  [27456] = {
    'Nicht auf leeren Maden',
    {'Wir haben Schwierigkeiten, unsere Nahrungsvorräte hier im tiefen Osten aufrechtzuerhalten.|n|nIn dieser Gegend gibt es nur eine Tierart, die nicht von der Seuche beeinträchtigt wird und das sind Aaswürmer. Sie schmecken zwar nach nichts, aber das Fleisch dieser Würmer kann über Monate hinweg aufbewahrt werden. Wir benötigen einige hundert Pfund, damit wir wieder ausreichend versorgt sind.|n|nMan findet Aaswürmer überall in den Pestländern, aber besonders häufig kommen sie südlich der Kapelle vor. Und denkt daran: Große Würmer liefern mehr Fleisch.', },
    {'Sucht in der Umgebung nach Aaslarven und Aasverschlingern. Tötet sie und bringt 15 Scheiben Aaswurmfleisch an Euch.', },
  },
  [27457] = {
    'Eine Gelegenheitsallianz',
    {'Durch Euren Beitrag zu den Nahrungslagern ist meine Aufgabe erledigt.|n|nIch werde mich als Nächstes nach Norden in den Pestwald begeben. Wie ich höre, geht Ihr in die gleiche Richtung?|n|nWürde es Euch etwas ausmachen, wenn ich mich Euch anschließe? |n|nIch bin unterwegs nach Nordwesten zum Ostwallturm. Wenn Ihr Interesse an einem Zusammenschluss habt, könnt Ihr mich dort treffen.', },
    {'Meldet Euch bei Fiona am Ostwallturm in den Östlichen Pestländern.', },
  },
  [27458] = {
    'Smokey und der Verband',
    {'He, Ihr da! Interesse, leichtes Geld zu verdienen?|n|nIch muss an eine Bandage kommen. Also, um ehrlich zu sein, hab ich einen Freund, der an eine Bandage kommen muss. Also, um ehrlich zu sein... sagen wir einfach, es ist zu kompliziert, aber wenn Ihr diese Bandage holt, bekommt Ihr Geld. Genau wie ich. Und mein Freund. Möglicherweise auch andere Leute.|n|nDie Mühle im Norden gehörte früher einmal Stephan Braumann, aber jetzt ist er tot. Ein Zombie. Der Kerl ganz oben möchte die Wickel von Braumanns Körper.|n|nWas ist los - mögt Ihr kein Geld?', },
    {'Besorgt Braumanns Wickel von Stephan Braumann in Braumanns Mühle.', },
  },
  [27459] = {
    'Die Bruderschaft des Lichts',
    {'Die Bruderschaft des Lichts ist für ihre unbesonnenen und gedankenlosen Entscheidungen bekannt. Sie haben eine Brücke zwischen dem Scharlachroten Kreuzzug und der Argentumdämmerung geschlagen. Sie waren unter den ersten, die sich in Nordend in den Kampf warfen, während wir anderen noch zögerten.|n|nDeshalb sind sie auch für ihre Ergebnisse bekannt und das respektiere ich. Jetzt kämpfen sie an zwei Fronten: Eine Schlacht in Stratholme und die andere - viel drängendere - Schlacht im Süden bei Tyrs Hand.|n|nIch schlage vor, Ihr sprecht mit Angela Dosantos in Tyrs Hand. Vielleicht hat sie Verwendung für Euch.', },
    {'Meldet Euch bei Erzmagierin Angela Dosantos in Tyrs Hand in den Östlichen Pestländern.', },
  },
  [27460] = {
    'Sanfte Landung',
    {'Man hat uns nur einhundert Männer überlassen, um diese Mission zu erfüllen, und einer fehlt uns bereits. Unser Späher wurde in die Feste des Feindes entsandt, um einige Wachen auszuschalten, die in der Gegend patrouillieren. Außerdem sollte er ein Leuchtfeuer entfachen, damit wir einen koordinierten Angriff durchführen können. Unsere neunundneunzig verbliebenen Männer sind bereit und warten auf das Leuchtfeuer. $GEin talentierter:Eine talentierte:c; $C wie Ihr muss sich nach Tyrs Hand schleichen, so viele Wachen wie möglich ausschalten und das Leuchtfeuer entfachen.|n|nFühlt Ihr Euch dem gewachsen?', },
    {'Tötet 10 beliebige Anhänger des Scharlachroten Kreuzzugs in Tyrs Hand.', },
  },
  [27461] = {
    'Die Abtei einnehmen',
    {'Der Scharlachrote Kreuzzug unterhält eine gut befestigte Abtei im unteren westlichen Teil von Tyrs Hand. Zunächst muss die Abtei gesichert werden, bevor man sich weiter in die Festung vorwagen kann.', },
    {'Meldet Euch bei Kommandant Eligor Morgenbringer außerhalb der Abtei in Tyrs Hand in den Östlichen Pestländern.', },
  },
  [27462] = {
    'Die Kaserne einnehmen',
    {'Eines der Schlüsselgebäude in Tyrs Hand ist die Kaserne, die sich ganz in der Nähe dieses Leuchtfeuers befindet. Die Bruderschaft des Lichts und ihre Zenturionen werden alle verfügbare Hilfe benötigen, um sie zu erobern.', },
    {'Meldet Euch bei Kreuzzugskommandant Korfax vor der Kaserne in Tyrs Hand in den Östlichen Pestländern.', },
  },
  [27463] = {
    'Ein Kindheitstraum',
    {'Ich wollte mich schon immer dem Kreuzzug anschließen. Deshalb bin ich Paladin geworden. Jahrelange Übung und Verbesserung meiner Fertigkeiten. Endlich bin ich bereit.|n|nTarenar glaubt ebenfalls, dass er bereit ist, aber da bin ich mir nicht so sicher. Er ist ein Angeber und hat seine Lektionen nie ernstgenommen. Dennoch - wir haben versprochen, dass wir das hier zusammen machen und hier stehen wir nun.|n|nSollen wir uns in die Kapelle begeben?', },
    {'Sprecht mit Lord Maxwell Tyrosus in der Kapelle des Hoffnungsvollen Lichts.', },
  },
  [27464] = {
    'Argentumruf: Die Prüfung der Gruft',
    {'Hinter unserer Kapelle findet Ihr eine kleine Gruft. Darin sind die Leichen unserer gefallenen Helden bestattet, die ihr Leben im Krieg gegen die Geißel verloren haben.|n|nIhre Seelen ruhen friedlich. Dennoch kehren sie hin und wieder zurück, um neue Mitglieder des Ordens zu prüfen.|n|nIhr drei dürft die Prüfung zusammen absolvieren. Betretet die Gruft und lest dann diese Schriftrolle. Lord Raymond George - mein Vorgänger - wird den Vorsitz bei Eurer Prüfung übernehmen.', },
    {'Betretet die Gruft hinter der Kapelle des Hoffnungsvollen Lichts, lest aus der Argentumschriftrolle und schließt die Prüfung ab.', },
  },
  [27465] = {
    'Argentumruf: Das Giftige Tal',
    {'Braumanns Mühle im Norden wimmelt nur so von Untoten. Das Giftige Tal, noch weiter nördlich, ist noch schlimmer befallen. Trotz der Nähe zu unserer Kapelle sind wir nicht in der Lage gewesen, sie zu entfernen.|n|nWachsamkeit ist der Schlüssel. Reist in das Giftige Tal und tötet so viele Untote, wie Ihr finden könnt, sowie die Kultisten, die sich darunter befinden.|n|nWährend Ihr dort seid, weicht Garginox dem Fleischriesen aus, der durch das Tal wandelt. Ich vermute, dass Ihr nicht stark genug seid, um ihn zu besiegen.', },
    {'Tötet 16 Angehörige der Geißel und 8 Kultisten in Braumanns Mühle und dem Giftigen Tal. Kehrt zur Kapelle des Hoffnungsvollen Lichts zurück, wenn Tarenar oder Gidwin getötet werden.', },
  },
  [27466] = {
    'Argentumruf: Nordtal',
    {'Tyrosus hat uns unsere nächste Aufgabe gestellt: weitere Untote in Nordtal vernichten. Gidwin freut sich darauf, weiterzuziehen, aber ich glaube, wir sollten etwas vorsichtiger sein.|n|nLasst uns Fiona aufsuchen. Sie sollte jetzt den nächsten Turm erreicht haben... Ich glaube, er heißt Ostwallturm. Er ist in der Nähe, nordwestlich der Kapelle. Dort können wir uns ausruhen und unseren Angriff auf Nordtal planen.', },
    {'Sprecht mit Fiona am Ostwallturm in den Östlichen Pestländern.', },
  },
  [27467] = {
    'Vergrabene Klingen',
    {'Das Giftige Tal ist ein Morast, im wörtlichen und übertragenen Sinne. Es gibt dort oben genug Angehörige der Geißel, um uns beiden bis an unser Lebensende Schwierigkeiten zu bereiten.|n|nSie können die schwächeren wieder auferstehen lassen, wenn sie sterben, $N. Sie werden nie aufhören, nachzurücken, wenn wir nicht etwas unternehmen.|n|nNehmt diese Klingen und durchstoßt damit die Leichen aller Reitersoldaten der Geißel, derer Ihr habhaft werden könnt. Die Klinge ist einfach, aber ihre Verzauberung wird verhindern, dass die toten Knochen wiederbelebt werden können. Für immer.', },
    {'Stoßt die lichtberührten Klingen in die Leichen von 10 getöteten Reitersoldaten der Geißel.', },
  },
  [27468] = {
    'Rettung des Belagerungspanzers',
    {'Wir müssen unsere Belagerungspanzer einen nach dem anderen aus dem Schlamm ziehen. Nehmt die Ersatzteile, die Ihr gesammelt habt und gebt sie einem der Belagerungspanzerkommandanten, die auf den kaputten Fahrzeugen stehen.|n|nUnd dann verteidigt den Panzer, während die Ingenieure versuchen, ihn unzukaputten.|n|nGeht un\' macht mich stolz, $C!', },
    {'Sprecht mit einem Belagerungspanzerkommandanten auf einem kaputten Belagerungspanzer von Hochstade. Verteidigt den Panzer, während die Ingenieure Reparaturen vornehmen.', },
  },
  [27469] = {
    'Freunde auf der anderen Seite',
    nil,
    {'Findet Acride.', },
  },
  [27470] = {
    'Ein möglicher Verbündeter',
    {'Es ist kein Geheimnis, dass wir die Orcs im Schwarzfels nicht mögen. Wir beobachten sie daher ganz genau. Hier in den Bergen passiert nichts, von dem ich nichts weiß, $C.|n|nVor Kurzem kam ein ganz andersartiger Orc nach Schwarzfels. Er hat sich in der Schwarzfelsspitze niedergelassen, und ich weiß, dass er irgendwie vorhat, Nefarian und seine ganze Orcarmee zu stürzen. Normalerweise würde ich keinem dieser Orcs trauen, aber zur Zeit verfolgen wir ein gemeinsames Ziel. Findet ihn. Er heißt Acride.', },
    {'Findet Acride.', },
  },
  [27471] = {
    'Schwarzfelsanomalie',
    {'In der Schwarzfelsspitze gibt es einen Orc, der ganz anders ist als alle anderen Orcs. Seine Sprache zeugt von Intelligenz und Wissen, die seinem Aussehen Hohn spricht. Im Gegensatz zu den anderen Orcs bekämpft er auch unsere Soldaten nicht.|n|nIhr müsst zur Schwarzfelsspitze reisen, nordwestlich von hier, und diesen Orc finden, der uns nur als Acride bekannt ist. Vielleicht ist er der Schlüssel, um die Armee der Orcs aufzuhalten. Vielleicht können wir Nefarian aufhalten, bevor es zu spät ist...', },
    {'Findet Acride.', },
  },
  [27472] = {
    'Erwacht, Godfrey',
    {'Eure Loyalität den Verlassenen gegenüber ist standhaft, $N. Was Ihr bisher für uns getan habt - Eure Dienste für die Horde - werden nicht unbemerkt bleiben. Nun, da Lord Godfrey und seine Männer sich bald wieder erholt haben werden, werden wir einen großen Vorteil gegenüber der Gilnearischen Befreiungsfront und dem Rest der Hunde der Allianz haben.|n|nIch möchte Euch zum Anlass von Lord Godfreys Wiedergeburt als Einem von uns an meiner Seite haben. Wir werden ihn und seine Männer gemeinsam in unseren Kreis aufnehmen.', },
    {'Bleibt bei Fürstin Sylvanas Windläufer, während sie Lord Godfrey und seine Männer aufnimmt.', },
  },
  [27473] = {
    'Was wackelt in Eisenschmiede?',
    {'Die Dinge haben sich in Eisenschmiede zum Schlechteren gewendet, $N. Bitte sprecht mit Sturmruferin Mylra in Eisenschmiede und findet heraus, ob Ihr auf irgendeine Weise helfen könnt.', },
    {'Sprecht mit Sturmruferin Mylra in Eisenschmiede.', },
  },
  [27474] = {
    'Die Barriere durchbrechen',
    {'Während Godfrey und ich unseren Angriff auf Gilneas vorbereiten, möchte ich, dass Ihr den Angriff auf Mühlenbern, direkt östlich von hier, leitet.|n|nDie früheren Magier von Dalaran in Mühlenbern haben eine magische Barriere errichtet, die sie unsichtbar macht. Sie befinden sich in einer Art Dimensionstasche und erwarten Befehle der Allianz, um ihren Angriff zu beginnen. Wir müssen diesen Angriff durch einen Präventivschlag verhindern. Begebt Euch nach Mühlenbern und sucht nach Informationen, die uns Zugang zu diesen Magiern verschaffen.', },
    {'Findet den Kodex von Mühlenbern.', },
  },
  [27475] = {
    'Unnachgiebige Diener',
    nil,
    {'Bergt 6 Dienerkerne.', },
  },
  [27476] = {
    'Dalar Morgenweber',
    {'Nehmt den Kodex und reist nach Norden zum Grabmal. Wenn Ihr dort eintrefft, sucht nach Dalar Morgenweber. Dalar ist ein früherer Erzmagier der Kirin Tor. Er wird sicherlich in der Lage sein, die Schutzzauber, die diesen Kodex umgeben, zu entfernen und ihm seine Geheimnisse zu entlocken.|n|nBeeilt Euch, $N.', },
    {'Liefert den Kodex von Mühlenbern bei Dalar Morgenweber am Grabmal im Silberwald ab.', },
  },
  [27477] = {
    'Der Korpulente',
    {'Nördlich von hier und westlich von Nordtal findet Ihr das fettleibige Madenungeheuer Blutschlinger.|n|nIch habe ganze Regimenter gegen dieses Monster eingebüßt. Seine Ausmaße sind gewaltig! Je mehr er frisst, desto größer wird sein Umfang...|n|nEs würde mir keine schlaflosen Nächte bereiten, sollte die Bestie Euch verschlingen, dennoch sähe ich es lieber, wenn Ihr als Sieger hervorgeht. Man weiß, dass Blutschlinger schon andere verschlungen hat, die versucht haben, ihn zu jagen.', },
    {'Findet Blutschlinger im nördlichen Ödland der Östlichen Pestländer und vernichtet ihn.', },
  },
  [27478] = {
    'Relios, Bewahrer der Relikte',
    {'Die Dunkle Fürstin hat Recht, dass ich in der Lage bin, den Kodex zu entschlüsseln. Leider benötige ich dafür einen Siegelring von einem Erzmagier aus Dalaran. Mein eigener Ring wurde mir weggenommen, als ich vor vielen Jahren starb, aber es gibt vielleicht eine Möglichkeit.|n|nObwohl Dalaran fortgeschwebt ist, sind doch die Außenbezirke der Stadt erhalten geblieben. Weit im Osten liegen die Ruinen von Dalaran. Dort werdet Ihr einen Erzmagier mit Namen Relios finden. Nehmt seinen Siegelring an Euch und bringt ihn zu mir zurück.|n|nIhr dürft das Portal hinter mir benutzen, um zu dem Krater zu gelangen.', },
    {'Findet einen Siegelring eines Erzmagiers aus Dalaran.', },
  },
  [27479] = {
    'Rechtschaffene Empörung',
    {'Die Moosschinder von Zul\'Mashar spucken dem Licht ins Gesicht! Ihr Kannibalismus, ihr Atheismus, ihr Atavismus stellen die Mächte des Bösen über die des Guten. Ich verschreibe, Ihr rückt ihnen zu Leibe, damit ihr Getreibe ein Ende finde und jeder noch so Blinde empfinde, welche Strafe auf Torheit stünde!|n|nIhr werdet nach Norden reisen und mit all Eurer rechtschaffenen Empörung über sie kommen, $N. Der Zorn, den sie im Angesicht des Lichts entflammt haben, wird Euch zueigen werden.', },
    {'Erbeutet 30 Moosschinderaugen von Moosschindertrollen in Zul\'Mashar.', },
  },
  [27480] = {
    'Ley-Energien',
    {'Das arkane Überbleibsel pulsiert mit seltsamer Energie. Vielleicht solltet Ihr nach weiteren Überbleibseln suchen. Dalar wäre an solchen Funden sicherlich interessiert.', },
    {'Findet 8 arkane Überbleibsel.', },
  },
  [27481] = {
    'Aus dem Ziggurat',
    {'Die Zeit ist gekommen, Euch um einen Gefallen zu bitten, $N.|n|nWeit nördlich des Ostwallturms, verborgen in den Hügeln, liegt die Moosschinderhauptstadt Zul\'Mashar. Hier wurde ich geboren und hier bin ich gestorben.|n|nDer Verräter Thresh\'jin sitzt auf Zul\'Mashars Ziggurat. Eigentlich hätte mir der Sitz zugestanden, aber er erschlich ihn sich von mir durch Verrat und Lügen. Er ist nicht stark. Er ist schwach.|n|nIch werde in Zul\'Mashar zu Euch stoßen. Dann werden wir ihn töten. Eure Stärke und die meine. Vereint.', },
    {'Erbeutet den Leichnam von Kriegsherr Thresh\'jin.', },
  },
  [27482] = {
    'Hinein in die Flammen',
    {'Dies ist unsere letzte Begegnung, $N. Ich verlasse die Karawane.|n|nBehaltet Thresh\'jins Leiche, wenn Ihr weiter an meiner Seite kämpfen wollt. Ich kann noch ein wenig länger ausharren. Werft den Körper in das Feuer oben auf Zul\'Mashars Ziggurat, wenn Ihr bereit zum Abschied seid.|n|nIch danke Euch für Eure Freundschaft, $N. Ihr wart stark.', },
    {'Werft den Leichnam des Kriegsherrn Thresh\'jin in das Feuer oben auf Zul\'Mashars Ziggurat, wenn Ihr bereit seid, Euch von Vex\'tul zu trennen.', },
  },
  [27483] = {
    'Praktische Rache',
    {'Eigentlich bin ich kein rachsüchtiger Mann. Um genau zu sein bin ich eher Pragmatiker. Wisst Ihr, Sachlichkeit ist im Grunde das Gegenteil zu Rache. Die meisten Rachepläne sind höchst unpraktisch.|n|nABER... in diesem Fall... Da Ihr Euch ohnehin schon zu den Ruinen von Dalaran begebt, könnt Ihr auch jeden Menschen, der mit Dalaran in Verbindung gebracht werden kann, töten. Die Gründe dafür, dass ich sie tot sehen will, reichen von Hass über Zorn bis zu Verrat, aber ich versichere Euch, der Groll ist durchweg berechtigt. Erledigt das für mich und ich werde Euch reich belohnen.', },
    {'Tötet 12 beliebige Menschen aus Dalaran.', },
  },
  [27484] = {
    'Es darf nur einer eintreten',
    {'<Dalar blättert durch den Kodex.>|n|nHAHAH!|n|nOh... Das ist schlimm.|n|n<Dalar klappt den Kodex zu und schaut zu Euch hoch.>|n|nNur EINER darf mit Hilfe dieses Rings die Dimensionstasche in Mühlenbern betreten. Diese Person muss sich dann einen Weg durch eine Armee von Magiern freikämpfen und den Erzmagier töten, der die Verschiebung von der anderen Seite her erschafft. Erst dann wird die Dimension in sich zusammenbrechen und alle Magier auswerfen.|n|nDas Portal, durch das man hineingelangen kann, liegt versteckt hinten in einer Höhle in Berens List.|n|nMehr weiß ich nicht. Bringt den Ring zu Sylvanas zurück.', },
    {'Bringt den Siegelring eines Erzmagiers aus Dalaran zu Fürstin Sylvanas Windläufer an der Frontlinie der Verlassenen im Silberwald zurück.', },
  },
  [27485] = {
    'Ein herzliches Willkommen',
    {'Ich bin froh, dass Ihr zurück seid! Um die Welt zu retten oder dergleichen, da bin ich sicher.|n|nIch wurde ausgeschickt, um Beziehungen mit den roten Drachen in der Gegend aufzubauen, aber ich finde sie weniger zugänglich als diejenigen in Wyrmruh. Allerdings sagte man mir, dass Ihr jemand seid, der Probleme löst.|n|nEin Problemlöser sozusagen.|n|nHättet Ihr vielleicht Lust, ein wenig Vertrauen mit Lirastrasza im Zinnoberrefugium im Südwesten aufzubauen? Alles, das sie mir gegenüber ein wenig milder stimmt, wäre wunderbar.', },
    {'Trefft Euch mit Lirastrasza im Zinnoberrefugium.', },
  },
  [27486] = {
    'Ein herzliches Willkommen',
    {'Gut. Ihr seid zurück. Rettet wohl wieder die Welt, was?|n|nIch wurde ausgeschickt, um Beziehungen zu den roten Drachen in der Gegend aufzunehmen, aber die hiesige Variante ist bei Weitem nicht so entgegenkommend, wie die Drachen im Wyrmruhtempel. Mir ist allerdings zu Ohren gekommen, dass Ihr jemand seid, der Probleme löst.|n|nEin Problemlöser sozusagen.|n|nIhr müsst das Vertrauen von Lirastrasza im Zinnoberrefugium südwestlich von hier gewinnen. Unsere Zusammenarbeit mit dem Drachenmalklan hat die Angelegenheit zugespitzt, aber ich bin zuversichtlich, dass Ihr die Wogen glätten könnt.', },
    {'Trefft Euch mit Lirastrasza im Zinnoberrefugium.', },
  },
  [27487] = {
    'Ix\'lar der Unterfürst',
    {'Ich weiß, dass wir eigentlich nach Nordtal aufbrechen sollten, aber das hat doch noch Zeit, oder? Dieser niedliche kleine Goblin hat mir übrigens erzählt, dass die Geißel in der Nähe weilt.|n|nAnscheinend gibt es einen nerubischen Unterfürsten namens Ix\'lar, der seit der Vernichtung des Lichkönigs versucht, sich einen Namen zu machen. Er und seine Untoten haben nördlich von uns ein Lager errichtet.|n|nNatürlich will Tyrosus, dass wir Banshees in Nordtal töten. Das werden wir auch. Aber lasst uns zuerst diesen Neruber töten, solange wir in der Nähe sind!', },
    {'Tötet Ix\'lar den Unterfürsten und 10 seiner Diener.', },
  },
  [27488] = {
    nil,
    {'Dieser verdammte Zwerg. Immer kriege ich wegen ihm Ärger mit Fiona. Seht sie Euch doch an! Sie REDET nicht einmal mehr mit mir!|n|nIch werde hier bleiben und versuchen, meine Freundschaft mit unserer Worgenfreundin zu kitten. Würde es Euch etwas ausmachen, allein nach Gidwin zu suchen? Es geht ihm bestimmt gut. Er kann auf sich allein aufpassen. Er war auf dem Weg nach Norden. Weit kann er nicht gekommen sein.', },
    {'Sucht nach Gidwin Goldzopf in Nordtal.', },
  },
  [27489] = {
    'Ich allein bin schuld',
    {'Das ist meine Schuld. Ich... Ich habe seine Warnungen und Beschwerden ignoriert. Ich konnte nicht anders - Ich sah die Geißel so nahe hinter dem Turm, da... Ich MUSSTE sie töten.|n|nArgus sagt, Gidwin sei nach Nordwesten gebracht worden. Das ist unsere einzige Spur, also werden wir in diese Richtung aufbrechen.|n|nIch pfeife auf Nordtal und den Argentumkreuzzug! Wir werden Gidwin von diesen Geißelmistkerlen zurückholen.', },
    {'Steigt in Fionas Karawanenwagen und fahrt zum Nordpassturm.', },
  },
  [27490] = {
    'Den SI:7 absetzen',
    {'Mathias Shaw und der SI:7 sind hier, um uns bei unserer Mission oben in der Schattenzitadelle zu unterstützen. Ihr müsst sie für mich dorthin geleiten.|n|nDie Wildhämmer sind so freundlich, uns dorthin zu fliegen. Die Agenten müssen jedoch zuerst etwas unten bei den Toren erledigen.|n|nSprecht mit Angus Stillberg und schnappt Euch eine Truppe, um sie sicher abzusetzen. Ihr werdet sie hereinfliegen. Die Stelle ist mit einem großen blauen X markiert.', },
    {'Holt bei Angus Stillberg eine Truppe der Wildhammervandalen ab und begleitet sie zum Landepunkt am Schattentor.', },
  },
  [27491] = {
    'Die Kor\'kron absetzen',
    {'Garona und ein Kommando der Kor\'kron sind hier, um uns bei unserer Mission oben in der Schattenzitadelle zu unterstützen. Ihr müsst sie für mich dorthin geleiten.|n|nDer ansässige Trollstamm ist so freundlich, uns auf ihren Windreiten dorthin zu fliegen. Die Assassinen müssen jedoch zuerst etwas unten bei den Toren erledigen.|n|nSprecht mit dem Anführer der Trolle, Jon-Jon Glibberhals, und schnappt Euch ein Kommando der Kor\'kron, um sie sicher abzusetzen. Ihr werdet sie hereinfliegen. Die Stelle ist mit einem großen roten X markiert.', },
    {'Holt bei Jon-Jon Glibberhals eine Truppe der Schmetterschlagwindreiter ab und begleitet sie zum Landepunkt am Schattentor.', },
  },
  [27492] = {
    'Oger und Ettins',
    nil,
    nil,
  },
  [27493] = {
    'Oger und Ettins',
    nil,
    nil,
  },
  [27494] = {
    'Berge versetzen',
    {'Wenn die Tore fallen sollen, müssen wir Schädelberster den Berg dort weglocken!|n|nBevor sie gegangen sind, habe ich dafür gesorgt, dass Eure Agenten des SI:7 ein paar Sprengsätze mitnahmen, die in einer Kiste des Schattenhammers versteckt waren. Sie sollten sie bereits auf den Stufen zum oberen Bereich der Zitadelle platziert haben.|n|nIch möchte, dass Ihr die Sprengsätze zündet und uns dann Bescheid gebt, wenn das Monster aus dem Weg geräumt ist.|n|nDann werden wir angreifen und den Ogern den Rest geben!', },
    {'Zündet die versteckten Sprengsätze, um Schädelberster den Berg vom Schattentor wegzulocken.', },
  },
  [27495] = {
    'Berge versetzen',
    {'Wenn die Tore fallen sollen, müssen wir Schädelberster den Berg dort weglocken!|n|nBevor sie gegangen sind, habe ich dafür gesorgt, dass Eure Assassinen der Kor\'kron ein paar Sprengsätze mitnahmen, die in einer Kiste des Schattenhammers versteckt waren. Sie sollten sie bereits auf den Stufen zum oberen Bereich der Zitadelle platziert haben.|n|nIch möchte, dass Ihr die Sprengsätze zündet und uns dann Bescheid gebt, wenn das Monster aus dem Weg geräumt ist.|n|nDann werden wir angreifen und den Ogern den Rest geben!', },
    {'Zündet die versteckten Sprengsätze, um Schädelberster den Berg vom Schattentor wegzulocken.', },
  },
  [27496] = {
    'Holt die Artillerie!',
    {'Ich bevorzuge einen ehrenhaften Kampf Mann gegen Mann. Diese Monster verdienen es, durch die Waffen in unseren Händen den Tod zu finden. In diesem speziellen Fall müssen wir jedoch auf mächtigere Methoden zurückgreifen.|n|nNehmt diese Leuchtpistole und markiert die vier Gebäude innerhalb des Schattentors im Südwesten. Unsere Kanonen werden den Rest erledigen.', },
    {'Benutzt die Artillerieleuchtpistole, um das nördliche, das nordöstliche, das südwestliche und das südliche Gebäude beim Schattentor als Ziel zu markieren.', },
  },
  [27497] = {
    'Holt die Artillerie!',
    {'Wie schade, dass wir unsere Feinde nicht mehr mit der Seuche strafen dürfen. Gerade in dieser Lage wäre das sehr effektiv. Nun ja, zumindest haben wir Kriegsmaschinen, um ihre ach so geliebten Tore einzureißen.|n|nNehmt diese Leuchtpistole und markiert die vier Gebäude innerhalb des Schattentors im Nordwesten. Unsere Kanonen werden den Rest erledigen.', },
    {'Benutzt die Artillerieleuchtpistole, um das nördliche, das nordöstliche, das südwestliche und das südliche Gebäude beim Schattentor als Ziel zu markieren.', },
  },
  [27498] = {
    'Befehlt den Angriff',
    {'Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr den Truppen am Gipfel des Siegers signalisieren, dass sie angreifen können!', },
    {'Benutzt das Angriffssignal auf einem der Türme beim Schattentor.', },
  },
  [27499] = {
    'Befehlt den Angriff',
    {'Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr den Truppen am Schmetterschlagposten signalisieren, dass sie angreifen können!', },
    {'Benutzt das Angriffssignal auf einem der Türme beim Schattentor.', },
  },
  [27500] = {
    'Vier Köpfe sind besser als keiner',
    {'Während der Angriff auf die Tore der Zitadelle in vollem Gange ist, gibt es noch eine Sache, um die Ihr Euch kümmern müsst: Za\'brox und Beeble\'phod, die Jünger Cho\'galls.|n|nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.|n|nIhr seid Euch ziemlich sicher, dass Cassius und Kurdran einen Beweis für ihren Tod sehen wollen.', },
    {'Sammelt die vier Köpfe von Za\'brox und Beeble\'phod.', },
  },
  [27501] = {
    'Vier Köpfe sind besser als keiner',
    {'Während der Angriff auf die Tore der Zitadelle in vollem Gange ist, gibt es noch eine Sache, um die Ihr Euch kümmern müsst: Za\'brox und Beeble\'phod, die Jünger Cho\'galls.|n|nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.|n|nIhr seid Euch ziemlich sicher, dass Lady Cozwyn und Zaela einen Beweis für ihren Tod sehen wollen.', },
    {'Sammelt die vier Köpfe von Za\'brox und Beeble\'phod.', },
  },
  [27502] = {
    'Hinauf zur Zitadelle',
    {'Jetzt, da der Angriff eingeleitet wurde, ist es Zeit, uns um die Schattenzitadelle zu kümmern. Wenn Ihr nichts dagegen habt, möchte ich Euch bitten, die Truppen des SI:7 zu Meister Mathias Shaw zu führen.|n|nEr hält sich irgendwo auf dem Gipfel versteckt. Der Truppenkommandant des SI:7 kann Euch den genauen Ort nennen.|n|nVielen Dank, $N. Wir freuen uns schon darauf, Euch beim Angriff auf die Zitadelle zur Seite zu stehen!', },
    {'Sprecht mit dem Truppenkommandanten des SI:7 und begleitet dann die Truppe des SI:7.', },
  },
  [27503] = {
    'Hinauf zur Zitadelle',
    {'Jetzt, da der Angriff eingeleitet wurde, ist es Zeit, uns um die Schattenzitadelle zu kümmern. Wenn Ihr nichts dagegen habt, möchte ich Euch bitten, die Truppen der Kor\'kron zu Garona zu führen.|n|nSie hält sich irgendwo auf dem Gipfel versteckt. Der Truppenkommandant der Kor\'kron kann Euch den genauen Ort nennen.|n|nVielen Dank, $N. Wir freuen uns schon darauf, Euch beim Angriff auf die Zitadelle zur Seite zu stehen!', },
    {'Sprecht mit dem Truppenkommandanten der Kor\'kron und begleitet dann die Truppe der Kor\'kron.', },
  },
  [27504] = {
    'Sogar Drachen bluten',
    {'Ich werde nicht so unhöflich sein, Eure Hilfe abzulehnen, wenn Ihr sie mir schon anbietet.|n|nWir befinden uns im stetigen Kampf mit den Zwielichtdrachen im Süden. Zwar sind unsere Angriffe nicht ganz fruchtlos, aber die Drachen, die aus Grim Batol hinausströmen, haben eine Art Verderbnis auf uns herab beschworen, die es nun zu läutern gilt.|n|nVelastrasza und Unheilsflamme kümmern sich um unsere verletzten Brüder. Geht und schaut, ob Ihr ihnen helfen könnt.', },
    {'Sprecht mit Velastrasza im Zinnoberrefugium.', },
  },
  [27505] = {
    'Heilung auf Drachenart',
    {'Wenn unsere Drachen aus der Schlacht zurückkehren, sind sie ganz in vom Zwielicht verderbte Flammen gehüllt und werden von den Zwielichtdrachen verfolgt.|n|nMeine Heiler können sich zwar um die Wunden unserer Drachen kümmern, aber sie müssen dabei geschützt werden. Haltet die Drachen von meinen Heilern fern. Wenn Ihr könnt, helft auch Ihr unseren Drachen mit Eurer Heilkraft.|n|nVielen Dank für Eure Unterstützung in dieser Angelegenheit. Unsere Schlachten um Grim Batol nehmen kein Ende. Wir müssen unsere mächtigsten Drachen so schnell wie möglich wieder in den Kampf schicken.', },
    {'Beschützt 5 zinnoberrote Heiler, während sie verwundete Drachen heilen.', },
  },
  [27506] = {
    'Leben aus dem Tod',
    nil,
    {'Pflanzt Rubinsamen in die Leichname von 6 Drachkin im Zinnoberrefugium.', },
  },
  [27507] = {
    'Die Ausbreitung des Zwielichts',
    {'Im Refugium wimmelt es von Zwielichteindringlingen. Sie strömen von einem unbekannten Ort im Westen auf die Lichtung.|n|nAn diesem heiligen Ort kann es für sie kein Mitleid geben. Welchen Funken der Gewalt Ihr auch in Eurem rechtschaffenen Herzen finden mögt, lasst sie darin in Flammen aufgehen.', },
    {'Tötet 12 Zwielichteindringlinge im Zinnoberrefugium.', },
  },
  [27508] = {
    'Weit weg vom Nest',
    {'Schaut… Ich weiß, dass Ihr keinen Grund habt, mich zu mögen, genauso wie auch ich Euch nicht besonders mag, aber ich brauche jede Hilfe, die ich bekommen kann.|n|nDiese Zwielichteindringlinge stehlen unsere Eier. Ohne Zweifel haben sie vor, sie zurück nach Grim Batol zu bringen, um damit zu experimentieren und sie zu pervertieren. Das werde ich einfach nicht zulassen.|n|nWenn Ihr uns wirklich helfen wollt, dann haltet sie auf! Holt die Eier zurück und bringt sie mir.', },
    {'Holt 6 Zinnobereier zurück.', },
  },
  [27509] = {
    'Verteidigungslücke',
    {'Jeder Millimeter der Luft um das Refugium herum wird permanent von Liras Drachen bewacht. Sie müssen sich von unten einen Weg in den Schrein gebahnt haben.|n|nNehmt diese Blitzwuchspartikel. Sie sollten sich gut dafür eignen, sämtliche Löcher, Tunnel oder Portale zu schließen, über die sie unsere Verteidigung durchbrochen haben könnten.|n|nFindet die Lücke in unserer Verteidigung, Schließt sie.', },
    {'Findet die Quelle des Schattenhammers im Zinnoberrefugium und vernichtet sie.', },
  },
  [27510] = {
    'Ein Wolf im Bärenpelz',
    {'Diese Worgen verkaufen uns für dumm! Man sollte meinen, dass nur ein Schwachkopf einen ihrer Druiden in Bärengestalt für einen echten Bären halten würde. Leider gibt es hier an der Frontlinie der Verlassenen viele Schwachköpfe. Wir haben bereits mehrere Bataillone bei organisierten Bärenangriffen der Worgen verloren. Ja, es ist in der Tat noch schwachsinniger, als es klingt.|n|nDirekt östlich von hier Richtung Hügelland findet Ihr Druiden der Worgen in den Wäldern. Sie sind als Bären getarnt. Tötet sie und sichert unsere südliche Versorgungslinie.', },
    {'Tötet 10 unauffällige Bären.', },
  },
  [27511] = {
    'Spannende Entdeckungen',
    {'Welch ein Fund! Und irgendwie ist alles von Plünderern verschont geblieben...|n|nHört zu, $N. Ich muss diesen Ort aufzeichnen, bevor wir etwas verändern. Warum seht Ihr Euch nicht ein wenig um, während ich das mache - Ihr wisst schon, ein wenig auf Entdeckungsreise gehen. Ihr habt es Euch verdient.|n|nHaltet Eure Augen offen und achtet auf Ungewöhnliches.|n|nOh! Und bitte... macht nichts kaputt, ja?', },
    {'Erforscht die Kammer der Sterne.', },
  },
  [27512] = {
    'Dimensionsübergreifender Krieg: Kapitel I',
    {'<Sylvanas gibt Euch den Siegelring.>|n|nNehmt den Ring und macht Euch auf nach Berens List im Südosten von hier in einer Höhle in den Hügeln. Sobald Ihr dort seid, durchsucht die Höhle nach dem Portal zu der Dimensionstasche, die die Magier von Mühlenbern verbirgt.|n|nIch werde mit Euch über Eure Gedanken kommunizieren, $N. Wenn Ihr das Portal erreicht habt, werde ich Euch Eure Befehle geben.', },
    {'Findet das Dimensionsportal von Mühlenbern.', },
  },
  [27513] = {
    'Dimensionsübergreifender Krieg: Kapitel II',
    {'<Die Worte der Bansheekönigin ertönen im Inneren Eures Kopfes.>|n|nIhr seid jetzt bereit, das Portal zu benutzen. Seid gewarnt, $N, sobald Ihr das Portal durchschreitet, erscheint Ihr in einer anderen Dimension von Mühlenbern. Dort werden Hunderte oder sogar Tausende Magier darauf warten, Euch zu töten.|n|nIhr müsst durchhalten und alle töten, die sich Euch in den Weg stellen.', },
    {'Tötet 20 Magier von Mühlenbern.', },
  },
  [27514] = {
    'Vogel am Boden! Vogel am Boden!',
    {'Während Ihr an der Küste gekämpft habt, habe ich gesehen, wie fast genau westlich von hier ein Greif aus den Wolken gestürzt ist.|n|nEs war keiner von unseren.|n|nWahrscheinlich gehörte er zu einem der Wildhämmer. Ich weiß, dass Kuran als eine der obersten Prioritäten nach der Einnahme des Strandes Kontakt zu den verschollenen Wildhammerklans aufnehmen wollte.|n|nIch kann keinen meiner Männer entbehren, um dort nachzusehen, aber Euch schon. Findet den abgestürzten Wildhammer!', },
    {'Findet den abgestürzten Greifenreiter der Wildhämmer Thordun Hammerschlag am Zwielichtufer im Schattenhochland.', },
  },
  [27515] = {
    'Die Wurzel alles Guten',
    {'Schaut doch, Kumpel. Sie liegt in den letzten Zügen! Wenn mein Vogel stirbt, bin ich so gut wie wertlos.|n|nAlso macht Euch nützlich. Hier auf der Halbinsel wächst dorniger Stinkwurz im Boden. Der Geruch zieht Euch die Socken aus, aber in Wasser eingeweicht wird daraus ein echtes Allheilmittel.|n|nSammelt ein paar Wurzeln, während ich meinen Vogel verteidige. Und beeilt Euch! Ihr Flachzangen von der Allianz habt ja nicht gerade den Ruf, rechtzeitig einzuschreiten, oder?', },
    {'Sammelt 8 Stück dorniger Stinkwurz am Zwielichtufer.', },
  },
  [27516] = {
    'Auf Schwingen nach Hochstade',
    {'He, schaut nur! Sie ist schon viel munterer.|n|nGut, $GHerr:Fräulein; Etepetete von der Allianz. Ist das Euer Lager da an der Küste? "Hochstade" sagt Ihr? Meint Ihr, mein Vogel und ich könnten dort eine Weile Unterschlupf finden, bis es ihr besser geht?|n|nSpringt auf! Wir fliegen gemeinsam nach Hochstade!', },
    {'Sprecht mit Thordun Hammerschlag und fliegt gemeinsam nach Hochstade!', },
  },
  [27517] = {
    'Seid vorbereitet',
    {'Jeder Abenteurer, der etwas auf sich hält, weiß, dass man niemals einen Fuß in eine Höhle, ein Verlies, eine Krypta oder eine Grabstätte setzt ohne ausreichend Seil dabeizuhaben... nicht wahr?|n|nDavon kann man nie genug haben!|n|nMan geht sogar so weit, jedes Stück, das man finden kann, von den Skeletten hier aufzusammeln.', },
    {'Sammelt 6 Stücke Seil.', },
  },
  [27518] = {
    'Dimensionsübergreifender Krieg: Kapitel III',
    {'<Sylvanas spricht direkt durch Euch.>|n|nIhr müsst das Wesen, das diese Dimensionstasche aufrechterhält, finden. Wahrscheinlich ist es dieser Narr, Ataeric... Sucht das Gelände nach ihm ab. Solltet Ihr ihn finden, müsst Ihr alles Notwendige tun, um ihn davon abzuhalten, seine Magie zu kanalisieren. Er wird zweifellos durch einen mächtigen, arkanen Schild geschützt und wird Handlanger aus arkaner Energie auf Euch loslassen. Besiegt die Handlanger in seiner Nähe, um ihre Energien freizusetzen. Kein Magier kann mit so viel Kraft umgehen!', },
    {'Überladet Erzmagier Ataeric mit arkaner Macht, um den transdimensionalen Schild auszuschalten.', },
  },
  [27519] = {
    'Unter dem erstickenden Sand',
    {'Nein... Das kann nicht sein.|n|nOrsis ist fast vollkommen unter dem Wüstensand begraben.|n|nDer Feind wird dafür bezahlen.|n|nDoch zunächst müssen wir meinem Volk helfen. Schnell, $N. Wir haben nicht viel Zeit, bevor auch der letzte meiner Brüder lebendig begraben wird!', },
    {'Rettet 8 Überlebende von Orsis.', },
  },
  [27520] = {
    'Al\'Akirs Diener',
    {'Al\'Akir hat seine Diener ausgesandt, um Todesschwinges Befehle zu befolgen.|n|nDie Botschaft ist deutlich. Wir schließen uns ihnen an oder sie vernichten uns.|n|nIch weiß nicht viel über Euch, <Volk>. Aber eins weiß ich. Wenn Ihr Euch als Feind Al\'Akirs erweist, wird Eure Hilfe nicht unbemerkt bleiben.|n|nWas sagt Ihr dazu, $C?', },
    {'Tötet 6 Abkömmlinge von Al\'Akir.', },
  },
  [27521] = {
    'Elender Hort des Abschaums und der Boshaftigkeit',
    nil,
    {'Tötet 9 Getriebene nahe der Jagdhütte von Quel\'Lithien in den Östlichen Pestländern.', },
  },
  [27522] = {
    'Prügelstrafe',
    {'Uns Paladinen bringt man bei, unseren Feinden gerecht und ruhig entgegenzutreten, aber dies ist ein Notfall. Außerdem habe ich noch nie auf meine Lehrer gehört.|n|nIch werde versuchen, im Pestwald mehr über Giddy herauszufinden. Kümmert Ihr Euch um die Geißel nordöstlich von hier, auf der anderen Seite dieses Turms. Die Untoten fürchten den Tod nicht, aber schlagt sie lang genug, dann verplappern sie sich vielleicht und geben uns Hinweise auf Gidwins Aufenthaltsort.', },
    {'Schlagt mindestens 6 Belagerungsingenieure der Geißel nieder, um an Informationen über Gidwins Verbleib und seinen Entführer zu gelangen.', },
  },
  [27523] = {
    'Dämmerschwinge, oh, wie ich Euch hasse...',
    nil,
    {'Beschafft einen Fellflicken von Dämmerschwinge.', },
  },
  [27524] = {
    'Blinde Wut',
    {'Tarenar hat nicht gescherzt, als er sagte, Vernunft und Vorsicht interessieren ihn nicht. Er hätte diesem Hochelfen beinahe den Kopf abgeschlagen, als er auf der Suche nach Gidwin in den Pestwald lief. Ihr solltet ihm folgen.|n|nDer Pestwald ist ziemlich groß, $N. Viel Glück. Ich hoffe, ihr $GJungs:Drei; kommt heil aus dem Wald heraus.', },
    {'Findet Tarenar Sonnenhieb im Pestwald in den Östlichen Pestländern.', },
  },
  [27525] = {
    'Wächter von Stratholme',
    {'Baroness Anastari hält ihn gefangen? Hier im Pestwald?|n|nDer Pestwald ist groß... aber wir werden ihn finden. Wir WERDEN Gidwin finden.|n|nUnmittelbar in unserem Osten und Westen befinden sich zwei Nekropolen neben dem Weg nach Stratholme. Im Inneren werdet Ihr zwei Todesrittern begegnen - Totenschwurs Leutnants. Ich bezweifle, dass einer von ihnen Verwendung für eine Paladingeisel hätte, aber vielleicht wissen sie ja, wo Gidwin ist.', },
    {'Tötet Omasum Pesthuf und Karthis Dunkelrune.', },
  },
  [27526] = {
    'Gidwins Schicksal enthüllt',
    {'Rasch - findet einen Eingang zum Schlachthaus südlich von uns. Ich treffe Euch im Inneren.|n|nBereitet Euch auf einen Kampf vor!', },
    {'Sucht nach Gidwin Goldzopf im Schlachthaus im Zentrum des Pestwalds.', },
  },
  [27527] = {
    'Ende der Reise',
    {'Ich halte die Luft an diesem Ort nicht mehr aus. Der Gestank der Untoten ist schon schlimm genug, aber wenn man dem noch Pilze hinzufügt? Ich hasse Pilze!!|n|nIch werde zur Kapelle des Hoffnungsvollen Lichts zurückkehren, $N... und ich nehme Tarenar und Fiona mit. Wir alle haben eine Pause verdient. |n|nHier, nehmt das. Das ist mein Ruhestein - mit ihm könnt Ihr Euch zur Kapelle versetzen lassen. Ich brauche ihn nicht - ich reise auf dem Wagen.|n|nUnd zwar auf dem VORDERSITZ.', },
    nil,
  },
  [27528] = {
    'Geißelmasse',
    {'Man kann die Geißel nicht einfach töten. Sie kommt zurück. Man muss die verdorbene Masse zerstören, aus denen sie besteht... und selbst dann kehren diese Unholde manchmal als Schreckgespenster zurück.|n|nNur wenige Untote bringen so viel Masse mit wie die schwerfälligen Monstrositäten. Tötet sie und verbrennt ihre Leichen. Ihr findet sie überall im Pestwald.|n|nLasst Euren Zorn nicht erkalten, <Volk>. Vergesst nicht, dass diese Monstrositäten aus den Körpern guter Leute zusammengenäht wurden. Ihre Existenz ist ein Verbrechen.', },
    {'Tötet 8 überladene Golems und steckt ihre Kadaver mit der Fackel des Kreuzfahrers in Brand.', },
  },
  [27529] = {
    'Verteidiger von Darroheim',
    {'Die Schlacht von Darroheim war eine der großen Tragödien, die wir Menschen durch die Geißel erleiden mussten. Bis heute hallt sie nach.|n|nViele der mutigen Verteidiger der Stadt ziehen nun als schreckliche Diener der Geißel umher. Wir werden ihr Leid beenden.|n|nJagt Menschenfresserghule hier im Pestwald. Viele dieser Abscheulichkeiten waren einst rechtschaffene Menschen in Darroheim. Die Zerstörung ihrer Körper wird ihre Seele befreien.', },
    {'Befreit 8 Darroheimgeister aus den Körpern der Menschenfresserghule und sprecht mit ihnen.', },
  },
  [27530] = {
    'Die Kadaverbestien',
    {'Feige Kultisten widmen sich im Süden einer düsteren Aufgabe: Sie reanimieren gewaltige Fleischberge, um aus ihnen Riesen zu erschaffen, die Kadaverbestien genannt werden. Zum Glück für uns sind diese Riesen noch leblos und schwach.|n|nNehmt dieses Amulett - benutzt es, um einen Brunnen heiliger Energie zu erschaffen. Versucht, drei dieser Quellen in der Nähe einer der Kadaverbestien zu platzieren, die von den Kultisten reanimiert werden. Die heilige Energie sollte ausreichen, um sie zu überladen und ihren Körper für immer zu zerstören.', },
    {'Zerstört die Hüllen dreier Kadaverbestien, indem Ihr drei oder mehr Argentumlichtbrunnen neben ihnen platziert. Ihr könnt die Argentumlichtbrunnen nicht im Kampf platzieren und nicht weniger als zehn Meter voneinander entfernt.', },
  },
  [27531] = {
    'Seuchenabwehrforschung',
    {'Einst habe ich als Apotheker für die sogenannte "Bansheekönigin" Sylvanas gearbeitet. Ich habe sie einmal bewundert, aber etwas in ihr hat sich verändert. Sie ist nicht mehr sie selbst.|n|nIch habe den Schwur, der mich an die Verlassenen band, gebrochen und trat dem Kreuzzug bei. Nun benutze ich meine Kenntnisse der Alchemie, um nach einem Wirkstoff gegen die Seuche zu suchen. Der Pestwald ist der geeignete Ort dafür.|n|nIch brauche Nachschub für einige Reagenzien, die man im Pestwald findet. Ich werde Euch für jeden Gegenstand, den Ihr findet, bezahlen.', },
    {'Beschafft 20 Faulbeeren, 5 abgetrennte Arme und 1 Stapel Fußabschabung eines Fleischgiganten.', },
  },
  [27532] = {
    'Der Pestwaldturm',
    {'Nach den ungünstigen Entwicklungen im Fall Gidwin denke ich, ein Mann meines Alters sollte die gefährliche Reise durch den Pestwald nicht antreten. Das ist nicht schlimm - ich werde den Pestwaldturm bei meiner nächsten Rundreise besuchen.|n|nAllerdings habe ich eine Lieferung für Judkins. Ihr seid jünger als ich und kampferprobt. Würdet Ihr ihm diese Lieferung bringen?', },
    {'Bringt Leuchtfeuers Paket zu Erzapotheker Judkins beim Pestwaldturm in den Östlichen Pestländern.', },
  },
  [27533] = {
    'Ein Schicksal schlimmer als der Schlachter',
    {'Die Bewohner des Schreckenstals wurden zuerst krank, dann böse. Das sind wirklich keine guten Zeiten.|n|nUnd die Schweine... sie wurden ebenfalls krank! Womit haben Schweine eine solche Krankheit verdient? Hah hah hah! Nichts!|n|nDie Leute interessieren mich nicht, aber die bösen Schweine machen mich immer noch traurig. Solltet Ihr sie jedoch töten... Wäre ich vielleicht glücklich.', },
    {'Tötet 9 verseuchte Schweine.', },
  },
  [27534] = {
    'Augustus\' Quittungsbuch',
    {'Ich bin jetzt bereit fürs Geschäftliche! Was wollt Ihr?|n|nOh, Moment mal... ohne mein Quittungsbuch kann ich kein Geschäft eröffnen. Wie soll ich ohne mein Quittungsbuch den Überblick behalten?|n|nIch muss es irgendwo in der Stadt gelassen haben. Ich hatte ein Zimmer im Gasthaus... dort muss das Buch sein.|n|nBringt mir mein Buch. Bitte, bringt es mir! Bringt mir mein Buch und Ihr werdet sehen! Ich eröffne mein Geschäft und Ihr werdet sehen, dass meine Preise der WAHNSINN sind!', },
    {'Beschafft Euch Augustus\' Quittungsbuch aus dem Gasthaus im Schreckenstal.', },
  },
  [27535] = {
    'Ein bisschen meschugge',
    {'Ich sehe gelegentlich nach Augustus im Schreckenstal, nur um sicherzustellen, dass es ihm gut geht. Manche von uns Untoten kommen wohl mit der Seuche besser klar als andere.|n|nDas Schreckenstal liegt westlich von hier. Würdet Ihr für mich nach ihm sehen?', },
    {'Sprecht mit Augustus dem Meschuggenen im Schreckenstal.', },
  },
  [27536] = {
    'Größtenteils harmlos',
    {'Hier ist noch ein Gefallen, den Ihr mir tun könnt, $Galter Freund:alte Freundin;.|n|nKürzlich ist eine ganze Ladung Landminen aus Beutebucht angekommen. Aber jemand hat sie alle über Nacht gestohlen!|n|nWer immer es war, er war nicht besonders sorgfältig, denn er hat sie überall im Sumpf östlich von hier fallengelassen. Kein Goblin, der mir bekannt ist, würde so unvorsichtig sein.|n|nIch möchte, dass Ihr da rausgeht und diese Landminen für mich einsammelt. Ich bin sicher, dass sie vollkommen sicher und entschärft sind. Jede einzelne. Jawohl.', },
    {'Sammelt 8 entschärfte Landminen im Sorgendunkel östlich von Kraulsumpf.', },
  },
  [27537] = {
    'Wer Elementare sät, wird Sturm ernten',
    {'Unsere Freunde des Irdenen Rings haben versucht, Portale zurück nach Sturmwind zu öffnen, aber sie hatten kein Glück. Thordun hier sagt mir jedoch, dass er vielleicht die Lösung für unser Problem hat.|n|nDie wahnsinnigen Wasserelementare im nahegelegenen Fluss Verrall sind in Raserei verfallen. Thordun sagt, dass wir ihre Energie kanalisieren können, um ein Portal zu schaffen.|n|nIch habe ja keine Ahnung von diesem Elementar-Schnickschnack, aber eines verstehe ich ganz deutlich: Elementare töten und ihren Strudelkern nehmen. Bringt sie zu Talaa im Hof!', },
    {'Tötet matschige Wasserelementare, um 5 Strudelkerne zu sammeln.', },
  },
  [27538] = {
    'Der perfekte Verband',
    {'Geht Ihr zufällig zur Mündung des Verrall? Dann habe ich einen Rat für Euch, der Euren Männern hier sehr helfen kann… und meinem Vogel!|n|nWenn Wasserelementare sich ihren Weg durch Gestein bahnen, entsteht ein seltsamer Schlamm. Getrocknet ist er hart wie Stein, aber er enthält die erfrischende Macht des Wassers. Wenn Ihr einen Gipsverband aus diesem Schlamm herstellt, wachsen gebrochene Knochen wieder zusammen, fest wie Eisen.|n|nBringt ein wenig von diesem Schlamm zu Talaa, der Schamanin da unten. Sie wird wissen, was damit zu tun ist!', },
    {'Sammelt 10 Haufen Verrallschlamm.', },
  },
  [27539] = {
    'Werft sie auf den Haufen',
    {'Ich sammle die Köpfe der Skelette, die ich besiege. Ich habe schon einen kleinen Haufen zusammen.|n|nSolltet Ihr zufällig Schädel finden, könnt Ihr sie gern dazu legen. Der Schädelhaufen scheint die Wellen der Untoten zurückzuhalten und... na ja... ich betrachte ihn auch sehr gern.', },
    {'Beschafft 16 stinkende Schädel von verfluchten Magiern und Soldaten der Geißel im Pestwald.', },
  },
  [27540] = {
    'Die Wildhämmer',
    {'Ihr habt zweifellos die Erdbeben gespürt. Vielleicht habt Ihr sogar gesehen, wie Elementare über das Land und die Städte hereinbrechen. Der Irdene Ring versucht krampfhaft zu verstehen, was hier passiert. Glücklicherweise haben uns die Schamanen der Wildhämmer ihre Hilfe angeboten.|n|nGavan Graufeder befindet sich auf Burg Sturmwind, um unsere Bemühungen mit den Anführern der verschiedenen Allianzfraktionen zu koordinieren. Sprecht mit ihm und versucht, etwas über diese Ereignisse in Erfahrung zu bringen, $N.', },
    {'Sprecht mit Gavan Graufeder auf Burg Sturmwind.', },
  },
  [27541] = {
    'Lektionen der Vergangenheit',
    {'Dieser unglückliche Forscher hat offensichtlich in letzter Zeit ziemliches Pech gehabt.|n|nDie Vernunft gebietet, dass Ihr die Leiche auf Hinweise durchsucht. Darum wird Euch niemand beneiden, aber wir brauchen Hinweise, die Licht in unsere Umgebung bringen...', },
    {'Erhaltet die zerbrochene Brille.', },
  },
  [27542] = {
    'An die Front',
    nil,
    nil,
  },
  [27543] = {
    'Was wir getan haben',
    nil,
    nil,
  },
  [27544] = {
    'Cenarische Hartnäckigkeit',
    {'Ich glaube, diese Druiden geben nie auf. Ich habe die Pestländer schon vor Jahren aufgegeben, aber diese Optimisten vom Zirkel des Cenarius behaupten, es gäbe noch Hoffnung für dieses Land.|n|nDie letzte Besucherin war eine Nachtelfe, die auf dem Weg nach Norden, ins Fungustal, war. Sie sagte, diese Länder würden sich vollständig erholen, wenn wir uns nur Mühe geben. Ich weiß nicht, ob ich das glauben soll.|n|nGlaubt Ihr diesen Unsinn?! Vielleicht solltet Ihr einmal mit ihr reden. Sie müsste immer noch dort oben sein.', },
    {'Sprecht mit Rayne nahe des Eingangs zum Fungustal.', },
  },
  [27545] = {
    'Der Weg ist geöffnet',
    {'Mein Schamanenfreund und ich werden hier bleiben, um das Portal aufrechtzuerhalten.|n|nIhr solltet nach oben gehen und Kurdran benachrichtigen, dass unsere Arbeit hier erledigt ist. Es wird ihn freuen, zur Abwechslung mal gute Nachrichten zu hören.', },
    {'Sprecht mit Kurdran Wildhammer in Hochstade im Schattenhochland.', },
  },
  [27546] = {
    'Sprecht mit Hauptmann Anton',
    {'Ihr habt zweifellos die Erdbeben gespürt. Vielleicht habt Ihr sogar gesehen, wie Elementare über das Land und die Städte hereinbrechen. Wir haben viele unserer weisesten Köpfe nach Nagrand entsandt, um von den Elementen Rat einzuholen.|n|nAber es gibt hier dennoch viel zu tun. Die Wachen von Sturmwind werden mit den Bürgern nicht fertig, die sich Sorgen um ihre Freunde und Verwandte machen.|n|nBitte, $C, sprecht mit Hauptmann Anton in Burg Sturmwind und stellt Euch in seinen Dienst.', },
    {'Sprecht mit Hauptmann Anton in Burg Sturmwind.', },
  },
  [27547] = {
    'Folgenlos',
    {'Unsere Streitkräfte in Lohenscheit wurden vor Kurzem durch einen Schleichangriff überrascht. Die 7. Legion hat es geschafft, ihre Späher in die Stadt einzuschleusen und schließlich unsere Truppen zu dezimieren.|n|nDie Dunkle Fürstin hat uns mit einer Rettungsmission beauftragt. Wir sollen Überlebende finden und sie sicher aus Lohenscheit herausbringen. Wenn noch Soldaten am Leben sind, so sind sie wahrscheinlich nutzlos, aber wir werden das tun, was die Dunkle Fürstin befiehlt.|n|nLasst uns diesen Unsinn hinter uns bringen, $N. Lohenscheit ist direkt im Südwesten der Frontlinie der Verlassenen.', },
    {'Rettet 8 kauernde Soldaten.', },
  },
  [27548] = {
    'Lehrstunden in Angst',
    {'Unsere Feinde werden immer schlauer und passen sich an unsere Strategien an. Erst vor Kurzem wurde Lohenscheit im Südwesten von hier angegriffen. Unsere Streitkräfte, die die Stadt besetzt halten, wurden natürlich dezimiert, aber was den Angriff besonders interessant macht, war die Völkerzusammensetzung der angreifenden Truppe. Es gab keine Menschen.|n|n<Walden lacht.>|n|nSie fürchten sich zu Recht davor, als Verlassene wiedererweckt zu werden.|n|nLasst uns den Nicht-Menschen eine Lektion in Angst erteilen. Zusammen werden wir ihnen zeigen, was mit Leichen geschieht, für die wir keine Verwendung haben.', },
    {'Tötet 12 Späher der 7. Legion.', },
  },
  [27549] = {
    'Bei Sternenlicht',
    {'Schaut Euch das an, $N.|n|n<Harrison hält die Brille des toten Spähers hoch.>|n|nIch habe die Klammer in der Mitte angezogen und die Drähte an den Kanten etwas gezwirbelt. Sie mag nicht bequem sein, aber sie sollte halten.|n|nWenn ich Eure Schrifttafeln richtig übersetzt habe, ist hier etwas versteckt - ein letztes Teil für unser Puzzle.|n|nIch hoffe, Eure Brille birgt den Schlüssel.|n|nLasst mich wissen, was Ihr findet!', },
    {'Sammelt 7 schwebende Sternenlichter.', },
  },
  [27550] = {
    'Lohenscheits Fall',
    {'Die Angriffe gegen unsere Front sind ein Ablenkungsmanöver. Da unsere Aufmerksamkeit dem Ansturm der Worgen galt, hat die Allianz es geschafft, Lohenscheit von unseren Besatzungstruppen zurückzuerobern.|n|n<Godfrey übergibt Euch ein Bündel Fackeln.>|n|nEs muss ausgelöscht werden.|n|nMit diesen Fackeln werden wir Lohenscheit bis auf die Grundmauern niederbrennen und nur Asche für den Feind hinterlassen, hinter der er sich verstecken kann.|n|nLasst uns keine weitere Minute vergeuden. Lohenscheit liegt südwestlich der Frontlinie der Verlassenen. Führt uns dorthin, $N.', },
    {'Benutzt das Bündel Fackeln, um das Rathaus von Lohenscheit, das Gasthaus von Lohenscheit und die Kapelle von Lohenscheit niederzubrennen.', },
  },
  [27551] = {
    'Das Schreiben der Baroness',
    {'Die Notiz stammt von Baroness Anastari. Darin beschreibt sie ein Ritual, das sehr bald auf dem mittleren Schlachthaus im Pestwald abgehalten werden soll - etwas südlich von Tarenars Aufenthaltsort. Vielleicht halten sie dort Gidwin fest!|n|nTarenar muss davon erfahren... und zwar rasch, bevor es zu spät ist!', },
    {'Bringt Tarenar das Schreiben der Baroness.', },
  },
  [27555] = {
    'Fionas Glücksbringer',
    nil,
    nil,
  },
  [27556] = {
    'Gidwins Waffenöl',
    nil,
    nil,
  },
  [27557] = {
    'Tarenars Talisman',
    nil,
    nil,
  },
  [27558] = {
    'Pamelas Puppe',
    nil,
    nil,
  },
  [27559] = {
