  [28768] = {
    nil,
    {'Die Zwergenfrau Donova Schneeweh ist mit dem Furbolgs der Holzschlundfeste befreundet.|n|nWir handeln mit Feuerwasser.|n|nSie ist bei den Frostfeuerquellen im Westen, wenn Ihr durch unsere Höhle geht.|n|nSie braucht Unterstützung beim Verprügeln der Furbolgs der Winterfelle. Vielleicht könnt Ihr ihr helfen.', },
    {'Meldet Euch bei Donova Schneeweh an den Frostfeuerquellen in Winterquell.', },
  },
  [28769] = {
    'Worgs im Schafspelz',
    {'Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.|n|nIm Wald nordwestlich sind Spione der Schwarzfelsorcs. Sie spähen uns durch Handfernrohre aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!|n|nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir wissen, dass sie uns beobachten und dass wir vorbereitet sind!', },
    {'Tötet 8 Spione des Schwarzfels.', },
  },
  [28770] = {
    'Worgs im Schafspelz',
    {'Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.|n|nIm Wald nordwestlich sind Spione der Schwarzfelsorcs. Sie spähen uns durch Handfernrohre aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!|n|nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir wissen, dass sie uns beobachten und dass wir vorbereitet sind!', },
