  [28775] = {
    'Zerbrochene Schlangenfigur',
    nil,
    {'Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.', },
  },
  [28776] = {
    'Zerbrochene Figur eines Irdenen',
    nil,
    {'Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.', },
  },
  [28777] = {
    'Beschädigte Figur einer Eule',
    nil,
    {'Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.', },
  },
  [28778] = {
    'Zerbrochene Figur eines Keilers',
    nil,
    {'Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.', },
  },
  [28779] = {
    'Weit von zuhause entfernt',
    {'Ich habe das Gefühl, dass man mich hat fliehen lassen, weil ich hier ohnehin nicht fort kann.|n|nIch sitze auf diesen Plattformen fest und deshalb finden sie mich früher oder später sowieso. Es sei denn...|n|nMan sagt, das Herz eines Elementarfürsten übertrüge demjenigen, der es in Händen hält, die Eigenschaften des jeweiligen Elements. Im Falle von Luft wäre das für eine Reise hinab äußerst nützlich.|n|nBringt mir das Herz von Großwesir Ertan, sodass ich mithilfe seiner Magie sicher an der Küste von Uldum landen kann.', },
    {'Beschafft das Herz von Großwesir Ertan.', },
  },
  [28780] = {
    'Stürzt Euch in die Schlacht!',
    nil,
    {'Meldet Euch bei Unteroffizier Willem hinter der Abtei von Nordhain im Wald von Elwynn.', },
  },
  [28781] = {
    'Gelegenheitsziele',
    {'Wir waren Teil einer verdeckten Operation, die Prinz Nadun von Ramkahen eingefädelt hat. Wir haben die meisten unserer Einheiten in einem Hinterhalt verloren und wir sind jetzt nicht mehr in der Lage, unsere Mission abzuschließen.|n|nFalls es für Euch eine Rolle spielt, kann ich Euch zu einer ansehnlichen Belohnung verhelfen.|n|nUns wurde aufgetragen, jedes sich bietende Ziel auszuschalten, das für die militärische Infrastruktur der Feinde von Bedeutung ist.|n|nWir haben General Husam ausfindig gemacht und zwei seiner Hauptmänner. Wenn Ihr sie für uns tötet, würdet Ihr Ramkahen einen großen Dienst erweisen.', },
    {'Tötet General Husam und 2 eingeschworene Hauptmänner.', },
  },
  [28782] = {
    'Ein legendärer Vogel',
    {'Die einheimischen Legenden berichten von einer riesenhaften Eule, die über den Berggipfeln kreist wie der geflügelte Tod. Man nannte sie Todesschwinge.|n|nKurz darauf erfuhr man, dass der Name bereits vergeben war. Also entschied man sich für einen Ersatznamen, der ebenfalls Furcht und Schrecken verbreiten sollte:|n|nHöllenschuhu.|n|nHöllenschuhu ist auf dem Berggipfel südwestlich unserer Räuchergrube anzutreffen. Bringt dieses teuflische Nachttier zum Schweigen... damit wir es essen können!', },
    {'Tötet Höllenschuhu.', },
  },
  [28783] = {
    'Die Quelle ihrer Macht',
    {'Bevor unsere Truppe in den Hinterhalt geriet, haben wir es noch geschafft, den Gegner auszuspionieren. |n|nWir haben herausgefunden, dass Siamat, der Gesandte von Todesschwinge, den Neferset ihre neue Kraft verleiht.|n|nSie haben behauptet, er hätte ihnen wieder zu alter Größe verholfen, aber es ist noch etwas anderes geschehen. Ihre Seelen wurden verdorben.|n|nAls einer der vier Winde ist Siamat unglaublich mächtig. Aber dieser Prozess hat ihn einiges seiner Kraft gekostet.|n|nSchlagt jetzt zu, während es noch möglich ist, ihn zu vernichten und bereitet diesem Wahnsinn ein Ende.', },
    {'Tötet Siamat.', },
  },
