  [28934] = {
    'Die Krone zerschmettern',
    {'In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!|n|nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: offenbar in Uldum, direkt östlich vom Grab des Khartut, in der Nähe des Zugangs von Tanaris. Begebt Euch dorthin und mischt sie ordentlich auf!|n|nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.', },
    {'Tötet 5 Techniker der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich vom Grab des Khartut in Uldum zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.', },
  },
  [28935] = {
    'Die Krone zerschmettern',
    {'In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!|n|nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: offenbar in Uldum, direkt östlich vom Grab des Khartut, in der Nähe des Zugangs von Tanaris. Begebt Euch dorthin und mischt sie ordentlich auf!|n|nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.', },
    {'Tötet 5 Techniker der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich vom Grab des Khartut in Uldum zu zerstören und kehrt zu Inspektor Snap Schnappbolz in Orgrimmar zurück.', },
  },
  [28936] = {
    'Diva-Dilemma',
    nil,
    {'Tötet 6 Naga.', },
  },
  [28937] = {
    nil,
    {'Monster! Da waren Monster, sage ich!|n|nUnser Schiff ist südlich von Stromgarde vor Anker gegangen, aber die Küste wimmelt nur so von merkwürdigen Kreaturen.|n|nIhre hässlichen Fratzen zu sehen und ihre komischen Gurgelgeräusche zu hören reicht mir. Ich habe mich aus dem Staub gemacht, bevor klar wurde, was sie im Schilde führen. Ihr geht besser meinen Schiffskameraden helfen, $N!', },
    {'Sprecht mit Lady Gurga in der Faldirbucht.', },
  },
  [28938] = {
