  [29015] = {
    'Des Minenarbeiters Vermögen',
    {'He, $R, seid Ihr an Schätzen interessiert? Wusste ich es doch, dass das Eure Aufmerksamkeit gewinnen würde.|n|nHier an den Flussdocks geht das Gerücht um, dass einer der Minenarbeiter in der Felsadermine der Venture Company nordöstlich von hier einen Smaragd von der Größe Eurer Faust gefunden hat.|n|nIch kenne ein paar Käufer, die daran interessiert wären, so etwas in die Finger zu bekommen, und ich wäre bereit, halbe-halbe beim Verkauf mit Euch zu machen. Seid Ihr dabei?', },
    {'Erhaltet den Katzenaugensmaragd von einem der Vorarbeiter oder Vollstrecker der Venture Co.', },
  },
  [29016] = {
    'Eimer mit Süßigkeiten',
    nil,
    nil,
  },
  [29017] = {
