  [29385] = {
    'Ein Winterhauchgeschenk',
    nil,
    nil,
  },
  [29386] = {
    'Heldenaufruf: Hyjal!',
    {'Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.|n|nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!|n|nSprecht mit Cenarius\' Abgesandter Jademond in Sturmwind, um Zugang zur Mondlichtung zu erlangen.|n|nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, $GBruder:Schwester;!', },
    {'Sprecht mit Cenarius\' Abgesandter Jademond, um auf die Mondlichtung zu reisen.', },
  },
  [29387] = {
    'Die Wächter des Hyjal: Die Invasion der Feuerlande!',
    nil,
    {'Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.', },
  },
  [29388] = {
