  [29389] = {
    'Die Wächter des Hyjal: Die Invasion der Feuerlande!',
    nil,
    {'Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.', },
  },
  [29390] = {
    'Die Wächter des Hyjal: Der Ruf der Uralten',
    nil,
    {'Helft Lo\'Gosh, Tortolla, Aviana und Aessina beim Hyjal.', },
  },
  [29391] = {
    'Die Wächter des Hyjal: Der Ruf der Uralten',
    nil,
    {'Helft Goldrinn, Tortolla, Aviana und Aessina beim Hyjal.', },
  },
  [29392] = {
    'Vermisste Erbstücke',
    {'Meine letzten Besitztümer hätten eigentlich heute aus Theramore eintreffen sollen. Das Schiff ist angekommen, aber ich habe nichts von dem Kurier gehört. Die Kiste, die er transportieren sollte, enthält Gegenstände, die schon seit Generationen im Familienbesitz sind.|n|nWürdet Ihr vielleicht hinunter zum Hafen von Sturmwind gehen und nachsehen, was ihn aufhält?', },
    {'Durchsucht die Kabine auf dem Schiff des angeheuerten Kuriers im Hafen von Sturmwind nach Hinweisen, was den Kurier aufhalten könnte.', },
  },
  [29393] = {
    'Gebräu fürs Braufest',
    {'Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie\'s besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann\'s also gar nicht sein!|n|nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.|n|nJetzt zur Abmachung. Ich lasse Euch dafür auf einem Widder reiten. Mal sehen, was Ihr drauf habt.|n|nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.', },
    {'Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.', },
  },
  [29394] = {
    'Gebräu fürs Braufest',
    {'Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie\'s besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann\'s also gar nicht sein!|n|nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.|n|nJetzt zur Abmachung. Ich lasse Euch dafür auf einem Widder reiten. Mal sehen, was Ihr drauf habt.|n|nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.', },
    {'Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.', },
  },
  [29395] = {
    'FLAG - Teleport nach Uldum',
    nil,
    nil,
  },
  [29396] = {
    'Ein neuer Souvenirlieferant',
    {'<seufz>|n|nHört mir auf mit den Krügen vom letzten Jahr...|n|nIch glaube, dass diese zwielichtigen Bierkruglieferanten irgendwas mit diesem merkwürdigen Schattenhammerkult zu tun hatten, der aufgetaucht ist, bevor die Elementare eingefallen sind.|n|nUnd das ist der Grund, warum wir einen neuen Lieferanten und einen besseren Krug haben!|n|nHier habt Ihr einen Gutschein für einen Bierkrug.|n|nSprecht mit Blix in der Nähe des hinteren Endes des Braufestlagers. Er ist ziemlich seltsam, vor allem, weil er immer diese Brille aufhat. Er wird den Gutschein für Euch bearbeiten, und alle anderen Transaktionen des Braufests.', },
    {'Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.', },
  },
  [29397] = {
    'Ein neuer Souvenirlieferant',
    {'Je weniger Worte wir über die Krüge vom letzten Jahr verlieren, je besser, $N. Ich kann Euch sagen, die letzten Lieferanten, das waren zwielichtige Typen. Letztendlich hat sich herausgestellt, dass sie in irgendwelche Kultistenaktivitäten verwickelt waren...|n|nMit Leuten, die versuchen, die Welt zu zerstören, können wir nicht arbeiten!!|n|nDeshalb haben wir uns einen neuen Lieferanten und einen neuen Krug gesucht.|n|nBringt diesen Gutschein zu Belbi Blitzknips im hinteren Teil des Braufestlagers. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte, die während der Festtage anstehen.', },
    {'Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.', },
  },
  [29398] = {
    'Hehlerware',
    {'Eine schnelle Überprüfung der Kabine ergibt keine Hinweise auf die Identität des Mörders oder seine Motive. Die Kiste, wegen der Ihr gekommen seid, ist verschwunden.|n|nWährend Ihr Euch umdreht, um die Kabine zu verlassen, bemerkt Ihr, dass sich am Boden etwas Kleines bewegt. Eine Gruppe Spinnen kriecht unter dem Bett des erschlagenen Kuriers hervor. Wo könnten sie hinwollen?', },
    {'Folgt den Spinnen zu ihrem Ziel und befragt den Mann, den Ihr dort findet.', },
  },
  [29399] = {
    'Preise vergleichen',
    {'Ich habe dem \'Herrn\' gesagt, dass es da einen Laden im Zwergendistrikt gibt, der vielleicht besser geeignet ist für seine Bedürfnisse. Er heißt "Schattenspiele" und Ihr findet den Eingang in der Nähe der Kanäle auf der westlichen Seite des Distrikts.|n|nQuincy Messerschmied ist Euer Mann. Er handelt mit Waren, die ein ehrlicher Händler nicht mal mit der Kneifzange anfassen würde!', },
    {'Begebt Euch zum Laden "Schattenspiele" im Zwergendistrikt von Sturmwind und sucht nach Hinweisen auf den Besuch des Kistendiebes.', },
  },
  [29400] = {
    'Eine Zeit zum Feiern',
    {'Frohe Grüße, $C.|n|nDie Schlotternächte sind eine Zeit des Feierns und der Besinnlichkeit, obwohl es scheint, dass viele von uns vergessen haben, warum. Das Verbrennen des Weidenmanns im Besonderen ist ein Rätsel für viele außerhalb der Verlassenen.|n|nBegebt Euch zu den Ruinen von Lordaeron über Unterstadt und sprecht mit der Ruferin der Dunkelheit Yanka. Sie wird Euch mehr von der Weidenmannzeremonie erzählen.', },
    {'Sprecht mit der Ruferin der Dunkelheit Yanka in den Ruinen von Lordaeron direkt außerhalb des Eingangs zu Unterstadt.', },
  },
  [29401] = {
    'Weggeweht',
    nil,
    {'Jaga möchte, dass Ihr 5 entflohene Ballons in Orgrimmar einsammelt.', },
  },
  [29402] = {
    'Vorsichtsmaßnahmen',
    nil,
    nil,
  },
  [29403] = {
    'Der Agent des Sammlers',
    {'Quincy zufolge ist der "Sammler", der die Kiste haben will, niemand anders als der wahnsinnige Erzmagier Xylem aus Azshara.|n|nDer treue Diener des Erzmagiers soll sich mit dem Mann, der die Kiste hat, in den Katakomben unterhalb der Kathedrale des Lichts treffen.|n|nIhr müsst Euch rechtzeitig dort einfinden, um den Austausch zu verhindern und die Kiste in Euren Besitz zu bringen, bevor sie für immer an Xylem verloren ist. Trefft mich im "Goldenen Fass", sobald Ihr die Kiste habt.', },
    {'Unterbrecht das Treffen zwischen Sanath Lim-yo und dem Dieb in den Katakomben unterhalb der Kathedrale des Lichts.', },
  },
  [29411] = {
    'Was jetzt?',
    nil,
    nil,
  },
  [29412] = {
    'Weggeweht',
    nil,
    {'Vin möchte, dass Ihr 5 entflohene Ballons in Sturmwind einsammelt.', },
  },
  [29413] = {
    'Die unheimliche Kiste',
    {'Nach ihr ist gesucht worden, sie wurde gestohlen und verkauft. Jeder, der versucht hat, die in ihr enthaltene Magie anzuzapfen, musste erleben, dass sich diese Macht gegen ihn wandte.|n|nUnd doch erscheint die Kiste selbst unversehrt zu sein und erfüllt von magischer Energie. Von Zeit zu Zeit zittert und hüpft sie, als ob ihr Inhalt lebendig wäre.|n|nSie scheint an Euch gebunden zu sein und jetzt gehört sie Euch.', },
    nil,
  },
  [29415] = {
    'Vermisste Erbstücke',
    {'Ich habe dem Kurier gesagt, dass er den Zeppelin nehmen soll, aber nein, er musste ja unbedingt ein Goblinschiff nehmen! Na ja, jetzt ist er verspätet und die wertvollen Erbstücke meiner Familie sind bei ihm.|n|nWenn Ihr helfen wollt, könntet Ihr vielleicht hinunter zu den Docks östlich von Orgrimmar gehen, Euch an Bord des Goblinschiffs begeben und nachsehen, was ihn aufhält?', },
    {'Durchsucht die Kabine auf dem Schiff des angeheuerten Kuriers an den Docks östlich von Orgrimmar nach Hinweisen, was den Kurier aufhalten könnte.', },
  },
  [29416] = {
    'Hehlerware',
    {'Eine schnelle Überprüfung der Kabine ergibt keine Hinweise auf die Identität des Mörders oder seine Motive. Die Kiste, wegen der Ihr gekommen seid, ist verschwunden.|n|nWährend Ihr Euch umdreht, um die Kabine zu verlassen, bemerkt Ihr, dass sich am Boden etwas Kleines bewegt. Eine Gruppe Spinnen kriecht unter dem Bett des erschlagenen Kuriers hervor. Wo könnten sie hinwollen?', },
    {'Folgt den Spinnen zu ihrem Ziel und befragt den Mann, den Ihr dort findet.', },
  },
  [29425] = {
    'Preise vergleichen',
    {'Passt auf, ich habe diesem zwielichtigen Kerl gesagt, dass es da einen Laden in der Gasse gibt, der seinen, ähm, Waren vielleicht offener gegenübersteht. "Droffers und Sohn Bergungen" ist der Name des Geschäfts.|n|nHaltet nach Dran Droffers Ausschau. Er überwacht die \'Bergung\' von seltenen und wertvollen Gegenständen aus ganz Azeroth.', },
    {'Begebt Euch zum Laden "Droffers und Sohn Bergungen" in der Gasse in Orgrimmar und sucht nach Hinweisen auf den Besuch des Kistendiebes.', },
  },
  [29426] = {
    'Vorsichtsmaßnahmen',
    nil,
    nil,
  },
  [29427] = {
    'Der Agent des Sammlers',
    {'Dran zufolge ist der "Sammler", der die Kiste haben will, niemand anders als der wahnsinnige Erzmagier Xylem aus Azshara.|n|nDer treue Diener des Erzmagiers soll sich mit dem Mann, der die Kiste hat, in einer versteckten Ecke im Hof der Ruinen von Lordaeron treffen.|n|nSchnell, nehmt den Zeppelin nach Tirisfal!|n|nIhr müsst Euch rechtzeitig dort einfinden, um den Austausch zu verhindern und die Kiste in Euren Besitz zu bringen, bevor sie für immer an Xylem verloren ist. Trefft mich im "Wyvernschweif" im Tal der Ehre, sobald Ihr die Kiste habt.', },
    {'Unterbrecht das Treffen zwischen Sanath Lim-yo und dem Dieb in den Ruinen von Lordaeron.', },
  },
  [29428] = {
    'Was jetzt?',
    nil,
    nil,
  },
  [29429] = {
    'Die unheimliche Kiste',
    {'Nach ihr ist gesucht worden, sie wurde gestohlen und verkauft. Jeder, der versucht hat, die in ihr enthaltene Magie anzuzapfen, musste erleben, dass sich diese Macht gegen ihn wandte.|n|nUnd doch erscheint die Kiste selbst unversehrt zu sein und erfüllt von magischer Energie. Von Zeit zu Zeit zittert und hüpft sie, als ob ihr Inhalt lebendig wäre.|n|nSie scheint an Euch gebunden zu sein und jetzt gehört sie Euch.', },
    nil,
  },
  [29430] = {
    'Ein Freund in der Not',
    {'Wisst Ihr, ich habe Anson noch gar nicht hier draußen gesehen.|n|nIn letzter Zeit verbringt er seine ganze Zeit damit, sich in der "Güldenen Rose" volllaufen zu lassen.|n|nEtwas muss ihm wirklich an die Nieren gehen! Würdet Ihr vielleicht mal nach ihm sehen?', },
    {'Besucht Anson Hastings in der "Güldenen Rose" in Sturmwinds Handelsdistrikt.', },
  },
  [29431] = {
    'Ein Freund in der Not',
    {'Mit meinem Freund Edgar ist etwas nicht in Ordnung. Normalerweise liebt er die Festivitäten rund um die Schlotternächte.|n|nEr verbringt seine ganze Zeit damit, in der Kneipe "Zum Gebrochenen Hauer" in Orgrimmar mit den Orcs zu trinken. Wäret Ihr so gut und würdet mal bei ihm vorbeischauen und nachsehen, ob es irgendwas gibt, womit man ihn aufmuntern könnte?', },
    {'Sprecht mit Edgar Siegesfroh im "Gebrochenen Hauer" in Orgrimmar.', },
  },
  [29432] = {
    'Delegierung',
    {'Meine Pflicht bindet mich, Euren Aussagen unverzüglich nachzugehen, <Volk>, was bedeutet, dass meine Mission hier nun in Eure Hände fällt.|n|nEin Anstieg uralter Magie, viel zu stark, um natürlichen Ursprungs zu sein, führte mich hierher. Seitdem habe ich eine zutiefst beunruhigende Entwicklung entdeckt.|n|nEin Ast wurde von Nordrassil abgebrochen und tief in die Feuerlande verschleppt. Dort droht ein mächtiges Ritual, Nordrassil zu verderben und ihn in Flammen aufzuzehren.|n|nIhr müsst einen Weg finden, das Ritual zu unterbrechen und den Zweig des Weltenbaumes zurückzuholen.', },
    {'Erlangt den Zweig von Nordrassil aus den Feuerlanden zurück.', },
  },
  [29433] = {
    'Beweist Eure Stärke',
    {'Einige Leute haben so lange Spaß, bis jemand verletzt wird. Ich nenne solche Leute Schwächlinge.|n|nWahre Stärke beweist nur der, der jemanden oder etwas verletzt. Ihr verletzt Euch selbst, weil Ihr Euren Körper an seine Grenzen führt, und Ihr verletzt die, die anderen schaden wollen.|n|nWenn Ihr der Stärkste sein wollt, müsst Ihr kämpfen. Wie wichtig ist Euch das?|n|nIch will, dass Ihr die niederstreckt, die Euch herausfordern und mir einen Beweis Eures Triumphs bringt.', },
    nil,
  },
  [29434] = {
    'Panzergeneral',
    {'Willkommen zu unserem bescheidenen kleinen Dampfpanzerkampf-Simulator! Für nur einen Spieljeton könnt Ihr Euer strategisches Können unter Beweis stellen. Fahrt über unseren Parcours und zerstört die Panzerziele.', },
    {'Zerstört mit Eurem Dunkelmond-Panzer 30 Ziele in der veranschlagten Zeit.', },
  },
  [29436] = {
    'Die menschliche Kanonenkugel',
    {'Für nur einen Spieljeton des Dunkelmond-Jahrmarkts könnt Ihr Euch aus der Blastenheimer 5000 Ultrakanone abschießen lassen. Doch damit ist der Spaß noch nicht vorbei! Wir haben ein Ziel im Meer nahe des Piers aufgebaut.|n|nWenn Ihr bei Euren Landungen fünf Punkte erzielt, könnt Ihr Gewinnlose bekommen.|n|nEin Treffer ins Schwarze bringt 5 Punkte, einer ins Ziel 3 Punkte und einer knapp neben dem Ziel 1 Punkt.|n|nViel Glück bei der Landung!', },
    {'Erreicht 5 Kanonenzielpunkte, indem Ihr in der Nähe des Kanonenziels landet.', },
  },
  [29437] = {
    'Der gefallene Wächter',
    {'Fandral Hirschhaupt ist hier auf dem Hyjal gefangen gehalten worden. Es war der grüne Drache Alysra - eine von uns! -, die damit beauftragt war, Fandral zu bewachen.|n|nWir können nur vermuten, dass es dem Schattenhammer gelungen ist, sie zu verderben. Ihr müsst sie stellen, $N. Vernichtet sie, wenn es sein muss - ich kann es nicht ertragen, dabei zuzusehen.|n|nZuletzt wurde sie bei den Ruinen von Lar\'donir gesichtet, westlich des Weltenbaums.', },
    {'Stellt und tötet Alysra bei den Ruinen von Lar\'donir.', },
  },
  [29438] = {
    'Er schießt, er trifft!',
    {'Glaubt Ihr, dass Ihr gut schießen könnt? Habt Ihr eine ruhige Hand?|n|nWie wäre es dann mit ein paar Schüssen?|n|nEs kostet Euch nur einen Spieljeton, Eure Fähigkeiten unter Beweis zu stellen.|n|nNa, wie gut seid Ihr?', },
    {'Erreicht 25 Punkte in 60 Sekunden.', },
  },
  [29439] = {
    'Der Ruf des Weltenschamanen',
    nil,
    {'Sprecht mit Thrall, direkt südlich des Weltenbaums auf dem Hyjal.', },
  },
  [29440] = {
    'Der Ruf des Weltenschamanen',
    {'Der Irdene Ring bittet Euch erneut um Eure Mithilfe, $N.|n|nThrall hat sein Amt als Kriegshäuptling der Horde niedergelegt, aber für seine neue Aufgabe benötigt er die Unterstützung seines Volkes mehr als je zuvor. Er hat darum gebeten, dass einer der besten Streiter der Horde ihm bei seiner nächsten Unternehmung zur Seite steht, bei einem Heilungsritual, das tiefgreifende Auswirkungen auf unsere Welt haben wird.|n|nIhr werdet ihn unter den Zweigen von Nordrassil auf dem Hyjal finden, auf der südlichen Seite des Baums.', },
    {'Sprecht mit Thrall, direkt südlich des Weltenbaums auf dem Hyjal.', },
  },
  [29441] = {
    'Aus dem Bauch der Bestie',
    nil,
    nil,
  },
  [29443] = {
    'Ein merkwürdiger Kristall',
    {'Energie wirbelt in dem seltsamen Kristall umher. Vielleicht diente er einst als magischer Brennpunkt, als Energiequelle oder als simpler Glücksbringer. Das lässt sich nicht sicher sagen.|n|nDer Abenteuerführer des Dunkelmond-Jahrmarkts weist Euch darauf hin, dass sich Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt dafür interessieren könnte.', },
    {'Bringt den energiegetränkten Kristall zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29444] = {
    'Ein exotisches Ei',
    {'Ihr seid Euch nicht sicher, welches Wesen sich in diesem Ei befindet, aber das Ei stammt sicherlich nicht von einem normalen Tier.|n|nIm Abenteuerführer des Dunkelmond-Jahrmarkts heißt es, ein unerschrockener Abenteurer könne bei seinen Reisen auf eine ganze Reihe seltsamer Eier stoßen. Außerdem weist er darauf hin, dass das Kuriositätenkabinett auf dem Dunkelmond-Jahrmarkt stets am Erwerb solcher Exemplare interessiert ist.|n|nBringt das Ei zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt.', },
    {'Bringt das monströse Ei zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29445] = {
    'Ein faszinierender Zauberfoliant',
    {'Ihr findet keinen Hinweis auf den Ursprung dieses gewaltigen magischen Werkes. Seine Seiten sind voll mit Zaubern und Verzauberungen, von denen Euch nur einige wenige vertraut sind.|n|nIm Abenteuerführer des Dunkelmond-Jahrmarkts steht, der Foliant könnte für Sayge, den berühmten gnollischen Jahrmarktswahrsager auf dem Dunkelmond-Jahrmarkt, von Interesse sein.', },
    {'Bringt den geheimnisvollen Zauberfolianten zu Sayge auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29446] = {
    'Eine wundersame Waffe',
    {'Ihr untersucht die Waffe und seht, dass sie hervorragend verarbeitet und edel verziert ist. Aber sie wurde nicht nur zur Zierde getragen, sondern auch im Kampf benutzt, das beweisen die winzigen Scharten auf der Klinge.|n|nIm Abenteuerführer des Dunkelmond-Jahrmarkts sind verschiedene seltene und wertvolle Waffen aufgeführt. Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt würde sich bestimmt für dieses Stück interessieren.', },
    {'Bringt die verzierte Waffe zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29447] = {
    'Ein merkwürdiger Kristall',
    {'Energie wirbelt in dem seltsamen Kristall umher. Vielleicht diente er einst als magischer Brennpunkt, als Energiequelle oder als simpler Glücksbringer. Das lässt sich nicht sicher sagen.|n|nDer Abenteuerführer des Dunkelmond-Jahrmarkts weist Euch darauf hin, dass sich Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt dafür interessieren könnte.', },
    {'Bringt den energiegetränkten Kristall zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29448] = {
    'Ein exotisches Ei',
    {'Ihr seid Euch nicht sicher, welches Wesen sich in diesem Ei befindet, aber das Ei stammt sicherlich nicht von einem normalen Tier.|n|nIm Abenteuerführer des Dunkelmond-Jahrmarkts heißt es, ein unerschrockener Abenteurer könne bei seinen Reisen auf eine ganze Reihe seltsamer Eier stoßen. Außerdem weist er darauf hin, dass das Kuriositätenkabinett auf dem Dunkelmond-Jahrmarkt stets am Erwerb solcher Exemplare interessiert ist.|n|nBringt das Ei zu Yebb Nabetand nahe der Tierunterkünfte, wenn der Jahrmarkt geöffnet ist.', },
    {'Bringt das monströse Ei zu Yebb Nabetand, wenn der Dunkelmond-Jahrmarkt geöffnet ist.', },
  },
  [29449] = {
    'Ein faszinierender Zauberfoliant',
    {'Ihr findet keinen Hinweis auf den Ursprung dieses gewaltigen magischen Werkes. Seine Seiten sind voll mit Zaubern und Verzauberungen, von denen Euch nur einige wenige vertraut sind.|n|nIm Abenteuerführer des Dunkelmond-Jahrmarkts steht, der Foliant könnte für Sayge, den berühmten Jahrmarktswahrsager, von Interesse sein. Ihr findet ihn in der Nähe seines Zeltes auf der Dunkelmond-Insel.', },
    {'Bringt den geheimnisvollen Zauberfolianten zu Sayge, wenn der Dunkelmond-Jahrmarkt geöffnet ist.', },
  },
  [29450] = {
    'Eine wundensame Waffe',
    {'Ihr untersucht die Waffe und seht, dass sie hervorragend verarbeitet und edel verziert ist. Aber sie wurde nicht nur zur Zierde getragen, sondern auch im Kampf benutzt, das beweisen die winzigen Scharten auf der Klinge.|n|nIm Abenteuerführer des Dunkelmond-Jahrmarkts sind verschiedene seltene und wertvolle Waffen aufgeführt. Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt würde sich bestimmt für dieses Stück interessieren.', },
    {'Bringt die verzierte Waffe zu Professor Thaddeus Paleo, wenn der Dunkelmond-Jahrmarkt geöffnet ist.', },
  },
  [29451] = {
    'Der Meisterstratege',
    {'Dieser Foliant über Strategie ist das Meisterwerk des berühmten menschlichen Generals Anduin Lothar. Darin beschreibt der Kommandant in seinen eigenen Worten die korrekte Aufstellung einer Armee und Strategien, mit denen man fast jede Schlacht gewinnen kann.|n|nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt würde sich bestimmt für ein so seltenes Buch interessieren.', },
    {'Bringt die Abhandlung zu strategischem Vorgehen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29452] = {
    'Eure Zeit ist gekommen',
    {'<Ein angenehmes Bild erscheint vor Eurem inneren Auge, als eine ruhige Stimme Euren Körper erfüllt.>|n|n<Junger/Junge:c> $C, seid ganz ruhig und hört meine Worte.|n|nIch wurde gerufen, um Euch abzuholen und abzuliefern, bei jemandem, dessen Blick niemand entkommt.|n|nFindet mich in Orgrimmar, sterbliches Wesen, denn Eure Zeit ist gekommen.', },
    {'Sprecht mit Ziradormi in Orgrimmar.', },
  },
  [29453] = {
    'Eure Zeit ist gekommen',
    {'<Ein angenehmes Bild erscheint vor Eurem inneren Auge, als eine ruhige Stimme Euren Körper erfüllt.>|n|n<Junger/Junge:c> $C, seid ganz ruhig und hört meine Worte.|n|nIch wurde gerufen, um Euch abzuholen und abzuliefern, bei jemandem, dessen Blick niemand entkommt.|n|nFindet mich in Sturmwind, sterbliches Wesen, denn Eure Zeit ist gekommen.', },
    {'Sprecht mit Coridormi in Sturmwind.', },
  },
  [29454] = {
    'Der Meisterstratege',
    {'Dieser Foliant über Strategie ist das Meisterwerk des berühmten menschlichen Generals Anduin Lothar. Darin beschreibt der Kommandant in seinen eigenen Worten die korrekte Aufstellung einer Armee und Strategien, mit denen man fast jede Schlacht gewinnen kann.|n|nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt würde sich bestimmt für ein so seltenes Buch interessieren. Sucht ihn in der Heimat des Jahrmarkts auf der Dunkelmond-Insel auf.', },
    {'Bringt die Abhandlung zu strategischem Vorgehen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29455] = {
    'Werft den Ring',
    {'Hey Ihr! Haltet ein!|n|nWollt Ihr allen beweisen, wie talentiert Ihr seid? Sorgt dafür, dass drei Ringe auf der Dunkelmond-Schildkröte landen, dann bekommt Ihr eine Belohnung.|n|nFür einen Spieljeton könnt Ihr einen Stapel Ringe kaufen, um der Welt zu zeigen, warum wir Euch auf dem Jahrmarkt $N, "$Gden Adleräugigen:die Adleräugige;" nennen.', },
    {'Werft 3 Ringe auf die Dunkelmond-Schildkröte.', },
  },
  [29456] = {
    'Ein erbeutetes Banner',
    {'Auf dem zerschlissenen Banner ist ein verblasstes Gildenwappen zu sehen. Das alte Banner muss viele Schlachten mitgemacht haben.|n|nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt sammelt Banner und andere Kriegsrelikte. Vielleicht wäre er auch an diesem interessiert. Zeigt ihm das Banner, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.', },
    {'Bringt das Banner der Gefallenen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29457] = {
    'Das Insigne des Feindes',
    {'Das Insigne eines gegnerischen Offiziers ist auf dem zerbeulten Abzeichen zu sehen. Für Euch ist es kaum mehr wert als das Metall, aus dem es besteht, aber für einen Sammler von Kriegsandenken wäre es von großem Interesse.|n|nDie Sammlung von Kriegsartefakten, die Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt zusammengetragen hat, ist in ganz Azeroth bekannt. Zeigt ihm das Abzeichen, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal aufsucht.', },
    {'Bringt das erbeutete Tagebuch zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29458] = {
    'Das erbeutete Tagebuch',
    {'Der Umschlag des Buches besteht aus abgewetztem, mit Blut und Schlamm besudeltem Leder. Ihr blättert die Seiten durch und erkennt, dass es sich um das Tagebuch eines Abenteurers handelt, der sehr von sich und seinen Abenteuern eingenommen ist.|n|nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt könnte sich dafür interessieren.', },
    {'Bringt das Tagebuch eines Abenteurers zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29459] = {
    'Ein erbeutetes Banner',
    {'Auf dem zerschlissenen Banner ist ein verblasstes Gildenwappen zu sehen. Das alte Banner muss viele Schlachten mitgemacht haben.|n|nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt sammelt Banner und andere Kriegsrelikte. Vielleicht wäre er auch an diesem interessiert.', },
    {'Bringt das Banner der Gefallenen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29460] = {
    'Das Insigne des Feindes',
    {'Das Insigne eines gegnerischen Offiziers ist auf dem zerbeulten Abzeichen zu sehen. Für Euch ist es kaum mehr wert als das Metall, aus dem es besteht, aber für einen Sammler von Kriegsandenken wäre es von großem Interesse.|n|nDie Sammlung von Kriegsartefakten, die Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt zusammengetragen hat, ist in ganz Azeroth bekannt.', },
    {'Bringt das erbeutete Tagebuch zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29461] = {
    'Das erbeutete Tagebuch',
    {'Der Umschlag des Buches besteht aus abgewetztem, mit Blut und Schlamm besudeltem Leder. Ihr blättert die Seiten durch und erkennt, dass es sich um das Tagebuch eines Abenteurers der Horde handelt, der sehr von sich und seinen Abenteuern eingenommen ist.|n|nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt könnte sich dafür interessieren.', },
    {'Bringt das erbeutete Tagebuch zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29463] = {
    'Hau-den-Gnoll',
    {'Wollt Ihr ein paar Gnolle hauen? Dann seid Ihr am richtigen Ort.|n|nEure Aufgabe ist einfach: Erreicht 30 Punkte in einer Minute.|n|nBenutzt den Holzhammer, den ich Euch geben werde und legt los. Sprecht mich an, wenn Ihr bereit seid.', },
    {'Erreicht 30 Punkte beim Gnollhauen.', },
  },
  [29464] = {
    'Werkzeuge der Weissagung',
    {'Diese Sammlung abgenutzter Runensteine wurde offensichtlich häufig benutzt. Die Steine wirken alt. Ihr könnt die Einkerbungen auf ihnen nicht zuordnen.|n|nEin Gelehrter oder Sammler könnte mehr darüber wissen. Bringt sie zu Professor Thaddeus Paleo, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.', },
    {'Bringt die Wahrsagerrunen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29465] = {
    'Werkzeuge der Weissagung',
    {'Diese Sammlung abgenutzter Runensteine wurde offensichtlich häufig benutzt. Die Steine wirken alt. Ihr könnt die Einkerbungen auf ihnen nicht zuordnen.|n|nEin Gelehrter oder Sammler könnte mehr darüber wissen. Bringt sie zu Professor Thaddeus Paleo, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.', },
    {'Bringt die Wahrsagerrunen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.', },
  },
  [29466] = {
    'Viele fette Frösche',
    {'Fast jeder in Azeroth hat schon von unseren weltberühmten Knusperfröschen gehört. Wir können kaum die Nachfrage danach erfüllen!|n|nIhr seht aus, als wüsstet Ihr, wie man eine Angel hält, <Volk>. Würdet Ihr mir helfen, meine Froschvorräte aufzufüllen?|n|nDie leckersten Knusperfrösche bekommt man, wenn man die fetten verwendet, die nahe des Steinbullensees vorkommen. Keine Sorge, es wird sich für Euch lohnen.', },
    {'Fangt 5 fette Frösche nahe des Steinbullensees.', },
  },
  [29467] = {
    'Panzerreparatur',
    {'Die Dunkelmonddampfpanzer gehören zu unseren beliebtesten Attraktionen. Unsere Besucher testen ihr Können stundenlang, aber bei all dem Spaß werden die Panzer stark beansprucht.|n|nIhr scheint zu wissen, wie man mit einem Schraubenschlüssel umgeht. Würdet Ihr mir bei der Reparatur der beschädigten Panzer helfen? Ich würde Euch für Euren Zeitaufwand entschädigen.', },
    {'Repariert 5 beschädigte Dampfpanzer auf dem Gelände des Dunkelmond-Jahrmarkts.', },
  },
  [29468] = {
    'Baby braucht zwei Paar Schuhe',
    {'Habt Ihr meine Stute Baby da hinten neben den Wagen gesehen? Sie zieht den Karren mit allen Tieren unseres Kuriositätenkabinetts.|n|nSie arbeitet hart und braucht mehr Hufeisen, als Ihr Euch vorstellen könnt. Es ist wieder einmal Zeit für neue. Die Rohmaterialien habe ich bereits gekauft.|n|nIhr müsst sie nur auf einem Amboss bearbeiten und Baby anlegen. Geht schnell und ist mir ein paar Lose wert, also was meint Ihr?', },
    {'Stellt aus den Eisenbeständen 4 Hufeisen her und legt sie Baby auf dem Dunkelmond-Jahrmarkt an.', },
  },
  [29469] = {
    'Wiederbewaffnung, Wiederverwendung, Wiederverwertung',
    {'Die Jahrmarktsbesucher lieben unsere Dampfpanzer! Wenn der Dunkelmond-Jahrmarkt schließt, liegt all der Panzerschrott auf dem Platz herum.|n|nWäre doch schade, wenn das gute Metall einfach im Dreck verrotten würde.|n|nWäret Ihr so nett, mir einige der größeren Stücke zu bringen, damit ich die kaputten Panzerteile damit reparieren kann? Das ist weitaus billiger als jedes Mal neues Metall zu kaufen. Was meint Ihr?', },
    {'Beschafft 6 Stücke Panzerschrott vom Lagerplatz des Dunkelmond-Jahrmarkts.', },
  },
  [29470] = {
    'Gerbt meine Häute',
    {'Auf dem Dunkelmond-Jahrmarkt wird ständig Leder für Zelte, Stiefel und alles, was Ihr Euch vorstellen könnt, benötigt. Ich habe einige Kreaturen gefangen und ihre Häute aufgespannt.|n|nIhr scheint Euch mit Häuten auszukennen. Ich würde Euch belohnen, wenn Ihr mir beim Abschaben der neuen Häute helfen könntet.', },
    {'Schabt 4 aufgespannte Häute auf dem Lagerplatz des Dunkelmond-Jahrmarkts ab.', },
  },
  [29471] = {
    'Ein Blick in die Zukunft',
    {'Die Beliebtheit des Dunkelmond-Jahrmarkts nimmt zu. Immer mehr Leute suchen mich auf, um einen Blick in ihre Zukunft zu werfen.|n|nHäufig bitten sie um Wissen, das besser im Nebel der Zeit verborgen bleiben sollte, aber solche Ratschläge stehen mir nicht zu.|n|nMein Vorrat an geschriebenen Horoskopen neigt sich dem Ende zu und Ihr scheint eine sichere Hand zu haben. Stellt Tinte aus diesen Kräutern her und schreibt einige Horoskope für mich. Ich werde Euch dafür belohnen.', },
    {'Stellt aus dem Bund exotischer Kräuter prophetische Tinte her. Verbindet die Tinte mit leichtem Pergament, um Sayges Horoskope zu schreiben.', },
  },
  [29472] = {
    'Begehrte Preise',
    {'Die Spiele werden immer beliebter, was bedeutet, dass wir mehr Preise ausgeben als je zuvor.|n|nWir brauchen dringend neue Preise. Wenn Ihr geübt in der Lederverarbeitung seid, würde ich Euch ein Set geben. Ihr werdet einige Teile bei einem Gemischtwarenhändler wie Shadi Nebelläufer auf der zentralen Anhöhe von Donnerfels erwerben müssen, aber sie sind nicht teuer.|n|nWollt Ihr mir helfen?', },
    {'Stellt mit Hilfe des Handwerkersets des Dunkelmond-Jahrmarkts 5 Gewinne des Dunkelmond-Jahrmarkts her. Dazu benötigt Ihr groben Faden, glänzende Schmuckstücke und blauen Farbstoff.', },
  },
  [29473] = {
    'Kratzer, Beulen, blaue Flecke',
    {'Die Arbeit auf dem Dunkelmond-Jahrmarkt ist gefährlich, $N. Unsere Arbeiter verletzen sich oft beim Aufbau, Abbau und Transport der Attraktionen.|n|nWir schicken die am schwersten verletzten Arbeiter auf die Anhöhe der Geister in Donnerfels, aber viele der leicht verletzten können auch hier behandelt werden. Warum nehmt Ihr nicht diese Bandagen und seht, ob Ihr den verletzten Arbeitern helfen könnt?', },
    {'Nehmt die Bandagen des Dunkelmond-Jahrmarkts und heilt damit 4 verletzte Schausteller.', },
  },
  [29474] = {
    'Auch Abfall kann nützlich sein',
    {'Die Leute kommen nicht nur zum Spaß auf den Jahrmarkt, $N. Die meisten wollen auch etwas mit nach Hause nehmen, deshalb helfe ich bei der Herstellung der magischen Schmuckstücke, die Besucher mit ihren Gewinnlosen kaufen können.|n|nDafür benötige ich ständig Wahrsagerstaub. Seht Euch auf dem Platz um, da gibt es jede Menge abgelegter Waffen. Diese Gegenstände kann jemand wie Ihr, der die Kunst des Verzauberns beherrscht, in Staub verwandeln. Würdet Ihr mir helfen?', },
    {'Sammelt 6 Wahrsagerstaub, indem Ihr die abgelegten Waffen, die auf dem Platz des Dunkelmond-Jahrmarkts liegen, entzaubert.', },
  },
  [29475] = {
    'Gobliningenieurskunst',
    {'Ein geübter Ingenieur kann sich für EINE Spezialisierung entscheiden. Ich kenne die Geheimnisse der Gobliningenieurskunst.|n|nIhr seht aus, als würdet Ihr gern Dinge in die Luft jagen, aber ich benötige Proben Eurer Arbeit. Bringt mir zwanzig große Eisenbomben, zwanzig Stangen robustes Dynamit und fünf explodierende Schafe.|n|nWenn Ihr diese Gegenstände zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt bringt, wird er Euch offiziell zum Gobliningenieur mit Zugang zu allen Bauplänen ernennen!', },
    {'Bringt 20 große Eisenbomben, 20 Stangen robustes Dynamit und 5 explodierende Schafe zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt.', },
  },
  [29476] = {
    'Gnomeningenieurskunst',
    {'Wenn Ihr bereit seid, ein paar RICHTIG tolle Dinge herzustellen, dann seid Ihr hier am richtigen Ort. Ich kann sehen, dass Ihr ein fähiger Ingenieur seid, doch möchte ich trotzdem ein paar Proben Eurer Arbeit. Was ich mir davon erhoffe, ist, Euer Können auf Wege zu analysieren die gnomenorientierten Techniken in Zukunft noch zu unterstreichen. Ich bräuchte die folgenden Proben: sechs Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen.|n|nBringt mir diese Gegenstände und Ihr seid ein offizieller Gnomeningenieur mit Zugriff auf alle Baupläne!', },
    {'Bringt 6 Mithrilrohre, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Glotz Widrikus in Beutebucht.', },
  },
  [29477] = {
    'Gnomeningenieurskunst',
    {'Ein geübter Ingenieur kann sich für EINE Spezialisierung entscheiden. Ich kann Euch die Gnomeningenieurskunst beibringen.|n|nIhr scheint zwar zu wissen, was Ihr tut, aber ich benötige einige Proben Eurer Arbeit. Bringt mir sechs Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen.|n|nSobald Ihr diese Gegenstände bei einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt abgebt, seid Ihr offiziell ein Gnomeningenieur und erhaltet Zugriff auf alle Baupläne!', },
    {'Bringt 6 Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt.', },
  },
  [29478] = {
    'Eine prickelnde Mischung',
    {'Als $GAlchemist:Alchemistin; habt Ihr sicherlich schon zahlreiche Tränke gebraut. Würdet Ihr mir vielleicht bei etwas weniger Gehaltvollem helfen?|n|nIch wollte immer schon eine fruchtige Variante unserer beliebten Prickelgetränke kreieren. Wenn Ihr Euch daran versuchen wollt, würde ich Euch das Basisgetränk verkaufen. Anschließend mischt Ihr es mit etwas Mondbeerensaft.|n|nGalissa Sonnentau wird Euch genügend Saft für Eure Kreation verkaufen können.', },
    {'Mischt mit Hilfe des Cocktail-Shakers aus Mondbeerensaft und prickelndem Marktgetränk 5 Krüge Mondbeerenfizz.', },
  },
  [29479] = {
    'Heilkräuter',
    {'Die kleinen purpurnen Blumen, die überall auf dem Platz wild wachsen, sind mehr als nur hübsch.|n|nMit ihnen kann man Wunden behandeln und Essen würzen.|n|nIhr scheint ein Talent zum Kräutersammeln zu besitzen. Würdet Ihr mir dabei helfen, meinen Vorrat an Dunkelblüten aufzustocken?', },
    {'Sammelt 6 Dunkelblüten auf dem Lagerplatz des Dunkelmond-Jahrmarkts.', },
  },
  [29480] = {
    'Banner, überall Banner!',
    {'Ist es nicht wundervoll, dass überall Banner des Dunkelmond-Jahrmarkts wehen? Das genieße ich am meisten beim Aufbau, aber viele sind mittlerweile alt und zerschlissen und müssten ersetzt werden.|n|nNehmt Nadel und Faden, wenn Ihr damit umgehen könnt, und stellt ein Banner aus diesem Set her. Steckt es dann in einige lose Steine auf der zentralen Anhöhe von Donnerfels.|n|nDie Gegenstände, die Ihr sonst noch benötigt, könnt Ihr bei Shadi Nebelläufer auf der zentralen Anhöhe von Donnerfels erwerben.', },
    {'Stellt mit Hilfe des Bannersets des Dunkelmond-Jahrmarkts ein Banner des Dunkelmond-Jahrmarkts her. Steckt es in einen Haufen loser Steine auf der zentralen Anhöhe von Donnerfels.', },
  },
  [29481] = {
    'Meister der Elixiere',
    {'Bei Elixieren geht es nur um Stärke! Ich kann Euch zum Meister der Elixiere ausbilden, wenn Ihr das wünscht.|n|nDas ist nichts für jeden und ich verlange einen Beweis für Eure Ernsthaftigkeit, bevor wir fortfahren können. Mit einigen Fläschchen könnt Ihr mir Eure Entschlossenheit zeigen.|n|nVergesst nicht, $N, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Elixierbeherrschung abgeschlossen habt, werden Euch Tränke und Transmutation nicht mehr angeboten.', },
    {'Bringt eine Reihe verschiedener Fläschchen zu einem Alchemielehrer.', },
  },
  [29482] = {
    'Meister der Transmutation',
    nil,
    {'Bringt die verlangten Materialien zu einem Alchemielehrer in einer beliebigen Hauptstadt.', },
  },
  [29483] = {
    'Jahrmarkt der Eitelkeiten',
    {'Die Künstler und Tiere des Dunkelmond-Jahrmarkts benötigen mehr Schmuck, als ich mir je hätte erträumen lassen. Zum Glück bestehen die Edelsteine nur aus geschliffenem Glas. Aber auch die muss jemand herstellen.|n|nSeid Ihr geübt in Juwelierskunst und würdet uns helfen, einige glitzernde Glasedelsteine für unsere Künstler herzustellen?|n|nManchmal kann man die erstaunlichsten Scherben auf dem Platz finden. Wenn die von jemandem mit einem Händchen für Juwelierskunst bearbeitet werden, entstehen daraus wunderschöne Edelsteine.', },
    {'Sucht nach Glasscherben auf dem Platz des Dunkelmond-Jahrmarkts und schleift daraus 5 funkelnde "Edelsteine".', },
  },
  [29484] = {
    'Wie der Frosch knusprig wird',
    {'Die Knusperfrösche des Dunkelmond-Jahrmarkts sind in ganz Azeroth berühmt!|n|nWir haben gerade frische Frösche bekommen. Warum helft Ihr uns nicht bei der Zubereitung und tut gleichzeitig etwas für Eure Kochkunst?|n|nBei Shadi Nebelläufer auf der zentralen Anhöhe von Donnerfels könnt Ihr Mehl kaufen. Darin wälzt Ihr die Frösche, dann kocht Ihr sie in dem Topf hinter mir.', },
    {'Bereitet 5 Knusperfrösche zu, indem Ihr Eure fetten Frösche in herkömmlichem Mehl wälzt und in dem Kessel hinter Stampf Donnerhorn bratet.', },
  },
  [29485] = {
    'Spaß für die Kleinen',
    {'Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.|n|nIch vergrabe Artefakte und Fossilien im Sand hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.|n|nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?', },
    {'Bringt 15 Fossilienfragmente zu Professor Thaddeus Paleo beim Dunkelmond-Jahrmarkt.', },
  },
  [29506] = {
    'Eine prickelnde Mischung',
    {'Als $GAlchemist:Alchemistin; habt Ihr sicherlich schon zahlreiche Tränke gebraut. Würdet Ihr mir vielleicht bei etwas weniger Gehaltvollem helfen?|n|nIch wollte immer schon eine fruchtige Variante unserer beliebten Prickelgetränke kreieren. Wenn Ihr Euch daran versuchen wollt, würde ich Euch das Basisgetränk verkaufen. Anschließend mischt Ihr es mit etwas Mondbeerensaft.|n|nEin Gastwirt im Wald von Elwynn oder in Mulgore wird Euch genügend Saft für Eure Kreation verkaufen können.', },
    {'Mischt mit Hilfe des Cocktail-Shakers aus Mondbeerensaft und prickelndem Marktgetränk 5 Krüge Mondbeerenfizz.', },
  },
  [29507] = {
    'Spaß für die Kleinen',
    {'Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.|n|nIch vergrabe Artefakte und Fossilien im Sandkasten hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.|n|nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?', },
    {'Bringt 15 mit Archäologie aufgespürte Fossilienfragmente zu Professor Thaddeus Paleo beim Dunkelmond-Jahrmarkt.', },
  },
  [29508] = {
    'Baby braucht zwei Paar Schuhe',
    {'Habt Ihr meine Stute Baby da hinten neben den Wagen gesehen? Sie zieht den Karren mit allen Tieren unseres Kuriositätenkabinetts.|n|nSie arbeitet hart und braucht mehr Hufeisen, als Ihr Euch vorstellen könnt. Es ist wieder einmal Zeit für neue. Die Rohmaterialien habe ich bereits gekauft.|n|nIhr müsst sie nur auf einem Amboss bearbeiten und Baby anlegen. Geht schnell und ist mir ein paar Lose wert, also was meint Ihr?', },
    {'Stellt aus den Eisenbeständen 4 Hufeisen her und legt sie Baby auf dem Dunkelmond-Jahrmarkt an.', },
  },
  [29509] = {
    'Wie der Frosch knusprig wird',
    {'Die Knusperfrösche des Dunkelmond-Jahrmarkts sind in ganz Azeroth berühmt!|n|nWir haben gerade frische Frösche bekommen. Warum helft Ihr uns nicht bei der Zubereitung und tut gleichzeitig etwas für Eure Kochkunst?|n|nDas Mehl, in dem Ihr die Frösche wälzen müsst, bekommt Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore.', },
    {'Bereitet 5 Knusperfrösche zu, indem Ihr Eure fetten Frösche in herkömmlichem Mehl wälzt und in dem Kessel hinter Stampf Donnerhorn bratet.', },
  },
  [29510] = {
    'Auch Abfall kann nützlich sein',
    {'Die Leute kommen nicht nur zum Spaß auf den Jahrmarkt, $N. Die meisten wollen auch etwas mit nach Hause nehmen, deshalb helfe ich bei der Herstellung der magischen Schmuckstücke, die Besucher mit ihren Gewinnlosen kaufen können.|n|nDafür benötige ich ständig Wahrsagerstaub. Seht Euch auf dem Platz um, da gibt es jede Menge abgelegter Waffen. Diese Gegenstände kann jemand wie Ihr, der die Kunst des Verzauberns beherrscht, in Staub verwandeln. Würdet Ihr mir helfen?', },
    {'Sammelt 6 Wahrsagerstaub, indem Ihr die abgelegten Waffen, die auf dem Platz des Dunkelmond-Jahrmarkts liegen, entzaubert.', },
  },
  [29511] = {
    'Panzerreparatur',
    {'Die Dunkelmonddampfpanzer gehören zu unseren beliebtesten Attraktionen. Unsere Besucher testen ihr Können stundenlang, aber bei all dem Spaß werden die Panzer stark beansprucht.|n|nIhr scheint zu wissen, wie man mit einem Schraubenschlüssel umgeht. Würdet Ihr mir bei der Reparatur der beschädigten Panzer helfen? Ich würde Euch für Euren Zeitaufwand entschädigen.', },
    {'Repariert 5 beschädigte Dampfpanzer auf dem Gelände des Dunkelmond-Jahrmarkts.', },
  },
  [29512] = {
    'Kratzer, Beulen, blaue Flecke',
    {'Die Arbeit auf dem Dunkelmond-Jahrmarkt ist gefährlich, $N. Unsere Arbeiter verletzen sich oft beim Aufbau, Abbau und Transport der Attraktionen.|n|nEinige der verletzten Arbeiter findet Ihr in der Nähe der Wagen. Andere wollen sich im Heilzelt behandeln lassen. Warum nehmt Ihr nicht diese Bandagen und seht, ob Ihr den verletzten Arbeitern helfen könnt?', },
    {'Nehmt die Bandagen des Dunkelmond-Jahrmarkts und heilt damit 4 verletzte Schausteller.', },
  },
  [29513] = {
    'Leckerer Fisch im Schlafrock',
    {'Wir haben gerade ein neues Gericht in unsere Speisekarte aufgenommen, den Fisch im Schlafrock. Es ist so beliebt, dass wir die Nachfrage kaum erfüllen können!|n|nIhr seht aus, als wüsstet Ihr, wie man mit einer Angel umgeht, <Volk>. Würdet Ihr mir bei der Aufstockung meiner Vorräte helfen?|n|nWir wollen doch all die Jahrmarktsbesucher, die etwas Neues ausprobieren wollen, nicht enttäuschen, oder?', },
    {'Fangt 5 große Meeresheringe im Ozean rund um die Dunkelmond-Insel.', },
  },
  [29514] = {
    'Heilkräuter',
    {'Die kleinen purpurnen Blumen, die überall auf dem Platz wild wachsen, sind mehr als nur hübsch.|n|nMit ihnen kann man Wunden behandeln und Essen würzen.|n|nIhr scheint ein Talent zum Kräutersammeln zu besitzen. Würdet Ihr mir dabei helfen, meinen Vorrat an Dunkelblüten aufzustocken?', },
    {'Sammelt 6 Dunkelblüten auf dem Lagerplatz des Dunkelmond-Jahrmarkts.', },
  },
  [29515] = {
    'Ein Blick in die Zukunft',
    {'Die Beliebtheit des Dunkelmond-Jahrmarkts nimmt zu. Immer mehr Leute suchen mich auf, um einen Blick in ihre Zukunft zu werfen.|n|nHäufig bitten sie um Wissen, das besser im Nebel der Zeit verborgen bleiben sollte, aber solche Ratschläge stehen mir nicht zu.|n|nMein Vorrat an geschriebenen Horoskopen neigt sich dem Ende zu und Ihr scheint eine sichere Hand zu haben. Stellt Tinte aus diesen Kräutern her und schreibt einige Horoskope für mich. Das Pergament, das Ihr dafür braucht, könnt Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben.', },
    {'Stellt aus dem Bund exotischer Kräuter prophetische Tinte her. Verbindet die Tinte mit leichtem Pergament, um Sayges Horoskope zu schreiben.', },
  },
  [29516] = {
    'Jahrmarkt der Eitelkeiten',
    {'Die Künstler und Tiere des Dunkelmond-Jahrmarkts benötigen mehr Schmuck, als ich mir je hätte erträumen lassen. Zum Glück bestehen die Edelsteine nur aus geschliffenem Glas. Aber auch die muss jemand herstellen.|n|nSeid Ihr geübt in Juwelierskunst und würdet uns helfen, einige glitzernde Glasedelsteine für unsere Künstler herzustellen?|n|nManchmal kann man die erstaunlichsten Scherben auf dem Platz finden. Wenn die von jemandem mit einem Händchen für Juwelierskunst bearbeitet werden, entstehen daraus wunderschöne Edelsteine.', },
    {'Sucht nach Glasscherben auf dem Platz des Dunkelmond-Jahrmarkts und schleift daraus 5 funkelnde "Edelsteine".', },
  },
  [29517] = {
    'Begehrte Preise',
    {'Die Spiele werden immer beliebter, was bedeutet, dass wir mehr Preise ausgeben als je zuvor.|n|nWir brauchen dringend neue Preise. Wenn Ihr geübt in der Lederverarbeitung seid, würde ich Euch gern ein Set geben. Ihr werdet einige Teile bei einem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben müssen, aber sie sind nicht teuer.|n|nWollt Ihr mir helfen?', },
    {'Stellt mit Hilfe des Handwerkersets des Dunkelmond-Jahrmarkts 5 Gewinne des Dunkelmond-Jahrmarkts her. Dazu benötigt Ihr groben Faden, glänzende Schmuckstücke und blauen Farbstoff.', },
  },
  [29518] = {
    'Wiederbewaffnung, Wiederverwendung, Wiederverwertung',
    {'Die Jahrmarktsbesucher lieben unsere Dampfpanzer! Wenn der Dunkelmond-Jahrmarkt schließt, liegt all der Panzerschrott auf dem Platz herum.|n|nWäre doch schade, wenn das gute Metall einfach im Dreck verrotten würde.|n|nWäret Ihr so nett, mir einige der größeren Stücke zu bringen, damit ich die kaputten Panzerteile damit reparieren kann? Das ist weitaus billiger als jedes Mal neues Metall zu kaufen. Was meint Ihr?', },
    {'Beschafft 6 Stücke Panzerschrott vom Lagerplatz des Dunkelmond-Jahrmarkts.', },
  },
  [29519] = {
    'Gerbt meine Häute',
    {'Auf dem Dunkelmond-Jahrmarkt wird ständig Leder für Zelte, Stiefel und alles, was Ihr Euch vorstellen könnt, benötigt. Ich habe einige Kreaturen gefangen und ihre Häute aufgespannt.|n|nIhr scheint Euch mit Häuten auszukennen. Ich würde Euch belohnen, wenn Ihr mir beim Abschaben der neuen Häute helfen könntet.', },
    {'Schabt 4 aufgespannte Häute auf dem Lagerplatz des Dunkelmond-Jahrmarkts ab.', },
  },
  [29520] = {
    'Banner, überall Banner!',
    {'Ist es nicht wundervoll, dass überall Banner des Dunkelmond-Jahrmarkts wehen? Das genieße ich am meisten beim Aufbau, aber viele sind mittlerweile alt und zerschlissen und müssten ersetzt werden.|n|nNehmt Nadel und Faden, wenn Ihr damit umgehen könnt, und stellt ein Banner aus diesem Set her. Steckt es dann in einige lose Steine auf dem Lagerplatz des Jahrmarkts.|n|nEs fehlen noch einige Teile, doch die solltet Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben können.', },
    {'Stellt mit einem groben Faden sowie rotem und blauem Farbstoff zusammen mit dem Bannersets des Dunkelmond-Jahrmarkts ein Banner des Dunkelmond-Jahrmarkts her. Steckt es in einen Haufen loser Steine auf dem Lagerplatz des Jahrmarkts.', },
  },
  [29527] = {
    'Krieg im Bollwerk',
    {'Wachhabender Gargolmar und Vazruden der Herold haben das Kommando über die Verteidigung des Bollwerks.|n|nWenn Ihr sie ausschaltet, werden die Soldaten in Panik geraten.|n|nTötet sie und bringt mir einen Beweis für Eure Tat, damit die Invasion beginnen kann!', },
    {'Tötet Wachhabenden Gargolmar, Vazruden den Herold und Vazrudens Drachen Nazan. Bringt Gargolmars Hand und Nazans Kopf zu Steingardist Stok\'ton.', },
  },
  [29528] = {
    'Krieg im Bollwerk',
    {'Die Verteidigung der Höllenfeuerzitadelle hängt in erster Linie vom Bollwerk ab, das als eine Art Frühwarnsystem dient.|n|nBeseitigt Wachhabenden Gargolmar und Vazruden den Herold. Ohne sie wird die Eroberung des Bollwerks ein Kinderspiel sein.', },
    {'Tötet Wachhabenden Gargolmar, Vazruden den Herold und Vazrudens Drachen Nazan. Bringt Gargolmars Hand und Nazans Kopf zu Vorhutsspäher Chadwick.', },
  },
  [29529] = {
    'Dämonen in der Zitadelle',
    {'Einer unserer Späher berichtet, er habe irgendwo im Bollwerk einen Agenten der Brennenden Legion gesehen. Wenn das stimmt, laufen wir Gefahr, dass die Ehrenfeste von zwei Seiten angegriffen wird!|n|nWenn Ihr diesen Teufel findet, dann bringt ihn um.', },
    {'Tötet Omor den Narbenlosen und bringt seinen Huf zu Vorhutsspäher Chadwick.', },
  },
  [29530] = {
    'Dämonen in der Zitadelle',
    {'Einer unserer Späher hat unangenehme Neuigkeiten überbracht. Wir haben einen mächtigen Agenten der Brennenden Legion im Bollwerk entdeckt!|n|nBringt diesen Dämon um, bevor er seinen Vorgesetzten von unseren Plänen berichten kann.', },
    {'Tötet Omor den Narbenlosen und bringt seinen Huf zu Steingardist Stok\'ton.', },
  },
  [29532] = {
    'Düstere Neuigkeiten',
    {'Als Ihr die Leiche von Vazruden dem Herold untersucht, entdeckt Ihr einen Brief, dessen Siegel ungebrochen ist. Ein reich verziertes "I" ist in dem blutroten Wachs zu sehen. Ihr öffnet das Siegel und lest die verstörende Nachricht.|n|nVorhutsspäher Chadwick wird sie sich bestimmt ansehen wollen!', },
    {'Bringt den unheilvollen Brief zu Vorhutsspäher Chadwick.', },
  },
  [29533] = {
    'Düstere Neuigkeiten',
    {'Als Ihr die Leiche von Vazruden dem Herold untersucht, entdeckt Ihr einen Brief, dessen Siegel ungebrochen ist. Ein reich verziertes "I" ist in dem blutroten Wachs zu sehen. Ihr öffnet das Siegel und lest die verstörende Nachricht.|n|nSteingardist Stok\'ton wird sie sich bestimmt ansehen wollen!', },
    {'Bringt den unheilvollen Brief zu Steingardist Stok\'ton.', },
  },
  [29535] = {
    'Lasst sie bluten!',
    {'Der Schöpfer erzeugt neue Höllenorcs, indem er ihnen Dämonenblut injiziert.|n|nMeine Vorgesetzten glauben, dass sich der Prozess rückgängig machen lässt, aber um das auszuprobieren, benötigen wir Proben ihres Blutes und die Injektionsspritze des Schöpfers.', },
    {'Beschafft 10 Phiolen mit Höllenorcblut und eine Teufelsinjektionsspritze für Caza\'rez.', },
  },
  [29536] = {
    'Im Herzen des Hasses',
    {'Wir wissen, dass die Höllenorcs ihren Fokus erhöhen, indem sie Orcs Dämonenblut injizieren.|n|nBegebt Euch tief in diese unheiligen Hallen und findet heraus, was dort geschieht. Wir können es erst riskieren, eine Armee hineinzuschicken, wenn wir genau wissen, was uns erwartet.', },
    {'Untersucht den Blutkessel vollständig und meldet Euch wieder bei Caza\'rez.', },
  },
  [29537] = {
    'Vorsicht, Lücke!',
    {'Im ganzen Blutkessel gibt es nur ein Gebiet, das unsere Seher trotz aller Mühen nicht erreichen können.|n|nDiese "Lücke", wie sie es nennen, ist recht groß. Dort wird bestimmt Magtheridon gefangen gehalten.|n|nIhr müsst die Ursache dieser Störungen finden und vernichten.', },
    {'Tötet Keli\'dan den Zerstörer und kehrt zu Caza\'rez zurück.', },
  },
  [29538] = {
    'Lasst sie bluten!',
    {'Mit Dämonenblut und einer speziellen Spritze verwandelt der Schöpfer braune und grüne Orcs in rote. Wir würden uns das Blut gern ansehen und damit herumspielen, bis es Orcs aller Farben in harmlose, friedliche Ochsen verwandelt.|n|nBringt mir einige Proben ihres Blutes, damit wir anfangen können. Und vergesst die Spritze nicht!', },
    {'Beschafft 10 Phiolen mit Höllenorcblut und eine Teufelsinjektionsspritze für Gunny.', },
  },
  [29539] = {
    'Im Herzen des Hasses',
    {'Hat sich gezeigt, dass die Eierköpfe in der Ehrenfeste nicht viel von diesem Ort hier sehen können. Lügende, faule Magier sind das, nichts weiter.|n|nWie dem auch sei, wir wissen nicht genau, was hier vorgeht. Also werdet Ihr das herausfinden!', },
    {'Untersucht den Blutkessel vollständig und meldet Euch wieder bei Gunny.', },
  },
  [29540] = {
    'Der Zerstörer',
    {'Die verstecken hier irgendwo so einen großen, alten Dämon, hab ich gehört. Und da gibt\'s auch einen Orc, der darauf achten soll, dass er bleibt, wo er hingehört.|n|nEin Orc ist ein Orc, und Orcs werden umgebracht, richtig? Ist egal, was er tut oder getan hat, einer weniger schadet nie.', },
    {'Tötet Keli\'dan den Zerstörer und kehrt zu Gunny zurück.', },
  },
  [29542] = {
    'Die Eroberung der Zitadelle',
    nil,
    {'Sprecht mit Steingardist Stok\'ton im Höllenfeuerbollwerk.', },
  },
  [29543] = {
    'Die Eroberung der Zitadelle',
    {'Die Legion steht auf der einen, die Höllenorcs auf der anderen Seite. Sie werden die Ehrenfeste in Kürze überrennen, wenn wir nichts unternehmen.|n|nMacht Euch auf nach Westen zum Höllenfeuerbollwerk und sprecht dort mit Vorhutsspäher Chadwick. Die Mission, die er leitet, wird der Allianz den Weg in die Zitadelle ebnen.', },
    {'Sprecht mit Vorhutsspäher Chadwick im Höllenfeuerbollwerk.', },
  },
  [29544] = {
    'Der Blutkessel',
    {'Caza\'rez erwartet Euch im Blutkessel. Er hat bereits einen kleinen Bereich gesäubert und unsere Seher versuchen gerade herauszufinden, was dort unten vorgeht.|n|nIch befürchte jedoch, dass das nicht reichen wird. Caza\'rez könnte ein oder zwei robuste Klingen sicherlich gut gebrauchen. Geht zu ihm und unterstützt ihn bei der Beseitigung der Höllenorcs.', },
    {'Sprecht mit Caza\'rez im Blutkessel.', },
  },
  [29545] = {
    'Der Blutkessel',
    {'Dieser Krieg ist längst noch nicht vorbei. Wir müssen dafür sorgen, dass die Front der Höllenorcs nicht mehr durch neue Rekruten verstärkt wird. Nur dann können wir siegen.|n|nBegebt Euch in den Blutkessel und sprecht mit Gunny. Er hat einen kleinen Bereich darin gesichert und könnte bestimmt Eure Hilfe gebrauchen. Aber seid gewarnt. Gunny ist... ungewöhnlich.', },
    {'Sprecht mit Gunny im Blutkessel.', },
  },
  [29563] = {
    'Bei der Arbeit verschollen',
    {'Ihr müsst mir helfen! Wir wurden ausgesandt, um die verschiedenen Bereiche des Kessels zu erkunden, aber das war vor einiger Zeit und meine Freunde sind noch nicht zurückgekehrt.|n|nBitte findet heraus, ob ihnen etwas zugestoßen ist. Naturalist Biss und Jäter Gründaum sind in diese Richtung gegangen.', },
    {'Findet heraus, was Naturalist Biss und Jäter Gründaum zugestoßen ist. Kehrt dann zu Behüterin Jhang zurück.', },
  },
  [29564] = {
    'Der betrogene Bruder',
    {'Anfangs gelang es meinem Dorf, den Angriffen der Naga auszuweichen. Wir hätten es bis nach Nagrand geschafft, wenn mein Bruder nicht gewesen wäre. Mit unseren Seelen erkaufte er sich seine Freiheit.|n|nNun arbeitet er hier als Sklavenaufseher und peitscht seine eigenen Brüder aus, bis ihre Rücken bluten. Dafür muss Mennu bezahlen, <Volk>.', },
    {'Tötet Mennu den Verräter und kehrt zu Nahuud zurück.', },
  },
  [29565] = {
    'Eine Herzensangelegenheit',
    {'Nahuud hat mir erklärt, zwei mächtige Wesen, Rokmar der Zerquetscher und Quagmirran, seien als erste von den Naga nach deren Ankunft versklavt worden. Sie haben bei der Unterwerfung vieler Völker in den Zangarmarschen geholfen.|n|nIch tue das sehr ungern, aber ich muss Euch bitten, sie zu töten.', },
    {'Bringt die Klaue des Eindringlings und das Auge des Sklaventreibers zu Behüterin Jhang.', },
  },
  [29566] = {
    'Die verlorene Expedition',
    {'Die Sümpfe sind wunderschön, findet Ihr nicht? Abgesehen natürlich von den Naga, die das Wasser abpumpen.|n|nIch habe eine kleine Expedition zum Echsenkessel geschickt. Sie sollte die Naga beobachten, aber bis jetzt ist niemand zurückgekehrt. Ich mache mir Sorgen um sie.|n|nWürdet Ihr Euch zu den Sklavenunterkünften unterhalb des Schlangensees begeben und nach Behüterin Jhang suchen?', },
    {'Sprecht mit Behüterin Jhang in den Sklavenunterkünften.', },
  },
  [29567] = {
    'Tötet die Mutter',
    {'Die Fungusgiganten greifen zwar heutzutage mein Volk an, aber die Marschenläufer haben bereits mehr Unschuldige auf dem Gewissen als alle anderen Kreaturen, die ich kenne. Sie sind seit Urzeiten unser Feind.|n|nIhre Brutmutter, die man auch Schattenmutter nennt, lebt in den Tiefen dieses Sumpfes. Wenn es Euch gelingen sollte, sie zu vernichten und mir ihr Gehirn als Beweis zu bringen, würde ich noch meinen Enkeln von Eurer ruhmreichen Tat erzählen.', },
    {'Bringt das Gehirn der Schattenmutter zu T\'shu.', },
  },
  [29568] = {
    'Ein notwendiges Übel',
    {'Hungarfenn und Quagmirran herrschten einst gemeinsam über die Fungusgiganten. Seit Quagmirrans Tod lastet diese Verantwortung allein auf Hungarfenns Ranken.|n|nWir müssen den Riesen töten, bevor er versklavt und als Waffe gegen uns eingesetzt werden kann.', },
    {'Tötet Hungarfenn und kehrt zu Naturalist Biss zurück.', },
  },
  [29569] = {
    'Kriegsherr Kalithreshs wichtigster Besitz',
    {'Kriegsherr Kalithresh benutzt den Tiefensumpf als eine Art Brutkammer für Gha\'zan, eine mächtige Hydra, die er auf die Zangarmarschen loslassen will, sobald sie ausgewachsen ist.|n|nIch befürchte, dass sich die Naga nicht mehr aufhalten lassen werden, wenn die Bestie ihre endgültige Größe erreicht hat. Findet Gha\'zan und tötet sie zu unserem Schutz.', },
    {'Tötet Gha\'zan und bringt ihre Schuppe zu Behüterin Jhang.', },
  },
  [29570] = {
    'Die Rettung der Expedition',
    {'Die restlichen Mitglieder meiner Expedition sind irgendwo hier drinnen. Wir brauchen das Wissen, das sie erlangt haben, und die Fähigkeiten, die sie besitzen, sonst werden wir die Naga niemals schlagen.|n|nSucht nach Erdbinder Rayge und Windrufer Klaue und stellt sicher, dass es ihnen gut geht.', },
    {'Findet heraus, was mit Erdbinder Rayge und Windrufer Klaue geschehen ist. Kehrt dann zu Behüterin Jhang zurück.', },
  },
  [29571] = {
    'Verteidigung der Wildnis',
    {'Der Irdene Ring arbeitet oft eng mit dem Zirkel des Cenarius zusammen. So ist es auch dieses Mal.|n|nReist nach Norden zum Tiefensumpf und sprecht mit Behüterin Jhang. Sie leitet eine Expedition in den Echsenkessel, um die Naga aufzuhalten und die Zangarmarschen zu retten.', },
    {'Sprecht mit Behüterin Jhang im Tiefensumpf.', },
  },
  [29572] = {
    'Sicherheit geht vor',
    {'Shaffars Astrale haben uns ganz aus der Managruft ausgeschlossen. Zum Glück habe ich einen Plan. Auch wenn wir nicht durch die Eingangstür können, bin ich mir sicher, dass es innen viele Transporter gibt.|n|nIch möchte, dass Ihr zuerst den Weg für meine Gruppe freiräumt und dann einen der Transporter aktiviert, damit wir hineinteleportieren können.|n|nAktiviert den Transporter in der Kammer genau vor Shaffars Kammern, wenn Ihr den Weg freigemacht habt. Keine Sorge, ich werde Euch dafür entlohnen...', },
    {'Konstrukteur Morphalius möchte, dass Ihr 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder tötet.|n|nWenn Ihr damit fertig seid, sucht den astralen Transporter in der Kammer vor Shaffars Kammer und aktiviert ihn.', },
  },
  [29573] = {
    'Sicherheit geht vor',
    nil,
    nil,
  },
  [29574] = {
    'Rätselhafte Wesen',
    {'Nahe des Eingangs dieser Hallen gibt es eine Kreatur, die Pandemonius genannt wird. Sie ist in der Lage, die Energien der Leere so zu verändern, dass sie sich daraus versorgen und stärken kann.|n|nWeiter hinten liegt Tavarok, ein Wesen, das die gleiche Energie in eine kristalline Struktur umwandelt, die stärker ist als alles, was ich je gesehen habe!|n|nIch brauche dringend Proben für weitere Untersuchungen.', },
    {'Bringt Pandemonius\' Essenz und Tavaroks Herz zu Mamdy dem Ologen.', },
  },
  [29575] = {
    'Die Konkurrenz untergraben',
    {'Dank der Barriere, die Nexusprinz Shaffar errichtet und der Truppen, die er aufgestellt hat, kann er diese Gruft in aller Seelenruhe ausplündern.|n|nNexusprinz Haramad ist darüber nicht gerade begeistert. Deshalb hat er einen sehr ansehnlichen Preis auf Shaffars Kopf ausgesetzt.', },
    {'Bringt Shaffars Bandagen zu Konstrukteur Morphalius.', },
  },
  [29582] = {
    'Greks verrückte Nacht',
    {'Grek hatte gestern ziemlich üble Nacht.|n|nGlänzender Mumienmann kam in Greks Haus und sagte, Grek solle zu Managruft in Auchindoun gehen. Aber Grek versuchte noch Steckbrief zu lesen!|n|n<Greks Augen beginnen zu leuchten.>|n|nGrek weiß! Ihr gehen zu glänzendem Mumienmann und sagt ihm, Grek schickt Euch. Perfekter Plan!', },
    {'Sprecht mit Konstrukteur Morphalius in der Managruft in Auchindoun.', },
  },
  [29583] = {
    'Eckert der Verrückte',
    nil,
    {'Sprecht mit Konstrukteur Morphalius in der Managruft in Auchindoun.', },
  },
  [29590] = {
    'Der Totenwächter',
    {'Ein schreckliches, überirdisches Wesen sucht die Welt der Geister und die der Lebenden heim. Wir nennen es Shirrak.|n|nEs kann nur in Eurem Reich verletzt werden. Bitte helft uns, diesen Alptraum zu beenden.', },
    {'Tötet Shirrak den Totenwächter und kehrt zu dem Draeneigeist zurück.', },
  },
  [29591] = {
    'Wütende Geister',
    {'Die Auchenai haben all unseren Werten den Rücken gekehrt. Sie erwecken die Toten und halten sie als ihre unheiligen Diener!|n|nDas muss ein Ende haben. Bringt diesen Geistern den Frieden und tötet alle, die sie zu Untoten gemacht haben.', },
    {'Tötet 5 erboste Skelette, 5 tobende Skelette und 3 Totenbeschwörer der Auchenai. Kehrt dann zur gequälten Seelenpriesterin in der Auchenaikrypta zurück.', },
  },
  [29593] = {
    'Trefft sie, wo es schmerzt',
    {'Die Höllenorcs lagern eine Menge Vorräte hier.|n|nEs würde ihren Feldzug empfindlich treffen und unserem deutlich helfen, wenn sie gestohlen würden. Traut Ihr Euch das zu, $C?', },
    {'Stehlt 3 Stapel Vorräte der Höllenfeuerhalbinsel und kehrt zu Steingardist Stok\'ton im Höllenfeuerbollwerk zurück.', },
  },
  [29594] = {
    'Trefft sie, wo es schmerzt',
    {'Die Höllenorcs lagern eine Menge Vorräte hier.|n|nEs würde ihren Feldzug empfindlich treffen und unserem deutlich helfen, wenn sie gestohlen würden. Traut Ihr Euch das zu, $C?', },
    {'Stehlt 3 Stapel Vorräte der Höllenfeuerhalbinsel und kehrt zu Vorhutsspäher Chadwick im Höllenfeuerbollwerk zurück.', },
  },
  [29595] = {
    'Alles wird gut',
    {'Da habt Ihr ja ein ziemliches Abenteuer hinter Euch, $N. Dabei habt Ihr die Auchenaikrypta noch nicht einmal betreten.|n|nIch bin einer der glücklichen Geister. Ich war nie an Levixus gebunden, noch war ich Teil von Exarch Maladaars verwerflichen Experimenten in der Nekromantie. Levixus habt Ihr bereits vernichtet, aber Maladaar quält weiter die Geister in der Krypta.|n|nIch habe eine simple Bitte an Euch. Betretet die Auchenaikrypta und sprecht mit dem Draeneigeist dort. Ihr müsst Exarch Maladaar vernichten.', },
    {'Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr Euch in die Auchenaikrypta begebt und mit dem Draeneigeist sprecht.', },
  },
  [29596] = {
    'Das Ende des Exarchen',
    {'Exarch Maladaar übt sein unheiliges Werk im tiefsten Teil der Krypta aus. Er stellt eine Bedrohung für unser beider Welten dar, wenn er nicht aufgehalten wird.|n|nTötet ihn zum Wohle aller, dem der Toten und der Lebenden.', },
    {'Tötet Exarch Maladaar und kehrt zu dem Draeneigeist in der Auchenaikrypta zurück.', },
  },
  [29597] = {
    'Das Ende des Exarchen',
    {'Exarch Maladaar übt sein unheiliges Werk im tiefsten Teil der Krypta aus. Er stellt eine Bedrohung für unser beider Welten dar, wenn er nicht aufgehalten wird.|n|nTötet ihn zum Wohle aller, dem der Toten und der Lebenden.', },
    {'Tötet Exarch Maladaar und kehrt zu dem Draeneigeist in der Auchenaikrypta zurück.', },
  },
  [29598] = {
    'Tarethas Ablenkungsmanöver',
    {'Taretha war es, die ursprünglich für das Ablenkungsmanöver in Durnholde sorgte und Thrall die Flucht ermöglichte.|n|nNun haben die Ewigen Taretha gefangen genommen. Wenn wir nicht eingreifen, wird es kein Ablenkungsmanöver geben. Nehmt die Brandsätze, die ich Euch gegeben habe, und brennt die Internierungsbaracken nieder.', },
    {'Reist zur Burg Durnholde und platziert mithilfe des Bündels mit Brandbomben, das Ihr von Erozion erhalten habt, 5 Brandsätze auf den Fässern in jeder Internierungsbaracke.|n|nSprecht mit Thrall im Kellergefängnis der Burg Durnholde, wenn Ihr die Internierungsbaracken angezündet habt.', },
  },
  [29599] = {
    'Flucht aus Durnholde',
    {'Ich habe große Pläne für mein Volk, $GFremder:Fremde;.|n|nEines Tages wird es seine Unterdrücker stürzen und sich erheben. Es wird die Ketten sprengen, die es halten und dies wird die Geburtsstunde der orcischen Horde sein.|n|nWir fliehen, wenn Ihr bereit seid.', },
    {'Gebt Thrall Bescheid, wenn Ihr bereit seid. Folgt Thrall aus der Burg Durnholde und helft ihm, Taretha zu befreien und sein Schicksal zu erfüllen.|n|nSprecht mit Erozion im Alten Hügelland, wenn Ihr diese Aufgabe erfüllt habt.', },
  },
  [29601] = {
    'Naturführer des Dunkelmond-Jahrmarkts',
    {'Habt Ihr eine Ausgabe des Naturführers des Dunkelmond-Jahrmarkts, $Gmein Freund:meine Liebe;? Das ist ein wirklich nützliches Buch.|n|nMit seiner Hilfe könnt Ihr auf Euren Reisen durch Azeroth wertvolle Artefakte identifizieren. Die Beschreibungen sind so genau, dass Ihr leicht erkennen könnt, ob Ihr Euren fünfhundertsten Messingknopf gefunden habt oder einen seltenen Schatz, nach dem sich die Sammler des Dunkelmond-Jahrmarkts die Finger lecken würden.', },
    nil,
  },
  [29605] = {
    'Bruder gegen Bruder',
    {'Die Sethekk verließen Skettis, als Auchindoun explodierte.|n|nMein Bruder Syth gehörte zu ihren Anführern. Auf seinen Befehl suchten wir die Ruinen auf und stellten uns unserem Gott.|n|nNach kurzer Zeit warf mich Syth jedoch aus den Hallen, weil mir Zweifel an ihren Fähigkeiten kamen. Er erlaubte mir nicht, meine Schwester Lakka mitzunehmen. Werdet Ihr mir helfen, sie zu retten?', },
    {'Befreit Lakka aus ihrer Gefangenschaft. Kehrt zu Isfar in den Sethekkhallen zurück, wenn Ihr die Rettung abgeschlossen habt.', },
  },
  [29606] = {
    'Terokks Erbe',
    {'Terokk, der Held von Arakkoa, verschwand eines Tages plötzlich und ließ nur seine Maske und seinen Speer zurück.|n|nDunkelwirker Syth hat sie immer noch in seinem Besitz und Klauenkönig Ikiss wacht über seinen Speer.|n|nEs würde meinem Volk viel bedeuten, wenn wir die Gegenstände zurückbekommen würden.', },
    {'Bringt Terokks Maske und Terokks Federkiel zu Isfar in den Sethekkhallen.', },
  },
  [29607] = {
    'Augen der Begierde',
    {'Ich habe einen Kunden, der sich für die Augen der kobaltblauen Schlangen interessiert, die sich hier angesiedelt haben.|n|nWenn Ihr mir einige dieser seltenen Edelsteine besorgen könntet, würde ich den Profit mit Euch teilen.|n|nEinverstanden?', },
    {'Händler Vijaad in den Sethekkhallen möchte, dass Ihr ihm 3 Kobaltaugen bringt.', },
  },
  [29608] = {
    'Verbündete in Dalaran',
    {'Willkommen in Nordend, $N. Man hat mich gebeten, die Reise nach Dalaran für Euch zu arrangieren, damit Ihr dort unsere Verbündeten treffen könnt.|n|nReitet auf einem Greifen nach Dalaran und sucht nach der Landung unser Gasthaus Zum Gefeierten Helden auf. Sprecht dort mit Isirami Sanftwind.|n|nSie wird Euch dabei helfen, Euren Ruhestein an die Stadt zu binden. Mit dem Portal in der Silbernen Enklave könnt Ihr dann rasch nach Sturmwind zurückreisen.', },
    {'Macht einen Greifenritt nach Dalaran und sprecht mit Isirami Sanftwind im Gasthaus Zum Gefeierten Helden.', },
  },
  [29609] = {
    'Freunde in Dalaran',
    {'Willkommen in Nordend. Man hat mich gebeten, Eure Reise nach Dalaran zu arrangieren, damit Ihr unsere Freunde in der Stadt kennenlernen könnt.|n|nSprecht mit mir und nehmt einen Flug nach Dalaran an. Begebt Euch nach der Landung zum Gasthaus "Das Rattenloch".|n|nRedet dort mit Uda dem Biest.|n|nSie wird Euch dabei helfen, Euren Ruhestein an die Stadt zu binden. Dann könnt Ihr durch das Portal in Sonnenhäschers Zuflucht rasch nach Orgrimmar reisen.', },
    {'Lasst Euch vom Flugmeister einen Flug nach Dalaran geben und sprecht mit Uda dem Biest im Rattenloch.', },
  },
  [29613] = {
    'Ein gerechtes Schicksal',
    {'Kriegsherr Kalithresh leitet Operation Dampfkammer.|n|nEr muss sterben, $N. Die Naga lassen uns keine andere Wahl als Gewalt.|n|nZeigt ihm keine Gnade.', },
    {'Tötet Kriegsherr Kalithresh und kehrt zu Behüterin Jhang in der Dampfkammer zurück.', },
  },
  [29614] = {
    'Eindämmung ist der Schlüssel',
    {'Die Naga haben sich mit den Lepragnomen verbündet, um eine schreckliche Krankheit in den Zangarmarschen zu verbreiten. Man begegnet ihr schon überall in der Dampfkammer.|n|nVernichtet alles, das bereits befallen ist, und bringt mir das mittlere Zahnrad von Robogenieur Dampfhammer. Beeilt Euch!', },
    {'Tötet 3 Sumpfoberanführer und 6 Aussätzige des Echsenkessels und erbeutet ein verstrahltes Zahnrad von Robogenieur Dampfhammer. Kehrt dann zu Naturalist Biss in der Dampfkammer zurück.', },
  },
  [29615] = {
    'Windrufer Klaue und die Wasserdiebin',
    {'Die Naga versuchen schon seit längerem, das Wasser aus den Zangarmarschen abzupumpen. Die Dampfkammer ist der Dreh- und Angelpunkt dieser Operation. Überwacht wird sie von Hydromantin Thespia.|n|nIhr Tod würde die Naga empfindlich treffen.', },
    {'Tötet Hydromantin Thespia und kehrt zu Windrufer Klaue in der Dampfkammer zurück.', },
  },
  [29616] = {
    'Sturm auf die Dampfkammer',
    {'Bisher ist es uns nicht gelungen, die Naga in der Dampfkammer, wo sich ihre Pumpenzentrale befindet, aufzuhalten.|n|nZum Glück versucht die Expedition, die ich ausgesandt habe, das zu ändern. Würdet Ihr Euch in die Dampfkammer begeben und Behüterin Jhang Eure Hilfe anbieten?', },
    {'Sprecht mit Behüterin Jhang in der Dampfkammer.', },
  },
  [29640] = {
    'Findet Spion To\'gun',
    {'Der Schattenrat hat die meisten unserer Spione bereits getötet, aber To\'gun, der fliehen konnte, war so dumm zurückzukehren!|n|nIhr müsst ihn finden. Er ist unvernünftig, aber wir müssen herausfinden, was er weiß.', },
    {'Findet Spion To\'gun im Schattenlabyrinth von Auchindoun.', },
  },
  [29641] = {
    'Seeleninstrumente',
    {'Sie haben mich gefoltert, damit ich ihnen alles verrate, was ich weiß.|n|nDie anderen haben sie an Höllenschlund verfüttert, ich hätte als Nächstes dran sein sollen. Aber ich habe ihnen nichts verraten!|n|nSie benutzen spezielle Geräte, damit ihre Beschwörungen mächtiger werden. Diese Geräte müsst Ihr stehlen!', },
    {'Stehlt 5 Seeleninstrumente und bringt sie zu Spionin Grik\'tha im Schattenlabyrinth von Auchindoun.', },
  },
  [29642] = {
    'Ärger in Auchindoun',
    {'Meine Spione in Auchindoun haben uns erschreckende Berichte geschickt. Seit seiner Explosion vor ein paar Jahren hat dieser Ort nichts als Ärger gebracht.|n|nDort ist etwas - mal wieder - ganz schön schief gegangen, und der Schattenrat bereitet sich auf einen Krieg vor. Auch wenn die Berichte viele Details verschweigen, müssen sie sich auf einen Krieg im Inneren vorbereiten.|n|nIhr müsst Euch zum Eingang des Schattenlabyrinths begeben. Mein Feldkommandeur, Mahfuun, wird Euch genau erklären, was zu tun ist.', },
    {'Meldet Euch bei Feldkommandeur Mahfuun im Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar.', },
  },
  [29643] = {
    'Kodex des Blutes',
    {'Vor zwei Jahren beschwor der Schattenrat ein Wesen, das eine Schneise der Verwüstung in Auchindoun hinterließ.|n|nLest den Kodex des Blutes, um herauszufinden, was damals geschah. Seid jedoch vorsichtig, denn Großmeister Vorpil beschützt ihn mit seinem Leben.', },
    {'Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun.', },
  },
  [29644] = {
    'In das Herz des Labyrinths',
    {'Der Schattenrat hat die Kontrolle über das kosmische Wesen, das sie vor fast zwei Jahren beschworen haben, verloren!|n|nMan nennt es Murmur und es droht, den Schattenrat zu überrennen und zu entkommen!', },
    {'Vernichtet Murmur und meldet Euch danach bei Feldkommandeur Mahfuun im Schattenlabyrinth von Auchindoun.', },
  },
  [29645] = {
    'Botschafter Höllenschlund',
    {'Als die Kabale unsere Spione entdeckte, verfütterte sie alle an Botschafter Höllenschlund.|n|nUnsere Männer verdienen Gerechtigkeit. Tötet die Ritualisten, die Höllenschlund binden und vernichtet dann auch ihn.|n|nEr hat dieses Schicksal schon lange verdient.', },
    nil,
  },
  [29649] = {
    'Wie man ein Leben rettet',
    {'Gunny stirbt an einem mächtigen Fluch, $N.|n|nGroßhexenmeister Nethekurse benutzt zwei mystische Kohlefeuer zur Verstärkung seiner Kräfte. Vielleicht könnten wir mit etwas Glut aus einem Kohlefeuer diese dunkle Magie rückgängig machen.', },
    {'Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr ihm Teufelsglut bringt.', },
  },
  [29650] = {
    'Teufelsglut',
    {'Caza\'rez stirbt wie ein Feigling.|n|nGroßhexenmeister Nethekurse hat ihn mit einem schrecklichen Fluch belegt. Bringt mir etwas Glut aus seinen Kohlenpfannen. Vielleicht können wir die Magie damit umkehren, bevor es zu spät ist.', },
    {'Steingardist Stok\'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr ihm Teufelsglut bringt.', },
  },
  [29651] = {
    'Ehrt die Sterbenden',
    nil,
    {'Caza\'rez in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr 4 Legionäre der Zerschmetterten Hand, 2 Zenturionen der Zerschmetterten Hand und 2 Champions der Zerschmetterten Hand tötet.', },
  },
  [29652] = {
    'Ein letzter Gefallen',
    {'Der alte Gunny macht\'s nicht mehr lange...|n|nErweist mir einen letzten Gefallen und tötet die größten, übelsten Höllenorcs, die Ihr finden könnt.|n|nIm Andenken an alte Zeiten, ja?', },
    {'Gunny in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr 4 Legionäre, 2 Zenturionen und 2 Champions der Zerschmetterten Hand tötet.', },
  },
  [29653] = {
    'Der Wille des Kriegshäuptlings',
    {'Kargath war einst einer der größten Helden der Horde.|n|nDoch nun trägt er den falschen Mantel des Kriegshäuptlings. Bringt mir die nach ihm benannte Waffe, damit wir uns an seine früheren Heldentaten erinnern können und nicht an die Gräuel, die er heute anrichtet.', },
    {'Bringt Kriegshäuptling Kargaths Faust zu Steingardist Stok\'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle.', },
  },
  [29654] = {
    'Das Schicksal wenden',
    {'Es gibt nur einen Weg, um sicherzustellen, dass die Höllenorcs die Ehrenfeste und die Allianz nicht länger bedrohen.|n|nIhr Kriegshäuptling muss sterben.|n|nBringt mir die Waffe, die nach ihm benannt ist, damit wir seinen Tod niemals vergessen.', },
    {'Bringt Kriegshäuptling Kargaths Faust zu Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle.', },
  },
  [29655] = {
    'Ein ganz besonderes Tuch',
    {'Kriegshetzer O\'mrogg hat mehr mutige Soldaten auf dem Gewissen als jeder andere Feind, dem ich bisher begegnet bin. Er ist skrupellos, listig und äußerst mächtig.|n|nTötet ihn und bringt mir sein Kriegstuch. Wir werden ein Banner daraus nähen, sodass der Zorn der Horde für alle sichtbar ist.', },
    {'Tötet Kriegshetzer O\'mrogg und bringt sein Kriegstuch zu Steingardist Stok\'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle.', },
  },
  [29656] = {
    'O\'mroggs Kriegstuch',
    {'Sturmwind möchte Beweise für unsere Kriegserfolge sehen.|n|nWir könnten ihm Leichensäcke schicken, aber ich denke, das Kriegstuch von O\'mrogg, Kargaths mächtigstem Krieger würde ihn mehr beeindrucken. Traut Ihr ihn Euch zu?', },
    {'Tötet Kriegshetzer O\'mrogg und bringt sein Kriegstuch zu Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle.', },
  },
  [29657] = {
    'Aus großer Kraft folgt große Verantwortung',
    {'<Ihr hört eine Stimme, leicht wie der Klang winziger Glocken, in Eurem Kopf.>|n|nIn der Mechanar entstehen durch die Technologie meines Volks Manazellen, Objekte, die eine gewaltige Energie in sich tragen.|n|nTötet Mechanolord Kapazitus, damit Kael\'thas\' Streitkräfte sich diese Macht nicht zu Nutze machen können.', },
    {'A\'dal bittet Euch, Mechanolord Kapazitus in der Mechanar der Festung der Stürme zu töten.', },
  },
  [29658] = {
    'Der Kalkulator',
    {'<Eine leichte Brise streicht über Euer Gesicht.>|n|nNur noch eines bleibt zu tun.|n|nPathaleon der Kalkulator überwacht die meisten Operationen seines Herrn. Er persönlich trägt die Verantwortung für einen Großteil des Leids, das in letzter Zeit über die Welt gekommen ist.|n|nIch möchte, dass Ihr ihn vernichtet.', },
    {'A\'dal hat Euch gebeten, Pathaleon den Kalkulator in der Mechanar der Festung der Stürme zu töten.', },
  },
  [29659] = {
    'Der verlorene Schatz',
    {'Ich spüre, dass eines der Artefakte meines Volkes gestohlen wurde und im Behälter der Legion aufbewahrt wird.|n|nSie dürfen nicht entdecken, wie mächtig es ist. Würdet Ihr die Torwächter töten und es wiederbeschaffen? Ich wäre Euch sehr dankbar.', },
    {'Beschafft für A\'dal den Blendenden Zorn aus dem Behälter der Legion in der Mechanar der Festung der Stürme.', },
  },
  [29660] = {
    'Rettung der Botanika',
    {'Kael\'thas und seinen Streitkräften ist es nicht gelungen, die vielen Kreaturen in der Botanika niederzuwerfen. Wir müssen versuchen, ihre Fehler wiedergutzumachen.|n|nDer erste Schritt ist die Eliminierung ihrer Streitkräfte, damit sie keinen weiteren Ärger mehr verursachen können.', },
    {'A\'dal möchte, dass Ihr Kommandantin Sarannis, Hochbotaniker Freywinn und Dorngrin den Hüter in der Botanika der Festung der Stürme tötet.', },
  },
  [29667] = {
    'Ausdünnung der Herde',
    {'Anscheinend haben Kael\'thas\' Streitkräfte die Wesen der Botanika bis zur Unkenntlichkeit verändert. Ich will nicht, dass sie auf die Scherbenwelt losgelassen werden, wie so viele vor ihnen.|n|nEines dieser Wesen heißt Laj. Ihn würde ich gern untersuchen, denn er scheint irgendwie anders zu sein. Vielleicht können wir etwas von ihm lernen.', },
    {'A\'dal bittet Euch, 6 mutierte Fleischpeitscher, 6 mutierte Furchtkreischer und 6 mutierte Schrecken zu töten und einen schnellentwickelnden Wedel von Laj in der Botanika der Festung der Stürme zu erbeuten.', },
  },
  [29669] = {
    'Eine äußerst traurige Aufgabe',
    {'Ich muss Euch leider mit einer äußerst traurigen Aufgabe betrauen.|n|nWarpzweig war einmal der Wächter der ganzen Botanika. Doch nun ist er unrein und muss beseitigt werden.', },
    {'A\'dal bittet Euch, Warpzweig in der Botanika in der Festung der Stürme zu töten.', },
  },
  [29671] = {
    'Der Schwarze Morast',
    {'Der ewige Drachenschwarm versucht nun nicht einmal mehr, seine Pläne geheim zu halten. Sie haben vor, den Wächter, Medivh, zu töten und zu verhindern, dass das Dunkle Portal jemals geöffnet wird. Auf den ersten Blick scheint das ein Gefallen für die Streitkräfte der Allianz zu sein, aber tatsächlich wären die Folgen katastrophal und würden in der Zerstörung Eurer Welt enden.|n|nIhr müsst auf dem Pfad der Zeit zum Schwarzen Morast reisen. Geht zuerst nach Westen und dann nach Süden, vorbei an meinem zukünftigen Ich, bis Ihr zu dem Tunnel kommt, in dem die Sumpfwesen leben. Durchquert ihn und sprecht mit Sa\'at.', },
    {'Reist durch die Höhlen der Zeit in den Schwarzen Morast während der Öffnung des Dunklen Portals und sprecht mit Sa\'at.', },
  },
  [29672] = {
    'Die Öffnung des Dunklen Portals',
    {'Hier arbeitet Medivh verbissen an der Öffnung des Dunklen Portals.|n|nÜberall im Morast werden sich Zeitlöcher öffnen, aus denen die Ewigen herausströmen werden mit dem Ziel, Medivhs Schilde und schließlich auch Medivh selbst zu vernichten.|n|nTötet die Lords des Zeitlochs und ihre Anführer, bis Medivh erfolgreich war.', },
    {'Sa\'at im Schwarzen Morast der Höhlen der Zeit möchte, dass Ihr Medivh verteidigt, bis er das Dunkle Portal geöffnet hat.|n|nKehrt zu Sa\'at zurück, wenn Ihr erfolgreich wart.', },
  },
  [29673] = {
    'Der Schwarze Morast',
    {'Der ewige Drachenschwarm versucht nun nicht einmal mehr, seine Pläne geheim zu halten. Sie haben vor, den Wächter, Medivh, zu töten und zu verhindern, dass das Dunkle Portal jemals geöffnet wird. Auf den ersten Blick scheint das ein Gefallen für die Streitkräfte der Allianz zu sein, aber tatsächlich wären die Folgen katastrophal und würden in der Zerstörung Eurer Welt enden.|n|nIhr müsst auf dem Pfad der Zeit zum Schwarzen Morast reisen. Geht zuerst nach Westen und dann nach Süden, vorbei an meinem zukünftigen Ich, bis Ihr zu dem Tunnel kommt, in dem die Sumpfwesen leben. Durchquert ihn und sprecht mit Sa\'at.', },
    {'Reist durch die Höhlen der Zeit in den Schwarzen Morast während der Öffnung des Dunklen Portals und sprecht mit Sa\'at.', },
  },
  [29674] = {
    'Unbändige Dunkelheit',
    {'<Ihr hört klagendes Geläut in Eurem Kopf.>|n|nWir haben die gefährlichsten Wesen, die uns auf unseren Reisen untergekommen sind, eingesperrt.|n|nZereketh ist ein mächtiger Leerenfürst. Wenn es ihm gelingt, in den Nethersturm zu entkommen, wird er die reichlich vorhandene Leerenenergie in sich aufsaugen.', },
    {'A\'dal hat Euch gebeten, Zereketh den Unabhängigen in der Arkatraz der Festung der Stürme zu töten.', },
  },
  [29675] = {
    'Zorn und Verdammnis',
    {'Zornseher Soccothrates und Dalliah die Verdammnisverkünderin sind zwei mächtige Agenten der Brennenden Legion. Sie haben damit begonnen, Dämonen um sich zu versammeln.|n|nNoch ist die Armee klein, aber Ihr dürft nicht zulassen, dasss sie größer wird, sonst wird die Arkatraz bald zu einem weiteren Stützpunkt der Legion werden.', },
    {'A\'dal bittet Euch, Zornseher Soccothrates und Dalliah die Verdammnisverkünderin in der Arkatraz der Festung der Stürme zu töten.', },
  },
  [29681] = {
    'Ausbruch aus dem Hochsicherheitstrakt',
    {'Herold Horizontiss stellt das größte Problem in der Arkatraz dar.|n|nEr hat Aufseher Mellichar korrumpiert und dafür gesorgt, dass er zahlreiche Gefangene entlässt. Es ist nur eine Frage der Zeit, bis auch der Herold selbst freigelassen wird.|n|n$N, Ihr dürft einen Diener der Alten Götter nicht am Leben lassen!', },
    {'A\'dal hat Euch gebeten, Herold Horizontiss in der Arkatraz der Festung der Stürme zu töten.', },
  },
  [29682] = {
    'Terrasse der Magister',
    {'Vor kurzem haben wir eine Expedition zur Terrasse der Magister geschickt, um die Streitkräfte der Legion aufzuhalten.|n|nAllerdings haben wir seitdem nichts mehr gehört, und ich befürchte das Schlimmste.|n|nWürdet Ihr dorthin gehen und versuchen, Exarch Larethor zu finden? Er leitet die Expedition.', },
    {'Hauptmann Theris Morgenheim möchte, dass Ihr Exarch Larethor in der Terrasse der Magister findet.', },
  },
  [29683] = {
    'Der Seher der Seher',
    {'Geht zur Terrasse... benutzt die Kugel.|n|n<Tyrith ringt nach Luft.>|n|nBeeilt Euch... Ihr müsst sie aufhalten... bevor sie...|n|n<Tyrith stirbt.>', },
    {'Tyrith möchte, dass Ihr die Kugel auf dem Balkon in der Terrasse der Magister benutzt.', },
  },
  [29684] = {
    'Abgerissene Kommunikation',
    {'Wir haben vor einiger Zeit einen Kontaktmann in der Terrasse der Magister eingeschleust, der für uns Informationen sammelt, aber der Kontakt zu ihm ist abgerissen.|n|nSein Wissen ist für unsere Mission essentiell.', },
    {'Exarch Larethor in der Terrasse der Magister möchte, dass Ihr den Bluelfenspion Tyrith findet.', },
  },
  [29685] = {
    'Nicht totzukriegen',
    {'Wie Ihr mittlerweile wisst, arbeiten die Streitkräfte der Legion unermüdlich daran, die Kräfte des Sonnenbrunnens zu manipulieren, um so ihre eigenen unholden Machenschaften zu verwirklichen.|n|nKael\'thas ist aus der Asche der Niederlage auferstanden und ist einmal mehr zu ihrem Anführer geworden. Er muss aufgehalten werden.', },
    {'Kalecgos hat Euch damit beauftragt, Kael\'thas in der Terrasse der Magister zu bezwingen. Ihr sollt Euch mit Kaels Kopf bei Larethor in der Terrasse der Magister melden.', },
  },
  [29686] = {
    'Eine radikale Idee',
    {'Wir können es uns nicht leisten, diesen Krieg zu verlieren. Ich möchte unsere Wachen stärken, damit mutige Männer und Frauen nicht sterben müssen.|n|nDer Legion ist ein mächtiges Elementarwesen in die Klauen gefallen. Seine Essenz könnte genau das sein, was wir brauchen.', },
    {'Exarch Larethor auf der Terrasse der Magister bittet Euch, Vexallus zu töten und seine Essenz an Euch zu bringen.', },
  },
  [29687] = {
    'Dunkle Allianzen',
    {'Die Legion arbeitet immer enger mit Kael\'thas\' Streitkräften zusammen. Das bereitet mir große Sorgen.|n|nSoweit wir wissen, sind vor allem Selin Feuerherz und Priesterin Delrissa mit der Vereinigung der beiden Armeen beschäftigt. Ihr müsst sie aufhalten.', },
    {'Exarch Larethor in der Terrasse der Magister möchte, dass Ihr Selin Feuerherz und Priesterin Delrissa tötet.', },
  },
  [29688] = {
    'Fortführung der Kampagne',
    {'Ich höre meistens zu, $C. Ich höre zu, damit es der Kriegshäuptling nicht muss.|n|nIch habe gehört, wie es um unsere Kampagne gegen die Höllenfeuerzitadelle steht. Die Zeit zur Eroberung der Zerschmetterten Hallen, dem Machtzentrum der Höllenorcs, ist gekommen.|n|nSprecht mit Steingardist Stok\'ton. Ihm unterstehen die Truppen dort.', },
    {'Schattenjäger Ty\'jin hat Euch gebeten, mit Steingardist Stok\'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle zu sprechen.', },
  },
  [29689] = {
    'Fortführung der Kampagne',
    {'Die Zeit ist reif für einen letzten Schlag gegen die Höllenorcs.|n|nVorhutsspäher Chadwick erwartet Euch in den Zerschmetterten Hallen der Höllenfeuerzitadelle. Beeilt Euch, ihre Streitkräfte können jeden Moment die Ehrenfeste angreifen!', },
    {'Truppenkommandant Danath Trollbann hat Euch gebeten, mit Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle zu sprechen.', },
  },
  [29691] = {
    'Bringt mir ein Gebüsch!',
    {'Wir benutzen Bluthibiskus für viele Zwecke.|n|nNatürlich kommt er nur im Tiefensumpf vor und zahlreiche Bewohner haben Gefallen daran gefunden.|n|nIch wäre Euch sehr dankbar, wenn Ihr mir etwas davon bringen würdet.', },
    {'Sammelt 5 Bluthibisken und kehrt zu T\'shu im Tiefensumpf zurück.', },
  },
  [29692] = {
    'Bringt mir ein weiteres Gebüsch!',
    nil,
    nil,
  },
  [29734] = {
    'Urahne Tiefenschmiede',
    nil,
    nil,
  },
  [29735] = {
    'Urahne Steinsiegel',
    nil,
    nil,
  },
  [29736] = {
